# ==================== v13.0 SECURITY CORE - secrets resolve from env / file, never ONLY from source ==============
# Resolution order for EVERY secret: environment variable (NAME upper-case) -> /root/bot_secrets.json[name]
# -> the value baked in below (last-resort fallback so a fresh box still boots). _SECRET_SOURCE records where
# each secret actually came from, so security_check()/self_test can honestly report which keys are still sitting
# in this source file and must be rotated + moved out. BEHAVIOUR-FROZEN: with no env var and no secrets-file
# entry, every secret is exactly the value it had before this change.
try:
    _SECRETS_FILE = json.load(open("/root/bot_secrets.json"))
    if not isinstance(_SECRETS_FILE, dict):
        _SECRETS_FILE = {}
except Exception:
    _SECRETS_FILE = {}


def _n701_recover_secret_config(config,backup_root='/root/nemo_backups',secrets_path='/root/bot_secrets.json'):
    """Recover missing external keys from the updater-recorded backup, if present.
    No arbitrary path lookup, no code execution, no value logging. Env keys win.
    """
    import ast as _ast, tempfile as _tempfile
    import os as _os, json as _json
    mapping={'_BAKED_TELEGRAM_TOKEN':'telegram_token','_BAKED_OPENROUTER_KEY':'openrouter_key',
             '_BAKED_NVIDIA_KEY':'nvidia_key','_BAKED_GEMINI_KEY':'gemini_key'}
    missing={k:v for k,v in mapping.items() if not config.get(v) and not _os.environ.get(v.upper())}
    if not missing or not config.get('last_backup'):return config
    path=_os.path.realpath(str(config['last_backup']));root=_os.path.realpath(backup_root)
    if _os.path.commonpath([path,root])!=root or not _os.path.isfile(path):return config
    if _os.path.getsize(path)>8*1024*1024:return config
    with open(path,encoding='utf-8') as f:tree=_ast.parse(f.read())
    recovered={}
    for node in tree.body:
        if isinstance(node,_ast.Assign) and isinstance(node.value,_ast.Constant) and isinstance(node.value.value,str) and node.value.value:
            for target in node.targets:
                if isinstance(target,_ast.Name) and target.id in missing:recovered[missing[target.id]]=node.value.value
    if not recovered:return config
    updated=dict(config);updated.update(recovered)
    fd,tmp=_tempfile.mkstemp(prefix='.nemo-secret-migration-',dir=_os.path.dirname(secrets_path))
    try:
        with _os.fdopen(fd,'w',encoding='utf-8') as f:
            _json.dump(updated,f);f.flush();_os.fsync(f.fileno())
        _os.chmod(tmp,0o600);_os.replace(tmp,secrets_path)
    finally:
        if _os.path.exists(tmp):_os.unlink(tmp)
    return updated

try:
    _SECRETS_FILE=_n701_recover_secret_config(_SECRETS_FILE)
except Exception as _n701_secret_error:
    print('Nemo external-secret recovery unavailable:',type(_n701_secret_error).__name__)


_SECRET_SOURCE = {}   # logical name -> "env" | "file" | "source" | "unset"


def _secret(name, baked=""):
    """Resolve one secret by precedence (env -> secrets file -> baked-in) and record where it came from."""
    ev = os.environ.get(name.upper())
    if ev:
        _SECRET_SOURCE[name] = "env"
        return ev
    fv = _SECRETS_FILE.get(name)
    if fv:
        _SECRET_SOURCE[name] = "file"
        return fv
    if baked:
        _SECRET_SOURCE[name] = "source"   # still hard-coded in THIS file => exposed, must be rotated + moved out
        return baked
    _SECRET_SOURCE[name] = "unset"
    return ""


# --- last-resort baked-in fallbacks. v13.0 auto-migrates any still-baked secret into the 600-perm secrets file
# --- on boot, so a later version can blank these four lines and the bot keeps running. ROTATE these keys: they
