def _atomic_write_json(path, obj):
    """Crash-safe JSON write: temp file -> flush -> fsync -> atomic replace, keeping a .bak of the last good copy.
    A kill mid-write can no longer corrupt Nemo's whole memory - the previous good file stays intact."""
    tmp = path + ".tmp"
    try:
        with open(tmp, "w") as f:
            json.dump(obj, f)
            f.flush()
            os.fsync(f.fileno())
        if os.path.exists(path):
            try:
                os.replace(path, path + ".bak")      # keep one known-good backup
            except Exception:
                pass
        os.replace(tmp, path)                          # atomic on POSIX - never a half-written main file
        return True
    except Exception:
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass
        return False


def _load_json_safe(path):
    """Load JSON, falling back to the .bak copy if the main file is missing or corrupt.
    Returns (data, recovered_from_bak). This is what stops one bad crash from wiping all memory."""
    for p, is_bak in ((path, False), (path + ".bak", True)):
        try:
            if os.path.exists(p) and os.path.getsize(p) > 2:
                return json.load(open(p)), is_bak
        except Exception:
            continue
    return {}, False


