def clean_text(t):
    if not t:
        return t
    nl = chr(10)
    # v13.19: provider/token garbage must never reach Telegram or TTS.
    t = re.sub(r"(?i)<\s*unk\s*>", " ", str(t))
    t = re.sub(r"<\|[^>]{0,80}\|>", " ", t)
    t = t.replace("\x00", " ").replace("\ufeff", "").replace("\u200b", "")
    out = []
    for line in t.splitlines():
        s = line.rstrip()
        if len(s) >= 4 and re.fullmatch(r"[\s|:=_*.-]+", s):
            continue
        s = re.sub(r"^#{1,6}\s*", "", s)
        if s.count("|") >= 2:
            s = " - ".join(c.strip() for c in s.split("|") if c.strip())
        s = s.replace("**", "").replace("__", "").replace("`", "").replace("→", "-")
        s = re.sub(r"^\s*[*-]\s+", "• ", s)
        out.append(s)
    cleaned = nl.join(out)
    while nl + nl + nl in cleaned:
        cleaned = cleaned.replace(nl + nl + nl, nl + nl)
    return cleaned.strip()


def groq_chat(msgs):
    if not GROQ_KEY:
        return None
    for m in ("llama-3.3-70b-versatile", "llama-3.1-8b-instant"):
        try:
            r = requests.post("https://api.groq.com/openai/v1/chat/completions",
                              headers={"Authorization": "Bearer " + GROQ_KEY},
                              json={"model": m, "messages": msgs, "max_tokens": 4000}, timeout=60)
            if r.status_code == 200:
                t = (r.json()["choices"][0]["message"].get("content") or "").strip()
                if t:
                    return t
        except Exception:
            pass
    return None


