def cerebras_chat(msgs):
    """v9.0 - Cerebras: 1,000,000 free tokens/day at ~2,600 tokens/sec. OpenAI-compatible.
    Free key from cloud.cerebras.ai -> /cerebras <key>. Silent no-op if no key."""
    if not CEREBRAS_KEY:
        return None
    for m in CEREBRAS_MODELS:
        try:
            r = requests.post("https://api.cerebras.ai/v1/chat/completions",
                              headers={"Authorization": "Bearer " + CEREBRAS_KEY},
                              json={"model": m, "messages": msgs, "max_tokens": 4000}, timeout=(10, 60))
            if r.status_code == 200:
                t = (r.json()["choices"][0]["message"].get("content") or "").strip()
                if t:
                    return t
            elif r.status_code in (400, 404):
                continue                       # model not available on this key - try the next
        except Exception:
            pass
    return None


def cerebras_probe():
    """Validate the Cerebras key, auto-discover a working model, and return (ok, human_detail).
    Tests the models the key actually lists, reports each one, and reorders CEREBRAS_MODELS."""
    if not CEREBRAS_KEY:
        return False, "no key set"
    avail = []
    try:
        r = requests.get("https://api.cerebras.ai/v1/models",
                         headers={"Authorization": "Bearer " + CEREBRAS_KEY}, timeout=(10, 30))
        if r.status_code == 401:
            return False, "the key was rejected (401) - it's wrong, expired, or revoked"
        if r.status_code == 200:
            avail = [m.get("id") for m in (r.json().get("data") or []) if m.get("id")]
    except Exception as e:
        return False, "couldn't reach Cerebras servers (" + type(e).__name__ + ")"
    # test the models the key really has (no max_tokens - reasoning models reject a tiny cap)
    order = (avail or []) + [m for m in CEREBRAS_MODELS if m not in (avail or [])]
    report = []
    for m in order[:6]:
        try:
            r = requests.post("https://api.cerebras.ai/v1/chat/completions",
                              headers={"Authorization": "Bearer " + CEREBRAS_KEY},
                              json={"model": m, "messages": [{"role": "user", "content": "Reply with just: OK"}]},
                              timeout=(10, 45))
            if r.status_code == 200:
                if m in CEREBRAS_MODELS:
                    CEREBRAS_MODELS.remove(m)
                CEREBRAS_MODELS.insert(0, m)
                save_secret("cerebras_model", m)
                return True, m
            report.append(m + "->" + str(r.status_code))
        except Exception as e:
            report.append(m + "->" + type(e).__name__)
    tail = ("  Your key is VALID (it can list models), so this is a Cerebras account-access limit, not the key."
            if avail else "")
    return False, ("no model accepted a chat request. Tried: " + " | ".join(report) + "." + tail)


def groq_transcribe(path, langs=("en", "hi")):
    """v9.0 - free Groq Whisper speech-to-text (2,000 voice notes/day, 99+ languages).
    Returns the transcript string, or None. Accepts .oga/.ogg/.mp3/.wav directly."""
    if not GROQ_KEY or not os.path.exists(path):
        return None
    try:
        fn = path.rsplit("/", 1)[-1]
        with open(path, "rb") as f:
            files = {"file": (fn, f, "application/octet-stream")}
            data = {"model": "whisper-large-v3-turbo", "response_format": "text"}
            # let Whisper auto-detect the language (handles English/Hindi/Hinglish well)
            r = requests.post("https://api.groq.com/openai/v1/audio/transcriptions",
                              headers={"Authorization": "Bearer " + GROQ_KEY},
                              files=files, data=data, timeout=90)
        if r.status_code == 200:
            txt = (r.text or "").strip()
            return txt or None
    except Exception:
        traceback.print_exc()
    return None


# ============================ v8.6 VECTOR MEMORY - semantic recall + model of you ============================
VEC_FILE = "nemo_vec.json"
MEMVEC = []  # [{"t": text, "v": [floats], "k": kind, "ts": epoch}]


def _mem_load():
    try:
        MEMVEC.extend(json.load(open(VEC_FILE)))
    except Exception:
        pass


def _mem_save():
    try:
        json.dump(MEMVEC[-1500:], open(VEC_FILE, "w"))
    except Exception:
        pass


def embed(text):
    """Free text embedding via Google's text-embedding-004 (uses the existing Gemini key). Returns a vector or None."""
    if not GEMINI_KEY or not text:
        return None
    try:
        r = requests.post("https://generativelanguage.googleapis.com/v1beta/models/text-embedding-004:embedContent",
                          params={"key": GEMINI_KEY},
                          json={"model": "models/text-embedding-004", "content": {"parts": [{"text": text[:2000]}]}},
                          timeout=30)
        if r.status_code == 200:
            v = (r.json().get("embedding") or {}).get("values")
            return v if v else None
    except Exception:
        pass
    return None


def _cos(a, b):
    s = da = db = 0.0
    for x, y in zip(a, b):
        s += x * y
        da += x * x
        db += y * y
    if da <= 0 or db <= 0:
        return 0.0
    return s / ((da ** 0.5) * (db ** 0.5))


def mem_add(text, kind="note"):
    """Embed a memory and store it (deduped). Silent no-op if embeddings aren't available."""
    t = (text or "").strip()
    if len(t) < 12:
        return False
    for m in MEMVEC[-40:]:
        if m["t"].strip().lower() == t.lower():
            return False
    v = embed(t)
    if not v:
        return False
    with LOCK:
        MEMVEC.append({"t": t[:1000], "v": v, "k": kind, "ts": time.time()})
        del MEMVEC[:-1500]
    _mem_save()
    return True


def mem_recall(query, k=5, minsim=0.62):
    """Semantic recall: the k most relevant stored memories for a query. Empty if none relevant / no embeddings."""
    if not MEMVEC:
        return []
    qv = embed(query)
    if not qv:
        return []
    scored = sorted(((_cos(qv, m["v"]), m) for m in MEMVEC), key=lambda x: -x[0])
    return [m["t"] for s, m in scored[:k] if s >= minsim]


def about_me(chat_id):
    """Build a 'model of you' - a living profile from everything Nemo has stored."""
    facts = FACTS.get(chat_id, [])
    vault = list(VAULT.get(chat_id, {}).items())
    mems = [m["t"] for m in MEMVEC[-120:]]
    src = ("Saved facts:\n- " + "\n- ".join(facts) + "\n\n" if facts else "") + \
          ("Vault:\n- " + "\n- ".join(f"{k}: {v}" for k, v in vault[:30]) + "\n\n" if vault else "") + \
          ("Recent memories:\n- " + "\n- ".join(mems) if mems else "")
    if not src.strip():
        return "I don't know much about you yet, Boss. The more we talk, the more I remember - or tell me things with /remember."
    return ask_ai(chat_id, "You are Nemo. From everything you've stored about your Boss below, write a warm, concise "
                  "'what I know about you' profile: who he is, his goals, work, people, preferences and routines. "
                  "Group it naturally, no markdown.\n\n" + src[:6000], remember=False, timeout=150)


def gemini_chat(msgs):
    if not GEMINI_KEY:
        return None
    sys_txt = ""
    contents = []
    for m in msgs:
        c = m.get("content")
        if not isinstance(c, str):
            continue
        if m["role"] == "system":
            sys_txt += c + "\n"
        else:
            contents.append({"role": "user" if m["role"] == "user" else "model",
                             "parts": [{"text": c}]})
    if not contents:
        return None
    if sys_txt:
        contents[0]["parts"][0]["text"] = sys_txt + "\n" + contents[0]["parts"][0]["text"]
    for model in ("gemini-3.1-flash", "gemini-2.5-flash", "gemini-2.0-flash"):
        try:
            r = requests.post("https://generativelanguage.googleapis.com/v1beta/models/" + model + ":generateContent",
                              params={"key": GEMINI_KEY}, json={"contents": contents}, timeout=60)
            if r.status_code == 200:
                t = (r.json()["candidates"][0]["content"]["parts"][0].get("text") or "").strip()
                if t:
                    return t
        except Exception:
            pass
    return None


