def _claude_id(tier):
    """A tier key (haiku/sonnet/opus/fable) OR a full 'claude-...' id -> the real model id."""
    if tier in CLAUDE_MODELS:
        return CLAUDE_MODELS[tier][0]
    return tier if str(tier).startswith("claude-") else CLAUDE_MODELS["haiku"][0]


def _claude_price(mid):
    for _t, (i, pin, pout) in CLAUDE_MODELS.items():
        if i == mid:
            return pin, pout
    return 1.0, 5.0


def _claude_msgs(msgs):
    """Convert OpenAI-style msgs -> (system_str, anthropic_messages): pull out system text, convert image
    blocks, coalesce consecutive same-role turns, and make sure it starts on a 'user' turn."""
    system = ""
    conv = []
    for m in msgs:
        role = m.get("role")
        c = m.get("content")
        if role == "system":
            if isinstance(c, str):
                system += c + "\n"
            continue
        if role not in ("user", "assistant"):
            role = "user"
        if isinstance(c, list):
            blocks = []
            for part in c:
                if not isinstance(part, dict):
                    continue
                if part.get("type") == "text":
                    blocks.append({"type": "text", "text": part.get("text", "")})
                elif part.get("type") == "image_url":
                    url = (part.get("image_url") or {}).get("url", "")
                    if url.startswith("data:"):
                        try:
                            head, b64 = url.split(",", 1)
                            mt = head.split(";")[0].split(":", 1)[1] or "image/jpeg"
                            blocks.append({"type": "image",
                                           "source": {"type": "base64", "media_type": mt, "data": b64}})
                        except Exception:
                            pass
            content = blocks or [{"type": "text", "text": ""}]
        else:
            content = c if isinstance(c, str) else str(c or "")
        if conv and conv[-1]["role"] == role:                 # merge same-role turns (Anthropic requires alternation)
            prev = conv[-1]["content"]
            pa = prev if isinstance(prev, list) else [{"type": "text", "text": prev}]
            ca = content if isinstance(content, list) else [{"type": "text", "text": content}]
            conv[-1]["content"] = pa + ca
        else:
            conv.append({"role": role, "content": content})
    while conv and conv[0]["role"] != "user":                  # must start with a user turn
        conv.pop(0)
    if not conv:
        conv = [{"role": "user", "content": "Hello"}]
    return system.strip(), conv


def claude_chat(msgs, model=None, max_tokens=4000, timeout=90):
    """Answer via the Boss's Claude (Anthropic Messages API). `model` = a tier key or a full model id.
    Returns the text, or None. Tracks a running cost estimate in CLAUDECFG['spent']."""
    if not CLAUDE_KEY or not CLAUDECFG.get("on", True):
        return None
    mid = _claude_id(model or CLAUDECFG.get("model", "haiku"))
    system, conv = _claude_msgs(msgs)
    body = {"model": mid, "max_tokens": max_tokens, "messages": conv}
    if system:
        body["system"] = system
    try:
        r = requests.post("https://api.anthropic.com/v1/messages",
                          headers={"x-api-key": CLAUDE_KEY, "anthropic-version": "2023-06-01",
                                   "content-type": "application/json"},
                          json=body, timeout=(15, timeout))
        if r.status_code == 200:
            j = r.json()
            txt = "".join(b.get("text", "") for b in j.get("content", []) if b.get("type") == "text").strip()
            try:
                u = j.get("usage", {}) or {}
                pin, pout = _claude_price(mid)
                cost = (u.get("input_tokens", 0) / 1e6) * pin + (u.get("output_tokens", 0) / 1e6) * pout
                CLAUDECFG["spent"] = round(CLAUDECFG.get("spent", 0.0) + cost, 5)
                CLAUDECFG["calls"] = CLAUDECFG.get("calls", 0) + 1
                save_secret("claudecfg", CLAUDECFG)
            except Exception:
                pass
            return txt or None
        CLAUDE_LAST["err"] = "HTTP " + str(r.status_code) + " " + (r.text or "")[:200]
    except Exception as e:
        CLAUDE_LAST["err"] = type(e).__name__ + " " + str(e)[:150]
    return None


def claude_ask(chat_id, text, image_b64=None, remember=True, timeout=120, model=None):
    """High-level: answer AS Nemo using the premium Claude brain (full system prompt + memory + history).
    Returns the answer, or None if Claude isn't available - so callers can fall back to the free brain."""
    if not CLAUDE_KEY:
        return None
    with LOCK:
        _n281_tls = globals().get('_N281_TLS')
        _n281_no_history = bool(getattr(_n281_tls, 'no_history', False)) if _n281_tls is not None else False
        past = [] if _n281_no_history else list(HISTORY.get(chat_id, []))
    sys_content = build_system(chat_id)
    if isinstance(text, str) and chat_id == OWNER.get("id"):
        try:
            mv = mem_recall(text, k=4)
            if mv:
                sys_content += "\n\nThings you remember about the Boss (recall naturally if relevant):\n- " + "\n- ".join(mv)
        except Exception:
            pass
    msgs = [{"role": "system", "content": sys_content}] + past
    if image_b64:
        # v13.15: original screenshots may be PNG/WEBP/GIF/BMP. OpenRouter should receive the real MIME,
        # not a hard-coded image/jpeg label. Invalid base64 safely falls back to JPEG for legacy callers.
        _imime = "image/jpeg"
        try:
            _raw_head = base64.b64decode(image_b64[:160] + "===", validate=False)
            _imime = _image_mime(_raw_head) or "image/jpeg"
        except Exception:
            pass
        msgs.append({"role": "user", "content": [
            {"type": "text", "text": text},
            {"type": "image_url", "image_url": {"url": "data:" + _imime + ";base64," + image_b64}}]})
    else:
        msgs.append({"role": "user", "content": text})
    out = claude_chat(msgs, model=model, max_tokens=4000, timeout=timeout)
    if out and remember:
        with LOCK:
            h = HISTORY.setdefault(chat_id, [])
            h.append({"role": "user", "content": ("[photo] " if image_b64 else "") + str(text)[:2000]})
            h.append({"role": "assistant", "content": out[:3000]})
            del h[:-72]
    return clean_text(out) if out else None


def claude_probe():
    """Validate the key with a tiny call. Returns (ok, detail)."""
    if not CLAUDE_KEY:
        return False, "no key set"
    out = claude_chat([{"role": "user", "content": "Reply with only: OK"}],
                      model=CLAUDECFG.get("model", "haiku"), max_tokens=16, timeout=40)
    if out:
        return True, _claude_id(CLAUDECFG.get("model", "haiku"))
    return False, (CLAUDE_LAST.get("err") or "no reply")


def browser_decide(chat_id, prompt, timeout=90, shot_b64=None):
    """The browser agent's 'what do I do next' brain. Uses the Boss's Claude when enabled (far more reliable at
    driving forms, dropdowns and multi-step portals), else the free brain. If shot_b64 is given (the page had no
    readable elements), the screenshot is sent too so a VISION model can act from what it SEES (with clickxy)."""
    if CLAUDE_KEY and CLAUDECFG.get("on", True) and CLAUDECFG.get("browser", True):
        content = ([{"type": "text", "text": prompt},
                    {"type": "image_url", "image_url": {"url": "data:image/jpeg;base64," + shot_b64}}]
                   if shot_b64 else prompt)
        out = claude_chat([{"role": "user", "content": content}],
                          model=CLAUDECFG.get("browser_model") or CLAUDECFG.get("model", "haiku"),
                          max_tokens=400, timeout=timeout)
        if out:
            return out
    return ask_ai(chat_id, prompt, remember=False, timeout=timeout, image_b64=shot_b64)


def brain_status():
    """Human-readable status of Nemo's live v13.14 model routes + Claude cost/config."""
    prem = ("not connected - add it with /claude sk-ant-..." if not CLAUDE_KEY else
            (("ON - " + _claude_id(CLAUDECFG.get("model", "haiku"))) if CLAUDECFG.get("on", True) else "key saved, OFF"))
    def _route(xs):
        return " -> ".join(x.split("/")[-1] for x in xs)
    lines = ["🧠 Nemo's brains (v" + VERSION + "):",
             "- SMART: " + _route(SMART_MODELS),
             "- FAST: " + _route(FAST_MODELS),
             "- VISION: " + _route(VISION_MODELS),
             "- Dynamic free fallback: openrouter/free (capability-aware)",
             "- Retired/blocked permanently: " + ", ".join(sorted(RETIRED_MODELS)),
             "- Premium (Claude): " + prem]
    now = time.time()
    cooled = []
    for m, h in list(MODEL_HEALTH.items()):
        left = max(0, int(float(h.get("until", 0) or 0) - now))
        if left:
            cooled.append(m.split("/")[-1] + " ~" + str(left // 60 + 1) + "m (" + str(h.get("why", ""))[:70] + ")")
    if cooled:
        lines.append("- Temporarily cooled down: " + "; ".join(cooled))
    if EXTRA_MODELS:
        lines.append("- Self-discovered extras: " + ", ".join(EXTRA_MODELS))
    if CLAUDE_KEY:
        lines += [
            "   - drives browser / land records: " + ("yes (" + str(CLAUDECFG.get("browser_model", "sonnet")) + ")"
                                                      if CLAUDECFG.get("browser", True) else "no"),
            "   - backup when free brains fail: " + ("yes" if CLAUDECFG.get("backup", True) else "no"),
            "   - /think uses: " + str(CLAUDECFG.get("hard_model", "sonnet")),
            "   - est. spent: ~$" + format(CLAUDECFG.get("spent", 0.0), ".3f") +
            " over " + str(CLAUDECFG.get("calls", 0)) + " calls",
            "   - switch model: /claude haiku | sonnet | opus | fable",
            "   - toggles: /claude browser off  ·  /claude backup off  ·  /claude off"]
    lines.append("Force my best brain on one question: /think <your question>")
    return "\n".join(lines)


