# ==================== v13.15 UNIVERSAL IMAGE ATTACHMENT ROUTER ====================
_IMAGE_EXTS = (".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp")


def _image_mime(raw=b"", name="", declared=""):
    """Best-effort image MIME without trusting only Telegram metadata or filename."""
    d = (declared or "").split(";", 1)[0].strip().lower()
    if d.startswith("image/"):
        return d
    b = raw or b""
    if b.startswith(b"\x89PNG\r\n\x1a\n"):
        return "image/png"
    if b.startswith(b"\xff\xd8\xff"):
        return "image/jpeg"
    if b.startswith((b"GIF87a", b"GIF89a")):
        return "image/gif"
    if len(b) >= 12 and b[:4] == b"RIFF" and b[8:12] == b"WEBP":
        return "image/webp"
    if b.startswith(b"BM"):
        return "image/bmp"
    low = (name or "").lower()
    if low.endswith(".png"):
        return "image/png"
    if low.endswith((".jpg", ".jpeg")):
        return "image/jpeg"
    if low.endswith(".webp"):
        return "image/webp"
    if low.endswith(".gif"):
        return "image/gif"
    if low.endswith(".bmp"):
        return "image/bmp"
    return ""


def _is_image_document(doc, raw=b""):
    """Telegram may send screenshots as document instead of photo; promote them to vision deterministically."""
    name = (doc or {}).get("file_name") or ""
    mime = (doc or {}).get("mime_type") or ""
    return bool(_image_mime(raw, name, mime))


def _handle_image_bytes(chat_id, raw, caption="", name="image", declared_mime=""):
    """Single image entry point for Telegram photo AND image-as-document paths."""
    if not raw:
        send_text(chat_id, "I couldn't read that image - please send it again.")
        return
    mime = _image_mime(raw, name, declared_mime)
    if not mime:
        send_text(chat_id, "That file does not appear to be a supported image (PNG/JPG/WEBP/GIF/BMP).")
        return
    b64 = base64.b64encode(raw).decode()
    LAST_PHOTO[chat_id] = b64
    cap = (caption or "").strip()
    pend2 = PENDING.get(chat_id)
    _cl = cap.lower()
    if pend2 in ("scan", "ocr", "qr") or _cl.startswith(("scan", "ocr", "qr", "pdf", "document", "barcode")) \
            or "scan this" in _cl or "make pdf" in _cl or "read text" in _cl or "extract text" in _cl:
        PENDING.pop(chat_id, None)
        _sm = "ocr" if (pend2 == "ocr" or "ocr" in _cl or "text" in _cl or _cl.startswith("read")) else \
              ("qr" if (pend2 == "qr" or "qr" in _cl or "barcode" in _cl) else "pdf")
        threading.Thread(target=scan_document, args=(chat_id, b64, _sm), daemon=True).start()
        return
    if pend2 == "bill" or _cl.startswith(("bill", "receipt", "kharcha")):
        PENDING.pop(chat_id, None)
        threading.Thread(target=scan_bill, args=(chat_id, b64), daemon=True).start()
        return
    if pend2 == "notes" or _cl.startswith(("notes", "note ")):
        PENDING.pop(chat_id, None)
        threading.Thread(target=photo_notes, args=(chat_id, b64), daemon=True).start()
        return
    q = cap or ("Look at this image carefully and be genuinely useful. If it is a document, form, receipt or "
                "screenshot, read and extract the important content and explain it. If it is a chart or graph, "
                "interpret the trend and key numbers. If it is a question, math or code, solve/explain it. If it "
                "is a scene or object, describe what matters. Then answer anything the user might want from it.")
    answer(chat_id, q, image_b64=b64)


def handle_document(chat_id, doc, caption=""):
    name = doc.get("file_name") or "file"
    if doc.get("file_size", 0) > 15 * 1024 * 1024:
        send_text(chat_id, "File too big (max 15 MB).")
        return
    info = tg("getFile", file_id=doc["file_id"])
    fp = info.get("result", {}).get("file_path")
    if not fp:
        send_text(chat_id, "Could not download that file, please try again.")
        return
    raw = requests.get(f"{TG_FILE}/{fp}", timeout=120).content
    low = name.lower()
    # v13.15: Telegram often sends screenshots/original images as `document`, not `photo`.
    # Detect by MIME, extension AND magic bytes, then use the exact same vision path.
    if _is_image_document(doc, raw):
        _handle_image_bytes(chat_id, raw, caption=caption, name=name, declared_mime=doc.get("mime_type", ""))
        return
    text = ""
    if low.endswith(".pdf"):
        try:
            from pypdf import PdfReader
            text = "\n".join((p.extract_text() or "") for p in PdfReader(io.BytesIO(raw)).pages)
        except ImportError:
            send_text(chat_id, "PDF reading needs: pip3 install pypdf --break-system-packages, then restart.")
            return
        except Exception:
            send_text(chat_id, "Could not read this PDF (maybe scanned images only).")
            return
    elif any(low.endswith(e) for e in (".xlsx", ".xlsm", ".xls")):
        try:
            import openpyxl
            wb = openpyxl.load_workbook(io.BytesIO(raw), data_only=True)
            rows = []
            for r2 in wb.active.iter_rows(values_only=True):
                rows.append(",".join("" if c is None else str(c) for c in r2))
                if len(rows) >= 2000:
                    break
            text = "\n".join(rows)
        except ImportError:
            send_text(chat_id, "Excel reading needs: pip3 install openpyxl --break-system-packages, then restart.")
            return
        except Exception:
            send_text(chat_id, "Could not read this Excel file - is it a normal .xlsx?")
            return
    elif low.endswith(".conf") and chat_id == OWNER.get("id") and "[Interface]" in raw.decode("utf-8", "ignore") and "[Peer]" in raw.decode("utf-8", "ignore"):
        try:
            os.makedirs(VPN_PROFILE_DIR, mode=0o700, exist_ok=True)
            nm = re.sub(r"[^A-Za-z0-9_.-]", "_", os.path.splitext(name)[0]) + ".conf"
            dst = os.path.join(VPN_PROFILE_DIR, nm)
            open(dst, "wb").write(raw)
            os.chmod(dst, 0o600)
            send_text(chat_id, "🔐 WireGuard profile imported as " + nm + ". Private key was stored locally only. Use /vpn connect " + os.path.splitext(nm)[0] + " after reviewing the provider/profile.")
        except Exception as e:
            send_text(chat_id, "VPN profile import failed: " + str(e)[:180])
        return
    elif any(low.endswith(e) for e in (".txt", ".md", ".csv", ".py", ".json", ".html", ".js", ".log")):
        text = raw.decode("utf-8", "ignore")
    else:
        send_text(chat_id, "Supported files: images (PNG/JPG/JPEG/WEBP/GIF/BMP), PDF, Excel (XLSX), TXT, CSV, MD, PY, JSON, HTML, JS, LOG.")
        return
    text = text.strip()
    if not text:
        send_text(chat_id, "The file seems empty or unreadable.")
        return
    note = " (kept first 50,000 characters)" if len(text) > 50000 else ""
    with LOCK:
        DOCS[chat_id] = {"name": name, "text": text[:50000]}
    saved = lib_save(name, text) if chat_id == OWNER.get("id") else False
    lib_note = ("\n\U0001F4DA Also saved to my permanent library - I will remember this "
                "document forever and use it in future answers. /library shows everything.") if saved else ""
    send_text(chat_id, f"\U0001F4CE Loaded '{name}' - {len(text)} characters{note}.\n"
                       "Ask me anything about it, or use /summary. /forgetdoc removes it." + lib_note)
    if chat_id == OWNER.get("id") and low.endswith(".py"):
        LAST_CODE[chat_id] = {"name": name, "code": text}
        if len(text) > 100000 and "VERSION" in text and ("nemotron_bot" in text or "def main()" in text):
            send_text(chat_id, "\U0001F195 This looks like a new version of ME (v" + _extract_version(text) +
                      ", I'm on v" + VERSION + "). To install it just send  /update  - I'll compile-check it, "
                      "back up the current me, and restart myself (you tap to confirm). No SSH, no server needed.")
        else:
            _sug = re.sub(r"[^a-z0-9]", "", name.lower().replace(".py", ""))[:20] or "myapp"
            send_text(chat_id, "\U0001F40D That's a Python program. I can RUN it on your server as a live 24/7 service.\n"
                      "1) /caps deploy on  (first time only)\n"
                      "2) set any secrets:  /env " + _sug + " KEY=VALUE  (e.g. its bot token, API keys)\n"
                      "3) /ship " + _sug + "  - I write it, install packages, bake in the secrets, and start it "
                      "(you tap to confirm).")
    if any(low.endswith(e) for e in (".csv", ".xlsx", ".xlsm", ".xls")):
        threading.Thread(target=analyze_sheet, args=(chat_id,), daemon=True).start()


def lib_save(name, text):
    """Forever-library: keep a permanent copy of every document on the 80GB disk."""
    try:
        os.makedirs(LIB_DIR, exist_ok=True)
        safe = re.sub(r"[^A-Za-z0-9._-]+", "_", name)[:80] or "doc"
        base = os.path.splitext(safe)[0]
        path = os.path.join(LIB_DIR, base + ".txt")
        n = 1
        while os.path.exists(path):
            try:
                head = open(path, encoding="utf-8", errors="ignore").read(300)
            except Exception:
                head = ""
            if text[:300] == head:
                return False  # exact same document already stored
            n += 1
            path = os.path.join(LIB_DIR, f"{base}_{n}.txt")
        open(path, "w", encoding="utf-8").write(text[:400000])
        return True
    except Exception:
        return False


def lib_files():
    try:
        return sorted(f for f in os.listdir(LIB_DIR) if f.endswith(".txt"))
    except Exception:
        return []


STOPWORDS = {"the", "and", "for", "what", "how", "why", "who", "where", "when",
             "this", "that", "with", "from", "about", "tell", "give", "make",
             "your", "you", "are", "can", "please", "will", "have", "has",
             "was", "were", "does", "did", "not", "all", "any", "get", "his",
             "her", "its", "our", "their", "there", "here", "into", "than"}


def lib_search(query, max_chars=2600):
    """Search every document ever saved in the permanent library, return best excerpts."""
    try:
        words = [w for w in re.findall(r"[a-z0-9]{3,}", (query or "").lower())
                 if w not in STOPWORDS][:12]
        if not words:
            return ""
        best = []
        for fn in lib_files()[:80]:
            try:
                txt = open(os.path.join(LIB_DIR, fn), encoding="utf-8", errors="ignore").read(300000)
            except Exception:
                continue
            low2 = txt.lower()
            score = sum(low2.count(w) for w in words)
            hit_kinds = sum(1 for w in words if w in low2)
            if score < 2 or hit_kinds < min(2, len(words)):
                continue
            pos = min((low2.find(w) for w in words if w in low2), default=0)
            start = max(0, pos - 200)
            best.append((score, fn, txt[start:start + 1200]))
        best.sort(reverse=True)
        out, used = [], 0
        for score, fn, ex in best[:3]:
            piece = f"--- from {fn} ---\n{ex.strip()}"
            if used + len(piece) > max_chars:
                break
            out.append(piece)
            used += len(piece)
        return "\n\n".join(out)
    except Exception:
        return ""


def email_html(body, title=""):
    """Turn plain-text (English/Hindi/Hinglish) into a polished, branded HTML email.
    Parses  === Section ===  / ## Section  -> section headers,
    'Lesson N:' / 'Executive Summary' / 'Conclusion' / short 'Word:' lines -> sub-headings,
    -,*,• -> styled bullet lists, 1. 2. -> numbered lists, **bold** -> bold,
    blank lines -> spacing.  Wrapped in a white card with a navy->blue gradient header."""
    import html as hmod
    import re as _re

    def _inline(t):
        t = hmod.escape(t or "")
        t = _re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", t)
        t = _re.sub(r"__(.+?)__", r"<b>\1</b>", t)
        t = _re.sub(r"`([^`]+)`",
                    r"<code style='background:#eef1f6;padding:1px 6px;border-radius:5px;"
                    r"font-family:Consolas,Menlo,monospace;font-size:13px;color:#0f2557'>\1</code>", t)
        t = _re.sub(r"(?<![\"'>])(https?://[^\s<)]+)",
                    r"<a href='\1' style='color:#2563eb;text-decoration:none'>\1</a>", t)
        return t

    SECTION_WORDS = ("executive summary", "summary", "overview", "introduction", "background",
                     "key takeaways", "takeaways", "recommendations", "recommendation", "next steps",
                     "conclusion", "disclaimer", "highlights", "analysis", "findings", "results",
                     "objective", "objectives", "scope", "methodology", "action items", "outlook")

    def _is_subheading(s):
        low = s.lower().strip().rstrip(":")
        if low in SECTION_WORDS:
            return True
        if _re.match(r"^(lesson|step|part|chapter|day|phase|point|tip|note|q|question)\s*\d+\s*[:.)-]", s, _re.I):
            return True
        if s.startswith("**") and s.endswith("**") and len(s) <= 80:
            return True
        if len(s) <= 58 and s.endswith(":") and s.count(":") == 1 and not s.startswith(("http", "-", "*", "•")):
            return True
        return False

    lines = (body or "").replace("\r\n", "\n").replace("\r", "\n").split("\n")
    parts, bullets, numbered = [], [], []

    def flush_b():
        if bullets:
            lis = "".join("<li style='margin:5px 0;line-height:1.55'>" + _inline(x) + "</li>" for x in bullets)
            parts.append("<ul style='margin:6px 0 14px 0;padding-left:22px;color:#333'>" + lis + "</ul>")
            bullets.clear()

    def flush_n():
        if numbered:
            lis = "".join("<li style='margin:5px 0;line-height:1.55'>" + _inline(x) + "</li>" for x in numbered)
            parts.append("<ol style='margin:6px 0 14px 0;padding-left:24px;color:#333'>" + lis + "</ol>")
            numbered.clear()

    def flush():
        flush_b()
        flush_n()

    for raw in lines:
        s = raw.strip()
        if not s:
            flush()
            continue
        m_sec = _re.match(r"^\s*={2,}\s*(.+?)\s*={2,}\s*$", s) or _re.match(r"^#{1,3}\s+(.+?)\s*#*$", s)
        if m_sec:
            flush()
            txt = m_sec.group(1).strip().strip("*").strip()
            parts.append("<h2 style='margin:22px 0 10px 0;padding:0 0 6px 0;color:#0f2557;"
                         "font-size:18px;font-weight:700;border-bottom:2px solid #e2e8f0'>" + _inline(txt) + "</h2>")
            continue
        m_bul = _re.match(r"^\s*[-*•·▪‣]\s+(.+)$", raw)
        if m_bul:
            flush_n()
            bullets.append(m_bul.group(1).strip())
            continue
        m_num = _re.match(r"^\s*(\d+)[.)]\s+(.+)$", raw)
        if m_num and not _is_subheading(s):
            flush_b()
            numbered.append(m_num.group(2).strip())
            continue
        if _is_subheading(s):
            flush()
            txt = s.strip("*").strip()
            parts.append("<h3 style='margin:16px 0 6px 0;color:#1e40af;font-size:15px;"
                         "font-weight:700'>" + _inline(txt) + "</h3>")
            continue
        flush()
        parts.append("<p style='margin:0 0 12px 0;color:#333;font-size:14.5px;line-height:1.7'>"
                     + _inline(s) + "</p>")
    flush()
    inner = "\n".join(parts) or ("<p style='color:#333'>" + _inline(body) + "</p>")

    hdr_title = hmod.escape(title.strip()) if title and title.strip() else "Nemo"
    try:
        import datetime as _dt
        stamp = _dt.datetime.now().strftime("%d %b %Y, %I:%M %p")
    except Exception:
        stamp = ""
    sub = "Prepared by Nemo, your personal AI assistant" + (" &nbsp;•&nbsp; " + stamp if stamp else "")

    return (
        "<div style='margin:0;padding:24px 12px;background:#eef1f6;"
        "font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif'>"
        "<div style='max-width:660px;margin:0 auto;background:#ffffff;border-radius:14px;"
        "overflow:hidden;box-shadow:0 6px 24px rgba(15,37,87,0.12)'>"
        # ---- header ----
        "<div style='background:#1e3a8a;background-image:linear-gradient(135deg,#0f2557 0%,#1e40af 60%,#2563eb 100%);"
        "padding:26px 30px 22px 30px'>"
        "<table role='presentation' cellpadding='0' cellspacing='0' style='width:100%'>"
        "<tr>"
        "<td style='vertical-align:middle'>"
        "<div style='color:#ffffff;font-size:22px;font-weight:800;letter-spacing:.3px;line-height:1.25'>"
        + hdr_title + "</div>"
        "<div style='color:#c7d7ff;font-size:12.5px;margin-top:6px'>" + sub + "</div>"
        "</td>"
        "<td style='vertical-align:middle;text-align:right;white-space:nowrap'>"
        "<span style='display:inline-block;width:44px;height:44px;border-radius:50%;"
        "background:rgba(255,255,255,0.16);color:#ffffff;font-size:20px;font-weight:800;"
        "text-align:center;line-height:44px'>N</span>"
        "</td>"
        "</tr></table>"
        "</div>"
        # ---- body ----
        "<div style='padding:28px 30px 6px 30px'>" + inner + "</div>"
        # ---- footer ----
        "<div style='background:#0f172a;padding:16px 30px;margin-top:14px'>"
        "<div style='color:#94a3b8;font-size:12px;line-height:1.6'>"
        "Sent automatically by <b style='color:#e2e8f0'>Nemo</b>, your 24x7 AI assistant. "
        "You can reply to this email or message Nemo on Telegram anytime."
        "</div></div>"
        "</div></div>")


LAST_EMAIL_ERR = ""      # plain-language reason the last email attempt failed (for REAL self-diagnosis)


def _email_diag(e):
    """Turn an SMTP/setup failure into a plain reason + the exact fix - so Nemo explains ITSELF, not email in general."""
    if not (BOT_EMAIL and BOT_EMAIL_PASS):
        return ("My email isn't connected. Easiest + most reliable: connect Google with /google - then I send over "
                "HTTPS (works even though this server blocks SMTP). Or set a Gmail App Password:\n"
                "/email set <my_gmail@gmail.com> <16-char app password>")
    s = str(e); low = s.lower()
    if "535" in s or "username and password not accepted" in low or "authenticationerror" in low or "auth" in low:
        return ("Gmail REJECTED my login (error 535) - the App Password is wrong/expired, or 2-Step Verification is "
                "off on my Gmail. Fix: turn on 2FA, make a NEW app password at myaccount.google.com → Security → "
                "App passwords, then /email set <my_gmail@gmail.com> <new app password>.  (Or just /google - HTTPS, no password needed.)")
    if any(w in low for w in ("gaierror", "name or service", "timed out", "connection", "network", "unreachable", "refused")):
        return ("I couldn't open a connection to Gmail's SMTP server. On DigitalOcean this is almost always because "
                "the host BLOCKS outbound SMTP ports - it is NOT your password. The reliable fix: connect Google "
                "with /google and I'll send over HTTPS instead (port 443, never blocked).")
    if "550" in s or "recipient" in low or "no such user" in low or "does not exist" in low:
        return "Gmail accepted my login but rejected the recipient address - double-check the email address is exactly right."
    return "Send failed: " + s[:200]


def email_selftest():
    """Report which send path ACTUALLY works, by doing a real test send - not just a profile ping. Prefers the
    Gmail API over HTTPS (unaffected by SMTP blocks); falls back to a live SMTP login. Returns (ok, message).
    v11.26: when Google is linked but the token can't SEND (scope granted before gmail.send existed), it says so
    precisely and points at the one-tap re-authorize, instead of the misleading SMTP error."""
    global LAST_EMAIL_ERR
    # 1) Gmail API over HTTPS - the path DigitalOcean's SMTP block can't touch. Prove SEND by actually sending.
    if google_ready():
        if not google_token():
            LAST_EMAIL_ERR = "google-token-refresh-failed"
            return False, ("⚠️ Google is linked, but its access token can't refresh right now. Re-authorize in one "
                           "tap: run /google and follow the link. (Nothing wrong with your password.)")
        prof = google_get("https://gmail.googleapis.com/gmail/v1/users/me/profile")
        addr = prof.get("emailAddress") if isinstance(prof, dict) else None
        if addr:
            ok, err = send_email_api(addr, "Nemo email self-test ✅",
                                     "This is Nemo confirming that email works via the Gmail API (HTTPS). "
                                     "You can ignore this message.")
            if ok:
                LAST_EMAIL_ERR = ""
                return True, ("✅ Email WORKS via the Gmail API (HTTPS). I just sent a test to " + addr +
                              " - check your inbox. This path ignores the SMTP port block completely.")
            LAST_EMAIL_ERR = err
            if re.search(r"insufficient|permission|scope|forbidden|403|ACCESS_TOKEN_SCOPE|not.*authorized", err, re.I):
                return False, ("⚠️ Google is connected, but WITHOUT Gmail SEND permission - your sign-in was done "
                               "before that permission existed. One-tap fix: run /google, open the link, tap Allow "
                               "(it now asks for send permission), then /gauth <code>. Email will work after that.")
            return False, "❌ Gmail API send failed: " + str(err)[:160] + "\nRe-authorize with /google if it persists."
        # token exists but Gmail profile call failed -> almost always a missing gmail scope
        _e = (prof or {}).get("error") if isinstance(prof, dict) else None
        LAST_EMAIL_ERR = str(_e or "gmail-scope-missing")[:200]
        return False, ("⚠️ Google is connected but the sign-in has no Gmail permission yet. Re-authorize in one tap: "
                       "run /google, approve the link (it asks for Gmail this time), then /gauth <code>.")
    # 2) SMTP fallback (only when Google isn't linked at all)
    if not (BOT_EMAIL and BOT_EMAIL_PASS):
        LAST_EMAIL_ERR = _email_diag(Exception("no creds"))
        return False, ("❌ Email isn't set up. Best fix (works on this server): run /google to send over HTTPS. "
                       "\n" + LAST_EMAIL_ERR)
    try:
        import smtplib
        with smtplib.SMTP_SSL("smtp.gmail.com", 465, timeout=20) as s:
            s.login(BOT_EMAIL, BOT_EMAIL_PASS)
        LAST_EMAIL_ERR = ""
        return True, "✅ Email works via SMTP as " + BOT_EMAIL + "."
    except Exception as e:
        LAST_EMAIL_ERR = _email_diag(e)
        return False, ("❌ " + LAST_EMAIL_ERR + "\n\nReliable fix on this server: run /google and I'll send over "
                       "HTTPS (port 443) instead - it's never blocked.")


def email_set(chat_id, gmail, app_pass):
    """Connect Nemo's Gmail from chat (no file editing), then immediately test it."""
    global BOT_EMAIL, BOT_EMAIL_PASS
    gmail = (gmail or "").strip()
    app_pass = (app_pass or "").replace(" ", "")     # Google shows app passwords with spaces; strip them
    if "@" not in gmail or len(app_pass) < 12:
        send_text(chat_id, "Usage:  /email set <my_gmail@gmail.com> <16-char app password>\n"
                  "Make the app password at myaccount.google.com → Security → App passwords (needs 2-Step "
                  "Verification ON). Paste it with or without spaces.")
        return
    BOT_EMAIL, BOT_EMAIL_PASS = gmail, app_pass
    save_secret("bot_email", BOT_EMAIL)
    save_secret("bot_email_pass", BOT_EMAIL_PASS)
    ok, msg = email_selftest()
    send_text(chat_id, ("\U0001F511 Saved and tested:\n" + msg) if ok else ("\U0001F511 Saved, but the live test failed:\n" + msg))


def _build_mime(to, subject, body, attach_path=None, frm=None):
    from email.message import EmailMessage
    m = EmailMessage()
    if frm:
        m["From"] = frm
    m["To"] = to
    m["Subject"] = subject[:150]
    m.set_content(body)
    try:
        m.add_alternative(email_html(body, subject), subtype="html")
    except Exception:
        pass
    if attach_path and os.path.exists(attach_path):
        try:
            with open(attach_path, "rb") as f:
                data = f.read()
            fn = attach_path.rsplit("/", 1)[-1]
            sub = "pdf" if fn.endswith(".pdf") else "octet-stream"
            m.add_attachment(data, maintype="application", subtype=sub, filename=fn)
        except Exception:
            pass
    return m


def send_email_api(to, subject, body, attach_path=None):
    """Send via the Gmail API over HTTPS (port 443) - works even where the host blocks SMTP (DigitalOcean).
    Uses the Google account connected with /google (has the gmail.send scope). Returns (ok, err)."""
    if not (google_ready() and google_token()):
        return False, "google-not-connected"
    try:
        import base64 as _b64
        m = _build_mime(to, subject, body, attach_path, frm=BOT_EMAIL or "me")
        raw = _b64.urlsafe_b64encode(m.as_bytes()).decode()
        j = google_post("https://gmail.googleapis.com/gmail/v1/users/me/messages/send", {"raw": raw})
        if isinstance(j, dict) and j.get("id"):
            return True, ""
        err = str((j or {}).get("error", {}).get("message") or (j or {}).get("error") or "gmail-api-send-failed")[:200]
        return False, err
    except Exception as e:
        return False, type(e).__name__ + ": " + str(e)[:150]


def send_email(to, subject, body, attach_path=None):
    global LAST_EMAIL_ERR
    # Prefer the Gmail API over HTTPS - the reliable path when the host blocks SMTP ports (DigitalOcean does).
    api_err = ""
    if google_ready():
        ok, api_err = send_email_api(to, subject, body, attach_path)
        if ok:
            LAST_EMAIL_ERR = ""
            return True
    if not (BOT_EMAIL and BOT_EMAIL_PASS):
        LAST_EMAIL_ERR = (("Gmail API send failed: " + api_err + "\nTip: re-run /google to refresh permissions.")
                          if api_err else _email_diag(Exception("no creds")))
        return False
    try:
        import smtplib
        m = _build_mime(to, subject, body, attach_path, frm=BOT_EMAIL)
        with smtplib.SMTP_SSL("smtp.gmail.com", 465, timeout=60) as s:
            s.login(BOT_EMAIL, BOT_EMAIL_PASS)
            s.send_message(m)
        LAST_EMAIL_ERR = ""
        return True
    except Exception as e:
        LAST_EMAIL_ERR = _email_diag(e)
        traceback.print_exc()
        return False


def extract_addr(frm):
    m = re.search(r"[\w.+-]+@[\w.-]+", frm or "")
    return m.group(0).lower() if m else ""


_PUNC = {"–": "-", "—": "-", "−": "-", "‘": "'", "’": "'",
         "“": '"', "”": '"', "•": "-", "…": "...", " ": " ",
         "₹": "Rs.", "→": "->", "←": "<-", "×": "x", "≥": ">=",
         "≤": "<=", "≈": "~", "±": "+/-", "’": "'", "﻿": ""}


def _norm(s):
    s = s or ""
    for k, v in _PUNC.items():
        s = s.replace(k, v)
    return s


def _lat(s):
    return _norm(s).encode("latin-1", "ignore").decode("latin-1")


def _is_heading(line):
    s = line.strip()
    if not s or len(s) > 65 or s.endswith((".", "!", "?", ",")):
        return False
    return (s.endswith(":") or s.isupper() or bool(re.match(r"^(\d+[.)]\s|section\s|part\s)", s, re.I)) or
            bool(re.match(r"^[A-Z][A-Za-z0-9 ,&/'-]{2,55}$", s)) and len(s.split()) <= 8)


def _sections(body):
    """Split body into (heading, [content lines]) sections for TOC + numbering."""
    secs = []
    cur = {"h": "Overview", "lines": []}
    for line in body.split("\n"):
        if _is_heading(line) and (cur["lines"] or secs):
            secs.append(cur)
            cur = {"h": line.strip().rstrip(":"), "lines": []}
        elif _is_heading(line) and not cur["lines"]:
            cur["h"] = line.strip().rstrip(":")
        else:
            cur["lines"].append(line)
    secs.append(cur)
    return [s for s in secs if s["h"] or s["lines"]] or [{"h": "Report", "lines": body.split("\n")}]


def simple_pdf(title, body, path):
    """Basic plain PDF (kept for compatibility)."""
    return _n75_pdf(title, body, path)


class _NemoPDF:
    pass


def _img_hw(path, w):
    """Return rendered height for an image drawn at width w (mm), keeping aspect."""
    try:
        from PIL import Image
        iw, ih = Image.open(path).size
        return w * ih / iw
    except Exception:
        return w * 0.6


def pro_pdf(title, body, path, prepared_for="Gautam", confidential=True, hero=None, figures=None):
    """v6.8 - PROFESSIONAL illustrated report: cover (with hero image), table of contents with real
    page numbers, continuously-flowing numbered sections with accent styling, inline figures, page
    numbers and a confidentiality footer. Unicode-safe."""
    try:
        from fpdf import FPDF
        NAVY = (31, 78, 121)
        GOLD = (201, 162, 39)
        date_str = time.strftime("%d %B %Y", time.gmtime(time.time() + IST_OFFSET))
        secs = _sections(body)
        figures = [f for f in (figures or []) if f and os.path.exists(f[0])]
        # spread figures across sections (one per chosen section, evenly)
        fig_at = {}
        if figures and secs:
            step = max(1, len(secs) // len(figures))
            for i, fg in enumerate(figures):
                idx = min(len(secs) - 1, i * step)
                fig_at[idx] = fg
        toc_pages = max(1, (len(secs) + 28) // 29)
        front = 1 + toc_pages

        class PDF(FPDF):
            def footer(self):
                if self.page_no() <= front:
                    return
                self.set_y(-14)
                self.set_draw_color(220, 220, 220)
                self.set_line_width(0.2)
                self.line(self.l_margin, self.get_y(), 210 - self.r_margin, self.get_y())
                self.ln(1)
                self.set_font("Helvetica", "I", 8)
                self.set_text_color(120, 120, 120)
                self.set_x(self.l_margin)
                foot = ("CONFIDENTIAL - prepared by Nemo for " + prepared_for) if confidential else \
                       ("Prepared by Nemo for " + prepared_for)
                self.cell(120, 8, _lat(foot), 0, 0, "L")
                self.cell(0, 8, "Page " + str(self.page_no() - front), 0, 0, "R")

        def render_body(pdf, record=None):
            pdf.set_auto_page_break(auto=True, margin=18)
            pdf.add_page()
            for i, s in enumerate(secs):
                # keep heading with some content: break if too near the bottom
                if pdf.get_y() > 250:
                    pdf.add_page()
                if record is not None:
                    record.append(pdf.page_no())
                # section header: gold number badge + navy title + underline
                y0 = pdf.get_y()
                pdf.set_fill_color(*GOLD)
                pdf.set_text_color(255, 255, 255)
                pdf.set_font("Helvetica", "B", 12)
                pdf.set_x(pdf.l_margin)
                pdf.cell(9, 8, str(i + 1), 0, 0, "C", fill=True)
                pdf.set_text_color(*NAVY)
                pdf.set_font("Helvetica", "B", 14)
                pdf.cell(2, 8, "", 0, 0)
                pdf.multi_cell(0, 8, _lat(s["h"]))
                pdf.set_draw_color(*GOLD)
                pdf.set_line_width(0.5)
                pdf.line(pdf.l_margin, pdf.get_y() + 0.5, 210 - pdf.r_margin, pdf.get_y() + 0.5)
                pdf.ln(4)
                # optional figure for this section
                if i in fig_at:
                    fpath, cap = fig_at[i]
                    w = 150
                    h = _img_hw(fpath, w)
                    if pdf.get_y() + h + 12 > 275:
                        pdf.add_page()
                    try:
                        pdf.image(fpath, x=(210 - w) / 2, y=pdf.get_y(), w=w)
                        pdf.set_y(pdf.get_y() + h + 2)
                        pdf.set_font("Helvetica", "I", 8)
                        pdf.set_text_color(120, 120, 120)
                        pdf.set_x(pdf.l_margin)
                        pdf.cell(0, 5, _lat("Figure: " + cap)[:110], 0, 1, "C")
                        pdf.ln(2)
                    except Exception:
                        pass
                # body text
                pdf.set_font("Helvetica", "", 11)
                pdf.set_text_color(30, 30, 30)
                for line in s["lines"]:
                    pdf.set_x(pdf.l_margin)
                    ls = line.strip()
                    if not ls:
                        pdf.ln(2.5)
                        continue
                    if len(ls) < 60 and (ls.endswith(":") or ls.isupper()):
                        pdf.set_font("Helvetica", "B", 11)
                        pdf.set_text_color(*NAVY)
                        pdf.multi_cell(0, 6, _lat(ls))
                        pdf.set_font("Helvetica", "", 11)
                        pdf.set_text_color(30, 30, 30)
                    elif ls[0] in "-*" and len(ls) > 1:
                        pdf.set_x(pdf.l_margin + 2)
                        pdf.multi_cell(0, 6, _lat("- " + ls.lstrip("-* ")))
                    else:
                        pdf.multi_cell(0, 6, _lat(line))
                pdf.ln(5)

        # ---- Pass 1: body only, to learn real page numbers ----
        p1 = PDF()
        pages = []
        render_body(p1, record=pages)
        sec_pages = [pg + front for pg in pages]

        # ---- Pass 2: cover + TOC + body ----
        pdf = PDF()
        pdf.set_auto_page_break(auto=True, margin=18)
        # ---------- COVER ----------
        pdf.add_page()
        pdf.set_fill_color(*NAVY)
        pdf.rect(0, 0, 210, 6, "F")           # top navy band
        pdf.rect(0, 291, 210, 6, "F")         # bottom navy band
        pdf.ln(28)
        if hero and os.path.exists(hero):
            w = 150
            h = min(90, _img_hw(hero, w))
            try:
                pdf.image(hero, x=(210 - w) / 2, y=pdf.get_y(), w=w, h=h)
                pdf.set_y(pdf.get_y() + h + 8)
            except Exception:
                pass
        else:
            pdf.ln(20)
        pdf.set_font("Helvetica", "B", 26)
        pdf.set_text_color(*NAVY)
        pdf.set_x(pdf.l_margin)
        pdf.multi_cell(0, 12, _lat(title[:150]), align="C")
        pdf.ln(4)
        pdf.set_draw_color(*GOLD)
        pdf.set_line_width(1)
        pdf.line(70, pdf.get_y(), 140, pdf.get_y())
        pdf.ln(8)
        pdf.set_font("Helvetica", "", 13)
        pdf.set_text_color(90, 90, 90)
        pdf.set_x(pdf.l_margin)
        pdf.cell(0, 8, _lat("Prepared by Nemo, AI Assistant of " + prepared_for), 0, 1, "C")
        pdf.set_x(pdf.l_margin)
        pdf.cell(0, 8, _lat(date_str), 0, 1, "C")
        if confidential:
            pdf.ln(6)
            pdf.set_font("Helvetica", "I", 10)
            pdf.set_text_color(150, 150, 150)
            pdf.set_x(pdf.l_margin)
            pdf.cell(0, 6, _lat("CONFIDENTIAL - for the intended recipient only"), 0, 1, "C")
        # ---------- TOC ----------
        pdf.add_page()
        pdf.set_font("Helvetica", "B", 17)
        pdf.set_text_color(*NAVY)
        pdf.set_x(pdf.l_margin)
        pdf.cell(0, 10, "Table of Contents", 0, 1)
        pdf.set_draw_color(*GOLD)
        pdf.line(pdf.l_margin, pdf.get_y(), 210 - pdf.r_margin, pdf.get_y())
        pdf.ln(4)
        pdf.set_font("Helvetica", "", 11)
        pdf.set_text_color(30, 30, 30)
        for i, s in enumerate(secs):
            pdf.set_x(pdf.l_margin)
            h = s["h"][:55]
            dots = "." * max(3, 62 - len(h))
            pdf.cell(0, 8, _lat(f"{i + 1}.  {h}  {dots}  {sec_pages[i]}"), 0, 1)
        # ---------- BODY ----------
        render_body(pdf)
        pdf.output(path)
        return os.path.getsize(path) > 600
    except Exception:
        traceback.print_exc()
        return False


def gen_report_figures(title, headings, n=3):
    """v6.8 - generate a few relevant illustrations for a report (best-effort, parallel)."""
    picks = [h for h in headings if h][:n] or [title]
    out = {}

    def one(idx, theme):
        p = f"/tmp/fig_{idx}.jpg"
        prompt = f"clean professional editorial illustration representing {theme}, subject: {title}, " \
                 "modern flat vector style, corporate report graphic, no text"
        try:
            if fetch_image(prompt, p):
                out[idx] = (p, theme)
        except Exception:
            pass

    threads = [threading.Thread(target=one, args=(i, t), daemon=True) for i, t in enumerate(picks)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=90)
    return [out[i] for i in sorted(out)]


def audit_log(recipient, path, title=""):
    """v6.6 - tamper-evident delivery log: timestamp, recipient, SHA-256 of the exact file sent."""
    try:
        import hashlib
        h = hashlib.sha256(open(path, "rb").read()).hexdigest()
        ts = time.strftime("%Y-%m-%d %H:%M:%S IST", time.gmtime(time.time() + IST_OFFSET))
        with open("/root/nemo_audit.log", "a") as f:
            f.write(f"{ts} | to: {recipient} | {title[:60]} | sha256: {h}\n")
        return h
    except Exception:
        return ""


def act_log(kind, detail):
    """v8.8 - activity ledger: record every real action Nemo takes so the Boss can review his day."""
    try:
        with LOCK:
            ACTLOG.append({"kind": kind, "detail": str(detail)[:220], "ts": time.time()})
            del ACTLOG[:-400]
    except Exception:
        pass


def email_task(addr, req, want_pdf=False):
    """v6.3 - SMART EMAIL AGENT: plan, multi-search, synthesize, self-check, deliver (with PDF for reports)."""
    if OWNER.get("id"):
        send_text(OWNER["id"], "\U0001F916 Working on an email task from " + addr + ":\n" + req[:150])
    plan = ask_ai(0, "List 3 to 4 focused web search queries that together fully answer this request. "
                  "Reply with ONLY the queries, one per line, no numbering.\nRequest: " + req,
                  remember=False, models_override=FAST_MODELS, timeout=90)
    queries = [q.strip(" -*0123456789.\t") for q in (plan or "").splitlines() if len(q.strip()) > 4][:4]
    if not queries:
        queries = [req]
    findings, sources = [], []
    for q in queries:
        for r in (web_search(q) or [])[:4]:
            findings.append(f"[{r.get('title', '')}] {r.get('body', '')[:400]}")
            if r.get("href"):
                sources.append(r["href"])
    draft = ask_ai(0, "You are Gautam's expert research analyst. Complete this task fully and deliver a finished, "
                   "well-structured report with clear section headings and specific numbers/dates. Be accurate: "
                   "use ONLY the findings below and general knowledge; if a specific figure is not in the findings, "
                   "say it needs to be confirmed rather than inventing it. For any market prices/levels/options use "
                   "ONLY the live ground-truth data if provided. Plain text, no markdown symbols.\n\n"
                   "TASK: " + req + "\n\nWEB FINDINGS:\n" + ("\n\n".join(findings[:20]) or "(no fresh web data found)"),
                   remember=False, deep=True, timeout=300, ground=market_context(req))
    _mh = market_header(req)
    if _mh:
        draft = _mh + "\n\n" + draft
    critique = ask_ai(0, "Task: " + req + "\nDraft:\n" + draft[:6000] + "\n\nList briefly anything inaccurate, "
                      "unsupported, or missing. If the draft is accurate and complete, reply only PERFECT.",
                      remember=False, models_override=FAST_MODELS, timeout=120)
    out = draft
    if "PERFECT" not in (critique or "")[:60].upper():
        improved = ask_ai(0, "Task: " + req + "\nDraft:\n" + draft[:6000] + "\nFixes needed:\n" + critique[:1500] +
                          "\nProduce the final corrected, complete report now. Plain text.",
                          remember=False, deep=True, timeout=300)
        if len(improved) > 200:
            out = improved
    uniq = []
    for s in sources:
        if s not in uniq:
            uniq.append(s)
    if uniq:
        out += "\n\nSources:\n" + "\n".join("- " + s for s in uniq[:10])
    out += "\n\n- Nemo, AI assistant of Gautam"
    is_report = want_pdf or any(w in req.lower() for w in ("report", "detailed", "analysis", "document"))
    attach = None
    if is_report:
        rtitle = make_report_title(req, out)
        heads = [s["h"] for s in _sections(out)][:3]
        figs = gen_report_figures(rtitle, heads, n=3)
        hero = figs[0][0] if figs else None
        if pro_pdf(rtitle[:120], out, "/tmp/task_report.pdf", prepared_for="Gautam",
                   hero=hero, figures=figs[1:] if len(figs) > 1 else []):
            attach = "/tmp/task_report.pdf"
    send_email(addr, "Done: " + req[:70], out, attach)
    sha = audit_log(addr, attach, req) if attach else ""
    if OWNER.get("id"):
        send_text(OWNER["id"], "✅ Emailed the finished task to " + addr +
                  (" with a professional PDF report" if attach else "") + ":\n" + req[:100] +
                  ("\n\U0001F512 Audit SHA-256: " + sha[:16] + "..." if sha else ""))


def check_inbox(force=False):
    if not (BOT_EMAIL and BOT_EMAIL_PASS and OWNER.get("id")):
        return
    try:
        import imaplib
        import email as em
        M = imaplib.IMAP4_SSL("imap.gmail.com")
        M.login(BOT_EMAIL, BOT_EMAIL_PASS)
        M.select("INBOX")
        if force:
            typ, data = M.search(None, "ALL")
            nums = (data[0].split() if data and data[0] else [])[-8:]
        else:
            typ, data = M.search(None, "UNSEEN")
            nums = (data[0].split() if data and data[0] else [])[:6]
        for num in nums:
            typ, msgdata = M.fetch(num, "(RFC822)")
            msg = em.message_from_bytes(msgdata[0][1])
            frm = str(msg.get("From", "?"))
            sub = str(msg.get("Subject", "(no subject)"))
            addr = extract_addr(frm)
            mid = str(msg.get("Message-ID", "")).strip() or (addr + "|" + sub + "|" + str(msg.get("Date", "")))
            if mid in PROCESSED:
                continue
            PROCESSED.append(mid)
            del PROCESSED[:-400]
            if not addr or any(x in addr for x in ("noreply", "no-reply", "mailer-daemon", "postmaster")):
                continue
            body = ""
            if msg.is_multipart():
                for part in msg.walk():
                    if part.get_content_type() == "text/plain":
                        body = part.get_payload(decode=True).decode("utf-8", "ignore")
                        break
            else:
                body = msg.get_payload(decode=True).decode("utf-8", "ignore")
            body = (body or "").strip()
            subl = sub.lower().strip()
            if subl.startswith("subscribe") or body.lower()[:30].strip() == "subscribe":
                if addr not in SUBS:
                    SUBS.append(addr)
                    save_data()
                send_email(addr, "Subscribed!", "You are subscribed. Reply with subject UNSUBSCRIBE to stop.")
                send_text(OWNER["id"], "\U0001F195 New email subscriber: " + addr)
                continue
            if subl.startswith("unsubscribe"):
                if addr in SUBS:
                    SUBS.remove(addr)
                    save_data()
                send_email(addr, "Unsubscribed", "You will not receive further emails. Goodbye!")
                continue
            saved = []
            try:
                if msg.is_multipart():
                    os.makedirs("/root/attachments", exist_ok=True)
                    for part in msg.walk():
                        fn = part.get_filename()
                        if fn:
                            data2 = part.get_payload(decode=True)
                            if data2 and len(data2) < 15 * 1024 * 1024:
                                safe_fn = time.strftime("%m%d_") + re.sub(r"[^\w.-]", "_", fn)[:60]
                                with open("/root/attachments/" + safe_fn, "wb") as f2:
                                    f2.write(data2)
                                saved.append(safe_fn)
            except Exception:
                pass
            with LOCK:
                for fu in [f2 for f2 in FOLLOWUP if f2.get("to") == addr]:
                    FOLLOWUP.remove(fu)
            is_cmd = subl.startswith(("task:", "ask:", "pdf:"))
            if is_cmd and (addr == OWNER_EMAIL.lower() or addr in ALLOWED):
                req = sub.split(":", 1)[1].strip() or body[:300]
                if body and len(body) > 5:
                    req = req + "\n\nDetails: " + body[:600]
                threading.Thread(target=email_task, args=(addr, req, subl.startswith("pdf:")), daemon=True).start()
                continue
            if is_cmd:
                # v6.3 - unknown sender: ask the owner to approve with one tap instead of silently refusing
                MAILN["n"] += 1
                tid = "t" + str(MAILN["n"])
                req = sub.split(":", 1)[1].strip() or body[:300]
                if body and len(body) > 5:
                    req = req + "\n\nDetails: " + body[:600]
                PENDTASK[tid] = {"addr": addr, "req": req, "pdf": subl.startswith("pdf:")}
                tg("sendMessage", chat_id=OWNER["id"],
                   text="\U0001F4E9 Email TASK from a sender not on your allow-list:\n" + addr +
                        "\nSubject: " + sub[:120] + "\n\nDo you want me to do it and reply to them?",
                   reply_markup={"inline_keyboard": [[
                       {"text": "✅ Allow & do it", "callback_data": "allowrun:" + tid},
                       {"text": "⛔ Ignore", "callback_data": "ignore:" + tid}]]})
                continue
            rule_hit = None
            blob = addr + " " + subl
            for ru in RULES:
                if ru.get("match", "") and ru["match"] in blob:
                    rule_hit = ru
                    break
            att_note = ("\n\U0001F4CE Saved attachments: " + ", ".join(saved)) if saved else ""
            if rule_hit and rule_hit.get("action") == "archive":
                continue
            if rule_hit and rule_hit.get("action") == "forward":
                send_email(OWNER_EMAIL, "Fwd: " + sub, "From: " + frm + "\n\n" + body[:5000])
                send_text(OWNER["id"], "\U0001F4E8 Forwarded per your rule: " + sub[:80] + att_note)
                continue
            pr = ask_ai(0, "Classify this email importance for a busy person. Reply ONE word only: HIGH, NORMAL or LOW."
                           "\nFrom: " + frm + "\nSubject: " + sub + "\n" + body[:500],
                        remember=False, models_override=FAST_MODELS, timeout=60)
            prw = (pr or "").strip().upper()[:6]
            if prw.startswith("LOW"):
                send_text(OWNER["id"], "\U0001F9FE Low-priority mail from " + addr + ": " + sub[:80] + att_note)
                continue
            draft_raw = ask_ai(0, "Two sections. First a line starting with SUMMARY: then 2 short lines summarizing "
                                  "the email. Then a line starting with REPLY: followed by a short polite professional "
                                  "reply (plain text), signed as: Nemo, AI assistant of Gautam. "
                                  "Never write placeholders like [Your Name].\n\n"
                                  "From: " + frm + "\nSubject: " + sub + "\n\n" + body[:2500], remember=False)
            if "REPLY:" in draft_raw:
                summ, draft = draft_raw.split("REPLY:", 1)
            else:
                summ, draft = "", draft_raw
            draft = draft.strip()
            summ = summ.replace("SUMMARY:", "").strip()
            MAILN["n"] += 1
            mid2 = str(MAILN["n"])
            PENDMAIL[mid2] = {"to": addr, "subject": "Re: " + sub[:120], "body": draft}
            head = "\u26A1 IMPORTANT email!" if prw.startswith("HIGH") else "\U0001F4E9 New email!"
            tg("sendMessage", chat_id=OWNER["id"],
               text=head + "\nFrom: " + frm + "\nSubject: " + sub + att_note +
                    ("\n\nSummary: " + summ[:400] if summ else "") + "\n\n" + body[:700] +
                    "\n\n--- My suggested reply ---\n" + draft[:1200],
               reply_markup={"inline_keyboard": [[{"text": "✉️ Approve & Send", "callback_data": "mailok:" + mid2}]]})
        M.logout()
        save_data()
    except Exception:
        pass


