def agent_step_exec(chat_id, tool, arg):
    """Execute one agent tool and return what happened, as text the AI can read."""
    try:
        if tool == "web":
            rs = web_search(arg)
            return ("\n\n".join(f"{r.get('title', '')}: {r.get('body', '')[:300]} ({r.get('href', '')})"
                                for r in rs[:4])) if rs else "No web results found."
        if tool == "open":
            try:
                r = requests.get(arg.strip(), headers={"User-Agent": "Mozilla/5.0 (Nemo reader)"}, timeout=40)
                page = strip_html(r.text)[:4000]
                return page or "Page had no readable text (may need login)."
            except Exception as e:
                return "Could not open page: " + type(e).__name__
        if tool == "quote":
            lv = fyers_quote_live(arg.strip())
            if lv:
                return (f"{arg.strip().upper()} (LIVE Fyers): {lv['price']:,.2f}" +
                        (f"  {lv['chp']:+.2f}%" if lv.get("chp") is not None else "") +
                        (f"  bid {lv['bid']} ask {lv['ask']}" if lv.get("bid") else ""))
            q = get_quote(arg.strip())
            return (f"{arg.strip().upper()}: price {q['price']:,.2f}"
                    if q else "Symbol not found.")
        if tool == "optionchain":
            oc = fyers_option_chain(arg.strip() or "NIFTY")
            if oc.startswith("X"):
                return "Option chain unavailable: " + oc[1:]
            threading.Thread(target=lambda: send_mono(chat_id, oc), daemon=True).start()
            return "LIVE option chain (from Fyers) delivered to the chat:\n" + oc[:1200]
        if tool == "godmode":
            a = godmode_analyze(arg.strip())
            if not a:
                return "No market data for that symbol."
            s = f"{a['name']} {a['price']:,.2f}: {a['signal']} (score {a['score']:+d}). " + "; ".join(a["reasons"][:5])
            if a["setup"]:
                st = a["setup"]
                s += f". Setup {st['side']} entry {st['entry']} SL {st['sl']} target {st['target']} RR 1:{st['rr']:g}"
            return s
        if tool == "library":
            return lib_search(arg) or "Nothing found in the library for that."
        if tool == "remember":
            with LOCK:
                FACTS.setdefault(chat_id, []).append(arg[:300])
            return "Fact saved permanently."
        if tool == "remind":
            mins, _, msgtxt = arg.partition("|")
            with LOCK:
                REMINDERS.append({"chat": chat_id, "at": time.time() + float(mins) * 60,
                                  "text": msgtxt.strip() or "Reminder"})
            return f"Reminder set, it will fire in {float(mins):g} minutes."
        if tool == "todo":
            with LOCK:
                TODOS.setdefault(chat_id, []).append({"text": arg[:200], "done": False})
            return "Added to the todo list."
        if tool == "email":
            sub, _, body = arg.partition("|")
            ok = send_email(OWNER_EMAIL, (sub.strip() or "Message from your bot")[:120],
                            body.strip() or sub.strip())
            return "Email sent to the owner." if ok else "Email sending failed."
        if tool == "code":
            import subprocess
            c2 = ask_ai(0, "Write a complete Python 3 script for this, print the result. Only raw code.\nTask: " +
                        arg, remember=False, deep=True, timeout=200)
            c2 = re.sub(r"^```[a-zA-Z]*\n?|```$", "", (c2 or "").strip(), flags=re.M).strip()
            try:
                os.makedirs("/root/nemo_code", exist_ok=True)
                open("/root/nemo_code/agent_job.py", "w").write(c2)
                r = subprocess.run(["python3", "/root/nemo_code/agent_job.py"], capture_output=True, text=True,
                                   timeout=CODECFG.get("timeout", 300), cwd="/root/nemo_code")
                return ((r.stdout or "") + (("\n[err] " + r.stderr) if r.stderr.strip() else ""))[:1500] or "(no output)"
            except Exception as e:
                return "code error: " + str(e)[:200]
        if tool == "pdf":
            threading.Thread(target=make_pdf, args=(chat_id, arg[:150]), daemon=True).start()
            return "PDF is being built now and will arrive in this chat in a few minutes."
        if tool == "docx":
            threading.Thread(target=make_docx, args=(chat_id, arg[:300]), daemon=True).start()
            return "Word document is being written and will arrive in this chat shortly."
        if tool == "xlsx":
            threading.Thread(target=make_xlsx, args=(chat_id, arg[:400]), daemon=True).start()
            return "Excel sheet is being built and will arrive in this chat shortly."
        if tool == "chart":
            threading.Thread(target=make_chart, args=(chat_id, arg[:400]), daemon=True).start()
            return "Chart is being generated and will arrive in this chat shortly."
        if tool == "textfile":
            threading.Thread(target=make_textfile, args=(chat_id, arg[:400]), daemon=True).start()
            return "Text file is being created and will arrive in this chat shortly."
        if tool == "image":
            threading.Thread(target=img_command, args=(chat_id, arg[:300]), daemon=True).start()
            return "Image is being created and will arrive in this chat shortly."
        if tool == "shell":
            if _SHELL_DANGER.search(arg or ""):
                return "Refused: that command is destructive; the Boss must run it manually via /shell."
            out, _cw = _shell_exec(arg, SHELL["cwd"], min(SHELL["timeout"], 120))
            v11_audit("agent_shell", (arg or "")[:200]); act_log("agent_shell", (arg or "")[:200])
            return out[:1800]
        if tool == "fetch":
            try:
                u = (arg or "").strip()
                u = u if u.startswith("http") else "https://" + u
                r = requests.get(u, headers={"User-Agent": "Mozilla/5.0 (Nemo data-grabber)"}, timeout=45)
                return _extract_site(r.text, r.headers.get("Content-Type", ""), u)[:2500] or "(empty page)"
            except Exception as e:
                return "fetch failed: " + type(e).__name__
        if tool == "readfile":
            p = _fs_path(arg)
            if not os.path.isfile(p):
                return "No such file: " + p
            try:
                return open(p, "r", errors="replace").read()[:2500] or "(empty file)"
            except Exception as e:
                return "read error: " + str(e)[:150]
        if tool == "ls":
            p = _fs_path(arg or SHELL["cwd"])
            try:
                return "\n".join(sorted(os.listdir(p))[:120]) or "(empty)"
            except Exception as e:
                return "ls error: " + str(e)[:150]
        if tool == "writefile":
            p2, _, body = (arg or "").partition("|")
            p2 = _fs_path(p2.strip())
            if re.match(r"^/(etc|bin|sbin|boot|dev|proc|sys|lib|lib64|usr/bin|usr/sbin)(/|$)", p2):
                return "Refused: writing a system path needs the Boss (/writefile)."
            try:
                d = os.path.dirname(p2)
                if d:
                    os.makedirs(d, exist_ok=True)
                open(p2, "w").write(body)
                v11_audit("agent_write", p2); act_log("agent_write", p2)
                return "Wrote " + str(len(body)) + " chars to " + p2
            except Exception as e:
                return "write error: " + str(e)[:150]
        if tool == "recall":
            parts = []
            try:
                rows = kb_search(arg, 4)
                if rows:
                    parts.append("From your files:\n" + "\n".join(
                        "[" + os.path.basename(r["path"]) + "] " + (r["chunk"] or "")[:400] for r in rows))
            except Exception:
                pass
            try:
                mv = mem_recall(arg, k=4)
                if mv:
                    parts.append("From memory:\n- " + "\n- ".join(mv))
            except Exception:
                pass
            return "\n\n".join(parts) or "Nothing found in your files or memory for that."
        if tool == "sysinfo":
            return _hands_sys_snapshot()[:2200]
        if tool == "netcheck":
            return _hands_net_diag((arg or "").strip(), compact=True)[:2200]
        if tool == "hashfile":
            p = _fs_path((arg or "").strip())
            if not os.path.isfile(p):
                return "No such file: " + p
            return p + " sha256=" + _hands_hash(p)
        if tool == "filefind":
            pat, _, root = (arg or "").partition("|")
            return _hands_filefind(pat.strip(), (root.strip() or "/root"), limit=80)
        if tool == "process":
            return _hands_process_list((arg or "").strip(), limit=30)
        if tool == "cyberaudit":
            return _cyber_audit_text(compact=True)[:3000]
        if tool == "cyberports":
            return _cyber_ports_text()[:2600]
        if tool == "cyberlogs":
            return _cyber_logs_text()[:2600]
        if tool == "api":
            mm = re.match(r"(GET|POST|PUT|DELETE|PATCH)\s+(\S+)(?:\s*::\s*(.+))?$", (arg or "").strip(), re.I | re.S)
            if not mm:
                return "api usage: 'GET https://...'  or  'POST https://... :: {json}'"
            b = None
            if mm.group(3):
                try:
                    b = json.loads(mm.group(3))
                except Exception:
                    b = mm.group(3)
            st, tx = _http_call(mm.group(1).upper(), mm.group(2), None, b)
            v11_audit("agent_api", mm.group(1).upper() + " " + mm.group(2)[:60])
            return "HTTP " + str(st) + ": " + (tx or "")[:1500]
    except Exception as e:
        return "Tool error: " + str(e)[:200]
    return "Unknown tool - pick one from the tool list."


def _resolve_refs(chat_id, request):
    """UNDERSTAND step: resolve 'it / that / the file / again / the same' from recent conversation + last answer,
    so a follow-up isn't misread (the exact failure behind 'give me the pdf here')."""
    if not re.search(r"\b(it|that|this|the file|the same|again|those|these|the last|previous|the report|the doc)\b",
                     request or "", re.I):
        return request
    ctx = []
    try:
        if CONVO.get(chat_id):
            ctx.append("Recently in this chat: " + " | ".join(CONVO[chat_id][-4:]))
        if LASTREPLY.get(chat_id):
            ctx.append("My last answer was about: " + LASTREPLY[chat_id][:280])
    except Exception:
        pass
    return request + ("\n\n[Context to resolve references like 'it/that/the file': " + " ; ".join(ctx) + "]" if ctx else "")


def _needs_clarify(chat_id, request):
    """CLARIFY gate: ask the fast brain whether ONE essential detail is genuinely missing. Returns '' when clear
    (the strong default) or a single short question. Conservative on purpose - I don't nitpick before acting."""
    try:
        # v12.0: use the PREMIUM brain for understanding (deeper judgement of what's actually being asked)
        j = _mm_brain("You are about to actually DO this task for the owner. If it is clear enough to start, "
                      "reply EXACTLY 'CLEAR'. Only if a SINGLE essential detail is truly missing and you cannot make "
                      "a reasonable assumption, reply with ONE short question. Strongly prefer CLEAR.\n\nTask: " + request,
                      timeout=45)
    except Exception:
        j = "CLEAR"
    j = (j or "CLEAR").strip()
    if j.upper().startswith("CLEAR") or "?" not in j:
        return ""
    return j.splitlines()[-1].strip()[:200]


def think_run(chat_id, request, apex=False, _clarify=True):
    """v11.27 THINK - Nemo's Claude-style operating loop, in mini form:
    UNDERSTAND (resolve references) -> CLARIFY only if a key detail is truly missing -> GATHER what he already
    knows (durable memory + your indexed files + a quick web look-up) -> then PLAN / EXECUTE / VERIFY through the
    autonomous agent (which self-checks before finishing) -> honest report. Reuses agent_run for the execute+verify
    core; the value it adds is understanding and grounding the task BEFORE acting, the way I read before I edit."""
    request = (request or "").strip()
    if not request:
        send_text(chat_id, "Tell me what to handle, e.g. /do audit my server and fix anything unhealthy.")
        return
    # 1) UNDERSTAND
    enriched = _resolve_refs(chat_id, request)
    # 2) CLARIFY (conservative; skipped in apex 'just go' mode)
    if _clarify and not apex:
        q = _needs_clarify(chat_id, request)
        if q:
            PENDING[chat_id] = {"q": request, "at": time.time()}
            send_text(chat_id, "\U0001F914 One quick thing so I get it right:\n" + q +
                      "\n\n(Just reply and I'll carry on.)")
            return
    send_text(chat_id, "\U0001F9E0 On it - understanding, gathering what I know, then doing and checking it.")
    # 3) GATHER - like reading the code before editing: pull relevant memory, files, and a quick web look-up
    ctx = []
    try:
        for m in (mem_recall(request, k=4) or []):
            ctx.append("- memory: " + str(m)[:200])
    except Exception:
        pass
    try:
        for r in (kb_search(request, k=3) or []):
            _c = (r.get("chunk") if isinstance(r, dict) else str(r)) or ""
            if _c:
                ctx.append("- your files: " + str(_c)[:200])
    except Exception:
        pass
    try:
        cg, _f = curiosity_ground(chat_id, request)
        if cg:
            ctx.append(cg)
    except Exception:
        pass
    goal = enriched
    if ctx:
        goal += "\n\nWHAT YOU ALREADY KNOW (use it, don't re-derive):\n" + "\n".join(ctx[:8])
    # 4 & 5) PLAN -> EXECUTE -> VERIFY (agent self-checks before finishing) -> honest report
    agent_run(chat_id, goal, apex=apex)


def resume_pending(chat_id, answer_text):
    """If a clarifying question was pending, treat this reply as the answer and resume the task. Returns True if it
    consumed the message. Expires after 15 min so a stale question never hijacks a new request."""
    p = PENDING.get(chat_id)
    if not p:
        return False
    if time.time() - p.get("at", 0) > 900:
        PENDING.pop(chat_id, None)
        return False
    PENDING.pop(chat_id, None)
    combined = p["q"] + "\n\n[Owner's clarification: " + (answer_text or "").strip() + "]"
    threading.Thread(target=think_run, args=(chat_id, combined), kwargs={"_clarify": False}, daemon=True).start()
    return True


# ================== v12.0 CONTINUUM: continuous work engine - he keeps working, not just answers ==================
def _work_load():
    if WORK.get("loaded"):
        return
    WORK["loaded"] = True
    try:
        import json as _j
        raw = kv_get("work_jobs")
        if raw:
            JOBS[:] = _j.loads(raw)
        WORK["on"] = (kv_get("work_on") != "0")
    except Exception:
        pass


def _work_save():
    try:
        import json as _j
        kv_set("work_jobs", _j.dumps(JOBS[-100:]))
    except Exception:
        pass


def work_add(chat_id, task):
    """Queue a job. Nemo works the queue one job at a time, autonomously, reporting each - and it survives restarts."""
    _work_load()
    task = (task or "").strip()
    if not task:
        send_text(chat_id, "What should I work on? e.g. /work research the top 5 NIFTY option strategies and make a PDF")
        return
    try:
        seq = int(kv_get("work_seq") or "0") + 1
    except Exception:
        seq = len(JOBS) + 1
    kv_set("work_seq", str(seq))
    JOBS.append({"id": str(seq), "chat": chat_id, "task": task[:800], "status": "pending",
                 "added": int(time.time()), "result": ""})
    _work_save()
    pend = sum(1 for j in JOBS if j["status"] in ("pending", "running"))
    WORK["on"] = True
    kv_set("work_on", "1")
    send_text(chat_id, "\U0001F4CB Added to my work list (#" + str(seq) + "). " + str(pend) +
              " job(s) in the queue — I'll work them one at a time and report each as it's done. /jobs to see them, "
              "/stopwork to pause.")


def work_tick():
    """Scheduler heartbeat: if idle and a job is pending, run the next one to completion in the background."""
    _work_load()
    if WORK.get("busy") or not WORK.get("on", True) or not OWNER.get("id"):
        return
    nxt = next((j for j in JOBS if j.get("status") == "pending"), None)
    if not nxt:
        return
    WORK["busy"] = True
    nxt["status"] = "running"
    _work_save()

    def _worker(job=nxt):
        try:
            send_text(job["chat"], "▶️ Working on job #" + job["id"] + ": " + job["task"][:140])
            try:
                agent_run(job["chat"], job["task"])          # plan -> act -> verify -> report (reports to chat itself)
                job["status"] = "done"
            except Exception as e:
                job["status"] = "error"
                job["result"] = str(e)[:200]
                send_text(job["chat"], "⚠️ Job #" + job["id"] + " hit an error: " + str(e)[:150] + " — moving on.")
            _work_save()
            left = sum(1 for j in JOBS if j.get("status") == "pending")
            send_text(job["chat"], "✅ Job #" + job["id"] + " finished. " +
                      (str(left) + " job(s) still queued — continuing." if left else "Work list clear."))
        finally:
            WORK["busy"] = False
    threading.Thread(target=_worker, daemon=True).start()


def work_list(chat_id):
    _work_load()
    mine = [j for j in JOBS if j.get("chat") == chat_id][-15:]
    if not mine:
        send_text(chat_id, "\U0001F4CB Work list is empty. Add a job: /work <task> (I'll work them one by one).")
        return
    icon = {"pending": "⏳", "running": "▶️", "done": "✅", "error": "⚠️"}
    lines = [icon.get(j.get("status"), "•") + " #" + j["id"] + " " + j.get("status", "") + " — " + j["task"][:70] for j in mine]
    pend = sum(1 for j in JOBS if j.get("status") == "pending")
    send_text(chat_id, "\U0001F4CB WORK LIST (" + ("running" if WORK.get("busy") else ("paused" if not WORK.get("on", True) else "idle")) +
              ", " + str(pend) + " queued):\n\n" + "\n".join(lines) + "\n\n/stopwork to pause · /work <task> to add")


def work_stop(chat_id):
    _work_load()
    n = 0
    for j in JOBS:
        if j.get("status") == "pending":
            j["status"] = "cancelled"
            n += 1
    WORK["on"] = False
    kv_set("work_on", "0")
    _work_save()
    send_text(chat_id, "⏸️ Paused the work engine and cleared " + str(n) + " queued job(s). "
              "The one in progress finishes; new /work jobs stay paused until you add one again.")


