def _cur_load():
    if CURRENCY.get("_loaded"):
        return
    CURRENCY["_loaded"] = True
    try:
        pv = kv_get("pine_ver")
        if pv and pv.isdigit():
            PINECFG["ver"] = pv
        CURRENCY["on"] = (kv_get("currency_on") != "0")
        CURRENCY["last"] = float(kv_get("currency_last") or 0)
    except Exception:
        pass


def _detect_pine_version():
    """Find the latest Pine Script version number from the live web (returns an int, or None)."""
    try:
        rs = web_search("latest Pine Script version TradingView v6 v7") or []
        blob = " ".join(((r.get("title") or "") + " " + (r.get("body") or "")) for r in rs[:6])
        found = re.findall(r"(?i)pine\s*(?:script)?\s*(?:v|version)\s*\.?\s*([0-9]{1,2})", blob) + \
            re.findall(r"//@version\s*=\s*([0-9]{1,2})", blob)
        nums = [int(x) for x in found if x.isdigit() and 4 <= int(x) <= 12]
        return max(nums) if nums else None
    except Exception:
        return None


def currency_watch(chat_id=None, manual=False):
    """Auto stay-current: research what's changed in his key fields, AUTO-apply safe settings (like the Pine
    version), learn the rest, and route code-level upgrades to the supervised self-grow rail (owner approves).
    It updates settings on its own; it never rewrites code unsupervised."""
    _cur_load()
    cid = chat_id or OWNER.get("id")
    if not cid:
        return
    CURRENCY["last"] = time.time()
    try:
        kv_set("currency_last", str(CURRENCY["last"]))
    except Exception:
        pass
    lines = []
    # 1) Pine Script version - a SAFE setting he can update himself
    v = _detect_pine_version()
    try:
        cur = int(PINECFG.get("ver", "6") or 6)
    except Exception:
        cur = 6
    if v and v > cur:
        PINECFG["ver"] = str(v)
        kv_set("pine_ver", str(v))
        lines.append("\U0001F195 Pine Script v" + str(v) + " is out — I've switched my code generator to it (was v" + str(cur) + ").")
    elif v:
        lines.append("• Pine Script: current (v" + str(cur) + ").")
    # 2) a short researched digest of what's new in his world (informational; also learned to memory)
    try:
        digest = ask_ai(cid, "In 2-4 very short bullet lines, what is genuinely NEW or CHANGED recently that matters "
                        "for: (a) TradingView Pine Script, (b) SEBI rules for Indian traders, (c) AI models/tools an "
                        "assistant like you would use. Only real, recent changes; if unsure, say 'no major change'. "
                        "Plain text.", remember=False, timeout=60)
        if digest and "no major change" not in digest.lower():
            lines.append("What changed lately:\n" + digest.strip()[:700])
            try:
                learn_from_web(cid, "recent changes in Pine/SEBI/AI", [{"title": "currency", "body": digest[:400], "href": ""}])
            except Exception:
                pass
    except Exception:
        pass
    if manual or lines:
        send_text(cid, "\U0001F6F0 STAY-CURRENT CHECK:\n\n" + ("\n".join(lines) if lines else "Nothing material changed.") +
                  "\n\nSafe settings I update myself; anything code-level I'll PROPOSE via /selfgrow for your one-tap "
                  "approval (I never rewrite myself unsupervised). /current off to stop these checks.")


