def agent_run(chat_id, goal, apex=False):
    """TRUE AGENT MODE: the AI plans, picks its own tools, executes step by step, then reports.
    apex=True = APEX/GODMODE: more steps, exhaustive, uses every tool - still within the safety rails."""
    _lbl = "⚡ APEX / GODMODE" if apex else "\U0001F916 AGENT MODE"
    ph = tg("sendMessage", chat_id=chat_id,
            text=_lbl + "\nGoal: " + goal[:200] + "\n\n\U0001F501 Step 1: thinking...")
    mid = ph.get("result", {}).get("message_id")
    steps_log, notes, final = [], "", ""
    checks = 0
    # v12.0.1: stop the duplicate-flood - a deliverable is made ONCE, and the same tool+arg never repeats.
    _DELIVER_ONCE = {"pdf", "report", "docx", "word", "xlsx", "excel", "chart", "image", "img", "ppt", "slides",
                     "podcast", "textfile", "pine", "video"}
    done_calls, delivered, skips = set(), set(), 0
    for step in range(1, (19 if apex else 13)):
        prompt = ("CONSTITUTION: never fabricate tool results; label facts vs inference; show uncertainty; "
                  "irreversible or high-impact actions need the Boss's approval.\n"
                  "RESOURCEFULNESS: if you're missing a fact or detail needed to proceed, find it out YOURSELF with "
                  "web / fetch / recall — never stop to ask the Boss for something you can look up.\n" +
                  ("APEX / GODMODE - MAXIMUM effort: use EVERY tool that helps (shell, fetch, readfile, ls, code, "
                   "web, recall, quote, godmode, pdf...), be exhaustive, cross-check facts, and VERIFY before you "
                   "finish.\n" if apex else "") +
                  "You are in AGENT MODE with real working tools.\nGOAL: " + goal +
                  "\n\nTOOLS (use exactly one per step):\n" + AGENT_TOOLS +
                  "\n\nWork done so far:\n" + (notes or "(nothing yet - this is step 1)") +
                  "\n\nReply with ONLY one single-line JSON object and nothing else. Formats:\n"
                  '{"tool":"web","arg":"best free python course 2026"}\n'
                  '{"tool":"remind","minutes":60,"text":"call the bank"}\n'
                  '{"tool":"email","subject":"Report","body":"full text here"}\n'
                  '{"tool":"finish","arg":"the complete final answer, plain text"}\n'
                  "Rules: never repeat a step already done. Never invent tool results - call the tool. "
                  "Use finish as soon as the goal is truly complete, with the FULL useful result in arg.")
        raw = ask_ai(chat_id, prompt, remember=False, timeout=150)
        act = None
        try:
            j0, j1 = raw.find("{"), raw.rfind("}")
            if j0 >= 0 and j1 > j0:
                act = json.loads(raw[j0:j1 + 1])
        except Exception:
            act = None
        if not isinstance(act, dict) or not act.get("tool"):
            final = raw  # model answered directly - accept it as the result
            break
        tool = str(act.get("tool", "")).lower().strip()
        if tool == "finish":
            proposed = str(act.get("arg") or act.get("answer") or act.get("text") or "").strip() or raw
            # plan -> act -> CHECK -> report: verify the goal is truly met before accepting 'finish', else adapt.
            if checks < 2 and len(proposed) > 1:
                verdict = _mm_brain("OBJECTIVE:\n" + goal + "\n\nWORK LOG:\n" + notes[-3500:] +
                                    "\n\nPROPOSED FINAL ANSWER:\n" + proposed[:3000] +
                                    "\n\nHas the objective been FULLY and correctly achieved? Be strict - if a real part "
                                    "is missing, wrong, or unverified, it is NOT done. Reply ONLY single-line JSON: "
                                    '{"done":true|false,"missing":"the ONE concrete thing to do next if not done"}',
                                    timeout=70)
                _done, _missing = True, ""
                try:
                    _vj = json.loads(verdict[verdict.find("{"):verdict.rfind("}") + 1])
                    _done = bool(_vj.get("done", True))
                    _missing = str(_vj.get("missing", ""))[:400]
                except Exception:
                    _done = True
                if not _done and _missing:
                    checks += 1
                    notes += ("\n[SELF-CHECK] Not finished yet - still missing: " + _missing +
                              "\nDo the next action to fix exactly this; do not finish until it's addressed.")
                    steps_log.append("\U0001F50E Checked my own work - not complete, fixing: " + _missing[:70])
                    if mid:
                        tg("editMessageText", chat_id=chat_id, message_id=mid,
                           text="\U0001F916 AGENT MODE\nGoal: " + goal[:200] + "\n\n" + "\n".join(steps_log) +
                                "\n\U0001F501 Adapting to finish it properly...")
                    continue
            final = proposed
            break
        if tool == "email":
            arg = str(act.get("subject", act.get("arg", ""))) + "|" + str(act.get("body", ""))
        elif tool == "remind":
            arg = str(act.get("minutes", act.get("arg", "30"))) + "|" + str(act.get("text", "Reminder"))
        elif tool == "writefile":
            arg = str(act.get("path", act.get("arg", ""))) + "|" + str(act.get("content", ""))
        else:
            arg = str(act.get("arg") or act.get("query") or act.get("text") or "")
        # v12.0.1: block the flood - a delivered file is made once; identical tool+arg calls are skipped.
        _dk = tool + "::" + re.sub(r"\s+", " ", (arg or "")[:120]).strip().lower()
        if (tool in _DELIVER_ONCE and tool in delivered) or (_dk in done_calls):
            skips += 1
            notes += ("\n[SKIPPED] '" + tool + "' was already done this run — repeating it just makes a duplicate. "
                      "Do a genuinely DIFFERENT action, or finish now with the result you already have.")
            steps_log.append("✓ skipped repeat of " + tool)
            if skips >= 3:
                break                              # it's stuck re-proposing the same thing -> go straight to the report
            continue
        skips = 0
        done_calls.add(_dk)
        obs = agent_step_exec(chat_id, tool, arg)
        if tool in _DELIVER_ONCE:
            delivered.add(tool)
        steps_log.append(f"✅ Step {step}: {tool} - {arg.replace(chr(10), ' ')[:70]}")
        notes += f"\nStep {step}: used {tool} with '{arg[:150]}'. Result: {obs[:700]}\n"
        if mid:
            tg("editMessageText", chat_id=chat_id, message_id=mid,
               text="\U0001F916 AGENT MODE\nGoal: " + goal[:200] + "\n\n" + "\n".join(steps_log) +
                    f"\n\U0001F501 Step {step + 1}: thinking...")
    if not final:
        final = ask_ai(chat_id, "GOAL was: " + goal + "\nWork completed:\n" + notes[-4000:] +
                       "\nWrite the complete final answer for the user now. Plain text only.",
                       remember=False, deep=True, timeout=180)
    report = "\U0001F3AF " + ("APEX / GODMODE" if apex else "AGENT") + " FINISHED\nGoal: " + goal[:200] + "\n\n" + final
    if steps_log:
        report += "\n\n\U0001F527 Steps I took myself:\n" + "\n".join(steps_log)
    deliver(chat_id, mid, report, buttons=True)
    save_data()


# ==================== PHASE 8: NEMO AGENCY - a team of AI specialists Nemo commands ====================

def agent_work(chat_id, name, role, task):
    """One specialist does its part. v7.2: remembers its own past work (persistent specialist memory)."""
    ctx = ""
    try:
        rs = web_search(task)
        if rs:
            ctx = "\n\nWeb findings you may use:\n" + "\n\n".join(
                f"[{r.get('title', '')}] {r.get('body', '')[:300]}" for r in rs[:3])
    except Exception:
        pass
    mem = TEAMMEM.get(chat_id, {}).get(name, [])
    memctx = ("\n\nYour own memory from past jobs (build on it, stay consistent):\n- " +
              "\n- ".join(str(m)[:180] for m in mem[-4:])) if mem else ""
    out = ask_ai(chat_id, f"You are {name}, a {role} working as part of Gautam's AI team. Do ONLY your part of "
                 "the work, thoroughly, concretely and accurately. If a fact is uncertain, say so rather than "
                 "inventing it. Plain text, no markdown.\n"
                 "IMPORTANT: Nemo already has his own working email, PDF, image and delivery tools. You NEVER "
                 "handle sending or formatting and must NEVER ask for SMTP details, API keys, credentials, or a "
                 "recipient address - delivery is fully automatic. Do not write 'execution notes', setup steps, or "
                 "requests for inputs. Just produce your finished expert content." + memctx +
                 "\n\nYour task: " + task + ctx,
                 remember=False, deep=True, timeout=240)
    out = out or "(no output)"
    with LOCK:
        tm = TEAMMEM.setdefault(chat_id, {}).setdefault(name, [])
        tm.append(task[:80] + " -> " + out[:180])
        del tm[:-12]
        st = AGENTSTAT.setdefault(chat_id, {}).setdefault(name, {"jobs": 0})
        st["jobs"] += 1
    return out


def run_mission(chat_id, mission):
    """BOSS orchestration: plan -> delegate to specialists in parallel -> synthesize one deliverable."""
    ph = tg("sendMessage", chat_id=chat_id,
            text="\U0001F454 MISSION received:\n" + mission[:200] + "\n\n\U0001F9E0 Assembling the team...")
    mid = ph.get("result", {}).get("message_id")
    roster = TEAM.get(chat_id, {})
    roster_txt = "; ".join(f"{n} ({r})" for n, r in roster.items()) if roster else \
        "no fixed team yet - invent 2 to 4 suitable expert specialists for this mission"
    plan_raw = ask_ai(chat_id, "You are the team leader. Split this mission into 2 to 4 clear subtasks, each given "
                      "to one specialist. Available team: " + roster_txt + ".\nGive each specialist a DIFFERENT "
                      "first name (never repeat a name) and a role that fits their subtask.\nReply with ONLY a JSON "
                      "list, like:\n"
                      '[{"name":"Ravi","role":"equity research analyst","subtask":"..."},'
                      '{"name":"Priya","role":"news analyst","subtask":"..."}]\nMission: ' + mission,
                      remember=False, models_override=FAST_MODELS, timeout=120)
    tasks = None
    try:
        j0, j1 = plan_raw.find("["), plan_raw.rfind("]")
        tasks = json.loads(plan_raw[j0:j1 + 1])
    except Exception:
        tasks = None
    if not isinstance(tasks, list) or not tasks:
        tasks = [{"name": "Analyst", "role": "expert analyst", "subtask": mission}]
    tasks = [t for t in tasks if isinstance(t, dict) and t.get("subtask")][:4]
    # The model sometimes gives every specialist the SAME name - force distinct names so the team is
    # real people AND so results don't overwrite each other (they're keyed per specialist below).
    _NAMEPOOL = ["Ravi", "Priya", "Arjun", "Meera", "Karan", "Anita", "Vikram", "Neha", "Rohan", "Sara"]
    _used = set()
    for i, t in enumerate(tasks):
        nm = (t.get("name") or "").strip()
        if not nm or nm.lower() in _used:
            nm = next((x for x in _NAMEPOOL if x.lower() not in _used), "Agent" + str(i + 1))
        t["name"] = nm
        _used.add(nm.lower())
    if mid:
        tg("editMessageText", chat_id=chat_id, message_id=mid,
           text="\U0001F454 MISSION: " + mission[:150] + "\n\n\U0001F91D Team dispatched:\n" +
                "\n".join(f"- {t['name']} ({t.get('role', 'specialist')}) -> {t['subtask'][:60]}"
                          for t in tasks) + "\n\n⏳ Everyone is working in parallel - a full illustrated report "
                "takes about 3-6 minutes. I'll ping you as each specialist finishes.")
    results = {}

    def worker(idx, t):
        nm = t["name"]
        out = agent_work(chat_id, nm, t.get("role", "specialist"), t["subtask"])
        # v7.2 B2 - manager quality gate: review and send back for one revision if below bar
        crit = ask_ai(chat_id, "You are the demanding team manager. Specialist " + nm + " produced this for the "
                      "task '" + t["subtask"][:100] + "':\n" + out[:3000] + "\n\nIs it thorough, accurate and "
                      "complete? If yes reply only PASS. If not, list the specific gaps in 2-3 short lines.",
                      remember=False, models_override=FAST_MODELS, timeout=90)
        if crit and "PASS" not in (crit or "")[:15].upper():
            improved = ask_ai(chat_id, "You are " + nm + ". Improve your work using the manager's feedback.\nTask: " +
                              t["subtask"] + "\nYour draft:\n" + out[:3000] + "\nManager feedback:\n" + crit[:800] +
                              "\nProduce the improved, complete final version.", remember=False, deep=True, timeout=200)
            if improved and len(improved) > 100:
                out = improved
        results[idx] = (nm + " (" + t.get("role", "specialist") + ")", out)
        try:
            send_text(chat_id, "\U00002705 " + nm + " finished their part (" +
                      str(len(results)) + "/" + str(len(tasks)) + " done).")
        except Exception:
            pass

    threads = []
    for i, t in enumerate(tasks):
        th = threading.Thread(target=worker, args=(i, t), daemon=True)
        th.start()
        threads.append(th)
    for th in threads:
        th.join(timeout=220)
    send_text(chat_id, "\U0001F9E9 Everyone's in - the team leader is now combining it all into the final report...")
    combined = "\n\n".join(f"=== {results[i][0]} ===\n{results[i][1]}" for i in sorted(results)) or "(no results)"
    final = ask_ai(chat_id, "You are the team leader writing the FINAL report for Gautam by combining your "
                   "specialists' work. Make it genuinely detailed and useful, not a summary of one-liners.\n"
                   "Structure: an 'Executive Summary' section (4-6 lines), then 5-9 clearly titled sections, each "
                   "with a SHORT title line on its own, followed by a solid paragraph or several detailed points "
                   "with specific numbers, names and dates. End with a 'Conclusion & Recommendation' section.\n"
                   "Write full sentences and enough depth that each section fills real space. Remove overlap, "
                   "resolve conflicts, stay accurate (say 'to be confirmed' rather than inventing figures).\n"
                   "IMPORTANT: output ONLY the finished document - no 'execution notes', no requests for "
                   "credentials/SMTP/recipient, no how-to-send commentary. Delivery is automatic. Plain text, no "
                   "markdown symbols like # or *.\n\nMission: " + mission +
                   "\n\nSpecialist contributions:\n" + combined[:9000], remember=False, deep=True, timeout=320)
    _em = re.search(r"[\w.+-]+@[\w-]+\.[\w.-]+", mission or "")
    send_text(chat_id, "\U0001F4C4 Formatting the illustrated report" +
              ((" and emailing it to " + _em.group(0) + "...") if (_em and "email" in mission.lower()) else "...") +
              " (almost there)")
    note = team_deliver(chat_id, mission[:70], final, mission)
    report = "\U0001F3AF MISSION COMPLETE: " + mission[:150] + "\n\n" + final + \
             "\n\n\U0001F465 Team: " + ", ".join(results.keys()) + note
    deliver(chat_id, mid, report, buttons=True)
    save_data()


def make_report_title(request_text, text):
    """v6.8 - a crisp professional report title instead of the raw command."""
    t = ask_ai(0, "Give a short, professional report TITLE (5-9 words, Title Case, no quotes, no 'report of') "
               "for this document. Reply with ONLY the title.\nRequest: " + (request_text or "")[:200] +
               "\nContent start: " + (text or "")[:400], remember=False, models_override=FAST_MODELS, timeout=50)
    t = _norm((t or "").strip().strip('"').splitlines()[0]) if t else ""
    if not t or len(t) > 90 or t.lower().startswith(("i ", "here", "sure", "title")):
        t = (request_text or "Report").strip().rstrip(".")[:70]
    return t


def team_deliver(chat_id, title, text, request_text):
    """v6.5+ - the team DELIVERS: illustrated professional PDF / email / image when the job asks."""
    rl = (request_text or "").lower()
    notes = []
    made_pdf = False
    sha = ""
    rtitle = title
    if any(w in rl for w in ("pdf", "report", "note ", "document", "write-up", "writeup", "brief")):
        rtitle = make_report_title(request_text, text)
        heads = [s["h"] for s in _sections(text)][:3]
        figs = gen_report_figures(rtitle, heads, n=3)
        hero = figs[0][0] if figs else None
        inline = figs[1:] if len(figs) > 1 else []
        if pro_pdf(rtitle[:120], text, "/tmp/mission.pdf", hero=hero, figures=inline):
            fn = re.sub(r"[^A-Za-z0-9]+", "_", rtitle)[:40] + ".pdf"
            send_document(chat_id, "/tmp/mission.pdf", fn, "application/pdf")
            made_pdf = True
            notes.append(f"illustrated PDF ({len(figs)} figures)" if figs else "professional PDF")
    if "email" in rl and BOT_EMAIL and BOT_EMAIL_PASS:
        _m = re.search(r"[\w.+-]+@[\w-]+\.[\w.-]+", request_text or "")
        to_addr = _m.group(0) if _m else OWNER_EMAIL
        if send_email(to_addr, rtitle[:70], text, "/tmp/mission.pdf" if made_pdf else None):
            notes.append("emailed to " + to_addr)
            act_log("email", "mission report '" + rtitle[:40] + "' -> " + to_addr)
            if made_pdf:
                sha = audit_log(to_addr, "/tmp/mission.pdf", rtitle)
    if any(w in rl for w in ("image", "poster", "picture", "logo", "diagram", "illustration")):
        threading.Thread(target=img_command, args=(chat_id, title), daemon=True).start()
        notes.append("image being created")
    out = ("\n\U0001F4E6 Delivered: " + ", ".join(notes)) if notes else ""
    if sha:
        out += "\n\U0001F512 Audit ID (SHA-256): " + sha[:16] + "... (full log: /audit)"
    return out


def run_debate(chat_id, question):
    """v6.5 - DEBATE MODE: two specialists argue opposite sides, a judge gives the verdict."""
    ph = tg("sendMessage", chat_id=chat_id,
            text="⚖️ DEBATE: " + question[:180] + "\n\nTwo experts are preparing opposite cases...")
    mid = ph.get("result", {}).get("message_id")
    sides = {}

    def arg(side, stance):
        sides[side] = ask_ai(chat_id, f"You are a sharp debater arguing the {stance} case on: {question}\n"
                             "Give your strongest, honest, specific arguments in 4-6 short points. Plain text.",
                             remember=False, deep=True, timeout=200)

    tA = threading.Thread(target=arg, args=("FOR", "YES / in-favour"), daemon=True)
    tB = threading.Thread(target=arg, args=("AGAINST", "NO / against"), daemon=True)
    tA.start()
    tB.start()
    tA.join(timeout=250)
    tB.join(timeout=250)
    verdict = ask_ai(chat_id, "You are a fair, wise judge. Weigh both cases on the question: " + question +
                     "\n\nCASE FOR:\n" + sides.get("FOR", "")[:2500] + "\n\nCASE AGAINST:\n" +
                     sides.get("AGAINST", "")[:2500] + "\n\nGive a balanced verdict: which side is stronger and "
                     "why, key trade-offs, and your clear recommendation. Plain text.",
                     remember=False, deep=True, timeout=250)
    out = ("⚖️ DEBATE: " + question[:180] + "\n\n\U0001F7E2 THE CASE FOR:\n" + sides.get("FOR", "(none)") +
           "\n\n\U0001F534 THE CASE AGAINST:\n" + sides.get("AGAINST", "(none)") +
           "\n\n\U0001F3DB VERDICT:\n" + verdict)
    deliver(chat_id, mid, out, buttons=True)


