def get_quote(sym):
    sym = sym.upper()
    for s in (sym, sym + ".NS", sym + "-USD"):
        try:
            r = requests.get("https://query1.finance.yahoo.com/v8/finance/chart/" + s,
                             params={"range": "1d", "interval": "5m"},
                             headers={"User-Agent": "Mozilla/5.0"}, timeout=20)
            meta = r.json()["chart"]["result"][0]["meta"]
            price = meta.get("regularMarketPrice")
            if price is None:
                continue
            prev = meta.get("chartPreviousClose")
            return {"name": s, "price": float(price), "prev": float(prev) if prev else None,
                    "cur": meta.get("currency", "")}
        except Exception:
            continue
    return None


def get_history(sym):
    sym = sym.upper()
    for s in (sym, sym + ".NS", sym + "-USD"):
        try:
            r = requests.get("https://query1.finance.yahoo.com/v8/finance/chart/" + s,
                             params={"range": "3mo", "interval": "1d"},
                             headers={"User-Agent": "Mozilla/5.0"}, timeout=20)
            res = r.json()["chart"]["result"][0]
            q = res["indicators"]["quote"][0]
            closes = [c for c in q["close"] if c]
            highs = [c for c in q["high"] if c]
            lows = [c for c in q["low"] if c]
            if len(closes) > 30:
                return {"name": res["meta"].get("symbol", s), "closes": closes,
                        "highs": highs, "lows": lows, "cur": res["meta"].get("currency", "")}
        except Exception:
            continue
    return None


def rsi14(closes):
    gains, losses = [], []
    for i in range(1, len(closes)):
        d = closes[i] - closes[i - 1]
        gains.append(max(d, 0))
        losses.append(max(-d, 0))
    if len(gains) < 14:
        return None
    ag = sum(gains[-14:]) / 14
    al = sum(losses[-14:]) / 14
    if al == 0:
        return 100.0
    return 100 - 100 / (1 + ag / al)


def _ema_series(vals, p):
    k = 2.0 / (p + 1)
    out = [vals[0]]
    for v in vals[1:]:
        out.append(v * k + out[-1] * (1 - k))
    return out


def _atr(highs, lows, closes, p=14):
    n = min(len(highs), len(lows), len(closes))
    if n < p + 1:
        return None
    trs = []
    for i in range(1, n):
        trs.append(max(highs[i] - lows[i], abs(highs[i] - closes[i - 1]), abs(lows[i] - closes[i - 1])))
    return sum(trs[-p:]) / p


def resolve_sym(sym):
    return INDEX_MAP.get(re.sub(r"[^A-Z0-9]", "", (sym or "").upper()), sym)


def fyers_resolve(sym):
    """Map a plain/Yahoo symbol to a Fyers symbol. Compound index names (BANKNIFTY, FINNIFTY,
    MIDCPNIFTY, NIFTYNXT50) MUST be matched before plain NIFTY, since 'NIFTY' is a substring of
    all of them - otherwise BANKNIFTY would wrongly resolve to NIFTY50."""
    su = re.sub(r"[^A-Z0-9]", "", (sym or "").upper())
    pairs = [("BANKNIFTY", "NSE:NIFTYBANK-INDEX"), ("NIFTYBANK", "NSE:NIFTYBANK-INDEX"),
             ("NSEBANK", "NSE:NIFTYBANK-INDEX"),
             ("FINNIFTY", "NSE:FINNIFTY-INDEX"), ("CNXFIN", "NSE:FINNIFTY-INDEX"),
             ("MIDCPNIFTY", "NSE:MIDCPNIFTY-INDEX"), ("MIDCAPNIFTY", "NSE:MIDCPNIFTY-INDEX"),
             ("NIFTYNXT50", "NSE:NIFTYNXT50-INDEX"), ("NIFTYNEXT50", "NSE:NIFTYNXT50-INDEX"),
             ("SENSEX", "BSE:SENSEX-INDEX"), ("BSESN", "BSE:SENSEX-INDEX"),
             ("BANKEX", "BSE:BANKEX-INDEX"),
             ("NIFTY50", "NSE:NIFTY50-INDEX"), ("NIFTY", "NSE:NIFTY50-INDEX"), ("NSEI", "NSE:NIFTY50-INDEX")]
    for k, v in pairs:            # exact match wins first
        if su == k:
            return v
    if ":" in (sym or ""):        # already a Fyers symbol
        return sym
    for k, v in pairs:            # then substring - compound names are ordered before plain NIFTY
        if k in su:
            return v
    base = re.sub(r"\.NS$|-EQ$", "", (sym or "").upper())
    return "NSE:" + base + "-EQ"


def godmode_analyze(sym):
    """GODMODE strategy - multi-indicator confluence on real price data. Returns a full structured read."""
    h = None
    if fyers_ready():                          # v7.1 - prefer accurate Fyers NSE data
        h = fyers_history(fyers_resolve(sym))
    if not h:                                  # fallback to free Yahoo data
        h = get_history(resolve_sym(sym))
    if not h or len(h["closes"]) < 50:
        return None
    c = h["closes"]
    hi, lo = h["highs"], h["lows"]
    last = c[-1]
    ema20 = _ema_series(c, 20)[-1]
    ema50 = _ema_series(c, 50)[-1]
    ema20_prev = _ema_series(c[:-5], 20)[-1] if len(c) > 25 else ema20
    rsi = rsi14(c) or 50
    macd_line = [a - b for a, b in zip(_ema_series(c, 12), _ema_series(c, 26))]
    sig = _ema_series(macd_line, 9)
    hist = [m - s for m, s in zip(macd_line, sig)]
    hist_now, hist_prev = hist[-1], hist[-2]
    atr = _atr(hi, lo, c) or (last * 0.015)
    hi3, lo3 = max(hi), min(lo)
    dh, dl = hi[-1], lo[-1]
    piv = (dh + dl + last) / 3
    r1, s1 = 2 * piv - dl, 2 * piv - dh
    r2, s2 = piv + (dh - dl), piv - (dh - dl)

    score = 0
    reasons = []
    ema_gap = abs(ema20 - ema50) / last if last else 0
    trending = ema_gap > 0.0015   # EMAs must be meaningfully apart (>0.15%) to call a real trend
    if trending and last > ema20 and ema20 > ema50:
        score += 2
        reasons.append("Price above rising EMA20 > EMA50 (uptrend)")
    elif trending and last < ema20 and ema20 < ema50:
        score -= 2
        reasons.append("Price below EMA20 < EMA50 (downtrend)")
    else:
        reasons.append("EMA20 and EMA50 tangled - no clear trend (range)")
    if ema20 > ema20_prev:
        score += 1
        reasons.append("EMA20 slope up")
    elif ema20 < ema20_prev:
        score -= 1
        reasons.append("EMA20 slope down")
    if rsi >= 55:
        score += 1
        reasons.append(f"RSI {rsi:.0f} (bullish momentum)")
    elif rsi <= 45:
        score -= 1
        reasons.append(f"RSI {rsi:.0f} (bearish momentum)")
    if rsi >= 75:
        reasons.append("RSI overbought - caution on longs")
    if rsi <= 25:
        reasons.append("RSI oversold - caution on shorts")
    if hist_now > 0 and hist_now > hist_prev:
        score += 1
        reasons.append("MACD positive and rising")
    elif hist_now < 0 and hist_now < hist_prev:
        score -= 1
        reasons.append("MACD negative and falling")
    if last >= hi3 * 0.98:
        score += 1
        reasons.append("Near 3-month high (breakout zone)")
    if last <= lo3 * 1.02:
        score -= 1
        reasons.append("Near 3-month low (breakdown zone)")

    if score >= 4:
        signal, bias = "STRONG BULLISH", "long"
    elif score >= 2:
        signal, bias = "BULLISH", "long"
    elif score <= -4:
        signal, bias = "STRONG BEARISH", "short"
    elif score <= -2:
        signal, bias = "BEARISH", "short"
    else:
        signal, bias = "NEUTRAL / SIDEWAYS", "none"

    setup = None
    if bias == "long":
        entry = last
        sl = round(entry - 1.5 * atr, 2)
        tgt = round(entry + 3 * atr, 2)
        setup = {"side": "BUY", "entry": round(entry, 2), "sl": sl, "target": tgt,
                 "rr": round((tgt - entry) / (entry - sl), 2) if entry > sl else 0}
    elif bias == "short":
        entry = last
        sl = round(entry + 1.5 * atr, 2)
        tgt = round(entry - 3 * atr, 2)
        setup = {"side": "SELL", "entry": round(entry, 2), "sl": sl, "target": tgt,
                 "rr": round((entry - tgt) / (sl - entry), 2) if sl > entry else 0}
    return {"name": h["name"], "cur": h.get("cur", ""), "price": last, "signal": signal, "score": score,
            "bias": bias, "reasons": reasons, "setup": setup, "rsi": rsi,
            "ema20": ema20, "ema50": ema50, "atr": atr, "levels": {"r1": r1, "r2": r2, "s1": s1, "s2": s2},
            "hi3": hi3, "lo3": lo3}


def _score_at(c, hi, lo):
    """v8.4 - the SAME GODMODE confluence score, computed on a window ending at the last bar.
    Used by the backtest so it scores each historical day with only the data available then."""
    if len(c) < 50:
        return None
    last = c[-1]
    ema20 = _ema_series(c, 20)[-1]
    ema50 = _ema_series(c, 50)[-1]
    ema20_prev = _ema_series(c[:-5], 20)[-1] if len(c) > 25 else ema20
    rsi = rsi14(c) or 50
    macd_line = [a - b for a, b in zip(_ema_series(c, 12), _ema_series(c, 26))]
    sig = _ema_series(macd_line, 9)
    hist = [m - s for m, s in zip(macd_line, sig)]
    hist_now, hist_prev = hist[-1], hist[-2]
    atr = _atr(hi, lo, c) or (last * 0.015)
    hi3, lo3 = max(hi), min(lo)
    score = 0
    ema_gap = abs(ema20 - ema50) / last if last else 0
    trending = ema_gap > 0.0015
    if trending and last > ema20 > ema50:
        score += 2
    elif trending and last < ema20 < ema50:
        score -= 2
    if ema20 > ema20_prev:
        score += 1
    elif ema20 < ema20_prev:
        score -= 1
    if rsi >= 55:
        score += 1
    elif rsi <= 45:
        score -= 1
    if hist_now > 0 and hist_now > hist_prev:
        score += 1
    elif hist_now < 0 and hist_now < hist_prev:
        score -= 1
    if last >= hi3 * 0.98:
        score += 1
    if last <= lo3 * 1.02:
        score -= 1
    return {"score": score, "atr": atr, "price": last}


def backtest(sym, maxbars=15):
    """v8.4 - HONEST backtest of the GODMODE strategy on daily history (no look-ahead): at each bar it
    scores using only past data; on a strong signal (|score|>=4) it enters and exits at 1.5xATR stop,
    3xATR target, or after maxbars days. Returns stats dict or None."""
    h = None
    if fyers_ready():
        h = fyers_history(fyers_resolve(sym), days=400)
    if not h:
        h = get_history(resolve_sym(sym))
    if not h or len(h["closes"]) < 120:
        return None
    c, hi, lo = h["closes"], h["highs"], h["lows"]
    n = len(c)
    trades = []
    i = 60
    while i < n - 1:
        w0 = max(0, i - 119)
        s = _score_at(c[w0:i + 1], hi[w0:i + 1], lo[w0:i + 1])
        if not s:
            i += 1
            continue
        score, atr, entry = s["score"], s["atr"], c[i]
        side = "long" if score >= 4 else "short" if score <= -4 else None
        if not side:
            i += 1
            continue
        if side == "long":
            sl, tgt = entry - 1.5 * atr, entry + 3 * atr
        else:
            sl, tgt = entry + 1.5 * atr, entry - 3 * atr
        end = min(i + 1 + maxbars, n)
        exit_i, pnl = end - 1, None
        for j in range(i + 1, end):
            if side == "long":
                if lo[j] <= sl:
                    exit_i, pnl = j, sl - entry
                    break
                if hi[j] >= tgt:
                    exit_i, pnl = j, tgt - entry
                    break
            else:
                if hi[j] >= sl:
                    exit_i, pnl = j, entry - sl
                    break
                if lo[j] <= tgt:
                    exit_i, pnl = j, entry - tgt
                    break
        if pnl is None:  # time-based exit at last bar's close
            exitp = c[exit_i]
            pnl = (exitp - entry) if side == "long" else (entry - exitp)
        trades.append({"side": side, "entry": entry, "pnl": pnl, "win": pnl > 0,
                       "pct": (pnl / entry * 100) if entry else 0})
        i = exit_i + 1
    if not trades:
        return {"name": h["name"], "bars": n, "trades": 0}
    wins = [t for t in trades if t["win"]]
    losses = [t for t in trades if not t["win"]]
    gross_w = sum(t["pnl"] for t in wins)
    gross_l = -sum(t["pnl"] for t in losses)
    # equity curve for max drawdown (in points)
    eq, peak, mdd = 0.0, 0.0, 0.0
    for t in trades:
        eq += t["pnl"]
        peak = max(peak, eq)
        mdd = max(mdd, peak - eq)
    tot_pct = sum(t["pct"] for t in trades)
    return {"name": h["name"], "bars": n, "trades": len(trades), "wins": len(wins), "losses": len(losses),
            "winrate": len(wins) / len(trades) * 100, "net_pts": eq, "net_pct": tot_pct,
            "avg_win": (gross_w / len(wins)) if wins else 0, "avg_loss": (gross_l / len(losses)) if losses else 0,
            "pf": (gross_w / gross_l) if gross_l else float("inf"), "mdd_pts": mdd,
            "best": max(t["pct"] for t in trades), "worst": min(t["pct"] for t in trades)}


def backtest_report(chat_id, sym):
    """Run the backtest and deliver a clean scorecard."""
    tg("sendMessage", chat_id=chat_id, text="\U0001F9EA Backtesting the GODMODE strategy on " +
       sym.upper() + " over ~1-2 years of daily history...")
    r = backtest(sym)
    if not r:
        send_text(chat_id, "Not enough history to backtest " + sym.upper() + ". Try NIFTY, BANKNIFTY, RELIANCE, TCS...")
        return
    if r.get("trades", 0) == 0:
        send_text(chat_id, "Backtest ran on " + r["name"] + " but the strategy took NO trades in this window "
                  "(no strong signals) - that's the system being selective, not a bug.")
        return
    pf = r["pf"]
    pf_s = "inf" if pf == float("inf") else f"{pf:.2f}"
    nl = chr(10)
    body = ["GODMODE BACKTEST - " + r["name"], f"({r['bars']} trading days of history)", "",
            f"Trades taken:   {r['trades']}",
            f"Win rate:       {r['winrate']:.0f}%   ({r['wins']}W / {r['losses']}L)",
            f"Net result:     {r['net_pct']:+.1f}%   ({r['net_pts']:+,.0f} points)",
            f"Avg win:        {r['avg_win']:+,.0f} pts   Avg loss: {-r['avg_loss']:,.0f} pts",
            f"Profit factor:  {pf_s}   (>1 = profitable; >1.5 = strong)",
            f"Max drawdown:   {r['mdd_pts']:,.0f} pts",
            f"Best / worst:   {r['best']:+.1f}% / {r['worst']:+.1f}%", "",
            "Rules: enter on confluence score >= 4 (or <= -4), 1.5xATR stop, 3xATR target, 15-day time-exit.",
            "Daily-bar, no look-ahead. Educational only, not advice - real options P&L differs from index points."]
    send_mono(chat_id, nl.join(body))


