def _b64(s):
    return base64.b64encode(str(s).encode()).decode()


def fyers_today():
    return time.strftime("%Y-%m-%d", time.gmtime(time.time() + IST_OFFSET))


def fyers_ready():
    return bool(BROKER.get("token") and BROKER.get("day") == fyers_today())


def fyers_login():
    """v6.9.3 - AUTOMATIC daily login. Uses the 15-day refresh token first (official, reliable);
    only if there is none does it try the legacy TOTP auto-flow."""
    b = BROKER
    # Preferred hands-free path: refresh token (set once via /brokerurl, lasts 15 days)
    if b.get("refresh"):
        t = fyers_refresh()
        if t:
            return t
    if not (b["app_id"] and b["secret"] and b["user"] and b["totp"] and b["pin"]):
        b["last_err"] = "Fyers credentials incomplete"
        return None
    try:
        import pyotp
    except ImportError:
        b["last_err"] = "pyotp not installed (pip3 install pyotp --break-system-packages)"
        return None
    try:
        s = requests.Session()
        h = {"Content-Type": "application/json", "Accept": "application/json",
             "User-Agent": "Mozilla/5.0", "Origin": "https://api-t2.fyers.in"}
        r = s.post("https://api-t2.fyers.in/vagator/v2/send_login_otp_v2",
                   json={"fy_id": _b64(b["user"]), "app_id": "2"}, headers=h, timeout=30)
        rk = r.json().get("request_key")
        if not rk:
            b["last_err"] = "send_otp: " + r.text[:200]
            return None
        r = s.post("https://api-t2.fyers.in/vagator/v2/verify_otp",
                   json={"request_key": rk, "otp": pyotp.TOTP(b["totp"]).now()}, headers=h, timeout=30)
        rk = r.json().get("request_key")
        if not rk:
            b["last_err"] = "verify_otp: " + r.text[:200]
            return None
        r = s.post("https://api-t2.fyers.in/vagator/v2/verify_pin_v2",
                   json={"request_key": rk, "identity_type": "pin", "identifier": _b64(b["pin"])},
                   headers=h, timeout=30)
        vtoken = (r.json().get("data") or {}).get("access_token")
        if not vtoken:
            b["last_err"] = "verify_pin: " + r.text[:200]
            return None
        appid = b["app_id"].split("-")[0]
        derived = b["app_id"].split("-")[1] if "-" in b["app_id"] else "100"
        url = ""
        for apptype in [derived, "100", "200"]:
            r = s.post("https://api.fyers.in/api/v2/token",
                       headers={"Authorization": "Bearer " + vtoken, "Content-Type": "application/json"},
                       json={"fyers_id": b["user"], "app_id": appid, "redirect_uri": b["redirect"],
                             "appType": apptype, "code_challenge": "", "state": "nemo", "scope": "",
                             "nonce": "", "response_type": "code", "create_cookie": True}, timeout=30)
            url = r.json().get("Url") or ""
            if "auth_code=" in url:
                break
        m = re.search(r"auth_code=([^&]+)", url)
        if not m:
            b["last_err"] = "auth_code: " + (r.text[:200])
            return None
        auth_code = m.group(1)
        apphash = hashlib.sha256((b["app_id"] + ":" + b["secret"]).encode()).hexdigest()
        r = requests.post("https://api-t1.fyers.in/api/v3/validate-authcode",
                          json={"grant_type": "authorization_code", "appIdHash": apphash, "code": auth_code},
                          timeout=30)
        j = r.json()
        tok = j.get("access_token")
        if not tok:
            b["last_err"] = "validate: " + r.text[:200]
            return None
        b["token"], b["day"], b["last_err"] = tok, fyers_today(), ""
        save_secret("fyers_token", tok)
        save_secret("fyers_day", b["day"])
        if j.get("refresh_token"):
            b["refresh"], b["refresh_day"] = j["refresh_token"], fyers_today()
            save_secret("fyers_refresh", b["refresh"])
            save_secret("fyers_refresh_day", b["refresh_day"])
        return tok
    except Exception as e:
        b["last_err"] = type(e).__name__ + ": " + str(e)[:180]
        return None


def fyers_authcode_url():
    return ("https://api-t1.fyers.in/api/v3/generate-authcode?client_id=" + BROKER["app_id"] +
            "&redirect_uri=" + BROKER["redirect"] + "&response_type=code&state=nemo")


def fyers_exchange(auth_code):
    """Exchange a browser auth_code for the access token AND the 15-day refresh token (for auto-login)."""
    try:
        apphash = hashlib.sha256((BROKER["app_id"] + ":" + BROKER["secret"]).encode()).hexdigest()
        r = requests.post("https://api-t1.fyers.in/api/v3/validate-authcode",
                          json={"grant_type": "authorization_code", "appIdHash": apphash,
                                "code": auth_code.strip()}, timeout=30)
        j = r.json()
        tok = j.get("access_token")
        if tok:
            BROKER["token"], BROKER["day"], BROKER["last_err"] = tok, fyers_today(), ""
            save_secret("fyers_token", tok)
            save_secret("fyers_day", BROKER["day"])
            rft = j.get("refresh_token")
            if rft:
                BROKER["refresh"], BROKER["refresh_day"] = rft, fyers_today()
                save_secret("fyers_refresh", rft)
                save_secret("fyers_refresh_day", BROKER["refresh_day"])
                return True, "Token saved + AUTO-LOGIN armed for 15 days (I refresh daily on my own now)."
            return True, "Token saved for today."
        return False, str(j)[:220]
    except Exception as e:
        return False, type(e).__name__ + ": " + str(e)[:150]


def fyers_refresh():
    """v6.9.3 - AUTOMATIC daily login: use the 15-day refresh token + PIN to mint today's access token.
    No browser, no TOTP - this is the official hands-free path."""
    if not (BROKER.get("refresh") and BROKER.get("pin") and BROKER.get("app_id") and BROKER.get("secret")):
        return None
    try:
        apphash = hashlib.sha256((BROKER["app_id"] + ":" + BROKER["secret"]).encode()).hexdigest()
        r = requests.post("https://api-t1.fyers.in/api/v3/validate-refresh-token",
                          json={"grant_type": "refresh_token", "appIdHash": apphash,
                                "refresh_token": BROKER["refresh"], "pin": str(BROKER["pin"])}, timeout=30)
        j = r.json()
        tok = j.get("access_token")
        if tok:
            BROKER["token"], BROKER["day"], BROKER["last_err"] = tok, fyers_today(), ""
            save_secret("fyers_token", tok)
            save_secret("fyers_day", BROKER["day"])
            return tok
        BROKER["last_err"] = "refresh: " + str(j)[:200]
        return None
    except Exception as e:
        BROKER["last_err"] = "refresh: " + type(e).__name__ + " " + str(e)[:150]
        return None


def fyers_get(path):
    try:
        r = requests.get("https://api-t1.fyers.in/api/v3/" + path,
                         headers={"Authorization": BROKER["app_id"] + ":" + BROKER["token"]}, timeout=30)
        return r.json()
    except Exception as e:
        return {"s": "error", "message": str(e)[:150]}


def fyers_data(path):
    """Fyers /data/ endpoints (quotes, option chain)."""
    try:
        r = requests.get("https://api-t1.fyers.in/data/" + path,
                         headers={"Authorization": BROKER["app_id"] + ":" + BROKER["token"]}, timeout=20)
        return r.json()
    except Exception as e:
        return {"s": "error", "message": str(e)[:150]}


def fyers_ltp(symbol):
    j = fyers_data("quotes?symbols=" + symbol)
    try:
        return float(j["d"][0]["v"]["lp"])
    except Exception:
        return None


def index_atm_option(index, bullish):
    """v7.7 - pick the at-the-money CE (bullish) or PE (bearish) for ANY index's nearest expiry.
    index: NIFTY / BANKNIFTY / FINNIFTY / MIDCPNIFTY / SENSEX. Returns (option_symbol, ltp, lot_qty) or None."""
    und = _oc_underlying(index)
    j = fyers_data(f"options-chain-v3?symbol={und}&strikecount=3")
    try:
        d = j.get("data", {}) or {}
        chain = d.get("optionsChain") or d.get("options_chain") or []
        spot = None
        for o in chain:
            if str(o.get("symbol", "")).endswith("-INDEX") or str(o.get("option_type", "")).upper() in ("", "XX"):
                spot = o.get("ltp") or spot
        if spot is None:
            spot = d.get("indiavixData", {}).get("ltp") or d.get("ltp")
        want = "CE" if bullish else "PE"
        cands = [o for o in chain if str(o.get("option_type", "")).upper() == want and o.get("symbol")]
        if not cands:
            return None
        if spot:
            atm = min(cands, key=lambda o: abs((o.get("strike_price") or o.get("strikePrice") or 0) - spot))
        else:
            atm = cands[len(cands) // 2]
        sym = atm["symbol"]
        ltp = atm.get("ltp") or fyers_ltp(sym)
        return (sym, float(ltp), lot_size(sym) or 1) if ltp else None
    except Exception:
        return None


def nifty_atm_option(bullish):
    """NIFTY at-the-money option (thin wrapper over index_atm_option). Returns (symbol, ltp)."""
    r = index_atm_option("NIFTY", bullish)
    return (r[0], r[1]) if r else None


def fyers_depth(symbol):
    """v7.7 - live 5-level market depth (order book) from the Fyers REST endpoint. Reliable and works
    on demand without the socket. Indices have no order book, so this returns None for them."""
    if not (fyers_ready() or fyers_login()):
        return None
    fs = symbol if ":" in (symbol or "") else fyers_resolve(symbol)
    if fs.upper().endswith("-INDEX"):
        return {"index": True, "sym": fs, "ltp": fyers_ltp(fs)}
    j = fyers_data(f"depth?symbol={fs}&ohlcv_flag=1")
    try:
        dd = j.get("d") or {}
        node = dd.get(fs) or (list(dd.values())[0] if dd else None)
        if not node:
            return None
        return {"index": False, "sym": fs, "ltp": node.get("ltp"),
                "bids": node.get("bids") or [], "asks": node.get("ask") or node.get("asks") or [],
                "buyqty": node.get("totalbuyqty") or node.get("tot_buy_qty"),
                "sellqty": node.get("totalsellqty") or node.get("tot_sell_qty"),
                "o": node.get("o"), "h": node.get("h"), "l": node.get("l"),
                "c": node.get("c"), "v": node.get("v"), "chp": node.get("chp")}
    except Exception:
        return None


def _oc_underlying(symbol):
    """Resolve a spoken name to the Fyers underlying for the option chain."""
    s = re.sub(r"[^A-Z0-9]", "", (symbol or "NIFTY").upper())
    idx = {"NIFTY": "NSE:NIFTY50-INDEX", "NIFTY50": "NSE:NIFTY50-INDEX",
           "BANKNIFTY": "NSE:NIFTYBANK-INDEX", "NIFTYBANK": "NSE:NIFTYBANK-INDEX",
           "FINNIFTY": "NSE:FINNIFTY-INDEX", "MIDCPNIFTY": "NSE:MIDCPNIFTY-INDEX",
           "MIDCAPNIFTY": "NSE:MIDCPNIFTY-INDEX", "SENSEX": "BSE:SENSEX-INDEX",
           "BANKEX": "BSE:BANKEX-INDEX", "NIFTYNXT50": "NSE:NIFTYNXT50-INDEX"}
    for k, v in idx.items():
        if k == s:
            return v
    if ":" in (symbol or ""):
        return symbol
    return "NSE:" + s + "-EQ"


def fyers_option_chain(symbol="NIFTY", strikes=8):
    """v7.5 - LIVE option chain straight from FYERS (real exchange data, not the NSE website).
    Returns a clean text table with LTP, OI, IV and PCR. Error strings start with 'X'."""
    if not fyers_ready() and not fyers_login():
        return "XFyers is not logged in yet - " + (BROKER.get("last_err") or "do the one-time /brokerurl login")
    und = _oc_underlying(symbol)
    cnt = max(1, min(int(strikes or 8), 20))
    j = fyers_data(f"options-chain-v3?symbol={und}&strikecount={cnt}")
    d = (j.get("data") or {}) if isinstance(j, dict) else {}
    chain = d.get("optionsChain") or d.get("options_chain") or []
    if not chain:
        return "XCould not read the chain from Fyers (" + str((isinstance(j, dict) and (j.get("message") or j.get("s"))) or "no data")[:120] + ")"

    def g(o, *keys):
        for k in keys:
            v = o.get(k)
            if v not in (None, ""):
                return v
        return None

    spot = None
    rows = {}
    for o in chain:
        sy = str(o.get("symbol", ""))
        ot = str(g(o, "option_type", "optionType") or "").upper()
        if sy.endswith("-INDEX") or ot in ("", "XX"):
            spot = g(o, "ltp", "fp") or spot
            continue
        if ot not in ("CE", "PE"):
            continue
        sp = g(o, "strike_price", "strikePrice", "strike")
        if sp is None:
            continue
        rows.setdefault(float(sp), {})[ot] = {
            "ltp": g(o, "ltp"), "oi": g(o, "oi", "openInterest", "open_interest"),
            "iv": g(o, "iv", "impliedVolatility", "implied_volatility"),
            "chp": g(o, "ltpchp", "ltpch")}
    if not rows:
        return "XThe Fyers chain returned no CE/PE strikes."
    allsp = sorted(rows)
    atm = min(allsp, key=lambda x: abs(x - spot)) if spot else allsp[len(allsp) // 2]
    tot_ce = sum((rows[x].get("CE", {}).get("oi") or 0) for x in allsp)
    tot_pe = sum((rows[x].get("PE", {}).get("oi") or 0) for x in allsp)
    pcr = (tot_pe / tot_ce) if tot_ce else 0.0
    atm_iv = (rows[atm].get("CE", {}) or {}).get("iv") or (rows[atm].get("PE", {}) or {}).get("iv")

    def k(v):
        if v is None:
            return "-"
        v = float(v)
        return f"{v/100000:.1f}L" if v >= 100000 else f"{v/1000:.0f}k" if v >= 1000 else f"{v:.0f}"

    def p(v):
        return "-" if v is None else f"{float(v):,.1f}"

    nl = chr(10)
    L = ["OPTION CHAIN - LIVE from FYERS   " + re.sub(r"[^A-Z0-9]", "", symbol.upper())]
    if spot:
        L.append(f"Spot {float(spot):,.2f}   ATM {atm:,.0f}   PCR {pcr:.2f}" +
                 (f"   ATM-IV {float(atm_iv):.1f}%" if atm_iv else ""))
    L.append("")
    L.append(" CALL-OI  CALL-LTP | STRIKE | PUT-LTP  PUT-OI")
    L.append("-" * 44)
    for x in allsp:
        ce = rows[x].get("CE", {}) or {}
        pe = rows[x].get("PE", {}) or {}
        star = " *ATM" if x == atm else ""
        L.append(f"{k(ce.get('oi')):>7} {p(ce.get('ltp')):>9} |{x:>7,.0f} | {p(pe.get('ltp')):>8} {k(pe.get('oi')):>6}{star}")
    L.append("-" * 44)
    bias = ("PUT-heavy -> bullish tilt" if pcr > 1.15 else
            "CALL-heavy -> bearish tilt" if (0 < pcr < 0.85) else "balanced")
    L.append(f"PCR {pcr:.2f} = {bias}")
    L.append("Real exchange data via your Fyers login. Educational, not advice.")
    return nl.join(L)


def send_mono(chat_id, text):
    """Send a monospace (aligned) block so tables line up on the phone."""
    for i in range(0, len(text), 3800):
        tg("sendMessage", chat_id=chat_id, text="```\n" + text[i:i + 3800] + "\n```", parse_mode="Markdown")


def oc_deliver(chat_id, sym="NIFTY"):
    """Fetch the live Fyers option chain and deliver it (aligned table, or a clear reason if unavailable)."""
    oc = fyers_option_chain(sym or "NIFTY")
    if oc.startswith("X"):
        send_text(chat_id, "\U0001F4C9 " + oc[1:])
    else:
        send_mono(chat_id, oc)


def fyers_quote_live(symbol):
    """v7.5 - real-time quote from Fyers when logged in (price, change, bid/ask, volume, OI)."""
    if not (fyers_ready() or fyers_login()):
        return None
    fs = fyers_resolve(symbol)
