def fyers_history(fyers_symbol, days=120):
    """v7.1 - accurate NSE daily history from Fyers. Returns {closes,highs,lows} or None."""
    try:
        end = int(time.time())
        start = end - days * 86400
        j = fyers_data(f"history?symbol={fyers_symbol}&resolution=D&date_format=0&range_from={start}"
                       f"&range_to={end}&cont_flag=1")
        candles = j.get("candles") or []
        if len(candles) < 30:
            return None
        return {"name": fyers_symbol, "closes": [c[4] for c in candles],
                "highs": [c[2] for c in candles], "lows": [c[3] for c in candles], "cur": "INR"}
    except Exception:
        return None


