# ============================ v8.4 EVERYDAY FREE ABILITIES (no API key needed) ============================
_WCODE = {0: "clear sky", 1: "mainly clear", 2: "partly cloudy", 3: "overcast", 45: "fog", 48: "rime fog",
          51: "light drizzle", 53: "drizzle", 55: "heavy drizzle", 61: "light rain", 63: "rain", 65: "heavy rain",
          71: "light snow", 73: "snow", 75: "heavy snow", 80: "rain showers", 81: "rain showers", 82: "violent showers",
          95: "thunderstorm", 96: "thunderstorm w/ hail", 99: "severe thunderstorm"}


def get_weather(city):
    """Free weather via Open-Meteo (no key): current + 3-day forecast for a city name."""
    try:
        g = requests.get("https://geocoding-api.open-meteo.com/v1/search",
                         params={"name": city, "count": 1}, timeout=20).json()
        res = (g.get("results") or [])
        if not res:
            return "Couldn't find a place called '" + city + "'."
        p = res[0]
        lat, lon = p["latitude"], p["longitude"]
        place = p["name"] + (", " + p.get("country", "") if p.get("country") else "")
        w = requests.get("https://api.open-meteo.com/v1/forecast",
                         params={"latitude": lat, "longitude": lon,
                                 "current": "temperature_2m,relative_humidity_2m,weather_code,wind_speed_10m",
                                 "daily": "temperature_2m_max,temperature_2m_min,precipitation_probability_max,weather_code",
                                 "timezone": "auto", "forecast_days": 3}, timeout=20).json()
        cur = w.get("current", {})
        d = w.get("daily", {})
        nl = chr(10)
        out = [f"\U0001F324 Weather - {place}",
               f"Now: {cur.get('temperature_2m')}C, {_WCODE.get(cur.get('weather_code'), '')}, "
               f"humidity {cur.get('relative_humidity_2m')}%, wind {cur.get('wind_speed_10m')} km/h", ""]
        days = d.get("time", [])
        for i in range(min(3, len(days))):
            out.append(f"{days[i]}: {d['temperature_2m_min'][i]:.0f}-{d['temperature_2m_max'][i]:.0f}C, "
                       f"{_WCODE.get(d['weather_code'][i], '')}, rain {d['precipitation_probability_max'][i]}%")
        return nl.join(out)
    except Exception as e:
        return "Weather lookup failed: " + type(e).__name__


def get_fx(base, quote, amount=1.0):
    """Free currency conversion via Frankfurter (ECB rates, no key)."""
    try:
        base, quote = base.upper(), quote.upper()
        r = requests.get("https://api.frankfurter.app/latest",
                         params={"from": base, "to": quote, "amount": amount}, timeout=20).json()
        rate = (r.get("rates") or {}).get(quote)
        if rate is None:
            return "Couldn't convert " + base + " to " + quote + " (check the currency codes)."
        return f"\U0001F4B1 {amount:g} {base} = {rate:,.2f} {quote}  (rate {rate/amount:,.4f}, ECB {r.get('date','')})"
    except Exception as e:
        return "Currency lookup failed: " + type(e).__name__


def get_crypto(coin):
    """Free crypto price via CoinGecko (no key). Accepts a name/id like bitcoin, ethereum, solana."""
    try:
        cid = re.sub(r"[^a-z0-9\- ]", "", (coin or "bitcoin").lower().strip()).replace(" ", "-")
        alias = {"btc": "bitcoin", "eth": "ethereum", "sol": "solana", "bnb": "binancecoin",
                 "xrp": "ripple", "doge": "dogecoin", "ada": "cardano", "matic": "matic-network"}
        cid = alias.get(cid, cid)
        r = requests.get("https://api.coingecko.com/api/v3/simple/price",
                         params={"ids": cid, "vs_currencies": "inr,usd", "include_24hr_change": "true"},
                         timeout=20).json()
        d = r.get(cid)
        if not d:
            return "Couldn't find crypto '" + coin + "'. Try bitcoin, ethereum, solana..."
        ch = d.get("usd_24h_change", 0) or 0
        return (f"\U0001FA99 {cid.title()}: Rs.{d.get('inr', 0):,.0f}  |  ${d.get('usd', 0):,.2f}  "
                f"({ch:+.2f}% 24h)")
    except Exception as e:
        return "Crypto lookup failed: " + type(e).__name__


def get_directions(text):
    """Free geocoding + straight-line distance via OpenStreetMap Nominatim (no key). text = 'A to B'."""
    try:
        parts = re.split(r"\s+to\s+|\s*->\s*|\s*-\s*", text, maxsplit=1, flags=re.I)
        if len(parts) < 2:
            return "Tell me two places, e.g. 'directions from Mumbai to Pune'."
        a = parts[0].replace("directions", "").replace("from", "").strip()
        b = parts[1].strip()

        def geo(place):
            r = requests.get("https://nominatim.openstreetmap.org/search",
                             params={"q": place, "format": "json", "limit": 1},
                             headers={"User-Agent": "NemoBot/1.0"}, timeout=20).json()
            return (float(r[0]["lat"]), float(r[0]["lon"]), r[0]["display_name"]) if r else None
        ga, gb = geo(a), geo(b)
        if not ga or not gb:
            return "Couldn't find one of those places."
        import math
        la1, lo1, la2, lo2 = math.radians(ga[0]), math.radians(ga[1]), math.radians(gb[0]), math.radians(gb[1])
        d = 6371 * 2 * math.asin(math.sqrt(math.sin((la2 - la1) / 2) ** 2 +
                                           math.cos(la1) * math.cos(la2) * math.sin((lo2 - lo1) / 2) ** 2))
        return (f"\U0001F5FA {ga[2].split(',')[0]} -> {gb[2].split(',')[0]}\n"
                f"Straight-line distance: {d:,.0f} km\n"
                f"Route map: https://www.openstreetmap.org/directions?from={ga[0]},{ga[1]}&to={gb[0]},{gb[1]}")
    except Exception as e:
        return "Directions lookup failed: " + type(e).__name__


def get_ifsc(code):
    """Free bank branch lookup by IFSC (Razorpay IFSC API, no key)."""
    try:
        c = re.sub(r"[^A-Za-z0-9]", "", code or "").upper()
        r = requests.get("https://ifsc.razorpay.com/" + c, timeout=20)
        if r.status_code != 200:
            return "No bank found for IFSC '" + c + "'."
        d = r.json()
        return (f"\U0001F3E6 {d.get('BANK','')}\nBranch: {d.get('BRANCH','')}\n"
                f"{d.get('ADDRESS','')}\nCity: {d.get('CITY','')}, {d.get('STATE','')}\n"
                f"IFSC: {d.get('IFSC', c)}  MICR: {d.get('MICR','-')}\nUPI: {d.get('UPI')}  RTGS: {d.get('RTGS')}")
    except Exception as e:
        return "IFSC lookup failed: " + type(e).__name__


