def request_order(chat_id, side, fsym, qty, ordtype="plain", sl=0.0, tp=0.0, stop=0.0):
    """Place a live order - directly, or behind a one-tap CONFIRM if money-confirm is on."""
    try:
        if mm_locked():
            send_text(chat_id, "\U0001F512 Lockdown is ON - live orders are blocked. Send /unlock to trade again.")
            return
    except Exception:
        pass
    def _fire():
        if ordtype == "bracket":
            ok, m = fyers_place_bracket(fsym, side, qty, sl, tp)
        elif ordtype == "cover":
            ok, m = fyers_place_cover(fsym, side, qty, stop)
        else:
            ok, m = fyers_place(fsym, side, qty)
        send_text(chat_id, ("✅ " + m) if ok else ("❌ " + m))
    desc = f"{side} {qty} {fsym}" + ("" if ordtype == "plain" else f" [{ordtype}]")
    if MONEYCFG.get("confirm"):
        MAILN["n"] += 1
        oid = "od" + str(MAILN["n"])
        PENDORDER[oid] = {"fire": _fire, "desc": desc, "at": time.time()}
        kb = {"inline_keyboard": [[{"text": "✅ Confirm order", "callback_data": "ordok:" + oid},
                                   {"text": "⛔ Cancel", "callback_data": "ordno:" + oid}]]}
        tg("sendMessage", chat_id=chat_id, text="\U0001F6E1 Confirm this REAL money order:\n" + desc, reply_markup=kb)
    else:
        threading.Thread(target=_fire, daemon=True).start()


def translate_text(text, target="en"):
    """Free translation. Tries a public LibreTranslate; falls back to the LLM if unavailable."""
    try:
        r = requests.post("https://translate.astian.org/translate",
                          json={"q": text, "source": "auto", "target": target, "format": "text"}, timeout=20)
        if r.status_code == 200:
            t = r.json().get("translatedText")
            if t:
                return "\U0001F310 " + t
    except Exception:
        pass
    out = ask_ai(0, "Translate this into " + target + " (language name or code). Reply with ONLY the translation:\n\n"
                 + text, remember=False, models_override=FAST_MODELS, timeout=60)
    return "\U0001F310 " + (out or text)


def wiki_summary(query):
    """Free factual lookup via Wikipedia REST summary (no key)."""
    try:
        import urllib.parse
        s = requests.get("https://en.wikipedia.org/w/api.php",
                         params={"action": "query", "list": "search", "srsearch": query,
                                 "format": "json", "srlimit": 1}, timeout=20,
                         headers={"User-Agent": "NemoBot/1.0"}).json()
        hits = s.get("query", {}).get("search", [])
        if not hits:
            return "Nothing on Wikipedia for '" + query + "'."
        title = hits[0]["title"]
        r = requests.get("https://en.wikipedia.org/api/rest_v1/page/summary/" +
                         urllib.parse.quote(title.replace(" ", "_")), timeout=20,
                         headers={"User-Agent": "NemoBot/1.0"}).json()
        extract = r.get("extract") or ""
        if not extract:
            return "Found '" + title + "' but no summary available."
        return "\U0001F4D6 " + title + "\n\n" + extract[:1500]
    except Exception as e:
        return "Wikipedia lookup failed: " + type(e).__name__


# ============================ v8.5 GOOGLE - Calendar + Gmail + Drive ============================
GOOGLE_SCOPES = ("https://www.googleapis.com/auth/calendar "
                 "https://www.googleapis.com/auth/gmail.modify "
                 "https://www.googleapis.com/auth/gmail.send "
                 "https://www.googleapis.com/auth/drive "
                 "https://www.googleapis.com/auth/spreadsheets "        # v10.15 Phase 1: Sheets
                 "https://www.googleapis.com/auth/documents "           # Docs
                 "https://www.googleapis.com/auth/tasks "               # Tasks
                 "https://www.googleapis.com/auth/contacts")            # Contacts (People API)


def google_ready():
    return bool(GOOGLE.get("refresh") and GOOGLE.get("client_id"))


def google_auth_url():
    from urllib.parse import urlencode
    return "https://accounts.google.com/o/oauth2/v2/auth?" + urlencode({
        "client_id": GOOGLE["client_id"], "redirect_uri": "http://localhost",
        "response_type": "code", "scope": GOOGLE_SCOPES,
        "access_type": "offline", "prompt": "consent"})


def google_exchange(code):
    """Exchange the one-time consent code for a long-lived refresh token."""
    try:
        r = requests.post("https://oauth2.googleapis.com/token", data={
            "code": code.strip(), "client_id": GOOGLE["client_id"], "client_secret": GOOGLE["client_secret"],
            "redirect_uri": "http://localhost", "grant_type": "authorization_code"}, timeout=30)
        j = r.json()
        if j.get("refresh_token"):
            GOOGLE["refresh"] = j["refresh_token"]
            GOOGLE["token"] = j.get("access_token", "")
            GOOGLE["token_exp"] = time.time() + int(j.get("expires_in", 3500))
            save_secret("google_refresh", GOOGLE["refresh"])
            return True, "Google connected - Calendar, Gmail and Drive are now linked."
        return False, str(j.get("error_description") or j)[:200]
    except Exception as e:
        return False, type(e).__name__ + ": " + str(e)[:150]


def google_token():
    """A valid access token, auto-refreshed from the stored refresh token."""
    if GOOGLE.get("token") and time.time() < GOOGLE.get("token_exp", 0) - 60:
        return GOOGLE["token"]
    if not google_ready():
        return None
    try:
        r = requests.post("https://oauth2.googleapis.com/token", data={
            "refresh_token": GOOGLE["refresh"], "client_id": GOOGLE["client_id"],
            "client_secret": GOOGLE["client_secret"], "grant_type": "refresh_token"}, timeout=30)
        j = r.json()
        if j.get("access_token"):
            GOOGLE["token"] = j["access_token"]
            GOOGLE["token_exp"] = time.time() + int(j.get("expires_in", 3500))
            return GOOGLE["token"]
    except Exception:
        pass
    return None


def google_get(url, params=None):
    tok = google_token()
    if not tok:
        return None
    try:
        return requests.get(url, headers={"Authorization": "Bearer " + tok}, params=params, timeout=30).json()
    except Exception:
        return None


def google_post(url, body):
    tok = google_token()
    if not tok:
        return None
    try:
        return requests.post(url, headers={"Authorization": "Bearer " + tok, "Content-Type": "application/json"},
                             json=body, timeout=30).json()
    except Exception:
        return None


def gcal_upcoming(days=2):
    """Upcoming Google Calendar events for the next N days. Returns a list."""
    tmin = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    tmax = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() + days * 86400))
    j = google_get("https://www.googleapis.com/calendar/v3/calendars/primary/events",
                   {"timeMin": tmin, "timeMax": tmax, "singleEvents": "true",
                    "orderBy": "startTime", "maxResults": 20})
    if not j:
        return None
    out = []
    for e in j.get("items", []):
        st = e.get("start", {})
        when = st.get("dateTime") or st.get("date") or ""
        out.append({"title": e.get("summary", "(no title)"), "when": when,
                    "where": e.get("location", ""), "link": e.get("htmlLink", "")})
    return out


def gcal_add(summary, start_iso, end_iso, tz="Asia/Kolkata"):
    body = {"summary": summary,
            "start": {"dateTime": start_iso, "timeZone": tz},
            "end": {"dateTime": end_iso, "timeZone": tz}}
    return google_post("https://www.googleapis.com/calendar/v3/calendars/primary/events", body)


def _cal_pretty(events):
    if events is None:
        return "\U0001F4C5 I couldn't reach your Google Calendar (is it connected? /google)."
    if not events:
        return "\U0001F4C5 Nothing on your calendar for the next couple of days - you're clear."
    lines = ["\U0001F4C5 Your upcoming schedule:", ""]
    for e in events[:15]:
        w = e["when"].replace("T", " ")[:16]
        lines.append("- " + w + "  " + e["title"] + (" @ " + e["where"] if e["where"] else ""))
    return "\n".join(lines)


def gmail_unread(n=8):
    """Recent unread inbox messages (from, subject, snippet)."""
    j = google_get("https://gmail.googleapis.com/gmail/v1/users/me/messages",
                   {"q": "is:unread in:inbox", "maxResults": n})
    if j is None:
        return None
    out = []
    for m in j.get("messages", []):
        d = google_get("https://gmail.googleapis.com/gmail/v1/users/me/messages/" + m["id"],
                       {"format": "metadata", "metadataHeaders": ["From", "Subject"]})
        if not d:
            continue
        hdr = {h["name"]: h["value"] for h in d.get("payload", {}).get("headers", [])}
        out.append({"from": hdr.get("From", ""), "subject": hdr.get("Subject", "(no subject)"),
                    "snippet": (d.get("snippet", "") or "")[:160]})
    return out


def inbox_triage(chat_id):
    """Read the unread inbox and give a smart 'what matters' summary."""
    tg("sendMessage", chat_id=chat_id, text="\U0001F4E7 Reading your inbox...")
    msgs = gmail_unread(10)
    if msgs is None:
        send_text(chat_id, "I couldn't reach Gmail - connect it first with /google.")
        return
    if not msgs:
        send_text(chat_id, "\U0001F4EC Inbox zero - no unread mail. Nice.")
        return
    raw = "\n".join(f"{i+1}. From {m['from']} | {m['subject']} | {m['snippet']}" for i, m in enumerate(msgs))
    summ = ask_ai(chat_id, "You are Nemo triaging your Boss's unread email. From the list, tell him briefly what "
                  "actually matters, group by importance, flag anything urgent/bills/deadlines, and note what he can "
                  "ignore. Be concise, natural, no markdown.\n\n" + raw, remember=False, timeout=150)
    send_text(chat_id, "\U0001F4E7 Inbox (" + str(len(msgs)) + " unread):\n\n" + summ)


def gdrive_search(q, n=10):
    j = google_get("https://www.googleapis.com/drive/v3/files",
                   {"q": "name contains '" + q.replace("'", "") + "' and trashed=false",
                    "pageSize": n, "fields": "files(id,name,mimeType,modifiedTime,webViewLink)",
                    "orderBy": "modifiedTime desc"})
    if j is None:
        return None
    return j.get("files", [])


def gdrive_upload(path, name=None):
    """v9.2 - upload a file to the Boss's Google Drive (multipart). Returns a shareable view link, or None."""
    tok = google_token()
    if not tok or not os.path.exists(path):
        return None
    try:
        name = name or os.path.basename(path)
        with open(path, "rb") as f:
            data = f.read()
        boundary = "nemo9x2xboundary7k"
        body = (("--" + boundary + "\r\n").encode() +
                b"Content-Type: application/json; charset=UTF-8\r\n\r\n" +
                json.dumps({"name": name}).encode() + b"\r\n" +
                ("--" + boundary + "\r\n").encode() +
                b"Content-Type: application/octet-stream\r\n\r\n" + data + b"\r\n" +
                ("--" + boundary + "--").encode())
        r = requests.post("https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart",
                          headers={"Authorization": "Bearer " + tok,
                                   "Content-Type": "multipart/related; boundary=" + boundary},
                          data=body, timeout=180)
        if r.status_code in (200, 201):
            fid = (r.json() or {}).get("id")
            return ("https://drive.google.com/file/d/" + fid + "/view") if fid else "uploaded"
    except Exception:
        traceback.print_exc()
    return None


def nl_addevent(chat_id, text):
    """v8.5 - add a Google Calendar event from plain language ('lunch with Sam tomorrow 1pm for 90 min')."""
    if not google_ready():
        send_text(chat_id, "Connect Google first with /google.")
        return
    if not text:
        send_text(chat_id, "Tell me the event, e.g. 'meeting with Ravi tomorrow 4pm for 1 hour'.")
        return
    today = time.strftime("%Y-%m-%d", time.gmtime(time.time() + IST_OFFSET))
    noww = time.strftime("%H:%M", time.gmtime(time.time() + IST_OFFSET))
    raw = _nl_call([
        {"role": "system", "content": "Extract ONE calendar event as JSON only. Today is " + today + ", now " +
         noww + " IST. Return {\"title\":..,\"date\":\"YYYY-MM-DD\",\"start\":\"HH:MM\" (24h),\"minutes\":<int, "
         "default 60>}. Resolve tomorrow/tonight/next monday relative to today. JSON only."},
        {"role": "user", "content": text}])
    try:
        import calendar as _cal
        j = json.loads(re.search(r"\{.*\}", raw, re.S).group(0))
        y, mo, dd = [int(x) for x in j["date"].split("-")]
        hh, mm = [int(x) for x in j["start"].split(":")]
        mins = int(j.get("minutes", 60) or 60)
        base = _cal.timegm((y, mo, dd, 0, 0, 0)) + hh * 3600 + mm * 60
        start_iso = time.strftime("%Y-%m-%dT%H:%M:00", time.gmtime(base))
        end_iso = time.strftime("%Y-%m-%dT%H:%M:00", time.gmtime(base + mins * 60))
        res = gcal_add(j["title"], start_iso, end_iso)
        if res and res.get("id"):
            send_text(chat_id, f"\U0001F4C5 Added: {j['title']} on {j['date']} at {j['start']} "
                      f"({mins} min). It's in your Google Calendar.")
        else:
            send_text(chat_id, "Couldn't add it to Calendar: " + str(res)[:150])
    except Exception:
        send_text(chat_id, "I couldn't turn that into an event. Try 'lunch with Sam tomorrow 1pm'.")


def atr_levels(entry, atr, bullish):
    """v7.1 - target/stop from real volatility (ATR): 1.5x ATR stop, 3x ATR target (1:2 reward)."""
    if not atr or atr <= 0:
        atr = entry * 0.01
    if bullish:
        return round(entry - 1.5 * atr, 2), round(entry + 3 * atr, 2)
    return round(entry + 1.5 * atr, 2), round(entry - 3 * atr, 2)


def strategy_insights(days=45):
    """v8.6 - LEARN FROM THE SCORECARD: mine the agent's own past trades (AUTOLOG) for what actually
    works - win-rate by instrument, by direction, by brain - so the live brain stops repeating losers."""
    cutoff = time.time() - days * 86400
    ts = [t for t in AUTOLOG if t.get("ts", t.get("t", 0)) >= cutoff or t.get("t", 0) >= cutoff]
    if len(ts) < 6:
        return ""
    from collections import defaultdict
    by = defaultdict(lambda: [0, 0.0])  # key -> [n, pnl]
    for t in ts:
        k = _instrument_kind(t.get("sym", ""))
        by[k][0] += 1
        by[k][1] += t.get("pnl", 0)
        d = "CE/long" if str(t.get("sym", "")).endswith("CE") or t.get("side") == "long" else \
            "PE/short" if str(t.get("sym", "")).endswith("PE") or t.get("side") == "short" else "equity"
        by[d][0] += 1
        by[d][1] += t.get("pnl", 0)
    wins = sum(1 for t in ts if t.get("pnl", 0) > 0)
    parts = [f"overall {wins}/{len(ts)} wins ({wins*100//len(ts)}%)"]
    for k, (n, pnl) in sorted(by.items(), key=lambda x: -x[1][1]):
        parts.append(f"{k}: {n} trades, net Rs.{pnl:+,.0f}")
    return ("YOUR OWN TRACK RECORD (last " + str(days) + "d - learn from it, favour what profits, avoid what bleeds): "
            + "; ".join(parts))


def ai_decide(now=None):
    """v7.7 - THE LIVE STRATEGY BRAIN: the AI decides the single best intraday trade now (or NONE),
    grounded in REAL computed indicators for NIFTY, BANKNIFTY & SENSEX + live news + the equity watchlist,
    plus the agent's OWN past-performance record. Output is bounded by all hard rails downstream."""
    reads = {}
    for idx in ("NIFTY", "BANKNIFTY", "SENSEX"):
        r = godmode_analyze(idx)
        if r:
            reads[idx] = r
    if not reads:
        return None
    news = get_news_brief("India NIFTY BANKNIFTY stock market news today")
    fii = get_fii_dii()
    if fii:
        news = (news + " || FII/DII flows: " + fii)[:1400]
    watch = AUTO.get("watch") or []
    insight = strategy_insights()
    lines = []
    for idx, a in reads.items():
        lv = a["levels"]
        lines.append(f"{idx}: {a['signal']} (score {a['score']} of +-6), price {a['price']:.0f}, RSI {a['rsi']:.0f}, "
                     f"S {lv['s1']:.0f}/{lv['s2']:.0f}, R {lv['r1']:.0f}/{lv['r2']:.0f}, ATR {a['atr']:.0f}")
    prompt = ("You are a disciplined intraday trading strategist for Gautam. Decide the SINGLE best trade to take "
              "RIGHT NOW, or NONE if there is no clear edge (most of the time the honest answer is NONE - be very "
              "selective, capital preservation first). BUY ONLY (never sell/write). You may buy an at-the-money "
              "option on NIFTY, BANKNIFTY or SENSEX (CE if bullish, PE if bearish) OR buy ONE stock strictly from "
              "the watchlist.\n\nComputed reads:\n" + "\n".join(lines) +
              (("\n\n" + insight) if insight else "") +
              f"\n\nLive news: {news}\nWatchlist stocks (Fyers symbols): {', '.join(watch) or 'none'}\n\n"
              "Reply with ONE line of JSON and nothing else:\n"
              '{"action":"BUY_CE|BUY_PE|BUY_EQ|NONE","index":"NIFTY|BANKNIFTY|SENSEX (only if option)",'
              '"symbol":"<exact watchlist Fyers symbol if BUY_EQ else empty>",'
              '"confidence":1-10,"reason":"one short line"}')
    raw = ask_ai(0, prompt, remember=False, deep=True, timeout=180)
    try:
        j0, j1 = raw.find("{"), raw.rfind("}")
        d = json.loads(raw[j0:j1 + 1])
        d["action"] = str(d.get("action", "NONE")).upper()
        d["confidence"] = int(d.get("confidence", 0))
        return d
    except Exception:
        return None


def _ist_mins(now=None):
    ist = time.gmtime((now or time.time()) + IST_OFFSET)
    return ist.tm_wday, ist.tm_hour * 60 + ist.tm_min


def can_enter(now=None):
    return _n81_session(now)['entry_open'] and not _n81_paused()


def must_square_off(now=None):
    wd, m = _ist_mins(now)
    return wd < 5 and m >= 15 * 60 + 10


def auto_report(msg):
    if OWNER.get("id"):
        send_text(OWNER["id"], msg)
        ntfy_send(msg[:400], title="NEMO AUTO-TRADE")
        threading.Thread(target=wa_send, args=("\U0001F916 " + msg[:1200],), daemon=True).start()


def _instrument_kind(sym):
    s = (sym or "").upper()
    if s.endswith("CE") or s.endswith("PE"):
        for idx in ("BANKNIFTY", "FINNIFTY", "MIDCPNIFTY", "SENSEX", "NIFTY"):
            if idx in s:
                return idx + " option"
        return "option"
    return "equity"


def trading_day_report(chat_id, on_demand=False, day=None):
    """v7.7 - the DAY-END REPORT CARD the stock-market agent hands to Nemotron: every virtual/live
    trade taken today, win rate, P&L, per-instrument breakdown, best & worst, and which brain drove it."""
    day = day or fyers_today()
    todays = [t for t in AUTOLOG
              if time.strftime("%Y-%m-%d", time.gmtime(t.get("t", 0) + IST_OFFSET)) == day]
    if not todays:
        if on_demand:
            send_text(chat_id, "\U0001F4CB No auto-trades today " + ("(agent is " + AUTO["mode"].upper() + ")." if AUTO["mode"] != "off"
                      else "- the trading agent is OFF. Turn it on with /autotrade shadow (virtual) or /autotrade live."))
        return
    n = len(todays)
    wins = [t for t in todays if t["pnl"] > 0]
    losses = [t for t in todays if t["pnl"] <= 0]
    gross = round(sum(t["pnl"] for t in todays), 1)
    winrate = round(len(wins) / n * 100)
    avgwin = round(sum(t["pnl"] for t in wins) / len(wins)) if wins else 0
    avgloss = round(sum(t["pnl"] for t in losses) / len(losses)) if losses else 0
    best = max(todays, key=lambda t: t["pnl"])
    worst = min(todays, key=lambda t: t["pnl"])
    mode = todays[-1].get("mode", AUTO["mode"])
    # per-instrument breakdown
    kinds = {}
    for t in todays:
        k = _instrument_kind(t["sym"])
        b = kinds.setdefault(k, {"n": 0, "pnl": 0.0})
        b["n"] += 1
        b["pnl"] += t["pnl"]
    nl = chr(10)
    L = [f"\U0001F4CA STOCK-MARKET AGENT - DAY-END REPORT  ({day})",
         f"Mode: {mode.upper()}" + ("   (VIRTUAL - no real money)" if mode == "shadow" else ""),
         "",
         f"Trades: {n}   Wins: {len(wins)}   Losses: {len(losses)}   Win-rate: {winrate}%",
         f"Net P&L: Rs.{gross:+,.0f}",
         f"Avg win: Rs.{avgwin:+,.0f}   Avg loss: Rs.{avgloss:+,.0f}",
         "",
         "By instrument:"]
    for k, b in sorted(kinds.items(), key=lambda x: -x[1]["pnl"]):
        L.append(f"  {k:16} {b['n']} trade(s)   Rs.{round(b['pnl']):+,.0f}")
    L.append("")
    L.append(f"Best:  {best['sym']}  Rs.{best['pnl']:+,.0f}  ({best.get('exit_reason','')})")
    L.append(f"Worst: {worst['sym']}  Rs.{worst['pnl']:+,.0f}  ({worst.get('exit_reason','')})")
    L.append("")
    L.append("Trades today:")
    for t in todays[-12:]:
        L.append(f"  {_instrument_kind(t['sym'])[:10]:10} {t['entry']:>8.1f}->{t['exit']:>8.1f}  "
                 f"Rs.{t['pnl']:+,.0f}  {t.get('exit_reason','')[:9]}")
    brains = {t.get("brain") for t in todays}
    L.append("")
    L.append("Brain: " + ", ".join(sorted(b for b in brains if b)))
    L.append("Educational only. " + ("Virtual results - not real trades." if mode == "shadow" else "Live trades."))
    body = nl.join(L)
    send_mono(chat_id, body)
    ntfy_send(f"Day-end: {n} trades, {winrate}% win, P&L Rs.{gross:+,.0f}", title="NEMO TRADING REPORT")


def auto_trade_tick(now=None):
    """v7.0 - the autonomous NIFTY-options agent. BUY-ONLY, 1 lot, strong signal only, hard daily rails."""
    if AUTO["mode"] == "off" or BROKER.get("halt") or not BROKER.get("token"):
        return
    _pos81=AUTO.get('pos')
    if AUTO.get('mode')=='shadow' and _pos81:
        try:
            _opened81=_n81_session(_pos81['at'],_n81_exchange(_pos81['symbol']))
            if not _opened81['market_open']:
                AUTO['_n81_reason']='Existing shadow position began in a closed/unverified session; retained for review, no simulated exit booked.'
                return
        except Exception:
            AUTO['_n81_reason']='Shadow entry timestamp missing/invalid; position retained for review.'
            return
    _session81=_n81_session(now)
    if not _session81['market_open'] and not (_session81['state']=='CALENDAR_UNVERIFIED' and AUTO.get('mode')=='live' and AUTO.get('pos')):
        AUTO['_n81_reason']='Market closed/unverified: '+_session81['state']+' '+str(_session81.get('holiday') or '')
        return
    today = fyers_today()
    if AUTO["day"] != today:
        AUTO["day"], AUTO["trades"], AUTO["pnl"], AUTO["halted"] = today, 0, 0.0, ""
    live = AUTO["mode"] == "live"

    # ---- manage an open position: exit on stop-loss, target, or square-off time ----
    if AUTO["pos"]:
        p = AUTO["pos"]
        if not live:
            try:
                _q81=_n75_quote(p['symbol'])
                if not _n81_session(None,_n81_exchange(p['symbol']))['market_open'] or not _n81_check_quote(_q81,p['symbol'],time.time()):return
                ltp=_q81['bid']
            except Exception:return
        else:
            ltp = live_ltp(p["symbol"])
        if ltp is None:
            return
        reason = ("stop-loss" if ltp <= p["sl"] else "target" if ltp >= p["target"]
                  else "square-off" if must_square_off(now) else None)
        if reason:
            # For a bracket position the exchange already holds the SL & target, so we must NOT
            # fire our own SELL (that would double-exit / flip the position). We only exit here
            # for plain positions; for brackets we just reconcile our own bookkeeping.
            if live and not p.get("bracket"):
                ok_exit, msg_exit = fyers_place(p["symbol"], "SELL", p["qty"])
                if not ok_exit:
                    # v13.2: a FAILED live exit must NOT be booked as closed - the real position is still open on
                    # the exchange. Keep managing it, alert once, and retry next tick (no phantom exit).
                    if AUTO.get("_exit_warned") != p.get("symbol"):
                        AUTO["_exit_warned"] = p.get("symbol")
                        auto_report("❗ AUTO-TRADE EXIT ORDER FAILED for " + str(p["symbol"]) + " (" + str(reason)
                                    + "): " + str(msg_exit)[:150] + "\nPosition is STILL OPEN - I'll retry each tick. "
                                    "To square off now: /order SELL " + str(p["symbol"]) + " " + str(p["qty"]))
                    return
            AUTO["_exit_warned"] = ""
            pnl = round((ltp - p["entry"]) * p["qty"], 1)
            AUTO["pnl"] = round(AUTO["pnl"] + pnl, 1)
            with LOCK:
                AUTOLOG.append({"sym": p["symbol"], "entry": p["entry"], "exit": ltp, "qty": p["qty"],
                                "pnl": pnl, "why": p.get("reason", ""), "exit_reason": reason,
                                "brain": AUTO.get("brain"), "mode": AUTO["mode"], "t": time.time(),
                                "bracket": p.get("bracket", False)})
                del AUTOLOG[:-500]
            AUTO["pos"] = None
            save_data()
            how = ("  [exit handled on-exchange by the bracket]" if (live and p.get("bracket"))
                   else "" if live else "  [SHADOW - no real money]")
            auto_report(f"\U0001F514 AUTO-TRADE EXIT ({reason}) {p['symbol']}\nExit ~{ltp} vs entry {p['entry']} | "
                        f"P&L Rs.{pnl:+,.0f}\nToday: {AUTO['trades']} trade(s), P&L Rs.{AUTO['pnl']:+,.0f}" + how)
        return

    # ---- consider a new entry ----
    if mm_locked():   # v13.2: master lockdown stops NEW autonomous entries (open positions above still auto-manage/exit)
        return
    if not can_enter(now):
        return
    if AUTO["pnl"] <= -abs(AUTO["dayloss"]):
        if AUTO["halted"] != today:
            AUTO["halted"] = today
            auto_report(f"\U0001F6D1 AUTO-TRADE halted for today - daily loss limit hit (P&L Rs.{AUTO['pnl']:+,.0f}, "
                        f"limit Rs.{AUTO['dayloss']:,}). Resumes tomorrow, or /autotrade off.")
        return
    if AUTO["trades"] >= AUTO["maxtrades"]:
        return

    # decide the trade: AI brain (LLM designs it) or GODMODE (fixed rules)
    symbol = entry = qty = sl = target = None
    reason = ""
    if AUTO.get("brain") == "ai":
        d = ai_decide(now)
        if not d or d["action"] == "NONE" or d["confidence"] < 6:
            return
        reason = "AI: " + str(d.get("reason", ""))[:120] + f" (conf {d['confidence']}/10)"
        if d["action"] in ("BUY_CE", "BUY_PE"):
            idx = str(d.get("index", "NIFTY")).upper().replace(" ", "") or "NIFTY"
            if idx not in ("NIFTY", "BANKNIFTY", "FINNIFTY", "MIDCPNIFTY", "SENSEX"):
                idx = "NIFTY"
            opt = index_atm_option(idx, d["action"] == "BUY_CE")
            if not opt:
                _option_chain_failure_notice(idx, "AI")
                return
            symbol, entry, qty = opt
            sl, target = round(entry * 0.70, 1), round(entry * 1.50, 1)   # premium %-based
            reason = "AI " + idx + ": " + str(d.get("reason", ""))[:110] + f" (conf {d['confidence']}/10)"
        elif d["action"] == "BUY_EQ":
            sym = str(d.get("symbol", "")).strip()
            if sym not in (AUTO.get("watch") or []):
                auto_report("\U0001F6D1 AI picked " + (sym or "a stock") + " which is NOT on your watchlist - "
                            "skipped for safety. Add it with /watchlist add " + sym + " if you trust it.")
                return
            entry = fyers_ltp(sym)
            if not entry:
                return
            symbol = sym
            qty = max(1, int(AUTO.get("dayloss", 3000) / max(entry, 1) / 3))   # size ~ risk budget
            hh = godmode_analyze(sym.split(":")[-1].replace("-EQ", ""))
            atrv = hh["atr"] if hh else entry * 0.02
            sl, target = atr_levels(entry, atrv, True)
    else:
        # GODMODE across the index-options universe: scan NIFTY, BANKNIFTY, SENSEX; take the strongest.
        best = None
        for idx in ("NIFTY", "BANKNIFTY", "SENSEX"):
            aa = godmode_analyze(idx)
            if aa and (best is None or abs(aa["score"]) > abs(best[1]["score"])):
                best = (idx, aa)
        if not best or abs(best[1]["score"]) < 4:   # STRONG signals only
            return
        idx, a = best
        opt = index_atm_option(idx, a["score"] > 0)
        if not opt:
            _option_chain_failure_notice(idx, "GODMODE", a.get("signal", ""))
            return
        symbol, entry, qty = opt
        sl, target = round(entry * 0.70, 1), round(entry * 1.50, 1)
        reason = idx + " " + a["signal"] + f" (score {a['score']:+d})"

    if not symbol or not entry or entry <= 0:
        return
    # AI may take minutes: re-check the real entry window and selected contract now.
    _entry81,_reason81=_n81_entry_quote(symbol,entry,sl,target,qty)
    if _entry81 is None:
        AUTO['_n81_reason']=_reason81
        return
    entry=_entry81
    AUTO['_n81_reason']='Entry gates passed; broker execution/fill is separate.'
    placed_bracket = False
    if live:
        if AUTO.get("bracket"):
            ok2, msg2 = fyers_place_bracket(symbol, "BUY", qty, abs(entry - sl), abs(target - entry))
            placed_bracket = ok2
            if not ok2:
                # bracket rejected (e.g. BO disabled for this symbol) - fall back to a plain buy
                ok2, msg2 = fyers_place(symbol, "BUY", qty)
        else:
            ok2, msg2 = fyers_place(symbol, "BUY", qty)
        if not ok2:
            auto_report("❌ Auto-trade order failed: " + msg2)
            return
    AUTO["pos"] = {"symbol": symbol, "entry": entry, "sl": sl, "target": target, "qty": qty,
                   "at": time.time(), "bracket": placed_bracket, "reason": reason}
    AUTO["trades"] += 1
    save_data()
    maxloss = abs(entry - sl) * qty
    prot = ("\n\U0001F6E1 Protected on-exchange: stop-loss & target are live BRACKET legs - safe even if I go offline."
            if placed_bracket else "")
    auto_report(f"\U0001F916 AUTO-TRADE ENTRY {'[LIVE]' if live else '[SHADOW]'}\n"
                f"BUY {symbol} x{qty} @ ~{entry}\nStop {sl} | Target {target}\n"
                f"Reason: {reason}. Max loss this trade ~Rs.{maxloss:,.0f}." + prot
                + ("" if live else "\n(SHADOW - not placed, watching what it would do)"))


def lot_size(fsym):
    """Current SEBI lot size for an index F&O symbol, or None for equities/unknown."""
    s = re.sub(r"[^A-Z0-9]", "", (fsym or "").upper())
    for k, sz in LOT_ORDER:
        if k in s:
            return sz
    return None


def fyers_place(symbol, side, qty):
    """Place a live order. side: 'BUY'/'SELL'. qty already in units. Returns (ok, message)."""
    if not fyers_ready():
        if not fyers_login():
            return False, "Broker not logged in: " + (BROKER.get("last_err") or "unknown") + \
                   "\nTip: paste today's token with /brokertoken <token>"
    payload = {"symbol": symbol, "qty": int(qty), "type": 2, "side": 1 if side.upper() == "BUY" else -1,
               "productType": "INTRADAY", "limitPrice": 0, "stopPrice": 0, "validity": "DAY",
               "disclosedQty": 0, "offlineOrder": False}
    try:
        r = requests.post("https://api-t1.fyers.in/api/v3/orders/sync",
                          headers={"Authorization": BROKER["app_id"] + ":" + BROKER["token"],
                                   "Content-Type": "application/json"},
                          json=payload, timeout=30)
        j = r.json()
        if j.get("s") == "ok" or j.get("id"):
            act_log("order", f"LIVE {side} {qty} {symbol} - id {j.get('id', '?')}")
            return True, "Order id " + str(j.get("id", "?"))
        return False, str(j.get("message") or j)[:200]
    except Exception as e:
        return False, type(e).__name__ + ": " + str(e)[:150]


def _tick_round(x):
    """Round to the NSE/BSE tick size (0.05)."""
    try:
        return round(round(float(x) / 0.05) * 0.05, 2)
    except Exception:
        return x


def _order_send(payload):
    try:
        r = requests.post("https://api-t1.fyers.in/api/v3/orders/sync",
                          headers={"Authorization": BROKER["app_id"] + ":" + BROKER["token"],
                                   "Content-Type": "application/json"}, json=payload, timeout=30)
        j = r.json()
        if j.get("s") == "ok" or j.get("id"):
            return True, j
        return False, str(j.get("message") or j)[:200]
    except Exception as e:
        return False, type(e).__name__ + ": " + str(e)[:150]


def fyers_place_bracket(symbol, side, qty, sl_points, tp_points, limit_price=0):
    """v7.6 - BRACKET ORDER (productType BO): entry + an exchange-side stop-loss AND target in one order.
    The SL/target sit ON THE EXCHANGE, so the position stays protected even if the bot or server dies.
    sl_points / tp_points = distance in rupees from entry. Returns (ok, message)."""
    if not fyers_ready() and not fyers_login():
        return False, "Broker not logged in: " + (BROKER.get("last_err") or "run /brokerurl once")
    sl = _tick_round(max(0.05, abs(sl_points)))
    tp = _tick_round(max(0.05, abs(tp_points)))
    payload = {"symbol": symbol, "qty": int(qty), "type": 1 if limit_price else 2,
               "side": 1 if side.upper() == "BUY" else -1, "productType": "BO",
               "limitPrice": float(limit_price) if limit_price else 0, "stopPrice": 0,
               "stopLoss": sl, "takeProfit": tp, "validity": "DAY",
               "disclosedQty": 0, "offlineOrder": False}
    ok, j = _order_send(payload)
    if ok:
        return True, "Bracket order id " + str(j.get("id", "?")) + f" | SL {sl} & target {tp} pts held on-exchange"
    return False, str(j)


def fyers_place_cover(symbol, side, qty, stop_price):
    """v7.6 - COVER ORDER (productType CO): entry + a compulsory exchange-side stop-loss at stop_price.
    stop_price = absolute trigger price. Returns (ok, message)."""
    if not fyers_ready() and not fyers_login():
        return False, "Broker not logged in: " + (BROKER.get("last_err") or "run /brokerurl once")
    sp = _tick_round(stop_price)
    payload = {"symbol": symbol, "qty": int(qty), "type": 2, "side": 1 if side.upper() == "BUY" else -1,
               "productType": "CO", "limitPrice": 0, "stopPrice": sp, "validity": "DAY",
               "disclosedQty": 0, "offlineOrder": False}
    ok, j = _order_send(payload)
    if ok:
        return True, "Cover order id " + str(j.get("id", "?")) + f" | SL @ {sp} held on-exchange"
    return False, str(j)


# ============================ v7.6 LIVE WEBSOCKET FEED ============================
# Real-time ticks + market depth so the autonomous agent reacts the instant price moves.
# 100% opt-in and crash-isolated: if the SDK is missing or the socket dies, everything
# transparently falls back to REST quotes and the bot keeps trading exactly as before.

def livefeed_start(symbols):
    if not (fyers_ready() or fyers_login()):
        LIVEFEED["err"] = "broker not logged in - do /brokerurl first"
        return False
    try:
        from fyers_apiv3.FyersWebsocket import data_ws
    except Exception:
        LIVEFEED["err"] = "fyers-apiv3 not installed. On the server run: pip3 install fyers-apiv3 --break-system-packages"
        return False
    syms = [(s if ":" in s else fyers_resolve(s)) for s in symbols]
    LIVEFEED["syms"] = syms
    tok = BROKER["app_id"] + ":" + BROKER["token"]

    def onmsg(m):
        try:
            if not isinstance(m, dict):
                return
            sy = m.get("symbol") or m.get("s")
            if not sy:
                return
            lp = m.get("ltp", m.get("last_price", m.get("lp")))
            if lp is not None:
                LIVEFEED["ticks"][sy] = {"lp": float(lp), "t": time.time()}
            if m.get("bids") or m.get("ask") or m.get("bid_price") or m.get("depth"):
                LIVEFEED["depth"][sy] = m
        except Exception:
            pass

    def onopen():
        LIVEFEED["connected"] = True
        s = LIVEFEED.get("_sock")
        if not s:
            return
        # Live ticks (LTP) for EVERYTHING - indices, stocks, options. (Order-book depth is fetched
        # on demand via the REST endpoint in fyers_depth(), which is more reliable than the socket.)
        try:
            s.subscribe(symbols=syms, data_type="SymbolUpdate")
        except Exception as e:
            LIVEFEED["err"] = "subscribe: " + str(e)[:150]

    def onclose(m=None):
        LIVEFEED["connected"] = False

    def onerror(m=None):
        t = str(m)
        # An index has no market depth - Fyers returns -300 on that DepthUpdate. It's harmless
        # (ticks still stream), so we don't surface it as an error.
        if "market depth" in t.lower() or "'code': -300" in t or '"code": -300' in t:
            return
        LIVEFEED["err"] = t[:200]

    try:
        sock = data_ws.FyersDataSocket(access_token=tok, log_path="", litemode=True,
                                       write_to_file=False, reconnect=True,
                                       on_connect=onopen, on_close=onclose,
                                       on_error=onerror, on_message=onmsg)
        LIVEFEED["_sock"] = sock
        LIVEFEED["on"] = True
        LIVEFEED["err"] = ""
        threading.Thread(target=sock.connect, daemon=True).start()
        return True
    except Exception as e:
        LIVEFEED["err"] = type(e).__name__ + ": " + str(e)[:150]
        LIVEFEED["on"] = False
        return False


def livefeed_stop():
    LIVEFEED["on"] = False
    LIVEFEED["connected"] = False
    try:
        if LIVEFEED.get("_sock"):
            LIVEFEED["_sock"].close_connection()
    except Exception:
        pass


def live_ltp(symbol):
    """Freshest price: a live socket tick (<6s old) if the feed is running, else a REST quote from Fyers."""
    fs = symbol if ":" in (symbol or "") else fyers_resolve(symbol)
    t = LIVEFEED["ticks"].get(fs)
    if t and t.get("lp") and (time.time() - t["t"] < 6):
        return t["lp"]
    return fyers_ltp(fs)


def _mentions_market(text):
    t = " " + (text or "").lower() + " "
    return any(w in t for w in ("nifty", "banknifty", "bank nifty", "sensex", "finnifty", "midcap", "midcpnifty",
                                " option", "strike", " pcr", "open interest", " oi ", "stock market", "share market",
                                " trade ", " trades ", "trading", "intraday", "expiry", " ce ", " pe ",
                                "f&o", "fno", "call option", "put option", "option chain", "spot price"))


def market_context(text, max_syms=3):
    """v7.9 - GROUND TRUTH for anything market-related: fetch the REAL live index/stock levels (and the
    real option chain if options are mentioned) so Nemo NEVER invents prices, strikes, OI, IV or expiry.
    Returns a text block to feed the model, or '' if the request is not about the market."""
    if not _mentions_market(text):
        return ""
    up = re.sub(r"[^A-Z ]", "", (text or "").upper())
    idxs = [name for name in ("BANKNIFTY", "FINNIFTY", "MIDCPNIFTY", "SENSEX", "NIFTY")
            if name in up.replace(" ", "") or name in up]
    # also catch explicit stock tickers the user typed in CAPS (best-effort)
    if not idxs:
        idxs = ["NIFTY"]
    idxs = list(dict.fromkeys(idxs))[:max_syms]
    lines, got = [], False
    for idx in idxs:
        try:
            lp = live_ltp(idx)
        except Exception:
            lp = None
        if lp:
            got = True
            lines.append(f"{idx} spot is LIVE {lp:,.2f} (as of now, {time.strftime('%d %b %Y %H:%M', time.gmtime(time.time()+IST_OFFSET))} IST)")
    wants_opts = any(w in (text or "").lower() for w in ("option", "call", "put", "strike", "pcr", "chain", " ce", " pe", "expiry", "f&o", "fno"))
    if wants_opts:
        for idx in idxs[:2]:
            try:
                oc = fyers_option_chain(idx, strikes=6)
            except Exception:
                oc = "X"
            if not oc.startswith("X"):
                got = True
                lines.append("\nREAL LIVE OPTION CHAIN for " + idx + " (use these exact strikes, LTPs, OI, PCR - do NOT invent any):\n" + oc)
    if not got:
        return ("Live market data is NOT available right now (broker logged out or market closed). "
                "You MUST NOT invent any index level, option strike, premium, OI, IV, PCR or expiry date. "
                "Instead tell the Boss the live data isn't available and offer to pull it when the market/broker is live.")
    return ("\n".join(lines) +
            "\n\nRULE: Use ONLY these real live numbers. Do NOT state any NIFTY/BANKNIFTY/SENSEX level, option "
            "strike, premium, OI, IV, PCR or expiry that is not shown above. Never use figures from your memory.")


def market_header(text):
    """v7.9 - a REAL, code-generated provenance line stamped at the top of any market email/report, so the
    reader can see at a glance the numbers are live and current - not the model's guess."""
    if not _mentions_market(text):
        return ""
    up = re.sub(r"[^A-Z ]", "", (text or "").upper()).replace(" ", "")
    idxs = [n for n in ("BANKNIFTY", "FINNIFTY", "SENSEX", "NIFTY") if n in up] or ["NIFTY"]
    parts = []
    for idx in list(dict.fromkeys(idxs))[:3]:
        try:
            lp = live_ltp(idx)
        except Exception:
            lp = None
        if lp:
            parts.append(f"{idx} {lp:,.2f}")
    if not parts:
        return ""
    ts = time.strftime("%d %b %Y %H:%M", time.gmtime(time.time() + IST_OFFSET))
    return "[LIVE market data as of " + ts + " IST - " + ", ".join(parts) + "  |  source: Fyers]"


