def analyze_symbol(chat_id, sym):
    nl = chr(10)
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F4C8 Analyzing " + sym.upper() + " with real market data...")
    mid = ph.get("result", {}).get("message_id")
    h = get_history(sym)
    if not h:
        deliver(chat_id, mid, "Could not fetch data for that symbol. Try RELIANCE, TCS, NIFTY, BTC...")
        return
    c = h["closes"]
    last = c[-1]
    sma20 = sum(c[-20:]) / 20
    sma50 = sum(c[-50:]) / 50 if len(c) >= 50 else None
    rsi = rsi14(c)
    hi3, lo3 = max(h["highs"]), min(h["lows"])
    dh, dl = h["highs"][-1], h["lows"][-1]
    piv = (dh + dl + last) / 3
    r1, s1 = 2 * piv - dl, 2 * piv - dh
    r2, s2 = piv + (dh - dl), piv - (dh - dl)
    chg5 = (c[-1] - c[-6]) / c[-6] * 100 if len(c) > 6 else 0
    facts = (f"Symbol: {h['name']}  Price: {last:,.2f} {h['cur']}" + nl +
             f"5-day change: {chg5:+.2f} percent" + nl +
             f"20-day average: {sma20:,.2f} (price is {'above' if last > sma20 else 'below'})" + nl +
             (f"50-day average: {sma50:,.2f} (price is {'above' if last > sma50 else 'below'})" + nl if sma50 else "") +
             (f"RSI(14): {rsi:.1f}" + nl if rsi else "") +
             f"3-month high/low: {hi3:,.2f} / {lo3:,.2f}" + nl +
             f"Next session pivots - Support: {s1:,.2f} and {s2:,.2f} | Resistance: {r1:,.2f} and {r2:,.2f}")
    out = ask_ai(chat_id, "You are given REAL computed market data. Explain in simple terms for an Indian retail "
                          "trader what it suggests: trend, momentum, key levels, and what would make it bullish or "
                          "bearish. Do NOT give buy or sell orders. End with: This is educational analysis, not "
                          "investment advice." + nl + nl + facts, remember=False)
    deliver(chat_id, mid, facts + nl + nl + out, buttons=True)


