def _yt_id(url):
    m = re.search(r"(?:v=|youtu\.be/|shorts/|embed/|live/)([A-Za-z0-9_-]{11})", url or "")
    return m.group(1) if m else None


def _vtt_text(vtt):
    """Turn a WebVTT subtitle string into clean, de-duplicated plain text."""
    out = []
    for line in (vtt or "").splitlines():
        line = line.strip()
        if not line or "-->" in line or line.isdigit() or line.startswith(("WEBVTT", "Kind:", "Language:", "NOTE")):
            continue
        line = re.sub(r"<[^>]+>", "", line)
        if line and (not out or out[-1] != line):
            out.append(line)
    return " ".join(out)


def _yt_transcript(vid, url):
    """Get a video's transcript, robust to YouTube's server blocks: 1) youtube-transcript-api, 2) yt-dlp auto-subs
    (uses imported cookies if present), 3) download the audio + Whisper. Returns the text, or None."""
    try:                                    # 1) transcript API (fastest when it works)
        mod = _imp("youtube_transcript_api", notify=False)
        if not mod:
            auto_install("youtube_transcript_api", notify=False)
            mod = _imp("youtube_transcript_api", notify=False)
        if mod:
            YT = mod.YouTubeTranscriptApi
            for langs in (["en"], ["hi"], ["en", "hi"], None):
                try:
                    parts = YT.get_transcript(vid, languages=langs) if langs else YT.get_transcript(vid)
                    if parts:
                        return " ".join(p["text"] for p in parts)
                except Exception:
                    continue
    except Exception:
        pass
    try:                                    # 2) yt-dlp subtitles (uses cookies -> gets past the bot-check)
        if not _imp("yt_dlp", notify=False):
            auto_install("yt_dlp", notify=False)
        import glob
        os.makedirs("/tmp/nemo_yt", exist_ok=True)
        for f in glob.glob("/tmp/nemo_yt/sub*"):
            try:
                os.remove(f)
            except Exception:
                pass
        cmd = ["yt-dlp", "--skip-download", "--write-auto-subs", "--write-subs", "--sub-langs", "en.*,hi.*",
               "--sub-format", "vtt", "-o", "/tmp/nemo_yt/sub", url]
        if os.path.exists("/root/nemo_cookies.txt"):
            cmd = cmd[:1] + ["--cookies", "/root/nemo_cookies.txt"] + cmd[1:]
        subprocess.run(cmd, capture_output=True, timeout=150)
        blob = ""
        for f in glob.glob("/tmp/nemo_yt/sub*.vtt"):
            blob += _vtt_text(open(f, errors="ignore").read()) + " "
        if blob.strip():
            return blob.strip()
    except Exception:
        pass
    try:                                    # 3) last resort: pull the audio and transcribe with Whisper
        if GROQ_KEY:
            ap = "/tmp/nemo_yt_audio.m4a"
            cmd = ["yt-dlp", "-f", "bestaudio", "-x", "--audio-format", "m4a", "-o", ap, url]
            if os.path.exists("/root/nemo_cookies.txt"):
                cmd = cmd[:1] + ["--cookies", "/root/nemo_cookies.txt"] + cmd[1:]
            subprocess.run(cmd, capture_output=True, timeout=300)
            if os.path.exists(ap):
                return groq_transcribe(ap)
    except Exception:
        pass
    return None


def youtube_summary(chat_id, url):
    nl = chr(10)
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F3AC Watching the video and understanding it...")
    mid = ph.get("result", {}).get("message_id")
    vid = _yt_id(url)
    if not vid:
        deliver(chat_id, mid, "That doesn't look like a YouTube link - send a full youtube.com or youtu.be URL.")
        return
    transcript = _yt_transcript(vid, url)
    if not transcript:
        deliver(chat_id, mid, "I couldn't get this video's words (captions may be off, or YouTube is blocking the "
                "server). If it keeps failing, import your cookies with /browsercookies and I'll get through.")
        return
    prompt = ("Explain this YouTube video simply, like you're telling a friend who has no background in it. Give:" + nl +
              "1) TL;DR - one line." + nl +
              "2) Main points - 5 to 8 short bullets." + nl +
              "3) 'In simple words' - a plain, easy explanation of the core idea." + nl +
              "4) Key takeaways - what's actually useful to remember." + nl +
              "Keep it clear and concise, no jargon." + nl + nl + "TRANSCRIPT:" + nl + transcript[:16000])
    out = (claude_ask(chat_id, prompt, remember=False, timeout=180) if CLAUDE_KEY else None) or \
        ask_ai(chat_id, prompt, remember=False, deep=True, timeout=180)
    deliver(chat_id, mid, "\U0001F3AC Video summary:" + nl + nl + (out or "(couldn't summarise)"), buttons=True)


def yt_download(chat_id, url, audio=False):
    """Download a YouTube video (or audio) with yt-dlp - uses imported cookies to get past the bot-check, and sends
    it over Telegram if it fits the 50MB limit, else saves it on the server (and to Drive if linked)."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Only the Boss can download videos.")
        return
    vid = _yt_id(url)
    if not vid:
        send_text(chat_id, "Send a valid YouTube link.")
        return
    if not _imp("yt_dlp", notify=False):
        send_text(chat_id, "\U0001F527 Installing the downloader (first time)...")
        auto_install("yt_dlp", notify=False)
    os.makedirs("/root/nemo_code", exist_ok=True)
    tmpl = "/root/nemo_code/yt_" + vid + ".%(ext)s"
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F4E5 Downloading the " + ("audio" if audio else "video") + "...")
    mid = ph.get("result", {}).get("message_id")
    if audio:
        cmd = ["yt-dlp", "-f", "bestaudio", "-x", "--audio-format", "mp3", "-o", tmpl, url]
    else:
        cmd = ["yt-dlp", "-f", "best[ext=mp4][filesize<48M]/best[height<=480][ext=mp4]/best[ext=mp4]/best",
               "-o", tmpl, url]
    if os.path.exists("/root/nemo_cookies.txt"):
        cmd = cmd[:1] + ["--cookies", "/root/nemo_cookies.txt"] + cmd[1:]
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
    except subprocess.TimeoutExpired:
        deliver(chat_id, mid, "That took too long or is too large to pull here.")
        return
    import glob
    files = [f for f in glob.glob("/root/nemo_code/yt_" + vid + ".*") if not f.endswith((".part", ".ytdl"))]
    files.sort(key=lambda f: os.path.getsize(f), reverse=True)
    if not files:
        err = (r.stderr or "")[-400:]
        tip = ("\n\nIt says 'Sign in to confirm you're not a bot' - import your YouTube cookies with /browsercookies "
               "and try again.") if "not a bot" in err.lower() else ""
        deliver(chat_id, mid, "Download failed." + tip)
        return
    fpath = files[0]
    size = os.path.getsize(fpath)
    if size <= 49 * 1024 * 1024:
        try:
            with open(fpath, "rb") as f:
                fld = "audio" if audio else "video"
                requests.post(TG + "/send" + ("Audio" if audio else "Video"),
                              data={"chat_id": chat_id, "caption": "\U0001F3AC " + os.path.basename(fpath)},
                              files={fld: (os.path.basename(fpath), f)}, timeout=300)
            deliver(chat_id, mid, "✅ Done: " + os.path.basename(fpath))
        except Exception:
            deliver(chat_id, mid, "Downloaded (~" + str(size // 1048576) + "MB) but Telegram wouldn't send it. Saved "
                    "on the server at " + fpath)
    else:
        deliver(chat_id, mid, "Downloaded (~" + str(size // 1048576) + "MB) - too big for Telegram's 50MB limit. "
                "Saved at " + fpath + ".")
        try:
            if google_ready():
                gdrive_upload(fpath, os.path.basename(fpath))
                send_text(chat_id, "☁️ Also uploaded it to your Google Drive.")
        except Exception:
            pass


def _short_host(url):
    try:
        return re.sub(r"^www\.", "", (url or "").split("/")[2])
    except Exception:
        return "the site"


def net_proxy():
    """The owner's OWN proxy / VPN endpoint, if they set one (/proxy set ...). It's applied to video downloads
    and (when set) to fetches, so he can reach content the server's bare IP is geo-blocked from or that you want
    routed privately. This is a proxy YOU provide (your subscription or your own box) - it is NOT a ban-evasion
    rotator and it does NOT defeat a site's bot-check/human-verification."""
    try:
        return (kv_get("net_proxy") or "").strip()
    except Exception:
        return ""


def _proxies():
    p = net_proxy()
    return {"http": p, "https": p} if p else None


# DRM-locked paid streaming: the stream is encrypted; yt-dlp can't pull it and we won't try to break the DRM.
_VID_DRM = re.compile(r"(netflix\.com|primevideo|amazon\.[a-z.]+/.*video|hotstar|jiocinema|disney|hbomax|max\.com|hulu|"
                      r"sonyliv|zee5|appletv|spotify\.com)", re.I)


def video_download(chat_id, url, audio=False):
    """Download a video (or just its audio) from ANY site yt-dlp supports (~1800: Instagram, X/Twitter, Facebook,
    TikTok, Reddit, Vimeo, Dailymotion, Twitch clips, news sites, most embeds...). Owner-only. Uses YOUR imported
    cookies for sites where you're logged in (/browsercookies) and YOUR /proxy if set. Sends over Telegram if it
    fits the 50MB limit, else saves on the server (+ Drive). DRM-locked paid streaming is refused honestly."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Only the Boss can download videos.")
        return
    m = re.search(r"https?://\S+", url or "")
    url = (m.group(0) if m else (url or "")).strip().strip("<>\"'")
    if not re.match(r"^https?://", url):
        send_text(chat_id, "Send a valid video link (https://...).")
        return
    if _VID_DRM.search(url):
        send_text(chat_id, "That's DRM-protected paid streaming — the video is encrypted, so it can't be downloaded "
                  "(yt-dlp can't decrypt it and I won't break the DRM). Any non-DRM site works fine.")
        return
    if not _imp("yt_dlp", notify=False):
        send_text(chat_id, "\U0001F527 Installing the downloader (first time)...")
        auto_install("yt_dlp", notify=False)
    os.makedirs("/root/nemo_code", exist_ok=True)
    tag = hashlib.md5(url.encode()).hexdigest()[:10]
    tmpl = "/root/nemo_code/vid_" + tag + ".%(ext)s"
    ph = tg("sendMessage", chat_id=chat_id,
            text="\U0001F4E5 Downloading the " + ("audio" if audio else "video") + " from " + _short_host(url) + "...")
    mid = ph.get("result", {}).get("message_id")
    if audio:
        cmd = ["yt-dlp", "-f", "bestaudio", "-x", "--audio-format", "mp3", "-o", tmpl, url]
    else:
        cmd = ["yt-dlp", "-f", "best[ext=mp4][filesize<48M]/best[height<=720][ext=mp4]/best[ext=mp4]/best",
               "--merge-output-format", "mp4", "-o", tmpl, url]
    if os.path.exists("/root/nemo_cookies.txt"):
        cmd = cmd[:1] + ["--cookies", "/root/nemo_cookies.txt"] + cmd[1:]
    _px = net_proxy()
    if _px:
        cmd = cmd[:1] + ["--proxy", _px] + cmd[1:]
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=900)
    except subprocess.TimeoutExpired:
        deliver(chat_id, mid, "That took too long or is too large to pull here.")
        return
    except Exception as e:
        deliver(chat_id, mid, "Downloader error: " + type(e).__name__ + ": " + str(e)[:150])
        return
    import glob
    files = [f for f in glob.glob("/root/nemo_code/vid_" + tag + ".*") if not f.endswith((".part", ".ytdl"))]
    files.sort(key=lambda f: os.path.getsize(f), reverse=True)
    if not files:
        err = (r.stderr or "")[-600:]
        el = err.lower()
        if any(w in el for w in ("not a bot", "sign in", "log in", "login", "private", "members-only", "cookies")):
            tip = ("\n\nThat one needs a logged-in session. Export YOUR cookies.txt from a browser where you're "
                   "logged into that site and send it with /browsercookies — I'll use your own session (I don't "
                   "defeat the login).")
        elif any(w in el for w in ("drm", "encrypted", "protected")):
            tip = "\n\nThe stream is DRM-encrypted, so it can't be downloaded."
        elif "unsupported url" in el or "no video" in el:
            tip = "\n\nyt-dlp doesn't recognise a video on that page. If it's embedded, send the direct video URL."
        elif _px:
            tip = "\n\n(Your /proxy may be down — try /proxy off, or a different proxy.)"
        else:
            tip = ("\n\n" + (err.strip().splitlines()[-1][:200] if err.strip() else "No downloadable media found."))
        deliver(chat_id, mid, "Couldn't download that video." + tip)
        return
    fpath = files[0]
    size = os.path.getsize(fpath)
    act_log("videodl", _short_host(url) + " -> " + os.path.basename(fpath))
    if size <= 49 * 1024 * 1024:
        try:
            with open(fpath, "rb") as f:
                fld = "audio" if audio else "video"
                requests.post(TG + "/send" + ("Audio" if audio else "Video"),
                              data={"chat_id": chat_id, "caption": "\U0001F3AC " + os.path.basename(fpath)},
                              files={fld: (os.path.basename(fpath), f)}, timeout=300)
            deliver(chat_id, mid, "✅ Done: " + os.path.basename(fpath))
        except Exception:
            deliver(chat_id, mid, "Downloaded (~" + str(size // 1048576) + "MB) but Telegram wouldn't send it. "
                    "Saved on the server at " + fpath)
    else:
        deliver(chat_id, mid, "Downloaded (~" + str(size // 1048576) + "MB) — too big for Telegram's 50MB limit. "
                "Saved at " + fpath + ".")
        try:
            if google_ready():
                gdrive_upload(fpath, os.path.basename(fpath))
                send_text(chat_id, "☁️ Also uploaded it to your Google Drive.")
        except Exception:
            pass


def proxy_cmd(chat_id, args):
    """Owner sets/clears their OWN proxy or VPN endpoint, applied to downloads and fetches."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner only.")
        return
    a = (args or "").strip()
    if not a or a.lower() in ("show", "status", "?"):
        cur = net_proxy()
        if cur:
            send_text(chat_id, "\U0001F310 Current proxy: " + re.sub(r"//[^@/]+@", "//***:***@", cur) +
                      "\nDownloads + fetches route through it. /proxy off to stop.")
        else:
            send_text(chat_id, "\U0001F310 No proxy set — using the server's own connection.\n\n"
                      "Route downloads/fetches through a proxy or VPN YOU provide (your subscription, or your own "
                      "box) — useful for privacy or to reach content your server's IP is geo-blocked from:\n"
                      "  /proxy set http://user:pass@host:port\n"
                      "  /proxy set socks5://host:port\n"
                      "  /proxy off   — clear it\n\n"
                      "Note: this is YOUR proxy for legitimate access. It is not a way past a site's "
                      "bot-check / human-verification.")
        return
    if a.lower() in ("off", "clear", "none", "remove", "stop"):
        kv_set("net_proxy", "")
        send_text(chat_id, "\U0001F310 Proxy cleared — back to the server's own connection.")
        return
    if a.lower().startswith("set "):
        a = a[4:].strip()
    if not re.match(r"(https?|socks[45]h?)://", a, re.I):
        send_text(chat_id, "Give a full proxy URL: http://host:port , http://user:pass@host:port , or socks5://host:port")
        return
    kv_set("net_proxy", a)
    send_text(chat_id, "\U0001F310 Proxy set. Downloads and fetches now route through it. /proxy off to stop.")


def _notes_pdf_file(title, subtitle, body, out="/tmp/nemo_notes.pdf"):
    """Render a title + text body (with simple headings/bullets) into a clean PDF. Hindi/Devanagari supported."""
    try:
        from fpdf import FPDF
    except Exception:
        auto_install("fpdf", notify=False)
        from fpdf import FPDF
    FAM = "Helvetica"
    pdf = FPDF()
    pdf.set_auto_page_break(auto=True, margin=16)
    if bool(re.search(r"[ऀ-ॿ]", (title or "") + " " + (body or ""))):
        hf = _ensure_hindi_font()
        if hf:
            try:
                pdf.add_font("noto", "", hf); pdf.add_font("noto", "B", hf); pdf.add_font("noto", "I", hf)
                FAM = "noto"
                try:
                    pdf.set_text_shaping(True)
                except Exception:
                    pass
            except Exception:
                FAM = "Helvetica"

    def _fit(s):
        return (s or "") if FAM == "noto" else (s or "").encode("latin-1", "replace").decode("latin-1")
    pdf.add_page()
    pdf.set_font(FAM, "B", 20)
    pdf.set_text_color(20, 40, 90)
    pdf.set_x(pdf.l_margin)
    pdf.multi_cell(0, 10, _fit((title or "Notes")[:120]))
    if subtitle:
        pdf.set_font(FAM, "", 9)
        pdf.set_text_color(120, 120, 120)
        pdf.set_x(pdf.l_margin)
        pdf.multi_cell(0, 6, _fit(subtitle[:200]))
    pdf.ln(3)
    pdf.set_text_color(0, 0, 0)
    pdf.set_font(FAM, size=11)
    for raw in (body or "").splitlines():
        st = raw.strip()
        head = st.lstrip("#").strip() if st.startswith("#") else None
        is_head = bool(head) or (0 < len(st) < 70 and st.endswith(":") and not st.startswith(("-", "*", chr(183))))
        line = ("   " + chr(183) + " " + st[2:]) if st.startswith(("- ", "* ")) else (head or st)
        line = line.replace("**", "")
        line = " ".join(w if len(w) <= 68 else " ".join(w[i:i + 68] for i in range(0, len(w), 68)) for w in line.split(" "))
        try:
            pdf.set_x(pdf.l_margin)
            if not st:
                pdf.ln(3)
            elif is_head:
                pdf.ln(2)
                pdf.set_font(FAM, "B", 13)
                pdf.set_text_color(20, 40, 90)
                pdf.multi_cell(0, 8, _fit(head or st.rstrip(":")))
                pdf.set_font(FAM, size=11)
                pdf.set_text_color(0, 0, 0)
            else:
                pdf.multi_cell(0, 6.5, _fit(line))
        except Exception:
            continue
    try:
        pdf.output(out)
        return out if os.path.exists(out) else None
    except Exception:
        return None


def _send_pdf(chat_id, path, caption="\U0001F4C4 Document"):
    try:
        with open(path, "rb") as f:
            requests.post(TG + "/sendDocument", data={"chat_id": chat_id, "caption": caption},
                          files={"document": (os.path.basename(path), f, "application/pdf")}, timeout=120)
        return True
    except Exception:
        return False


def youtube_notes(chat_id, url):
    """Turn a YouTube video into clean study notes and deliver them as a PDF."""
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F4DD Turning the video into study notes...")
    mid = ph.get("result", {}).get("message_id")
    vid = _yt_id(url)
    if not vid:
        deliver(chat_id, mid, "Send a valid YouTube link.")
        return
    tr = _yt_transcript(vid, url)
    if not tr:
        deliver(chat_id, mid, "I couldn't get the video's words (captions off, or YouTube blocking the server). "
                "Try /browsercookies.")
        return
    prompt = ("Turn this video transcript into clean, well-structured STUDY NOTES a student can revise from. Use short "
              "SECTION HEADINGS that end with a colon, bullet points under them, define key terms, and finish with a "
              "'Key Questions:' section of 5 short Q&A. Be thorough but tight. Plain text with headings and bullets.\n\n"
              "TRANSCRIPT:\n" + tr[:16000])
    notes = (claude_ask(chat_id, prompt, remember=False, timeout=200) if CLAUDE_KEY else None) or \
        ask_ai(chat_id, prompt, remember=False, deep=True, timeout=200)
    if not notes:
        deliver(chat_id, mid, "I couldn't write the notes this time - try again.")
        return
    p = _notes_pdf_file("Video Notes", url, notes)
    if p and _send_pdf(chat_id, p, "\U0001F4DD Study notes"):
        deliver(chat_id, mid, "\U0001F4DD Notes ready - sent as a PDF above.")
    else:
        deliver(chat_id, mid, "\U0001F4DD Study notes:\n\n" + notes[:3600], buttons=True)


def _yt_playlist_ids(url, cap=12):
    """List (video_id, title) for a playlist via yt-dlp (cookie-aware). Capped."""
    try:
        if not _imp("yt_dlp", notify=False):
            auto_install("yt_dlp", notify=False)
        cmd = ["yt-dlp", "--flat-playlist", "--print", "%(id)s\t%(title)s", url]
        if os.path.exists("/root/nemo_cookies.txt"):
            cmd = cmd[:1] + ["--cookies", "/root/nemo_cookies.txt"] + cmd[1:]
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=150)
        out = []
        for line in (r.stdout or "").splitlines():
            if "\t" in line:
                vid, title = line.split("\t", 1)
                if len(vid.strip()) >= 8:
                    out.append((vid.strip(), title.strip()))
        return out[:cap]
    except Exception:
        return []


def youtube_playlist_summary(chat_id, url):
    """Summarise a whole playlist: a few bullets per video + an overall overview, delivered as a PDF study guide."""
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F3AC Reading the playlist (this can take a few minutes)...")
    mid = ph.get("result", {}).get("message_id")
    ids = _yt_playlist_ids(url)
    if not ids:
        deliver(chat_id, mid, "I couldn't read that playlist - send a full playlist link (has 'list=...'). If YouTube "
                "is blocking the server, import cookies with /browsercookies.")
        return
    deliver(chat_id, mid, "Found " + str(len(ids)) + " videos - summarising each (up to 12)...")
    body = []
    for i, (vid, title) in enumerate(ids, 1):
        tr = _yt_transcript(vid, "https://youtu.be/" + vid)
        if not tr:
            body.append(str(i) + ". " + title + ":\n(no transcript available)\n")
            continue
        sp = "In 3-4 short bullets, give the key points of this video. Bullets only, no preamble.\n\n" + tr[:8000]
        s = (claude_ask(chat_id, sp, remember=False, timeout=120) if CLAUDE_KEY else
             ask_ai(chat_id, sp, remember=False, timeout=120))
        body.append(str(i) + ". " + title + ":\n" + (s or "(couldn't summarise)") + "\n")
        if i % 4 == 0:
            try:
                tg("editMessageText", chat_id=chat_id, message_id=mid, text="\U0001F3AC Summarised " + str(i) +
                   "/" + str(len(ids)) + " videos...")
            except Exception:
                pass
    joined = "\n".join(body)
    ov = (claude_ask(chat_id, "These are per-video summaries of a YouTube playlist. Write a 4-6 line OVERVIEW of what "
                     "the whole playlist teaches and the best way to go through it.\n\n" + joined[:12000],
                     remember=False, timeout=150) if CLAUDE_KEY else None)
    full = ("Overview:\n" + ov + "\n\n" if ov else "") + "Per-video summaries:\n\n" + joined
    p = _notes_pdf_file("Playlist Study Guide", url, full)
    if p and _send_pdf(chat_id, p, "\U0001F3AC Playlist study guide"):
        deliver(chat_id, mid, "\U0001F3AC Playlist summary ready (" + str(len(ids)) + " videos) - sent as a PDF above.")
    else:
        deliver(chat_id, mid, "\U0001F3AC Playlist summary:\n\n" + full[:3600], buttons=True)


def show_portfolio(chat_id):
    nl = chr(10)
    holdings = PORT.get(chat_id, {})
    if not holdings:
        send_text(chat_id, "Your portfolio is empty. Add with:\n/buy RELIANCE 10 2900  (symbol, qty, buy price)")
        return
    tg("sendMessage", chat_id=chat_id, text="\U0001F4BC Checking live prices...")
    lines, tot_inv, tot_now = [], 0.0, 0.0
    for sym, hd in holdings.items():
        q = get_quote(sym)
        inv = hd["qty"] * hd["avg"]
        tot_inv += inv
        if q:
            now = hd["qty"] * q["price"]
            tot_now += now
            pl = now - inv
            pct = pl / inv * 100 if inv else 0
            lines.append(f"{sym}: {hd['qty']:g} @ {hd['avg']:,.2f} -> now {q['price']:,.2f}  P/L {pl:+,.0f} ({pct:+.1f}%)")
        else:
            tot_now += inv
            lines.append(f"{sym}: {hd['qty']:g} @ {hd['avg']:,.2f} (live price unavailable)")
    total_pl = tot_now - tot_inv
    total_pct = total_pl / tot_inv * 100 if tot_inv else 0
    send_text(chat_id, "\U0001F4BC Your Portfolio:" + nl + nl + nl.join(lines) + nl + nl +
                       f"Invested: Rs.{tot_inv:,.0f}" + nl + f"Current: Rs.{tot_now:,.0f}" + nl +
                       f"Total P/L: Rs.{total_pl:+,.0f} ({total_pct:+.1f}%)" + nl + "(Prices may be delayed. Educational only.)")


def evening_review(chat_id):
    nl = chr(10)
    todos = TODOS.get(chat_id, [])
    pending = [t for t in todos if not t.get("done")]
    habits = HABITS.get(chat_id, {})
    today = time.strftime("%Y-%m-%d", time.gmtime(time.time() + IST_OFFSET))
    hbits = ", ".join(f"{k} (streak {v.get('streak', 0)})" for k, v in habits.items()) or "none set"
    sp = SPENT.get(chat_id, {}).get(today[:7], [])
    spent_today = sum(x["amt"] for x in sp if x.get("date") == today)
