def _needs_fresh(q):
    """Heuristic: does answering this WELL need him to LOOK UP a fact he may not hold, or one that changes over
    time? Deliberately conservative - we never want to web-search 'hi' or 'write a function'. Returns True/False."""
    if not isinstance(q, str):
        return False
    t = q.strip().lower()
    if len(t) < 12:
        return False
    # never for pure code / math / creative / meta-about-himself - those don't need the outside world
    if re.search(r"```|\bdef \b|\bclass \b|write (a |the |me )?(code|script|program|function|poem|story|essay|"
                 r"email|letter)|\bcalculate\b|\bsolve\b|\bcompile\b|\brefactor\b|\bdebug\b", t):
        return False
    if re.search(r"\b(you|your|yourself)\b.*\b(feel|think|opinion|name|who are you|how are you)\b", t):
        return False
    # strong 'time-sensitive / current' signals -> definitely look it up
    if re.search(r"\b(latest|current|currently|today|todays|tonight|now|right now|recent|recently|this (week|month|"
                 r"year)|as of|up to date|up-to-date|newest|breaking|live|these days)\b", t):
        return True
    # 'external fact that changes' signals
    if re.search(r"\b(news|price|prices|cost|worth|rate|stock|share price|market cap|valuation|score|results?|"
                 r"release date|released|launch|launched|latest version|update|schedule|fixture|standings|weather|"
                 r"forecast|who won|who is winning|deadline|when is|when does|when did|how much (is|does|are|will))\b", t):
        return True
    # 'who/what/where is <a Named Entity>' - a factual lookup about something specific (not a timeless 'explain')
    rest = q.strip()
    rest = rest[rest.find(" ") + 1:] if " " in rest else ""     # drop the (capitalised) first word
    if re.search(r"\b(who|what|which|where|when)\b", t) and re.search(r"[A-Z][a-zA-Z0-9.&'-]{2,}", rest) and \
            not re.search(r"\b(how do i|how to|explain|difference between|meaning of|define|what is a |what is an |"
                          r"what are )\b", t):
        return True
    return False


def curiosity_ground(chat_id, q):
    """He fills the gap himself: quietly web-search the question and hand back a compact, sourced grounding block
    (plus the raw findings so he can learn from them). Returns (ground_text, findings_list). Silent no-op when
    curiosity is off, the question doesn't need it, or the web isn't reachable - so it never hurts an answer."""
    _curiosity_loaded()
    if not CURIOSITY.get("on", True) or not _needs_fresh(q):
        return "", []
    try:
        results = web_search(q) or []
    except Exception:
        results = []
    findings = []
    for r in results[:4]:
        body = (r.get("body") or "").strip()
        if body:
            findings.append({"title": (r.get("title") or "").strip(), "body": body[:400],
                             "href": (r.get("href") or "").strip()})
    if not findings:
        return "", []
    block = ("LIVE WEB FINDINGS - you looked this up yourself just now because it needs current or factual "
             "knowledge. Use them to answer accurately and specifically, weave them in naturally, and don't say you "
             "can't check the web. If sources conflict, say so.\n" +
             "\n".join(f"- {f['title']}: {f['body']} ({f['href']})" for f in findings))
    return block, findings


def learn_from_web(chat_id, q, findings):
    """Learn side by side: distil 1-2 DURABLE, generally-true facts from what he just looked up and store them in
    permanent memory, so next time he already knows it (mem_recall surfaces it automatically). Background thread."""
    if not findings:
        return

    def _worker():
        try:
            src = "\n".join(f"- {f['title']}: {f['body']}" for f in findings)
            got = ask_ai(chat_id, "From these web findings, extract up to 2 DURABLE, generally-true facts worth "
                         "remembering long-term (NOT ephemeral prices/scores/weather, NOT personal to the user). "
                         "Each under 18 words, one per line, no numbering. If nothing durable, reply exactly NONE."
                         "\n\nQuestion: " + q[:300] + "\n\nFindings:\n" + src[:2500],
                         remember=False, models_override=FAST_MODELS, timeout=60)
            for line in (got or "").splitlines():
                fact = line.strip(" -*0123456789.").strip()
                if not fact or fact.upper() == "NONE" or len(fact) < 8 or len(fact) > 160:
                    continue
                try:
                    mem_add(fact, "knowledge")
                except Exception:
                    pass
                _learned_add(fact, (findings[0].get("href") or "")[:120])
        except Exception:
            pass
    threading.Thread(target=_worker, daemon=True).start()


def _learned_add(fact, source=""):
    """Append to the visible 'what he taught himself' log (kv-persisted, survives updates)."""
    try:
        import json as _j
        lst = _j.loads(kv_get("learned_log") or "[]")
        if not isinstance(lst, list):
            lst = []
        if any(fact.lower() == str(x.get("fact", "")).lower() for x in lst[-60:]):
            return
        lst.append({"fact": fact[:160], "src": source, "t": int(time.time())})
        del lst[:-LEARNED_MAX]
        kv_set("learned_log", _j.dumps(lst))
    except Exception:
        pass


def learned_show(chat_id, query=""):
    """Show the owner what Nemo has taught himself from the web (optionally filtered by a word)."""
    try:
        import json as _j
        lst = _j.loads(kv_get("learned_log") or "[]")
    except Exception:
        lst = []
    if query:
        ql = query.lower()
        lst = [x for x in lst if ql in str(x.get("fact", "")).lower()]
    if not lst:
        send_text(chat_id, "\U0001F9E0 I haven't logged anything I taught myself yet" +
                  (" about that." if query else " — ask me things that need looking up and I'll learn as I go."))
        return
    lines = []
    for x in lst[-25:][::-1]:
        when = time.strftime("%d %b", time.gmtime(x.get("t", 0) + IST_OFFSET))
        lines.append("• " + str(x.get("fact", ""))[:150] + "  (" + when + ")")
    send_text(chat_id, "\U0001F9E0 What I've taught myself lately (newest first):\n\n" + "\n".join(lines) +
              "\n\nI look things up on my own when a question needs it. /curiosity off to stop.")


def curiosity_cmd(chat_id, args):
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner only.")
        return
    _curiosity_loaded()
    a = (args or "").strip().lower()
    if a in ("on", "start", "enable", "yes"):
        CURIOSITY["on"] = True
        kv_set("curiosity", "1")
        send_text(chat_id, "\U0001F9E0 Curiosity ON — when a question needs a fact I don't hold, I'll look it up "
                  "myself and remember what I learn, without you asking.")
    elif a in ("off", "stop", "disable", "no"):
        CURIOSITY["on"] = False
        kv_set("curiosity", "0")
        send_text(chat_id, "\U0001F9E0 Curiosity OFF — I'll answer from what I already know and won't auto-search.")
    else:
        send_text(chat_id, "\U0001F9E0 Curiosity is " + ("ON" if CURIOSITY.get("on", True) else "OFF") +
                  ".\nWhen a question needs current or factual knowledge I look it up on my own, answer from it, and "
                  "remember it for next time.\n/curiosity on | off   ·   /learned — see what I've taught myself.")


def deep_research(chat_id, topic):
    """v6.2 #5 - deep research: many searches, cross-checked, delivered as a sourced report."""
    ph = tg("sendMessage", chat_id=chat_id,
            text="\U0001F52C DEEP RESEARCH: '" + topic[:100] + "'\nPlanning searches...")
    mid = ph.get("result", {}).get("message_id")
    plan = ask_ai(chat_id, "Break this research topic into 4 specific web search queries that together cover "
                  "it well. Reply with ONLY the 4 queries, one per line, no numbering.\nTopic: " + topic,
                  remember=False, models_override=FAST_MODELS, timeout=90)
    queries = [q.strip(" -*0123456789.") for q in (plan or "").splitlines() if len(q.strip()) > 4][:4]
    if not queries:
        queries = [topic]
    allres, sources = [], []
    for i, q in enumerate(queries):
        if mid:
            tg("editMessageText", chat_id=chat_id, message_id=mid,
               text=f"\U0001F52C DEEP RESEARCH: '{topic[:80]}'\nSearching {i + 1}/{len(queries)}: {q[:60]}")
        rs = web_search(q) or []
        for r in rs[:4]:
            allres.append(f"[{r.get('title', '')}] {r.get('body', '')[:400]}")
            if r.get("href"):
                sources.append(r["href"])
    if mid:
        tg("editMessageText", chat_id=chat_id, message_id=mid,
           text=f"\U0001F52C DEEP RESEARCH: '{topic[:80]}'\nCross-checking and writing the report...")
    report = ask_ai(chat_id, "You are a research analyst. Using the web findings below, write a thorough, "
                    "well-structured report on: " + topic + "\nBe factual and specific, note where sources "
                    "agree or disagree, and if something is uncertain say so. Plain text with clear sections. "
                    "End with a short 'Bottom line' summary.\n\nFindings:\n" + "\n\n".join(allres[:24]),
                    remember=False, deep=True, timeout=300)
    uniq = []
    for s in sources:
        if s not in uniq:
            uniq.append(s)
    if uniq:
        report += "\n\nSources:\n" + "\n".join("- " + s for s in uniq[:10])
    deliver(chat_id, mid, "\U0001F52C RESEARCH REPORT: " + topic[:100] + "\n\n" + report, buttons=True)


