def finance_report(chat_id):
    """v6.2 #2 - financial mastermind: spending + portfolio into one monthly money report."""
    nl = chr(10)
    ist = time.gmtime(time.time() + IST_OFFSET)
    month = time.strftime("%Y-%m", ist)
    last = time.strftime("%Y-%m", time.gmtime(time.time() + IST_OFFSET - 30 * 86400))
    sp = SPENT.get(chat_id, {}).get(month, [])
    sp_last = SPENT.get(chat_id, {}).get(last, [])
    tot = sum(x.get("amt", 0) for x in sp)
    tot_last = sum(x.get("amt", 0) for x in sp_last)
    cats = {}
    for x in sp:
        key = (x.get("what", "misc").split() or ["misc"])[0].lower()
        cats[key] = cats.get(key, 0) + x.get("amt", 0)
    top = sorted(cats.items(), key=lambda kv: -kv[1])[:6]
    pf = PORT.get(chat_id, {})
    inv = now = 0.0
    for sym, h in pf.items():
        q = get_quote(sym)
        inv += h["qty"] * h["avg"]
        now += h["qty"] * (q["price"] if q else h["avg"])
    ctx = (f"This month spending: Rs.{tot:,.0f} across {len(sp)} entries" + nl +
           f"Last month spending: Rs.{tot_last:,.0f}" + nl +
           "Top categories: " + (", ".join(f"{k} Rs.{v:,.0f}" for k, v in top) or "none logged") + nl +
           f"Portfolio invested: Rs.{inv:,.0f}, current value: Rs.{now:,.0f}, P/L: Rs.{now - inv:+,.0f}")
    ai = ask_ai(chat_id, "You are the user's sharp personal money manager for an Indian user. From this data, "
                "write a short monthly money report: where money is going, any overspending vs last month, "
                "portfolio health, and 3 concrete money moves. Show simple maths. End with: Educational only, "
                "not financial advice." + nl + nl + ctx, remember=False, deep=True, timeout=240)
    deliver(chat_id, None, "\U0001F4B0 MONEY REPORT - " + month + nl + nl + ctx + nl + nl + "-----" + nl + ai,
            buttons=True)


