def market_nudge_tick(now=None):
    """v8.3 - LIVE MARKET NUDGES: the moment NIFTY or BANKNIFTY breaks a key level or a strong signal
    forms, Nemo tells the Boss - unprompted. Deduped per event, capped per day, market hours only."""
    if not (PROACTIVE.get("on") and PROACTIVE.get("nudge") and OWNER.get("id") and BROKER.get("token")):
        return
    wd, mins = _ist_mins(now)
    if wd >= 5 or not (9 * 60 + 20 <= mins <= 15 * 60 + 20):
        return
    today = fyers_today()
    st = PROACTIVE.setdefault("nstate", {})
    if st.get("day") != today:
        st.clear()
        st["day"], st["count"] = today, 0
    if st.get("count", 0) >= PROACTIVE.get("maxnudge", 8):
        return
    hon = IDENTITY.get("honorific", "Boss")
    for idx in ("NIFTY", "BANKNIFTY"):
        try:
            a = godmode_analyze(idx)
        except Exception:
            a = None
        if not a:
            continue
        price, lv = a["price"], a["levels"]
        sign = 1 if a["score"] > 0 else -1
        prev = st.get(idx, {})
        events = []
        if abs(a["score"]) >= 5 and prev.get("sign") not in (None, sign):
            events.append(f"{idx}: a strong {a['signal']} is forming (confluence {a['score']:+d} of 6) around {price:,.0f}")
        if prev.get("price"):
            if prev["price"] < lv["r1"] <= price:
                events.append(f"{idx} just broke ABOVE resistance {lv['r1']:,.0f} - now {price:,.0f}")
            elif prev["price"] > lv["s1"] >= price:
                events.append(f"{idx} just broke BELOW support {lv['s1']:,.0f} - now {price:,.0f}")
        st[idx] = {"price": price, "sign": sign}
        for e in events:
            if st.get("count", 0) >= PROACTIVE.get("maxnudge", 8):
                break
            proactive_push("\U0001F4E1 " + hon + ", " + e + ". (educational, not advice)", title="NEMO - MARKET")
            st["count"] = st.get("count", 0) + 1


