def run_code(chat_id, task):
    """v10.2.1 - CODE AGENT: the best available brain writes Python, Nemo RUNS it isolated in a subprocess, and if
    it errors he reads the traceback and FIXES it himself (up to 2 repairs) before reporting. Uses the RAW code
    path (no markdown cleaning) so Python dunders (__name__/__main__) and **kwargs survive intact. Scripts must be
    SELF-CONTAINED (inputs hardcoded from the task; no required argv / no input()) since the job runs with no args."""
    import subprocess
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F4BB Writing and running code for: " + task[:120] + " ...")
    mid = ph.get("result", {}).get("message_id")

    def _gen(prompt):
        # prefer the premium Claude brain for code quality; fall back to the free brain (RAW - no text cleaning)
        if CLAUDE_KEY and CLAUDECFG.get("on", True):
            c = claude_chat([{"role": "user", "content": prompt}],
                            model=CLAUDECFG.get("hard_model", "sonnet"), timeout=240, max_tokens=6000)
            if c:
                return c
        return ask_ai(chat_id, prompt, remember=False, deep=True, timeout=240, raw=True)

    def _strip(c):
        return re.sub(r"^```[a-zA-Z]*\n?|```$", "", (c or "").strip(), flags=re.M).strip()

    code = _strip(_gen(
        "Write a COMPLETE, runnable Python 3 script for this task on a Linux server. Print results with print(). "
        "CRITICAL: the script is run as `python3 job.py` with NO command-line arguments and NO interactive input. "
        "So do NOT use argparse with required arguments, and NEVER call input() or read sys.stdin. Take every input "
        "(search queries, song/video names, symbols, URLs, etc.) directly from the task text below and HARDCODE it "
        "near the top as a variable, or use a sensible default. The script must run fully on its own and print the "
        "result. If it needs a third-party package, pip-install it in-script (subprocess + --break-system-packages) "
        "and handle the case where a system binary like ffmpeg is missing (apt-get install -y, or report clearly). "
        "Write correct Python - real dunders like __name__ == \"__main__\", real **kwargs. "
        "Reply with ONLY the raw code - no prose, no markdown fences.\nTask: " + task))
    if not code:
        deliver(chat_id, mid, "I couldn't produce code for that.")
        return
    os.makedirs("/root/nemo_code", exist_ok=True)
    jobfile = "/root/nemo_code/job.py"
    out = ""
    repaired = 0
    for attempt in range(3):                       # initial run + up to 2 self-repairs
        failed = False
        try:
            with open(jobfile, "w") as f:
                f.write(code)
            r = subprocess.run(["python3", jobfile], capture_output=True, text=True,
                               timeout=CODECFG.get("timeout", 300), cwd="/root/nemo_code")
            out = ((r.stdout or "") + (("\n[stderr]\n" + r.stderr) if r.stderr.strip() else "")).strip() \
                or "(the script ran but printed nothing)"
            failed = (r.returncode != 0) or ("Traceback (most recent call last)" in (r.stderr or ""))
        except subprocess.TimeoutExpired:
            out = f"Timed out after {CODECFG.get('timeout', 300)}s. Raise it with /codetimeout <seconds> for longer jobs."
        except Exception as e:
            out = "Run error: " + type(e).__name__ + " " + str(e)[:200]
            failed = True
        if not failed or attempt == 2:
            break
        repaired += 1
        try:
            tg("editMessageText", chat_id=chat_id, message_id=mid,
               text="\U0001F527 Code hit an error - reading the traceback and fixing it myself (attempt " +
               str(repaired) + ")...")
        except Exception:
            pass
        fixed = _strip(_gen("This Python script failed when run as `python3 job.py` with NO arguments and NO stdin. "
                            "Fix it and return the COMPLETE corrected script (raw code only, no prose, no markdown). "
                            "If the error is an argparse 'usage:' / 'the following arguments are required' error, or "
                            "an EOFError from input(), then REMOVE argparse/input entirely and HARDCODE the needed "
                            "values (e.g. the search query or URL) taken from the original task below.\n\n"
                            "--- original task ---\n" + task[:600] +
                            "\n\n--- script ---\n" + code[:6000] +
                            "\n\n--- error output ---\n" + out[:1500]))
        if not fixed:
            break
        code = fixed
    if len(out) > 3500:
        out = out[:3500] + "\n... (truncated)"
    tag = ("  (self-corrected " + str(repaired) + "x)" if repaired else "")
    deliver(chat_id, mid, "\U0001F4BB CODE RESULT" + tag + ":\n\n" + out +
            "\n\n(code saved at /root/nemo_code/job.py)", buttons=True)


# ================== v11.24 MAKER: mini-me abilities — plan, code-as-a-file, charts, and real doc/sheet/text files ==
def _send_file(chat_id, path, caption="\U0001F4C4 File", mime=None):
    """Deliver any file to the chat as a Telegram document."""
    try:
        with open(path, "rb") as f:
            fname = os.path.basename(path)
            files = {"document": (fname, f, mime)} if mime else {"document": (fname, f)}
            requests.post(TG + "/sendDocument", data={"chat_id": chat_id, "caption": caption[:1000]},
                          files=files, timeout=180)
        try:
            LASTFILE[chat_id] = path       # so 'give me the file again / here' can resend it
        except Exception:
            pass
        return True
    except Exception:
        return False


def _num(x):
    """Coerce numeric-looking strings to real numbers so spreadsheets/charts get numbers, not text."""
    if isinstance(x, (int, float)):
        return x
    s = str(x).strip().replace(",", "")
    try:
        if re.match(r"^-?\d+$", s):
            return int(s)
        if re.match(r"^-?\d*\.\d+$", s):
            return float(s)
    except Exception:
        pass
    return str(x)


def make_docx(chat_id, topic, email_to=""):
    """Write a real Word (.docx) document on a topic and deliver it (optionally email it too)."""
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F4DD Writing your Word document: " + (topic or "")[:100] + " ...")
    mid = ph.get("result", {}).get("message_id")
    body = ask_ai(chat_id, "Write a complete, well-structured document on this. The VERY FIRST line must be the "
                  "document TITLE only. Then use lines starting with '# ' for section headings and '- ' for bullet "
                  "points; everything else is normal paragraphs. No markdown bold/italic markers, no code fences. Be "
                  "thorough and specific.\n\nTopic: " + (topic or ""), remember=False, deep=True, timeout=240)
    if not body:
        deliver(chat_id, mid, "I couldn't generate that document just now.")
        return
    if not _imp("docx", notify=False):
        auto_install("docx", notify=False)
    try:
        from docx import Document
        lines = [l.rstrip() for l in body.splitlines()]
        title = (next((l for l in lines if l.strip()), topic) or topic).strip("# ").strip()[:120] or "Document"
        doc = Document()
        doc.add_heading(title, level=0)
        started = False
        for raw in lines:
            s = raw.strip()
            if not started:                      # skip everything up to & including the title line
                if s:
                    started = True
                continue
            if not s:
                continue
            if s.startswith("# "):
                doc.add_heading(s[2:].strip()[:120], level=1)
            elif s.startswith(("- ", "* ")):
                doc.add_paragraph(s[2:].strip(), style="List Bullet")
            else:
                doc.add_paragraph(s)
        os.makedirs("/root/nemo_code", exist_ok=True)
        safe = (re.sub(r"[^\w -]", "", title)[:50].strip().replace(" ", "_") or "document")
        path = "/root/nemo_code/" + safe + ".docx"
        doc.save(path)
    except Exception as e:
        deliver(chat_id, mid, "Word engine hit an error (" + type(e).__name__ + ") — here's the text instead:\n\n" + body[:3000])
        return
    deliver(chat_id, mid, "✅ Word document ready.")
    _send_file(chat_id, path, "\U0001F4DD " + title[:120],
               "application/vnd.openxmlformats-officedocument.wordprocessingml.document")
    if email_to:
        try:
            if send_email(email_to, title[:120], "Attached: " + title, attach=path):
                send_text(chat_id, "\U0001F4E7 Emailed it to " + email_to)
        except Exception:
            pass


def make_xlsx(chat_id, spec):
    """Build a real Excel (.xlsx) sheet from a description or data and deliver it."""
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F4CA Building your Excel sheet: " + (spec or "")[:100] + " ...")
    mid = ph.get("result", {}).get("message_id")
    raw = ask_ai(chat_id, "Turn this request into a spreadsheet. Reply ONLY as JSON: "
                 '{"title":"Sheet name","headers":["Col1","Col2"],"rows":[["a","1"],["b","2"]]}. '
                 "Fill real, sensible values from the request; keep numbers as numbers. Up to 200 rows.\n\n"
                 "Request: " + (spec or ""), remember=False, deep=True, timeout=200)
    try:
        j = json.loads(raw[raw.find("{"):raw.rfind("}") + 1])
        headers = j.get("headers") or []
        rows = j.get("rows") or []
        title = (j.get("title") or "Sheet")[:60]
    except Exception:
        deliver(chat_id, mid, "I couldn't structure that into a sheet — tell me the columns you want.")
        return
    if not headers and not rows:
        deliver(chat_id, mid, "That produced no rows — tell me the columns and what to fill.")
        return
    if not _imp("openpyxl", notify=False):
        auto_install("openpyxl", notify=False)
    try:
        import openpyxl
        from openpyxl.styles import Font
        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = (re.sub(r"[^\w ]", "", title)[:31] or "Sheet1")
        if headers:
            ws.append([str(h) for h in headers])
            for c in ws[1]:
                c.font = Font(bold=True)
        for r in rows[:500]:
            ws.append([_num(x) for x in (r if isinstance(r, list) else [r])])
        for col in ws.columns:
            w = max((len(str(c.value)) for c in col if c.value is not None), default=8)
            ws.column_dimensions[col[0].column_letter].width = min(48, max(10, w + 2))
        os.makedirs("/root/nemo_code", exist_ok=True)
        safe = (re.sub(r"[^\w -]", "", title)[:50].strip().replace(" ", "_") or "sheet")
        path = "/root/nemo_code/" + safe + ".xlsx"
        wb.save(path)
    except Exception as e:
        deliver(chat_id, mid, "Excel engine error: " + type(e).__name__)
        return
    deliver(chat_id, mid, "✅ Excel sheet ready (" + str(len(rows)) + " rows).")
    _send_file(chat_id, path, "\U0001F4CA " + title,
               "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


def make_textfile(chat_id, spec, kind="txt"):
    """Generate a plain text / markdown / csv file from a request and deliver it."""
    kind = kind if kind in ("txt", "md", "csv") else "txt"
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F4C4 Making your ." + kind + " file ...")
    mid = ph.get("result", {}).get("message_id")
    if kind == "csv":
        instr = ("Produce ONLY valid CSV: a header row first, comma-separated, quote any field containing a comma. "
                 "No prose, no code fences.")
    elif kind == "md":
        instr = "Produce a clean, well-structured Markdown document. No surrounding code fences."
    else:
        instr = "Produce clean plain text. No markdown symbols, no code fences."
    content = ask_ai(chat_id, instr + "\n\nRequest: " + (spec or ""), remember=False, deep=True, timeout=200, raw=True)
    content = _clean_code(content)
    if _looks_scratchpad(content):                  # v12.05: retry once if the brain 'thought out loud' instead of producing the file
        content = _clean_code(ask_ai(chat_id, instr + " Output ONLY the finished content itself - no commentary, no "
                              "'here is', no placeholders.\n\nRequest: " + (spec or ""), remember=False, deep=True,
                              timeout=200, raw=True))
    if not content or _looks_scratchpad(content):
        deliver(chat_id, mid, "I couldn't produce clean content for that - tell me a bit more precisely what to put in it.")
        return
    os.makedirs("/root/nemo_code", exist_ok=True)
    safe = (re.sub(r"[^\w -]", "", (spec or ""))[:40].strip().replace(" ", "_") or "file")
    path = "/root/nemo_code/" + safe + "." + kind
    with open(path, "w") as f:
        f.write(content)
    deliver(chat_id, mid, "✅ Your ." + kind + " file is ready.")
    _send_file(chat_id, path, "\U0001F4C4 " + os.path.basename(path))


def make_chart(chat_id, spec):
    """Turn a request (with data, or a described dataset) into a chart image and send it."""
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F4C8 Making your chart ...")
    mid = ph.get("result", {}).get("message_id")
    raw = ask_ai(chat_id, "Turn this into ONE chart. Reply ONLY as JSON: "
                 '{"type":"bar|line|pie","title":"...","xlabel":"","ylabel":"","labels":["A","B"],'
                 '"series":[{"name":"S1","data":[1,2]}]}. Use the real numbers if given, else sensible '
                 "representative values. For pie use one series. Max 20 labels.\n\nRequest: " + (spec or ""),
                 remember=False, deep=True, timeout=180)
    try:
        j = json.loads(raw[raw.find("{"):raw.rfind("}") + 1])
        ctype = (j.get("type") or "bar").lower()
        labels = [str(x) for x in (j.get("labels") or [])]
        series = j.get("series") or []
        title = (j.get("title") or "Chart")[:120]
    except Exception:
        deliver(chat_id, mid, "I couldn't structure that into a chart — give me the numbers or a clearer ask.")
        return
    if not series:
        deliver(chat_id, mid, "No data to plot — tell me the values (or a dataset to use).")
        return
    if not _imp("matplotlib", notify=False):
        auto_install("matplotlib", notify=False)
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        colors = ["#2563eb", "#16a34a", "#dc2626", "#d97706", "#7c3aed", "#0891b2", "#db2777", "#4b5563"]
        plt.figure(figsize=(9, 5))
        if ctype == "pie":
            data = [_num(x) for x in series[0].get("data", [])]
            plt.pie(data, labels=(labels[:len(data)] or None), autopct="%1.1f%%",
                    colors=colors[:len(data)] or None)
        elif ctype == "line":
            for i, s in enumerate(series):
                d = [_num(x) for x in s.get("data", [])]
                plt.plot(labels[:len(d)] or list(range(len(d))), d, marker="o",
                         color=colors[i % len(colors)], label=s.get("name", ""))
            if len(series) > 1:
                plt.legend()
            plt.xlabel(j.get("xlabel", "")); plt.ylabel(j.get("ylabel", ""))
            plt.xticks(rotation=30, ha="right")
        else:                                      # bar (grouped if multi-series) - no numpy needed
            n = len(series)
            base = list(range(len(labels) if labels else len(series[0].get("data", []))))
            w = 0.8 / max(1, n)
            for i, s in enumerate(series):
                d = [_num(x) for x in s.get("data", [])]
                plt.bar([x + i * w for x in base][:len(d)], d, width=w,
                        color=colors[i % len(colors)], label=s.get("name", ""))
            if labels:
                plt.xticks([x + w * (n - 1) / 2 for x in base], labels, rotation=30, ha="right")
            if n > 1:
                plt.legend()
            plt.xlabel(j.get("xlabel", "")); plt.ylabel(j.get("ylabel", ""))
        plt.title(title)
        plt.tight_layout()
        path = "/tmp/nemo_chart.png"
        plt.savefig(path, dpi=120)
        plt.close()
    except Exception as e:
        deliver(chat_id, mid, "Chart engine error: " + type(e).__name__)
        return
    deliver(chat_id, mid, "✅ Chart ready: " + title)
    try:
        with open(path, "rb") as f:
            requests.post(TG + "/sendPhoto", data={"chat_id": chat_id, "caption": "\U0001F4C8 " + title[:180]},
                          files={"photo": ("chart.png", f)}, timeout=120)
    except Exception:
        pass


# ================== v11.29 PINE: error-free TradingView Pine Script (verified template + linter + repair loop) ==
# A hand-verified, compiles-clean Pine v5 STRATEGY (real entries/exits with an ATR take-profit and % stop-loss).
# It is BOTH the guaranteed fallback and the style reference the brain must mirror.
PINE_TEMPLATE = '''//@version=6
strategy("EMA Crossover + Vol + ATR TP/SL", overlay=true, initial_capital=100000, default_qty_type=strategy.percent_of_equity, default_qty_value=100, commission_type=strategy.commission.percent, commission_value=0.03)

// ---- Inputs ----
fastLen = input.int(9,  "Fast EMA")
slowLen = input.int(21, "Slow EMA")
useVol  = input.bool(true, "Require volume above its average")
volLen  = input.int(20, "Volume MA length")
atrLen  = input.int(14, "ATR length")
tpMult  = input.float(3.0, "Take-profit (x ATR)", step=0.1)
slPerc  = input.float(1.0, "Stop-loss (%)", step=0.1)

// ---- Indicators ----
fastEMA = ta.ema(close, fastLen)
slowEMA = ta.ema(close, slowLen)
volMA   = ta.sma(volume, volLen)
atr     = ta.atr(atrLen)
volOK   = not useVol or volume > volMA

longSig  = ta.crossover(fastEMA, slowEMA) and volOK
shortSig = ta.crossunder(fastEMA, slowEMA) and volOK

// ---- Entries ----
if longSig
    strategy.entry("Long", strategy.long)
if shortSig
    strategy.entry("Short", strategy.short)

// ---- Exits: ATR take-profit + percent stop-loss ----
longTP  = strategy.position_avg_price + tpMult * atr
longSL  = strategy.position_avg_price * (1.0 - slPerc / 100.0)
shortTP = strategy.position_avg_price - tpMult * atr
shortSL = strategy.position_avg_price * (1.0 + slPerc / 100.0)
if strategy.position_size > 0
    strategy.exit("Exit Long", from_entry="Long", limit=longTP, stop=longSL)
if strategy.position_size < 0
    strategy.exit("Exit Short", from_entry="Short", limit=shortTP, stop=shortSL)

// ---- Plots ----
plot(fastEMA, "Fast EMA", color=color.new(color.aqua, 0))
plot(slowEMA, "Slow EMA", color=color.new(color.orange, 0))
plotshape(longSig,  title="Buy",  style=shape.triangleup,   location=location.belowbar, color=color.new(color.green, 0), size=size.small)
plotshape(shortSig, title="Sell", style=shape.triangledown, location=location.abovebar, color=color.new(color.red, 0), size=size.small)

// ---- Alerts ----
alertcondition(longSig,  title="Buy",  message="EMA crossover BUY")
alertcondition(shortSig, title="Sell", message="EMA crossover SELL")
'''

def _pine_sys():
    ver = PINECFG.get("ver", "6")
    return (
        "You are a TradingView Pine Script v" + ver + " EXPERT. Output ONLY valid Pine v" + ver +
        " that compiles with ZERO errors.\n"
        "HARD RULES:\n"
        "- The FIRST line must be exactly //@version=" + ver + "\n"
        "- Then EXACTLY ONE declaration: strategy(...) when it needs entries/exits/target/stop-loss, otherwise "
        "indicator(...). NEVER call strategy.* inside an indicator().\n"
        "- Use the ta./math./request.security namespaces: ta.ema/ta.sma/ta.rsi/ta.atr/ta.crossover/ta.crossunder/"
        "ta.highest/ta.lowest, math.*, request.security(), and input.int()/input.float()/input.bool()/input.string(). "
        "NEVER bare sma()/rsi()/atr()/crossover()/input()/security()/study().\n"
        "- plot(), plotshape(), hline(), bgcolor(), fill(), barcolor(), alertcondition() ONLY at global scope - NEVER "
        "inside an if/for block.\n"
        "- Balance every parenthesis and bracket. Use real 4-space indentation for if/for bodies.\n"
        "- For buy/sell with a target and a stop-loss, use strategy() with strategy.entry, and wrap entries/exits in "
        "if blocks; use strategy.exit(limit=<target>, stop=<stop>).\n" +
        ("- v6 RULES (IMPORTANT): bool is strictly true/false - never assign na to a bool, and cast with bool() if "
         "needed. There is NO 'when=' parameter on strategy.entry/exit/close (wrap them in if instead). Use the "
         "'1D'/'1W'/'1M' timeframe format, not bare 'D'/'W'/'M'. No 'transp=' - use color.new(col, transp). "
         "request.security accepts dynamic strings. You MAY use v6 extras (input.enum, log.info/warning/error, "
         "polyline) when they help.\n" if ver == "6" else "") +
        "Output ONLY the raw code - no prose, no markdown fences.\n\n"
        "Mirror the STYLE and exact syntax of this KNOWN-GOOD reference:\n" + PINE_TEMPLATE)


# v11.31: a LIBRARY of hand-verified, lint-clean, ADVANCED Pine v5 strategies - rotated so no two generic requests
# come out the same, and used as accurate style references so the brain writes varied, sophisticated code.
