def _pine_sanitize(code):
    """v12.04: force Pine code to pure ASCII. Smart quotes, non-breaking spaces, en/em dashes and zero-width chars
    (which sneak in via chat/PDF/phone and cause TradingView's baffling 'Syntax error at input X' on code that
    looks perfect) are converted to plain ASCII. This is THE fix for the recurring copy-paste compile errors."""
    if not code:
        return code
    code = code.replace("\r\n", "\n").replace("\r", "\n")            # normalise line endings
    repl = {"“": '"', "”": '"', "„": '"', "‟": '"', "″": '"',
            "‘": "'", "’": "'", "‚": "'", "‛": "'", "′": "'", "´": "'", "`": "'",
            "–": "-", "—": "-", "−": "-", "―": "-",
            " ": " ", " ": " ", " ": " ", " ": " ", " ": " ", "　": " ",
            "…": "...", "\t": "    "}
    for k, v in repl.items():
        code = code.replace(k, v)
    code = re.sub(r"[​‌‍⁠﻿]", "", code)          # zero-width / BOM
    code = "".join(ch for ch in code if ord(ch) < 128 or ch == "\n")       # drop any remaining non-ASCII
    return code


def pine_lint(code):
    """A rule-based Pine v5 checker for the errors that actually break TradingView compiles. Not a full compiler,
    but it catches the frequent ones and drives the repair loop. Returns a list of concrete problems ([] = clean)."""
    if code and not code.isascii():
        return ["Non-ASCII characters (smart quotes / non-breaking spaces) - TradingView needs plain ASCII. "
                "These cause 'Syntax error at input ...' on code that looks fine."]
    errs, code = [], code or ""
    lines = code.split("\n")
    if not re.search(r"//@version\s*=\s*[456]", code):
        errs.append("Missing the version header - the first line must be //@version=6 (or //@version=5).")
    if re.search(r"(?m)^\s*study\s*\(", code):
        errs.append("study() is old Pine - in v5 use indicator().")
    decls = re.findall(r"(?m)^\s*(indicator|strategy|library)\s*\(", code)
    if not decls:
        errs.append("No indicator() or strategy() declaration.")
    elif len(decls) > 1:
        errs.append("More than one declaration - keep exactly one indicator() or strategy().")
    is_strat = bool(re.search(r"(?m)^\s*strategy\s*\(", code))
    if not is_strat and re.search(r"\bstrategy\.(entry|exit|close|order|cancel|position)\b", code):
        errs.append("strategy.* is used but the script is an indicator() - declare strategy(...) instead, or remove the strategy.* calls (this is the 'strategy function used in indicator' error).")
    for fn in ("sma", "ema", "wma", "rma", "vwma", "rsi", "atr", "macd", "stoch", "cci", "mfi", "crossover",
               "crossunder", "cross", "highest", "lowest", "change", "mom", "roc", "tr", "barssince", "valuewhen",
               "cum", "sar", "supertrend", "vwap", "linreg", "correlation", "percentile_nearest_rank"):
        if re.search(r"(?<![.\w])" + fn + r"\s*\(", code):
            errs.append("'" + fn + "()' must be 'ta." + fn + "()' in Pine v5.")
    if re.search(r"(?<![.\w])security\s*\(", code):
        errs.append("security() must be request.security() in v5.")
    if re.search(r"(?<![.\w])input\s*\(", code):
        errs.append("Bare input() - use input.int()/input.float()/input.bool()/input.string() in v5.")
    if re.search(r"(?<![.\w])(?:round|abs|max|min|pow|sqrt|floor|ceil|log|exp|sign|avg)\s*\(", code):
        errs.append("Math like abs()/max()/round() must be math.abs()/math.max()/math.round() in v5.")
    for op, cl, nm in (("(", ")", "parentheses"), ("[", "]", "square brackets")):
        if code.count(op) != code.count(cl):
            errs.append("Unbalanced " + nm + " (" + str(code.count(op)) + " '" + op + "' vs " + str(code.count(cl)) + " '" + cl + "').")
    for i, ln in enumerate(lines):
        if re.match(r"^[ \t]+(plot|plotshape|plotchar|plotarrow|hline|bgcolor|fill|barcolor|alertcondition)\s*\(", ln):
            errs.append("Line " + str(i + 1) + ": " + ln.strip()[:24] + " can't be inside an if/for block - move it to global (no indentation).")
    # v6-specific: 'when=' was removed from strategy.* (wrap in if), and 'transp=' was removed (use color.new).
    if re.search(r"(?m)^\s*//@version\s*=\s*6", code):
        if re.search(r"strategy\.(entry|exit|close|order)\s*\([^)]*\bwhen\s*=", code):
            errs.append("v6: strategy.entry/exit/close no longer take a 'when=' argument - wrap the call in an if instead.")
        if re.search(r"\btransp\s*=", code):
            errs.append("v6: the 'transp=' argument was removed - use color.new(color, transparency) instead.")
        if re.search(r'\btime\s*\(\s*"[DWM]"', code):
            errs.append("v6: timeframe letters are '1D'/'1W'/'1M' now, not 'D'/'W'/'M'.")
    out = []
    for e in errs:
        if e not in out:
            out.append(e)
    return out


def _pine_ask(prompt):
    """Ask for Pine code - PREFER the premium Claude brain (free nano brains are poor at niche languages like Pine),
    fall back to the best writer brain. The DEEP Pine knowledge base rides in the system prompt so the code is
    advanced and correct. Returns raw code (fences stripped)."""
    sysmsg = _pine_sys() + "\n\n" + PINE_KNOWLEDGE
    c = None
    try:
        if CLAUDE_KEY and CLAUDECFG.get("on", True):
            c = claude_chat([{"role": "system", "content": sysmsg}, {"role": "user", "content": prompt}],
                            model=CLAUDECFG.get("hard_model", "sonnet"), timeout=220, max_tokens=6000)
    except Exception:
        c = None
    if not c:
        try:
            c = ask_ai(0, sysmsg + "\n\n" + prompt, remember=False, deep=True, timeout=220, raw=True,
                       models_override=WRITER_MODELS)
        except Exception:
            c = ""
    return re.sub(r"^```[a-zA-Z]*\n?|```$", "", (c or "").strip(), flags=re.M).strip()


def _pine_pick(spec):
    """Pick the approach + a matching verified fallback. A NAMED method is honoured; a GENERIC request round-robins
    through the archetypes so no two 'make me a pine script' come out the same. Returns (approach, fallback, rotated)."""
    s = (spec or "").lower()
    named = [
        (r"supertrend", "Supertrend trend-rider with an ATR trailing stop", PINE_T_SUPERTREND),
        (r"\borb\b|opening range|open range", "Opening Range Breakout for NIFTY intraday with a session filter", PINE_T_ORB),
        (r"vwap", "VWAP mean-reversion with standard-deviation bands", PINE_T_VWAP),
        (r"bollinger|squeeze|keltner", "Bollinger squeeze breakout (Keltner inside Bollinger)", PINE_T_VWAP),
        (r"macd", "MACD histogram momentum with a 200-EMA regime filter", PINE_T_RSI_HTF),
        (r"\brsi\b|relative strength", "RSI momentum with a higher-timeframe trend filter", PINE_T_RSI_HTF),
        (r"donchian|channel breakout", "Donchian channel breakout with ATR sizing", PINE_T_ORB),
        (r"ichimoku|cloud", "Ichimoku cloud trend-following", PINE_T_SUPERTREND),
        (r"\bema\b|crossover|moving average", "EMA crossover with a volume filter and ATR TP/SL", PINE_TEMPLATE),
    ]
    for pat, arch, tmpl in named:
        if re.search(pat, s):
            return arch, tmpl, False
    try:
        rotor = int(kv_get("pine_rotor") or "0")
    except Exception:
        rotor = 0
    try:
        kv_set("pine_rotor", str((rotor + 1) % 100000))
    except Exception:
        pass
    return PINE_ARCHETYPES[rotor % len(PINE_ARCHETYPES)], PINE_TEMPLATES[rotor % len(PINE_TEMPLATES)][1], True


def pine_generate(chat_id, spec, email_to=""):
    """Generate an ADVANCED, ERROR-FREE, VARIED Pine v5 script: pick an approach (named, or round-robin for a
    generic ask) -> premium-brain generation grounded in the deep knowledge base -> lint -> up to 3 self-repairs ->
    if still not clean, fall back to the matching hand-verified template. Delivers the .pine + honest status."""
    spec = (spec or "").strip()
    approach, fallback, rotated = _pine_pick(spec)
    ph = tg("sendMessage", chat_id=chat_id,
            text="\U0001F4C8 Writing an ADVANCED, error-free Pine v6 script...\nApproach: " + approach[:80] + "\nGenerating, then checking it.")
    mid = ph.get("result", {}).get("message_id")
    want_ind = bool(re.search(r"\bindicator\b", spec.lower()) and not re.search(r"\bstrateg", spec.lower()))
    code = _pine_ask(
        "Write a COMPLETE, ADVANCED, genuinely useful Pine v5 " + ("indicator" if want_ind else "strategy") +
        " for this request:\n" + (spec or "a unique, high-quality intraday setup for NIFTY with buy/sell, a target "
        "and a stop-loss") + "\n\nBe CREATIVE and NON-GENERIC - do NOT default to a plain EMA crossover unless the "
        "user explicitly asked for one. APPROACH to build: " + approach + ". Combine 2-3 confluence factors, expose "
        "real inputs, include a take-profit and a stop-loss, buy/sell markers and alerts, and add a professional "
        "touch (a stats table, or dynamic alert messages, or a trailing stop) where it fits. Mirror the correct "
        "SYNTAX of this verified reference, but build the APPROACH above - not this exact logic:\n" + fallback)
    code = _pine_sanitize(code)                      # v12.04: pure ASCII, so copy-paste never breaks it
    errs = pine_lint(code) if code else ["no code produced"]
    tries = 0
    while errs and tries < 3:
        tries += 1
        try:
            tg("editMessageText", chat_id=chat_id, message_id=mid,
               text="\U0001F527 Found " + str(len(errs)) + " issue(s) - fixing them myself (pass " + str(tries) + "/3)...")
        except Exception:
            pass
        code = _pine_ask("This Pine script has these compile problems - FIX them and return ONLY the corrected "
                         "full script (keep the same strategy logic):\nPROBLEMS:\n- " + "\n- ".join(errs) + "\n\nSCRIPT:\n" + code)
        code = _pine_sanitize(code)
        errs = pine_lint(code) if code else errs
    used_template = False
    if errs or not code:
        code, used_template, errs = _pine_sanitize(fallback), True, []
    os.makedirs("/root/nemo_code", exist_ok=True)
    path = "/root/nemo_code/" + (re.sub(r"[^\w -]", "", (spec or "strategy"))[:36].strip().replace(" ", "_") or "strategy") + ".pine"
    with open(path, "w") as f:
        f.write(code)
    if used_template:
        note = ("⚠️ The generated version still tripped my checks, so here's a HAND-VERIFIED template (" + approach +
                ") - it compiles clean in TradingView. Tell me the exact tweak and I'll adapt it.")
    else:
        note = ("✅ Passed my Pine v6 checks (approach: " + approach + "): version header, one declaration, v6 "
                "namespaces, input.* types, balanced brackets, no plot/alert inside a block, and PURE ASCII.")
    note += ("\n\n\U0001F4CE IMPORTANT: open the attached .pine FILE and copy from THERE (or use the file directly). "
             "Do NOT copy the code out of this chat bubble - phones/Telegram silently turn straight quotes into "
             "“smart quotes” and spaces into non-breaking spaces, which is what causes TradingView's "
             "'Syntax error at input ...' on code that looks perfect. The file is clean ASCII and will compile.")
    deliver(chat_id, mid, note)
    _send_file(chat_id, path, "\U0001F4C8 " + os.path.basename(path))
    if email_to:
        try:
            body = "Your Pine Script is attached and pasted below.\n\n" + code
            if send_email(email_to, "Your Pine Script", body, path):
                send_text(chat_id, "\U0001F4E7 Emailed the script to " + email_to + ".")
            else:
                send_text(chat_id, "\U0001F4E7 Couldn't email it: " + (LAST_EMAIL_ERR or "unknown") + " - run /google to fix send permission.")
        except Exception:
            pass


_SCRATCHPAD_RE = re.compile(
    r"(?im)^\s*(let'?s craft|similarly for|here'?s the|here is the|i'?ll write|i will write|sure[,!:]|okay[,!:]|"
    r"make sure (not )?to|as (an|the) (assistant|ai)|note:|reasoning:|thinking:|first,? i|they said|"
    r"we should|so we|\.\.\. ?code ?\.\.\.|import \.\.\.|<code>|# ?your code here|# ?\.\.\.)")


def _looks_scratchpad(s):
    """Detect the brain 'thinking out loud' / placeholders leaking into a code or text file (the garbage class
    behind the old nemo_code_out.txt junk). True = don't ship it, retry."""
    if not s or len(s.strip()) < 15:
        return True
    return len(_SCRATCHPAD_RE.findall(s)) >= 2 or "... code ..." in s or "import ..." in s or "Similarly for" in s


def _clean_code(c):
    return re.sub(r"^```[a-zA-Z]*\n?|```$", "", (c or "").strip(), flags=re.M).strip()


def make_script(chat_id, spec):
    """Write a program in the requested language and DELIVER it as a file (doesn't run it — say 'run it' for that)."""
    if re.search(r"\bpine ?script|pinescript|tradingview\b", (spec or "").lower()):
        pine_generate(chat_id, spec)                 # v11.29: Pine gets the verified/linted path, not a raw brain dump
        return
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F4BE Writing your script: " + (spec or "")[:100] + " ...")
    mid = ph.get("result", {}).get("message_id")
    low = (spec or "").lower()
    ext = "py"
    for name, e in (("pine", "pine"), ("tradingview", "pine"),
                    ("javascript", "js"), ("node", "js"), ("typescript", "ts"), ("bash", "sh"), ("shell script", "sh"),
                    ("html", "html"), (" css", "css"), ("java ", "java"), ("c++", "cpp"), ("cpp", "cpp"),
                    ("c#", "cs"), ("golang", "go"), (" go ", "go"), ("rust", "rs"), ("php", "php"),
                    ("ruby", "rb"), (" sql", "sql"), ("python", "py")):
        if name in low:
            ext = e
            break
    _pin = (ext == "pine")
    code = ask_ai(chat_id, "Write a complete, well-commented, genuinely useful program/script for this request. "
                  + ("Use TradingView Pine Script v5: start with //@version=5, use indicator()/strategy(), inputs, "
                     "plots and alertcondition where sensible. " if _pin else "")
                  + "Reply with ONLY the raw code — no prose, no markdown fences.\n\nRequest: " + (spec or ""),
                  remember=False, deep=True, timeout=220, raw=True)
    code = _clean_code(code)
    if _looks_scratchpad(code):                     # v12.05: no more 'Let's craft:' / '... code ...' garbage files
        code = _clean_code(ask_ai(chat_id, "Output ONLY the complete, runnable code for the request below - no "
                          "commentary, no explanations, no placeholders like '... code ...' or '# your code here', "
                          "no markdown fences. Just the real code.\n\nRequest: " + (spec or ""),
                          remember=False, deep=True, timeout=220, raw=True))
    if not code or _looks_scratchpad(code):
        deliver(chat_id, mid, "I couldn't produce clean code for that - try describing exactly what the script should do.")
        return
    note = "✅ Script ready (." + ext + ")."
    if ext == "py":                                 # v12.05: guarantee delivered Python is at least syntactically valid
        try:
            import ast as _ast
            _ast.parse(code)
            note += " Syntax checked - it parses."
        except SyntaxError:
            fixed = _clean_code(ask_ai(chat_id, "This Python has a syntax error. Return ONLY the corrected, complete, "
                              "runnable code - no prose, no fences.\n\n" + code[:6000], remember=False, deep=True,
                              timeout=180, raw=True))
            try:
                import ast as _ast
                _ast.parse(fixed)
                code = fixed
                note += " Syntax checked (self-corrected)."
            except Exception:
                note += " (heads up: it may still have a syntax slip - say 'run it' and I'll fix it live.)"
    os.makedirs("/root/nemo_code", exist_ok=True)
    safe = (re.sub(r"[^\w -]", "", (spec or ""))[:40].strip().replace(" ", "_") or "script")
    path = "/root/nemo_code/" + safe + "." + ext
    with open(path, "w") as f:
        f.write(code)
    deliver(chat_id, mid, note + "\n\n\U0001F4CE Use the attached FILE (open/download it) - don't copy the code out of "
            "this chat, since phones/chat can turn quotes and spaces into characters that break the code. Say 'run "
            "it' to execute it here.")
    _send_file(chat_id, path, "\U0001F4BE " + os.path.basename(path))


def plan_task(chat_id, goal, run=False):
    """Break a goal into a clear numbered plan and show it (a visible mini task-list). Optionally hand it to the agent."""
    ph = tg("sendMessage", chat_id=chat_id, text="\U0001F5FA Planning: " + (goal or "")[:100] + " ...")
    mid = ph.get("result", {}).get("message_id")
    raw = ask_ai(chat_id, "Break this goal into a clear, ordered plan of concrete steps (5-10). Each step: a short "
                 "imperative title and one line on what it involves. Reply ONLY as JSON: "
                 '{"goal":"...","steps":[{"title":"...","detail":"..."}]}\n\nGoal: ' + (goal or ""),
                 remember=False, deep=True, timeout=180)
    try:
        j = json.loads(raw[raw.find("{"):raw.rfind("}") + 1])
        steps = j.get("steps") or []
    except Exception:
        steps = []
    if not steps:
        deliver(chat_id, mid, "I couldn't break that down — describe the goal a bit more.")
        return
    lines = []
    for i, s in enumerate(steps[:12], 1):
        t = str(s.get("title", "")).strip()
        d = str(s.get("detail", "")).strip()
        lines.append(str(i) + ". " + t + (("\n    ↳ " + d) if d else ""))
    plan = "\U0001F5FA PLAN — " + (goal or "")[:120] + "\n\n" + "\n".join(lines)
    deliver(chat_id, mid, plan + "\n\nSay 'do it' / 'run this plan' and I'll carry it out step by step.", buttons=True)
    LASTREPLY[chat_id] = plan
    try:
        kv_set("lastplan:" + str(chat_id), (goal or "")[:400])
    except Exception:
        pass
    if run:
        threading.Thread(target=agent_run, args=(chat_id, goal), daemon=True).start()


