def _curi_load_dark():
    if DARK.get("_loaded"):
        return
    DARK["_loaded"] = True
    try:
        v = kv_get("darkmode")
        if v is not None:
            DARK["on"] = (str(v) == "1")
    except Exception:
        pass


def dark_cmd(chat_id, args):
    """Toggle DARK MODE - a blunt, ruthless, no-filter TONE (still honest, never harmful)."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner only.")
        return
    _curi_load_dark()
    a = (args or "").strip().lower()
    if a in ("on", "start", "enable", "yes", ""):
        if a == "" and DARK.get("on"):
            DARK["on"] = False
            kv_set("darkmode", "0")
            send_text(chat_id, "\U0001F311 DARK MODE off. Back to the normal voice.")
            return
        DARK["on"] = True
        kv_set("darkmode", "1")
        send_text(chat_id, "\U0001F5A4 DARK MODE on. No more hand-holding — I'll give it to you straight and sharp, "
                  "built to put you ahead. (Still won't lie to you or help anything illegal.) /dark off to soften.")
    else:
        DARK["on"] = False
        kv_set("darkmode", "0")
        send_text(chat_id, "\U0001F311 DARK MODE off. Back to the normal voice.")


