def memory_search(chat_id, q):
    """v7.2 A2 - SECOND BRAIN: search everything Nemo knows about you and answer, connecting the dots."""
    bits = []
    for f in FACTS.get(chat_id, []):
        bits.append("fact: " + str(f))
    for k, v in (VAULT.get(chat_id, {}) or {}).items():
        bits.append("vault: " + k + " = " + str(v))
    for a in ARCHIVE.get(chat_id, []):
        bits.append("memory: " + str(a))
    lb = lib_search(q)
    if lb:
        bits.append("documents:\n" + lb)
    for pn, pj in (PROJECTS.get(chat_id, {}) or {}).items():
        bits.append("project: " + pn + " - " + "; ".join(s.get("text", "") for s in pj.get("steps", [])[:5]))
    for cn, cv in (CONTACTS.get(chat_id, {}) or {}).items():
        bits.append("contact: " + cn + " - " + str(cv.get("notes", "")) + (" bday " + cv["bday"] if cv.get("bday") else ""))
    try:
        for mm in mem_recall(q, k=6, minsim=0.5):
            bits.append("remembered: " + mm)
    except Exception:
        pass
    if not bits:
        return "I don't have anything in my memory about that yet. Tell me facts with /remember or /save, or send me documents."
    ctx = "\n".join(bits)[:9000]
    return ask_ai(chat_id, "From everything I know about Gautam below, answer his question - connect related pieces, "
                  "be specific, and if the answer isn't in here say so honestly.\n\nQuestion: " + q +
                  "\n\nWhat I know:\n" + ctx, remember=False, timeout=150)


def make_ppt(chat_id, topic):
    """v7.2 A6 - generate a real PowerPoint presentation."""
    send_text(chat_id, "\U0001F4CA Building your presentation on '" + topic[:80] + "'...")
    raw = ask_ai(chat_id, "Create a professional slide deck outline on: " + topic + "\nReply as JSON only:\n"
                 '{"title":"Deck Title","slides":[{"h":"Slide heading","points":["point 1","point 2","point 3"]}]}\n'
                 "6-9 slides, 3-5 crisp points each. Plain facts.", remember=False, deep=True, timeout=200)
    try:
        j0, j1 = raw.find("{"), raw.rfind("}")
        d = json.loads(raw[j0:j1 + 1])
    except Exception:
        send_text(chat_id, "Could not build the deck this time - try a more specific topic.")
        return
    try:
        from pptx import Presentation
        from pptx.util import Inches, Pt
        from pptx.dml.color import RGBColor
        prs = Presentation()
        s0 = prs.slides.add_slide(prs.slide_layouts[0])
        s0.shapes.title.text = _norm(d.get("title", topic))[:110]
        s0.placeholders[1].text = "Prepared by Nemo for Gautam"
        for sl in d.get("slides", [])[:12]:
            s = prs.slides.add_slide(prs.slide_layouts[1])
            s.shapes.title.text = _norm(sl.get("h", ""))[:90]
            tf = s.placeholders[1].text_frame
            tf.clear()
            pts = sl.get("points", []) or []
            for i, p in enumerate(pts[:6]):
                para = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
                para.text = _norm(str(p))[:200]
                para.font.size = Pt(18)
        path = "/tmp/deck.pptx"
        prs.save(path)
        send_document(chat_id, path, re.sub(r"[^A-Za-z0-9]+", "_", topic)[:40] + ".pptx",
                      "application/vnd.openxmlformats-officedocument.presentationml.presentation")
    except ImportError:
        send_text(chat_id, "Presentations need: pip3 install python-pptx --break-system-packages, then restart.")
    except Exception:
        traceback.print_exc()
        send_text(chat_id, "Something went wrong building the deck.")


