def compress_history(chat_id):
    """PHASE 1 - memory compression: old chat becomes a permanent dense summary, never lost."""
    if chat_id in COMPRESSING:
        return
    COMPRESSING.add(chat_id)
    try:
        with LOCK:
            old = list(HISTORY.get(chat_id, [])[:16])
        if len(old) < 16:
            return
        convo = "\n".join(("User: " if m.get("role") == "user" else "Nemo: ") + str(m.get("content", ""))[:400]
                          for m in old)
        summ = ask_ai(0, "Summarize this old conversation into 3-5 dense lines a personal assistant must "
                         "remember forever: the user's facts, decisions, preferences, plans and ongoing topics. "
                         "Plain text lines only.\n\n" + convo,
                      remember=False, models_override=FAST_MODELS, timeout=90)
        if summ and len(summ) > 30 and not summ.startswith("All free models"):
            with LOCK:
                h2 = HISTORY.get(chat_id, [])
                if len(h2) >= 16 and h2[:16] == old:
                    arc = ARCHIVE.setdefault(chat_id, [])
                    arc.append(time.strftime("%d %b %Y") + ": " + summ[:900])
                    del arc[:-24]
                    del h2[:16]
            save_data()
    except Exception:
        pass
    finally:
        COMPRESSING.discard(chat_id)


def nemo_call(text2):
    """PHASE 2 - real ringing Telegram voice call via CallMeBot (free personal API)."""
    u = CALLCFG.get("user")
    if not u:
        return False
    try:
        r = requests.get("http://api.callmebot.com/start.php",
                         params={"user": u, "text": (text2 or "Alert from Nemo")[:250], "rpt": 2},
                         timeout=45)
        return r.status_code == 200
    except Exception:
        return False


def ntfy_send(text2, title="NEMO ALERT", priority="urgent"):
    """v6.1 - instant push notification to the owner's phones via ntfy.sh (free, reliable).
    priority 'urgent' plays a loud repeated alarm on the phone, even bypassing silent on Android."""
    topic = CALLCFG.get("push_topic")
    if not topic:
        return False
    try:
        r = requests.post("https://ntfy.sh/" + topic,
                          data=(text2 or "")[:1500].encode("utf-8"),
                          headers={"Title": title, "Priority": priority, "Tags": "robot"},
                          timeout=30)
        return r.status_code == 200
    except Exception:
        return False


def textmebot_send(text2):
    """v8.1 - WhatsApp message via TextMeBot (api.textmebot.com). Uses YOUR own WhatsApp number and is
    far more reliable than CallMeBot. Configure with /wasetup <your-number> <apikey>."""
    ph, key = CALLCFG.get("tmb_phone"), CALLCFG.get("tmb_key")
    if not (ph and key):
        return False
    try:
        r = requests.get("https://api.textmebot.com/send.php",
                         params={"recipient": ph, "apikey": key, "text": (text2 or "")[:2000]}, timeout=45)
        return r.status_code == 200 and "error" not in r.text.lower()[:200]
    except Exception:
        return False


def callmebot_wa(text2):
    """Legacy fallback - WhatsApp via CallMeBot personal API (often overloaded)."""
    ph, key = CALLCFG.get("wa_phone"), CALLCFG.get("wa_key")
    if not (ph and key):
        return False
    try:
        r = requests.get("https://api.callmebot.com/whatsapp.php",
                         params={"phone": ph, "text": (text2 or "")[:900], "apikey": key}, timeout=45)
        return r.status_code == 200
    except Exception:
        return False


def wa_send(text2):
    """Send a WhatsApp message to the owner - TextMeBot first (reliable), CallMeBot as fallback."""
    return textmebot_send(text2) or callmebot_wa(text2)


def wa_send_to(number, text2):
    """v8.2 - send a WhatsApp message to ANYONE (any number), from the owner's own linked WhatsApp via
    TextMeBot. Returns True on success. The owner's TextMeBot key must be set (/wasetup)."""
    key = CALLCFG.get("tmb_key")
    num = re.sub(r"[^\d+]", "", str(number or ""))
    if not num.startswith("+"):
        num = "+" + num.lstrip("+")
    if not (key and len(num) >= 8):
        return False
    try:
        r = requests.get("https://api.textmebot.com/send.php",
                         params={"recipient": num, "apikey": key, "text": (text2 or "")[:2000]}, timeout=45)
        return r.status_code == 200 and "error" not in r.text.lower()[:200]
    except Exception:
        return False


def wa_resolve(chat_id, who):
    """Turn a name or raw number into a phone number: check the owner's saved contacts first."""
    who = (who or "").strip()
    if re.fullmatch(r"\+?\d[\d ]{7,}", who):
        return re.sub(r"[^\d+]", "", who)
    cs = CONTACTS.get(chat_id, {}) or {}
    for nm, c in cs.items():
        if nm.lower() == who.lower() and c.get("phone"):
            return re.sub(r"[^\d+]", "", c["phone"])
    for nm, c in cs.items():
        if who.lower() in nm.lower() and c.get("phone"):
            return re.sub(r"[^\d+]", "", c["phone"])
    return None


def phone_cmd(macro, params=None):
    """PHASE 5 - fire a MacroDroid webhook on the owner's phone."""
    did = CALLCFG.get("phone_id")
    if not did:
        return False
    try:
        r = requests.get("https://trigger.macrodroid.com/" + did + "/" + macro,
                         params=params or {}, timeout=45)
        return r.status_code == 200
    except Exception:
        return False


def strip_html(html2):
    html2 = re.sub(r"(?is)<(script|style|noscript)[^>]*>.*?</\1>", " ", html2 or "")
    txt = re.sub(r"(?s)<[^>]+>", " ", html2)
    return re.sub(r"\s+", " ", txt).strip()


def check_watches():
    """PHASE 3 - website watcher: alert when a watched page really changes."""
    import difflib
    dirty = False
    for w in list(WATCHES):
        try:
            r = requests.get(w["url"], headers={"User-Agent": "Mozilla/5.0 (Nemo personal watcher)"}, timeout=45)
            txt = strip_html(r.text)[:20000]
            if not txt:
                continue
            old = w.get("text", "")
            if old:
                ratio = difflib.SequenceMatcher(None, old, txt).ratio()
                if ratio < 0.985:
                    note = ("\U0001F440 WEBSITE CHANGED\n" + w["url"] +
                            f"\n\nAbout {max(1, round((1 - ratio) * 100))}% of the page is different since my last check.")
                    ai = ask_ai(0, "Old page text:\n" + old[:3000] + "\n\nNew page text:\n" + txt[:3000] +
                                "\n\nIn 2-3 short plain lines: what changed that a person would care about?",
                                remember=False, models_override=FAST_MODELS, timeout=90)
                    if ai and not ai.startswith("All free models"):
                        note += "\nWhat changed: " + ai[:500]
                    send_text(w["chat"], note)
            w["text"] = txt
            w["fails"] = 0
            dirty = True
        except Exception:
            w["fails"] = w.get("fails", 0) + 1
            if w["fails"] == 5:
                send_text(w["chat"], "⚠️ I could not open " + w["url"] + " five checks in a row - still trying every 30 min.")
    if dirty:
        save_data()


def check_news():
    """PHASE 3 - news radar: alert only when something genuinely big happens on a followed topic."""
    for cid, topics in list(FOLLOWS.items()):
        for topic in list(topics)[:6]:
            try:
                rs = web_search("latest news " + topic)
                if not rs:
                    continue
                heads = [r2.get("title", "") for r2 in rs[:5] if r2.get("title")]
                seen = SEENNEWS.setdefault(topic, [])
                fresh = [h2 for h2 in heads if h2 not in seen]
                if not fresh:
                    continue
                v = ask_ai(0, "The user follows this topic: " + topic + "\nFresh headlines:\n" +
                           "\n".join("- " + h2 for h2 in fresh) +
                           "\n\nIs any of these genuinely BIG, important news (not routine updates)? "
                           "Reply exactly NONE, or the single most important headline followed by | and one "
                           "line on why it matters.",
                           remember=False, models_override=FAST_MODELS, timeout=90)
                seen.extend(fresh)
                del seen[:-40]
                if v and not v.strip().upper().startswith("NONE"):
                    hl, _, why = v.partition("|")
                    link = next((r2.get("href", "") for r2 in rs
                                 if hl.strip()[:40] in r2.get("title", "") or r2.get("title", "")[:40] in hl), "")
                    send_text(cid, "\U0001F4E1 NEWS RADAR - " + topic.upper() + "\n\n" + hl.strip()[:220] +
                              (("\n" + why.strip()[:300]) if why.strip() else "") + (("\n" + link) if link else ""))
            except Exception:
                pass
    save_data()


def parse_when(day, tim):
    """PHASE 6 - parse 'today 17:00' / 'tomorrow 5pm' / 'sunday 10am' / '25/08 14:30' into a timestamp."""
    try:
        now = time.time()
        ist = time.gmtime(now + IST_OFFSET)
        midnight = now - (ist.tm_hour * 3600 + ist.tm_min * 60 + ist.tm_sec)
        day, tim = day.lower().strip(), tim.lower().strip()
        wd3 = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
        off = None
        if day in ("today", "aaj"):
            off = 0
        elif day in ("tomorrow", "kal"):
            off = 1
        elif day[:3] in wd3:
            off = (wd3.index(day[:3]) - ist.tm_wday) % 7 or 7
        elif re.match(r"^\d{1,2}/\d{1,2}$", day):
            dd, mm2 = map(int, day.split("/"))
            yr = ist.tm_year + (1 if (mm2, dd) < (ist.tm_mon, ist.tm_mday) else 0)
            import calendar as _cal
            utc_mid = _cal.timegm((yr, mm2, dd, 0, 0, 0))
            midnight, off = utc_mid - IST_OFFSET, 0
        if off is None:
            return None
        m = re.match(r"^(\d{1,2})(?::(\d{2}))?\s*(am|pm)?$", tim)
        if not m:
            return None
        hh, mm3, ap = int(m.group(1)), int(m.group(2) or 0), m.group(3)
        if ap == "pm" and hh < 12:
            hh += 12
        if ap == "am" and hh == 12:
            hh = 0
        ts = midnight + off * 86400 + hh * 3600 + mm3 * 60
        if ts <= now and off == 0 and not re.match(r"^\d{1,2}/\d{1,2}$", day):
            ts += 86400
        return ts if ts > now else None
    except Exception:
        return None


