def _wf_parse(text):
    """v13.4: parse a numbered / bulleted / arrow list into workflow steps (inline or multi-line)."""
    text = (text or "").strip()
    if not text:
        return []
    text = re.sub(r"\s+(\d+[\).:\-])\s*", r"\n\1 ", text)   # break an inline '1. a 2. b' onto lines
    parts = []
    for line in text.splitlines():
        line = line.strip()
        m = re.match(r"^(?:\d+[\).:\-]|[-*•])\s*(.+)$", line)
        parts.append(m.group(1).strip() if m else line)
    parts = [p for p in parts if p]
    if len(parts) <= 1 and text:
        parts = [x.strip() for x in re.split(r"\s*->\s*|\s*;\s*", text) if x.strip()]
    return parts[:20]


def _wf_run(chat_id, wid):
    """v13.4: run a workflow one step at a time, persisting progress after each so it survives a crash/restart."""
    wf = WORKFLOWS.get(wid)
    if not wf:
        return
    wf["status"] = "running"
    save_data()
    steps = wf.get("steps", [])
    try:
        while wf.get("current", 0) < len(steps):
            i = wf["current"]
            step = steps[i]
            prior = "".join("Step " + str(r["step"]) + ": " + str(r["result"])[:600] + "\n"
                            for r in wf.get("results", []))[-3000:]
            ans = ask_ai(chat_id,
                         "You are executing step " + str(i + 1) + " of a " + str(len(steps)) + "-step plan. Do ONLY "
                         "this step and return a concrete, usable result. NEVER claim you performed an external action "
                         "(sending email, placing an order, saving a file) unless a real Nemo tool actually did it.\n\n"
                         + (("Results so far:\n" + prior + "\n") if prior else "") +
                         "STEP " + str(i + 1) + ": " + step,
                         remember=False, deep=True, timeout=240) or ""
            if not ans.strip():
                raise RuntimeError("step produced no result")
            wf.setdefault("results", []).append({"step": i + 1, "task": step, "result": ans[:5000]})
            wf["current"] = i + 1
            save_data()
            send_text(chat_id, "✅ Step " + str(i + 1) + "/" + str(len(steps)) + ": " + step[:70] + "\n" + ans[:1400])
        wf["status"] = "done"
        save_data()
        send_text(chat_id, "\U0001F9E9 Workflow " + wid + " COMPLETE (" + str(len(steps)) + " steps). Review: /nemoworkflows")
    except Exception as e:
        wf["status"] = "failed"
        wf["error"] = str(e)[:300]
        save_data()
        send_text(chat_id, "⚠️ Workflow " + wid + " stopped at step " + str(wf.get("current", 0) + 1) + ": " +
                  str(e)[:200] + "\nContinue after fixing: /nemoresume " + wid)


def nemoworkflow_cmd(chat_id, text):
    """/nemoworkflow <numbered plan> - run a multi-step plan, one checkpointed step at a time."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner only.")
        return
    steps = _wf_parse(text)
    if not steps:
        send_text(chat_id, "Give me a numbered plan, e.g.\n/nemoworkflow 1. research NIFTY option strategies "
                  "2. compare the top 3  3. write the best one as a Pine script")
        return
    if len(WORKFLOWS) > 30:   # keep the store bounded
        for old in sorted(WORKFLOWS, key=lambda k: WORKFLOWS[k].get("created", 0))[:len(WORKFLOWS) - 30]:
            WORKFLOWS.pop(old, None)
    wid = "wf" + time.strftime("%m%d%H%M%S")
    WORKFLOWS[wid] = {"id": wid, "chat": chat_id, "steps": steps, "results": [],
                      "status": "queued", "current": 0, "created": time.time()}
    save_data()
    send_text(chat_id, "\U0001F9E9 Workflow " + wid + " queued - " + str(len(steps)) + " steps. Working through them now...")
    threading.Thread(target=_wf_run, args=(chat_id, wid), daemon=True).start()


