# ==================== v13.9 QUANT LENSES (regime / walk-forward / Monte-Carlo) - READ-ONLY, no orders ============
# Ported from the ChatGPT v19 quant file, rebuilt on our base: no uuid dependency, uses Nemo's real data helpers
# (get_history / _ema_series / rsi14), and adds the genuinely-new lenses we lacked. It NEVER places an order.
def _q_num(x, d=0.0):
    try:
        if x is None or x == "":
            return d
        return float(x)
    except Exception:
        return d


def _q_atr_series(h, l, c, p=14):
    n = min(len(h), len(l), len(c))
    if n < p + 1:
        return []
    tr = [max(h[i] - l[i], abs(h[i] - c[i - 1]), abs(l[i] - c[i - 1])) for i in range(1, n)]
    return [sum(tr[i - p + 1:i + 1]) / p for i in range(p - 1, len(tr))]


def _q_adx(h, l, c, p=14):
    n = min(len(h), len(l), len(c))
    if n < p * 2 + 1:
        return None
    trs = []; plus = []; minus = []
    for i in range(1, n):
        up = h[i] - h[i - 1]; dn = l[i - 1] - l[i]
        trs.append(max(h[i] - l[i], abs(h[i] - c[i - 1]), abs(l[i] - c[i - 1])))
        plus.append(up if up > dn and up > 0 else 0.0)
        minus.append(dn if dn > up and dn > 0 else 0.0)
    atr = sum(trs[:p]) / p; ap = sum(plus[:p]) / p; am = sum(minus[:p]) / p
    dx = []
    for i in range(p, len(trs)):
        atr = (atr * (p - 1) + trs[i]) / p; ap = (ap * (p - 1) + plus[i]) / p; am = (am * (p - 1) + minus[i]) / p
        pi = 100 * ap / atr if atr else 0; mi = 100 * am / atr if atr else 0
        dx.append(100 * abs(pi - mi) / (pi + mi) if pi + mi else 0)
    return sum(dx[-p:]) / p if len(dx) >= p else None


def _q_macd(c, fast=12, slow=26, signal=9):
    if len(c) < slow + signal:
        return None
    ef = _ema_series(c, fast); es = _ema_series(c, slow)
    mac = [a - b for a, b in zip(ef, es)]
    sg = _ema_series(mac, signal)
    return mac[-1], sg[-1], mac[-1] - sg[-1]


def _q_mc(values, sims=2000):
    """Monte-Carlo bootstrap of trade returns - terminal + drawdown percentiles (the empirical distribution)."""
    vals = [float(x) for x in values if isinstance(x, (int, float)) and x == x]
    if len(vals) < 10:
        return None
    import random
    sims = max(500, min(int(sims), 8000))
    terminal = []; maxdds = []
    for _ in range(sims):
        eq = 0.0; peak = 0.0; dd = 0.0
        for _j in range(len(vals)):
            eq += random.choice(vals); peak = max(peak, eq); dd = max(dd, peak - eq)
        terminal.append(eq); maxdds.append(dd)
    terminal.sort(); maxdds.sort()
    qf = lambda a, p: a[min(len(a) - 1, max(0, int(p * (len(a) - 1))))]
    return {"sims": sims, "p5": round(qf(terminal, .05), 2), "p50": round(qf(terminal, .50), 2),
            "p95": round(qf(terminal, .95), 2), "dd_p50": round(qf(maxdds, .50), 2), "dd_p95": round(qf(maxdds, .95), 2)}


def quant_regime(sym):
    """Classify the market regime (trend / range / expansion / low-vol) from ADX + EMAs + ATR-ratio + slope."""
    h = get_history(sym)
    if not h or len(h.get("closes", [])) < 60:
        return {"symbol": sym, "regime": "UNKNOWN", "confidence": 0, "reason": "insufficient history"}
    c = [_q_num(x) for x in h["closes"] if x is not None]
    hi = [_q_num(x) for x in h["highs"] if x is not None]
    lo = [_q_num(x) for x in h["lows"] if x is not None]
    n = min(len(c), len(hi), len(lo)); c = c[-n:]; hi = hi[-n:]; lo = lo[-n:]
    e20 = _ema_series(c, 20)[-1]; e50 = _ema_series(c, 50)[-1]
    atrs = _q_atr_series(hi, lo, c, 14); atr = atrs[-1] if atrs else 0
    adx = _q_adx(hi, lo, c, 14) or 0
    vol20 = sum(atrs[-20:]) / min(20, len(atrs)) if atrs else 0
    atr_ratio = atr / vol20 if vol20 else 1
    slope = (c[-1] - c[-21]) / c[-21] * 100 if len(c) > 21 and c[-21] else 0
    rsi = rsi14(c) or 50
    if atr_ratio > 1.35 and abs(slope) > 2.0:
        reg = "EXPANSION_UP" if slope > 0 else "EXPANSION_DOWN"
    elif adx >= 25 and e20 > e50 and slope > 1:
        reg = "TREND_UP"
    elif adx >= 25 and e20 < e50 and slope < -1:
        reg = "TREND_DOWN"
    elif atr_ratio < 0.80 and adx < 20:
        reg = "LOW_VOL_RANGE"
    elif adx < 20:
        reg = "RANGE"
    else:
        reg = "TRANSITION"
    conf = min(95, max(25, 45 + abs(adx - 20) * 1.4 + min(abs(slope) * 5, 20)))
    return {"symbol": h.get("name", sym), "regime": reg, "confidence": round(conf, 1), "price": c[-1],
            "ema20": e20, "ema50": e50, "rsi": rsi, "adx": adx, "atr": atr, "atr_ratio": atr_ratio, "slope_pct": slope}


def quant_signal(sym):
    """Transparent multi-factor score (EMA/RSI/MACD/ADX). A score, not a promise."""
    h = get_history(sym)
    if not h or len(h.get("closes", [])) < 60:
        return None
    c = [_q_num(x) for x in h["closes"] if x is not None]
    hi = [_q_num(x) for x in h["highs"] if x is not None]
    lo = [_q_num(x) for x in h["lows"] if x is not None]
    n = min(len(c), len(hi), len(lo)); c = c[-n:]; hi = hi[-n:]; lo = lo[-n:]
    e20 = _ema_series(c, 20)[-1]; e50 = _ema_series(c, 50)[-1]
    rsi = rsi14(c) or 50; mac = _q_macd(c)
    adx = _q_adx(hi, lo, c, 14) or 0
    atrs = _q_atr_series(hi, lo, c, 14); atr = atrs[-1] if atrs else 0
    score = 0; reasons = []
    if c[-1] > e20: score += 1; reasons.append("price>EMA20")
    else: score -= 1; reasons.append("price<EMA20")
    if e20 > e50: score += 2; reasons.append("EMA20>EMA50")
    else: score -= 2; reasons.append("EMA20<EMA50")
    if rsi >= 55: score += 1; reasons.append("RSI bullish")
    elif rsi <= 45: score -= 1; reasons.append("RSI bearish")
    if mac:
        if mac[2] > 0: score += 1; reasons.append("MACD+")
        elif mac[2] < 0: score -= 1; reasons.append("MACD-")
    if adx >= 25:
        score += 1 if e20 > e50 else -1; reasons.append("ADX strong")
    label = ("STRONG_BULL" if score >= 5 else "BULL" if score >= 2 else "NEUTRAL" if score > -2
             else "BEAR" if score > -5 else "STRONG_BEAR")
    return {"symbol": h.get("name", sym), "score": score, "max_score": 7, "label": label, "price": c[-1],
            "ema20": e20, "ema50": e50, "rsi": rsi, "adx": adx, "atr": atr, "reasons": reasons}


def quant_quality(sig, regime=""):
    if not sig:
        return None
    base = 50 + sig["score"] * 6
    if regime in ("TREND_UP", "TREND_DOWN"): base += 8
    if regime in ("RANGE", "LOW_VOL_RANGE") and abs(sig["score"]) >= 5: base -= 8
    base = max(0, min(100, round(base)))
    grade = "A+" if base >= 90 else "A" if base >= 80 else "B" if base >= 70 else "C" if base >= 60 else "D"
    return {"score": base, "grade": grade}


def quant_backtest(sym, fast=20, slow=50):
    h = get_history(sym)
    if not h:
        return None
    c = [_q_num(x) for x in h["closes"] if x is not None]
    if len(c) < max(slow + 20, 80):
        return None
    trades = []; position = 0; entry = 0.0
    for i in range(slow, len(c)):
        ef = sum(c[i - fast + 1:i + 1]) / fast; es = sum(c[i - slow + 1:i + 1]) / slow
        efp = sum(c[i - fast:i]) / fast; esp = sum(c[i - slow:i]) / slow
        if position == 0 and ef > es and efp <= esp:
            position = 1; entry = c[i]
        elif position == 0 and ef < es and efp >= esp:
            position = -1; entry = c[i]
        elif position == 1 and ef < es:
            trades.append((c[i] - entry) / entry * 100); position = 0
        elif position == -1 and ef > es:
            trades.append((entry - c[i]) / entry * 100); position = 0
    if position:
        trades.append((c[-1] - entry) / entry * 100 * position)
    if not trades:
        return {"symbol": h.get("name", sym), "trades": 0}
    wins = [x for x in trades if x > 0]; losses = [x for x in trades if x <= 0]
    grossw = sum(wins); grossl = -sum(losses)
    eq = 0; peak = 0; mdd = 0
    for x in trades:
        eq += x; peak = max(peak, eq); mdd = max(mdd, peak - eq)
    return {"symbol": h.get("name", sym), "trades": len(trades), "winrate": round(len(wins) / len(trades) * 100, 1),
            "net_pct": round(sum(trades), 2), "avg_trade": round(sum(trades) / len(trades), 2),
            "profit_factor": round(grossw / grossl, 2) if grossl else None, "maxdd_pct": round(mdd, 2),
            "best_pct": round(max(trades), 2), "worst_pct": round(min(trades), 2), "mc": _q_mc(trades, 2000)}


def quant_walkforward(sym):
    """Rolling out-of-sample check: pick the best EMA pair on a training window, score it on the next (unseen) one."""
    h = get_history(sym)
    if not h or len(h.get("closes", [])) < 120:
        return None
    c = [_q_num(x) for x in h["closes"] if x is not None]
    segments = []
    step = max(20, (len(c) - 80) // 3)
    for s in (40, 40 + step, 40 + 2 * step):
        if s + 40 >= len(c):
            continue
        train = c[:s]; test = c[s:s + 40]; best = None
        for f in (10, 20, 30):
            for sl in (40, 50, 60):
                if len(train) < sl + 5:
                    continue
                hits = tot = 0
                for i in range(sl, len(train) - 1):
                    a = sum(train[i - f + 1:i + 1]) / f; b = sum(train[i - sl + 1:i + 1]) / sl
                    hits += (1 if a > b else -1) == (1 if train[i + 1] > train[i] else -1); tot += 1
                sc = hits / tot if tot else 0
                if best is None or sc > best[0]:
                    best = (sc, f, sl)
        if not best:
            continue
        f, sl = best[1], best[2]; hits = tot = 0
        for i in range(sl, len(test)):
            a = sum(test[i - f + 1:i + 1]) / f; b = sum(test[i - sl + 1:i + 1]) / sl
            hits += (1 if a > b else -1) == (1 if test[i] > test[i - 1] else -1); tot += 1
        segments.append({"train_hit": round(best[0] * 100, 1), "fast": f, "slow": sl,
                         "test_hit": round(hits / tot * 100, 1) if tot else 0})
    if not segments:
        return None
    return {"segments": segments, "avg_oos_hit": round(sum(x["test_hit"] for x in segments) / len(segments), 1)}


