def memory_forget(chat_id, query):
    """v13.8 MEMORY 3.0: forget SPECIFIC memories matching a query (vs /forgetme which wipes EVERYTHING). Removes
    from the durable facts AND the semantic vector store, and reports exactly what it dropped."""
    q = (query or "").strip()
    if not q:
        send_text(chat_id, "Usage: /forget <what to forget>  -  e.g. /forget my old phone number.\n"
                  "(To wipe EVERYTHING I know about you, use /forgetme.)")
        return
    ql = q.lower()
    removed = []
    with LOCK:
        fl = FACTS.get(chat_id, [])
        keep = []
        for f in fl:
            if ql in f.lower():
                removed.append(f[:120])
            else:
                keep.append(f)
        FACTS[chat_id] = keep
    try:
        hits = set(mem_recall(query, k=8, minsim=0.78))   # also catch close semantic matches
    except Exception:
        hits = set()
    with LOCK:
        newvec = []
        for m in MEMVEC:
            t = m.get("t", "")
            if ql in t.lower() or t in hits:
                removed.append(t[:120])
            else:
                newvec.append(m)
        MEMVEC[:] = newvec
    try:
        save_data()
    except Exception:
        pass
    try:
        _mem_save()
    except Exception:
        pass
    if removed:
        uniq = list(dict.fromkeys(removed))[:12]
        send_text(chat_id, "\U0001F9F9 Forgotten (" + str(len(removed)) + " item(s)):\n- " + "\n- ".join(uniq))
    else:
        send_text(chat_id, "I didn't find a memory matching \"" + q + "\" - nothing removed. "
                  "(See what I remember: /aboutme or /profile.)")


def _unknown_command(chat_id, text):
    """v13.8: an unrecognised /command gets an HONEST reply with REAL commands - never routed to the chat brain,
    which used to invent plausible-but-fake command names."""
    cmd = (text.split() or [text])[0][:32]
    send_text(chat_id, "I don't recognise " + cmd + ", and I never make up commands. Real ones you can use:\n\n"
              "/nemo - control center  ·  /verify - fact-check  ·  /abilities - the full list\n"
              "/pine - Pine script  ·  /pdf <topic>  ·  /web <question>  ·  /img <description>\n"
              "/remember <fact>  ·  /recall <q>  ·  /memory <q>  ·  /forget <q>\n"
              "/order  ·  /security  ·  /updatecheck  ·  /nemoworkflow <steps>\n\n"
              "Or just tell me in plain words what you want - you don't need a command at all.")


def self_test():
    """PHASE 1 - weekly drill: he tests his own systems and sends a PASS/FAIL report card."""
    res = []

    def check(name, fn):
        try:
            ok = bool(fn())
        except Exception:
            ok = False
        res.append(("✅" if ok else "❌") + " " + name)
        return ok

    check("Main brain (Nemotron)", lambda: (lambda r: r and "busy" not in r[:40].lower())(
        ask_ai(0, "Reply with exactly: OK", remember=False, models_override=FAST_MODELS, timeout=90)))
    if GROQ_KEY:
        check("Backup brain (Groq)", lambda: groq_chat([{"role": "user", "content": "Say OK"}]))
    if GEMINI_KEY:
        check("Backup brain (Gemini)", lambda: gemini_chat([{"role": "user", "content": "Say OK"}]))
    check("Web search", lambda: web_search("india news today"))
    check("Market data (quote)", lambda: get_quote("RELIANCE"))
    check("Market history + technicals", lambda: get_history("RELIANCE"))
    if google_ready() or (BOT_EMAIL and BOT_EMAIL_PASS):
        # v12.06: test the REAL email paths. Email sending works over the Gmail API (HTTPS) - DigitalOcean BLOCKS
        # the SMTP/IMAP ports, so the old raw-port login test always failed even though email was fine. Now: Gmail
        # API first (the path actually used), SMTP/IMAP only as a fallback when there's no Google connection.
        def _send_ok():
            if google_ready() and google_token():
                prof = google_get("https://gmail.googleapis.com/gmail/v1/users/me/profile")
                if isinstance(prof, dict) and prof.get("emailAddress"):
                    return True
            if BOT_EMAIL and BOT_EMAIL_PASS:
                import smtplib
                s = smtplib.SMTP_SSL("smtp.gmail.com", 465, timeout=30)
                s.login(BOT_EMAIL, BOT_EMAIL_PASS)
                s.quit()
                return True
            return False
        check("Email sending (Gmail API / SMTP)", _send_ok)

        def _read_ok():
            if google_ready() and google_token():
                r = google_get("https://gmail.googleapis.com/gmail/v1/users/me/labels")
                if isinstance(r, dict) and r.get("labels") is not None:
                    return True
            if BOT_EMAIL and BOT_EMAIL_PASS:
                import imaplib
                M = imaplib.IMAP4_SSL("imap.gmail.com")
                M.login(BOT_EMAIL, BOT_EMAIL_PASS)
                M.logout()
                return True
            return False
        check("Email reading (Gmail API / IMAP)", _read_ok)
    def _pdft():
        from fpdf import FPDF
        p = FPDF()
        p.add_page()
        p.set_font("Helvetica", size=12)
        p.cell(0, 10, "self test")
        p.output("/tmp/selftest.pdf")
        return os.path.getsize("/tmp/selftest.pdf") > 300
    check("PDF engine", _pdft)
    def _voicet():
        from gtts import gTTS
        gTTS("test").save("/tmp/selftest.mp3")
        return os.path.getsize("/tmp/selftest.mp3") > 1000
    check("Voice engine (TTS)", _voicet)
    check("Image engine (with fallback)", lambda: fetch_image("simple blue circle icon on white", "/tmp/selftest.jpg"))
    check("Disk space > 5 GB free", lambda: shutil.disk_usage("/").free > 5e9)
    check("Memory file healthy", lambda: os.path.getsize(DATA_FILE) > 10 if os.path.exists(DATA_FILE) else True)
    check("No API keys exposed in source", lambda: not secrets_status()["in_source"])
    passed = sum(1 for r in res if r.startswith("✅"))
    report = ("\U0001F9EA WEEKLY SELF-TEST REPORT CARD\n" +
              f"Score: {passed}/{len(res)} systems passing\n\n" + "\n".join(res) +
              "\n\nI run this drill every Sunday evening. If anything fails two weeks in a row, tell Claude to fix me.")
    if OWNER.get("id"):
        send_text(OWNER["id"], report)
    send_email(OWNER_EMAIL, f"Nemo self-test: {passed}/{len(res)} passing", report)


# ==================== v10.7 SCANNER - a photo becomes a clean PDF / extracted text / decoded QR ====================
LAST_PHOTO = {}   # chat_id -> last image b64, so /scandoc /ocr /qr can act on the most recent photo


def _four_point_transform(cv2, np, image, pts):
    rect = np.zeros((4, 2), dtype="float32")
    s = pts.sum(axis=1); rect[0] = pts[np.argmin(s)]; rect[2] = pts[np.argmax(s)]
    d = np.diff(pts, axis=1); rect[1] = pts[np.argmin(d)]; rect[3] = pts[np.argmax(d)]
    (tl, tr, br, bl) = rect
    maxW = int(max(np.linalg.norm(br - bl), np.linalg.norm(tr - tl)))
    maxH = int(max(np.linalg.norm(tr - br), np.linalg.norm(tl - bl)))
    dst = np.array([[0, 0], [maxW - 1, 0], [maxW - 1, maxH - 1], [0, maxH - 1]], dtype="float32")
    M = cv2.getPerspectiveTransform(rect, dst)
    return cv2.warpPerspective(image, M, (max(maxW, 1), max(maxH, 1)))


def _scan_to_pdf(img_path, out_pdf):
    """Detect the document in a photo, crop + straighten it (perspective), clean it, and save as PDF. Falls back
    to a grayscale-enhance if no clean document edge is found - so it always produces something usable."""
    try:
        from PIL import Image, ImageOps
    except Exception:
        auto_install("PIL", notify=False)
        from PIL import Image, ImageOps
    cv2 = _imp("cv2", notify=False)
    np = _imp("numpy", notify=False)
    scanned = None
    if cv2 and np:
        try:
            image = cv2.imread(img_path)
            if image is not None and image.shape[0] > 10:
                ratio = image.shape[0] / 500.0
                orig = image.copy()
                small = cv2.resize(image, (max(int(image.shape[1] / ratio), 1), 500))
                gray = cv2.GaussianBlur(cv2.cvtColor(small, cv2.COLOR_BGR2GRAY), (5, 5), 0)
                edged = cv2.Canny(gray, 60, 200)
                cnts, _h = cv2.findContours(edged.copy(), cv2.RETR_LIST, cv2.CHAIN_APPROX_SIMPLE)
                cnts = sorted(cnts, key=cv2.contourArea, reverse=True)[:5]
                area = small.shape[0] * small.shape[1]
                doc = None
                for c in cnts:
                    approx = cv2.approxPolyDP(c, 0.02 * cv2.arcLength(c, True), True)
                    if len(approx) == 4 and cv2.contourArea(c) > 0.25 * area:
                        doc = approx.reshape(4, 2).astype("float32") * ratio
                        break
                warped = _four_point_transform(cv2, np, orig, doc) if doc is not None else orig
                g = cv2.cvtColor(warped, cv2.COLOR_BGR2GRAY)
                th = cv2.adaptiveThreshold(g, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C, cv2.THRESH_BINARY, 21, 12)
                cv2.imwrite("/tmp/nemo_scan.png", th)
                scanned = "/tmp/nemo_scan.png"
        except Exception:
            scanned = None
    if not scanned:
        try:
            ImageOps.autocontrast(Image.open(img_path).convert("L")).save("/tmp/nemo_scan.png")
            scanned = "/tmp/nemo_scan.png"
        except Exception:
            scanned = img_path
    try:
        Image.open(scanned).convert("RGB").save(out_pdf, "PDF", resolution=150.0)
        return os.path.exists(out_pdf) and os.path.getsize(out_pdf) > 500
    except Exception:
        return False


def _scan_qr(img_path):
    cv2 = _imp("cv2", notify=False)
    if not cv2:
        return None
    try:
        data, _pts, _ = cv2.QRCodeDetector().detectAndDecode(cv2.imread(img_path))
        return data or None
    except Exception:
        return None


def scan_document(chat_id, b64, mode="pdf"):
    """Turn a photo into a clean scanned PDF (mode='pdf'), pull its text (mode='ocr'), or read a QR (mode='qr')."""
    import base64 as _b64
    try:
        raw = _b64.b64decode(b64)
    except Exception:
        send_text(chat_id, "I couldn't read that image.")
        return
    inp = "/tmp/nemo_scan_in.jpg"
    try:
        open(inp, "wb").write(raw)
    except Exception:
        pass
    if mode == "ocr":
        send_text(chat_id, "\U0001F524 Reading the text...")
        txt = ask_ai(chat_id, "You are an OCR engine. Extract ALL text from this image EXACTLY as written, keeping "
                     "line breaks and layout. Include Hindi/Devanagari text if present. Output ONLY the text.",
                     image_b64=b64, remember=False, timeout=150)
        send_text(chat_id, "\U0001F524 Text:\n\n" + (txt or "(no readable text)")[:3800])
        return
    if mode == "qr":
        if not _imp("cv2", notify=False):
            send_text(chat_id, "\U0001F527 Setting up the code reader (first time)...")
            auto_install("cv2", notify=False)
        data = _scan_qr(inp)
        if not data:
            data = ask_ai(chat_id, "If this image has a QR code or barcode, output ONLY the decoded text/URL. "
                          "If none, output NONE.", image_b64=b64, remember=False, timeout=90)
            data = None if (not data or data.strip().upper() == "NONE") else data.strip()
        send_text(chat_id, ("\U0001F533 Code content:\n" + data) if data else "I couldn't find a QR/barcode in that image.")
        return
    if not (_imp("cv2", notify=False) and _imp("numpy", notify=False)):
        send_text(chat_id, "\U0001F5A8️ Setting up the scanner (first time - a moment)...")
        auto_install("cv2", notify=False)
        auto_install("numpy", notify=False)
    send_text(chat_id, "\U0001F5A8️ Scanning the document...")
    out = "/tmp/nemo_scanned.pdf"
    if _scan_to_pdf(inp, out):
        try:
            with open(out, "rb") as f:
                requests.post(TG + "/sendDocument", data={"chat_id": chat_id, "caption": "\U0001F4C4 Scanned document"},
                              files={"document": ("scan.pdf", f, "application/pdf")}, timeout=120)
        except Exception:
            send_text(chat_id, "Scanned it but couldn't send the PDF.")
        send_text(chat_id, "Want the text out of it too? Send /ocr, or resend the photo with caption 'ocr'.")
    else:
        send_text(chat_id, "I couldn't turn that into a clean scan - try a brighter photo with the whole document "
                  "flat and fully in frame.")


def scan_bill(chat_id, b64):
    """PHASE 4 - read a bill/receipt photo and auto-log it into the money tracker."""
    send_text(chat_id, "\U0001F9FE Reading the bill...")
    raw = ask_ai(chat_id, "This is a photo of a bill or receipt. Extract and reply with ONLY one line of JSON, "
                          'nothing else: {"amount": <grand total, number only>, "shop": "<merchant name>", '
                          '"date": "<date on bill or unknown>"}',
                 image_b64=b64, remember=False, timeout=150)
    amt, shop, bdate = None, "shop", "today"
    try:
        j0, j1 = raw.find("{"), raw.rfind("}")
        d = json.loads(raw[j0:j1 + 1])
        amt = float(str(d.get("amount", "")).replace(",", "").replace("Rs", "").replace("₹", "").strip())
        shop = str(d.get("shop", "shop"))[:60]
        bdate = str(d.get("date", "today"))[:20]
    except Exception:
        amt = None
    if not amt or amt <= 0:
        send_text(chat_id, "I could not read a clear total from that photo. Try a closer, straighter photo - "
                           "or log it manually: /spent 250 groceries")
        return
    today = time.strftime("%Y-%m-%d", time.gmtime(time.time() + IST_OFFSET))
    month = today[:7]
    with LOCK:
        SPENT.setdefault(chat_id, {}).setdefault(month, []).append({"amt": amt, "what": shop, "date": today})
        mtot = sum(x["amt"] for x in SPENT[chat_id][month])
    save_data()
    send_text(chat_id, f"\U0001F9FE Bill read: Rs.{amt:,.0f} at {shop} ({bdate})\n"
                       f"\U0001F4B8 Logged automatically. This month so far: Rs.{mtot:,.0f}\n"
                       "/spent report shows the full month.")


