            # v7.2 A4 - birthday reminders from the CRM (8:05am)
            if ist.tm_hour == 8 and ist.tm_min < 5 and SELFTEST.get("bday") != today:
                SELFTEST["bday"] = today
                dm = f"{ist.tm_mday:02d}/{ist.tm_mon:02d}"
                for cid, cs in list(CONTACTS.items()):
                    for nm, c in cs.items():
                        b = (c.get("bday") or "").replace("-", "/")
