            if ist.tm_hour == 21 and 3 <= ist.tm_min < 6 and SELFTEST.get("agenda") != today:
                SELFTEST["agenda"] = today
                midn = now - (ist.tm_hour * 3600 + ist.tm_min * 60 + ist.tm_sec)
