def _nemo_icon_png(size=512):
    if size in _ICON_CACHE:
        return _ICON_CACHE[size]
    data = b""
    try:
        from PIL import Image, ImageDraw, ImageFont
        import io as _io
        img = Image.new("RGB", (size, size), (11, 15, 23))
        d = ImageDraw.Draw(img)
        d.rounded_rectangle([size * 0.08, size * 0.08, size * 0.92, size * 0.92],
                            radius=int(size * 0.2), fill=(20, 36, 54))
        try:
            f = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", int(size * 0.56))
        except Exception:
            f = ImageFont.load_default()
        d.text((size / 2, size / 2 - size * 0.03), "N", font=f, fill=(43, 108, 255), anchor="mm")
        b = _io.BytesIO()
        img.save(b, "PNG")
        data = b.getvalue()
    except Exception:
        import base64 as _b
        data = _b.b64decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk"
                            "+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==")
    _ICON_CACHE[size] = data
    return data


# ══════════════════ v11.17 DEPTH: smarter reasoning · knowledge base · watchdog · dashboard ══════════════════
def _is_hard(q):
    """Heuristic: is this worth reasoning harder about (not a quick fact / chit-chat)?"""
    ql = (q or "").lower()
    if len(q or "") > 220 or len((q or "").split()) >= 22 or ql.count("?") >= 2:
        return True
    return bool(re.search(r"\b(why|how (do|does|can|should|would|to)|should i|compare|versus|vs\b|trade-?off|"
                          r"pros and cons|analy[sz]e|evaluate|strateg|plan (for|out)|design|explain (how|why)|"
                          r"best way|step by step|decide|decision|implication|reason|worth it|which (is|one))", ql))


# ---- KNOWLEDGE BASE: full-text index over the user's own files (no embeddings needed) ----
_KB = {"init": False, "fts": True}
_KB_EXT = (".txt", ".md", ".csv", ".tsv", ".json", ".log", ".py", ".js", ".html", ".htm", ".xml", ".yaml",
           ".yml", ".ini", ".conf", ".cfg", ".sql", ".srt", ".env", ".rst")


def _kb_init():
    if _KB["init"]:
        return
    try:
        _exec("CREATE VIRTUAL TABLE IF NOT EXISTS knowledge USING fts5(path, chunk)")
        _KB["fts"] = True
    except Exception:
        try:
            _exec("CREATE TABLE IF NOT EXISTS knowledge(path TEXT, chunk TEXT)")
        except Exception:
            pass
        _KB["fts"] = False
    _KB["init"] = True


def _kb_read(fp):
    low = fp.lower()
    try:
        if low.endswith(".pdf"):
            from pypdf import PdfReader
            return "\n".join((p.extract_text() or "") for p in PdfReader(fp).pages)[:200000]
        return open(fp, "r", errors="replace").read()[:200000]
    except Exception:
        return ""


def kb_index(chat_id, path):
    """Index a file or a whole folder of the user's files into the full-text knowledge base."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner only.")
        return
    _kb_init()
    path = _fs_path(path or "/root")
    targets = []
    if os.path.isfile(path):
        targets = [path]
    elif os.path.isdir(path):
        for root, _d, fs in os.walk(path):
            if any(x in root for x in ("/.", "/nemo_backups", "__pycache__", "/node_modules")):
                continue
            for f in fs:
                if f.lower().endswith(_KB_EXT) or f.lower().endswith(".pdf"):
                    targets.append(os.path.join(root, f))
            if len(targets) >= 500:
                break
    else:
        send_text(chat_id, "No such path: " + path)
        return
    send_text(chat_id, "\U0001F4DA Indexing " + str(len(targets)) + " files from " + path + " ...")
    files = chunks = 0
    for fp in targets[:500]:
        try:
            txt = _kb_read(fp)
            if not txt or not txt.strip():
                continue
            _exec("DELETE FROM knowledge WHERE path=?", (fp,))
            for i in range(0, len(txt), 1500):
                _exec("INSERT INTO knowledge(path, chunk) VALUES(?,?)", (fp, txt[i:i + 1500]))
                chunks += 1
            files += 1
            if chunks > 12000:
                break
        except Exception:
            continue
    v11_audit("kb_index", path + " (" + str(files) + " files)")
    send_text(chat_id, "✅ Indexed " + str(files) + " files (" + str(chunks) + " chunks).\n"
              "Now ask:  /know <question>  or just say 'search my files for ...'.")


def kb_search(query, k=6):
    _kb_init()
    try:
        if _KB["fts"]:
            m = " OR ".join(re.findall(r"[A-Za-z0-9]{2,}", query)[:12]) or (query or "")[:60]
            return _q("SELECT path, chunk FROM knowledge WHERE knowledge MATCH ? LIMIT ?", (m, k)) or []
        toks = re.findall(r"[A-Za-z0-9]{3,}", query or "")
        like = "%" + (toks[0] if toks else (query or "")[:20]) + "%"
        return _q("SELECT path, chunk FROM knowledge WHERE chunk LIKE ? LIMIT ?", (like, k)) or []
    except Exception:
        return []


def kb_answer(chat_id, query):
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner only.")
        return
    rows = kb_search(query, 6)
    if not rows:
        send_text(chat_id, "Nothing in your knowledge base matches that yet.\nIndex some files first, e.g. "
                  "/index /root  or  /index /root/apps.")
        return
    ctx = "\n\n".join("[" + os.path.basename(r["path"]) + "]\n" + (r["chunk"] or "") for r in rows)[:9000]
    ans = ask_ai(chat_id, "Answer the question using ONLY these excerpts from the user's own files. Be precise and "
                 "cite the file name(s) you used. If the excerpts don't contain the answer, say so plainly.\n\n"
                 "QUESTION: " + query + "\n\nEXCERPTS:\n" + ctx, remember=False, timeout=90)
    srcs = sorted(set(os.path.basename(r["path"]) for r in rows))[:6]
    convo_note(chat_id, "searched my files for: " + query[:60])
    LASTREPLY[chat_id] = ans or ""
    deliver(chat_id, None, "\U0001F4DA " + (ans or "(no answer)") + "\n\n\U0001F4C4 From: " + ", ".join(srcs), buttons=True)


# ---- SELF-RUNNING WATCHDOG: auto-restart deployed apps whose service has CRASHED ----
def apps_watchdog():
    """Auto-recover: restart any deployed app whose systemd unit has FAILED (crashed) — notify + audit.
    Only touches 'failed' units, never 'inactive' (a deliberate stop), and rate-limits per app."""
    oid = OWNER.get("id")
    try:
        names = [d for d in os.listdir(APPS_DIR) if os.path.isdir(app_dir(d))] if os.path.isdir(APPS_DIR) else []
    except Exception:
        return
    for n in names:
        try:
            st = (app_ctl(n, "is-active") or "").strip().lower()
        except Exception:
            continue
        if "fail" in st and _chief_ok("wd_" + n, 1800):
            try:
                app_ctl(n, "restart")
            except Exception:
                pass
            v11_audit("watchdog_restart", n)
            act_log("watchdog", "restarted crashed app " + n)
            if oid:
                send_text(oid, "\U0001F6E1 Watchdog: app '" + n + "' had crashed — I restarted it automatically.")


# ---- COMMAND-CENTER DASHBOARD (served by the web server; the power made visible) ----
def _dash_apps():
    try:
        names = [d for d in os.listdir(APPS_DIR) if os.path.isdir(app_dir(d))] if os.path.isdir(APPS_DIR) else []
        return [{"name": n, "status": (app_ctl(n, "is-active") or "?").strip()[:16]} for n in names[:12]]
    except Exception:
        return []


def _dash_data():
    now = time.time()
    oid = OWNER.get("id")
    try:
        acts = [{"kind": a.get("kind", ""), "detail": str(a.get("detail", ""))[:90],
                 "ago": int((now - a.get("ts", now)) / 60)} for a in list(ACTLOG)[-14:]][::-1]
    except Exception:
        acts = []
    todos = [t.get("text", "")[:80] for t in TODOS.get(oid, []) if not t.get("done")][:8] if oid else []
    try:
        rem = sorted([r for r in REMINDERS if r.get("chat") == oid], key=lambda r: r["at"])[:5] if oid else []
        reminders = [{"text": str(r.get("text", ""))[:70], "in_min": max(0, int((r["at"] - now) / 60))} for r in rem]
    except Exception:
        reminders = []
    ms = HEALTH.get("ms", []) or []
    return {"version": VERSION, "brain": "down" if HEALTH.get("down") else "ok",
            "resp_ms": int(sum(ms) / len(ms)) if ms else 0, "answers": HEALTH.get("ok", 0),
            "disk": _disk_pct(), "mem": _mem_pct(), "acts": acts, "todos": todos,
            "reminders": reminders, "apps": _dash_apps()}


