def gh_review(chat_id, n, repo=None, post=False):
    repo = _gh_repo(repo)
    if not repo:
        send_text(chat_id, "Set a repo first: /gh repo owner/name")
        return
    diff, err = _gh("GET", "/repos/" + repo + "/pulls/" + str(n), raw=True)
