# ==================== v10.5 SELF-DEFENSE (blue-team, THIS SERVER ONLY) ====================
# Defensive security scoped ENTIRELY to Nemo's own host: detect tampering/viruses/rootkits/intruders, see what
# he exposes to the internet, audit his own packages for known CVEs, and harden himself. By design there is NO
# target field anywhere - every check runs against this server, so it can never be pointed at anyone else.
# Owner-only + capability-gated + audited. This is armour and alarms, not weapons.
# bot_secrets.json is deliberately NOT tripwired: it changes legitimately every time a key/cap/config is saved,
# so it would false-alarm constantly (alert fatigue). It's protected by file perms (chmod 600 via /harden).
# The tripwire watches files that should NEVER silently change - his own code, SSH keys, accounts, cron.
SEC_CRIT_FILES = [SELF_PATH, "/root/.ssh/authorized_keys", "/etc/passwd", "/etc/crontab"]
SECCFG = {"tripwire": False, "autolock": False}
try:
    _sc0 = _sec_get("seccfg")
    if isinstance(_sc0, dict):
        SECCFG.update(_sc0)
except Exception:
    pass


def _sha(path):
    import hashlib
    try:
        h = hashlib.sha256()
        with open(path, "rb") as f:
            for b in iter(lambda: f.read(65536), b""):
                h.update(b)
        return h.hexdigest()
    except Exception:
        return None


def sec_tripwire_baseline():
    """Record SHA-256 of Nemo's critical files, so any later tampering (a virus, an intruder editing his code
    or SSH keys) is detected."""
    SECCFG["tripwire"] = True
    save_secret("seccfg", SECCFG)          # persist FIRST, so no watched file is written AFTER we fingerprint it
    base = {}
    for p in SEC_CRIT_FILES:
        s = _sha(p)
        if s:
            base[p] = s
    kv_set("tripwire_base", json.dumps(base))
    return base


def sec_tripwire_check():
    try:
        base = json.loads(kv_get("tripwire_base") or "{}")
    except Exception:
        base = {}
    changed, missing = [], []
    for p, old in base.items():
        now = _sha(p)
        if now is None:
            missing.append(p)
        elif now != old:
            changed.append(p)
    return changed, missing


def sec_monitor():
    """Background guard: periodically re-check the tripwire; alert (and optionally auto-lockdown) on tampering."""
    while True:
        try:
            time.sleep(1200)
            if not SECCFG.get("tripwire"):
                continue
            changed, missing = sec_tripwire_check()
            if changed or missing:
                mlog("ERROR", "tripwire", "changed=" + ",".join(os.path.basename(x) for x in changed) +
                     " missing=" + ",".join(os.path.basename(x) for x in missing))
                msg = "\U0001F6E1️ TAMPER ALERT - a protected file changed on your server:\n"
                if changed:
                    msg += "Modified: " + ", ".join(changed) + "\n"
                if missing:
                    msg += "Missing: " + ", ".join(missing) + "\n"
                if SECCFG.get("autolock"):
                    kv_set("lockdown", "1")
                    msg += "I engaged /lockdown automatically as a precaution. Review it, then /unlock."
                else:
                    msg += "If that wasn't you, send /lockdown now."
                try:
                    send_text(OWNER.get("id"), msg)
                except Exception:
                    pass
                sec_tripwire_baseline()      # re-baseline so you're not re-alerted every cycle for the same change
        except Exception:
            pass


def sec_intruders(paths=None):
    """Who's been trying to break into the server: failed SSH logins by source IP, from auth logs."""
    import collections
    fails = collections.Counter()
    users = collections.Counter()
    total = 0
    for lg in (paths or ("/var/log/auth.log", "/var/log/auth.log.1", "/var/log/secure")):
        try:
            with open(lg, "r", errors="ignore") as f:
                for line in f:
                    if "Failed password" in line or "Invalid user" in line or "authentication failure" in line:
                        total += 1
                        mip = re.search(r"from (\d+\.\d+\.\d+\.\d+)", line)
                        if mip:
                            fails[mip.group(1)] += 1
                        mu = re.search(r"(?:Invalid user|for)\s+(\w+)", line)
                        if mu:
                            users[mu.group(1)] += 1
        except Exception:
            continue
    return total, fails.most_common(8), users.most_common(6)


def sec_intruders_report():
    total, top, users = sec_intruders()
    if total == 0:
        return "\U0001F6E1️ No failed-login / brute-force attempts found in the logs. Quiet so far."
    out = ["\U0001F6A8 " + str(total) + " failed login attempts on your server.", "Top source IPs:"]
    out += ["  " + ip + " — " + str(n) + " tries" for ip, n in top]
    if users:
        out.append("Usernames they tried: " + ", ".join(u + "(" + str(n) + ")" for u, n in users))
    out.append("Block the worst with:  /harden firewall CONFIRM  (enables fail2ban + ufw).")
    return "\n".join(out)


def sec_exposure(raw=None):
    """What this server exposes to the internet: listening TCP ports on public (0.0.0.0) vs local addresses."""
    try:
        if raw is None:
            r = subprocess.run(["ss", "-tlnp"], capture_output=True, text=True, timeout=15)
            raw = r.stdout or ""
        lines = [l for l in raw.splitlines()[1:] if l.strip()]
    except Exception:
        return None, None
    pub, loc = [], []
    for l in lines:
        parts = l.split()
        if len(parts) < 4:
            continue
        addr, _, port = parts[3].rpartition(":")
        proc = ""
        mp = re.search(r'\("([^"]+)"', l)
        if mp:
            proc = mp.group(1)
        entry = port + (" (" + proc + ")" if proc else "")
        bucket = pub if addr in ("0.0.0.0", "*", "[::]", "::") else loc
        if entry not in bucket:          # collapse duplicate IPv4/IPv6 listeners on the same port
            bucket.append(entry)
    return pub, loc


def sec_exposure_report():
    pub, loc = sec_exposure()
    if pub is None:
        return "Couldn't read listening ports (ss unavailable)."
    out = ["\U0001F310 What your server exposes to the internet (public):"]
    out += ["  • port " + p for p in (pub or [])] or ["  (nothing public - good)"]
    out.append("Local-only (safe): " + (", ".join(loc) if loc else "none"))
    out.append("Every public port is a door - close any you don't need. SSH (22) + the gateway (8088) are expected.")
    return "\n".join(out)


def sec_scan_virus(chat_id):
    """ClamAV antivirus scan of this server's key folders (installs ClamAV on first use)."""
    def _has(x):
        return subprocess.run(["which", x], capture_output=True).returncode == 0
    env = dict(os.environ, DEBIAN_FRONTEND="noninteractive")
    if not _has("clamscan"):
        send_text(chat_id, "\U0001F4E6 Installing ClamAV antivirus (first time - a minute or two)...")
        try:
            subprocess.run(["apt-get", "install", "-y", "clamav"], capture_output=True, timeout=300, env=env)
            subprocess.run(["freshclam"], capture_output=True, timeout=600)
        except Exception:
            pass
    if not _has("clamscan"):
        return "Couldn't install ClamAV automatically. Run: apt-get install -y clamav && freshclam"
    send_text(chat_id, "\U0001F9EA Scanning /root, /home, /tmp for malware...")
    try:
        r = subprocess.run(["clamscan", "-r", "-i", "--no-summary", "/root", "/home", "/tmp"],
                           capture_output=True, text=True, timeout=1200)
        infected = [l for l in (r.stdout or "").splitlines() if "FOUND" in l]
        return ("\U0001F9A0 Malware FOUND:\n" + "\n".join(infected[:30]) + "\n\nSend /lockdown and I'll help you "
                "quarantine.") if infected else "✅ ClamAV scan complete - no malware found on your server."
    except subprocess.TimeoutExpired:
        return "The virus scan timed out (large filesystem). I can scan a single folder if you name one."
    except Exception as e:
        return "Scan error: " + type(e).__name__ + " " + str(e)[:150]


def sec_audit_deps(chat_id):
    """Check Nemo's own installed Python packages for known CVEs (pip-audit)."""
    env = dict(os.environ, DEBIAN_FRONTEND="noninteractive")
    try:
        subprocess.run(["python3", "-m", "pip", "install", "--break-system-packages", "--quiet", "pip-audit"],
                       capture_output=True, timeout=180, env=env)
        r = subprocess.run(["python3", "-m", "pip_audit", "-f", "columns"], capture_output=True, text=True, timeout=300)
        out = (r.stdout or "") + (r.stderr or "")
        if "No known vulnerabilities" in out or (r.returncode == 0 and "Name" not in out):
            return "✅ No known CVEs in your installed Python packages."
        return "\U0001F50E Package vulnerability audit:\n" + out[-3000:]
    except Exception as e:
        return "Couldn't run the CVE audit: " + str(e)[:150] + "\n(try: pip install --break-system-packages pip-audit)"


def sec_harden(chat_id, do_firewall=False):
    """Harden THIS server. Safe steps run always; the firewall (which could lock you out) needs explicit CONFIRM
    and always keeps SSH (22) + the gateway (8088) open."""
    env = dict(os.environ, DEBIAN_FRONTEND="noninteractive")
    steps = []
    for p in ("/root/bot_secrets.json", NEMO_DB):
        try:
            if os.path.exists(p):
                os.chmod(p, 0o600)
                steps.append("locked file permissions on " + os.path.basename(p))
        except Exception:
            pass
    try:
        if subprocess.run(["which", "fail2ban-server"], capture_output=True).returncode != 0:
            subprocess.run(["apt-get", "install", "-y", "fail2ban"], capture_output=True, timeout=300, env=env)
        subprocess.run(["systemctl", "enable", "--now", "fail2ban"], capture_output=True, timeout=60)
        steps.append("fail2ban active (auto-bans brute-forcers)")
    except Exception:
        steps.append("couldn't set up fail2ban (install manually: apt install fail2ban)")
    if do_firewall:
        try:
            if subprocess.run(["which", "ufw"], capture_output=True).returncode != 0:
                subprocess.run(["apt-get", "install", "-y", "ufw"], capture_output=True, timeout=300, env=env)
            for c in (["ufw", "default", "deny", "incoming"], ["ufw", "default", "allow", "outgoing"],
                      ["ufw", "allow", "22/tcp"], ["ufw", "allow", "80/tcp"], ["ufw", "allow", "443/tcp"],
                      ["ufw", "allow", "8088/tcp"], ["ufw", "--force", "enable"]):
                subprocess.run(c, capture_output=True, timeout=30)
            steps.append("firewall ON: SSH(22) + web(80/443) + gateway(8088) open, everything else blocked "
                         "(if you need other ports like 8080/8090, tell me and I'll allow them)")
        except Exception:
            steps.append("firewall step failed - left unchanged for safety")
    else:
        steps.append("firewall NOT changed - run '/harden firewall CONFIRM' to enable it (keeps SSH open)")
    audit("owner", "harden", "firewall=" + str(do_firewall))
    return "\U0001F6E1️ Hardening done:\n- " + "\n- ".join(steps)


def sec_full(chat_id):
    """One-shot self-defense sweep of this server."""
    parts = []
    ch, mi = sec_tripwire_check()
    if kv_get("tripwire_base"):
        parts.append("Integrity: " + ("⚠️ CHANGED " + ",".join(os.path.basename(x) for x in ch + mi)
                     if (ch or mi) else "✅ untouched"))
    else:
        parts.append("Integrity: tripwire not set (turn on with /tripwire on)")
    pub, _ = sec_exposure()
    parts.append("Exposed ports: " + (", ".join(pub) if pub else "none public"))
    total, top, _ = sec_intruders()
    parts.append("Break-in attempts: " + (str(total) + " (worst: " + top[0][0] + ")" if total and top else str(total)))
    return "\U0001F6E1️ SELF-DEFENSE SWEEP (this server):\n- " + "\n- ".join(parts) + \
           "\n\nDeeper: /scanvirus (malware) · /audit (package CVEs) · /exposure · /intruders · /harden"


def sec_status():
    tw = "ON" if SECCFG.get("tripwire") else "off"
    al = "ON" if SECCFG.get("autolock") else "off"
    pub, _ = sec_exposure()
    total, _, _ = sec_intruders()
    return ("\U0001F6E1️ DEFENSE STATUS (this server only)\n"
            "Tripwire (tamper-detect): " + tw + "  ·  auto-lockdown: " + al + "\n"
            "Public ports: " + str(len(pub or [])) + "  ·  failed-login attempts logged: " + str(total) + "\n"
            "Commands: /scan (sweep) · /scanvirus · /audit · /exposure · /intruders · /tripwire on|check · /harden\n"
            "All of this targets ONLY this server - it can't be pointed anywhere else.")


def _sec_dispatch(chat_id, text, msg):
    """Self-defense commands. Owner-only. Returns True if handled."""
    try:
        low = (text or "").strip().lower()
        if not low.startswith(("/defend", "/secure", "/scan", "/scanvirus", "/tripwire", "/intruders",
                               "/exposure", "/audit", "/harden")):
            return False
        if chat_id != OWNER.get("id"):
            send_text(chat_id, "Owner-only.")
            return True
        arg = text.split(None, 1)[1].strip() if len(text.split(None, 1)) > 1 else ""
        lowarg = arg.lower()
        if low.startswith(("/defend", "/secure")):
            send_text(chat_id, sec_status())
        elif low.startswith("/scanvirus"):
            threading.Thread(target=lambda: send_text(chat_id, sec_scan_virus(chat_id)), daemon=True).start()
        elif low.startswith("/scan"):
            threading.Thread(target=lambda: send_text(chat_id, sec_full(chat_id)), daemon=True).start()
        elif low.startswith("/tripwire"):
            if lowarg.startswith("on"):
                sec_tripwire_baseline()
                send_text(chat_id, "\U0001F6E1️ Tripwire ON - I've fingerprinted your critical files (my code, secrets, "
                          "SSH keys, /etc/passwd). I'll alert you if any are tampered with. /tripwire autolock on to "
                          "also auto-/lockdown on tamper.")
            elif lowarg.startswith("check"):
                ch, mi = sec_tripwire_check()
                send_text(chat_id, ("⚠️ Changed: " + ", ".join(ch + mi)) if (ch or mi) else
                          "✅ All protected files are untouched." if kv_get("tripwire_base") else
                          "Tripwire isn't set yet - /tripwire on.")
            elif lowarg.startswith("autolock"):
                SECCFG["autolock"] = not lowarg.endswith("off")
                save_secret("seccfg", SECCFG)
                send_text(chat_id, "Auto-lockdown on tamper: " + ("ON" if SECCFG["autolock"] else "off"))
            elif lowarg.startswith("off"):
                SECCFG["tripwire"] = False
                save_secret("seccfg", SECCFG)
                send_text(chat_id, "Tripwire off.")
            else:
                send_text(chat_id, "Usage: /tripwire on | check | autolock on|off | off")
        elif low.startswith("/intruders"):
            threading.Thread(target=lambda: send_text(chat_id, sec_intruders_report()), daemon=True).start()
        elif low.startswith("/exposure"):
            threading.Thread(target=lambda: send_text(chat_id, sec_exposure_report()), daemon=True).start()
        elif low.startswith("/audit"):
            threading.Thread(target=lambda: send_text(chat_id, sec_audit_deps(chat_id)), daemon=True).start()
        elif low.startswith("/harden"):
            fw = ("firewall" in lowarg and "confirm" in lowarg)
            if "firewall" in lowarg and not fw:
                send_text(chat_id, "⚠️ Enabling the firewall could lock you out if misconfigured. I keep SSH(22) + "
                          "gateway(8088) open. To proceed:  /harden firewall CONFIRM")
                return True
            threading.Thread(target=lambda: send_text(chat_id, sec_harden(chat_id, do_firewall=fw)), daemon=True).start()
        return True
    except Exception as e:
        try:
            send_text(chat_id, "Defense command error: " + str(e)[:200])
        except Exception:
            pass
        return True


# ============================ APP FACTORY (v10.11) - hands to SHIP a service ============================
# Nemo takes a program (one he writes, or a .py you send him) and actually RUNS it on this server as a
# managed systemd service: write the file -> install its pip deps -> compile-check -> create the service ->
# start it. End to end. Owner-only, gated by the 'deploy' capability + /lockdown, and every START waits for
# your tap. Apps live under /root/apps/<name>; it refuses to touch protected/system units.
APPS_DIR = "/root/apps"
PENDSHIP = {}                                  # token -> pending service to start
LAST_CODE = {}                                 # chat_id -> {"name","code"} : last .py you sent, ready to /ship
_PROTECTED_UNITS = {"nemobot", "nemo", "ssh", "sshd", "systemd", "networkd", "cron", "crond", "dbus",
                    "nginx", "caddy", "docker", "fail2ban", "ufw"}


def _svc_ok(name):
    name = (name or "").strip().lower().replace(".service", "")
    if not re.match(r"^[a-z][a-z0-9_-]{2,30}$", name):
        return None
    if name in _PROTECTED_UNITS or name.startswith("systemd"):
        return None
    return name


def app_dir(name):
    return os.path.join(APPS_DIR, name)


def _mask(v):
    v = str(v)
    return (v[:3] + "…" + v[-2:]) if len(v) > 7 else "***"


def _app_env(name):
    try:
        return json.loads(kv_get("appenv:" + name, "{}")) or {}
    except Exception:
        return {}


def _app_env_path(name):
    return os.path.join(app_dir(name), ".env")


def _write_env_file(name, env):
    """Write the app's secrets to a chmod-600 .env file (kept OUT of the unit + journal). Returns path or ''."""
    if not env:
        return ""
    try:
        os.makedirs(app_dir(name), exist_ok=True)
        p = _app_env_path(name)
        open(p, "w", encoding="utf-8").write("".join(str(k) + "=" + str(v) + "\n" for k, v in env.items()))
        try:
            os.chmod(p, 0o600)
        except Exception:
            pass
        return p
    except Exception:
        return ""


def _systemd_unit(name, entry, env_file, workdir):
    lines = ["[Unit]", "Description=Nemo app: " + name, "After=network-online.target", "",
             "[Service]", "Type=simple", "WorkingDirectory=" + workdir]
    if env_file:
        lines.append("EnvironmentFile=-" + env_file)     # '-' = optional; secrets stay in the 600 file
    lines += ["ExecStart=/usr/bin/python3 " + os.path.join(workdir, entry),
              "Restart=always", "RestartSec=5", "User=root", "",
              "[Install]", "WantedBy=multi-user.target", ""]
    return "\n".join(lines)


def app_write_code(name, code, entry="main.py"):
    """Write the program under /root/apps/<name>/, compile-check it. Returns (path, "") or (None, error)."""
    try:
        d = app_dir(name)
        os.makedirs(d, exist_ok=True)
        path = os.path.join(d, entry)
        open(path, "w", encoding="utf-8").write(code)
    except Exception as e:
        return None, "write failed: " + str(e)[:200]
    if entry.endswith(".py"):
        ok, err = _compile_check(code)
        if not ok:
            return None, err
    return path, ""


def _systemctl(*args, **kw):
    try:
        r = subprocess.run(["systemctl", *args], capture_output=True, text=True, timeout=kw.get("timeout", 60))
        return r.returncode, (r.stdout or "") + (r.stderr or "")
    except Exception as e:
        return 1, type(e).__name__ + " " + str(e)[:150]


def app_start_service(name, entry, env_file, workdir):
    try:
        open("/etc/systemd/system/" + name + ".service", "w", encoding="utf-8").write(
            _systemd_unit(name, entry, env_file, workdir))
    except Exception as e:
        return False, "couldn't write unit file: " + str(e)[:200]
    _systemctl("daemon-reload")
    _systemctl("enable", name)
    rc, out = _systemctl("restart", name, timeout=45)
    return rc == 0, out


def app_ctl(name, action):
    if action not in ("start", "stop", "restart", "status", "is-active"):
        return "actions: status | start | stop | restart | logs | rm"
    rc, out = _systemctl(action, name, timeout=40)
    return out.strip()[:1500] or ("(" + action + " done)")


def app_logs(name, n=25):
    try:
        r = subprocess.run(["journalctl", "-u", name, "--no-pager", "-n", str(n)],
                           capture_output=True, text=True, timeout=30)
        return (r.stdout or r.stderr or "no logs yet")[-2500:]
    except Exception as e:
        return "log error " + str(e)[:120]


def app_remove(chat_id, name):
    _systemctl("stop", name)
    _systemctl("disable", name)
    try:
        os.remove("/etc/systemd/system/" + name + ".service")
    except Exception:
        pass
    _systemctl("daemon-reload")
    try:
        import shutil
        shutil.rmtree(app_dir(name))
    except Exception:
        pass
    audit("owner", "app.remove", name)
    send_text(chat_id, "\U0001F5D1 Removed '" + name + "' - service stopped & disabled, unit + files deleted.")


def app_list():
    try:
        names = [d for d in os.listdir(APPS_DIR) if os.path.isdir(app_dir(d))] if os.path.isdir(APPS_DIR) else []
    except Exception:
        names = []
    if not names:
        return ("No apps deployed yet.\nSend me a .py file then /ship <name>, or /build <name>: <what it does>. "
                "(First enable the power once with /caps deploy on.)")
    out = ["\U0001F4E6 Deployed apps:"]
    for n in names:
        out.append("• " + n + " — " + app_ctl(n, "is-active"))
    out.append("\nManage: /app <name> status|logs|restart|stop|rm")
    return "\n".join(out)


def deploy_app(chat_id, name, code, reqs=None, entry="main.py", env=None):
    """Write -> deps -> compile-check -> PROPOSE the service (tap to start). Supervised, owner + deploy-cap gated."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner-only.")
        return
    if not cap_ok("deploy"):
        send_text(chat_id, "\U0001F512 The DEPLOY power is off (or /lockdown is on). Turn it on once with "
                  "/caps deploy on, then try again. This is the switch that lets me put new services on your server.")
        return
    sname = _svc_ok(name)
    if not sname:
        send_text(chat_id, "Pick a simple service name (lowercase letters/digits/-/_, 3-31 chars, not a system "
                  "name). e.g.  /ship signalbot")
        return
    code = _clean_code(code) if "```" in (code or "") else (code or "")
    if len(code) < 40 or ("def " not in code and "import " not in code):
        send_text(chat_id, "That doesn't look like a runnable program. Send me the .py file as an attachment, "
                  "then /ship " + sname + " - or /build " + sname + ": <what it should do>.")
        return
    send_text(chat_id, "\U0001F6E0 Shipping '" + sname + "' - writing the file, installing its packages, and "
              "safety-compiling it...")
    path, err = app_write_code(sname, code, entry)
    if not path:
        send_text(chat_id, "It FAILED my compile-check, so I did NOT deploy it (nothing is running):\n" +
                  (err or "")[:500])
        return
    if reqs is None:
        reqs = _parse_reqs(code)
    dep_line = ""
    if reqs:
        ok, msg = _pip_install(reqs)
        dep_line = ("\n✓ Installed: " + ", ".join(reqs)) if ok else ("\n⚠ Some packages may be missing (" +
                    ", ".join(reqs) + ")")
    env = env if env is not None else _app_env(sname)          # secrets you set with /env <name> K=V
    env_file = _write_env_file(sname, env)
    env_line = ("\n✓ " + str(len(env)) + " env var(s) baked in: " + ", ".join(env.keys())) if env else ""
    import secrets as _s2
    tok = _s2.token_hex(4)
    PENDSHIP[tok] = {"name": sname, "entry": entry, "env_file": env_file, "workdir": app_dir(sname), "at": time.time()}
    preview = _systemd_unit(sname, entry, env_file, app_dir(sname))
    kb = {"inline_keyboard": [[{"text": "\U0001F680 Ship & start", "callback_data": "shipok:" + tok},
                               {"text": "❌ Cancel", "callback_data": "shipno:" + tok}]]}
    tg("sendMessage", chat_id=chat_id,
       text=("✓ Wrote " + path + "\n✓ Passed compile-check" + dep_line + env_line +
             "\n\nI'll run it as this service:\n" + preview[:1100] +
             "\n\nStart it now? It'll keep running, auto-restart on crash, and come back on reboot.\n"
             "After: /app " + sname + " logs (watch it) · /app " + sname + " stop · /app " + sname + " rm"),
       reply_markup=kb)


def apply_ship(chat_id, sh):
    ok, out = app_start_service(sh["name"], sh["entry"], sh.get("env_file", ""), sh["workdir"])
    audit("owner", "app.ship", sh["name"], "ok" if ok else "fail")
    if ok:
        send_text(chat_id, "✅ '" + sh["name"] + "' is LIVE - running now, auto-restart on, starts on boot.")
        time.sleep(2)
        send_text(chat_id, "\U0001F4CB First logs:\n" + app_logs(sh["name"], 15))
    else:
        send_text(chat_id, "It didn't start cleanly:\n" + (out or "")[:600] + "\nSee /app " + sh["name"] + " logs.")


def _build_and_ship(chat_id, name, desc):
    if not cap_ok("deploy"):
        send_text(chat_id, "Turn on the deploy power first (once): /caps deploy on")
        return
    send_text(chat_id, "\U0001F9D1‍\U0001F4BB Writing a complete program for: " + desc[:160] + " ...")
    code = _clean_code(_mm_brain(
        "Write a COMPLETE, self-contained Python 3 program (single file) that does this: " + desc +
        ". It must run as a long-lived process/service (loop or server). Hardcode sensible config at the top. "
        "If it needs third-party packages, declare them on the FIRST line as a comment EXACTLY like "
        "'# requires: pkg1 pkg2'. Return ONLY the raw Python - no markdown, no commentary.", timeout=220, raw=True))
    if not code or len(code) < 40:
        send_text(chat_id, "I couldn't draft that cleanly - try describing it more specifically.")
        return
    deploy_app(chat_id, name, code)


PENDAEDIT = {}                                 # token -> pending edit to a deployed app


def _app_main(name):
    return os.path.join(app_dir(name), "main.py")


def app_edit(chat_id, name, instruction):
    """Supervised edit of a DEPLOYED app: pick a function -> rewrite -> compile-check -> diff -> tap -> restart app.
    Same safety rails as Nemo's self-upgrade, but pointed at /root/apps/<name>/main.py instead of his own code."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner-only.")
        return
    if not cap_ok("deploy"):
        send_text(chat_id, "\U0001F512 The DEPLOY power is off (or /lockdown). Turn it on with /caps deploy on.")
        return
    sname = _svc_ok(name)
    path = _app_main(sname) if sname else ""
    if not sname or not os.path.exists(path):
        send_text(chat_id, "I don't have a deployed app called '" + str(name) + "'. /apps shows what I'm running.")
        return
    instruction = (instruction or "").strip()
    if len(instruction) < 6:
        send_text(chat_id, "Tell me what to change, e.g. /app " + sname + " edit add a /ping command that replies pong.")
        return
    send_text(chat_id, "\U0001F9D1‍\U0001F4BB Working out how to change " + sname + " for that...")
    try:
        src = open(path, encoding="utf-8").read()
    except Exception as e:
        send_text(chat_id, "Couldn't read " + sname + "'s code: " + str(e)[:150])
        return
    names = _top_def_names(src)
    if not names:
        send_text(chat_id, "That app has no editable functions I can target.")
        return
    pick = ask_ai(chat_id,
                  "You are editing the Python source of an app called '" + sname + "'. The owner asked:\n\"" +
                  instruction + "\"\n\nIts top-level function names:\n" + ", ".join(names) + "\n\nWhich ONE existing "
                  "function should be edited (or is the best place to add this)? Reply with ONLY that exact name from "
                  "the list, nothing else.", remember=False, timeout=90)
    tgt = ((pick or "").strip().split() or [""])[0].strip(".,`'\"()")
    if tgt not in names:
        send_text(chat_id, "I couldn't pinpoint which part of " + sname + " to change. Be more specific about the "
                  "feature or the function to touch.")
        return
    old_block = _func_block_text(src, tgt)
    if not old_block or len(old_block) > 9000:
        send_text(chat_id, "That function is too large to rewrite safely in one go. Ask for a smaller change.")
        return
    new_block = _strip_fence(ask_ai(chat_id,
                "You are editing the app '" + sname + "'. The owner asked:\n\"" + instruction + "\"\n\n"
                "CURRENT function:\n```python\n" + old_block + "\n```\n\nRewrite ONLY this one function to satisfy the "
                "request. Keep the same name and signature unless the request truly requires a change. Preserve every "
                "existing behaviour except the requested one. Return ONLY the complete new function as raw Python - no "
                "markdown fence, no commentary.", remember=False, deep=True, timeout=200, raw=True))
    if not new_block or not re.match(r"^(?:def|class)\s+" + re.escape(tgt) + r"\b", new_block):
        send_text(chat_id, "My rewrite didn't come out clean (name/shape changed). Nothing touched - please rephrase.")
        return
    newtext = _replace_func(src, tgt, new_block)
    ok, err = _compile_check(newtext) if newtext else (False, "splice failed")
    if not ok:
        fix = _strip_fence(ask_ai(chat_id, "Your rewrite of `" + tgt + "` caused this Python error:\n" + err[:600] +
                           "\n\nThe function you wrote:\n```python\n" + new_block + "\n```\n"
                           "Return ONLY the corrected complete function, raw Python, no fence.",
                           remember=False, deep=True, timeout=200, raw=True))
        if fix and re.match(r"^(?:def|class)\s+" + re.escape(tgt) + r"\b", fix):
            new_block = fix
            newtext = _replace_func(src, tgt, new_block)
            ok, err = _compile_check(newtext) if newtext else (False, "splice failed")
    if not ok:
        send_text(chat_id, "I wrote a change but it FAILED my compile-check, so I did NOT apply it:\n" + err[:400] +
                  "\n\nNothing changed.")
        return
    diff = _unified(old_block, new_block, tgt)
    if not diff.strip():
        send_text(chat_id, "That would make no actual change. Nothing to apply.")
        return
    import secrets as _s3
    tok = _s3.token_hex(4)
    PENDAEDIT[tok] = {"app": sname, "newtext": newtext, "target": tgt, "at": time.time()}
    shown = diff if len(diff) < 3200 else diff[:3200] + "\n... (diff truncated)"
    kb = {"inline_keyboard": [[{"text": "✅ Apply & restart " + sname, "callback_data": "aeok:" + tok},
                               {"text": "❌ Discard", "callback_data": "aeno:" + tok}]]}
    tg("sendMessage", chat_id=chat_id,
       text=("\U0001F9E9 Change to " + sname + "  ·  function " + tgt + ":\n\n" + shown +
             "\n\n✓ Passed my compile-check. Apply it? I'll back up the current " + sname + " first, then restart it. "
             "If it misbehaves, /app " + sname + " rollback."),
       reply_markup=kb)


def apply_app_edit(chat_id, ae):
    name, newtext = ae["app"], ae["newtext"]
    ok, err = _compile_check(newtext)
    if not ok:
        send_text(chat_id, "Aborted - it no longer compiles cleanly, so I left " + name + " untouched.\n" + err[:250])
        return
    path = _app_main(name)
    bpath = "(backup skipped)"
    try:
        bdir = os.path.join(app_dir(name), "backups")
        os.makedirs(bdir, exist_ok=True)
        bpath = os.path.join(bdir, "main." + time.strftime("%Y%m%d_%H%M%S") + ".py")
        open(bpath, "w", encoding="utf-8").write(open(path, encoding="utf-8").read())
    except Exception:
        pass
    try:
        open(path, "w", encoding="utf-8").write(newtext)
    except Exception as e:
        send_text(chat_id, "Couldn't write " + name + "'s file: " + str(e)[:150] + " - nothing changed.")
        return
    audit("owner", "app.edit", name + ":" + ae.get("target", "?"))
    _systemctl("restart", name)
    send_text(chat_id, "✅ Updated " + name + " (" + ae.get("target", "?") + ") and restarted it.\nBackup: " + bpath +
              "\nIf it misbehaves: /app " + name + " rollback")
    time.sleep(2)
    send_text(chat_id, "\U0001F4CB Logs:\n" + app_logs(name, 15))


def app_rollback(chat_id, name):
    sname = _svc_ok(name)
    bdir = os.path.join(app_dir(sname), "backups") if sname else ""
    try:
        backups = sorted(os.listdir(bdir)) if bdir and os.path.isdir(bdir) else []
    except Exception:
        backups = []
    if not backups:
        send_text(chat_id, "No backup to roll back to for '" + str(name) + "'.")
        return
    last = os.path.join(bdir, backups[-1])
    try:
        txt = open(last, encoding="utf-8").read()
        ok, err = _compile_check(txt)
        if not ok:
            send_text(chat_id, "The backup won't compile, so I'm not restoring it. (" + err[:150] + ")")
            return
        open(_app_main(sname), "w", encoding="utf-8").write(txt)
        _systemctl("restart", sname)
        send_text(chat_id, "↩️ Restored " + sname + " from the last backup and restarted it.")
    except Exception as e:
        send_text(chat_id, "Rollback failed: " + str(e)[:150])


def _app_dispatch(chat_id, text, msg):
    """App Factory command surface: /apps /ship /build /env /app. Returns True if consumed. Owner-only."""
    try:
        low = (text or "").strip().lower()
        if not low.startswith(("/apps", "/app ", "/ship", "/build", "/env")):
            return False
        if chat_id != OWNER.get("id"):
            send_text(chat_id, "Owner-only.")
            return True
        arg = text.split(None, 1)[1].strip() if len(text.split(None, 1)) > 1 else ""
        if low.startswith("/env"):
            parts = arg.split()
            nm = _svc_ok(parts[0]) if parts else None
            if not nm:
                send_text(chat_id, "Usage: /env <app> KEY=VALUE [KEY2=VALUE2]   ·   /env <app>  (show)   ·   "
                          "/env <app> clear\nExample: /env signalbot SIGNALBOT_TG_TOKEN=123:ABC SIGNALBOT_OWNER_ID=" +
                          str(OWNER.get("id", "")))
            elif len(parts) == 1:
                env = _app_env(nm)
                send_text(chat_id, ("\U0001F510 " + nm + " env: " + ", ".join(k + "=" + _mask(v) for k, v in env.items()))
                          if env else "No env vars set for '" + nm + "'. Add: /env " + nm + " KEY=VALUE")
            elif parts[1].lower() in ("clear", "reset", "wipe"):
                kv_set("appenv:" + nm, "{}")
                send_text(chat_id, "Cleared env for '" + nm + "'.")
            else:
                env = _app_env(nm)
                added = []
                for kvp in parts[1:]:
                    if "=" in kvp:
                        k, v = kvp.split("=", 1)
                        env[k.strip()] = v.strip()
                        added.append(k.strip())
                kv_set("appenv:" + nm, json.dumps(env))
                if os.path.exists(_app_main(nm)):
                    # app is already live -> rewrite its .env and restart it now (one-step, e.g. daily token refresh)
                    env_file = _write_env_file(nm, env)

                    def _apply_env(_nm=nm, _ef=env_file, _added=list(added)):
                        ok, out = app_start_service(_nm, "main.py", _ef, app_dir(_nm))
                        if ok:
                            send_text(chat_id, "\U0001F510 Updated " + ", ".join(_added) + " and restarted " + _nm +
                                      " - live now with the new value(s). No re-ship needed.")
                        else:
                            send_text(chat_id, "Saved the value(s), but couldn't restart " + _nm + ":\n" +
                                      (out or "")[:300] + "\nTry /app " + _nm + " restart.")
                    threading.Thread(target=_apply_env, daemon=True).start()
                else:
                    send_text(chat_id, "\U0001F510 Saved " + str(len(added)) + " var(s) for '" + nm + "': " +
                              ", ".join(added) + ".\nThey'll be baked into the service when you /ship " + nm +
                              " (kept in a locked 600 file, never shown again).")
        elif low.startswith("/apps"):
            send_text(chat_id, app_list())
        elif low.startswith("/ship"):
            name = arg.split()[0] if arg else ""
            lc = LAST_CODE.get(chat_id)
            if not name:
                send_text(chat_id, "Usage: send me the .py file, then  /ship <name>  (e.g. /ship signalbot).")
            elif not lc:
                send_text(chat_id, "Send me the .py file first (as an attachment), then /ship " + name + ".")
            else:
                threading.Thread(target=deploy_app, args=(chat_id, name, lc["code"]), daemon=True).start()
        elif low.startswith("/build"):
            if ":" not in arg:
                send_text(chat_id, "Usage: /build <name>: <what the program should do>")
            else:
                nm, desc = arg.split(":", 1)
                threading.Thread(target=_build_and_ship, args=(chat_id, nm.strip(), desc.strip()), daemon=True).start()
        elif low.startswith("/app "):
            parts = arg.split()
            if len(parts) < 2:
                send_text(chat_id, "Usage: /app <name> status|logs|restart|stop|start|edit <change>|rollback|rm")
            else:
                nm, action = _svc_ok(parts[0]), parts[1].lower()
                if not nm:
                    send_text(chat_id, "Unknown/invalid app name.")
                elif action == "rm":
                    app_remove(chat_id, nm)
                elif action == "logs":
                    send_text(chat_id, "\U0001F4CB " + nm + " logs:\n" + app_logs(nm, 30))
                elif action == "edit":
                    instr = arg.split(None, 2)[2] if len(arg.split(None, 2)) > 2 else ""
                    threading.Thread(target=app_edit, args=(chat_id, nm, instr), daemon=True).start()
                elif action == "rollback":
                    app_rollback(chat_id, nm)
                else:
                    send_text(chat_id, app_ctl(nm, action))
        return True
    except Exception as e:
        send_text(chat_id, "App command error: " + str(e)[:150])
        return True


# ============================ GOOGLE SUPER-LAYER (v10.15) ============================
# Phase 1 - WORKSPACE (free; reuses his Google login, needs ONE re-consent for the wider scopes):
#   Drive backup + shareable uploads · Sheets as a live database · Docs · Tasks · Contacts.
# Phase 2 - CLOUD AI (needs a Google Cloud API key + billing; generous free tiers + a hard daily cap):
#   Vision (eyes/OCR) · Translate · Text-to-Speech · Speech-to-Text · Gemini · Programmable Search.
# All calls go through the existing google_get/google_post bearer helpers (Phase 1) or a Cloud key (Phase 2).

# ---------------- Phase 1: DRIVE ----------------
def _drive_share(file_id):
    google_post("https://www.googleapis.com/drive/v3/files/" + file_id + "/permissions",
                {"role": "reader", "type": "anyone"})


def drive_upload(path, name=None, share=True):
    """Upload a local file to Drive (multipart). Returns (link, '') or (None, err)."""
    tok = google_token()
    if not tok:
        return None, "Google isn't connected - /google first."
    if not os.path.exists(path):
        return None, "file not found"
    name = name or os.path.basename(path)
    try:
        data = open(path, "rb").read()
        b = "nemo" + str(int(time.time() * 1000) % 1000000)
        meta = json.dumps({"name": name}).encode()
        body = (b"--" + b.encode() + b"\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n" + meta +
                b"\r\n--" + b.encode() + b"\r\nContent-Type: application/octet-stream\r\n\r\n" + data +
                b"\r\n--" + b.encode() + b"--")
        r = requests.post("https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,webViewLink",
                          headers={"Authorization": "Bearer " + tok,
                                   "Content-Type": "multipart/related; boundary=" + b}, data=body, timeout=180)
        j = r.json()
        fid = j.get("id")
        if not fid:
            return None, str(j.get("error", j))[:200]
        if share:
            _drive_share(fid)
        return j.get("webViewLink") or ("https://drive.google.com/file/d/" + fid + "/view"), ""
    except Exception as e:
        return None, type(e).__name__ + ": " + str(e)[:150]


def drive_backup(chat_id=None):
    """Zip his brain (code + nemo.db memory + secrets) and upload it to Drive."""
    import zipfile
    stamp = time.strftime("%Y%m%d_%H%M%S")
    zpath = "/tmp/nemo_backup_" + stamp + ".zip"
    try:
        with zipfile.ZipFile(zpath, "w", zipfile.ZIP_DEFLATED) as z:
            for p in (SELF_PATH, NEMO_DB, "/root/bot_secrets.json"):
                try:
                    if os.path.exists(p):
                        z.write(p, os.path.basename(p))
                except Exception:
                    pass
        link, err = drive_upload(zpath, "nemo_backup_" + stamp + ".zip", share=False)
        return link, err
    finally:
        try:
            os.remove(zpath)
        except Exception:
            pass


# ---------------- Phase 1: SHEETS (his live database) ----------------
def _sheet_key(name):
    return "gsheet_" + re.sub(r"[^a-z0-9]", "_", name.lower())[:40]


def _sheet_id_for(name):
    sid = _sec_get(_sheet_key(name))
    if sid:
        return sid
    j = google_post("https://sheets.googleapis.com/v4/spreadsheets", {"properties": {"title": "Nemo · " + name}})
    sid = (j or {}).get("spreadsheetId")
    if sid:
        save_secret(_sheet_key(name), sid)
    return sid


def sheet_log(name, values):
    """Append a timestamped row to the named sheet (creates it the first time)."""
    sid = _sheet_id_for(name)
    if not sid:
        return None, "couldn't open/create the sheet (re-consent Google with the Sheets scope)"
    row = [str(v) for v in ([time.strftime("%Y-%m-%d %H:%M")] + list(values))]
    j = google_post("https://sheets.googleapis.com/v4/spreadsheets/" + sid +
                    "/values/A1:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS", {"values": [row]})
    if j and not j.get("error"):
        return "https://docs.google.com/spreadsheets/d/" + sid, ""
    return None, str((j or {}).get("error", "append failed"))[:150]


def sheet_read(name, n=12):
    sid = _sec_get(_sheet_key(name))
    if not sid:
        return None
    j = google_get("https://sheets.googleapis.com/v4/spreadsheets/" + sid + "/values/A1:Z100")
    rows = (j or {}).get("values", [])
    return rows[-n:] if rows else []


# ---------------- Phase 1: DOCS ----------------
def doc_create(title, body_text):
    j = google_post("https://docs.googleapis.com/v1/documents", {"title": title})
    did = (j or {}).get("documentId")
    if not did:
        return None, "couldn't create the doc (Docs scope connected?)"
    google_post("https://docs.googleapis.com/v1/documents/" + did + ":batchUpdate",
                {"requests": [{"insertText": {"location": {"index": 1}, "text": body_text}}]})
    return "https://docs.google.com/document/d/" + did, ""


# ---------------- Phase 1: TASKS + CONTACTS ----------------
def task_add(title, notes=""):
    j = google_post("https://tasks.googleapis.com/tasks/v1/lists/@default/tasks", {"title": title, "notes": notes})
    return bool(j and j.get("id"))


def tasks_list(n=15):
    j = google_get("https://tasks.googleapis.com/tasks/v1/lists/@default/tasks",
                   {"showCompleted": "false", "maxResults": n})
    return [t.get("title", "") for t in (j or {}).get("items", [])]


def contact_add(name, phone="", email=""):
    body = {"names": [{"givenName": name}]}
    if phone:
        body["phoneNumbers"] = [{"value": phone}]
    if email:
        body["emailAddresses"] = [{"value": email}]
    j = google_post("https://people.googleapis.com/v1/people:createContact", body)
    return bool(j and j.get("resourceName"))


def contacts_find(q, n=8):
    j = google_get("https://people.googleapis.com/v1/people:searchContacts",
                   {"query": q, "readMask": "names,phoneNumbers,emailAddresses", "pageSize": n})
    out = []
    for r in (j or {}).get("results", []):
        p = r.get("person", {})
        nm = (p.get("names") or [{}])[0].get("displayName", "")
        ph = (p.get("phoneNumbers") or [{}])[0].get("value", "")
        em = (p.get("emailAddresses") or [{}])[0].get("value", "")
        out.append(nm + (" · " + ph if ph else "") + (" · " + em if em else ""))
    return out


def _gws_dispatch(chat_id, text, msg):
    """Phase-1 Google Workspace commands. Owner-only. Returns True if consumed."""
    try:
        low = (text or "").strip().lower()
        if not low.startswith(("/backup", "/log ", "/gsheet", "/gdoc", "/gtask", "/gcontact", "/findcontact")):
            return False
        if chat_id != OWNER.get("id"):
            send_text(chat_id, "Owner-only.")
            return True
        arg = text.split(None, 1)[1].strip() if len(text.split(None, 1)) > 1 else ""
        if low.startswith("/backup"):
            send_text(chat_id, "\U0001F4E6 Backing up my brain (code + memory + secrets) to your Google Drive...")

            def _b():
                link, err = drive_backup(chat_id)
                send_text(chat_id, ("✅ Backup saved to Drive:\n" + link) if link else
                          ("Backup failed: " + err + "\n(Re-consent Google with the Drive scope: /google.)"))
            threading.Thread(target=_b, daemon=True).start()
        elif low.startswith("/log "):
            if ":" in arg:
                nm, vals = arg.split(":", 1)
                link, err = sheet_log(nm.strip(), [v.strip() for v in vals.split(",")])
                send_text(chat_id, ("✅ Logged to '" + nm.strip() + "':\n" + link) if link else ("Couldn't log: " + err))
            else:
                send_text(chat_id, "Usage: /log <sheet name>: value1, value2, ...  (e.g. /log expenses: fuel, 500)")
        elif low.startswith("/gsheet"):
            rows = sheet_read(arg) if arg else None
            send_text(chat_id, ("\U0001F4CA " + arg + " (recent):\n" + "\n".join(" · ".join(r) for r in rows))
                      if rows else "Usage: /gsheet <sheet name>  (shows recent rows of a sheet I keep)")
        elif low.startswith("/gdoc"):
            if ":" in arg:
                title, bodytext = arg.split(":", 1)
                link, err = doc_create(title.strip(), bodytext.strip())
                send_text(chat_id, ("✅ Doc created:\n" + link) if link else ("Couldn't create doc: " + err))
            else:
                send_text(chat_id, "Usage: /gdoc <title>: <body text>")
        elif low.startswith("/gtask"):
            if arg and arg.lower() not in ("list", "ls"):
                send_text(chat_id, "✅ Task added to Google Tasks." if task_add(arg) else "Couldn't add it (Tasks scope?).")
            else:
                ts = tasks_list()
                send_text(chat_id, "\U0001F4DD Google Tasks:\n" + ("\n".join("• " + t for t in ts) if ts else "(none)"))
        elif low.startswith("/gcontact"):
            ps = [p.strip() for p in arg.split(",")]
            if ps and ps[0]:
                ok = contact_add(ps[0], ps[1] if len(ps) > 1 else "", ps[2] if len(ps) > 2 else "")
                send_text(chat_id, "✅ Contact saved to Google." if ok else "Couldn't save (Contacts scope?).")
            else:
                send_text(chat_id, "Usage: /gcontact <name>, <phone>, <email>")
        elif low.startswith("/findcontact"):
            res = contacts_find(arg) if arg else []
            send_text(chat_id, ("\U0001F464 " + "\n".join(res)) if res else "No matches (or Contacts not connected).")
        return True
    except Exception as e:
        send_text(chat_id, "Google command error: " + str(e)[:150])
        return True


# ---------------- Phase 2: CLOUD AI (Vision/Translate/Speech/Gemini/Search) ----------------
GAI = {"key": "", "cx": "", "calls": 0, "day": "", "cap": 500}     # hard daily call cap = bill safety


def _gai_load():
    GAI["key"] = _sec_get("gcloud_key") or GAI["key"]
    GAI["cx"] = _sec_get("gsearch_cx") or GAI["cx"]


def _gai_ok():
    if not GAI["key"]:
        _gai_load()
    today = time.strftime("%Y-%m-%d")
    if GAI["day"] != today:
        GAI["day"], GAI["calls"] = today, 0
    if not GAI["key"]:
        return False, "No Google Cloud key set yet. Send /gcloud <API key> (see the setup guide)."
    if GAI["calls"] >= GAI["cap"]:
        return False, "Daily Cloud-AI cap (" + str(GAI["cap"]) + ") hit - safety stop so no bill surprise. Resets tomorrow."
    GAI["calls"] += 1
    return True, ""


def _gai_post(url, body, timeout=60):
    ok, err = _gai_ok()
    if not ok:
        return None, err
    try:
        r = requests.post(url + ("&" if "?" in url else "?") + "key=" + GAI["key"], json=body, timeout=timeout)
        return r.json(), ""
    except Exception as e:
        return None, type(e).__name__ + ": " + str(e)[:150]


def gvision(image_b64, mode="ocr"):
    feat = {"type": "TEXT_DETECTION" if mode == "ocr" else "LABEL_DETECTION", "maxResults": 15}
    j, err = _gai_post("https://vision.googleapis.com/v1/images:annotate",
                       {"requests": [{"image": {"content": image_b64}, "features": [feat]}]})
    if not j:
        return None, err
    resp = (j.get("responses") or [{}])[0]
    if mode == "ocr":
        return ((resp.get("fullTextAnnotation") or {}).get("text")
                or (resp.get("textAnnotations") or [{}])[0].get("description", "")), ""
    return ", ".join(l.get("description", "") for l in resp.get("labelAnnotations", [])), ""


def gtranslate(text, target="en"):
    j, err = _gai_post("https://translation.googleapis.com/language/translate/v2",
                       {"q": text, "target": target, "format": "text"})
    if not j:
        return None, err
    return ((j.get("data", {}).get("translations") or [{}])[0].get("translatedText", "")), ""


def gtts(text, voice="en-IN-Wavenet-D", lang="en-IN"):
    j, err = _gai_post("https://texttospeech.googleapis.com/v1/text:synthesize",
                       {"input": {"text": text[:5000]}, "voice": {"languageCode": lang, "name": voice},
                        "audioConfig": {"audioEncoding": "MP3"}})
    if not j:
        return None, err
    a = j.get("audioContent")
    return (base64.b64decode(a) if a else None), ("" if a else str(j.get("error", "no audio"))[:150])


def gstt(audio_b64, lang="en-IN"):
    j, err = _gai_post("https://speech.googleapis.com/v1/speech:recognize",
                       {"config": {"languageCode": lang, "enableAutomaticPunctuation": True},
                        "audio": {"content": audio_b64}})
    if not j:
        return None, err
    return " ".join((r.get("alternatives") or [{}])[0].get("transcript", "") for r in j.get("results", [])), ""


def gemini_ai(prompt, model="gemini-1.5-flash"):
    j, err = _gai_post("https://generativelanguage.googleapis.com/v1beta/models/" + model + ":generateContent",
                       {"contents": [{"parts": [{"text": prompt}]}]})
    if not j:
        return None, err
    try:
        return j["candidates"][0]["content"]["parts"][0]["text"], ""
    except Exception:
        return None, str(j.get("error", "no answer"))[:150]


def gsearch(q, n=5):
    ok, err = _gai_ok()
    if not ok:
        return None, err
    if not GAI["cx"]:
        return None, "No search-engine id set. Send /gcloud cx <id> (see setup)."
    try:
        r = requests.get("https://www.googleapis.com/customsearch/v1",
                         params={"key": GAI["key"], "cx": GAI["cx"], "q": q, "num": n}, timeout=30).json()
        return [(it.get("title", ""), it.get("link", ""), it.get("snippet", "")) for it in r.get("items", [])], ""
    except Exception as e:
        return None, str(e)[:150]


def _gai_dispatch(chat_id, text, msg):
    """Phase-2 Cloud AI commands. Owner-only. Returns True if consumed."""
    try:
        low = (text or "").strip().lower()
        if not low.startswith(("/gcloud", "/gtranslate", "/gvision", "/gsee", "/gemini", "/gsearch", "/gsay")):
            return False
        if chat_id != OWNER.get("id"):
            send_text(chat_id, "Owner-only.")
            return True
        arg = text.split(None, 1)[1].strip() if len(text.split(None, 1)) > 1 else ""
        if low.startswith("/gcloud"):
            ps = arg.split()
            if len(ps) >= 2 and ps[0].lower() == "cx":
                save_secret("gsearch_cx", ps[1]); _gai_load()
                send_text(chat_id, "Search-engine id saved. /gsearch works now.")
            elif arg:
                save_secret("gcloud_key", ps[0]); _gai_load()
                send_text(chat_id, "\U0001F511 Google Cloud key saved. Vision, Translate, Speech, Gemini & Search are "
                          "on. Daily safety cap: " + str(GAI["cap"]) + " calls.")
            else:
                _gai_load()
                send_text(chat_id, "Cloud AI: key " + ("set ✅" if GAI["key"] else "not set") + " · cx " +
                          ("set" if GAI["cx"] else "not set") + " · used " + str(GAI["calls"]) + "/" +
                          str(GAI["cap"]) + " today.")
        elif low.startswith("/gtranslate"):
            target, txt = "en", arg
            if ":" in arg and len(arg.split(":", 1)[0].strip()) <= 5:
                target, txt = arg.split(":", 1)[0].strip(), arg.split(":", 1)[1].strip()
            def _t():
                out, err = gtranslate(txt, target)
                send_text(chat_id, ("\U0001F310 " + out) if out else ("Translate error: " + err))
            threading.Thread(target=_t, daemon=True).start()
        elif low.startswith(("/gvision", "/gsee")):
            b64 = LAST_PHOTO.get(chat_id)
            if not b64:
                send_text(chat_id, "Send me a photo first, then /gsee (reads text) or /gsee labels (what's in it).")
            else:
                mode = "labels" if "label" in arg.lower() else "ocr"
                def _v():
                    out, err = gvision(b64, mode)
                    send_text(chat_id, ("\U0001F441 " + (out or "(nothing found)")) if out is not None
                              else ("Vision error: " + err))
                threading.Thread(target=_v, daemon=True).start()
        elif low.startswith("/gemini"):
            def _g():
                out, err = gemini_ai(arg)
                send_text(chat_id, ("\U0001F52E " + out) if out else ("Gemini error: " + err))
            threading.Thread(target=_g, daemon=True).start()
        elif low.startswith("/gsearch"):
            def _s():
                res, err = gsearch(arg)
                send_text(chat_id, ("\U0001F50E " + "\n\n".join(t + "\n" + l for t, l, _ in res)) if res
                          else ("Search error: " + err))
            threading.Thread(target=_s, daemon=True).start()
        elif low.startswith("/gsay"):
            def _say():
                audio, err = gtts(arg)
                if audio:
                    p = "/tmp/gsay_" + str(int(time.time())) + ".mp3"
                    open(p, "wb").write(audio)
                    try:
                        requests.post(TG + "/sendVoice", data={"chat_id": chat_id},
                                      files={"voice": ("say.mp3", open(p, "rb"), "audio/mpeg")}, timeout=60)
                    finally:
                        try:
                            os.remove(p)
                        except Exception:
                            pass
                else:
                    send_text(chat_id, "TTS error: " + err)
            threading.Thread(target=_say, daemon=True).start()
        return True
    except Exception as e:
        send_text(chat_id, "Cloud AI command error: " + str(e)[:150])
        return True


# ---------------- NEMO OS v11 · PHASE 1: WORLD MODEL / KNOWLEDGE GRAPH ----------------
# A persistent, TEMPORAL model of the Boss's world in the existing nemo.db (ADR-2): entities,
# relations, and dated facts with SOURCE + CONFIDENCE (provenance, spec §5). Facts are NEVER
# overwritten - "Supplier X quoted 10L in March" and "8.5L in August" coexist (spec §4).
# Purely additive: new kg_* tables, new dispatcher; nothing existing is touched (spec §2).

def _kg_init():
    for s in (
        "CREATE TABLE IF NOT EXISTS kg_entities(id INTEGER PRIMARY KEY, name TEXT COLLATE NOCASE, "
        "kind TEXT DEFAULT '', created REAL)",
        "CREATE TABLE IF NOT EXISTS kg_facts(id INTEGER PRIMARY KEY, entity INTEGER, fact TEXT, "
        "source TEXT DEFAULT 'you', confidence REAL DEFAULT 0.9, created REAL)",
        "CREATE TABLE IF NOT EXISTS kg_relations(id INTEGER PRIMARY KEY, src INTEGER, rel TEXT, "
        "dst INTEGER, created REAL)",
    ):
        _exec(s)


def kg_entity(name, kind=""):
    """Find-or-create an entity (case-insensitive). Returns its id, or None for a blank name."""
    name = (name or "").strip()[:80]
    if not name:
        return None
    _kg_init()
    r = _q("SELECT id, kind FROM kg_entities WHERE name=?", (name,))
    if r:
        if kind and not r[0]["kind"]:
            _exec("UPDATE kg_entities SET kind=? WHERE id=?", (kind.strip()[:30], r[0]["id"]))
        return r[0]["id"]
    _exec("INSERT INTO kg_entities(name, kind, created) VALUES(?,?,?)", (name, kind.strip()[:30], time.time()))
    return _q("SELECT id FROM kg_entities WHERE name=?", (name,))[0]["id"]


def kg_fact(name, fact, source="you", confidence=0.9, kind="", ts=None):
    """Record a dated fact about an entity. History is preserved - never overwrites (temporal, spec §4).
    Every fact stores FACT / SOURCE / DATE / CONFIDENCE (provenance, spec §5)."""
    fact = (fact or "").strip()[:500]
    eid = kg_entity(name, kind)
    if not eid or not fact:
        return None
    _exec("INSERT INTO kg_facts(entity, fact, source, confidence, created) VALUES(?,?,?,?,?)",
          (eid, fact, (source or "you")[:40], float(confidence), ts or time.time()))
    try:
        mem_add("[world] " + name.strip() + ": " + fact, kind="world")   # so /recall finds it semantically too
    except Exception:
        pass
    return eid


def kg_relate(a, rel, b):
    """Record a relation A -rel-> B (owns, supplies, works_with, depends_on...)."""
    ia, ib = kg_entity(a), kg_entity(b)
    rel = re.sub(r"[^a-z_ ]", "", (rel or "").lower()).strip().replace(" ", "_")[:30]
    if not (ia and ib and rel):
        return False
    if not _q("SELECT id FROM kg_relations WHERE src=? AND rel=? AND dst=?", (ia, rel, ib)):
        _exec("INSERT INTO kg_relations(src, rel, dst, created) VALUES(?,?,?,?)", (ia, rel, ib, time.time()))
    return True


def _kg_when(t):
    try:
        return time.strftime("%d %b %Y", time.localtime(float(t)))
    except Exception:
        return "?"


def kg_profile(name):
    """Everything known about an entity: dated facts (latest first, with provenance) + relations."""
    _kg_init()
    r = _q("SELECT id, name, kind FROM kg_entities WHERE name=?", ((name or "").strip()[:80],))
    if not r:
        hits = _q("SELECT DISTINCT e.name FROM kg_entities e LEFT JOIN kg_facts f ON f.entity=e.id "
                  "WHERE e.name LIKE ? OR f.fact LIKE ? LIMIT 8",
                  ("%" + name.strip() + "%", "%" + name.strip() + "%"))
        if hits:
            return "I don't have '" + name + "' exactly, but these match:\n" + \
                   "\n".join("• " + h["name"] for h in hits) + "\n\n/world <name> for one of them."
        return "Nothing in my world model about '" + name + "' yet. Teach me:  /fact " + name + ": <something true about it>"
    eid, ename, kind = r[0]["id"], r[0]["name"], r[0]["kind"]
    facts = _q("SELECT fact, source, confidence, created FROM kg_facts WHERE entity=? ORDER BY created DESC", (eid,))
    outs = _q("SELECT r.rel, e2.name AS o FROM kg_relations r JOIN kg_entities e2 ON e2.id=r.dst WHERE r.src=?", (eid,))
    ins = _q("SELECT r.rel, e1.name AS o FROM kg_relations r JOIN kg_entities e1 ON e1.id=r.src WHERE r.dst=?", (eid,))
    lines = ["\U0001F30D " + ename + ((" (" + kind + ")") if kind else "")]
    if facts:
        lines.append("\nFacts (" + str(len(facts)) + ", newest first - history is kept):")
        for f in facts[:10]:
            lines.append("• " + f["fact"] + "   [" + _kg_when(f["created"]) + " · " + (f["source"] or "you") +
                         " · " + str(int(round((f["confidence"] or 0.9) * 100))) + "%]")
        if len(facts) > 10:
            lines.append("  ... " + str(len(facts) - 10) + " older - /timeline " + ename)
    if outs:
        lines.append("\nRelations: " + " · ".join("→ " + o["rel"] + " " + o["o"] for o in outs[:8]))
    if ins:
        lines.append("Linked from: " + " · ".join(i["o"] + " " + i["rel"] + " →" for i in ins[:8]))
    if not facts and not outs and not ins:
        lines.append("(known, but no facts yet - /fact " + ename + ": <fact>)")
    return "\n".join(lines)


def kg_timeline(name):
    """Chronological (oldest -> newest) dated history of an entity - temporal memory (spec §20)."""
    _kg_init()
    r = _q("SELECT id, name FROM kg_entities WHERE name=?", ((name or "").strip()[:80],))
    if not r:
        return "No entity '" + name + "' in my world model. /world " + name + " to search."
    facts = _q("SELECT fact, source, created FROM kg_facts WHERE entity=? ORDER BY created ASC", (r[0]["id"],))
    if not facts:
        return "No dated facts for " + r[0]["name"] + " yet."
    return "\U0001F553 Timeline - " + r[0]["name"] + ":\n" + \
           "\n".join("• " + _kg_when(f["created"]) + " - " + f["fact"] + "  (" + (f["source"] or "you") + ")"
                     for f in facts[:25])


def kg_stats():
    _kg_init()
    ne = _q("SELECT COUNT(*) c FROM kg_entities")[0]["c"]
    nf = _q("SELECT COUNT(*) c FROM kg_facts")[0]["c"]
    nr = _q("SELECT COUNT(*) c FROM kg_relations")[0]["c"]
    tops = _q("SELECT e.name, COUNT(f.id) c FROM kg_entities e LEFT JOIN kg_facts f ON f.entity=e.id "
              "GROUP BY e.id ORDER BY c DESC LIMIT 6")
    s = "Entities " + str(ne) + " · Facts " + str(nf) + " · Relations " + str(nr)
    if ne:
        s += "\nMost known: " + ", ".join(t["name"] + " (" + str(t["c"]) + ")" for t in tops if t["name"])
    return s


_KG_CMD = re.compile(r"/(world|fact|relate|timeline|graph|os)(\s|$)")


def _kg_dispatch(chat_id, text, msg):
    """World-model commands (owner-only). Exact-word gate so /fact can never swallow a future /facts."""
    try:
        low = (text or "").strip().lower()
        m = _KG_CMD.match(low)
        if not m:
            return False
        if chat_id != OWNER.get("id"):
            send_text(chat_id, "Owner-only.")
            return True
        cmd = m.group(1)
        rest = text.split(None, 1)[1].strip() if len(text.split(None, 1)) > 1 else ""

        if cmd == "os":
            send_text(chat_id, "\U0001F9E0 NEMO OS v11 - Phase 1 LIVE: World Model (temporal knowledge graph)\n" +
                      kg_stats() +
                      "\n\nNext phases: 2 memory+context · 3 decisions · 4 predict+radar · 5 board+red-team · "
                      "6 simulation · 7 chief-of-staff · 8 computer-agent · 9 governance · 10 dashboard\n\n"
                      "/fact <entity>: <fact> · /world <entity> · /timeline <entity> · /relate A | rel | B · /graph")
            return True
        if cmd == "graph":
            send_text(chat_id, "\U0001F578 World model:\n" + kg_stats())
            return True
        if cmd == "world":
            send_text(chat_id, (kg_profile(rest) if rest else
                      ("\U0001F30D My world model:\n" + kg_stats() +
                       "\n\n/world <entity> - profile · /fact <entity>: <fact> - teach me · /timeline <entity>")))
            return True
        if cmd == "timeline":
            send_text(chat_id, kg_timeline(rest) if rest else "Usage: /timeline <entity>")
            return True
        if cmd == "relate":
            parts = [p.strip() for p in rest.split("|")]
            if len(parts) != 3:
                toks = rest.split()
                parts = [toks[0], toks[1], " ".join(toks[2:])] if len(toks) >= 3 else []
            if len(parts) == 3 and kg_relate(parts[0], parts[1], parts[2]):
                send_text(chat_id, "\U0001F517 Noted: " + parts[0] + " -" + parts[1] + "-> " + parts[2] +
                          "\n/world " + parts[0] + " shows it.")
            else:
                send_text(chat_id, "Usage: /relate Supplier X | supplies | CBG Project   (A | relation | B)")
            return True
        # /fact
        if not rest:
            send_text(chat_id, "Usage:\n/fact Supplier X: quoted ₹8.5 lakh for the dryer\n"
                      "/fact Supplier X (supplier): first quote was ₹10 lakh\n"
                      "Or free-form: /fact ravi from jodhpur quoted 2 lakh - I'll work out entity + fact.")
            return True
        if ":" in rest:
            name, fact = rest.split(":", 1)
            kind = ""
            km = re.match(r"(.+?)\s*\(([\w ]{1,25})\)\s*$", name.strip())
            if km:
                name, kind = km.group(1), km.group(2)
            kg_fact(name.strip(), fact.strip(), kind=kind)
            send_text(chat_id, "\U0001F30D Noted about " + name.strip() + " (dated " + _kg_when(time.time()) +
                      ", history kept):\n" + fact.strip()[:200] + "\n\n/world " + name.strip() + " · /timeline " + name.strip())
        else:
            def _ai_fact(rt=rest, cid=chat_id):
                j = _mm_brain("Extract the entity and the fact from this note. Reply ONLY single-line JSON "
                              '{"entity":"who/what it is about","kind":"person|supplier|project|company|other",'
                              '"fact":"the fact as one clear sentence"}\nNote: ' + rt, timeout=60)
                try:
                    d = json.loads(j[j.find("{"):j.rfind("}") + 1])
                    kg_fact(d["entity"], d["fact"], kind=d.get("kind", ""))
                    send_text(cid, "\U0001F30D Noted about " + d["entity"] + ":\n" + d["fact"][:200] +
                              "\n\n/world " + d["entity"] + " shows everything I know.")
                except Exception:
                    send_text(cid, "Couldn't parse that - use the clear form:  /fact <entity>: <fact>")
            threading.Thread(target=_ai_fact, daemon=True).start()
        return True
    except Exception as e:
        send_text(chat_id, "World-model error: " + str(e)[:150])
        return True


