# ---------- Phase 6: SIMULATION (spec §15) + BUSINESS SIM (§16) - real Monte Carlo, pure Python ----------
def businesssim(capex, monthly_revenue, monthly_cost, months=36, growth=0.0, vol=0.10, trials=500, seed=None):
    """Monte Carlo business model. Returns scenario dict - BASE/OPTIMISTIC/PESSIMISTIC/STRESS + probabilities."""
    import random as _r
    rng = _r.Random(seed)

    def run(g, rev0, cost0, jitter=True):
        paybacks, finals = [], []
        for _ in range(trials):
            rev, cash, payback = rev0, -float(capex), None
            for m in range(1, months + 1):
                gm = g + (rng.gauss(0, vol) if jitter else 0)
                rev = max(0.0, rev * (1 + gm))
                cash += rev - cost0
                if payback is None and cash >= 0:
                    payback = m
            paybacks.append(payback)
            finals.append(cash)
        ok = [p for p in paybacks if p]
        return {"payback_med": (sorted(ok)[len(ok) // 2] if ok else None),
                "p_no_payback": round(100.0 * (trials - len(ok)) / trials, 1),
                "p_loss": round(100.0 * sum(1 for f in finals if f < 0) / trials, 1),
                "final_med": sorted(finals)[trials // 2],
                "roi_pct": round(100.0 * (sorted(finals)[trials // 2]) / capex, 1) if capex else 0}

    return {"BASE": run(growth, monthly_revenue, monthly_cost),
            "OPTIMISTIC": run(growth + vol, monthly_revenue, monthly_cost),
            "PESSIMISTIC": run(max(-0.9, growth - vol), monthly_revenue, monthly_cost),
            "STRESS": run(growth, monthly_revenue * 0.7, monthly_cost * 1.15),
            "break_even_monthly_revenue": monthly_cost}


def _sim_fmt(name, s):
    return (name + ": payback " + (str(s["payback_med"]) + "mo" if s["payback_med"] else "NONE") +
            " · P(loss @36mo) " + str(s["p_loss"]) + "% · median ROI " + str(s["roi_pct"]) + "%")


def businesssim_cmd(chat_id, text):
    j = _mm_brain("Extract business-sim inputs from this. Reply ONLY JSON (numbers in rupees, rates as decimals): "
                  "{\"capex\":0,\"monthly_revenue\":0,\"monthly_cost\":0,\"months\":36,\"growth\":0.0,\"vol\":0.1}\n"
                  "Text: " + text, timeout=90)
    try:
        p = json.loads(j[j.find("{"):j.rfind("}") + 1])
        r = businesssim(float(p["capex"]), float(p["monthly_revenue"]), float(p["monthly_cost"]),
                        int(p.get("months", 36)), float(p.get("growth", 0.0)), float(p.get("vol", 0.10)))
    except Exception as e:
        send_text(chat_id, "Give me numbers like: /businesssim capex 60 lakh, revenue 8 lakh/month, cost 5 lakh/month"
                  "\n(parse error: " + str(e)[:80] + ")")
        return
    V11_STATS["sims"] += 1
    v11_audit("businesssim", text[:120])
    send_text(chat_id, "\U0001F3ED BUSINESS SIMULATION (Monte Carlo, 500 runs/scenario, 36mo):\n" +
              "\n".join(_sim_fmt(k, r[k]) for k in ("BASE", "OPTIMISTIC", "PESSIMISTIC", "STRESS")) +
              "\nBreak-even revenue: ₹" + str(int(r["break_even_monthly_revenue"])) + "/month" +
              "\n\nProbabilities, not promises. /board to debate it · /biascheck before committing.")


