# ---------- Autonomous, web-researched SELF-IMPROVEMENT (safe by design - proposes, never self-applies to core) ----------
def selfgrow(chat_id, auto=False):
    """Nemo researches the INTERNET (+ his own recent errors) for ways to improve himself, forms ONE concrete,
    low-risk improvement to a non-core function, and routes it through the SUPERVISED self-editor
    (compile-check -> diff -> your tap -> backup -> /rollback). He grows himself; you stay the one tap that
    keeps him from wrecking himself (spec §22: never uncontrolled recursive self-modification)."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner-only.")
        return
    tg("sendMessage", chat_id=chat_id, text="\U0001F331 Self-grow: researching the web for ways to improve myself"
       + (" (weekly auto-review)" if auto else "") + "...")
    errs = " | ".join(list(REPAIRLOG)[-8:]) if REPAIRLOG else ""
    tq = _mm_brain("I'm a single-file Python Telegram assistant. From my recent issues below, give 2 short web-search "
                   "queries to find concrete engineering improvements (resilience, performance, safety, capability). "
                   "Reply ONLY a JSON array of 2 strings.\nRecent issues: " + (errs or "none logged"), timeout=60)
    try:
        topics = [str(x) for x in json.loads(tq[tq.find("["):tq.rfind("]") + 1])][:2]
    except Exception:
        topics = ["python long-running telegram bot resilience retry backoff best practice",
                  "python service self-healing error handling pattern"]
    research = ""
    for t in topics:
        try:
            rs = web_search(t) or []
            research += "\n[" + t + "]\n" + "\n".join("- " + (r.get("title", "") + ": " + r.get("body", "")[:180])
                                                      for r in rs[:3])
        except Exception:
            pass
    src = _self_read()
    funcs = [n for n in _top_def_names(src) if n not in _UNEDITABLE]
    prop = _mm_brain("You are Nemo improving YOURSELF, grounded in this web research and my recent errors. Propose the "
                     "SINGLE highest-value, LOW-RISK improvement to ONE of my EXISTING functions. It must NOT touch "
                     "security, secrets, money/trading, or self-modification. Reply ONLY JSON: "
                     '{"function":"exact existing function name from the list","change":"the precise change in one '
                     'sentence","why":"the concrete benefit","source":"which web finding inspired it"}\n\n'
                     "My editable functions:\n" + ", ".join(funcs[:400]) + "\n\nWeb research:\n" + research[:2500] +
                     "\n\nMy recent errors:\n" + (errs or "none"), timeout=120)
    try:
        p = json.loads(prop[prop.find("{"):prop.rfind("}") + 1])
        fn = str(p.get("function", "")).strip()
    except Exception:
        send_text(chat_id, "\U0001F331 No solid proposal formed this round - I'll try again next cycle.")
        return
    SELFGROW["last"] = time.time()
    if fn not in funcs:
        send_text(chat_id, "\U0001F331 Researched idea (no safe single-function target this round, so nothing to apply):\n"
                  + str(p.get("change", "")) + "\nWhy: " + str(p.get("why", "")) +
                  "\nSource: " + str(p.get("source", "")))
        return
    try:
        v11_audit("selfgrow.propose", fn + ": " + str(p.get("change", ""))[:100])
    except Exception:
        pass
    send_text(chat_id, "\U0001F331 SELF-GROW proposal (from my own web research):\n"
              "• Target: " + fn + "()\n• Change: " + str(p.get("change", "")) + "\n• Why: " + str(p.get("why", "")) +
              "\n• Inspired by: " + str(p.get("source", "")) +
              "\n\nDrafting it through my supervised editor now (compile-check → you tap Apply → backup → /rollback)...")
    self_upgrade(chat_id, "Improve the function " + fn + ": " + str(p.get("change", "")))   # proven safe path


def _selfgrow_tick():
    while True:
        try:
            time.sleep(3600)
            if SELFGROW.get("auto") and OWNER.get("id") and not mm_locked() \
                    and time.time() - SELFGROW.get("last", 0) > 6.5 * 86400:
                selfgrow(OWNER["id"], auto=True)
        except Exception:
            pass


def _start_selfgrow():
    try:
        SELFGROW["auto"] = (_sec_get("selfgrow_auto", "") == "1")
    except Exception:
        pass
    threading.Thread(target=_selfgrow_tick, daemon=True).start()


_V11_CMD = re.compile(r"/(status|decision|decisions|decisionreview|counterfactual|biascheck|board|redteam|predict|"
                      r"forecast|radar|opportunity|simulate|businesssim|chief|taskgraph|contradictions|verify|"
                      r"permissions|constitution|why|agenthealth|auditchain|selfgrow)(\s|$)")


def _v11_dispatch(chat_id, text, msg):
    """NEMO OS v11 phases 2-10 command router (owner-only, exact-word gate)."""
    try:
        low = (text or "").strip().lower()
        m = _V11_CMD.match(low)
        if not m:
            return False
        if chat_id != OWNER.get("id"):
            send_text(chat_id, "Owner-only.")
            return True
        cmd = m.group(1)
        rest = text.split(None, 1)[1].strip() if len(text.split(None, 1)) > 1 else ""
        if cmd == "status":
            send_text(chat_id, v11_status())
        elif cmd in ("decision", "decisions"):
            _v11_decisions(chat_id, rest, low)
        elif cmd == "decisionreview":
            threading.Thread(target=decision_review, args=(chat_id,), daemon=True).start()
        elif cmd == "counterfactual":
            if rest.strip().isdigit():
                threading.Thread(target=counterfactual, args=(chat_id, int(rest)), daemon=True).start()
            else:
                send_text(chat_id, "Usage: /counterfactual <decision id>   (/decisions shows ids)")
        elif cmd == "biascheck":
            threading.Thread(target=bias_check, args=(chat_id, rest), daemon=True).start()
        elif cmd in ("board", "redteam"):
            if rest:
                threading.Thread(target=board_run, args=(chat_id, rest), daemon=True).start()
            else:
                send_text(chat_id, "Usage: /board Should I invest in the CBG plant?  (5 seats + red team + judge)")
        elif cmd in ("predict", "forecast"):
            if rest:
                threading.Thread(target=predict_run, args=(chat_id, rest), daemon=True).start()
            else:
                send_text(chat_id, "Usage: /predict will cement prices rise this quarter?")
        elif cmd == "radar":
            _v11_radar(chat_id, rest)
        elif cmd == "opportunity":
            threading.Thread(target=opportunity_run, args=(chat_id, rest or "my current situation"), daemon=True).start()
        elif cmd in ("simulate", "businesssim"):
            if rest:
                threading.Thread(target=businesssim_cmd, args=(chat_id, rest), daemon=True).start()
            else:
                send_text(chat_id, "Usage: /businesssim capex 60 lakh, revenue 8 lakh/month, cost 5 lakh/month")
        elif cmd == "chief":
            chief_brief(chat_id)
        elif cmd == "taskgraph":
            _v11_taskgraph(chat_id, rest)
        elif cmd == "contradictions":
            threading.Thread(target=_v11_contradictions, args=(chat_id, rest), daemon=True).start()
        elif cmd == "verify":
            _v11_verify(chat_id, rest)
        elif cmd == "permissions":
            try:
                lk = mm_locked()
            except Exception:
                lk = False
            send_text(chat_id, "\U0001F510 PERMISSION LEVELS (zero-trust):\n" + PERM_LEVELS +
                      "\n\nLockdown: " + ("ON \U0001F512" if lk else "off") +
                      " · /caps controls powers · money + self-modification always need your tap.")
        elif cmd == "constitution":
            send_text(chat_id, CONSTITUTION)
        elif cmd == "why":
            _v11_why(chat_id, rest)
        elif cmd == "agenthealth":
            st = AGENTSTAT.get(chat_id, {})
            send_text(chat_id, "\U0001F916 AGENT HEALTH\nSpecialists: " +
                      (", ".join(n + " (" + str(v.get("jobs", 0)) + " jobs)" for n, v in list(st.items())[:8]) or "none yet") +
                      "\nv11: boards " + str(V11_STATS["boards"]) + " · decisions " + str(V11_STATS["decisions"]) +
                      " · sims " + str(V11_STATS["sims"]) + " · predictions " + str(V11_STATS["predictions"]) +
                      " · radar reports " + str(V11_STATS["radar_reports"]))
        elif cmd == "auditchain":
            ok, n, tot = v11_audit_verify()
            send_text(chat_id, "\U0001F517 Audit chain: " + ("INTACT ✅ - " + str(tot) + " events, every hash verifies"
                      if ok else "⚠ BROKEN at row " + str(n) + "/" + str(tot) + " - possible tampering"))
        elif cmd == "selfgrow":
            sub = rest.lower().strip()
            if sub in ("auto on", "auto"):
                SELFGROW["auto"] = True
                try:
                    save_secret("selfgrow_auto", "1")
                except Exception:
                    pass
                send_text(chat_id, "\U0001F331 Auto self-grow ON - about weekly I'll research the web and PROPOSE one "
                          "improvement (you still tap Apply; I never self-apply to my core - spec §22). /selfgrow auto off to stop.")
            elif sub == "auto off":
                SELFGROW["auto"] = False
                try:
                    save_secret("selfgrow_auto", "0")
                except Exception:
                    pass
                send_text(chat_id, "\U0001F331 Auto self-grow OFF. /selfgrow still runs one cycle on demand.")
            elif sub == "status":
                send_text(chat_id, "\U0001F331 Self-grow: auto " + ("ON" if SELFGROW.get("auto") else "off") +
                          " · last run " + (_kg_when(SELFGROW["last"]) if SELFGROW.get("last") else "never") +
                          "\nI research the web for improvements and propose them through the supervised editor "
                          "(you approve). I never rewrite my core or apply without your tap.")
            else:
                threading.Thread(target=selfgrow, args=(chat_id,), daemon=True).start()
        return True
    except Exception as e:
        send_text(chat_id, "v11 error: " + str(e)[:150])
        return True


# ---------------- PROJECT BUILDER: Nemo builds whole MULTI-FILE projects (plan -> generate -> test -> repair -> zip) ----------------
PROJECTS_DIR = "/root/nemo_projects"


def _proj_dir(name):
    return os.path.join(PROJECTS_DIR, re.sub(r"[^a-z0-9_\-]", "", (name or "").lower())[:40] or "project")


def _proj_zip(pdir, name):
    import zipfile
    z = "/tmp/" + (re.sub(r"[^a-z0-9_\-]", "", (name or "").lower())[:30] or "project") + ".zip"
    try:
        with zipfile.ZipFile(z, "w", zipfile.ZIP_DEFLATED) as zf:
            for root, _, fs in os.walk(pdir):
                for fn in fs:
                    fp = os.path.join(root, fn)
                    zf.write(fp, os.path.relpath(fp, pdir))
        return z
    except Exception:
        return ""


def _proj_run_tests(pdir, test_cmd):
    import subprocess
    try:
        r = subprocess.run(test_cmd, shell=True, cwd=pdir, capture_output=True, text=True, timeout=180)
        return r.returncode == 0, ((r.stdout or "") + (r.stderr or ""))[-2500:]
    except Exception as e:
        return False, "test run error: " + str(e)[:300]


def build_project(chat_id, name, description):
    """Build a whole MULTI-FILE project: plan a file manifest -> generate each file -> install deps ->
    run tests -> self-repair on failure -> zip & deliver. This is how Nemo creates 'vast things', not one script."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner-only.")
        return
    if not cap_ok("deploy"):
        send_text(chat_id, "Turn on the build power once: /caps deploy on")
        return
    pdir = _proj_dir(name)
    send_text(chat_id, "\U0001F3D7 Planning project '" + name + "'... (I'll plan the files, write them, install deps, "
              "run tests, and fix failures myself.)")
    plan_raw = _mm_brain(
        "You are a senior engineer. Plan a small, COMPLETE, runnable Python project for:\n" + description +
        "\n\nReply ONLY JSON: {\"requires\":[\"pip pkgs\"],\"files\":[{\"path\":\"app.py\",\"purpose\":\"...\"},"
        "{\"path\":\"test_app.py\",\"purpose\":\"tests that verify the core with plain asserts\"}],"
        "\"test_cmd\":\"python3 test_app.py\"}. 2-6 files, ALWAYS include a test file, only widely-available packages, "
        "and prefer plain-assert tests runnable with 'python3 <file>'.", timeout=120)
    try:
        man = json.loads(plan_raw[plan_raw.find("{"):plan_raw.rfind("}") + 1])
        files = [f for f in man.get("files", []) if f.get("path")][:8]
        requires = [str(r) for r in man.get("requires", [])][:15]
        test_cmd = str(man.get("test_cmd") or "python3 -m pytest -q")
    except Exception:
        send_text(chat_id, "I couldn't plan that project cleanly - try describing it more specifically.")
        return
    if not files:
        send_text(chat_id, "No files planned - try a clearer description.")
        return
    if "pytest" in test_cmd and "pytest" not in requires:
        requires.append("pytest")
    send_text(chat_id, "\U0001F4D0 Plan - " + str(len(files)) + " files:\n" +
              "\n".join("• " + f["path"] + " - " + f.get("purpose", "")[:60] for f in files) +
              (("\nDeps: " + ", ".join(requires)) if requires else ""))
    os.makedirs(pdir, exist_ok=True)
    written = {}
    for f in files:
        others = "\n".join("- " + o["path"] + ": " + o.get("purpose", "") for o in files if o["path"] != f["path"])
        code = _strip_fence(_mm_brain(
            "Write the COMPLETE contents of file '" + f["path"] + "' for this project:\n" + description +
            "\n\nThis file's job: " + f.get("purpose", "") + "\nOther files:\n" + others +
            "\n\nOutput ONLY the raw file contents - no markdown, no commentary.", timeout=180))
        try:
            open(os.path.join(pdir, os.path.basename(f["path"])), "w").write(code)   # flat + basename = no path traversal
            written[f["path"]] = code
        except Exception:
            pass
    if requires:
        try:
            open(os.path.join(pdir, "requirements.txt"), "w").write("\n".join(requires))
            _pip_install(requires)
        except Exception:
            pass
    ok, out = _proj_run_tests(pdir, test_cmd)
    fixes = 0
    while not ok and fixes < 2:
        fixes += 1
        send_text(chat_id, "\U0001F527 Tests failed - fixing myself (try " + str(fixes) + "/2)...")
        filelist = "\n".join("### " + p + "\n" + c[:1500] for p, c in written.items())
        fix_raw = _mm_brain("This project fails its tests. Fix it.\nTest output:\n" + out[-1800:] +
                            "\n\nCurrent files:\n" + filelist + "\n\nReply ONLY JSON: "
                            "{\"path\":\"the ONE file to rewrite\",\"content\":\"the full corrected file contents\"}",
                            timeout=180)
        try:
            fx = json.loads(fix_raw[fix_raw.find("{"):fix_raw.rfind("}") + 1])
            fp = os.path.basename(str(fx["path"]))
            open(os.path.join(pdir, fp), "w").write(fx["content"])
            written[str(fx["path"])] = fx["content"]
        except Exception:
            break
        ok, out = _proj_run_tests(pdir, test_cmd)
    z = _proj_zip(pdir, name)
    if z and os.path.exists(z):
        send_document(chat_id, z, (re.sub(r"[^a-z0-9_\-]", "", name.lower())[:30] or "project") + ".zip", "application/zip")
    send_text(chat_id, "\U0001F3C1 Project '" + name + "': " +
              ("✅ built and tests PASS" if ok else "⚠️ built, but tests not fully passing after " + str(fixes) + " fixes") +
              "\nFiles: " + ", ".join(written.keys()) +
              ("\n\nLast test output:\n" + out[-500:] if not ok else "") +
              "\n\nThe files are on your server at " + pdir + ". /projects lists all · /project " + name + " zip re-sends it.")


def _proj_dispatch(chat_id, text, msg):
    """Project builder commands (owner-only). /project <name>: <what> · /projects · /project <name> zip"""
    try:
        low = (text or "").strip().lower()
        if not (low.startswith("/project") or low.startswith("/projects")):
            return False
        if chat_id != OWNER.get("id"):
            send_text(chat_id, "Owner-only.")
            return True
        if low.startswith("/projects"):
            names = []
            try:
                names = sorted(n for n in os.listdir(PROJECTS_DIR) if os.path.isdir(os.path.join(PROJECTS_DIR, n)))
            except Exception:
                pass
            send_text(chat_id, ("\U0001F3D7 Your projects:\n" + "\n".join("• " + n for n in names) +
                      "\n\n/project <name> zip to download one") if names else
                      "No projects yet. Build one:\n/project jokeapi: a Flask API that returns a random joke, with tests")
            return True
        rest = text.split(None, 1)[1].strip() if len(text.split(None, 1)) > 1 else ""
        if ":" in rest:
            name, desc = rest.split(":", 1)
            name, desc = name.strip(), desc.strip()
            if not name or not desc:
                send_text(chat_id, "Give a name AND a description:\n/project jokeapi: a Flask API that returns a random joke, with tests")
                return True
            threading.Thread(target=build_project, args=(chat_id, name, desc), daemon=True).start()
        else:
            parts = rest.split()
            if len(parts) >= 2 and parts[1].lower() == "zip":
                z = _proj_zip(_proj_dir(parts[0]), parts[0])
                if z and os.path.exists(z):
                    send_document(chat_id, z, parts[0] + ".zip", "application/zip")
                else:
                    send_text(chat_id, "No such project. /projects lists them.")
            else:
                send_text(chat_id, "Usage:\n/project <name>: <what to build>  - a whole multi-file project + tests\n"
                          "/projects  - list them\n/project <name> zip  - download one")
        return True
    except Exception as e:
        send_text(chat_id, "Project builder error: " + str(e)[:150])
        return True


# ---------------- BOT FACTORY: a library of ready-made bot types Nemo can ship + modify ----------------
# Each template is a complete, standalone Telegram bot. {{BUSINESS}} is filled at build time; it ships through
# the SAME supervised pipeline as /ship (compile-check -> env -> tap-to-start) and is editable via /app <name> edit.
_TPL_FAQ = r"""# requires: requests
import os, time, json, requests
TOKEN = os.environ.get("BOT_TOKEN", ""); OWNER = os.environ.get("OWNER_ID", "")
API = "https://api.telegram.org/bot" + TOKEN
BUSINESS = "{{BUSINESS}}"
FAQS = {"timing": "We're open 10am-8pm, Mon-Sat.",
        "location": "Search '" + BUSINESS + "' on Google Maps to find us.",
        "price": "Tell us what you need and we'll share a quote.",
        "contact": "Reply here and our team will get back to you shortly."}
def send(cid, t):
    try: requests.post(API + "/sendMessage", json={"chat_id": cid, "text": t}, timeout=20)
    except Exception: pass
def main():
    if not TOKEN: print("Set BOT_TOKEN via /env"); return
    off = 0
    while True:
        try:
            r = requests.get(API + "/getUpdates", params={"offset": off, "timeout": 50}, timeout=60).json()
            for u in r.get("result", []):
                off = u["update_id"] + 1
                m = u.get("message") or {}; cid = (m.get("chat") or {}).get("id"); txt = (m.get("text") or "")
                if not cid: continue
                if txt.startswith("/start"):
                    send(cid, "Hi! Welcome to " + BUSINESS + ". Ask me about our timing, location, price or contact.")
                    continue
                low = txt.lower(); hit = None
                for k, v in FAQS.items():
                    if k in low: hit = v; break
                if hit: send(cid, hit)
                else:
                    send(cid, "Thanks for messaging " + BUSINESS + "! A team member will reply soon. "
                          "You can ask about: timing, location, price, contact.")
                    if OWNER and str(cid) != str(OWNER): send(OWNER, "New msg on " + BUSINESS + " bot:\n" + txt)
        except Exception: time.sleep(3)
main()
"""

