_TPL_YTDL = r"""# requires: requests yt-dlp
# {{BUSINESS}} - YouTube video/playlist downloader bot (from Nemo's factory, v13.10).
# Token/owner come ONLY from env (/env <name> BOT_TOKEN=... OWNER_ID=...). Sends files under
# Telegram's ~50MB bot cap; bigger ones are kept on the server and the path is reported.
# Only download content you own or are permitted to; DRM streams are not supported.
import os, re, time, threading, shutil, tempfile
from pathlib import Path
import requests

TOKEN = os.environ.get("BOT_TOKEN", "")
OWNER = os.environ.get("OWNER_ID", "").strip()
API = "https://api.telegram.org/bot" + TOKEN
MAXV = int(os.environ.get("MAX_VIDEOS", "25"))
DL = Path(os.environ.get("DOWNLOAD_ROOT", "") or (os.path.join(os.getcwd(), "downloads")))
LIMIT = 49 * 1024 * 1024
YT = re.compile(r"https?://(?:www\.|m\.|music\.)?(?:youtube\.com/(?:playlist\?[^ ]*\blist=|watch\?|shorts/)|youtu\.be/)[^ ]+", re.I)

def send(cid, t):
    try: requests.post(API + "/sendMessage", json={"chat_id": cid, "text": t[:4000]}, timeout=30)
    except Exception: pass

def send_file(cid, path, audio=False):
    try:
        with open(path, "rb") as fh:
            which = "sendAudio" if audio else "sendDocument"
            field = "audio" if audio else "document"
            r = requests.post(API + "/" + which, data={"chat_id": cid, "caption": os.path.basename(path)[:200]},
                              files={field: (os.path.basename(path), fh)}, timeout=600)
        return bool(r.ok and r.json().get("ok"))
    except Exception:
        return False

def grab(cid, url, audio):
    import yt_dlp
    DL.mkdir(parents=True, exist_ok=True)
    tmp = Path(tempfile.mkdtemp(prefix="job_", dir=str(DL)))
    opts = {"outtmpl": str(tmp / "%(playlist_index|)s%(playlist_index&_|)s%(title).120B.%(ext)s"),
            "restrictfilenames": True, "no_overwrites": True, "ignoreerrors": True,
            "quiet": True, "no_warnings": True, "playlistend": MAXV,
            "socket_timeout": 30, "retries": 5, "fragment_retries": 5,
            "concurrent_fragment_downloads": 4}
    if audio:
        opts["format"] = "bestaudio/best"
        opts["postprocessors"] = [{"key": "FFmpegExtractAudio", "preferredcodec": "mp3", "preferredquality": "192"}]
    else:
        opts["format"] = "bv*+ba/b"
        opts["merge_output_format"] = "mp4"
    rc = 0
    try:
        with yt_dlp.YoutubeDL(opts) as y:
            rc = y.download([url])          # int exit code (0 = clean)
    except Exception as e:
        send(cid, "Download error: " + str(e)[:300])
    files = sorted(p for p in tmp.iterdir() if p.is_file())
    if not files:
        send(cid, "No files came out - the link may be private, removed, or region-blocked.")
        shutil.rmtree(tmp, ignore_errors=True); return
    send(cid, "Got " + str(len(files)) + " file(s). Sending the ones under 50MB...")
    sent = kept = 0
    for f in files:
        if f.stat().st_size <= LIMIT and send_file(cid, str(f), audio):
            sent += 1
        else:
            final = DL / f.name
            try: f.replace(final)
            except Exception: final = f
            kept += 1
            send(cid, f.name + " is " + str(round(f.stat().st_size / 1e6) if f.exists() else round(final.stat().st_size / 1e6)) +
                 "MB (over Telegram's cap) - saved on the server:\n" + str(final))
    shutil.rmtree(tmp, ignore_errors=True)
    done = "Done - sent " + str(sent) + " file(s)" + (", kept " + str(kept) + " large on the server" if kept else "")
    if rc: done += " (some items were skipped: private/removed)"
    send(cid, done + ".")

def main():
    if not TOKEN: print("Set BOT_TOKEN via /env"); return
    if not OWNER: print("WARNING: OWNER_ID not set - ANYONE can use this bot. Set it via /env.")
    off = 0
    while True:
        try:
            r = requests.get(API + "/getUpdates", params={"offset": off, "timeout": 50}, timeout=60).json()
            for u in r.get("result", []):
                off = u["update_id"] + 1
                m = u.get("message") or {}; cid = (m.get("chat") or {}).get("id"); txt = (m.get("text") or "").strip()
                if not cid or not txt: continue
                if OWNER and str(cid) != OWNER:
                    send(cid, "Sorry - this is a private bot."); continue
                low = txt.lower()
                if low.startswith("/start"):
                    send(cid, "{{BUSINESS}} downloader ready.\n\n/download <YouTube video or playlist URL> - mp4\n"
                         "/download <URL> audio - mp3 only\n\nUp to " + str(MAXV) + " items per playlist. Files under "
                         "~50MB come to you here; bigger ones are saved on the server.")
                elif low.startswith("/download"):
                    parts = txt.split()
                    url = parts[1] if len(parts) > 1 else ""
                    audio = any(a.lower() in ("audio", "--audio", "mp3") for a in parts[2:])
                    if not YT.search(url):
                        send(cid, "That doesn't look like a YouTube video/playlist link. Paste the full URL after /download.")
                    else:
                        send(cid, "Starting - big playlists can take a while...")
                        threading.Thread(target=grab, args=(cid, url, audio), daemon=True).start()
                else:
                    send(cid, "Commands: /start  ·  /download <url> [audio]")
        except Exception:
            time.sleep(3)

main()
"""

BOT_TEMPLATES = {
    "ytdl": {"title": "YouTube / playlist downloader bot", "env": ["BOT_TOKEN", "OWNER_ID"],
             "commands": "/download <url> [audio]",
             "desc": "downloads a YouTube video or whole playlist (mp4, or mp3 with 'audio') and sends the files; "
                     "under-50MB files arrive in chat, bigger ones are saved on the server",
             "code": _TPL_YTDL},
    "faq": {"title": "FAQ / auto-reply bot", "env": ["BOT_TOKEN", "OWNER_ID"], "commands": "/start",
            "desc": "answers common customer questions, forwards anything else to the owner",
            "code": _TPL_FAQ},
    "booking": {"title": "Appointment booking bot", "env": ["BOT_TOKEN", "OWNER_ID"], "commands": "/book",
                "desc": "takes appointments (service -> date/time -> name -> phone) and pings the owner",
                "code": _TPL_BOOKING},
    "order": {"title": "Order / catalogue bot", "env": ["BOT_TOKEN", "OWNER_ID"], "commands": "/menu",
              "desc": "shows a menu, takes orders with address + phone, totals it and alerts the owner",
              "code": _TPL_ORDER},
    "broadcast": {"title": "Subscribe & broadcast bot", "env": ["BOT_TOKEN", "OWNER_ID"], "commands": "/subscribe /broadcast",
                  "desc": "users subscribe; the owner broadcasts updates to everyone with /broadcast",
                  "code": _TPL_BROADCAST},
    "feedback": {"title": "Feedback / rating bot", "env": ["BOT_TOKEN", "OWNER_ID"], "commands": "/feedback /summary",
                 "desc": "collects 1-5 star ratings + comments; owner sees the average with /summary",
                 "code": _TPL_FEEDBACK},
}


def bt_render(tkey, business=""):
    """Fill a template with the business name. Returns runnable standalone bot code (or '')."""
    t = BOT_TEMPLATES.get(tkey)
    if not t:
        return ""
    biz = (business or "Our Business").replace('"', "'").replace("\n", " ").strip()[:60] or "Our Business"
    return t["code"].strip().replace("{{BUSINESS}}", biz)


def bt_build(chat_id, name, tkey, business=""):
    """Scaffold a bot of the given type from the factory library and ship it (supervised)."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner-only.")
        return
    t = BOT_TEMPLATES.get(tkey)
    if not t:
        send_text(chat_id, "Unknown type '" + str(tkey) + "'. /templates lists them.")
        return
    code = bt_render(tkey, business)
    send_text(chat_id, "\U0001F3ED Building a " + t["title"] + " named '" + name + "'" +
              ((" for " + business) if business else "") + " from the factory...\n"
              "After it ships, set its token:  /env " + name + " BOT_TOKEN=<from @BotFather> OWNER_ID=<your id>")
    deploy_app(chat_id, name, code)      # same supervised ship pipeline as /ship


def _bf_dispatch(chat_id, text, msg):
    """Bot Factory commands (owner-only). Returns True if consumed.
    /templates  ·  /template <type>  ·  /newbot <type> <name> [: business]"""
    try:
        low = (text or "").strip().lower()
        if not (low.startswith("/templates") or low.startswith("/newbot") or low.startswith("/template ")):
            return False
        if chat_id != OWNER.get("id"):
            send_text(chat_id, "Owner-only.")
            return True
        if low.startswith("/templates"):
            lines = ["\U0001F3ED BOT FACTORY - ready-made bot types (each ships as a live 24/7 bot):"]
            for k, t in BOT_TEMPLATES.items():
                lines.append("• " + k + " - " + t["title"] + ": " + t["desc"])
            lines.append("\nBuild one:  /newbot booking clinicbot : Dr Sharma Clinic")
            lines.append("Then set its token:  /env <name> BOT_TOKEN=<@BotFather token> OWNER_ID=<your id>")
            lines.append("Modify it anytime:  /app <name> edit <what to change>")
            send_text(chat_id, "\n".join(lines))
            return True
        if low.startswith("/template "):
            k = text.split(None, 1)[1].strip().lower()
            t = BOT_TEMPLATES.get(k)
            if not t:
                send_text(chat_id, "No template '" + k + "'. /templates lists them.")
            else:
                send_text(chat_id, "\U0001F3ED " + t["title"] + "\n" + t["desc"] + "\n\nBot commands: " + t["commands"] +
                          "\nNeeds env: " + ", ".join(t["env"]) + "\n\nBuild it:  /newbot " + k + " <name> : <business>")
            return True
        rest = text.split(None, 1)[1].strip() if len(text.split(None, 1)) > 1 else ""
        if not rest:
            send_text(chat_id, "Usage:  /newbot <type> <name> : <business>\nTypes: " + ", ".join(BOT_TEMPLATES) +
                      "   (see /templates)")
            return True
        business = ""
        if ":" in rest:
            rest, business = rest.split(":", 1)
            business = business.strip()
            rest = rest.strip()
        parts = rest.split()
        if len(parts) < 2:
            send_text(chat_id, "Give a type AND a name:  /newbot faq shopbot : My Shop\nTypes: " + ", ".join(BOT_TEMPLATES))
            return True
        bt_build(chat_id, parts[1], parts[0].lower(), business)
        return True
    except Exception as e:
        send_text(chat_id, "Bot factory error: " + str(e)[:150])
        return True


# ---------------- GOOGLE MAPS layer (reuses the Phase-2 Cloud key + daily safety cap) ----------------
MAPS_BASE = "https://maps.googleapis.com/maps/api"


def _stars(r):
    if not r:
        return ""
    try:
        f = int(round(float(r)))
    except Exception:
        return str(r)
    return "⭐" * max(0, min(5, f)) + " " + str(r)


def _maps_get(path, params, timeout=30):
    """GET a Maps Platform endpoint with the shared Cloud key + daily cap. Returns (json, err)."""
    ok, err = _gai_ok()
    if not ok:
        return None, err
    try:
        p = dict(params or {})
        p["key"] = GAI["key"]
        j = requests.get(MAPS_BASE + path, params=p, timeout=timeout).json()
        st = j.get("status", "OK")
        if st not in ("OK", "ZERO_RESULTS"):
            return None, "Maps: " + st + ((" - " + j.get("error_message", "")) if j.get("error_message") else "")
        return j, ""
    except Exception as e:
        return None, type(e).__name__ + ": " + str(e)[:150]


def _places_new(path, body=None, field_mask="", method="POST", timeout=30):
    """Call Places API (New) with the shared key + daily cap. Returns (json, err)."""
    ok, err = _gai_ok()
    if not ok:
        return None, err
    try:
        headers = {"X-Goog-Api-Key": GAI["key"], "X-Goog-FieldMask": field_mask, "Content-Type": "application/json"}
        url = "https://places.googleapis.com/v1/" + path
        r = requests.post(url, json=body, headers=headers, timeout=timeout) if method == "POST" \
            else requests.get(url, headers=headers, timeout=timeout)
        j = r.json()
        if r.status_code != 200:
            e = j.get("error", {}) if isinstance(j, dict) else {}
            return None, "PlacesNew:" + str(e.get("status") or r.status_code)
        return j, ""
    except Exception as e:
        return None, type(e).__name__ + ": " + str(e)[:120]


def maps_find(query, limit=5):
    """Text search for places / stores / shops. Places API (New) first, legacy fallback. Returns (list, err)."""
    fm = ("places.id,places.displayName,places.formattedAddress,places.rating,"
          "places.userRatingCount,places.location,places.currentOpeningHours.openNow")
    j, err = _places_new("places:searchText", {"textQuery": query, "maxResultCount": max(1, min(limit, 10))}, fm)
    if j is not None and "places" in j:
        out = []
        for r in (j.get("places") or [])[:limit]:
            loc = r.get("location") or {}
            out.append({"name": (r.get("displayName") or {}).get("text", ""),
                        "address": r.get("formattedAddress", ""), "rating": r.get("rating"),
                        "count": r.get("userRatingCount"), "place_id": r.get("id", ""),
                        "open": (r.get("currentOpeningHours") or {}).get("openNow"),
                        "lat": loc.get("latitude"), "lng": loc.get("longitude")})
        return out, ""
    j2, err2 = _maps_get("/place/textsearch/json", {"query": query})     # legacy fallback
    if not j2:
        return None, err or err2
    out = []
    for r in (j2.get("results") or [])[:limit]:
        loc = (r.get("geometry") or {}).get("location", {})
        out.append({"name": r.get("name", ""), "address": r.get("formatted_address", ""),
                    "rating": r.get("rating"), "count": r.get("user_ratings_total"),
                    "place_id": r.get("place_id", ""), "open": (r.get("opening_hours") or {}).get("open_now"),
                    "lat": loc.get("lat"), "lng": loc.get("lng")})
    return out, ""


def maps_details(place_id):
    """Full place details + up to 5 reviews. Places API (New) first, legacy fallback. Returns (dict, err)."""
    fm = ("displayName,formattedAddress,nationalPhoneNumber,internationalPhoneNumber,rating,"
          "userRatingCount,currentOpeningHours,websiteUri,googleMapsUri,location,reviews")
    j, err = _places_new("places/" + place_id, None, fm, method="GET")
    if j is not None and (j.get("displayName") or j.get("formattedAddress")):
        oh = j.get("currentOpeningHours") or {}
        loc = j.get("location") or {}
        reviews = []
        for rv in (j.get("reviews") or [])[:5]:
            reviews.append({"author_name": (rv.get("authorAttribution") or {}).get("displayName", ""),
                            "rating": rv.get("rating"),
                            "text": (rv.get("text") or {}).get("text", "") or (rv.get("originalText") or {}).get("text", ""),
                            "relative_time_description": rv.get("relativePublishTimeDescription", "")})
        return {"name": (j.get("displayName") or {}).get("text", ""), "formatted_address": j.get("formattedAddress", ""),
                "formatted_phone_number": j.get("nationalPhoneNumber") or j.get("internationalPhoneNumber", ""),
                "rating": j.get("rating"), "user_ratings_total": j.get("userRatingCount"),
                "opening_hours": {"open_now": oh.get("openNow")}, "website": j.get("websiteUri", ""),
                "url": j.get("googleMapsUri", ""),
                "geometry": {"location": {"lat": loc.get("latitude"), "lng": loc.get("longitude")}},
                "reviews": reviews}, ""
    j2, err2 = _maps_get("/place/details/json", {                        # legacy fallback
        "place_id": place_id,
        "fields": "name,formatted_address,formatted_phone_number,rating,user_ratings_total,"
                  "opening_hours,website,url,reviews,geometry"})
    if not j2:
        return None, err or err2
    return j2.get("result") or {}, ""


def maps_trip(origin, dest, mode="driving"):
    """Real road distance + time (live traffic for driving). Returns (dict, err)."""
    params = {"origin": origin, "destination": dest, "mode": mode}
    if mode == "driving":
        params["departure_time"] = "now"          # unlocks duration_in_traffic
    j, err = _maps_get("/directions/json", params)
    if not j or not j.get("routes"):
        return None, err or "No route found between those two places."
    route = j["routes"][0]
    leg = route["legs"][0]
    return {"from": leg.get("start_address", origin), "to": leg.get("end_address", dest),
            "distance": (leg.get("distance") or {}).get("text", "?"),
            "duration": (leg.get("duration") or {}).get("text", "?"),
            "traffic": (leg.get("duration_in_traffic") or {}).get("text", ""),
            "summary": route.get("summary", ""),
            "polyline": (route.get("overview_polyline") or {}).get("points", ""),
            "mode": mode}, ""


def maps_staticmap(markers=None, path_poly=None, center=None, zoom=None, size="640x400"):
    """PNG bytes of a map: a marker (place) and/or a route polyline (trip). Returns (bytes, err)."""
    ok, err = _gai_ok()
    if not ok:
        return None, err
    params = [("size", size), ("scale", "2"), ("key", GAI["key"])]
    for m in (markers or []):
        params.append(("markers", "color:red|" + str(m)))
    if path_poly:
        params.append(("path", "weight:4|color:0x1a73e8ff|enc:" + path_poly))
    if center:
        params.append(("center", str(center)))
    if zoom:
        params.append(("zoom", str(zoom)))
    try:
        r = requests.get(MAPS_BASE + "/staticmap", params=params, timeout=30)
        if r.status_code == 200 and "image" in r.headers.get("Content-Type", "") and len(r.content) > 800:
            return r.content, ""
        return None, "static map error " + str(r.status_code)
    except Exception as e:
        return None, type(e).__name__


def _maps_photo(chat_id, png, caption=""):
    try:
        requests.post(TG + "/sendPhoto", data={"chat_id": chat_id, "caption": caption[:1000]},
                      files={"photo": ("map.png", png, "image/png")}, timeout=60)
        return True
    except Exception:
        return False


def _maps_dispatch(chat_id, text, msg):
    """Google Maps commands (owner-only). Returns True if consumed.
    /place|/find <name>  ·  /near <what> in <where>  ·  /trip|/distance|/route <A> to <B>  ·
    /reviews <name>  ·  /map <place>  ·  /gmaps (status)."""
    try:
        low = (text or "").strip().lower()
        cmds = ("/place", "/find", "/near", "/trip", "/distance", "/route", "/reviews", "/map ", "/map\n", "/gmaps")
        if not (low.startswith(cmds) or low.strip() == "/map"):
            return False
        if chat_id != OWNER.get("id"):
            send_text(chat_id, "Owner-only.")
            return True
        arg = text.split(None, 1)[1].strip() if len(text.split(None, 1)) > 1 else ""

        if low.startswith("/gmaps"):
            _gai_load()
            send_text(chat_id, "\U0001F5FA Google Maps: key " +
                      ("set ✅" if GAI["key"] else "NOT set - send /gcloud <key> first") +
                      ".\nTry:  /place Blue Tokai Bandra   ·   /near cafes in Andheri   ·   "
                      "/trip Mumbai to Pune   ·   /reviews Phoenix Mall   ·   /map Gateway of India\n"
                      "Shares the Cloud key + daily cap (" + str(GAI["calls"]) + "/" + str(GAI["cap"]) + " today).")
            return True

        if not arg:
            send_text(chat_id, "Give me something: /place <name> · /trip <A> to <B> · /near <what> in <where>")
            return True

        # ---- trip / distance / route: real road km + time (+ traffic) + a route map ----
        if low.startswith(("/trip", "/distance", "/route")):
            def _tr():
                parts = re.split(r"\s+to\s+|\s*->\s*|\s+se\s+", arg, maxsplit=1, flags=re.I)
                if len(parts) < 2:
                    send_text(chat_id, "Two places please: /trip Mumbai to Pune")
                    return
                origin, dest, mode = parts[0].strip(), parts[1].strip(), "driving"
                for mm in ("walking", "bicycling", "transit"):
                    if dest.lower().endswith(" by " + mm):
                        mode, dest = mm, dest[: -len(" by " + mm)].strip()
                t, err = maps_trip(origin, dest, mode)
                if not t:
                    send_text(chat_id, "Trip error: " + err)
                    return
                body = ("\U0001F697 " + t["from"] + "\n➡️ " + t["to"] + "\n\n\U0001F4CF " + t["distance"] +
                        "   ·   ⏱ " + t["duration"] +
                        (("   ·   \U0001F6A6 " + t["traffic"] + " in traffic") if t["traffic"] else "") +
                        (("\nvia " + t["summary"]) if t["summary"] else "") +
                        ("\nmode: " + t["mode"] if t["mode"] != "driving" else ""))
                png, _ = maps_staticmap(path_poly=t.get("polyline"), markers=[origin, dest])
                _maps_photo(chat_id, png, body) if png else send_text(chat_id, body)
            threading.Thread(target=_tr, daemon=True).start()
            return True

        # ---- near / nearby: a ranked list of places ----
        if low.startswith("/near"):
            def _nr():
                res, err = maps_find(arg, limit=6)
                if not res:
                    send_text(chat_id, "Nothing found: " + (err or "no results"))
                    return
                lines = ["\U0001F4CD " + arg]
                for i, p in enumerate(res, 1):
                    rate = ("  " + _stars(p["rating"]) + ((" (" + str(p["count"]) + ")") if p["count"] else "")) if p["rating"] else ""
                    opn = "  \U0001F7E2" if p["open"] else ("  \U0001F534" if p["open"] is False else "")
                    lines.append(str(i) + ". " + p["name"] + rate + opn + "\n    " + p["address"])
                send_text(chat_id, "\n".join(lines))
            threading.Thread(target=_nr, daemon=True).start()
            return True

        # ---- place / find / reviews / map: top hit + details (+ reviews) + a map ----
        def _pl():
            res, err = maps_find(arg, limit=1)
            if not res:
                send_text(chat_id, "Couldn't find that: " + (err or "no results"))
                return
            top = res[0]
            det, _ = maps_details(top["place_id"]) if top.get("place_id") else ({}, "")
            det = det or {}
            name = det.get("name") or top["name"]
            addr = det.get("formatted_address") or top["address"]
            rating = det.get("rating") or top["rating"]
            cnt = det.get("user_ratings_total") or top["count"]
            oh = det.get("opening_hours") or {}
            summary = "\U0001F4CD " + name + "\n" + addr
            if rating:
                summary += "\n⭐ " + _stars(rating) + ((" · " + str(cnt) + " reviews") if cnt else "")
            if oh.get("open_now") is not None:
                summary += "\n" + ("\U0001F7E2 Open now" if oh["open_now"] else "\U0001F534 Closed now")
            if det.get("formatted_phone_number"):
                summary += "\n\U0001F4DE " + det["formatted_phone_number"]
            if det.get("website"):
                summary += "\n\U0001F310 " + det["website"]
            if det.get("url"):
                summary += "\n\U0001F5FA " + det["url"]
            g = (det.get("geometry") or {}).get("location") or {}
            lat, lng = g.get("lat", top.get("lat")), g.get("lng", top.get("lng"))
            png = None
            if lat and lng:
                png, _ = maps_staticmap(markers=[str(lat) + "," + str(lng)],
                                        center=str(lat) + "," + str(lng), zoom=15)
            _maps_photo(chat_id, png, summary) if png else send_text(chat_id, summary)
            # reviews (not for /map)
            if not low.startswith("/map"):
                revs = (det.get("reviews") or [])[:3]
                if revs:
                    out = "\U0001F4AC Top reviews - " + name
                    for rv in revs:
                        rt = (rv.get("text") or "").strip().replace("\n", " ")
                        if len(rt) > 260:
                            rt = rt[:260] + "…"
                        out += "\n\n" + _stars(rv.get("rating")) + " — " + (rv.get("author_name") or "") + \
                               (("  (" + rv.get("relative_time_description", "") + ")") if rv.get("relative_time_description") else "") + \
                               "\n" + rt
                    send_text(chat_id, out)
        threading.Thread(target=_pl, daemon=True).start()
        return True
    except Exception as e:
        send_text(chat_id, "Maps command error: " + str(e)[:150])
        return True



_BROWSER_AGENT_V13_ORIGINAL = browser_agent


# ==================== v13.13 MEDIA + HUMAN BROWSER + NETWORK SECURITY ====================
# Security principle: VPN/proxy profiles are user-supplied or official-client based. Never embed a public/private
# VPN credential in source. Protected tasks fail closed when the requested VPN route cannot be verified.
VIDEO_PENDING = {}
VPN_ROOT = "/root/nemo_vpn"
VPN_PROFILE_DIR = os.path.join(VPN_ROOT, "profiles")
VPN_STATE = {"profile": "", "mode": "", "connected": False, "verified": False, "last_ip": "", "last_check": 0.0}
try:
    os.makedirs(VPN_PROFILE_DIR, mode=0o700, exist_ok=True)
except Exception:
    pass


def _vpn_mask(s):
    s = str(s or "")
    return re.sub(r"(?i)(PrivateKey|PresharedKey|password|passwd|token)\s*=\s*[^\n]+", r"\1 = ***", s)


def _vpn_profiles():
    try:
        os.makedirs(VPN_PROFILE_DIR, mode=0o700, exist_ok=True)
        return sorted(os.path.splitext(x)[0] for x in os.listdir(VPN_PROFILE_DIR) if x.endswith(".conf") and os.path.isfile(os.path.join(VPN_PROFILE_DIR, x)))
    except Exception:
        return []


def _vpn_run(cmd, timeout=25):
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return r.returncode, (r.stdout or "").strip(), (r.stderr or "").strip()
    except Exception as e:
        return 127, "", type(e).__name__ + ": " + str(e)[:180]


def _vpn_public_ip():
    for u in ("https://api.ipify.org", "https://ifconfig.me/ip"):
        try:
            r = requests.get(u, timeout=12)
            ip = (r.text or "").strip().splitlines()[0][:80]
            if re.match(r"^[0-9a-fA-F:.]+$", ip):
                return ip
        except Exception:
            pass
    return ""


def _vpn_dns_check():
    # Lightweight resolver check. This does not claim a full DNS leak audit; it verifies DNS is functional.
    try:
        socket.gethostbyname("cloudflare.com")
        return True, "DNS resolution OK"
    except Exception as e:
        return False, "DNS resolution failed: " + str(e)[:100]


def vpn_verify(chat_id=None, require_connected=True):
    """Verify the active route. Conservative: no claim of privacy beyond checks actually performed."""
    ip = _vpn_public_ip()
    dns_ok, dns_msg = _vpn_dns_check()
    rc, out, err = _vpn_run(["wg", "show"], timeout=10) if shutil.which("wg") else (127, "", "wg not installed")
    wg_ok = (rc == 0 and bool(out.strip()))
    warp_ok = False
    if shutil.which("warp-cli"):
        rc2, out2, err2 = _vpn_run(["warp-cli", "status"], timeout=15)
