    connected = bool(ip) and (wg_ok or warp_ok or VPN_STATE.get("connected")) if require_connected else bool(ip)
    ok = bool(ip) and dns_ok and connected
    VPN_STATE.update({"verified": ok, "last_ip": ip, "last_check": time.time()})
    if ok and chat_id:
        send_text(chat_id, "🛡️ VPN/network verification PASSED\nPublic IP: " + ip + "\n" + dns_msg + "\nRoute: " + ("WireGuard" if wg_ok else "WARP" if warp_ok else "configured profile"))
    elif chat_id:
        send_text(chat_id, "🔴 VPN/network verification FAILED\nPublic IP: " + (ip or "unavailable") + "\n" + dns_msg + "\nI will not call this a protected route.")
    return ok, ip


