def video_download(chat_id, url, audio=False, quality="best"):
    """v13.13 universal media downloader. Uses yt-dlp for supported public media and the user's own cookies/proxy.
    It does not bypass DRM, authentication, CAPTCHA or access controls."""
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Only the Boss can download videos.")
        return
    m = re.search(r"https?://\S+", url or "")
    url = (m.group(0) if m else (url or "")).strip().strip("<>\"'")
    if not re.match(r"^https?://", url):
        send_text(chat_id, "Send a valid https:// video/media URL.")
        return
    if _VID_DRM.search(url):
        send_text(chat_id, "🔒 DRM-protected streaming detected. I won't bypass DRM. Non-DRM downloadable media is supported.")
        return
    if not _imp("yt_dlp", notify=False):
        send_text(chat_id, "🔧 Installing yt-dlp for the first run...")
        auto_install("yt_dlp", notify=False)
    os.makedirs("/root/nemo_code", exist_ok=True)
    tag = hashlib.sha256(url.encode()).hexdigest()[:12]
    tmpl = "/root/nemo_code/vid_" + tag + ".%(ext)s"
    if audio:
        fmt = "bestaudio/best"
        cmd = ["yt-dlp", "-f", fmt, "-x", "--audio-format", "mp3", "--no-playlist", "-o", tmpl, url]
    else:
        q = str(quality or "best").lower()
        if q.isdigit():
            fmt = "bestvideo[height<=" + q + "][ext=mp4]+bestaudio[ext=m4a]/best[height<=" + q + "][ext=mp4]/best"
        else:
            fmt = "bestvideo[ext=mp4]+bestaudio[ext=m4a]/best[ext=mp4]/best"
        cmd = ["yt-dlp", "-f", fmt, "--merge-output-format", "mp4", "--no-playlist", "-o", tmpl, url]
    if os.path.exists("/root/nemo_cookies.txt"): cmd[1:1] = ["--cookies", "/root/nemo_cookies.txt"]
    px = net_proxy()
    if px: cmd[1:1] = ["--proxy", px]
    ph = tg("sendMessage", chat_id=chat_id, text="⬇️ Downloading " + ("audio" if audio else (quality + "p video" if quality != "best" else "best practical video")) + " from " + _short_host(url) + "...")
    mid = ph.get("result", {}).get("message_id")
    rc, out, err = _vpn_run(cmd, timeout=1200)
    import glob
    files = [f for f in glob.glob("/root/nemo_code/vid_" + tag + ".*") if not f.endswith((".part", ".ytdl"))]
    files.sort(key=lambda f: os.path.getsize(f), reverse=True)
    if rc != 0 or not files:
        el = (err or out or "").lower()
        if any(w in el for w in ("login", "sign in", "private", "members-only", "cookies")):
            tip = "\nThis media needs YOUR logged-in session. Use /browsercookies with your own cookies; I won't bypass the login."
        elif any(w in el for w in ("drm", "encrypted")):
            tip = "\nThe media is DRM/encrypted and I won't bypass that protection."
        elif "unsupported url" in el:
            tip = "\nyt-dlp does not support this page. If it contains a direct non-DRM media URL, send that URL."
        else:
            tip = "\n" + ((err or out).strip().splitlines()[-1][:300] if (err or out).strip() else "No downloadable media found.")
        deliver(chat_id, mid, "❌ Download failed." + tip)
        return
    fpath = files[0]
    ok, meta = _video_safe_file(fpath)
    if not ok:
        deliver(chat_id, mid, "🔴 Downloaded file failed media validation: " + meta)
        try: os.remove(fpath)
        except Exception: pass
        return
    size = os.path.getsize(fpath)
    act_log("videodl", _short_host(url) + " -> " + os.path.basename(fpath) + " " + meta)
    if size <= 49 * 1024 * 1024:
        try:
            with open(fpath, "rb") as f:
                fld = "audio" if audio else "video"
                rr = requests.post(TG + "/send" + ("Audio" if audio else "Video"),
                                   data={"chat_id": chat_id, "caption": "🎬 " + os.path.basename(fpath) + "\n" + meta},
                                   files={fld: (os.path.basename(fpath), f)}, timeout=300)
            if rr.ok:
                deliver(chat_id, mid, "✅ Download complete: " + os.path.basename(fpath))
            else:
                deliver(chat_id, mid, "Downloaded but Telegram rejected the upload. Saved: " + fpath)
        except Exception:
            deliver(chat_id, mid, "Downloaded (~" + str(size // 1048576) + " MB) but Telegram could not receive it. Saved: " + fpath)
    else:
        deliver(chat_id, mid, "✅ Downloaded (~" + str(size // 1048576) + " MB). Too large for Telegram's current upload path; saved: " + fpath + "\n" + meta)
        try:
            if google_ready(): gdrive_upload(fpath, os.path.basename(fpath))
        except Exception: pass


