# ==================== v13.22 OFFLINE MIND + SPEED ROUTER + SYSTEMATIC RESPONSE UI ====================
# Goal: more useful knowledge without a network round-trip, much faster ordinary replies, and a consistent
# Telegram-native answer layout. No production dependency installs are required by this layer.
OFFLINE_BUILTINS = {
    "linux_basics": "Linux: inspect services with systemctl status; logs with journalctl; disk with df -h; memory with free -m; sockets with ss -lntup. Prefer least privilege, backups, and reversible changes.",
    "network_basics": "Networking: DNS maps names to addresses; TCP provides reliable streams; UDP is datagram-based; TLS authenticates/encrypts application traffic. 80 is commonly HTTP and 443 HTTPS. Never infer security only from an open/closed port.",
    "python_basics": "Python: isolate project dependencies in virtual environments, pin production versions, catch specific exceptions where possible, validate external input, and use pathlib/context managers for filesystem work.",
    "git_basics": "Git: commit small coherent changes, inspect git diff before commit, use branches for risky work, and never commit secrets. A revert creates a new inverse commit; reset rewrites local history and should be used carefully.",
    "sql_basics": "SQL: parameterize values instead of concatenating user input. Index columns used often in selective WHERE/JOIN clauses. Transactions provide atomic groups of changes; always test backup/restore, not only backup creation.",
    "security_basics": "Defensive security: patch exposed software, use MFA, restrict inbound ports, disable unused services, protect secrets with least privilege, monitor authentication logs, keep integrity baselines, and verify backups. Authorization is required before scanning systems you do not own.",
    "web_basics": "Web: HTTP is request/response; HTTPS is HTTP over TLS. Cookies maintain browser state and can be equivalent to login credentials. CORS is a browser policy, not an authentication system. Validate server-side even when the UI validates inputs.",
    "api_basics": "API reliability: use explicit connect/read timeouts, bounded retries with backoff for transient errors, idempotency for retryable writes where supported, schema validation, and structured error handling. Never log secrets.",
    "finance_basics": "Finance: simple interest = principal × rate × time. Compound growth = principal × (1+rate)^periods. EMI depends on principal, periodic rate, and number of periods. Separate cash flow, profit, debt and net worth; they are not interchangeable.",
    "trading_risk": "Trading risk: expectancy depends on win rate, average win and average loss. Position sizing and maximum daily loss matter more than confidence labels. Backtests require out-of-sample validation and should include costs/slippage; past performance is not a guarantee.",
    "statistics_basics": "Statistics: mean is sensitive to outliers; median is robust to extremes. Correlation does not establish causation. A confidence interval describes uncertainty of an estimate under model assumptions; p-values are not the probability a hypothesis is true.",
    "business_basics": "Business: contribution margin = selling price minus variable cost. Break-even units = fixed cost / contribution per unit. Inventory ties up working capital; gross margin, operating profit and cash flow answer different questions.",
    "project_basics": "Project execution: define outcome, constraints, owner, dependencies, acceptance criteria and rollback. Break work into observable steps, checkpoint state after each consequential step, and verify the result rather than assuming success.",
    "privacy_basics": "Privacy: passwords, session cookies, private keys, recovery codes and API tokens are credentials. Keep them out of chat/logs/source when possible, store with restrictive permissions, rotate exposed secrets, and revoke credentials from lost devices.",
}

def _offline_init():
    try:
        _kb_init()
        _exec("CREATE TABLE IF NOT EXISTS answer_cache(chat_id TEXT, qkey TEXT, answer TEXT, ts REAL, hits INTEGER DEFAULT 0, PRIMARY KEY(chat_id,qkey))")
        # Seed durable built-in reference cards into the same FTS knowledge surface exactly once.
        if kv_get("offline_builtin_v1322") != "1":
            for name,chunk in OFFLINE_BUILTINS.items():
                try:
                    _exec("DELETE FROM knowledge WHERE path=?", ("builtin://"+name,))
                    _exec("INSERT INTO knowledge(path,chunk) VALUES(?,?)", ("builtin://"+name, chunk))
                except Exception:
                    pass
            kv_set("offline_builtin_v1322","1")
    except Exception:
        pass

def _qnorm(q):
    q=re.sub(r"\s+"," ",str(q or "").strip().lower())
    return re.sub(r"[^a-z0-9₹%+*/().? -]","",q)[:500]

def _stable_question(q):
    t=str(q or "").lower()
    if len(t)<8 or len(t)>900: return False
    if _needs_fresh(t): return False
    # Do not cache highly contextual/personal/transient instructions.
    if re.search(r"\b(today|tomorrow|yesterday|now|current|latest|my last|this screenshot|this image|this file|above|below|remember|forget|send|email|order|buy|sell)\b",t): return False
    return True

def _cache_get(chat_id,q):
    if not _stable_question(q): return ""
    _offline_init(); key=_qnorm(q)
    try:
        rows=_q("SELECT answer,ts FROM answer_cache WHERE chat_id=? AND qkey=?",(str(chat_id),key)) or []
        if rows and time.time()-float(rows[0]["ts"] or 0) < 30*86400:
            _exec("UPDATE answer_cache SET hits=hits+1 WHERE chat_id=? AND qkey=?",(str(chat_id),key))
            return str(rows[0]["answer"] or "")
    except Exception: pass
    return ""

def _cache_put(chat_id,q,ans):
    if not _stable_question(q) or not ans or len(ans)<30: return
    try:
        _offline_init(); key=_qnorm(q)
        _exec("INSERT OR REPLACE INTO answer_cache(chat_id,qkey,answer,ts,hits) VALUES(?,?,?,?,COALESCE((SELECT hits FROM answer_cache WHERE chat_id=? AND qkey=?),0))",
              (str(chat_id),key,str(ans)[:7000],time.time(),str(chat_id),key))
        # Keep cache bounded per bot; newest 500 rows are plenty for fast repeats.
        _exec("DELETE FROM answer_cache WHERE rowid NOT IN (SELECT rowid FROM answer_cache ORDER BY ts DESC LIMIT 500)")
    except Exception: pass

def _local_math(q):
    """Instant deterministic arithmetic for plain expressions; never eval arbitrary Python."""
    import ast as _ast, operator as _op
    t=str(q or "").strip()
    t=re.sub(r"(?i)^\s*(?:calculate|what\s+is|solve|answer)\s*[:\-]?\s*","",t).rstrip(" ?")
    t=t.replace(",","").replace("₹","")
    if not t or len(t)>120 or not re.fullmatch(r"[0-9.()+\-*/%\s]+",t): return ""
    ops={_ast.Add:_op.add,_ast.Sub:_op.sub,_ast.Mult:_op.mul,_ast.Div:_op.truediv,_ast.Mod:_op.mod,_ast.Pow:_op.pow,_ast.USub:_op.neg,_ast.UAdd:_op.pos}
    def ev(n):
        if isinstance(n,_ast.Expression): return ev(n.body)
        if isinstance(n,_ast.Constant) and isinstance(n.value,(int,float)): return n.value
        if isinstance(n,_ast.UnaryOp) and type(n.op) in ops: return ops[type(n.op)](ev(n.operand))
        if isinstance(n,_ast.BinOp) and type(n.op) in ops:
            a,b=ev(n.left),ev(n.right)
            if type(n.op) is _ast.Pow and abs(b)>12: raise ValueError("power too large")
            return ops[type(n.op)](a,b)
        raise ValueError("unsupported")
    try:
        v=ev(_ast.parse(t,mode="eval"))
        if isinstance(v,float) and v.is_integer(): v=int(v)
        return "🧮 RESULT\n"+t+" = "+str(v)
    except Exception: return ""

def _offline_ground(q,max_chars=4200):
    """Gather local evidence before the internet: built-ins + FTS knowledge + library + durable memory."""
    _offline_init(); blocks=[]; seen=set(); qtokens=set(re.findall(r"[a-z0-9]{3,}",str(q or "").lower()))
    # Built-ins are searched directly too, so they work even before SQLite/FTS has initialized on a fresh boot.
    scored=[]
    for name,chunk in OFFLINE_BUILTINS.items():
        toks=set(re.findall(r"[a-z0-9]{3,}",(name+" "+chunk).lower()))
        score=len(qtokens & toks)
        if score: scored.append((score,name,chunk))
    for _score,name,chunk in sorted(scored,reverse=True)[:3]:
        blocks.append("[builtin:"+name+"] "+chunk)
    try:
        for r in kb_search(q,5):
            path=str(r.get("path") or "") if isinstance(r,dict) else str(r["path"] or "")
            chunk=str(r.get("chunk") or "") if isinstance(r,dict) else str(r["chunk"] or "")
            k=(path,chunk[:120])
            if chunk and k not in seen:
                seen.add(k); blocks.append("["+(os.path.basename(path) or path)+"] "+chunk[:1000])
    except Exception: pass
    try:
        lb=lib_search(q,max_chars=1600)
        if lb: blocks.append("[permanent library] "+lb[:1600])
    except Exception: pass
    try:
        mv=mem_recall(q,k=3) if OWNER.get("id") else []
        if mv: blocks.append("[durable memory] "+" | ".join(str(x)[:300] for x in mv))
    except Exception: pass
    text="\n".join(blocks)
    return text[:max_chars]

def _offline_fallback(q):
    ctx=_offline_ground(q,3500)
    if not ctx: return ""
    return "📚 OFFLINE KNOWLEDGE\nI couldn't reach an AI model, so here are the closest verified local notes I found:\n\n"+ctx[:3500]

