def _simple_query(q):
    t=str(q or "").strip().lower()
    if len(t)>320 or _needs_fresh(t) or _is_hard(t): return False
    if re.search(r"\b(deep|research|analyse deeply|analyze deeply|report|strategy|architecture|compare in detail|audit)\b",t): return False
    return True

def _format_contract(chat_id,q):
    mode=_format_get(chat_id); t=str(q or "").lower()
    if mode=="compact":
        return "RESPONSE FORMAT: compact. Give the answer first, then at most 3 short bullets. No filler."
    if any(k in t for k in ("calculate","split","bill","emi","profit","loss","percentage","percent","how much")):
        return "RESPONSE FORMAT: systematic calculation card. Use: 🧮 RESULT, CALCULATION, ✅ FINAL. Keep arithmetic visible and concise."
    if any(k in t for k in ("error","problem","not working","failed","fix","solve","issue")):
        return "RESPONSE FORMAT: troubleshooting card. Use: ⚠️ CAUSE, 🛠 FIX, ✅ TEST. Put the most likely cause first and give executable steps."
    if any(k in t for k in ("compare","vs","versus","which is best","better")):
        return "RESPONSE FORMAT: decision card. Start with 🔎 VERDICT, then KEY DIFFERENCES, then ✅ BEST CHOICE. Avoid decorative filler."
    if re.search(r"\b(how to|steps|setup|install|configure|guide me)\b",t):
        return "RESPONSE FORMAT: action card. Use 🎯 GOAL, numbered STEPS, then ✅ DONE WHEN. One action per step."
    if mode=="executive":
        return "RESPONSE FORMAT: executive. Start with ✅ ANSWER/VERDICT, then 3-6 decision-relevant bullets, then NEXT ACTION only if useful."
    if mode=="detailed":
        return "RESPONSE FORMAT: detailed but systematic. Use a short direct answer, clear section labels, concise bullets, examples only when useful, and a final takeaway."
    return "RESPONSE FORMAT: clean Telegram style. Answer directly first. For non-trivial answers use short emoji section labels and concise bullets; avoid walls of text, repeated conclusions and unnecessary preambles."

