def _cockpit_cpu_pct():
    try:
        import psutil as ps
        return round(float(ps.cpu_percent(interval=0.05)),1)
    except Exception:
        pass
    try:
        return round(min(100.0,max(0.0,os.getloadavg()[0]*25.0)),1)
    except Exception: return 0.0

def _cockpit_data():
    """Read-only live telemetry. Never performs consequential actions."""
    try: disk=float(_disk_pct() or 0)
    except Exception: disk=0
    try: mem=float(_mem_pct() or 0)
    except Exception: mem=0
    try: load=", ".join(f"{x:.2f}" for x in os.getloadavg())
    except Exception: load="—"
    try:
        cooled=sum(1 for v in MODEL_HEALTH.values() if (v or {}).get("until",0)>time.time())
    except Exception: cooled=0
    try:
        cyfind=_cyber_audit_data(); findings=len(cyfind) if isinstance(cyfind,list) else len(cyfind.get("findings",[])) if isinstance(cyfind,dict) else 0
        cyscore=_cyber_score(cyfind if isinstance(cyfind,list) else cyfind.get("findings",[]) if isinstance(cyfind,dict) else [])
    except Exception: findings,cyscore=0,100
    try: cc=_cyber_cfg()
    except Exception: cc={}
    tasks=[]
    def add(kind,detail,state="RUNNING"):
        if len(tasks)<18: tasks.append({"kind":kind,"detail":str(detail)[:140],"state":state})
    try:
        if BROWSER_INPUT: add("Browser",f"Waiting for human input in {len(BROWSER_INPUT)} session(s)","WAITING")
    except Exception: pass
    try:
        for cid,st in list(VIDEO_PENDING.items())[:4]: add("Media",(st or {}).get("url","video") if isinstance(st,dict) else "quality selection","WAITING")
    except Exception: pass
    try:
        obj=globals().get("JOBS",[])
        if isinstance(obj,list):
            for v in obj[:6]: add("Job",str(v)[:120])
        elif isinstance(obj,dict):
            for k,v in list(obj.items())[:6]: add("Job",f"{k}: {str(v)[:90]}")
    except Exception: pass
    try:
        w=globals().get("WORK",{})
        if isinstance(w,dict) and w.get("busy"):
            add("Worker","Continuous work engine is busy","RUNNING")
    except Exception: pass
    try:
        if AUTO.get("pos"): add("Trading",str(AUTO.get("pos")),"OPEN")
    except Exception: pass
    try:
        ps=VPN_STATE.copy(); profile=ps.get("profile") or "DIRECT"
    except Exception: ps={}; profile="DIRECT"
    try:
        pos=AUTO.get("pos"); ptxt=(str(pos.get("symbol"))+" x"+str(pos.get("qty"))) if isinstance(pos,dict) else "NONE"
        pnl=str(AUTO.get("pnl",AUTO.get("day_pnl",0)))
        mode=str(AUTO.get("mode","off")).upper()
    except Exception: ptxt,pnl,mode="NONE","0","OFF"
    try: locked=bool(mm_locked())
    except Exception: locked=False
    shot=os.path.exists("/tmp/nemo_browser.png")
    try:
        files=[]
        for root in ("/root/nemo_code","/root/nemo_downloads"):
            if os.path.isdir(root): files += [os.path.join(root,x) for x in os.listdir(root)]
        files=[x for x in files if os.path.isfile(x)]; files.sort(key=lambda p:os.path.getmtime(p),reverse=True)
        latest=os.path.basename(files[0]) if files else ""; nfiles=len(files)
    except Exception: latest,nfiles="",0
    return {"version":VERSION,"ts":int(time.time()),
      "brain":{"state":"DOWN" if HEALTH.get("down") else "ONLINE","mode":str(MODE.get(OWNER.get("id"),"smart")).upper(),"primary":SMART_MODELS[0] if SMART_MODELS else "openrouter/free","vision":VISION_MODELS[0] if VISION_MODELS else "openrouter/free","cooldowns":cooled},
      "server":{"cpu":_cockpit_cpu_pct(),"mem":mem,"disk":disk,"load":load},
      "cyber":{"score":cyscore,"findings":findings,"monitor":bool(cc.get("monitor")),"baseline":os.path.exists(globals().get("CYBER_BASELINE_FILE","/nonexistent"))},
      "tasks":tasks,
      "network":{"profile":profile,"connected":bool(ps.get("connected")),"verified":bool(ps.get("verified")),"ip":ps.get("last_ip","")},
      "trading":{"mode":mode,"position":ptxt,"pnl":pnl,"lockdown":locked},
      "browser":{"waiting":bool(globals().get("BROWSER_INPUT",{})),"pending":len(globals().get("BROWSER_INPUT",{})),"screenshot":shot},
      "media":{"pending":len(globals().get("VIDEO_PENDING",{})),"files":nfiles,"latest":latest},
      "devices":{"total":len(_device_load().get("devices",{})),"online":sum(1 for _d in _device_load().get("devices",{}).values() if _device_online(_d))}}

def _cockpit_action(action):
    """Only safe/read-only actions from web UI. Anything consequential stays Telegram-confirmed."""
    a=(action or "").strip().lower()
    if a=="status":
        try: return v11_status()
        except Exception: return "Nemo is online."
    if a=="brain":
        try:
            return "Brain: "+("DOWN" if HEALTH.get("down") else "ONLINE")+"\nSmart: "+" -> ".join(SMART_MODELS[:4])+"\nVision: "+" -> ".join(VISION_MODELS[:4])+"\nCooldowns: "+str(len(MODEL_HEALTH))
        except Exception as e: return "Brain status unavailable: "+str(e)[:120]
    if a=="cyber_audit":
        try: return _cyber_audit_text(compact=True)
        except Exception as e: return "Cyber audit unavailable: "+str(e)[:120]
    if a=="hands":
        try: return _hands_snapshot_text()
        except Exception:
            try: return hands_status_text()
            except Exception: return "HANDS status is available in Telegram with /hands status."
    if a=="vpn_status":
        try:
            ok,ip=vpn_verify(None,require_connected=False); return "Profile: "+str(VPN_STATE.get("profile") or "DIRECT")+"\nConnected: "+str(bool(VPN_STATE.get("connected")))+"\nVerified: "+str(bool(VPN_STATE.get("verified")))+"\nPublic IP: "+str(ip or "unknown")
        except Exception as e: return "VPN status unavailable: "+str(e)[:120]
    if a=="browser_status":
        return "Browser waiting for human input: "+("YES" if globals().get("BROWSER_INPUT",{}) else "NO")+"\nLatest checkpoint screenshot: "+("READY" if os.path.exists("/tmp/nemo_browser.png") else "NONE")
    if a=="mind":
        return "MIND CORE 2.0 active: scratchpad firewall, answer compiler, bill/math/image verifier, repetition/token filter, TTS quality gate, semantic browser checkpoints."
    return "That cockpit action is not allowlisted. Consequential actions must be confirmed in Telegram."

def cockpit_link():
    base=(WEBCFG.get("public_url") or WEBCFG.get("url") or "").rstrip("/")
    if not base:
        try:
            ip=requests.get("https://api.ipify.org",timeout=5).text.strip(); base="http://"+ip+":"+str(WEBCFG.get("port",8090))
        except Exception: base="http://YOUR_SERVER_IP:"+str(WEBCFG.get("port",8090))
    return base+"/cockpit?k="+(WEBCFG.get("token") or "")

def cockpit_cmd(chat_id):
    if chat_id != OWNER.get("id"):
        send_text(chat_id,"Owner only."); return
    url=cockpit_link(); pub=(WEBCFG.get("public_url") or "")
    if pub.startswith("https://"):
        kb={"inline_keyboard":[[{"text":"🧠 Open Nemo Cockpit","web_app":{"url":url}}]]}
        send_text(chat_id,"🧠 NEMO COCKPIT 1.0\n\nLive visual control center for Brain, VPS, Cyber, VPN, Trading, Tasks, Browser and Media.\n\nSensitive/consequential actions still require Telegram approval.",kb)
    else:
        send_text(chat_id,"🧠 NEMO COCKPIT 1.0\n\n"+url+"\n\nFor an in-Telegram Mini App button, configure HTTPS first with /setdomain.")

def _cockpit_install_menu():
    """Telegram only accepts Web App menu buttons on HTTPS URLs."""
    try:
        pub=(WEBCFG.get("public_url") or "").rstrip("/")
        if not pub.startswith("https://") or not WEBCFG.get("token"): return False
        mb={"type":"web_app","text":"Nemo Cockpit","web_app":{"url":pub+"/cockpit?k="+WEBCFG["token"]}}
        r=tg("setChatMenuButton",menu_button=mb)
        return bool(r.get("ok"))
    except Exception: return False

# ==================== v13.19 MIND/BROWSER CONTROL ====================
def mind_cmd(chat_id, args=""):
    if chat_id != OWNER.get("id"):
        send_text(chat_id, "Owner only."); return
    a=(args or "").strip().lower()
    if a in ("", "status", "help", "?"):
        send_text(chat_id, "🧠 MIND CORE 2.0 — ACTIVE\n\n• Scratchpad firewall: ON\n• Final-answer compiler: ON\n• Bill/math/image verifier: ON (selective)\n• Repetition/token-garbage filter: ON\n• TTS garbage hard-stop: ON\n• Browser natural checkpoint parser: ON\n• Sensitive auth via Telegram: BLOCKED\n• Semantic stuck-page detection: ON\n\nUse /debug after an answer to inspect model routing, or /guard for the existing regulator.")
        return
    if a.startswith("test"):
        sample="We need to analyze this. Hmm maybe the question wants 25+17. <unk> The final answer is 42."
        send_text(chat_id, "🧪 Compiler sample\nBefore: "+sample+"\n\nDetected: "+str(_mind_answer_bad("calculate 25+17",sample))+"\nTTS: "+(_tts_sanitize(sample) or "BLOCKED")); return
    send_text(chat_id,"Use /mind or /mind test")

def _v1319_dispatch(chat_id,text,msg=None):
    low=(text or "").strip().lower()
