# ==================== v13.23 LEARNING CORE 1.0 + EXPERIENCE BRAIN ====================
LEARN_DB = "/root/nemo_learning.db"
_LEARN_LOCK = threading.RLock()
_LEARN_TLS = threading.local()
_LEARN_SAMPLER_STARTED = False


def _learn_conn():
    import sqlite3
    os.makedirs(os.path.dirname(LEARN_DB), exist_ok=True)
    c = sqlite3.connect(LEARN_DB, timeout=10, check_same_thread=False)
    c.execute("PRAGMA journal_mode=WAL")
    c.execute("PRAGMA synchronous=NORMAL")
    c.executescript("""
    CREATE TABLE IF NOT EXISTS experiences(
      id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, chat_id TEXT, task TEXT, answer TEXT,
      model TEXT, success INTEGER, latency REAL, source TEXT, note TEXT, fingerprint TEXT);
    CREATE INDEX IF NOT EXISTS idx_exp_ts ON experiences(ts DESC);
    CREATE INDEX IF NOT EXISTS idx_exp_fp ON experiences(fingerprint);
    CREATE TABLE IF NOT EXISTS model_stats(
      model TEXT PRIMARY KEY, calls INTEGER DEFAULT 0, ok INTEGER DEFAULT 0, fail INTEGER DEFAULT 0,
      avg_latency REAL DEFAULT 0, last_ts REAL DEFAULT 0, last_error TEXT DEFAULT '');
    CREATE TABLE IF NOT EXISTS tool_stats(
      tool TEXT PRIMARY KEY, calls INTEGER DEFAULT 0, ok INTEGER DEFAULT 0, fail INTEGER DEFAULT 0,
      avg_latency REAL DEFAULT 0, last_ts REAL DEFAULT 0, last_error TEXT DEFAULT '');
    CREATE TABLE IF NOT EXISTS errors(
      fingerprint TEXT PRIMARY KEY, first_ts REAL, last_ts REAL, count INTEGER DEFAULT 0,
      where_name TEXT, sample TEXT, last_fix TEXT, solved INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS feedback(
      id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, chat_id TEXT, rating INTEGER,
      question TEXT, answer TEXT, note TEXT);
    CREATE TABLE IF NOT EXISTS metrics(
      id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, load1 REAL, mem_pct REAL, disk_pct REAL);
    """)
    return c


def _learn_init():
    try:
        c=_learn_conn(); c.close(); return True
    except Exception as e:
        try: _repair_note("learning DB init failed: "+str(e)[:120])
        except Exception: pass
        return False


def _learn_redact(s, limit=2400):
    s=str(s or "")[:limit]
    # Do not turn the learning DB into a credential store.
    s=re.sub(r"(?i)(authorization\s*:\s*bearer\s+)[A-Za-z0-9._~+\-/=]+", r"\1[REDACTED]", s)
    s=re.sub(r"(?i)\b(sk-[A-Za-z0-9_-]{16,}|nvapi-[A-Za-z0-9_-]{16,}|[0-9]{8,12}:[A-Za-z0-9_-]{20,})\b", "[REDACTED_SECRET]", s)
    s=re.sub(r"(?i)(password|passwd|private[_ -]?key|api[_ -]?key|token)\s*[:=]\s*\S+", r"\1=[REDACTED]", s)
    return s


def _learn_sensitive(s):
    x=str(s or "")
    return bool(re.search(r"(?i)(password\s*[:=]|private\s*key|recovery\s*code|otp\s*[:=]|bearer\s+[A-Za-z0-9._-]{12,}|sk-[A-Za-z0-9_-]{16,}|nvapi-[A-Za-z0-9_-]{16,})", x))


def _learn_tokens(s):
    stop={"the","and","for","that","this","with","from","have","what","when","where","how","into","your","you","are","was","were","will","can","could","should","would","about","then","than","not","but"}
    return {w for w in re.findall(r"[a-z0-9_]{3,}", str(s or "").lower()) if w not in stop}


def _learn_fp(text):
    toks=sorted(_learn_tokens(text))[:80]
    return hashlib.sha256(" ".join(toks).encode()).hexdigest()[:20] if toks else ""


def _learn_model_from_debug(chat_id):
    d=str(DEBUG.get(chat_id, "") or "")
    for ln in reversed(d.splitlines()):
        m=re.match(r"(.+?):\s+OK,", ln.strip())
        if m: return m.group(1).strip()
    if "answered by backup brain" in d: return "backup-brain"
    return "unknown"


def _learn_model_event(model, ok, latency, error=""):
    if not model: model="unknown"
    try:
        with _LEARN_LOCK:
            c=_learn_conn()
            row=c.execute("SELECT calls,ok,fail,avg_latency FROM model_stats WHERE model=?",(model,)).fetchone()
            calls,oks,fails,avg=(row or (0,0,0,0.0))
            nc=calls+1; navg=((avg*calls)+float(latency or 0))/nc
            c.execute("INSERT OR REPLACE INTO model_stats(model,calls,ok,fail,avg_latency,last_ts,last_error) VALUES(?,?,?,?,?,?,?)",
                      (model,nc,oks+(1 if ok else 0),fails+(0 if ok else 1),navg,time.time(),"" if ok else str(error)[:220]))
            c.commit(); c.close()
    except Exception: pass


def learn_tool_event(tool, ok=True, latency=0.0, error=""):
    """Shared hook for future HANDS/tools; safe for callers that don't care about learning failures."""
    try:
        with _LEARN_LOCK:
            c=_learn_conn(); row=c.execute("SELECT calls,ok,fail,avg_latency FROM tool_stats WHERE tool=?",(str(tool),)).fetchone()
            calls,oks,fails,avg=(row or (0,0,0,0.0)); nc=calls+1
            navg=((avg*calls)+float(latency or 0))/nc
            c.execute("INSERT OR REPLACE INTO tool_stats(tool,calls,ok,fail,avg_latency,last_ts,last_error) VALUES(?,?,?,?,?,?,?)",
                      (str(tool),nc,oks+(1 if ok else 0),fails+(0 if ok else 1),navg,time.time(),"" if ok else str(error)[:220]))
            c.commit(); c.close()
    except Exception: pass


def _learn_experience(chat_id, task, answer, model, success=True, latency=0.0, source="ai", note=""):
    if _learn_sensitive(task) or _learn_sensitive(answer): return
    task=_learn_redact(task,2200); answer=_learn_redact(answer,3000); note=_learn_redact(note,500)
    if not task.strip(): return
    try:
        with _LEARN_LOCK:
            c=_learn_conn()
            c.execute("INSERT INTO experiences(ts,chat_id,task,answer,model,success,latency,source,note,fingerprint) VALUES(?,?,?,?,?,?,?,?,?,?)",
                      (time.time(),str(chat_id),task,answer,str(model or ""),1 if success else 0,float(latency or 0),source,note,_learn_fp(task)))
            # Bound the DB's hot experience set; export can preserve history before pruning if desired.
            c.execute("DELETE FROM experiences WHERE id NOT IN (SELECT id FROM experiences ORDER BY id DESC LIMIT 12000)")
            c.commit(); c.close()
    except Exception: pass


def _learn_similar(query, k=4):
    qt=_learn_tokens(query)
    if not qt or _learn_sensitive(query): return []
    try:
        c=_learn_conn(); rows=c.execute("SELECT task,answer,model,success,latency,ts,note FROM experiences WHERE success=1 ORDER BY id DESC LIMIT 500").fetchall(); c.close()
    except Exception: return []
    scored=[]; now=time.time()
    for task,ans,model,success,lat,ts,note in rows:
        tt=_learn_tokens(task); inter=len(qt & tt); union=max(1,len(qt | tt))
        if not inter: continue
        sim=inter/union
        rec=max(0.0,1.0-min(1.0,(now-float(ts or now))/(120*86400)))
        score=sim*0.88+rec*0.12
        if score>=0.12: scored.append((score,task,ans,model,lat,note))
    scored.sort(key=lambda x:x[0], reverse=True)
    return scored[:max(1,int(k))]


def _learn_hints(query):
    sims=_learn_similar(query,3)
    if not sims: return ""
    lines=[]
    for sc,task,ans,model,lat,note in sims:
        outcome=(ans or "").replace("\n"," ")[:280]
        lines.append("• Similar successful task: "+task[:180]+" | result: "+outcome+" | model: "+str(model)+" | similarity: "+str(round(sc,2)))
    return "NEMO EXPERIENCE MEMORY — previous successful patterns that may help. Use only if actually relevant; do not copy blindly:\n"+"\n".join(lines)


def _learn_rank_models(models):
    """Reorder only when enough evidence exists; never remove configured fallbacks."""
    try:
        c=_learn_conn(); rows={r[0]:r[1:] for r in c.execute("SELECT model,calls,ok,fail,avg_latency FROM model_stats").fetchall()}; c.close()
    except Exception: return list(models)
    def score(m):
        r=rows.get(m)
        if not r or r[0] < 5: return (0,0)
        calls,ok,fail,avg=r; rate=ok/max(1,calls)
        # quality dominates; latency is a gentle tie-breaker.
        return (1, rate*100 - min(20,float(avg or 0)/2))
    enumerated=list(enumerate(models))
    return [m for _,m in sorted(enumerated,key=lambda im:(-score(im[1])[0],-score(im[1])[1],im[0]))]


def _learn_refresh_routes():
    try:
        SMART_MODELS[:] = _learn_rank_models(SMART_MODELS)
        FAST_MODELS[:] = _learn_rank_models(FAST_MODELS)
        VISION_MODELS[:] = _learn_rank_models(VISION_MODELS)
    except Exception: pass


_ASK_AI_V1322 = ask_ai

def ask_ai(chat_id, text, image_b64=None, remember=True, timeout=180,
           long_output=False, models_override=None, deep=False, ground="", raw=False):
    """v13.23 wrapper: retrieve prior successful experience, observe model outcomes, learn without changing authority."""
    depth=getattr(_LEARN_TLS,"ai_depth",0); _LEARN_TLS.ai_depth=depth+1
    userish=bool(depth==0 and remember and chat_id==OWNER.get("id") and isinstance(text,str) and len(text.strip())>=3)
    g=ground or ""
    if userish and not image_b64:
        h=_learn_hints(text)
        if h: g=(g+"\n\n"+h).strip()
    mo=models_override
    # Preserve caller model-list identity/order; automatic ranking already happened upstream.
    t0=time.time(); reply=""; err=""
    try:
        reply=_ASK_AI_V1322(chat_id,text,image_b64=image_b64,remember=remember,timeout=timeout,
                            long_output=long_output,models_override=mo,deep=deep,ground=g,raw=raw)
        return reply
    except Exception as e:
        err=type(e).__name__+": "+str(e)[:180]
        if userish: _learn_experience(chat_id,text,err,"exception",False,time.time()-t0,"ai",err)
        raise
    finally:
        _LEARN_TLS.ai_depth=depth
        if depth==0:
            lat=time.time()-t0; model=_learn_model_from_debug(chat_id)
            bad=bool(err or not reply or str(reply).startswith(("🧠 My brains are all busy","OpenRouter key invalid")))
            _learn_model_event(model,not bad,lat,err or ("empty/failed answer" if bad else ""))
            if userish and not err:
                _learn_experience(chat_id,text,reply,model,not bad,lat,"ai","")
            if int(time.time()) % 7 == 0: _learn_refresh_routes()


_SELF_REPAIR_V1322 = self_repair

def self_repair(chat_id, exc, where="a request"):
    try:
        sig=type(exc).__name__+"|"+str(where)+"|"+re.sub(r"\d+","#",str(exc)[:220])
        fp=hashlib.sha256(sig.encode()).hexdigest()[:20]
        sample=_learn_redact(type(exc).__name__+": "+str(exc),500)
        with _LEARN_LOCK:
            c=_learn_conn(); row=c.execute("SELECT count FROM errors WHERE fingerprint=?",(fp,)).fetchone(); n=(row[0] if row else 0)+1
            c.execute("INSERT OR REPLACE INTO errors(fingerprint,first_ts,last_ts,count,where_name,sample,last_fix,solved) VALUES(?,?,?,?,?,?,COALESCE((SELECT last_fix FROM errors WHERE fingerprint=?),''),COALESCE((SELECT solved FROM errors WHERE fingerprint=?),0))",
                      (fp,time.time() if not row else c.execute("SELECT first_ts FROM errors WHERE fingerprint=?",(fp,)).fetchone()[0],time.time(),n,str(where)[:120],sample,fp,fp))
            c.commit(); c.close()
    except Exception: pass
    return _SELF_REPAIR_V1322(chat_id,exc,where)


def _learn_feedback(chat_id, rating, note=""):
    q=str(LASTQ.get(chat_id,"") or ""); a=str(LASTREPLY.get(chat_id,"") or "")
    if not q and not a: return False
    try:
        c=_learn_conn(); c.execute("INSERT INTO feedback(ts,chat_id,rating,question,answer,note) VALUES(?,?,?,?,?,?)",
             (time.time(),str(chat_id),int(rating),_learn_redact(q,2200),_learn_redact(a,3000),_learn_redact(note,500))); c.commit(); c.close()
        _learn_experience(chat_id,q,a,_learn_model_from_debug(chat_id),rating>0,0,"feedback",note)
        return True
    except Exception: return False


def _learn_metric_sample():
    try:
        load=float(open('/proc/loadavg').read().split()[0])
        mi={}
        for ln in open('/proc/meminfo'):
            if ':' in ln:
                k,v=ln.split(':',1); mi[k]=float(re.findall(r"\d+",v)[0])
        total=mi.get('MemTotal',1); avail=mi.get('MemAvailable',mi.get('MemFree',0)); mem=100*(1-avail/max(1,total))
        du=shutil.disk_usage('/'); disk=100*du.used/max(1,du.total)
        c=_learn_conn(); c.execute("INSERT INTO metrics(ts,load1,mem_pct,disk_pct) VALUES(?,?,?,?)",(time.time(),load,mem,disk));
        c.execute("DELETE FROM metrics WHERE ts < ?",(time.time()-30*86400,)); c.commit(); c.close()
        return load,mem,disk
    except Exception: return None


def _learn_anomaly_text():
    try:
        c=_learn_conn(); rows=c.execute("SELECT load1,mem_pct,disk_pct FROM metrics ORDER BY id DESC LIMIT 288").fetchall(); c.close()
        if len(rows)<8: return "Not enough baseline samples yet (need at least 8)."
        cur=rows[0]; hist=rows[1:]
        import statistics
        names=("Load","Memory %","Disk %"); out=[]
        for i,n in enumerate(names):
            vals=[float(r[i]) for r in hist]; mu=statistics.mean(vals); sd=statistics.pstdev(vals) or 0.0001; z=(float(cur[i])-mu)/sd
            state="🔴 ANOMALY" if abs(z)>=4 else "🟡 unusual" if abs(z)>=2.5 else "🟢 normal"
            out.append(f"{n}: {cur[i]:.2f} | baseline {mu:.2f} | z={z:.1f} | {state}")
        return "\n".join(out)
    except Exception as e: return "Anomaly analysis unavailable: "+str(e)[:120]


def _learn_sampler_loop():
    while True:
        try: _learn_metric_sample()
        except Exception: pass
        time.sleep(300)


def _learn_start_sampler():
    global _LEARN_SAMPLER_STARTED
    if _LEARN_SAMPLER_STARTED: return
    _LEARN_SAMPLER_STARTED=True
    threading.Thread(target=_learn_sampler_loop,daemon=True,name="nemo-learning-metrics").start()


def _learn_status_text():
    try:
        c=_learn_conn()
        ex=c.execute("SELECT COUNT(*),SUM(CASE WHEN success=1 THEN 1 ELSE 0 END),AVG(latency) FROM experiences").fetchone()
        fb=c.execute("SELECT COUNT(*),SUM(CASE WHEN rating>0 THEN 1 ELSE 0 END) FROM feedback").fetchone()
        er=c.execute("SELECT COUNT(*),COALESCE(SUM(count),0) FROM errors").fetchone()
        ms=c.execute("SELECT model,calls,ok,fail,avg_latency FROM model_stats ORDER BY calls DESC LIMIT 5").fetchall(); c.close()
        total=int(ex[0] or 0); ok=int(ex[1] or 0); rate=(100*ok/max(1,total))
        lines=["🧠 LEARNING CORE 1.0 — ACTIVE",f"Experiences: {total:,}",f"Successful outcomes: {rate:.1f}%",f"Explicit feedback: {int(fb[0] or 0)}",f"Error fingerprints: {int(er[0] or 0)} ({int(er[1] or 0)} occurrences)",f"Avg learned task latency: {float(ex[2] or 0):.2f}s","","TOP MODEL HISTORY"]
        for m,calls,oks,fails,lat in ms: lines.append(f"• {m}: {oks}/{calls} OK | {float(lat or 0):.2f}s avg")
        lines += ["","Commands: /learned models | experiences | errors | anomaly | good | bad <note> | export | reset"]
        return "\n".join(lines)
    except Exception as e: return "Learning Core unavailable: "+str(e)[:160]


def learned_cmd(chat_id,args=""):
    if chat_id != OWNER.get("id"): send_text(chat_id,"Owner only."); return
    a=(args or "").strip(); low=a.lower()
    if low in ("","status","help","?"):
        send_text(chat_id,_learn_status_text()); return
    if low in ("good","up","yes") or low.startswith("good "):
        note=a[5:].strip() if low.startswith("good ") else ""
        send_text(chat_id,"✅ Learned from your positive feedback." if _learn_feedback(chat_id,1,note) else "Nothing recent to rate yet."); return
    if low in ("bad","down","no") or low.startswith("bad "):
        note=a[4:].strip() if low.startswith("bad ") else ""
        send_text(chat_id,"🧠 Recorded as a failed/poor outcome. Future routing can learn from it." if _learn_feedback(chat_id,-1,note) else "Nothing recent to rate yet."); return
    if low=="models":
        try:
            c=_learn_conn(); rows=c.execute("SELECT model,calls,ok,fail,avg_latency,last_error FROM model_stats ORDER BY calls DESC LIMIT 20").fetchall(); c.close()
            out=["🧠 MODEL LEARNING"]+[f"• {m}: {o}/{ca} OK ({100*o/max(1,ca):.0f}%) | {la:.2f}s"+(f" | last: {er[:80]}" if er else "") for m,ca,o,f,la,er in rows]
            send_text(chat_id,"\n".join(out) if rows else "No model history yet.")
        except Exception as e: send_text(chat_id,"Model stats unavailable: "+str(e)[:120])
        return
    if low in ("experiences","experience","recent"):
        try:
            c=_learn_conn(); rows=c.execute("SELECT task,model,success,latency,note FROM experiences ORDER BY id DESC LIMIT 12").fetchall(); c.close()
            out=["🧠 RECENT EXPERIENCE"]
            for task,m,s,lat,n in rows: out.append(("✅ " if s else "❌ ")+task.replace("\n"," ")[:150]+f"\n   {m} • {lat:.2f}s"+(" • "+n[:80] if n else ""))
            send_text(chat_id,"\n".join(out) if rows else "No learned experiences yet.")
        except Exception as e: send_text(chat_id,"Experience history unavailable: "+str(e)[:120])
        return
    if low=="errors":
        try:
            c=_learn_conn(); rows=c.execute("SELECT fingerprint,count,where_name,sample,solved FROM errors ORDER BY last_ts DESC LIMIT 15").fetchall(); c.close()
            out=["🛠 ERROR MEMORY"]+[f"• {fp} ×{n} at {w}: {s[:130]}"+(" ✅ solved" if sol else "") for fp,n,w,s,sol in rows]
            send_text(chat_id,"\n".join(out) if rows else "No learned error fingerprints yet.")
        except Exception as e: send_text(chat_id,"Error memory unavailable: "+str(e)[:120])
        return
    if low=="anomaly": send_text(chat_id,"📈 LEARNED SYSTEM BASELINE\n\n"+_learn_anomaly_text()); return
    if low.startswith("similar "):
        q=a[8:].strip(); sims=_learn_similar(q,5)
        out=["🔎 SIMILAR EXPERIENCE"]+[f"• {sc:.2f} — {task[:170]}\n  {ans.replace(chr(10),' ')[:200]}" for sc,task,ans,m,lat,n in sims]
        send_text(chat_id,"\n".join(out) if sims else "No similar successful experience found yet."); return
    if low=="export":
        try:
            import datetime
            p="/root/nemo_learning_export_"+datetime.datetime.now().strftime("%Y%m%d_%H%M%S")+".jsonl"
            c=_learn_conn(); rows=c.execute("SELECT ts,task,answer,model,success,latency,source,note FROM experiences ORDER BY id").fetchall(); c.close()
            with open(p,"w",encoding="utf-8") as f:
                for r in rows: f.write(json.dumps({"ts":r[0],"task":r[1],"answer":r[2],"model":r[3],"success":bool(r[4]),"latency":r[5],"source":r[6],"note":r[7]},ensure_ascii=False)+"\n")
            LASTFILE[chat_id]=p; _send_file(chat_id,p,"🧠 Nemo learning dataset export (secrets are redacted/skipped)")
        except Exception as e: send_text(chat_id,"Export failed: "+str(e)[:160])
        return
    if low=="reset":
        send_text(chat_id,"⚠️ Learning reset is destructive. Use /learned reset CONFIRM to erase experience/model/error/feedback history."); return
    if low=="reset confirm":
        try:
            c=_learn_conn(); [c.execute("DELETE FROM "+x) for x in ("experiences","model_stats","tool_stats","errors","feedback","metrics")]; c.commit(); c.close(); send_text(chat_id,"🧹 Learning history reset. Nemo's normal memory/knowledge was NOT touched.")
        except Exception as e: send_text(chat_id,"Reset failed: "+str(e)[:120])
        return
    send_text(chat_id,"Use /learned status|models|experiences|errors|anomaly|similar <task>|good|bad <note>|export|reset")


def _v1323_dispatch(chat_id,text,msg=None):
    low=(text or "").strip().lower()
    if low in ("/learned","/learn","/learning","/ml") or low.startswith(("/learned ","/learn ","/learning ","/ml ")):
        parts=(text or "").split(None,1); learned_cmd(chat_id,parts[1] if len(parts)>1 else ""); return True
    if low in ("👍","good answer","that was good","correct answer"):
        learned_cmd(chat_id,"good"); return True
    if low in ("👎","bad answer","wrong answer","that was wrong"):
        learned_cmd(chat_id,"bad"); return True
    return False


