def _creation_ascii(s):
    """Typography normalizer for core-font PDFs. Prevents the v13.25 '?' glyph corruption."""
    s = str(s or "")
    repl = {
        "\u2010":"-", "\u2011":"-", "\u2012":"-", "\u2013":"-", "\u2014":"-", "\u2212":"-",
        "\u2018":"'", "\u2019":"'", "\u201c":"\"", "\u201d":"\"", "\u2022":"-", "\u2026":"...",
        "\u00a0":" ", "\u202f":" ", "\u00d7":"x", "\u2192":"->", "\u00b7":" | ",
        "\u20b9":"Rs ", "\u00a3":"GBP ", "\u20ac":"EUR ", "\u00a5":"JPY "
    }
    for a,b in repl.items(): s=s.replace(a,b)
    s=re.sub(r"[\u200b-\u200f\u202a-\u202e\ufeff]", "", s)
    s=re.sub(r"[ \t]+", " ", s)
    # Do NOT hide literal question marks; only eliminate common mojibake patterns around words/numbers.
    s=re.sub(r"(?<=\w)\?(?=\w)", "-", s)
    s=re.sub(r"(?<=\d)\?(?=%)", "", s)
    s=re.sub(r"(?<=\w)\?s\b", "'s", s)
    return s.strip()


def _creation_short_title(topic):
    """Create a clean cover title without ellipsis/truncated-word artefacts."""
    t=_creation_ascii(topic)
    t=re.sub(r"(?i)\b(create|prepare|professional|intelligence|report|email it to me|email me|current)\b", " ", t)
    t=re.sub(r"\s+", " ", t).strip(" -:,.|")
    if not t:
        return "Strategic Intelligence Brief"
    if len(t)<=110:
        return t.title()
    # Prefer a meaningful first clause, but never print an ellipsis on the cover.
    parts=re.split(r"\s+(?:and|with|including)\s+|[,;:]", t, maxsplit=1, flags=re.I)
    first=(parts[0] or "").strip()
    if 28 <= len(first) <= 100:
        return first.title()
    words=t.split(); acc=[]
    for w in words:
        if len(" ".join(acc+[w]))>105: break
        acc.append(w)
    return (" ".join(acc) or t[:105]).strip().title()

def _report_source_score(url, title="", body=""):
    """v13.26 authority ontology. Score is provenance quality, never a truth guarantee."""
    host=_report_host(url); text=(str(title)+" "+str(body)).lower()
    if not host: return 0,"UNATTRIBUTED"
    if any(x in host for x in _CREATION_BAD_DOMAINS): return -10,"REJECT"
    # reject obvious index/tag/search pages masquerading as research
    if "nature.com" in host and re.search(r"/nature-index/|/topics/", str(url), re.I): return 1,"INDEX/AGGREGATOR"
    if any(x in host for x in _CREATION_PRIMARY): return 5,"PRIMARY/INSTITUTIONAL"
    if any(x in host for x in _CREATION_WIRES): return 5,"MAJOR NEWS/WIRE"
    if any(x in host for x in _CREATION_INSTITUTIONAL): return 4,"INSTITUTIONAL/RESEARCH"
    if any(x in host for x in _CREATION_STRONG): return 4,"STRONG SECONDARY"
    if re.search(r"\b(university|institute|foundation|research centre|research center|official|ministry|central bank)\b", text):
        return 3,"SPECIALIST"
    if re.search(r"\b(blog|opinion|commentary|sponsored|advertorial)\b", text): return 1,"LOW-AUTHORITY"
    return 2,"GENERAL"


def _creation_norm_source_key(r):
    u=(r.get("url") or "").lower().strip()
    u=re.sub(r"[?#].*$", "", u).rstrip("/")
    title=re.sub(r"\W+", " ", (r.get("title") or "").lower()).strip()
    return u or title[:180]


def _report_query_plan(topic):
    """v13.26: materiality-first + primary-source biased query plan."""
    t=(topic or "").strip()
    qs=[t, t+" latest developments", t+" impact outlook risks", t+" India implications"]
    if re.search(r"\b(geopolit|war|conflict|econom|market|policy|outlook|trade|energy|security)\b",t,re.I):
        qs += [
            t+" site:reuters.com", t+" site:imf.org", t+" site:worldbank.org", t+" site:un.org",
            t+" site:weforum.org", t+" site:bbc.com", t+" official data 2026"
        ]
    else:
        qs += [t+" official data", t+" research paper", t+" primary source"]
    out=[]
    for q in qs:
        q=re.sub(r"\s+"," ",q).strip()
        if q and q not in out: out.append(q)
    return out[:12]


def _report_research(topic, min_good=6, max_sources=18):
    """v13.26: curate evidence, not search-result volume."""
    seen=set(); cand=[]
    for qi,q in enumerate(_report_query_plan(topic)):
        modes=(False,True) if qi<5 else (False,)
        for news in modes:
            for r in _report_web_search(q,news=news,max_results=8):
                url=(r.get("href") or r.get("url") or "").strip(); title=(r.get("title") or "").strip()
                body=(r.get("body") or r.get("snippet") or r.get("description") or "").strip()
                row={"title":title,"body":body,"url":url,"query":q,"kind":"news" if news else "web"}
                k=_creation_norm_source_key(row)
                if not k or k in seen: continue
                seen.add(k)
                sc,tier=_report_source_score(url,title,body)
                if sc<2: continue
                row.update(score=sc,tier=tier); cand.append(row)
        if sum(1 for x in cand if x["score"]>=4)>=min_good and len(cand)>=12: break
    # Prefer evidence quality + domain diversity. General sources cannot crowd out institutional ones.
    cand.sort(key=lambda x:(x.get("score",0),len(x.get("body",""))),reverse=True)
    rows=[]; per_domain={}; general_count=0
    for r in cand:
        h=_report_host(r.get("url")) or "unknown"
        if per_domain.get(h,0)>=1 and len(rows)>=8: continue
        if r.get("score",0)<=2 and general_count>=4: continue
        rows.append(r); per_domain[h]=per_domain.get(h,0)+1
        if r.get("score",0)<=2: general_count+=1
        if len(rows)>=max_sources: break
    return rows


def _creation_used_source_ids(content):
    return sorted({int(x) for x in re.findall(r"\[(\d+)\]",content or "") if str(x).isdigit()})


def _report_research_quality(rows, content=""):
    """Evidence grade now follows USED evidence and penalizes weak-source dependence."""
    used=_creation_used_source_ids(content)
    pool=[rows[i-1] for i in used if 1<=i<=len(rows)] if used else list(rows)
    n=len(pool); scores=[int(r.get("score",0)) for r in pool]
    auth=sum(1 for s in scores if s>=4); primary=sum(1 for s in scores if s>=5); weak=sum(1 for s in scores if s<=2)
    domains=len({_report_host(r.get("url")) for r in pool if _report_host(r.get("url"))})
    avg=(sum(scores)/max(1,n)) if n else 0
    # 100 is deliberately difficult. Weak evidence can never receive an A.
    score=round(min(100,max(0,avg*16 + min(auth,6)*3 + min(primary,4)*2 + min(domains,8)*1.5 - weak*7))) if n else 0
    if weak>max(1,n//3): grade="C" if score>=45 else "D"
    elif score>=88 and auth>=4 and primary>=2: grade="A"
    elif score>=72 and auth>=3: grade="B+"
    elif score>=60: grade="B"
    elif score>=42: grade="C"
    else: grade="D"
    return {"sources":len(rows),"used_sources":n,"authoritative":auth,"primary":primary,"weak":weak,
            "domains":domains,"avg_authority":round(avg,2),"score":int(score),"grade":grade}


def _creation_strip_appendices(content):
    """Remove machine/source appendices before analytical rendering.

    Headings produced by older brains were inconsistent about a trailing colon,
    so v13.27 accepts both forms and prevents evidence metadata leaking into KPI
    extraction or the narrative pages.
    """
    s=content or ""
    s=re.split(r"\n\s*(?:EVIDENCE INDEX|SOURCE REGISTER|RESEARCH EVIDENCE|RESEARCH AUDIT|SOURCE APPENDIX)\s*:?[ \t]*\n",s,1,flags=re.I)[0]
    return s.strip()

def _creation_sections(content):
    major=("EVIDENCE QUALITY","EXECUTIVE SUMMARY","CURRENT SITUATION","KEY DEVELOPMENTS","IMPACT ASSESSMENT",
           "OUTLOOK - NEXT 6 TO 24 MONTHS","RISK MATRIX","WHAT TO WATCH","CONCLUSION","SOURCES USED")
    sec={}; cur="BODY"; sec[cur]=[]
    for raw in (content or "").splitlines():
        st=raw.strip(); up=st.rstrip(":").upper()
        hit=next((h for h in major if up==h),None)
        if hit: cur=hit; sec.setdefault(cur,[]); continue
        sec.setdefault(cur,[]).append(st)
    return sec


def _creation_extract_bullets(lines,limit=6):
    out=[]
    for x in lines or []:
        s=re.sub(r"^\s*(?:[-*]|\d+[.)])\s*","",x).strip()
        if s: out.append(s)
        if len(out)>=limit: break
    return out


def _creation_risk_rows(lines):
    rows=[]
    for x in lines or []:
        s=x.strip()
        m=re.match(r"(.+?)\s*[|\-]\s*Likelihood:\s*(Low|Medium|High)\s*[|\-]\s*Impact:\s*(Low|Medium|High)\s*[|\-]\s*(?:Watch indicator|Indicator):\s*(.+)",s,re.I)
        if m: rows.append((m.group(1).strip(),m.group(2).title(),m.group(3).title(),m.group(4).strip()))
    return rows[:7]


def _creation_scenario_rows(lines):
    rows=[]
    for x in lines or []:
        s=x.strip()
        m=re.match(r"(BASE CASE|UPSIDE CASE|DOWNSIDE CASE)\s*(?:\(analysis\))?\s*:\s*(.+)",s,re.I)
        if m: rows.append((m.group(1).title(),m.group(2).strip()))
    return rows


def _creation_key_numbers(content,limit=3):
    """Extract only genuine decision-useful metrics for visual KPI cards.

    v13.26 could mistake years, citation IDs and evidence metadata (e.g. SCORE=5/5)
    for KPIs. v13.27 requires a meaningful unit/currency/percentage and rejects
    source-quality vocabulary outright.
    """
    bad_meta=re.compile(r"(?:AUTHORITY|SCORE\s*=|PRIMARY/INSTITUTIONAL|INSTITUTIONAL/RESEARCH|STRONG SECONDARY|GENERAL|SOURCE REGISTER|EVIDENCE INDEX|RESEARCH QUALITY|EVIDENCE GRADE|CITED SOURCES|DISTINCT DOMAINS)",re.I)
    # Explicit unit-bearing values only. Bare 2026/5/etc. are not KPIs.
    metric_re=re.compile(
        r"(?:US\$|USD\s*|Rs\s*|INR\s*|EUR\s*|GBP\s*|\$)\s*\d[\d,]*(?:\.\d+)?(?:\s*(?:billion|million|trillion|bn|mn|crore|lakh))?"
        r"|\b\d+(?:\.\d+)?\s*(?:%|bps|basis points?|billion|million|trillion|bn|mn|crore|lakh|years?|months?|days?|km|kilomet(?:er|re)s?|tonnes?|tons?|barrels?|mbpd|mmbpd|gw|mw|twh)(?!\w)",
        re.I)
    out=[]; seen=set()
    clean=_creation_strip_appendices(content or "")
    # Work line-by-line because many report writers place [n] after sentence punctuation;
    # sentence splitting would detach the citation and accidentally discard a valid metric.
    for sent in clean.splitlines():
        sent=sent.strip()
        if not sent or not re.search(r"\[\d+\]",sent):
            continue
        if bad_meta.search(sent):
            continue
        scan=re.sub(r"\[\d+\]","",sent)
        scan=re.sub(r"\s+"," ",scan).strip(" -•")
        m=metric_re.search(scan)
        if not m:
            continue
        num=m.group(0).strip()
        # Ignore duration phrases that are report-horizon boilerplate rather than evidence.
        if re.fullmatch(r"(?:6|12|18|24)\s*months?",num,re.I) and re.search(r"outlook|scenario|next",scan,re.I):
            continue
        label=re.sub(r"\s+"," ",scan).strip()
        key=(num.lower(),re.sub(r"\W+"," ",label.lower())[:80])
        if key in seen: continue
        seen.add(key); out.append((num,label[:135]))
        if len(out)>=limit: break
    # One lonely KPI tile usually looks accidental. Prefer no panel to a weak panel.
    return out if len(out)>=2 else []

def _creation_link_cell(pdf,w,h,text,url="",align="L"):
    try: pdf.cell(w,h,text,link=url or "",align=align)
    except TypeError: pdf.cell(w,h,text,align=align)


def _creation_render_pdf(topic, content, research, quality, out, godmode=True, subtitle="Strategic Intelligence Report"):
    """v13.27 Publisher Godmode 5.0: measured-flow renderer with no fixed-height text clipping."""
    from fpdf import FPDF
    from datetime import datetime
    content=_creation_ascii(_creation_strip_appendices(content))
    sections=_creation_sections(content); short=_creation_short_title(topic)
    used_ids=_creation_used_source_ids(content); used_rows=[(i,research[i-1]) for i in used_ids if 1<=i<=len(research)]
    if not used_rows: used_rows=list(enumerate(research[:8],1))

    class PDF(FPDF):
        def header(self):
            if self.page_no()>1:
                self.set_draw_color(221,226,233); self.line(16,13,self.w-16,13)
                self.set_y(6); self.set_x(16); self.set_font(self._nemo_font,"B",8); self.set_text_color(56,72,92)
                self.cell(self.w-32,5,"NEMO | PUBLISHER GODMODE",align="L")
        def footer(self):
            self.set_y(-12); self.set_x(16); self.set_draw_color(228,231,236); self.line(16,self.h-14,self.w-16,self.h-14)
            self.set_font(self._nemo_font,"",8); self.set_text_color(115,121,132)
            self.cell(self.w-32,8,"Nemo Intelligence  |  Confidential working report  |  Page "+str(self.page_no()),align="C")

    pdf=PDF(); pdf.set_margins(16,20,16); pdf.set_auto_page_break(True,18); pw=pdf.w-32
    # Use an embedded Unicode family when Ubuntu provides it. Fall back cleanly to Helvetica.
    fam="Helvetica"
    try:
        reg="/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"; bold="/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"
        if os.path.exists(reg) and os.path.exists(bold):
            pdf.add_font("DejaVu","",reg); pdf.add_font("DejaVu","B",bold); fam="DejaVu"
    except Exception:
        fam="Helvetica"
    pdf._nemo_font=fam

    def tx(v):
        # Input was already normalized. Unicode family can display it; Helvetica receives ASCII-safe text.
        return str(v or "") if fam!="Helvetica" else _creation_ascii(v)

    def setf(style="",size=9): pdf.set_font(fam,style,size)
    def wrap(text,width,size=9,style=""):
        setf(style,size); text=tx(text).replace("\r","")
        lines=[]
        for para in text.split("\n"):
            words=para.split()
            if not words: lines.append(""); continue
            cur=""
            for word in words:
                trial=(cur+" "+word).strip()
                if not cur or pdf.get_string_width(trial)<=width:
                    cur=trial
                else:
                    lines.append(cur); cur=word
            if cur: lines.append(cur)
        return lines or [""]
    def ensure(h):
        if pdf.get_y()+h > pdf.h-19:
            pdf.add_page(); pdf.set_y(max(pdf.get_y(),20))
    def text_block(text,width=None,size=9.3,style="",lh=5.2,x=16,color=(43,48,56),after=2):
        width=width or pw; lines=wrap(text,width,size,style); h=max(lh,len(lines)*lh)
        ensure(h+after); pdf.set_xy(x,pdf.get_y()); setf(style,size); pdf.set_text_color(*color)
        pdf.multi_cell(width,lh,tx(text),align="L"); pdf.ln(after); return h
    def major(title):
        ensure(16); pdf.ln(2); pdf.set_x(16); setf("B",14); pdf.set_text_color(20,67,108); pdf.multi_cell(pw,7,tx(title),align="L")
        yy=pdf.get_y()+1; pdf.set_draw_color(106,180,238); pdf.line(16,yy,pdf.w-16,yy); pdf.ln(4)
    def card(x,y,w,title,body,fill=(246,249,252),title_size=10,body_size=9.2,min_h=0):
        title_lines=wrap(title,w-10,title_size,"B"); body_lines=wrap(body,w-10,body_size,"")
        h=max(min_h,7+len(title_lines)*5.2+3+len(body_lines)*4.8+5)
        pdf.set_fill_color(*fill); pdf.set_draw_color(226,231,237); pdf.rect(x,y,w,h,"DF")
        pdf.set_xy(x+5,y+4); setf("B",title_size); pdf.set_text_color(31,86,128); pdf.multi_cell(w-10,5.2,tx(title),align="L")
        by=pdf.get_y()+2; pdf.set_xy(x+5,by); setf("",body_size); pdf.set_text_color(42,49,58); pdf.multi_cell(w-10,4.8,tx(body),align="L")
        return h

    # Cover
    pdf.add_page(); pdf.set_fill_color(15,29,48); pdf.rect(0,0,pdf.w,86,"F")
    pdf.set_xy(16,17); setf("B",9); pdf.set_text_color(108,190,255); pdf.cell(pw,6,"NEMO INTELLIGENCE  /  PUBLISHER GODMODE")
    # Measure title; shrink rather than collide or truncate.
    title_size=25
    while title_size>17 and len(wrap(short,pw,title_size,"B"))>4: title_size-=1
    pdf.set_xy(16,31); setf("B",title_size); pdf.set_text_color(255,255,255); pdf.multi_cell(pw,9.8,tx(short),align="L")
    pdf.set_xy(16,93); setf("B",12); pdf.set_text_color(19,47,78); pdf.multi_cell(pw,7,tx(subtitle),align="L")
    pdf.set_x(16); setf("",9); pdf.set_text_color(93,101,113)
    pdf.cell(pw,6,"Prepared "+datetime.now().strftime("%d %B %Y")+"  |  Evidence "+quality.get("grade","D")+"  |  "+str(quality.get("used_sources",0))+" cited sources")
    pdf.ln(12)
    badges=[("EVIDENCE",quality.get("grade","D")),("AUTHORITY",str(quality.get("avg_authority",0))+"/5"),("DOMAINS",str(quality.get("domains",0))), ("QA","PASSED")]
    gap=3; bw=(pw-gap*3)/4; y=pdf.get_y()
    for j,(k,v) in enumerate(badges):
        x=16+j*(bw+gap); pdf.set_fill_color(242,246,250); pdf.set_draw_color(219,226,233); pdf.rect(x,y,bw,25,"DF")
        pdf.set_xy(x+4,y+4); setf("",7); pdf.set_text_color(100,108,120); pdf.cell(bw-8,5,k)
        pdf.set_xy(x+4,y+11); setf("B",13); pdf.set_text_color(24,59,92); pdf.cell(bw-8,7,str(v))
    pdf.set_y(y+34)
    std="Materiality-first analysis | cited evidence | fact/assessment separation | scenario triggers | measured layout | compact clickable sources"
    std_lines=wrap(std,pw-10,8.2,""); sh=12+len(std_lines)*4.5+5
    pdf.set_fill_color(247,249,252); pdf.set_draw_color(226,230,236); pdf.rect(16,pdf.get_y(),pw,sh,"DF")
    sy=pdf.get_y(); pdf.set_xy(21,sy+5); setf("B",9); pdf.set_text_color(24,59,92); pdf.cell(pw-10,5,"REPORT STANDARD")
    pdf.set_xy(21,sy+12); setf("",8.2); pdf.set_text_color(68,77,90); pdf.multi_cell(pw-10,4.5,std,align="L")

    # Executive page
    pdf.add_page(); pdf.set_y(20); major("EXECUTIVE SNAPSHOT")
    bullets=_creation_extract_bullets(sections.get("EXECUTIVE SUMMARY"),6)
    for i,b in enumerate(bullets,1):
        num=str(i).zfill(2); body_lines=wrap(b,pw-19,9.2,""); h=max(16,8+len(body_lines)*4.8+4); ensure(h+3); y=pdf.get_y()
        pdf.set_fill_color(246,249,252); pdf.set_draw_color(226,231,237); pdf.rect(16,y,pw,h,"DF")
        pdf.set_xy(20,y+4); setf("B",10); pdf.set_text_color(31,86,128); pdf.cell(9,5,num)
        pdf.set_xy(31,y+4); setf("",9.2); pdf.set_text_color(42,49,58); pdf.multi_cell(pw-19,4.8,tx(b),align="L"); pdf.set_y(y+h+3)

    nums=_creation_key_numbers(content,3)
    if nums:
        major("KEY NUMBERS")
        gap=3; bw=(pw-gap*(len(nums)-1))/len(nums); y=pdf.get_y(); heights=[]
        for num,label in nums:
            heights.append(14+len(wrap(label,bw-8,6.8,""))*3.8+7)
        h=max(30,max(heights)); ensure(h+4); y=pdf.get_y()
        for j,(num,label) in enumerate(nums):
            x=16+j*(bw+gap); pdf.set_fill_color(19,54,83); pdf.rect(x,y,bw,h,"F")
            pdf.set_xy(x+4,y+4); setf("B",13.5); pdf.set_text_color(255,255,255); pdf.multi_cell(bw-8,6.5,tx(num),align="L")
            pdf.set_xy(x+4,y+13); setf("",6.8); pdf.set_text_color(213,228,240); pdf.multi_cell(bw-8,3.8,tx(label),align="L")
        pdf.set_y(y+h+4)

    # Narrative sections
    for sec_name in ("CURRENT SITUATION","KEY DEVELOPMENTS","IMPACT ASSESSMENT"):
        lines=[x for x in sections.get(sec_name,[]) if x]
        if not lines: continue
        major(sec_name)
        for st in lines:
            if st.endswith(":") and len(st)<90:
                text_block(st,size=10.3,style="B",lh=5.6,color=(35,61,84),after=1)
            else:
                text_block(st,size=9.2,lh=5.3,color=(43,48,56),after=1.5)

    # Scenario dashboard
    sc=_creation_scenario_rows(sections.get("OUTLOOK - NEXT 6 TO 24 MONTHS",[]))
    if sc:
        pdf.add_page(); pdf.set_y(20); major("6-24 MONTH SCENARIO DASHBOARD")
        fills={"Base Case":(238,246,252),"Upside Case":(238,249,241),"Downside Case":(253,241,241)}
        for name,desc in sc:
            h=10+len(wrap(name,pw-10,11,"B"))*5.4+2+len(wrap(desc,pw-10,9,""))*4.8+6
            ensure(h+4); y=pdf.get_y(); rgb=fills.get(name,(246,248,251)); pdf.set_fill_color(*rgb); pdf.set_draw_color(223,229,235); pdf.rect(16,y,pw,h,"DF")
            pdf.set_xy(21,y+5); setf("B",11); pdf.set_text_color(24,62,94); pdf.multi_cell(pw-10,5.4,tx(name.upper()),align="L")
            pdf.set_xy(21,pdf.get_y()+2); setf("",9); pdf.set_text_color(45,52,61); pdf.multi_cell(pw-10,4.8,tx(desc),align="L"); pdf.set_y(y+h+4)

    # Risk dashboard with real wrapping and measured row heights.
    risks=_creation_risk_rows(sections.get("RISK MATRIX",[]))
    if risks:
        major("RISK DASHBOARD")
        widths=[51,25,25,pw-101]; hdr=["Risk","Likelihood","Impact","Leading indicator"]
        def risk_header():
            pdf.set_fill_color(26,55,82); pdf.set_text_color(255,255,255); setf("B",7.7); pdf.set_x(16)
            for w,hdrt in zip(widths,hdr): pdf.cell(w,8,hdrt,border=0,fill=True,align="C" if hdrt in ("Likelihood","Impact") else "L")
            pdf.ln(8)
        risk_header(); score={"Low":1,"Medium":2,"High":3}
        for risk,lk,imp,ind in risks:
            risk_lines=wrap(risk,widths[0]-5,7.4,""); ind_lines=wrap(ind,widths[3]-5,7.0,""); n=max(len(risk_lines),len(ind_lines),2); rowh=max(13,5+n*4.0)
            if pdf.get_y()+rowh>pdf.h-21:
                pdf.add_page(); pdf.set_y(20); major("RISK DASHBOARD (CONTINUED)"); risk_header()
            y=pdf.get_y(); x=16
            # backgrounds
            pdf.set_fill_color(247,249,251); pdf.rect(x,y,widths[0],rowh,"F"); x+=widths[0]
            for val,w in ((lk,widths[1]),(imp,widths[2])):
                scv=score.get(val,2); rgb=(232,246,236) if scv==1 else (255,244,218) if scv==2 else (252,228,228); pdf.set_fill_color(*rgb); pdf.rect(x,y,w,rowh,"F"); x+=w
            pdf.set_fill_color(247,249,251); pdf.rect(x,y,widths[3],rowh,"F")
            # text, clipped nowhere
            x=16; pdf.set_xy(x+2.5,y+3); setf("",7.4); pdf.set_text_color(45,50,58); pdf.multi_cell(widths[0]-5,4.0,tx(risk),align="L"); x+=widths[0]
            for val,w in ((lk,widths[1]),(imp,widths[2])):
                setf("B",7.4); tw=pdf.get_string_width(val); pdf.set_xy(x+(w-tw)/2,y+(rowh-4.2)/2); pdf.cell(tw,4.2,val); x+=w
            pdf.set_xy(x+2.5,y+3); setf("",7.0); pdf.set_text_color(45,50,58); pdf.multi_cell(widths[3]-5,4.0,tx(ind),align="L"); pdf.set_y(y+rowh+1)

    watch=_creation_extract_bullets(sections.get("WHAT TO WATCH"),10)
    if watch:
        major("WHAT TO WATCH")
        for i,w in enumerate(watch,1):
            lines=wrap(w,pw-11,8.7,""); h=max(5,len(lines)*4.8); ensure(h+1.5); y=pdf.get_y()
            pdf.set_xy(18,y); setf("B",8.5); pdf.set_text_color(31,86,128); pdf.cell(9,4.8,str(i).zfill(2))
            pdf.set_xy(29,y); setf("",8.7); pdf.set_text_color(45,51,59); pdf.multi_cell(pw-13,4.8,tx(w),align="L"); pdf.set_y(y+h+1.5)

    concl=" ".join(x for x in sections.get("CONCLUSION",[]) if x).strip()
    if concl:
        major("BOTTOM LINE")
        lines=wrap(concl,pw-10,9.2,""); h=10+len(lines)*5+6; ensure(h+3); y=pdf.get_y(); pdf.set_fill_color(18,49,76); pdf.rect(16,y,pw,h,"F")
        pdf.set_xy(21,y+5); setf("",9.2); pdf.set_text_color(255,255,255); pdf.multi_cell(pw-10,5,tx(concl),align="L"); pdf.set_y(y+h+3)

    # Compact source cards with measured title height, no overlap.
    if used_rows:
        pdf.add_page(); pdf.set_y(20); major("SOURCES & EVIDENCE")
        text_block("Only sources cited in the analytical body are listed below. Titles are clickable where the PDF viewer supports links.",size=8.1,lh=4.7,color=(80,87,97),after=3)
        for i,r in used_rows[:12]:
            tier=tx(r.get("tier","GENERAL")); title=tx(r.get("title") or "Source"); url=r.get("url") or ""; host=_report_host(url) or "source"
            title_lines=wrap(title,pw-8,8.0,""); h=6+4.0+2+len(title_lines)*4.5+2+3.8+5
            ensure(h+2); y=pdf.get_y(); pdf.set_fill_color(247,249,252); pdf.set_draw_color(233,236,240); pdf.rect(16,y,pw,h,"DF")
            pdf.set_xy(20,y+3); setf("B",6.8); pdf.set_text_color(32,78,115); pdf.multi_cell(pw-8,4.0,"["+str(i)+"] "+tier,align="L")
            pdf.set_xy(20,pdf.get_y()+1.5); setf("",8.0); pdf.set_text_color(43,49,58)
            # Multi-cell cannot carry one hyperlink reliably across lines; the domain line is linked deterministically.
            pdf.multi_cell(pw-8,4.5,title,align="L")
            pdf.set_xy(20,pdf.get_y()+1); setf("",6.7); pdf.set_text_color(112,119,130); _creation_link_cell(pdf,pw-8,3.8,host,url)
            pdf.set_y(y+h+2)

    pdf.output(out)
    return out

def _creation_pdf_qa(path, content, research, quality):
    """v13.27 fail-closed publication QA, including metadata/KPI/layout regressions."""
    issues=[]
    if not path or not os.path.exists(path) or os.path.getsize(path)<1500: issues.append("PDF missing or too small")
    c=_creation_ascii(_creation_strip_appendices(content))
    if re.search(r"\b(?:\w+\?\w+|\d+\?%)\b",c): issues.append("broken glyph/mojibake pattern")
    if quality.get("grade") in ("D",): issues.append("evidence grade D")
    if quality.get("used_sources",0)>=4 and quality.get("authoritative",0)<2: issues.append("insufficient high-authority cited evidence")
    # Internal evidence metadata must never become analytical-body content or KPI tiles.
    body_no_appendix=_creation_strip_appendices(content or "")
    if re.search(r"(?:AUTHORITY\s*=|SCORE\s*=\s*\d/5|PRIMARY/INSTITUTIONAL\s+SCORE)",body_no_appendix,re.I):
        issues.append("source/evidence metadata leaked into report body")
    try:
        import fitz
        doc=fitz.open(path); pages=len(doc)
        if pages<3: issues.append("publication too short")
        if pages>14: issues.append("publication excessively long")
        for i,p in enumerate(doc):
            txt=p.get_text("text") or ""
            if i>0 and len(txt)>5600: issues.append("page "+str(i+1)+" is too dense")
            if txt.count("http://") + txt.count("https://") > 2: issues.append("raw URL wall on page "+str(i+1))
            # v13.26 regression signature: evidence-source metadata rendered as KPI tiles.
            if "KEY NUMBERS" in txt and re.search(r"AUTHORITY=|SCORE=\s*5/5|PRIMARY/INSTITUTIONAL",txt,re.I):
                issues.append("invalid evidence metadata in Key Numbers panel")
            # Fixed-width clipping often left truncated words at a line edge. This is a heuristic warning only.
            for ln in txt.splitlines():
                st=ln.strip()
                if re.search(r"\b(?:announcemen|reported mon|missile strikes in k)$",st,re.I):
                    issues.append("clipped table text on page "+str(i+1)); break
        doc.close()
    except Exception:
        pass
    # stable de-duplication
    seen=[]
    for x in issues:
        if x not in seen: seen.append(x)
    return seen

def _creation_report_content_gate(content,research):
    ok,reasons=_report_content_gate(content,research,currentish=True)
    if not ok: return ok,reasons
    used=_creation_used_source_ids(content)
    if research and len(used)<4: reasons.append("fewer than 4 cited sources")
    # Material current reports need at least 2 high-authority sources actually cited.
    used_rows=[research[i-1] for i in used if 1<=i<=len(research)]
    if used_rows and sum(1 for r in used_rows if r.get("score",0)>=4)<2: reasons.append("too few authoritative cited sources")
    # Reject oversized evidence/debug appendices in model output.
    if re.search(r"(?im)^\s*(EVIDENCE INDEX|SOURCE REGISTER|RESEARCH EVIDENCE)\s*:",content or ""):
        # not fatal; deterministic renderer strips them. Their presence is not a content-quality failure.
        pass
    return (not reasons),reasons


def make_pdf(chat_id, topic, email_to="", godmode=None):
    """v13.26 PUBLISHER GODMODE: research -> analysis -> evidence QA -> visual information design -> PDF QA."""
    topic=(topic or "").strip(); is_code=_pdf_is_code(topic)
    is_course=bool(re.search(r"\b(course|learn|teach|tutorial|lessons?|study guide|syllabus|curriculum|beginner|basics of|how to learn)\b",topic,re.I))
    if godmode is None: godmode=not (is_code or is_course)
    # Keep mature legacy paths for code/course artifacts; v13.26 focuses the new publisher on analytical reports.
    if is_code or is_course:
        return _MAKE_PDF_V1325(chat_id,topic,email_to,godmode)

    tg("sendMessage",chat_id=chat_id,text="NEMO PUBLISHER GODMODE 5.0\n"+topic+"\n\nResearch -> source curation -> analyst -> verifier -> executive editor -> visual design -> PDF QA")
    research=_report_research(topic,min_good=6 if godmode else 4,max_sources=18 if godmode else 12)
    preq=_report_research_quality(research)
    if godmode and (len(research)<6 or sum(1 for r in research if r.get("score",0)>=4)<3):
        tg("sendMessage",chat_id=chat_id,text="Evidence quality is below publication standard; widening toward primary/institutional sources...")
        extra=_report_research(topic+" official primary institutional evidence",min_good=5,max_sources=20)
        seen={_creation_norm_source_key(r) for r in research}; research += [r for r in extra if _creation_norm_source_key(r) not in seen]
        research=sorted(research,key=lambda r:(r.get("score",0),len(r.get("body",""))),reverse=True)[:20]
    if godmode and (len(research)<4 or sum(1 for r in research if r.get("score",0)>=4)<2):
        send_text(chat_id,"Publication stopped: not enough high-quality attributable evidence. I will not disguise weak research with a polished PDF.")
        return

    packet=_report_source_packet(research)
    prompt=_report_structure_prompt(topic,packet)
    # Materiality instruction: prevent search-snippet accidents from defining the agenda.
    prompt += ("\n\nPUBLISHER GODMODE ADDITIONAL RULES: Prioritize developments by MATERIALITY to the user's topic, not by search-result order. "
               "For geopolitical reports, major conflict systems, great-power competition, energy/trade routes, sanctions/technology, cyber/critical infrastructure and India transmission channels outrank minor domestic anecdotes unless directly material. "
               "Separate VERIFIED FACT, ASSESSMENT, SCENARIO and UNKNOWN. Do not assign a precise scenario number unless evidence explicitly supports it.")
    draft=ask_ai(chat_id,prompt,remember=False,timeout=300,long_output=True,models_override=WRITER_MODELS,ground=market_context(topic))
    verified=_report_verify_draft(chat_id,topic,draft,packet) if godmode else draft
    edited=_report_final_editor(chat_id,topic,verified or draft,packet) if godmode else (verified or draft)
    content=_creation_strip_appendices(edited or verified or draft)
    ok,reasons=_creation_report_content_gate(content,research)
    if not ok and godmode:
        repair=("Return the COMPLETE corrected report only. Fix these publication QA failures: "+"; ".join(reasons)+". "
                "Use only supplied evidence; prioritize material developments; remove weak unsupported claims; preserve citations.\n\nREPORT:\n"+content[:18000]+"\n\nEVIDENCE:\n"+packet[:18000])
        content=_creation_strip_appendices(ask_ai(chat_id,repair,remember=False,timeout=300,long_output=True,models_override=SMART_MODELS))
        ok,reasons=_creation_report_content_gate(content,research)
    if not ok:
        send_text(chat_id,"Publisher QA refused this draft: "+"; ".join(reasons)+". No weak artifact was delivered.")
        return

    quality=_report_research_quality(research,content)
    if godmode and quality.get("grade") in ("D",):
        send_text(chat_id,"Publisher QA refused publication because cited evidence quality graded D.")
        return

    fname="".join(c for c in _creation_short_title(topic) if c.isalnum() or c in " -_").strip().replace(" ","_")[:48] or "Nemo_Report"
    out="/tmp/nemo_publisher_"+str(chat_id)+"_"+str(int(time.time()))+".pdf"; manifest_path=out[:-4]+".research.json"
    _report_write_manifest(topic,research,quality,content,manifest_path)
    try:
        _creation_render_pdf(topic,content,research,quality,out,godmode=True,subtitle="Strategic Intelligence Report | Prepared by Nemo")
        qa,issues=_creation_pdf_qa(out,content,research,quality)
        if not qa:
            send_text(chat_id,"Publisher visual QA stopped delivery: "+"; ".join(issues)+". The PDF was not sent.")
            return
    except Exception as e:
        traceback.print_exc(); send_text(chat_id,"Publisher rendering failed ("+type(e).__name__+"): "+str(e)[:260]); return

    sent=send_document(chat_id,out,fname+".pdf","application/pdf")
    if sent: LASTFILE[chat_id]=out
    if email_to and sent:
        if send_email(email_to,_creation_short_title(topic),"Your Nemo Publisher Godmode report is attached.\n\n- Nemo",out):
            send_text(chat_id,"Also emailed the SAME QA-passed PDF to "+email_to+"."); act_log("email","publisher pdf '"+topic[:40]+"' -> "+email_to)
        else: send_text(chat_id,"PDF created, but email failed: "+(LAST_EMAIL_ERR or "unknown"))
    if sent:
        send_text(chat_id,"Publisher QA: PASS | Evidence "+quality.get("grade","D")+" ("+str(quality.get("score",0))+"/100) | "+str(quality.get("used_sources",0))+" cited sources | "+str(quality.get("authoritative",0))+" high-authority")
        act_log("report","publisher godmode sources="+str(len(research))+" grade="+quality.get("grade","D")+" manifest="+manifest_path)



# ==================== v13.28 NEMO PRIME FOUNDATION ====================
import uuid as _prime_uuid
import contextvars as _prime_contextvars
import subprocess as _prime_subprocess
import ast as _prime_ast
import sys as _prime_sys

_PRIME_DB = os.environ.get("NEMO_PRIME_DB", "/root/nemo_prime.db")
_PRIME_LOCK = threading.RLock()
_PRIME_TRACE = _prime_contextvars.ContextVar("nemo_trace", default="")
_PRIME_CURRENT_TASK = _prime_contextvars.ContextVar("nemo_task", default="")
_PRIME_READY = False


def _prime_conn():
    c = sqlite3.connect(_PRIME_DB, timeout=15)
    c.row_factory = sqlite3.Row
    try: c.execute("PRAGMA journal_mode=WAL")
    except Exception: pass
    return c


def _prime_init():
    global _PRIME_READY
    if _PRIME_READY: return
    with _PRIME_LOCK:
        if _PRIME_READY: return
        c = _prime_conn()
        c.executescript("""
        CREATE TABLE IF NOT EXISTS prime_tasks(
          id TEXT PRIMARY KEY, created REAL, updated REAL, owner TEXT, kind TEXT, goal TEXT,
          status TEXT, progress REAL DEFAULT 0, step TEXT DEFAULT '', retries INTEGER DEFAULT 0,
          result TEXT DEFAULT '', error TEXT DEFAULT '', parent TEXT DEFAULT '', meta TEXT DEFAULT '{}');
        CREATE INDEX IF NOT EXISTS idx_prime_tasks_status ON prime_tasks(status,updated);
        CREATE TABLE IF NOT EXISTS prime_traces(
          id TEXT PRIMARY KEY, ts REAL, task_id TEXT, stage TEXT, name TEXT, duration_ms REAL,
          ok INTEGER, detail TEXT, meta TEXT DEFAULT '{}');
        CREATE INDEX IF NOT EXISTS idx_prime_traces_ts ON prime_traces(ts);
        CREATE TABLE IF NOT EXISTS prime_policy_audit(
          id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, actor TEXT, action TEXT, resource TEXT,
          decision TEXT, reason TEXT, context TEXT DEFAULT '{}');
        CREATE TABLE IF NOT EXISTS prime_strategy(
          fingerprint TEXT PRIMARY KEY, task_class TEXT, strategy TEXT, attempts INTEGER DEFAULT 0,
          successes INTEGER DEFAULT 0, avg_ms REAL DEFAULT 0, last_ts REAL, notes TEXT DEFAULT '');
        CREATE TABLE IF NOT EXISTS prime_knowledge(
          id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT, title TEXT, body TEXT, tags TEXT,
          updated REAL, sha TEXT UNIQUE);
        CREATE INDEX IF NOT EXISTS idx_prime_knowledge_source ON prime_knowledge(source);
        """)
        try:
            c.execute("CREATE VIRTUAL TABLE IF NOT EXISTS prime_knowledge_fts USING fts5(title,body,tags,content='prime_knowledge',content_rowid='id')")
            c.executescript("""
            CREATE TRIGGER IF NOT EXISTS pk_ai AFTER INSERT ON prime_knowledge BEGIN
              INSERT INTO prime_knowledge_fts(rowid,title,body,tags) VALUES(new.id,new.title,new.body,new.tags);
            END;
            CREATE TRIGGER IF NOT EXISTS pk_ad AFTER DELETE ON prime_knowledge BEGIN
              INSERT INTO prime_knowledge_fts(prime_knowledge_fts,rowid,title,body,tags) VALUES('delete',old.id,old.title,old.body,old.tags);
            END;
            CREATE TRIGGER IF NOT EXISTS pk_au AFTER UPDATE ON prime_knowledge BEGIN
              INSERT INTO prime_knowledge_fts(prime_knowledge_fts,rowid,title,body,tags) VALUES('delete',old.id,old.title,old.body,old.tags);
              INSERT INTO prime_knowledge_fts(rowid,title,body,tags) VALUES(new.id,new.title,new.body,new.tags);
            END;
            """)
        except Exception:
            pass
        c.commit(); c.close(); _PRIME_READY = True


def _prime_id(prefix="T"):
    return prefix + "-" + _prime_uuid.uuid4().hex[:10].upper()


def _prime_json(x):
    try: return json.dumps(x or {}, ensure_ascii=False, default=str)[:12000]
    except Exception: return "{}"


# ---- Unified Task OS ----
def prime_task_create(goal, kind="general", owner="", parent="", meta=None):
    _prime_init(); tid=_prime_id("TASK"); now=time.time(); c=_prime_conn()
    c.execute("INSERT INTO prime_tasks(id,created,updated,owner,kind,goal,status,parent,meta) VALUES(?,?,?,?,?,?,?,?,?)",
              (tid,now,now,str(owner or ""),str(kind or "general")[:80],str(goal or "")[:8000],"QUEUED",str(parent or ""),_prime_json(meta)))
    c.commit(); c.close(); return tid


def prime_task_update(tid,status=None,progress=None,step=None,result=None,error=None,retries=None,meta=None):
    _prime_init(); fields=["updated=?"]; vals=[time.time()]
    vals_map=(("status",status),("progress",progress),("step",step),("result",result),("error",error),("retries",retries),("meta",_prime_json(meta) if meta is not None else None))
    for k,v in vals_map:
        if v is not None: fields.append(k+"=?"); vals.append(v)
    vals.append(tid); c=_prime_conn(); c.execute("UPDATE prime_tasks SET "+",".join(fields)+" WHERE id=?", vals); c.commit(); c.close()


def prime_task_get(tid):
    _prime_init(); c=_prime_conn(); r=c.execute("SELECT * FROM prime_tasks WHERE id=?",(tid,)).fetchone(); c.close(); return dict(r) if r else None


def prime_task_list(limit=20,status=None):
    _prime_init(); c=_prime_conn()
    if status: rows=c.execute("SELECT * FROM prime_tasks WHERE status=? ORDER BY updated DESC LIMIT ?",(status,int(limit))).fetchall()
    else: rows=c.execute("SELECT * FROM prime_tasks ORDER BY updated DESC LIMIT ?",(int(limit),)).fetchall()
    c.close(); return [dict(r) for r in rows]


def prime_task_import_legacy():
    _prime_init(); n=0
    try:
        for j in (JOBS or [])[-100:]:
            if not isinstance(j,dict): continue
            key="legacy-job:"+str(j.get("id") or j.get("t") or hash(str(j)))
            c=_prime_conn(); exists=c.execute("SELECT 1 FROM prime_tasks WHERE parent=?",(key,)).fetchone(); c.close()
            if not exists:
                tid=prime_task_create(j.get("task") or j.get("goal") or str(j),"legacy_work",OWNER.get("id"),key,{"legacy":True,"state":j.get("status")})
                st=str(j.get("status") or "QUEUED").upper(); prime_task_update(tid,status=st if st in ("QUEUED","RUNNING","DONE","FAILED","CANCELLED","WAITING") else "QUEUED"); n+=1
    except Exception: pass
    try:
        for wid,w in list((WORKFLOWS or {}).items())[-100:]:
            if not isinstance(w,dict): continue
            key="legacy-workflow:"+str(wid); c=_prime_conn(); exists=c.execute("SELECT 1 FROM prime_tasks WHERE parent=?",(key,)).fetchone(); c.close()
            if not exists:
                tid=prime_task_create(w.get("goal") or w.get("task") or ("workflow "+str(wid)),"workflow",OWNER.get("id"),key,{"legacy":True,"current":w.get("current")})
                st=str(w.get("status") or "QUEUED").upper(); prime_task_update(tid,status=st if st in ("QUEUED","RUNNING","DONE","FAILED","CANCELLED","WAITING") else "QUEUED"); n+=1
    except Exception: pass
    return n


# ---- Central Policy Engine ----
_PRIME_POLICY_DEFAULT = {
 "read.web":"AUTO_SAFE", "read.files":"AUTO_SAFE", "read.system":"AUTO_SAFE", "analyze":"AUTO_SAFE",
 "download.media":"AUTO_SAFE", "create.artifact":"AUTO_SAFE",
 "email.send":"OWNER_APPROVAL", "browser.submit":"OWNER_APPROVAL", "device.command":"OWNER_APPROVAL",
 "service.restart":"OWNER_APPROVAL", "file.write.system":"OWNER_APPROVAL", "cyber.remediate":"OWNER_APPROVAL",
 "trade.order":"ALWAYS_CONFIRM", "money.transfer":"ALWAYS_CONFIRM", "account.delete":"ALWAYS_CONFIRM",
 "self.update":"ALWAYS_CONFIRM", "secret.export":"FORBIDDEN", "device.unenrolled":"FORBIDDEN"
}


def prime_policy_decide(action,resource="",actor="",context=None):
    _prime_init(); action=str(action or "").strip().lower(); resource=str(resource or "")
    rule=_PRIME_POLICY_DEFAULT.get(action)
    if rule is None:
        if action.startswith(("read.","inspect.","analyze.")): rule="AUTO_SAFE"
        elif any(x in action for x in ("delete","destroy","trade","payment","transfer","secret","credential")): rule="ALWAYS_CONFIRM"
        else: rule="OWNER_APPROVAL"
    reason="policy="+rule
    try:
        c=_prime_conn(); c.execute("INSERT INTO prime_policy_audit(ts,actor,action,resource,decision,reason,context) VALUES(?,?,?,?,?,?,?)",
                                   (time.time(),str(actor or ""),action,resource,rule,reason,_prime_json(context))); c.commit(); c.close()
    except Exception: pass
    return rule,reason


# ---- Flight Recorder / Observability ----
def prime_trace_start(stage,name,task_id="",meta=None):
    _prime_init(); trace=_PRIME_TRACE.get() or _prime_id("TR")
    if not _PRIME_TRACE.get(): _PRIME_TRACE.set(trace)
    return {"id":trace,"t":time.perf_counter(),"stage":stage,"name":name,"task":task_id or _PRIME_CURRENT_TASK.get(),"meta":meta or {}}


def prime_trace_end(tok,ok=True,detail="",meta=None):
    try:
        ms=(time.perf_counter()-tok["t"])*1000.0; c=_prime_conn(); span=_prime_id("SP")
        m=dict(tok.get("meta") or {}); m.update(meta or {}); m["trace_id"]=tok.get("id")
        c.execute("INSERT INTO prime_traces(id,ts,task_id,stage,name,duration_ms,ok,detail,meta) VALUES(?,?,?,?,?,?,?,?,?)",
                  (span,time.time(),tok.get("task") or "",tok.get("stage") or "",tok.get("name") or "",round(ms,2),1 if ok else 0,str(detail or "")[:4000],_prime_json(m)))
        c.commit(); c.close(); return ms
    except Exception: return 0.0


def prime_trace_recent(limit=30):
    _prime_init(); c=_prime_conn(); rows=c.execute("SELECT * FROM prime_traces ORDER BY ts DESC LIMIT ?",(int(limit),)).fetchall(); c.close(); return [dict(r) for r in rows]


# Mature ask_ai behavior is preserved; this wrapper only records performance/outcome.
_ASK_AI_V1327 = ask_ai

def ask_ai(chat_id, text, image_b64=None, remember=True, timeout=180,
           long_output=False, models_override=None, deep=False, ground="", raw=False):
    tok=prime_trace_start("brain","ask_ai",meta={"vision":bool(image_b64),"long":bool(long_output),"deep":bool(deep),"raw":bool(raw)})
    try:
        ans=_ASK_AI_V1327(chat_id,text,image_b64=image_b64,remember=remember,timeout=timeout,
                           long_output=long_output,models_override=models_override,deep=deep,ground=ground,raw=raw)
        dbg=str(DEBUG.get(chat_id,""))[:240] if isinstance(DEBUG,dict) else ""
        ms=prime_trace_end(tok,True,"ok",{"chars":len(str(ans or "")),"debug":dbg})
        try: prime_strategy_record(_prime_task_class(text),"brain-route:"+(dbg.splitlines()[0][:100] if dbg else "unknown"),True,ms)
        except Exception: pass
        return ans
    except Exception as e:
        ms=prime_trace_end(tok,False,type(e).__name__+": "+str(e)[:500])
        try: prime_strategy_record(_prime_task_class(text),"brain-route",False,ms,str(e)[:180])
        except Exception: pass
        raise


# ---- Strategy Learning 2.0 ----
def _prime_task_class(text):
    t=(text or "").lower()
    if any(x in t for x in ("pdf","report","research")): return "research_artifact"
    if any(x in t for x in ("image","screenshot","photo","ocr","bill")): return "vision"
    if any(x in t for x in ("browser","website","login","form")): return "browser"
    if any(x in t for x in ("python","code","script","debug","error")): return "coding"
    if any(x in t for x in ("nifty","banknifty","stock","trade","market")): return "market"
    if any(x in t for x in ("server","vps","service","process")): return "systems"
    return "general"


def prime_strategy_record(task_class,strategy,success,ms,notes=""):
    _prime_init(); fp=hashlib.sha256((str(task_class)+"|"+str(strategy)).encode()).hexdigest()[:24]
    with _PRIME_LOCK:
        c=_prime_conn(); r=c.execute("SELECT * FROM prime_strategy WHERE fingerprint=?",(fp,)).fetchone()
        if not r:
            c.execute("INSERT INTO prime_strategy(fingerprint,task_class,strategy,attempts,successes,avg_ms,last_ts,notes) VALUES(?,?,?,?,?,?,?,?)",
                      (fp,task_class,strategy,1,1 if success else 0,float(ms or 0),time.time(),str(notes or "")[:1000]))
        else:
            a=int(r["attempts"])+1; su=int(r["successes"])+(1 if success else 0); avg=((float(r["avg_ms"])*int(r["attempts"]))+float(ms or 0))/a
            c.execute("UPDATE prime_strategy SET attempts=?,successes=?,avg_ms=?,last_ts=?,notes=? WHERE fingerprint=?",
                      (a,su,avg,time.time(),str(notes or r["notes"] or "")[:1000],fp))
        c.commit(); c.close()


def prime_strategy_rank(task_class,limit=8):
    _prime_init(); c=_prime_conn(); rows=c.execute("SELECT *, CASE WHEN attempts>0 THEN 1.0*successes/attempts ELSE 0 END sr FROM prime_strategy WHERE task_class=? ORDER BY sr DESC, attempts DESC, avg_ms ASC LIMIT ?",(task_class,int(limit))).fetchall(); c.close(); return [dict(r) for r in rows]


# ---- Knowledge Lake / Hybrid Offline Retrieval ----
def _prime_knowledge_add(source,title,body,tags=""):
    _prime_init(); body=str(body or "").strip()
    if len(body)<20: return False
    sha=hashlib.sha256((str(source)+"\n"+str(title)+"\n"+body).encode("utf-8","ignore")).hexdigest()
    try:
        c=_prime_conn(); c.execute("INSERT OR IGNORE INTO prime_knowledge(source,title,body,tags,updated,sha) VALUES(?,?,?,?,?,?)",
                                   (str(source)[:500],str(title)[:500],body[:120000],str(tags)[:1000],time.time(),sha)); c.commit(); c.close(); return True
    except Exception: return False


def prime_knowledge_rebuild():
    _prime_init(); n=0
    try:
        for k,v in list((FACTS or {}).items()):
            if _prime_knowledge_add("FACTS",str(k),json.dumps(v,ensure_ascii=False,default=str),"memory facts"): n+=1
    except Exception: pass
    try:
        for k,v in list((DOCS or {}).items()):
            txt=v if isinstance(v,str) else json.dumps(v,ensure_ascii=False,default=str)
            if _prime_knowledge_add("DOCS",str(k),txt,"documents"): n+=1
    except Exception: pass
    roots=["/root/nemo_knowledge","/root/apps"]; exts={".txt",".md",".py",".json",".csv",".log",".yaml",".yml",".html",".js"}
    for root in roots:
        if not os.path.isdir(root): continue
        count=0
        for dp,dn,fn in os.walk(root):
            dn[:]=[d for d in dn if not d.startswith('.') and d not in ('node_modules','venv','.venv','__pycache__')]
            for f in fn:
                p=os.path.join(dp,f); ext=os.path.splitext(f)[1].lower()
                if ext not in exts: continue
                try:
                    if os.path.getsize(p)>2_000_000: continue
                    txt=open(p,'r',encoding='utf-8',errors='ignore').read()
                    if _prime_knowledge_add(p,f,txt,"local file"): n+=1
                    count+=1
                    if count>=1000: break
                except Exception: pass
            if count>=1000: break
    return n


def prime_knowledge_search(q,limit=8):
    _prime_init(); q=(q or "").strip()
    if not q: return []
    c=_prime_conn(); rows=[]
    try:
        terms=" ".join(re.findall(r"[A-Za-z0-9_]{2,}",q)[:16])
        if terms:
            rows=c.execute("SELECT k.*, bm25(prime_knowledge_fts) rank FROM prime_knowledge_fts f JOIN prime_knowledge k ON k.id=f.rowid WHERE prime_knowledge_fts MATCH ? ORDER BY rank LIMIT ?",(terms,int(limit))).fetchall()
    except Exception: rows=[]
    if not rows:
        like="%"+q[:120].replace("%","")+"%"; rows=c.execute("SELECT *,0 rank FROM prime_knowledge WHERE title LIKE ? OR body LIKE ? ORDER BY updated DESC LIMIT ?",(like,like,int(limit))).fetchall()
    c.close(); return [dict(r) for r in rows]


# ---- Evaluation Laboratory ----
def prime_eval_file(path):
    result={"path":path,"compile":False,"ast":False,"version":"?","functions":0,"duplicates":[],"size":0,"sha":"","critical":[]}
    try:
        data=open(path,'rb').read(); result["size"]=len(data); result["sha"]=hashlib.sha256(data).hexdigest(); text=data.decode('utf-8','replace')
        m=re.search(r"(?m)^VERSION\s*=\s*['\"]([^'\"]+)",text); result["version"]=m.group(1) if m else "?"
        tree=_prime_ast.parse(text); result["ast"]=True; names={}
        for node in tree.body:
            if isinstance(node,(_prime_ast.FunctionDef,_prime_ast.AsyncFunctionDef)): names[node.name]=names.get(node.name,0)+1
        result["functions"]=sum(names.values()); result["duplicates"]=[k for k,v in names.items() if v>1][:50]
        cp=_prime_subprocess.run([_prime_sys.executable,"-m","py_compile",path],capture_output=True,text=True,timeout=40); result["compile"]=(cp.returncode==0)
        if cp.returncode: result["critical"].append((cp.stderr or cp.stdout)[-1000:])
        for must in ("def handle(","def main(","def ask_ai(","VERSION ="):
            if must not in text: result["critical"].append("missing "+must)
        if "TELEGRAM_TOKEN" not in text: result["critical"].append("telegram configuration marker missing")
    except Exception as e: result["critical"].append(type(e).__name__+": "+str(e))
    result["pass"]=bool(result["compile"] and result["ast"] and not result["critical"]); return result


def prime_eval_current(): return prime_eval_file(os.path.abspath(__file__))


# ---- Trade State Reconciliation 2.0 ----
def prime_trade_reconcile_boot():
    p=AUTO.get("pos")
    if not isinstance(p,dict):
        if p is not None: AUTO["pos"]=None; save_data(); return "cleared corrupt position state"
        return "none"
    sym=str(p.get("symbol") or ""); qty=p.get("qty"); entry=p.get("entry"); at=float(p.get("at") or 0)
    if not sym or not qty or not entry:
        if AUTO.get("mode")!="live": AUTO["pos"]=None; save_data(); return "cleared incomplete shadow position"
        return "live state incomplete; preserved"
    if AUTO.get("mode")!="live":
        age=max(0,time.time()-at) if at else 10**9
        try: today=fyers_today()
        except Exception: today=time.strftime("%Y-%m-%d")
        stale_day=bool(AUTO.get("day") and str(AUTO.get("day"))!=str(today))
        if stale_day or age>18*3600:
            old=dict(p); AUTO["pos"]=None; save_data()
            try: AUTOLOG.append({"sym":old.get("symbol"),"entry":old.get("entry"),"exit":old.get("entry"),"qty":old.get("qty"),"pnl":0.0,"why":old.get("reason",""),"exit_reason":"stale-shadow-reconciled","brain":AUTO.get("brain"),"mode":"shadow","t":time.time()})
            except Exception: pass
            return "cleared stale shadow position "+sym
        return "valid shadow position"
    return "live position preserved; broker remains source of truth"


# ---- Enrolled Device Agent Generator ----
def prime_device_agent_script(base_url,enroll_token,name):
    """Device Agent 2.0: telemetry + bounded read-only diagnostic jobs; never arbitrary shell."""
    tpl="#!/usr/bin/env python3\nimport json, os, platform, time, urllib.request, shutil, subprocess, socket\nBASE=__BASE__.rstrip('/')\nENROLL=__ENROLL__\nNAME=__NAME__\nSTATE=os.path.expanduser('~/.nemo_device.json'); PENDING=[]\ndef post(url,obj,auth=''):\n    h={'Content-Type':'application/json'}\n    if auth:h['Authorization']='Bearer '+auth\n    req=urllib.request.Request(BASE+url,data=json.dumps(obj).encode(),headers=h,method='POST')\n    return json.loads(urllib.request.urlopen(req,timeout=25).read().decode())\ndef load_state():\n    try:return json.load(open(STATE))\n    except Exception:return {}\ndef save_state(x):\n    with open(STATE,'w') as f:json.dump(x,f)\n    try:os.chmod(STATE,0o600)\n    except Exception:pass\ndef enroll():\n    st=load_state()\n    if st.get('device_id') and st.get('device_secret'):return st\n    r=post('/api/device/enroll',{'token':ENROLL,'name':NAME,'platform':platform.system(),'hostname':platform.node()})\n    if not r.get('device_id') or not r.get('device_secret'):raise RuntimeError('enrollment failed')\n    save_state(r);return r\ndef run(cmd,timeout=8):\n    try:\n        p=subprocess.run(cmd,capture_output=True,text=True,timeout=timeout);return (p.stdout or p.stderr)[-8000:]\n    except Exception as e:return type(e).__name__+': '+str(e)\ndef telemetry():\n    t={'os':platform.platform(),'arch':platform.machine(),'user':os.environ.get('USER') or os.environ.get('USERNAME')}\n    try:t['local_ip']=socket.gethostbyname(socket.gethostname())\n    except Exception:pass\n    try:\n        total,used,free=shutil.disk_usage(os.path.expanduser('~'));t['disk_pct']=round(100*used/max(total,1),1)\n    except Exception:pass\n    try:\n        with open('/proc/uptime') as f:t['uptime_s']=float(f.read().split()[0])\n        with open('/proc/meminfo') as f:m={a:int(b.split()[0]) for a,b in (ln.split(':',1) for ln in f if ':' in ln)};t['mem_pct']=round(100*(1-m.get('MemAvailable',0)/max(m.get('MemTotal',1),1)),1)\n    except Exception:pass\n    return t\ndef execute(j):\n    kind=j.get('kind');a=j.get('args') or {};res=''\n    if kind=='sysinfo':res=json.dumps(telemetry(),indent=2)\n    elif kind=='disk':res=run(['df','-h']) if os.name!='nt' else run(['wmic','logicaldisk','get','size,freespace,caption'])\n    elif kind=='processes':res=run(['ps','aux']) if os.name!='nt' else run(['tasklist'])\n    elif kind=='network':res=run(['ss','-lntup']) if os.name!='nt' else run(['netstat','-ano'])\n    elif kind=='service_status':\n        svc=str(a.get('service') or '')[:80]\n        if not svc:return {'id':j.get('id'),'ok':False,'error':'service required'}\n        res=run(['systemctl','status','--no-pager',svc]) if os.name!='nt' else run(['sc','query',svc])\n    else:return {'id':j.get('id'),'ok':False,'error':'unsupported diagnostic'}\n    return {'id':j.get('id'),'ok':True,'result':res[:10000]}\nwhile True:\n    try:\n        st=enroll();payload={'telemetry':telemetry(),'job_results':PENDING};PENDING=[]\n        r=post('/api/device/'+st['device_id']+'/heartbeat',payload,st['device_secret'])\n        for j in (r.get('jobs') or [])[:3]:PENDING.append(execute(j))\n    except Exception as e:print('Nemo agent:',e)\n    time.sleep(30)\n"
    return tpl.replace('__BASE__',repr(base_url)).replace('__ENROLL__',repr(enroll_token)).replace('__NAME__',repr(name))


# ---- v13.31 Device Agents 2.0 + Remote Hands + Fleet ----
def _device_jobs_init(db):
    db.setdefault("jobs",{}); return db

def _device_pick(q):
    db=_device_load(); q=str(q or "").strip().lower()
    for did,d in db.get("devices",{}).items():
        if did.lower()==q or str(d.get("name","")).lower()==q: return did,d
    return None,None

def _device_queue_job(did,kind,args=None):
    allowed={"sysinfo","processes","service_status","disk","network"}
    if kind not in allowed: return None,"remote action is not in the diagnostic allowlist"
    with _DEVICE_LOCK:
        db=_device_jobs_init(_device_load())
        if did not in db.get("devices",{}): return None,"device not found"
        import uuid
        jid="job_"+uuid.uuid4().hex[:14]
        db["jobs"][jid]={"id":jid,"device_id":did,"kind":kind,"args":args or {},"state":"queued","created":time.time(),"result":None}
        _device_save(db)
    try: audit("device","queue_job",jid+" "+kind,"ok")
    except Exception: pass
    return jid,None

def _device_claim_jobs(did,secret):
    with _DEVICE_LOCK:
        dev,db=_device_auth(did,secret)
        if not dev:return []
        db=_device_jobs_init(db); out=[]
        for jid,j in list(db["jobs"].items()):
            if j.get("device_id")==did and j.get("state")=="queued" and len(out)<3:
                j["state"]="sent"; j["sent_at"]=time.time(); db["jobs"][jid]=j
                out.append({"id":jid,"kind":j.get("kind"),"args":j.get("args") or {}})
        _device_save(db); return out

def _device_job_results(did,secret,payload):
    results=payload.get("job_results") if isinstance(payload,dict) else None
    if not isinstance(results,list):return
    with _DEVICE_LOCK:
        dev,db=_device_auth(did,secret)
        if not dev:return
        db=_device_jobs_init(db)
        for r in results[:10]:
            if not isinstance(r,dict):continue
            jid=str(r.get("id") or ""); j=db["jobs"].get(jid)
            if not j or j.get("device_id")!=did:continue
            j["state"]="done" if r.get("ok") else "failed"; j["finished_at"]=time.time()
            j["result"]=str(r.get("result") or r.get("error") or "")[:12000]; db["jobs"][jid]=j
        _device_save(db)

def _device_fleet_text():
    db=_device_jobs_init(_device_load()); ds=list(db.get("devices",{}).values()); now=time.time()
    online=sum(1 for d in ds if _device_online(d) and not d.get("revoked")); revoked=sum(1 for d in ds if d.get("revoked"))
    jobs=list(db.get("jobs",{}).values()); queued=sum(1 for j in jobs if j.get("state") in ("queued","sent"))
    lines=["NEMO FLEET | Device Agents 2.0",f"Devices: {len(ds)} | Online: {online} | Offline: {max(0,len(ds)-online-revoked)} | Revoked: {revoked}",f"Diagnostic jobs pending: {queued}",""]
    for d in sorted(ds,key=lambda x:str(x.get("name",""))):
        age=now-float(d.get("last_seen") or 0); state="ONLINE" if _device_online(d) else "OFFLINE"
        t=d.get("telemetry") or {}; health=[]
        for k,label in (("cpu_pct","CPU"),("mem_pct","RAM"),("disk_pct","DISK"),("battery_pct","BAT")):
            if k in t:health.append(label+" "+str(t[k])+"%")
        lines.append(f"{state} | {d.get('name')} | {d.get('platform')} | seen {int(age)}s ago"+(" | "+" · ".join(health) if health else ""))
    return "\n".join(lines)[:3900]

def _device_job_text(q=""):
    db=_device_jobs_init(_device_load()); jobs=list(db.get("jobs",{}).values())
    if q: jobs=[j for j in jobs if j.get("id")==q]
    jobs=sorted(jobs,key=lambda j:float(j.get("created",0)),reverse=True)[:12]
    if not jobs:return "No device diagnostic jobs."
    lines=["DEVICE JOBS"]
    for j in jobs:
        lines.append(f"{j.get('id')} | {j.get('kind')} | {j.get('state')} | {j.get('device_id')}")
        if j.get("result"):lines.append("  "+str(j.get("result"))[:700].replace("\n"," | "))
    return "\n".join(lines)[:3900]

_DEVICE_HEARTBEAT_V1330=_device_heartbeat
def _device_heartbeat(did,secret,payload):
    ok,msg=_DEVICE_HEARTBEAT_V1330(did,secret,payload)
    if ok:
        try:_device_job_results(did,secret,payload)
        except Exception:pass
    return ok,msg

