# Whole Telegram request wrapper: produces one trace id per incoming message.
_HANDLE_V1328_OBS = handle

def handle(msg):
    try:
        chat_id=(msg.get('chat') or {}).get('id'); text=msg.get('text') or msg.get('caption') or ''
    except Exception:
        chat_id=''; text=''
    tok=prime_request_begin(chat_id,text); tr=prime_trace_start('request','telegram_handle',meta={'request_id':tok['id'],'class':tok['class']})
    try:
        r=_HANDLE_V1328_OBS(msg); prime_trace_end(tr,True,'handled'); prime_request_end(tok,True); return r
    except Exception as e:
        prime_trace_end(tr,False,type(e).__name__+': '+str(e)); prime_request_end(tok,False,type(e).__name__+': '+str(e)); raise


def _v1329_dispatch(chat_id,text,msg=None):
    raw=(text or '').strip(); low=raw.lower()
    if not low.startswith(('/obs','/observability','/trace','/eval','/prime')): return False
    if chat_id != OWNER.get('id'): send_text(chat_id,'Owner only.'); return True
    _prime_obs_init()
    if low in ('/prime','/prime status'):
        st=prime_observability_stats(24); ev=prime_eval_deep(os.path.abspath(__file__)); tasks=prime_task_list(8)
        send_text(chat_id,"NEMO PRIME v13.29\n\nTask OS: "+str(len(tasks))+" recent\nPolicy Engine: ACTIVE\nObservability: "+str(st['requests'])+" requests / "+str(st['success_rate'])+"% success (24h)\nLatency p50/p95: "+str(st['p50_ms'])+" / "+str(st['p95_ms'])+" ms\nEval Lab 2.0: "+('PASS' if ev['pass'] else 'CHECK')+" score "+str(ev['score'])+"\nKnowledge Lake: ACTIVE\nTrade reconciliation: ACTIVE\nTool/task correlation: report + browser + media\n\n/obs /trace /eval /taskos /policy /knowledge /strategies /agents")
        return True
    if low.startswith(('/obs','/observability')):
        parts=raw.split(); hours=24
        if len(parts)>1:
            try: hours=max(1,min(720,float(parts[1])))
            except Exception: pass
        st=prime_observability_stats(hours); lines=[f"FLIGHT RECORDER 2.0 | last {hours:g}h",f"Requests: {st['requests']} | Success: {st['success_rate']}% | Failures: {st['failures']}",f"Latency p50: {st['p50_ms']} ms | p95: {st['p95_ms']} ms",f"Brain p50: {st['brain_p50_ms']} ms | Spans: {st['spans']}","",'By task class:']
        for k,v in sorted(st['classes'].items(), key=lambda kv:kv[1]['n'], reverse=True): lines.append(f"{k}: {v['n']} req | fail {v['fail']} | p50 {v['p50_ms']}ms")
        send_text(chat_id,'\n'.join(lines)[:3900]); return True
    if low.startswith('/trace'):
        arg=raw[len('/trace'):].strip()
        if arg.lower() in ('','last'):
            c=_prime_conn(); r=c.execute("SELECT * FROM prime_requests ORDER BY ts DESC LIMIT 1").fetchone(); c.close()
            if not r: send_text(chat_id,'No request traces yet.'); return True
            arg=r['trace_id']
        if arg.lower()=='errors':
            c=_prime_conn(); rows=c.execute("SELECT * FROM prime_requests WHERE ok=0 ORDER BY ts DESC LIMIT 12").fetchall(); c.close(); send_text(chat_id,'RECENT REQUEST ERRORS\n'+('\n'.join(f"{r['trace_id']} | {r['task_class']} | {r['error'][:160]}" for r in rows) if rows else 'None.')); return True
        if arg.lower()=='stats':
            st=prime_observability_stats(24); send_text(chat_id,json.dumps(st,ensure_ascii=False,indent=2)[:3900]); return True
        req,spans=prime_trace_detail(arg); lines=['TRACE '+str((req or {}).get('trace_id') or arg)]
        if req: lines.append(f"Request: {req['task_class']} | {req['duration_ms']:.0f}ms | {'OK' if req['ok'] else 'FAIL'} | {req['text_hint'][:160]}")
        for r in spans[:30]: lines.append(f"{r['stage']}/{r['name']} | {r['duration_ms']:.0f}ms | {'OK' if r['ok'] else 'FAIL'} | {r['detail'][:120]}")
        send_text(chat_id,'\n'.join(lines)[:3900]); return True
    if low.startswith('/eval'):
        arg=raw[len('/eval'):].strip()
        if arg.lower()=='history':
            rows=prime_eval_history(); send_text(chat_id,'EVALUATION HISTORY\n'+('\n'.join(f"{r['id']} | {r['verdict']} {r['score']:.1f} | {os.path.basename(r['candidate_path'])}" for r in rows) if rows else 'No candidate evaluations yet.')); return True
        if arg.lower().startswith('compare '): arg=arg[8:].strip()
        if not arg or arg.lower() in ('self','current'):
            ev=prime_eval_deep(os.path.abspath(__file__)); send_text(chat_id,"EVALUATION LAB 2.0 — RUNNING BUILD\nVersion: "+ev['version']+"\nScore: "+str(ev['score'])+"/100\nCompile: "+str(ev['compile'])+" | AST: "+str(ev['ast'])+"\nFunctions: "+str(ev['functions'])+" | Duplicates: "+str(len(ev['duplicates']))+"\nMissing critical: "+(', '.join(ev['required_missing']) if ev['required_missing'] else 'none')+"\nWarnings: "+('; '.join(ev['syntax_risk']) if ev['syntax_risk'] else 'none')); return True
        if not os.path.isfile(arg): send_text(chat_id,'Candidate path not found on this VPS: '+arg); return True
        ev=prime_eval_compare(arg); lines=['EVALUATION LAB 2.0 — CANDIDATE',ev['summary']]
        if ev['blockers']: lines.append('BLOCKERS: '+'; '.join(ev['blockers']))
        if ev['warnings']: lines.append('WARNINGS: '+'; '.join(ev['warnings'][:12]))
        lines.append('Recommendation: '+ev['verdict']); send_text(chat_id,'\n'.join(lines)[:3900]); return True
    return False

# ==================== v13.30 KNOWLEDGE LAKE 2.0 + LEARNING CORE 2.0 ====================
import math as _rag_math
_RAG_READY=False
_RAG_LOCK=threading.RLock()
_RAG_DIM=768
_RAG_SYNONYMS={'error':['failure','bug','exception','issue'],'failure':['error','bug','problem'],'fix':['repair','solve','resolve'],'server':['vps','host','machine'],'computer':['pc','machine','device'],'phone':['mobile','device'],'money':['finance','cash','capital'],'loan':['debt','credit','emi'],'business':['company','commercial','enterprise'],'report':['analysis','study','brief'],'research':['study','analysis','evidence'],'security':['cyber','safety','hardening'],'trading':['market','trade','strategy'],'market':['trading','price','exchange'],'image':['photo','screenshot','vision'],'browser':['website','web','page'],'code':['programming','script','software'],'memory':['knowledge','recall','history']}

def _rag_init():
    global _RAG_READY
    if _RAG_READY:return
    _prime_init()
    with _RAG_LOCK:
        if _RAG_READY:return
        c=_prime_conn()
        c.executescript("""
        CREATE TABLE IF NOT EXISTS prime_rag_chunks(id INTEGER PRIMARY KEY AUTOINCREMENT,source TEXT,title TEXT,body TEXT,tags TEXT,source_ref TEXT DEFAULT '',chunk_no INTEGER DEFAULT 0,updated REAL,sha TEXT UNIQUE,vec TEXT DEFAULT '{}',token_count INTEGER DEFAULT 0,quality REAL DEFAULT 0.5);
        CREATE INDEX IF NOT EXISTS idx_rag_source ON prime_rag_chunks(source,updated);
        CREATE TABLE IF NOT EXISTS prime_episodes(id TEXT PRIMARY KEY,ts REAL,task_class TEXT,goal_hint TEXT,strategy TEXT,success INTEGER,duration_ms REAL,trace_id TEXT UNIQUE,result_hint TEXT DEFAULT '',feedback REAL DEFAULT 0);
        CREATE INDEX IF NOT EXISTS idx_episode_class ON prime_episodes(task_class,success,ts);
        """)
        try:
            c.execute("CREATE VIRTUAL TABLE IF NOT EXISTS prime_rag_fts USING fts5(title,body,tags,source,content='prime_rag_chunks',content_rowid='id')")
            c.executescript("""
            CREATE TRIGGER IF NOT EXISTS pr_ai AFTER INSERT ON prime_rag_chunks BEGIN INSERT INTO prime_rag_fts(rowid,title,body,tags,source) VALUES(new.id,new.title,new.body,new.tags,new.source); END;
            CREATE TRIGGER IF NOT EXISTS pr_ad AFTER DELETE ON prime_rag_chunks BEGIN INSERT INTO prime_rag_fts(prime_rag_fts,rowid,title,body,tags,source) VALUES('delete',old.id,old.title,old.body,old.tags,old.source); END;
            CREATE TRIGGER IF NOT EXISTS pr_au AFTER UPDATE ON prime_rag_chunks BEGIN INSERT INTO prime_rag_fts(prime_rag_fts,rowid,title,body,tags,source) VALUES('delete',old.id,old.title,old.body,old.tags,old.source); INSERT INTO prime_rag_fts(rowid,title,body,tags,source) VALUES(new.id,new.title,new.body,new.tags,new.source); END;
            """)
        except Exception:pass
        c.commit();c.close();_RAG_READY=True

def _rag_tokens(text):
    toks=re.findall(r"[a-z0-9][a-z0-9_+.-]{1,30}",str(text or '').lower())
    stop={'the','and','for','with','this','that','from','into','are','was','were','have','has','had','you','your','about','what','when','where','which','will','would','should','could','can','how','why','not','but','use','using','then','than','its','our','their','they','them','his','her','all','any','some','more','most','very','also','just','please'}
    out=[]
    for t in toks:
        if t in stop or len(t)<2:continue
        out.append(t);out.extend(_RAG_SYNONYMS.get(t,[])[:2])
    return out[:2500]

def _rag_vec(text):
    v={};toks=_rag_tokens(text)
    for i,t in enumerate(toks):
        h=int(hashlib.blake2b(t.encode('utf-8','ignore'),digest_size=8).hexdigest(),16);k=str(h%_RAG_DIM);sg=1.0 if ((h>>8)&1) else -1.0;v[k]=v.get(k,0.0)+sg*(1.0+0.12*min(len(t),12))
        if i and i<600:
            bg=toks[i-1]+'_'+t;hb=int(hashlib.blake2b(bg.encode(),digest_size=8).hexdigest(),16);kb=str(hb%_RAG_DIM);sg2=1.0 if ((hb>>8)&1) else -1.0;v[kb]=v.get(kb,0.0)+0.35*sg2
    n=_rag_math.sqrt(sum(x*x for x in v.values())) or 1.0
    return {k:round(x/n,6) for k,x in v.items() if abs(x/n)>0.015}

def _rag_cos(a,b):
    if not a or not b:return 0.0
    if len(a)>len(b):a,b=b,a
    return sum(v*b.get(k,0.0) for k,v in a.items())

def _rag_chunks(text,max_chars=1800,overlap=260):
    text=re.sub(r'\r','',str(text or '')).strip()
    if not text:return []
    paras=[p.strip() for p in re.split(r'\n\s*\n',text) if p.strip()];chunks=[];cur=''
    for p in paras:
        if len(cur)+len(p)+2<=max_chars:cur=(cur+'\n\n'+p).strip();continue
        if cur:chunks.append(cur)
        if len(p)<=max_chars:cur=p
        else:
            start=0
            while start<len(p):chunks.append(p[start:start+max_chars]);start+=max(300,max_chars-overlap)
            cur=''
    if cur:chunks.append(cur)
    return chunks[:4000]

def _rag_quality(source,title,body):
    s=str(source or '').lower();q=.55
    if s in ('facts','docs','builtin'):q+=.15
    if len(str(body or ''))>700:q+=.08
    if any(x in str(title or '').lower() for x in ('manual','documentation','official','report','guide')):q+=.07
    return max(.1,min(1.0,q))

def prime_rag_add(source,title,body,tags='',source_ref=''):
    _rag_init();n=0
    for i,ch in enumerate(_rag_chunks(body)):
        sha=hashlib.sha256((str(source_ref or source)+'|'+str(title)+'|'+ch).encode('utf-8','ignore')).hexdigest();vec=_rag_vec(str(title)+' '+str(tags)+' '+ch)
        try:
            c=_prime_conn();before=c.total_changes;c.execute("INSERT OR IGNORE INTO prime_rag_chunks(source,title,body,tags,source_ref,chunk_no,updated,sha,vec,token_count,quality) VALUES(?,?,?,?,?,?,?,?,?,?,?)",(str(source)[:100],str(title)[:500],ch,str(tags)[:600],str(source_ref)[:1000],i,time.time(),sha,json.dumps(vec,separators=(',',':')),len(_rag_tokens(ch)),_rag_quality(source,title,ch)));n+=1 if c.total_changes>before else 0;c.commit();c.close()
        except Exception:pass
    return n

def prime_rag_rebuild(clear=False):
    _rag_init();total=0;c=_prime_conn()
    if clear:
        c.execute('DELETE FROM prime_rag_chunks');c.commit()
        try:c.execute("INSERT INTO prime_rag_fts(prime_rag_fts) VALUES('rebuild')");c.commit()
        except Exception:pass
    rows=c.execute('SELECT source,title,body,tags FROM prime_knowledge ORDER BY updated DESC').fetchall();c.close()
    for r in rows:total+=prime_rag_add(r['source'],r['title'],r['body'],r['tags'],r['source'])
    try:
        for r in (_q('SELECT path,chunk FROM knowledge LIMIT 12000') or []):total+=prime_rag_add('LEGACY_KB',r['path'],r['chunk'],'legacy knowledge',r['path'])
    except Exception:pass
    return total

def prime_rag_search(query,limit=8):
    _rag_init();q=str(query or '').strip()
    if not q:return []
    qv=_rag_vec(q);candidates={};c=_prime_conn()
    try:
        terms=' OR '.join(dict.fromkeys(_rag_tokens(q)[:12]))
        if terms:
            for r in c.execute("SELECT k.*,bm25(prime_rag_fts) bm FROM prime_rag_fts f JOIN prime_rag_chunks k ON k.id=f.rowid WHERE prime_rag_fts MATCH ? ORDER BY bm LIMIT 50",(terms,)).fetchall():
                d=dict(r);d['lex']=1.0/(1.0+abs(float(d.get('bm') or 0)));candidates[d['id']]=d
    except Exception:pass
    for r in c.execute('SELECT * FROM prime_rag_chunks ORDER BY updated DESC LIMIT 1000').fetchall():candidates.setdefault(r['id'],dict(r))
    c.close();now=time.time();scored=[]
    for d in candidates.values():
        try:v=json.loads(d.get('vec') or '{}')
        except Exception:v={}
        sem=max(-1,min(1,_rag_cos(qv,v)));lex=float(d.get('lex') or 0);qual=float(d.get('quality') or .5);age=max(0,(now-float(d.get('updated') or now))/86400);fresh=1/(1+age/365);score=.58*max(0,sem)+.25*lex+.12*qual+.05*fresh
        if score>=.12:d['score']=round(score,4);d['semantic']=round(sem,4);scored.append(d)
    scored.sort(key=lambda x:x['score'],reverse=True);out=[];per={}
    for d in scored:
        key=(d.get('source_ref') or d.get('title') or '')[:200];per[key]=per.get(key,0)+1
        if per[key]>2:continue
        out.append(d)
        if len(out)>=int(limit):break
    return out

def prime_rag_context(query,limit=5,max_chars=6500):
    rows=prime_rag_search(query,limit);parts=[];used=0
    for i,r in enumerate(rows,1):
        x=f"[LOCAL-{i}] {r.get('title','')} | source={r.get('source','')} | score={r.get('score',0)}\n{r.get('body','')}"
        if used+len(x)>max_chars:break
        parts.append(x);used+=len(x)
    return '\n\n'.join(parts),rows

def _rag_should_ground(text,image=False):
    if image:return False
    t=str(text or '').lower()
    if len(t)<12:return False
    if re.search(r'\b(today|latest|current price|right now|breaking|live score|weather|news today|this screenshot|this image)\b',t):return False
    if re.search(r'\b(password|otp|private key|api key|secret token)\b',t):return False
    return True

def prime_episode_record(trace_id,task_class,goal_hint,success,duration_ms,result_hint=''):
    _rag_init();c=_prime_conn();spans=c.execute("SELECT stage,name FROM prime_traces WHERE json_extract(meta,'$.trace_id')=? ORDER BY ts",(trace_id,)).fetchall();seq=[]
    for r in spans:
        x=str(r['stage'])+'/'+str(r['name'])
        if not seq or seq[-1]!=x:seq.append(x)
    strategy=' -> '.join(seq[:20]) or 'direct';eid='EP-'+hashlib.sha256((str(trace_id)+'|'+strategy).encode()).hexdigest()[:12].upper()
    try:c.execute("INSERT OR IGNORE INTO prime_episodes(id,ts,task_class,goal_hint,strategy,success,duration_ms,trace_id,result_hint) VALUES(?,?,?,?,?,?,?,?,?)",(eid,time.time(),str(task_class),str(goal_hint)[:500],strategy,1 if success else 0,float(duration_ms or 0),str(trace_id),str(result_hint)[:800]));c.commit()
    except Exception:pass
    c.close();return strategy

def prime_episode_rank(task_class,limit=6):
    _rag_init();c=_prime_conn();rows=c.execute("SELECT strategy,COUNT(*) attempts,SUM(success) successes,AVG(duration_ms) avg_ms,MAX(ts) last_ts FROM prime_episodes WHERE task_class=? GROUP BY strategy ORDER BY (1.0*SUM(success)/COUNT(*)) DESC,COUNT(*) DESC,AVG(duration_ms) ASC LIMIT ?",(str(task_class),int(limit))).fetchall();c.close();return [dict(r) for r in rows]

def prime_learning_hint(text):
    rows=prime_episode_rank(_prime_task_class(text),3)
    if not rows or rows[0]['attempts']<2:return ''
    b=rows[0];rate=100*b['successes']/max(1,b['attempts']);return f"Previously effective workflow for this task class ({rate:.0f}% across {b['attempts']} attempts): {b['strategy']}. Use only if relevant; do not imitate failures."

_PRIME_REQUEST_END_V1329=prime_request_end
def prime_request_end(tok,ok=True,error=''):
    ms=_PRIME_REQUEST_END_V1329(tok,ok,error)
    try:
        c=_prime_conn();r=c.execute('SELECT * FROM prime_requests WHERE id=?',(tok.get('id'),)).fetchone();c.close()
        if r:prime_episode_record(r['trace_id'],r['task_class'],r['text_hint'],bool(r['ok']),r['duration_ms'],r['error'] if not r['ok'] else 'completed')
    except Exception:pass
    return ms

_ASK_AI_V1329_RAG=ask_ai
def ask_ai(chat_id,text,image_b64=None,remember=True,timeout=180,long_output=False,models_override=None,deep=False,ground='',raw=False):
    local_ctx='';rows=[]
    try:
        if _rag_should_ground(text,bool(image_b64)):local_ctx,rows=prime_rag_context(text,5,5200)
    except Exception:pass
    try:learn_hint=prime_learning_hint(text)
    except Exception:learn_hint=''
    extra=[]
    if ground:extra.append(str(ground))
    if local_ctx:extra.append('LOCAL KNOWLEDGE (may be stale; prefer fresh tools for current facts):\n'+local_ctx)
    if learn_hint:extra.append('LEARNED OPERATING EXPERIENCE:\n'+learn_hint)
    tok=prime_trace_start('knowledge','hybrid_rag',meta={'hits':len(rows),'grounded':bool(local_ctx)})
    try:
        ans=_ASK_AI_V1329_RAG(chat_id,text,image_b64=image_b64,remember=remember,timeout=timeout,long_output=long_output,models_override=models_override,deep=deep,ground='\n\n'.join(extra),raw=raw);prime_trace_end(tok,True,'hits='+str(len(rows)),{'top_score':rows[0]['score'] if rows else 0});return ans
    except Exception as e:prime_trace_end(tok,False,type(e).__name__+': '+str(e)[:300]);raise

def prime_rag_status():
    _rag_init();c=_prime_conn();chunks=c.execute('SELECT COUNT(*) FROM prime_rag_chunks').fetchone()[0];eps=c.execute('SELECT COUNT(*) FROM prime_episodes').fetchone()[0];src=c.execute('SELECT COUNT(DISTINCT source_ref) FROM prime_rag_chunks').fetchone()[0];c.close();return {'chunks':chunks,'sources':src,'episodes':eps,'dim':_RAG_DIM,'engine':'FTS5 + offline hashed sparse vectors'}

def _v1330_dispatch(chat_id,text,msg=None):
    raw=(text or '').strip();low=raw.lower()
    if not low.startswith(('/rag','/learn2','/prime','/fleet','/hands','/devicejobs')):return False
    if chat_id!=OWNER.get('id'):send_text(chat_id,'Owner only.');return True
    if low.startswith('/fleet'):
        send_text(chat_id,_device_fleet_text());return True
    if low.startswith('/devicejobs'):
        q=raw[len('/devicejobs'):].strip();send_text(chat_id,_device_job_text(q));return True
    if low.startswith('/hands'):
        parts=raw.split()
        if len(parts)<3:send_text(chat_id,'REMOTE HANDS 2.0 - diagnostic allowlist only\n/hands <device> sysinfo|processes|disk|network\n/hands <device> service <name>\n/devicejobs');return True
        did,d=_device_pick(parts[1])
        if not d:send_text(chat_id,'Device not found.');return True
        kind=parts[2].lower();args={}
        if kind=='service':
            if len(parts)<4:send_text(chat_id,'Use: /hands <device> service <name>');return True
            kind='service_status';args={'service':parts[3]}
        jid,err=_device_queue_job(did,kind,args);send_text(chat_id,('Queued '+jid+' for '+d.get('name')+'. Results: /devicejobs '+jid) if jid else ('Not queued: '+str(err)));return True
    if low in ('/prime','/prime status'):
        st=prime_rag_status();obs=prime_observability_stats(24);ev=prime_eval_deep(os.path.abspath(__file__));tasks=prime_task_list(8);send_text(chat_id,f"NEMO PRIME v13.32\n\nTask OS: {len(tasks)} recent\nPolicy Engine: ACTIVE\nObservability: {obs['requests']} requests / {obs['success_rate']}% success (24h)\nEval Lab 2.0: {'PASS' if ev['pass'] else 'CHECK'} score {ev['score']}\nKnowledge Lake 2.0: {st['chunks']} chunks / {st['sources']} sources\nHybrid RAG: ACTIVE ({st['engine']})\nLearning Core 2.0: {st['episodes']} workflow episodes\nTrade reconciliation: ACTIVE\nDevice Agents 2.0: ACTIVE\nRemote Hands: DIAGNOSTIC ALLOWLIST\n\n/fleet /hands /devicejobs /rag /learn2 /obs /trace /eval /taskos /policy /agents");return True
    if low.startswith('/rag'):
        arg=raw[len('/rag'):].strip()
        if not arg or arg.lower()=='status':
            st=prime_rag_status();send_text(chat_id,f"KNOWLEDGE LAKE 2.0\nChunks: {st['chunks']}\nDistinct sources: {st['sources']}\nVector dimensions: {st['dim']}\nEngine: {st['engine']}\nCloud dependency: NONE for retrieval\n\n/rag rebuild\n/rag search <question>\n/rag context <question>");return True
        if arg.lower() in ('rebuild','rebuild clear','reset'):
            clear=arg.lower()!='rebuild';send_text(chat_id,'Rebuilding Knowledge Lake 2.0...');n=prime_rag_rebuild(clear=clear);st=prime_rag_status();send_text(chat_id,f"RAG rebuild complete. New chunks: {n}; total: {st['chunks']}; sources: {st['sources']}");return True
        if arg.lower().startswith('search '):arg=arg[7:].strip()
        if arg.lower().startswith('context '):
            q=arg[8:].strip();ctx,rows=prime_rag_context(q,6,7000);send_text(chat_id,('RAG CONTEXT\n'+ctx)[:3900] if ctx else 'No local evidence matched.');return True
        rows=prime_rag_search(arg,8);lines=['HYBRID RAG RESULTS']
        for i,r in enumerate(rows,1):lines.append(f"{i}. {r['title'][:100]} | score {r['score']:.3f} sem {r['semantic']:.3f} | {r['source']}\n{r['body'][:220]}")
        send_text(chat_id,'\n\n'.join(lines)[:3900] if rows else 'No local evidence matched.');return True
    if low.startswith('/learn2'):
        arg=raw[len('/learn2'):].strip();cls=arg or 'general'
        if cls.lower()=='status':
            st=prime_rag_status();c=_prime_conn();ok=c.execute('SELECT COUNT(*) FROM prime_episodes WHERE success=1').fetchone()[0];fail=c.execute('SELECT COUNT(*) FROM prime_episodes WHERE success=0').fetchone()[0];c.close();send_text(chat_id,f"LEARNING CORE 2.0\nEpisodes: {st['episodes']}\nSuccessful: {ok}\nFailed: {fail}\nStrategy learning: ACTIVE\nHybrid knowledge grounding: ACTIVE\nUse /learn2 <task-class>");return True
        rows=prime_episode_rank(cls,10);lines=['LEARNED WORKFLOWS | '+cls]
        for r in rows:lines.append(f"{r['successes']}/{r['attempts']} ({100*r['successes']/max(1,r['attempts']):.0f}%) | {r['avg_ms']:.0f}ms | {r['strategy'][:180]}")
        send_text(chat_id,'\n'.join(lines) if len(lines)>1 else 'No workflow episodes yet for '+cls);return True
    return False

_HANDLE_V1329_RAG=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=msg.get('text') or msg.get('caption') or ''
        if _v1330_dispatch(cid,txt,msg):return
    except Exception as _e:
        try:print('v13.30 dispatch:',str(_e)[:180])
        except Exception:pass
    return _HANDLE_V1329_RAG(msg)


# ==================== v13.32.1 OMNISOURCE HOTFIX + RESILIENCE ====================
# Fixes undefined send_long crash; adds compatibility sender and bounded GDELT retry.
# ==================== v13.32 OMNISOURCE FABRIC + IMPOSSIBLE TASK ENGINE ====================
# Free/open-source research mesh. Every adapter is fail-soft; one dead provider cannot kill a task.
import concurrent.futures as _omni_cf
import urllib.parse as _omni_up
import xml.etree.ElementTree as _omni_et
_OMNI_TIMEOUT=8
_OMNI_UA={'User-Agent':'NemoPrime/13.32 research-agent (owner-operated)'}

def _omni_get(url,params=None,timeout=_OMNI_TIMEOUT):
    r=requests.get(url,params=params,headers=_OMNI_UA,timeout=timeout); r.raise_for_status(); return r

def _omni_item(source,title,url='',snippet='',date='',kind='web',score=.5,meta=None):
    return {'source':source,'title':str(title or '')[:400],'url':str(url or '')[:1200],'snippet':re.sub(r'<[^>]+>',' ',str(snippet or ''))[:1800],'date':str(date or '')[:80],'kind':kind,'score':float(score),'meta':meta or {}}

def _src_wikipedia(q,n=5):
    j=_omni_get('https://en.wikipedia.org/w/api.php',{'action':'query','list':'search','srsearch':q,'format':'json','utf8':1,'srlimit':n}).json();out=[]
    for x in j.get('query',{}).get('search',[]):out.append(_omni_item('Wikipedia',x.get('title'),'https://en.wikipedia.org/wiki/'+_omni_up.quote(str(x.get('title','')).replace(' ','_')),x.get('snippet'),kind='reference',score=.72))
    return out

def _src_crossref(q,n=5):
    j=_omni_get('https://api.crossref.org/works',{'query.bibliographic':q,'rows':n,'select':'DOI,title,author,published,URL,type'}).json();out=[]
    for x in j.get('message',{}).get('items',[]):
        title=(x.get('title') or [''])[0]; doi=x.get('DOI',''); out.append(_omni_item('Crossref',title,x.get('URL') or ('https://doi.org/'+doi if doi else ''),'DOI '+doi,kind='scholarly',score=.88,meta={'doi':doi}))
    return out

def _src_openalex(q,n=5):
    j=_omni_get('https://api.openalex.org/works',{'search':q,'per-page':n,'select':'id,display_name,publication_date,doi,primary_location,cited_by_count'}).json();out=[]
    for x in j.get('results',[]):
        loc=x.get('primary_location') or {}; url=(loc.get('landing_page_url') or x.get('doi') or x.get('id') or '')
        out.append(_omni_item('OpenAlex',x.get('display_name'),url,'Citations: '+str(x.get('cited_by_count',0)),x.get('publication_date'),kind='scholarly',score=.9))
    return out

def _src_arxiv(q,n=5):
    txt=_omni_get('https://export.arxiv.org/api/query',{'search_query':'all:'+q,'start':0,'max_results':n,'sortBy':'relevance'}).text; root=_omni_et.fromstring(txt); ns={'a':'http://www.w3.org/2005/Atom'};out=[]
    for e in root.findall('a:entry',ns):out.append(_omni_item('arXiv',e.findtext('a:title','',ns).strip(),e.findtext('a:id','',ns),e.findtext('a:summary','',ns).strip(),e.findtext('a:published','',ns),kind='scholarly',score=.84))
    return out

def _src_gdelt(q,n=6):
    # GDELT can occasionally stall. Keep it on a shorter budget and retry once
    # with the simplest supported query so one slow public endpoint never delays OmniSource.
    url='https://api.gdeltproject.org/api/v2/doc/doc'
    params={'query':q,'mode':'ArtList','maxrecords':n,'format':'json','sort':'HybridRel'}
    try:
        r=requests.get(url,params=params,headers=_OMNI_UA,timeout=(3.5,5.0));r.raise_for_status();j=r.json()
    except Exception:
        params.pop('sort',None)
        r=requests.get(url,params=params,headers=_OMNI_UA,timeout=(3.5,5.0));r.raise_for_status();j=r.json()
    out=[]
    for x in j.get('articles',[]):out.append(_omni_item('GDELT',x.get('title'),x.get('url'),x.get('domain',''),x.get('seendate',''),kind='news',score=.78,meta={'domain':x.get('domain',''),'language':x.get('language','')}))
    return out

def _src_hn(q,n=5):
    j=_omni_get('https://hn.algolia.com/api/v1/search',{'query':q,'tags':'story','hitsPerPage':n}).json();out=[]
    for x in j.get('hits',[]):out.append(_omni_item('Hacker News',x.get('title'),x.get('url') or ('https://news.ycombinator.com/item?id='+str(x.get('objectID'))),x.get('story_text') or '',x.get('created_at',''),kind='tech',score=.64))
    return out

def _src_stackexchange(q,n=5):
    j=_omni_get('https://api.stackexchange.com/2.3/search/advanced',{'order':'desc','sort':'relevance','q':q,'site':'stackoverflow','pagesize':n,'filter':'default'}).json();out=[]
    for x in j.get('items',[]):out.append(_omni_item('Stack Overflow',x.get('title'),x.get('link'),'score '+str(x.get('score',0))+'; answers '+str(x.get('answer_count',0)),kind='technical',score=.76))
    return out

def _src_worldbank(q,n=5):
    # Search World Bank documents API; useful for economics/development/business-country research.
    j=_omni_get('https://search.worldbank.org/api/v2/wds',{'format':'json','qterm':q,'rows':n}).json();out=[]
    for _,x in (j.get('documents') or {}).items():
        out.append(_omni_item('World Bank',x.get('display_title') or x.get('title'),x.get('pdfurl') or x.get('url') or '',x.get('abstracts') or x.get('docna') or '',x.get('docdt') or '',kind='institutional',score=.96))
    return out

def _src_github(q,n=5):
    j=_omni_get('https://api.github.com/search/repositories',{'q':q,'sort':'stars','order':'desc','per_page':n}).json();out=[]
    for x in j.get('items',[]):out.append(_omni_item('GitHub',x.get('full_name'),x.get('html_url'),x.get('description') or '',x.get('updated_at',''),kind='code',score=.73,meta={'stars':x.get('stargazers_count',0),'language':x.get('language')}))
    return out

_OMNI_SOURCES={'wikipedia':_src_wikipedia,'crossref':_src_crossref,'openalex':_src_openalex,'arxiv':_src_arxiv,'gdelt':_src_gdelt,'hackernews':_src_hn,'stackoverflow':_src_stackexchange,'worldbank':_src_worldbank,'github':_src_github}

def _omni_route(q):
    t=str(q or '').lower(); names=['wikipedia','gdelt']
    if any(x in t for x in ('research','paper','study','science','medical','algorithm','machine learning','ai ','physics','chemistry')): names+=['openalex','crossref','arxiv']
    if any(x in t for x in ('code','python','javascript','github','library','software','error','exception','api','docker','linux')): names+=['github','stackoverflow','hackernews']
    if any(x in t for x in ('economy','gdp','development','poverty','india','country','business','finance','infrastructure')): names+=['worldbank']
    # Deep mode intentionally broadens across all free/open providers.
    return list(dict.fromkeys(names))

def omni_search(q,deep=True,per_source=5):
    names=list(_OMNI_SOURCES) if deep else _omni_route(q); results=[]; health={}
    def one(name):
        t=time.time()
        try:return name,_OMNI_SOURCES[name](q,per_source),None,int((time.time()-t)*1000)
        except Exception as e:return name,[],type(e).__name__+': '+str(e)[:180],int((time.time()-t)*1000)
    with _omni_cf.ThreadPoolExecutor(max_workers=min(8,len(names))) as ex:
        futs=[ex.submit(one,n) for n in names]
        for f in _omni_cf.as_completed(futs):
            name,rows,err,ms=f.result();health[name]={'ok':not bool(err),'count':len(rows),'ms':ms,'error':err or ''};results.extend(rows)
    seen=set();out=[]
    for r in sorted(results,key=lambda x:x.get('score',0),reverse=True):
        k=(r.get('url') or r.get('title','')).lower().strip()
        if not k or k in seen:continue
        seen.add(k);out.append(r)
    # Feed reusable evidence into the local Knowledge Lake without making it authoritative forever.
    try:
        for r in out[:30]:
            prime_rag_add('omnisource',r['title'],(r.get('snippet') or '')+'\nURL: '+r.get('url',''),tags=r.get('kind',''),source_ref=r.get('url') or r['source']+':'+r['title'])
    except Exception:pass
    return out,health

def omni_context(q,deep=True,max_items=18,max_chars=14000):
    rows,health=omni_search(q,deep,5);parts=[]
    for i,r in enumerate(rows[:max_items],1):parts.append(f"[{i}] {r['source']} | {r['title']}\n{r.get('snippet','')}\n{r.get('url','')}")
    return '\n\n'.join(parts)[:max_chars],rows,health

def _omni_health_text(health):
    lines=['OMNISOURCE FABRIC 1.0']
    for n in sorted(health):
        h=health[n];lines.append(('ONLINE' if h['ok'] else 'DEGRADED')+f" | {n} | {h['count']} results | {h['ms']}ms"+((' | '+h['error'][:80]) if h['error'] else ''))
    return '\n'.join(lines)[:3900]

def send_long(chat_id,text,kb=None):
    """Compatibility sender for long model output. send_text already chunks at Telegram-safe size."""
    return send_text(chat_id,text,kb)

def _omni_answer(chat_id,q):
    tid=prime_task_create(q,'research',chat_id);prime_task_update(tid,status='RUNNING',progress=10,step='parallel free-source research')
    send_text(chat_id,'OMNISOURCE: searching independent free/open sources in parallel...')
    try:
        ctx,rows,health=omni_context(q,True);prime_task_update(tid,progress=55,step=f'{len(rows)} evidence items collected')
        if not rows:
            prime_task_update(tid,status='FAILED',error='no free-source evidence');send_text(chat_id,'No free/open source returned usable evidence. I did not invent an answer.');return
        prompt="""You are NEMO PRIME OMNISOURCE analyst. Answer the owner's request using the evidence packet below. Synthesize; do not copy snippets. Distinguish verified evidence from inference. Mention disagreements/uncertainty. Never claim a source says something not present in the packet. For current facts, prefer institutional/news evidence; for science prefer scholarly evidence; for code prefer primary repositories/technical evidence. End with a compact SOURCES USED section containing source names and titles, not raw tracking URLs.\n\nREQUEST:\n"""+q+"\n\nEVIDENCE PACKET:\n"+ctx
        ans=ask_ai(chat_id,prompt,remember=False,timeout=240,long_output=True)
        if ans: send_text(chat_id,ans)
        send_text(chat_id,_omni_health_text(health));prime_task_update(tid,status='DONE',progress=100,step='verified synthesis complete',result=str(ans or '')[:1500])
    except Exception as e:
        prime_task_update(tid,status='FAILED',error=str(e)[:1200]);send_text(chat_id,'OMNISOURCE task failed safely: '+type(e).__name__+': '+str(e)[:500])

def _v1332_dispatch(chat_id,text,msg=None):
    raw=(text or '').strip();low=raw.lower()
    if not low.startswith(('/omni','/sources','/sourcehealth','/impossible')):return False
    if chat_id!=OWNER.get('id'):send_text(chat_id,'Owner only.');return True
    if low in ('/sources','/sourcehealth'):
        send_text(chat_id,'Testing free/open source mesh...')
        _,h=omni_search('artificial intelligence',True,1);send_text(chat_id,_omni_health_text(h));return True
    if low.startswith('/impossible'):
        q=raw[len('/impossible'):].strip()
        if not q:send_text(chat_id,'IMPOSSIBLE TASK ENGINE\nUse: /impossible <goal>\nNemo decomposes the goal, researches free/open sources, uses specialist routing, and returns the strongest feasible plan. It will identify genuine external/physical/legal limits rather than pretending they do not exist.');return True
        plan=prime_governor_plan(q);threading.Thread(target=_omni_answer,args=(chat_id,'GOAL: '+q+'\nSpecialist route: '+str(plan)),daemon=True).start();return True
    q=raw[len('/omni'):].strip()
    if not q:send_text(chat_id,'OMNISOURCE FABRIC 1.0\n/omni <question> — parallel evidence synthesis\n/sources — live provider health\n/impossible <goal> — research + specialist feasibility engine\n\nFree/open connectors: Wikipedia, GDELT, OpenAlex, Crossref, arXiv, GitHub, Stack Overflow, Hacker News, World Bank. Fail-soft parallel routing + Knowledge Lake ingestion.');return True
    threading.Thread(target=_omni_answer,args=(chat_id,q),daemon=True).start();return True

_HANDLE_V1331_OMNI=handle
