    c.execute("CREATE TABLE IF NOT EXISTS prime_guardian_events(id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, origin TEXT, verdict TEXT, score INTEGER, reasons TEXT, content_hash TEXT, meta TEXT)")
    c.execute("CREATE TABLE IF NOT EXISTS prime_regression_runs(id TEXT PRIMARY KEY, ts REAL, version TEXT, passed INTEGER, failed INTEGER, verdict TEXT, detail TEXT)")
