# MCP Universal Tool Bus: registry + capability discovery. Network invocation remains policy/Guardian gated.
def prime_mcp_register(name,endpoint='',transport='stdio',capabilities=None,trust='UNTRUSTED'):
    _v134_init(); name=re.sub(r'[^a-z0-9_.-]+','_',str(name).lower())[:80]; transport=str(transport).lower()
    if transport not in ('stdio','http','sse','streamable-http'): raise ValueError('unsupported MCP transport')
    g=guardian_scan_text(str(endpoint),origin='mcp_endpoint');
    if g['verdict']=='BLOCK': raise ValueError('Guardian blocked endpoint')
    c=_prime_conn();c.execute('INSERT OR REPLACE INTO prime_mcp_servers(name,endpoint,transport,enabled,trust,capabilities,last_ok,last_error,meta) VALUES(?,?,?,?,?,?,?,?,?)',(name,str(endpoint)[:1000],transport,1,str(trust)[:32],json.dumps(capabilities or []),0,'','{}'));c.commit();c.close();return name

def prime_mcp_list():
    _v134_init();c=_prime_conn();r=c.execute('SELECT name,endpoint,transport,enabled,trust,capabilities,last_ok,last_error FROM prime_mcp_servers ORDER BY name').fetchall();c.close();return r

