    c=_prime_conn();c.execute('INSERT OR REPLACE INTO prime_a2a_agents(name,description,endpoint,enabled,trust,skills,last_ok,last_error,meta) VALUES(?,?,?,?,?,?,?,?,?)',(name,str(description)[:1500],str(endpoint)[:1000],1,str(trust)[:32],json.dumps(skills or []),0,'','{}'));c.commit();c.close();return name

