def prime_governor_v2(goal):
    txt=str(goal or '').lower(); plan=[]
    mapping=[('researcher',['research','find','compare','study','latest']),('coder',['code','python','bug','build','app']),('browser',['browser','website','login','page']),('cyber',['security','cyber','vulnerability','audit']),('market',['market','stock','nifty','trade']),('publisher',['report','pdf','document']),('verifier',['verify','check','audit','compare'])]
    for agent,keys in mapping:
        if any(k in txt for k in keys):plan.append(agent)
    if not plan:plan=['researcher']
    if len(plan)>1 and 'verifier' not in plan:plan.append('verifier')
    return {'goal':goal,'agents':plan[:5],'policy':'All consequential actions remain Policy Engine gated; external content passes Guardian.'}

def _v134_dispatch(chat_id,text,msg=None):
    raw=(text or '').strip();low=raw.lower()
    if not low.startswith(('/health','/selftest2','/mcpbus','/mcp ','/a2a','/delegate','/batch2')):return False
    if chat_id!=OWNER.get('id'):send_text(chat_id,'Owner only.');return True
    _v134_init();_v134_seed_agents()
    if low in ('/batch2','/mcpbus'):
        send_text(chat_id,'NEMO v13.34 BATCH 2\nRELIABILITY INTELLIGENCE: ACTIVE\nMCP UNIVERSAL TOOL BUS: ACTIVE\nA2A FOUNDATION: ACTIVE\nAGENT GOVERNOR 2.0: ACTIVE\n\n/health run | /health history\n/mcpbus | /mcp add <name> <transport> <endpoint>\n/a2a\n/delegate <goal>');return True
    if low in ('/health','/health run','/selftest2'):
        send_text(chat_id,'Running diagnostic self-test...');r=prime_health_run(False);send_text(chat_id,r['report'][:3900]);return True
    if low=='/health history':
        rows=prime_health_history(30);send_text(chat_id,'HEALTH HISTORY\n'+'\n'.join(f"{time.strftime('%m-%d %H:%M',time.localtime(x[0]))} | {'PASS' if x[3] else 'FAIL'} | {x[1]} | {x[4]}ms | {x[5] or '-'}" for x in rows)[:3900]);return True
    if low.startswith('/mcp add '):
        p=raw.split(None,4)
        if len(p)<5:send_text(chat_id,'Use: /mcp add <name> <stdio|http|sse|streamable-http> <endpoint>');return True
        try:n=prime_mcp_register(p[2],p[4],p[3]);send_text(chat_id,'MCP server registered: '+n+'\nRegistration does not bypass Guardian/Policy authorization.')
        except Exception as e:send_text(chat_id,'MCP registration failed: '+str(e)[:400])
        return True
    if low in ('/mcp','/mcp list','/mcpbus list'):
        rows=prime_mcp_list();send_text(chat_id,'MCP TOOL BUS\n'+(('No external MCP servers registered.' if not rows else '\n'.join(f"{r[0]} | {r[2]} | {r[4]} | {'ON' if r[3] else 'OFF'}" for r in rows)))[:3800]);return True
    if low in ('/a2a','/a2a list'):
        rows=prime_a2a_list();send_text(chat_id,'A2A AGENT NETWORK\n'+'\n'.join(f"{r[0]} | {r[4]} | {r[1]}" for r in rows)[:3800]);return True
    if low.startswith('/delegate '):
        p=prime_governor_v2(raw.split(None,1)[1]);send_text(chat_id,'AGENT GOVERNOR 2.0\nPlan: '+' -> '.join(p['agents'])+'\n'+p['policy']);return True
    return False

