def prime_regression_suite():
    r=_PRIME_REGRESSION_V1333(); extra=[]
    def add(n,fn):
        try: ok=bool(fn());d='ok' if ok else 'false'
        except Exception as e:ok=False;d=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':n,'ok':ok,'detail':d})
    add('health-db',lambda: (_v134_init() is None))
    add('mcp-registry',lambda: isinstance(prime_mcp_list(),list))
    add('a2a-agent-cards',lambda: len(prime_a2a_list())>=5)
    add('governor-plan',lambda: bool(prime_governor_v2('research and verify this')['agents']))
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x['ok']);r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION
    return r

