def _v135_dispatch(chat_id,text,msg=None):
    raw=(text or '').strip();low=raw.lower()
    if not low.startswith(('/doctor','/providerdoctor','/emaildoctor','/computer','/computers','/batch3')):return False
    if chat_id!=OWNER.get('id'):send_text(chat_id,'Owner only.');return True
    _v135_init()
    if low in ('/batch3','/computer'):
        send_text(chat_id,'NEMO v13.35 BATCH 3\nPROVIDER DOCTOR: ACTIVE\nEMAIL NETWORK DOCTOR: ACTIVE\nCOMPUTER-USE 5.0: ACTIVE\nDOM + semantic accessibility + screenshot state: ACTIVE\nGUARDIAN page firewall: ACTIVE\nAction verification/checkpoints: ACTIVE\n\n/doctor\n/emaildoctor\n/computer <goal>\n/computers');return True
    if low in ('/doctor','/providerdoctor'):
        send_text(chat_id,'Running provider diagnostics...');g=groq_probe_diagnostic() if GROQ_KEY else {'ok':False,'reason':'no key'};m=gemini_probe_diagnostic() if GEMINI_KEY else {'ok':False,'reason':'no key'}
        lines=['PROVIDER DOCTOR',f"Groq: {'PASS' if g.get('ok') else 'FAIL'} | {g.get('model') or g.get('reason')} | {g.get('latency_ms',0)}ms",f"Gemini: {'PASS' if m.get('ok') else 'FAIL'} | {m.get('model') or m.get('reason')} | {m.get('latency_ms',0)}ms"]
        if g.get('attempts'):lines.append('Groq attempts: '+json.dumps(g['attempts'][:4],ensure_ascii=False))
        if m.get('attempts'):lines.append('Gemini attempts: '+json.dumps(m['attempts'][:4],ensure_ascii=False))
        send_text(chat_id,'\n'.join(lines)[:3900]);return True
    if low=='/emaildoctor':
        d=email_network_doctor();lines=['EMAIL NETWORK DOCTOR',f"Diagnosis: {d.get('diagnosis')}",f"DNS: {d['dns']}",f"TCP 465: {d['tcp465']}",f"TCP 587: {d['tcp587']}",f"HTTPS 443: {d['google443']}",f"Gmail API: {d['gmail_api']}",f"SMTP auth: {d['smtp_auth']}"];send_text(chat_id,'\n'.join(lines)[:3900]);return True
    if low=='/computers':
        rows=prime_computer_sessions();send_text(chat_id,'COMPUTER-USE SESSIONS\n'+(('No sessions yet.' if not rows else '\n'.join(f"{r['id']} | {r['status']} | step {r['step']} | {r['url'][:80]}\n{r['goal'][:140]}" for r in rows)))[:3800]);return True
    if low.startswith('/computer '):
        goal=raw.split(None,1)[1].strip()
        if not goal:send_text(chat_id,'Use: /computer <goal>');return True
        send_text(chat_id,'Computer-Use 5.0 started. External page instructions are untrusted; sensitive/consequential actions stop at an approval checkpoint.')
        def run():
            r=computer_use_v5(chat_id,goal);send_text(chat_id,(('COMPUTER-USE DONE\n' if r.get('ok') else 'COMPUTER-USE FAILED\n')+'Session: '+str(r.get('session'))+'\n'+str(r.get('result') or r.get('error'))+'\n'+str(r.get('url') or ''))[:3900])
            try:
                ss=(prime_computer_sessions(1)[0].get('screenshot') if prime_computer_sessions(1) else '')
            except Exception:ss=''
        threading.Thread(target=run,daemon=True).start();return True
    return False


