                if digest!=last or time.time()-updated>24*3600:send_text(OWNER['id'],sig);c.execute('INSERT OR REPLACE INTO prime_proactive_state(key,value,updated) VALUES("last_alert",?,?)',(digest,time.time()));c.commit()
