def _v136_dispatch(chat_id,text,msg=None):
    raw=(text or '').strip();low=raw.lower()
    if not low.startswith(('/batch4','/context','/link ','/event ','/review','/improvements','/drills','/drill ','/progress','/followup','/chief','/proactive')):return False
    if chat_id!=OWNER.get('id'):send_text(chat_id,'Owner only.');return True
    _v136_start()
    if low=='/batch4':send_text(chat_id,'NEMO v13.36 BATCH 4\nPERSONAL CONTEXT GRAPH: ACTIVE\nPROACTIVE INTELLIGENCE: ACTIVE\nCHIEF-OF-STAFF: ACTIVE\nPERFORMANCE LEARNING 3.0: ACTIVE\nMICRO-DRILLS: ACTIVE\nPROGRESS TAXONOMY + COURTEOUS FOLLOW-UPS: ACTIVE\n\n/context | /review | /improvements | /drills | /progress | /chief');return True
    if low.startswith('/context add '):
        rest=raw[len('/context add '):].strip();p=rest.split(None,1)
        if len(p)<2:send_text(chat_id,'Use: /context add <kind> <name> [| summary]');return True
        kind=p[0];parts=[x.strip() for x in p[1].split('|',1)];name=parts[0];summary=parts[1] if len(parts)>1 else ''
        try:eid=prime_context_add(kind,name,summary);send_text(chat_id,'Context entity saved: '+eid+'\n'+kind+' | '+name)
        except Exception as e:send_text(chat_id,'Context save failed: '+str(e)[:700])
        return True
    if low.startswith('/context find '):
        q=raw[len('/context find '):].strip();rows=prime_context_search(q,15);send_text(chat_id,'CONTEXT RESULTS\n'+(('No match.' if not rows else '\n'.join(f"{x['id']} | {x['kind']} | {x['name']}\n{x['summary'][:180]}" for x in rows)))[:3800]);return True
    if low in ('/context','/context status'):
        s=prime_context_snapshot();send_text(chat_id,'PERSONAL CONTEXT GRAPH\nEntities: '+str(len(s['entities']))+'\nRelations: '+str(len(s['relations']))+'\nRecent/significant events: '+str(len(s['events']))+'\n\n/context add <kind> <name> | <summary>\n/context find <query>\n/link <src> | <relation> | <dst>\n/event <type> | <text>');return True
    if low.startswith('/link '):
        p=[x.strip() for x in raw[len('/link '):].split('|')]
        if len(p)!=3:send_text(chat_id,'Use: /link <entity id/name> | <relation> | <entity id/name>');return True
        try:rid=prime_context_link(p[0],p[1],p[2]);send_text(chat_id,'Context relation saved: '+rid)
        except Exception as e:send_text(chat_id,'Link failed: '+str(e)[:700])
        return True
    if low.startswith('/event '):
        p=[x.strip() for x in raw[len('/event '):].split('|',1)];typ=p[0] or 'note';txt=p[1] if len(p)>1 else p[0];eid=prime_context_event(txt,typ,'',0.6,'owner');send_text(chat_id,'Context event saved: '+eid);return True
    if low.startswith('/review'):
        arg=raw[len('/review'):].strip();r=prime_performance_review(arg,True)
        if not r:send_text(chat_id,'No request available to review.');return True
        lines=['PERFORMANCE REVIEW '+r['id'],f"Overall: {r['overall']}/100 | {r['label']}",f"Correctness {r['correctness']:.0f} | Completeness {r['completeness']:.0f} | Evidence {r['evidence']:.0f}",f"Execution {r['execution']:.0f} | Efficiency {r['efficiency']:.0f} | Clarity {r['clarity']:.0f}",f"Policy {r['policy']:.0f} | Goal achievement {r['goal_achievement']:.0f}",'','Strengths: '+('; '.join(r['strengths']) or '-'),'Improve: '+('; '.join(r['improvements']) or 'No material weakness detected.'),'Corrective action: '+r['corrective_action'],'Next test: '+r['next_test']];send_text(chat_id,'\n'.join(lines)[:3900]);return True
    if low=='/improvements':
        z=prime_improvement_summary();send_text(chat_id,'IMPROVEMENT INTELLIGENCE\nReviews: '+str(z['count'])+'\nAverage score: '+str(z['avg'])+'\nLabels: '+json.dumps(z['labels'])+'\nMost common weak dimensions: '+json.dumps(z['weak'])+'\n\nUse /review to score the latest request and /drills to inspect focused practice.');return True
    if low=='/drills':
        rows=prime_micro_drills();send_text(chat_id,'MICRO-DRILLS\n'+(('No drills yet.' if not rows else '\n'.join(f"{x['id']} | {x['status']} | {x['area']} | {x['successes']}/{x['attempts']}\n{x['objective'][:180]}" for x in rows)))[:3800]);return True
    if low.startswith('/drill '):
        did=raw.split(None,1)[1].strip();send_text(chat_id,'Running focused drill '+did+'...');r=prime_micro_drill_run(did);send_text(chat_id,('PASS' if r.get('ok') else 'FAIL')+' | '+str(r.get('status') or '')+'\n'+str(r.get('detail') or r.get('error'))[:3200]);return True
    if low=='/progress':send_text(chat_id,'PROGRESS TAXONOMY\n'+'\n'.join(k+' — '+v for k,v in _PROGRESS_TAXONOMY.items()));return True
    if low.startswith('/followup'):
        arg=raw[len('/followup'):].strip();r=prime_followup_phrase(arg);send_text(chat_id,'FOLLOW-UP STYLE: '+r['tone'].upper()+'\n'+r['text']);return True
    if low=='/chief':send_text(chat_id,prime_chief_brief());return True
    if low=='/proactive':send_text(chat_id,'PROACTIVE INTELLIGENCE\nHourly significance check: ACTIVE\nOnly persistent health failures (2+ consecutive) trigger an alert; duplicate alerts are suppressed for up to 24 hours.\nNo autonomous trading, purchases, deletes, credential changes, or production patches.');return True
    return False

