def _v137_dispatch(chat_id,text,msg=None):
    raw=(text or '').strip(); low=raw.lower()
    if not low.startswith(('/batch5','/localnode','/localnodes','/localtest','/hybrid ','/hybridstatus','/jarvislive','/interrupt')):return False
    if chat_id!=OWNER.get('id'):send_text(chat_id,'Owner only.');return True
    _v137_init()
