    if low in ('/localnode','/localnodes'):
        ns=prime_local_nodes(); lines=['LOCAL AI NODES']+(['No nodes configured.'] if not ns else [f"{x['id']} | {'ON' if x['enabled'] else 'OFF'} | {x['name']} | {x['model'] or '-'} | {x['latency_ms']}ms\n{x['url']}" for x in ns]); lines+=['','Add: /localnode add <name> | <http(s)://host:11434> [| model]','Toggle: /localnode on|off <id>'];send_text(chat_id,'\n'.join(lines)[:3900]);return True
    if low.startswith('/localnode add '):
        p=[x.strip() for x in raw[len('/localnode add '):].split('|')]
        if len(p)<2:send_text(chat_id,'Use: /localnode add <name> | <url> [| model]');return True
        try:nid=prime_local_node_add(p[0],p[1],p[2] if len(p)>2 else '');send_text(chat_id,'Local AI node registered: '+nid+'\nNo network discovery was performed. Run /localtest '+nid)
        except Exception as e:send_text(chat_id,'Local node rejected: '+str(e)[:700])
        return True
    if low.startswith('/localnode on ') or low.startswith('/localnode off '):
        parts=raw.split(); en=parts[1].lower()=='on'; ok=prime_local_node_set(parts[2] if len(parts)>2 else '',en);send_text(chat_id,'Updated.' if ok else 'Node not found.');return True
    if low.startswith('/localtest'):
        nid=raw[len('/localtest'):].strip(); send_text(chat_id,'Testing explicitly configured local inference node...'); p=prime_local_node_probe(nid);send_text(chat_id,('PASS' if p.get('ok') else 'FAIL')+'\n'+json.dumps(p,ensure_ascii=False,indent=2)[:3600]);return True
    if low.startswith('/hybrid '):
        q=raw.split(None,1)[1]; r=prime_hybrid_route(chat_id,q);send_text(chat_id,f"HYBRID {r['route'].upper()} | {r['class']} | {r.get('model','')} | {r.get('latency_ms',0)}ms\n\n"+str(r.get('text') or r.get('error'))[:3500]);return True
    if low=='/hybridstatus':
        st=prime_hybrid_status();send_text(chat_id,'HYBRID BRAIN\nNodes: '+str(len(st['nodes']))+'\nRecent routes: '+(', '.join(x['route'] for x in st['runs']) or 'none'));return True
    if low=='/jarvislive on':_v137_voice_set(chat_id,True,'LISTENING',False);send_text(chat_id,'JARVIS LIVE FOUNDATION: ON\nState: LISTENING\nVoice turns can now maintain session/interruption state. Telegram is turn-based, so this is not a continuous microphone stream.');return True
    if low=='/jarvislive off':_v137_voice_set(chat_id,False,'IDLE',False);send_text(chat_id,'JARVIS LIVE FOUNDATION: OFF');return True
    if low in ('/jarvislive','/jarvislive status'):
        d=_v137_voice_get(chat_id);send_text(chat_id,f"JARVIS LIVE FOUNDATION\nEnabled: {bool(d['enabled'])}\nState: {d['state']}\nTurns: {d['turn']}\nInterrupted: {bool(d['interrupted'])}\n\n/jarvislive on | /interrupt | /jarvislive off");return True
    if low=='/interrupt':prime_voice_interrupt(chat_id);send_text(chat_id,'INTERRUPTED. Current Jarvis session state is stopped and ready for the next owner turn.');return True
    return False

