def _v140_init():
    _v139_init()
    c=_prime_conn()
    c.execute("CREATE TABLE IF NOT EXISTS prime_os_state(key TEXT PRIMARY KEY,value TEXT,updated REAL)")
    c.execute("CREATE TABLE IF NOT EXISTS prime_os_boot(id TEXT PRIMARY KEY,ts REAL,version TEXT,status TEXT,modules TEXT,regression TEXT,meta TEXT)")
    c.execute("CREATE TABLE IF NOT EXISTS prime_os_events(id TEXT PRIMARY KEY,ts REAL,kind TEXT,severity TEXT,detail TEXT)")
    c.commit();c.close()

def _v140_state_get(key, default=''):
    try:
        c=_prime_conn();r=c.execute('SELECT value FROM prime_os_state WHERE key=?',(key,)).fetchone();c.close();return r['value'] if r else default
    except Exception:return default

def _v140_state_set(key,value):
    c=_prime_conn();c.execute('INSERT OR REPLACE INTO prime_os_state(key,value,updated) VALUES(?,?,?)',(key,str(value),time.time()));c.commit();c.close()

def nemo_os_safe_mode(enabled=None):
    if enabled is not None:_v140_state_set('safe_mode','1' if enabled else '0')
    return _v140_state_get('safe_mode','0')=='1'

def nemo_os_modules():
    out=[]
    for name,(desc,symbols) in _V140_MODULES.items():
        missing=[x for x in symbols if not callable(globals().get(x))]
        out.append({'module':name,'description':desc,'status':'DEGRADED' if missing else 'READY','missing':missing})
    return out

def nemo_os_doctor(run_regression=False):
    mods=nemo_os_modules(); ready=sum(1 for x in mods if x['status']=='READY')
    result={'version':VERSION,'safe_mode':nemo_os_safe_mode(),'modules_ready':ready,'modules_total':len(mods),'modules':mods,'regression':None}
    if run_regression:
        try:result['regression']=prime_regression_suite()
        except Exception as e:result['regression']={'verdict':'ERROR','error':type(e).__name__+': '+str(e)[:240]}
    result['status']='READY' if ready==len(mods) and (not run_regression or result['regression'].get('verdict')=='PASS') else 'DEGRADED'
    return result

def nemo_os_boot_record():
    d=nemo_os_doctor(False);bid='BOOT'+_prime_uuid.uuid4().hex[:10].upper()
    try:
        c=_prime_conn();c.execute('INSERT INTO prime_os_boot(id,ts,version,status,modules,regression,meta) VALUES(?,?,?,?,?,?,?)',(bid,time.time(),VERSION,d['status'],json.dumps(d['modules']), '',json.dumps({'safe_mode':d['safe_mode']})));c.commit();c.close()
    except Exception:pass
    return d

def nemo_os_manifest():
    mods=nemo_os_modules()
    return {'name':'NEMO OS','version':VERSION,'architecture':'compatibility-kernel','modules':len(mods),'ready':sum(x['status']=='READY' for x in mods),'safe_mode':nemo_os_safe_mode(),'prime_db':_PRIME_DB,'production_authority':'policy-gated'}

