def _v140_dispatch(chat_id,text,msg=None):
    raw=(text or '').strip();low=raw.lower()
    if low in ('/batchfinal','/v14'):
        send_text(chat_id,'NEMO OS v14.0 FINAL FOUNDATION\n\nModular control plane • boot manifest • module doctor • safe-mode recovery • regression gate • compatibility kernel.\n\n'+_v140_commands_text());return True
    if low=='/modules':
        rows=nemo_os_modules();send_text(chat_id,'NEMO OS MODULES\n\n'+'\n'.join(('✅' if x['status']=='READY' else '⚠️')+' '+x['module'].upper()+' — '+x['status'] for x in rows));return True
    if low in ('/os','/os status'):
        send_text(chat_id,json.dumps(nemo_os_manifest(),ensure_ascii=False,indent=2));return True
    if low=='/os doctor':
        send_text(chat_id,json.dumps(nemo_os_doctor(False),ensure_ascii=False,indent=2)[:3900]);return True
    if low=='/os verify':
        d=nemo_os_doctor(True);send_text(chat_id,'NEMO OS VERIFY\nStatus: '+d['status']+'\nModules: '+str(d['modules_ready'])+'/'+str(d['modules_total'])+'\nRegression: '+str((d.get('regression') or {}).get('verdict','N/A'))+' '+str((d.get('regression') or {}).get('passed',''))+'/'+str(len((d.get('regression') or {}).get('tests',[]))));return True
    if low=='/safemode':send_text(chat_id,'NEMO OS Safe Mode: '+('ON' if nemo_os_safe_mode() else 'OFF'));return True
    if low=='/safemode on':nemo_os_safe_mode(True);send_text(chat_id,'NEMO OS Safe Mode ON. Recovery/diagnostic OS commands remain available.');return True
    if low=='/safemode off':nemo_os_safe_mode(False);send_text(chat_id,'NEMO OS Safe Mode OFF. Normal compatibility dispatch restored.');return True
    if nemo_os_safe_mode() and low.startswith('/'):
        send_text(chat_id,'NEMO OS is in Safe Mode. Use /os doctor, /os verify, /modules, or /safemode off.');return True
    return False

