class _VedaTextExtractor(_VedaHTMLParser):
    def __init__(self):
        super().__init__();self.parts=[];self.skip=0
    def handle_starttag(self,tag,attrs):
        if tag.lower() in ('script','style','noscript'): self.skip+=1
        elif tag.lower() in ('p','div','br','h1','h2','h3','h4','li','tr'): self.parts.append('\n')
    def handle_endtag(self,tag):
        if tag.lower() in ('script','style','noscript') and self.skip:self.skip-=1
        elif tag.lower() in ('p','div','h1','h2','h3','h4','li','tr'): self.parts.append('\n')
    def handle_data(self,data):
        if not self.skip:self.parts.append(data)

def _veda_clean_html(raw):
    p=_VedaTextExtractor();p.feed(raw);t=_veda_html.unescape(''.join(p.parts));
    t=t.replace('\r','\n');t=re.sub(r'[ \t]+',' ',t);t=re.sub(r'\n\s*\n\s*\n+','\n\n',t)
    return t.strip()

def _v142_init():
    _v140_init();os.makedirs(_VEDA_ROOT,exist_ok=True)
    c=_prime_conn()
    c.execute('''CREATE TABLE IF NOT EXISTS prime_veda_chunks(
      id TEXT PRIMARY KEY,veda TEXT,recension TEXT,book TEXT,section TEXT,ref TEXT,lang TEXT,text TEXT,
      source_id TEXT,source_url TEXT,translator TEXT,year TEXT,checksum TEXT,updated REAL)''')
    c.execute('''CREATE TABLE IF NOT EXISTS prime_veda_sync(
      source_id TEXT PRIMARY KEY,veda TEXT,status TEXT,chunks INTEGER,bytes INTEGER,last_error TEXT,updated REAL,meta TEXT)''')
    try:c.execute("CREATE VIRTUAL TABLE IF NOT EXISTS prime_veda_fts USING fts5(id UNINDEXED,veda,recension,ref,text)")
    except Exception:pass
    c.commit();c.close();_veda_seed_map()

def _veda_seed_map():
    c=_prime_conn()
    for key,d in _VEDA_CANON.items():
        txt=(d['title']+'\nCore: '+d['core']+'\nExtant traditions: '+d['extant']+'\nStructure: '+d['structure']+'\nThemes: '+', '.join(d['themes'])+'\nOfficial reference: '+d['official'])
        cid='CANON-'+key
        ck=_veda_hashlib.sha256(txt.encode()).hexdigest()
        c.execute('''INSERT OR REPLACE INTO prime_veda_chunks(id,veda,recension,book,section,ref,lang,text,source_id,source_url,translator,year,checksum,updated)
                     VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)''',(cid,key,'canonical-map','','overview',key,'en',txt,'vedic-heritage',d['official'],'','',ck,time.time()))
        try:c.execute('DELETE FROM prime_veda_fts WHERE id=?',(cid,));c.execute('INSERT INTO prime_veda_fts(id,veda,recension,ref,text) VALUES(?,?,?,?,?)',(cid,key,'canonical-map',key,txt))
        except Exception:pass
        try:
            if callable(globals().get('prime_rag_add')):prime_rag_add(txt,source='veda:'+key,meta={'veda':key,'type':'canonical-map','url':d['official']})
        except Exception:pass
    c.commit();c.close()

def _veda_fetch(url,timeout=35):
    h={'User-Agent':'NemoOS-VedicResearch/14.02 (+scholarly personal knowledge indexing)'}
    r=requests.get(url,headers=h,timeout=timeout);r.raise_for_status();return r.content

def _veda_chunks(text,size=2400,overlap=260):
    text=re.sub(r'\n{3,}','\n\n',str(text or '')).strip();out=[];i=0
    while i<len(text):
        j=min(len(text),i+size)
        if j<len(text):
            k=text.rfind('\n',i+int(size*.65),j)
            if k>i:j=k
        part=text[i:j].strip()
        if len(part)>=80:out.append(part)
        if j>=len(text):break
        i=max(i+1,j-overlap)
    return out

def _veda_source_done(source_id):
    try:
        c=_prime_conn();r=c.execute("SELECT status,chunks FROM prime_veda_sync WHERE source_id=?",(source_id,)).fetchone();c.close();return bool(r and r['status']=='READY' and int(r['chunks'] or 0)>0)
    except Exception:return False

def _veda_store_source(src,text,source_url=None,book=''):
    chunks=_veda_chunks(text);c=_prime_conn();n=0;total=0
    for idx,part in enumerate(chunks,1):
        ref=(book+':'+str(idx)) if book else str(idx);base=src['id']+'|'+book+'|'+str(idx)+'|'+part[:160]
        cid='VEDA-'+_veda_hashlib.sha1(base.encode('utf-8','ignore')).hexdigest()[:20]
        ck=_veda_hashlib.sha256(part.encode('utf-8','ignore')).hexdigest();url=source_url or src['url']
        c.execute('''INSERT OR REPLACE INTO prime_veda_chunks(id,veda,recension,book,section,ref,lang,text,source_id,source_url,translator,year,checksum,updated)
                     VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)''',(cid,src['veda'],src.get('recension',''),book,'text',ref,src.get('lang',''),part,src['id'],url,src.get('translator',''),src.get('year',''),ck,time.time()))
        try:c.execute('DELETE FROM prime_veda_fts WHERE id=?',(cid,));c.execute('INSERT INTO prime_veda_fts(id,veda,recension,ref,text) VALUES(?,?,?,?,?)',(cid,src['veda'],src.get('recension',''),ref,part))
        except Exception:pass
        n+=1;total+=len(part.encode('utf-8','ignore'))
        if n%100==0:c.commit()
    c.commit();c.close()
    try:
        # Add source-sized segments to the general Knowledge Lake without flooding it with every tiny chunk.
        if callable(globals().get('prime_rag_add')):
            for p in _veda_chunks(text,5200,300):prime_rag_add(p,source='veda:'+src['id'],meta={'veda':src['veda'],'recension':src.get('recension',''),'lang':src.get('lang',''),'url':source_url or src['url']})
    except Exception:pass
    return n,total

def _veda_mark(src,status,chunks=0,bytes_=0,error='',meta=None):
    c=_prime_conn();c.execute('INSERT OR REPLACE INTO prime_veda_sync(source_id,veda,status,chunks,bytes,last_error,updated,meta) VALUES(?,?,?,?,?,?,?,?)',(src['id'],src['veda'],status,int(chunks),int(bytes_),str(error)[:1200],time.time(),json.dumps(meta or {},ensure_ascii=False)));c.commit();c.close()

def _veda_sync_one(src,force=False):
    if _veda_source_done(src['id']) and not force:return {'source':src['id'],'status':'SKIPPED','reason':'already indexed'}
    _veda_mark(src,'SYNCING')
    try:
        total_chunks=0;total_bytes=0
        if src['kind']=='translation-gzip':
            raw=_veda_fetch(src['url']);text=_veda_gzip.decompress(raw).decode('utf-8','replace');n,b=_veda_store_source(src,text);total_chunks+=n;total_bytes+=b
        elif src['kind']=='translation-series':
            for i in range(1,int(src.get('count',0))+1):
                url=src['url'].format(n=i);raw=_veda_fetch(url).decode('utf-8','replace');text=_veda_clean_html(raw);n,b=_veda_store_source(src,text,url,book=str(i));total_chunks+=n;total_bytes+=b
        else:
            raw=_veda_fetch(src['url']).decode('utf-8','replace');text=_veda_clean_html(raw);n,b=_veda_store_source(src,text);total_chunks+=n;total_bytes+=b
        _veda_mark(src,'READY',total_chunks,total_bytes,'',{'note':src.get('note','')});return {'source':src['id'],'status':'READY','chunks':total_chunks,'bytes':total_bytes}
    except Exception as e:
        _veda_mark(src,'DEGRADED',0,0,type(e).__name__+': '+str(e));return {'source':src['id'],'status':'DEGRADED','error':type(e).__name__+': '+str(e)[:350]}

def veda_sync_full(chat_id=None,force=False):
    global _VEDA_SYNCING
    if not _VEDA_SYNC_LOCK.acquire(False):return {'ok':False,'error':'sync already running'}
    _VEDA_SYNCING=True;results=[]
    try:
        _v142_init()
        for src in _VEDA_SOURCES:
            r=_veda_sync_one(src,force=force);results.append(r)
            if chat_id and r.get('status') in ('READY','DEGRADED'):
                try:send_text(chat_id,'VEDA SYNC '+src['id']+': '+r.get('status')+((' — '+str(r.get('chunks'))+' chunks') if r.get('chunks') else ''))
                except Exception:pass
        ok=sum(1 for x in results if x.get('status') in ('READY','SKIPPED'));return {'ok':ok==len(results),'ready':ok,'total':len(results),'results':results}
    finally:
        _VEDA_SYNCING=False;_VEDA_SYNC_LOCK.release()

def veda_status():
    _v142_init();c=_prime_conn();rows=c.execute('SELECT source_id,veda,status,chunks,bytes,last_error,updated FROM prime_veda_sync ORDER BY veda,source_id').fetchall();cnt=c.execute('SELECT veda,lang,COUNT(*) n FROM prime_veda_chunks GROUP BY veda,lang ORDER BY veda,lang').fetchall();c.close()
    return {'syncing':_VEDA_SYNCING,'sources':[dict(x) for x in rows],'chunks':[dict(x) for x in cnt],'canonical_vedas':list(_VEDA_CANON)}

def veda_search(query,veda='',limit=8):
    _v142_init();q=str(query or '').strip();veda=str(veda or '').strip().lower();limit=max(1,min(int(limit or 8),20));c=_prime_conn();rows=[]
    if not q:return []
    try:
        mq=' '.join(re.findall(r'[\w\u0900-\u097F\u1E00-\u1EFF]+',q,flags=re.UNICODE)[:12])
        sql='SELECT p.* FROM prime_veda_fts f JOIN prime_veda_chunks p ON p.id=f.id WHERE prime_veda_fts MATCH ?'
        args=[mq]
        if veda:sql+=' AND p.veda=?';args.append(veda)
        sql+=' LIMIT ?';args.append(limit);rows=c.execute(sql,args).fetchall()
    except Exception:
        toks=[x.lower() for x in re.findall(r'\w+',q) if len(x)>2][:8]
        sql='SELECT * FROM prime_veda_chunks WHERE '+('veda=? AND ' if veda else '')+'('+ ' OR '.join(['lower(text) LIKE ?']*max(1,len(toks))) +') LIMIT ?'
        args=(([veda] if veda else [])+['%'+x+'%' for x in (toks or [q.lower()])]+[limit]);rows=c.execute(sql,args).fetchall()
    c.close();return [dict(x) for x in rows]

def veda_context(query,veda='',limit=6,max_chars=12500):
    rows=veda_search(query,veda,limit);parts=[];used=0
    for r in rows:
        tag='['+r['veda'].upper()+' | '+(r.get('recension') or 'text')+' | '+(r.get('ref') or '')+' | '+(r.get('translator') or r.get('lang') or '')+']'
        p=tag+'\n'+r['text'].strip()+'\nSOURCE '+r.get('source_url','')
        if used+len(p)>max_chars:break
        parts.append(p);used+=len(p)
    return '\n\n'.join(parts)

def veda_answer(question,veda='',chat_id=None):
    ctx=veda_context(question,veda,8,14000)
    if not ctx:return 'The Vedic corpus has no matching indexed passage yet. Run /veda sync and try again.'
    sys=('You are Nemo Vedic Knowledge Engine. Answer from the retrieved Vedic corpus first. Distinguish Sanskrit source text, historical translation, and modern explanation. '
         'Never invent a mantra reference. Treat translations as interpretations, not definitive meanings. If traditions or recensions differ, say so. '
         'For practical advice distinguish what the text states from later Hindu interpretation and from your inference. Cite the bracketed Veda/source labels in the answer. '
         'Do not claim that ancient ritual or medical passages are modern scientific or medical evidence.')
    prompt=sys+'\n\nQUESTION:\n'+str(question)+'\n\nRETRIEVED VEDIC EVIDENCE:\n'+ctx
    try:return ask_ai(chat_id or OWNER.get('id'),prompt,remember=False,deep=True,ground='') or 'Unable to synthesize the retrieved passages.'
    except Exception as e:return 'Vedic synthesis failed: '+str(e)[:500]

def _veda_map_text():
    lines=['FOUR VEDAS — NEMO CANONICAL MAP']
    for k,d in _VEDA_CANON.items():lines += ['',d['title'].upper(),d['core'],d['structure'],'Extant: '+d['extant'],'Themes: '+', '.join(d['themes'])]
    lines += ['','Textual layers: Vedic literature is traditionally organized through Samhita, Brahmana, Aranyaka and Upanishad layers; this v14.02 corpus concentrates on the four Samhitas while preserving branch/recension metadata.']
    return '\n'.join(lines)[:3900]

def _veda_sources_text():
    lines=['VEDA SOURCES','Primary structural reference: Vedic Heritage Portal / IGNCA-Ministry of Culture ecosystem.','Sanskrit e-texts: GRETIL scholarly reference files.','Historical English translations: Griffith (Rig/Sama/Atharva/White Yajur) and A.B. Keith (Taittiriya/Black Yajur).','Translations are interpretation layers; Sanskrit text and recension metadata remain distinct.','','Configured corpus sources:']
    for s in _VEDA_SOURCES:lines.append('- '+s['id']+' | '+s['veda']+' | '+s.get('recension','')+' | '+s.get('lang','')+' | '+s.get('translator',''))
    return '\n'.join(lines)[:3900]

def _v142_dispatch(chat_id,text,msg=None):
    raw=(text or '').strip();low=raw.lower()
    if not low.startswith(('/veda','/vedas','/shruti')):return False
    if low in ('/veda','/vedas','/shruti'):
        st=veda_status();send_text(chat_id,'NEMO VEDIC KNOWLEDGE ENGINE v14.02\nFour-Veda canonical map: READY\nFull corpus sync: '+('RUNNING' if st['syncing'] else 'IDLE')+'\n\n/veda map\n/veda sources\n/veda status\n/veda sync\n/veda search <query>\n/veda ask <question>\n/veda rig|sama|yajur|atharva <question>');return True
    if low=='/veda map':send_text(chat_id,_veda_map_text());return True
    if low=='/veda sources':send_text(chat_id,_veda_sources_text());return True
    if low=='/veda status':send_text(chat_id,json.dumps(veda_status(),ensure_ascii=False,indent=2)[:3900]);return True
    if low in ('/veda sync','/veda sync full'):
        if chat_id!=OWNER.get('id'):send_text(chat_id,'Owner only.');return True
        send_text(chat_id,'Four-Veda corpus synchronization started in background. It is resumable and source-aware; existing completed sources are skipped.')
        threading.Thread(target=veda_sync_full,args=(chat_id,False),daemon=True,name='nemo-veda-sync').start();return True
    if low=='/veda sync force':
        if chat_id!=OWNER.get('id'):send_text(chat_id,'Owner only.');return True
        send_text(chat_id,'Forced Four-Veda re-index started.');threading.Thread(target=veda_sync_full,args=(chat_id,True),daemon=True,name='nemo-veda-force').start();return True
    if low.startswith('/veda search '):
        q=raw[len('/veda search '):].strip();rows=veda_search(q,'',8)
        txt=['VEDA SEARCH — '+q]
        for r in rows:txt += ['','['+r['veda'].upper()+' '+(r.get('ref') or '')+'] '+(r.get('recension') or ''),r['text'][:650].replace('\n',' '),'Source: '+r.get('source_url','')]
        send_text(chat_id,'\n'.join(txt)[:3900] if rows else 'No indexed Vedic passage matched. Run /veda sync if the full corpus is not ready.');return True
    m=re.match(r'^/veda\s+(rig|rigveda|sama|samaveda|yajur|yajurveda|atharva|atharvaveda)\s+(.+)$',raw,re.I|re.S)
    if m:
        mp={'rig':'rigveda','rigveda':'rigveda','sama':'samaveda','samaveda':'samaveda','yajur':'yajurveda','yajurveda':'yajurveda','atharva':'atharvaveda','atharvaveda':'atharvaveda'}
        send_text(chat_id,veda_answer(m.group(2).strip(),mp[m.group(1).lower()],chat_id));return True
    if low.startswith('/veda ask '):send_text(chat_id,veda_answer(raw[len('/veda ask '):].strip(),'',chat_id));return True
    return False

