_PRIME_REGRESSION_V140=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V140();extra=[]
    def add(n,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':n,'ok':ok,'detail':detail})
    add('v142-db',lambda:_v142_init() is None)
    add('veda-four-canon',lambda:set(_VEDA_CANON)=={'rigveda','samaveda','yajurveda','atharvaveda'})
    add('veda-source-provenance',lambda:all(s.get('url','').startswith('https://') for s in _VEDA_SOURCES))
    add('veda-sanskrit-layer',lambda:len([s for s in _VEDA_SOURCES if s.get('kind')=='sanskrit'])>=4)
    add('veda-translation-layer',lambda:len([s for s in _VEDA_SOURCES if str(s.get('kind','')).startswith('translation')])>=4)
    add('veda-search-symbol',lambda:callable(globals().get('veda_search')) and callable(globals().get('veda_answer')))
    add('veda-recision-awareness',lambda:'Shukla' in _VEDA_CANON['yajurveda']['extant'] and 'Krishna' in _VEDA_CANON['yajurveda']['extant'])
