def evolution_enabled(v=None):
    if v is not None:_evo_state_set('enabled','1' if v else '0')
    return _evo_state_get('enabled','1')=='1'

def _evo_today_count():
    try:
        start=time.time()-(time.time()%86400)
        c=_prime_conn();n=c.execute('SELECT COUNT(*) FROM prime_evolution_cycles WHERE ts>=?',(start,)).fetchone()[0];c.close();return int(n)
    except Exception:return 0

def _evo_fingerprint(text):
    import hashlib
    z=re.sub(r'\s+',' ',str(text or '').lower()).strip()
    return hashlib.sha256(z.encode()).hexdigest()[:24]

def _evo_observe():
    parts=[]
    try:
        h=prime_health_run(False)
        parts.append('HEALTH '+json.dumps(h,default=str)[:3500])
    except Exception as e:parts.append('HEALTH unavailable '+type(e).__name__)
    try:
        c=_prime_conn()
        rows=c.execute("SELECT ts,kind,severity,detail FROM prime_os_events ORDER BY ts DESC LIMIT 8").fetchall()
        if rows:parts.append('OS_EVENTS '+json.dumps(rows,default=str)[:2500])
        rows=c.execute("SELECT id,status,title,rationale FROM prime_evolution_ideas ORDER BY ts DESC LIMIT 8").fetchall()
        if rows:parts.append('RECENT_IDEAS '+json.dumps(rows,default=str)[:2500])
        c.close()
    except Exception:pass
    try:
        ds=prime_micro_drills(8)
        if ds:parts.append('MICRO_DRILLS '+str(ds)[:2500])
    except Exception:pass
    try:
        ps=prime_factory_from_improvements(5)
        if ps:parts.append('PERFORMANCE_GAPS '+str(ps)[:2500])
    except Exception:pass
    return '\n'.join(parts)[:10000] or 'No strong failure signal. Seek one safe, measurable capability or knowledge improvement.'

def _evo_research(chat_id,observation):
    prompt=('You are Nemo Evolution Analyst. Study this local telemetry and identify ONE highest-value, safe, measurable improvement. '
            'Do not propose credential access, arbitrary shell, security bypass, autonomous money/trading authority, covert surveillance, or silent production code deployment. '
            'Return exactly four short fields: TITLE:, RATIONALE:, RESEARCH_QUERY:, SUCCESS_TEST:.\n\nTELEMETRY:\n'+observation[:9000])
    try:return str(ask_ai(chat_id or OWNER.get('id') or 0,prompt,remember=False,deep=False,ground=''))[:7000]
    except Exception:return ''

def _evo_parse_plan(txt):
    d={}
    for key in ('TITLE','RATIONALE','RESEARCH_QUERY','SUCCESS_TEST'):
        m=re.search(r'(?im)^'+key+r'\s*:\s*(.+?)(?=\n[A-Z_]+\s*:|\Z)',txt or '',re.S)
        d[key]=re.sub(r'\s+',' ',m.group(1)).strip()[:1200] if m else ''
    if not d['TITLE']:d['TITLE']='Improve weakest observed Nemo subsystem'
    return d

def _evo_safe_goal(plan):
    z=' '.join(plan.values()).lower()
    banned=('dump credential','steal credential','private key','seed phrase','brute force','bypass guardian','bypass policy','disable approval','arbitrary shell','covert surveillance','silent deploy','auto trade real money')
    return not any(x in z for x in banned)

def evolution_cycle(trigger='idle',chat_id=None):
    if not _EVOLVE_LOCK.acquire(False):return {'ok':False,'status':'BUSY'}
    try:
        _v1410_init()
        if not evolution_enabled():return {'ok':False,'status':'OFF'}
        if _evo_today_count()>=_EVOLVE_DAILY_BUDGET:return {'ok':False,'status':'DAILY_BUDGET'}
        eid='EVO-'+_prime_uuid.uuid4().hex[:10].upper();obs=_evo_observe();analysis=_evo_research(chat_id,obs);plan=_evo_parse_plan(analysis)
        if not _evo_safe_goal(plan):status='BLOCKED';cid='';research='Guardian rejected unsafe evolution goal.';score=0.0
        else:
            fp=_evo_fingerprint(plan['TITLE']+' '+plan['RATIONALE'])
            c=_prime_conn();old=c.execute('SELECT id FROM prime_evolution_ideas WHERE fingerprint=?',(fp,)).fetchone();c.close()
            if old:status='DUPLICATE';cid='';research='Suppressed duplicate of '+str(old[0]);score=0.2
            else:
                research=''
                q=plan.get('RESEARCH_QUERY','')
                if q:
                    try:
                        rr=web_search(q)
                        research=str(rr)[:8000]
                    except Exception as e:research='Research unavailable: '+type(e).__name__
                evidence=(obs+'\nRESEARCH '+research)[:12000]
                try:cid=prime_factory_propose(plan['TITLE']+' — '+plan['RATIONALE'],source='evolution') or ''
                except Exception:cid=''
                status='STAGED' if cid else 'LEARNED'
                score=0.7 if cid else 0.5
                c=_prime_conn();c.execute('INSERT OR IGNORE INTO prime_evolution_ideas(id,ts,fingerprint,title,rationale,evidence,candidate_id,status,updated) VALUES(?,?,?,?,?,?,?,?,?)',(eid,time.time(),fp,plan['TITLE'],plan['RATIONALE'],evidence,str(cid),status,time.time()));c.commit();c.close()
                # Safe knowledge retention only: index the research note; never executable code.
                if research and 'unavailable' not in research.lower():
                    try:prime_rag_add('evolution',plan['TITLE'],('Hypothesis: '+plan['RATIONALE']+'\nResearch: '+research)[:12000],'evolution,research',eid)
                    except Exception:pass
        c=_prime_conn();c.execute('INSERT INTO prime_evolution_cycles(id,ts,trigger,observation,hypothesis,research,candidate_id,score,status,detail) VALUES(?,?,?,?,?,?,?,?,?,?)',(eid,time.time(),trigger,obs,analysis,research,str(cid),score,status,json.dumps(plan)));c.commit();c.close()
        return {'ok':True,'id':eid,'status':status,'title':plan['TITLE'],'candidate_id':str(cid),'score':score}
    finally:_EVOLVE_LOCK.release()

def _evo_history(limit=10):
    c=_prime_conn();rows=c.execute('SELECT id,ts,trigger,status,score,detail,candidate_id FROM prime_evolution_cycles ORDER BY ts DESC LIMIT ?',(int(limit),)).fetchall();c.close();return rows

def _evo_ideas(limit=10):
    c=_prime_conn();rows=c.execute('SELECT id,ts,title,status,candidate_id FROM prime_evolution_ideas ORDER BY ts DESC LIMIT ?',(int(limit),)).fetchall();c.close();return rows

def _evo_loop():
    global _EVOLVE_LAST_ACTIVITY
    while True:
        try:
            time.sleep(60)
            if evolution_enabled() and time.time()-_EVOLVE_LAST_ACTIVITY>=_EVOLVE_IDLE_SECONDS and _evo_today_count()<_EVOLVE_DAILY_BUDGET:
                evolution_cycle('idle',OWNER.get('id'))
                _EVOLVE_LAST_ACTIVITY=time.time()-max(0,_EVOLVE_IDLE_SECONDS-_EVOLVE_INTERVAL_SECONDS)
                time.sleep(max(60,_EVOLVE_INTERVAL_SECONDS))
        except Exception as e:
            try:print('Evolution loop:',type(e).__name__,str(e)[:180])
            except Exception:pass
            time.sleep(120)

def _evo_start():
    global _EVOLVE_THREAD_STARTED
    if _EVOLVE_THREAD_STARTED:return
    _EVOLVE_THREAD_STARTED=True
    threading.Thread(target=_evo_loop,daemon=True,name='nemo-continuous-evolution').start()

def _evo_owner(chat_id):
    try:return bool(OWNER.get('id')) and chat_id==OWNER.get('id')
    except Exception:return False

def _evo_dispatch(chat_id,text,msg=None):
    raw=(text or '').strip();low=raw.lower()
    if not low.startswith('/evolve'):return False
    if not _evo_owner(chat_id):send_text(chat_id,'Evolution controls are owner-only.');return True
    if low=='/evolve':
        send_text(chat_id,'CONTINUOUS EVOLUTION '+('ON' if evolution_enabled() else 'OFF')+'\nIdle threshold: '+str(_EVOLVE_IDLE_SECONDS//60)+' min\nCycle interval: ~'+str(_EVOLVE_INTERVAL_SECONDS//60)+' min\nDaily budget: '+str(_evo_today_count())+'/'+str(_EVOLVE_DAILY_BUDGET)+'\n\n/evolve now | on | off | history | ideas\nProduction code promotion remains owner-approved.');return True
    if low=='/evolve on':evolution_enabled(True);send_text(chat_id,'Continuous Evolution: ON');return True
    if low=='/evolve off':evolution_enabled(False);send_text(chat_id,'Continuous Evolution: OFF');return True
    if low=='/evolve now':
        send_text(chat_id,'Evolution cycle started. I will observe, research, learn, and stage any consequential upgrade rather than silently deploying it.')
        def run():
            r=evolution_cycle('manual',chat_id);send_text(chat_id,'Evolution result: '+json.dumps(r,ensure_ascii=False,indent=2))
        threading.Thread(target=run,daemon=True,name='nemo-evolve-manual').start();return True
    if low=='/evolve history':send_text(chat_id,'EVOLUTION HISTORY\n'+('\n'.join(str(x) for x in _evo_history(12)) or 'No cycles yet.'));return True
    if low=='/evolve ideas':send_text(chat_id,'EVOLUTION IDEAS\n'+('\n'.join(str(x) for x in _evo_ideas(12)) or 'No ideas yet.'));return True
    if low.startswith('/evolve approve '):
        x=raw.split(None,2)[2].strip();c=_prime_conn();r=c.execute('SELECT candidate_id FROM prime_evolution_ideas WHERE id=?',(x,)).fetchone();c.close()
        if not r or not r[0]:send_text(chat_id,'No staged factory candidate for '+x);return True
        send_text(chat_id,'Candidate '+str(r[0])+' is staged. Use the existing /factory show and /factory test controls, then /factory approve only after review. Evolution will not bypass that gate.');return True
    if low.startswith('/evolve reject '):
        x=raw.split(None,2)[2].strip();c=_prime_conn();c.execute("UPDATE prime_evolution_ideas SET status='REJECTED',updated=? WHERE id=?",(time.time(),x));c.commit();c.close();send_text(chat_id,'Rejected '+x);return True
    send_text(chat_id,'Use /evolve | /evolve now | /evolve on | /evolve off | /evolve history | /evolve ideas');return True

