# ============================================================================
# v14.10.1 — EMAIL RELIABILITY HOTFIX
# Gmail API/HTTPS is authoritative whenever Google is connected. SMTP is a
# legacy fallback ONLY when Google is not configured. This prevents blocked
# VPS SMTP ports (465/587) from being misclassified as recurring email faults.
# ============================================================================
_EMAIL_HOTFIX_PREV_SEND = send_email

def _email_api_health():
    """Non-destructive Gmail API health check. Never sends mail and never probes SMTP."""
    t0=time.time()
    try:
        if not google_ready():
            return {'ok':False,'reason':'Google OAuth not configured','latency_ms':int((time.time()-t0)*1000)}
        tok=google_token()
        if not tok:
            return {'ok':False,'reason':'Google OAuth token refresh failed; re-authorize /google','latency_ms':int((time.time()-t0)*1000)}
        p=google_get('https://gmail.googleapis.com/gmail/v1/users/me/profile')
        addr=p.get('emailAddress') if isinstance(p,dict) else None
        if addr:
            return {'ok':True,'reason':'Gmail API authenticated over HTTPS','account':addr,'transport':'gmail_api_https','latency_ms':int((time.time()-t0)*1000)}
        err='Gmail API profile check failed'
        if isinstance(p,dict) and p.get('error'):err=str(p.get('error'))[:220]
        return {'ok':False,'reason':err,'transport':'gmail_api_https','latency_ms':int((time.time()-t0)*1000)}
    except Exception as e:
        return {'ok':False,'reason':type(e).__name__+': '+str(e)[:180],'transport':'gmail_api_https','latency_ms':int((time.time()-t0)*1000)}

def email_network_doctor():
    """Transport-aware email doctor. SMTP is irrelevant when Gmail API is configured."""
    out={'dns':{'ok':True,'reason':'not required for Gmail API'},
         'tcp465':{'ok':True,'skipped':True,'reason':'SMTP disabled while Gmail API is configured'},
         'tcp587':{'ok':True,'skipped':True,'reason':'SMTP disabled while Gmail API is configured'},
         'google443':{},'smtp_auth':{'ok':False,'skipped':True},'gmail_api':{},'ok':False,
         'transport':'none','latency_ms':0}
    if google_ready():
        out['google443']=_v135_tcp_probe('www.googleapis.com',443,4)
        api=_email_api_health();out['gmail_api']=api;out['ok']=bool(api.get('ok'));out['transport']='gmail_api_https';out['latency_ms']=int(api.get('latency_ms') or 0)
        if out['ok']:
            out['diagnosis']='HEALTHY — Gmail API over HTTPS is authenticated. SMTP 465/587 is intentionally ignored.'
        elif not out['google443'].get('ok'):
            out['diagnosis']='Gmail API unavailable because HTTPS connectivity to Google failed.'
        else:
            out['diagnosis']=str(api.get('reason') or 'Gmail API authentication unavailable')
        return out
    # Legacy fallback only when Google OAuth is absent.
    out['tcp465']=_v135_tcp_probe('smtp.gmail.com',465,4)
    out['tcp587']=_v135_tcp_probe('smtp.gmail.com',587,4)
    out['google443']=_v135_tcp_probe('www.googleapis.com',443,4)
    out['gmail_api']={'ok':False,'reason':'Google OAuth not configured'}
    if BOT_EMAIL and BOT_EMAIL_PASS:
        import smtplib
        for port,mode in ((465,'SSL'),(587,'STARTTLS')):
            if not out['tcp465' if port==465 else 'tcp587'].get('ok'):continue
            t=time.time();smtp=None
            try:
                if port==465:smtp=smtplib.SMTP_SSL('smtp.gmail.com',465,timeout=8)
                else:
                    smtp=smtplib.SMTP('smtp.gmail.com',587,timeout=8);smtp.ehlo();smtp.starttls();smtp.ehlo()
                code,_=smtp.login(BOT_EMAIL,BOT_EMAIL_PASS)
                out['smtp_auth']={'ok':200<=int(code)<400,'port':port,'mode':mode,'latency_ms':int((time.time()-t)*1000)}
                if out['smtp_auth']['ok']:break
            except Exception as e:
                out['smtp_auth']={'ok':False,'port':port,'mode':mode,'reason':type(e).__name__+': '+str(e)[:180],'latency_ms':int((time.time()-t)*1000)}
            finally:
                try:
                    if smtp:smtp.quit()
                except Exception:pass
    else:out['smtp_auth']={'ok':False,'reason':'SMTP credentials not configured'}
    out['ok']=bool(out['smtp_auth'].get('ok'));out['transport']='smtp_legacy' if out['ok'] else 'none'
    out['diagnosis']='HEALTHY — legacy SMTP authenticated.' if out['ok'] else 'No working email transport. Connect Google with /google; Gmail API over HTTPS is preferred.'
    return out

def send_email(to, subject, body, attach_path=None):
    """Gmail API is authoritative when connected; never falls through to blocked SMTP."""
    global LAST_EMAIL_ERR
    if google_ready():
        ok,err=send_email_api(to,subject,body,attach_path)
        if ok:
            LAST_EMAIL_ERR='';return True
        LAST_EMAIL_ERR='Gmail API send failed: '+str(err)[:200]+' | Re-authorize with /google if persistent.'
        return False
    return _EMAIL_HOTFIX_PREV_SEND(to,subject,body,attach_path)

def _email_hotfix_clear_legacy_failures():
    """Remove stale SMTP-derived health failures so proactive alerts cannot resurrect them."""
    try:
        _v135_init();c=_prime_conn()
        c.execute("DELETE FROM prime_health_history WHERE category='email' AND ok=0 AND (reason LIKE '%SMTP%' OR detail LIKE '%tcp465%' OR detail LIKE '%tcp587%' OR detail LIKE '%SMTP%')")
        c.execute("DELETE FROM prime_proactive_state WHERE key='last_alert'")
        c.commit();c.close()
    except Exception:pass

_PRIME_HEALTH_EMAIL_PREV=prime_health_run
def prime_health_run(notify=False):
    """Run normal health suite, but make email transport status API-authoritative."""
    r=_PRIME_HEALTH_EMAIL_PREV(notify)
    # Previous v13.35 health calls the late-bound email_network_doctor above, so
    # its email result is already corrected. Normalize any legacy label/reason.
    for p in r.get('probes',[]):
        if p.get('category')=='email' and p.get('name','').startswith('Email sending') and google_ready():
            if p.get('ok'):
                p['reason']='Gmail API/HTTPS healthy; SMTP intentionally ignored'
    return r

_PRIME_REGRESSION_EMAIL_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_EMAIL_PREV();extra=[]
    def add(n,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':n,'ok':ok,'detail':detail})
    add('email-api-authoritative',lambda:'never falls through to blocked SMTP' in (send_email.__doc__ or ''))
    add('email-doctor-api-first',lambda:'SMTP is irrelevant when Gmail API is configured' in (email_network_doctor.__doc__ or ''))
    add('email-stale-alert-cleaner',lambda:callable(globals().get('_email_hotfix_clear_legacy_failures')))
    add('email-no-smtp-on-google',lambda:'if google_ready()' in __import__('inspect').getsource(send_email) and '_EMAIL_HOTFIX_PREV_SEND' in __import__('inspect').getsource(send_email))
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x['ok']);r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_MAIN_EMAIL_HOTFIX_PREV=main
def main():
    try:
        _email_hotfix_clear_legacy_failures()
        print('NEMO Email Reliability Hotfix: Gmail API authoritative; SMTP ignored when Google connected')
    except Exception as e:
        try:print('email hotfix startup:',str(e)[:180])
        except Exception:pass
    return _MAIN_EMAIL_HOTFIX_PREV()



