def _fno_init():
    _prime_init(); c=_prime_conn()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS prime_fno_snapshots(
      id TEXT PRIMARY KEY, ts REAL, symbol TEXT, source TEXT, expiry TEXT,
      spot REAL, pcr REAL, atm REAL, atm_iv REAL, payload TEXT, quality REAL DEFAULT 0);
    CREATE INDEX IF NOT EXISTS idx_fno_snap_ts ON prime_fno_snapshots(symbol,ts DESC);
    CREATE TABLE IF NOT EXISTS prime_fno_nse_lake(
      id TEXT PRIMARY KEY, trade_date TEXT, report TEXT, source_url TEXT,
      status TEXT, bytes INTEGER DEFAULT 0, checksum TEXT, payload TEXT, updated REAL);
    CREATE TABLE IF NOT EXISTS prime_fno_setups(
      id TEXT PRIMARY KEY, ts REAL, symbol TEXT, regime TEXT, score REAL,
      decision TEXT, strategy TEXT, reasons TEXT, snapshot_id TEXT);
    """); c.commit(); c.close()

def _fno_sym(x):
    s=re.sub(r'[^A-Z0-9]','',str(x or 'NIFTY').upper())
    return {'NIFTY50':'NIFTY','NIFTYBANK':'BANKNIFTY','BANK':'BANKNIFTY','NIFTYFIN':'FINNIFTY'}.get(s,s)

def _fno_num(v, default=0.0):
    try:return float(v)
    except Exception:return default

def _fno_pct(v):
    v=_fno_num(v)
    return v*100.0 if 0 < abs(v) < 2 else v

def _fno_norm_leg(o):
    if not isinstance(o,dict): return {}
    g=o.get('greeks') or o.get('option_greeks') or {}
    md=o.get('market_data') or o
    return {
      'ltp':_fno_num(md.get('ltp',md.get('last_price'))), 'oi':_fno_num(md.get('oi')),
      'prev_oi':_fno_num(md.get('prev_oi',md.get('previous_oi'))),
      'volume':_fno_num(md.get('volume')), 'bid':_fno_num(md.get('bid_price',md.get('top_bid_price'))),
      'ask':_fno_num(md.get('ask_price',md.get('top_ask_price'))),
      'bid_qty':_fno_num(md.get('bid_qty',md.get('top_bid_quantity'))),
      'ask_qty':_fno_num(md.get('ask_qty',md.get('top_ask_quantity'))),
      'iv':_fno_pct(g.get('iv',o.get('implied_volatility',o.get('iv')))),
      'delta':_fno_num(g.get('delta')), 'gamma':_fno_num(g.get('gamma')),
      'theta':_fno_num(g.get('theta')), 'vega':_fno_num(g.get('vega')),
    }

def _fno_fyers_raw(symbol='NIFTY', strikes=12):
    sym=_fno_sym(symbol)
    if not (fyers_ready() or fyers_login()): return {'ok':False,'source':'FYERS','error':'Fyers not logged in'}
    j=fyers_data('options-chain-v3?symbol='+_oc_underlying(sym)+'&strikecount='+str(max(4,min(int(strikes),20))))
    d=(j.get('data') or {}) if isinstance(j,dict) else {}; chain=d.get('optionsChain') or d.get('options_chain') or []
    if not chain:return {'ok':False,'source':'FYERS','error':str((j or {}).get('message','empty chain'))[:180]}
    rows={};spot=0.0;expiry=''
    for o in chain:
        ot=str(o.get('option_type',o.get('optionType',''))).upper(); sy=str(o.get('symbol',''))
        if ot not in ('CE','PE'):
            spot=_fno_num(o.get('ltp',o.get('fp')),spot);continue
        sp=_fno_num(o.get('strike_price',o.get('strikePrice',o.get('strike'))))
        if not sp:continue
        leg={'ltp':_fno_num(o.get('ltp')),'oi':_fno_num(o.get('oi',o.get('openInterest'))),
             'prev_oi':_fno_num(o.get('prev_oi',o.get('previous_oi'))),'volume':_fno_num(o.get('volume')),
             'bid':_fno_num(o.get('bid',o.get('bid_price'))),'ask':_fno_num(o.get('ask',o.get('ask_price'))),
             'iv':_fno_pct(o.get('iv',o.get('impliedVolatility'))),'delta':_fno_num(o.get('delta')),
             'gamma':_fno_num(o.get('gamma')),'theta':_fno_num(o.get('theta')),'vega':_fno_num(o.get('vega'))}
        rows.setdefault(sp,{})[ot]=leg; expiry=str(o.get('expiry',o.get('expiry_date',expiry)) or expiry)
    return {'ok':bool(rows),'source':'FYERS','symbol':sym,'spot':spot,'expiry':expiry,'rows':rows}

def _fno_dhan_raw(symbol='NIFTY', expiry=''):
    sym=_fno_sym(symbol); cfg=_FNO_INDEX.get(sym)
    if not (_FNO_DHAN_CLIENT and _FNO_DHAN_TOKEN and cfg):return {'ok':False,'source':'DHAN','error':'Dhan env credentials/source mapping not configured'}
    h={'Content-Type':'application/json','access-token':_FNO_DHAN_TOKEN,'client-id':_FNO_DHAN_CLIENT}
    try:
        if not expiry:
            r=requests.post('https://api.dhan.co/v2/optionchain/expirylist',headers=h,json={'UnderlyingScrip':cfg['dhan_id'],'UnderlyingSeg':cfg['dhan_seg']},timeout=15); a=(r.json().get('data') or []); expiry=str(a[0]) if a else ''
        r=requests.post('https://api.dhan.co/v2/optionchain',headers=h,json={'UnderlyingScrip':cfg['dhan_id'],'UnderlyingSeg':cfg['dhan_seg'],'Expiry':expiry},timeout=20);j=r.json();d=j.get('data') or {};oc=d.get('oc') or {};rows={}
        for k,v in oc.items(): rows[_fno_num(k)]={'CE':_fno_norm_leg(v.get('ce')),'PE':_fno_norm_leg(v.get('pe'))}
        return {'ok':bool(rows),'source':'DHAN','symbol':sym,'spot':_fno_num(d.get('last_price')),'expiry':expiry,'rows':rows}
    except Exception as e:return {'ok':False,'source':'DHAN','error':str(e)[:180]}

def _fno_upstox_raw(symbol='NIFTY', expiry=''):
    sym=_fno_sym(symbol);cfg=_FNO_INDEX.get(sym)
    if not (_FNO_UPSTOX_TOKEN and cfg):return {'ok':False,'source':'UPSTOX','error':'Upstox token/source mapping not configured'}
    h={'Accept':'application/json','Authorization':'Bearer '+_FNO_UPSTOX_TOKEN}
    try:
        if not expiry:return {'ok':False,'source':'UPSTOX','error':'expiry required for Upstox adapter'}
        r=requests.get('https://api.upstox.com/v2/option/chain',headers=h,params={'instrument_key':cfg['upstox'],'expiry_date':expiry},timeout=20);j=r.json();rows={};spot=0
        for x in j.get('data') or []:
            sp=_fno_num(x.get('strike_price')); spot=_fno_num(x.get('underlying_spot_price'),spot)
            rows[sp]={'CE':_fno_norm_leg(x.get('call_options') or {}),'PE':_fno_norm_leg(x.get('put_options') or {})}
        return {'ok':bool(rows),'source':'UPSTOX','symbol':sym,'spot':spot,'expiry':expiry,'rows':rows}
    except Exception as e:return {'ok':False,'source':'UPSTOX','error':str(e)[:180]}

def fno_chain(symbol='NIFTY', expiry=''):
    """Authorized-source failover: Dhan -> Upstox (when expiry known) -> existing Fyers."""
    sym=_fno_sym(symbol); attempts=[]
    for fn,args in ((_fno_dhan_raw,(sym,expiry)),(_fno_upstox_raw,(sym,expiry)),(_fno_fyers_raw,(sym,12))):
        r=fn(*args); attempts.append(r.get('source','?')+': '+('OK' if r.get('ok') else r.get('error','fail')))
        if r.get('ok'):
            r['attempts']=attempts;return fno_analyze_chain(r)
    return {'ok':False,'symbol':sym,'attempts':attempts,'error':'No authorized live option source available'}

def fno_analyze_chain(raw):
    rows=raw.get('rows') or {}; spot=_fno_num(raw.get('spot')); strikes=sorted(k for k in rows if k)
    if not strikes:return dict(raw,ok=False,error='No strikes')
    atm=min(strikes,key=lambda x:abs(x-spot)) if spot else strikes[len(strikes)//2]
    ceoi=sum(_fno_num(rows[x].get('CE',{}).get('oi')) for x in strikes); peoi=sum(_fno_num(rows[x].get('PE',{}).get('oi')) for x in strikes)
    pcr=peoi/ceoi if ceoi else 0; atmce=rows[atm].get('CE',{});atmpe=rows[atm].get('PE',{})
    atm_iv=sum(v for v in (_fno_num(atmce.get('iv')),_fno_num(atmpe.get('iv'))) if v)/max(1,sum(1 for v in (atmce.get('iv'),atmpe.get('iv')) if _fno_num(v)))
    call_wall=max(strikes,key=lambda x:_fno_num(rows[x].get('CE',{}).get('oi')));put_wall=max(strikes,key=lambda x:_fno_num(rows[x].get('PE',{}).get('oi')))
    # concentration proxy only; exact dealer gamma exposure cannot be inferred from public OI alone.
    gamma=[];liq=[]
    for x in strikes:
        for typ in ('CE','PE'):
            z=rows[x].get(typ,{}) or {}; oi=_fno_num(z.get('oi')); g=abs(_fno_num(z.get('gamma'))); gamma.append((g*oi,x,typ))
            bid=_fno_num(z.get('bid'));ask=_fno_num(z.get('ask'));ltp=_fno_num(z.get('ltp')); spread=((ask-bid)/ltp*100) if ltp and ask>=bid and bid else 0
            if ltp:liq.append(spread)
    gamma.sort(reverse=True); avg_spread=sum(liq)/len(liq) if liq else 0
    dce=sum(_fno_num(rows[x].get('CE',{}).get('oi'))-_fno_num(rows[x].get('CE',{}).get('prev_oi')) for x in strikes)
    dpe=sum(_fno_num(rows[x].get('PE',{}).get('oi'))-_fno_num(rows[x].get('PE',{}).get('prev_oi')) for x in strikes)
    q=85 if raw.get('source') in ('DHAN','UPSTOX') else 72
    out=dict(raw);out.update({'ok':True,'atm':atm,'pcr':pcr,'atm_iv':atm_iv,'call_wall':call_wall,'put_wall':put_wall,'ce_oi':ceoi,'pe_oi':peoi,'delta_ce_oi':dce,'delta_pe_oi':dpe,'gamma_concentration':gamma[:5],'avg_spread_pct':avg_spread,'quality':q})
    try:
        _fno_init();sid='FNO-'+_prime_uuid.uuid4().hex[:12];c=_prime_conn();c.execute('INSERT INTO prime_fno_snapshots VALUES(?,?,?,?,?,?,?,?,?,?,?)',(sid,time.time(),out.get('symbol',''),out.get('source',''),out.get('expiry',''),spot,pcr,atm,atm_iv,json.dumps(out,ensure_ascii=False,default=str)[:200000],q));c.commit();c.close();out['snapshot_id']=sid
    except Exception:pass
    return out

def fno_regime(chain):
    if not chain.get('ok'):return {'regime':'UNKNOWN','score':0,'reasons':[chain.get('error','no chain')]}
    pcr=_fno_num(chain.get('pcr'));iv=_fno_num(chain.get('atm_iv'));dce=_fno_num(chain.get('delta_ce_oi'));dpe=_fno_num(chain.get('delta_pe_oi'));spread=_fno_num(chain.get('avg_spread_pct'))
    directional=0; reasons=[]
    if pcr>=1.15:directional+=18;reasons.append('put-heavy OI')
    elif pcr<=0.85:directional-=18;reasons.append('call-heavy OI')
    if dpe>dce and abs(dpe)>0:directional+=12;reasons.append('put OI building faster')
    elif dce>dpe and abs(dce)>0:directional-=12;reasons.append('call OI building faster')
    vol='HIGH_IV' if iv>=22 else 'LOW_IV' if iv and iv<=12 else 'NORMAL_IV'
    if spread>5:reasons.append('poor option liquidity')
    trend='BULLISH' if directional>=15 else 'BEARISH' if directional<=-15 else 'BALANCED'
    return {'regime':trend+'_'+vol,'direction_score':directional,'volatility':vol,'score':max(0,min(100,55+abs(directional)-min(spread*2,25))),'reasons':reasons}

def fno_strategy_decision(symbol='NIFTY', expiry=''):
    ch=fno_chain(symbol,expiry); rg=fno_regime(ch)
    if not ch.get('ok'):return {'decision':'NO TRADE','score':0,'strategy':'NONE','reasons':ch.get('attempts',[ch.get('error')])}
    score=_fno_num(rg.get('score'));reasons=list(rg.get('reasons') or []); spread=_fno_num(ch.get('avg_spread_pct'));iv=_fno_num(ch.get('atm_iv'));reg=rg.get('regime','')
    if spread>4:score-=25;reasons.append('spread/slippage filter failed')
    if not ch.get('spot'):score-=10;reasons.append('underlying spot unavailable')
    if score<62:decision='NO TRADE';strategy='NONE'
    else:
        decision='VALID SETUP FOR REVIEW'
        if 'BULLISH' in reg:strategy='DEFINED-RISK BULLISH STRUCTURE' if iv>=18 else 'DIRECTIONAL BULLISH CANDIDATE'
        elif 'BEARISH' in reg:strategy='DEFINED-RISK BEARISH STRUCTURE' if iv>=18 else 'DIRECTIONAL BEARISH CANDIDATE'
        else:strategy='VOLATILITY/RANGE STRUCTURE — BACKTEST FIRST' if iv>=18 else 'WAIT / RANGE RESEARCH'
    result={'symbol':_fno_sym(symbol),'decision':decision,'score':round(max(0,min(100,score)),1),'strategy':strategy,'regime':reg,'reasons':reasons,'chain':ch}
    try:
        _fno_init();i='SET-'+_prime_uuid.uuid4().hex[:10];c=_prime_conn();c.execute('INSERT INTO prime_fno_setups VALUES(?,?,?,?,?,?,?,?,?)',(i,time.time(),result['symbol'],reg,result['score'],decision,strategy,json.dumps(reasons),ch.get('snapshot_id','')));c.commit();c.close();result['id']=i
    except Exception:pass
    return result

def nse_institutional_sync(trade_date=''):
    """Best-effort official NSE archive ingestion. Failure is explicit; no scraped value is invented."""
    _fno_init(); dt=trade_date or time.strftime('%d%m%Y'); saved=[]
    candidates=[('participant_oi','fao_participant_oi_'+dt+'.csv'),('participant_volume','fao_participant_vol_'+dt+'.csv'),('fii_stats','fii_stats_'+dt+'.xls')]
    h={'User-Agent':'Mozilla/5.0','Accept':'*/*','Referer':_FNO_NSE_REPORTS}
    for name,fn in candidates:
        url=_FNO_NSE_ARCHIVE+fn;status='MISSING';body=b'';err=''
        try:
            r=requests.get(url,headers=h,timeout=20);body=r.content if r.status_code==200 else b'';status='READY' if body and len(body)>40 else 'UNAVAILABLE';err='' if status=='READY' else 'HTTP '+str(r.status_code)
        except Exception as e:err=str(e)[:120]
        checksum=hashlib.sha256(body).hexdigest() if body else ''
        rid='NSE-'+name+'-'+dt;c=_prime_conn();c.execute('INSERT OR REPLACE INTO prime_fno_nse_lake VALUES(?,?,?,?,?,?,?,?,?)',(rid,dt,name,url,status,len(body),checksum,(body[:100000].decode('utf-8','ignore') if name!='fii_stats' else ''),time.time()));c.commit();c.close();saved.append({'report':name,'status':status,'bytes':len(body),'error':err})
    return saved

