      f"Spot {ch.get('spot',0):,.2f} | ATM {ch.get('atm',0):,.0f} | PCR {ch.get('pcr',0):.2f} | ATM IV {ch.get('atm_iv',0):.2f}%\n"
      f"Call wall {ch.get('call_wall',0):,.0f} | Put wall {ch.get('put_wall',0):,.0f}\n"
      f"ΔCE OI {ch.get('delta_ce_oi',0):,.0f} | ΔPE OI {ch.get('delta_pe_oi',0):,.0f}\n"
