    if low.startswith('/fnoregime'):send_text(cid,json.dumps(fno_regime(ch),ensure_ascii=False,indent=2));return True
    if low.startswith('/fnosetup'):
        d=fno_strategy_decision(sym);send_text(cid,(f"F&O SETUP | {d['symbol']}\nDecision: {d['decision']}\nSetup quality: {d['score']}/100\nRegime: {d['regime']}\nCandidate family: {d['strategy']}\nReasons: "+'; '.join(d['reasons'])+"\n\nThis is a research/setup-quality output, not a win probability or guaranteed trade."));return True
    return True

