def _v152_init():
    _fno_init(); c=_prime_conn()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS prime_fno_migrations(
      id TEXT PRIMARY KEY, ts REAL, symbol TEXT, from_snapshot TEXT, to_snapshot TEXT,
      spot_change REAL, call_wall_from REAL, call_wall_to REAL, put_wall_from REAL,
      put_wall_to REAL, pcr_change REAL, summary TEXT);
    CREATE TABLE IF NOT EXISTS prime_fno_walkforward(
      id TEXT PRIMARY KEY, ts REAL, symbol TEXT, train INTEGER, test INTEGER,
      windows INTEGER, hit_rate REAL, expectancy REAL, max_drawdown REAL,
      payload TEXT);
    """); c.commit(); c.close()


def _v152_snapshots(symbol='NIFTY', limit=100):
    _v152_init(); sym=_fno_sym(symbol); c=_prime_conn()
    rows=c.execute('SELECT id,ts,spot,pcr,atm,atm_iv,payload FROM prime_fno_snapshots WHERE symbol=? ORDER BY ts DESC LIMIT ?', (sym,max(2,min(int(limit),500)))).fetchall(); c.close()
    out=[]
    for r in rows:
        try:p=json.loads(r[6] or '{}')
        except Exception:p={}
        out.append({'id':r[0],'ts':r[1],'spot':r[2] or 0,'pcr':r[3] or 0,'atm':r[4] or 0,'atm_iv':r[5] or 0,'payload':p})
    return out


def fno_oi_migration(symbol='NIFTY'):
    """Compare the two latest option-chain snapshots; reports observed OI movement, never inferred hidden positions."""
    ss=_v152_snapshots(symbol,2)
    if len(ss)<2:return {'ok':False,'error':'Need at least two saved option-chain snapshots. Run /fnochain twice over time.'}
    new,old=ss[0],ss[1]; a=old['payload']; b=new['payload']
    def normrows(p):
        z={}
        for k,v in (p.get('rows') or {}).items():
            try:z[float(k)]=v
            except Exception:pass
        return z
    ar,br=normrows(a),normrows(b); strikes=sorted(set(ar)|set(br)); changes=[]
    for sp in strikes:
        for typ in ('CE','PE'):
            x=_fno_num((ar.get(sp,{}).get(typ) or {}).get('oi')); y=_fno_num((br.get(sp,{}).get(typ) or {}).get('oi')); d=y-x
            if d:changes.append({'strike':sp,'type':typ,'delta_oi':d,'old_oi':x,'new_oi':y})
    changes.sort(key=lambda x:abs(x['delta_oi']),reverse=True)
    cw0=_fno_num(a.get('call_wall'));cw1=_fno_num(b.get('call_wall'));pw0=_fno_num(a.get('put_wall'));pw1=_fno_num(b.get('put_wall'))
    res={'ok':True,'symbol':_fno_sym(symbol),'seconds':round(new['ts']-old['ts'],1),'spot_change':round(new['spot']-old['spot'],2),'pcr_change':round(new['pcr']-old['pcr'],4),'call_wall':[cw0,cw1],'put_wall':[pw0,pw1],'largest_moves':changes[:12],'from_snapshot':old['id'],'to_snapshot':new['id']}
    try:
        mid='MIG-'+_prime_uuid.uuid4().hex[:10]; c=_prime_conn(); c.execute('INSERT INTO prime_fno_migrations VALUES(?,?,?,?,?,?,?,?,?,?,?)',(mid,time.time(),res['symbol'],old['id'],new['id'],res['spot_change'],cw0,cw1,pw0,pw1,res['pcr_change'],json.dumps(res,ensure_ascii=False)[:100000]));c.commit();c.close();res['id']=mid
    except Exception:pass
    return res


def fno_vol_surface(symbol='NIFTY', expiry=''):
    ch=fno_chain(symbol,expiry)
    if not ch.get('ok'):return {'ok':False,'error':ch.get('error','chain unavailable'),'attempts':ch.get('attempts',[])}
    spot=_fno_num(ch.get('spot')); pts=[]
    for sp,row in sorted((ch.get('rows') or {}).items()):
        sp=_fno_num(sp)
        for typ in ('CE','PE'):
            z=row.get(typ,{}) or {}; iv=_fno_num(z.get('iv'))
            if iv>0:pts.append({'strike':sp,'type':typ,'iv':round(iv,3),'moneyness_pct':round(((sp/spot)-1)*100,3) if spot else 0,'delta':_fno_num(z.get('delta')),'vega':_fno_num(z.get('vega'))})
    hist=[x['atm_iv'] for x in _v152_snapshots(symbol,252) if _fno_num(x.get('atm_iv'))>0]
    cur=_fno_num(ch.get('atm_iv')); rank=(100.0*sum(1 for x in hist if x<=cur)/len(hist)) if hist and cur else None
    lo=min(hist) if hist else None; hi=max(hist) if hist else None
    ivrank=((cur-lo)/(hi-lo)*100) if cur and lo is not None and hi is not None and hi>lo else None
    return {'ok':True,'symbol':_fno_sym(symbol),'source':ch.get('source'),'expiry':ch.get('expiry'),'spot':spot,'atm_iv':cur,'iv_percentile':round(rank,1) if rank is not None else None,'iv_rank':round(ivrank,1) if ivrank is not None else None,'history_samples':len(hist),'surface':pts,'note':'IV rank/percentile use Nemo saved snapshots; more history improves stability.'}


def _v152_expiry_dt(s):
    s=str(s or '').strip()
    for f in ('%Y-%m-%d','%d-%m-%Y','%d/%m/%Y','%d-%b-%Y','%d %b %Y'):
        try:return _v152_dt.datetime.strptime(s,f).date()
        except Exception:pass
    return None


def fno_expiry_intelligence(symbol='NIFTY', expiry=''):
    ch=fno_chain(symbol,expiry)
    if not ch.get('ok'):return {'ok':False,'error':ch.get('error','chain unavailable'),'attempts':ch.get('attempts',[])}
    ed=_v152_expiry_dt(ch.get('expiry') or expiry); today=_v152_dt.datetime.now().date(); dte=max(0,(ed-today).days) if ed else None
    spot=_fno_num(ch.get('spot')); atmiv=_fno_num(ch.get('atm_iv')); years=(max((dte if dte is not None else 1),0.25)/365.0)
    expected=spot*(atmiv/100.0)*_v152_math.sqrt(years) if spot and atmiv else 0
    gamma=ch.get('gamma_concentration') or []; total=sum(max(0,_fno_num(x[0])) for x in gamma); top=(gamma[0] if gamma else None); concentration=(_fno_num(top[0])/total*100) if top and total else 0
    phase='EXPIRY_DAY' if dte==0 else 'NEAR_EXPIRY' if dte is not None and dte<=2 else 'NORMAL_EXPIRY'
    risk=[]
    if phase!='NORMAL_EXPIRY':risk.append('gamma/theta sensitivity can change rapidly near expiry')
    if concentration>=45:risk.append('high OI×|gamma| concentration proxy near one strike')
    if _fno_num(ch.get('avg_spread_pct'))>4:risk.append('quoted spread/slippage risk elevated')
    return {'ok':True,'symbol':_fno_sym(symbol),'expiry':ch.get('expiry') or expiry,'dte':dte,'phase':phase,'spot':spot,'atm_iv':atmiv,'one_sigma_expected_move':round(expected,2),'gamma_proxy_top':({'strike':top[1],'type':top[2],'value':top[0]} if top else None),'top5_concentration_pct':round(concentration,1),'call_wall':ch.get('call_wall'),'put_wall':ch.get('put_wall'),'risks':risk,'note':'Gamma metric is an OI×|gamma| concentration proxy, not exact dealer gamma exposure.'}


def _v152_ema(vals,n):
    if not vals:return []
    k=2/(n+1.0); out=[float(vals[0])]
    for x in vals[1:]:out.append(float(x)*k+out[-1]*(1-k))
    return out


def _v152_strategy_returns(closes,fast,slow):
    if len(closes)<slow+3:return []
    ef=_v152_ema(closes,fast); es=_v152_ema(closes,slow); ret=[]
    for i in range(1,len(closes)):
        pos=1 if ef[i-1]>es[i-1] else -1
        r=(closes[i]/closes[i-1]-1)*pos if closes[i-1] else 0
        ret.append(r)
    return ret


def _v152_metrics(ret):
    if not ret:return {'hit_rate':0,'expectancy':0,'max_drawdown':0,'total_return':0}
    eq=1.0;peak=1.0;mdd=0
    for r in ret:eq*=1+r;peak=max(peak,eq);mdd=max(mdd,(peak-eq)/peak if peak else 0)
    return {'hit_rate':100*sum(1 for r in ret if r>0)/len(ret),'expectancy':100*sum(ret)/len(ret),'max_drawdown':100*mdd,'total_return':100*(eq-1)}


def fno_walkforward_lab(symbol='NIFTY',train=45,test=15):
    """Out-of-sample EMA-family laboratory. It validates robustness; it does not promise future profitability."""
    h=get_history(_fno_sym(symbol)); closes=[float(x) for x in ((h or {}).get('closes') or []) if x]
    train=max(30,int(train));test=max(10,int(test))
    if len(closes)<train+test:return {'ok':False,'error':f'Need >= {train+test} historical closes; got {len(closes)}'}
    candidates=[(5,13),(8,21),(10,30),(13,34),(20,50)];windows=[];alltest=[];i=0
    while i+train+test<=len(closes):
        tr=closes[i:i+train];te=closes[i+train:i+train+test]
        scored=[]
        for f,s in candidates:
            m=_v152_metrics(_v152_strategy_returns(tr,f,s));scored.append((m['total_return']-0.35*m['max_drawdown'],f,s,m))
        scored.sort(reverse=True,key=lambda x:x[0]);_,f,s,tm=scored[0]
        # warm test with training tail so EMA state is not cold-started
        joined=tr[-max(s+3,10):]+te; rr=_v152_strategy_returns(joined,f,s); rr=rr[-test:] if len(rr)>=test else rr; mm=_v152_metrics(rr);alltest.extend(rr)
        windows.append({'start':i,'fast':f,'slow':s,'train_return':round(tm['total_return'],2),'test_return':round(mm['total_return'],2),'test_hit_rate':round(mm['hit_rate'],1),'test_drawdown':round(mm['max_drawdown'],2)})
        i+=test
    m=_v152_metrics(alltest); res={'ok':True,'symbol':_fno_sym(symbol),'train':train,'test':test,'windows':len(windows),'oos_hit_rate':round(m['hit_rate'],1),'oos_expectancy_pct_per_bar':round(m['expectancy'],4),'oos_total_return':round(m['total_return'],2),'oos_max_drawdown':round(m['max_drawdown'],2),'details':windows,'warning':'Research validation only. Uses underlying daily closes, excludes option premium path, brokerage, taxes and slippage.'}
    try:
        wid='WF-'+_prime_uuid.uuid4().hex[:10];c=_prime_conn();c.execute('INSERT INTO prime_fno_walkforward VALUES(?,?,?,?,?,?,?,?,?,?)',(wid,time.time(),res['symbol'],train,test,len(windows),m['hit_rate'],m['expectancy'],m['max_drawdown'],json.dumps(res,ensure_ascii=False)[:150000]));c.commit();c.close();res['id']=wid
    except Exception:pass
    return res


def _v152_dispatch(cid,text,msg=None):
    raw=(text or '').strip();low=raw.lower(); prefixes=('/batch3','/oimigrate','/ivsurface','/ivrank','/expiryintel','/walkforward2')
    if not low.startswith(prefixes):return False
