def option_lake_status(symbol=''):
    _v153_init(); c=_prime_conn(); wh=''; args=()
    if symbol: wh=' WHERE symbol=?'; args=(_fno_sym(symbol),)
    contracts=c.execute('SELECT COUNT(*),COUNT(DISTINCT expiry) FROM prime_option_contracts'+wh,args).fetchone()
    if symbol:
        candles=c.execute('SELECT COUNT(*) FROM prime_option_candles x JOIN prime_option_contracts c ON c.contract_key=x.contract_key WHERE c.symbol=?',args).fetchone()[0]
    else:candles=c.execute('SELECT COUNT(*) FROM prime_option_candles').fetchone()[0]
    bt=c.execute('SELECT COUNT(*) FROM prime_option_backtests').fetchone()[0]; c.close()
    return {'ok':True,'symbol':_fno_sym(symbol) if symbol else 'ALL','contracts':contracts[0] or 0,'expiries':contracts[1] or 0,'candles':candles or 0,'backtests':bt or 0,
            'note':'Historical option data is stored locally. Upstox expired-instrument access may require the broker plan currently documented for that endpoint.'}


def option_fetch_expired_contracts(symbol='NIFTY', expiry=''):
    """Fetch authorized expired-contract metadata from Upstox. Does not scrape websites."""
    _v153_init(); sym=_fno_sym(symbol); cfg=_FNO_INDEX.get(sym)
    if not (_FNO_UPSTOX_TOKEN and cfg):return {'ok':False,'error':'NEMO_UPSTOX_ACCESS_TOKEN/source mapping not configured'}
    if not _v152_expiry_dt(expiry):return {'ok':False,'error':'expiry required as YYYY-MM-DD'}
    try:
        r=requests.get('https://api.upstox.com/v2/expired-instruments/option/contract',headers=_v153_upstox_headers(),params={'instrument_key':cfg['upstox'],'expiry_date':expiry},timeout=25)
        j=r.json() if r.content else {}; data=j.get('data') or []
        if r.status_code!=200:
            return {'ok':False,'status':r.status_code,'error':str(j.get('errors') or j.get('message') or r.text)[:500],'plan_note':'Expired-instrument historical endpoints may require an eligible Upstox plan.'}
        n=0;c=_prime_conn()
        for x in data:
            key=str(x.get('expired_instrument_key') or x.get('instrument_key') or '').strip()
            if not key:continue
            typ=str(x.get('instrument_type') or x.get('option_type') or '').upper()
            if typ not in ('CE','PE'): typ='CE' if str(x.get('trading_symbol','')).upper().endswith('CE') else 'PE' if str(x.get('trading_symbol','')).upper().endswith('PE') else typ
            c.execute('INSERT OR REPLACE INTO prime_option_contracts VALUES(?,?,?,?,?,?,?,?,?,?)',(key,sym,expiry,_fno_num(x.get('strike_price')),typ,str(x.get('trading_symbol') or x.get('tradingsymbol') or ''),_fno_num(x.get('lot_size')), 'UPSTOX',json.dumps(x,ensure_ascii=False)[:30000],time.time()));n+=1
        c.commit();c.close();return {'ok':True,'symbol':sym,'expiry':expiry,'contracts_saved':n}
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)[:300]}


def option_fetch_candles(contract_key, interval='5minute', from_date='', to_date=''):
    """Fetch real historical expired-option OHLCV+OI into the local lake via authorized Upstox API."""
    _v153_init(); key=str(contract_key or '').strip(); allowed={'1minute','3minute','5minute','15minute','30minute','day'}
    if interval not in allowed:return {'ok':False,'error':'interval must be '+','.join(sorted(allowed))}
    if not (_FNO_UPSTOX_TOKEN and key):return {'ok':False,'error':'Upstox token and contract_key required'}
    if not (from_date and to_date):return {'ok':False,'error':'from_date and to_date required (YYYY-MM-DD)'}
    try:
        ek=_v153_urlparse.quote(key,safe=''); url=f'https://api.upstox.com/v2/expired-instruments/historical-candle/{ek}/{interval}/{to_date}/{from_date}'
        r=requests.get(url,headers=_v153_upstox_headers(),timeout=30); j=r.json() if r.content else {}
        if r.status_code!=200:return {'ok':False,'status':r.status_code,'error':str(j.get('errors') or j.get('message') or r.text)[:500],'plan_note':'Upstox currently documents this expired-history endpoint as plan-gated.'}
        rows=(j.get('data') or {}).get('candles') or []; c=_prime_conn();n=0
        for z in rows:
            if not isinstance(z,(list,tuple)) or len(z)<6:continue
            ts=str(z[0]); ep=0
            try:ep=_v152_dt.datetime.fromisoformat(ts).timestamp()
            except Exception:pass
            oi=_fno_num(z[6]) if len(z)>6 else 0
            c.execute('INSERT OR REPLACE INTO prime_option_candles VALUES(?,?,?,?,?,?,?,?,?,?,?)',(key,interval,ts,ep,_fno_num(z[1]),_fno_num(z[2]),_fno_num(z[3]),_fno_num(z[4]),_fno_num(z[5]),oi,'UPSTOX'));n+=1
        c.commit();c.close();return {'ok':True,'contract_key':key,'interval':interval,'candles_saved':n,'from':from_date,'to':to_date}
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)[:300]}


def _v153_candles(contract_key, interval='5minute'):
    _v153_init();c=_prime_conn();rs=c.execute('SELECT ts,epoch,open,high,low,close,volume,oi FROM prime_option_candles WHERE contract_key=? AND interval=? ORDER BY epoch,ts',(contract_key,interval)).fetchall();c.close()
    return [{'ts':r[0],'epoch':r[1],'open':r[2],'high':r[3],'low':r[4],'close':r[5],'volume':r[6],'oi':r[7]} for r in rs]


def _v153_signal(strategy, closes, i, fast=5, slow=13):
    if i<max(slow,10):return 0
    now=closes[i]; prev=closes[i-1]
    if strategy=='premium_momentum':
        base=sum(closes[i-5:i])/5.0; return 1 if now>base and now>prev else 0
    if strategy=='premium_breakout': return 1 if now>max(closes[i-10:i]) else 0
    if strategy=='premium_mean_revert':
        w=closes[i-10:i]; mu=sum(w)/len(w); sd=_v153_stats.pstdev(w) if len(w)>1 else 0; return 1 if sd and now<mu-1.25*sd else 0
    ef=_v152_ema(closes[:i+1],fast)[-1]; es=_v152_ema(closes[:i+1],slow)[-1]; return 1 if ef>es else 0


def option_premium_backtest(contract_key, strategy='premium_momentum', interval='5minute', cost_bps=10, hold_bars=3, start_frac=0.0, end_frac=1.0, persist=True):
    """Backtest on actual stored option-premium closes. Costs are explicit; fills remain candle-model estimates, not tick-level execution."""
    rows=_v153_candles(contract_key,interval); n=len(rows); start=max(0,min(n,int(n*float(start_frac)))); end=max(start,min(n,int(n*float(end_frac)))); rows=rows[start:end]
    if len(rows)<30:return {'ok':False,'error':f'Need >=30 stored premium candles in selected slice; got {len(rows)}'}
    closes=[_fno_num(x['close']) for x in rows]; hold=max(1,min(int(hold_bars),30)); cost=max(0,float(cost_bps))/10000.0; rets=[]; trades=[];i=10
    while i<len(closes)-hold:
        if _v153_signal(strategy,closes,i):
            entry=closes[i];exitp=closes[i+hold]
            if entry>0:
                rr=(exitp/entry-1)-2*cost;rets.append(rr);trades.append({'entry_ts':rows[i]['ts'],'exit_ts':rows[i+hold]['ts'],'entry':entry,'exit':exitp,'return_pct':round(rr*100,3)})
                i+=hold;continue
        i+=1
    m=_v152_metrics(rets); res={'ok':True,'contract_key':contract_key,'strategy':strategy,'interval':interval,'candles':len(rows),'trades':len(rets),'win_rate':round(m['hit_rate'],2),'expectancy_pct_trade':round(m['expectancy'],4),'total_return_pct':round(m['total_return'],2),'max_drawdown_pct':round(m['max_drawdown'],2),'cost_bps_each_side':float(cost_bps),'hold_bars':hold,'sample_trades':trades[:12], 'warning':'Uses actual stored option OHLC closes but modeled candle-close entries/exits; excludes spread path, partial fills, taxes and market impact unless represented by cost_bps.'}
    if persist:
        try:
            bid='OBT-'+_prime_uuid.uuid4().hex[:10];c=_prime_conn();c.execute('INSERT INTO prime_option_backtests VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',(bid,time.time(),contract_key,strategy,interval,len(rets),m['hit_rate'],m['expectancy'],m['total_return'],m['max_drawdown'],json.dumps(res,ensure_ascii=False)[:150000]));c.commit();c.close();res['id']=bid
        except Exception:pass
    return res


def option_expiry_replay(contract_key, interval='5minute'):
    rows=_v153_candles(contract_key,interval)
    if len(rows)<5:return {'ok':False,'error':'Not enough stored candles for replay'}
    closes=[_fno_num(x['close']) for x in rows]; highs=[_fno_num(x['high']) for x in rows]; lows=[_fno_num(x['low']) for x in rows]; vols=[_fno_num(x['volume']) for x in rows];ois=[_fno_num(x['oi']) for x in rows]
    first=closes[0]; last=closes[-1]; peak=max(highs); trough=min(x for x in lows if x>=0); peak_i=highs.index(peak); trough_i=lows.index(trough)
    res={'ok':True,'contract_key':contract_key,'interval':interval,'bars':len(rows),'open_premium':first,'close_premium':last,'premium_change_pct':round((last/first-1)*100,2) if first else 0,'session_high':peak,'session_low':trough,'max_up_from_open_pct':round((peak/first-1)*100,2) if first else 0,'max_down_from_open_pct':round((trough/first-1)*100,2) if first else 0,'high_time':rows[peak_i]['ts'],'low_time':rows[trough_i]['ts'],'volume_total':round(sum(vols),2),'oi_first':ois[0],'oi_last':ois[-1],'oi_change':round(ois[-1]-ois[0],2),'timeline':[{'ts':x['ts'],'close':x['close'],'volume':x['volume'],'oi':x['oi']} for x in rows[::max(1,len(rows)//20)]], 'note':'Replay describes the observed premium/OI path. It does not infer hidden participant intent.'}
    try:
        c=_prime_conn();cr=c.execute('SELECT symbol,expiry FROM prime_option_contracts WHERE contract_key=?',(contract_key,)).fetchone();rid='RPL-'+_prime_uuid.uuid4().hex[:10];c.execute('INSERT INTO prime_option_replays VALUES(?,?,?,?,?,?)',(rid,time.time(),cr[0] if cr else '',cr[1] if cr else '',contract_key,json.dumps(res,ensure_ascii=False)[:150000]));c.commit();c.close();res['id']=rid
    except Exception:pass
    return res


def option_strategy_tournament(contract_key, interval='5minute', cost_bps=10):
    """Chronological train/test tournament. Champion must survive unseen final 30% and basic robustness gates."""
    rows=_v153_candles(contract_key,interval); n=len(rows)
    if n<100:return {'ok':False,'error':f'Need >=100 premium candles for tournament; got {n}'}
    strategies=['premium_momentum','premium_breakout','premium_mean_revert','premium_ema']; board=[]
    for st in strategies:
        train=option_premium_backtest(contract_key,st,interval,cost_bps,3,0,.70,False); test=option_premium_backtest(contract_key,st,interval,cost_bps,3,.70,1,False)
        if not (train.get('ok') and test.get('ok')):continue
        # Reward OOS expectancy/return; penalize drawdown and train->test degradation.
        degradation=max(0,_fno_num(train.get('expectancy_pct_trade'))-_fno_num(test.get('expectancy_pct_trade')))
        score=_fno_num(test.get('total_return_pct')) + 3*_fno_num(test.get('expectancy_pct_trade')) - .6*_fno_num(test.get('max_drawdown_pct')) - degradation
        robust=(test.get('trades',0)>=5 and _fno_num(test.get('expectancy_pct_trade'))>0 and _fno_num(test.get('total_return_pct'))>0)
        board.append({'strategy':st,'score':round(score,3),'robust':robust,'train':{k:train.get(k) for k in ('trades','win_rate','expectancy_pct_trade','total_return_pct','max_drawdown_pct')},'test':{k:test.get(k) for k in ('trades','win_rate','expectancy_pct_trade','total_return_pct','max_drawdown_pct')}})
    board.sort(key=lambda x:x['score'],reverse=True); champ=next((x for x in board if x['robust']),None)
    res={'ok':True,'contract_key':contract_key,'interval':interval,'champion':champ['strategy'] if champ else 'NO_CHAMPION','champion_score':champ['score'] if champ else None,'leaderboard':board,'decision':'RESEARCH_CANDIDATE' if champ else 'NO_STRATEGY_PASSED_OOS_GATE','warning':'A historical champion is not a prediction. Re-test across many expiries/regimes before considering any live use.'}
    try:
        c=_prime_conn();cr=c.execute('SELECT symbol FROM prime_option_contracts WHERE contract_key=?',(contract_key,)).fetchone();tid='TRN-'+_prime_uuid.uuid4().hex[:10];c.execute('INSERT INTO prime_strategy_tournaments VALUES(?,?,?,?,?,?,?)',(tid,time.time(),cr[0] if cr else '',contract_key,res['champion'],_fno_num(res.get('champion_score')),json.dumps(res,ensure_ascii=False)[:200000]));c.commit();c.close();res['id']=tid
    except Exception:pass
    return res


def _v153_contracts_text(symbol='NIFTY', expiry=''):
    _v153_init();c=_prime_conn();q='SELECT contract_key,expiry,strike,option_type,trading_symbol,lot_size FROM prime_option_contracts WHERE symbol=?';a=[_fno_sym(symbol)]
    if expiry:q+=' AND expiry=?';a.append(expiry)
    q+=' ORDER BY expiry DESC,strike,option_type LIMIT 40';rs=c.execute(q,tuple(a)).fetchall();c.close()
    if not rs:return 'No contracts in local lake. Use /optfetch SYMBOL YYYY-MM-DD first.'
    return '\n'.join(f'{r[1]} | {r[2]:g} {r[3]} | {r[4]} | key={r[0]}' for r in rs)


def _v153_dispatch(cid,text,msg=None):
    raw=(text or '').strip();low=raw.lower(); prefs=('/finalfno','/optlake','/optfetch','/optcontracts','/optcandles','/optionbt','/expiryreplay','/tournament')
    if not low.startswith(prefs):return False
    if not _v150_owner(cid):send_text(cid,'Owner only.');return True
    p=raw.split()
    if low=='/finalfno':
        send_text(cid,'NEMO v15.3 — FINAL F&O RESEARCH BATCH\n1) Historical Options Data Lake\n2) True Option-Premium Backtester\n3) Expiry Replay Simulator\n4) Strategy Tournament / Champion Engine\n\n/optlake [NIFTY]\n/optfetch NIFTY YYYY-MM-DD\n/optcontracts NIFTY [YYYY-MM-DD]\n/optcandles <contract_key> <interval> <from> <to>\n/optionbt <contract_key> [strategy] [interval]\n/expiryreplay <contract_key> [interval]\n/tournament <contract_key> [interval]\n\nResearch only. No order-placement authority.');return True
    if low.startswith('/optlake'):send_text(cid,json.dumps(option_lake_status(p[1] if len(p)>1 else ''),ensure_ascii=False,indent=2)[:3900]);return True
    if low.startswith('/optfetch'):
        if len(p)<3:send_text(cid,'Usage: /optfetch NIFTY YYYY-MM-DD');return True
        send_text(cid,json.dumps(option_fetch_expired_contracts(p[1],p[2]),ensure_ascii=False,indent=2)[:3900]);return True
    if low.startswith('/optcontracts'):send_text(cid,_v153_contracts_text(p[1] if len(p)>1 else 'NIFTY',p[2] if len(p)>2 else '')[:3900]);return True
    if low.startswith('/optcandles'):
        if len(p)<5:send_text(cid,'Usage: /optcandles <contract_key> <1minute|3minute|5minute|15minute|30minute|day> <YYYY-MM-DD from> <YYYY-MM-DD to>');return True
        send_text(cid,json.dumps(option_fetch_candles(p[1],p[2],p[3],p[4]),ensure_ascii=False,indent=2)[:3900]);return True
    if low.startswith('/optionbt'):
        if len(p)<2:send_text(cid,'Usage: /optionbt <contract_key> [premium_momentum|premium_breakout|premium_mean_revert|premium_ema] [interval]');return True
        send_text(cid,json.dumps(option_premium_backtest(p[1],p[2] if len(p)>2 else 'premium_momentum',p[3] if len(p)>3 else '5minute'),ensure_ascii=False,indent=2)[:3900]);return True
    if low.startswith('/expiryreplay'):
        if len(p)<2:send_text(cid,'Usage: /expiryreplay <contract_key> [interval]');return True
        send_text(cid,json.dumps(option_expiry_replay(p[1],p[2] if len(p)>2 else '5minute'),ensure_ascii=False,indent=2)[:3900]);return True
    if low.startswith('/tournament'):
        if len(p)<2:send_text(cid,'Usage: /tournament <contract_key> [interval]');return True
        send_text(cid,json.dumps(option_strategy_tournament(p[1],p[2] if len(p)>2 else '5minute'),ensure_ascii=False,indent=2)[:3900]);return True
    return True

_PRIME_REGRESSION_V153_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V153_PREV();extra=[]
    def add(n,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:160]
        extra.append({'name':n,'ok':ok,'detail':detail})
    add('v153-db',lambda:_v153_init() is None)
    add('v153-option-lake',lambda:callable(option_lake_status))
    add('v153-expired-contract-adapter',lambda:callable(option_fetch_expired_contracts))
    add('v153-premium-backtester',lambda:callable(option_premium_backtest))
    add('v153-expiry-replay',lambda:callable(option_expiry_replay))
    add('v153-tournament',lambda:callable(option_strategy_tournament))
    add('v153-no-order-path',lambda:'place_order' not in _v153_dispatch.__code__.co_names)
    add('v153-owner-gate',lambda:callable(_v150_owner))
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x['ok']);r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_HANDLE_V153_PREV=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=msg.get('text') or msg.get('caption') or ''
        if _v153_dispatch(cid,txt,msg):return
    except Exception as e:
        try:print('v15.3 final FNO dispatch:',str(e)[:180])
        except Exception:pass
    return _HANDLE_V153_PREV(msg)

