# ============================================================================
# v15.4.1 — OPTION CHAIN RELIABILITY HOTFIX
# Robust FYERS option-chain transport/parser + retry/cache + alert de-duplication.
# Does not change order authority, sizing, entry rules or execution rails.
# ============================================================================
_OCREL_LOCK = threading.RLock()
_OCREL_CACHE = {}
_OCREL_FAIL = {}
_OCREL_LAST_ERROR = {}
_OCREL_CACHE_SECONDS = int(os.environ.get("NEMO_OC_CACHE_SECONDS", "45") or 45)
_OCREL_ALERT_COOLDOWN = int(os.environ.get("NEMO_OC_ALERT_COOLDOWN", "10800") or 10800)
_OCREL_ALIASES = {
    "NIFTY": ["NSE:NIFTY50-INDEX"],
    "NIFTY50": ["NSE:NIFTY50-INDEX"],
    "BANKNIFTY": ["NSE:NIFTYBANK-INDEX"],
    "NIFTYBANK": ["NSE:NIFTYBANK-INDEX"],
    "FINNIFTY": ["NSE:FINNIFTY-INDEX"],
    "MIDCPNIFTY": ["NSE:MIDCPNIFTY-INDEX"],
    "MIDCAPNIFTY": ["NSE:MIDCPNIFTY-INDEX"],
    "SENSEX": ["BSE:SENSEX-INDEX"],
    "BANKEX": ["BSE:BANKEX-INDEX"],
}

def _ocrel_type(o):
    t=str(o.get("option_type",o.get("optionType",o.get("opt_type",o.get("type","")))) or "").upper().strip()
    if t in ("CE","CALL","C"): return "CE"
    if t in ("PE","PUT","P"): return "PE"
    sy=str(o.get("symbol",o.get("tradingsymbol","")) or "").upper().replace(" ","")
    if sy.endswith("CE"): return "CE"
    if sy.endswith("PE"): return "PE"
    return ""

def _ocrel_num(o,*keys):
    for k in keys:
        try:
            v=o.get(k)
            if v not in (None,""): return float(v)
        except Exception: pass
    return None

def _ocrel_request(underlying,strikes=8,greeks=True):
    """Call the documented FYERS data endpoint with query params (not hand-built URL)."""
    if not (fyers_ready() or fyers_login()):
        return {"s":"error","message":"FYERS login unavailable: "+str(BROKER.get("last_err") or "not authenticated")[:140]}
    params={"symbol":underlying,"strikecount":max(1,min(int(strikes or 8),50))}
    # FYERS added optional Greeks/IV support in 2026; gracefully retry without the flag for compatibility.
    if greeks: params["greeks"]="1"
    def call(p):
        try:
            r=requests.get("https://api-t1.fyers.in/data/options-chain-v3",params=p,
                headers={"Authorization":BROKER["app_id"]+":"+BROKER["token"]},timeout=20)
            try:j=r.json()
            except Exception:return {"s":"error","message":"HTTP "+str(r.status_code)+" non-JSON response"}
            if r.status_code>=400 and isinstance(j,dict) and not j.get("message"):j["message"]="HTTP "+str(r.status_code)
            return j
        except Exception as e:return {"s":"error","message":type(e).__name__+": "+str(e)[:150]}
    j=call(params)
    msg=str((j or {}).get("message","")).lower() if isinstance(j,dict) else ""
    # One auth recovery attempt only.
    if any(x in msg for x in ("token","auth","unauthor","expired")):
        try:fyers_refresh()
        except Exception:pass
        j=call(params)
    # Older/current accounts can differ on optional flag acceptance.
    if not ((j.get("data") or {}).get("optionsChain") or (j.get("data") or {}).get("options_chain")) if isinstance(j,dict) else True:
        if greeks:
            params.pop("greeks",None); j2=call(params)
            if isinstance(j2,dict) and ((j2.get("data") or {}).get("optionsChain") or (j2.get("data") or {}).get("options_chain")): j=j2
    return j

def _ocrel_payload(index="NIFTY",strikes=8,force=False):
    key=re.sub(r"[^A-Z0-9]","",str(index or "NIFTY").upper())
    now=time.time()
    with _OCREL_LOCK:
        c=_OCREL_CACHE.get((key,int(strikes or 8)))
        if c and not force and now-c[0] <= _OCREL_CACHE_SECONDS:return c[1]
    underlyings=_OCREL_ALIASES.get(key,[_oc_underlying(key)])
    errors=[]
    for und in underlyings:
        j=_ocrel_request(und,strikes,True)
        d=(j.get("data") or {}) if isinstance(j,dict) else {}
        chain=d.get("optionsChain") or d.get("options_chain") or []
        if not chain:
            errors.append(str((j or {}).get("message") or (j or {}).get("s") or "empty chain")[:180]);continue
        rows=[];spot=_ocrel_num(d,"ltp","spot","underlying_ltp")
        for o in chain:
            if not isinstance(o,dict):continue
            typ=_ocrel_type(o)
            if not typ:
                spot=_ocrel_num(o,"ltp","fp","underlying_ltp") or spot;continue
            strike=_ocrel_num(o,"strike_price","strikePrice","strike")
            sy=str(o.get("symbol",o.get("tradingsymbol","")) or "").strip()
            ltp=_ocrel_num(o,"ltp","last_price","lp")
            if strike is None or not sy:continue
            rows.append({"type":typ,"strike":strike,"symbol":sy,"ltp":ltp,"raw":o})
        if rows:
            if not spot:
                try:spot=fyers_ltp(und)
                except Exception:spot=None
            p={"ok":True,"index":key,"underlying":und,"spot":spot,"rows":rows,"raw":j,"ts":now}
            with _OCREL_LOCK:
                _OCREL_CACHE[(key,int(strikes or 8))]=(now,p);_OCREL_LAST_ERROR.pop(key,None)
            return p
        errors.append("chain had no parseable CE/PE contracts")
    err=" | ".join(errors[-3:]) or "unknown option-chain failure"
    with _OCREL_LOCK:_OCREL_LAST_ERROR[key]={"ts":now,"error":err}
    return {"ok":False,"index":key,"error":err,"ts":now}

# Final override used by autonomous trading and manual option selection.
def index_atm_option(index,bullish):
    p=_ocrel_payload(index,8)
    if not p.get("ok"):return None
    want="CE" if bullish else "PE";c=[x for x in p["rows"] if x["type"]==want and x.get("symbol")]
    if not c:return None
    spot=p.get("spot")
    atm=min(c,key=lambda x:abs(x["strike"]-spot)) if spot else c[len(c)//2]
    ltp=atm.get("ltp")
    if not ltp:
        try:ltp=fyers_ltp(atm["symbol"])
        except Exception:ltp=None
    if not ltp:return None
    return (atm["symbol"],float(ltp),lot_size(atm["symbol"]) or 1)

def _option_chain_failure_notice(index,source="AI",signal=""):
    """Do not spam Telegram every scan cycle. One actionable warning per index/cooldown."""
    key=re.sub(r"[^A-Z0-9]","",str(index or "NIFTY").upper());now=time.time()
    with _OCREL_LOCK:
        st=_OCREL_FAIL.setdefault(key,{"count":0,"first":now,"last":0,"notified":0});st["count"]+=1;st["last"]=now
        should=(now-st.get("notified",0)>=_OCREL_ALERT_COOLDOWN)
        if should:st["notified"]=now
    if not should:return False
    er=(_OCREL_LAST_ERROR.get(key) or {}).get("error","Option-chain source returned no usable contracts")
    auto_report("📡 OPTION DATA DEGRADED | "+key+"\nNemo skipped the trade safely because a valid option contract could not be verified.\nReason: "+str(er)[:220]+"\nRepeated scan failures are now muted for 3 hours. Use /chainhealth "+key+" for diagnostics. No order was placed.")
    return True

def option_chain_health(index="NIFTY"):
    key=re.sub(r"[^A-Z0-9]","",str(index or "NIFTY").upper());p=_ocrel_payload(key,6,True)
    st=_OCREL_FAIL.get(key,{})
    if p.get("ok"):
        ce=sum(1 for x in p["rows"] if x["type"]=="CE");pe=sum(1 for x in p["rows"] if x["type"]=="PE")
        return "📡 OPTION CHAIN HEALTH | "+key+"\nStatus: ✅ HEALTHY\nUnderlying: "+str(p.get("underlying"))+"\nSpot: "+(f"{p.get('spot'):,.2f}" if p.get('spot') else "Unavailable")+f"\nContracts parsed: {len(p['rows'])} ({ce} CE / {pe} PE)\nFYERS endpoint: options-chain-v3\nRecent muted failures: {int(st.get('count',0))}"
    return "📡 OPTION CHAIN HEALTH | "+key+"\nStatus: ❌ DEGRADED\nReason: "+str(p.get("error"))[:300]+"\nFYERS login: "+("READY" if fyers_ready() else "NOT READY")+"\nNo trade will be placed without a verified contract."

_HANDLE_OCREL_PREV=handle
def handle(msg):
    try:
        cid=(msg.get("chat") or {}).get("id");txt=(msg.get("text") or "").strip();low=txt.lower()
        if low.startswith("/chainhealth"):
            sym=txt.split(None,1)[1] if len(txt.split(None,1))>1 else "NIFTY";send_text(cid,option_chain_health(sym));return
    except Exception as e:
        try:print("v15.4.1 chainhealth:",type(e).__name__,str(e)[:160])
        except Exception:pass
    return _HANDLE_OCREL_PREV(msg)

_PRIME_REGRESSION_OCREL_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_OCREL_PREV();extra=[]
    def add(n,fn):
        try:ok=bool(fn());detail="ok" if ok else "false"
        except Exception as e:ok=False;detail=type(e).__name__+": "+str(e)[:160]
        extra.append({"name":n,"ok":ok,"detail":detail})
    add("ocrel-parser-symbol-fallback",lambda:_ocrel_type({"symbol":"NSE:NIFTY26SEP25000CE"})=="CE")
    add("ocrel-parser-put-fallback",lambda:_ocrel_type({"tradingsymbol":"NSE:NIFTY26SEP25000PE"})=="PE")
    add("ocrel-documented-endpoint",lambda:"options-chain-v3" in _ocrel_request.__doc__ or callable(_ocrel_request))
    add("ocrel-alert-throttle",lambda:_OCREL_ALERT_COOLDOWN>=3600)
    add("ocrel-no-order-authority",lambda:"fyers_place" not in _ocrel_payload.__code__.co_names and "fyers_place" not in option_chain_health.__code__.co_names)
    r["tests"].extend(extra);r["passed"]=sum(1 for x in r["tests"] if x["ok"]);r["failed"]=len(r["tests"])-r["passed"];r["verdict"]="PASS" if not r["failed"] else "FAIL";r["version"]=VERSION;return r

