def _v155_owner(cid):
    try:return bool(_v154_owner(cid))
    except Exception:return cid == OWNER.get('id')

# --------------------------- DATA / DATABASE HANDS ---------------------------
def dbhands_add(name, engine, target, secret_env=''):
    _v155_init(); name=re.sub(r'[^A-Za-z0-9_.-]','',str(name or ''))[:48]
    eng=str(engine or '').lower().strip(); tgt=str(target or '').strip(); env=str(secret_env or '').strip()
    if not name:return {'ok':False,'error':'invalid profile name'}
    if eng not in ('sqlite','postgres','mysql'):return {'ok':False,'error':'engine must be sqlite, postgres, or mysql'}
    if eng=='sqlite':
        p=os.path.realpath(os.path.expanduser(tgt))
        if not os.path.isfile(p):return {'ok':False,'error':'SQLite file not found'}
        if not p.lower().endswith(('.db','.sqlite','.sqlite3')):return {'ok':False,'error':'SQLite target must be a .db/.sqlite/.sqlite3 file'}
        tgt=p;env=''
    else:
        # Never persist database passwords/DSNs in Nemo DB. Store only an env-var name.
        if not env and tgt.lower().startswith('env:'):env=tgt[4:].strip();tgt=''
        if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]{1,95}',env or ''):
            return {'ok':False,'error':'external DB requires env:ENV_VAR containing its DSN; secrets are not stored in Nemo'}
        tgt='env:'+env
    with sqlite3.connect(_V155_DB) as c:c.execute('INSERT OR REPLACE INTO prime_db_profiles(name,engine,target,secret_env,enabled,created,updated) VALUES(?,?,?,?,1,COALESCE((SELECT created FROM prime_db_profiles WHERE name=?),?),?)',(name,eng,tgt,env,name,time.time(),time.time()))
    return {'ok':True,'name':name,'engine':eng,'target':tgt}


def dbhands_profiles():
    _v155_init()
    with sqlite3.connect(_V155_DB) as c:
        c.row_factory=sqlite3.Row;return [dict(r) for r in c.execute('SELECT name,engine,target,enabled,updated FROM prime_db_profiles ORDER BY name')]


def _dbhands_safe_sql(sql):
    q=(sql or '').strip()
    if not q or len(q)>12000:return False,'empty or oversized SQL'
    if ';' in q.rstrip(';'):return False,'multiple statements are not allowed'
    low=re.sub(r'/\*.*?\*/|--[^\n]*',' ',q,flags=re.S).lower().strip()
    if not re.match(r'^(select|with|explain\s+select|pragma\s+(table_info|table_xinfo|index_list|index_info)\b)',low):
        return False,'read-only queries only (SELECT/WITH/EXPLAIN or safe schema PRAGMA)'
    bad=r'\b(insert|update|delete|replace|drop|alter|create|attach|detach|vacuum|reindex|truncate|grant|revoke|copy|load|install|call|execute|merge)\b'
    if re.search(bad,low):return False,'write/admin SQL blocked'
    return True,''


def _dbhands_redact(columns,row):
    out=[]
    for i,v in enumerate(row):
        col=str(columns[i] if i<len(columns) else '').lower()
        if any(x in col for x in ('password','passwd','secret','token','api_key','apikey','private_key','seed','credential')):
            out.append('[REDACTED]')
        else:
            s=str(v)
            out.append(s[:500] + ('…' if len(s)>500 else ''))
    return out


def dbhands_query(profile, sql, limit=50):
    _v155_init();safe,why=_dbhands_safe_sql(sql)
    if not safe:return {'ok':False,'error':why}
    lim=max(1,min(int(limit or 50),100));start=time.time()
    with sqlite3.connect(_V155_DB) as c:
        c.row_factory=sqlite3.Row;r=c.execute('SELECT * FROM prime_db_profiles WHERE name=? AND enabled=1',(profile,)).fetchone()
    if not r:return {'ok':False,'error':'unknown/disabled DB profile'}
    eng=r['engine'];cols=[];rows=[]
    try:
        if eng=='sqlite':
            uri='file:'+_v155_urlparse.quote(os.path.realpath(r['target']))+'?mode=ro'
            con=sqlite3.connect(uri,uri=True,timeout=8);con.execute('PRAGMA query_only=ON');cur=con.execute(sql);cols=[d[0] for d in (cur.description or [])];rows=cur.fetchmany(lim);con.close()
        elif eng=='postgres':
            dsn=os.environ.get(r['secret_env'] or '')
            if not dsn:raise RuntimeError('configured DSN environment variable is missing')
            import psycopg
            with psycopg.connect(dsn,connect_timeout=8) as con:
                con.execute('SET TRANSACTION READ ONLY');cur=con.execute(sql);cols=[d.name for d in (cur.description or [])];rows=cur.fetchmany(lim)
        elif eng=='mysql':
            dsn=os.environ.get(r['secret_env'] or '')
            if not dsn:raise RuntimeError('configured DSN environment variable is missing')
            u=_v155_urlparse.urlparse(dsn);import pymysql
            con=pymysql.connect(host=u.hostname,user=_v155_urlparse.unquote(u.username or ''),password=_v155_urlparse.unquote(u.password or ''),database=(u.path or '/').lstrip('/'),port=u.port or 3306,connect_timeout=8,read_timeout=12,write_timeout=12)
            try:
                cur=con.cursor();cur.execute('SET SESSION TRANSACTION READ ONLY');cur.execute(sql);cols=[d[0] for d in (cur.description or [])];rows=cur.fetchmany(lim)
            finally:con.close()
        ms=(time.time()-start)*1000;clean=[_dbhands_redact(cols,x) for x in rows]
        with sqlite3.connect(_V155_DB) as c:c.execute('INSERT INTO prime_db_queries(ts,profile,sql_sha,row_count,elapsed_ms,ok,error) VALUES(?,?,?,?,?,1,\'\')',(time.time(),profile,hashlib.sha256(sql.encode()).hexdigest()[:16],len(clean),ms))
        return {'ok':True,'profile':profile,'engine':eng,'columns':cols,'rows':clean,'row_count':len(clean),'limited_to':lim,'elapsed_ms':round(ms,1)}
    except Exception as e:
        er=type(e).__name__+': '+str(e)[:220];ms=(time.time()-start)*1000
        with sqlite3.connect(_V155_DB) as c:c.execute('INSERT INTO prime_db_queries(ts,profile,sql_sha,row_count,elapsed_ms,ok,error) VALUES(?,?,?,?,?,0,?)',(time.time(),profile,hashlib.sha256(sql.encode()).hexdigest()[:16],0,ms,er))
        return {'ok':False,'error':er,'elapsed_ms':round(ms,1)}

