def devops_repo_add(name, local_path='', github_repo=''):
    _v155_init();name=re.sub(r'[^A-Za-z0-9_.-]','',str(name or ''))[:48]
    lp=os.path.realpath(os.path.expanduser(local_path)) if local_path else ''
    if lp and not os.path.isdir(os.path.join(lp,'.git')):return {'ok':False,'error':'local path is not a git repository'}
    gh=str(github_repo or '').strip()
    if gh and not re.fullmatch(r'[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+',gh):return {'ok':False,'error':'GitHub repo must be owner/name'}
    if not name or not (lp or gh):return {'ok':False,'error':'name and local path or GitHub repo required'}
    with sqlite3.connect(_V155_DB) as c:c.execute('INSERT OR REPLACE INTO prime_devops_repos(name,local_path,github_repo,enabled,created,updated) VALUES(?,?,?,1,COALESCE((SELECT created FROM prime_devops_repos WHERE name=?),?),?)',(name,lp,gh,name,time.time(),time.time()))
    return {'ok':True,'name':name,'local_path':lp,'github_repo':gh}


def _devops_repo(name):
    _v155_init()
    with sqlite3.connect(_V155_DB) as c:
        c.row_factory=sqlite3.Row;r=c.execute('SELECT * FROM prime_devops_repos WHERE name=? AND enabled=1',(name,)).fetchone();return dict(r) if r else None


def _git_ro(path,args,timeout=12):
    allowed={'status','log','diff','branch','rev-parse','show'}
    if not args or args[0] not in allowed:return {'ok':False,'error':'git operation not allowlisted'}
    try:
        r=subprocess.run(['git','-C',path]+list(args),capture_output=True,text=True,timeout=timeout,env={**os.environ,'GIT_TERMINAL_PROMPT':'0'})
        return {'ok':r.returncode==0,'output':((r.stdout or '')+(('\n'+r.stderr) if r.stderr else ''))[:12000],'rc':r.returncode}
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)[:180]}


def devops_status(name):
    r=_devops_repo(name)
    if not r:return {'ok':False,'error':'unknown repo'}
    out={'ok':True,'name':name,'local':None,'github':None}
    if r.get('local_path'):
        lp=r['local_path'];branch=_git_ro(lp,['rev-parse','--abbrev-ref','HEAD']);st=_git_ro(lp,['status','--short']);lg=_git_ro(lp,['log','-5','--pretty=format:%h | %ad | %s','--date=short'])
        out['local']={'branch':(branch.get('output') or '').strip(),'dirty':bool((st.get('output') or '').strip()),'changes':(st.get('output') or '').strip().splitlines()[:20],'recent_commits':(lg.get('output') or '').strip().splitlines()[:5]}
    gh=r.get('github_repo')
    if gh:
        prs,ep=_gh('GET','/repos/'+gh+'/pulls?state=open&per_page=10');runs,er=_gh('GET','/repos/'+gh+'/actions/runs?per_page=5')
        out['github']={'repo':gh,'open_prs':len(prs or []) if not ep else None,'ci':[{'name':x.get('name'),'status':x.get('conclusion') or x.get('status'),'branch':x.get('head_branch')} for x in ((runs or {}).get('workflow_runs',[]) if not er else [])],'errors':[x for x in (ep,er) if x]}
    return out


def devops_review_plan(name, change):
    r=_devops_repo(name)
    if not r:return {'ok':False,'error':'unknown repo'}
    ctx=json.dumps(devops_status(name),ensure_ascii=False)[:8000]
    prompt=('You are Nemo DevOps Planner. Produce a SAFE deployment plan only; do not claim execution. '
            'Include: current-state risks, proposed changes, tests, rollback, observability, approval gates. '
            'Never output secrets. Repo context:\n'+ctx+'\n\nRequested change:\n'+str(change)[:4000])
    ans=ask_ai(OWNER.get('id') or 0,prompt,remember=False,deep=True,raw=True,timeout=150)
    return {'ok':True,'plan':ans or 'No plan generated','execution':'NOT_PERFORMED'}

# ------------------------------- SRE HANDS 2.0 -------------------------------
def sre_register_service(name):
    _v155_init();n=str(name or '').strip()
    if not _V155_SAFE_SERVICE.fullmatch(n) or n.lower() in _V155_BLOCKED_SERVICES:return {'ok':False,'error':'service is invalid or protected'}
    # Restrict to Nemo/app-style services to avoid broad machine control.
    if not (n.lower().startswith(('nemo','nemotron','app-')) or n.lower().endswith(('.service',))):return {'ok':False,'error':'only Nemo/app managed services may be registered'}
    with sqlite3.connect(_V155_DB) as c:c.execute('INSERT OR REPLACE INTO prime_sre_services(name,enabled,created,updated) VALUES(?,1,COALESCE((SELECT created FROM prime_sre_services WHERE name=?),?),?)',(n,n,time.time(),time.time()))
    return {'ok':True,'service':n}


