def _sre_run(args,timeout=10):
    try:
        r=subprocess.run(args,capture_output=True,text=True,timeout=timeout,env={**os.environ,'SYSTEMD_COLORS':'0','PAGER':'cat'})
        return {'ok':r.returncode==0,'rc':r.returncode,'output':((r.stdout or '')+(('\n'+r.stderr) if r.stderr else ''))[:12000]}
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)[:180]}


def sre_health():
    _v155_init();d={}
    try:
        la=os.getloadavg();d['load']=[round(x,2) for x in la]
    except Exception:d['load']=[]
    try:
        du=shutil.disk_usage('/');d['disk']={'used_pct':round(du.used*100/du.total,1),'free_gb':round(du.free/1024**3,2)}
    except Exception:d['disk']={}
    try:
        mem={}
        for ln in open('/proc/meminfo',errors='ignore'):
            if ':' in ln:
                k,v=ln.split(':',1);mem[k]=int(re.findall(r'\d+',v)[0]) if re.findall(r'\d+',v) else 0
        d['memory']={'used_pct':round((1-mem.get('MemAvailable',0)/max(mem.get('MemTotal',1),1))*100,1)}
    except Exception:d['memory']={}
    with sqlite3.connect(_V155_DB) as c:sv=[x[0] for x in c.execute('SELECT name FROM prime_sre_services WHERE enabled=1 ORDER BY name')]
    states={}
    for n in sv[:30]:
        q=_sre_run(['systemctl','is-active',n],5);states[n]=(q.get('output') or '').strip().splitlines()[0] if q.get('output') else ('active' if q.get('ok') else 'unknown')
    d['services']=states
    risk=[]
    if d.get('disk',{}).get('used_pct',0)>=90:risk.append('disk usage >=90%')
    if d.get('memory',{}).get('used_pct',0)>=92:risk.append('memory usage >=92%')
    for n,s in states.items():
        if s!='active':risk.append(n+' is '+s)
    d['status']='DEGRADED' if risk else 'HEALTHY';d['risks']=risk
    return d


def sre_logs(name,lines=80):
    if not _sre_service_allowed(name):return {'ok':False,'error':'service not registered'}
    n=max(20,min(int(lines or 80),200));return _sre_run(['journalctl','-u',name,'-n',str(n),'--no-pager','--output=short-iso'],12)


def sre_restart_request(name):
    if not _sre_service_allowed(name):return {'ok':False,'error':'service not registered'}
    aid='SRE-'+_v155_secrets.token_hex(3).upper();now=time.time()
    with sqlite3.connect(_V155_DB) as c:c.execute('INSERT INTO prime_sre_approvals(approval_id,action,resource,created,expires,status,detail) VALUES(?,?,?,?,?,\'PENDING\',\'\')',(aid,'restart_service',name,now,now+600))
    return {'ok':True,'approval_id':aid,'expires_in_seconds':600,'message':'No restart performed. Explicit /sre approve '+aid+' required.'}


def sre_approve(aid):
    _v155_init();now=time.time()
    with sqlite3.connect(_V155_DB) as c:
        c.row_factory=sqlite3.Row;r=c.execute('SELECT * FROM prime_sre_approvals WHERE approval_id=?',(aid,)).fetchone()
        if not r:return {'ok':False,'error':'unknown approval'}
        if r['status']!='PENDING':return {'ok':False,'error':'approval already '+r['status']}
        if float(r['expires'])<now:c.execute('UPDATE prime_sre_approvals SET status=\'EXPIRED\' WHERE approval_id=?',(aid,));return {'ok':False,'error':'approval expired'}
        if r['action']!='restart_service' or not _sre_service_allowed(r['resource']):return {'ok':False,'error':'approval target no longer allowed'}
        out=_sre_run(['systemctl','restart',r['resource']],20);status='EXECUTED' if out.get('ok') else 'FAILED';c.execute('UPDATE prime_sre_approvals SET status=?,detail=? WHERE approval_id=?',(status,str(out.get('output') or out.get('error') or '')[:500],aid))
    return {'ok':bool(out.get('ok')),'service':r['resource'],'status':status,'detail':str(out.get('output') or out.get('error') or '')[:500]}

# --------------------------- MULTI-AGENT SWARM 2.0 ----------------------------
_SWARM2_ROLES=(
 ('RESEARCHER','evidence, facts, missing information and source quality'),
 ('ENGINEER','technical feasibility, architecture, execution and failure modes'),
 ('RISK','security, legal, financial, operational and downside risk'),
 ('CRITIC','challenge assumptions, find contradictions and strongest counter-case'),
 ('OPERATOR','practical sequence, resources, dependencies and measurable next actions'),
)

def _swarm2_parse(text):
    m=re.search(r'VERDICT\s*:\s*([^\n]+)',text or '',re.I);c=re.search(r'CONFIDENCE\s*:\s*(\d{1,3})',text or '',re.I)
    return ((m.group(1).strip()[:120] if m else 'UNRESOLVED'),max(0,min(int(c.group(1)),100))/100 if c else .5)


def swarm2_run(task,chat_id=None):
    _v155_init();rid='SW2-'+_v155_secrets.token_hex(4).upper();start=time.time();task=str(task or '').strip()[:6000]
    if not task:return {'ok':False,'error':'task required'}
    with sqlite3.connect(_V155_DB) as c:c.execute('INSERT INTO prime_swarm2_runs(run_id,ts,task,status) VALUES(?,?,?,\'RUNNING\')',(rid,time.time(),task))
    votes={};lock=threading.Lock()
    def worker(role,focus):
        t=time.time()
        p=('You are the '+role+' in Nemo Swarm 2.0. Work independently. Focus on '+focus+'. '
           'Do not claim actions were executed. Separate facts from assumptions. Reply in this exact compact structure:\n'
           'VERDICT: <one-line recommendation>\nCONFIDENCE: <0-100>\nEVIDENCE: <key evidence/unknowns>\nRISKS: <top risks>\nNEXT: <best next action>\n\nTASK:\n'+task)
        try:a=ask_ai(chat_id or OWNER.get('id') or 0,p,remember=False,deep=False,raw=True,timeout=120) or '';v,cf=_swarm2_parse(a);ok=bool(a)
        except Exception as e:a=type(e).__name__+': '+str(e)[:180];v='FAILED';cf=0;ok=False
        with lock:votes[role]={'analysis':a[:5000],'verdict':v,'confidence':cf,'ok':ok,'elapsed_ms':round((time.time()-t)*1000,1)}
    th=[]
    for role,focus in _SWARM2_ROLES:
        x=threading.Thread(target=worker,args=(role,focus),daemon=True,name='nemo-sw2-'+role.lower());x.start();th.append(x)
    for x in th:x.join(timeout=150)
    blob='\n\n'.join('== '+r+' ==\n'+votes.get(r,{}).get('analysis','NO RESPONSE') for r,_ in _SWARM2_ROLES)
    synth=('You are the Nemo Swarm Governor. Synthesize independent specialists without majority-vote blindly. '
           'Resolve contradictions using evidence quality. If evidence is insufficient, say so. Do not execute anything. '
           'Return:\nDECISION: ...\nCONFIDENCE: 0-100\nCONSENSUS: high|medium|low\nDISAGREEMENT: ...\nWHY: ...\nRISKS: ...\nNEXT ACTION: ...\n\nTASK:\n'+task+'\n\nSPECIALISTS:\n'+blob[:22000])
    try:final=ask_ai(chat_id or OWNER.get('id') or 0,synth,remember=False,deep=True,raw=True,timeout=180) or 'No synthesis';_,conf=_swarm2_parse(final.replace('DECISION:','VERDICT:',1));dm=re.search(r'DISAGREEMENT\s*:\s*([^\n]+)',final,re.I);dis=dm.group(1).strip()[:1000] if dm else ''
    except Exception as e:final='Synthesis failed: '+type(e).__name__+': '+str(e)[:180];conf=0;dis='synthesis failure'
    elapsed=(time.time()-start)*1000
    with sqlite3.connect(_V155_DB) as c:
        c.execute('UPDATE prime_swarm2_runs SET status=\'DONE\',verdict=?,confidence=?,disagreement=?,elapsed_ms=? WHERE run_id=?',(final[:7000],conf,dis,elapsed,rid))
        for role,d in votes.items():c.execute('INSERT INTO prime_swarm2_votes(run_id,role,verdict,confidence,analysis,elapsed_ms,ok) VALUES(?,?,?,?,?,?,?)',(rid,role,d['verdict'],d['confidence'],d['analysis'],d['elapsed_ms'],1 if d['ok'] else 0))
    return {'ok':True,'run_id':rid,'specialists':len(votes),'verdict':final,'confidence':conf,'disagreement':dis,'elapsed_ms':round(elapsed,1),'execution':'NONE'}


def swarm2_history(limit=8):
    _v155_init()
    with sqlite3.connect(_V155_DB) as c:
        c.row_factory=sqlite3.Row;return [dict(x) for x in c.execute('SELECT run_id,ts,status,confidence,substr(task,1,160) task,elapsed_ms FROM prime_swarm2_runs ORDER BY ts DESC LIMIT ?',(max(1,min(int(limit),20)),))]

