def _v155_status_text():
    return ('NEMO v15.5 | OPERATIONS & ORCHESTRATION BATCH 3\n━━━━━━━━━━━━━━━━━━━━\n'
            '🗄 Database Hands  READY — read-only SQLite/Postgres/MySQL profiles\n'
            '🧑‍💻 DevOps Hands   READY — local Git + GitHub/CI inspection + deployment planning\n'
            '🩺 SRE Hands       READY — health/logs + approval-gated app-service restart\n'
            '🧠 Swarm 2.0      READY — 5 independent specialists + evidence-weighted governor\n\n'
            'Authority: no DB writes, no arbitrary shell, no silent deploy, no swarm tool execution.')


def _v155_dispatch(cid,text,msg=None):
    raw=(text or '').strip();low=raw.lower()
    if not low.startswith(('/batch5','/v155','/db','/devops','/sre','/swarm2')):return False
    if not _v155_owner(cid):send_text(cid,'Operations & Orchestration controls are owner-only.');return True
    _v155_init()
    if low in ('/batch5','/v155'):send_text(cid,_v155_status_text());return True
    if low=='/db':
        ps=dbhands_profiles();send_text(cid,'🗄 DATABASE HANDS 1.0\n/db add sqlite <name> | <path>\n/db add postgres|mysql <name> | env:DSN_ENV\n/db query <name> | <SELECT...>\n\nProfiles:\n'+('\n'.join(f"• {x['name']} [{x['engine']}] {x['target']}" for x in ps) or 'None'));return True
    m=re.match(r'^/db\s+add\s+(sqlite|postgres|mysql)\s+([^|\s]+)\s*\|\s*(.+)$',raw,re.I)
    if m:
        eng,name,tgt=m.group(1).lower(),m.group(2),m.group(3).strip();send_text(cid,json.dumps(dbhands_add(name,eng,tgt),ensure_ascii=False,indent=2));return True
    m=re.match(r'^/db\s+query\s+([^|\s]+)\s*\|\s*(.+)$',raw,re.I|re.S)
    if m:send_text(cid,json.dumps(dbhands_query(m.group(1),m.group(2)),ensure_ascii=False,indent=2)[:3900]);return True
    if low=='/devops':send_text(cid,'🧑‍💻 DEVOPS HANDS 2.0\n/devops add <name> | <local_path> | <owner/repo>\n/devops status <name>\n/devops plan <name> | <change>\nRead-only inspection; plan does not deploy.');return True
    m=re.match(r'^/devops\s+add\s+([^|\s]+)\s*\|\s*([^|]*)\|\s*(.*)$',raw,re.I)
    if m:send_text(cid,json.dumps(devops_repo_add(m.group(1),m.group(2).strip(),m.group(3).strip()),indent=2));return True
    m=re.match(r'^/devops\s+status\s+(\S+)$',raw,re.I)
    if m:send_text(cid,json.dumps(devops_status(m.group(1)),ensure_ascii=False,indent=2)[:3900]);return True
    m=re.match(r'^/devops\s+plan\s+([^|\s]+)\s*\|\s*(.+)$',raw,re.I|re.S)
    if m:
        send_text(cid,'🧑‍💻 Building a deployment plan — no changes will be executed.')
        threading.Thread(target=lambda:send_text(cid,str(devops_review_plan(m.group(1),m.group(2)).get('plan'))[:3900]),daemon=True,name='nemo-devops-plan').start();return True
    if low=='/sre':send_text(cid,'🩺 SRE HANDS 2.0\n/sre health\n/sre add <service>\n/sre logs <service> [lines]\n/sre restart <service> → approval\n/sre approve <SRE-id>');return True
    if low=='/sre health':send_text(cid,json.dumps(sre_health(),ensure_ascii=False,indent=2));return True
    m=re.match(r'^/sre\s+add\s+(\S+)$',raw,re.I)
    if m:send_text(cid,json.dumps(sre_register_service(m.group(1)),indent=2));return True
    m=re.match(r'^/sre\s+logs\s+(\S+)(?:\s+(\d+))?$',raw,re.I)
    if m:send_text(cid,json.dumps(sre_logs(m.group(1),int(m.group(2) or 80)),ensure_ascii=False,indent=2)[:3900]);return True
    m=re.match(r'^/sre\s+restart\s+(\S+)$',raw,re.I)
    if m:send_text(cid,json.dumps(sre_restart_request(m.group(1)),indent=2));return True
    m=re.match(r'^/sre\s+approve\s+(SRE-[A-F0-9]+)$',raw,re.I)
    if m:send_text(cid,json.dumps(sre_approve(m.group(1).upper()),ensure_ascii=False,indent=2));return True
    if low=='/swarm2':send_text(cid,'🧠 SWARM 2.0\n/swarm2 <hard question/task>\n/swarm2 history\n5 independent specialists → evidence-weighted governor. No direct tool execution.');return True
    if low=='/swarm2 history':send_text(cid,json.dumps(swarm2_history(),ensure_ascii=False,indent=2)[:3900]);return True
    if low.startswith('/swarm2 '):
        task=raw.split(None,1)[1].strip();send_text(cid,'🧠 Swarm 2.0 convened: Researcher + Engineer + Risk + Critic + Operator…')
        def _go():
            d=swarm2_run(task,cid);send_text(cid,(f"🧠 SWARM 2.0 | {d.get('run_id')}\n\n"+str(d.get('verdict') or d.get('error')))[:3900])
        threading.Thread(target=_go,daemon=True,name='nemo-swarm2-run').start();return True
    send_text(cid,'Use /batch5 | /db | /devops | /sre | /swarm2');return True

_PRIME_REGRESSION_V155_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V155_PREV();extra=[]
    def add(n,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':n,'ok':ok,'detail':detail})
    add('v155-init',lambda:(_v155_init() is None))
    add('v155-db-readonly-select',lambda:_dbhands_safe_sql('SELECT * FROM x')[0])
    add('v155-db-block-write',lambda:not _dbhands_safe_sql('DELETE FROM x')[0])
    add('v155-db-block-multistmt',lambda:not _dbhands_safe_sql('SELECT 1; DROP TABLE x')[0])
    add('v155-db-secret-redaction',lambda:_dbhands_redact(['api_token'],['abc'])[0]=='[REDACTED]')
    add('v155-git-readonly-allowlist',lambda:_git_ro('/tmp',['push']).get('ok') is False)
    add('v155-devops-no-deploy',lambda:'NOT_PERFORMED' in devops_review_plan.__code__.co_consts)
    add('v155-sre-protected-services',lambda:sre_register_service('sshd').get('ok') is False)
    add('v155-sre-approval',lambda:callable(sre_restart_request) and callable(sre_approve))
    add('v155-swarm-roles',lambda:len(_SWARM2_ROLES)==5)
    add('v155-swarm-no-tool-exec',lambda:'subprocess' not in swarm2_run.__code__.co_names and 'fyers_place' not in swarm2_run.__code__.co_names)
    add('v155-owner-gate',lambda:callable(_v155_owner))
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x['ok']);r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r


