def _v156_init():
    _v155_init()
    with sqlite3.connect(_PRIME_DB,timeout=20) as c:
        c.executescript("""
        CREATE TABLE IF NOT EXISTS prime_world_watches(id TEXT PRIMARY KEY,created REAL,updated REAL,topic TEXT,query TEXT,enabled INTEGER DEFAULT 1,last_scan REAL DEFAULT 0,last_error TEXT DEFAULT '');
        CREATE TABLE IF NOT EXISTS prime_world_events(id TEXT PRIMARY KEY,ts REAL,watch_id TEXT,source TEXT,title TEXT,url TEXT,event_date TEXT,score REAL,fingerprint TEXT UNIQUE,snippet TEXT);
        CREATE TABLE IF NOT EXISTS prime_ops_decisions(id TEXT PRIMARY KEY,ts REAL,objective TEXT,context_json TEXT,plan TEXT,status TEXT DEFAULT 'OPEN');
        CREATE TABLE IF NOT EXISTS prime_simulations(id TEXT PRIMARY KEY,ts REAL,question TEXT,assumptions_json TEXT,result TEXT);
        CREATE TABLE IF NOT EXISTS prime_missions(id TEXT PRIMARY KEY,created REAL,updated REAL,title TEXT,objective TEXT,horizon_days INTEGER,status TEXT DEFAULT 'ACTIVE',progress REAL DEFAULT 0,next_review REAL,last_review TEXT DEFAULT '');
        CREATE TABLE IF NOT EXISTS prime_mission_steps(id TEXT PRIMARY KEY,mission_id TEXT,created REAL,due REAL,title TEXT,status TEXT DEFAULT 'TODO',evidence TEXT DEFAULT '',weight REAL DEFAULT 1);
        """)

def _v156_owner(cid):
    try:return bool(_v155_owner(cid))
    except Exception:return cid==OWNER.get('id')

def world_watch_add(topic,query=''):
    _v156_init();topic=str(topic or '').strip()[:160];query=str(query or topic).strip()[:500]
    if not topic:return {'ok':False,'error':'topic required'}
    wid=_prime_id('WATCH');now=time.time()
    with sqlite3.connect(_PRIME_DB) as c:c.execute('INSERT INTO prime_world_watches(id,created,updated,topic,query) VALUES(?,?,?,?,?)',(wid,now,now,topic,query))
    return {'ok':True,'watch_id':wid,'topic':topic,'query':query}

def world_watch_list():
    _v156_init()
    with sqlite3.connect(_PRIME_DB) as c:
        c.row_factory=sqlite3.Row
        return [dict(x) for x in c.execute('SELECT * FROM prime_world_watches ORDER BY updated DESC LIMIT 30')]

def world_scan(watch_id='',topic=''):
    _v156_init();q=str(topic or '').strip();wid=str(watch_id or '').strip()
    if wid:
        with sqlite3.connect(_PRIME_DB) as c:
            c.row_factory=sqlite3.Row;r=c.execute('SELECT * FROM prime_world_watches WHERE id=?',(wid,)).fetchone()
        if not r:return {'ok':False,'error':'watch not found'}
        q=r['query'];topic=r['topic']
    if not q:return {'ok':False,'error':'topic/query required'}
    try:rows,health=omni_search(q,True,4)
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)[:300]}
    items=[x for x in rows if x.get('kind') in ('news','institutional','tech','scholarly')][:20];added=0
    with sqlite3.connect(_PRIME_DB) as c:
        for x in items:
            fp=hashlib.sha256(((x.get('url') or '')+'|'+(x.get('title') or '')).encode()).hexdigest()
            try:
                c.execute('INSERT INTO prime_world_events VALUES(?,?,?,?,?,?,?,?,?,?)',(_prime_id('WEV'),time.time(),wid,x.get('source',''),x.get('title','')[:500],x.get('url','')[:1500],x.get('date','')[:100],float(x.get('score') or 0),fp,x.get('snippet','')[:2000]));added+=1
            except sqlite3.IntegrityError:pass
        if wid:c.execute('UPDATE prime_world_watches SET last_scan=?,updated=?,last_error="" WHERE id=?',(time.time(),time.time(),wid))
    return {'ok':True,'topic':topic or q,'new_events':added,'items':items[:10],'source_health':health}

def personal_ops_brief(objective=''):
    _v156_init();snap=prime_context_snapshot(24);tasks=prime_task_list(15);objective=str(objective or 'Prioritize my current open commitments and next actions').strip()
    ctx={'entities':snap.get('entities',[])[:16],'events':snap.get('events',[])[:10],'tasks':tasks[:12]}
    prompt="You are Nemo Personal Operations Chief of Staff. Use ONLY supplied context. Separate facts from inference. Rank priorities by urgency, impact, dependency and reversibility. Do not invent private facts. Give TOP PRIORITIES, CONFLICTS/RISKS, NEXT 3 ACTIONS, DEFER/IGNORE.\nOBJECTIVE: "+objective+"\nCONTEXT:\n"+json.dumps(ctx,ensure_ascii=False)[:14000]
    ans=ask_ai(OWNER.get('id'),prompt,remember=False,timeout=180,long_output=True) or 'No synthesis returned.'
    did=_prime_id('OPS')
    with sqlite3.connect(_PRIME_DB) as c:c.execute('INSERT INTO prime_ops_decisions(id,ts,objective,context_json,plan) VALUES(?,?,?,?,?)',(did,time.time(),objective,json.dumps(ctx,ensure_ascii=False),str(ans)[:12000]))
    return {'ok':True,'decision_id':did,'brief':ans}

def simulate_decision(question,assumptions=None):
    _v156_init();question=str(question or '').strip();assumptions=assumptions or {}
    if not question:return {'ok':False,'error':'question required'}
    prompt="You are Nemo Simulation Engine. Decision support, not prophecy. Build 4 scenarios: BASE, UPSIDE, DOWNSIDE, TAIL-RISK. For each: assumptions, causal chain, leading indicators, consequences, reversibility, mitigation. Give robust actions across scenarios. Quantify only when inputs justify it; otherwise label uncertainty. Never execute actions.\nQUESTION: "+question+"\nASSUMPTIONS: "+json.dumps(assumptions,ensure_ascii=False)
    ans=ask_ai(OWNER.get('id'),prompt,remember=False,timeout=220,long_output=True) or 'No simulation returned.'
    sid=_prime_id('SIM')
    with sqlite3.connect(_PRIME_DB) as c:c.execute('INSERT INTO prime_simulations VALUES(?,?,?,?,?)',(sid,time.time(),question,json.dumps(assumptions,ensure_ascii=False),str(ans)[:16000]))
    return {'ok':True,'simulation_id':sid,'result':ans,'note':'scenario analysis, not prediction'}

def mission_create(title,objective,horizon_days=90):
    _v156_init();title=str(title or '').strip()[:180];objective=str(objective or '').strip()[:3000]
    try:h=max(1,min(3650,int(horizon_days)))
    except Exception:h=90
    if not title or not objective:return {'ok':False,'error':'title and objective required'}
    mid=_prime_id('MISSION');now=time.time()
    with sqlite3.connect(_PRIME_DB) as c:c.execute('INSERT INTO prime_missions(id,created,updated,title,objective,horizon_days,next_review) VALUES(?,?,?,?,?,?,?)',(mid,now,now,title,objective,h,now+7*86400))
    return {'ok':True,'mission_id':mid,'title':title,'horizon_days':h}

def mission_add_step(mid,title,due_days=7,weight=1):
    _v156_init()
    with sqlite3.connect(_PRIME_DB) as c:
        if not c.execute('SELECT 1 FROM prime_missions WHERE id=?',(mid,)).fetchone():return {'ok':False,'error':'mission not found'}
        sid=_prime_id('STEP');c.execute('INSERT INTO prime_mission_steps(id,mission_id,created,due,title,weight) VALUES(?,?,?,?,?,?)',(sid,mid,time.time(),time.time()+max(0,int(due_days))*86400,str(title)[:500],float(weight)))
    return {'ok':True,'step_id':sid}

def mission_status(mid=''):
    _v156_init()
    with sqlite3.connect(_PRIME_DB) as c:
        c.row_factory=sqlite3.Row
        if mid:
            m=c.execute('SELECT * FROM prime_missions WHERE id=?',(mid,)).fetchone();steps=c.execute('SELECT * FROM prime_mission_steps WHERE mission_id=? ORDER BY due',(mid,)).fetchall()
            return {'ok':bool(m),'mission':dict(m) if m else None,'steps':[dict(x) for x in steps]}
        return {'ok':True,'missions':[dict(x) for x in c.execute("SELECT * FROM prime_missions WHERE status!='ARCHIVED' ORDER BY updated DESC LIMIT 20")]}

def mission_review(mid):
    d=mission_status(mid)
    if not d.get('ok'):return {'ok':False,'error':'mission not found'}
    m=d['mission'];steps=d['steps'];done=sum(float(x.get('weight') or 1) for x in steps if x.get('status')=='DONE');total=sum(float(x.get('weight') or 1) for x in steps) or 1;progress=round(100*done/total,1)
    prompt="Review this long-horizon mission. Diagnose progress, bottlenecks, stale assumptions, dependencies and next best milestone. Do not execute anything. Preserve human approval for consequential actions.\n"+json.dumps({'mission':m,'steps':steps},ensure_ascii=False)[:14000]
    ans=ask_ai(OWNER.get('id'),prompt,remember=False,timeout=180,long_output=True) or 'No review returned.'
    with sqlite3.connect(_PRIME_DB) as c:c.execute('UPDATE prime_missions SET updated=?,progress=?,next_review=?,last_review=? WHERE id=?',(time.time(),progress,time.time()+7*86400,str(ans)[:10000],mid))
    return {'ok':True,'mission_id':mid,'progress':progress,'review':ans}

def _v156_dispatch(cid,text,msg=None):
    raw=str(text or '').strip();low=raw.lower()
    if not any(low.startswith(x) for x in ('/batch6','/world','/ops2','/simulate','/mission')):return False
    if not _v156_owner(cid):send_text(cid,'Owner-only.');return True
    if low=='/batch6':send_text(cid,'🌍 NEMO v15.6 — WORLD & MISSION INTELLIGENCE\n\n🌐 World Monitor/Event Radar\n🧭 Personal Operations Graph 2.0\n🧪 Simulation Engine\n🎯 Long-Horizon Mission Engine\n\nNo autonomous financial/security/physical execution authority added.');return True
    if low=='/world':send_text(cid,'🌐 WORLD MONITOR\n/world add <topic> | <query>\n/world scan <WATCH-id>\n/world now <topic>\n/world list');return True
    if low=='/world list':send_text(cid,json.dumps(world_watch_list(),ensure_ascii=False,indent=2)[:3900]);return True
    m=re.match(r'^/world\s+add\s+([^|]+)(?:\|(.+))?$',raw,re.I)
    if m:send_text(cid,json.dumps(world_watch_add(m.group(1).strip(),(m.group(2) or '').strip()),ensure_ascii=False,indent=2));return True
    m=re.match(r'^/world\s+scan\s+(WATCH-[A-Za-z0-9-]+)$',raw,re.I)
    if m:send_text(cid,json.dumps(world_scan(m.group(1)),ensure_ascii=False,indent=2)[:3900]);return True
    if low.startswith('/world now '):send_text(cid,json.dumps(world_scan(topic=raw.split(None,2)[2]),ensure_ascii=False,indent=2)[:3900]);return True
    if low=='/ops2':send_text(cid,'🧭 PERSONAL OPS 2.0\n/ops2 brief [objective]');return True
    if low.startswith('/ops2 brief'):
        obj=raw[len('/ops2 brief'):].strip();send_text(cid,'🧭 Building context-grounded operations brief…')
        def _go():
            d=personal_ops_brief(obj);send_text(cid,str(d.get('brief') or d.get('error'))[:12000])
        threading.Thread(target=_go,daemon=True,name='nemo-ops2').start();return True
    if low=='/simulate':send_text(cid,'🧪 SIMULATION ENGINE\n/simulate <decision/question>\nScenario analysis only — not prediction.');return True
    if low.startswith('/simulate '):
        q=raw.split(None,1)[1];send_text(cid,'🧪 Running base/upside/downside/tail-risk simulation…')
        def _sim():
            d=simulate_decision(q);send_text(cid,str(d.get('result') or d.get('error'))[:12000])
        threading.Thread(target=_sim,daemon=True,name='nemo-simulation').start();return True
    if low=='/mission':send_text(cid,'🎯 MISSION ENGINE\n/mission create <title> | <objective> | <days>\n/mission step <MISSION-id> | <step> | <due-days>\n/mission status [MISSION-id]\n/mission review <MISSION-id>');return True
    m=re.match(r'^/mission\s+create\s+([^|]+)\|([^|]+)(?:\|(\d+))?$',raw,re.I)
    if m:send_text(cid,json.dumps(mission_create(m.group(1).strip(),m.group(2).strip(),int(m.group(3) or 90)),ensure_ascii=False,indent=2));return True
    m=re.match(r'^/mission\s+step\s+(MISSION-[A-Za-z0-9-]+)\s*\|\s*([^|]+)(?:\|(\d+))?$',raw,re.I)
    if m:send_text(cid,json.dumps(mission_add_step(m.group(1),m.group(2).strip(),int(m.group(3) or 7)),indent=2));return True
    m=re.match(r'^/mission\s+status(?:\s+(MISSION-[A-Za-z0-9-]+))?$',raw,re.I)
    if m:send_text(cid,json.dumps(mission_status(m.group(1) or ''),ensure_ascii=False,indent=2)[:3900]);return True
    m=re.match(r'^/mission\s+review\s+(MISSION-[A-Za-z0-9-]+)$',raw,re.I)
    if m:
        mid=m.group(1);send_text(cid,'🎯 Reviewing mission…')
        def _rev():
            d=mission_review(mid);send_text(cid,str(d.get('review') or d.get('error'))[:12000])
        threading.Thread(target=_rev,daemon=True,name='nemo-mission-review').start();return True
    send_text(cid,'Use /batch6 | /world | /ops2 | /simulate | /mission');return True

_PRIME_REGRESSION_V156_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V156_PREV();extra=[]
    def add(n,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':n,'ok':ok,'detail':detail})
    add('v156-init',lambda:(_v156_init() is None))
    add('v156-world-watch',lambda:callable(world_watch_add) and callable(world_scan))
    add('v156-world-dedupe',lambda:'fingerprint TEXT UNIQUE' in str(_v156_init.__code__.co_consts))
    add('v156-context-grounded-ops',lambda:'prime_context_snapshot' in personal_ops_brief.__code__.co_names)
    add('v156-simulation-four-scenarios',lambda:'BASE, UPSIDE, DOWNSIDE, TAIL-RISK' in str(simulate_decision.__code__.co_consts))
    add('v156-simulation-no-exec',lambda:'subprocess' not in simulate_decision.__code__.co_names and 'fyers_place' not in simulate_decision.__code__.co_names)
    add('v156-mission-engine',lambda:all(callable(globals().get(x)) for x in ('mission_create','mission_add_step','mission_status','mission_review')))
    add('v156-owner-gate',lambda:callable(_v156_owner))
    add('v156-no-order-path',lambda:'place_order' not in _v156_dispatch.__code__.co_names and 'fyers_place' not in _v156_dispatch.__code__.co_names)
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x['ok']);r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

