def _v157_init():
    try:
        _v156_init()
    except Exception:
        try:_prime_init()
        except Exception:pass
    with sqlite3.connect(_PRIME_DB) as c:
        c.execute("""CREATE TABLE IF NOT EXISTS prime_capability_scout(
            id TEXT PRIMARY KEY, ts REAL, topic TEXT, query TEXT, source TEXT,
            title TEXT, url TEXT, score REAL DEFAULT 0, rationale TEXT DEFAULT '',
            status TEXT DEFAULT 'DISCOVERED', payload TEXT DEFAULT ''
        )""")
        c.execute("""CREATE TABLE IF NOT EXISTS prime_digital_twin_snapshots(
            id TEXT PRIMARY KEY, ts REAL, objective TEXT, facts_json TEXT,
            assumptions_json TEXT, model TEXT, confidence REAL DEFAULT 0
        )""")
        c.execute("""CREATE TABLE IF NOT EXISTS prime_failure_replays(
            id TEXT PRIMARY KEY, ts REAL, source_table TEXT, source_id TEXT,
            failure_class TEXT, evidence_json TEXT, diagnosis TEXT,
            prevention TEXT, status TEXT DEFAULT 'ANALYZED'
        )""")
        c.execute("""CREATE TABLE IF NOT EXISTS prime_evolution3_experiments(
            id TEXT PRIMARY KEY, created REAL, updated REAL, title TEXT,
            hypothesis TEXT, evidence_json TEXT, experiment_plan TEXT,
            success_metric TEXT, risk_level TEXT DEFAULT 'LOW',
            status TEXT DEFAULT 'PROPOSED', result TEXT DEFAULT ''
        )""")
        c.execute("""CREATE INDEX IF NOT EXISTS idx_v157_scout_ts ON prime_capability_scout(ts DESC)""")
        c.execute("""CREATE INDEX IF NOT EXISTS idx_v157_replay_ts ON prime_failure_replays(ts DESC)""")
        c.execute("""CREATE INDEX IF NOT EXISTS idx_v157_evo_ts ON prime_evolution3_experiments(created DESC)""")

def _v157_owner(cid):
    try:
        oid = OWNER.get('id') if isinstance(OWNER, dict) else OWNER
        return str(cid) == str(oid)
    except Exception:
        return False

def _v157_j(obj, limit=14000):
    try:return json.dumps(obj, ensure_ascii=False, indent=2)[:limit]
    except Exception:return str(obj)[:limit]

def _v157_table_exists(c, name):
    try:return bool(c.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",(name,)).fetchone())
    except Exception:return False

def capability_scout(topic, query=''):
    """Research capability candidates. Discovery only; never installs or executes anything."""
    _v157_init()
    topic=str(topic or '').strip()
    query=str(query or topic).strip()
    if not topic:
        return {'ok':False,'error':'topic required'}
    try:
        rows, health = omni_search(query, True, 5)
    except Exception as e:
        return {'ok':False,'error':type(e).__name__+': '+str(e)[:300]}
    picked=[]
    for x in (rows or [])[:30]:
        url=str(x.get('url') or '')
        title=str(x.get('title') or '')
        source=str(x.get('source') or '')
        snippet=str(x.get('snippet') or '')
        base=float(x.get('score') or 0)
        authority=0.0
        low=url.lower()
        if any(d in low for d in ('github.com','docs.python.org','pypi.org','npmjs.com','kubernetes.io','docker.com','postgresql.org','sqlite.org','apache.org')):
            authority += 0.25
        if source.lower() in ('institutional','tech','scholarly'):
            authority += 0.10
        score=min(1.0, max(0.0, base if base <= 1 else base/100.0) + authority)
        rationale=(snippet[:500] if snippet else 'Potential capability source; requires manual review.')
        cid=_prime_id('CAP')
        payload={'kind':x.get('kind'),'date':x.get('date'),'snippet':snippet[:1200]}
        with sqlite3.connect(_PRIME_DB) as c:
            c.execute("""INSERT OR REPLACE INTO prime_capability_scout
                (id,ts,topic,query,source,title,url,score,rationale,status,payload)
                VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                (cid,time.time(),topic,query,source,title[:500],url[:1500],score,rationale,'DISCOVERED',json.dumps(payload,ensure_ascii=False)))
        picked.append({'id':cid,'title':title[:180],'source':source,'url':url,'score':round(score,3),'why':rationale[:260]})
    picked=sorted(picked,key=lambda z:z.get('score',0),reverse=True)[:12]
    return {'ok':True,'topic':topic,'query':query,'candidates':picked,'source_health':health,
            'policy':'Discovery only. No package install, code execution, credential use, or production mutation.'}

