def _v157_collect_failures(limit=12):
    """Best-effort failure harvesting across known Nemo telemetry tables."""
    _v157_init()
    out=[]
    candidates=[
        ('prime_learning_errors',['id','ts','error','context']),
        ('prime_provider_health',['id','ts','provider','status','detail']),
        ('prime_requests',['id','ts','status','error','request']),
        ('prime_guardian_events',['id','ts','event','detail']),
        ('prime_evolution_backlog',['id','created','title','evidence'])
    ]
    with sqlite3.connect(_PRIME_DB) as c:
        c.row_factory=sqlite3.Row
        for table,cols in candidates:
            if not _v157_table_exists(c,table):continue
            try:
                info=[x[1] for x in c.execute("PRAGMA table_info("+table+")").fetchall()]
                pick=[x for x in cols if x in info]
                if not pick:continue
                order='ts' if 'ts' in info else ('created' if 'created' in info else 'rowid')
                q="SELECT "+",".join(pick)+" FROM "+table+" ORDER BY "+order+" DESC LIMIT ?"
                for r in c.execute(q,(limit,)).fetchall():
                    d=dict(r);d['_table']=table;out.append(d)
            except Exception:
                pass
    return out[:max(1,limit)]

def failure_replay(source_id=''):
    """Reconstructs a failure from stored telemetry. Analysis only; no replay against production."""
    _v157_init()
    events=_v157_collect_failures(20)
    if source_id:
        events=[e for e in events if str(e.get('id',''))==str(source_id)] or events
    if not events:
        return {'ok':False,'error':'no replayable telemetry found'}
    ev=events[0]
    rid=_prime_id('REPLAY')
    evidence=json.dumps(ev,ensure_ascii=False)[:12000]
    prompt=(
        "You are Nemo Failure Replay Laboratory. Reconstruct the likely failure sequence using ONLY the supplied telemetry. "
        "Distinguish observed evidence from hypotheses. Produce: TIMELINE, ROOT-CAUSE CANDIDATES, CONTRIBUTING CONDITIONS, "
        "WHAT WOULD FALSIFY EACH HYPOTHESIS, SAFE REPRODUCTION PLAN IN AN ISOLATED LAB, PREVENTION TESTS, and ROLLBACK CHECKS. "
        "Never execute commands, never touch production, never expose secrets.\nTELEMETRY:\n"+evidence
    )
    ans=ask_ai(OWNER.get('id'),prompt,remember=False,timeout=220,long_output=True) or 'No replay analysis returned.'
    with sqlite3.connect(_PRIME_DB) as c:
        c.execute("""INSERT INTO prime_failure_replays
            (id,ts,source_table,source_id,failure_class,evidence_json,diagnosis,prevention,status)
            VALUES(?,?,?,?,?,?,?,?,?)""",
            (rid,time.time(),str(ev.get('_table','')),str(ev.get('id','')),
             'TELEMETRY_FAILURE',evidence,str(ans)[:16000],'See diagnosis/prevention plan','ANALYZED'))
    return {'ok':True,'replay_id':rid,'source':ev.get('_table'),'source_id':ev.get('id'),'analysis':ans,
            'policy':'Lab analysis only; production replay is not automatic.'}

