def _v157_dispatch(cid,text,msg=None):
    raw=str(text or '').strip(); low=raw.lower()
    prefixes=('/batch7','/scout','/twin','/replay','/evolve3')
    if not any(low.startswith(x) for x in prefixes):return False
    if not _v157_owner(cid):
        send_text(cid,'Owner-only.')
        return True
    if low=='/batch7':
        send_text(cid,
            "🧬 NEMO v15.7 — ADVANCED EVOLUTION BATCH 5\n\n"
            "🔎 Capability / Open-Source Scout\n"
            "🪞 Explainable Digital Twin\n"
            "🧯 Failure Replay Laboratory\n"
            "🧪 Scientific Self-Evolution 3.0\n\n"
            "Discovery, modeling and experiments are isolated from production authority.")
        return True
    if low=='/scout':
        send_text(cid,"🔎 CAPABILITY SCOUT\n/scout <topic> | [query]\n/scout list")
        return True
    if low=='/scout list':
        send_text(cid,_v157_j(capability_scout_list(),12000));return True
    m=re.match(r'^/scout\s+([^|]+)(?:\|(.+))?$',raw,re.I)
    if m:
        topic=m.group(1).strip();q=(m.group(2) or '').strip()
        send_text(cid,'🔎 Scouting sources and capability candidates…')
        def _go():
            d=capability_scout(topic,q)
            if not d.get('ok'):send_text(cid,'Scout failed: '+str(d.get('error')));return
            lines=["🔎 CAPABILITY SCOUT | "+d.get('topic',''),"━━━━━━━━━━━━━━━━━━━━"]
            for i,x in enumerate(d.get('candidates',[])[:8],1):
                lines.append(f"{i}. {x.get('title') or 'Untitled'}\n   Source: {x.get('source') or 'unknown'} | Score: {x.get('score')}\n   {x.get('url') or ''}")
            lines.append("\n⚠️ Discovery only — nothing installed or executed.")
            send_text(cid,"\n".join(lines)[:12000])
        threading.Thread(target=_go,daemon=True,name='nemo-capability-scout').start();return True
    if low=='/twin':
        send_text(cid,"🪞 DIGITAL TWIN\n/twin build [objective]\n/twin latest\nExplainable operational model only; not a behavioral clone.")
        return True
    if low=='/twin latest':
        d=digital_twin_latest();send_text(cid,str((d.get('snapshot') or {}).get('model') or d.get('snapshot') or 'No twin snapshot yet.')[:12000]);return True
    if low.startswith('/twin build'):
        obj=raw[len('/twin build'):].strip()
        send_text(cid,'🪞 Building explainable operational twin…')
        def _tw():
            d=digital_twin_build(obj);send_text(cid,str(d.get('model') or d.get('error'))[:12000])
        threading.Thread(target=_tw,daemon=True,name='nemo-digital-twin').start();return True
    if low=='/replay':
        send_text(cid,"🧯 FAILURE REPLAY LAB\n/replay latest\n/replay <source-id>\n/replay list\nAnalysis runs against stored telemetry only.")
        return True
    if low=='/replay list':
        send_text(cid,_v157_j(failure_replay_list(),12000));return True
    if low=='/replay latest' or low.startswith('/replay '):
        sid='' if low=='/replay latest' else raw.split(None,1)[1].strip()
        send_text(cid,'🧯 Reconstructing failure from stored evidence…')
        def _rp():
            d=failure_replay(sid);send_text(cid,str(d.get('analysis') or d.get('error'))[:12000])
        threading.Thread(target=_rp,daemon=True,name='nemo-failure-replay').start();return True
    if low=='/evolve3':
        send_text(cid,"🧪 SCIENTIFIC SELF-EVOLUTION 3.0\n/evolve3 propose [goal]\n/evolve3 list\n/evolve3 mark <EXP3-id> <PASS|FAIL|REJECTED|ROLLED_BACK> | [result]\nNo silent production rewrite.")
        return True
    if low=='/evolve3 list':
        send_text(cid,_v157_j(evolution3_list(),12000));return True
    if low.startswith('/evolve3 propose'):
        goal=raw[len('/evolve3 propose'):].strip()
        send_text(cid,'🧪 Designing falsifiable isolated experiment…')
        def _ev():
            d=evolution3_propose(goal);send_text(cid,str(d.get('plan') or d.get('error'))[:12000])
        threading.Thread(target=_ev,daemon=True,name='nemo-evolution3').start();return True
    m=re.match(r'^/evolve3\s+mark\s+(EXP3-[A-Za-z0-9-]+)\s+(PROPOSED|RUNNING|PASS|FAIL|REJECTED|ROLLED_BACK)(?:\s*\|\s*(.*))?$',raw,re.I)
    if m:
        send_text(cid,_v157_j(evolution3_mark(m.group(1),m.group(2),m.group(3) or ''),6000));return True
    send_text(cid,'Use /batch7 | /scout | /twin | /replay | /evolve3')
    return True

# Regression extension
_PRIME_REGRESSION_V157_PREV = prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V157_PREV(); extra=[]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v157-init',lambda:(_v157_init() is None))
    add('v157-scout-discovery-only',lambda:'subprocess' not in capability_scout.__code__.co_names and 'pip' not in capability_scout.__code__.co_names)
    add('v157-scout-persistence',lambda:'prime_capability_scout' in str(_v157_init.__code__.co_consts))
    add('v157-twin-explainable',lambda:'EXPLAINABLE' in str(digital_twin_build.__code__.co_consts))
    add('v157-twin-no-sensitive-inference',lambda:'sensitive traits' in str(digital_twin_build.__code__.co_consts))
    add('v157-replay-no-production-exec',lambda:'subprocess' not in failure_replay.__code__.co_names and 'os.system' not in failure_replay.__code__.co_names)
    add('v157-evolution-falsifiable',lambda:'falsifiable' in str(evolution3_propose.__code__.co_consts))
    add('v157-evolution-no-prod-rewrite',lambda:'production' in str(evolution3_propose.__code__.co_consts))
    add('v157-owner-gate',lambda:callable(_v157_owner))
    add('v157-no-order-path',lambda:'place_order' not in _v157_dispatch.__code__.co_names and 'fyers_place' not in _v157_dispatch.__code__.co_names)
    r['tests'].extend(extra)
    r['passed']=sum(1 for x in r['tests'] if x.get('ok'))
    r['failed']=len(r['tests'])-r['passed']
    r['verdict']='PASS' if not r['failed'] else 'FAIL'
    r['version']=VERSION
    return r

# IMPORTANT: repair v15.6 wrapper-order regression.
# In v15.6, a later v15.5 handle wrapper shadowed the v15.6 wrapper.
# v15.7 explicitly exposes both new layers before falling through to the existing chain.
_HANDLE_V157_BASE = handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id')
        txt=msg.get('text') or msg.get('caption') or ''
        if _v157_dispatch(cid,txt,msg):return
        if _v156_dispatch(cid,txt,msg):return
    except Exception as e:
        try:print('v15.7 dispatch:',type(e).__name__,str(e)[:180])
        except Exception:pass
    return _HANDLE_V157_BASE(msg)

_MAIN_V157_PREV = main
