# ---- Goal Completion Engine ------------------------------------------------
def goal2_create(objective,priority=50,owner=''):
    gid='GOAL2-'+_v160_uuid.uuid4().hex[:10].upper();now=_v160_time.time();c=_v160_conn()
    c.execute('INSERT INTO prime_goals2(id,created,updated,objective,state,owner,priority) VALUES(?,?,?,?,?,?,?)',
              (gid,now,now,str(objective),'NEW',str(owner or ''),max(0,min(100,int(priority)))))
    c.commit();c.close();return gid


def goal2_plan(goal_id):
    c=_v160_conn();r=c.execute('SELECT * FROM prime_goals2 WHERE id=?',(str(goal_id),)).fetchone();c.close()
    if not r:return {'ok':False,'error':'goal not found'}
    objective=r['objective'];caps=capability_list(200)
    cap_summary=[{'name':x['name'],'risk':x['risk'],'health':x['health'],'description':x['description']} for x in caps]
    prompt=("You are Nemo's goal planner. Build a concise execution plan for the owner's objective. "
            "Use ONLY capabilities that exist in CAPABILITIES. Each step needs title, capability, risk, requires_approval, success_check. "
            "Never invent a capability. High-impact external/financial/physical/security actions require approval. "
            "Return JSON array only.\nOBJECTIVE: "+str(objective)+"\nCAPABILITIES:\n"+_v160_j(cap_summary,9000))
    try:raw=ask_ai(0,prompt,remember=False,timeout=120,raw=True)
    except TypeError:
        try:raw=ask_ai(0,prompt,remember=False,timeout=120)
        except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)}
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)}
    txt=str(raw or '').strip();m=_v160_re.search(r'\[[\s\S]*\]',txt)
    try:plan=_v160_json.loads(m.group(0) if m else txt)
    except Exception:
        # deterministic safe fallback: planning only
        plan=[{'title':'Clarify objective and constraints','capability':'owner_state','risk':'READ_ONLY','requires_approval':False,'success_check':'requirements captured'},
              {'title':'Identify available healthy capabilities','capability':'capability_registry','risk':'READ_ONLY','requires_approval':False,'success_check':'dependencies known'},
              {'title':'Execute task-specific workflow','capability':'goal_completion','risk':'LOCAL_WRITE','requires_approval':False,'success_check':'objective verified'}]
    if not isinstance(plan,list):plan=[]
    known={x['name']:x for x in caps};clean=[]
    for i,x in enumerate(plan[:20],1):
        if not isinstance(x,dict):continue
        cap=str(x.get('capability') or '')
        if cap not in known:cap='goal_completion'
        risk=str(known.get(cap,{}).get('risk') or x.get('risk') or 'READ_ONLY').upper()
        approval=bool(x.get('requires_approval')) or risk in ('EXTERNAL_WRITE','FINANCIAL','PHYSICAL_DEVICE','SECURITY_SENSITIVE')
        clean.append({'seq':i,'title':str(x.get('title') or ('Step '+str(i)))[:500],'capability':cap,'risk':risk,'requires_approval':approval,'success_check':str(x.get('success_check') or '')[:800]})
    c=_v160_conn();now=_v160_time.time();c.execute('DELETE FROM prime_goal_steps2 WHERE goal_id=?',(str(goal_id),))
    for x in clean:
        sid='GST-'+_v160_uuid.uuid4().hex[:10].upper();c.execute('INSERT INTO prime_goal_steps2(id,goal_id,seq,title,capability,state,risk,requires_approval,updated) VALUES(?,?,?,?,?,?,?,?,?)',
          (sid,str(goal_id),x['seq'],x['title'],x['capability'],'PENDING',x['risk'],1 if x['requires_approval'] else 0,now))
    c.execute('UPDATE prime_goals2 SET state="PLANNED",plan_json=?,updated=? WHERE id=?',(_v160_json.dumps(clean,ensure_ascii=False),now,str(goal_id)));c.commit();c.close()
    return {'ok':True,'goal_id':goal_id,'objective':objective,'plan':clean,'execution':'NOT_PERFORMED'}


def goal2_status(goal_id=''):
    c=_v160_conn()
    if goal_id:
        g=c.execute('SELECT * FROM prime_goals2 WHERE id=?',(str(goal_id),)).fetchone();steps=c.execute('SELECT * FROM prime_goal_steps2 WHERE goal_id=? ORDER BY seq',(str(goal_id),)).fetchall();c.close()
        return {'goal':dict(g) if g else None,'steps':[dict(x) for x in steps]}
    rows=c.execute('SELECT * FROM prime_goals2 ORDER BY priority DESC,updated DESC LIMIT 20').fetchall();c.close();return [dict(x) for x in rows]


# ---- Recovery Planner ------------------------------------------------------
def recovery_plan(failure,evidence='',goal_id=''):
    fid='REC-'+_v160_uuid.uuid4().hex[:10].upper();caps=capability_list(200)
    prompt=("You are Nemo Recovery Planner. Diagnose the failure and produce a SAFE alternate-path plan. "
            "Order: classify -> likely causes -> cheap verification -> retry/failover -> graceful degradation -> human escalation. "
            "Never fabricate success and never expand authority. Return JSON object with failure_class, likely_causes, checks, alternatives, stop_conditions.\n"
            "FAILURE: "+str(failure)+"\nEVIDENCE: "+str(evidence)[:6000]+"\nCAPABILITIES: "+_v160_j([{'name':x['name'],'health':x['health'],'risk':x['risk']} for x in caps],5000))
    try:raw=ask_ai(0,prompt,remember=False,timeout=120,raw=True)
    except TypeError:
        try:raw=ask_ai(0,prompt,remember=False,timeout=120)
        except Exception as e:raw=''
    except Exception:raw=''
    txt=str(raw or '').strip();m=_v160_re.search(r'\{[\s\S]*\}',txt)
    try:plan=_v160_json.loads(m.group(0) if m else txt)
    except Exception:plan={'failure_class':'UNKNOWN','likely_causes':['insufficient diagnostic evidence'],'checks':['inspect exact error and dependency health'],'alternatives':['retry once if transient','use a healthy alternate provider if available','degrade gracefully'],'stop_conditions':['do not claim completion without verification']}
    c=_v160_conn();c.execute('INSERT INTO prime_recovery_plans(id,ts,goal_id,failure_class,evidence,plan_json,state) VALUES(?,?,?,?,?,?,?)',
      (fid,_v160_time.time(),str(goal_id),str(plan.get('failure_class') or 'UNKNOWN'),str(evidence)[:12000],_v160_json.dumps(plan,ensure_ascii=False,default=str),'PROPOSED'));c.commit();c.close()
    return {'ok':True,'id':fid,'plan':plan,'execution':'NOT_PERFORMED'}


# ---- Conversation Continuity / Short-Utterance Resolver -------------------
def continuity_add_turn(chat_id,role,text,active_topic=''):
    c=_v160_conn();r=c.execute('SELECT * FROM prime_conversation_continuity WHERE chat_id=?',(str(chat_id),)).fetchone();turns=[]
    if r:
        try:turns=_v160_json.loads(r['turns_json'] or '[]')
        except Exception:turns=[]
    turns=(turns+[{'ts':_v160_time.time(),'role':str(role),'text':str(text)[:1200]}])[-12:]
    topic=str(active_topic or (r['active_topic'] if r else '') or '')[:500]
    c.execute('INSERT OR REPLACE INTO prime_conversation_continuity(chat_id,updated,active_topic,turns_json,unresolved_json,mode) VALUES(?,?,?,?,?,?)',
      (str(chat_id),_v160_time.time(),topic,_v160_json.dumps(turns,ensure_ascii=False),'[]',(r['mode'] if r else 'NORMAL')));c.commit();c.close();return True


def continuity_resolve(chat_id,text):
    t=str(text or '').strip();c=_v160_conn();r=c.execute('SELECT * FROM prime_conversation_continuity WHERE chat_id=?',(str(chat_id),)).fetchone();c.close()
    if not r:return {'resolved':t,'changed':False,'reason':'no active context'}
    try:turns=_v160_json.loads(r['turns_json'] or '[]')
    except Exception:turns=[]
    short=(len(t.split())<=5 or len(t)<=28)
    refs=bool(_v160_re.search(r'\b(that|this|it|same|one|wala|wali|uska|iska|wo|woh|fir|phir|aur|kal|haan|ha|yes|no|nahi)\b',t,_v160_re.I))
    if not (short or refs):return {'resolved':t,'changed':False,'reason':'self-contained'}
    context='\n'.join((str(x.get('role'))+': '+str(x.get('text'))) for x in turns[-6:])
    prompt=("Resolve the user's short/elliptical utterance using ONLY recent conversation context. "
            "Return one explicit sentence preserving intent. If context is insufficient, return the original text unchanged. "
            "Do not answer the question.\nRECENT:\n"+context+"\nACTIVE TOPIC: "+str(r['active_topic'] or '')+"\nUTTERANCE: "+t)
    try:resolved=str(ask_ai(chat_id,prompt,remember=False,timeout=45,raw=True) or '').strip()
    except TypeError:
        try:resolved=str(ask_ai(chat_id,prompt,remember=False,timeout=45) or '').strip()
        except Exception:resolved=t
    except Exception:resolved=t
    resolved=resolved.splitlines()[0][:1200] if resolved else t
    return {'resolved':resolved,'changed':resolved.strip()!=t.strip(),'reason':'contextual ellipsis resolution','original':t}


# ---- Daily Chief-of-Staff --------------------------------------------------
def daily_brief2():
    snap=owner_state_snapshot();now=_v160_time.time()
    loops=snap.get('open_loops') or [];inbox=snap.get('inbox') or [];tasks=snap.get('tasks') or []
    due=[x for x in loops if float(x.get('due') or 0)>0 and float(x.get('due'))<now+86400]
    lines=['🧭 NEMO DAILY CHIEF-OF-STAFF','━━━━━━━━━━━━━━━━━━━━']
    lines.append('\n🔔 WHAT NEEDS YOU')
    if inbox:
        for x in inbox[:5]:lines.append('• ['+str(x.get('category'))+'] '+str(x.get('title'))[:180])
    else:lines.append('• Nothing urgent in the owner inbox.')
    if due:
        lines.append('\n🔁 OPEN LOOPS')
        for x in due[:5]:lines.append('• '+str(x.get('text'))[:180])
    active=[x for x in tasks if str(x.get('status','')).upper() in ('QUEUED','RUNNING','WAITING')]
    if active:
        lines.append('\n🎯 ACTIVE WORK')
        for x in active[:5]:lines.append('• '+str(x.get('title') or x.get('goal') or x.get('task') or x.get('id'))[:180])
    if not inbox and not due and not active:lines.append('\nNo urgent owner-facing items are currently recorded.')
    lines.append('\nPrinciple: owner-facing work outranks background research/evolution.')
    return '\n'.join(lines)


# ---- v16 owner commands ----------------------------------------------------
def _v160_dispatch(cid,text,msg=None):
    raw=str(text or '').strip();low=raw.lower()
    prefixes=('/v160','/ownerstate','/inbox','/attention','/openloop','/capreg','/goal2','/recover','/brief2','/companion')
    if not any(low.startswith(x) for x in prefixes):return False
    if not _v160_owner(cid):
        send_text(cid,'Owner-only.');return True
    if low in ('/v160','/batch8'):
        send_text(cid,"🧠 NEMO v16.0 — PERSONAL AI OS FOUNDATION\n\n"
          "🧭 Unified Owner State\n📡 Event Bus + Attention Manager\n📥 Owner Inbox\n🔁 Open Loop Manager\n🎯 Goal Completion Engine\n🧩 Capability Registry + Dependencies\n🛟 Recovery Planner\n🗣 Conversation Continuity / Short-Utterance Resolver\n☀️ Daily Chief-of-Staff\n\nThis release builds executive-function infrastructure; consequential actions remain approval/policy gated.")
        return True
    if low=='/ownerstate':send_text(cid,_v160_j(owner_state_snapshot(),12000));return True
    if low.startswith('/ownerstate set '):
        body=raw[len('/ownerstate set '):];
        if '=' not in body:send_text(cid,'Usage: /ownerstate set key=value');return True
        k,v=body.split('=',1);owner_state_set(k.strip(),v.strip(),1.0,'owner');send_text(cid,'✅ Owner state updated: '+k.strip());return True
    if low=='/inbox':
        xs=owner_inbox_list('OPEN',20);send_text(cid,'📥 OWNER INBOX\n'+('\n'.join(f"• {x['id']} [{x['category']}] {x['title']}" for x in xs) if xs else 'No open items.'));return True
    m=_v160_re.match(r'^/inbox\s+(done|dismiss)\s+(\S+)$',raw,_v160_re.I)
    if m:send_text(cid,'✅ Updated.' if owner_inbox_mark(m.group(2),'DONE' if m.group(1).lower()=='done' else 'DISMISSED') else 'Item not found.');return True
    if low=='/attention':send_text(cid,'🧠 ATTENTION ENGINE\nLevels: SILENT → DIGEST → MESSAGE → SPEAK_WHEN_FREE → INTERRUPT_NOW\nUses severity, relevance, confidence, freshness, interruption cost and owner-busy state.');return True
    if low=='/openloop':
        xs=open_loop_list('OPEN',20);send_text(cid,'🔁 OPEN LOOPS\n'+('\n'.join(f"• {x['id']} [{x['kind']}] {x['text']}" for x in xs) if xs else 'None.'));return True
    if low.startswith('/openloop add '):
        oid=open_loop_add(raw[len('/openloop add '):].strip(),'FOLLOWUP',0,'owner');send_text(cid,'✅ Open loop created: '+oid);return True
    m=_v160_re.match(r'^/openloop\s+done\s+(\S+)(?:\s*\|\s*(.*))?$',raw,_v160_re.I)
    if m:send_text(cid,'✅ Closed.' if open_loop_close(m.group(1),m.group(2) or '') else 'Loop not found.');return True
    if low=='/capreg':
        xs=capability_list(100);send_text(cid,'🧩 CAPABILITY REGISTRY\n'+('\n'.join(f"• {x['name']} — {x['health']} — {x['risk']}" for x in xs) if xs else 'Empty.'));return True
    m=_v160_re.match(r'^/capreg\s+health\s+(\S+)$',raw,_v160_re.I)
    if m:send_text(cid,_v160_j(capability_health(m.group(1)),8000));return True
    if low.startswith('/goal2 create '):
        obj=raw[len('/goal2 create '):].strip();gid=goal2_create(obj,70,str(cid));send_text(cid,'🎯 Goal created: '+gid+'\nUse /goal2 plan '+gid);return True
    m=_v160_re.match(r'^/goal2\s+plan\s+(\S+)$',raw,_v160_re.I)
    if m:
        send_text(cid,'🧠 Planning goal…')
        def _gp():send_text(cid,_v160_j(goal2_plan(m.group(1)),12000))
        threading.Thread(target=_gp,daemon=True,name='nemo-goal2-plan').start();return True
    if low=='/goal2':send_text(cid,_v160_j(goal2_status(''),12000));return True
    m=_v160_re.match(r'^/goal2\s+(status)\s+(\S+)$',raw,_v160_re.I)
    if m:send_text(cid,_v160_j(goal2_status(m.group(2)),12000));return True
    if low.startswith('/recover '):
        failure=raw[len('/recover '):].strip();send_text(cid,'🛟 Building recovery plan…')
        def _rp():send_text(cid,_v160_j(recovery_plan(failure),12000))
        threading.Thread(target=_rp,daemon=True,name='nemo-recovery-plan').start();return True
    if low=='/brief2':send_text(cid,daily_brief2());return True
    if low=='/companion':send_text(cid,'🗣 CONVERSATION CONTINUITY\nTracks active topic and recent turns for short phrases like “wo wala”, “same”, “aur?”, “uska kya?”.\nUse /companion resolve <short phrase> for diagnostics.');return True
    if low.startswith('/companion resolve '):send_text(cid,_v160_j(continuity_resolve(cid,raw[len('/companion resolve '):]),8000));return True
    return False


# Regression extension: architecture/safety invariants, not claims of live integrations.
_PRIME_REGRESSION_V160_PREV = prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V160_PREV();extra=[]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v160-init',lambda:(_v160_init() is None))
    add('v160-attention-levels',lambda:attention_decide('CRITICAL',1,1,1,0)['level'] in _V160_ATTENTION_LEVELS)
    add('v160-event-dedup',lambda:'fingerprint' in str(event_publish.__code__.co_consts))
    add('v160-open-loop-detect',lambda:open_loop_detect('I will check this tomorrow')['is_open_loop'])
    add('v160-capability-risk-taxonomy',lambda:'FINANCIAL' in _V160_CAP_RISK and 'SECURITY_SENSITIVE' in _V160_CAP_RISK)
    add('v160-goal-high-risk-approval',lambda:'requires_approval' in str(goal2_plan.__code__.co_consts))
    add('v160-goal-no-direct-order',lambda:'fyers_place' not in goal2_plan.__code__.co_names and 'place_order' not in goal2_plan.__code__.co_names)
    add('v160-recovery-no-authority-expansion',lambda:'expand authority' in str(recovery_plan.__code__.co_consts))
    add('v160-continuity-short-context',lambda:'elliptical' in str(continuity_resolve.__code__.co_consts))
    add('v160-owner-inbox',lambda:callable(owner_inbox_list))
    add('v160-chief-of-staff',lambda:'WHAT NEEDS YOU' in daily_brief2())
    add('v160-owner-gate',lambda:callable(_v160_owner))
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r


# Final wrapper must remain the last handle definition.
_HANDLE_V160_PREV = handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=msg.get('text') or msg.get('caption') or ''
        if _v160_dispatch(cid,txt,msg):return
        # record conversational turn for continuity only after command routing; bounded text only.
        if txt and cid is not None:
            try:continuity_add_turn(cid,'user',str(txt)[:1200])
            except Exception:pass
    except Exception as e:
        try:print('v16.0 dispatch:',type(e).__name__,str(e)[:180])
        except Exception:pass
    return _HANDLE_V160_PREV(msg)


_MAIN_V160_PREV = main
def main():
    try:
        _v160_init()
        print('NEMO v16.0 PERSONAL AI OS READY — Owner State + Attention + Open Loops + Goals + Recovery + Continuity')
    except Exception as e:
        print('v16.0 init:',type(e).__name__,str(e)[:180])
    return _MAIN_V160_PREV()



# =============================================================================
# NEMO v16.1 — PREMIUM TELEGRAM UI / PRESENTATION ENGINE 3.0
# Human-first rendering: no raw JSON in normal owner-facing v16 commands.
# =============================================================================
import math as _v161_math
import datetime as _v161_dt

_V161_WIDTH = 30

def _v161_txt(v, default='—'):
    if v is None:return default
    x=str(v).strip()
    return x if x else default

def _v161_clip(v,n=120):
    x=' '.join(str(v or '').split())
    return x if len(x)<=n else x[:max(1,n-1)].rstrip()+'…'

def _v161_bar(pct,width=10):
    try:p=max(0.0,min(100.0,float(pct or 0)))
    except Exception:p=0.0
    fill=int(round((p/100.0)*width));return '█'*fill+'░'*(width-fill)

def _v161_rel(ts):
    try:
        t=float(ts or 0)
        if not t:return '—'
        d=_v160_time.time()-t
        if d < 0:
            d=abs(d); suffix='from now'
        else:suffix='ago'
        if d<60:return 'just now' if suffix=='ago' else '<1 min from now'
        if d<3600:return f'{int(d//60)}m {suffix}'
        if d<86400:return f'{int(d//3600)}h {suffix}'
        if d<604800:return f'{int(d//86400)}d {suffix}'
        return _v161_dt.datetime.fromtimestamp(t).strftime('%d %b %Y')
    except Exception:return '—'

def _v161_state_icon(state):
    s=str(state or '').upper()
    if s in ('DONE','COMPLETED','PASS','HEALTHY','GREEN','SUCCESS'):return '✅'
    if s in ('RUNNING','ACTIVE','IN_PROGRESS','WORKING'):return '🟢'
    if s in ('PLANNED','PENDING','NEW','PROPOSED','OPEN'):return '🟡'
    if s in ('BLOCKED','FAIL','FAILED','RED','DEGRADED','ERROR'):return '🔴'
    if s in ('PAUSED','DISMISSED','CANCELLED','CANCELED'):return '⚪'
    return '🔹'

def _v161_risk_icon(risk):
    r=str(risk or '').upper()
    return {'READ_ONLY':'🟢','LOCAL_WRITE':'🟡','EXTERNAL_WRITE':'🟠','FINANCIAL':'🔴','PHYSICAL_DEVICE':'🔴','SECURITY_SENSITIVE':'🔴'}.get(r,'⚪')

def _v161_header(icon,title,subtitle=''):
    x=f'{icon} {str(title).upper()}\n'+'━'*28
    if subtitle:x+='\n'+str(subtitle)
    return x

def _v161_goal_card(g,steps=None,details=False):
    if not g:return _v161_header('🎯','Goal not found')+'\nNo matching goal exists.'
    gid=_v161_txt(g.get('id'))
    state=_v161_txt(g.get('state'),'UNKNOWN').upper()
    priority=int(g.get('priority') or 0)
    progress=float(g.get('progress') or 0)
    if 0 <= progress <= 1:progress*=100
    objective=_v161_clip(g.get('objective'),260)
    lines=[_v161_header('🎯','Goal',gid),objective,'',f'{_v161_state_icon(state)} Status     {state}',f'⚡ Priority   {priority}/100',f'📈 Progress   {_v161_bar(progress)}  {progress:.0f}%',f'🕒 Updated    {_v161_rel(g.get("updated"))}']
    if g.get('blocked_reason'):lines += ['', '🚧 BLOCKED', _v161_clip(g.get('blocked_reason'),220)]
    if details and steps:
        lines += ['', '🧭 EXECUTION PLAN']
        for x in steps[:12]:
            seq=x.get('seq') or '?';st=str(x.get('state') or 'PENDING').upper();risk=str(x.get('risk') or 'READ_ONLY').upper()
            approval=' • approval' if bool(x.get('requires_approval')) else ''
            lines.append(f'{seq}. {_v161_state_icon(st)} {_v161_clip(x.get("title"),90)}')
            lines.append(f'   {_v161_risk_icon(risk)} {risk}{approval} • {_v161_txt(x.get("capability"))}')
    lines += ['', f'Next: /goal2 plan {gid}' if state=='NEW' else f'Details: /goal2 status {gid}']
    return '\n'.join(lines)

def _v161_goal_list(rows):
    rows=rows or []
    if not rows:return _v161_header('🎯','Goals')+'\nNo active goals yet.\n\nCreate one with:\n/goal2 create <objective>'
    lines=[_v161_header('🎯','Mission Control',f'{len(rows)} recent goals')]
    for i,g in enumerate(rows[:10],1):
        state=str(g.get('state') or 'UNKNOWN').upper();progress=float(g.get('progress') or 0)
        if 0<=progress<=1:progress*=100
        lines += ['', f'{_v161_state_icon(state)} {i}. {_v161_clip(g.get("objective"),88)}', f'   {g.get("id")}  •  {state}  •  P{int(g.get("priority") or 0)}  •  {progress:.0f}%']
    lines += ['', 'Tip: /goal2 status <goal-id>']
    return '\n'.join(lines)

def _v161_plan_render(result):
    if not isinstance(result,dict) or not result.get('ok'):
        return _v161_header('❌','Planning failed')+'\n'+_v161_clip((result or {}).get('error') if isinstance(result,dict) else result,300)
    lines=[_v161_header('🧠','Execution Plan',_v161_txt(result.get('goal_id'))),_v161_clip(result.get('objective'),240),'']
    plan=result.get('plan') or []
    if not plan:lines.append('No executable steps were produced.')
    for x in plan[:15]:
        risk=str(x.get('risk') or 'READ_ONLY').upper();approval=' • NEEDS APPROVAL' if x.get('requires_approval') else ''
        lines.append(f'{x.get("seq","?")}. {_v161_clip(x.get("title"),100)}')
        lines.append(f'   {_v161_risk_icon(risk)} {risk}{approval}')
        lines.append(f'   🧩 {_v161_txt(x.get("capability"))}')
        if x.get('success_check'):lines.append(f'   ✓ {_v161_clip(x.get("success_check"),120)}')
        lines.append('')
    lines += ['Execution has not started automatically.', 'Nemo will keep high-impact actions approval-gated.']
    return '\n'.join(lines).rstrip()

def _v161_owner_render(snap):
    snap=snap or {};state=snap.get('state') or {}
    lines=[_v161_header('🧭','Owner State','Nemo’s current operating context')]
    if state:
        for k,v in list(state.items())[:10]:
            if isinstance(v,dict):val=v.get('value',v)
            else:val=v
            lines.append(f'• {str(k).replace("_"," ").title()}: {_v161_clip(val,100)}')
    else:lines.append('No explicit owner-state values set yet.')
    loops=snap.get('open_loops') or [];inbox=snap.get('inbox') or [];tasks=snap.get('tasks') or []
    lines += ['', '📌 NOW', f'Open loops  {len(loops)}', f'Inbox       {len(inbox)}', f'Tasks       {len(tasks)}']
    return '\n'.join(lines)

def _v161_inbox_render(xs):
    xs=xs or [];lines=[_v161_header('📥','Owner Inbox',f'{len(xs)} open items')]
    if not xs:return '\n'.join(lines+['','✨ Nothing needs attention right now.'])
    for i,x in enumerate(xs[:15],1):
        cat=str(x.get('category') or 'INFO').upper();lines += ['',f'{i}. {_v161_state_icon("OPEN")} {_v161_clip(x.get("title"),95)}',f'   {cat} • {_v161_txt(x.get("id"))}']
    lines += ['', 'Close: /inbox done <id>  •  Dismiss: /inbox dismiss <id>']
    return '\n'.join(lines)

def _v161_loops_render(xs):
    xs=xs or [];lines=[_v161_header('🔁','Open Loops',f'{len(xs)} unfinished items')]
    if not xs:return '\n'.join(lines+['','✅ No unfinished loops.'])
    for i,x in enumerate(xs[:15],1):
        due='';dv=float(x.get('due') or 0)
        if dv:due=' • due '+_v161_rel(dv)
        lines += ['',f'{i}. {_v161_clip(x.get("text"),105)}',f'   {_v161_txt(x.get("kind"),"FOLLOWUP")} • {_v161_txt(x.get("id"))}{due}']
    lines += ['', 'Complete: /openloop done <id>']
    return '\n'.join(lines)

def _v161_caps_render(xs):
    xs=xs or [];green=sum(1 for x in xs if str(x.get('health')).upper()=='GREEN');degraded=len(xs)-green
    lines=[_v161_header('🧩','Capability Center',f'{len(xs)} registered • {green} healthy • {degraded} need attention')]
    for x in xs[:24]:
        h=str(x.get('health') or 'UNKNOWN').upper();risk=str(x.get('risk') or 'READ_ONLY').upper()
        lines.append(f'{_v161_state_icon(h)} {_v161_txt(x.get("name"))}  {_v161_risk_icon(risk)}')
        lines.append(f'   {h} • {risk}')
    lines += ['', 'Inspect: /capreg health <capability>']
    return '\n'.join(lines)

def _v161_caphealth_render(x):
    x=x or {};name=x.get('name') or x.get('capability') or 'Capability';health=str(x.get('health') or x.get('effective_health') or 'UNKNOWN').upper()
    lines=[_v161_header('🩺','Capability Health',name),f'{_v161_state_icon(health)} Overall     {health}']
    for k in ('risk','reason','dependency_health','dependencies','commands','version'):
        if k in x and x.get(k) not in (None,'',[],{}):lines.append(f'• {k.replace("_"," ").title()}: {_v161_clip(x.get(k),160)}')
    return '\n'.join(lines)

def _v161_recovery_render(x):
    if not isinstance(x,dict) or not x.get('ok'):return _v161_header('🛟','Recovery')+'\nCould not build a recovery plan.'
    p=x.get('plan') or {};lines=[_v161_header('🛟','Recovery Plan',_v161_txt(x.get('id'))),f'Failure class: {_v161_txt(p.get("failure_class"))}']
    for title,key,icon in [('Likely causes','likely_causes','🔎'),('Checks','checks','🧪'),('Alternate paths','alternatives','🛣'),('Stop conditions','stop_conditions','🛑')]:
        vals=p.get(key) or []
        if not isinstance(vals,list):vals=[vals]
        if vals:
            lines += ['',f'{icon} {title.upper()}']
            lines += [f'• {_v161_clip(v,150)}' for v in vals[:8]]
    lines += ['', 'No recovery action was executed automatically.']
    return '\n'.join(lines)

def _v161_continuity_render(x):
    x=x or {};changed=bool(x.get('changed'))
    return '\n'.join([_v161_header('🗣','Context Resolver'),'Original: '+_v161_txt(x.get('original')),'Resolved: '+_v161_txt(x.get('resolved')),('✅ Context expanded' if changed else 'ℹ️ No expansion needed'),'Reason: '+_v161_txt(x.get('reason'))])

def _v161_ui_home():
    return '\n'.join([_v161_header('✨','Nemo Interface','Premium Presentation Engine 3.0'),'Human-first • compact • contextual • no raw JSON by default','',
        '🎯 /goal2        Mission control','🧭 /ownerstate    Current owner context','📥 /inbox         Action center','🔁 /openloop      Unfinished matters','🧩 /capreg        Capability health','🛟 /recover       Recovery planner','☀️ /brief2        Chief-of-staff brief','🗣 /companion     Conversation continuity','',
        'Diagnostic/raw data stays behind explicit debug paths—not normal owner UI.'])

# Intercept v16 owner-facing commands before the original v16.0 JSON-oriented renderer.
def _v161_dispatch(cid,text,msg=None):
    raw=str(text or '').strip();low=raw.lower()
    if not (low.startswith('/ui') or low.startswith('/goal2') or low.startswith('/ownerstate') or low.startswith('/inbox') or low.startswith('/openloop') or low.startswith('/capreg') or low.startswith('/recover') or low.startswith('/companion')):return False
    if not _v160_owner(cid):send_text(cid,'🔒 Owner-only command.');return True
    if low in ('/ui','/v161','/batch9'):send_text(cid,_v161_ui_home());return True
    if low=='/goal2':send_text(cid,_v161_goal_list(goal2_status('')));return True
    if low.startswith('/goal2 create '):
        obj=raw[len('/goal2 create '):].strip()
        if not obj:send_text(cid,'🎯 Add an objective after /goal2 create');return True
        gid=goal2_create(obj,70,str(cid));g=(goal2_status(gid) or {}).get('goal') or {'id':gid,'objective':obj,'state':'NEW','priority':70}
        send_text(cid,_v161_goal_card(g));return True
    m=_v160_re.match(r'^/goal2\s+plan\s+(\S+)$',raw,_v160_re.I)
    if m:
        gid=m.group(1);send_text(cid,_v161_header('🧠','Planning',gid)+'\nBuilding a capability-aware execution plan…')
        def _v161_gp():send_text(cid,_v161_plan_render(goal2_plan(gid)))
        threading.Thread(target=_v161_gp,daemon=True,name='nemo-v161-goal-plan').start();return True
    m=_v160_re.match(r'^/goal2\s+status\s+(\S+)$',raw,_v160_re.I)
    if m:
        st=goal2_status(m.group(1));send_text(cid,_v161_goal_card((st or {}).get('goal'),(st or {}).get('steps'),True));return True
    if low=='/ownerstate':send_text(cid,_v161_owner_render(owner_state_snapshot()));return True
    if low.startswith('/ownerstate set '):
        body=raw[len('/ownerstate set '):]
        if '=' not in body:send_text(cid,'🧭 Usage: /ownerstate set key=value');return True
        k,v=body.split('=',1);owner_state_set(k.strip(),v.strip(),1.0,'owner');send_text(cid,f'✅ Updated\n{k.strip().replace("_"," ").title()} → {_v161_clip(v.strip(),120)}');return True
    if low=='/inbox':send_text(cid,_v161_inbox_render(owner_inbox_list('OPEN',20)));return True
    m=_v160_re.match(r'^/inbox\s+(done|dismiss)\s+(\S+)$',raw,_v160_re.I)
    if m:
        ok=owner_inbox_mark(m.group(2),'DONE' if m.group(1).lower()=='done' else 'DISMISSED');send_text(cid,('✅ Inbox item updated.' if ok else '⚠️ Inbox item not found.'));return True
    if low=='/openloop':send_text(cid,_v161_loops_render(open_loop_list('OPEN',20)));return True
    if low.startswith('/openloop add '):
        text2=raw[len('/openloop add '):].strip();oid=open_loop_add(text2,'FOLLOWUP',0,'owner');send_text(cid,f'🔁 Open loop saved\n{_v161_clip(text2,180)}\n\nID: {oid}');return True
    m=_v160_re.match(r'^/openloop\s+done\s+(\S+)(?:\s*\|\s*(.*))?$',raw,_v160_re.I)
    if m:send_text(cid,'✅ Open loop completed.' if open_loop_close(m.group(1),m.group(2) or '') else '⚠️ Open loop not found.');return True
    if low=='/capreg':send_text(cid,_v161_caps_render(capability_list(100)));return True
    m=_v160_re.match(r'^/capreg\s+health\s+(\S+)$',raw,_v160_re.I)
    if m:send_text(cid,_v161_caphealth_render(capability_health(m.group(1))));return True
    if low.startswith('/recover '):
        failure=raw[len('/recover '):].strip();send_text(cid,_v161_header('🛟','Recovery Analysis')+'\nDiagnosing failure and checking alternate paths…')
        def _v161_rp():send_text(cid,_v161_recovery_render(recovery_plan(failure)))
        threading.Thread(target=_v161_rp,daemon=True,name='nemo-v161-recovery').start();return True
    if low=='/companion':send_text(cid,_v161_header('🗣','Conversation Continuity')+'\nUnderstands short follow-ups using active context.\n\nExamples: “wo wala” • “same” • “aur?” • “uska kya?” • “kal ka?”\n\nDiagnostic: /companion resolve <phrase>');return True
    if low.startswith('/companion resolve '):send_text(cid,_v161_continuity_render(continuity_resolve(cid,raw[len('/companion resolve '):])));return True
    return False

# Regression extension for presentation invariants.
_PRIME_REGRESSION_V161_PREV = prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V161_PREV();extra=[]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v161-goal-list-human-ui',lambda:'GOALS' in _v161_goal_list([]) or 'MISSION CONTROL' in _v161_goal_list([]))
    add('v161-no-json-goal-default',lambda:'"objective"' not in _v161_goal_list([{'id':'G','objective':'Test','state':'NEW','priority':1,'progress':0}]))
    add('v161-risk-render',lambda:_v161_risk_icon('FINANCIAL')=='🔴')
    add('v161-progress-render',lambda:'█' in _v161_bar(50))
    add('v161-recovery-human-ui',lambda:'RECOVERY PLAN' in _v161_recovery_render({'ok':True,'id':'R','plan':{'failure_class':'TEST'}}))
    add('v161-owner-gate',lambda:callable(_v160_owner))
    add('v161-no-order-authority',lambda:'fyers_place' not in _v161_dispatch.__code__.co_names and 'place_order' not in _v161_dispatch.__code__.co_names)
    add('v161-final-dispatch',lambda:callable(_v161_dispatch))
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_HANDLE_V161_PREV = handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=msg.get('text') or msg.get('caption') or ''
        if _v161_dispatch(cid,txt,msg):return
    except Exception as e:
        try:print('v16.1 ui dispatch:',type(e).__name__,str(e)[:180])
        except Exception:pass
    return _HANDLE_V161_PREV(msg)

_MAIN_V161_PREV = main
def main():
    try:print('NEMO v16.1 PREMIUM UI READY — human-first presentation, no raw JSON by default')
    except Exception:pass
    return _MAIN_V161_PREV()

