import base64 as _v162_b64
import tempfile as _v162_tmp
import secrets as _v162_secrets
import hashlib as _v162_hash
import os as _v162_os

VERSION = "16.2"
_V162_VOICE_DIR = _v162_os.environ.get("NEMO_VOICE3_DIR", "/root/nemo_voice3")
try:_v162_os.makedirs(_V162_VOICE_DIR, exist_ok=True)
except Exception:pass

def _v162_init():
    try:_v160_init()
    except Exception:pass
    c=_v160_conn()
    c.execute('''CREATE TABLE IF NOT EXISTS prime_voice3_devices(
      id TEXT PRIMARY KEY, name TEXT, token_hash TEXT, enabled INTEGER DEFAULT 1,
      mode TEXT DEFAULT 'NORMAL', created REAL, last_seen REAL, meta_json TEXT DEFAULT '{}')''')
    c.execute('''CREATE TABLE IF NOT EXISTS prime_voice3_sessions(
      id TEXT PRIMARY KEY, device_id TEXT, chat_id TEXT, state TEXT DEFAULT 'IDLE',
      active_topic TEXT DEFAULT '', last_user TEXT DEFAULT '', last_reply TEXT DEFAULT '',
      turns INTEGER DEFAULT 0, interrupted INTEGER DEFAULT 0, updated REAL)''')
    c.execute('''CREATE TABLE IF NOT EXISTS prime_voice3_outbox(
      id TEXT PRIMARY KEY, ts REAL, device_id TEXT DEFAULT '*', priority INTEGER DEFAULT 50,
      text TEXT, status TEXT DEFAULT 'QUEUED', expires REAL DEFAULT 0, source TEXT DEFAULT 'nemo')''')
    c.commit();c.close()
    try:capability_register('ambient_voice','16.2','Laptop voice sessions, short-utterance continuity, TTS/STT and proactive speech queue.','READ_ONLY',[],['/voice3'],'voice3')
    except Exception:pass

def voice3_enroll(name='GAUTAM-LAPTOP'):
    _v162_init();did='V3-'+_v160_uuid.uuid4().hex[:10].upper();token=_v162_secrets.token_urlsafe(32);h=_v162_hash.sha256(token.encode()).hexdigest();now=_v160_time.time()
    c=_v160_conn();c.execute('INSERT INTO prime_voice3_devices(id,name,token_hash,enabled,mode,created,last_seen,meta_json) VALUES(?,?,?,?,?,?,?,?)',(did,str(name)[:80],h,1,'NORMAL',now,0,'{}'));c.commit();c.close()
    return {'device_id':did,'token':token,'name':name}

def _v162_auth(did,token):
    if not did or not token:return False
    h=_v162_hash.sha256(str(token).encode()).hexdigest();c=_v160_conn();r=c.execute('SELECT enabled,token_hash FROM prime_voice3_devices WHERE id=?',(str(did),)).fetchone()
    ok=bool(r and int(r['enabled'] or 0)==1 and _v162_secrets.compare_digest(str(r['token_hash']),h))
    if ok:c.execute('UPDATE prime_voice3_devices SET last_seen=? WHERE id=?',(_v160_time.time(),str(did)));c.commit()
    c.close();return ok

def voice3_status():
    _v162_init();c=_v160_conn();rows=c.execute('SELECT id,name,enabled,mode,created,last_seen FROM prime_voice3_devices ORDER BY created DESC').fetchall();c.close();return [dict(x) for x in rows]

def voice3_set_mode(did,mode):
    mode=str(mode or '').upper();
    if mode not in ('QUIET','NORMAL','FRIEND','JARVIS'):return False
    c=_v160_conn();cur=c.execute('UPDATE prime_voice3_devices SET mode=? WHERE id=?',(mode,str(did)));c.commit();ok=cur.rowcount>0;c.close();return ok

def voice3_queue_speech(text,device_id='*',priority=50,ttl=3600,source='nemo'):
    txt=_tts_sanitize(str(text or ''))[:1200]
    if not txt:return None
    oid='VOUT-'+_v160_uuid.uuid4().hex[:10].upper();now=_v160_time.time();c=_v160_conn();c.execute('INSERT INTO prime_voice3_outbox(id,ts,device_id,priority,text,status,expires,source) VALUES(?,?,?,?,?,?,?,?)',(oid,now,str(device_id or '*'),int(priority),txt,'QUEUED',now+int(ttl),str(source)));c.commit();c.close();return oid

def _v162_outbox_claim(did):
    now=_v160_time.time();c=_v160_conn();r=c.execute("SELECT * FROM prime_voice3_outbox WHERE status='QUEUED' AND (device_id=? OR device_id='*') AND (expires=0 OR expires>?) ORDER BY priority DESC,ts ASC LIMIT 1",(str(did),now)).fetchone()
    if not r:c.close();return None
    c.execute("UPDATE prime_voice3_outbox SET status='DELIVERED' WHERE id=?",(r['id'],));c.commit();d=dict(r);c.close();return d

def _v162_voice_reply(chat_id,text,device_id=''):
    raw=str(text or '').strip();resolved=continuity_resolve(chat_id,raw)
    prompt=str(resolved.get('resolved') or raw)
    # voice answers should be concise by default; existing brain/tools remain authoritative.
    vp=("VOICE MODE. Answer naturally for spoken conversation. Default to 1-3 short sentences. "
        "Use Hindi/Hinglish/English matching the user. No markdown tables. If a consequential action needs approval, say so. "
        "User said: "+prompt)
    try:reply=ask_ai(chat_id,vp,remember=True,timeout=90)
    except Exception as e:reply='I hit a temporary brain error: '+type(e).__name__
    reply=_tts_sanitize(str(reply or ''))[:1800]
    try:continuity_add_turn(chat_id,'user',raw);continuity_add_turn(chat_id,'assistant',reply)
    except Exception:pass
    return {'reply':reply,'resolved':prompt,'contextual':bool(resolved.get('changed'))}

def _v162_make_tts(text):
    p=_v162_os.path.join(_V162_VOICE_DIR,'reply-'+_v160_uuid.uuid4().hex[:8]+'.mp3')
    ok=False
    try:ok=_edge_tts(_tts_sanitize(text)[:1500],p)
    except Exception:ok=False
    if not ok:return None
    try:
        raw=open(p,'rb').read();_v162_os.remove(p);return _v162_b64.b64encode(raw).decode()
    except Exception:return None

# Extend the existing Flask app without replacing its established endpoints.
_BUILD_WEB_APP_V162_PREV = build_web_app
def build_web_app():
    app=_BUILD_WEB_APP_V162_PREV()
    try:
        from flask import request, jsonify
        @app.route('/api/voice3/ping',methods=['POST'])
        def _v3_ping():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '');tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            item=_v162_outbox_claim(did);return jsonify({'ok':True,'version':VERSION,'proactive':item})
        @app.route('/api/voice3/transcribe',methods=['POST'])
        def _v3_transcribe():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '');tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            b=str(d.get('audio_b64') or '');
            try:raw=_v162_b64.b64decode(b); 
            except Exception:return jsonify({'ok':False,'error':'bad audio'}),400
            if not raw or len(raw)>8*1024*1024:return jsonify({'ok':False,'error':'audio size'}),400
            fd,p=_v162_tmp.mkstemp(suffix='.wav');_v162_os.close(fd)
            try:
                open(p,'wb').write(raw);txt=groq_transcribe(p) or ''
            finally:
                try:_v162_os.remove(p)
                except Exception:pass
            return jsonify({'ok':bool(txt),'text':txt})
        @app.route('/api/voice3/chat',methods=['POST'])
        def _v3_chat():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '');tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            txt=str(d.get('text') or '')[:2000];cid=OWNER.get('id') or 0
            if not txt:return jsonify({'ok':False,'error':'empty text'}),400
            out=_v162_voice_reply(cid,txt,did);out['ok']=True
            if bool(d.get('audio',True)):out['audio_mp3_b64']=_v162_make_tts(out['reply'])
            return jsonify(out)
    except Exception as e:
        try:print('v16.2 web routes:',type(e).__name__,str(e)[:180])
        except Exception:pass
    return app

def _v162_render_status():
    xs=voice3_status();lines=['🎙 NEMO SIRI MODE — LAPTOP FOUNDATION','━━━━━━━━━━━━━━━━━━━━━━━━━━━━','Voice gateway: READY','Transport: HTTP low-latency MVP','Next transport: realtime WebRTC','']
