    m=_v160_re.match(r'^/voice3\s+mode\s+(\S+)\s+(quiet|normal|friend|jarvis)$',raw,_v160_re.I)
    if m:send_text(cid,'✅ Voice mode updated.' if voice3_set_mode(m.group(1),m.group(2)) else 'Device/mode not found.');return True
    if low.startswith('/voice3 say '):
        oid=voice3_queue_speech(raw[len('/voice3 say '):],priority=80,source='owner');send_text(cid,'🔊 Queued for laptop speech: '+str(oid));return True
    return True

