# ==================== v16.3 FAST HANDSFREE VOICE ====================
# Low-latency voice path: single-pass conversational context + Groq-first response.
VERSION='16.3'

import time as _v163_time

def _v163_recent_turns(chat_id,limit=8):
    try:
        c=_v160_conn();r=c.execute('SELECT turns_json FROM prime_conversation_continuity WHERE chat_id=?',(str(chat_id),)).fetchone();c.close()
        if not r:return []
        xs=_v160_json.loads(r['turns_json'] or '[]')
        return xs[-int(limit):]
    except Exception:return []

def _v163_fast_voice_reply(chat_id,text,device_id=''):
    raw=str(text or '').strip()
    turns=_v163_recent_turns(chat_id,8)
    msgs=[{'role':'system','content':(
        'You are Nemo in LIVE VOICE MODE. Respond immediately and naturally for spoken conversation. '
        'Use the same language as the user (Hindi/Hinglish/English). Default to one or two short sentences. '
        'Understand short follow-ups from recent turns without asking the user to repeat obvious context. '
        'Do not use markdown, tables, headings, or long lists. For consequential external actions, ask for confirmation when required.'
    )}]
    for x in turns[-6:]:
        role='assistant' if str(x.get('role'))=='assistant' else 'user'
        t=str(x.get('text') or '').strip()
        if t:msgs.append({'role':role,'content':t[:900]})
    msgs.append({'role':'user','content':raw[:1200]})
    reply=''
    t0=_v163_time.time()
    try:reply=str(groq_chat(msgs) or '').strip()
    except Exception:reply=''
    provider='groq-fast'
    if not reply:
        provider='router-fallback'
        prompt=("VOICE MODE. Answer naturally and briefly in 1-2 sentences, matching Hindi/Hinglish/English. "
                "Use recent conversational context where relevant. User said: "+raw)
        try:reply=str(ask_ai(chat_id,prompt,remember=True,timeout=45) or '').strip()
        except Exception as e:reply='I hit a temporary brain error: '+type(e).__name__
    reply=_tts_sanitize(reply)[:1200]
    try:
        continuity_add_turn(chat_id,'user',raw)
        continuity_add_turn(chat_id,'assistant',reply)
    except Exception:pass
    return {'reply':reply,'resolved':raw,'contextual':bool(turns),'provider':provider,'brain_ms':int((_v163_time.time()-t0)*1000)}

# Route v16.2 Voice3 through the v16.3 fast path. Existing auth/TTS routes remain unchanged.
_v162_voice_reply=_v163_fast_voice_reply

