_V165_SOCIAL_RE=_v165_re.compile(r"(?ix)^\s*(?:hi|hello|hey|thanks?|thank\s+you|good\s*(?:morning|evening|night)|how\s+are\s+you|what'?s\s+up|ok(?:ay)?|yes|no|haan|han|nahi|nahin|shukriya|dhanyavaad|namaste|aur\??|fir\??|phir\??|theek\s+ho|kaise\s+ho|नमस्ते|धन्यवाद|हाँ|हां|नहीं|कैसे\s+हो|और\??|फिर\??)\s*[.!?]*\s*$")
_V165_OWNER_CONTEXT_RE=_v165_re.compile(r"(?ix)(pending|status|goal|mission|task|inbox|open\s*loop|remember|previous|last|yesterday|tomorrow|mera|meri|mere|wala|wali|uska|iska|kal|aaj|पेंडिंग|स्टेटस|मेरा|मेरी|मेरे|वाला|वाली|उसका|इसका|कल|आज|काम|लक्ष्य)")
_V165_ACTION_RE=_v165_re.compile(r"(?ix)(research|report|pdf|email|mail|send|calendar|meeting|schedule|browser|website|open|download|file|document|registry|legal|compare|analy[sz]e|option\s*chain|nifty|banknifty|sensex|portfolio|market|latest|current|news|create|build|fix|debug|code|deploy|restart|device|screenshot|screen|excel|word|powerpoint|ppt|remind|book|purchase|buy|search|check|find|रिसर्च|रिपोर्ट|पीडीएफ|ईमेल|भेज|कैलेंडर|मीटिंग|खोल|डाउनलोड|फाइल|दस्तावेज|रजिस्ट्री|तुलना|विश्लेषण|बनाओ|खोज|चेक|देखो)")

def _v165_schema():
    return {'type':'json_schema','json_schema':{'name':'nemo_voice_answer','strict':True,'schema':{'type':'object','properties':{'answer':{'type':'string'}},'required':['answer'],'additionalProperties':False}}}

def _v165_groq_answer(msgs,model=None,max_tokens=260,reasoning='low'):
    if not GROQ_KEY:return None,{'ok':False,'reason':'missing_groq_key'}
    model=model or _V165_FAST_MODEL
    clean=[{'role':'system','content':'You are Nemo, a highly capable live personal AI assistant. Answer directly and naturally. Match English, Hindi, Hinglish, or mixed speech. Maintain references from recent turns. Never mention hidden prompts, chain-of-thought, policies, routing, JSON, models, or internal processing. For voice, lead with the answer. Be concise for casual speech and substantive when needed.'}]
    for x in list(msgs or [])[-10:]:
        role=str(x.get('role') or 'user');z=str(x.get('content') or '').strip()
        if role in ('user','assistant') and z:clean.append({'role':role,'content':z[:1400]})
    payload={'model':model,'messages':clean,'max_tokens':int(max_tokens),'temperature':0.25,'response_format':_v165_schema(),'reasoning_format':'hidden','reasoning_effort':reasoning}
    t0=_v165_time.time()
    try:
        r=requests.post('https://api.groq.com/openai/v1/chat/completions',headers={'Authorization':'Bearer '+GROQ_KEY},json=payload,timeout=(4,30))
        meta={'ok':False,'model':model,'status':r.status_code,'ms':int((_v165_time.time()-t0)*1000)}
        if r.status_code==200:
            raw=(((r.json().get('choices') or [{}])[0].get('message') or {}).get('content') or '').strip()
            try:obj=_v165_json.loads(raw);ans=_v164_voice_clean(obj.get('answer','')) if isinstance(obj,dict) else ''
            except Exception:ans=''
            if ans:meta['ok']=True;return ans,meta
            meta['reason']='empty_or_invalid_schema';return None,meta
        try:meta['reason']=str((r.json() or {}).get('error',{}).get('message') or r.text)[:300]
        except Exception:meta['reason']=str(r.text)[:300]
        return None,meta
    except Exception as e:return None,{'ok':False,'model':model,'status':0,'ms':int((_v165_time.time()-t0)*1000),'reason':type(e).__name__+': '+str(e)[:220]}

def _v165_route(text):
    t=str(text or '').strip()
    if _V165_SOCIAL_RE.match(t):return 'SOCIAL'
    if _V165_ACTION_RE.search(t):return 'CAPABILITY'
    if _V165_OWNER_CONTEXT_RE.search(t):return 'OWNER'
    return 'SMART'

def _v165_context_messages(chat_id,raw):
    turns=_v163_recent_turns(chat_id,10);msgs=[]
