VERSION='16.7'
import json as _v167_json, time as _v167_time, os as _v167_os

_V167_STT_PROMPT=(
    'Natural personal-assistant conversation spoken by an Indian user in Hindi, Hinglish or English. '
    'For Hindi/Hinglish speech, write ONLY Devanagari Hindi and/or Latin-script English/Hinglish. '
    'NEVER output Urdu, Perso-Arabic, Arabic, Shahmukhi or Nastaliq script unless the speaker explicitly asks for Urdu. '
    'Do not translate Hindi into Urdu. Preserve English words naturally inside Hinglish. '
    'Common words/names: Nemo, Gautam, Udaipur, Rajasthan, pending, important, laptop, Android, Telegram, '
    'Chrome, YouTube, WhatsApp, Nifty, Sensex, option chain, PDF, research. '
    'Transcribe what was actually spoken; do not invent missing words.'
)

def groq_transcribe(path, langs=('en','hi')):
    """v16.7 accuracy-first STT. Large-v3 primary; turbo is only a provider fallback."""
    if not GROQ_KEY or not _v167_os.path.exists(path):return None
    fn=path.rsplit('/',1)[-1]
    for model in ('whisper-large-v3','whisper-large-v3-turbo'):
        try:
            with open(path,'rb') as f:
                files={'file':(fn,f,'audio/wav')}
                data={'model':model,'response_format':'json','temperature':'0','prompt':_V167_STT_PROMPT}
                r=requests.post('https://api.groq.com/openai/v1/audio/transcriptions',
                    headers={'Authorization':'Bearer '+GROQ_KEY},files=files,data=data,timeout=45)
            if r.status_code==200:
                try:txt=str((r.json() or {}).get('text') or '').strip()
                except Exception:txt=str(r.text or '').strip()
                # Reject common non-speech hallucinations/punctuation-only turns.
                if txt and re.search(r'[A-Za-z0-9\u0900-\u097F]',txt):return txt
                return None
            if r.status_code not in (400,404,429,500,502,503):break
        except Exception:
            continue
    return None

# Voice-command vocabulary is intentionally declarative. Execution happens only on the explicitly
# enrolled owner's Windows client, where a fixed local allowlist is enforced.
def _v167_desktop_intent(text):
    t=str(text or '').strip().lower()
    if not t:return None
    apps={'chrome':'chrome','google chrome':'chrome','notepad':'notepad','calculator':'calculator',
          'calc':'calculator','explorer':'explorer','file explorer':'explorer','telegram':'telegram','whatsapp':'whatsapp'}
    sites={'youtube':'https://www.youtube.com','google':'https://www.google.com','gmail':'https://mail.google.com'}
    # Explicit local control language only; normal questions stay with Nemo's brain.
    open_words=('open ','launch ','start ','khol ','kholo ','खोलो ','खोल ')
    if any(t.startswith(x) or (' '+x) in t for x in open_words):
        for k,v in sites.items():
            if k in t:return {'kind':'open_url','target':v,'label':k}
        for k,v in apps.items():
            if k in t:return {'kind':'open_app','target':v,'label':k}
    if any(x in t for x in ('volume up','awaz badhao','आवाज़ बढ़ाओ','आवाज बढ़ाओ')):return {'kind':'media_key','target':'volume_up'}
