# ============================================================================
# v16.8 — WINDOWS HANDS 2.0 + SCREEN AWARENESS
# Bounded, owner-visible desktop control. No arbitrary shell/code generation.
# Consequential actions remain confirmation-gated on the enrolled Windows client.
# ============================================================================
VERSION='16.8'
import urllib.parse as _v168_urlparse, base64 as _v168_b64, time as _v168_time, re as _v168_re

_V168_DIRECT_KINDS={
    'open_app','open_url','open_search','media_key','window','key_press','scroll','mouse_click',
    'type_text','find_file','system_status','screen_describe','screenshot_save','lock'
}

def _v168_normalize_transcript(text):
    """Very conservative repair of recurrent assistant-command mishears.
    Never free-form rewrites the transcript and never changes long dictation."""
    s=str(text or '').strip()
    if not s:return s
    low=s.lower()
    # Recurrent STT confusion observed in short Hindi/Hinglish owner-status commands.
    command_ctx=any(x in low for x in ('aaj','आज','mera','meri','मेरे','मेरी','kya','क्या','status','pending','पेंडिंग'))
    if command_ctx and len(s.split())<=12:
        reps=(('banding','pending'),('bending','pending'),('पैंडिंग','पेंडिंग'),('बैंडिंग','पेंडिंग'),('पेन्डिंग','पेंडिंग'))
        for a,b in reps:
            s=_v168_re.sub(_v168_re.escape(a),b,s,flags=_v168_re.I)
    return s.strip()

def _v168_desktop_intent(text):
    t=str(text or '').strip(); low=t.lower()
    if not low:return None
    # Never turn dictated credentials/secrets into keyboard actions.
    secret_words=('password','otp','one time password','cvv','pin number','पासवर्ड','ओटीपी')
    if (low.startswith(('type ','write ','likho ','लिखो ')) and any(x in low for x in secret_words)):
        return {'kind':'blocked_sensitive','label':'sensitive text'}

    base=_v167_desktop_intent(t)
    if base:return base

    # Browser search.
    for p in ('search google for ','google search ','search web for ','google par search ','गूगल पर सर्च '):
        if low.startswith(p):
            q=t[len(p):].strip()
            if q:return {'kind':'open_search','query':q[:300]}

    # Screen awareness and screenshots.
    if any(x in low for x in ('what is on my screen','what\'s on my screen','describe my screen','screen dekho','screen देखो','मेरी स्क्रीन','screen par kya')):
        return {'kind':'screen_describe','question':t[:500]}
    if any(x in low for x in ('take screenshot','save screenshot','screenshot lo','स्क्रीनशॉट लो')):
        return {'kind':'screenshot_save'}

    # Window management.
    if any(x in low for x in ('switch window','next window','alt tab','window badlo','विंडो बदलो')):return {'kind':'window','target':'switch'}
    if any(x in low for x in ('minimize window','minimise window','window minimize','विंडो मिनिमाइज')):return {'kind':'window','target':'minimize'}
    if any(x in low for x in ('maximize window','maximise window','window maximize','विंडो मैक्सिमाइज')):return {'kind':'window','target':'maximize'}
    if any(x in low for x in ('close window','close this app','close active window','विंडो बंद','app band karo')):return {'kind':'window','target':'close','confirm':True}

    # Explicit keyboard primitives.
    key_map=(('press enter','enter'),('press escape','escape'),('press esc','escape'),('press tab','tab'),('press backspace','backspace'),
             ('enter dabao','enter'),('एंटर दबाओ','enter'),('tab dabao','tab'))
    for phrase,key in key_map:
        if phrase in low:return {'kind':'key_press','target':key}

    # Scroll primitives.
    if any(x in low for x in ('scroll down','neeche scroll','नीचे स्क्रॉल')):return {'kind':'scroll','target':'down','amount':-5}
    if any(x in low for x in ('scroll up','upar scroll','ऊपर स्क्रॉल')):return {'kind':'scroll','target':'up','amount':5}

    # Explicit coordinate click only. No model-inferred blind clicking.
    m=_v168_re.search(r'click(?: at)?\s+(?:x\s*)?(\d{1,4})[ ,]+(?:y\s*)?(\d{1,4})',low)
    if m:return {'kind':'mouse_click','x':int(m.group(1)),'y':int(m.group(2))}

    # Explicit typing into the currently focused app. Sensitive dictation is blocked above.
    for p in ('type ','write ','likho ','लिखो '):
        if low.startswith(p):
            val=t[len(p):].strip()
            if val:return {'kind':'type_text','text':val[:1000]}

    # Bounded local file search (Desktop/Documents/Downloads only on client).
    for p in ('find file ','search file ','file dhundo ','फाइल ढूंढो ','फ़ाइल ढूंढो '):
        if low.startswith(p):
            q=t[len(p):].strip()
            if q:return {'kind':'find_file','query':q[:180]}

    if any(x in low for x in ('laptop status','computer status','battery status','system status')):
        return {'kind':'system_status'}
    return None

_V168_REPLY_PREV=_v167_voice_reply
def _v168_voice_reply(chat_id,text,device_id=''):
    raw=_v168_normalize_transcript(text)
    intent=_v168_desktop_intent(raw)
    if intent:
        if intent.get('kind')=='blocked_sensitive':
            return {'reply':'I will not type passwords, OTPs, PINs, or other authentication secrets from voice dictation.',
                    'resolved':raw,'contextual':False,'provider':'local-policy','route':'DESKTOP-BLOCKED','brain_ms':0,'desktop_intent':intent,'stt_model':'whisper-large-v3'}
        # Direct laptop operations do not need an LLM round-trip. Client reports actual success/failure.
        return {'reply':'Ready on your laptop.','resolved':raw,'contextual':False,'provider':'local-intent-router',
                'route':'DESKTOP','brain_ms':0,'desktop_intent':intent,'stt_model':'whisper-large-v3'}
    out=_V168_REPLY_PREV(chat_id,raw,device_id)
    out['resolved']=raw;out['normalized_text']=raw
    return out

