VERSION='16.9'
import json as _v169_json, re as _v169_re, time as _v169_time

_V169_ALLOWED_ACTIONS={'none','click','key_press','scroll','type_text'}
_V169_HIGH_RISK_WORDS=(
    'buy','purchase','pay','payment','transfer','send money','order','checkout','place order','trade','buy call','buy put',
    'delete','remove account','factory reset','format','install','uninstall','submit form','send email','send message','post',
    'password','otp','cvv','pin','private key','seed phrase','recovery code','security setting','bank','upi'
)

def _v169_json_obj(raw):
    s=str(raw or '').strip()
    if not s:return None
    s=_v164_voice_clean(s)
    try:
        x=_v169_json.loads(s)
        return x if isinstance(x,dict) else None
    except Exception:pass
    m=_v169_re.search(r'\{.*\}',s,_v169_re.S)
    if not m:return None
    try:
        x=_v169_json.loads(m.group(0));return x if isinstance(x,dict) else None
    except Exception:return None

def _v169_screen_goal_intent(text):
    t=str(text or '').strip();low=t.lower()
    if not low:return None
    triggers=(
        'click the ','click on ','find and click ','on screen ','on my screen ','screen par ','screen pe ',
        'button dabao','button दबाओ','इस पर क्लिक','उस पर क्लिक','यहाँ क्लिक','वहाँ क्लिक',
        'select the ','choose the ','tick the ','untick the ','open the menu','press the button'
    )
    if any(x in low for x in triggers):
        # Explicit coordinates remain handled by v16.8 before this layer.
        if _v169_re.search(r'click(?: at)?\s+(?:x\s*)?\d{1,4}[ ,]+(?:y\s*)?\d{1,4}',low):return None
        return {'kind':'computer_use_goal','goal':t[:700],'requires_confirmation':True}
    return None

_V169_DESKTOP_PREV=_v168_desktop_intent
def _v169_desktop_intent(text):
    base=_V169_DESKTOP_PREV(text)
    if base:return base
    return _v169_screen_goal_intent(text)

_V168_DIRECT_KINDS=set(_V168_DIRECT_KINDS)|{'computer_use_goal'}

_V169_REPLY_PREV=_v168_voice_reply
