def _v169_validate_plan(plan,width,height,goal=''):
    if not isinstance(plan,dict):return {'ok':False,'error':'invalid plan'}
    summary=str(plan.get('summary') or '')[:500]
    risk=str(plan.get('risk') or 'MEDIUM').upper()
    try:conf=float(plan.get('confidence') or 0)
    except Exception:conf=0.0
    act=plan.get('action') if isinstance(plan.get('action'),dict) else {}
    kind=str(act.get('kind') or 'none').lower()
    if kind not in _V169_ALLOWED_ACTIONS:kind='none'
    low=(str(goal)+' '+summary+' '+str(act)).lower()
    if any(w in low for w in _V169_HIGH_RISK_WORDS):
        return {'ok':True,'summary':summary or 'This request could create a consequential external action.',
                'confidence':conf,'risk':'HIGH','requires_confirmation':True,'blocked':True,
                'action':{'kind':'none'},'reason':'High-impact computer-use actions are not auto-executed.'}
    clean={'kind':kind}
    if kind=='click':
        try:x=int(act.get('x'));y=int(act.get('y'))
        except Exception:return {'ok':False,'error':'invalid click coordinates'}
        if not (0<=x<int(width or 1) and 0<=y<int(height or 1)):return {'ok':False,'error':'click outside current screen'}
        clean.update({'x':x,'y':y,'label':str(act.get('label') or 'target')[:140]})
    elif kind=='key_press':
        key=str(act.get('key') or '').lower()
        if key not in ('enter','escape','tab','backspace','space','up','down','left','right'):kind='none';clean={'kind':'none'}
        else:clean['key']=key
    elif kind=='scroll':
        try:amt=int(act.get('amount') or -4)
        except Exception:amt=-4
        clean['amount']=max(-8,min(8,amt))
    elif kind=='type_text':
        val=str(act.get('text') or '')[:500]
        if any(w in val.lower() for w in ('password','otp','cvv','pin','seed phrase','private key')):
            return {'ok':True,'summary':'Sensitive authentication text will not be typed by Computer Use.',
                    'confidence':conf,'risk':'HIGH','requires_confirmation':True,'blocked':True,'action':{'kind':'none'}}
        clean['text']=val
    return {'ok':True,'summary':summary,'confidence':max(0,min(1,conf)),'risk':risk if risk in ('LOW','MEDIUM','HIGH') else 'MEDIUM',
            'requires_confirmation':True,'blocked':False,'action':clean}

