    q=str(question or 'Describe my current screen and the safest useful next action.')[:700]
    prompt=(
        'NEMO FAST SCREEN VISION. Inspect only the attached CURRENT Windows screenshot. '
        'Answer the owner directly in at most 5 concise sentences. Identify the active app, visible dialog/error, '
        'and the most relevant visible control or next step. Never ask the owner to provide a screenshot because '
        'the screenshot is already attached. Never claim an action was executed. Never infer hidden secrets. '
        'No internal reasoning, no markdown preamble. Owner request: '+q)
    models=list(VISION_MODELS[:1] or VISION_MODELS)
    attempts=[]
    if models:
        attempts.append((models,35))
    if len(VISION_MODELS)>1:
        attempts.append((list(VISION_MODELS),65))
    for mods,to in attempts:
        try:
            raw=ask_ai(OWNER.get('id') or 0,prompt,image_b64=img,remember=False,timeout=to,
                       models_override=mods,deep=False,raw=True) or ''
            ans=_v164_voice_clean(raw)
            low=ans.lower()
            if ans and len(ans)>=18 and 'share a screenshot' not in low and 'provide a screenshot' not in low:
                return ans, (mods[0] if mods else 'vision')
        except Exception:
            pass
    return '', 'vision-unavailable'

