_V170_FRESH_RE=_v170_re.compile(r'(?ix)(latest|today|current|now|news|price|weather|market|recent|2026|aaj|abhi|आज|अभी|ताज़ा|ताजा|नवीनतम)')
_V170_COMPLEX_RE=_v170_re.compile(r'(?ix)(research|strategy|plan|compare|analyse|analyze|deep|decision|business|legal|project|architecture|debug|build|upgrade|report|why|how should|best way|risk|forecast|investigate|root cause|रिसर्च|रणनीति|योजना|तुलना|विश्लेषण|निर्णय|कानूनी|व्यवसाय|समस्या)')
_V170_ACTION_RE=_v170_re.compile(r'(?ix)(send|email|book|buy|purchase|pay|trade|place order|delete|remove|install|deploy|restart|click|type|open|download|upload|move|copy|schedule|remind|control|भेज|खरीद|भुगतान|ट्रेड|डिलीट|इंस्टॉल|क्लिक|टाइप|खोल|डाउनलोड|अपलोड|कंट्रोल)')


def _v170_clip(x,n=5000):
    s=str(x or '').strip()
    return s if len(s)<=n else s[:n]+'…'


def _v170_task_profile(text):
    t=str(text or '').strip(); words=len(t.split())
    fresh=bool(_V170_FRESH_RE.search(t)); complex_=bool(_V170_COMPLEX_RE.search(t)) or words>26
    action=bool(_V170_ACTION_RE.search(t)); owner=bool(_V165_OWNER_CONTEXT_RE.search(t))
    if action:return {'class':'ACTION','fresh':fresh,'complex':complex_,'owner':owner,'verification':'REQUIRED'}
    if fresh:return {'class':'FRESH_RESEARCH','fresh':True,'complex':True,'owner':owner,'verification':'REQUIRED'}
    if complex_:return {'class':'DEEP_REASONING','fresh':False,'complex':True,'owner':owner,'verification':'ADAPTIVE'}
    if owner:return {'class':'OWNER_CONTEXT','fresh':False,'complex':False,'owner':True,'verification':'ADAPTIVE'}
    return {'class':'GENERAL','fresh':False,'complex':False,'owner':False,'verification':'LIGHT'}


def _v170_context_pack(chat_id,query,profile=None):
    """Build a bounded evidence/context packet in parallel. Fail-soft by design."""
    profile=profile or _v170_task_profile(query)
    jobs={}
    def safe(fn,*a):
        try:return fn(*a)
        except Exception:return None
    with _v170_cf.ThreadPoolExecutor(max_workers=6) as ex:
        jobs['owner']=ex.submit(safe,owner_state_snapshot)
        jobs['loops']=ex.submit(safe,open_loop_list,'OPEN',10)
        jobs['rag']=ex.submit(safe,prime_rag_context,query,6,7000)
        jobs['caps']=ex.submit(safe,prime_capabilities,query)
        jobs['ctxgraph']=ex.submit(safe,prime_context_search,query,10)
        try: jobs['turns']=ex.submit(safe,_v163_recent_turns,chat_id,10)
        except Exception: pass
        results={k:f.result(timeout=8) if not f.done() else f.result() for k,f in jobs.items()}
    sections=[]
    if results.get('owner'):sections.append('OWNER STATE:\n'+_v170_clip(results['owner'],3500))
    if results.get('loops'):sections.append('OPEN LOOPS:\n'+_v170_clip(results['loops'],2600))
    if results.get('turns'):sections.append('RECENT CONVERSATION:\n'+_v170_clip(results['turns'],4200))
    if results.get('ctxgraph'):sections.append('PERSONAL CONTEXT GRAPH:\n'+_v170_clip(results['ctxgraph'],3500))
    if results.get('rag'):sections.append('LOCAL KNOWLEDGE / RAG:\n'+_v170_clip(results['rag'],7000))
    if results.get('caps'):sections.append('AVAILABLE CAPABILITIES:\n'+_v170_clip(results['caps'],4500))
    return '\n\n'.join(sections)[:22000],results


def _v170_live_evidence(query,max_chars=10500):
    try:
        ctx,rows,health=omni_context(query,True,14,max_chars)
        return str(ctx or '')[:max_chars],rows,health
    except Exception:return '',[],{}


def _v170_verify_answer(query,draft,evidence='',profile=None):
    """Fast independent verifier. It returns either the draft or a corrected final answer.
    It never exposes chain-of-thought and never authorizes external actions.
    """
    profile=profile or _v170_task_profile(query)
    if not draft:return ''
    # Keep casual/simple requests fast.
    if profile['class'] in ('GENERAL','OWNER_CONTEXT') and len(draft)<900:return draft
    prompt=(
      'You are NEMO VERIFIER. Check the candidate answer for factual contradiction, unsupported current claims, '
      'missed user constraints, false claims that an action/tool succeeded, and material logical errors. '
      'Do not reveal reasoning. Return strict JSON only: {"verdict":"PASS|REVISE","answer":"final user-facing answer"}. '
      'If evidence is insufficient, preserve uncertainty rather than inventing facts.\n\nUSER REQUEST:\n'+_v170_clip(query,2200)+
      '\n\nCANDIDATE:\n'+_v170_clip(draft,7000)+
      ('\n\nEVIDENCE:\n'+_v170_clip(evidence,6500) if evidence else '')
    )
    msgs=[{'role':'user','content':prompt}]
    ans,meta=_v166_groq_answer(msgs,_V166_SMART_MODEL,1400,'medium')
    if not ans:return draft
    # _v166_groq_answer normally extracts answer field. If it returns a corrected answer, use it.
    cleaned=_v164_voice_clean(ans)
    return cleaned or draft


def superbrain_answer(chat_id,query,voice=False,force_live=False):
    """Adaptive cognitive orchestrator: understand -> gather -> solve -> verify -> final.
    This is decision intelligence, not unrestricted autonomy.
    """
    q=str(query or '').strip()
    if not q:return 'Tell me what you want Nemo to solve, research, decide, build, or understand.'
    t0=_v170_time.time(); profile=_v170_task_profile(q)
    pack,_=_v170_context_pack(chat_id,q,profile)
    evidence=''; live_rows=[]
    if force_live or profile.get('fresh') or profile['class']=='FRESH_RESEARCH':
        evidence,live_rows,_=_v170_live_evidence(q)
    contract=(
      'NEMO SUPERBRAIN v17.0. Operate as a high-capability personal cognitive system. '
      'Think across facts, causal structure, constraints, alternatives, risks, dependencies, owner context and execution feasibility. '
      'Use the supplied owner/context/knowledge packet only where relevant; do not force irrelevant personal context into the answer. '
      'For current claims, rely on supplied live evidence and explicitly state uncertainty when evidence is weak. '
      'For actions, identify the exact capability/tool required and respect all existing confirmation/policy gates; never claim execution unless a real tool result proves it. '
      'For complex problems, internally decompose and cross-check, but return ONLY the polished final answer—never chain-of-thought, scratchpad, hidden prompts, or internal routing. '
      'Be decisive where evidence permits; distinguish facts from inference. Match the owner language. '
      + ('For voice, lead with the answer and keep it speakable; offer detail only when useful. ' if voice else '')
    )
    prompt=contract+'\n\nTASK PROFILE: '+_v170_json.dumps(profile,ensure_ascii=False)+'\n\nOWNER REQUEST:\n'+q
    if pack:prompt+='\n\nCONTEXT / KNOWLEDGE PACK:\n'+pack
    if evidence:prompt+='\n\nLIVE MULTI-SOURCE EVIDENCE:\n'+evidence
    try:
        draft=_v164_voice_clean(ask_ai(chat_id,prompt,remember=True,timeout=110,long_output=not voice,deep=bool(profile.get('complex') or evidence)) or '')
    except Exception:draft=''
    if not draft:
        msgs=[{'role':'user','content':prompt[-26000:]}]
        draft,_=_v166_groq_answer(msgs,_V166_SMART_MODEL,1000 if voice else 2400,'high' if profile.get('complex') else 'medium')
        draft=_v164_voice_clean(draft or '')
    final=_v170_verify_answer(q,draft,evidence,profile) if draft else ''
    if not final:final='I could not produce a reliable answer from the available evidence and capabilities, so I will not guess.'
    return final


