def _v171_conn():
    c=_v171_sqlite3.connect(_V171_DB,timeout=20);c.row_factory=_v171_sqlite3.Row;return c


def _v171_init():
    c=_v171_conn()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS prime_exec_missions(
      id TEXT PRIMARY KEY, created REAL, updated REAL, chat_id TEXT, objective TEXT,
      status TEXT, confidence REAL DEFAULT 0, risk TEXT DEFAULT 'MEDIUM',
      current_step TEXT DEFAULT '', summary TEXT DEFAULT '', last_error TEXT DEFAULT ''
    );
    CREATE TABLE IF NOT EXISTS prime_exec_steps(
      id TEXT PRIMARY KEY, mission_id TEXT, ord INTEGER, title TEXT, kind TEXT,
      capability TEXT, dependencies_json TEXT, status TEXT, confidence REAL DEFAULT 0,
      risk TEXT DEFAULT 'MEDIUM', verification TEXT DEFAULT '', result TEXT DEFAULT '',
      error TEXT DEFAULT '', created REAL, updated REAL
    );
    CREATE INDEX IF NOT EXISTS idx_exec_steps_mission ON prime_exec_steps(mission_id,ord);
    CREATE TABLE IF NOT EXISTS prime_exec_events(
      id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, mission_id TEXT, step_id TEXT,
      event TEXT, detail TEXT
    );
    """)
    c.commit();c.close()


def _v171_event(mid,event,detail='',sid=''):
    try:
        c=_v171_conn();c.execute('INSERT INTO prime_exec_events(ts,mission_id,step_id,event,detail) VALUES(?,?,?,?,?)',
          (_v171_time.time(),str(mid),str(sid or ''),str(event)[:80],str(detail or '')[:5000]));c.commit();c.close()
    except Exception:pass


def _v171_json_extract(raw,default=None):
    if isinstance(raw,(dict,list)):return raw
    s=str(raw or '').strip()
    for a,b in [('{','}'),('[',']')]:
        i=s.find(a);j=s.rfind(b)
        if i>=0 and j>i:
            try:return _v171_json.loads(s[i:j+1])
            except Exception:pass
    return default


def _v171_capability_digest(query=''):
    try:
        caps=prime_capabilities(query) or prime_capabilities('') or []
        out=[]
        for x in caps[:120]:
            out.append({'name':x.get('name'),'kind':x.get('kind'),'target':x.get('target'),'capabilities':(x.get('capabilities') or [])[:12]})
        return _v170_clip(_v171_json.dumps(out,ensure_ascii=False,default=str),8000)
    except Exception:return '[]'


def _v171_plan_prompt(objective,chat_id=None):
    context=''
    try:context,_=_v170_context_pack(chat_id or OWNER.get('id') or 0,objective,_v170_task_profile(objective))
    except Exception:pass
    return (
      'You are NEMO EXECUTIVE PLANNER v17.1. Convert the owner objective into the smallest reliable dependency-aware plan. '
      'Use THINK/ANALYZE/RESEARCH/SYNTHESIZE/VERIFY for cognitive work. Use ACTION/COMPUTER/BROWSER_ACTION/EMAIL/MESSAGE/FILE_WRITE/DEVICE/DEPLOY/PAYMENT/TRADE for external effects. '
      'External effects are proposals only and must retain existing approval/policy gates. Never invent tool success. '
      'Return STRICT JSON only with this schema: '
      '{"mission_summary":"...","confidence":0.0,"risk":"LOW|MEDIUM|HIGH","steps":['
      '{"title":"...","kind":"THINK|ANALYZE|RESEARCH|SYNTHESIZE|VERIFY|ACTION|COMPUTER|BROWSER_ACTION|EMAIL|MESSAGE|FILE_WRITE|DEVICE|DEPLOY|PAYMENT|TRADE",'
      '"capability":"best existing capability or none","depends_on":[1],"confidence":0.0,"risk":"LOW|MEDIUM|HIGH","verification":"how success is checked"}]}. '
      'Use 2-8 steps. confidence is 0..1. depends_on contains 1-based prior step numbers only. '
      'For ambiguous/high-impact goals, add an ANALYZE or VERIFY step before any external-effect step.\n\nOBJECTIVE:\n'+str(objective)[:5000]+
      '\n\nAVAILABLE CAPABILITY REGISTRY:\n'+_v171_capability_digest(objective)+
      ('\n\nRELEVANT OWNER/KNOWLEDGE CONTEXT:\n'+context[:12000] if context else '')
    )


def _v171_normalize_plan(obj,rawplan):
    d=rawplan if isinstance(rawplan,dict) else {}
    steps=d.get('steps') if isinstance(d.get('steps'),list) else []
    clean=[]
    allowed=_V171_SAFE_KINDS|_V171_EXTERNAL_KINDS
    for i,s in enumerate(steps[:8],1):
        if not isinstance(s,dict):continue
        title=str(s.get('title') or '').strip()[:500]
        if not title:continue
        kind=str(s.get('kind') or 'ANALYZE').upper().strip()
        if kind not in allowed:kind='ANALYZE'
        deps=[]
        for x in (s.get('depends_on') or []):
            try:
                n=int(x)
                if 1<=n<i and n not in deps:deps.append(n)
            except Exception:pass
        try:conf=max(0.0,min(1.0,float(s.get('confidence',0.65))))
        except Exception:conf=.65
        risk=str(s.get('risk') or ('HIGH' if _V171_HIGH_RISK_RE.search(title) else 'MEDIUM')).upper()
        if risk not in ('LOW','MEDIUM','HIGH'):risk='MEDIUM'
        if kind in _V171_EXTERNAL_KINDS and _V171_HIGH_RISK_RE.search(title):risk='HIGH'
        clean.append({'title':title,'kind':kind,'capability':str(s.get('capability') or 'none')[:180],
                      'depends_on':deps,'confidence':conf,'risk':risk,'verification':str(s.get('verification') or 'Verify the observable result before marking complete.')[:600]})
    if not clean:
        clean=[{'title':'Analyze the objective, constraints, evidence needs, and success criteria','kind':'ANALYZE','capability':'superbrain','depends_on':[], 'confidence':.7,'risk':'LOW','verification':'A concrete evidence-based execution plan exists.'},
               {'title':'Synthesize the best next action and required approvals','kind':'SYNTHESIZE','capability':'superbrain','depends_on':[1], 'confidence':.7,'risk':'LOW','verification':'Recommendation maps to real capabilities and does not claim unexecuted actions.'}]
    try:mc=max(0,min(1,float(d.get('confidence',sum(x['confidence'] for x in clean)/len(clean)))))
    except Exception:mc=.65
    risk=str(d.get('risk') or max((x['risk'] for x in clean),key=lambda x:{'LOW':1,'MEDIUM':2,'HIGH':3}[x])).upper()
    if risk not in ('LOW','MEDIUM','HIGH'):risk='MEDIUM'
    return {'mission_summary':str(d.get('mission_summary') or obj)[:1600],'confidence':mc,'risk':risk,'steps':clean}


def exec17_plan(chat_id,objective):
    _v171_init();objective=str(objective or '').strip()
    if not objective:return {'ok':False,'error':'objective required'}
    raw=''
    try:raw=ask_ai(chat_id,_v171_plan_prompt(objective,chat_id),remember=False,timeout=120,deep=True,raw=True) or ''
    except Exception:pass
    plan=_v171_normalize_plan(objective,_v171_json_extract(raw,{}))
    mid='EXEC-'+_v171_uuid.uuid4().hex[:10].upper();now=_v171_time.time()
    c=_v171_conn();c.execute('INSERT INTO prime_exec_missions(id,created,updated,chat_id,objective,status,confidence,risk,summary) VALUES(?,?,?,?,?,?,?,?,?)',
      (mid,now,now,str(chat_id),objective,'PLANNED',plan['confidence'],plan['risk'],plan['mission_summary']))
    ids=[]
    for i,s in enumerate(plan['steps'],1):
        sid='XS-'+_v171_uuid.uuid4().hex[:9].upper();ids.append(sid)
        deps=[ids[n-1] for n in s['depends_on'] if 1<=n<=len(ids)]
        status='WAITING_APPROVAL' if s['kind'] in _V171_EXTERNAL_KINDS else 'READY'
        c.execute('INSERT INTO prime_exec_steps(id,mission_id,ord,title,kind,capability,dependencies_json,status,confidence,risk,verification,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',
          (sid,mid,i,s['title'],s['kind'],s['capability'],_v171_json.dumps(deps),status,s['confidence'],s['risk'],s['verification'],now,now))
    c.commit();c.close();_v171_event(mid,'MISSION_PLANNED',plan['mission_summary'])
    try:open_loop_add('Executive mission '+mid+': '+objective,'MISSION',0,'exec17',{'mission_id':mid})
    except Exception:pass
    return exec17_status(mid)


def exec17_status(mid=''):
    _v171_init();c=_v171_conn()
    if not mid:
        rows=[dict(x) for x in c.execute("SELECT * FROM prime_exec_missions ORDER BY updated DESC LIMIT 12").fetchall()];c.close();return {'ok':True,'missions':rows}
    m=c.execute('SELECT * FROM prime_exec_missions WHERE id=?',(str(mid),)).fetchone()
    if not m:c.close();return {'ok':False,'error':'mission not found'}
    steps=[dict(x) for x in c.execute('SELECT * FROM prime_exec_steps WHERE mission_id=? ORDER BY ord',(str(mid),)).fetchall()]
    events=[dict(x) for x in c.execute('SELECT ts,step_id,event,detail FROM prime_exec_events WHERE mission_id=? ORDER BY id DESC LIMIT 20',(str(mid),)).fetchall()]
    c.close()
    for s in steps:
        try:s['dependencies']=_v171_json.loads(s.pop('dependencies_json') or '[]')
        except Exception:s['dependencies']=[]
    return {'ok':True,'mission':dict(m),'steps':steps,'events':events}


def _v171_ready_step(mid):
    st=exec17_status(mid)
    if not st.get('ok'):return None,st
    done={s['id'] for s in st['steps'] if s['status']=='DONE'}
    for s in st['steps']:
        if s['status'] not in ('READY','FAILED'):continue
        if all(d in done for d in s.get('dependencies',[])):return s,st
    return None,st


def _v171_step_prompt(mission,step,previous):
    return ('NEMO EXECUTIVE WORKER v17.1. Complete exactly this bounded cognitive step. Do not execute external actions. '
            'Do not claim tools/actions succeeded unless a provided real result proves it. Return a concise professional deliverable with facts vs assumptions distinguished.\n\n'
            'MISSION OBJECTIVE:\n'+str(mission.get('objective',''))[:4000]+'\n\nSTEP:\n'+str(step.get('title',''))+
            '\nKIND: '+str(step.get('kind'))+'\nSUCCESS CHECK: '+str(step.get('verification',''))+
            ('\n\nPRIOR COMPLETED STEP RESULTS:\n'+previous[:10000] if previous else ''))


def exec17_run_next(chat_id,mid):
    _v171_init();step,st=_v171_ready_step(mid)
    if not st.get('ok'):return st
    if not step:
        done={s['id'] for s in st['steps'] if s['status']=='DONE'}
        for s in st['steps']:
            if s['status']=='WAITING_APPROVAL' and all(d in done for d in s.get('dependencies',[])):
                g=guardian_action('execute.'+str(s['kind']).lower(),s.get('capability',''),s.get('title',''),actor='owner',context={'mission_id':mid,'step_id':s['id']})
                return {'ok':True,'mission_id':mid,'state':'APPROVAL_REQUIRED','step':s,'guardian':g,
                        'message':'External-effect step is ready, but v17.1 will not execute it silently. Use the existing capability-specific approval/action flow.'}
        if all(s['status']=='DONE' for s in st['steps']):
            c=_v171_conn();c.execute("UPDATE prime_exec_missions SET status='DONE',updated=? WHERE id=?",(_v171_time.time(),mid));c.commit();c.close();_v171_event(mid,'MISSION_DONE','All planned steps completed')
            return {'ok':True,'mission_id':mid,'state':'DONE','message':'Mission cognitive plan is complete.'}
        return {'ok':True,'mission_id':mid,'state':'BLOCKED','message':'No executable cognitive step is ready. Check dependencies or approval-gated steps.'}
    if step['kind'] not in _V171_SAFE_KINDS:return {'ok':True,'mission_id':mid,'state':'APPROVAL_REQUIRED','step':step}
    c=_v171_conn();c.execute("UPDATE prime_exec_steps SET status='RUNNING',updated=?,error='' WHERE id=?",(_v171_time.time(),step['id']));c.execute("UPDATE prime_exec_missions SET status='RUNNING',current_step=?,updated=? WHERE id=?",(step['id'],_v171_time.time(),mid));c.commit();c.close();_v171_event(mid,'STEP_STARTED',step['title'],step['id'])
    previous='\n\n'.join('#'+str(s['ord'])+' '+s['title']+'\n'+str(s.get('result') or '') for s in st['steps'] if s['status']=='DONE')
    try:
        result=superbrain_answer(chat_id,_v171_step_prompt(st['mission'],step,previous),voice=False,force_live=(step['kind']=='RESEARCH'))
        if not result:raise RuntimeError('empty result')
        c=_v171_conn();c.execute("UPDATE prime_exec_steps SET status='DONE',result=?,updated=? WHERE id=?",(str(result)[:16000],_v171_time.time(),step['id']));c.execute('UPDATE prime_exec_missions SET updated=? WHERE id=?',(_v171_time.time(),mid));c.commit();c.close();_v171_event(mid,'STEP_DONE',str(result)[:1200],step['id'])
        return {'ok':True,'mission_id':mid,'state':'STEP_DONE','step_id':step['id'],'title':step['title'],'result':result,'next':exec17_status(mid)}
    except Exception as e:
        err=type(e).__name__+': '+str(e)[:700];c=_v171_conn();c.execute("UPDATE prime_exec_steps SET status='FAILED',error=?,updated=? WHERE id=?",(err,_v171_time.time(),step['id']));c.execute("UPDATE prime_exec_missions SET status='DEGRADED',last_error=?,updated=? WHERE id=?",(err,_v171_time.time(),mid));c.commit();c.close();_v171_event(mid,'STEP_FAILED',err,step['id']);return {'ok':False,'mission_id':mid,'state':'FAILED','step_id':step['id'],'error':err}


def exec17_recover(chat_id,mid,step_id='',failure=''):
    st=exec17_status(mid)
    if not st.get('ok'):return st
    target=next((s for s in st['steps'] if step_id and s['id']==step_id),None)
    if target is None:target=next((s for s in st['steps'] if s['status']=='FAILED'),None)
    if target is None:return {'ok':False,'error':'no failed step found'}
    prompt=('NEMO EXECUTIVE RECOVERY PLANNER. Repair a failed mission step without widening authority. '
            'Return strict JSON only: {"strategy":"RETRY|REPLAN|ASK_OWNER|ABORT","reason":"...","replacement_title":"...","replacement_kind":"THINK|ANALYZE|RESEARCH|SYNTHESIZE|VERIFY"}. '
            'Never convert a blocked external action into hidden execution.\nMISSION: '+str(st['mission'].get('objective',''))[:3000]+
            '\nFAILED STEP: '+str(target.get('title',''))+'\nERROR: '+str(failure or target.get('error') or '')[:2000])
    try:raw=ask_ai(chat_id,prompt,remember=False,timeout=90,deep=True,raw=True) or '';d=_v171_json_extract(raw,{}) or {}
    except Exception:d={}
    strategy=str(d.get('strategy') or 'ASK_OWNER').upper()
    if strategy not in ('RETRY','REPLAN','ASK_OWNER','ABORT'):strategy='ASK_OWNER'
    if strategy=='RETRY':
        c=_v171_conn();c.execute("UPDATE prime_exec_steps SET status='READY',error='',updated=? WHERE id=?",(_v171_time.time(),target['id']));c.execute("UPDATE prime_exec_missions SET status='PLANNED',last_error='',updated=? WHERE id=?",(_v171_time.time(),mid));c.commit();c.close()
    elif strategy=='REPLAN':
        title=str(d.get('replacement_title') or ('Re-evaluate and recover: '+target['title']))[:500];kind=str(d.get('replacement_kind') or 'ANALYZE').upper()
        if kind not in _V171_SAFE_KINDS:kind='ANALYZE'
        sid='XS-'+_v171_uuid.uuid4().hex[:9].upper();c=_v171_conn();ordn=max([s['ord'] for s in st['steps']]+[0])+1;c.execute('INSERT INTO prime_exec_steps(id,mission_id,ord,title,kind,capability,dependencies_json,status,confidence,risk,verification,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',(sid,mid,ordn,title,kind,'superbrain','[]','READY',.6,'MEDIUM','Recovery step produces a verified path forward.',_v171_time.time(),_v171_time.time()));c.execute("UPDATE prime_exec_missions SET status='PLANNED',updated=? WHERE id=?",(_v171_time.time(),mid));c.commit();c.close()
    elif strategy=='ABORT':
        c=_v171_conn();c.execute("UPDATE prime_exec_missions SET status='ABORTED',updated=? WHERE id=?",(_v171_time.time(),mid));c.commit();c.close()
    _v171_event(mid,'RECOVERY_'+strategy,str(d.get('reason') or ''),target['id'])
    return {'ok':True,'mission_id':mid,'strategy':strategy,'reason':str(d.get('reason') or ''),'status':exec17_status(mid)}


def _v171_render_status(st):
    if not st.get('ok'):return 'Executive Brain: '+str(st.get('error','unknown error'))
    if 'missions' in st:
        if not st['missions']:return 'NEMO EXECUTIVE BRAIN\nNo executive missions yet.'
        return 'NEMO EXECUTIVE MISSIONS\n\n'+'\n'.join(str(x['id'])+' — '+str(x['status'])+' — '+str(x['objective'])[:120] for x in st['missions'])
    m=st['mission'];lines=['NEMO EXECUTIVE MISSION '+m['id'],str(m['objective']),'Status: '+str(m['status'])+' | Risk: '+str(m['risk'])+' | Confidence: '+str(round(float(m['confidence'] or 0)*100))+'%','']
    for s in st['steps']:
        icon={'DONE':'✅','RUNNING':'⏳','READY':'▶️','WAITING_APPROVAL':'🛡️','FAILED':'❌'}.get(s['status'],'•')
        lines.append(icon+' '+str(s['ord'])+'. '+str(s['title'])+' ['+str(s['kind'])+']')
    return '\n'.join(lines)


