_HANDLE_V171_PREV=handle
def handle(msg):
    try:
        text=(msg.get('text') or '').strip();cid=msg.get('chat',{}).get('id');low=text.lower()
        if low in ('/exec17','/executive17','/agentic17'):
            send_text(cid,_v171_health_text());return
        if low.startswith('/execplan '):
            r=exec17_plan(cid,text[len('/execplan '):].strip());send_text(cid,_v171_render_status(r));return
        if low=='/execstatus':send_text(cid,_v171_render_status(exec17_status()));return
        if low.startswith('/execstatus '):send_text(cid,_v171_render_status(exec17_status(text.split(None,1)[1].strip())));return
        if low.startswith('/execrun '):
            mid=text.split(None,1)[1].strip();r=exec17_run_next(cid,mid)
            if r.get('state')=='STEP_DONE':send_text(cid,'✅ '+str(r.get('title'))+'\n\n'+str(r.get('result'))[:3400]+'\n\n'+_v171_render_status(r.get('next') or exec17_status(mid)))
            else:send_text(cid,_v170_clip(_v171_json.dumps(r,ensure_ascii=False,default=str),3800))
            return
        if low.startswith('/execrecover '):
            parts=text.split(None,2);mid=parts[1] if len(parts)>1 else '';failure=parts[2] if len(parts)>2 else ''
            r=exec17_recover(cid,mid,'',failure);send_text(cid,_v170_clip(_v171_json.dumps(r,ensure_ascii=False,default=str),3800));return
    except Exception as e:
        try:send_text(cid,'Executive Brain error: '+type(e).__name__+': '+str(e)[:180])
        except Exception:pass
        return
    return _HANDLE_V171_PREV(msg)


_PRIME_REGRESSION_V171_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V171_PREV();r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v170-version',)];extra=[]
    def add(n,f):
        try:ok=bool(f());d='ok' if ok else 'false'
        except Exception as e:ok=False;d=type(e).__name__+': '+str(e)[:150]
        extra.append({'name':n,'ok':ok,'detail':d})
    add('v171-version',lambda:VERSION=='17.1')
    add('v171-init',lambda:(_v171_init() is None))
    add('v171-planner-callable',lambda:callable(exec17_plan) and callable(exec17_run_next))
    add('v171-recovery-callable',lambda:callable(exec17_recover))
    add('v171-safe-kinds',lambda:'RESEARCH' in _V171_SAFE_KINDS and 'PAYMENT' not in _V171_SAFE_KINDS)
    add('v171-external-gated',lambda:'PAYMENT' in _V171_EXTERNAL_KINDS and 'TRADE' in _V171_EXTERNAL_KINDS)
    add('v171-guardian-preserved',lambda:callable(guardian_action) and callable(prime_policy_decide))
    add('v171-no-arbitrary-shell',lambda:'subprocess' not in exec17_run_next.__code__.co_names and 'system' not in exec17_run_next.__code__.co_names)
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r


