# Compatibility-first voice upgrade for the existing Windows companion.
# - one-roundtrip audio->STT->brain endpoint
# - deterministic transcript cleanup and duplicate suppression
# - session telemetry and health
# - chunk-friendly TTS endpoint
# - no expansion of computer/device/trading authority
VERSION='18.1'
import threading as _v181_threading
import time as _v181_time
import re as _v181_re

_V181_SESSIONS={}
_V181_LOCK=_v181_threading.RLock()
_V181_DUP_SEC=1.15
_V181_FILLER=_v181_re.compile(r"(?i)^\s*(?:uh+|um+|hmm+|hm+|haan+|ha+|okay+|ok+|achha+|accha+|अच्छा|हम्म+|हाँ+)\s*[.!?]*\s*$")

def _v181_session(device_id):
    did=str(device_id or 'unknown')[:128]
    with _V181_LOCK:
        return _V181_SESSIONS.setdefault(did,{'turns':0,'duplicates':0,'last_text':'','last_ts':0.0,'stt_ms':0,'brain_ms':0,'turn_ms':0,'route':'','provider':''})

def _v181_clean_transcript(text):
    t=' '.join(str(text or '').replace('\x00',' ').split()).strip()
    # Conservative repair only for known owner command vocabulary.
    low=t.lower()
    fixes={'banding':'pending','bending':'pending','pendding':'pending','nemu':'nemo','nimo':'nemo'}
    if len(t.split())<=8:
        for a,b in fixes.items():
            low=_v181_re.sub(r'\b'+_v181_re.escape(a)+r'\b',b,low)
        # Preserve original script/case unless a repair actually changed the phrase.
        if low!=t.lower(): t=low
    return t[:5000]

def _v181_is_duplicate(device_id,text):
    now=_v181_time.time(); st=_v181_session(device_id); norm=' '.join(str(text or '').lower().split())
    with _V181_LOCK:
        dup=bool(norm and norm==st.get('last_text') and now-float(st.get('last_ts') or 0)<_V181_DUP_SEC)
        if dup: st['duplicates']=int(st.get('duplicates') or 0)+1
        else: st['last_text']=norm;st['last_ts']=now
    return dup

def _v181_voice_turn(device_id,audio_b64):
    t0=_v181_time.time(); txt,stt_ms,err=_v166_audio_to_text(audio_b64)
    txt=_v181_clean_transcript(txt)
    if err:return {'ok':False,'error':err,'stt_ms':stt_ms}
    if not txt:return {'ok':False,'error':'no speech','stt_ms':stt_ms}
    if _v181_is_duplicate(device_id,txt):return {'ok':False,'error':'duplicate echo','text':txt,'stt_ms':stt_ms,'suppressed':True}
    # Extremely short acoustic backchannels are not sent into owner memory/brain by default.
    if _V181_FILLER.match(txt):return {'ok':False,'error':'backchannel','text':txt,'stt_ms':stt_ms,'suppressed':True}
    cid=OWNER.get('id') or 0
    out=_v166_voice_reply(cid,txt,device_id)
    out['ok']=True;out['text']=txt;out['stt_ms']=stt_ms;out['turn_ms']=int((_v181_time.time()-t0)*1000);out['voice_version']='18.1'
    st=_v181_session(device_id)
    with _V181_LOCK:
        st['turns']=int(st.get('turns') or 0)+1;st['stt_ms']=stt_ms;st['brain_ms']=int(out.get('brain_ms') or 0);st['turn_ms']=out['turn_ms'];st['route']=str(out.get('route') or '');st['provider']=str(out.get('provider') or '')
    return out

_BUILD_WEB_APP_V181_PREV=build_web_app
def build_web_app():
    app=_BUILD_WEB_APP_V181_PREV()
    try:
        from flask import request,jsonify
        @app.route('/api/voice18/ping',methods=['POST'])
        def _v181_ping():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '');tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            return jsonify({'ok':True,'version':VERSION,'voice':'18.1','transport':'single-roundtrip','adaptive_client_vad':True,'chunked_tts_client':True,'semantic_backchannel_filter':True,'authority':'unchanged'})
        @app.route('/api/voice18/turn',methods=['POST'])
        def _v181_turn_route():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '');tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            return jsonify(_v181_voice_turn(did,d.get('audio_b64')))
        @app.route('/api/voice18/tts',methods=['POST'])
        def _v181_tts_route():
            t0=_v181_time.time();d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '');tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            text=str(d.get('text') or '').strip()[:1800]
            if not text:return jsonify({'ok':False,'error':'empty text'}),400
            try:
                audio=_v162_make_tts(text)
                out={'audio_mp3_b64':audio}
                out['ok']=True;out['tts_ms']=int((_v181_time.time()-t0)*1000);out['voice_version']='18.1';return jsonify(out)
            except Exception as e:return jsonify({'ok':False,'error':type(e).__name__}),500
        @app.route('/api/voice18/session',methods=['POST'])
        def _v181_session_route():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '');tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            return jsonify({'ok':True,'session':dict(_v181_session(did))})
    except Exception:pass
    return app

