# ==================== v18.1.2 VOICE + VISION ROUTER REPAIR ====================
VERSION='18.1.2'
import re as _v1812_re, time as _v1812_time

_V1812_SCREEN_RE=_v1812_re.compile(
    r'\b(screen|screenshot|display|monitor|window|what(?:\'s| is) (?:on|going on) my screen|'
    r'what do you see|see my screen|analy[sz]e (?:my )?screen|'
    r'screen par|screen pe|स्क्रीन|स्क्रीन पर|स्क्रीन पे)\b',_v1812_re.I)
_V1812_TEST_TASK_RE=_v1812_re.compile(
    r'(test|demo|example|sample|dummy|www\.eponer\.com|download a video of cat)',_v1812_re.I)

def _v1812_screen_intent(text):
    return bool(_V1812_SCREEN_RE.search(str(text or '')))

def _v1812_hinglish_style(text):
    t=str(text or '')
    latin=len(_v1812_re.findall(r'[A-Za-z]',t))
    deva=len(_v1812_re.findall(r'[\u0900-\u097F]',t))
    if latin>=4 and deva==0:return 'HINGLISH_LATIN'
    if latin>=2 and deva>0:return 'HINGLISH_MIXED'
    if deva>0:return 'HINDI'
    return 'ENGLISH'

def _v1812_voice_style_instruction(text):
    st=_v1812_hinglish_style(text)
    if st=='HINGLISH_LATIN':
        return ('Reply naturally in Roman-script Hinglish, matching the user. '
                'Do not switch to Urdu script or formal Devanagari unless asked.')
    if st=='HINGLISH_MIXED':
        return ('Reply in natural Hindi/Hinglish matching the user’s mixed Devanagari + English style. '
                'Never use Urdu/Perso-Arabic script unless explicitly requested.')
    if st=='HINDI':
        return 'Reply naturally in Hindi Devanagari. Never use Urdu/Perso-Arabic script unless explicitly requested.'
    return 'Reply naturally in English unless the user clearly switches language.'

# Wrap the full-brain lane to preserve spoken language style.
_V1812_FULL_BRAIN_PREV=_v166_full_brain
def _v166_full_brain(chat_id,raw,turns):
    if _v1812_screen_intent(raw):
        return '__NEMO_SCREEN_INTENT__'
    styled=(str(raw or '')+'\n\nVOICE LANGUAGE STYLE: '+_v1812_voice_style_instruction(raw))
    return _V1812_FULL_BRAIN_PREV(chat_id,styled,turns)

def _v1812_clean_owner_items(items):
    out=[]
    for x in (items or []):
        blob=''
        try:
            blob=' '.join(str(x.get(k,'')) for k in ('id','title','objective','goal','text','description','status','source','meta'))
        except Exception: blob=str(x)
        if _V1812_TEST_TASK_RE.search(blob):continue
        out.append(x)
    return out

# Authoritative fast screen lane. Screenshot is already attached; never ask for one.
def _v1812_fast_screen_answer(img,question='What is on my screen?'):
    prompt=(
      'You are Nemo Desktop Vision. A CURRENT screenshot is already attached. '
      'Answer ONLY from the screenshot. Never ask the user to upload/share/describe a screenshot. '
      'Be concise and operational: identify foreground app, important visible state, and what the user likely needs next. '
      'If text is unreadable say exactly which part is unreadable. Question: '+str(question or '')[:1200])
    # Prefer direct vision model list, bounded timeout; no Superbrain/RAG/research.
    try:
        ans=ask_ai(0,prompt,image_b64=img,remember=False,timeout=28,long_output=False,
                   models_override=VISION_MODELS[:1],deep=False)
        if ans and not _v1812_re.search(r'(share|upload|provide).{0,25}screenshot',ans,_v1812_re.I):
            return ans
    except Exception: pass
    try:
        ans=ask_ai(0,prompt,image_b64=img,remember=False,timeout=38,long_output=False,
                   models_override=VISION_MODELS,deep=False)
        if ans:return ans
    except Exception:pass
    return 'I received the screen capture but the vision provider did not return a reliable result.'

