# =============================================================================
# NEMO v18.2 — VOICE OS 3.0 / SMART REALTIME CONVERSATION ENGINE
# New architecture rather than another VAD/TTS patch:
# STT candidate selection -> deterministic intent router -> specialist voice brain
# -> spoken-style response -> authoritative client event -> pipelined TTS.
# Existing Guardian / policy / computer approval rails remain authoritative.
# =============================================================================
VERSION='18.2'
import re as _v182_re, time as _v182_time, threading as _v182_threading

_V182_LOCK=_v182_threading.RLock()
_V182_SESSIONS={}
_V182_ARABIC=_v182_re.compile(r'[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF]')
_V182_DEVA=_v182_re.compile(r'[\u0900-\u097F]')
_V182_LATIN=_v182_re.compile(r'[A-Za-z]')
_V182_SCREEN=_v182_re.compile(
    r"(screen|screenshot|display|monitor|what(?:'s| is) (?:on|going on) (?:my|the) screen|"
    r"what do you see|see my screen|analy[sz]e (?:my )?screen|"
    r"screen par|screen pe|स्क्रीन|स्क्रीन पर|स्क्रीन पे)",_v182_re.I)
_V182_PENDING=_v182_re.compile(
    r"(pending|open loops?|remaining tasks?|unfinished|what.*left|"
    r"mera pending|mere pending|pending kaam|बाकी काम|पेंडिंग|लंबित)",_v182_re.I)
_V182_SOCIAL=_v182_re.compile(
    r"^\s*(hi|hello|hey|thanks?|thank you|good morning|good evening|"
    r"kaise ho|kya haal|shukriya|namaste|नमस्ते|धन्यवाद|कैसे हो)[!?. ]*$",_v182_re.I)
_V182_COMPLEX=_v182_re.compile(
    r"(research|deep|analyse|analyze|strategy|compare|business plan|legal|architecture|"
    r"debug|build|upgrade|report|financially viable|root cause|decision|risk analysis|"
    r"deeply|detail mein|विस्तार|विश्लेषण)",_v182_re.I)

def _v182_session(device_id):
    did=str(device_id or 'unknown')[:128]
    with _V182_LOCK:
        return _V182_SESSIONS.setdefault(did,{
            'turns':0,'last_text':'','last_reply':'','last_route':'','last_style':'ENGLISH',
            'stt_ms':0,'brain_ms':0,'turn_ms':0,'screen_turns':0,'pending_turns':0
        })

def _v182_script_style(text):
    t=str(text or '')
    a=len(_V182_ARABIC.findall(t));d=len(_V182_DEVA.findall(t));l=len(_V182_LATIN.findall(t))
    if a:return 'URDU_SCRIPT'
    if d and l:return 'HINGLISH_MIXED'
    if d:return 'HINDI'
    # Roman Hindi/Hinglish hints. English sentences should not be forced to Hinglish.
    low=t.lower()
    roman=('mera ','mere ','mujhe ','batao','kya ','kaam','karna','hai','nahi','haan','aaj ','kal ','screen pe','screen par','karo','kholo','dikhao')
    hits=sum(1 for x in roman if x in low)
    if hits>=2:return 'HINGLISH_LATIN'
    return 'ENGLISH'

def _v182_candidate_score(text, forced_hi=False):
    t=' '.join(str(text or '').split()).strip()
    if not t:return -9999
    score=min(len(t),120)*0.05
    if _V182_ARABIC.search(t):score-=60
    if _V182_DEVA.search(t):score+=8
    if _V182_LATIN.search(t):score+=5
    low=t.lower()
    for kw in ('nemo','pending','laptop','screen','telegram','nifty','sensex','udaipur','rajasthan','report','chrome'):
        if kw in low:score+=2
    if forced_hi and not _V182_ARABIC.search(t):score+=3
    return score

def _v182_transcribe_smart(path):
    """Accuracy-first candidate selection with a Hindi recovery pass only when useful."""
    t0=_v182_time.time();cands=[]
    # Pass A: normal multilingual Whisper.
    for model in ('whisper-large-v3','whisper-large-v3-turbo'):
        txt=_v1811_groq_transcribe_request(path,model,prompt=_V167_STT_PROMPT)
        if txt:
            cands.append((txt,False,model))
            # If clean Latin/Devanagari and non-trivial, large-v3 is usually enough.
            if model=='whisper-large-v3' and not _V182_ARABIC.search(txt) and len(txt.split())>=3:
                break
    # Pass B: Hindi-forced recovery for Urdu script or obviously Indian/Hinglish ambiguity.
    need_hi=any(_V182_ARABIC.search(x[0]) for x in cands)
    if need_hi or not cands:
        p=('Indian Hindi/Hinglish speech. Transcribe the SAME audio faithfully. '
           'Use Devanagari for Hindi and Latin for English words. NEVER use Urdu/Perso-Arabic script. '
           'Do not translate. Keep names and technical words such as Nemo, pending, laptop, screen, Telegram, '
           'Nifty, Sensex, Udaipur, Rajasthan in their natural form.')
        txt=_v1811_groq_transcribe_request(path,'whisper-large-v3',language='hi',prompt=p)
        if txt:cands.append((txt,True,'whisper-large-v3/hi'))
    if not cands:return '',int((_v182_time.time()-t0)*1000),''
    best=max(cands,key=lambda x:_v182_candidate_score(x[0],x[1]))
    text=_v181_clean_transcript(best[0])
    return text,int((_v182_time.time()-t0)*1000),best[2]

def _v182_audio_to_text(audio_b64):
    try:raw=_v166_b64.b64decode(str(audio_b64 or ''))
    except Exception:return '',0,'bad audio',''
    if not raw or len(raw)>8*1024*1024:return '',0,'audio size',''
    fd,p=_v166_tmp.mkstemp(suffix='.wav');_v166_os.close(fd)
    try:
        with open(p,'wb') as f:f.write(raw)
        txt,ms,model=_v182_transcribe_smart(p)
    finally:
        try:_v166_os.unlink(p)
        except Exception:pass
    return txt,ms,('',model)[bool(txt)],model

def _v182_intent(text):
    t=str(text or '').strip()
    if _V182_SCREEN.search(t):return {'kind':'SCREEN','route':'SCREEN','brain':False}
    # Preserve the safe Windows intent router, but let screen be handled above.
    try:
        di=_v169_desktop_intent(t)
        if di:return {'kind':'DESKTOP','route':'DESKTOP','brain':False,'desktop_intent':di}
    except Exception:pass
    if _V182_PENDING.search(t):return {'kind':'PENDING','route':'OWNER-STATE','brain':False}
    if _V182_SOCIAL.match(t):return {'kind':'SOCIAL','route':'SOCIAL','brain':True}
    if _V182_COMPLEX.search(t):return {'kind':'COMPLEX','route':'SUPERBRAIN','brain':True}
    return {'kind':'CHAT','route':'SMART','brain':True}

def _v182_spoken_instruction(style):
    if style=='HINGLISH_LATIN':
        return ('Reply in natural Roman Hinglish, like a smart Indian personal assistant. '
                'Use simple English technical words naturally. Do not use Urdu script or formal Hindi unless asked.')
    if style=='HINGLISH_MIXED':
        return ('Reply in natural Hindi/Hinglish matching the user’s mixed Devanagari-English style. '
                'Never switch to Urdu/Perso-Arabic script unless explicitly requested.')
    if style=='HINDI':
        return 'Reply in natural conversational Hindi Devanagari. Avoid overly formal Hindi and never use Urdu script unless asked.'
    return 'Reply in natural concise spoken English.'

def _v182_voice_trim(text,limit=850):
    t=' '.join(str(text or '').split()).strip()
    # Voice should not dump essay-length answers unless the owner asks for detail.
    if len(t)<=limit:return t
    cut=t[:limit]
    k=max(cut.rfind('. '),cut.rfind('? '),cut.rfind('! '),cut.rfind('। '))
    if k>420:cut=cut[:k+1]
    return cut.rstrip()+' I can continue if you want more detail.'

def _v182_pending_items():
    """Return only current-looking owner loops/tasks; filter obvious demo/test contamination."""
    rows=[]
    try:
        for x in open_loop_list(limit=30) or []:
            rows.append(x)
    except Exception:pass
    try:
        rows=_v1812_clean_owner_items(rows)
    except Exception:pass
    clean=[]
    now=_v182_time.time()
    for x in rows:
        try:
            status=str(x.get('status') or '').upper()
            if status in ('DONE','COMPLETED','CLOSED','ARCHIVED','CANCELLED'):continue
            blob=' '.join(str(x.get(k,'')) for k in ('title','objective','goal','text','description','source','meta'))
            if _V1812_TEST_TASK_RE.search(blob):continue
            clean.append(x)
        except Exception:continue
    return clean[:8]

def _v182_render_pending(style):
    items=_v182_pending_items()
    if not items:
        if style in ('HINGLISH_LATIN','HINGLISH_MIXED'):
            return 'Abhi mujhe koi verified active pending task nahi mil raha. Main purane test ya demo tasks ko pending nahi maan raha.'
        if style=='HINDI':
            return 'अभी मुझे कोई सत्यापित सक्रिय पेंडिंग काम नहीं मिल रहा। पुराने टेस्ट या डेमो काम मैंने हटा दिए हैं।'
        return 'I do not see any verified active pending task right now. Old test or demo tasks are excluded.'
    names=[]
    for x in items:
        name=''
        for k in ('title','objective','goal','text','description'):
            v=str(x.get(k,'')).strip()
            if v:name=v;break
        if name:names.append(name[:150])
    if not names:return _v182_render_pending(style)
    if style=='HINGLISH_LATIN':
        return 'Aapke verified pending kaam hain: '+ '; '.join('%d) %s'%(i+1,n) for i,n in enumerate(names))
    if style in ('HINDI','HINGLISH_MIXED'):
        return 'आपके verified pending काम हैं: '+ '; '.join('%d) %s'%(i+1,n) for i,n in enumerate(names))
    return 'Your verified pending tasks are: '+ '; '.join('%d) %s'%(i+1,n) for i,n in enumerate(names))

def _v182_brain(chat_id,text,style,intent,device_id=''):
    t0=_v182_time.time()
    kind=intent.get('kind')
    if kind=='PENDING':
        return _v182_render_pending(style),'owner-state',int((_v182_time.time()-t0)*1000)
    if kind=='SCREEN':
        return '', 'screen-bypass', 0
    if kind=='DESKTOP':
        return 'Ready on your laptop.','local-intent-router',0
    # A voice-specific prompt: answer first, spoken not essay-like, no fake capabilities.
    instr=(
      'NEMO VOICE OS 3.0. You are speaking live with the owner. '
      'Answer the current utterance directly. Use recent conversation only when needed. '
      'Never invent pending tasks, current facts, screen contents, completed actions, emails, trades, files or device actions. '
      'For screen questions, the client vision lane is authoritative. '
      'Keep normal voice answers short: usually 1-4 sentences. '
      +_v182_spoken_instruction(style)+'\nOwner: '+str(text)[:2600])
    if kind=='SOCIAL':
        msgs=[{'role':'user','content':instr}]
        ans,diag=_v166_groq_answer(msgs,_V166_FAST_MODEL,220,'low')
        provider='groq-20b'
    elif kind=='COMPLEX':
        try:ans=superbrain_answer(chat_id,str(text),voice=True,force_live=False);diag={}
        except Exception:ans='';diag={}
        provider='nemo-superbrain'
    else:
        # 120B for ordinary useful conversation, but without the huge owner/RAG stack.
        msgs=[]
        try:
            for x in _v163_recent_turns(chat_id,6)[-4:]:
                z=str(x.get('text') or '').strip()
                if z:msgs.append({'role':'assistant' if str(x.get('role'))=='assistant' else 'user','content':z[:900]})
        except Exception:pass
        msgs.append({'role':'user','content':instr})
        ans,diag=_v166_groq_answer(msgs,_V166_SMART_MODEL,520,'medium')
        provider='groq-120b'
    ans=_v164_voice_clean(ans or '')
    if not ans:
        try:ans=_v164_voice_clean(_V1812_FULL_BRAIN_PREV(chat_id,str(text),[]) or '');provider+='->fallback'
        except Exception:ans=''
    ans=_v182_voice_trim(ans or 'Please say that once more.')
    try:
        continuity_add_turn(chat_id,'user',str(text))
        continuity_add_turn(chat_id,'assistant',ans)
    except Exception:pass
    return ans,provider,int((_v182_time.time()-t0)*1000)

def _v182_turn(device_id,audio_b64):
    t0=_v182_time.time()
    txt,stt_ms,err,stt_model=_v182_audio_to_text(audio_b64)
    if err and not txt:return {'ok':False,'error':err,'stt_ms':stt_ms}
    if not txt:return {'ok':False,'error':'no speech','stt_ms':stt_ms}
    if _v181_is_duplicate(device_id,txt):
        return {'ok':False,'error':'duplicate echo','text':txt,'stt_ms':stt_ms,'suppressed':True}
    if _V181_FILLER.match(txt):
        return {'ok':False,'error':'backchannel','text':txt,'stt_ms':stt_ms,'suppressed':True}
    style=_v182_script_style(txt)
    intent=_v182_intent(txt)
    # SCREEN is returned immediately. Client captures current screenshot. Zero brain waste.
    if intent.get('kind')=='SCREEN':
        out={'ok':True,'text':txt,'reply':'','route':'SCREEN','provider':'local-screen-router',
             'brain_ms':0,'desktop_intent':{'kind':'screen_describe','question':txt},
             'style':style,'stt_ms':stt_ms,'stt_model':stt_model}
    elif intent.get('kind')=='DESKTOP':
        out={'ok':True,'text':txt,'reply':'Ready on your laptop.','route':'DESKTOP','provider':'local-intent-router',
             'brain_ms':0,'desktop_intent':intent.get('desktop_intent'),'style':style,
             'stt_ms':stt_ms,'stt_model':stt_model}
    else:
        cid=OWNER.get('id') or 0
        reply,provider,brain_ms=_v182_brain(cid,txt,style,intent,device_id)
        out={'ok':True,'text':txt,'reply':reply,'route':intent.get('route'),'provider':provider,
             'brain_ms':brain_ms,'style':style,'stt_ms':stt_ms,'stt_model':stt_model}
    out['turn_ms']=int((_v182_time.time()-t0)*1000);out['voice_version']='18.2'
    st=_v182_session(device_id)
    with _V182_LOCK:
        st['turns']+=1;st['last_text']=txt;st['last_reply']=out.get('reply','');st['last_route']=out.get('route','')
        st['last_style']=style;st['stt_ms']=stt_ms;st['brain_ms']=out.get('brain_ms',0);st['turn_ms']=out['turn_ms']
        if out.get('route')=='SCREEN':st['screen_turns']+=1
        if out.get('route')=='OWNER-STATE':st['pending_turns']+=1
    return out

def _v182_screen_answer(img,question):
    prompt=(
      'NEMO DESKTOP VISION. A current Windows screenshot is attached RIGHT NOW. '
      'Never ask for another screenshot. Answer the spoken question directly. '
      'Identify the foreground app/window, important visible status/error/text, and the next useful observation. '
      'Do not infer hidden content or claim an action was performed. Keep it concise for speech. '
      'Question: '+str(question or 'What is on my screen?')[:1000])
    t0=_v182_time.time();ans='';provider=''
    # Keep the call narrow. No owner memory, no RAG, no verification loop.
    try:
        ans=ask_ai(OWNER.get('id') or 0,prompt,image_b64=img,remember=False,timeout=30,
                   long_output=False,models_override=VISION_MODELS[:1],deep=False) or ''
        provider=str(VISION_MODELS[0] if VISION_MODELS else 'vision')
    except Exception:ans=''
    if not ans:
        try:
            ans=ask_ai(OWNER.get('id') or 0,prompt,image_b64=img,remember=False,timeout=38,
                       long_output=False,models_override=VISION_MODELS,deep=False) or ''
            provider='vision-fallback'
        except Exception:ans=''
    ans=_v182_voice_trim(_v164_voice_clean(ans or ''),700)
    bad=_v182_re.search(r'(share|upload|provide).{0,35}screenshot',ans or '',_v182_re.I)
    if bad:ans=''
    return {'ok':bool(ans),'reply':ans or 'I captured the screen, but the vision provider did not return a reliable answer.',
            'provider':provider or 'vision','vision_ms':int((_v182_time.time()-t0)*1000),'authoritative':True}

_BUILD_WEB_APP_V182_PREV=build_web_app
def build_web_app():
    app=_BUILD_WEB_APP_V182_PREV()
    try:
        from flask import request,jsonify
        @app.route('/api/voice182/ping',methods=['POST'])
        def _v182_ping():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '')
            tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            return jsonify({'ok':True,'version':VERSION,'voice_os':'3.0','transport':'smart-turn',
                            'screen_bypass':True,'smart_stt':True,'spoken_style':True,'authority':'unchanged'})
        @app.route('/api/voice182/turn',methods=['POST'])
        def _v182_turn_route():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '')
            tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            return jsonify(_v182_turn(did,d.get('audio_b64')))
        @app.route('/api/voice182/tts',methods=['POST'])
        def _v182_tts_route():
            t0=_v182_time.time();d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '')
            tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            text=str(d.get('text') or '').strip()[:1400]
            if not text:return jsonify({'ok':False,'error':'empty text'}),400
            try:
                audio=_v162_make_tts(text)
                return jsonify({'ok':True,'audio_mp3_b64':audio,'tts_ms':int((_v182_time.time()-t0)*1000),'voice_version':'18.2'})
            except Exception as e:return jsonify({'ok':False,'error':type(e).__name__}),500
        @app.route('/api/voice182/screen',methods=['POST'])
        def _v182_screen_route():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '')
            tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            img=str(d.get('image_b64') or '')
            if len(img)<200 or len(img)>6*1024*1024:return jsonify({'ok':False,'error':'invalid screenshot'}),400
            return jsonify(_v182_screen_answer(img,str(d.get('question') or 'What is on my screen?')))
        @app.route('/api/voice182/session',methods=['POST'])
        def _v182_session_route():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '')
            tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            return jsonify({'ok':True,'session':dict(_v182_session(did))})
    except Exception as e:
        try:print('v18.2 voice routes:',type(e).__name__,str(e)[:180])
        except Exception:pass
    return app

