# =============================================================================
# v18.2.1 — VISION PROVIDER REPAIR
# Root cause: the old primary Nano-Omni/free route can return unusable/empty
# visual output, while openrouter/free is nondeterministic. Use Groq's current
# dedicated Qwen vision models first, then explicit OpenRouter multimodal models,
# then openrouter/free only as last resort.
# =============================================================================
VERSION='18.2.1'
import base64 as _v1821_b64, re as _v1821_re, time as _v1821_time

_V1821_GROQ_VISION=('qwen/qwen3.6-27b','qwen/qwen3.8-27b')
_V1821_OR_VISION=(
    'google/gemma-4-31b-it:free',
    'google/gemma-4-26b-a4b-it:free',
    'openrouter/free',
)

def _v1821_clean_vision_text(x):
    t=' '.join(str(x or '').split()).strip()
    if not t:return ''
    low=t.lower()
    bad=(
      'user safety: safe','response safety: safe','safe/unsafe',
      'i cannot see images','i can’t see images','i cannot view images',
      'please share a screenshot','please upload a screenshot',
      'please provide a screenshot'
    )
    if any(z in low for z in bad):return ''
    if len(t)<25:return ''
    return t

def _v1821_groq_vision(img_b64,question,model):
    if not GROQ_KEY:return ''
    try:
        raw=_v1821_b64.b64decode(str(img_b64 or ''),validate=False)
        if not raw:return ''
        # Windows client sends JPEG; keep MIME explicit.
        data_uri='data:image/jpeg;base64,'+_v1821_b64.b64encode(raw).decode('ascii')
        prompt=(
          'You are Nemo Desktop Vision. Analyze the CURRENT attached Windows screenshot. '
          'Never ask for a screenshot because it is already attached. '
          'Answer the user directly and concisely for speech. Identify the foreground app/window, '
          'important visible status/error/text, and useful next observation. Do not invent hidden content. '
          'Question: '+str(question or 'What is on my screen?')[:900])
        body={
          'model':model,
          'messages':[{'role':'user','content':[
              {'type':'text','text':prompt},
              {'type':'image_url','image_url':{'url':data_uri}}
          ]}],
          'temperature':0.1,
          'max_completion_tokens':500
        }
        r=requests.post('https://api.groq.com/openai/v1/chat/completions',
            headers={'Authorization':'Bearer '+GROQ_KEY,'Content-Type':'application/json'},
            json=body,timeout=18)
        if r.status_code!=200:return ''
        j=r.json() or {}
        msg=((j.get('choices') or [{}])[0].get('message') or {})
        return _v1821_clean_vision_text(msg.get('content'))
    except Exception:
        return ''

def _v1821_openrouter_vision(img_b64,question,model):
    try:
        ans=ask_ai(OWNER.get('id') or 0,
          ('A CURRENT Windows screenshot is attached. Analyze it now. Never ask for another screenshot. '
           'Give a concise spoken answer: foreground app/window, important visible status/error/text, '
           'and the most useful observation. Question: '+str(question or '')[:900]),
          image_b64=img_b64,remember=False,timeout=22,long_output=False,
          models_override=[model],deep=False) or ''
        return _v1821_clean_vision_text(ans)
    except Exception:return ''

def _v182_screen_answer(img,question):
    t0=_v1821_time.time();attempts=[]
    # 1. Groq dedicated vision: fast and deterministic.
    for model in _V1821_GROQ_VISION:
        st=_v1821_time.time();ans=_v1821_groq_vision(img,question,model)
        attempts.append((model,bool(ans),int((_v1821_time.time()-st)*1000)))
        if ans:
            return {'ok':True,'reply':_v182_voice_trim(ans,700),'provider':'groq:'+model,
                    'vision_ms':int((_v1821_time.time()-t0)*1000),'authoritative':True,
                    'attempts':attempts}
    # 2. Explicit OpenRouter multimodal models; random router only last.
    for model in _V1821_OR_VISION:
        st=_v1821_time.time();ans=_v1821_openrouter_vision(img,question,model)
        attempts.append((model,bool(ans),int((_v1821_time.time()-st)*1000)))
        if ans:
            return {'ok':True,'reply':_v182_voice_trim(ans,700),'provider':'openrouter:'+model,
                    'vision_ms':int((_v1821_time.time()-t0)*1000),'authoritative':True,
                    'attempts':attempts}
    return {'ok':False,
            'reply':'I captured your screen correctly, but every configured vision provider failed this turn.',
            'provider':'vision-exhausted','vision_ms':int((_v1821_time.time()-t0)*1000),
            'authoritative':True,'attempts':attempts}

def _v1821_health_text():
    return ('NEMO v18.2.1 VISION PROVIDER REPAIR\n'
            'Groq Qwen 3.6 Vision primary: READY\n'
            'Groq Qwen 3.8 Vision fallback: READY\n'
            'Explicit OpenRouter multimodal fallback: READY\n'
            'openrouter/free: LAST RESORT ONLY\n'
            'Empty/moderation/non-visual response rejection: READY\n'
            'Voice OS 3.0 intent-first screen bypass: PRESERVED\n'
            'Computer-use approval rails: PRESERVED')

