# =============================================================================
# NEMO v18.4 — LEGEND VOICE + GENIUS CONTROL BRAIN
# Adds a conversational control compiler, context-aware follow-up commands,
# explain-before-act mode, voice modes, and safe chained laptop plans.
# No expansion of external authority: sensitive/high-impact actions remain gated.
# =============================================================================
VERSION='18.4'
import re as _v184_re, time as _v184_time, threading as _v184_threading
_V184_LOCK=_v184_threading.RLock()
_V184_CTX={}

def _v184_ctx(device_id):
    k=str(device_id or 'owner')
    with _V184_LOCK:
        return _V184_CTX.setdefault(k,{
          'mode':'NORMAL','last_app':'','last_control':'','last_query':'',
          'last_screen_question':'','last_plan':None,'turn':0,'updated':_v184_time.time()
        })

_V184_CONTROL_PATTERNS=[
 ('STOP_SPEECH',r'^(stop|stop speaking|chup|bas|बस|रुको|रुक जाओ)$'),
 ('PAUSE_LISTEN',r'(stop listening|pause listening|listening band|sunna band|सुनना बंद)'),
 ('RESUME_LISTEN',r'(start listening|resume listening|sunna shuru|सुनना शुरू)'),
 ('SCREEN',r'(what.*screen|screen.*(?:kya|what|dikha|bata)|see my screen|analy[sz]e.*screen|स्क्रीन)'),
 ('STATUS',r'(system status|laptop status|computer status|battery.*(?:kitni|status)|ram.*status)'),
 ('VOLUME_UP',r'(volume.*(?:up|badha|increase)|awaaz.*badha|आवाज़.*बढ़ा)'),
 ('VOLUME_DOWN',r'(volume.*(?:down|kam|decrease)|awaaz.*kam|आवाज़.*कम)'),
 ('MUTE',r'(^mute$|mute.*(?:sound|audio)|awaaz band|आवाज़ बंद)'),
 ('WINDOW_CLOSE',r'(close (?:this|current|active) window|yeh window band|इस विंडो.*बंद)'),
 ('WINDOW_MIN',r'(minimi[sz]e (?:this|current|window)|window.*minimi[sz]e)'),
 ('WINDOW_MAX',r'(maximi[sz]e (?:this|current|window)|window.*maximi[sz]e)'),
 ('SWITCH',r'(switch window|next window|alt tab|dusri window|दूसरी विंडो)'),
 ('SCROLL_DOWN',r'(scroll down|neeche scroll|नीचे स्क्रॉल)'),
 ('SCROLL_UP',r'(scroll up|upar scroll|ऊपर स्क्रॉल)'),
 ('BACK',r'^(go back|back|peeche|पीछे)$'),
 ('ENTER',r'^(press enter|enter|एंटर)$'),
 ('ESC',r'^(press escape|escape|esc|एस्केप)$'),
]

def _v184_control_kind(text):
    t=' '.join(str(text or '').strip().split()).lower()
    for kind,p in _V184_CONTROL_PATTERNS:
        if _v184_re.search(p,t,_v184_re.I):return kind
    return ''

def _v184_mode_command(text):
    t=str(text or '').lower()
    if _v184_re.search(r'(focus mode|deep work mode|focus on)',t):return 'FOCUS'
    if _v184_re.search(r'(friend mode|casual mode|chill mode)',t):return 'FRIEND'
    if _v184_re.search(r'(silent mode|quiet mode)',t):return 'SILENT'
    if _v184_re.search(r'(normal mode|default mode)',t):return 'NORMAL'
    return ''

def _v184_extract_app(text):
    t=str(text or '')
    m=_v184_re.search(r'\bopen\s+(.+?)(?:\s+please)?$',t,_v184_re.I)
    if not m:return ''
    app=m.group(1).strip(' .!?')
    # Keep this declarative. Actual execution remains the client's allowlisted desktop layer.
    return app[:80]

def _v184_search_query(text):
    t=str(text or '')
    m=_v184_re.search(r'(?:search(?: google)? for|google|find online)\s+(.+)$',t,_v184_re.I)
    return m.group(1).strip()[:400] if m else ''

def _v184_compile_control(device_id,text):
    """Turns natural speech into a bounded control intent. Never returns shell."""
    ctx=_v184_ctx(device_id);t=' '.join(str(text or '').split()).strip()
    mode=_v184_mode_command(t)
    if mode:
        ctx['mode']=mode;ctx['updated']=_v184_time.time()
        return {'kind':'voice_mode','mode':mode,'risk':'LOW','requires_approval':False}
    k=_v184_control_kind(t)
    mapping={
      'STOP_SPEECH':{'kind':'stop_speech'},'PAUSE_LISTEN':{'kind':'pause_listening'},
      'RESUME_LISTEN':{'kind':'resume_listening'},'SCREEN':{'kind':'screen_describe','question':t},
      'STATUS':{'kind':'system_status'},'VOLUME_UP':{'kind':'volume_up'},'VOLUME_DOWN':{'kind':'volume_down'},
      'MUTE':{'kind':'volume_mute'},'WINDOW_CLOSE':{'kind':'close_window'},
      'WINDOW_MIN':{'kind':'minimize_window'},'WINDOW_MAX':{'kind':'maximize_window'},
      'SWITCH':{'kind':'switch_window'},'SCROLL_DOWN':{'kind':'scroll','amount':-654},
      'SCROLL_UP':{'kind':'scroll','amount':654},'BACK':{'kind':'key_press','key':'alt+left'},
      'ENTER':{'kind':'key_press','key':'enter'},'ESC':{'kind':'key_press','key':'esc'}
    }
    if k:
        x=dict(mapping[k]);x.update({'risk':'MEDIUM' if k=='WINDOW_CLOSE' else 'LOW',
          'requires_approval':k=='WINDOW_CLOSE'});ctx['last_control']=k;return x
    app=_v184_extract_app(t)
    if app:
        ctx['last_app']=app;ctx['last_control']='OPEN'
        return {'kind':'open_target','target':app,'risk':'LOW','requires_approval':False}
    q=_v184_search_query(t)
    if q:
        ctx['last_query']=q;ctx['last_control']='SEARCH'
        return {'kind':'web_search','query':q,'risk':'LOW','requires_approval':False}
    # Contextual follow-up: "close it" after opening an app.
    if _v184_re.search(r'^(close it|band karo|ise band karo|इसे बंद करो)$',t,_v184_re.I) and ctx.get('last_app'):
        return {'kind':'close_window','context_target':ctx['last_app'],'risk':'MEDIUM','requires_approval':True}
    return None

# Integrate the genius compiler ahead of the generic voice brain.
_V184_INTENT_PREV=_v182_intent
def _v182_intent(text):
    base=_V184_INTENT_PREV(text)
    # Preserve deterministic SCREEN/PENDING routes.
    if base.get('kind') in ('SCREEN','PENDING'):return base
    return base

_V184_TURN_PREV=_v182_turn
def _v182_turn(device_id,audio_b64):
    # We need the transcript first, so retain v18.2's proven STT and routing.
    out=_V184_TURN_PREV(device_id,audio_b64)
    if not isinstance(out,dict) or not out.get('ok'):return out
    text=str(out.get('text') or '')
    ctl=_v184_compile_control(device_id,text)
    if ctl:
        ctx=_v184_ctx(device_id);ctx['turn']+=1;ctx['updated']=_v184_time.time()
        if ctl.get('kind')=='screen_describe':
            out.update({'route':'SCREEN','provider':'legend-control-router','brain_ms':0,
                        'reply':'','desktop_intent':ctl,'control':True})
        elif ctl.get('kind')=='voice_mode':
            mode=ctl.get('mode')
            reply={'FOCUS':'Focus mode on. I will keep replies brief and task-oriented.',
                   'FRIEND':'Friend mode on. I will be more conversational.',
                   'SILENT':'Silent mode on. I will minimize spoken output.',
                   'NORMAL':'Normal mode restored.'}.get(mode,'Mode updated.')
            out.update({'route':'CONTROL','provider':'legend-control-router','brain_ms':0,
                        'reply':reply,'desktop_intent':ctl,'control':True})
        else:
            out.update({'route':'CONTROL','provider':'legend-control-router','brain_ms':0,
                        'reply':'','desktop_intent':ctl,'control':True})
    return out

