# v18.4.1 — FALSE-HEARING + TTS STALL REPAIR
# =============================================================================
VERSION='18.4.1'
import re as _v1841_re

_V1841_AMBIENT_PHRASES=(
 'thank you for watching','thanks for watching','subtitles by the amara.org community',
 'please subscribe','like and subscribe','see you in the next video',
 'transcribe what was actually spoken','captioning provided by'
)
_V1841_LAST_ASSISTANT={}

def _v1841_norm(t):
    return _v1841_re.sub(r'[^a-z0-9\u0900-\u097f]+',' ',str(t or '').lower()).strip()

def _v1841_false_hearing(device_id,text):
    n=_v1841_norm(text)
    if not n:return True
    # Common media/caption contamination when no Nemo invocation is present.
    if any(p in n for p in _V1841_AMBIENT_PHRASES) and 'nemo' not in n:return True
    last=_v1841_norm(_V1841_LAST_ASSISTANT.get(str(device_id),''))
    if last and len(n)>10 and (n in last or last in n) and 'nemo' not in n:return True
    return False

_V1841_TURN_PREV=_v182_turn
def _v182_turn(device_id,audio_b64):
    out=_V1841_TURN_PREV(device_id,audio_b64)
    if not isinstance(out,dict):return out
    text=str(out.get('text') or '')
    if out.get('ok') and _v1841_false_hearing(device_id,text):
        return {'ok':False,'error':'ambient/media/echo suppressed','text':text,
                'route':'SUPPRESSED','provider':'legend-audio-guard','reply':''}
    if out.get('reply'):
        _V1841_LAST_ASSISTANT[str(device_id)]=str(out.get('reply'))[:1200]
    return out

_HANDLE_V1841_PREV=handle
def handle(msg):
    try:
        low=(msg.get('text') or '').strip().lower();cid=msg.get('chat',{}).get('id')
        if low in ('/voice1841','/audioguard','/ttsdoctor'):
            send_text(cid,'NEMO v18.4.1\nAmbient/media false-hearing guard: READY\nAssistant echo suppression: READY\nLegend controls: PRESERVED\nVision: PRESERVED\nApproval rails: PRESERVED')
            return
    except Exception:pass
    return _HANDLE_V1841_PREV(msg)

_MAIN_V1841_PREV=main
def main():
    print('NEMO v18.4.1 FALSE-HEARING + TTS STALL REPAIR READY')
    return _MAIN_V1841_PREV()

if False and __name__ == '__main__':
    main()

