# =============================================================================
# NEMO v19.1.1 — AMARA + COMPOUND HANDS FIX
# Fixes:
# 1) Amara.org contamination matcher normalization bug.
# 2) Multi-action speech: "open Chrome and search latest smartphones".
# 3) Prevents fake "Opening X and search Y" success replies.
# =============================================================================
VERSION='19.1.1'

_V1911_AMBIENT_NORM=(
 'thank you for watching','thanks for watching',
 'subtitles by the amara org community',
 'amara org community','captioning provided by',
 'please subscribe','like and subscribe','see you in the next video'
)

def _v1911_is_ambient(text):
    n=_v1841_norm(text)
    if not n:return True
    return any(p in n for p in _V1911_AMBIENT_NORM) and 'nemo' not in n

# Replace the older ambient guard with corrected normalized matching.
_V1911_FALSE_PREV=_v1841_false_hearing
def _v1841_false_hearing(device_id,text):
    if _v1911_is_ambient(text): return True
    return _V1911_FALSE_PREV(device_id,text)

def _v1911_parse_compound(text):
    """Parse bounded two-step open + search/go-to commands."""
    t=' '.join(str(text or '').split()).strip()
    t=_v191_re.sub(r'^(?:nemo[,\s]*)','',t,flags=_v191_re.I)

    # "Open Google Chrome and search latest smartphones"
    m=_v191_re.match(
      r'^(?:open|launch|start)\s+(.+?)\s+(?:and|then)\s+'
      r'(?:search(?:\s+(?:google|web))?\s+(?:for\s+)?|google\s+)(.+)$',
      t,_v191_re.I)
    if m:
        app=m.group(1).strip(' .!?')[:100]
        q=m.group(2).strip(' .!?')[:400]
        return {'kind':'control_sequence','steps':[
            {'kind':'open_target','target':app,'risk':'LOW','requires_approval':False},
            {'kind':'web_search','query':q,'risk':'LOW','requires_approval':False}],
            'risk':'LOW','requires_approval':False,'summary':'Open %s and search %s'%(app,q)}

    # "Open Chrome and go to youtube.com"
    m=_v191_re.match(
      r'^(?:open|launch|start)\s+(.+?)\s+(?:and|then)\s+'
      r'(?:go to|open)\s+([a-z0-9][a-z0-9._-]+\.[a-z]{2,}(?:/\S*)?)$',
      t,_v191_re.I)
    if m:
        app=m.group(1).strip(' .!?')[:100]
        url=m.group(2).strip()
        return {'kind':'control_sequence','steps':[
            {'kind':'open_target','target':app,'risk':'LOW','requires_approval':False},
            {'kind':'open_url','target':'https://'+url,'label':url,'risk':'LOW','requires_approval':False}],
            'risk':'LOW','requires_approval':False,'summary':'Open %s and go to %s'%(app,url)}
    return None

_V1911_COMPILE_PREV=_v184_compile_control
def _v184_compile_control(device_id,text):
    seq=_v1911_parse_compound(text)
    if seq:return seq
    return _V1911_COMPILE_PREV(device_id,text)

# Do not let a compound command be swallowed by the old open-target route.
_V1911_TURN_PREV=_v182_turn
def _v182_turn(device_id,audio_b64):
    out=_V1911_TURN_PREV(device_id,audio_b64)
    if not isinstance(out,dict):return out
    text=str(out.get('text') or '')
    if out.get('ok') and _v1911_is_ambient(text):
        return {'ok':False,'error':'ambient/media/echo suppressed','text':text,
                'route':'SUPPRESSED','provider':'legend-amara-guard','reply':''}
    seq=_v1911_parse_compound(text)
    if out.get('ok') and seq:
        out.update({'route':'CONTROL','provider':'legend-compound-router','brain_ms':0,
                    'reply':'','desktop_intent':seq,'control':True})
    return out

_HANDLE_V1911_PREV=handle
def handle(msg):
    try:
        low=(msg.get('text') or '').strip().lower();cid=msg.get('chat',{}).get('id')
        if low in ('/hands1911','/amarafix','/compoundhands'):
            send_text(cid,
              'NEMO v19.1.1\n'
              'Amara.org normalized contamination guard: READY\n'
              'Compound open+search commands: READY\n'
              'Compound open+website commands: READY\n'
              'False success suppression: READY\n'
              'Hands 4 + Vision + Approval rails: PRESERVED')
            return
    except Exception: pass
    return _HANDLE_V1911_PREV(msg)

_PRIME_REGRESSION_V1911_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V1911_PREV()
    r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v191-version',)]
    extra=[]
    def add(n,f):
        try:ok=bool(f());d='ok' if ok else 'false'
        except Exception as e:ok=False;d=type(e).__name__+': '+str(e)[:140]
        extra.append({'name':n,'ok':ok,'detail':d})
    add('v1911-version',lambda:VERSION=='19.1.1')
    add('v1911-amara',lambda:_v1911_is_ambient('Subtitles by the Amara.org community'))
    add('v1911-compound',lambda:_v1911_parse_compound('Open Google Chrome and search latest smartphones')['kind']=='control_sequence')
    add('v1911-compound-steps',lambda:len(_v1911_parse_compound('Open Chrome and search latest smartphones')['steps'])==2)
    add('v1911-policy',lambda:callable(guardian_action) and callable(prime_policy_decide))
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed']
    r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_MAIN_V1911_PREV=main
def main():
    print('NEMO v19.1.1 AMARA + COMPOUND HANDS FIX READY')
    return _MAIN_V1911_PREV()

