# v19.2 — LEGEND HANDS 5: TARGETED WINDOW CONTROL + VERIFY CONTRACT
# =============================================================================
VERSION='19.2'

def _v192_close_target(text):
    t=' '.join(str(text or '').split()).strip()
    m=_v191_re.match(r'^(?:nemo[,\s]*)?(?:close|quit|exit|band karo|बंद करो)\s+(.+?)(?:\s+(?:browser|app|application|window))?[.!?]*$',t,_v191_re.I)
    if not m:return ''
    x=m.group(1).strip(' .!?')
    if x.lower() in ('this','current','active','window','this window','current window'):return '__ACTIVE__'
    return x[:120]

def _v192_activate_target(text):
    t=' '.join(str(text or '').split()).strip()
    m=_v191_re.match(r'^(?:nemo[,\s]*)?(?:switch to|focus|bring|activate)\s+(.+?)(?:\s+(?:window|app))?[.!?]*$',t,_v191_re.I)
    return m.group(1).strip(' .!?')[:120] if m else ''

_V192_COMPILE_PREV=_v184_compile_control
def _v184_compile_control(device_id,text):
    t=' '.join(str(text or '').split()).strip()
    close=_v192_close_target(t)
    if close:
        return {'kind':'window_target','action':'close','target':close,'risk':'MEDIUM',
                'requires_approval':True if close=='__ACTIVE__' else False}
    act=_v192_activate_target(t)
    if act:
        return {'kind':'window_target','action':'activate','target':act,'risk':'LOW','requires_approval':False}
    return _V192_COMPILE_PREV(device_id,t)

_V192_TURN_PREV=_v182_turn
def _v182_turn(device_id,audio_b64):
    out=_V192_TURN_PREV(device_id,audio_b64)
    if not isinstance(out,dict) or not out.get('ok'):return out
    txt=str(out.get('text') or '')
    ctl=_v184_compile_control(device_id,txt)
    if isinstance(ctl,dict) and ctl.get('kind')=='window_target':
        out.update({'route':'CONTROL','provider':'legend-hands5-router','brain_ms':0,
                    'reply':'','desktop_intent':ctl,'control':True})
    return out

_HANDLE_V192_PREV=handle
def handle(msg):
    try:
        low=(msg.get('text') or '').strip().lower();cid=msg.get('chat',{}).get('id')
        if low in ('/hands192','/hands5','/windowcontrol'):
            send_text(cid,'NEMO v19.2 LEGEND HANDS 5\nTargeted close/switch window routing: READY\nExecution verification contract: READY\nHands 4.1 + vision + ambient guard: PRESERVED\nArbitrary shell: BLOCKED\nHigh-impact controls: APPROVAL POLICY PRESERVED')
            return
    except Exception:pass
    return _HANDLE_V192_PREV(msg)

