def _v193_single_control(text):
    t=' '.join(str(text or '').split()).strip()
    for name,pat in _V193_SIMPLE:
        if _v191_re.search(pat,t,_v191_re.I):
            if name in _V193_KEYS:
                return {'kind':'key_press','key':_V193_KEYS[name],'risk':'LOW','requires_approval':False}
            if name in _V193_SETTINGS:
                return {'kind':'open_uri','target':_V193_SETTINGS[name],'risk':'LOW','requires_approval':False}
            if name in _V193_FOLDERS:
                return {'kind':'known_folder','target':_V193_FOLDERS[name],'risk':'LOW','requires_approval':False}
            if name=='file_explorer':return {'kind':'open_target','target':'File Explorer','risk':'LOW','requires_approval':False}
            if name=='recycle_bin':return {'kind':'known_folder','target':'Recycle Bin','risk':'LOW','requires_approval':False}
            if name=='store':return {'kind':'open_uri','target':'ms-windows-store://home/','risk':'LOW','requires_approval':False}
            if name=='weather':return {'kind':'open_uri','target':'msnweather:','risk':'LOW','requires_approval':False}
            if name=='photos':return {'kind':'open_uri','target':'ms-photos:','risk':'LOW','requires_approval':False}
    # Search inside a named site: "search YouTube for X"
    m=_v191_re.match(r'^(?:nemo[,\s]*)?search\s+(youtube|google|github)\s+(?:for\s+)?(.+)$',t,_v191_re.I)
    if m:return {'kind':'site_search','site':m.group(1).lower(),'query':m.group(2).strip()[:400],
                 'risk':'LOW','requires_approval':False}
    # Browser zoom.
    m=_v191_re.search(r'\b(browser|page)\s+zoom\s+(in|out|reset)\b',t,_v191_re.I)
    if m:return {'kind':'key_press','key':{'in':'ctrl++','out':'ctrl+-','reset':'ctrl+0'}[m.group(2).lower()],
                 'risk':'LOW','requires_approval':False}
    return None

def _v193_split_sequence(text):
    t=' '.join(str(text or '').split()).strip()
    # Bounded sequence, max 5 actions; "and" is accepted only when each side compiles.
    parts=_v191_re.split(r'\s+(?:and then|then|after that)\s+',t,flags=_v191_re.I)
    if len(parts)<=1:return None
    return [p.strip(' ,') for p in parts if p.strip()][:5]

_V193_COMPILE_PREV=_v184_compile_control
def _v184_compile_control(device_id,text):
    t=' '.join(str(text or '').split()).strip()
    one=_v193_single_control(t)
    if one:return one
    parts=_v193_split_sequence(t)
    if parts and len(parts)>1:
        steps=[]
        for p in parts:
            x=_v193_single_control(p) or _V193_COMPILE_PREV(device_id,p)
            if not isinstance(x,dict) or x.get('kind') in ('control_sequence','voice_mode'):return _V193_COMPILE_PREV(device_id,t)
            steps.append(x)
        if steps:return {'kind':'control_sequence','steps':steps,'risk':'LOW','requires_approval':any(bool(x.get('requires_approval')) for x in steps)}
    return _V193_COMPILE_PREV(device_id,t)

