# NEMO v19.4.1 — VOICE STABILITY + CONTEXT HYGIENE
# Fixes transcript-shaped LLM leakage, stale-task injection, greeting overthinking,
# and voice replies that become unnecessarily long.
# =============================================================================
VERSION='19.4.1'
_V1941_TRANSCRIPT_LEAK=_v191_re.compile(
 r'(?i)\b(?:transcription\s*:|assistant\s*:|user\s*:|system\s*:|transcribe what was actually|'
 r'this is the material i have already sent|/update\b|subtitles by the amara|thank you for watching)'
)
_V1941_GREETING=_v191_re.compile(
 r'(?i)^\s*(?:nemo[\s,!.-]*)?(?:hi|hello|hey|namaste|नमस्ते|हाय|hello nemo|hi nemo|hey nemo|nemo)\s*[!.?]*\s*$'
)

def _v1941_bad_voice_answer(ans,current_text):
    a=' '.join(str(ans or '').split()).strip()
    cur=' '.join(str(current_text or '').split()).strip()
    if not a:return True
    # A normal answer must never suddenly become a role-labelled transcript.
    if _V1941_TRANSCRIPT_LEAK.search(a):return True
    if a.lower().startswith(('transcription:','assistant:','user:')):return True
    # Short current utterances must not trigger huge unrelated memory/task dumps.
    if len(cur)<45 and len(a)>520:return True
    return False

_V1941_BRAIN_PREV=_v182_brain
def _v182_brain(chat_id,text,style,intent,device_id=''):
    raw=' '.join(str(text or '').split()).strip()
    t0=_v182_time.time()

    # Deterministic greeting lane: zero stale owner memory and zero fallback.
    if _V1941_GREETING.match(raw):
        if style in ('HINDI','HINGLISH_MIXED'): ans='हाँ, मैं यहाँ हूँ। बताइए।'
        elif style=='HINGLISH_LATIN': ans='Haan, main yahin hoon. Boliye.'
        else: ans="Yes, I'm here. What can I do for you?"
        return ans,'local-greeting',int((_v182_time.time()-t0)*1000)

    ans,provider,ms=_V1941_BRAIN_PREV(chat_id,text,style,intent,device_id)

    # If a provider/fallback leaked transcript/history, discard it instead of speaking it.
    if _v1941_bad_voice_answer(ans,raw):
        instr=(
          'NEMO CLEAN VOICE RECOVERY. Answer ONLY the current user utterance below. '
          'Do not output transcripts, role labels, old tasks, emails, previous conversations, update commands, '
          'or material not explicitly requested now. Never invent pending work. '
          'Use 1-3 natural spoken sentences. '+_v182_spoken_instruction(style)+
          '\nCURRENT USER UTTERANCE: '+raw[:1800])
        try:
            clean,_diag=_v166_groq_answer([{'role':'user','content':instr}],_V166_FAST_MODEL,180,'low')
            clean=_v164_voice_clean(clean or '')
        except Exception: clean=''
        if _v1941_bad_voice_answer(clean,raw):
            clean='I heard you. Please say the request once more.' if style=='ENGLISH' else 'मैंने सुना। कृपया अपना अनुरोध एक बार फिर बोलिए।'
        ans=_v182_voice_trim(clean)
        provider='voice-clean-recovery'
        ms=int((_v182_time.time()-t0)*1000)
    return ans,provider,ms

_V1941_TURN_PREV=_v182_turn
def _v182_turn(device_id,audio_b64):
    out=_V1941_TURN_PREV(device_id,audio_b64)
    if not isinstance(out,dict):return out
    txt=' '.join(str(out.get('text') or '').split()).strip()
    # Reject Whisper/provider prompt-contamination style transcripts before brain/TTS.
    if out.get('ok') and (_V1941_TRANSCRIPT_LEAK.search(txt) or len(txt)>700):
        return {'ok':False,'error':'stt contamination suppressed','text':txt[:240],
                'route':'SUPPRESSED','provider':'voice-context-hygiene','reply':'',
                'suppressed':True,'stt_ms':out.get('stt_ms',0)}
    return out

_HANDLE_V1941_PREV=handle
def handle(msg):
    try:
        low=(msg.get('text') or '').strip().lower();cid=msg.get('chat',{}).get('id')
        if low in ('/voice1941','/voicefix1941','/contexthygiene'):
            send_text(cid,'NEMO v19.4.1 VOICE STABILITY\nTranscript leakage suppression: READY\nGreeting fast lane: READY\nStale-task injection guard: READY\nClean-answer recovery: READY\nHands 7 + Vision + Approvals: PRESERVED')
            return
    except Exception:pass
    return _HANDLE_V1941_PREV(msg)

_MAIN_V1941_PREV=main
def main():
    print('NEMO v19.4.1 VOICE STABILITY + CONTEXT HYGIENE READY')
    return _MAIN_V1941_PREV()
if False and __name__ == '__main__':
    main()

# =============================================================================
# NEMO 20.0 — FOUNDATION CORE
# First consolidation layer for the Personal AI OS architecture.
# Goals: capability registry, health-aware routing, event/audit ledger,
# verified action contract, bounded memory classes, mission kernel,
# and runtime observability — while preserving v19.4.1 compatibility.
# =============================================================================
VERSION='20.0'
import threading as _n20_threading
import time as _n20_time
import json as _n20_json
import sqlite3 as _n20_sqlite3
import os as _n20_os
import uuid as _n20_uuid

_N20_DB='/root/nemo20_core.db'
_N20_LOCK=_n20_threading.RLock()
_N20_SCHEMA_READY=False

def n20_db():
    c=_n20_sqlite3.connect(_N20_DB,timeout=8,check_same_thread=False)
    try:
        c.execute('PRAGMA journal_mode=WAL')
        c.execute('PRAGMA busy_timeout=8000')
        c.execute('PRAGMA synchronous=NORMAL')
    except Exception:pass
    return c

def n20_schema():
    global _N20_SCHEMA_READY
    if _N20_SCHEMA_READY:return
    with _N20_LOCK:
        if _N20_SCHEMA_READY:return
        c=n20_db()
        c.executescript("""
        CREATE TABLE IF NOT EXISTS n20_events(
          id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL NOT NULL, trace_id TEXT,
          kind TEXT NOT NULL, component TEXT, status TEXT, detail TEXT);
        CREATE INDEX IF NOT EXISTS idx_n20_events_ts ON n20_events(ts);
        CREATE INDEX IF NOT EXISTS idx_n20_events_trace ON n20_events(trace_id);

        CREATE TABLE IF NOT EXISTS n20_capabilities(
          name TEXT PRIMARY KEY, family TEXT, risk TEXT, enabled INTEGER DEFAULT 1,
          health REAL DEFAULT 1.0, successes INTEGER DEFAULT 0, failures INTEGER DEFAULT 0,
          last_ms INTEGER DEFAULT 0, updated REAL, meta TEXT);
        CREATE TABLE IF NOT EXISTS n20_provider_health(
          provider TEXT PRIMARY KEY, health REAL DEFAULT 1.0, successes INTEGER DEFAULT 0,
          failures INTEGER DEFAULT 0, latency_ema REAL DEFAULT 0, cooldown_until REAL DEFAULT 0,
          updated REAL, last_error TEXT);
        CREATE TABLE IF NOT EXISTS n20_memory(
          id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL NOT NULL, class TEXT NOT NULL,
          key TEXT, text TEXT NOT NULL, confidence REAL DEFAULT 1.0, expires REAL DEFAULT 0,
          source TEXT, meta TEXT);
        CREATE INDEX IF NOT EXISTS idx_n20_memory_class ON n20_memory(class,ts);
        CREATE TABLE IF NOT EXISTS n20_missions(
          id TEXT PRIMARY KEY, created REAL, updated REAL, status TEXT, goal TEXT,
          risk TEXT, current_step INTEGER DEFAULT 0, plan TEXT, result TEXT, error TEXT);
        CREATE TABLE IF NOT EXISTS n20_action_receipts(
          id TEXT PRIMARY KEY, ts REAL, trace_id TEXT, action TEXT, target TEXT,
          status TEXT, verified INTEGER DEFAULT 0, evidence TEXT, meta TEXT);
        """)
        c.commit();c.close();_N20_SCHEMA_READY=True

def n20_event(kind,component='',status='',detail='',trace_id=''):
    try:
        n20_schema();c=n20_db()
        c.execute('INSERT INTO n20_events(ts,trace_id,kind,component,status,detail) VALUES(?,?,?,?,?,?)',
                  (_n20_time.time(),trace_id or '',kind,component,status,str(detail)[:5000]))
        c.commit();c.close()
    except Exception:pass

def n20_capability_register(name,family='core',risk='LOW',meta=None):
    try:
        n20_schema();c=n20_db()
        c.execute("""INSERT INTO n20_capabilities(name,family,risk,enabled,health,updated,meta)
                     VALUES(?,?,?,?,?,?,?)
                     ON CONFLICT(name) DO UPDATE SET family=excluded.family,risk=excluded.risk,
                     updated=excluded.updated,meta=excluded.meta""",
                  (name,family,risk,1,1.0,_n20_time.time(),_n20_json.dumps(meta or {})))
        c.commit();c.close()
    except Exception:pass

def n20_provider_result(provider,ok,latency_ms=0,error=''):
    if not provider:return
    try:
        n20_schema();c=n20_db()
        row=c.execute('SELECT health,successes,failures,latency_ema FROM n20_provider_health WHERE provider=?',(provider,)).fetchone()
        h,s,f,ema=(row or (1.0,0,0,0.0))
        s+=1 if ok else 0;f+=0 if ok else 1
        h=max(.05,min(1.0,h*.92+(.08 if ok else 0.0)))
        if not ok:h=max(.05,h-.14)
        ema=float(latency_ms) if not ema else ema*.8+float(latency_ms)*.2
        cooldown=_n20_time.time()+30 if (not ok and h<.35) else 0
        c.execute("""INSERT OR REPLACE INTO n20_provider_health
          (provider,health,successes,failures,latency_ema,cooldown_until,updated,last_error)
          VALUES(?,?,?,?,?,?,?,?)""",(provider,h,s,f,ema,cooldown,_n20_time.time(),str(error)[:600]))
        c.commit();c.close()
    except Exception:pass

def n20_provider_snapshot():
    try:
        n20_schema();c=n20_db()
        rows=c.execute('SELECT provider,health,latency_ema,cooldown_until,successes,failures FROM n20_provider_health ORDER BY health DESC').fetchall()
        c.close()
        return [{'provider':r[0],'health':round(r[1],3),'latency_ms':round(r[2]),'cooldown':r[3],
                 'successes':r[4],'failures':r[5]} for r in rows]
    except Exception:return []

def n20_memory_put(cls,text,key='',confidence=1.0,ttl=0,source='runtime',meta=None):
    allowed={'working','episodic','semantic','procedural','project','preference'}
    if cls not in allowed:raise ValueError('unsupported memory class')
    n20_schema();c=n20_db();now=_n20_time.time()
    c.execute('INSERT INTO n20_memory(ts,class,key,text,confidence,expires,source,meta) VALUES(?,?,?,?,?,?,?,?)',
              (now,cls,key,str(text)[:12000],float(confidence),now+ttl if ttl else 0,source,_n20_json.dumps(meta or {})))
    c.commit();c.close()

def n20_memory_search(q,classes=None,limit=8):
    q=' '.join(str(q or '').split()).strip()
    if not q:return []
    n20_schema();c=n20_db();now=_n20_time.time()
    classes=classes or ['working','episodic','semantic','procedural','project','preference']
    marks=','.join('?' for _ in classes)
    sql=("SELECT class,key,text,confidence,ts FROM n20_memory WHERE class IN ("+marks+
         ") AND (expires=0 OR expires>?) AND lower(text) LIKE ? ORDER BY confidence DESC,ts DESC LIMIT ?")
    rows=c.execute(sql,tuple(classes)+ (now,'%'+q.lower()+'%',int(limit))).fetchall();c.close()
    return [{'class':r[0],'key':r[1],'text':r[2],'confidence':r[3],'ts':r[4]} for r in rows]

def n20_receipt(action,target,status='attempted',verified=False,evidence='',trace_id='',meta=None):
    rid='act_'+_n20_uuid.uuid4().hex[:14]
    try:
        n20_schema();c=n20_db()
        c.execute('INSERT INTO n20_action_receipts(id,ts,trace_id,action,target,status,verified,evidence,meta) VALUES(?,?,?,?,?,?,?,?,?)',
                  (rid,_n20_time.time(),trace_id,action,target,status,1 if verified else 0,str(evidence)[:5000],_n20_json.dumps(meta or {})))
        c.commit();c.close()
    except Exception:pass
    return rid

def n20_mission_create(goal,plan=None,risk='LOW'):
    mid='m20_'+_n20_uuid.uuid4().hex[:12];now=_n20_time.time()
    n20_schema();c=n20_db()
    c.execute('INSERT INTO n20_missions(id,created,updated,status,goal,risk,current_step,plan,result,error) VALUES(?,?,?,?,?,?,?,?,?,?)',
              (mid,now,now,'PLANNED',str(goal)[:8000],risk,0,_n20_json.dumps(plan or []),'',''))
    c.commit();c.close();n20_event('mission','executive','PLANNED',goal,mid);return mid

def n20_mission_get(mid):
    n20_schema();c=n20_db()
    r=c.execute('SELECT id,created,updated,status,goal,risk,current_step,plan,result,error FROM n20_missions WHERE id=?',(mid,)).fetchone();c.close()
    if not r:return None
    try:plan=_n20_json.loads(r[7] or '[]')
    except Exception:plan=[]
    return {'id':r[0],'created':r[1],'updated':r[2],'status':r[3],'goal':r[4],'risk':r[5],
            'current_step':r[6],'plan':plan,'result':r[8],'error':r[9]}

def n20_runtime_snapshot():
    n20_schema()
    caps=[]
    try:
        c=n20_db()
        caps=c.execute('SELECT family,count(*),avg(health) FROM n20_capabilities WHERE enabled=1 GROUP BY family ORDER BY family').fetchall()
        ev=c.execute('SELECT count(*) FROM n20_events').fetchone()[0]
        mem=c.execute('SELECT class,count(*) FROM n20_memory GROUP BY class').fetchall()
        mis=c.execute('SELECT status,count(*) FROM n20_missions GROUP BY status').fetchall()
        c.close()
    except Exception:ev=0;mem=[];mis=[]
    return {'version':VERSION,'db':_N20_DB,'events':ev,
            'capabilities':[{'family':x[0],'count':x[1],'health':round(x[2] or 0,3)} for x in caps],
            'memory':dict(mem),'missions':dict(mis),'providers':n20_provider_snapshot()}

# Register the stable families already present in Nemo.
for _n,_f,_r in [
 ('brain_router','brain','LOW'),('voice','voice','LOW'),('vision','vision','LOW'),
 ('windows_hands','computer','MEDIUM'),('browser','browser','MEDIUM'),
 ('research','research','LOW'),('memory','memory','LOW'),('executive','executive','MEDIUM'),
 ('guardian','policy','HIGH'),('reports','artifacts','LOW'),('learning','learning','MEDIUM'),
 ('cyber_defensive','cyber','HIGH'),('device_grid','devices','HIGH'),
 ('trading_analytics','finance','HIGH')]:
    n20_capability_register(_n,_f,_r)

# Instrument the current v19.4.1 voice turn without changing its behavior.
_N20_TURN_PREV=_v182_turn
def _v182_turn(device_id,audio_b64):
    trace='v20_'+_n20_uuid.uuid4().hex[:12];t0=_n20_time.time()
    n20_event('turn','voice','START','device='+str(device_id),trace)
    try:
        out=_N20_TURN_PREV(device_id,audio_b64)
        ms=int((_n20_time.time()-t0)*1000)
        if isinstance(out,dict):
            p=str(out.get('provider') or '')
            ok=bool(out.get('ok'))
            n20_provider_result(p,ok,ms,out.get('error',''))
            out['trace_id']=trace;out['nemo_core']='20.0'
            n20_event('turn','voice','OK' if ok else 'SUPPRESSED',_n20_json.dumps({'route':out.get('route'),'provider':p,'ms':ms}),trace)
        return out
    except Exception as e:
        ms=int((_n20_time.time()-t0)*1000);n20_event('turn','voice','ERROR',type(e).__name__+': '+str(e),trace)
        raise

_HANDLE_N20_PREV=handle
def handle(msg):
    try:
        low=(msg.get('text') or '').strip().lower();cid=msg.get('chat',{}).get('id')
        if low in ('/nemo20','/core20','/foundation20'):
            snap=n20_runtime_snapshot()
            send_text(cid,'NEMO 20.0 FOUNDATION CORE\n'
              'Compatibility layer: READY\nCapability Registry: READY\nProvider Health: READY\n'
              'Event/Audit Ledger: READY\nMemory Classes: READY\nMission Kernel: READY\n'
              'Verified Action Receipts: READY\nRuntime Observability: READY\n\n'
              +_n20_json.dumps(snap,indent=2)[:3200]);return
        if low=='/health20':
            send_text(cid,_n20_json.dumps(n20_provider_snapshot(),indent=2)[:3800]);return
        if low=='/missions20':
            n20_schema();c=n20_db();rows=c.execute('SELECT id,status,goal,updated FROM n20_missions ORDER BY updated DESC LIMIT 12').fetchall();c.close()
            send_text(cid,_n20_json.dumps([{'id':r[0],'status':r[1],'goal':r[2],'updated':r[3]} for r in rows],indent=2)[:3800]);return
    except Exception as e:
        try:send_text(cid,'Nemo 20 command error: '+str(e)[:300])
        except Exception:pass
        return
    return _HANDLE_N20_PREV(msg)

_PRIME_REGRESSION_N20_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_N20_PREV()
    r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v193-version','v192-version','v1911-version')]
    extra=[]
    def add(n,f):
        try:ok=bool(f());d='ok' if ok else 'false'
        except Exception as e:ok=False;d=type(e).__name__+': '+str(e)[:140]
        extra.append({'name':n,'ok':ok,'detail':d})
    add('n20-version',lambda:VERSION=='20.0')
    add('n20-schema',lambda:(n20_schema() is None and _N20_SCHEMA_READY))
    add('n20-runtime',lambda:n20_runtime_snapshot().get('version')=='20.0')
    add('n20-receipts',lambda:n20_receipt('selftest','none','verified',True,'selftest').startswith('act_'))
    add('n20-mission',lambda:n20_mission_create('regression self-test',[],risk='LOW').startswith('m20_'))
    add('n20-policy-preserved',lambda:callable(guardian_action) and callable(prime_policy_decide))
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed']
    r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_MAIN_N20_PREV=main
def main():
    n20_schema()
    print('NEMO 20.0 FOUNDATION CORE READY')
    print('Capability Registry | Provider Health | Audit | Memory Classes | Missions | Receipts')
    return _MAIN_N20_PREV()

if False and __name__ == '__main__':
    main()
# === NEMO 20.2 PHASE 2+3: VERIFIED HANDS 8 + BRAIN ROUTER 3 ===
VERSION='20.2'
import re as _n202_re, time as _n202_time, json as _n202_json
def n202_hands_semantic(text):
    t=' '.join(str(text or '').split()).strip()
    rules=[
      ('invoke',r'^(?:nemo[,\s]*)?(?:click|press|invoke)\s+(?:the\s+)?(.+?)\s+(?:button|menu item)$'),
      ('focus',r'^(?:nemo[,\s]*)?(?:focus|select|go to)\s+(?:the\s+)?(.+?)\s+(?:field|textbox|control)$'),
      ('set_value',r'^(?:nemo[,\s]*)?(?:set|fill|enter)\s+(.+?)\s+(?:field|textbox)\s+(?:to|with)\s+(.+)$'),
      ('toggle',r'^(?:nemo[,\s]*)?(?:toggle|tick|check|uncheck)\s+(?:the\s+)?(.+?)\s+(?:checkbox|switch)$'),
      ('read',r'^(?:nemo[,\s]*)?(?:read|inspect|describe)\s+(?:the\s+)?(.+?)\s+(?:dialog|window|control)$')]
    for op,p in rules:
        m=_n202_re.match(p,t,_n202_re.I)
        if m:
            d={'kind':'uia_semantic','op':op,'name':m.group(1).strip()[:180],'risk':'LOW','requires_approval':False,'verify':True}
            if op=='set_value':
                d['value']=m.group(2).strip()[:1500]
                if _n202_re.search(r'(?i)password|passcode|otp|2fa|pin|private key|seed|recovery',d['name']):
                    d.update({'requires_approval':True,'risk':'HIGH','blocked_secret_field':True})
            return d
    return None
_N202_COMPILE_PREV=_v184_compile_control
def _v184_compile_control(device_id,text):
    return n202_hands_semantic(text) or _N202_COMPILE_PREV(device_id,text)
def n202_route(text,needs_fresh=False,has_image=False):
    t=' '.join(str(text or '').split()).strip(); low=t.lower()
    risk='HIGH' if _n202_re.search(r'\b(pay|payment|transfer money|trade|delete|password|otp|deploy)\b',low) else 'LOW'
    if has_image:return {'route':'VISION','tier':'vision','risk':risk}
    if needs_fresh or _n202_re.search(r'\b(today|latest|current|news|live)\b',low):return {'route':'RESEARCH','tier':'research','risk':risk}
    if n202_hands_semantic(t) or _n202_re.search(r'\b(open|close|click|type|scroll|switch to|volume|screenshot)\b',low):return {'route':'ACTION','tier':'fast','risk':risk}
    if len(t)<55 and not _n202_re.search(r'\b(analy[sz]e|compare|research|deep|plan|strategy|reason)\b',low):return {'route':'FAST','tier':'fast','risk':risk}
    if len(t)>450 or _n202_re.search(r'\b(deep|comprehensive|strategy|audit|architecture|complex|verify)\b',low):return {'route':'DEEP','tier':'deep','risk':risk}
    return {'route':'SMART','tier':'smart','risk':risk}
def n202_provider_score(provider,quality=1.0,cost_weight=.08):
    snap={x['provider']:x for x in n20_provider_snapshot()}; x=snap.get(provider,{})
    h=float(x.get('health',1.0));lat=float(x.get('latency_ms',900) or 900);cool=float(x.get('cooldown',0) or 0)
    if cool>_n202_time.time():return -999
    return round(quality*2+h*1.25-min(lat/12000.0,.65)-cost_weight,4)
_N202_TURN_PREV=_v182_turn
def _v182_turn(device_id,audio_b64):
    out=_N202_TURN_PREV(device_id,audio_b64)
    if not isinstance(out,dict) or not out.get('ok'):return out
    txt=str(out.get('text') or ''); ctl=_v184_compile_control(device_id,txt)
    if isinstance(ctl,dict) and ctl.get('kind')=='uia_semantic':
        out.update({'route':'CONTROL','provider':'hands8-semantic','brain_ms':0,'reply':'','desktop_intent':ctl,'control':True})
    out['router3']=n202_route(txt); return out
_HANDLE_N202_PREV=handle
def handle(msg):
    try:
        low=(msg.get('text') or '').strip().lower();cid=msg.get('chat',{}).get('id')
        if low in ('/phase23','/hands8','/router3','/nemo202'):
            send_text(cid,'NEMO 20.2 PHASE 2+3\nHands 8 semantic target-act-verify: READY\nBrain Router 3 FAST/SMART/DEEP/RESEARCH/VISION/ACTION: READY\nProvider health+latency scoring: READY\nSecret-field guard + Guardian approvals: PRESERVED');return
    except Exception:pass
    return _HANDLE_N202_PREV(msg)
_MAIN_N202_PREV=main
def main():
    print('NEMO 20.2 PHASE 2+3 READY'); return _MAIN_N202_PREV()
if False and __name__ == '__main__':
    main()

