VERSION='20.2.2'
import re as _n2022_re, time as _n2022_time, traceback as _n2022_traceback

_N2022_INTERPRETIVE=_n2022_re.compile(
 r'(?i)\b(astrolog(?:y|ical)|kundli|horoscope|birth chart|natal chart|vedic astrology|'
 r'mahadasha|antardasha|dasha|nakshatra|rashi|lagna|numerology|gemstone|graha|'
 r'rahu|ketu|shani|jupiter|guru|mangal|venus|shukra|moon sign|sun sign|'
 r'spiritual profile|personality profile)\b'
)
_N2022_CURRENT=_n2022_re.compile(
 r'(?i)\b(today|latest|current|recent|2026|news|market|stock|price|government|policy|'
 r'law|legal|subsidy|scheme|election|geopolit|war|company|industry|financial|'
 r'research report|evidence|source|citation|statistics|data|forecast|outlook)\b'
)

def n2022_report_mode(topic):
    t=str(topic or '')
    if _N2022_INTERPRETIVE.search(t):
        return 'INTERPRETIVE'
    if _N2022_CURRENT.search(t):
        return 'EVIDENCE'
    return 'GENERAL'

def _n2022_interpretive_gate(content):
    reasons=[]
    c=str(content or '').strip()
    if len(c)<1400: reasons.append('report too short')
    # Require useful structure, not current-news sections/citations.
    required=('EXECUTIVE SUMMARY','FOUNDATION','ANALYSIS','GUIDANCE','CONCLUSION')
    up=c.upper()
    hits=sum(1 for x in required if x in up)
    if hits<3: reasons.append('insufficient report structure')
    if _n2022_re.search(r'(?i)\b(user safety|response safety|<unk>|we need to analyze|assistant:|system:)\b',c):
        reasons.append('model artifact detected')
    return (not reasons),reasons

