# Preserve raw QA implementation, then expose a stable normalized contract.
_N2023_PDF_QA_RAW=_creation_pdf_qa
def _n2023_pdf_qa_contract(path,content,research,quality):
    raw=_N2023_PDF_QA_RAW(path,content,research,quality)
    # Historical implementation returns a list of issues.
    if isinstance(raw,list):
        issues=raw
        return (len(issues)==0),issues
    # Defensive compatibility for any older/newer tuple implementation.
    if isinstance(raw,tuple) and len(raw)>=2:
        return bool(raw[0]),list(raw[1] or [])
    if raw is True:return True,[]
    if raw is False:return False,['PDF QA failed']
    return False,['unexpected PDF QA return contract: '+type(raw).__name__]

