def _n203_parse_birth(topic):
    t=' '.join(str(topic or '').replace('\n',' ').split())
    dob=None;tm=None;place=''
    md=_n203_re.search(r'(?i)(?:dob|date of birth|birth date)\s*[:\-]?\s*(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})',t)
    if md:
        d,m,y=map(int,md.groups()); dob=(y,m,d)
    mt=_n203_re.search(r'(?i)(?:birth time|time of birth)\s*[:\-]?\s*(\d{1,2})[:.](\d{2})\s*(am|pm)?',t)
    if mt:
        h=int(mt.group(1));mi=int(mt.group(2));ap=(mt.group(3) or '').lower()
        if ap=='pm' and h<12:h+=12
        if ap=='am' and h==12:h=0
        tm=(h,mi)
    mp=_n203_re.search(r'(?i)(?:birth place|place of birth|born in)\s*(?:is|:|-)?\s*([A-Za-z][A-Za-z .,-]{2,80}?)(?=\s+(?:in\s+pdf|pdf\s+format|create|make|prepare|$))',t)
    if mp:place=mp.group(1).strip(' ,.-')
    if not place:
        mp=_n203_re.search(r'(?i)(?:birth place|place of birth)\s*(?:is|:|-)?\s*([A-Za-z][A-Za-z .,-]{2,80})',t)
        if mp:place=mp.group(1).strip(' ,.-')
    return {'date':dob,'time':tm,'place':place}

# Small offline gazetteer for common Indian cities; no network dependency in Publisher.
# Unknown locations are handled honestly: report can still be written, but house/Ascendant
# facts are not fabricated.
_N203_PLACES={
 'indore':(22.7196,75.8577,'Asia/Kolkata'),'indore madhya pradesh':(22.7196,75.8577,'Asia/Kolkata'),
 'udaipur':(24.5854,73.7125,'Asia/Kolkata'),'udaipur rajasthan':(24.5854,73.7125,'Asia/Kolkata'),
 'jaipur':(26.9124,75.7873,'Asia/Kolkata'),'delhi':(28.6139,77.2090,'Asia/Kolkata'),
 'new delhi':(28.6139,77.2090,'Asia/Kolkata'),'mumbai':(19.0760,72.8777,'Asia/Kolkata'),
 'ahmedabad':(23.0225,72.5714,'Asia/Kolkata'),'jodhpur':(26.2389,73.0243,'Asia/Kolkata'),
 'kota':(25.2138,75.8648,'Asia/Kolkata'),'bhopal':(23.2599,77.4126,'Asia/Kolkata')
}
def _n203_place(place):
    p=' '.join(str(place or '').lower().replace(',',' ').split())
    if p in _N203_PLACES:return _N203_PLACES[p]
    for k,v in _N203_PLACES.items():
        if k in p:return v
    return None

def _n203_sign(lon):
    lon=float(lon)%360; i=int(lon//30)
    return _N203_SIGNS[i],lon-i*30

def _n203_nak(lon):
    lon=float(lon)%360; span=360.0/27.0; idx=int(lon//span); within=lon-idx*span
    pada=min(4,int(within/(span/4.0))+1)
    return _N203_NAK[idx],pada,within/span

def _n203_fmt_deg(x):
    d=int(x);m=int(round((x-d)*60))
    if m==60:d+=1;m=0
    return "%d°%02d′"%(d,m)

def _n203_dasha_from_moon(moon_lon,birth_dt):
    nak,pada,fraction=_n203_nak(moon_lon)
    lord=_N203_DASHA_LORDS[_N203_NAK.index(nak)%9]
    order=list(_N203_DASHA_LORDS);start=order.index(lord);seq=order[start:]+order[:start]
    # fraction traversed through the birth nakshatra; remaining balance of first Mahadasha.
    remaining=1.0-fraction
    cur=birth_dt
    rows=[]
    for j,L in enumerate(seq+order+order):
        yrs=_N203_DASHA_YEARS[L]*(remaining if j==0 else 1.0)
        days=yrs*365.2425
        end=cur+_n203_dt.timedelta(days=days)
        rows.append({'lord':L,'start':cur.date().isoformat(),'end':end.date().isoformat(),'years':round(yrs,2)})
        cur=end
        if (cur-birth_dt).days>125*365:break
    return {'birth_nakshatra':nak,'birth_pada':pada,'starting_lord':lord,'timeline':rows}

def _n203_astro_calc(topic):
    b=_n203_parse_birth(topic)
    out={'engine':'unavailable','verified':False,'birth':b,'warnings':[],'planets':{},'dasha':None}
    if not b['date'] or not b['time']:
        out['warnings'].append('Complete date/time could not be parsed.');return out
    loc=_n203_place(b['place'])
    if not loc:
        out['warnings'].append('Birth-place coordinates unavailable in offline gazetteer; Ascendant/houses not calculated.')
    try:
        import swisseph as swe
    except Exception as e:
        out['warnings'].append('Swiss Ephemeris Python binding is not installed: '+type(e).__name__)
        return out
    try:
        y,m,d=b['date'];hh,mm=b['time']
        # India-local input currently supported by built-in gazetteer. Convert IST to UT.
        utc=_n203_dt.datetime(y,m,d,hh,mm)-_n203_dt.timedelta(hours=5,minutes=30)
        hour=utc.hour+utc.minute/60.0+utc.second/3600.0
        jd=swe.julday(utc.year,utc.month,utc.day,hour)
        swe.set_sid_mode(swe.SIDM_LAHIRI)
        flags=swe.FLG_SWIEPH|swe.FLG_SIDEREAL|swe.FLG_SPEED
        bodies=[('Sun',swe.SUN),('Moon',swe.MOON),('Mars',swe.MARS),('Mercury',swe.MERCURY),
                ('Jupiter',swe.JUPITER),('Venus',swe.VENUS),('Saturn',swe.SATURN),
                ('Rahu',swe.MEAN_NODE)]
        for name,bid in bodies:
            xx,rf=swe.calc_ut(jd,bid,flags);lon=float(xx[0])%360
            sign,deg=_n203_sign(lon);nak,pada,_=_n203_nak(lon)
            out['planets'][name]={'longitude':round(lon,6),'sign':sign,'degree':_n203_fmt_deg(deg),
                                  'nakshatra':nak,'pada':pada,'retrograde':bool(float(xx[3])<0)}
        rahu=out['planets']['Rahu']['longitude'];ketu=(rahu+180)%360;sg,dg=_n203_sign(ketu);nk,pd,_=_n203_nak(ketu)
        out['planets']['Ketu']={'longitude':round(ketu,6),'sign':sg,'degree':_n203_fmt_deg(dg),
                                'nakshatra':nk,'pada':pd,'retrograde':True}
        if loc:
            lat,lon,tz=loc
            # Whole-sign Vedic houses from sidereal Ascendant.
            cusps,ascmc=swe.houses_ex(jd,lat,lon,b'W',flags)
            asc=float(ascmc[0])%360;sg,dg=_n203_sign(asc);nk,pd,_=_n203_nak(asc)
            out['ascendant']={'longitude':round(asc,6),'sign':sg,'degree':_n203_fmt_deg(dg),'nakshatra':nk,'pada':pd}
            asc_sign=int(asc//30)
            for name,p in out['planets'].items():
                p['house']=((int(float(p['longitude'])//30)-asc_sign)%12)+1
            out['location']={'lat':lat,'lon':lon,'timezone':tz}
        moon=float(out['planets']['Moon']['longitude'])
        birth_local=_n203_dt.datetime(y,m,d,hh,mm)
        out['dasha']=_n203_dasha_from_moon(moon,birth_local)
        out['engine']='Swiss Ephemeris / Lahiri sidereal / whole-sign houses'
        out['verified']=True
        return out
    except Exception as e:
        out['warnings'].append('Calculation failed: '+type(e).__name__+': '+str(e)[:180])
        return out

def _n203_calc_block(calc):
    if not calc.get('verified'):
        return ("CALCULATION STATUS: UNAVAILABLE\n"+
                "\n".join("- "+x for x in calc.get('warnings',[]))+
                "\nDo not state exact Lagna, houses, planetary signs/degrees, Nakshatras, Yogas or Dashas as facts.")
    lines=["CALCULATION STATUS: VERIFIED",
           "ENGINE: "+calc.get('engine',''),
           "All placements below are machine-calculated inputs. Interpretation remains an astrological belief framework."]
    a=calc.get('ascendant')
    if a:lines.append("ASCENDANT: %s %s | %s Pada %s"%(a['sign'],a['degree'],a['nakshatra'],a['pada']))
    lines.append("PLANETS:")
    for n in _N203_BODY_NAMES:
        p=calc['planets'].get(n)
        if p:
            lines.append("- %s: %s %s | %s Pada %s | House %s%s"%(n,p['sign'],p['degree'],p['nakshatra'],p['pada'],
                         p.get('house','N/A'),' | retrograde' if p.get('retrograde') else ''))
    ds=calc.get('dasha') or {}
    if ds:
        lines.append("VIMSHOTTARI MAHADASHA (calculated from Moon Nakshatra):")
        for x in ds.get('timeline',[])[:10]:
            lines.append("- %s: %s to %s"%(x['lord'],x['start'],x['end']))
    return '\n'.join(lines)

