def _n203_content_gate(content,calc):
    c=str(content or '');up=c.upper();reasons=[]
    if len(c)<12000:reasons.append('long-form report too short')
    req=('BIRTH DATA','EXECUTIVE','PLANET','HOUSE','DASHA','CAREER','MONEY','RELATIONSHIP','GUIDANCE','LIMITATIONS','CONCLUSION')
    if sum(1 for x in req if x in up)<8:reasons.append('missing major astrology sections')
    if _n203_re.search(r'(?i)\bassistant:|system:|we need to analyze|<unk>\b',c):reasons.append('model artifact detected')
    if not calc.get('verified') and _n203_re.search(r'(?i)\bascendant is\b|\blagna is\b|\b\d{1,2}°\d{1,2}',c):
        reasons.append('unverified precision detected')
    return not reasons,reasons

