def _n270_inbox_add(cid,title,source='manual',project_key='',priority=2,detail=''):
    iid='A27-'+_n270_uuid.uuid4().hex[:10].upper();now=_n270_time.time()
    try:
        c=_n270_conn();c.execute("""INSERT INTO action_inbox
          (id,chat_id,title,source,project_key,priority,status,created,updated,due,detail)
          VALUES(?,?,?,?,?,?, 'OPEN',?,?,?,?)""",
          (iid,str(cid),str(title)[:700],source,str(project_key)[:100],int(priority),now,now,'',str(detail)[:5000]))
        c.commit();c.close()
    except Exception:return ''
    return iid

def _n270_inbox(cid,status='OPEN',limit=20):
    try:
        c=_n270_conn();rows=c.execute("""SELECT id,title,source,project_key,priority,status,updated,detail
          FROM action_inbox WHERE chat_id=? AND status=? ORDER BY priority DESC,updated DESC LIMIT ?""",
          (str(cid),status,int(limit))).fetchall();c.close();return rows
    except Exception:return []

def _n270_inbox_close(cid,iid):
    try:
        c=_n270_conn();c.execute("UPDATE action_inbox SET status='DONE',updated=? WHERE id=? AND chat_id=?",
          (_n270_time.time(),iid,str(cid)));c.commit();ok=c.total_changes>0;c.close();return ok
    except Exception:return False

def _n270_productivity_sync(cid):
    # Pull unfinished mission steps into the owner action inbox without duplicating aggressively.
    added=0
    try:
        c25=_n250_conn()
        rows=c25.execute("""SELECT m.id,m.objective,s.id,s.title,s.kind,s.status
          FROM missions m JOIN mission_steps s ON s.mission_id=m.id
          WHERE m.chat_id=? AND s.status IN ('READY','WAITING_APPROVAL','FAILED')
          ORDER BY m.updated DESC,s.ord LIMIT 30""",(str(cid),)).fetchall()
        c25.close()
    except Exception:rows=[]
    try:
        c=_n270_conn()
        existing=set(r[0] for r in c.execute("SELECT detail FROM action_inbox WHERE chat_id=? AND status='OPEN'",(str(cid),)).fetchall())
        c.close()
    except Exception:existing=set()
    for mid,obj,sid,title,kind,status in rows:
        marker='mission_step='+sid
        if marker in existing:continue
        p=3 if status in ('WAITING_APPROVAL','FAILED') else 2
        if _n270_inbox_add(cid,title,'mission25',mid,p,marker+' | '+status+' | '+kind):added+=1
    return added

def _n270_brief(cid):
    _n270_productivity_sync(cid)
    lines=['NEMO PRODUCTIVITY OS 27 — OWNER BRIEF']
    try:
        lines.append(_n240_brief(cid))
    except Exception:pass
    inbox=_n270_inbox(cid,'OPEN',10)
    if inbox:
        lines.append('NEXT ACTIONS:')
        for r in inbox:
            lines.append('- [%s/P%d] %s | %s'%(r[0],r[4],r[1][:120],r[2]))
    graph=_n270_graph_context(cid)
    if graph:lines.append(graph)
    return '\n\n'.join(lines)[:3900]

# ---------------------------------------------------------------------------
# SKILLS 4
# ---------------------------------------------------------------------------
_N270_SAFE_KINDS=('THINK','ANALYZE','RESEARCH','SYNTHESIZE','VERIFY','READ_TOOL')
_N270_EXTERNAL_KINDS=('ACTION','COMPUTER','BROWSER_ACTION','EMAIL','MESSAGE','FILE_WRITE','DEVICE','DEPLOY','PAYMENT','TRADE')

def _n270_skill_create(cid,name,description,steps):
    sid='SK27-'+_n270_uuid.uuid4().hex[:10].upper();now=_n270_time.time()
    risk='LOW'
    for x in steps:
        if str(x.get('kind','')).upper() in _N270_EXTERNAL_KINDS:risk='MEDIUM'
        if str(x.get('kind','')).upper() in ('PAYMENT','TRADE','DEPLOY'):risk='HIGH'
    c=_n270_conn()
    c.execute("INSERT INTO skills VALUES(?,?,?,?,?,?,?,?)",
      (sid,str(cid),str(name)[:160],str(description)[:1000],risk,1,now,now))
    for i,x in enumerate(steps[:20],1):
        kind=str(x.get('kind') or 'THINK').upper()
        if kind not in _N270_SAFE_KINDS+_N270_EXTERNAL_KINDS:kind='THINK'
        approval=1 if kind in _N270_EXTERNAL_KINDS else 0
        c.execute("INSERT INTO skill_steps VALUES(?,?,?,?,?,?,?,?)",
          ('SS27-'+_n270_uuid.uuid4().hex[:9].upper(),sid,i,kind,str(x.get('action') or '')[:700],
           _n270_json.dumps(x.get('payload') or {},ensure_ascii=False)[:5000],
           str(x.get('risk') or ('MEDIUM' if approval else 'LOW')).upper(),approval))
    c.commit();c.close();return sid

def _n270_skill_plan(cid,name,description):
    prompt=(
      "NEMO SKILL DESIGNER 4. Return strict JSON only: "
      '{"steps":[{"kind":"THINK|ANALYZE|RESEARCH|SYNTHESIZE|VERIFY|READ_TOOL|ACTION|COMPUTER|BROWSER_ACTION|EMAIL|MESSAGE|FILE_WRITE|DEVICE|DEPLOY|PAYMENT|TRADE","action":"...","payload":{},"risk":"LOW|MEDIUM|HIGH"}]}. '
      "Design the smallest reusable workflow. Never disguise an external effect as a safe step. "
      "Passwords/OTP/private keys are never skill parameters.\n\nSKILL NAME: "+str(name)[:300]+"\nDESCRIPTION: "+str(description)[:3000])
    raw=_N260_ASK_PREV(cid,prompt,remember=False,timeout=180,deep=True,raw=True)
    try:
        m=_n270_re.search(r'\{[\s\S]*\}',str(raw or ''));d=_n270_json.loads(m.group(0) if m else str(raw or '{}'))
    except Exception:d={}
    steps=d.get('steps') if isinstance(d.get('steps'),list) else []
    if not steps:steps=[{'kind':'THINK','action':'Understand the requested workflow','payload':{},'risk':'LOW'}]
    sid=_n270_skill_create(cid,name,description,steps)
    return sid

def _n270_skill_get(cid,name_or_id):
    try:
        c=_n270_conn()
        r=c.execute("""SELECT id,name,description,risk,enabled FROM skills
          WHERE chat_id=? AND (id=? OR lower(name)=lower(?)) ORDER BY updated DESC LIMIT 1""",
          (str(cid),name_or_id,name_or_id)).fetchone()
        if not r:c.close();return None
        steps=c.execute("""SELECT ord,kind,action,payload,risk,approval FROM skill_steps
          WHERE skill_id=? ORDER BY ord""",(r[0],)).fetchall();c.close()
        return {'id':r[0],'name':r[1],'description':r[2],'risk':r[3],'enabled':bool(r[4]),'steps':steps}
    except Exception:return None

def _n270_skill_run(cid,name_or_id):
    sk=_n270_skill_get(cid,name_or_id)
    if not sk:return {'ok':False,'error':'skill not found'}
    if not sk['enabled']:return {'ok':False,'error':'skill disabled'}
    results=[]
    for ord_,kind,action,payload,risk,approval in sk['steps']:
        if approval:
            return {'ok':False,'status':'WAITING_APPROVAL','skill':sk['name'],'step':ord_,'kind':kind,
                    'action':action,'completed_safe_steps':results}
        prompt=("Execute this SAFE skill step cognitively/read-only. Do not perform external actions.\n"
                "SKILL: "+sk['name']+"\nSTEP: "+action+"\nPAYLOAD: "+payload+"\nPRIOR: "+str(results)[-6000:])
        r=_N260_ASK_PREV(cid,prompt,remember=False,timeout=180,deep=(kind in ('ANALYZE','RESEARCH','VERIFY')))
        results.append({'step':ord_,'kind':kind,'result':str(r)[:6000]})
    return {'ok':True,'status':'SAFE_STEPS_DONE','skill':sk['name'],'results':results}

# ---------------------------------------------------------------------------
# TOOL BUS 2
# ---------------------------------------------------------------------------
def _n270_health(tool,ok,latency_ms,error=''):
    try:
        c=_n270_conn();r=c.execute("SELECT success,failure,latency_ms FROM tool_health WHERE tool=?",(tool,)).fetchone()
        s=(r[0] if r else 0)+(1 if ok else 0);f=(r[1] if r else 0)+(0 if ok else 1)
        old=float(r[2] if r else 0);lat=(old*.75+float(latency_ms)*.25) if old else float(latency_ms)
        cooldown=0 if ok else (_n270_time.time()+min(600,30*(2**min(4,f))))
        c.execute("INSERT OR REPLACE INTO tool_health VALUES(?,?,?,?,?,?,?)",
          (tool,s,f,lat,cooldown,str(error)[:800],_n270_time.time()));c.commit();c.close()
    except Exception:pass

def n270_tool_invoke(cid,name,action,payload=None):
    payload=payload or {}
    x=_N260_TOOLS.get(name)
    rid='TB27-'+_n270_uuid.uuid4().hex[:10].upper()
    if not x:return {'ok':False,'receipt':rid,'error':'unknown tool'}
    try:
        c=_n270_conn();h=c.execute("SELECT cooldown_until FROM tool_health WHERE tool=?",(name,)).fetchone();c.close()
        if h and float(h[0] or 0)>_n270_time.time():
            return {'ok':False,'receipt':rid,'status':'COOLDOWN','error':'tool temporarily cooling down after failures'}
    except Exception:pass

    risk=str(x.get('risk') or 'LOW').upper()
    if risk in ('HIGH','CRITICAL'):
        return {'ok':False,'receipt':rid,'status':'WAITING_APPROVAL','risk':risk}
    started=_n270_time.time()
    try:
        result=x['handler'](action,payload)
        ok=bool(result);err=''
    except Exception as e:
        result=None;ok=False;err=type(e).__name__+': '+str(e)[:1000]
    ms=int((_n270_time.time()-started)*1000)
    _n270_health(name,ok,ms,err)
    return {'ok':ok,'receipt':rid,'status':'VERIFIED' if ok else 'FAILED',
            'tool':name,'action':action,'latency_ms':ms,'result':result,'error':err}

