_N270_ASK_PREV=ask_ai
def ask_ai(chat_id,text,image_b64=None,remember=True,timeout=180,long_output=False,models_override=None,deep=False,ground='',raw=False):
    src=str(text or '')
    _n281_tls=globals().get('_N281_TLS')
    _n281_suppress_graph=bool(getattr(_n281_tls,'suppress_graph',False)) if _n281_tls is not None else False
    if remember and len(src)<7000 and not _n281_suppress_graph:
        _n270_graph_extract(chat_id,src,'conversation')
        graph=_n270_graph_context(chat_id)
        # Only inject a compact recent graph; v25/v26 memory layers remain authoritative for durable facts.
        if graph:
            src=(graph+
              "\nCONTEXT GRAPH RULE: Use recent entities only when they resolve a current referent. "
              "Do not force unrelated recent entities into the answer.\n\nCURRENT MESSAGE:\n"+src)
    return _N270_ASK_PREV(chat_id,src,image_b64=image_b64,remember=remember,timeout=timeout,
      long_output=long_output,models_override=models_override,deep=deep,ground=ground,raw=raw)

# ---------------------------------------------------------------------------
# VOICE DEICTIC EXTENSION: app/file/topic continuity
# ---------------------------------------------------------------------------
def _n270_voice_context_intent(cid,device_id,text):
    t=' '.join(str(text or '').split()).strip()
    # "switch back to it/that app" => latest app context.
    if _n270_re.search(r'(?i)\b(?:switch back|go back|focus|bring it back)\b',t) and _n270_re.search(r'(?i)\b(it|that|that app|same app)\b',t):
        app=_n270_latest_node(cid,'app',4*3600)
        if app:
            return {'kind':'context_action','op':'focus_app','target':app['label'],'risk':'LOW',
                    'requires_approval':False,'verify':True}
    # "open that file again" => latest file context.
    if _n270_re.search(r'(?i)\b(?:open|show)\b.*\b(that file|same file|it again)\b',t):
        f=_n270_latest_node(cid,'file',8*3600)
        if f:
            return {'kind':'context_action','op':'open_file','target':f['value'] or f['label'],'risk':'LOW',
                    'requires_approval':False,'verify':True}
    return None

_N270_TURN_PREV=_v182_turn
def _v182_turn(device_id,audio_b64):
    out=_N270_TURN_PREV(device_id,audio_b64)
    if not isinstance(out,dict) or not out.get('ok'):return out
    cid=OWNER.get('id') or 0
    txt=' '.join(str(out.get('text') or '').split()).strip()
    _n270_graph_extract(cid,txt,'voice')
    ci=_n270_voice_context_intent(cid,device_id,txt)
    if ci:
        out.update({'route':'CONTROL','provider':'context-graph27','brain_ms':0,'reply':'',
                    'desktop_intent':ci,'control':True,'context_graph27':True})
    return out

