def _n270_eval():
    tests=[]
    def add(name,fn):
        try:ok=bool(fn());d='ok' if ok else 'false'
        except Exception as e:ok=False;d=type(e).__name__+': '+str(e)[:120]
        tests.append((name,ok,d))
    add('version',lambda:VERSION=='27.0')
    add('graph-node',lambda:bool(_n270_node(0,'topic','eval-topic','eval','eval',.5)))
    add('skill-safe-kinds',lambda:'READ_TOOL' in _N270_SAFE_KINDS and 'PAYMENT' in _N270_EXTERNAL_KINDS)
    add('toolbus-health',lambda:callable(n270_tool_invoke))
    add('inbox-add',lambda:bool(_n270_inbox_add(0,'eval action','eval','',1,'eval')))
    add('voice-context-func',lambda:callable(_n270_voice_context_intent))
    return tests

_N270_HANDLE_PREV=handle
def handle(msg):
    try:
        cid=msg.get('chat',{}).get('id');txt=(msg.get('text') or '').strip();lo=txt.lower()
        if lo in ('/nemo27','/productivity27','/toolbus27'):
            send_text(cid,
              'NEMO 27.0 — PRODUCTIVITY OS + SKILLS 4 + TOOL BUS 2 + CONTEXT GRAPH\n'
              'Action inbox: ACTIVE\nMission→next-action sync: ACTIVE\nOwner brief: ACTIVE\n'
              'Reusable typed skills: ACTIVE\nExternal skill steps: APPROVAL-GATED\n'
              'Tool health/cooldowns: ACTIVE\nTyped context graph: ACTIVE\n'
              'Voice app/file/media/person continuity: ACTIVE\n'
              'Existing v26 voice memory + media referents: PRESERVED')
            return
        if lo=='/brief27':
            send_text(cid,_n270_brief(cid));return
        if lo=='/inbox27':
            _n270_productivity_sync(cid);rows=_n270_inbox(cid,'OPEN',20)
            send_text(cid,'ACTION INBOX 27\n'+('\n'.join(
              '- %s | P%d | %s'%(r[0],r[4],r[1][:150]) for r in rows) if rows else 'No open actions.'));return
        if lo.startswith('/done27 '):
            iid=txt[len('/done27 '):].strip().upper()
            send_text(cid,'Action closed.' if _n270_inbox_close(cid,iid) else 'Action not found.');return
        if lo.startswith('/skill27 create '):
            body=txt[len('/skill27 create '):].strip()
            if '|' not in body:send_text(cid,'Use /skill27 create NAME | description');return
            name,desc=body.split('|',1);sid=_n270_skill_plan(cid,name.strip(),desc.strip())
            send_text(cid,'Skill created: '+sid+' | '+name.strip());return
        if lo.startswith('/skill27 run '):
            name=txt[len('/skill27 run '):].strip()
            r=_n270_skill_run(cid,name)
            send_text(cid,_n270_json.dumps(r,ensure_ascii=False,indent=2)[:3900]);return
        if lo=='/skills27':
            try:
                c=_n270_conn();rows=c.execute("SELECT id,name,risk,enabled FROM skills WHERE chat_id=? ORDER BY updated DESC LIMIT 30",(str(cid),)).fetchall();c.close()
            except Exception:rows=[]
            send_text(cid,'SKILLS 4\n'+('\n'.join('- %s | %s | %s'%(r[0],r[1],r[2]) for r in rows) if rows else 'No skills yet.'));return
        if lo=='/context27':
            send_text(cid,_n270_graph_context(cid) or 'No recent context graph yet.');return
        if lo=='/eval27':
            rows=_n270_eval();p=sum(1 for _,ok,_ in rows if ok)
            send_text(cid,'NEMO 27 SELF-EVAL %d/%d PASS\n'%(p,len(rows))+
              '\n'.join(('PASS' if ok else 'FAIL')+' | '+n+' | '+d for n,ok,d in rows));return
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail(msg.get('chat',{}).get('id'),'nemo27_handle',msg.get('text',''),str(e))
        except Exception:pass
    return _N270_HANDLE_PREV(msg)

_N270_MAIN_PREV=main
def main():
    try:
        c=_n270_conn();c.close()
        print('NEMO 27.0 PRODUCTIVITY OS + SKILLS 4 + TOOL BUS 2 + CONTEXT GRAPH READY')
    except Exception as e:print('NEMO27 init warning:',e)
    return _N270_MAIN_PREV()

# ============================ v27-AUDIT OWNER GATE ============================
# The base handler makes non-owner users chat-only (25 answers/day) and checks
# owner per-command — but every appended layer (v13.28 observability through
# v27 Skills/ToolBus) runs BEFORE the base handler, and none of those layers
# check the sender. Net effect before this gate: any stranger who found the bot
# could run all 124 layered commands (/superbrain, /execplan, /mission25 run,
# /skill27 run, status/eval dumps, ...) with no owner check and no daily limit.
# This outermost wrapper closes that: in private chats, slash commands from a
# non-owner are refused (except a small allowlist). Plain-text chat from
# strangers, the group flow, and first-boot owner claiming are unchanged.
_GATE_ALLOWED_PUBLIC_CMDS=('/start','/help')
_GATE_PREV_HANDLE=handle
def handle(msg):
    try:
        chat=msg.get('chat') or {}
        cid=chat.get('id')
        if chat.get('type','private')=='private':
            oid=OWNER.get('id')
            t=(msg.get('text') or '').strip()
            if oid and cid is not None and cid!=oid and t.startswith('/'):
                cmd=t.split()[0].split('@')[0].lower()
                if cmd not in _GATE_ALLOWED_PUBLIC_CMDS:
                    try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                    except Exception:pass
                    return
    except Exception:
        pass
    return _GATE_PREV_HANDLE(msg)

