VERSION='28.0'
import sqlite3 as _n28_sqlite, time as _n28_time, re as _n28_re, json as _n28_json
import os as _n28_os, hashlib as _n28_hashlib, uuid as _n28_uuid
import threading as _n28_threading

_N28_DB='/root/nemo28_cortex.db'
_N28_LOCK=_n28_threading.RLock()
_N28_RELATIONS={
    'wife_name':'wife','husband_name':'husband','father_name':'father','mother_name':'mother',
    'sister_name':'sister','brother_name':'brother','fiancee_name':'fiancee','fiance_name':'fiance',
    'partner_name':'partner','daughter_name':'daughter','son_name':'son'
}
_N28_SECRET_RE=_n28_re.compile(
    r'(?i)(password|passwd|otp|one[ -]?time password|cvv|private key|api[ _-]?key|access[ _-]?token|refresh[ _-]?token|authorization)\s*[:=]?\s*([^\s,;]{3,})')


def _n28_redact(text):
    s=str(text or '')
    return _N28_SECRET_RE.sub(lambda m:m.group(1)+'=[REDACTED]',s)[:12000]


def _n28_conn():
    c=_n28_sqlite.connect(_N28_DB,timeout=12)
    c.execute('PRAGMA journal_mode=WAL')
    c.execute('PRAGMA busy_timeout=8000')
    c.execute('PRAGMA synchronous=NORMAL')
    c.executescript("""
    CREATE TABLE IF NOT EXISTS meta(
      k TEXT PRIMARY KEY, v TEXT, updated REAL
    );
    CREATE TABLE IF NOT EXISTS facts(
      id TEXT PRIMARY KEY, chat_id TEXT, fkey TEXT, value TEXT, norm TEXT,
      source TEXT, confidence REAL, active INTEGER DEFAULT 1,
      seen_count INTEGER DEFAULT 1, created REAL, updated REAL
    );
    CREATE INDEX IF NOT EXISTS idx_n28_fact ON facts(chat_id,fkey,active,updated DESC);
    CREATE TABLE IF NOT EXISTS conflicts(
      id TEXT PRIMARY KEY, chat_id TEXT, fkey TEXT, old_value TEXT, new_value TEXT,
      old_conf REAL, new_conf REAL, source TEXT, status TEXT DEFAULT 'OPEN', created REAL
    );
    CREATE INDEX IF NOT EXISTS idx_n28_conflict ON conflicts(chat_id,status,created DESC);
    CREATE TABLE IF NOT EXISTS episodes(
      id TEXT PRIMARY KEY, chat_id TEXT, role TEXT, text TEXT, thread TEXT,
      source TEXT, latency_ms INTEGER DEFAULT 0, created REAL
    );
    CREATE INDEX IF NOT EXISTS idx_n28_episode ON episodes(chat_id,created DESC);
    CREATE TABLE IF NOT EXISTS lessons(
      id TEXT PRIMARY KEY, chat_id TEXT, topic TEXT, lesson TEXT, polarity TEXT,
      source TEXT, weight REAL DEFAULT 1.0, created REAL, updated REAL
    );
    CREATE INDEX IF NOT EXISTS idx_n28_lesson ON lessons(chat_id,updated DESC);
    CREATE TABLE IF NOT EXISTS visual_history(
      id TEXT PRIMARY KEY, chat_id TEXT, title TEXT, request TEXT, path TEXT, created REAL
    );
    """)
    return c


def _n28_meta_get(k,default=''):
    try:
        c=_n28_conn();r=c.execute('SELECT v FROM meta WHERE k=?',(str(k),)).fetchone();c.close()
        return r[0] if r else default
    except Exception:return default


def _n28_meta_set(k,v):
    try:
        c=_n28_conn();c.execute('INSERT OR REPLACE INTO meta(k,v,updated) VALUES(?,?,?)',(str(k),str(v),_n28_time.time()));c.commit();c.close();return True
    except Exception:return False


def _n28_norm(v):
    return ' '.join(str(v or '').strip(' .,!?:;').lower().split())[:500]


def _n28_pretty_name(v):
    x=' '.join(str(v or '').strip(' .,!?:;').split())
    if not x:return ''
    if x==x.lower():x=' '.join(p.capitalize() for p in x.split())
    return x[:180]


def _n28_thread(text):
    t=str(text or '').lower()
    if _n28_re.search(r'\b(nifty|sensex|banknifty|option|stock|trade|trading|fyers|dhan|zerodha)\b',t):return 'trading'
    if _n28_re.search(r'\b(loan|emi|credit card|debt|rupee|finance|money|budget)\b',t):return 'finance'
    if _n28_re.search(r'\b(business|shop|showroom|customer|sales|inventory|supplier|rent)\b',t):return 'business'
    if _n28_re.search(r'\b(project|code|python|nemo|nemotron|server|vps|api|bot)\b',t):return 'nemo'
    if _n28_re.search(r'\b(trip|travel|hotel|flight|train|visit)\b',t):return 'travel'
    if _n28_re.search(r'\b(kundli|astrology|gemstone|rahu|saturn|jupiter|pukhraj|gomed|gomet)\b',t):return 'astro'
    return 'general'


def _n28_episode(cid,role,text,source='chat',latency_ms=0):
    s=_n28_redact(text)
    if not s.strip():return ''
    eid='E28-'+_n28_uuid.uuid4().hex[:12].upper()
    try:
        c=_n28_conn();c.execute('INSERT INTO episodes VALUES(?,?,?,?,?,?,?,?)',
          (eid,str(cid),str(role),s,_n28_thread(s),str(source),int(latency_ms or 0),_n28_time.time()));c.commit();c.close()
    except Exception:return ''
    return eid


def _n28_current_fact(cid,key):
    try:
        c=_n28_conn();r=c.execute('SELECT id,value,norm,source,confidence,seen_count,updated FROM facts WHERE chat_id=? AND fkey=? AND active=1 ORDER BY updated DESC LIMIT 1',(str(cid),str(key))).fetchone();c.close()
        if not r:return None
        return {'id':r[0],'value':r[1],'norm':r[2],'source':r[3],'confidence':float(r[4] or 0),'seen_count':int(r[5] or 1),'updated':r[6]}
    except Exception:return None


def _n28_conflict(cid,key,old,new,old_conf,new_conf,source):
    xid='C28-'+_n28_uuid.uuid4().hex[:12].upper()
    try:
        c=_n28_conn();c.execute('INSERT INTO conflicts VALUES(?,?,?,?,?,?,?,?,?,?)',
          (xid,str(cid),str(key),str(old)[:500],str(new)[:500],float(old_conf or 0),float(new_conf or 0),str(source)[:120],'OPEN',_n28_time.time()));c.commit();c.close()
    except Exception:pass
    return xid


def _n28_set_fact(cid,key,value,source='explicit-user',confidence=.98,force=False):
    value=_n28_pretty_name(value) if str(key).endswith('_name') else ' '.join(str(value or '').split())[:1200]
    if not value:return {'ok':False,'status':'EMPTY'}
    norm=_n28_norm(value);now=_n28_time.time()
    with _N28_LOCK:
        cur=_n28_current_fact(cid,key)
        if cur and cur['norm']==norm:
            try:
                c=_n28_conn();c.execute('UPDATE facts SET value=?,source=?,confidence=?,seen_count=seen_count+1,updated=? WHERE id=?',
                  (value,str(source),max(float(confidence),cur['confidence']),now,cur['id']));c.commit();c.close()
            except Exception:pass
            return {'ok':True,'status':'REINFORCED','value':value,'previous':cur['value']}

        # A strong established fact is never silently overwritten by another ordinary statement.
        # Explicit correction language or /resolve28 is required unless the old fact was weak.
        if cur and not force:
            oldc=float(cur['confidence'] or 0);newc=float(confidence or 0)
            if oldc>=.90 or newc<=oldc+.08:
                xid=_n28_conflict(cid,key,cur['value'],value,oldc,newc,source)
                return {'ok':False,'status':'CONFLICT','value':value,'current':cur['value'],'conflict_id':xid}

        try:
            c=_n28_conn()
            c.execute('UPDATE facts SET active=0,updated=? WHERE chat_id=? AND fkey=? AND active=1',(now,str(cid),str(key)))
            fid='F28-'+_n28_uuid.uuid4().hex[:12].upper()
            c.execute('INSERT INTO facts VALUES(?,?,?,?,?,?,?,?,?,?,?)',
              (fid,str(cid),str(key),value,norm,str(source),float(confidence),1,1,now,now))
            if force:
                c.execute("UPDATE conflicts SET status='RESOLVED' WHERE chat_id=? AND fkey=? AND status='OPEN'",(str(cid),str(key)))
            c.commit();c.close()
            return {'ok':True,'status':'UPDATED' if cur else 'NEW','value':value,'previous':cur['value'] if cur else ''}
        except Exception as e:return {'ok':False,'status':'ERROR','error':type(e).__name__}


_N28_REL_PATTERNS=[
 ('wife_name',r"(?i)\bmy wife(?:'s)?\s+(?:name\s+is|is named|name's)\s+([A-Za-z][A-Za-z .'-]{1,80})"),
 ('wife_name',r"(?i)\bmeri wife ka naam\s+([A-Za-z][A-Za-z .'-]{1,80})\s+hai\b"),
 ('husband_name',r"(?i)\bmy husband(?:'s)?\s+(?:name\s+is|is named)\s+([A-Za-z][A-Za-z .'-]{1,80})"),
 ('father_name',r"(?i)\bmy father(?:'s)?\s+name\s+is\s+([A-Za-z][A-Za-z .'-]{1,80})"),
 ('mother_name',r"(?i)\bmy mother(?:'s)?\s+name\s+is\s+([A-Za-z][A-Za-z .'-]{1,80})"),
 ('sister_name',r"(?i)\bmy sister(?:'s)?\s+name\s+is\s+([A-Za-z][A-Za-z .'-]{1,80})"),
 ('brother_name',r"(?i)\bmy brother(?:'s)?\s+name\s+is\s+([A-Za-z][A-Za-z .'-]{1,80})"),
 ('fiancee_name',r"(?i)\bmy fianc(?:e|é)e(?:'s)?\s+name\s+is\s+([A-Za-z][A-Za-z .'-]{1,80})"),
 ('fiance_name',r"(?i)\bmy fianc(?:e|é)(?:'s)?\s+name\s+is\s+([A-Za-z][A-Za-z .'-]{1,80})"),
 ('partner_name',r"(?i)\bmy partner(?:'s)?\s+name\s+is\s+([A-Za-z][A-Za-z .'-]{1,80})"),
]


def _n28_extract_fact(cid,text,source='text-explicit'):
    t=' '.join(str(text or '').split())
    correction=bool(_n28_re.search(r'(?i)\b(actually|correction|correct that|i meant|change that|update that|galat|sahi naam|correct name)\b',t))
    for key,pat in _N28_REL_PATTERNS:
        m=_n28_re.search(pat,t)
        if not m:continue
        val=_n28_pretty_name(m.group(1))
        val=_n28_re.split(r'(?i)\s+(?:and|but|so|because|please|remember)\s+',val)[0].strip()
        return key,val,_n28_set_fact(cid,key,val,'owner-correction' if correction else source,.995 if correction else .98,force=correction)
    return None


def _n28_relation_answer(cid,text):
    t=' '.join(str(text or '').strip().lower().split())
    for key,rel in _N28_RELATIONS.items():
        variants=(
          'what is my '+rel+"'s name",'what is my '+rel+' name','who is my '+rel,
          'my '+rel+' ka naam kya','mera '+rel+' ka naam kya','meri '+rel+' ka naam kya')
        if any(v in t for v in variants):
            r=_n28_current_fact(cid,key)
            if r:return "Your %s's name is %s."%(rel,r['value'])
            return None
    m=_n28_re.match(r"(?i)^\s*who is\s+([A-Za-z][A-Za-z .'-]{1,80})[?.!]*\s*$",str(text or ''))
    if m:
        q=_n28_norm(m.group(1))
        try:
            c=_n28_conn();rows=c.execute('SELECT fkey,value,confidence FROM facts WHERE chat_id=? AND active=1 ORDER BY updated DESC LIMIT 100',(str(cid),)).fetchall();c.close()
        except Exception:rows=[]
        for k,v,conf in rows:
            if _n28_norm(v)==q and k in _N28_RELATIONS:return '%s is your %s.'%(v,_N28_RELATIONS[k])
    return None


def _n28_recent_episodes(cid,limit=8):
    try:
        c=_n28_conn();rows=c.execute('SELECT role,text,thread,source,created FROM episodes WHERE chat_id=? ORDER BY created DESC LIMIT ?',(str(cid),int(limit))).fetchall();c.close();return rows
    except Exception:return []


def _n28_referent_context(cid,text):
    t=str(text or '').lower()
    if not _n28_re.search(r'\b(it|that|this|same|again|earlier|previous|last one|that one|same one|there|them)\b',t):return ''
    lines=[]
    try:
        for typ in ('app','file','media','person','project','topic'):
            r=_n270_latest_node(cid,typ,12*3600)
            if r:lines.append('%s=%s'%(typ,r.get('value') or r.get('label')))
    except Exception:pass
    # Last two human messages are often a better deictic anchor than a generic graph node.
    for role,body,thread,source,ts in _n28_recent_episodes(cid,6):
        if role=='user' and body.strip() and body.strip().lower()!=str(text or '').strip().lower():
            lines.append('recent_user='+body[:350]);break
    return ('RESOLVED RECENT CONTEXT: '+'; '.join(lines[:7])) if lines else ''


def _n28_world_class(text):
    t=str(text or '').lower()
    if _n28_re.search(r'\b(my|mine|our|remember|last time|previous conversation|what did i|what did we|did i tell|earlier conversation|do you remember)\b',t):return 'PERSONAL'
    if _n28_re.search(r'\b(price|quote|nifty|sensex|banknifty|option chain|stock price)\b',t):return 'MARKET'
    if _n28_re.search(r'\b(live|right now|currently open|score now|traffic now)\b',t):return 'REALTIME'
    if _n28_re.search(r'\b(today|latest|recent|current|newest|this week|this month|released|launch|news)\b',t):return 'CURRENT'
    return 'STATIC'


def _n28_world_ground(text,limit=5):
    cls=_n28_world_class(text)
    if cls not in ('CURRENT','REALTIME'):return '',cls
    if not callable(globals().get('web_search')):return '',cls
    try:rows=web_search(str(text)[:700]) or []
    except Exception:return '',cls
    parts=[]
    for i,r in enumerate(rows[:int(limit)],1):
        title=str(r.get('title') or '')[:240];url=str(r.get('url') or r.get('href') or '')[:500]
        body=str(r.get('body') or r.get('snippet') or '')[:900]
        if title or body:parts.append('[FRESH-%d] %s\n%s\n%s'%(i,title,url,body))
    if not parts:return '',cls
    stamp=_n28_time.strftime('%Y-%m-%d %H:%M:%S',_n28_time.localtime())
    return ('FRESH WORLD EVIDENCE retrieved '+stamp+' local server time. Prefer this evidence for current claims; '
            'check dates and disagreements; do not invent missing facts.\n'+'\n\n'.join(parts)),cls


def _n28_lesson_tokens(s):
    return set(x for x in _n28_re.findall(r'[a-z0-9]{3,}',str(s or '').lower()) if x not in {'that','this','with','from','have','will','your','you','the','and','for','not'})


def _n28_teach(cid,lesson,topic='',polarity='GUIDANCE',source='owner'):
    lesson=_n28_redact(lesson).strip()
    if not lesson:return ''
    topic=(topic or _n28_thread(lesson))[:120]
    lid='L28-'+_n28_uuid.uuid4().hex[:12].upper();now=_n28_time.time()
    try:
        c=_n28_conn();c.execute('INSERT INTO lessons VALUES(?,?,?,?,?,?,?,?,?)',(lid,str(cid),topic,lesson,str(polarity),str(source),1.0,now,now));c.commit();c.close();return lid
    except Exception:return ''


def _n28_lesson_context(cid,text,limit=4):
    toks=_n28_lesson_tokens(text)
    if not toks:return ''
    try:
        c=_n28_conn();rows=c.execute('SELECT topic,lesson,polarity,weight,updated FROM lessons WHERE chat_id=? ORDER BY updated DESC LIMIT 80',(str(cid),)).fetchall();c.close()
    except Exception:rows=[]
    scored=[]
    for r in rows:
        lt=_n28_lesson_tokens(r[1]);ov=len(toks&lt)
        if ov:scored.append((ov*float(r[3] or 1),r))
    scored.sort(key=lambda x:x[0],reverse=True)
    if not scored:return ''
    return 'RELEVANT OWNER-TAUGHT LESSONS:\n'+'\n'.join('- '+x[1][1][:600] for x in scored[:int(limit)])


def _n28_capture_feedback(cid,text):
    t=str(text or '').strip();low=t.lower()
    if len(t)<4:return None
    if _n28_re.search(r"\b(that's wrong|that is wrong|you are wrong|you were wrong|not correct|galat hai|wrong answer)\b",low):
        return _n28_teach(cid,t,_n28_thread(t),'NEGATIVE_FEEDBACK','conversation-feedback')
    if _n28_re.search(r"\b(that worked|working now|perfect now|correct now|sahi hai|good now)\b",low):
        return _n28_teach(cid,t,_n28_thread(t),'POSITIVE_FEEDBACK','conversation-feedback')
    m=_n28_re.search(r'(?i)\b(?:next time|from now on|always remember to)\s+(.{6,700})',t)
    if m:return _n28_teach(cid,m.group(1),_n28_thread(t),'GUIDANCE','conversation-guidance')
    return None


def _n28_migrate_v26_once():
    if _n28_meta_get('migrated_v26')=='1':return 0
    path='/root/nemo26_voice_memory.db';n=0
    if _n28_os.path.exists(path):
        try:
            src=_n28_sqlite.connect('file:'+path+'?mode=ro',uri=True,timeout=5)
            rows=src.execute('SELECT chat_id,fkey,value,source,confidence FROM voice_facts WHERE active=1 ORDER BY updated').fetchall();src.close()
            for cid,key,val,source,conf in rows:
                r=_n28_set_fact(cid,key,val,'migrated-v26:'+str(source),float(conf or .9),force=False)
                if r.get('ok'):n+=1
        except Exception:pass
    _n28_meta_set('migrated_v26','1');return n


