def _n28_json_obj(raw):
    try:
        s=str(raw or '');m=_n28_re.search(r'\{[\s\S]*\}',s);return _n28_json.loads(m.group(0) if m else s)
    except Exception:return {}


def _n28_render_diagram(cid,spec,request_text=''):
    nodes=spec.get('nodes') if isinstance(spec.get('nodes'),list) else []
    edges=spec.get('edges') if isinstance(spec.get('edges'),list) else []
    title=str(spec.get('title') or 'Nemo Visual')[:120]
    clean=[]
    for i,n in enumerate(nodes[:14]):
        if not isinstance(n,dict):continue
        nid=str(n.get('id') or ('N'+str(i+1)))[:40];label=' '.join(str(n.get('label') or nid).split())[:120]
        clean.append({'id':nid,'label':label})
    if len(clean)<2:return {'ok':False,'error':'not enough diagram nodes'}
    ids={x['id'] for x in clean};ed=[]
    for e in edges[:24]:
        if not isinstance(e,dict):continue
        a=str(e.get('from') or '');b=str(e.get('to') or '')
        if a in ids and b in ids and a!=b:ed.append({'from':a,'to':b,'label':str(e.get('label') or '')[:60]})
    try:
        if not _imp('matplotlib',notify=False):auto_install('matplotlib',notify=False)
        import matplotlib
        matplotlib.use('Agg')
        import matplotlib.pyplot as plt
        from matplotlib.patches import FancyBboxPatch, FancyArrowPatch
        # Lightweight level assignment; cycles fall back to a balanced grid.
        indeg={x['id']:0 for x in clean};adj={x['id']:[] for x in clean}
        for e in ed:indeg[e['to']]+=1;adj[e['from']].append(e['to'])
        levels={k:0 for k in indeg};q=[k for k,v in indeg.items() if v==0]
        seen=set()
        while q:
            a=q.pop(0);seen.add(a)
            for b in adj.get(a,[]):
                levels[b]=max(levels[b],levels[a]+1);indeg[b]-=1
                if indeg[b]==0:q.append(b)
        if len(seen)<len(clean):
            for i,x in enumerate(clean):levels[x['id']]=i//4
        groups={}
        for x in clean:groups.setdefault(levels[x['id']],[]).append(x)
        max_level=max(groups) if groups else 0
        pos={}
        for lv,arr in groups.items():
            n=len(arr)
            for i,x in enumerate(arr):pos[x['id']]=((i+1)/(n+1),1-(lv+1)/(max_level+2))
        fig,ax=plt.subplots(figsize=(12,max(6,2.25*(max_level+2))))
        ax.set_xlim(0,1);ax.set_ylim(0,1);ax.axis('off');ax.set_title(title,fontsize=18,pad=18)
        for e in ed:
            x1,y1=pos[e['from']];x2,y2=pos[e['to']]
            ar=FancyArrowPatch((x1,y1-.04),(x2,y2+.04),arrowstyle='-|>',mutation_scale=14,linewidth=1.2,alpha=.75)
            ax.add_patch(ar)
            if e['label']:ax.text((x1+x2)/2,(y1+y2)/2,e['label'],fontsize=8,ha='center',va='center')
        for x in clean:
            px,py=pos[x['id']];w=.19;h=.085
            box=FancyBboxPatch((px-w/2,py-h/2),w,h,boxstyle='round,pad=0.012,rounding_size=0.018',linewidth=1.4,fill=False)
            ax.add_patch(box);ax.text(px,py,x['label'],ha='center',va='center',fontsize=9,wrap=True)
        ax.text(.01,.01,'Generated by NEMO Visual Cortex 28',fontsize=7,alpha=.65)
        _n28_os.makedirs('/root/nemo_visuals',exist_ok=True)
        path='/root/nemo_visuals/visual28_'+_n28_uuid.uuid4().hex[:10]+'.png'
        plt.tight_layout();plt.savefig(path,dpi=150,bbox_inches='tight');plt.close(fig)
    except Exception as e:return {'ok':False,'error':'renderer '+type(e).__name__+': '+str(e)[:150]}
    vid='V28-'+_n28_uuid.uuid4().hex[:10].upper()
    try:
        c=_n28_conn();c.execute('INSERT INTO visual_history VALUES(?,?,?,?,?,?)',(vid,str(cid),title,_n28_redact(request_text)[:3000],path,_n28_time.time()));c.commit();c.close()
    except Exception:pass
    return {'ok':True,'id':vid,'title':title,'path':path}


def n28_visualize(cid,request_text):
    req=' '.join(str(request_text or '').split()).strip()
    if not req:return {'ok':False,'error':'Tell me what to visualize.'}
    # Use the pre-v28 brain for an internal planning call to avoid recursive memory/visual routing.
    prompt=("NEMO VISUAL CORTEX. Convert the request into a truthful flow/system/mind-map diagram. "
            "Return JSON ONLY: {\"title\":\"...\",\"nodes\":[{\"id\":\"A\",\"label\":\"...\"}],"
            "\"edges\":[{\"from\":\"A\",\"to\":\"B\",\"label\":\"...\"}]}. "
            "Use 3-12 nodes. Do not invent numeric facts, named sources, dates or claims not present in the request/context. "
            "For a process, show sequence. For a system, show components and relationships. REQUEST: "+req[:5000])
    raw=_N28_ASK_PREV(cid,prompt,remember=False,timeout=180,deep=True,raw=True)
    spec=_n28_json_obj(raw)
    return _n28_render_diagram(cid,spec,req)


def _n28_send_visual(cid,res):
    if not res.get('ok'):
        send_text(cid,'Visual Cortex: '+str(res.get('error') or 'could not build diagram'));return False
    try:
        with open(res['path'],'rb') as f:
            rr=requests.post(TG+'/sendPhoto',data={'chat_id':cid,'caption':'🧠 '+res['title'][:180]},files={'photo':('nemo_visual.png',f)},timeout=120)
        if getattr(rr,'status_code',500)<300:return True
    except Exception:pass
    try:_send_file(cid,res['path'],'🧠 '+res['title']);return True
    except Exception:return False


