_N28_CONTROL_PREV=_v184_compile_control

def _n28_control_single(device_id,text):
    t=' '.join(str(text or '').split()).strip();low=t.lower()
    # Let the established voice-mode compiler own exact modes before generic focus matching.
    if low in ('focus mode','friend mode','silent mode','normal mode','nemo focus mode','nemo friend mode','nemo silent mode','nemo normal mode'):
        mode=_v184_mode_command(t) if callable(globals().get('_v184_mode_command')) else {'focus mode':'FOCUS','friend mode':'FRIEND','silent mode':'SILENT','normal mode':'NORMAL'}.get(low.replace('nemo ',''),'NORMAL')
        return {'kind':'voice_mode','mode':mode,'risk':'LOW','requires_approval':False}
    m=_n28_re.match(r'(?i)^(?:nemo[,. ]*)?search\s+(youtube|google|github)\s+(?:for\s+)?(.+)$',t)
    if m:return {'kind':'site_search','site':m.group(1).lower(),'query':m.group(2).strip()[:400],'risk':'LOW','requires_approval':False,'verify':True}
    m=_n28_re.match(r'(?i)^(?:nemo[,. ]*)?(?:switch to|focus|bring forward|activate)\s+(.+?)(?:\s+(?:window|app|application))?$',t)
    if m:
        target=m.group(1).strip()
        if target.lower()!='mode':return {'kind':'window_target','action':'activate','target':target[:180],'risk':'LOW','requires_approval':False,'verify':True}
    m=_n28_re.match(r'(?i)^(?:nemo[,. ]*)?close\s+(.+?)(?:\s+(?:browser|app|application|window))?$',t)
    if m:
        target=m.group(1).strip()
        if target.lower() not in ('everything','all','all windows'):
            return {'kind':'window_target','action':'close','target':target[:180],'risk':'MEDIUM','requires_approval':True,'verify':True}
    # Context-aware deictic window action.
    if _n28_re.search(r'(?i)^\s*(?:nemo[,. ]*)?close\s+(?:that|the same|it)\s+(?:app|window)?\s*$',t):
        try:r=_n270_latest_node(OWNER.get('id') or 0,'app',4*3600)
        except Exception:r=None
        if r:return {'kind':'window_target','action':'close','target':r['label'],'risk':'MEDIUM','requires_approval':True,'verify':True}
    return None


def _n28_control_sequence(device_id,text):
    t=' '.join(str(text or '').split()).strip()
    # Add natural "and" chaining only for imperative utterances, and only when every component compiles safely.
    if not _n28_re.match(r'(?i)^(?:nemo[,. ]*)?(open|search|switch|focus|close|volume|play|pause|scroll|show|take|create)\b',t):return None
    parts=_n28_re.split(r'(?i)\s+(?:and then|then|after that|and)\s+',t)
    parts=[p.strip(' ,') for p in parts if p.strip()][:5]
    if len(parts)<2:return None
    steps=[]
    for p in parts:
        x=_n28_control_single(device_id,p) or _N28_CONTROL_PREV(device_id,p)
        if not isinstance(x,dict) or x.get('kind') in ('control_sequence','voice_mode','blocked_sensitive'):return None
        steps.append(x)
    risk='MEDIUM' if any(x.get('risk') in ('MEDIUM','HIGH','CRITICAL') for x in steps) else 'LOW'
    return {'kind':'control_sequence','steps':steps,'risk':risk,'requires_approval':any(bool(x.get('requires_approval')) for x in steps),'verify':True}


def _v184_compile_control(device_id,text):
    return _n28_control_single(device_id,text) or _n28_control_sequence(device_id,text) or _N28_CONTROL_PREV(device_id,text)


# --------------------------- UNIFIED INTELLIGENCE ----------------------------
_N28_ASK_PREV=ask_ai

def ask_ai(chat_id,text,image_b64=None,remember=True,timeout=180,long_output=False,models_override=None,deep=False,ground='',raw=False):
    src=str(text or '')
    # Internal model/tool prompts must stay on the previous proven stack and must not pollute personal memory.
    if not remember:
        return _N28_ASK_PREV(chat_id,src,image_b64=image_b64,remember=False,timeout=timeout,long_output=long_output,models_override=models_override,deep=deep,ground=ground,raw=raw)
    _n28_episode(chat_id,'user',src,'text')
    _n28_capture_feedback(chat_id,src)
    fact=_n28_extract_fact(chat_id,src,'text-explicit') if len(src)<3000 else None
    if fact and not fact[2].get('ok') and fact[2].get('status')=='CONFLICT':
        return ("I did not overwrite the strong memory '%s' with '%s'. If you really want to change it, say "
                "'correction, %s' or use /resolve28 %s | %s."%(fact[2].get('current'),fact[1],src,fact[0],fact[1]))
    direct=_n28_relation_answer(chat_id,src)
    if direct:
        _n28_episode(chat_id,'assistant',direct,'memory28-local');return direct
    refctx=_n28_referent_context(chat_id,src)
    lessonctx=_n28_lesson_context(chat_id,src)
    worldctx,wclass=_n28_world_ground(src,5)
    extra=[x for x in (str(ground or ''),refctx,lessonctx,worldctx) if x]
    if refctx:
        extra.append('CONTINUITY RULE: Resolve obvious it/that/same-one references from the recent context. Ask only when more than one plausible referent remains.')
    if wclass in ('CURRENT','REALTIME'):
        extra.append('CURRENTNESS RULE: Distinguish retrieved facts from inference and mention the relevant date/time when freshness matters.')
    t0=_n28_time.time()
    ans=_N28_ASK_PREV(chat_id,src,image_b64=image_b64,remember=remember,timeout=timeout,long_output=long_output,
      models_override=models_override,deep=deep,ground='\n\n'.join(extra),raw=raw)
    ms=int((_n28_time.time()-t0)*1000)
    if ans:_n28_episode(chat_id,'assistant',str(ans),'brain',ms)
    return ans


