def _v182_turn(device_id,audio_b64):
    out=_N28_TURN_PREV(device_id,audio_b64)
    if not isinstance(out,dict) or not out.get('ok'):return out
    cid=OWNER.get('id') or 0;txt=' '.join(str(out.get('text') or '').split()).strip()
    if txt:_n28_episode(cid,'user',txt,'voice')
    fact=_n28_extract_fact(cid,txt,'voice-explicit') if txt else None
    if fact and not fact[2].get('ok') and fact[2].get('status')=='CONFLICT':
        out.update({'route':'MEMORY','provider':'memory-guard28','brain_ms':0,'control':False,
                    'reply':("I heard %s, but I already have %s stored with stronger confidence. I did not overwrite it. "
                             "Say correction if you want to change that memory."%(fact[1],fact[2].get('current'))),
                    'memory_guard28':True})
        return out
    direct=_n28_relation_answer(cid,txt) if txt else None
    if direct:
        out.update({'route':'MEMORY','provider':'memory28-local','brain_ms':0,'control':False,'reply':direct,'memory_guard28':True});return out
    ctl=_v184_compile_control(device_id,txt) if txt else None
    if isinstance(ctl,dict):
        allowed={'voice_mode','site_search','window_target','control_sequence','workspace_windows','open_target','open_url','open_search','open_uri','known_folder','media_key','window','key_press','scroll','mouse_click','find_file','system_status','screenshot_save','screen_describe','context_action','media_context','stop_speech','pause_listening','resume_listening'}
        if ctl.get('kind') in allowed:
            out.update({'route':'CONTROL','provider':'hands11-router','brain_ms':0,'reply':'','desktop_intent':ctl,'control':True,'hands11':True})
    return out


