# ========================== v28 OUTERMOST OWNER GATE ==========================
# New v28 natural-language abilities are owner-only. Public normal chat still falls through to the v27 behavior.
# Privileged slash commands remain blocked for non-owner private users. This wrapper MUST remain last.
_N28_GATE_PREV_HANDLE=_n28_inner_handle
_N28_PUBLIC_CMDS=('/start','/help')

def handle(msg):
    try:
        chat=msg.get('chat') or {};cid=chat.get('id');t=(msg.get('text') or '').strip();oid=OWNER.get('id')
        if chat.get('type','private')=='private' and oid and cid is not None and cid!=oid:
            if t.startswith('/'):
                cmd=t.split()[0].split('@')[0].lower()
                if cmd not in _N28_PUBLIC_CMDS:
                    try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                    except Exception:pass
                    return
            # Do not expose newly-added maintenance/action-like natural-language routes to strangers.
            if _n28_re.match(r'(?i)^\s*(visualize|make a diagram|speed status|nemo status|teach nemo|hands28)\b',t):
                try:send_text(cid,'That action is owner-only. You can still chat with me normally.')
                except Exception:pass
                return
    except Exception:pass
    return _N28_GATE_PREV_HANDLE(msg)


# =============================================================================
# NEMO 28.1 — CONTEXT HYGIENE + VISIBLE PROGRESS HOTFIX
# Fixes stale-topic bleed (including repeated AstroBot content), isolates internal
# synthesis from unrelated chat history, adds deterministic Telegram YouTube
# search, cleans leaked action payloads, and exposes safe progress stages.
# No expansion of trading/payment/security/shell authority.
# =============================================================================
VERSION='28.1'
import ast as _n281_ast, urllib.parse as _n281_urlparse
_N281_TLS=_n28_threading.local()

_N281_LEAK_MARKERS=(
    'astrology bot creation path','/newbot astrology','bot_token','owner_id','/ship astrobot',
    'factory returns creation confirmation','subject=',"'subject':",'body=',"'body':"
)


def _n281_current_text(text):
    s=str(text or '')
    # Later context wrappers often prepend CURRENT MESSAGE. Judge continuity on the actual user message.
    for marker in ('CURRENT MESSAGE:\n','OWNER REQUEST:\n','OWNER SAYS: '):
        if marker in s:
            s=s.rsplit(marker,1)[-1]
    return s.strip()


def _n281_contextual_query(text):
    t=_n281_current_text(text).lower()
    if not t:return False
    return bool(_n28_re.search(
      r"\b(it|that|this|same|again|continue|earlier|previous|last one|that one|same one|there|them|"
      r"what did i|what did we|do you remember|remember when|as before|like before|the one|open it|play it|send it|"
      r"above|below|last answer|previous answer|meri pichli|pehle wala|wahi|usko|isko)\b",t))


def _n281_progress_start(cid,label='🧭 Understanding your request...'):
    try:
        r=tg('sendMessage',chat_id=cid,text=label)
        return (r or {}).get('result',{}).get('message_id')
    except Exception:return None


def _n281_progress(cid,mid,label):
    if not mid:return
    try:tg('editMessageText',chat_id=cid,message_id=mid,text=label)
    except Exception:pass


def _n281_isolated_ai(prompt,timeout=120,deep=False,long_output=False,raw=False,ground=''):
    """Internal synthesis with no owner chat history/context graph. Uses chat id 0 deliberately."""
    old_h=bool(getattr(_N281_TLS,'no_history',False));old_g=bool(getattr(_N281_TLS,'suppress_graph',False))
    _N281_TLS.no_history=True;_N281_TLS.suppress_graph=True
    try:
        return _N281_ASK_PREV(0,str(prompt or ''),remember=False,timeout=timeout,deep=deep,long_output=long_output,raw=raw,ground=ground)
    finally:
        _N281_TLS.no_history=old_h;_N281_TLS.suppress_graph=old_g


def _n281_suspicious_leak(query,answer):
    q=_n281_current_text(query).lower();a=str(answer or '').lower()
    if any(x in q for x in ('astrology bot','astrobot','newbot','bot factory','bot_token','owner_id')):return False
    score=sum(1 for x in _N281_LEAK_MARKERS if x in a)
    return score>=2 or ('astrology bot creation path' in a and 'astrolog' not in q)


def _n281_relevance_repair(query,answer):
    ans=str(answer or '')
    if not _n281_suspicious_leak(query,ans):return ans
    prompt=(
      'NEMO RELEVANCE REPAIR. The candidate response contains stale/unrelated content from another task. '
      'Answer ONLY the CURRENT USER REQUEST. Remove every unrelated bot-factory, astrology, prior-email, prior-report, '
      'credential/config, or previous-task fragment. Do not mention that a repair happened. If the current request asks '
      'for a search and the candidate lacks verified results, say only what can actually be supported.\n\nCURRENT USER REQUEST:\n'
      +_n281_current_text(query)[:2500]+'\n\nBAD CANDIDATE:\n'+ans[:6500])
    fixed=_n281_isolated_ai(prompt,timeout=90,deep=False)
    return str(fixed or '').strip() or 'I could not produce a clean relevant answer for that request. Please try once more.'


def _n281_unwrap_payload(text):
    """Unwrap accidental Python-like subject/body action payloads without touching normal code/JSON output."""
    s=str(text or '')
    head=s[:500].lower()
    if '```' in s[:120]:return s
    if not (('subject=' in head and 'body=' in s.lower()) or ("'subject':" in head and "'body':" in s.lower()) or ('"subject":' in head and '"body":' in s.lower())):
        return s
    pats=(r"\bbody\s*=\s*(?P<lit>'(?:\\.|[^'])*'|\"(?:\\.|[^\"])*\")",
          r"['\"]body['\"]\s*:\s*(?P<lit>'(?:\\.|[^'])*'|\"(?:\\.|[^\"])*\")")
    for pat in pats:
        m=_n28_re.search(pat,s,_n28_re.S)
        if not m:continue
        try:body=_n281_ast.literal_eval(m.group('lit'))
        except Exception:continue
        if isinstance(body,str) and len(body.strip())>=40:return body.strip()
    return s


def _n281_output_clean(text):
    s=_n281_unwrap_payload(text)
    # Literal escaped newlines are a common symptom of leaked serialized text; decode only when clearly not code.
    if s.count('\\n')>=3 and '```' not in s and not _n28_re.search(r'(?m)^\s*(def |class |import |from \w+ import )',s):
        s=s.replace('\\r\\n','\n').replace('\\n','\n').replace('\\t','    ')
    return s


# User-facing output hygiene wrappers. Exact action payloads are cleaned; ordinary JSON/code is unchanged.
_N281_SEND_TEXT_PREV=send_text
def send_text(chat_id,text,kb=None):
    return _N281_SEND_TEXT_PREV(chat_id,_n281_output_clean(text),kb=kb)

_N281_DELIVER_PREV=deliver
def deliver(chat_id,mid,text,buttons=False):
    return _N281_DELIVER_PREV(chat_id,mid,_n281_output_clean(text),buttons=buttons)


# Current v28.0 ask wrapper becomes the parent. Independent user questions do not inherit stale short-term HISTORY
# or recent context-graph nodes; explicit follow-ups still do. Durable memory/owner facts remain available.
_N281_ASK_PREV=ask_ai
def ask_ai(chat_id,text,image_b64=None,remember=True,timeout=180,long_output=False,models_override=None,deep=False,ground='',raw=False):
    src=str(text or '')
    contextual=_n281_contextual_query(src)
    old_h=bool(getattr(_N281_TLS,'no_history',False));old_g=bool(getattr(_N281_TLS,'suppress_graph',False))
    if remember and not contextual:
        _N281_TLS.no_history=True;_N281_TLS.suppress_graph=True
    try:
        ans=_N281_ASK_PREV(chat_id,src,image_b64=image_b64,remember=remember,timeout=timeout,
          long_output=long_output,models_override=models_override,deep=deep,ground=ground,raw=raw)
    finally:
        _N281_TLS.no_history=old_h;_N281_TLS.suppress_graph=old_g
    if raw:return ans
    return _n281_relevance_repair(src,_n281_output_clean(ans))


# Selective v17 context fusion: independent/general/current requests no longer receive unrelated owner/open-loop/
# capability/history payloads. Context is fetched only when the request actually needs it.
_N281_CONTEXT_PACK_PREV=_v170_context_pack
def _v170_context_pack(chat_id,query,profile=None):
    profile=profile or _v170_task_profile(query);q=_n281_current_text(query);low=q.lower()
    contextual=_n281_contextual_query(q)
    personal=bool(profile.get('owner')) or bool(_n28_re.search(r'\b(my|mine|our|me|remember|family|wife|father|mother|project)\b',low))
    needs_loops=bool(_n28_re.search(r'\b(pending|unfinished|open loop|todo|task|follow.?up|what is left|remaining)\b',low))
    needs_caps=profile.get('class')=='ACTION' or bool(_n28_re.search(r'\b(can you|ability|capability|tool|how can nemo|what can you do)\b',low))
    needs_rag=profile.get('class') in ('DEEP_REASONING','OWNER_CONTEXT') or bool(_n28_re.search(r'\b(my files|document|report|notes|knowledge|project|agreement|registry)\b',low))
    # Fresh independent research should stay clean; live evidence is gathered separately by Superbrain.
    if profile.get('class') in ('GENERAL','FRESH_RESEARCH') and not (contextual or personal or needs_loops or needs_caps or needs_rag):
        return '',{}
    jobs={}
    def safe(fn,*a):
        try:return fn(*a)
        except Exception:return None
    with _v170_cf.ThreadPoolExecutor(max_workers=5) as ex:
        if personal:jobs['owner']=ex.submit(safe,owner_state_snapshot)
        if needs_loops:jobs['loops']=ex.submit(safe,open_loop_list,'OPEN',10)
        if needs_rag:jobs['rag']=ex.submit(safe,prime_rag_context,q,6,7000)
        if needs_caps:jobs['caps']=ex.submit(safe,prime_capabilities,q)
        if contextual or personal:jobs['ctxgraph']=ex.submit(safe,prime_context_search,q,8)
        if contextual:
            try:jobs['turns']=ex.submit(safe,_v163_recent_turns,chat_id,6)
            except Exception:pass
        results={}
        for k,f in jobs.items():
            try:results[k]=f.result(timeout=8)
            except Exception:results[k]=None
    sections=[]
    if results.get('owner'):sections.append('OWNER STATE:\n'+_v170_clip(results['owner'],3000))
    if results.get('loops'):sections.append('OPEN LOOPS:\n'+_v170_clip(results['loops'],2200))
    if results.get('turns'):sections.append('RECENT CONVERSATION:\n'+_v170_clip(results['turns'],2800))
    if results.get('ctxgraph'):sections.append('PERSONAL CONTEXT GRAPH:\n'+_v170_clip(results['ctxgraph'],2600))
    if results.get('rag'):sections.append('LOCAL KNOWLEDGE / RAG:\n'+_v170_clip(results['rag'],6500))
    if results.get('caps'):sections.append('AVAILABLE CAPABILITIES:\n'+_v170_clip(results['caps'],3000))
    return '\n\n'.join(sections)[:16000],results


# Internal Visual Cortex planning must never inherit an unrelated Telegram conversation.
_N281_VISUAL_PREV=n28_visualize
def n28_visualize(cid,request_text):
    req=' '.join(str(request_text or '').split()).strip()
    if not req:return {'ok':False,'error':'Tell me what to visualize.'}
    prompt=("NEMO VISUAL CORTEX. Convert the request into a truthful flow/system/mind-map diagram. "
            "Return JSON ONLY: {\"title\":\"...\",\"nodes\":[{\"id\":\"A\",\"label\":\"...\"}],"
            "\"edges\":[{\"from\":\"A\",\"to\":\"B\",\"label\":\"...\"}]}. "
            "Use 3-12 nodes. Do not import unrelated prior topics. Do not invent numeric facts, named sources, dates or claims "
            "not present in the request/context. REQUEST: "+req[:5000])
    raw=_n281_isolated_ai(prompt,timeout=180,deep=True,raw=True)
    return _n28_render_diagram(cid,_n28_json_obj(raw),req)


def _n281_store_web_turn(cid,query,answer):
    try:
        with LOCK:
            h=HISTORY.setdefault(cid,[])
            h.append({'role':'user','content':str(query)[:2000]});h.append({'role':'assistant','content':str(answer)[:3000]});del h[:-50]
    except Exception:pass
    try:_n28_episode(cid,'user',query,'web-search');_n28_episode(cid,'assistant',answer,'web-search')
    except Exception:pass


# Replace generic web synthesis with a history-isolated, relevance-locked path and visible stages.
def web_answer(chat_id,query):
    q=' '.join(str(query or '').split()).strip()
    mid=_n281_progress_start(chat_id,'🔎 Searching the web...')
    results=web_search(q)
    if not results:
        deliver(chat_id,mid,'Web search is unavailable right now. I did not invent results. Try again shortly or run /doctor.');return
    _n281_progress(chat_id,mid,'🧠 Analysing %d fresh search results...'%min(len(results),5))
    rows=[]
    for i,r in enumerate(results[:5],1):
        rows.append('[%d] %s\n%s\n%s'%(i,str(r.get('title') or '')[:260],str(r.get('href') or r.get('url') or '')[:600],str(r.get('body') or r.get('snippet') or '')[:1200]))
    prompt=(
      'Answer ONLY the current request using ONLY the fresh search results below. Do not use unrelated prior chat, old tasks, '
      'bot-factory instructions, astrology content, or cached assistant answers. If the results do not support a claim, say so. '
      'For a search request, give the most useful matching results and links instead of asking the user to provide a URL that you '
      'can already find.\n\nCURRENT REQUEST:\n'+q+'\n\nFRESH RESULTS:\n'+'\n\n'.join(rows))
    out=_n281_isolated_ai(prompt,timeout=120,deep=('research' in q.lower() or len(q)>180))
    out=_n281_relevance_repair(q,_n281_output_clean(out))
    srcs='\n'.join('[%d] %s'%(i+1,str(r.get('href') or r.get('url') or '')) for i,r in enumerate(results[:5]) if (r.get('href') or r.get('url')))
    if srcs:out=str(out).rstrip()+'\n\nSources:\n'+srcs
    _n281_store_web_turn(chat_id,q,out)
    deliver(chat_id,mid,out,buttons=True)


def _n281_youtube_results(query,limit=5):
    q=' '.join(str(query or '').split()).strip();raw=web_search('site:youtube.com/watch '+q) or []
    out=[];seen=set()
    for r in raw:
        u=str(r.get('href') or r.get('url') or '').strip();title=' '.join(str(r.get('title') or '').split()).strip()
        if not u or ('youtube.com/watch' not in u and 'youtu.be/' not in u):continue
        if u in seen:continue
        seen.add(u);out.append({'title':title or 'YouTube result','url':u,'snippet':' '.join(str(r.get('body') or r.get('snippet') or '').split())[:320]})
        if len(out)>=int(limit):break
    return out


def _n281_youtube_search(cid,query,source_text=''):
    q=' '.join(str(query or '').split()).strip();mid=_n281_progress_start(cid,'🔎 Searching YouTube...')
    rows=_n281_youtube_results(q,5)
    if not rows:
        url='https://www.youtube.com/results?search_query='+_n281_urlparse.quote_plus(q)
        try:_n260_ref_set(cid,'telegram','media_search',q,{'query':q,'service':'youtube','url':url},source_text or q)
        except Exception:pass
        deliver(cid,mid,'I could not verify individual video results through web search, so I will not invent them.\n\nYouTube search:\n'+url);return
    _n281_progress(cid,mid,'🧠 Analysing YouTube results...')
    first=rows[0]
    try:_n260_ref_set(cid,'telegram','media_search',q,{'query':q,'service':'youtube','url':first['url'],'results':rows},source_text or q)
    except Exception:pass
    try:_n270_node(cid,'media',first['title'],first['url'],source_text or q,.96)
    except Exception:pass
    lines=['▶️ YouTube results for: '+q]
    for i,r in enumerate(rows,1):
        lines.append('\n%d. %s\n%s'%(i,r['title'],r['url']))
    lines.append('\nI saved result #1 as the current media referent. You can say: “play that latest one”.')
    deliver(cid,mid,'\n'.join(lines),buttons=True)


def _n281_history_clean(cid):
    removed=0
    try:
        with LOCK:
            h=list(HISTORY.get(cid,[]));new=[]
            for x in h:
                txt=str(x.get('content') or '')
                bad=('astrology bot creation path' in txt.lower() and ('/newbot' in txt.lower() or 'bot_token' in txt.lower())) or \
                    (('subject=' in txt[:500].lower() or "'subject':" in txt[:500].lower()) and ('body=' in txt.lower() or "'body':" in txt.lower()))
                if bad:removed+=1;continue
                new.append(x)
            HISTORY[cid]=new[-50:]
    except Exception:pass
    return removed


_N281_HANDLE_PREV=handle
def _n281_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo281','/hotfix281'):
        send_text(cid,'NEMO 28.1 — CONTEXT HYGIENE + VISIBLE PROGRESS\nHistory isolation: ACTIVE\nContext Graph relevance gate: ACTIVE\nSuperbrain selective context: ACTIVE\nWeb synthesis isolation: ACTIVE\nYouTube deterministic search: ACTIVE\nOutput payload cleaner: ACTIVE\nProgress stages: ACTIVE\nAuthority expansion: NONE');return True
    if low=='/contextclean28':
        n=_n281_history_clean(cid);
        try:save_data()
        except Exception:pass
        send_text(cid,'Short-term context hygiene complete. Removed %d leaked/stale payload turn(s). Durable memories/databases were not deleted.'%n);return True
    # Telegram-specific YouTube search. Do this before the old general-web NL route.
    m=_n28_re.match(r'(?i)^\s*(?:nemo[,. ]*)?(?:search|find|look up)\s+(?:on\s+)?youtube\s+(?:for\s+)?(.{2,500})$',txt)
    if not m:
        m=_n28_re.match(r'(?i)^\s*(?:nemo[,. ]*)?search\s+youtube\s+for\s+(.{2,500})$',txt)
    if m:
        q=m.group(1).strip();_n28_threading.Thread(target=_n281_youtube_search,args=(cid,q,txt),daemon=True,name='nemo-youtube281').start();return True
    if _n28_re.match(r'(?i)^\s*(?:nemo[,. ]*)?play\s+(?:that|it|the)\s+(?:latest\s+)?(?:one|song|video)\s*$',txt):
        try:ref=_n260_ref_get(cid,'telegram','media_search')
        except Exception:ref=None
        url=((ref or {}).get('payload') or {}).get('url') if ref else ''
        if url:
            send_text(cid,'▶️ Latest saved YouTube result:\n'+url);return True
    return False


def handle(msg):
    try:
        if _n281_dispatch(msg):return
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo281_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N281_HANDLE_PREV(msg)


# Cumulative regression extension.
_N281_REGRESSION_PREV=prime_regression_suite
def prime_regression_suite():
    r=_N281_REGRESSION_PREV();extra=[]
    if isinstance(r,dict):
        # Superseded by the effective v28.1 contract below.
        r['tests']=[x for x in r.get('tests',[]) if x.get('name')!='v28-version']
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v281-version',lambda:VERSION=='28.1')
    add('v281-context-independent',lambda:not _n281_contextual_query('Search YouTube for latest Arijit Singh song'))
    add('v281-context-followup',lambda:_n281_contextual_query('play that latest one'))
    add('v281-relevance-leak-detect',lambda:_n281_suspicious_leak('search youtube for music','Astrology Bot Creation Path /newbot astrology BOT_TOKEN OWNER_ID'))
    add('v281-output-payload-clean',lambda:'\\n' not in _n281_output_clean("subject='x', body='Hello\\nWorld\\nAgain\\nDone'"))
    add('v281-youtube-router',lambda:bool(_n28_re.match(r'(?i)^\s*(?:nemo[,. ]*)?(?:search|find|look up)\s+(?:on\s+)?youtube\s+(?:for\s+)?(.{2,500})$','Search YouTube for latest Arijit Singh song')))
    add('v281-progress',lambda:callable(_n281_progress_start) and callable(_n281_progress))
    add('v281-selective-superbrain-context',lambda:_v170_context_pack(0,'What is photosynthesis?',_v170_task_profile('What is photosynthesis?'))[0]=='')
    if not isinstance(r,dict):
        return {'id':'RG281-'+_n28_uuid.uuid4().hex[:8].upper(),'version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r


# Keep /eval28 useful on 28.1 while adding the new checks.
_N281_EVAL_PREV=_n28_eval
def _n28_eval():
    rows=_N281_EVAL_PREV()
    for x in rows:
        if x.get('name')=='v28-version':x['ok']=str(VERSION).startswith('28.');x['detail']='compatible '+str(VERSION)
    rows.extend([
      {'name':'v281-context-hygiene','ok':not _n281_contextual_query('latest AI news today'),'detail':'ok'},
      {'name':'v281-youtube-search','ok':callable(_n281_youtube_search),'detail':'ok'},
      {'name':'v281-output-clean','ok':callable(_n281_output_clean),'detail':'ok'},
      {'name':'v281-progress-ui','ok':callable(_n281_progress),'detail':'ok'}])
    return rows


