# =============================================================================
# NEMO 28.2 — RESPONSIVE ROUTER + REQUEST WATCHDOG
# Fixes the hidden pre-answer stall where nl_route() called the network LLM intent
# classifier before ordinary chat reached answer(). Ordinary informational chat now
# bypasses the action classifier, starts in a worker thread, and immediately exposes
# Telegram progress/typing. The natural-language action classifier is hard-bounded.
# No expansion of trading/payment/security/shell authority.
# =============================================================================
VERSION='28.2'
import uuid as _n282_uuid

_N282_PREV_HANDLE=handle
_N282_PREV_NL_CALL=_nl_call
_N282_STATE_LOCK=_n28_threading.RLock()
_N282_ACTIVE={}

# Strong action markers: these should continue through the mature deterministic/action
# routing stack rather than being mistaken for ordinary informational chat.
_N282_ACTION_RE=_n28_re.compile(
  r"(?i)(?:^|\b)(?:open|close|search|find|look\s+up|download|save|send|email|mail|call|remind|"
  r"remember|forget|create|make|build|generate|run|execute|start|stop|turn\s+on|turn\s+off|set|"
  r"schedule|add\s+(?:a|an|to)|delete|remove|upload|install|restart|lock|unlock|play|pause|next|previous|"
  r"switch|focus|volume|mute|click|type|scroll|place\s+(?:an\s+)?order|buy|sell|trade|order|visualize|"
  r"draw|fetch|scrape|browse|go\s+to|visit|connect|disconnect|ship|deploy|update|rollback|backup)\b")

_N282_ARTIFACT_RE=_n28_re.compile(
  r"(?i)\b(pdf|docx|word\s+document|excel|xlsx|spreadsheet|csv|file|attachment|chart|graph|diagram|"
  r"pine\s*script|pinescript|tradingview|python\s+script|code\s+file|presentation|pptx|slides?)\b")

_N282_OWNER_STATE_RE=_n28_re.compile(
  r"(?i)\b(pending\s+(?:task|tasks|work)|todo|to-do|open\s+loop|inbox|status\s+center|nemo\s+status|"
  r"my\s+files|my\s+documents|my\s+calendar|my\s+email|my\s+inbox|positions?|funds|portfolio)\b")

_N282_INFO_START_RE=_n28_re.compile(
  r"(?i)^\s*(?:please\s+)?(?:what\b|why\b|how\b|who\b|where\b|when\b|which\b|explain\b|describe\b|"
  r"teach\s+me\b|tell\s+me\s+about\b|compare\b|difference\b|analyse\b|analyze\b|is\b|are\b|does\b|"
  r"do\b|can\b|could\b|should\b|would\b|give\s+me\s+(?:information|details|an\s+overview)\b)")


def _n282_currentish(text):
    q=' '.join(str(text or '').split()).strip()
    try:
        wc=_n28_world_class(q)
        if wc in ('CURRENT','REALTIME','MARKET'):
            return True
    except Exception:
        pass
    l=q.lower()
    return bool(_n28_re.search(r"\b(latest|today|right now|currently|current news|breaking|this week|live news)\b",l))


def _n282_direct_chat(text):
    """True for ordinary conversational/informational messages that should skip nl_intent()."""
    t=' '.join(str(text or '').split()).strip()
    if not t or t.startswith('/'):
        return False
    low=t.lower()
    # Keep explicit device/tool/external-effect requests on the mature action router.
    if _N282_ACTION_RE.search(t) or _N282_ARTIFACT_RE.search(t) or _N282_OWNER_STATE_RE.search(t):
        # Informational phrasing such as "how does email work" is still chat unless it asks Nemo to act.
        if _N282_INFO_START_RE.search(t) and not _n28_re.search(
            r"(?i)\b(?:for\s+me|now|on\s+my|my\s+laptop|my\s+computer|my\s+phone|to\s+my|from\s+my)\b",t):
            # Artifact nouns remain routed to makers when user asks creation verbs; here there are none at the start.
            if not _n28_re.match(r"(?i)^\s*(?:can|could|would)\s+you\s+(?:open|close|search|find|download|send|email|"
                                 r"create|make|build|run|play|set|schedule|delete|upload|install|restart|visualize|draw)\b",t):
                return True
        return False
    # Obvious informational starts, greetings, statements/facts, and normal social chat bypass the classifier.
    if _N282_INFO_START_RE.search(t):
        return True
    if _n28_re.match(r"(?i)^\s*(?:hi|hello|hey|thanks|thank\s+you|good\s+(?:morning|afternoon|evening)|"
                     r"my\s+|i\s+am\b|i'm\b|i\s+think\b|i\s+have\b|i\s+want\s+to\s+know\b)",t):
        return True
    # If there is no action-like verb at all, treating it as chat is safer than spending a network call to classify it.
    return not bool(_N282_ACTION_RE.search(t))


def _n282_nl_call(msgs):
    """Hard-bounded action classifier: fast providers only; failure falls through to normal chat."""
    # Groq first, but unlike the legacy groq_chat() this classifier never waits 60s per model.
    if GROQ_KEY:
        models=list(globals().get('_V135_GROQ_MODELS') or ['llama-3.1-8b-instant','llama-3.3-70b-versatile'])[:2]
        for m in models:
            try:
                r=requests.post('https://api.groq.com/openai/v1/chat/completions',
                    headers={'Authorization':'Bearer '+GROQ_KEY,'Content-Type':'application/json'},
                    json={'model':m,'messages':msgs,'max_tokens':180,'temperature':0},timeout=(3.5,8.5))
                if r.status_code==200:
                    j=r.json() or {};c=((j.get('choices') or [{}])[0].get('message') or {}).get('content','')
                    if str(c or '').strip():return str(c).strip()
            except Exception:
                continue
    # One short OpenRouter lane. Do not cascade through every provider for a mere intent classification.
    if OPENROUTER_KEY:
        try:
            mods=_model_route_unique(list(FAST_MODELS))[:2]
        except Exception:
            mods=list(FAST_MODELS)[:2]
        for m in mods:
            try:
                r=requests.post(OR_URL,headers={'Authorization':'Bearer '+OPENROUTER_KEY,'Content-Type':'application/json'},
                    json={'model':m,'messages':msgs,'max_tokens':180,'reasoning':{'effort':'low'}},timeout=(3.5,9.5))
                if r.status_code==200:
                    j=r.json() or {};c=((j.get('choices') or [{}])[0].get('message') or {}).get('content','')
                    if str(c or '').strip():return str(c).strip()
            except Exception:
                continue
    return None

# nl_intent resolves _nl_call dynamically, so this safely replaces only the classifier transport.
_nl_call=_n282_nl_call


def _n282_mark(cid,token,text):
    with _N282_STATE_LOCK:
        _N282_ACTIVE[str(cid)]={'token':token,'text':str(text or '')[:500],'started':_n28_time.time()}


def _n282_is_active(cid,token):
    with _N282_STATE_LOCK:
        return (_N282_ACTIVE.get(str(cid)) or {}).get('token')==token


def _n282_clear(cid,token):
    with _N282_STATE_LOCK:
        if (_N282_ACTIVE.get(str(cid)) or {}).get('token')==token:
            _N282_ACTIVE.pop(str(cid),None)


def _n282_watchdog(cid,token,done):
    """Visible liveness without exposing chain-of-thought."""
    t0=_n28_time.time();notified25=False;notified55=False
    while not done.wait(4.0):
        if not _n282_is_active(cid,token):return
        try:tg('sendChatAction',chat_id=cid,action='typing')
        except Exception:pass
        age=_n28_time.time()-t0
        if age>=25 and not notified25:
            notified25=True
            try:send_text(cid,'⏳ Still working — the brain/provider is slower than normal. I am keeping the request alive and fallback routing remains active.')
            except Exception:pass
        if age>=55 and not notified55:
            notified55=True
            try:send_text(cid,'🔄 Still working — this is taking too long. Nemo is still responsive; you can send /debug or /brain while this request finishes.')
            except Exception:pass


def _n282_run_chat(cid,text,current=False):
    token='RQ282-'+_n282_uuid.uuid4().hex[:10].upper();done=_n28_threading.Event();_n282_mark(cid,token,text)
    _n28_threading.Thread(target=_n282_watchdog,args=(cid,token,done),daemon=True,name='nemo-watchdog282').start()
    try:
        if current:
            web_answer(cid,text)
        else:
            answer(cid,text)
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail(cid,'nemo282_chat',text,str(e))
        except Exception:pass
        try:send_text(cid,'⚠️ That request failed instead of hanging silently: '+type(e).__name__+'. Send /debug for the provider trace.')
        except Exception:pass
    finally:
        done.set();_n282_clear(cid,token)


def _n282_status(cid):
    with _N282_STATE_LOCK:
        a=dict(_N282_ACTIVE.get(str(cid)) or {})
    if not a:return 'NEMO 28.2 RESPONSIVE ROUTER\nActive chat request: NONE\nHidden pre-answer classifier stall: BYPASSED for normal chat\nAction classifier hard timeout: ACTIVE\nTyping heartbeat: ACTIVE\n25s/55s watchdog: ACTIVE\nAuthority expansion: NONE'
    age=max(0,int(_n28_time.time()-float(a.get('started') or _n28_time.time())))
    return 'NEMO 28.2 RESPONSIVE ROUTER\nActive request: %ss\nRequest: %s\nTyping heartbeat: ACTIVE\nWatchdog: ACTIVE'%(age,str(a.get('text') or '')[:250])


def _n282_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo282','/responsive28','/watchdog28'):
        send_text(cid,_n282_status(cid));return True
    return False


def handle(msg):
    try:
        if _n282_dispatch(msg):return
        cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();chat=(msg.get('chat') or {})
        if cid==OWNER.get('id') and txt and not txt.startswith('/') and chat.get('type','private')=='private':
            if _n282_direct_chat(txt):
                # Keep the Telegram polling loop free: long AI work happens in a daemon worker.
                _n28_threading.Thread(target=_n282_run_chat,args=(cid,txt,_n282_currentish(txt)),daemon=True,name='nemo-chat282').start()
                return
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo282_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N282_PREV_HANDLE(msg)


# Extend regression without deleting historical tests.
_N282_REGRESSION_PREV=prime_regression_suite
def prime_regression_suite():
    r=_N282_REGRESSION_PREV();extra=[]
    if isinstance(r,dict):
        r['tests']=[x for x in r.get('tests',[]) if x.get('name')!='v281-version']
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v282-version',lambda:VERSION=='28.2')
    add('v282-cbg-direct-chat',lambda:_n282_direct_chat('Explain how a CBG plant works'))
    add('v282-youtube-stays-action',lambda:not _n282_direct_chat('Search YouTube for latest Arijit Singh song'))
    add('v282-play-referent-stays-action',lambda:not _n282_direct_chat('play that latest one'))
    add('v282-open-chrome-stays-action',lambda:not _n282_direct_chat('open Chrome'))
    add('v282-memory-question-chat',lambda:_n282_direct_chat("What is my wife's name?"))
    add('v282-nl-hard-bounded',lambda:_nl_call is _n282_nl_call)
    add('v282-watchdog',lambda:callable(_n282_watchdog) and callable(_n282_run_chat))
    if not isinstance(r,dict):
        return {'id':'RG282-'+_n282_uuid.uuid4().hex[:8].upper(),'version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r


_N282_EVAL_PREV=_n28_eval
def _n28_eval():
    rows=_N282_EVAL_PREV()
    for x in rows:
        if x.get('name')=='v281-context-hygiene':x['detail']='preserved under 28.2'
    rows.extend([
      {'name':'v282-responsive-router','ok':_n282_direct_chat('Explain how a CBG plant works'),'detail':'ordinary info bypasses network intent classifier'},
      {'name':'v282-action-preserved','ok':not _n282_direct_chat('open Chrome'),'detail':'actions stay on mature router'},
      {'name':'v282-watchdog','ok':callable(_n282_watchdog),'detail':'typing + liveness notices'},
      {'name':'v282-fast-intent','ok':_nl_call is _n282_nl_call,'detail':'classifier hard-bounded'}])
    return rows


