# =============================================================================
# NEMO 28.3 — COMPLETION SYNC + AUTO VISUAL CORTEX
# Fixes the watchdog/final-answer race: a liveness notice can never be emitted
# after the final answer begins delivery. Adds owner-controlled SMART auto-visuals
# for process/flow/architecture explanations, using the existing Visual Cortex.
# No expansion of trading/payment/security/shell authority.
# =============================================================================
VERSION='28.3'

_N283_REQ_TLS=_n28_threading.local()
_N283_WATCH_LOCK=_n28_threading.RLock()
_N283_VIS_LOCK=_n28_threading.RLock()
_N283_VIS_LAST={}


def _n283_visual_key(cid):
    return 'n283_auto_visual_'+str(cid)


def _n283_visual_mode(cid):
    try:
        v=str(kv_get(_n283_visual_key(cid)) or 'smart').strip().lower()
    except Exception:
        v='smart'
    return v if v in ('off','smart','on') else 'smart'


def _n283_set_visual_mode(cid,mode):
    m=str(mode or '').strip().lower()
    if m not in ('off','smart','on'):return False
    try:kv_set(_n283_visual_key(cid),m)
    except Exception:return False
    return True


def _n283_should_visualize(cid,question,answer_text):
    mode=_n283_visual_mode(cid)
    if mode=='off':return False
    q=' '.join(str(question or '').split()).strip(); a=str(answer_text or '')
    if len(a)<260:return False
    ql=q.lower()
    if not q or ql.startswith(('/visual','visualize ','make a diagram ','draw a diagram ')):return False
    if any(x in ql for x in ('latest news','today news','current price','stock price','live price','weather now')):return False
    if str(a).startswith(('⚠️','❌','🧠 My brains are all busy')):return False
    if mode=='on':return True
    # SMART mode: visualize when a process, architecture, sequence or system is being explained.
    return bool(_n28_re.search(
      r'(?i)\b(how .{0,55} works?|how does|process|process flow|workflow|flowchart|flow chart|pipeline|architecture|'
      r'system design|life ?cycle|cycle|mechanism|stages?|step[- ]?by[- ]?step|plant works?|setup process|'
      r'manufacturing process|production process|from .{0,30} to .{0,30})\b',q))


def _n283_auto_visual(cid,question,answer_text):
    # Cool down automatic visuals so short follow-ups do not generate duplicate diagrams.
    now=_n28_time.time()
    with _N283_VIS_LOCK:
        last=float(_N283_VIS_LAST.get(str(cid),0) or 0)
        if now-last<75:return
        _N283_VIS_LAST[str(cid)]=now
    try:send_text(cid,'🖼 Visual Cortex: turning that explanation into a diagram...')
    except Exception:pass
    req=(
      'Create a clear, truthful process/flow diagram that helps the owner understand the answer below. '
      'Use only concepts supported by the request and answer; do not invent numbers, equipment, dates, sources or claims. '
      'Keep labels short and readable.\n\nREQUEST:\n'+str(question)[:1800]+'\n\nANSWER:\n'+str(answer_text)[:5200])
    try:
        res=n28_visualize(cid,req)
        _n28_send_visual(cid,res)
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail(cid,'nemo283_auto_visual',question,str(e))
        except Exception:pass


def _n283_maybe_auto_visual(cid,question,answer_text):
    if not _n283_should_visualize(cid,question,answer_text):return False
    _n28_threading.Thread(target=_n283_auto_visual,args=(cid,question,answer_text),daemon=True,name='nemo-autovis283').start()
    return True


# Completion-aware final delivery. The done event is set BEFORE the final Telegram
# answer is sent, under the same synchronization lock used by the watchdog.
_N283_DELIVER_PREV=deliver

def deliver(chat_id,mid,text,buttons=False):
    ctx=getattr(_N283_REQ_TLS,'ctx',None)
    q=''
    if isinstance(ctx,dict) and str(ctx.get('cid'))==str(chat_id):
        q=str(ctx.get('text') or '')
        done=ctx.get('done');token=ctx.get('token')
        with _N283_WATCH_LOCK:
            try:
                if done is not None:done.set()
            except Exception:pass
            try:_n282_clear(chat_id,token)
            except Exception:pass
    out=_N283_DELIVER_PREV(chat_id,mid,text,buttons=buttons)
    if q:
        try:_n283_maybe_auto_visual(chat_id,q,text)
        except Exception:pass
    return out


# Race-free watchdog. Any due liveness notice re-checks completion while holding
# the same lock used by final delivery. Result: status may appear BEFORE the final
# answer when genuinely slow, but never AFTER it.
def _n282_watchdog(cid,token,done):
    t0=_n28_time.time();notified25=False;notified55=False
    while not done.wait(4.0):
        with _N283_WATCH_LOCK:
            if done.is_set() or not _n282_is_active(cid,token):return
        try:tg('sendChatAction',chat_id=cid,action='typing')
        except Exception:pass
        age=_n28_time.time()-t0
        if age>=25 and not notified25:
            with _N283_WATCH_LOCK:
                if done.is_set() or not _n282_is_active(cid,token):return
                notified25=True
                try:send_text(cid,'⏳ Still working — the brain/provider is slower than normal. I am keeping the request alive and fallback routing remains active.')
                except Exception:pass
        if age>=55 and not notified55:
            with _N283_WATCH_LOCK:
                if done.is_set() or not _n282_is_active(cid,token):return
                notified55=True
                try:send_text(cid,'🔄 Still working — this is taking too long. Nemo is still responsive; you can send /debug or /brain while this request finishes.')
                except Exception:pass


def _n282_run_chat(cid,text,current=False):
    token='RQ283-'+_n282_uuid.uuid4().hex[:10].upper();done=_n28_threading.Event();_n282_mark(cid,token,text)
    ctx={'cid':cid,'token':token,'done':done,'text':text,'started':_n28_time.time()}
    _N283_REQ_TLS.ctx=ctx
    _n28_threading.Thread(target=_n282_watchdog,args=(cid,token,done),daemon=True,name='nemo-watchdog283').start()
    try:
        if current:web_answer(cid,text)
        else:answer(cid,text)
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail(cid,'nemo283_chat',text,str(e))
        except Exception:pass
        with _N283_WATCH_LOCK:
            done.set();_n282_clear(cid,token)
        try:send_text(cid,'⚠️ That request failed instead of hanging silently: '+type(e).__name__+'. Send /debug for the provider trace.')
        except Exception:pass
    finally:
        with _N283_WATCH_LOCK:
            done.set();_n282_clear(cid,token)
        try:_N283_REQ_TLS.ctx=None
        except Exception:pass


_N283_PREV_HANDLE=handle

def _n283_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo283','/visualstatus','/autovisual'):
        send_text(cid,
          'NEMO 28.3 — COMPLETION SYNC + AUTO VISUAL\n'
          'Final-answer/watchdog race: FIXED\n'
          'Auto Visual mode: '+_n283_visual_mode(cid).upper()+'\n'
          'SMART = diagrams only for useful process/flow/system explanations\n'
          '/visualauto smart | on | off\n'
          '/visual28 <request> still works manually\n'
          'Trading/payment/shell authority: UNCHANGED')
        return True
    if low.startswith('/visualauto'):
        arg=low[len('/visualauto'):].strip()
        if not arg:
            send_text(cid,'Auto Visual is '+_n283_visual_mode(cid).upper()+'. Use /visualauto smart | on | off')
            return True
        if arg in ('smart','on','off') and _n283_set_visual_mode(cid,arg):
            send_text(cid,'🖼 Auto Visual set to '+arg.upper()+'.')
        else:send_text(cid,'Use /visualauto smart | on | off')
        return True
    return False


def handle(msg):
    try:
        if _n283_dispatch(msg):return
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo283_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N283_PREV_HANDLE(msg)


_N283_REGRESSION_PREV=prime_regression_suite

def prime_regression_suite():
    r=_N283_REGRESSION_PREV();extra=[]
    if isinstance(r,dict):
        r['tests']=[x for x in r.get('tests',[]) if x.get('name')!='v282-version']
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v283-version',lambda:VERSION=='28.3')
    add('v283-completion-sync',lambda:callable(_n282_watchdog) and callable(_n282_run_chat) and callable(deliver))
    add('v283-auto-visual-smart',lambda:_n283_should_visualize(0,'Explain how a CBG plant works','x'*400))
    add('v283-auto-visual-no-news',lambda:not _n283_should_visualize(0,'latest news today','x'*400))
