# =============================================================================
# NEMO 28.3.1 — SILENT WATCHDOG HOTFIX
# Keeps the responsive-router watchdog and Telegram typing heartbeat, but disables
# noisy standalone 25s/55s "Still working" messages by default. Owner can opt in
# to diagnostic delay notices with /watchdogmsg on. No authority expansion.
# =============================================================================
VERSION='28.3.1'


def _n2831_watch_key(cid):
    return 'n2831_watchdog_messages_'+str(cid)


def _n2831_watch_messages(cid):
    try:
        return str(kv_get(_n2831_watch_key(cid)) or 'off').strip().lower()=='on'
    except Exception:
        return False


def _n2831_set_watch_messages(cid,on):
    try:
        kv_set(_n2831_watch_key(cid),'on' if on else 'off')
        return True
    except Exception:
        return False


# Quiet-by-default watchdog. Telegram typing remains visible, while the existing
# answer() progress message continues to show Understanding/Thinking/Analysing.
# Diagnostic delay messages are optional instead of being injected into normal chat.
def _n282_watchdog(cid,token,done):
    t0=_n28_time.time();notified35=False;notified75=False
    while not done.wait(4.0):
        with _N283_WATCH_LOCK:
            if done.is_set() or not _n282_is_active(cid,token):return
        try:tg('sendChatAction',chat_id=cid,action='typing')
        except Exception:pass
        if not _n2831_watch_messages(cid):
            continue
        age=_n28_time.time()-t0
        if age>=35 and not notified35:
            with _N283_WATCH_LOCK:
                if done.is_set() or not _n282_is_active(cid,token):return
                notified35=True
                try:send_text(cid,'⏳ Diagnostic: this request has been running for about 35 seconds; fallback routing remains active.')
                except Exception:pass
        if age>=75 and not notified75:
            with _N283_WATCH_LOCK:
                if done.is_set() or not _n282_is_active(cid,token):return
                notified75=True
                try:send_text(cid,'🔄 Diagnostic: this request has exceeded about 75 seconds. Use /debug or /brain if you want the provider trace.')
                except Exception:pass


_N2831_PREV_HANDLE=handle

def _n2831_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo2831','/silentwatchdog','/watchdogstatus'):
        send_text(cid,
          'NEMO 28.3.1 — SILENT WATCHDOG HOTFIX\n'
          'Typing heartbeat: ACTIVE\n'
          'Standalone “Still working” messages: '+('ON (diagnostic)' if _n2831_watch_messages(cid) else 'OFF')+'\n'
          'Existing Understanding/Thinking/Analysing progress: PRESERVED\n'
          'Completion sync: ACTIVE\n'
          'Auto Visual: '+_n283_visual_mode(cid).upper()+'\n'
          '/watchdogmsg on | off\n'
          'Authority expansion: NONE')
        return True
    if low.startswith('/watchdogmsg'):
        arg=low[len('/watchdogmsg'):].strip()
        if arg not in ('on','off'):
            send_text(cid,'Watchdog diagnostic messages are '+('ON' if _n2831_watch_messages(cid) else 'OFF')+'. Use /watchdogmsg on | off')
            return True
        ok=_n2831_set_watch_messages(cid,arg=='on')
        send_text(cid,('✅ ' if ok else '⚠️ ')+('Watchdog diagnostic messages '+arg.upper()+'.' if ok else 'Could not save watchdog preference.'))
        return True
    return False


def handle(msg):
    try:
        if _n2831_dispatch(msg):return
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo2831_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N2831_PREV_HANDLE(msg)


_N2831_REGRESSION_PREV=prime_regression_suite

def prime_regression_suite():
    r=_N2831_REGRESSION_PREV();extra=[]
    if isinstance(r,dict):
        r['tests']=[x for x in r.get('tests',[]) if x.get('name')!='v283-version']
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v2831-version',lambda:VERSION=='28.3.1')
    add('v2831-watchdog-default-silent',lambda:not _n2831_watch_messages('__eval_silent__'))
    add('v2831-watchdog-callable',lambda:callable(_n282_watchdog))
    add('v2831-completion-sync-preserved',lambda:callable(deliver) and callable(_n282_run_chat))
    add('v2831-autovisual-preserved',lambda:callable(_n283_maybe_auto_visual) and callable(n28_visualize))
    if not isinstance(r,dict):
        return {'id':'RG2831-'+_n28_uuid.uuid4().hex[:8].upper(),'version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r


