# =============================================================================
# NEMO 28.3.2 — CONVERSATIONAL VISUAL BRIDGE
# Connects Nemo's own visual/diagram offers to natural follow-ups such as
# "yes diagram", "show me", "do it", "visualize it", and a Diagram button.
# Uses the existing Visual Cortex renderer; no new execution authority.
# =============================================================================
VERSION='28.3.2'

_N2832_VISUAL_WORDS=_n28_re.compile(
    r'(?i)\b(diagram|flow ?chart|visual|visuali[sz]e|mind ?map|process ?flow|architecture ?diagram)\b')
_N2832_OFFER_RE=_n28_re.compile(
    r"(?i)(?:if you(?:'|’)?d like|if you want|would you like|want me to|i can|shall i|should i|let me)"
    r".{0,90}\b(?:diagram|flow ?chart|visual|visuali[sz]ation|mind ?map|process ?flow)\b|"
    r"\b(?:diagram|flow ?chart|visual)\b.{0,45}(?:if you want|if you(?:'|’)?d like|available|can make|can create)")


def _n2832_visual_context(cid):
    """Return the previous substantive question/answer before a visual follow-up."""
    q=str(LASTQ.get(cid,'') or '').strip()
    a=str(LASTREPLY.get(cid,'') or '').strip()
    return q,a


def _n2832_previous_offered_visual(cid):
    q,a=_n2832_visual_context(cid)
    if not a:return False
    return bool(_N2832_OFFER_RE.search(a))


def _n2832_is_visual_followup(cid,text):
    """Resolve terse affirmative replies only when the previous answer offered a visual."""
    t=' '.join(str(text or '').split()).strip().lower()
    if not t or len(t)>90:return False
    # Explicit requests do not need an offer in the previous answer.
    if _n28_re.fullmatch(
        r'(?i)(?:yes[, ]*)?(?:please[, ]*)?(?:diagram|flow ?chart|visual|visuali[sz]ation|mind ?map)(?: please)?|'
        r'(?:yes[, ]*)?(?:make|show|give|create|draw) (?:me )?(?:the |that |it )?(?:diagram|flow ?chart|visual|mind ?map)|'
        r'(?:yes[, ]*)?visuali[sz]e (?:it|that|this|the answer)|'
        r'(?:show|make|draw) (?:it|that|this) (?:visually|as a diagram|as a flow ?chart)',t):
        return True
    # Ultra-short affirmations are ambiguous; accept only after Nemo explicitly offered a visual.
    if t in ('yes','yes please','yeah','yep','sure','ok','okay','okay yes','go ahead','do it','show me','make it','please do','yes do it'):
        return _n2832_previous_offered_visual(cid)
    return False


def _n2832_build_previous_visual(cid,source='followup'):
    q,a=_n2832_visual_context(cid)
    if not (q or a):
        send_text(cid,'I do not have a previous explanation to turn into a diagram yet.')
        return False
    try:send_text(cid,'🖼 Yes — building the diagram from my previous explanation...')
    except Exception:pass
    req=(
      'Create a clear, professional, truthful diagram for the previous conversation. '
      'Choose the layout that best fits the subject (process flow, system architecture, mind map or decision flow). '
      'Use only concepts supported by the previous request and answer. Keep labels short and readable. '
      'Do not invent numbers, equipment, dates, sources or claims.\n\n'
      'PREVIOUS USER REQUEST:\n'+q[:1800]+'\n\nPREVIOUS NEMO ANSWER:\n'+a[:6000])
    def _go():
        try:
            res=n28_visualize(cid,req)
            _n28_send_visual(cid,res)
        except Exception as e:
            try:
                if '_n210_log_fail' in globals():_n210_log_fail(cid,'nemo2832_visual_followup',q,str(e))
            except Exception:pass
            try:send_text(cid,'⚠️ Visual Cortex could not build that diagram: '+type(e).__name__)
            except Exception:pass
    _n28_threading.Thread(target=_go,daemon=True,name='nemo-visual-followup2832').start()
    return True


# Add a real Diagram follow-up button without removing Simpler / More detail / Example.
try:
    _rows=FOLLOWUP_KB.setdefault('inline_keyboard',[])
    if not any(isinstance(b,dict) and b.get('callback_data')=='diagram' for row in _rows for b in (row or [])):
        _rows.append([{'text':'🖼 Diagram','callback_data':'diagram'}])
except Exception:
    pass


_N2832_CALLBACK_PREV=handle_callback

def handle_callback(cq):
    try:
        cid=cq.get('message',{}).get('chat',{}).get('id')
        data=str(cq.get('data') or '')
        if data=='diagram':
            try:tg('answerCallbackQuery',callback_query_id=cq.get('id'))
            except Exception:pass
            if cid!=OWNER.get('id'):
                try:send_text(cid,'That action is owner-only.')
                except Exception:pass
                return
            _n2832_build_previous_visual(cid,'button')
            return
    except Exception:
        pass
    return _N2832_CALLBACK_PREV(cq)


_N2832_PREV_HANDLE=handle

def _n2832_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo2832','/visualbridge','/diagramstatus'):
        send_text(cid,
          'NEMO 28.3.2 — CONVERSATIONAL VISUAL BRIDGE\n'
          '“yes diagram” follow-up: ACTIVE\n'
          'Short “yes / do it / show me” after a visual offer: ACTIVE\n'
          'Diagram follow-up button: ACTIVE\n'
          'Manual /visual28: PRESERVED\n'
          'Auto Visual: '+_n283_visual_mode(cid).upper()+'\n'
          'Silent watchdog: '+('DIAGNOSTIC ON' if _n2831_watch_messages(cid) else 'ON')+'\n'
          'Authority expansion: NONE')
        return True
    if low in ('/diagram','/diagramlast','/visualize-last'):
        _n2832_build_previous_visual(cid,'command');return True
    if txt and not txt.startswith('/') and _n2832_is_visual_followup(cid,txt):
        _n2832_build_previous_visual(cid,'natural-followup');return True
    return False


def handle(msg):
    try:
        if _n2832_dispatch(msg):return
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo2832_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N2832_PREV_HANDLE(msg)


