# =============================================================================
# NEMO 29.0 — SMOOTHFLOW OMNI BATCH
# One compatibility-first production layer consolidating the recent reliability,
# conversational continuity, professional visualization, learning, and safe Hands
# improvements into a single final outer layer.
#
# PRINCIPLES:
# - preserve every historical capability and persistent database
# - never expose/modify credential values
# - no new payment/trading/arbitrary-shell authority
# - deterministic safe actions before LLM classification
# - stale asynchronous replies are suppressed instead of arriving out-of-order
# - visual follow-ups and ordinary conversational follow-ups work naturally
# - diagrams are presentation-quality and deduplicated
# =============================================================================
VERSION='29.0'

import hashlib as _n29_hashlib
import math as _n29_math
import textwrap as _n29_textwrap

_N29_LOCK=_n28_threading.RLock()
_N29_VIS_LOCK=_n28_threading.RLock()
_N29_VIS_LAST={}
_N29_OFFER={}
_N29_METRICS={}


def _n29_now():
    return _n28_time.time()


def _n29_norm_text(s):
    return ' '.join(str(s or '').split()).strip()


def _n29_sig(*parts):
    raw='\x1f'.join(_n29_norm_text(x).lower() for x in parts)
    return _n29_hashlib.sha256(raw.encode('utf-8','ignore')).hexdigest()[:24]


def _n29_metric(cid,key,value):
    try:
        with _N29_LOCK:
            d=_N29_METRICS.setdefault(str(cid),{})
            d[key]=value
    except Exception:
        pass


# -----------------------------------------------------------------------------
# 1) SMOOTHFLOW REQUEST LIFECYCLE — STALE REPLY SUPPRESSION + QUIET HEARTBEAT
# -----------------------------------------------------------------------------
# v28.3 fixed the watchdog race. v29 also suppresses an OLD worker's final answer
# if the owner has already asked a newer independent question in the same chat.
# This prevents: Q1 slow -> user asks Q2 -> Q2 answers -> late Q1 answer appears.
_N29_DELIVER_PREV=deliver

def deliver(chat_id,mid,text,buttons=False):
    ctx=getattr(_N283_REQ_TLS,'ctx',None)
    if isinstance(ctx,dict) and str(ctx.get('cid'))==str(chat_id):
        token=ctx.get('token')
        try:
            if token and not _n282_is_active(chat_id,token):
                _n29_metric(chat_id,'stale_reply_suppressed',_n29_now())
                return None
        except Exception:
            pass
    return _N29_DELIVER_PREV(chat_id,mid,text,buttons=buttons)


# Keep watchdog SILENT by default forever. The owner can still enable diagnostics.
# Never inject standalone "Still working" messages in normal mode.
def _n282_watchdog(cid,token,done):
    t0=_n29_now();notified45=False;notified90=False
    while not done.wait(4.0):
        with _N283_WATCH_LOCK:
            if done.is_set() or not _n282_is_active(cid,token):return
        try:tg('sendChatAction',chat_id=cid,action='typing')
        except Exception:pass
        if not _n2831_watch_messages(cid):
            continue
        age=_n29_now()-t0
        if age>=45 and not notified45:
            with _N283_WATCH_LOCK:
                if done.is_set() or not _n282_is_active(cid,token):return
                notified45=True
                try:send_text(cid,'⏱ Diagnostic: request age ~45s. Provider fallback is active.')
                except Exception:pass
        if age>=90 and not notified90:
            with _N283_WATCH_LOCK:
                if done.is_set() or not _n282_is_active(cid,token):return
                notified90=True
                try:send_text(cid,'🧪 Diagnostic: request age ~90s. Use /debug or /brain for provider details.')
                except Exception:pass


# -----------------------------------------------------------------------------
# 2) CONVERSATIONAL OFFER MEMORY — YES / DO IT / SHOW ME WITHOUT GUESSING
# -----------------------------------------------------------------------------
def _n29_offer_set(cid,kind,payload=None,ttl=900):
    if kind not in ('diagram','detail','example','pdf'):
        return False
    with _N29_LOCK:
        _N29_OFFER[str(cid)]={'kind':kind,'payload':payload or {},'at':_n29_now(),'ttl':int(ttl)}
    return True


def _n29_offer_get(cid):
    with _N29_LOCK:
        o=dict(_N29_OFFER.get(str(cid)) or {})
    if not o:return None
    if _n29_now()-float(o.get('at') or 0)>float(o.get('ttl') or 0):
        with _N29_LOCK:_N29_OFFER.pop(str(cid),None)
        return None
    return o


def _n29_offer_clear(cid):
    with _N29_LOCK:_N29_OFFER.pop(str(cid),None)


def _n29_detect_offer(answer_text):
    a=_n29_norm_text(answer_text).lower()
    kinds=[]
    if re.search(r'\b(?:if you(?:\'|’)?d like|if you want|i can|want me to|shall i|let me)\b.{0,120}\b(?:diagram|flow ?chart|visual|mind ?map)\b',a):kinds.append('diagram')
    if re.search(r'\b(?:if you(?:\'|’)?d like|if you want|i can|want me to)\b.{0,120}\b(?:more detail|deeper|detail|expand)\b',a):kinds.append('detail')
    if re.search(r'\b(?:if you(?:\'|’)?d like|if you want|i can|want me to)\b.{0,120}\b(?:example|worked example)\b',a):kinds.append('example')
    if re.search(r'\b(?:if you(?:\'|’)?d like|if you want|i can|want me to)\b.{0,120}\b(?:pdf|document)\b',a):kinds.append('pdf')
    return kinds


# Track ONE unambiguous offer from the final answer. Multiple offers are not bound
# to bare "yes"; the user can still say "yes diagram" / "give example" explicitly.
_N29_TRACK_DELIVER_PREV=deliver

def deliver(chat_id,mid,text,buttons=False):
    out=_N29_TRACK_DELIVER_PREV(chat_id,mid,text,buttons=buttons)
    if out is None:
        return out
    try:
        kinds=_n29_detect_offer(text)
        if len(kinds)==1:
            _n29_offer_set(chat_id,kinds[0],{'question':str(LASTQ.get(chat_id,'') or ''),'answer':str(text or '')})
        elif len(kinds)>1:
            _n29_offer_clear(chat_id)
    except Exception:pass
    return out


def _n29_is_affirmative(text):
    t=_n29_norm_text(text).lower().strip(' .!?')
    return t in {'yes','yes please','yeah','yep','sure','ok','okay','go ahead','do it','please do','show me','make it','haan','ha','hanji','kar do','kardo'}


def _n29_followup_kind(text):
    t=_n29_norm_text(text).lower()
    if re.search(r'\b(diagram|flow ?chart|visuali[sz]e|visual|mind ?map)\b',t):return 'diagram'
    if re.search(r'\b(more detail|more detailed|deeper|expand|detail me|explain more)\b',t):return 'detail'
    if re.search(r'\b(example|worked example|give me an example)\b',t):return 'example'
    if re.search(r'\b(pdf|make .*pdf|give .*pdf|save .*pdf)\b',t):return 'pdf'
    return ''


def _n29_pdf_last(cid):
    ans=str(LASTREPLY.get(cid,'') or '').strip()
    if not ans:
        send_text(cid,'I do not have a previous answer to turn into a PDF yet.');return True
    try:
        p=_notes_pdf_file('Nemo — previous answer','',ans)
        if p:
            LASTFILE[cid]=p
            _send_file(cid,p,'📄 Your PDF')
        else:send_text(cid,'⚠️ I could not render the previous answer as a PDF.')
    except Exception as e:
        send_text(cid,'⚠️ PDF creation failed: '+type(e).__name__)
    return True


# -----------------------------------------------------------------------------
# 3) VISUAL CORTEX PRO — PROFESSIONAL MULTI-LAYOUT RENDERER
# -----------------------------------------------------------------------------
def _n29_visual_kind(request_text,spec=None):
    if isinstance(spec,dict):
        k=str(spec.get('kind') or spec.get('type') or '').lower().strip()
        if k in ('process','architecture','mindmap','decision','timeline','comparison'):return k
    t=_n29_norm_text(request_text).lower()
    if re.search(r'\b(mind ?map|brainstorm|concept map)\b',t):return 'mindmap'
    if re.search(r'\b(decision|if .* then|decision tree|choose between)\b',t):return 'decision'
    if re.search(r'\b(timeline|chronology|history of|roadmap by year|sequence over time)\b',t):return 'timeline'
    if re.search(r'\b(architecture|system design|components|stack|layers?)\b',t):return 'architecture'
    if re.search(r'\b(compare|comparison|versus| vs |pros and cons)\b',t):return 'comparison'
    return 'process'


def _n29_wrap(s,width=18):
    s=' '.join(str(s or '').split())
    return '\n'.join(_n29_textwrap.wrap(s,width=max(10,int(width)),break_long_words=False,break_on_hyphens=False)) or ' '


def _n29_clean_edge_label(s):
    x=' '.join(str(s or '').split())[:42]
    if x.lower() in {'feeds','goes to','then','next','produces','enters','flows to','leads to'}:return ''
    return x


def _n29_prepare_spec(spec,request_text=''):
    spec=spec if isinstance(spec,dict) else {}
    raw_nodes=spec.get('nodes') if isinstance(spec.get('nodes'),list) else []
    raw_edges=spec.get('edges') if isinstance(spec.get('edges'),list) else []
    title=' '.join(str(spec.get('title') or 'Nemo Visual').split())[:120]
    kind=_n29_visual_kind(request_text,spec)
    nodes=[]
    for i,n in enumerate(raw_nodes[:18]):
        if not isinstance(n,dict):continue
        nid=str(n.get('id') or ('N'+str(i+1)))[:40]
        label=' '.join(str(n.get('label') or nid).split())[:120]
        ntype=str(n.get('type') or n.get('role') or ('source' if i==0 else 'output' if i==len(raw_nodes)-1 else 'process')).lower()[:30]
        group=' '.join(str(n.get('group') or n.get('layer') or '').split())[:50]
        nodes.append({'id':nid,'label':label,'type':ntype,'group':group})
    if len(nodes)<2:
        return {'ok':False,'error':'not enough diagram nodes'}
    ids={n['id'] for n in nodes};edges=[]
    for e in raw_edges[:36]:
        if not isinstance(e,dict):continue
        a=str(e.get('from') or '');b=str(e.get('to') or '')
        if a in ids and b in ids and a!=b:
            edges.append({'from':a,'to':b,'label':_n29_clean_edge_label(e.get('label'))})
    if not edges and kind in ('process','timeline'):
        edges=[{'from':nodes[i]['id'],'to':nodes[i+1]['id'],'label':''} for i in range(len(nodes)-1)]
    return {'ok':True,'title':title,'kind':kind,'nodes':nodes,'edges':edges,'notes':spec.get('notes') or []}


def _n29_topological_levels(nodes,edges):
    ids=[n['id'] for n in nodes];ind={x:0 for x in ids};adj={x:[] for x in ids}
    for e in edges:
        if e['from'] in ind and e['to'] in ind:
            ind[e['to']]+=1;adj[e['from']].append(e['to'])
    q=[x for x in ids if ind[x]==0];levels={x:0 for x in ids};seen=[]
    while q:
        a=q.pop(0);seen.append(a)
        for b in adj[a]:
            levels[b]=max(levels[b],levels[a]+1);ind[b]-=1
            if ind[b]==0:q.append(b)
    if len(seen)<len(ids):
        for i,x in enumerate(ids):levels[x]=i//4
    return levels


def _n29_positions(kind,nodes,edges):
    pos={};n=len(nodes)
    if kind in ('process','timeline'):
        # A branched process (digestate side-streams, by-products, recycle loops)
        # gets a left-to-right level layout rather than being forced into one chain.
        indeg={x['id']:0 for x in nodes};outdeg={x['id']:0 for x in nodes}
        for e in edges:
            if e['from'] in outdeg and e['to'] in indeg:
                outdeg[e['from']]+=1;indeg[e['to']]+=1
        branched=kind=='process' and any(v>1 for v in list(indeg.values())+list(outdeg.values()))
        if branched:
            levels=_n29_topological_levels(nodes,edges);groups={}
            for node in nodes:groups.setdefault(levels[node['id']],[]).append(node)
            maxlv=max(groups) if groups else 0
            for lv,arr in groups.items():
                x=.08+.84*lv/max(1,maxlv)
                for i,node in enumerate(arr):
                    y=.5 if len(arr)==1 else .78-(.56*i/max(1,len(arr)-1))
                    pos[node['id']]=(x,y)
        elif n<=8:
            xs=[.08+i*(.84/max(1,n-1)) for i in range(n)]
            for i,node in enumerate(nodes):pos[node['id']]=(xs[i],.52)
        else:
            cols=min(6,(n+1)//2);top=nodes[:cols];bottom=nodes[cols:]
            for i,node in enumerate(top):pos[node['id']]=(.08+i*(.84/max(1,len(top)-1)),.68)
            for j,node in enumerate(bottom):pos[node['id']]=(.92-j*(.84/max(1,len(bottom)-1)),.34)
    elif kind=='mindmap':
        pos[nodes[0]['id']]=(.5,.5)
        rem=nodes[1:];r=.34
        for i,node in enumerate(rem):
            ang=2*_n29_math.pi*i/max(1,len(rem))- _n29_math.pi/2
            pos[node['id']]=(.5+r*_n29_math.cos(ang),.5+r*_n29_math.sin(ang))
    else:
        levels=_n29_topological_levels(nodes,edges);groups={}
        for node in nodes:groups.setdefault(levels[node['id']],[]).append(node)
        maxlv=max(groups) if groups else 0
        for lv,arr in groups.items():
            y=.82-(.64*lv/max(1,maxlv))
            for i,node in enumerate(arr):pos[node['id']]=((i+1)/(len(arr)+1),y)
    return pos


def _n29_node_style(ntype,idx):
    n=str(ntype or '').lower()
    if any(x in n for x in ('source','input','feed')):return ('#E8F5E9','#2E7D32')
    if any(x in n for x in ('output','product','dispens')):return ('#E3F2FD','#1565C0')
    if any(x in n for x in ('storage','tank','store')):return ('#FFF3E0','#EF6C00')
    if any(x in n for x in ('decision','choice')):return ('#FCE4EC','#AD1457')
    if any(x in n for x in ('clean','filter','scrub','treat','upgrade')):return ('#E0F7FA','#00838F')
    palette=[('#F3E5F5','#6A1B9A'),('#E8EAF6','#283593'),('#FFFDE7','#9E7B00'),('#E0F2F1','#00695C')]
    return palette[idx%len(palette)]


def _n29_render_diagram(cid,spec,request_text=''):
    p=_n29_prepare_spec(spec,request_text)
    if not p.get('ok'):return p
    nodes,edges,title,kind=p['nodes'],p['edges'],p['title'],p['kind']
    try:
        if not _imp('matplotlib',notify=False):auto_install('matplotlib',notify=False)
        import matplotlib
        matplotlib.use('Agg')
        import matplotlib.pyplot as plt
        from matplotlib.patches import FancyBboxPatch,FancyArrowPatch,Circle
        pos=_n29_positions(kind,nodes,edges)
        landscape=kind in ('process','timeline','architecture','comparison')
        figw=15 if landscape else 11
        figh=8.5 if landscape else 10
        fig,ax=plt.subplots(figsize=(figw,figh))
        fig.patch.set_facecolor('#F7F9FC');ax.set_facecolor('#F7F9FC')
        ax.set_xlim(0,1);ax.set_ylim(0,1);ax.axis('off')
        ax.text(.5,.955,title,ha='center',va='center',fontsize=21,fontweight='bold',color='#17212B')
        ax.text(.5,.915,{'process':'PROCESS FLOW','architecture':'SYSTEM ARCHITECTURE','mindmap':'MIND MAP','decision':'DECISION FLOW','timeline':'TIMELINE','comparison':'COMPARISON'}.get(kind,'VISUAL'),ha='center',va='center',fontsize=9,color='#667085')
        # edges first so boxes stay clean above them
        for e in edges:
            if e['from'] not in pos or e['to'] not in pos:continue
            x1,y1=pos[e['from']];x2,y2=pos[e['to']]
            dx=x2-x1;dy=y2-y1;dist=max(.001,(dx*dx+dy*dy)**.5)
            sx=x1+dx/dist*.076;sy=y1+dy/dist*.055;tx=x2-dx/dist*.076;ty=y2-dy/dist*.055
            rad=.0
            if kind not in ('process','timeline') and abs(dy)<.05:rad=.12
            ar=FancyArrowPatch((sx,sy),(tx,ty),arrowstyle='-|>',mutation_scale=15,linewidth=1.55,color='#667085',connectionstyle='arc3,rad='+str(rad),zorder=1)
            ax.add_patch(ar)
            if e.get('label'):
                mx=(sx+tx)/2;my=(sy+ty)/2+.018
                ax.text(mx,my,_n29_wrap(e['label'],18),ha='center',va='center',fontsize=8,color='#475467',bbox=dict(boxstyle='round,pad=.18',facecolor='#F7F9FC',edgecolor='none'),zorder=2)
        for i,node in enumerate(nodes):
            x,y=pos[node['id']];face,edge=_n29_node_style(node.get('type'),i)
            w=.13 if landscape else .18;h=.12 if landscape else .095
            if kind=='mindmap' and i==0:w=.21;h=.12
            box=FancyBboxPatch((x-w/2,y-h/2),w,h,boxstyle='round,pad=0.012,rounding_size=0.018',linewidth=1.8,edgecolor=edge,facecolor=face,zorder=3)
            ax.add_patch(box)
            if kind=='process':
                ax.text(x-w/2+.014,y+h/2-.018,str(i+1),ha='left',va='top',fontsize=8,fontweight='bold',color=edge,zorder=4)
            ax.text(x,y,_n29_wrap(node['label'],18 if landscape else 22),ha='center',va='center',fontsize=10.2,fontweight='semibold',color='#1D2939',zorder=4)
        ax.text(.015,.025,'NEMO Visual Cortex Pro • generated '+_n28_time.strftime('%d %b %Y'),fontsize=7.5,color='#98A2B3')
        _n28_os.makedirs('/root/nemo_visuals',exist_ok=True)
        path='/root/nemo_visuals/visual29_'+_n28_uuid.uuid4().hex[:10]+'.png'
        plt.tight_layout(rect=[0,.04,1,.92]);plt.savefig(path,dpi=170,bbox_inches='tight',facecolor=fig.get_facecolor());plt.close(fig)
        if not _n28_os.path.exists(path) or _n28_os.path.getsize(path)<2500:return {'ok':False,'error':'rendered image was empty'}
    except Exception as e:
        return {'ok':False,'error':'renderer '+type(e).__name__+': '+str(e)[:180]}
    vid='V29-'+_n28_uuid.uuid4().hex[:10].upper()
    try:
        c=_n28_conn();c.execute('INSERT INTO visual_history VALUES(?,?,?,?,?,?)',(vid,str(cid),title,_n28_redact(request_text)[:3000],path,_n29_now()));c.commit();c.close()
    except Exception:pass
    return {'ok':True,'id':vid,'title':title,'path':path,'kind':kind}


def _n29_fallback_visual_spec(req):
    s=str(req or '')
    # Prefer explicit arrows first.
    bits=[_n29_norm_text(x) for x in re.split(r'\s*(?:→|->|=>|\|)\s*',s) if _n29_norm_text(x)]
    if len(bits)<3:
        # Extract concise section/bullet-like phrases from embedded answer text.
        cand=[]
        for line in s.splitlines():
            line=_n29_norm_text(re.sub(r'^[-*•\d.)\s]+','',line))
            if 3<=len(line)<=80 and not line.upper().startswith(('REQUEST','ANSWER','PREVIOUS','CREATE A CLEAR')):
                cand.append(line)
        # de-duplicate preserving order
        seen=set();bits=[]
        for x in cand:
            k=x.lower()
            if k not in seen:seen.add(k);bits.append(x)
            if len(bits)>=9:break
    if len(bits)<2:
        bits=['Input / starting point','Core process','Result / output']
    bits=bits[:12]
    nodes=[{'id':'N'+str(i+1),'label':x[:100],'type':'source' if i==0 else 'output' if i==len(bits)-1 else 'process'} for i,x in enumerate(bits)]
    edges=[{'from':'N'+str(i+1),'to':'N'+str(i+2),'label':''} for i in range(len(bits)-1)]
    return {'title':'Nemo Visual','kind':_n29_visual_kind(req),'nodes':nodes,'edges':edges}


def n28_visualize(cid,request_text):
    req=str(request_text or '').strip()
    if not req:return {'ok':False,'error':'Tell me what to visualize.'}
    kind=_n29_visual_kind(req)
    prompt=(
      'NEMO VISUAL CORTEX PRO. Design a presentation-quality diagram. Return JSON ONLY with schema: '
      '{"title":"...","kind":"process|architecture|mindmap|decision|timeline|comparison",'
      '"nodes":[{"id":"A","label":"short label","type":"source|process|cleaning|storage|output|decision","group":"optional"}],'
      '"edges":[{"from":"A","to":"B","label":"only when meaningful"}]}. '
      'Use 3-14 nodes. Prefer landscape process flow for sequential systems. Include real branches only when supported by the request/context. '
      'Do NOT invent numeric facts, equipment, dates, sources, or claims. Keep labels concise. REQUEST:\n'+req[:7000])
    raw=None
    try:raw=_N28_ASK_PREV(cid,prompt,remember=False,timeout=90,deep=True,raw=True)
    except Exception:raw=None
    spec=_n28_json_obj(raw)
    if not isinstance(spec,dict) or len(spec.get('nodes') or [])<2:
        spec=_n29_fallback_visual_spec(req)
    if not spec.get('kind'):spec['kind']=kind
    return _n29_render_diagram(cid,spec,req)


# Dedupe automatic visuals by question+answer signature. Explicit "different/new"
# requests still build a fresh diagram.
def _n29_visual_recent(cid,sig,window=900):
    with _N29_VIS_LOCK:
        r=dict(_N29_VIS_LAST.get(str(cid)) or {})
    return bool(r and r.get('sig')==sig and _n29_now()-float(r.get('at') or 0)<window and _n28_os.path.exists(str(r.get('path') or '')))


def _n29_record_visual(cid,sig,res):
    if not res.get('ok'):return
    with _N29_VIS_LOCK:
        _N29_VIS_LAST[str(cid)]={'sig':sig,'at':_n29_now(),'path':res.get('path'),'title':res.get('title'),'kind':res.get('kind')}
    try:LASTFILE[cid]=res.get('path')
    except Exception:pass


def _n283_auto_visual(cid,question,answer_text):
    sig=_n29_sig(question,answer_text)
    if _n29_visual_recent(cid,sig):return
    try:send_text(cid,'🖼 Visual Cortex Pro: building a useful visual...')
    except Exception:pass
    req=('Build a professional diagram for this explanation. Choose the best visual type automatically. '
         'Do not invent facts.\n\nREQUEST:\n'+str(question)[:1800]+'\n\nANSWER:\n'+str(answer_text)[:6200])
    try:
        res=n28_visualize(cid,req);_n29_record_visual(cid,sig,res);_n28_send_visual(cid,res)
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail(cid,'nemo29_auto_visual',question,str(e))
        except Exception:pass


def _n2832_build_previous_visual(cid,source='followup'):
    q=str(LASTQ.get(cid,'') or '').strip();a=str(LASTREPLY.get(cid,'') or '').strip()
    if not (q or a):
        send_text(cid,'I do not have a previous explanation to turn into a diagram yet.');return False
    sig=_n29_sig(q,a)
    if _n29_visual_recent(cid,sig) and source!='force-new':
        with _N29_VIS_LOCK:r=dict(_N29_VIS_LAST.get(str(cid)) or {})
        try:
            _send_file(cid,r.get('path'),'🖼 Here is the diagram from that explanation.')
            return True
        except Exception:pass
    try:send_text(cid,'🖼 Building a professional diagram from my previous explanation...')
    except Exception:pass
    req=('Create a professional diagram for the previous conversation. Choose process flow, architecture, mind map, decision flow, timeline, or comparison automatically. '
         'Use only supported concepts; no invented numbers or claims.\n\nPREVIOUS USER REQUEST:\n'+q[:1800]+'\n\nPREVIOUS NEMO ANSWER:\n'+a[:6500])
    def _go():
        try:
            res=n28_visualize(cid,req);_n29_record_visual(cid,sig,res);_n28_send_visual(cid,res)
        except Exception as e:
            try:send_text(cid,'⚠️ Visual Cortex Pro failed: '+type(e).__name__)
            except Exception:pass
    _n28_threading.Thread(target=_go,daemon=True,name='nemo-visual29').start();return True


