_N29_EXTRACT_PREV=_n28_extract_fact
_N29_ALT_REL=[
 ('wife_name',r"(?i)^\s*([A-Za-z][A-Za-z .'-]{1,80})\s+is\s+my\s+wife\b"),
 ('husband_name',r"(?i)^\s*([A-Za-z][A-Za-z .'-]{1,80})\s+is\s+my\s+husband\b"),
 ('father_name',r"(?i)^\s*([A-Za-z][A-Za-z .'-]{1,80})\s+is\s+my\s+father\b"),
 ('mother_name',r"(?i)^\s*([A-Za-z][A-Za-z .'-]{1,80})\s+is\s+my\s+mother\b"),
 ('sister_name',r"(?i)^\s*([A-Za-z][A-Za-z .'-]{1,80})\s+is\s+my\s+sister\b"),
 ('brother_name',r"(?i)^\s*([A-Za-z][A-Za-z .'-]{1,80})\s+is\s+my\s+brother\b"),
 ('partner_name',r"(?i)^\s*([A-Za-z][A-Za-z .'-]{1,80})\s+is\s+my\s+partner\b"),
]

def _n28_extract_fact(cid,text,source='text-explicit'):
    r=_N29_EXTRACT_PREV(cid,text,source)
    if r:return r
    t=_n29_norm_text(text)
    correction=bool(re.search(r'(?i)^\s*(?:no[, ]+|actually[, ]+|correction[:, ]+|correct(?:ion)?[, ]+)',t))
    for key,pat in _N29_ALT_REL:
        m=re.search(pat,t)
        if m:
            val=_n28_pretty_name(m.group(1));res=_n28_set_fact(cid,key,val,'owner-correction' if correction else source,.995 if correction else .98,force=correction)
            return key,val,res
    return None


_N29_FEEDBACK_PREV=_n28_capture_feedback

def _n28_capture_feedback(cid,text):
    r=_N29_FEEDBACK_PREV(cid,text)
    if r:return r
    t=_n29_norm_text(text);low=t.lower()
    m=re.search(r'(?i)\b(?:do not|don\'t|never)\s+(.{8,650})',t)
    if m and any(k in low for k in ('next time','again','from now','when i ask','always','never')):
        return _n28_teach(cid,t,_n28_thread(t),'NEGATIVE_GUIDANCE','owner-guidance')
    m=re.search(r'(?i)\b(?:always|whenever i ask|when i ask)\s+(.{8,650})',t)
    if m:return _n28_teach(cid,t,_n28_thread(t),'GUIDANCE','owner-guidance')
    return None


