_N29_CONTROL_PREV=_v184_compile_control

def _n29_control_extra(device_id,text):
    t=_n29_norm_text(text);low=t.lower()
    # Preserve the mature site-specific compiler contract (YouTube/Google/GitHub).
    # Generic browser search must never steal a command such as 'search youtube for ...'.
    if re.match(r'(?i)^(?:nemo[,. ]*)?search\s+(?:youtube|google|github)\b',t):
        return None
    # Media referent layer remains authoritative for PLAY/deictic media semantics,
    # but search-only site commands stay with the historical site_search route.
    if re.search(r'(?i)\bplay\b',t):
        try:
            mm=_n260_media_intent(OWNER.get('id') or 0,device_id,t)
            if mm:return mm
        except Exception:pass
    # Natural search without naming a site defaults to browser search, not shell.
    m=re.match(r'(?i)^(?:nemo[,. ]*)?(?:search|google|look up)\s+(?:for\s+)?(.{2,400})$',t)
    if m and not re.search(r'(?i)\b(file|folder|computer|pc|laptop)\b',m.group(1)):
        return {'kind':'open_search','query':m.group(1).strip(),'risk':'LOW','requires_approval':False,'verify':True}
    return None


def _v184_compile_control(device_id,text):
    return _n29_control_extra(device_id,text) or _N29_CONTROL_PREV(device_id,text)


def _n29_hands_plan(cid,text):
    try:r=_v184_compile_control('preview',text)
    except Exception as e:r=None
    if not isinstance(r,dict):
        send_text(cid,'I could not compile that into a deterministic safe Hands action.');return True
    safe=dict(r)
    # Do not leak any incidental sensitive fields if a future schema adds them.
    for k in list(safe):
        if any(x in k.lower() for x in ('token','secret','password','cookie','authorization')):safe[k]='[REDACTED]'
    send_text(cid,'🖐 HANDS PLAN — preview only, nothing executed\n\n'+_n28_json.dumps(safe,ensure_ascii=False,indent=2)[:3800])
    return True


