# 6) LOCAL FOLLOW-UP ROUTER — BYPASS AI FOR OBVIOUS CONTINUATIONS
# -----------------------------------------------------------------------------
def _n29_followup_dispatch(cid,text):
    t=_n29_norm_text(text);low=t.lower()
    kind=_n29_followup_kind(t)
    if kind=='diagram':return _n2832_build_previous_visual(cid,'explicit-followup')
    if kind=='pdf':return _n29_pdf_last(cid)
    if kind=='detail':
        _n28_threading.Thread(target=answer,args=(cid,'Expand your previous answer with more depth, useful detail, and practical explanation.'),daemon=True).start();return True
    if kind=='example':
        _n28_threading.Thread(target=answer,args=(cid,'Give a concrete practical worked example for your previous answer.'),daemon=True).start();return True
    if _n29_is_affirmative(t):
        o=_n29_offer_get(cid)
        if not o:return False
        _n29_offer_clear(cid)
        if o['kind']=='diagram':return _n2832_build_previous_visual(cid,'offered-followup')
        if o['kind']=='pdf':return _n29_pdf_last(cid)
        if o['kind']=='detail':
            _n28_threading.Thread(target=answer,args=(cid,'Expand your previous answer with more depth and practical detail.'),daemon=True).start();return True
        if o['kind']=='example':
            _n28_threading.Thread(target=answer,args=(cid,'Give a concrete practical example for your previous answer.'),daemon=True).start();return True
    return False


