def _n29_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower();chat=(msg.get('chat') or {})
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo29','/smoothflow','/omni29'):
        send_text(cid,_n29_status(cid));return True
    if low in ('/voice29','/girlvoice','/voicestatus29'):
        return _n29_voice_status(cid)
    if low.startswith('/handsplan'):
        q=txt[len('/handsplan'):].strip()
        if not q:send_text(cid,'Usage: /handsplan <Windows command>');return True
        return _n29_hands_plan(cid,q)
    if low in ('/diagramnew','/visualnew'):
        return _n2832_build_previous_visual(cid,'force-new')
    if low=='/visualpro':
        send_text(cid,'Visual Cortex Pro supports process flow, architecture, mind map, decision flow, timeline and comparison. Use /visual28 <request> or just say “yes diagram” after an explanation.');return True
    if txt and not txt.startswith('/') and chat.get('type','private')=='private':
        if _n29_followup_dispatch(cid,txt):return True
    return False


def handle(msg):
    # Final owner security boundary for new v29 actions. Public normal chat remains on
    # the pre-existing gate; v29 commands/actions never bypass owner authorization.
    try:
        cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();chat=(msg.get('chat') or {})
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id'):
            low=txt.lower()
            if low.startswith(('/nemo29','/smoothflow','/omni29','/handsplan','/diagramnew','/visualnew','/visualpro','/voice29','/girlvoice','/voicestatus29')):
                try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                except Exception:pass
                return
        if _n29_dispatch(msg):return
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo29_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N29_PREV_HANDLE(msg)


