# =============================================================================
# NEMO 29.1 — PRODUCTION HARDENING / RELIABILITY CONTRACT
# Compatibility-first reliability layer over NEMO 29.0 SMOOTHFLOW OMNI.
#
# Goals:
# - one request token -> at most one substantive final delivery
# - duplicate async reply suppression without changing normal conversational output
# - stale/abandoned worker observability and bounded registry cleanup
# - provider + brain latency/failure telemetry without exposing prompts or secrets
# - on-demand SQLite contention probe (no schema migration, no DB deletion)
# - persistent low-noise health event recorder with secret-shaped value redaction
# - historical regression contract snapshot so future builds cannot silently drop tests
# - owner-only /health29 /providers29 /requests29 /baseline29 dashboard commands
#
# Explicit non-goals:
# - no new trading/payment authority
# - no arbitrary shell authority
# - no credential/config modification
# - no historical database migration/deletion
# =============================================================================
VERSION='29.1'

import json as _n291_json
import os as _n291_os
import glob as _n291_glob
import shutil as _n291_shutil
import resource as _n291_resource
import statistics as _n291_statistics

_N291_BOOT_AT=_n29_now()
_N291_LOCK=_n28_threading.RLock()
_N291_REQ={}              # token -> bounded request metadata (no full prompts)
_N291_WORKERS={}          # token -> Thread object while alive
_N291_FINAL={}            # token -> final-delivery metadata
_N291_LAST_FINAL={}       # chat -> latest signature/question signature
_N291_PROVIDER={}         # provider -> aggregate metrics + bounded samples
_N291_COUNTS={
    'final_delivered':0,
    'duplicate_final_suppressed':0,
    'stale_final_suppressed':0,
    'request_failures':0,
    'requests_started':0,
    'requests_finished':0,
}
_N291_HEALTH_LOG='/root/nemo29_health.jsonl'
_N291_BASELINE='/root/nemo29_regression_baseline.json'
_N291_MAX_RECENT=160
_N291_MAX_PROVIDER_SAMPLES=80
_N291_SECRETISH_RE=re.compile(r'(?i)(bearer\s+[a-z0-9._-]+|(?:api[_ -]?key|token|secret|password|authorization|cookie)\s*[:=]\s*[^\s,;]+)')


def _n291_safe_text(v,limit=220):
    s=' '.join(str(v or '').split())[:max(0,int(limit))]
    return _N291_SECRETISH_RE.sub('[REDACTED]',s)


def _n291_event(kind,**fields):
    """Low-noise JSONL telemetry. Never stores prompts, model outputs or secret values."""
    try:
        row={'ts':round(_n29_now(),3),'kind':str(kind)[:60],'version':VERSION}
        for k,v in fields.items():
            if any(x in str(k).lower() for x in ('token','secret','password','cookie','authorization','prompt','body','content')):
                continue
            if isinstance(v,(int,float,bool)) or v is None:row[str(k)[:50]]=v
            else:row[str(k)[:50]]=_n291_safe_text(v,240)
        p=_N291_HEALTH_LOG
        try:
            if _n291_os.path.exists(p) and _n291_os.path.getsize(p)>2_000_000:
                old=p+'.1'
                try:_n291_os.replace(p,old)
                except Exception:pass
        except Exception:pass
        with open(p,'a',encoding='utf-8') as f:
            f.write(_n291_json.dumps(row,ensure_ascii=False,separators=(',',':'))+'\n')
    except Exception:
        pass


def _n291_counter(key,inc=1):
    with _N291_LOCK:
        _N291_COUNTS[key]=int(_N291_COUNTS.get(key,0) or 0)+int(inc)


def _n291_req_start(cid,token,text,current=False):
    now=_n29_now();qsig=_n29_sig(text)
    with _N291_LOCK:
        _N291_REQ[token]={
            'chat':str(cid),'qsig':qsig,'started':now,'finished':0.0,
            'state':'RUNNING','current':bool(current),'thread':_n28_threading.current_thread().name,
            'summary':_n291_safe_text(text,120)
        }
        _N291_WORKERS[token]=_n28_threading.current_thread()
    _n291_counter('requests_started')
    _n291_sweep()


def _n291_req_finish(token,state='DONE',error=''):
    now=_n29_now();count_it=False
    with _N291_LOCK:
        r=_N291_REQ.get(token)
        if r:
            count_it=not bool(r.get('finished'))
            r['finished']=float(r.get('finished') or now);r['state']=str(state)[:30]
            if error:r['error']=_n291_safe_text(error,160)
        _N291_WORKERS.pop(token,None)
    if count_it:_n291_counter('requests_finished')


def _n291_sweep():
    """Bound registries. Python cannot safely kill provider threads; stale output is suppressed instead."""
    now=_n29_now()
    with _N291_LOCK:
        # Mark dead registry entries and drop old finished metadata.
        for tok,th in list(_N291_WORKERS.items()):
            try:alive=bool(th and th.is_alive())
            except Exception:alive=False
            if not alive:
                _N291_WORKERS.pop(tok,None)
                if tok in _N291_REQ and _N291_REQ[tok].get('state')=='RUNNING':
                    _N291_REQ[tok]['state']='ENDED';_N291_REQ[tok]['finished']=now
        old=[(float(v.get('finished') or v.get('started') or 0),k) for k,v in _N291_REQ.items() if v.get('state')!='RUNNING']
        old.sort(reverse=True)
        keep={k for _,k in old[:_N291_MAX_RECENT]}
        for _,k in old[_N291_MAX_RECENT:]:
            _N291_REQ.pop(k,None);_N291_FINAL.pop(k,None)
        # Final-token map must also remain bounded if a provider exits abnormally.
        if len(_N291_FINAL)>_N291_MAX_RECENT*2:
            for k in list(_N291_FINAL)[:-_N291_MAX_RECENT]:_N291_FINAL.pop(k,None)


def _n291_provider_record(name,ms,ok,error=''):
    name=str(name or 'unknown')[:40];ms=max(0.0,float(ms or 0))
    with _N291_LOCK:
        d=_N291_PROVIDER.setdefault(name,{'calls':0,'ok':0,'fail':0,'total_ms':0.0,'max_ms':0.0,'last_ms':0.0,'last_error':'','samples':[]})
        d['calls']+=1;d['ok']+=1 if ok else 0;d['fail']+=0 if ok else 1;d['total_ms']+=ms;d['max_ms']=max(float(d['max_ms']),ms);d['last_ms']=ms
        if error:d['last_error']=_n291_safe_text(error,130)
        ss=d['samples'];ss.append(ms)
        if len(ss)>_N291_MAX_PROVIDER_SAMPLES:del ss[:-_N291_MAX_PROVIDER_SAMPLES]
    if (not ok) or ms>=12000:
        _n291_event('provider_call',provider=name,ms=round(ms,1),ok=bool(ok),error=type(error).__name__ if isinstance(error,BaseException) else _n291_safe_text(error,80))


def _n291_call_provider(name,fn,*args,**kwargs):
    t=_n29_now();err=''
    try:
        r=fn(*args,**kwargs)
        ok=bool(r)
        if isinstance(r,str) and re.search(r'(?i)\b(?:all free models|brains are all busy|provider unavailable|rate limit)\b',r[:180]):ok=False
        _n291_provider_record(name,(_n29_now()-t)*1000.0,ok,'')
        return r
    except Exception as e:
        _n291_provider_record(name,(_n29_now()-t)*1000.0,False,e)
        raise


# Explicit provider wrappers only — never monkey-patch requests globally.
_N291_GROQ_PREV=groq_chat
def groq_chat(*args,**kwargs):return _n291_call_provider('groq',_N291_GROQ_PREV,*args,**kwargs)

_N291_GEMINI_PREV=gemini_chat
def gemini_chat(*args,**kwargs):return _n291_call_provider('gemini',_N291_GEMINI_PREV,*args,**kwargs)

_N291_CEREBRAS_PREV=cerebras_chat
def cerebras_chat(*args,**kwargs):return _n291_call_provider('cerebras',_N291_CEREBRAS_PREV,*args,**kwargs)

_N291_CLAUDE_PREV=claude_chat
def claude_chat(*args,**kwargs):return _n291_call_provider('claude',_N291_CLAUDE_PREV,*args,**kwargs)

_N291_ASK_PREV=ask_ai
def ask_ai(*args,**kwargs):return _n291_call_provider('brain_total',_N291_ASK_PREV,*args,**kwargs)


def _n291_final_permission(chat_id,text):
    """Atomic gate for async request finals. Returns (allow, reason, token)."""
    ctx=getattr(_N283_REQ_TLS,'ctx',None)
    if not isinstance(ctx,dict) or str(ctx.get('cid'))!=str(chat_id):
        return True,'non-worker',''
    token=str(ctx.get('token') or '')
    if not token:return True,'no-token',''
    qsig=_n29_sig(ctx.get('text') or '')
    asig=_n29_sig(text)
    # Share the same active-token lock used by _n282_mark/_n282_clear so a newer
    # request cannot slip between the stale check and final-delivery reservation.
    try:state_lock=_N282_STATE_LOCK
    except Exception:state_lock=_N291_LOCK
    with state_lock:
        if not _n282_is_active(chat_id,token):
            _n291_counter('stale_final_suppressed')
            with _N291_LOCK:
                if token in _N291_REQ:_N291_REQ[token]['state']='STALE_SUPPRESSED'
            return False,'stale',token
        with _N291_LOCK:
            if token in _N291_FINAL:
                _n291_counter('duplicate_final_suppressed')
                return False,'same-token-duplicate',token
            last=dict(_N291_LAST_FINAL.get(str(chat_id)) or {})
            # Suppress only an almost-immediate exact duplicate for the same question.
            # Re-asking later or asking a different question is never hidden.
            if last and last.get('qsig')==qsig and last.get('asig')==asig and _n29_now()-float(last.get('at') or 0)<6.0:
                _N291_FINAL[token]={'at':_n29_now(),'asig':asig,'suppressed':'duplicate'}
                _n291_counter('duplicate_final_suppressed')
                return False,'cross-token-duplicate',token
            # Reserve before network delivery. A newer request can start after this point,
            # but this final has already begun delivery and should be allowed to finish.
            _N291_FINAL[token]={'at':_n29_now(),'asig':asig,'qsig':qsig,'state':'SENDING'}
            _N291_LAST_FINAL[str(chat_id)]={'at':_n29_now(),'asig':asig,'qsig':qsig,'token':token}
    return True,'reserved',token


_N291_DELIVER_PREV=deliver
def deliver(chat_id,mid,text,buttons=False):
    allow,reason,token=_n291_final_permission(chat_id,text)
    if not allow:
        _n291_event('final_suppressed',reason=reason,chat=str(chat_id),age_ms=0)
        return None
    try:
        out=_N291_DELIVER_PREV(chat_id,mid,text,buttons=buttons)
        if token:
            with _N291_LOCK:
                if token in _N291_FINAL:_N291_FINAL[token]['state']='DELIVERED';_N291_FINAL[token]['delivered']=_n29_now()
                if token in _N291_REQ:_N291_REQ[token]['state']='FINAL_DELIVERED'
            _n291_counter('final_delivered')
        return out
    except Exception:
        if token:
            with _N291_LOCK:_N291_FINAL.pop(token,None)
        raise


# Replace only the normal-chat worker lifecycle. The Telegram polling thread still
# launches this asynchronously; historical action/tool workers are untouched.
def _n282_run_chat(cid,text,current=False):
    token='RQ291-'+_n282_uuid.uuid4().hex[:10].upper();done=_n28_threading.Event();_n282_mark(cid,token,text)
    ctx={'cid':cid,'token':token,'done':done,'text':text,'started':_n29_now()}
    _N283_REQ_TLS.ctx=ctx
    _n291_req_start(cid,token,text,current=current)
    _n28_threading.Thread(target=_n282_watchdog,args=(cid,token,done),daemon=True,name='nemo-watchdog291').start()
    try:
        if current:web_answer(cid,text)
        else:answer(cid,text)
    except Exception as e:
        _n291_counter('request_failures');_n291_req_finish(token,'FAILED',type(e).__name__+': '+str(e)[:120])
        _n291_event('request_failed',chat=str(cid),error=type(e).__name__,current=bool(current))
        with _N283_WATCH_LOCK:
            done.set();_n282_clear(cid,token)
        # Do not append a second error message if a final response already entered delivery.
        with _N291_LOCK:already=token in _N291_FINAL
        if not already:
            try:send_text(cid,'⚠️ That request failed instead of hanging silently: '+type(e).__name__+'. Send /debug for the provider trace.')
            except Exception:pass
    finally:
        with _N283_WATCH_LOCK:
            done.set();_n282_clear(cid,token)
        with _N291_LOCK:
            st=(_N291_REQ.get(token) or {}).get('state')
        _n291_req_finish(token,'DONE' if st not in ('FAILED','STALE_SUPPRESSED') else st or 'DONE')
        try:_N283_REQ_TLS.ctx=None
        except Exception:pass


def _n291_provider_snapshot():
    with _N291_LOCK:return {k:dict(v) for k,v in _N291_PROVIDER.items()}


def _n291_pct(vals,p=.95):
    vals=sorted(float(x) for x in vals if isinstance(x,(int,float)))
    if not vals:return 0.0
    i=min(len(vals)-1,max(0,int(round((len(vals)-1)*p))))
    return vals[i]


def _n291_provider_text():
    snap=_n291_provider_snapshot()
    if not snap:return 'PROVIDER TELEMETRY\nNo provider calls recorded since this restart.'
    lines=['PROVIDER TELEMETRY — since restart']
    for name in sorted(snap):
        d=snap[name];calls=int(d.get('calls') or 0);avg=(float(d.get('total_ms') or 0)/calls) if calls else 0
        p95=_n291_pct(d.get('samples') or [],.95)
        lines.append('%s: %s calls | ok %s | fail %s | avg %.0fms | p95 %.0fms | last %.0fms'%(name,calls,d.get('ok',0),d.get('fail',0),avg,p95,float(d.get('last_ms') or 0)))
        if d.get('last_error'):lines.append('  last error: '+_n291_safe_text(d.get('last_error'),100))
    return '\n'.join(lines)[:3900]


def _n291_sqlite_probe():
    """Short owner-invoked contention probe; never changes schema or deletes/migrates data."""
    paths=set()
    try:paths.update(_n291_glob.glob('/root/nemo*.db'))
    except Exception:pass
    for n in ('DB_PATH','DB_FILE','_N28_DB'):
        try:
            p=globals().get(n)
            if isinstance(p,str) and p.endswith('.db'):paths.add(p)
        except Exception:pass
    rows=[]
    for p in sorted(paths)[:24]:
        if not _n291_os.path.exists(p):continue
        t=_n29_now();ok=True;err=''
        c=None
        try:
            c=_n28_sqlite.connect(p,timeout=.25)
            c.execute('PRAGMA busy_timeout=180')
            c.execute('SELECT 1').fetchone()
            # A very brief write-reservation probe reveals current writer contention.
            c.execute('BEGIN IMMEDIATE');c.execute('ROLLBACK')
        except Exception as e:
            ok=False;err=type(e).__name__+': '+str(e)[:90]
            try:
                if c:c.rollback()
            except Exception:pass
        finally:
            try:
                if c:c.close()
            except Exception:pass
        rows.append({'path':p,'ok':ok,'ms':round((_n29_now()-t)*1000,1),'error':err})
    return rows


def _n291_system_snapshot():
    try:
        ru=_n291_resource.getrusage(_n291_resource.RUSAGE_SELF);rss_mb=float(ru.ru_maxrss)/1024.0
    except Exception:rss_mb=0.0
    try:
        du=_n291_shutil.disk_usage('/root');disk_free_gb=du.free/(1024**3)
    except Exception:disk_free_gb=0.0
    try:threads=len(_n28_threading.enumerate())
    except Exception:threads=0
    with _N291_LOCK:
        workers=sum(1 for t in _N291_WORKERS.values() if getattr(t,'is_alive',lambda:False)())
        active=sum(1 for r in _N291_REQ.values() if r.get('state')=='RUNNING')
        counts=dict(_N291_COUNTS)
    return {'uptime_s':int(_n29_now()-_N291_BOOT_AT),'rss_mb':round(rss_mb,1),'disk_free_gb':round(disk_free_gb,2),'threads':threads,'workers':workers,'active':active,'counts':counts}


def _n291_contract_names(tests):
    names=[]
    for x in tests or []:
        n=str((x or {}).get('name') or '').strip()
        if not n:continue
        # Version/runtime assertions are intentionally superseded by later outer layers.
        if re.search(r'(?i)(?:^|[-_])(version|runtime)(?:[-_]|$)',n):continue
        names.append(n)
    return sorted(set(names))


def _n291_baseline_read():
    try:
        d=_n291_json.load(open(_N291_BASELINE,encoding='utf-8'))
        return d if isinstance(d,dict) else {}
    except Exception:return {}


def _n291_baseline_write(names):
    try:
        names=sorted(set(str(x) for x in names if x))
        d={'version':VERSION,'created':_n29_now(),'count':len(names),'names':names,'sha256':_n29_hashlib.sha256('\n'.join(names).encode()).hexdigest()}
        tmp=_N291_BASELINE+'.tmp'
        with open(tmp,'w',encoding='utf-8') as f:_n291_json.dump(d,f,ensure_ascii=False,indent=2)
        _n291_os.replace(tmp,_N291_BASELINE)
        return d
    except Exception:return {}


def _n291_baseline_check(tests,capture_ok=False):
    names=_n291_contract_names(tests);b=_n291_baseline_read()
    if not b:
        if capture_ok:
            b=_n291_baseline_write(names)
            return bool(b),'captured %s functional test names'%len(names)
        return True,'baseline not captured yet; run a fully passing /regress once'
    expected=set(str(x) for x in b.get('names') or []);current=set(names);missing=sorted(expected-current)
    if missing:return False,'MISSING '+str(len(missing))+': '+', '.join(missing[:8])
    return True,'preserved %s/%s baseline functional tests'%(len(expected),len(expected))


def _n291_baseline_text():
    b=_n291_baseline_read()
    if not b:return 'REGRESSION CONTRACT\nNo baseline captured yet. A fully passing /regress on this VPS will capture it automatically.'
    return 'REGRESSION CONTRACT\nBaseline version: %s\nFunctional tests: %s\nSHA-256: %s\nCreated: %s\nPolicy: future suites may ADD tests but may not silently drop these functional tests.'%(b.get('version'),b.get('count'),str(b.get('sha256') or '')[:24],_n28_time.strftime('%Y-%m-%d %H:%M:%S',_n28_time.localtime(float(b.get('created') or 0))))


def _n291_requests_text(cid):
    _n291_sweep()
    with _N291_LOCK:
        arr=[(k,dict(v)) for k,v in _N291_REQ.items()]
    arr.sort(key=lambda kv:float(kv[1].get('started') or 0),reverse=True)
    lines=['REQUEST LIFECYCLE — recent']
    for tok,r in arr[:12]:
        age=int((_n29_now()-(float(r.get('finished') or 0) or _n29_now())) if r.get('finished') else (_n29_now()-float(r.get('started') or _n29_now())))
        elapsed=int((float(r.get('finished') or _n29_now())-float(r.get('started') or _n29_now()))*1000)
        lines.append('%s | %s | %sms | %s'%(tok,r.get('state'),max(0,elapsed),_n291_safe_text(r.get('summary'),80)))
    if len(lines)==1:lines.append('No v29.1 normal-chat requests recorded since restart.')
    return '\n'.join(lines)[:3900]


def _n291_health_text(cid,full=False):
    s=_n291_system_snapshot();db=_n291_sqlite_probe();locked=[x for x in db if not x.get('ok')]
    lines=[
      'NEMO 29.1 — PRODUCTION HEALTH',
      '━━━━━━━━━━━━━━━━━━━━',
      'Uptime: %ss | RSS peak: %.1f MB | Disk free: %.2f GB'%(s['uptime_s'],s['rss_mb'],s['disk_free_gb']),
      'Python threads: %s | tracked workers: %s | active chat requests: %s'%(s['threads'],s['workers'],s['active']),
      'Final answers: %s | duplicate finals suppressed: %s | stale finals suppressed: %s'%(s['counts'].get('final_delivered',0),s['counts'].get('duplicate_final_suppressed',0),s['counts'].get('stale_final_suppressed',0)),
      'Request failures: %s'%(s['counts'].get('request_failures',0)),
      'SQLite DBs probed: %s | contention/lock failures: %s'%(len(db),len(locked)),
      'Standalone watchdog messages: '+('ON (diagnostic)' if _n2831_watch_messages(cid) else 'OFF'),
      'One-token/one-final gate: ACTIVE',
      'Regression contract: '+('CAPTURED' if _n291_baseline_read() else 'PENDING FIRST CLEAN /regress'),
      'Authority expansion: NONE',
    ]
    if locked:
        lines.append('DB contention: '+', '.join(_n291_os.path.basename(x['path'])+' ('+_n291_safe_text(x.get('error'),55)+')' for x in locked[:5]))
    if full:
        lines+=['',_n291_provider_text()] 
    return '\n'.join(lines)[:3900]


# -----------------------------------------------------------------------------
# OWNER COMMANDS / OUTERMOST SECURITY GATE
# -----------------------------------------------------------------------------
_N291_PREV_HANDLE=handle

def _n291_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo291','/production29','/hardening29'):
        send_text(cid,_n291_health_text(cid,False));return True
    if low.startswith('/health29'):
        send_text(cid,_n291_health_text(cid,'full' in low));return True
    if low in ('/providers29','/providerhealth29'):
        send_text(cid,_n291_provider_text());return True
    if low in ('/requests29','/workers29'):
        send_text(cid,_n291_requests_text(cid));return True
    if low in ('/baseline29','/contract29'):
        send_text(cid,_n291_baseline_text());return True
    return False


def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();chat=(msg.get('chat') or {})
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id'):
            low=txt.lower()
            if low.startswith(('/nemo291','/production29','/hardening29','/health29','/providers29','/providerhealth29','/requests29','/workers29','/baseline29','/contract29')):
                try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                except Exception:pass
                return
        if _n291_dispatch(msg):return
    except Exception as e:
        try:
            if '_n210_log_fail' in globals():_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo291_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N291_PREV_HANDLE(msg)


