_N291_REG_PREV=prime_regression_suite

def prime_regression_suite():
    r=_N291_REG_PREV();extra=[]
    if isinstance(r,dict):
        # Only the final version contract is replaced. Functional v29 tests remain.
        r['tests']=[x for x in r.get('tests',[]) if x.get('name')!='v29-version']
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v291-version',lambda:VERSION=='29.1')
    add('v291-one-final-gate',lambda:callable(_n291_final_permission) and callable(deliver))
    add('v291-provider-telemetry',lambda:all(callable(x) for x in (groq_chat,gemini_chat,cerebras_chat,claude_chat,ask_ai)))
    add('v291-request-registry',lambda:callable(_n291_req_start) and callable(_n291_req_finish) and callable(_n291_sweep))
    add('v291-silent-watchdog-preserved',lambda:not _n2831_watch_messages('__v291_eval__'))
    add('v291-sqlite-probe-nondestructive',lambda:callable(_n291_sqlite_probe))
    add('v291-health-dashboard',lambda:callable(_n291_health_text) and callable(_n291_provider_text))
    add('v291-stale-output-protection',lambda:callable(_n282_is_active) and callable(_n291_final_permission))
    add('v291-historical-contract-engine',lambda:callable(_n291_baseline_check) and callable(_n291_contract_names))
    if not isinstance(r,dict):
        rr={'id':'RG291-'+_n28_uuid.uuid4().hex[:8].upper(),'version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
        return rr
    prospective=list(r.get('tests',[]))+extra
    clean_so_far=all(bool(x.get('ok')) for x in prospective)
    bok,bdetail=_n291_baseline_check(prospective,capture_ok=clean_so_far)
    extra.append({'name':'v291-regression-contract','ok':bool(bok),'detail':bdetail})
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r


