def _n34_conn():
    c=_n34_sqlite.connect(_N34_DB,timeout=12)
    c.execute('PRAGMA journal_mode=WAL')
    c.execute('PRAGMA busy_timeout=8000')
    c.execute('PRAGMA synchronous=NORMAL')
    c.executescript("""
    CREATE TABLE IF NOT EXISTS voice_profile(
      chat_id TEXT PRIMARY KEY, girl_voice INTEGER DEFAULT 1,
      verbosity TEXT DEFAULT 'BRIEF', visual_narration INTEGER DEFAULT 1,
      updated REAL
    );
    CREATE TABLE IF NOT EXISTS screen_context(
      id TEXT PRIMARY KEY, chat_id TEXT, image_sig TEXT, question TEXT,
      summary TEXT, app_hint TEXT, created REAL
    );
    CREATE INDEX IF NOT EXISTS idx_n34_screen ON screen_context(chat_id,created DESC);
    CREATE TABLE IF NOT EXISTS memory_alias(
      chat_id TEXT, alias TEXT, canonical TEXT, kind TEXT,
      confidence REAL DEFAULT .98, updated REAL,
      PRIMARY KEY(chat_id,alias)
    );
    CREATE TABLE IF NOT EXISTS memory_temporal(
      id TEXT PRIMARY KEY, chat_id TEXT, fkey TEXT, value TEXT,
      valid_from REAL, valid_to REAL, source TEXT, confidence REAL,
      created REAL
    );
    CREATE INDEX IF NOT EXISTS idx_n34_temporal ON memory_temporal(chat_id,fkey,valid_to,created DESC);
    CREATE TABLE IF NOT EXISTS action_receipt(
      id TEXT PRIMARY KEY, chat_id TEXT, device_id TEXT, request TEXT,
      plan_json TEXT, risk TEXT, status TEXT, result TEXT,
      created REAL, updated REAL
    );
    CREATE INDEX IF NOT EXISTS idx_n34_action ON action_receipt(chat_id,created DESC);
    CREATE TABLE IF NOT EXISTS world_evidence(
      id TEXT PRIMARY KEY, chat_id TEXT, query TEXT, classification TEXT,
      title TEXT, url TEXT, snippet TEXT, domain TEXT, created REAL
    );
    CREATE INDEX IF NOT EXISTS idx_n34_world ON world_evidence(chat_id,created DESC);
    CREATE TABLE IF NOT EXISTS visual_voice(
      id TEXT PRIMARY KEY, chat_id TEXT, title TEXT, narration TEXT,
      path TEXT, created REAL
    );
    """)
    return c


def _n34_clean(v,limit=1000):
    try:return _n28_redact(' '.join(str(v or '').split()))[:int(limit)]
    except Exception:return ' '.join(str(v or '').split())[:int(limit)]


