def _n31_img_sig(img):
    try:return _n34_hashlib.sha256(str(img or '')[:200000].encode('utf-8','ignore')).hexdigest()[:20]
    except Exception:return ''


def _n31_last_screen(cid):
    try:
        c=_n34_conn();r=c.execute('SELECT image_sig,question,summary,app_hint,created FROM screen_context WHERE chat_id=? ORDER BY created DESC LIMIT 1',(str(cid),)).fetchone();c.close()
        if r:return {'image_sig':r[0],'question':r[1],'summary':r[2],'app_hint':r[3],'created':r[4]}
    except Exception:pass
    return None


def _n31_store_screen(cid,img,question,summary):
    sig=_n31_img_sig(img);app=''
    try:
        m=_n34_re.search(r'(?i)\b(?:app|window|browser|application)[:\s]+([A-Za-z0-9 ._-]{2,60})',str(summary or ''))
        if m:app=_n34_clean(m.group(1),60)
    except Exception:pass
    try:
        c=_n34_conn();c.execute('INSERT INTO screen_context VALUES(?,?,?,?,?,?,?)',('SC31-'+_n34_uuid.uuid4().hex[:10].upper(),str(cid),sig,_n34_clean(question,800),_n34_clean(summary,3500),app,_n34_time.time()));c.commit();c.close()
    except Exception:pass
    with _N34_LOCK:_N34_SCREEN_MEM[str(cid)]={'image_sig':sig,'question':question,'summary':summary,'app_hint':app,'created':_n34_time.time()}
    return sig


_N31_SCREEN_PREV=_v182_screen_answer

def _v182_screen_answer(img,question):
    cid=OWNER.get('id') or 0;q=str(question or 'What is on my screen?').strip();prev=_n31_last_screen(cid);sig=_n31_img_sig(img)
    if prev and sig and sig==prev.get('image_sig') and _n34_re.search(r'(?i)\b(what changed|changed|different now|same screen|anything changed)\b',q):
        ans='The screenshot is byte-for-byte the same as the last captured screen, so I do not see a new visual change.'
        _n31_store_screen(cid,img,q,ans);return {'ok':True,'reply':ans,'provider':'screen31-local-diff','vision_ms':0,'authoritative':True,'screen_context':True}
    aug=q
    if prev and _n34_re.search(r'(?i)\b(it|this|that|same|previous|before|changed|again|there|screen)\b',q):
        aug=q+'\nPrevious screen summary for continuity only: '+str(prev.get('summary') or '')[:1400]
    res=_N31_SCREEN_PREV(img,aug)
    if isinstance(res,dict):
        res['vision_os']='31.0';res['screen_context']=bool(prev)
        if res.get('reply'):_n31_store_screen(cid,img,q,res.get('reply'))
    return res


