def _n32_alias_set(cid,alias,canonical,kind='entity',confidence=.99):
    a=_n34_clean(alias,120).lower();cname=_n34_clean(canonical,240)
    if not a or not cname:return False
    try:
        c=_n34_conn();c.execute('INSERT OR REPLACE INTO memory_alias(chat_id,alias,canonical,kind,confidence,updated) VALUES(?,?,?,?,?,?)',(str(cid),a,cname,str(kind)[:60],float(confidence),_n34_time.time()));c.commit();c.close();return True
    except Exception:return False


def _n32_temporal_set(cid,key,value,source='owner-explicit',confidence=.98):
    key=_n34_re.sub(r'[^a-z0-9_]+','_',str(key or '').lower()).strip('_')[:120];value=_n34_clean(value,1200)
    if not key or not value:return None
    now=_n34_time.time();rid='MT32-'+_n34_uuid.uuid4().hex[:10].upper()
    try:
        c=_n34_conn();c.execute('UPDATE memory_temporal SET valid_to=? WHERE chat_id=? AND fkey=? AND valid_to=0',(now,str(cid),key));c.execute('INSERT INTO memory_temporal VALUES(?,?,?,?,?,?,?,?,?)',(rid,str(cid),key,value,now,0.0,str(source)[:80],float(confidence),now));c.commit();c.close();return rid
    except Exception:return None


def _n32_tokens(s):
    stop={'the','and','for','with','that','this','what','when','where','who','how','your','you','are','was','were','have','has','from','about','into','can','could','would','should','my','our','me'}
    return set(x for x in _n34_re.findall(r'[a-z0-9]{3,}',str(s or '').lower()) if x not in stop)


def _n32_memory_context(cid,query,limit=6):
    q=_n32_tokens(query);rows=[]
    try:
        c=_n34_conn()
        for a,can,kind,conf,upd in c.execute('SELECT alias,canonical,kind,confidence,updated FROM memory_alias WHERE chat_id=? ORDER BY updated DESC LIMIT 120',(str(cid),)).fetchall():
            sc=len(q & _n32_tokens(a+' '+can))*4
            if str(a).lower() in str(query).lower():sc+=8
            if sc:rows.append((sc,'ALIAS: %s → %s (%s)'%(a,can,kind)))
        for k,v,vf,src,conf,cr in c.execute('SELECT fkey,value,valid_from,source,confidence,created FROM memory_temporal WHERE chat_id=? AND valid_to=0 ORDER BY created DESC LIMIT 160',(str(cid),)).fetchall():
            sc=len(q & _n32_tokens(k+' '+v))*3
            if sc:rows.append((sc,'CURRENT %s = %s'%(k,v)))
        c.close()
    except Exception:pass
    try:
        c=_n28_conn();facts=c.execute('SELECT fkey,value,confidence,updated FROM facts WHERE chat_id=? AND active=1 ORDER BY updated DESC LIMIT 100',(str(cid),)).fetchall();c.close()
        for k,v,conf,upd in facts:
            sc=len(q & _n32_tokens(str(k)+' '+str(v)))*3
            if sc:rows.append((sc,'FACT %s = %s'%(k,v)))
    except Exception:pass
    rows.sort(key=lambda x:x[0],reverse=True);seen=set();out=[]
    for sc,line in rows:
        k=line.lower()
        if k in seen:continue
        seen.add(k);out.append(line)
        if len(out)>=int(limit):break
    return ('MEMORYOS 7 RELEVANT MEMORY:\n'+'\n'.join('- '+x for x in out)) if out else ''


def _n32_capture(cid,text):
    t=' '.join(str(text or '').split()).strip()
    # Explicit current-state statements only; do not infer sensitive/private attributes.
    m=_n34_re.match(r'(?i)^\s*my current\s+([A-Za-z][A-Za-z0-9 _-]{1,60})\s+is\s+(.{1,500})$',t)
    if m:return _n32_temporal_set(cid,m.group(1),m.group(2),'owner-current',.99)
    m=_n34_re.match(r'(?i)^\s*remember(?: that)?\s+([A-Za-z][A-Za-z0-9 _-]{1,60})\s*(?:=|is)\s*(.{1,500})$',t)
    if m:return _n32_temporal_set(cid,m.group(1),m.group(2),'owner-remember',.99)
    return None


# Inject only query-relevant memory into normal remembered calls. Internal calls
# (remember=False) remain isolated, preserving v28.1 context hygiene.
_N32_ASK_PREV=ask_ai

def ask_ai(chat_id,text,image_b64=None,remember=True,timeout=180,long_output=False,models_override=None,deep=False,ground='',raw=False):
    g=str(ground or '')
    if remember and not image_b64:
        try:
            mc=_n32_memory_context(chat_id,str(text or ''),6)
            if mc:g=(g+'\n\n'+mc).strip()
        except Exception:pass
    return _N32_ASK_PREV(chat_id,text,image_b64=image_b64,remember=remember,timeout=timeout,long_output=long_output,models_override=models_override,deep=deep,ground=g,raw=raw)


