def _n33_risk(intent):
    if not isinstance(intent,dict):return 'UNKNOWN'
    if intent.get('requires_approval'):return 'APPROVAL'
    k=str(intent.get('kind') or '')
    if k in ('window_target','window','lock','type_text','mouse_click'):return 'MEDIUM'
    if k in ('shell','powershell','cmd','terminal','blocked_sensitive','blocked'):return 'BLOCKED'
    return str(intent.get('risk') or 'LOW').upper()


def _n33_compile_plan(text,device_id='preview'):
    raw=' '.join(str(text or '').split()).strip()
    if not raw:return {'ok':False,'error':'empty request'}
    # Prefer mature compiler first; it already supports bounded control_sequence.
    try:r=_v184_compile_control(device_id,raw)
    except Exception:r=None
    if isinstance(r,dict):
        steps=list(r.get('steps') or []) if r.get('kind')=='control_sequence' else [r]
        if steps and len(steps)<=5:
            risks=[_n33_risk(x) for x in steps]
            if 'BLOCKED' in risks:return {'ok':False,'error':'blocked control class','steps':steps}
            return {'ok':True,'request':raw,'intent':r,'steps':steps,'risk':'APPROVAL' if 'APPROVAL' in risks else 'MEDIUM' if 'MEDIUM' in risks else 'LOW','requires_approval':any(bool(x.get('requires_approval')) for x in steps)}
    return {'ok':False,'error':'could not compile deterministically'}


def _n33_receipt_create(cid,device_id,request,plan,status='PLANNED'):
    rid='ACT33-'+_n34_uuid.uuid4().hex[:10].upper();risk=str((plan or {}).get('risk') or 'UNKNOWN')
    try:
        c=_n34_conn();c.execute('INSERT INTO action_receipt VALUES(?,?,?,?,?,?,?,?,?,?)',(rid,str(cid),str(device_id or ''),_n34_clean(request,1200),_n34_json.dumps(plan,ensure_ascii=False)[:10000],risk,str(status), '',_n34_time.time(),_n34_time.time()));c.commit();c.close();return rid
    except Exception:return ''


def _n33_receipt_from_voice(cid,device_id,text,intent):
    plan={'ok':True,'request':text,'intent':intent,'steps':intent.get('steps') if isinstance(intent,dict) and intent.get('kind')=='control_sequence' else [intent],'risk':_n33_risk(intent),'requires_approval':bool((intent or {}).get('requires_approval'))}
    return _n33_receipt_create(cid,device_id,text,plan,'SENT_TO_DEVICE')


def _n33_receipt_update(rid,status,result=''):
    try:
        c=_n34_conn();cur=c.execute('UPDATE action_receipt SET status=?,result=?,updated=? WHERE id=?',(str(status)[:40],_n34_clean(result,2200),_n34_time.time(),str(rid))).rowcount;c.commit();c.close();return cur>0
    except Exception:return False


def _n33_receipts_text(cid):
    try:
        c=_n34_conn();rows=c.execute('SELECT id,request,risk,status,result,created FROM action_receipt WHERE chat_id=? ORDER BY created DESC LIMIT 12',(str(cid),)).fetchall();c.close()
    except Exception:rows=[]
    lines=['ACTIONOS 33 — RECEIPTS']
    for rid,req,risk,status,result,created in rows:
        lines.append('%s | %s | %s\n%s%s'%(rid,status,risk,_n34_clean(req,110),('\n↳ '+_n34_clean(result,140)) if result else ''))
    if len(lines)==1:lines.append('No action receipts yet.')
    return '\n'.join(lines)[:3900]


