def _n34_world_class(text):
    try:return _n28_world_class(text)
    except Exception:return 'STATIC'


def _n34_world_should_ground(text):
    return _n34_world_class(text) in ('CURRENT','REALTIME')


def _n34_domain(url):
    try:return (_n34_urlparse(str(url or '')).netloc or '').lower().replace('www.','')[:120]
    except Exception:return ''


def _n34_evidence_search(cid,query,limit=6):
    try:raw=web_search(str(query)[:900]) or []
    except Exception:raw=[]
    out=[];seen=set();domains=set();cls=_n34_world_class(query)
    for r in raw:
        url=str(r.get('href') or r.get('url') or '').strip();title=_n34_clean(r.get('title'),260);snip=_n34_clean(r.get('body') or r.get('snippet'),1000)
        key=(url or title).lower()
        if not key or key in seen:continue
        seen.add(key);dom=_n34_domain(url)
        # Prefer source diversity when enough results exist, but do not discard all duplicates.
        if dom and dom in domains and len(raw)>int(limit):continue
        if dom:domains.add(dom)
        row={'title':title,'url':url,'snippet':snip,'domain':dom};out.append(row)
        try:
            c=_n34_conn();c.execute('INSERT INTO world_evidence VALUES(?,?,?,?,?,?,?,?,?)',('WE34-'+_n34_uuid.uuid4().hex[:10].upper(),str(cid),_n34_clean(query,900),cls,title,url,snip,dom,_n34_time.time()));c.commit();c.close()
        except Exception:pass
        if len(out)>=int(limit):break
    return out,cls


def _n34_world_text(cid,query,limit=6):
    rows,cls=_n34_evidence_search(cid,query,limit)
    if not rows:return '',{'class':cls,'sources':0}
    evidence=[]
    for i,r in enumerate(rows,1):evidence.append('[%d] %s\n%s\n%s'%(i,r['title'],r['url'],r['snippet']))
    prompt=(
      'NEMO WORLDSENSE 3. Answer the CURRENT request using ONLY the fresh evidence below for time-sensitive claims. '
      'Separate confirmed facts from uncertainty when sources disagree. Do not invent missing details. Keep exact dates when relevant. '
      'For voice-friendly readability, lead with the answer, then the key evidence.\n\nREQUEST:\n'+str(query)[:2200]+'\n\nFRESH EVIDENCE:\n'+'\n\n'.join(evidence))
    try:ans=_N32_ASK_PREV(cid,prompt,remember=False,timeout=110,deep=True,raw=False) or ''
    except Exception:ans=''
    if ans:
        links='\n'.join('- '+r['url'] for r in rows[:5] if r['url'])
        if links:ans=str(ans).rstrip()+'\n\nSources:\n'+links
    return ans,{'class':cls,'sources':len(rows),'domains':len(set(r['domain'] for r in rows if r['domain']))}


def _n34_world_ledger_text(cid):
    try:
        c=_n34_conn();rows=c.execute('SELECT classification,title,url,created FROM world_evidence WHERE chat_id=? ORDER BY created DESC LIMIT 15',(str(cid),)).fetchall();c.close()
    except Exception:rows=[]
    lines=['WORLDSENSE 3 — EVIDENCE LEDGER']
    for cls,title,url,created in rows:lines.append('%s | %s\n%s'%(cls,_n34_clean(title,100),_n34_clean(url,180)))
    if len(lines)==1:lines.append('No v34 evidence recorded yet.')
    return '\n'.join(lines)[:3900]


