def _n34_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo34','/omni34','/fivebatch'):
        send_text(cid,_n34_status(cid));return True
    if low in ('/voice30','/voice34','/girlvoice','/voicestatus34'):
        send_text(cid,_n34_voice_status_text(cid));return True
    if low.startswith('/voicegirl'):
        arg=low[len('/voicegirl'):].strip()
        if arg in ('off','male'):
            _n30_profile_set(cid,girl_voice=False);send_text(cid,'Girl-voice preference disabled. Existing custom voice config was not erased.');return True
        _n30_apply_girl_voice(True);_n30_profile_set(cid,girl_voice=True);send_text(cid,'🎙 Girl Voice ON — Neerja for English, Swara for Hindi.');return True
    if low.startswith('/voicevisual'):
        arg=low[len('/voicevisual'):].strip()
        if arg in ('on','off'):
            _n30_profile_set(cid,visual_narration=(arg=='on'));send_text(cid,'🖼🔊 Visual narration '+arg.upper()+'.');return True
        send_text(cid,'Visual narration is '+('ON' if _n30_profile(cid)['visual_narration'] else 'OFF')+'. Use /voicevisual on | off');return True
    if low in ('/voicebrief','/voicenormal','/voicefull'):
        mode={'/voicebrief':'BRIEF','/voicenormal':'NORMAL','/voicefull':'FULL'}[low];_n30_profile_set(cid,verbosity=mode);send_text(cid,'Voice verbosity set to '+mode+'.');return True
    if low in ('/visualexplain','/readvisual','/read diagram'):
        with _N34_LOCK:v=dict(_N34_LAST_VISUAL.get(str(cid)) or {})
        if not v:send_text(cid,'I do not have a recent visual narration yet. Create a diagram first.');return True
        _n34_threading.Thread(target=speak,args=(cid,v.get('narration') or ('I created '+str(v.get('title') or 'the diagram'))),daemon=True).start();send_text(cid,'🔊 Reading the latest visual in Nemo girl voice.');return True
    if low in ('/screen31','/vision31'):
        p=_n31_last_screen(cid);send_text(cid,'SCREEN INTELLIGENCE 31\n'+(('Last summary: '+str(p.get('summary') or '')[:2600]) if p else 'No screen context captured yet.'));return True
    if low.startswith('/alias32 '):
        body=txt[len('/alias32 '):].strip();a,sep,b=body.partition('=')
        if not sep:send_text(cid,'Usage: /alias32 alias = canonical name');return True
        send_text(cid,'✅ Alias saved.' if _n32_alias_set(cid,a,b) else 'Could not save alias.');return True
    if low.startswith('/remember32 '):
        body=txt[len('/remember32 '):].strip();k,sep,v=body.partition('=')
        if not sep:send_text(cid,'Usage: /remember32 key = value');return True
        rid=_n32_temporal_set(cid,k,v,'owner-command',.995);send_text(cid,'🧠 MemoryOS 7 saved: '+k.strip()+' = '+v.strip() if rid else 'Could not save memory.');return True
    if low.startswith('/recall32'):
        q=txt[len('/recall32'):].strip() or str(LASTQ.get(cid,'') or 'recent')
        mc=_n32_memory_context(cid,q,10);send_text(cid,mc or 'MemoryOS 7 found no relevant current memory for that query.');return True
    if low in ('/memory32','/memoryos7'):
        try:
            c=_n34_conn();a=c.execute('SELECT COUNT(*) FROM memory_alias WHERE chat_id=?',(str(cid),)).fetchone()[0];t=c.execute('SELECT COUNT(*) FROM memory_temporal WHERE chat_id=? AND valid_to=0',(str(cid),)).fetchone()[0];c.close()
        except Exception:a=t=0
        send_text(cid,'MEMORYOS 7\nActive temporal facts: %s\nAliases: %s\nMemory Guard 6: PRESERVED\nUse /remember32 key = value | /alias32 alias = canonical | /recall32 query'%(t,a));return True
    if low.startswith('/actionplan'):
        q=txt[len('/actionplan'):].strip()
        if not q:send_text(cid,'Usage: /actionplan <Windows task>');return True
        p=_n33_compile_plan(q,'preview');rid=_n33_receipt_create(cid,'preview',q,p,'PLANNED') if p.get('ok') else ''
        safe=dict(p);safe.pop('intent',None)
        send_text(cid,'ACTIONOS PLAN — preview only, nothing executed\nReceipt: '+(rid or 'none')+'\n\n'+_n34_json.dumps(safe,ensure_ascii=False,indent=2)[:3300]);return True
    if low in ('/actions33','/receipts33'):
        send_text(cid,_n33_receipts_text(cid));return True
    if low.startswith('/world34 '):
        q=txt[len('/world34 '):].strip();send_text(cid,'🔎 WorldSense 3 is gathering fresh evidence...')
        def _go():
            ans,meta=_n34_world_text(cid,q,6);send_text(cid,ans or 'Fresh evidence was unavailable; I did not invent an answer.')
        _n34_threading.Thread(target=_go,daemon=True,name='nemo-world34').start();return True
    if low in ('/worldledger','/evidence34'):
        send_text(cid,_n34_world_ledger_text(cid));return True
    return False


