_N34_PREV_HANDLE=handle

def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();chat=(msg.get('chat') or {})
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id'):
            low=txt.lower()
            if low.startswith(('/nemo34','/omni34','/fivebatch','/voice30','/voice34','/girlvoice','/voicestatus34','/voicegirl','/voicevisual','/voicebrief','/voicenormal','/voicefull','/visualexplain','/readvisual','/screen31','/vision31','/alias32','/remember32','/recall32','/memory32','/memoryos7','/actionplan','/actions33','/receipts33','/world34','/worldledger','/evidence34')):
                try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                except Exception:pass
                return
        if _n34_dispatch(msg):return
        if cid==OWNER.get('id') and txt and not txt.startswith('/'):
            try:_n32_capture(cid,txt)
            except Exception:pass
    except Exception as e:
        try:_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo34_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N34_PREV_HANDLE(msg)


