def build_web_app():
    app=_N34_WEB_PREV()
    try:
        from flask import request,jsonify
        @app.route('/api/voice34/ping',methods=['POST'])
        def _n34_voice_ping():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '');tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            p=_n30_profile(OWNER.get('id') or 0)
            return jsonify({'ok':True,'version':VERSION,'voice_os':'6.0','persona':'NEMO_GIRL','girl_voice':bool(p['girl_voice']),'visual_narration':bool(p['visual_narration']),'legacy_voice182_compatible':True,'authority':'unchanged'})
        @app.route('/api/action33/receipt',methods=['POST'])
        def _n33_receipt_api():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '');tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            rid=str(d.get('receipt_id') or '')[:80];status=str(d.get('status') or '')[:40];result=str(d.get('result') or '')[:2200]
            if not rid or not status:return jsonify({'ok':False,'error':'missing receipt/status'}),400
            return jsonify({'ok':_n33_receipt_update(rid,status,result),'receipt_id':rid})
        @app.route('/api/voice34/visual',methods=['POST'])
        def _n34_visual_api():
            d=request.get_json(force=True,silent=True) or {};did=str(d.get('device_id') or '');tok=request.headers.get('Authorization','').replace('Bearer ','',1).strip()
            if not _v162_auth(did,tok):return jsonify({'ok':False,'error':'unauthorized'}),403
            q=str(d.get('request') or '')[:2400]
            if not q:return jsonify({'ok':False,'error':'empty request'}),400
            cid=OWNER.get('id') or 0
            _n34_threading.Thread(target=_n30_queue_voice_visual,args=(cid,q),daemon=True,name='voice34-visual').start()
            return jsonify({'ok':True,'queued':True,'target':'telegram','voice_os':'6.0'})
    except Exception as e:
        try:print('v34 web routes:',type(e).__name__,str(e)[:180])
        except Exception:pass
    return app


