def prime_regression_suite():
    r=_N34_REG_PREV();extra=[]
    if isinstance(r,dict):
        # Supersede only obsolete version assertions; preserve every functional test.
        r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v291-version','v281-version','v282-version','v283-version','v2831-version','v2832-version')]  # v34.0-FIXED: stale 28.x version contracts superseded by 34.0
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v34-version',lambda:VERSION=='34.0')
    add('v30-girl-voice',lambda:VOICECFG.get('en')=='en-IN-NeerjaNeural' and VOICECFG.get('hi')=='hi-IN-SwaraNeural')
    add('v30-unique-tts-path',lambda:callable(speak) and callable(_n30_profile))
