    add('v31-screen-context',lambda:callable(_v182_screen_answer) and callable(_n31_store_screen) and callable(_n31_last_screen))
    add('v32-memory-alias',lambda:_n32_alias_set('__eval34__','wife','Hetvi','person') and 'Hetvi' in _n32_memory_context('__eval34__','wife',5))
    add('v32-temporal-memory',lambda:bool(_n32_temporal_set('__eval34__','current_project','Nemo','eval',.9)))
    add('v32-memory-isolation',lambda:callable(ask_ai) and callable(_n32_memory_context))
    add('v33-action-plan',lambda:_n33_compile_plan('open Chrome then search youtube for cats').get('ok'))
    add('v33-shell-blocked',lambda:not _n33_compile_plan('run powershell delete all files').get('ok'))
    add('v33-action-receipts',lambda:callable(_n33_receipt_create) and callable(_n33_receipt_update))
    add('v34-world-class-current',lambda:_n34_world_should_ground('latest AI news today'))
    add('v34-world-class-static',lambda:not _n34_world_should_ground('what is photosynthesis'))
    add('v34-evidence-ledger',lambda:callable(_n34_evidence_search) and callable(_n34_world_ledger_text))
    add('v34-owner-gate',lambda:callable(handle) and callable(_n34_dispatch))
    add('v34-production-hardening-preserved',lambda:callable(_n291_health_text) and callable(_n291_baseline_check))
    add('v34-arbitrary-shell-authority-unchanged',lambda:(_v184_compile_control('x','run powershell delete all files') or {}).get('kind') not in ('shell','powershell','cmd','terminal'))
    if not isinstance(r,dict):
        return {'id':'RG34-'+_n34_uuid.uuid4().hex[:8].upper(),'version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r


