    rows.extend([
      {'name':'v30-voiceos6','ok':VOICECFG.get('en')=='en-IN-NeerjaNeural','detail':'girl voice + concurrency-safe TTS + visual narration'},
      {'name':'v31-vision-context','ok':callable(_n31_last_screen),'detail':'screen continuity and exact-image change detection'},
      {'name':'v32-memoryos7','ok':callable(_n32_memory_context),'detail':'aliases + temporal facts + query-relevant injection'},
      {'name':'v33-actionos','ok':callable(_n33_compile_plan),'detail':'bounded deterministic plans + receipts'},
      {'name':'v34-worldsense3','ok':_n34_world_should_ground('latest market news today'),'detail':'fresh evidence classification + ledger'},
      {'name':'v34-authority','ok':(_v184_compile_control('x','run powershell delete all files') or {}).get('kind') not in ('shell','powershell','cmd','terminal'),'detail':'no arbitrary shell authority'}])
    # de-duplicate eval names while preserving newest instance.
    seen=set();out=[]
    for x in reversed(rows):
        n=str(x.get('name') or '')
        if n in seen:continue
        seen.add(n);out.append(x)
    return list(reversed(out))


