VERSION='35.0'
import sqlite3 as _n35_sqlite, re as _n35_re, time as _n35_time, json as _n35_json, os as _n35_os
import threading as _n35_threading, uuid as _n35_uuid, math as _n35_math

_N35_LOCK=_n35_threading.RLock()
_N35_STATE={'migrated':False,'migrated_rows':0,'migration_detail':{}}

def _n35_db_path():
    for d in ('/root',_n35_os.path.expanduser('~'),'/tmp'):
        try:
            if _n35_os.path.isdir(d) and _n35_os.access(d,_n35_os.W_OK):return _n35_os.path.join(d,'nemo_memory.db')
        except Exception:pass
    return 'nemo_memory.db'
_N35_DB=_n35_db_path()

def _n35_conn():
    c=_n35_sqlite.connect(_N35_DB,timeout=12,check_same_thread=False)
    try:
        c.execute('PRAGMA journal_mode=WAL');c.execute('PRAGMA busy_timeout=8000');c.execute('PRAGMA synchronous=NORMAL')
    except Exception:pass
    return c

def _n35_init():
    c=_n35_conn()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS facts(
      id TEXT PRIMARY KEY, chat_id TEXT, fkey TEXT, value TEXT, norm TEXT,
      category TEXT DEFAULT 'fact', source TEXT, confidence REAL DEFAULT .95,
      active INTEGER DEFAULT 1, seen_count INTEGER DEFAULT 1,
      created REAL, updated REAL, superseded_by TEXT DEFAULT ''
    );
    CREATE INDEX IF NOT EXISTS idx_n35_facts ON facts(chat_id,fkey,active,updated DESC);
    CREATE TABLE IF NOT EXISTS episodes(
      id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id TEXT, ts REAL, role TEXT, text TEXT, source TEXT, latency_ms INTEGER DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS idx_n35_ep ON episodes(chat_id,ts DESC);
    CREATE TABLE IF NOT EXISTS corrections(
      id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id TEXT, ts REAL, fkey TEXT, old_value TEXT, new_value TEXT, source TEXT
    );
    CREATE TABLE IF NOT EXISTS migration(src TEXT PRIMARY KEY, ts REAL, rows INTEGER, detail TEXT);
    """)
    c.commit();c.close()
try:_n35_init()
except Exception:pass

# ------------------------------- helpers --------------------------------------
_N35_STOP=set('the a an is are was were be my me i you your of to in on at for and or it that this with what who which how kya hai ka ki ke mera meri mere hai hain ho'.split())
def _n35_norm(s):return ' '.join(_n35_re.findall(r'[a-z0-9@._+-]+',str(s or '').lower()))
def _n35_tokens(s):return {w for w in _n35_norm(s).split() if len(w)>2 and w not in _N35_STOP}
def _n35_name(v):
    v=' '.join(str(v or '').split()).strip(' .,!?;:"\'')
    v=_n35_re.split(r'(?i)\s+(?:and|but|so|because|please|remember|aur|lekin|kyunki)\s+',v)[0].strip(' .,')
    if v.lower()==v or v.upper()==v:v=' '.join(w.capitalize() for w in v.split())
    return v[:80]

# single-valued keys supersede; these keys hold many values
_N35_MULTI=('preference','remembered','standing_instruction','note')

_N35_REL_WORDS={
 'wife':'wife','patni':'wife','biwi':'wife','husband':'husband','pati':'husband',
 'father':'father','papa':'father','pita':'father','dad':'father','mother':'mother','maa':'mother','mummy':'mother','mom':'mother','mata':'mother',
 'son':'son','beta':'son','daughter':'daughter','beti':'daughter','brother':'brother','bhai':'brother','sister':'sister','behen':'sister','didi':'sister',
 'friend':'friend','dost':'friend','best friend':'best_friend','boss':'boss','manager':'manager','partner':'partner','girlfriend':'girlfriend','boyfriend':'boyfriend',
 'teacher':'teacher','doctor':'doctor','dog':'dog','cat':'cat','company':'company','city':'city','boss name':'boss'}
_N35_REL_ALT='|'.join(sorted((_n35_re.escape(k) for k in _N35_REL_WORDS),key=len,reverse=True))

_N35_SINGLE_PATS=[
 (r"(?i)\bmy name is\s+([A-Za-z][A-Za-z .'-]{1,60})",'name'),
 (r"(?i)\b(?:call me|mujhe .{0,10}bulao)\s+([A-Za-z][A-Za-z .'-]{1,40})",'nickname'),
 (r"(?i)\bmera naam\s+([A-Za-z][A-Za-z .'-]{1,60}?)\s+hai\b",'name'),
 (r"(?i)\bmy email(?: id| address)?(?: is)?\s*[:=]?\s*([\w.+-]+@[\w.-]+\.\w+)",'email'),
 (r"(?i)\bmy (?:phone|mobile|number|whatsapp)(?: number)?(?: is)?\s*[:=]?\s*(\+?[\d][\d\s-]{7,16}\d)",'phone'),
 (r"(?i)\bi live in\s+([A-Za-z][A-Za-z ,.'-]{1,60})",'city'),
 (r"(?i)\bi am from\s+([A-Za-z][A-Za-z ,.'-]{1,60})",'hometown'),
 (r"(?i)\bi work (?:at|for|in)\s+([A-Za-z0-9][A-Za-z0-9 &.'-]{1,60})",'workplace'),
 (r"(?i)\bmy birthday is\s+(.{3,40})",'birthday'),
 (r"(?i)\bmy (?:%s)(?:'s)?(?: name)? is\s+([A-Za-z][A-Za-z .'-]{1,60})"%_N35_REL_ALT,'REL'),
 (r"(?i)\b(?:mera|meri|mere)\s+(?:%s)\s+ka naam\s+([A-Za-z][A-Za-z .'-]{1,60}?)\s+hai\b"%_N35_REL_ALT,'REL'),
 (r"(?i)^\s*([A-Z][A-Za-z .'-]{1,60}?)\s+is my\s+(%s)\b"%_N35_REL_ALT,'REL_REV'),
 (r"(?i)^\s*([A-Z][A-Za-z .'-]{1,60}?)\s+(?:mera|meri|mere)\s+(%s)\s+hai\b"%_N35_REL_ALT,'REL_REV'),
 (r"(?i)^\s*my current\s+([A-Za-z][A-Za-z0-9 _-]{1,60}?)\s+is\s+(.{1,300})$",'CURRENT'),
 (r"(?i)^\s*remember(?: that)?\s+([A-Za-z][A-Za-z0-9 _-]{1,40}?)\s*(?:=|\bis\b)\s*(.{1,300})$",'KV'),
]
_N35_MULTI_PATS=[
 (r"(?i)^\s*(?:nemo[,\s]*)?remember(?: that| this)?[:,]?\s+(.{3,600})$",'remembered'),
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:yaad rakhna|yaad rakho)[:,]?\s+(.{3,600})$",'remembered'),
 (r"(?i)\bfrom now on[, ]+\s*(.{3,400})",'standing_instruction'),
 (r"(?i)\b(?:always|never)\s+(.{3,200})\s+(?:from now|going forward)",'standing_instruction'),
 (r"(?i)\bi prefer\s+(.{3,300})",'preference'),
 (r"(?i)\bmujhe\s+(.{3,200})\s+pasand hai",'preference'),
]

def _n35_rel_key(word):
    w=str(word or '').strip().lower()
    return _N35_REL_WORDS.get(w,w.replace(' ','_'))

def _n35_is_correction(text):
    return bool(_n35_re.match(r'(?i)^\s*(?:no[, ]+|nahi[, ]+|actually[, ]+|correction[:, ]+|correct(?:ion)?[, ]+|galat[, ]+|wrong[, ]+)',str(text or '')))

# ------------------------------- store ----------------------------------------
def _n35_set_fact(cid,key,value,source='owner-explicit',confidence=.95,force=False,category=''):
    key=str(key or '').strip().lower().replace(' ','_')[:60];value=str(value or '').strip()[:400]
    if not key or not value:return {'ok':False,'status':'EMPTY'}
    norm=_n35_norm(value);now=_n35_time.time();cid=str(cid)
    cat=category or ('relation' if key in set(_N35_REL_WORDS.values()) else ('identity' if key in ('name','nickname','email','phone','city','hometown','workplace','birthday') else ('current' if key.startswith('current:') else ('preference' if key in _N35_MULTI else 'fact'))))
    with _N35_LOCK:
        c=_n35_conn()
        try:
            if key in _N35_MULTI:
                row=c.execute('SELECT id,seen_count,updated FROM facts WHERE chat_id=? AND fkey=? AND norm=? AND active=1',(cid,key,norm)).fetchone()
                if row:
                    if now-(row[2] or 0)>5:c.execute('UPDATE facts SET seen_count=seen_count+1,updated=? WHERE id=?',(now,row[0]));c.commit()
                    return {'ok':True,'status':'SAME','current':value}
                fid='F35-'+_n35_uuid.uuid4().hex[:10].upper()
                c.execute('INSERT INTO facts(id,chat_id,fkey,value,norm,category,source,confidence,active,seen_count,created,updated) VALUES(?,?,?,?,?,?,?,?,1,1,?,?)',(fid,cid,key,value,norm,cat,source,confidence,now,now))
                c.commit();return {'ok':True,'status':'NEW','current':value,'id':fid}
            row=c.execute('SELECT id,value,norm,confidence,seen_count,updated FROM facts WHERE chat_id=? AND fkey=? AND active=1 ORDER BY updated DESC LIMIT 1',(cid,key)).fetchone()
            if row and row[2]==norm:
                # same sentence reaches us twice (handle + ask_ai) within seconds: count it once
                if now-(row[5] or 0)>5:c.execute('UPDATE facts SET seen_count=seen_count+1,updated=?,confidence=MAX(confidence,?) WHERE id=?',(now,confidence,row[0]));c.commit()
                return {'ok':True,'status':'SAME','current':row[1]}
            if row and not force and 'correction' not in str(source) and row[3]>=.97 and row[4]>=2:
                return {'ok':False,'status':'CONFLICT','current':row[1],'heard':value}
            fid='F35-'+_n35_uuid.uuid4().hex[:10].upper()
            c.execute('INSERT INTO facts(id,chat_id,fkey,value,norm,category,source,confidence,active,seen_count,created,updated) VALUES(?,?,?,?,?,?,?,?,1,1,?,?)',(fid,cid,key,value,norm,cat,source,confidence,now,now))
            if row:
                c.execute('UPDATE facts SET active=0,superseded_by=?,updated=? WHERE id=?',(fid,now,row[0]))
                c.execute('INSERT INTO corrections(chat_id,ts,fkey,old_value,new_value,source) VALUES(?,?,?,?,?,?)',(cid,now,key,row[1],value,source))
            c.commit();return {'ok':True,'status':'UPDATED' if row else 'NEW','current':value,'previous':row[1] if row else '','id':fid}
        finally:c.close()

def _n35_get_fact(cid,key):
    try:
        c=_n35_conn();r=c.execute('SELECT value FROM facts WHERE chat_id=? AND fkey=? AND active=1 ORDER BY updated DESC LIMIT 1',(str(cid),str(key).lower())).fetchone();c.close()
        return r[0] if r else ''
    except Exception:return ''

def _n35_facts(cid,limit=200):
    try:
        c=_n35_conn();rows=c.execute('SELECT fkey,value,category,source,confidence,seen_count,updated FROM facts WHERE chat_id=? AND active=1 ORDER BY updated DESC LIMIT ?',(str(cid),int(limit))).fetchall();c.close()
        return rows
    except Exception:return []

def _n35_forget(cid,needle):
    n=_n35_norm(needle);cid=str(cid)
    if not n:return 0
    with _N35_LOCK:
        c=_n35_conn()
        try:
            rows=c.execute('SELECT id,fkey,norm FROM facts WHERE chat_id=? AND active=1',(cid,)).fetchall()
            hit=[r[0] for r in rows if n in (r[1] or '').replace('_',' ') or n in (r[2] or '') or (r[2] or '') in n and len(r[2] or '')>3]
            for fid in hit:c.execute('UPDATE facts SET active=0,updated=? WHERE id=?',(_n35_time.time(),fid))
            c.commit();return len(hit)
        finally:c.close()

def _n35_episode(cid,role,text,source='chat',latency_ms=0):
    try:
        with _N35_LOCK:
            c=_n35_conn()
            c.execute('INSERT INTO episodes(chat_id,ts,role,text,source,latency_ms) VALUES(?,?,?,?,?,?)',(str(cid),_n35_time.time(),str(role)[:16],str(text or '')[:4000],str(source)[:40],int(latency_ms or 0)))
            c.execute('DELETE FROM episodes WHERE chat_id=? AND id NOT IN (SELECT id FROM episodes WHERE chat_id=? ORDER BY id DESC LIMIT 300)',(str(cid),str(cid)))
            c.commit();c.close()
    except Exception:pass

# ------------------------------- extraction -----------------------------------
def _n35_extract(cid,text,source='owner-text'):
    """ONE extractor for every layer. Returns (key,value,result) or None."""
    t=' '.join(str(text or '').split()).strip()
    if not t or len(t)>1200 or t.startswith('/'):return None
    # questions are never facts ("what is my wife's name" must not store wife = "What")
    if '?' in t or _n35_re.match(r"(?i)^\s*(?:nemo[,\s]*)?(what|who|whose|whom|which|when|where|why|how|is|are|was|were|do|does|did|can|could|would|will|should|tell me|batao|kya|kaun|kon|kab|kahan|kyun|kaise|kitna|kitne)\b",t):return None
    force=_n35_is_correction(t)
    if force:
        t=_n35_re.sub(r'(?i)^\s*(?:no[, ]+|nahi[, ]+|actually[, ]+|correction[:, ]+|correct(?:ion)?[, ]+|galat[, ]+|wrong[, ]+)','',t).strip()
        source='owner-correction'
    for pat,kind in _N35_SINGLE_PATS:
        m=_n35_re.search(pat,t)
        if not m:continue
        if kind=='REL':
            rel=_n35_re.search(r'(?i)\b(%s)\b'%_N35_REL_ALT,m.group(0)).group(1);key=_n35_rel_key(rel);val=_n35_name(m.group(1))
        elif kind=='REL_REV':key=_n35_rel_key(m.group(2));val=_n35_name(m.group(1))
        elif kind=='CURRENT':key='current:'+m.group(1).strip().lower().replace(' ','_');val=m.group(2).strip(' .')
        elif kind=='KV':key=m.group(1).strip().lower().replace(' ','_');val=m.group(2).strip(' .')
        else:key=kind;val=_n35_name(m.group(1)) if kind in ('name','nickname','city','hometown','workplace') else m.group(1).strip(' .')
        if not val or len(val)<1:continue
        res=_n35_set_fact(cid,key,val,source,.995 if force else .98,force=force)
        return key,val,res
    for pat,key in _N35_MULTI_PATS:
        m=_n35_re.search(pat,t)
        if m:
            val=m.group(1).strip(' .')
            if len(val)<3:continue
            res=_n35_set_fact(cid,key,val,source,.97)
            return key,val,res
    return None

# ------------------------------- context --------------------------------------
def _n35_context(cid,query,limit=8,budget=1600):
    rows=_n35_facts(cid,240)
    if not rows:return ''
    q=_n35_tokens(query);ql=str(query or '').lower();out=[]
    for k,v,cat,src,conf,seen,upd in rows:
        kk=k.replace('_',' ').replace(':',' ');sc=0
        if k=='name':sc+=3
        if k=='standing_instruction':sc+=4
        if k in ('nickname','preference'):sc+=1
        toks=_n35_tokens(kk+' '+v)
        sc+=len(q & toks)*3
        if kk and kk in ql:sc+=6
        if any(w in ql for w in ('me','my','mera','meri','mere','about me','who am i','remember','know about')):sc+=1
        for hw,rk in _N35_REL_WORDS.items():
            if rk==k and hw in ql:sc+=8
        if sc>0:out.append((sc,upd,k,v,cat))
    if not out:return ''
    out.sort(key=lambda x:(-x[0],-x[1]));lines=[];used=0
    for sc,upd,k,v,cat in out[:max(limit,3)]:
        label=k.replace('_',' ')
        if k.startswith('current:'):label='current '+k[8:].replace('_',' ')
        line='- %s: %s'%(label,v)
        if used+len(line)>budget:break
        lines.append(line);used+=len(line)
    if not lines:return ''
    return 'NEMO UNIFIED MEMORY (facts the owner told me; use only when relevant, never invent more):\n'+'\n'.join(lines)

def _n35_relation_answer(cid,text):
    t=' '.join(str(text or '').lower().split())
    if not _n35_re.search(r"(?i)\b(what|who|kya|kaun|kon|naam|name)\b",t):return None
    for hw,rk in sorted(_N35_REL_WORDS.items(),key=lambda x:-len(x[0])):
        if _n35_re.search(r"(?i)\b(?:my|mera|meri|mere)\s+%s(?:'s)?(?:\s+(?:ka\s+)?(?:name|naam))?\b"%_n35_re.escape(hw),t):
            v=_n35_get_fact(cid,rk)
            if v:return "Your %s is %s."%(hw,v)
            return None
    if _n35_re.search(r"(?i)\b(what is my name|who am i|mera naam kya)\b",t):
        v=_n35_get_fact(cid,'name')
        if v:return "You are %s."%v
    return None

# ------------------------------- migration ------------------------------------
def _n35_migrate():
    """Read the old per-layer memory DBs once into the unified store. Old files stay untouched."""
    plan=[
      ('/root/nemo_memory204.db','SELECT key,value,confidence,ts FROM facts WHERE active=1','v20.4',lambda r:(r[0],r[1],r[2] or .9)),
      ('/root/nemo25_core.db','SELECT mkey,value,confidence,updated FROM memory_pins WHERE active=1','v25',lambda r:(r[0],r[1],r[2] or .9)),
      ('/root/nemo26_voice_memory.db','SELECT fkey,value,confidence,updated FROM voice_facts WHERE active=1','v26',lambda r:(r[0],r[1],r[2] or .9)),
      ('/root/nemo28_cortex.db','SELECT fkey,value,confidence,updated FROM facts WHERE active=1','v28',lambda r:(r[0],r[1],r[2] or .9)),
      ('/root/nemo34_omni.db','SELECT fkey,value,confidence,created FROM memory_temporal WHERE valid_to=0','v32-temporal',lambda r:('current:'+str(r[0]).lower().replace(' ','_') if not str(r[0]).startswith('current:') else r[0],r[1],r[2] or .9)),
      ('/root/nemo34_omni.db#alias','SELECT alias,canonical,confidence,updated FROM memory_alias','v32-alias',lambda r:(r[0],r[1],r[2] or .9)),
    ]
    total=0;detail={}
    for path,sql,tag,mapper in plan:
        real=path.split('#')[0]
        if not _n35_os.path.exists(real):continue
        try:
            c=_n35_conn();done=c.execute('SELECT 1 FROM migration WHERE src=?',(path,)).fetchone();c.close()
            if done:continue
            src=_n35_sqlite.connect(real,timeout=8);rows=src.execute(sql).fetchall();src.close()
        except Exception as e:
            detail[tag]='skip: '+type(e).__name__;continue
        n=0
        for r in rows:
            try:
                k,v,conf=mapper(r)
                if not k or not v:continue
                res=_n35_set_fact('OWNER_MIGRATE',k,v,'migrated:'+tag,min(float(conf),.96))
                if res.get('ok'):n+=1
            except Exception:pass
        try:
            c=_n35_conn();c.execute('INSERT OR REPLACE INTO migration(src,ts,rows,detail) VALUES(?,?,?,?)',(path,_n35_time.time(),n,tag));c.commit();c.close()
        except Exception:pass
        total+=n;detail[tag]=n
    # facts were migrated under a placeholder chat id; re-home them to the owner once OWNER is known
    try:
        oid=str(OWNER.get('id') or '') if isinstance(OWNER,dict) else ''
        if oid:
            c=_n35_conn();c.execute("UPDATE facts SET chat_id=? WHERE chat_id='OWNER_MIGRATE'",(oid,));c.commit();c.close()
    except Exception:pass
    _N35_STATE['migrated']=True;_N35_STATE['migrated_rows']+=total;_N35_STATE['migration_detail']=detail
    return total,detail

# ------------------------------- RE-BIND OLD LAYERS ----------------------------
# Every function below is looked up by name at call time inside the older wrappers,
# so re-binding here silently routes all six memory systems into the unified store.
_N35_REBOUND=[]
def _n35_rebind(name,fn):
    if name in globals():
        globals()['_N35_OLD_'+name]=globals()[name];globals()[name]=fn;_N35_REBOUND.append(name)
# v20.4 — memory store + continuity context (recent turns already handled by base history + v21 contract)
_n35_rebind('_m204facts',lambda cid,text:None)
_n35_rebind('_m204store',lambda cid,role,text:None)
_n35_rebind('_m204ctx',lambda cid,q:'')
_n35_rebind('_n204_context',lambda cid,q:'')
# v25 — project pins
_n35_rebind('_n250_extract_pin',lambda cid,text,project_key=None:None)
_n35_rebind('_n250_memory_context',lambda cid,text:'')
# v26 — voice relation facts
_n35_rebind('_n260_extract_explicit_fact',lambda cid,text,source='voice-explicit':(lambda r:(r[0],r[1]) if r else None)(_n35_extract(cid,text,source)))
_n35_rebind('_n260_relation_question',lambda cid,text:None)
_n35_rebind('_n260_fact_set',lambda cid,key,value,source='voice-explicit',confidence=.98:bool(_n35_set_fact(cid,key,value,source,confidence).get('ok')))
# v27 — context graph
_n35_rebind('_n270_graph_extract',lambda cid,text,source='conversation':None)
_n35_rebind('_n270_graph_context',lambda cid:'')
# v28 — cortex facts / relation answer / episodes (keeps its referent, lesson and world contexts)
_n35_rebind('_n28_extract_fact',lambda cid,text,source='text-explicit':_n35_extract(cid,text,source))
_n35_rebind('_n28_relation_answer',_n35_relation_answer)
_n35_rebind('_n28_set_fact',lambda cid,key,value,source='explicit-user',confidence=.98,force=False:_n35_set_fact(cid,key,value,source,confidence,force=force))
_n35_rebind('_n28_episode',_n35_episode)
# v32 — aliases / temporal facts / capture; its context slot becomes THE single injection point
_n35_rebind('_n32_capture',lambda cid,text:None)
_n35_rebind('_n32_alias_set',lambda cid,alias,canonical,kind='entity',confidence=.99:bool(_n35_set_fact(cid,alias,canonical,'alias-'+str(kind),confidence).get('ok')))
_n35_rebind('_n32_temporal_set',lambda cid,key,value,source='owner-explicit',confidence=.98:_n35_set_fact(cid,('current:'+str(key).lower().replace(' ','_')) if not str(key).startswith('current:') else key,value,source,confidence))
_n35_rebind('_n32_memory_context',lambda cid,query,limit=6:_n35_context(cid,query,limit))

# ------------------------------- /mind graph ----------------------------------
_N35_CAT_COLOR={'you':'#F4B942','relation':'#5DADE2','identity':'#58D68D','current':'#F1948A','preference':'#BB8FCE','fact':'#AAB7B8','alias':'#F5CBA7','entity':'#7FB3D5'}

def _n35_graph_data(cid,max_nodes=42):
    rows=_n35_facts(cid,300);nodes=[];edges=[]
    name=_n35_get_fact(cid,'name') or 'You'
    nodes.append({'id':'you','label':name,'cat':'you'})
    for k,v,cat,src,conf,seen,upd in rows:
        if k=='name':continue
        c='alias' if str(src).startswith('alias') else cat
        label=v if c in ('relation','alias') else (k.replace('_',' ').replace('current:','')+': '+v)
        nid='f:'+k+':'+_n35_norm(v)[:30]
        nodes.append({'id':nid,'label':label[:38],'cat':c});edges.append(('you',nid,k.replace('_',' ').replace('current:','now: ') if c in ('relation','alias') else ''))
        if len(nodes)>=max_nodes:break
    # knowledge-graph entities from the v11 world model, if available
    try:
        if '_q' in globals():
            ents=_q('SELECT e.name,e.kind,COUNT(f.id) FROM kg_entities e LEFT JOIN kg_facts f ON f.entity=e.id GROUP BY e.id ORDER BY COUNT(f.id) DESC LIMIT 10')
            for e in ents or []:
                if len(nodes)>=max_nodes+10:break
                nid='kg:'+str(e[0]);nodes.append({'id':nid,'label':str(e[0])[:30],'cat':'entity'});edges.append(('you',nid,str(e[1] or 'knows')[:14]))
    except Exception:pass
    return nodes,edges

def _n35_render_mind(cid):
    nodes,edges=_n35_graph_data(cid)
    if len(nodes)<=1:return None,'empty'
    try:
        import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt;import matplotlib.patches as mp;import textwrap as _tw
    except Exception as e:return None,'matplotlib unavailable: '+str(e)[:80]
    cats={}
    for n in nodes:
        if n['cat']!='you':cats.setdefault(n['cat'],[]).append(n)
    order=['relation','alias','identity','current','preference','fact','entity']
    # ring plan: relations/aliases/identity close to you, others outward; big rings when many nodes
    rings=[];r=2.7
    for cat in order:
        grp=cats.get(cat) or []
        if not grp:continue
        need=max(2.7,len(grp)*0.62/(2*_n35_math.pi)*2.6)
        r=max(r,need);rings.append((cat,grp,r));r+=1.7
    pos={'you':(0.0,0.0)};k=0
    for cat,grp,rr in rings:
        for i,n in enumerate(grp):
            a=2*_n35_math.pi*i/len(grp)+k*0.5
            pos[n['id']]=(rr*_n35_math.cos(a),rr*_n35_math.sin(a))
        k+=1
    lim=r+0.6
    fig,ax=plt.subplots(figsize=(13,13),dpi=110);fig.patch.set_facecolor('#0F1419');ax.set_facecolor('#0F1419')
    for a,b,lab in edges:
        if a in pos and b in pos:
            ax.plot([pos[a][0],pos[b][0]],[pos[a][1],pos[b][1]],color='#34465A',lw=1.0,zorder=1)
            if lab:
                mx,my=(pos[a][0]*0.42+pos[b][0]*0.58),(pos[a][1]*0.42+pos[b][1]*0.58)
                ax.text(mx,my,lab,fontsize=7.5,color='#9FB3C8',ha='center',va='center',zorder=3,bbox=dict(boxstyle='round,pad=0.15',fc='#0F1419',ec='none'))
    for n in nodes:
        x,y=pos[n['id']];col=_N35_CAT_COLOR.get(n['cat'],'#AAB7B8')
        if n['cat']=='you':
            ax.scatter([x],[y],s=3200,color=col,zorder=4,edgecolors='white',linewidths=1.6)
            ax.text(x,y,_tw.fill(n['label'],12),fontsize=11,ha='center',va='center',color='#0F1419',weight='bold',zorder=5)
        else:
            ax.scatter([x],[y],s=140,color=col,zorder=4)
            ax.text(x,y,_tw.fill(n['label'],20),fontsize=8.3,ha='center',va='center',color='#0F1419',zorder=5,
                    bbox=dict(boxstyle='round,pad=0.35',fc=col,ec='none',alpha=.96))
    total=len(nodes)-1;rel=len(cats.get('relation',[]));ent=len(cats.get('entity',[]))
    ax.set_title('NEMO MIND  ·  %d facts  ·  %d people  ·  %d entities'%(total,rel,ent),color='white',fontsize=15,pad=16)
    ax.legend(handles=[mp.Patch(color=v,label=k) for k,v in _N35_CAT_COLOR.items() if k in cats or k=='you'],loc='lower left',fontsize=8.5,facecolor='#1B2530',edgecolor='none',labelcolor='white')
    ax.set_aspect('equal');ax.axis('off');ax.set_xlim(-lim,lim);ax.set_ylim(-lim,lim)
    fig.text(0.5,0.02,'Only facts you told me. /mindforget <thing> removes one. Generated %s'%_n35_time.strftime('%d %b %Y %H:%M'),color='#6B7B8C',fontsize=8.5,ha='center')
    out=_n35_os.path.join(_n35_os.path.dirname(_N35_DB) or '.','nemo_mind.png')
    fig.savefig(out,bbox_inches='tight',facecolor=fig.get_facecolor());plt.close(fig)
    return out,'ok'

def _n35_send_photo(cid,path,caption=''):
    try:
        import requests as _rq
        with open(path,'rb') as f:
            r=_rq.post(TG+'/sendPhoto',data={'chat_id':cid,'caption':caption[:1000]},files={'photo':f},timeout=60)
        if r.ok:return True
    except Exception:pass
    try:_send_file(cid,path,caption or 'NEMO Mind');return True
    except Exception:return False

def _n35_mind_text(cid):
    rows=_n35_facts(cid,120)
    if not rows:return 'My unified memory about you is empty so far. Tell me things like "my name is …", "remember that …", "from now on …", or "my wife\'s name is …".'
    groups={}
    for k,v,cat,src,conf,seen,upd in rows:groups.setdefault(cat,[]).append('- %s: %s'%(k.replace('_',' ').replace('current:','now · '),v))
    parts=['🧠 NEMO MIND — %d facts'%len(rows)]
    for cat in ('identity','relation','current','preference','fact'):
        if groups.get(cat):parts.append(cat.upper()+'\n'+'\n'.join(groups[cat][:25]))
    parts.append('/mind = graph image · /mindforget <thing> · /nemo35 = status')
    return '\n\n'.join(parts)

def _n35_status(cid):
    rows=_n35_facts(cid,500)
    try:
        c=_n35_conn();ep=c.execute('SELECT COUNT(*) FROM episodes WHERE chat_id=?',(str(cid),)).fetchone()[0];cor=c.execute('SELECT COUNT(*) FROM corrections WHERE chat_id=?',(str(cid),)).fetchone()[0];mig=c.execute('SELECT src,rows FROM migration').fetchall();c.close()
    except Exception:ep=cor=0;mig=[]
    return ('NEMO 35.0 — UNIFIED MIND\n━━━━━━━━━━━━━━━━━━━━\n'
            'Unified memory store: '+_N35_DB+'\nActive facts: %d · episodes: %d · corrections: %d\n'%(len(rows),ep,cor)+
            'Old memory layers re-routed here: %d functions (v20.4, v25, v26, v27, v28, v32)\n'%len(_N35_REBOUND)+
            'Migrated from old DBs: '+(', '.join('%s=%s'%(s.split('/')[-1],n) for s,n in mig) if mig else 'nothing found / not yet')+'\n'
            'Prompt memory injection: SINGLE (query-relevant, ≤1600 chars)\n'
            'Smart auto-visual: WIDENED (compare/timeline/types/structure/how-to/Hinglish)\n'
            '/mind · /mindfacts · /mindforget <thing> · /visualauto smart|on|off\n'
            'Keys, connections, trading/shell/payment authority: UNCHANGED')

# ------------------------------- smart auto-visual widened --------------------
_N35_SHOULD_VIS_PREV=_n283_should_visualize if '_n283_should_visualize' in globals() else (lambda cid,q,a:False)
_N35_VIS_RE=_n35_re.compile(
  r'(?i)\b(compare|comparison|difference between|differences?|vs\.?|versus|pros and cons|advantages?|disadvantages?|'
  r'timeline|history of|evolution of|types? of|kinds? of|categories of|classification|structure of|anatomy|components?|parts of|'
  r'explain|how to|steps to|roadmap|plan for|framework|hierarchy|relationship between|layers? of|overview of|'
  r'kaise|kya hota|kya hai|samjhao|samjha(?:o|iye)|farak|prakriya|tarika|antar|prakar)\b')
def _n283_should_visualize(cid,question,answer_text):
    try:
        if _N35_SHOULD_VIS_PREV(cid,question,answer_text):return True
    except Exception:pass
    try:mode=_n283_visual_mode(cid)
    except Exception:mode='smart'
    if mode!='smart':return False
    q=' '.join(str(question or '').split()).strip();a=str(answer_text or '');ql=q.lower()
    if not q or len(a)<320:return False
    if ql.startswith(('/','visualize ','make a diagram ','draw a diagram ')):return False
    if any(x in ql for x in ('latest news','today news','current price','stock price','live price','weather now','email','send ','download','open ','run ')):return False
    if a.startswith(('⚠️','❌','🧠 My brains are all busy')):return False
    return bool(_N35_VIS_RE.search(ql))

# ------------------------------- dispatcher -----------------------------------
def _n35_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo35','/unifiedmind','/mindstatus'):send_text(cid,_n35_status(cid));return True
    if low in ('/mind','/mindmap','/mymind'):
        try:send_text(cid,'🧠 Drawing your mind map...')
        except Exception:pass
        def _go():
            path,st=_n35_render_mind(cid)
            if path:_n35_send_photo(cid,path,'🧠 NEMO Mind — what you have taught me. /mindfacts for text, /mindforget <thing> to remove.')
            elif st=='empty':send_text(cid,_n35_mind_text(cid))
            else:send_text(cid,'Could not draw the graph ('+st+'). Text view:\n\n'+_n35_mind_text(cid))
        _n35_threading.Thread(target=_go,daemon=True,name='nemo-mind35').start();return True
    if low in ('/mindfacts','/mindtext'):send_text(cid,_n35_mind_text(cid));return True
    if low.startswith('/mindforget'):
        arg=txt[len('/mindforget'):].strip()
        if not arg:send_text(cid,'Use /mindforget <word or value>, e.g. /mindforget wife');return True
        n=_n35_forget(cid,arg);send_text(cid,'🧹 Removed %d unified-memory fact(s) matching "%s".'%(n,arg) if n else 'Nothing in unified memory matched "%s".'%arg);return True
    if low.startswith('/mindmigrate'):
        t,d=_n35_migrate();send_text(cid,'Migration run: %d facts imported. %s'%(t,_n35_json.dumps(d)));return True
    return False

_N35_PREV_HANDLE=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();chat=(msg.get('chat') or {});low=txt.lower()
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id'):
            if low.startswith(('/nemo35','/mind','/unifiedmind')):
                try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                except Exception:pass
                return
        if _n35_dispatch(msg):return
        if cid==OWNER.get('id') and txt:
            # /forget <thing> also clears the unified store, then continues to the base /forget
            if low.startswith('/forget ') and not low.startswith('/forgetme'):
                try:_n35_forget(cid,txt[8:].strip())
                except Exception:pass
            elif not txt.startswith('/'):
                # single extraction point for plain owner text (the old six are now no-ops)
                try:_n35_extract(cid,txt,'owner-text')
                except Exception:pass
    except Exception as e:
        try:_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo35_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N35_PREV_HANDLE(msg)

# ------------------------------- regression / eval ----------------------------
_PRIME_REGRESSION_V35_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V35_PREV();extra=[]
    if isinstance(r,dict):
        r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v34-version',)]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v35-version',lambda:VERSION=='35.0')
    add('v35-unified-store',lambda:_n35_set_fact('__eval35__','wife','Hetvi','eval').get('ok') is not None and _n35_get_fact('__eval35__','wife')=='Hetvi')
    add('v35-extract-hinglish',lambda:(_n35_extract('__eval35__','meri behen ka naam Priya hai','eval') or ('',))[0]=='sister')
    add('v35-extract-remember',lambda:(_n35_extract('__eval35__','remember that I take my medicine at 9pm','eval') or ('',))[0]=='remembered')
    add('v35-context-relevant',lambda:'Hetvi' in _n35_context('__eval35__','what is my wife name'))
    add('v35-context-empty-unrelated',lambda:'Hetvi' not in _n35_context('__eval35__','explain photosynthesis'))
    add('v35-relation-answer',lambda:'Hetvi' in (_n35_relation_answer('__eval35__',"what is my wife's name") or ''))
    add('v35-correction',lambda:_n35_extract('__eval35__',"no, my wife's name is Heta",'eval')[2].get('status') in ('UPDATED','NEW') and _n35_get_fact('__eval35__','wife')=='Heta')
    add('v35-question-not-fact',lambda:_n35_extract('__eval35__',"what is my wife's name",'eval') is None and _n35_extract('__eval35__','kya mera brother ka naam Rahul hai','eval') is None)
    add('v35-forget',lambda:_n35_forget('__eval35__','Heta')>=1 and not _n35_get_fact('__eval35__','wife'))
    add('v35-old-layers-rebound',lambda:len(_N35_REBOUND)>=12)
    add('v35-v32-bridge',lambda:_n32_alias_set('__eval35__','wife','Hetvi','person') and 'Hetvi' in _n32_memory_context('__eval35__','wife',5))
    add('v35-visual-compare',lambda:_n283_should_visualize(0,'compare python and javascript','x'*400))
    add('v35-visual-hinglish',lambda:_n283_should_visualize(0,'photosynthesis kaise hota hai','x'*400))
    add('v35-visual-no-action',lambda:not _n283_should_visualize(0,'email the compare report to me','x'*400))
    add('v35-visual-process-preserved',lambda:_n283_should_visualize(0,'Explain how a CBG plant works','x'*400))
    add('v35-owner-gate',lambda:callable(handle) and callable(_n35_dispatch))
    add('v35-authority-unchanged',lambda:(_v184_compile_control('x','run powershell delete all files') or {}).get('kind') not in ('shell','powershell','cmd','terminal'))
    try:_n35_forget('__eval35__','Hetvi');_n35_forget('__eval35__','Priya');_n35_forget('__eval35__','medicine')
    except Exception:pass
    if not isinstance(r,dict):
        return {'id':'RG35-'+_n35_uuid.uuid4().hex[:8].upper(),'version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_N35_EVAL_PREV=_n28_eval
def _n28_eval():
    rows=_N35_EVAL_PREV()
    rows.extend([
      {'name':'v35-unified-mind','ok':callable(_n35_set_fact) and callable(_n35_context),'detail':'one memory store, one extractor, one injection (%d old functions re-routed)'%len(_N35_REBOUND)},
      {'name':'v35-mind-graph','ok':callable(_n35_render_mind),'detail':'/mind graph image of everything you taught Nemo'},
      {'name':'v35-smart-visual','ok':_n283_should_visualize(0,'difference between RAM and ROM','x'*400),'detail':'compare/timeline/types/how-to/Hinglish explanations earn a diagram'}])
    seen=set();out=[]
    for x in reversed(rows):
        n=str(x.get('name') or '')
        if n in seen:continue
        seen.add(n);out.append(x)
    return list(reversed(out))

# ------------------------------- boot -----------------------------------------
_N35_MAIN_PREV=main
def main():
    try:_n35_threading.Thread(target=_n35_migrate,daemon=True,name='nemo-mind35-migrate').start()
    except Exception:pass
    print('NEMO 35.0 UNIFIED MIND READY — one memory store (%s), %d old memory functions re-routed, /mind graph, wider smart visuals'%(_N35_DB,len(_N35_REBOUND)))
    return _N35_MAIN_PREV()


# =============================================================================
# NEMO 36.0 — DAY CARD + DOC-TO-VISUAL + NARRATION + SELF-AUDIT (Batch 3 + 4)
#   3) /daycard — one generated image every morning (08:00 IST by default): date,
#      server health tiles, calendar, reminders, to-dos, unread mail, weather.
#      /infographic — turns the loaded document (or pasted text / last answer) into
#      a one-page visual summary. /narration on|off controls spoken visual summaries.
#   4) Boot self-audit: counts its own wrapper layers, memory DBs and regression
#      verdict, prints ONE ready line (the ~15 stacked banners are filtered), and
#      sends the owner a compact boot report. /selfaudit on demand.
#   Keys, secrets, connections, trading/shell/payment authority: UNCHANGED.
# =============================================================================
VERSION='36.0'
import time as _n36_time, os as _n36_os, re as _n36_re, json as _n36_json, threading as _n36_threading
import hashlib as _n36_hashlib, datetime as _n36_dt, textwrap as _n36_tw, builtins as _n36_builtins

_N36_IST=_n36_dt.timezone(_n36_dt.timedelta(hours=5,minutes=30))
def _n36_now():return _n36_dt.datetime.now(_N36_IST)
def _n36_out_dir():
    d=_n36_os.path.dirname(_N35_DB) if '_N35_DB' in globals() else '/root'
    return d if _n36_os.access(d,_n36_os.W_OK) else '/tmp'

def _n36_kv_get(k,d=None):
    try:v=kv_get(k,None);return d if v is None else v
    except Exception:return d
def _n36_kv_set(k,v):
    try:kv_set(k,v);return True
    except Exception:return False

# ------------------------------- data gathering --------------------------------
def _n36_sys():
    out={}
    try:
        import shutil as _sh;du=_sh.disk_usage('/');out['disk_free_gb']=du.free/1e9;out['disk_pct']=100.0*du.used/max(1,du.total)
    except Exception:pass
    try:
        mem={};
        for line in open('/proc/meminfo'):
            k,v=line.split(':',1);mem[k]=float(v.strip().split()[0])
        out['mem_pct']=100.0*(1-mem.get('MemAvailable',0)/max(1,mem.get('MemTotal',1)));out['mem_free_gb']=mem.get('MemAvailable',0)/1e6
    except Exception:pass
    try:out['load']=_n36_os.getloadavg()[0]
    except Exception:pass
    try:out['uptime_h']=(_n36_time.time()-START_TS)/3600.0
    except Exception:pass
    try:out['brain']='DOWN' if HEALTH.get('down') else 'ONLINE'
    except Exception:out['brain']='?'
    return out

def _n36_day_data(cid):
    d={'date':_n36_now().strftime('%A, %d %B %Y'),'time':_n36_now().strftime('%H:%M IST'),'sys':_n36_sys(),'calendar':[],'reminders':[],'todos':[],'mail':None,'weather':'','facts':0,'name':''}
    try:d['name']=_n35_get_fact(cid,'nickname') or _n35_get_fact(cid,'name') or ''
    except Exception:pass
    try:d['facts']=len(_n35_facts(cid,500))
    except Exception:pass
    now=_n36_time.time()
    try:
        rs=[r for r in list(REMINDERS) if str(r.get('chat'))==str(cid) and 0<=float(r.get('at',0))-now<=36*3600]
        rs.sort(key=lambda r:r.get('at',0))
        d['reminders']=[(_n36_dt.datetime.fromtimestamp(float(r['at']),_N36_IST).strftime('%a %H:%M'),str(r.get('text') or 'Reminder')[:60]) for r in rs[:6]]
    except Exception:pass
    try:d['todos']=[str(t.get('text') or '')[:60] for t in TODOS.get(cid,[]) if not t.get('done')][:7]
    except Exception:pass
    try:
        if google_ready():
            ev=gcal_upcoming(1) or []
            for e in ev[:6]:
                w=str(e.get('when') or '')
                try:
                    if 'T' in w:w=_n36_dt.datetime.fromisoformat(w.replace('Z','+00:00')).astimezone(_N36_IST).strftime('%a %H:%M')
                except Exception:pass
                d['calendar'].append((w[:12],str(e.get('title') or '')[:55]))
            um=gmail_unread(5)
            if um is not None:d['mail']={'count':len(um),'top':[(str(m.get('from') or '').split('<')[0].strip()[:24],str(m.get('subject') or '')[:48]) for m in um[:3]]}
    except Exception:pass
    try:
        city=_n35_get_fact(cid,'city') or _n35_get_fact(cid,'hometown')
        if city:
            w=' '.join(str(get_weather(city) or '').split());d['weather']=((''if w.lower().startswith(city.lower()) else city+': ')+w[:150]) if w and not w.startswith("Couldn't") else ''
    except Exception:pass
    return d

# ------------------------------- card renderer ---------------------------------
_N36_BG='#0F1419';_N36_PANEL='#1B2530';_N36_TXT='#E8EEF4';_N36_MUTE='#8FA3B8';_N36_ACC='#F4B942'
def _n36_canvas(w=10.8,h=13.5):
    import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
    fig=plt.figure(figsize=(w,h),dpi=110);fig.patch.set_facecolor(_N36_BG);ax=fig.add_axes([0,0,1,1]);ax.set_xlim(0,100);ax.set_ylim(0,100);ax.axis('off');ax.set_facecolor(_N36_BG)
    return fig,ax,plt
def _n36_panel(ax,x,y,w,h,title=None,color=_N36_PANEL):
    import matplotlib.patches as mp
    ax.add_patch(mp.FancyBboxPatch((x,y),w,h,boxstyle='round,pad=0.4,rounding_size=1.4',fc=color,ec='none'))
    if title:ax.text(x+1.6,y+h-2.3,title,fontsize=10,color=_N36_MUTE,weight='bold')
def _n36_tile(ax,x,y,w,h,label,value,sub='',color=_N36_PANEL,vcolor=_N36_TXT):
    _n36_panel(ax,x,y,w,h,None,color);ax.text(x+1.6,y+h-2.4,label,fontsize=9.5,color=_N36_MUTE,weight='bold')
    ax.text(x+1.6,y+h/2-1.4,value,fontsize=18,color=vcolor,weight='bold')
    if sub:ax.text(x+1.6,y+1.5,sub,fontsize=8.5,color=_N36_MUTE)
def _n36_lines(ax,x,y,items,maxn,empty,fs=9.6,step=2.6,width=52):
    if not items:ax.text(x,y,empty,fontsize=fs,color=_N36_MUTE,style='italic');return
    for it in items[:maxn]:
        s=('%s  %s'%it if isinstance(it,tuple) else str(it))
        ax.text(x,y,_n36_tw.shorten(s,width,placeholder='…'),fontsize=fs,color=_N36_TXT);y-=step

def _n36_render_daycard(cid):
    d=_n36_day_data(cid)
    try:fig,ax,plt=_n36_canvas()
    except Exception as e:return None,'matplotlib unavailable: '+str(e)[:80],d
    hello='Good morning' if _n36_now().hour<12 else ('Good afternoon' if _n36_now().hour<17 else 'Good evening')
    ax.text(4,95.5,hello+(', '+d['name'] if d['name'] else '')+'.',fontsize=22,color=_N36_TXT,weight='bold')
    ax.text(4,92.3,d['date']+'   ·   '+d['time'],fontsize=11.5,color=_N36_MUTE)
    s=d['sys'];warn=lambda pct,hi:'#F1948A' if pct>=hi else _N36_TXT
    _n36_tile(ax,4,80,21.5,9,'DISK','%.0f%%'%s.get('disk_pct',0) if 'disk_pct' in s else '?','%.1f GB free'%s.get('disk_free_gb',0),vcolor=warn(s.get('disk_pct',0),88))
    _n36_tile(ax,27.5,80,21.5,9,'MEMORY','%.0f%%'%s.get('mem_pct',0) if 'mem_pct' in s else '?','%.1f GB free'%s.get('mem_free_gb',0),vcolor=warn(s.get('mem_pct',0),92))
    _n36_tile(ax,51,80,21.5,9,'UPTIME','%.0fh'%s.get('uptime_h',0) if 'uptime_h' in s else '?','load %.2f'%s.get('load',0))
    m=d['mail'];_n36_tile(ax,74.5,80,21.5,9,'UNREAD MAIL',str(m['count']) if m else '—','Gmail' if m else 'Google not linked',vcolor=_N36_ACC if m and m['count'] else _N36_TXT)
    _n36_panel(ax,4,55,45,22,'CALENDAR · next 24h');_n36_lines(ax,5.8,71.5,d['calendar'],6,'No events' if google_ready() else 'Google not connected (/google)',width=46)
    _n36_panel(ax,51,55,45,22,'REMINDERS · next 36h');_n36_lines(ax,52.8,71.5,d['reminders'],6,'Nothing due',width=46)
    _n36_panel(ax,4,29,45,23,'TO-DO');_n36_lines(ax,5.8,46.5,['• '+t for t in d['todos']],7,'List is clear',width=46)
    _n36_panel(ax,51,29,45,23,'INBOX · top unread')
    if m and m['top']:_n36_lines(ax,52.8,46.5,[(f+' —',sj) for f,sj in m['top']],3,'',fs=9,step=4.2,width=50)
    else:ax.text(52.8,46.5,'No unread mail' if m else 'Link Google to see mail',fontsize=9.6,color=_N36_MUTE,style='italic')
    _n36_panel(ax,4,15,92,11,'WEATHER' if d['weather'] else 'WEATHER · tell me "I live in <city>" to enable')
    if d['weather']:
        for i,line in enumerate(_n36_tw.wrap(d['weather'],120)[:2]):ax.text(5.8,21.3-i*2.6,line,fontsize=9.6,color=_N36_TXT)
    ax.text(4,9.5,'Brain %s  ·  %d facts in unified memory  ·  /mind  ·  /daycard off to stop'%(s.get('brain','?'),d['facts']),fontsize=9,color=_N36_MUTE)
    ax.text(4,6.5,'NEMO %s · Day Card · generated %s'%(VERSION,_n36_now().strftime('%d %b %H:%M')),fontsize=8.5,color='#5B6B7C')
    out=_n36_os.path.join(_n36_out_dir(),'nemo_daycard.png');fig.savefig(out,facecolor=fig.get_facecolor());plt.close(fig)
    return out,'ok',d

def _n36_daycard_summary(d):
    bits=[]
    if d['calendar']:bits.append('%d calendar event%s'%(len(d['calendar']),'' if len(d['calendar'])==1 else 's'))
    if d['reminders']:bits.append('%d reminder%s due'%(len(d['reminders']),'' if len(d['reminders'])==1 else 's'))
    if d['todos']:bits.append('%d open to-do%s'%(len(d['todos']),'' if len(d['todos'])==1 else 's'))
    if d['mail'] and d['mail']['count']:bits.append('%d unread mail'%d['mail']['count'])
    s=d['sys'];
    if s.get('disk_pct',0)>=88:bits.append('disk is %.0f%% full'%s['disk_pct'])
    return 'Here is your day. '+(', '.join(bits) if bits else 'Nothing pressing today.')+'.'

def _n36_send_daycard(cid,speak_it=True):
    path,st,d=_n36_render_daycard(cid)
    if not path:
        send_text(cid,'Could not draw the day card ('+st+').');return False
    ok=_n35_send_photo(cid,path,'🗓 '+d['date']+' — '+_n36_daycard_summary(d))
    try:
        if ok and speak_it and _n30_profile(cid).get('visual_narration'):_n36_threading.Thread(target=speak,args=(cid,_n36_daycard_summary(d)),daemon=True).start()
    except Exception:pass
    return ok

def _n36_daycard_loop():
    while True:
        try:
            if _n36_kv_get('n36_daycard_on','1')=='1':
                oid=OWNER.get('id');now=_n36_now();target=str(_n36_kv_get('n36_daycard_time','08:00'))
                if oid and now.strftime('%H:%M')==target and _n36_kv_get('n36_daycard_last','')!=now.strftime('%Y-%m-%d'):
                    _n36_kv_set('n36_daycard_last',now.strftime('%Y-%m-%d'));_n36_send_daycard(oid)
        except Exception:pass
        _n36_time.sleep(45)

# ------------------------------- document → visual -----------------------------
def _n36_json_loose(s):
    s=str(s or '');s=_n36_re.sub(r'```(?:json)?','',s)
    i=s.find('{');j=s.rfind('}')
    if i<0 or j<=i:return None
    try:return _n36_json.loads(s[i:j+1])
    except Exception:
        try:return _n36_json.loads(_n36_re.sub(r',\s*([}\]])',r'\1',s[i:j+1]))
        except Exception:return None

def _n36_infographic_spec(text):
    prompt=('Turn the document below into a ONE-PAGE INFOGRAPHIC SPEC. Return ONLY a JSON object, no prose, no markdown fences:\n'
            '{"title":"<=60 chars","subtitle":"<=90 chars","key_points":["<=95 chars", ... 4 to 6 items],'
            '"numbers":[{"label":"<=18 chars","value":"<=12 chars"}, ... 0 to 4 REAL figures from the text only],'
            '"sections":[{"heading":"<=22 chars","line":"<=110 chars"}, ... 3 to 5 items],"takeaway":"<=160 chars"}\n'
            'Rules: use only what the document states; never invent numbers; plain English (or the document language); no emojis.\n\nDOCUMENT:\n'+str(text)[:14000])
    raw=ask_ai(OWNER.get('id'),prompt,remember=False,raw=True,timeout=120)
    spec=_n36_json_loose(raw)
    if not isinstance(spec,dict) or not spec.get('key_points'):return None
    spec['title']=str(spec.get('title') or 'Summary')[:70];spec['subtitle']=str(spec.get('subtitle') or '')[:100]
    spec['key_points']=[str(x)[:110] for x in (spec.get('key_points') or [])][:6]
    spec['numbers']=[{'label':str(n.get('label',''))[:20],'value':str(n.get('value',''))[:14]} for n in (spec.get('numbers') or []) if isinstance(n,dict)][:4]
    spec['sections']=[{'heading':str(n.get('heading',''))[:24],'line':str(n.get('line',''))[:130]} for n in (spec.get('sections') or []) if isinstance(n,dict)][:5]
    spec['takeaway']=str(spec.get('takeaway') or '')[:180]
    return spec

def _n36_render_infographic(spec,source_name=''):
    try:fig,ax,plt=_n36_canvas(10.8,14.2)
    except Exception as e:return None,'matplotlib unavailable: '+str(e)[:80]
    import matplotlib.patches as mp
    ax.add_patch(mp.Rectangle((0,89),100,11,fc=_N36_ACC,ec='none'))
    ax.text(4,94.6,_n36_tw.shorten(spec['title'],58,placeholder='…'),fontsize=20,color=_N36_BG,weight='bold')
    if spec['subtitle']:ax.text(4,91.2,_n36_tw.shorten(spec['subtitle'],95,placeholder='…'),fontsize=10.5,color=_N36_BG)
    y=86.5
    if spec['numbers']:
        n=len(spec['numbers']);w=(92-(n-1)*2)/n
        for i,num in enumerate(spec['numbers']):
            x=4+i*(w+2);_n36_panel(ax,x,y-9,w,9);ax.text(x+w/2,y-3.2,num['value'],fontsize=17,color=_N36_ACC,weight='bold',ha='center');ax.text(x+w/2,y-7.4,num['label'],fontsize=8.5,color=_N36_MUTE,ha='center')
        y-=12.5
    kp=spec['key_points'];h=3.4*len(kp)+5;_n36_panel(ax,4,y-h,92,h,'KEY POINTS');yy=y-5.4
    for p in kp:
        for k,line in enumerate(_n36_tw.wrap(p,100)[:2]):ax.text(5.8 if k==0 else 8.2,yy,('•  ' if k==0 else '')+line,fontsize=9.8,color=_N36_TXT);yy-=2.55
        yy-=0.85
    y=y-h-2.5
    secs=spec['sections']
    if secs:
        cols=min(len(secs),3);rows=(len(secs)+cols-1)//cols;cw=(92-(cols-1)*2)/cols;ch=9.5
        for i,s in enumerate(secs):
            r,c=divmod(i,cols);x=4+c*(cw+2);yy=y-(r+1)*(ch+1.5)+1.5
            _n36_panel(ax,x,yy,cw,ch);ax.text(x+1.6,yy+ch-2.6,s['heading'].upper(),fontsize=9,color=_N36_ACC,weight='bold')
            for k,line in enumerate(_n36_tw.wrap(s['line'],int(cw*1.25))[:3]):ax.text(x+1.6,yy+ch-5.2-k*2.1,line,fontsize=8.3,color=_N36_TXT)
        y=y-rows*(ch+1.5)-1
    if spec['takeaway']:
        _n36_panel(ax,4,max(6,y-9.5),92,8.5,'TAKEAWAY',color='#243447')
        for k,line in enumerate(_n36_tw.wrap(spec['takeaway'],105)[:2]):ax.text(5.8,max(6,y-9.5)+4.4-k*2.4,line,fontsize=9.8,color=_N36_TXT)
    bottom=max(0.0,(y-11.5 if spec['takeaway'] else y)-4.5)
    ax.text(4,bottom+1.4,('Source: '+source_name[:60]+'  ·  ' if source_name else '')+'NEMO %s · summary of the document, not new facts'%VERSION,fontsize=8,color='#5B6B7C')
    ax.set_ylim(bottom,100);fig.set_size_inches(10.8,max(6.0,14.2*(100-bottom)/100.0))
    out=_n36_os.path.join(_n36_out_dir(),'nemo_infographic.png');fig.savefig(out,facecolor=fig.get_facecolor());plt.close(fig)
    return out,'ok'

def _n36_infographic(cid,arg=''):
    src=arg.strip();name=''
    if len(src)<80:
        doc=DOCS.get(cid) if isinstance(DOCS,dict) else None
        if doc and doc.get('text'):src=doc['text'];name=str(doc.get('name') or '')
        elif LASTREPLY.get(cid):src=str(LASTREPLY.get(cid));name='my last answer'
    if len(src)<80:
        send_text(cid,'Send me a document (PDF/Word/text) or paste the text after /infographic, and I will turn it into a one-page visual.');return False
    try:send_text(cid,'🖼 Reading and laying out the infographic...')
    except Exception:pass
    def _go():
        spec=_n36_infographic_spec(src)
        if not spec:send_text(cid,'I could not extract a clean structure from that text right now. Try again or use /summary.');return
        path,st=_n36_render_infographic(spec,name)
        if not path:send_text(cid,'Could not draw the infographic ('+st+').');return
        cap='🖼 '+spec['title']+(' — '+spec['takeaway'] if spec['takeaway'] else '')
        _n35_send_photo(cid,path,cap[:1000])
        try:
            if _n30_profile(cid).get('visual_narration'):_n36_threading.Thread(target=speak,args=(cid,(spec['title']+'. '+spec['takeaway'])[:400]),daemon=True).start()
        except Exception:pass
    _n36_threading.Thread(target=_go,daemon=True,name='nemo-infographic36').start();return True

_N36_INFO_RE=_n36_re.compile(r'(?i)^\s*(?:nemo[,\s]*)?(?:make|create|build|draw|give me|show me)?\s*(?:an?\s+)?(?:infographic|visual summary|one[- ]page visual|visual of (?:this|the) (?:document|file|pdf|doc))\b')

# ------------------------------- self audit ------------------------------------
_N36_AUDIT={'regression':None}
def _n36_self_audit(run_regression=False):
    a={'version':VERSION,'file':'','size_kb':0,'lines':0,'sha':'','handle_layers':0,'ask_ai_layers':0,'main_layers':0,'version_assignments':0,'memory_dbs':[],'unified_facts':0,'rebound':len(globals().get('_N35_REBOUND',[])),'baked_keys_in_source':0}
    try:
        p=_n36_os.path.abspath(__file__);a['file']=p;src=open(p,'r',encoding='utf-8',errors='ignore').read()
        a['size_kb']=len(src)//1024;a['lines']=src.count('\n');a['sha']=_n36_hashlib.sha256(src.encode('utf-8','ignore')).hexdigest()[:16]
        a['handle_layers']=len(_n36_re.findall(r'(?m)^def handle\(',src));a['ask_ai_layers']=len(_n36_re.findall(r'(?m)^def ask_ai\(',src))
        a['main_layers']=len(_n36_re.findall(r'(?m)^def main\(',src));a['version_assignments']=len(_n36_re.findall(r'(?m)^VERSION\s*=',src))
        a['baked_keys_in_source']=sum(1 for m in _n36_re.finditer(r'(?m)^_BAKED_[A-Z_]+\s*=\s*["\']([^"\']*)["\']',src) if len(m.group(1))>10)
    except Exception:pass
    try:a['memory_dbs']=sorted(f for f in _n36_os.listdir('/root') if f.startswith('nemo') and f.endswith('.db'))
    except Exception:pass
    try:a['unified_facts']=len(_n35_facts(OWNER.get('id'),2000))
    except Exception:pass
    if run_regression:
        try:r=prime_regression_suite();_N36_AUDIT['regression']={'verdict':r.get('verdict'),'passed':r.get('passed'),'failed':r.get('failed'),'failed_names':[t.get('name') for t in r.get('tests',[]) if not t.get('ok')][:8]}
        except Exception as e:_N36_AUDIT['regression']={'verdict':'ERROR','detail':str(e)[:120]}
    a['regression']=_N36_AUDIT['regression'];return a

def _n36_audit_text(a):
    reg=a.get('regression') or {}
    return ('🔍 NEMO SELF-AUDIT — v'+a['version']+'\n━━━━━━━━━━━━━━━━━━━━\n'
            'Source: %d lines · %d KB · sha %s\n'%(a['lines'],a['size_kb'],a['sha'])+
            'Wrapper layers: handle=%d · ask_ai=%d · main=%d · VERSION lines=%d\n'%(a['handle_layers'],a['ask_ai_layers'],a['main_layers'],a['version_assignments'])+
            'Memory: unified facts=%d · old memory functions re-routed=%d · nemo*.db files=%d\n'%(a['unified_facts'],a['rebound'],len(a['memory_dbs']))+
            'Embedded credential values found: %d (external key loading is reported by /security)\n'%a['baked_keys_in_source']+
            ('Regression: %s (%s passed, %s failed%s)\n'%(reg.get('verdict'),reg.get('passed'),reg.get('failed'),(' → '+', '.join(reg.get('failed_names') or [])) if reg.get('failed') else '') if reg else 'Regression: not run yet (/selfaudit full)\n')+
            'Verdict: '+('⚠️ layer stack is heavy — next consolidation phase recommended' if a['ask_ai_layers']>12 else '✅ healthy'))

def _n36_boot_report():
    try:
        _n36_time.sleep(30);a=_n36_self_audit(run_regression=True);oid=OWNER.get('id')
        if oid:send_text(oid,'🚀 NEMO v%s booted.\n\n'%VERSION+_n36_audit_text(a)+'\n\n/daycard now · /mind · /infographic · /nemo36')
    except Exception:pass

# ------------------------------- status / dispatcher ---------------------------
def _n36_status(cid):
    on=_n36_kv_get('n36_daycard_on','1')=='1';t=_n36_kv_get('n36_daycard_time','08:00');last=_n36_kv_get('n36_daycard_last','never')
    try:narr=_n30_profile(cid).get('visual_narration')
    except Exception:narr=None
    return ('NEMO 36.0 — DAY CARD + DOC-TO-VISUAL + SELF-AUDIT\n━━━━━━━━━━━━━━━━━━━━\n'
            'Day card: %s at %s IST (last sent %s)\n'%('ON' if on else 'OFF',t,last)+
            'Document → infographic: ACTIVE (/infographic, or send a file then say "infographic")\n'
            'Voice narration of visuals: %s\n'%('ON' if narr else 'OFF')+
            'Boot self-audit + single READY line: ACTIVE\n'
            'Unified memory (v35): %d facts · /mind\n'%len(_n35_facts(cid,500))+
            '/daycard now|on|off|time HH:MM · /infographic [text] · /narration on|off · /selfaudit [full] · /nemo36\n'
            'Keys, connections, trading/shell/payment authority: UNCHANGED')

def _n36_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo36','/batch34status'):send_text(cid,_n36_status(cid));return True
    if low.startswith('/daycard'):
        arg=low[len('/daycard'):].strip()
        if arg in ('','now'):
            send_text(cid,'🗓 Building your day card...');_n36_threading.Thread(target=_n36_send_daycard,args=(cid,),daemon=True).start();return True
        if arg in ('on','off'):_n36_kv_set('n36_daycard_on','1' if arg=='on' else '0');send_text(cid,'🗓 Daily day card '+arg.upper()+('. It arrives at %s IST.'%_n36_kv_get('n36_daycard_time','08:00') if arg=='on' else '.'));return True
        m=_n36_re.match(r'time\s+(\d{1,2}):(\d{2})$',arg)
        if m and 0<=int(m.group(1))<24 and 0<=int(m.group(2))<60:
            t='%02d:%s'%(int(m.group(1)),m.group(2));_n36_kv_set('n36_daycard_time',t);_n36_kv_set('n36_daycard_on','1');send_text(cid,'🗓 Day card time set to '+t+' IST.');return True
        send_text(cid,'Use /daycard now | on | off | time HH:MM');return True
    if low.startswith('/infographic'):_n36_infographic(cid,txt[len('/infographic'):]);return True
    if _N36_INFO_RE.match(txt):_n36_infographic(cid,'');return True
    if low.startswith('/narration'):
        arg=low[len('/narration'):].strip()
        if arg in ('on','off'):
            ok=_n30_profile_set(cid,visual_narration=(arg=='on'));send_text(cid,('🔊 ' if arg=='on' else '🔇 ')+('Spoken summaries of visuals '+arg.upper()+'.' if ok else 'Could not save.'));return True
        send_text(cid,'Spoken visual summaries are '+('ON' if _n30_profile(cid).get('visual_narration') else 'OFF')+'. Use /narration on | off');return True
    if low.startswith('/selfaudit'):
        full='full' in low
        if full:send_text(cid,'🔍 Running the full regression suite, this can take a minute...')
        def _go():send_text(cid,_n36_audit_text(_n36_self_audit(run_regression=full)))
        _n36_threading.Thread(target=_go,daemon=True).start();return True
    return False

_N36_PREV_HANDLE=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();chat=(msg.get('chat') or {});low=txt.lower()
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id'):
            if low.startswith(('/nemo36','/daycard','/infographic','/narration','/selfaudit')):
                try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                except Exception:pass
                return
        if _n36_dispatch(msg):return
    except Exception as e:
        try:_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo36_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N36_PREV_HANDLE(msg)

# ------------------------------- regression / eval ----------------------------
_PRIME_REGRESSION_V36_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V36_PREV();extra=[]
    if isinstance(r,dict):r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v35-version',)]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v36-version',lambda:VERSION=='36.0')
    add('v36-daycard-data',lambda:isinstance(_n36_day_data(OWNER.get('id')).get('sys'),dict))
    add('v36-daycard-render',lambda:_n36_render_daycard(OWNER.get('id'))[1]=='ok')
    add('v36-json-loose',lambda:(_n36_json_loose('```json\n{"a":1,}\n```') or {}).get('a')==1)
    add('v36-infographic-render',lambda:_n36_render_infographic({'title':'T','subtitle':'S','key_points':['one','two','three'],'numbers':[{'label':'L','value':'42'}],'sections':[{'heading':'H','line':'x'}],'takeaway':'done'},'eval')[1]=='ok')
    add('v36-infographic-nl',lambda:bool(_N36_INFO_RE.match('make an infographic of this document')) and not _N36_INFO_RE.match('what is an infographic'))
    add('v36-self-audit',lambda:_n36_self_audit(False)['ask_ai_layers']>=1)
    add('v36-owner-gate',lambda:callable(handle) and callable(_n36_dispatch))
    add('v36-authority-unchanged',lambda:(_v184_compile_control('x','run powershell delete all files') or {}).get('kind') not in ('shell','powershell','cmd','terminal'))
    if not isinstance(r,dict):
        return {'id':'RG36','version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_N36_EVAL_PREV=_n28_eval
def _n28_eval():
    rows=_N36_EVAL_PREV()
    rows.extend([
      {'name':'v36-daycard','ok':callable(_n36_render_daycard),'detail':'one morning image: health, calendar, reminders, to-dos, mail, weather'},
      {'name':'v36-doc-visual','ok':callable(_n36_infographic),'detail':'document → one-page infographic'},
      {'name':'v36-self-audit','ok':callable(_n36_self_audit),'detail':'boot audit of wrapper layers, memory DBs, regression; single READY line'}])
    seen=set();out=[]
    for x in reversed(rows):
        n=str(x.get('name') or '')
        if n in seen:continue
        seen.add(n);out.append(x)
    return list(reversed(out))

# ------------------------------- boot: one READY line ---------------------------
_N36_BANNER_RE=_n36_re.compile(r'^\s*NEMO\b.*\b(READY|ACTIVE)\b',_n36_re.I)
_N36_REAL_PRINT=_n36_builtins.print
_N36_SWALLOWED=[]
def _n36_quiet_print(*args,**kw):
    try:
        s=' '.join(str(a) for a in args)
        if _N36_BANNER_RE.match(s) and 'UNIFIED READY' not in s:
            _N36_SWALLOWED.append(s[:80]);return
    except Exception:pass
    return _N36_REAL_PRINT(*args,**kw)

_N36_MAIN_PREV=main
def main():
    _n36_builtins.print=_n36_quiet_print
    a=_n36_self_audit(False)
    _N36_REAL_PRINT('NEMO v%s UNIFIED READY — %d lines · handle×%d ask_ai×%d layers · unified memory %d facts · day card %s @ %s IST · stacked boot banners folded into this line'%(
        VERSION,a['lines'],a['handle_layers'],a['ask_ai_layers'],a['unified_facts'],'ON' if _n36_kv_get('n36_daycard_on','1')=='1' else 'OFF',_n36_kv_get('n36_daycard_time','08:00')))
    try:_n36_threading.Thread(target=_n36_daycard_loop,daemon=True,name='nemo-daycard36').start()
    except Exception:pass
    try:_n36_threading.Thread(target=_n36_boot_report,daemon=True,name='nemo-bootreport36').start()
    except Exception:pass
    return _N36_MAIN_PREV()


# =============================================================================
# NEMO 36.1 — EMAIL ROUTE FIRST + FUNCTION-CALL LEAK GUARD 2.0 (hotfix)
#   Seen live: "EMAIL HELLO LOVE TO <address>" reached the brain instead of the
#   v11.14 deterministic email route, and the brain printed
#   "<dots_function_call> [send_email(recipient=..., subject=..., body=...)]" as
#   chat text. Nothing was sent.
#   Fix 1: an OUTERMOST email route — any owner message that names an address and
#          says email/mail (and is not a report/pdf request) goes straight to the
#          real send path (nl_emailto) before any other layer can touch it.
#   Fix 2: the final send_text is guarded — if an outgoing reply is a leaked
#          function call in ANY format (<dots_function_call>, <function_call>,
#          <tool_call>, bare send_email(...)), NEMO executes it when it is a
#          recognisable email and reports the REAL result; otherwise the markup is
#          stripped and an honest fallback is shown. Internal syntax never reaches you.
#   Keys, connections, trading/shell/payment authority: UNCHANGED.
# =============================================================================
VERSION='36.1'
import re as _n361_re, threading as _n361_threading

# widen the base leak detector too (looked up by name inside _tool_leak)
try:
    _TOOL_RE=_n361_re.compile(_TOOL_RE.pattern+r"|<dots_function_call|</dots_function_call|<function_call|</function_call|<tool_code|\[\s*send_email\s*\(|\bsend_email\s*\(\s*(?:recipient|to)\s*=",_n361_re.I)
except Exception:pass

_N361_EMAIL_CMD_RE=_n361_re.compile(
  r"(?i)^\s*(?:hey\s+|ok\s+|please\s+|pls\s+|can you\s+|could you\s+|would you\s+|nemo[ ,]+)*"
  r"(?:send\s+(?:an?\s+|out\s+)?(?:e-?mail|mail)|e-?mail|mail|drop\s+(?:an?\s+)?(?:e-?mail|mail)|shoot\s+(?:an?\s+)?(?:e-?mail|mail))\b")
_N361_ADDR_RE=_n361_re.compile(r"[\w.+-]+@[\w-]+\.[\w.-]+")
_N361_NOT_PLAIN_RE=_n361_re.compile(r"(?i)\b(report|pdf|slides?|deck|presentation|invoice|attach|spreadsheet|excel|docx|word doc|chart|pine)\b")

def _n361_is_plain_email_order(text):
    t=str(text or '').strip()
    return bool(t and not t.startswith('/') and _N361_EMAIL_CMD_RE.match(t) and _N361_ADDR_RE.search(t) and not _N361_NOT_PLAIN_RE.search(t))

# ------------------------------ leak parsing ------------------------------------
_N361_LEAK_RE=_n361_re.compile(r"(?is)(<dots_function_call>|<function_call>|<tool_call>|<tool_code>|<function\s*=|\[\s*[a-z_]+\s*\((?:recipient|to|subject|body|query|path)\s*=)")
_N361_SEND_RE=_n361_re.compile(r"(?is)send_email\s*\((.*?)\)\s*\]?\s*(?:</[a-z_]+>)?\s*$|send_email\s*\((.*)\)")
def _n361_parse_kwargs(s):
    out={}
    for m in _n361_re.finditer(r"""(\w+)\s*=\s*(?:'((?:[^'\\]|\\.)*)'|"((?:[^"\\]|\\.)*)")""",s or ''):
        out[m.group(1).lower()]=(m.group(2) if m.group(2) is not None else m.group(3) or '').replace("\\'","'").replace('\\"','"').replace('\\n','\n')
    return out

def _n361_leaked_email(text):
    """Return {'to','subject','body'} if the text is a leaked send_email call, else None."""
    if not text or 'send_email' not in text:return None
    m=_N361_SEND_RE.search(text)
    if not m:return None
    kw=_n361_parse_kwargs(m.group(1) or m.group(2) or '')
    to=kw.get('recipient') or kw.get('to') or kw.get('email') or ''
    if not _N361_ADDR_RE.search(to):return None
    return {'to':_N361_ADDR_RE.search(to).group(0),'subject':(kw.get('subject') or 'Message from Nemo')[:200],'body':(kw.get('body') or kw.get('message') or kw.get('text') or '')[:8000]}

def _n361_strip(text):
    t=_n361_re.sub(r"(?is)</?(?:dots_function_call|function_call|tool_call|tool_code|invoke|parameter|function)[^>]*>",' ',str(text or ''))
    t=_n361_re.sub(r"(?is)\[\s*[a-z_]+\s*\(.*?\)\s*\]",' ',t)
    return ' '.join(t.split()).strip()

def _n361_handle_leak(chat_id,text):
    """Execute a leaked email call for the owner; otherwise return a clean fallback string."""
    if chat_id!=OWNER.get('id'):return 'I hit an internal formatting glitch on that reply. Please ask again.'
    em=_n361_leaked_email(text)
    if em:
        try:
            if not (google_ready() or (BOT_EMAIL and BOT_EMAIL_PASS)):
                return "I tried to email "+em['to']+" but my email isn't connected. Run /google (recommended) or /email set, then ask again."
        except Exception:pass
        try:ok=send_email(em['to'],em['subject'],em['body'] or em['subject'])
        except Exception as e:ok=False;globals()['LAST_EMAIL_ERR']=type(e).__name__+': '+str(e)[:160]
        if ok:return '📧 Sent to '+em['to']+'\nSubject: '+em['subject']+'\n\n'+(em['body'][:600] or em['subject'])+'\n\n(caught a leaked tool call and executed it for real — receipt above)'
        return '⚠️ I tried to email '+em['to']+' but the send FAILED: '+str(globals().get('LAST_EMAIL_ERR') or 'unknown error')+'\nYour draft: '+(em['body'][:400] or em['subject'])
    clean=_n361_strip(text)
    return clean if len(clean)>=12 else 'I started to call a tool instead of answering. Tell me exactly what you want done (e.g. "email <address> <message>") and I will do it directly.'

# ------------------------------ outermost guards --------------------------------
_N361_SEND_PREV=send_text
def send_text(chat_id,text,kb=None):
    try:
        s=str(text or '')
        if s and _N361_LEAK_RE.search(s) and 'caught a leaked tool call' not in s:
            try:_n210_log_fail(chat_id,'nemo361_tool_leak','',s[:300])
            except Exception:pass
            s=_n361_handle_leak(chat_id,s)
            return _N361_SEND_PREV(chat_id,s,kb)
    except Exception:pass
    return _N361_SEND_PREV(chat_id,text,kb)

_N361_PREV_HANDLE=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip()
        if cid==OWNER.get('id') and _n361_is_plain_email_order(txt):
            _n361_threading.Thread(target=nl_emailto,args=(cid,txt,txt),daemon=True,name='nemo-email361').start()
            return
        if cid==OWNER.get('id') and txt.lower() in ('/nemo361','/emailroute'):
            send_text(cid,'NEMO 36.1 — EMAIL ROUTE FIRST + LEAK GUARD 2.0\nPlain "email/mail <message> <address>" → real send path BEFORE any other layer: ACTIVE\nLeaked tool-call formats caught at delivery (dots/function_call/tool_call/bare send_email): ACTIVE\nRecognised leaked email calls are executed and receipted; others are stripped honestly.\nLast email error: '+(str(globals().get('LAST_EMAIL_ERR') or 'none')));return
    except Exception as e:
        try:_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo361_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N361_PREV_HANDLE(msg)

_PRIME_REGRESSION_V361_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V361_PREV();extra=[]
    if isinstance(r,dict):r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v36-version',)]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v361-version',lambda:VERSION=='36.1')
    add('v361-email-order-upper',lambda:_n361_is_plain_email_order('EMAIL HELLO LOVE TO PARIKHHONEY2005@GMAIL.COM'))
    add('v361-email-order-addr-first',lambda:_n361_is_plain_email_order('email someone@x.com happy birthday'))
    add('v361-email-order-report-excluded',lambda:not _n361_is_plain_email_order('email the pdf report to someone@x.com'))
    add('v361-email-order-no-addr-excluded',lambda:not _n361_is_plain_email_order('email hello to my wife'))
    add('v361-leak-detect-dots',lambda:bool(_N361_LEAK_RE.search("<dots_function_call>\n [send_email(recipient='a@b.com', subject='Hi', body='X')]")))
    add('v361-leak-parse',lambda:(_n361_leaked_email("<dots_function_call> [send_email(recipient='parikhhoney2005@gmail.com', subject='Hello Love', body='HELLO LOVE')]") or {}).get('subject')=='Hello Love')
    add('v361-leak-strip',lambda:_n361_strip('<function_call>[foo(x=1)]</function_call> real words here')=='real words here')
    add('v361-normal-text-untouched',lambda:not _N361_LEAK_RE.search('Send an email to your team about the Q3 report.'))
    add('v361-owner-gate',lambda:callable(handle) and callable(_n361_handle_leak))
    if not isinstance(r,dict):
        return {'id':'RG361','version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r


# =============================================================================
# NEMO 37.0 — PHOTO MEMORY + VOICE SESSION (ideas 3 + 4 in one)
#   PHOTO MEMORY: every image the owner sends is (a) answered as before and
#     (b) filed: a vision pass extracts kind / title / summary / names / phones /
#     emails / amounts / dates into a searchable ledger (nemo_memory.db: photos),
#     the image is kept under /root/nemo_photos, and durable facts (a plumber's
#     number on a visiting card, a bill amount) flow into unified memory with the
#     photo as source. "what was the plumber's number from that card" now works.
#     /photos [query] · /photo <id> · /photoforget <id> · /photomemory on|off
#   VOICE SESSION: /talk (or "let's talk") opens a live conversation: every voice
#     note or text gets a SHORT spoken reply in the same language, context kept,
#     memory learned, auto-closes after 10 idle minutes or "bye nemo" / /talk off.
#   Also fixes: speak() no longer re-forces the female voice on every utterance,
#     so /voice choices finally stick.
#   Keys, connections, trading/shell/payment authority: UNCHANGED.
# =============================================================================
VERSION='37.0'
import re as _n37_re, time as _n37_time, os as _n37_os, json as _n37_json, threading as _n37_threading, hashlib as _n37_hashlib, base64 as _n37_b64

_N37_LOCK=_n37_threading.RLock()
_N37_PHOTO_DIR=_n37_os.path.join(_n36_out_dir() if '_n36_out_dir' in globals() else '/root','nemo_photos')
try:_n37_os.makedirs(_N37_PHOTO_DIR,exist_ok=True)
except Exception:pass

def _n37_init():
    c=_n35_conn()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS photos(
      id TEXT PRIMARY KEY, chat_id TEXT, ts REAL, kind TEXT, title TEXT, summary TEXT,
      entities TEXT, tokens TEXT, sha TEXT, path TEXT, caption TEXT, active INTEGER DEFAULT 1
    );
    CREATE INDEX IF NOT EXISTS idx_n37_photos ON photos(chat_id,active,ts DESC);
    """)
    c.commit();c.close()
try:_n37_init()
except Exception:pass

# ------------------------------- voice-choice fix ------------------------------
if '_n30_apply_girl_voice' in globals():
    _N37_GIRL_PREV=_n30_apply_girl_voice
    def _n30_apply_girl_voice(force=True):
        # v37: never override a voice the owner chose; only fill empty defaults.
        return _N37_GIRL_PREV(False)

# ------------------------------- photo memory ----------------------------------
_N37_PHOTO_PROMPT=('You are filing this image into a personal photo memory. Return ONLY a JSON object, no prose, no markdown fences:\n'
  '{"kind":"bill|receipt|visiting_card|id_document|prescription|whiteboard|notes|screenshot|document|product|place|person|scene|other",'
  '"title":"<=60 chars, what this is (e.g. Sharma Plumbing visiting card, Amazon invoice 12 Aug)",'
  '"summary":"<=300 chars of the useful content (names, what it is about, key lines)",'
  '"names":["people or business names"],"phones":["digits as written"],"emails":[],"amounts":["with currency if shown"],"dates":[],"addresses":[],'
  '"remember":[{"key":"<=40 chars, e.g. plumber_phone or sharma_plumbing_phone","value":"<=120 chars"}]}\n'
  'Rules: only what is visibly in the image; empty lists when nothing; "remember" holds at most 4 facts a person would want to recall later; never invent.')

def _n37_tokens(s):return {w for w in _n37_re.findall(r'[a-z0-9@+]+',str(s or '').lower()) if len(w)>2}

def _n37_file_photo(cid,b64,caption=''):
    """Background: vision → ledger row → unified facts. Silent on failure."""
    try:
        if _n36_kv_get('n37_photomemory','1')!='1':return None
    except Exception:pass
    try:raw=_n37_b64.b64decode(b64)
    except Exception:return None
    sha=_n37_hashlib.sha256(raw).hexdigest()[:16]
    try:
        c=_n35_conn();dup=c.execute('SELECT id,title FROM photos WHERE chat_id=? AND sha=? AND active=1',(str(cid),sha)).fetchone();c.close()
        if dup:
            try:send_text(cid,'📸 Already in photo memory as #%s (%s).'%(dup[0],dup[1]))
            except Exception:pass
            return dup[0]
    except Exception:pass
    try:raw_ans=ask_ai(cid,_N37_PHOTO_PROMPT+(('\nUser caption: '+caption[:300]) if caption else ''),image_b64=b64,remember=False,raw=True,timeout=120)
    except Exception:raw_ans=''
    spec=_n36_json_loose(raw_ans) if '_n36_json_loose' in globals() else None
    if not isinstance(spec,dict):return None
    kind=str(spec.get('kind') or 'other')[:24];title=str(spec.get('title') or 'Photo')[:80];summary=str(spec.get('summary') or '')[:400]
    ents={k:[str(x)[:120] for x in (spec.get(k) or []) if x][:8] for k in ('names','phones','emails','amounts','dates','addresses')}
    pid='P'+_n37_time.strftime('%y%m%d')+sha[:4].upper()
    path=_n37_os.path.join(_N37_PHOTO_DIR,pid+'.jpg')
    try:
        with open(path,'wb') as f:f.write(raw)
    except Exception:path=''
    toks=' '.join(sorted(_n37_tokens(title+' '+summary+' '+caption+' '+' '.join(sum(ents.values(),[]))+' '+kind)))
    try:
        with _N37_LOCK:
            c=_n35_conn()
            c.execute('INSERT OR REPLACE INTO photos(id,chat_id,ts,kind,title,summary,entities,tokens,sha,path,caption,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,1)',
                      (pid,str(cid),_n37_time.time(),kind,title,summary,_n37_json.dumps(ents,ensure_ascii=False),toks,sha,path,caption[:300]))
            c.commit();c.close()
    except Exception:return None
    learned=[]
    for item in (spec.get('remember') or [])[:4]:
        try:
            k=str(item.get('key') or '').strip();v=str(item.get('value') or '').strip()
            if k and v and _n35_set_fact(cid,k,v,'photo:'+pid,.9).get('ok'):learned.append(k.replace('_',' ')+' = '+v)
        except Exception:pass
    try:
        send_text(cid,'📸 Filed in photo memory as #%s — %s · %s'%(pid,kind.replace('_',' '),title)+(('\nRemembered: '+'; '.join(learned)) if learned else '')+'\n/photos <word> finds it later · /photoforget %s removes it'%pid)
    except Exception:pass
    return pid

def _n37_photo_search(cid,query,limit=5):
    q=_n37_tokens(query)
    try:
        c=_n35_conn();rows=c.execute('SELECT id,ts,kind,title,summary,entities,tokens,path FROM photos WHERE chat_id=? AND active=1 ORDER BY ts DESC LIMIT 400',(str(cid),)).fetchall();c.close()
    except Exception:rows=[]
    out=[]
    for r in rows:
        sc=len(q & set((r[6] or '').split()))*3
        if not q:sc=1
        for w in q:
            if w in (r[3] or '').lower():sc+=4
        if sc>0:out.append((sc,r))
    out.sort(key=lambda x:(-x[0],-x[1][1]))
    return [r for sc,r in out[:limit]]

def _n37_photo_line(r):
    ents={}
    try:ents=_n37_json.loads(r[5] or '{}')
    except Exception:pass
    bits=[]
    for k in ('phones','emails','amounts','dates'):
        if ents.get(k):bits.append(k[:-1]+': '+', '.join(ents[k][:3]))
    return '#%s · %s · %s\n   %s%s'%(r[0],_n37_time.strftime('%d %b %y',_n37_time.localtime(r[1])),r[3],(r[4] or '')[:160],('\n   '+' | '.join(bits)) if bits else '')

def _n37_photo_context(cid,query):
    """Photo ledger hits for the single memory injection (only when the query touches a photo)."""
    q=_n37_tokens(query)
    if not q or not (q & {'photo','card','bill','receipt','invoice','number','phone','contact','address','amount','paid','prescription','whiteboard','screenshot','picture','image','pic','wala','wali','uska','that'} or len(q)>=2):return ''
    hits=_n37_photo_search(cid,query,3)
    hits=[r for r in hits if len(q & set((r[6] or '').split()))>=1]
    if not hits:return ''
    return 'PHOTO MEMORY (from images the owner sent; cite the photo id):\n'+'\n'.join('- #%s %s: %s %s'%(r[0],r[3],(r[4] or '')[:200],(r[5] or '')[:200]) for r in hits)

if '_n35_context' in globals():
    _N37_CTX_PREV=_n35_context
    def _n35_context(cid,query,limit=8,budget=1600):
        base=_N37_CTX_PREV(cid,query,limit,budget)
        try:pc=_n37_photo_context(cid,query)
        except Exception:pc=''
        return (base+('\n\n'+pc if pc else '')).strip()

_N37_IMG_PREV=_handle_image_bytes
def _handle_image_bytes(chat_id,raw,caption='',name='image',declared_mime=''):
    res=_N37_IMG_PREV(chat_id,raw,caption=caption,name=name,declared_mime=declared_mime)
    try:
        if chat_id==OWNER.get('id') and raw and len(raw)<12*1024*1024:
            b64=_n37_b64.b64encode(raw).decode()
            _n37_threading.Thread(target=_n37_file_photo,args=(chat_id,b64,caption or ''),daemon=True,name='nemo-photomem37').start()
    except Exception:pass
    return res

# ------------------------------- voice session ---------------------------------
_N37_TALK={}   # cid -> {'until':ts,'turns':n,'lang':''}
_N37_TALK_IDLE=600
_N37_TALK_START_RE=_n37_re.compile(r"(?i)^\s*(?:nemo[,\s]*)?(?:let'?s talk|talk to me|voice (?:mode|chat|session) on|start (?:a )?(?:voice )?(?:conversation|chat|talk)|baat karo|baat karte hain|bolo nemo)\b")
_N37_TALK_STOP_RE=_n37_re.compile(r"(?i)^\s*(?:ok(?:ay)?[,\s]*)?(?:bye(?: nemo)?|stop talking|end (?:the )?(?:voice )?(?:session|conversation|chat)|voice (?:mode|chat|session) off|that'?s all|chup ho jao|bas nemo|bye bye)\s*[.!]*\s*$")

def _n37_talk_on(cid):
    with _N37_LOCK:s=_N37_TALK.get(cid);return bool(s and s['until']>_n37_time.time())
def _n37_talk_start(cid):
    with _N37_LOCK:_N37_TALK[cid]={'until':_n37_time.time()+_N37_TALK_IDLE,'turns':0}
def _n37_talk_touch(cid):
    with _N37_LOCK:
        s=_N37_TALK.get(cid)
        if s:s['until']=_n37_time.time()+_N37_TALK_IDLE;s['turns']+=1
def _n37_talk_stop(cid):
    with _N37_LOCK:return _N37_TALK.pop(cid,None)

_N37_TALK_CONTRACT=('LIVE VOICE CONVERSATION. You are speaking out loud with the owner. Reply in 1-3 short natural spoken sentences '
  '(max ~45 words), same language/mix the owner used (Hindi, Hinglish or English), no lists, no markdown, no emojis, no headings, '
  'no URLs. If a real action is needed (email, reminder, search), say what you will do in one sentence and do not pretend it is done. '
  'Ask at most one short follow-up question when genuinely needed.')

_N37_ACTION_FALLBACK_RE=_n37_re.compile(r"(?i)\b(remind|reminder|email|mail|send|search|find|look up|open|play|set|call|schedule|add|note|remember|forget|download|timer|alarm|todo|to-do|yaad|bhejo|dhundo|khol)\b")
def _n37_is_action(t):
    try:
        if '_N282_ACTION_RE' in globals() and _N282_ACTION_RE.search(t):return True
    except Exception:pass
    return bool(_N37_ACTION_FALLBACK_RE.search(t))

def _n37_talk_turn(cid,said,source='voice'):
    _n37_talk_touch(cid)
    try:_n35_extract(cid,said,'talk-'+source)
    except Exception:pass
    try:_n35_episode(cid,'user',said,'talk-'+source)
    except Exception:pass
    if _n37_is_action(said):
        # Real actions (reminders, email, search, play...) go through the mature command stack so they
        # actually happen; then the result is spoken. Never let the voice brain merely promise an action.
        if source=='voice':
            try:send_text(cid,'🎤 '+said)
            except Exception:pass
        before=str(LASTREPLY.get(cid,'') or '');t0=_n37_time.time()
        try:_N37_PREV_HANDLE({'message_id':0,'date':int(t0),'chat':{'id':cid,'type':'private'},'from':{'id':cid},'text':said,'_n37_talk':True})
        except Exception as e:
            try:send_text(cid,'That action hit an error: '+str(e)[:120])
            except Exception:pass
        for _ in range(16):
            after=str(LASTREPLY.get(cid,'') or '')
            if after and after!=before:break
            _n37_time.sleep(0.5)
        else:after=''
        spoken=' '.join((after or 'Done. I ran that for you.').replace('*','').split())
        if len(spoken)>320:spoken=spoken[:300].rsplit('.',1)[0]+'.'
        try:speak(cid,spoken)
        except Exception:pass
        return spoken
    ans=''
    try:ans=ask_ai(cid,said,remember=True,ground=_N37_TALK_CONTRACT,timeout=60) or ''
    except Exception as e:ans=''
    ans=' '.join(str(ans).replace('*','').replace('#','').split())
    if not ans:ans='Sorry, my brain hiccupped. Say that again?'
    if len(ans)>520:ans=ans[:500].rsplit('.',1)[0]+'.'
    try:LASTREPLY[cid]=ans;LASTQ[cid]=said
    except Exception:pass
    try:_n35_episode(cid,'assistant',ans,'talk')
    except Exception:pass
    try:send_text(cid,('🎤 '+said+'\n' if source=='voice' else '')+'💬 '+ans)
    except Exception:pass
    try:speak(cid,ans)
    except Exception:pass
    return ans

def _n37_talk_open(cid):
    _n37_talk_start(cid)
    try:name=_n35_get_fact(cid,'nickname') or _n35_get_fact(cid,'name') or ''
    except Exception:name=''
    hello="I'm listening%s. Send voice notes or type, I'll answer out loud and keep it short. Say bye when you're done."%((', '+name) if name else '')
    send_text(cid,'🎙 Voice session ON (auto-ends after 10 quiet minutes).\n💬 '+hello)
    try:_n37_threading.Thread(target=speak,args=(cid,hello),daemon=True).start()
    except Exception:pass

def _n37_talk_close(cid,reason='bye'):
    s=_n37_talk_stop(cid)
    if not s:return False
    msg='Voice session closed after %d turn%s.'%(s.get('turns',0),'' if s.get('turns',0)==1 else 's')
    send_text(cid,'🎙 '+msg+(' Talk soon.' if reason=='bye' else ' (idle)'))
    if reason=='bye':
        try:_n37_threading.Thread(target=speak,args=(cid,'Bye, talk soon.'),daemon=True).start()
        except Exception:pass
    return True

def _n37_talk_reaper():
    while True:
        try:
            now=_n37_time.time()
            with _N37_LOCK:expired=[c for c,s in _N37_TALK.items() if s['until']<=now]
            for c in expired:_n37_talk_close(c,'idle')
        except Exception:pass
        _n37_time.sleep(30)

# transcription reused from the base handler; the session decides what happens next
_N37_VOICE_PREV=handle_voice
def _n37_transcribe(v):
    try:
        info=tg('getFile',file_id=v['file_id']);fp=info.get('result',{}).get('file_path')
        if not fp:return None
        raw=requests.get(f"{TG_FILE}/{fp}",timeout=60).content
        ext=('.'+fp.rsplit('.',1)[-1]) if '.' in fp.rsplit('/',1)[-1] else '.oga'
        inpath='/tmp/nemo37_in'+ext
        with open(inpath,'wb') as f:f.write(raw)
        return groq_transcribe(inpath)
    except Exception:return None

def handle_voice(chat_id,v):
    if chat_id==OWNER.get('id') and _n37_talk_on(chat_id):
        said=_n37_transcribe(v)
        if not said:
            send_text(chat_id,"I couldn't make that out. Say it again?");return
        if _N37_TALK_STOP_RE.match(said):_n37_talk_close(chat_id,'bye');return
        _n37_talk_turn(chat_id,said,'voice');return
    return _N37_VOICE_PREV(chat_id,v)

# ------------------------------- dispatcher -------------------------------------
def _n37_status(cid):
    try:
        c=_n35_conn();n=c.execute('SELECT COUNT(*) FROM photos WHERE chat_id=? AND active=1',(str(cid),)).fetchone()[0];c.close()
    except Exception:n=0
    return ('NEMO 37.0 — PHOTO MEMORY + VOICE SESSION\n━━━━━━━━━━━━━━━━━━━━\n'
            'Photo memory: %s · %d photos filed · folder %s\n'%('ON' if _n36_kv_get('n37_photomemory','1')=='1' else 'OFF',n,_N37_PHOTO_DIR)+
            'Voice session: %s\n'%('ON (%d turns)'%_N37_TALK.get(cid,{}).get('turns',0) if _n37_talk_on(cid) else 'off — /talk or "let\'s talk"')+
            'Voice choice now sticks (speak() no longer re-forces a default voice)\n'
            '/photos [word] · /photo <id> · /photoforget <id> · /photomemory on|off · /talk · /talk off · /nemo37\n'
            'Keys, connections, trading/shell/payment authority: UNCHANGED')

def _n37_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo37','/photovoice'):send_text(cid,_n37_status(cid));return True
    if low.startswith('/photomemory'):
        arg=low[len('/photomemory'):].strip()
        if arg in ('on','off'):_n36_kv_set('n37_photomemory','1' if arg=='on' else '0');send_text(cid,'📸 Photo memory '+arg.upper()+'.');return True
        send_text(cid,'Photo memory is '+('ON' if _n36_kv_get('n37_photomemory','1')=='1' else 'OFF')+'. Use /photomemory on | off');return True
    if low.startswith('/photos'):
        q=txt[len('/photos'):].strip();hits=_n37_photo_search(cid,q,8)
        if not hits:send_text(cid,'No photos in memory'+((' matching "%s"'%q) if q else '')+'. Send me a photo of a card, bill or note and I will file it.');return True
        send_text(cid,'📸 PHOTO MEMORY'+((' · "%s"'%q) if q else '')+'\n\n'+'\n\n'.join(_n37_photo_line(r) for r in hits)+'\n\n/photo <id> shows one');return True
    if low.startswith('/photoforget'):
        pid=txt[len('/photoforget'):].strip().lstrip('#').upper()
        if not pid:send_text(cid,'Use /photoforget <id>');return True
        try:
            c=_n35_conn();c.execute('UPDATE photos SET active=0 WHERE chat_id=? AND id=?',(str(cid),pid));n=c.total_changes;c.commit();c.close()
            try:
                c=_n35_conn();c.execute("UPDATE facts SET active=0 WHERE chat_id=? AND source=?",(str(cid),'photo:'+pid));c.commit();c.close()
            except Exception:pass
        except Exception:n=0
        send_text(cid,('🧹 Removed #%s and the facts learned from it.'%pid) if n else 'No photo with id #%s.'%pid);return True
    if low.startswith('/photo '):
        pid=txt[7:].strip().lstrip('#').upper()
        try:
            c=_n35_conn();r=c.execute('SELECT id,ts,kind,title,summary,entities,tokens,path,caption FROM photos WHERE chat_id=? AND id=? AND active=1',(str(cid),pid)).fetchone();c.close()
        except Exception:r=None
        if not r:send_text(cid,'No photo with id #%s. /photos lists them.'%pid);return True
        if r[7] and _n37_os.path.exists(r[7]):_n35_send_photo(cid,r[7],_n37_photo_line(r)[:900])
        else:send_text(cid,_n37_photo_line(r)+'\n(image file no longer on disk)')
        return True
    if low in ('/talk','/talk on','/voicesession') or _N37_TALK_START_RE.match(txt):
        if _n37_talk_on(cid):send_text(cid,'🎙 Already in a voice session — just talk. /talk off ends it.');return True
        _n37_talk_open(cid);return True
    if low in ('/talk off','/talk stop','/talk end'):
        if not _n37_talk_close(cid,'bye'):send_text(cid,'No voice session is open. /talk starts one.')
        return True
    if _n37_talk_on(cid) and txt and not txt.startswith('/'):
        if _N37_TALK_STOP_RE.match(txt):_n37_talk_close(cid,'bye');return True
        _n37_threading.Thread(target=_n37_talk_turn,args=(cid,txt,'text'),daemon=True,name='nemo-talk37').start();return True
    return False

_N37_PREV_HANDLE=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();chat=(msg.get('chat') or {});low=txt.lower()
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id'):
            if low.startswith(('/nemo37','/photos','/photo','/talk','/photomemory')):
                try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                except Exception:pass
                return
        if _n37_dispatch(msg):return
    except Exception as e:
        try:_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo37_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N37_PREV_HANDLE(msg)

# ------------------------------- regression / eval ----------------------------
_PRIME_REGRESSION_V37_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V37_PREV();extra=[]
    if isinstance(r,dict):r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v361-version',)]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    def _seed():
        c=_n35_conn();c.execute('INSERT OR REPLACE INTO photos VALUES(?,?,?,?,?,?,?,?,?,?,?,1)',('PEVAL37','__eval37__',_n37_time.time(),'visiting_card','Sharma Plumbing visiting card','Ramesh Sharma, plumber, Alwar. Phone 98290 12345',_n37_json.dumps({'names':['Ramesh Sharma'],'phones':['98290 12345']}),'sharma plumbing visiting card ramesh plumber alwar phone 98290 12345','shaeval','','plumber'));c.commit();c.close();return True
    add('v37-version',lambda:VERSION=='37.0')
    add('v37-photo-table',lambda:_seed())
    add('v37-photo-search',lambda:_n37_photo_search('__eval37__','plumber number')[0][0]=='PEVAL37')
    add('v37-photo-context-injected',lambda:'PEVAL37' in _n35_context('__eval37__','what was the plumber phone from that card'))
    add('v37-photo-context-silent-unrelated',lambda:'PEVAL37' not in _n35_context('__eval37__','explain photosynthesis'))
    add('v37-talk-state',lambda:(_n37_talk_start('__eval37__') or True) and _n37_talk_on('__eval37__') and (_n37_talk_stop('__eval37__') is not None) and not _n37_talk_on('__eval37__'))
    add('v37-talk-start-phrase',lambda:bool(_N37_TALK_START_RE.match("let's talk")) and bool(_N37_TALK_START_RE.match('nemo, baat karo')))
    add('v37-talk-stop-phrase',lambda:bool(_N37_TALK_STOP_RE.match('bye nemo')) and bool(_N37_TALK_STOP_RE.match('stop talking')) and not _N37_TALK_STOP_RE.match('tell me about the bye laws'))
    add('v37-image-hook',lambda:callable(_handle_image_bytes) and _handle_image_bytes is not _N37_IMG_PREV)
    add('v37-voice-hook',lambda:callable(handle_voice) and handle_voice is not _N37_VOICE_PREV)
    add('v37-voice-choice-sticks',lambda:(VOICECFG.__setitem__('en','en-IN-PrabhatNeural') or True) and _n30_apply_girl_voice(True) and VOICECFG.get('en')=='en-IN-PrabhatNeural')
    add('v37-owner-gate',lambda:callable(handle) and callable(_n37_dispatch))
    add('v37-authority-unchanged',lambda:(_v184_compile_control('x','run powershell delete all files') or {}).get('kind') not in ('shell','powershell','cmd','terminal'))
    try:
        c=_n35_conn();c.execute("DELETE FROM photos WHERE chat_id='__eval37__'");c.commit();c.close()
    except Exception:pass
    if not isinstance(r,dict):
        return {'id':'RG37','version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_N37_EVAL_PREV=_n28_eval
def _n28_eval():
    rows=_N37_EVAL_PREV()
    rows.extend([
      {'name':'v37-photo-memory','ok':callable(_n37_file_photo),'detail':'every photo filed, searchable, facts flow to unified memory'},
      {'name':'v37-voice-session','ok':callable(_n37_talk_turn),'detail':'/talk live spoken conversation with context, auto-close'}])
    seen=set();out=[]
    for x in reversed(rows):
        n=str(x.get('name') or '')
        if n in seen:continue
        seen.add(n);out.append(x)
    return list(reversed(out))

_N37_MAIN_PREV=main
def main():
    try:_n37_threading.Thread(target=_n37_talk_reaper,daemon=True,name='nemo-talk37-reaper').start()
    except Exception:pass
    return _N37_MAIN_PREV()


# =============================================================================
# NEMO 38.0 — ATTENTION LOOP + OPEN LOOPS (Nemo stops waiting to be asked)
#   OPEN LOOPS: unfinished business is now remembered as a first-class thing.
#     Captured automatically when the owner defers ("I'll send it tomorrow",
#     "kal karunga", "remind me later to..."), when an action failed because the
#     brains were busy (so it can be retried), and when Nemo asked a question that
#     never got an answer. Manual: /loop <text>. /loops lists, /loopdone <id>,
#     /loopdrop <id>. "Anything pending?" is answered from the loop list.
#   ATTENTION: a quiet background loop (every 3 min) decides whether anything
#     deserves ONE unprompted message: a calendar event starting in ~20 min, a loop
#     that has been open a day (nudged at most once a day, three times total), a
#     failed action to retry, an owner-deferred item whose time has come. Max one
#     attention message per 20 minutes, none during quiet hours (22:30-07:30 IST,
#     configurable) except calendar heads-ups. Disk/memory/reminder-in-the-hour
#     alerts stay with the existing chief-of-staff watch (no duplicates).
#   /attention on|off · /attention status · /quiet HH:MM-HH:MM · /nemo38
#   Keys, connections, trading/shell/payment authority: UNCHANGED.
# =============================================================================
VERSION='38.0'
import re as _n38_re, time as _n38_time, json as _n38_json, threading as _n38_threading, datetime as _n38_dt

_N38_LOCK=_n38_threading.RLock()
def _n38_now():return _n36_now() if '_n36_now' in globals() else _n38_dt.datetime.now()

def _n38_init():
    c=_n35_conn()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS loops(
      id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id TEXT, ts REAL, text TEXT, kind TEXT, status TEXT DEFAULT 'open',
      due REAL DEFAULT 0, nudges INTEGER DEFAULT 0, last_nudge REAL DEFAULT 0, source TEXT, tokens TEXT
    );
    CREATE INDEX IF NOT EXISTS idx_n38_loops ON loops(chat_id,status,ts DESC);
    """)
    c.commit();c.close()
try:_n38_init()
except Exception:pass

def _n38_fmt(ts,f='%d %b %H:%M'):
    try:return _n38_dt.datetime.fromtimestamp(float(ts),_N36_IST).strftime(f) if '_N36_IST' in globals() else _n38_time.strftime(f,_n38_time.localtime(float(ts)))
    except Exception:return '?'
def _n38_tokens(s):return {w for w in _n38_re.findall(r'[a-z0-9]+',str(s or '').lower()) if len(w)>2 and w not in ('the','and','for','that','this','with','will','tomorrow','later','kal','baad','mein')}

# ------------------------------- loop store -----------------------------------
def _n38_add(cid,text,kind='owner',due=0,source='auto'):
    text=' '.join(str(text or '').split())[:300]
    if len(text)<4:return None
    toks=' '.join(sorted(_n38_tokens(text)))
    with _N38_LOCK:
        c=_n35_conn()
        try:
            for r in c.execute("SELECT id,tokens FROM loops WHERE chat_id=? AND status='open' AND kind=? ORDER BY ts DESC LIMIT 60",(str(cid),kind)).fetchall():
                a=set((r[1] or '').split());b=set(toks.split())
                if a and b and len(a&b)/max(1,len(a|b))>=0.6:return r[0]   # near-duplicate already open
            c.execute('INSERT INTO loops(chat_id,ts,text,kind,status,due,source,tokens) VALUES(?,?,?,?,?,?,?,?)',(str(cid),_n38_time.time(),text,kind,'open',float(due or 0),source,toks))
            c.commit();return c.execute('SELECT last_insert_rowid()').fetchone()[0]
        finally:c.close()

def _n38_open(cid,limit=30):
    try:
        c=_n35_conn();rows=c.execute("SELECT id,ts,text,kind,due,nudges,last_nudge,source FROM loops WHERE chat_id=? AND status='open' ORDER BY ts DESC LIMIT ?",(str(cid),int(limit))).fetchall();c.close();return rows
    except Exception:return []

def _n38_set_status(cid,lid,status):
    with _N38_LOCK:
        c=_n35_conn();c.execute("UPDATE loops SET status=? WHERE chat_id=? AND id=? AND status='open'",(status,str(cid),int(lid)));n=c.total_changes;c.commit();c.close();return n>0

def _n38_close_matching(cid,text):
    """Owner says 'done with X' / 'sent the invoice' → close the best-matching open loop."""
    q=_n38_tokens(text)
    if len(q)<2:return None
    best=None;bs=0
    for r in _n38_open(cid,60):
        s=len(q & set((r[7] and '') or _n38_tokens(r[2])))
        if s>bs:bs=s;best=r
    if best and bs>=2 and bs>=len(_n38_tokens(best[2]))*0.5:
        _n38_set_status(cid,best[0],'done');return best
    return None

# ------------------------------- capture ---------------------------------------
_N38_DEFER_RE=_n38_re.compile(r"(?i)^\s*(?:ok(?:ay)?[,\s]+|yes[,\s]+|haan[,\s]+)?(?:i'?ll|i will|i'?m going to|i have to|i need to|i should|i must|let me|remind me later to|remind me to|main|mujhe)\s+(.{4,160}?)\s*(?:$|\.|,)")
_N38_TIME_RE=_n38_re.compile(r"(?i)\b(tomorrow|tonight|this evening|in the evening|later|later today|next week|on monday|on tuesday|on wednesday|on thursday|on friday|on saturday|on sunday|kal|parso|baad mein|shaam ko|raat ko|subah|agle hafte|kal subah)\b")
_N38_PENDING_Q_RE=_n38_re.compile(r"(?i)\b(anything pending|what'?s pending|what is pending|open loops?|what did i (?:forget|leave)|kya pending|kya baaki|baaki kya|unfinished|what am i forgetting|pending kya hai)\b")
_N38_DONE_RE=_n38_re.compile(r"(?i)^\s*(?:done|did it|finished|completed|ho gaya|kar diya|sent|paid|booked|called)\b\s*[:,-]?\s*(.{3,200})?$")

def _n38_due_from(text):
    t=str(text or '').lower();now=_n38_now();base=now.replace(second=0,microsecond=0)
    def at(d,h,m=0):return (base+_n38_dt.timedelta(days=d)).replace(hour=h,minute=m).timestamp()
    if 'tomorrow' in t or 'kal subah' in t or _n38_re.search(r'\bkal\b',t):return at(1,9,30)
    if 'parso' in t:return at(2,9,30)
    if 'tonight' in t or 'raat ko' in t:return at(0,20,30) if now.hour<20 else at(1,9,30)
    if 'evening' in t or 'shaam' in t:return at(0,18,0) if now.hour<18 else at(1,9,30)
    if 'subah' in t or 'morning' in t:return at(1 if now.hour>=11 else 0,9,30)
    if 'next week' in t or 'agle hafte' in t:return at(7,9,30)
    for i,d in enumerate(('monday','tuesday','wednesday','thursday','friday','saturday','sunday')):
        if 'on '+d in t:
            delta=(i-now.weekday())%7 or 7;return at(delta,9,30)
    return (now+_n38_dt.timedelta(hours=4)).timestamp()

def _n38_capture_owner(cid,text):
    t=' '.join(str(text or '').split())
    if not t or t.startswith('/') or len(t)>400 or '?' in t:return None
    if not _N38_TIME_RE.search(t):return None
    m=_N38_DEFER_RE.match(t)
    if not m:return None
    item=_N38_TIME_RE.sub('',m.group(1)).strip(' ,.')
    item=_n38_re.sub(r'(?i)^(?:to|ko)\s+','',item)
    if len(item)<4:return None
    lid=_n38_add(cid,item,'owner',_n38_due_from(t),'deferral')
    return lid

_N38_LAST_ASSISTANT_Q={}   # cid -> (ts,question)
def _n38_note_assistant(cid,text):
    s=str(text or '').strip()
    if not s or len(s)>900:return
    last=s.splitlines()[-1].strip()
    if last.endswith('?') and 12<len(last)<200 and not last.lower().startswith(('anything else','want me to','shall i','would you like')):
        _N38_LAST_ASSISTANT_Q[cid]=(_n38_time.time(),last)
    if s.startswith('\U0001F9E0 My brains are all busy') and LASTQ.get(cid) and not str(LASTQ.get(cid)).startswith('/'):
        _n38_add(cid,'retry: '+str(LASTQ.get(cid))[:200],'retry',_n38_time.time()+900,'brains-busy')

# ------------------------------- attention -------------------------------------
def _n38_quiet():
    q=str(_n36_kv_get('n38_quiet','22:30-07:30'));now=_n38_now().strftime('%H:%M')
    try:
        a,b=q.split('-');a=a.strip();b=b.strip()
        return (a<=now or now<b) if a>b else (a<=now<b)
    except Exception:return False

def _n38_can_send():
    last=float(_n36_kv_get('n38_last_attention','0') or 0);return _n38_time.time()-last>=20*60

def _n38_mark_sent():_n36_kv_set('n38_last_attention',str(_n38_time.time()))

def _n38_calendar_soon():
    try:
        if not google_ready():return None
        ev=gcal_upcoming(1) or [];now=_n38_dt.datetime.now(_n38_dt.timezone.utc)
        for e in ev:
            w=str(e.get('when') or '')
            if 'T' not in w:continue
            try:t=_n38_dt.datetime.fromisoformat(w.replace('Z','+00:00'))
            except Exception:continue
            mins=(t-now).total_seconds()/60
            if 12<=mins<=25:
                key='n38_cal_'+w[:16]
                if _n36_kv_get(key,'')=='1':continue
                _n36_kv_set(key,'1');return '📅 In about %d min: %s'%(int(mins),str(e.get('title') or 'event')[:80])
    except Exception:pass
    return None

def _n38_pick_loop(cid):
    now=_n38_time.time();best=None
    for lid,ts,text,kind,due,nudges,last_nudge,source in _n38_open(cid,60):
        if nudges>=3:continue
        if now-last_nudge<20*3600:continue
        if kind=='retry' and due and now>=due:return (lid,text,kind,'retry')
        if kind=='owner' and due and now>=due:return (lid,text,kind,'due')
        if now-ts>=24*3600 and (best is None or ts<best[1]):best=(lid,ts,text,kind)
    if best:return (best[0],best[2],best[3],'stale')
    return None

def _n38_tick(force=False):
    if _n36_kv_get('n38_attention','1')!='1' and not force:return None
    oid=OWNER.get('id')
    if not oid:return None
    msg=_n38_calendar_soon()
    if msg:
        send_text(oid,msg);_n38_mark_sent();return msg
    if _n38_quiet() and not force:return None
    if not _n38_can_send() and not force:return None
    pick=_n38_pick_loop(oid)
    if not pick:return None
    lid,text,kind,why=pick
    if why=='retry':m='🔁 Earlier my brains were busy and this did not get done: "%s". Want me to try again now? Reply "retry" or /loopdrop %d.'%(text[7:] if text.startswith("retry: ") else text,lid)
    elif why=='due':m='⏰ You said you would: %s. Is it done? /loopdone %d · /loopdrop %d'%(text,lid,lid)
    else:m='🔔 Still open since %s: "%s". Done, or drop it? /loopdone %d · /loopdrop %d'%(_n38_fmt([r for r in _n38_open(oid,60) if r[0]==lid][0][1],'%d %b'),text,lid,lid)
    try:
        c=_n35_conn();c.execute('UPDATE loops SET nudges=nudges+1,last_nudge=? WHERE id=?',(_n38_time.time(),lid));c.commit();c.close()
    except Exception:pass
    send_text(oid,m);_n38_mark_sent();return m

def _n38_loop_thread():
    _n38_time.sleep(90)
    while True:
        try:_n38_tick()
        except Exception:pass
        _n38_time.sleep(180)

# ------------------------------- views -----------------------------------------
def _n38_list_text(cid):
    rows=_n38_open(cid,25)
    if not rows:return '✅ No open loops. Nothing pending that I know of.'
    lines=[]
    for lid,ts,text,kind,due,nudges,last_nudge,source in rows:
        tag={'owner':'you','retry':'retry','nemo':'me','manual':'note'}.get(kind,kind)
        when=_n38_fmt(ts,'%d %b');d=(' · due '+_n38_fmt(due)) if due else ''
        lines.append('#%d [%s · %s%s] %s'%(lid,tag,when,d,text))
    return '🧵 OPEN LOOPS (%d)\n\n'%len(rows)+'\n'.join(lines)+'\n\n/loopdone <id> · /loopdrop <id> · /loop <text> adds one'

def _n38_status(cid):
    return ('NEMO 38.0 — ATTENTION + OPEN LOOPS\n━━━━━━━━━━━━━━━━━━━━\n'
            'Attention loop: %s · quiet hours %s IST · one message per 20 min\n'%('ON' if _n36_kv_get('n38_attention','1')=='1' else 'OFF',_n36_kv_get('n38_quiet','22:30-07:30'))+
            'Open loops: %d · last attention message: %s\n'%(len(_n38_open(cid,200)),(_n38_fmt(float(_n36_kv_get('n38_last_attention','0') or 0)) if float(_n36_kv_get('n38_last_attention','0') or 0) else 'never'))+
            'Captures: your deferrals ("I\'ll do X tomorrow"), failed actions (brains busy), my unanswered questions\n'
            'Disk/memory/reminder alerts stay with the existing chief-of-staff watch (no duplicates)\n'
            '/loops · /loop <text> · /loopdone <id> · /loopdrop <id> · /attention on|off|now · /quiet HH:MM-HH:MM\n'
            'Keys, connections, trading/shell/payment authority: UNCHANGED')

# ------------------------------- dispatcher ------------------------------------
def _n38_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo38','/attentionstatus'):send_text(cid,_n38_status(cid));return True
    if low in ('/loops','/openloops','/pending'):send_text(cid,_n38_list_text(cid));return True
    if low.startswith('/loop '):
        lid=_n38_add(cid,txt[6:],'manual',0,'manual');send_text(cid,'🧵 Open loop #%s noted: %s'%(lid,txt[6:].strip()[:120]) if lid else 'Give me a few words to remember.');return True
    if low.startswith('/loopdone') or low.startswith('/loopdrop'):
        m=_n38_re.search(r'(\d+)',low);st='done' if 'done' in low else 'dropped'
        if not m:send_text(cid,'Use /loopdone <id> or /loopdrop <id> (see /loops)');return True
        ok=_n38_set_status(cid,int(m.group(1)),st);send_text(cid,('✅ Loop #%s marked %s.'%(m.group(1),st)) if ok else 'No open loop #%s.'%m.group(1));return True
    if low.startswith('/attention'):
        arg=low[len('/attention'):].strip()
        if arg in ('on','off'):_n36_kv_set('n38_attention','1' if arg=='on' else '0');send_text(cid,'🔔 Attention loop '+arg.upper()+'.');return True
        if arg=='now':
            r=_n38_tick(force=True);send_text(cid,'Nothing needs your attention right now.' if not r else 'Sent.');return True
        send_text(cid,_n38_status(cid));return True
    if low.startswith('/quiet'):
        m=_n38_re.match(r'/quiet\s+(\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})',low)
        if m:_n36_kv_set('n38_quiet',m.group(1).zfill(5)+'-'+m.group(2).zfill(5));send_text(cid,'🌙 Quiet hours set to %s-%s IST (calendar heads-ups still come through).'%(m.group(1),m.group(2)));return True
        send_text(cid,'Quiet hours: '+_n36_kv_get('n38_quiet','22:30-07:30')+' IST. Use /quiet 23:00-07:00');return True
    if _N38_PENDING_Q_RE.search(low):send_text(cid,_n38_list_text(cid));return True
    if txt and not txt.startswith('/'):
        m=_N38_DONE_RE.match(txt)
        if m and m.group(1):
            hit=_n38_close_matching(cid,m.group(1))
            if hit:send_text(cid,'✅ Closed loop #%d: %s'%(hit[0],hit[2][:100]))
        elif low.strip() in ('retry','try again','retry now','fir se try karo'):
            for lid,ts,text,kind,due,nudges,last_nudge,source in _n38_open(cid,60):
                if kind=='retry':
                    q=text[7:] if text.startswith('retry: ') else text;_n38_set_status(cid,lid,'done')
                    send_text(cid,'🔁 Retrying: '+q[:120]);_N38_PREV_HANDLE({'message_id':0,'date':int(_n38_time.time()),'chat':{'id':cid,'type':'private'},'from':{'id':cid},'text':q});return True
        else:
            try:_n38_capture_owner(cid,txt)
            except Exception:pass
            try:
                lq=_N38_LAST_ASSISTANT_Q.pop(cid,None)
                if lq and _n38_time.time()-lq[0]>1800 and not any(w in low for w in ('yes','no','haan','nahi','ok')):
                    _n38_add(cid,'you never answered: '+lq[1][:150],'nemo',0,'unanswered')
            except Exception:pass
    return False

_N38_PREV_HANDLE=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();chat=(msg.get('chat') or {});low=txt.lower()
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id'):
            if low.startswith(('/nemo38','/loop','/attention','/quiet','/pending')):
                try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                except Exception:pass
                return
        if _n38_dispatch(msg):return
    except Exception as e:
        try:_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo38_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N38_PREV_HANDLE(msg)

# watch what Nemo says, to catch unanswered questions and busy-brain failures
_N38_SEND_PREV=send_text
def send_text(chat_id,text,kb=None):
    try:
        if chat_id==OWNER.get('id'):_n38_note_assistant(chat_id,text)
    except Exception:pass
    return _N38_SEND_PREV(chat_id,text,kb)

# pending loops also join the single memory injection when the owner asks about them
if '_n35_context' in globals():
    _N38_CTX_PREV=_n35_context
    def _n35_context(cid,query,limit=8,budget=1600):
        base=_N38_CTX_PREV(cid,query,limit,budget)
        try:
            if _n38_re.search(r'(?i)\b(pending|forgot|forget|left|open|unfinished|baaki|promised|said i would)\b',str(query or '')):
                rows=_n38_open(cid,5)
                if rows:base=(base+'\n\nOPEN LOOPS (unfinished items):\n'+'\n'.join('- #%d %s'%(r[0],r[2]) for r in rows)).strip()
        except Exception:pass
        return base

# ------------------------------- regression / eval -----------------------------
_PRIME_REGRESSION_V38_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V38_PREV();extra=[]
    if isinstance(r,dict):r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v37-version',)]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v38-version',lambda:VERSION=='38.0')
    add('v38-capture-defer-en',lambda:_n38_capture_owner('__eval38__',"I'll send the invoice to Rahul tomorrow") is not None and any('invoice' in r[2] for r in _n38_open('__eval38__')))
    add('v38-capture-defer-hi',lambda:_n38_capture_owner('__eval38__','main kal electrician ko call karunga') is not None)
    add('v38-no-capture-question',lambda:_n38_capture_owner('__eval38__',"will you remind me tomorrow?") is None)
    add('v38-no-capture-plain',lambda:_n38_capture_owner('__eval38__',"the weather is nice today") is None)
    add('v38-dedupe',lambda:_n38_add('__eval38__','send the invoice to Rahul','owner')==[r for r in _n38_open('__eval38__') if 'invoice' in r[2]][0][0])
    add('v38-pending-question',lambda:bool(_N38_PENDING_Q_RE.search('anything pending?')) and bool(_N38_PENDING_Q_RE.search('kya baaki hai')))
    add('v38-done-closes',lambda:_n38_close_matching('__eval38__','sent the invoice to Rahul') is not None)
    add('v38-context-injects',lambda:'#' in _n35_context('__eval38__','what did I promise / pending') or not _n38_open('__eval38__'))
    add('v38-quiet-parse',lambda:isinstance(_n38_quiet(),bool))
    add('v38-due-tomorrow',lambda:_n38_due_from('tomorrow')>_n38_time.time())
    add('v38-owner-gate',lambda:callable(handle) and callable(_n38_dispatch))
    add('v38-authority-unchanged',lambda:(_v184_compile_control('x','run powershell delete all files') or {}).get('kind') not in ('shell','powershell','cmd','terminal'))
    try:
        c=_n35_conn();c.execute("DELETE FROM loops WHERE chat_id='__eval38__'");c.commit();c.close()
    except Exception:pass
    if not isinstance(r,dict):
        return {'id':'RG38','version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_N38_EVAL_PREV=_n28_eval
def _n28_eval():
    rows=_N38_EVAL_PREV()
    rows.extend([
      {'name':'v38-open-loops','ok':callable(_n38_add),'detail':'deferrals, failed actions and unanswered questions remembered as open loops'},
      {'name':'v38-attention','ok':callable(_n38_tick),'detail':'unprompted, rate-limited nudges with quiet hours; calendar heads-ups'}])
    seen=set();out=[]
    for x in reversed(rows):
        n=str(x.get('name') or '')
        if n in seen:continue
        seen.add(n);out.append(x)
    return list(reversed(out))

_N38_MAIN_PREV=main
def main():
    try:_n38_threading.Thread(target=_n38_loop_thread,daemon=True,name='nemo-attention38').start()
    except Exception:pass
    return _N38_MAIN_PREV()


# =============================================================================
# NEMO 39.0 — FAST CORE (consolidation by routing)
#   The file carries 10 ChatGPT-era ask_ai rewrite layers (v20.4, v21, v24 cortex,
#   v25, v26, v27, v28, v28.1, v29.1, v32) stacked on top of the mature v13.x
#   brain. Each normal message paid for every layer: repeated rule paragraphs,
#   multiple context rewrites, extra planning calls, and ~10 wrapper frames.
#   v39 keeps all of that code in place (rollback safety) but routes NORMAL OWNER
#   CHAT around it: the outermost ask_ai calls the pre-ChatGPT brain directly with
#   ONE compact ground block built from the pieces that proved useful —
#     · unified memory (v35) + photo memory (v37) + open loops (v38)
#     · lessons the owner taught (v28/v29 feedback)
#     · fresh world evidence when the question is time-sensitive (v28 world ground)
#     · recent-referent context only for follow-ups ("do it again", "that one")
#   and keeps the v29.1 telemetry counter, v28 episodes and v21 continuity state.
#   Internal prompts (remember=False), raw/JSON calls, vision requests, and
#   /fastcore off all fall back to the full old chain unchanged.
#   /fastcore on|off · /fastcore stats · /fastcore test <question> (A/B both paths)
#   Keys, connections, trading/shell/payment authority: UNCHANGED.
# =============================================================================
VERSION='39.0'
import time as _n39_time, re as _n39_re, threading as _n39_threading

_N39_STATS={'fast':0,'chain':0,'fast_ms':0.0,'chain_ms':0.0,'fast_ground_chars':0,'errors':0}
_N39_LOCK=_n39_threading.Lock()

# The brain as it stood before the first ChatGPT rewrite layer (v20.4). This still includes
# v13.23 learning, v13.27 tracing, v13.29 RAG/learned-experience and the Dharma persona hook.
_N39_CORE_ASK=globals().get('_M204_ASK')
_N39_ASK_PREV=ask_ai

def _n39_enabled():
    try:return _n36_kv_get('n39_fastcore','1')=='1' and callable(_N39_CORE_ASK)
    except Exception:return False

def _n39_eligible(chat_id,text,image_b64,remember,raw):
    if not remember or raw or image_b64:return False
    if chat_id!=OWNER.get('id'):return False
    src=str(text or '')
    if not src.strip() or len(src)>14000:return False
    try:
        if _n240_is_internal(src):return False
    except Exception:pass
    if _n39_re.search(r'(?is)(COMPLETE REPORT only|CALCULATION BLOCK:|senior QA editor|system prompt|Return ONLY a JSON|ONE-PAGE INFOGRAPHIC SPEC|filing this image|Write a complete, warm, natural email)',src[:2000]):return False
    return True

def _n39_ground(chat_id,src,ground):
    parts=[str(ground or '').strip()]
    try:parts.append(_n35_context(chat_id,src,8,1600))
    except Exception:pass
    try:parts.append(_n28_lesson_context(chat_id,src))
    except Exception:pass
    try:
        w,cls=_n28_world_ground(src,5)
        if w:parts.append(w);parts.append('CURRENTNESS RULE: Distinguish retrieved facts from inference and mention the date when freshness matters.')
    except Exception:pass
    try:
        if _n281_contextual_query(src):
            ref=_n28_referent_context(chat_id,src)
            if ref:parts.append(ref);parts.append('CONTINUITY RULE: Resolve obvious it/that/same-one references from the recent context. Ask only when more than one plausible referent remains.')
    except Exception:pass
    parts.append('ACTION RULE: If an external action lacks a receipt or verification, do not say it happened.')
    return '\n\n'.join(p for p in parts if p).strip()

def _n39_fast_answer(chat_id,src,timeout,long_output,models_override,deep,ground):
    # bookkeeping the old layers used to do (episodes, feedback lessons, conflict guard, direct relation answers)
    try:_n35_episode(chat_id,'user',src,'text')
    except Exception:pass
    try:_n28_capture_feedback(chat_id,src)
    except Exception:pass
    try:
        fact=_n35_extract(chat_id,src,'text-explicit') if len(src)<3000 else None
        if fact and not fact[2].get('ok') and fact[2].get('status')=='CONFLICT':
            return ("I did not overwrite the strong memory '%s' with '%s'. If you really want to change it, say 'correction, %s'."%(fact[2].get('current'),fact[1],src))
    except Exception:pass
    try:
        direct=_n35_relation_answer(chat_id,src)
        if direct:
            _n35_episode(chat_id,'assistant',direct,'memory-local');return direct
    except Exception:pass
    profile=_n71_profile(src,_n71_mode(chat_id))
    if profile['deep']:
        deep=True;long_output=True
    g=_n39_ground(chat_id,src,ground)+'\n\nRESPONSE CONTRACT: '+profile['instruction']
    with _N39_LOCK:_N39_STATS['fast_ground_chars']+=len(g)
    def _call():return _N39_CORE_ASK(chat_id,src,image_b64=None,remember=True,timeout=timeout,long_output=long_output,models_override=models_override,deep=deep,ground=g,raw=False)
    try:ans=_n291_call_provider('brain_total',_call) if callable(globals().get('_n291_call_provider')) else _call()
    except Exception:
        with _N39_LOCK:_N39_STATS['errors']+=1
        raise
    try:ans=_n281_output_clean(ans)
    except Exception:pass
    try:
        _n35_episode(chat_id,'assistant',ans,'text')
        if callable(globals().get('_n210_state_write')):
            if _n39_re.search(r'\?\s*$',str(ans or '').strip()[-200:]):_n210_state_write(chat_id,last_question=ans,last_answer=ans)
            else:_n210_state_write(chat_id,last_answer=ans)
    except Exception:pass
    return ans

def ask_ai(chat_id,text,image_b64=None,remember=True,timeout=180,long_output=False,models_override=None,deep=False,ground='',raw=False):
    if _n39_enabled() and _n39_eligible(chat_id,text,image_b64,remember,raw):
        t0=_n39_time.time()
        try:return _n39_fast_answer(chat_id,str(text or ''),timeout,long_output,models_override,deep,ground)
        finally:
            with _N39_LOCK:_N39_STATS['fast']+=1;_N39_STATS['fast_ms']+=(_n39_time.time()-t0)*1000
    t0=_n39_time.time()
    try:return _N39_ASK_PREV(chat_id,text,image_b64=image_b64,remember=remember,timeout=timeout,long_output=long_output,models_override=models_override,deep=deep,ground=ground,raw=raw)
    finally:
        with _N39_LOCK:_N39_STATS['chain']+=1;_N39_STATS['chain_ms']+=(_n39_time.time()-t0)*1000

# ------------------------------- status / dispatcher ---------------------------
def _n39_stats_text():
    s=dict(_N39_STATS);fa=s['fast_ms']/s['fast'] if s['fast'] else 0;ca=s['chain_ms']/s['chain'] if s['chain'] else 0;gc=s['fast_ground_chars']/s['fast'] if s['fast'] else 0
    return ('NEMO 39.0 — FAST CORE\n━━━━━━━━━━━━━━━━━━━━\n'
            'Fast core: %s (core brain reachable: %s)\n'%('ON' if _n39_enabled() else 'OFF',bool(_N39_CORE_ASK))+
            'Since boot — fast path: %d calls, avg %.0f ms, avg ground %d chars · full chain: %d calls, avg %.0f ms · errors %d\n'%(s['fast'],fa,gc,s['chain'],ca,s['errors'])+
            'Fast path skips: v20.4/v21/v24-cortex/v25/v26/v27/v28/v28.1/v32 rewrites (10 layers) — all still present for fallback\n'
            'Fast path keeps: unified memory · photo memory · open loops · lessons · fresh-world evidence · follow-up referents · telemetry · episodes\n'
            'Full chain still used for: internal prompts, JSON/raw calls, vision, guests, and when /fastcore off\n'
            '/fastcore on|off · /fastcore stats · /fastcore test <question>')

def _n39_ab_test(cid,q):
    out=[]
    for label,fn in (('FAST CORE',lambda:_n39_fast_answer(cid,q,90,False,None,False,'')),('FULL CHAIN',lambda:_N39_ASK_PREV(cid,q,remember=True,timeout=90))):
        t0=_n39_time.time()
        try:a=str(fn() or '')
        except Exception as e:a='ERROR: '+type(e).__name__+': '+str(e)[:120]
        out.append('%s — %.1fs, %d chars\n%s'%(label,_n39_time.time()-t0,len(a),a[:700]))
    send_text(cid,'🧪 A/B on: '+q[:120]+'\n\n'+'\n\n────────\n\n'.join(out))

def _n39_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo39','/fastcore','/fastcore stats','/fastcore status'):send_text(cid,_n39_stats_text());return True
    if low in ('/fastcore on','/fastcore off'):
        _n36_kv_set('n39_fastcore','1' if low.endswith('on') else '0');send_text(cid,'⚡ Fast core '+('ON — normal chat now bypasses the 10 old rewrite layers.' if low.endswith('on') else 'OFF — every message goes through the full old chain again.'));return True
    if low.startswith('/fastcore test'):
        q=txt[len('/fastcore test'):].strip() or 'What do you know about me, and what is pending?'
        send_text(cid,'🧪 Running the same question through both paths (two brain calls)...')
        _n39_threading.Thread(target=_n39_ab_test,args=(cid,q),daemon=True).start();return True
    return False

_N39_PREV_HANDLE=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();chat=(msg.get('chat') or {});low=txt.lower()
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id'):
            if low.startswith(('/nemo39','/fastcore')):
                try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                except Exception:pass
                return
        if _n39_dispatch(msg):return
    except Exception as e:
        try:_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo39_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N39_PREV_HANDLE(msg)

# self-audit verdict now reflects the routing, not just the raw layer count
if '_n36_audit_text' in globals():
    _N39_AUDIT_TEXT_PREV=_n36_audit_text
    def _n36_audit_text(a):
        t=_N39_AUDIT_TEXT_PREV(a)
        if _n39_enabled():
            t=t.replace('Verdict: ⚠️ layer stack is heavy — next consolidation phase recommended','Verdict: ✅ fast core ON — normal chat bypasses the 10 old rewrite layers (still in file for fallback)')
        return t+'\nFast core: %s · fast %d / chain %d calls since boot'%('ON' if _n39_enabled() else 'OFF',_N39_STATS['fast'],_N39_STATS['chain'])

# ------------------------------- regression / eval -----------------------------
_PRIME_REGRESSION_V39_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V39_PREV();extra=[]
    if isinstance(r,dict):r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v38-version',)]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v39-version',lambda:VERSION=='39.0')
    add('v39-core-brain-bound',lambda:callable(_N39_CORE_ASK) and _N39_CORE_ASK is not ask_ai)
    add('v39-eligible-owner-chat',lambda:_n39_eligible(OWNER.get('id'),'how are you today',None,True,False))
    add('v39-ineligible-internal',lambda:not _n39_eligible(OWNER.get('id'),'Return ONLY a JSON object {"a":1}',None,True,False))
    add('v39-ineligible-raw',lambda:not _n39_eligible(OWNER.get('id'),'hello',None,True,True))
    add('v39-ineligible-vision',lambda:not _n39_eligible(OWNER.get('id'),'what is this','QUJD',True,False))
    add('v39-ineligible-guest',lambda:not _n39_eligible(999999999,'hello',None,True,False))
    add('v39-ground-compact',lambda:len(_n39_ground(OWNER.get('id'),'hello there',''))<2600)
    add('v39-ground-has-action-rule',lambda:'ACTION RULE' in _n39_ground(OWNER.get('id'),'hello',''))
    add('v39-toggle',lambda:(_n36_kv_set('n39_fastcore','0') or True) and not _n39_enabled() and (_n36_kv_set('n39_fastcore','1') or True) and _n39_enabled())
    add('v39-owner-gate',lambda:callable(handle) and callable(_n39_dispatch))
    add('v39-authority-unchanged',lambda:(_v184_compile_control('x','run powershell delete all files') or {}).get('kind') not in ('shell','powershell','cmd','terminal'))
    if not isinstance(r,dict):
        return {'id':'RG39','version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_N39_EVAL_PREV=_n28_eval
def _n28_eval():
    rows=_N39_EVAL_PREV()
    rows.append({'name':'v39-fast-core','ok':callable(_N39_CORE_ASK),'detail':'normal chat routed around 10 old rewrite layers; one compact ground block; old chain kept for fallback'})
    seen=set();out=[]
    for x in reversed(rows):
        n=str(x.get('name') or '')
        if n in seen:continue
        seen.add(n);out.append(x)
    return list(reversed(out))

_N39_MAIN_PREV=main
def main():
    try:
        if _N39_CORE_ASK is None:print('NEMO 39.0 warning: core brain reference not found; fast core disabled, full chain in use')
    except Exception:pass
    return _N39_MAIN_PREV()


# =============================================================================
# NEMO 40.0 — COMMAND CENTER + LEARN MODE
#   COMMAND CENTER: the v35–v39 features grew ~35 commands and five separate
#     /nemo3x status screens. Now: ONE tappable /menu (inline buttons, grouped),
#     ONE /nemostatus screen, plain-language routing for every new feature
#     ("show my mind", "day card", "anything pending", "check yourself", "find the
#     plumber photo", "quiet hours 11 to 7"), and the Telegram "/" command list is
#     registered at boot so the important commands autocomplete. Old /nemo3x
#     commands still work but are no longer advertised.
#   LEARN MODE: /learn <topic> in <N> days (or "teach me Power BI in 10 days") →
#     Nemo builds a syllabus, sends lesson 1 now (simple explanation + example +
#     a lesson card image + a 3-question tap quiz), then one lesson a day at your
#     learn time (default 19:00 IST). Progress and scores live in unified memory.
#     /learn status · /learn next · /learn pause · /learn stop · /learn time HH:MM
#   Keys, connections, trading/shell/payment authority: UNCHANGED.
# =============================================================================
VERSION='40.0'
import re as _n40_re, time as _n40_time, json as _n40_json, threading as _n40_threading, datetime as _n40_dt

def _n40_init():
    c=_n35_conn()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id TEXT, ts REAL, topic TEXT, title TEXT, days INTEGER,
      status TEXT DEFAULT 'active', current INTEGER DEFAULT 0, last_sent REAL DEFAULT 0, syllabus TEXT, score INTEGER DEFAULT 0, answered INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS lessons(course_id INTEGER, idx INTEGER, ts REAL, title TEXT, content TEXT, quiz TEXT, answers TEXT DEFAULT '', PRIMARY KEY(course_id,idx));
    """)
    c.commit();c.close()
try:_n40_init()
except Exception:pass

def _n40_run(cid,command):
    """Run an existing command exactly as if the owner typed it."""
    try:return handle({'message_id':0,'date':int(_n40_time.time()),'chat':{'id':cid,'type':'private'},'from':{'id':cid},'text':command})
    except Exception as e:
        try:send_text(cid,'That action hit an error: '+str(e)[:120])
        except Exception:pass

