# natural-language routes for the new features (deterministic, owner only)
_N40_NL=[
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:menu|show (?:the )?menu|options|buttons)\s*$",'/menu'),
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:show|draw|open)?\s*(?:my )?(?:mind ?map|mind graph|memory graph|what (?:do )?you know about me graph)\s*$",'/mind'),
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:what (?:all )?do you (?:know|remember) about me|what have you learned about me|mujhe kya jaante ho)\s*\??\s*$",'/mindfacts'),
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:day ?card|morning (?:brief|card)|today'?s card|aaj ka card|my day)\s*(?:now|please)?\s*$",'/daycard now'),
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:check yourself|self[- ]?audit|audit yourself|how healthy are you)\s*\??\s*$",'/selfaudit'),
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:full status|new features status|status of (?:new )?features|nemo status)\s*\??\s*$",'/nemostatus'),
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:fast ?core (?:stats|status)|how fast are you)\s*\??\s*$",'/fastcore stats'),
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:find|show|search)\s+(?:the |my )?(?:photo|picture|pic|image)s?\s+(?:of|for|about)\s+(.{2,60})$",'/photos {1}'),
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:quiet hours?|do not disturb|dnd)\s+(?:from\s+)?(\d{1,2})(?::(\d{2}))?\s*(?:to|-|–)\s*(\d{1,2})(?::(\d{2}))?\s*$",'QUIET'),
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:teach me|i want to learn|help me learn|learn|course on|sikhao)\s+(.{2,80}?)\s+(?:in|over|within)\s+(\d{1,2})\s*(?:days?|din)\s*$",'/learn {1} in {2} days'),
 (r"(?i)^\s*(?:nemo[,\s]*)?(?:next lesson|agla lesson|continue (?:the )?course)\s*$",'/learn next'),
]
def _n40_nl_route(cid,txt):
    for pat,cmd in _N40_NL:
        m=_n40_re.match(pat,txt)
        if not m:continue
        if cmd=='QUIET':
            a='%02d:%s'%(int(m.group(1)),(m.group(2) or '00'));b='%02d:%s'%(int(m.group(3)),(m.group(4) or '00'));return '/quiet %s-%s'%(a,b)
        out=cmd
        for i in range(1,(m.lastindex or 0)+1):out=out.replace('{%d}'%i,(m.group(i) or '').strip())
        return out
    return None

# ------------------------------- learn mode ------------------------------------
_N40_SYLLABUS_PROMPT=('Design a %d-day learning plan on "%s" for a motivated adult beginner. Return ONLY a JSON object, no prose, no markdown fences:\n'
 '{"title":"<=50 chars","lessons":[{"title":"<=45 chars","goal":"<=90 chars","key_points":["<=70 chars", 2 to 4 items]}, ... exactly %d items in learning order]}')
_N40_LESSON_PROMPT=('Write lesson %d of %d in the course "%s". Lesson title: "%s". Goal: %s. Return ONLY a JSON object, no prose, no markdown fences:\n'
 '{"explanation":"600-1100 chars, plain simple English (Hinglish allowed if the topic is Indian-context), short paragraphs, no markdown headings",'
 '"example":"<=300 chars, one concrete worked example or mini exercise","key_points":["<=90 chars", 3 to 5 items],'
 '"quiz":[{"q":"<=120 chars","options":["<=40 chars", exactly 4],"answer":0,"why":"<=140 chars"}, exactly 3 items]}\n'
 'Rules: teach, do not lecture; build on earlier lessons; the quiz must be answerable from this lesson only.')

def _n40_course(cid):
    try:
        c=_n35_conn();r=c.execute("SELECT id,topic,title,days,status,current,last_sent,syllabus,score,answered FROM courses WHERE chat_id=? AND status IN ('active','paused') ORDER BY ts DESC LIMIT 1",(str(cid),)).fetchone();c.close();return r
    except Exception:return None

def _n40_start(cid,topic,days):
    days=max(2,min(30,int(days or 7)));topic=' '.join(str(topic).split())[:80]
    if _n40_course(cid):send_text(cid,'You already have a course running. /learn status to see it, /learn stop to end it first.');return
    send_text(cid,'📚 Building a %d-day plan for "%s"...'%(days,topic))
    def _go():
        raw=ask_ai(cid,_N40_SYLLABUS_PROMPT%(days,topic,days),remember=False,raw=True,timeout=120);spec=_n36_json_loose(raw)
        if not isinstance(spec,dict) or not spec.get('lessons'):send_text(cid,'My brain could not draft a clean plan just now. Try again in a minute.');return
        lessons=[{'title':str(l.get('title') or 'Lesson')[:60],'goal':str(l.get('goal') or '')[:120],'key_points':[str(x)[:90] for x in (l.get('key_points') or [])][:4]} for l in spec['lessons'] if isinstance(l,dict)][:days]
        if not lessons:send_text(cid,'The plan came back empty. Try a more specific topic.');return
        title=str(spec.get('title') or topic)[:60]
        c=_n35_conn();c.execute('INSERT INTO courses(chat_id,ts,topic,title,days,status,current,last_sent,syllabus) VALUES(?,?,?,?,?,?,?,?,?)',(str(cid),_n40_time.time(),topic,title,len(lessons),'active',0,0,_n40_json.dumps(lessons,ensure_ascii=False)));c.commit();cid_row=c.execute('SELECT last_insert_rowid()').fetchone()[0];c.close()
        send_text(cid,'📚 %s — %d lessons\n\n'%(title,len(lessons))+'\n'.join('%d. %s'%(i+1,l['title']) for i,l in enumerate(lessons))+'\n\nLesson 1 is coming now; then one lesson a day at %s IST. /learn next skips ahead, /learn pause holds.'%_n36_kv_get('n40_learn_time','19:00'))
        _n40_send_lesson(cid,cid_row)
    _n40_threading.Thread(target=_go,daemon=True,name='nemo-learn40').start()

def _n40_send_lesson(cid,course_id):
    c=_n35_conn();r=c.execute('SELECT topic,title,days,current,syllabus,status FROM courses WHERE id=?',(course_id,)).fetchone();c.close()
    if not r or r[5]!='active':return False
    topic,title,days,current,syl,status=r;lessons=_n40_json.loads(syl or '[]');idx=current
    if idx>=len(lessons):
        c=_n35_conn();sc=c.execute('SELECT score,answered FROM courses WHERE id=?',(course_id,)).fetchone();c.execute("UPDATE courses SET status='done' WHERE id=?",(course_id,));c.commit();c.close()
        send_text(cid,'🎓 Course complete: %s. Quiz score %d/%d. Say "teach me <topic> in <N> days" to start another.'%(title,sc[0],sc[1]));return False
    L=lessons[idx]
    raw=ask_ai(cid,_N40_LESSON_PROMPT%(idx+1,len(lessons),title,L['title'],L.get('goal','')),remember=False,raw=True,timeout=150);spec=_n36_json_loose(raw)
    if not isinstance(spec,dict) or not spec.get('explanation'):send_text(cid,'Could not draft lesson %d right now; I will retry at the next learn time. /learn next retries now.'%(idx+1));return False
    quiz=[q for q in (spec.get('quiz') or []) if isinstance(q,dict) and len(q.get('options') or [])==4][:3]
    kp=[str(x)[:90] for x in (spec.get('key_points') or [])][:5]
    body='📖 Lesson %d/%d — %s\n\n%s'%(idx+1,len(lessons),L['title'],str(spec.get('explanation'))[:1400])
    if spec.get('example'):body+='\n\n💡 Example: '+str(spec.get('example'))[:320]
    if kp:body+='\n\n🔑 '+'\n🔑 '.join(kp)
    send_text(cid,body)
    try:
        path,st=_n36_render_infographic({'title':L['title'],'subtitle':'%s · lesson %d of %d'%(title,idx+1,len(lessons)),'key_points':kp or L.get('key_points',[]),'numbers':[],'sections':[{'heading':'Example','line':str(spec.get('example') or '')[:130]}] if spec.get('example') else [],'takeaway':L.get('goal','')},title)
        if path:_n35_send_photo(cid,path,'🖼 Lesson card — '+L['title'])
    except Exception:pass
    c=_n35_conn();c.execute('INSERT OR REPLACE INTO lessons(course_id,idx,ts,title,content,quiz,answers) VALUES(?,?,?,?,?,?,?)',(course_id,idx,_n40_time.time(),L['title'],body,_n40_json.dumps(quiz,ensure_ascii=False),''));c.execute('UPDATE courses SET current=?,last_sent=? WHERE id=?',(idx+1,_n40_time.time(),course_id));c.commit();c.close()
    if quiz:_n40_send_quiz(cid,course_id,idx,0)
    try:
        if '_n30_profile' in globals() and _n30_profile(cid).get('visual_narration'):_n40_threading.Thread(target=speak,args=(cid,('Lesson %d. %s. '%(idx+1,L['title']))+str(spec.get('explanation'))[:500]),daemon=True).start()
    except Exception:pass
    return True

def _n40_send_quiz(cid,course_id,idx,qi):
    c=_n35_conn();r=c.execute('SELECT quiz FROM lessons WHERE course_id=? AND idx=?',(course_id,idx)).fetchone();c.close()
    quiz=_n40_json.loads(r[0]) if r and r[0] else []
    if qi>=len(quiz):return
    q=quiz[qi];rows=[[(('%s'%str(o)[:40]),'q:%d:%d:%d:%d'%(course_id,idx,qi,i))] for i,o in enumerate(q['options'])]
    send_text(cid,'❓ Quiz %d/%d: %s'%(qi+1,len(quiz),q['q']),kb=_n40_kb(rows))

def _n40_grade(cid,course_id,idx,qi,choice):
    c=_n35_conn();r=c.execute('SELECT quiz,answers FROM lessons WHERE course_id=? AND idx=?',(course_id,idx)).fetchone()
    if not r:c.close();return
    quiz=_n40_json.loads(r[0] or '[]');done=set(int(x) for x in (r[1] or '').split(',') if x)
    if qi in done or qi>=len(quiz):c.close();return
    q=quiz[qi];ok=int(choice)==int(q.get('answer',0))
    done.add(qi);c.execute('UPDATE lessons SET answers=? WHERE course_id=? AND idx=?',(','.join(str(x) for x in sorted(done)),course_id,idx))
    c.execute('UPDATE courses SET score=score+?,answered=answered+1 WHERE id=?',(1 if ok else 0,course_id));c.commit();c.close()
    send_text(cid,('✅ Correct. ' if ok else '❌ Not quite — the answer is "%s". '%str(q['options'][int(q.get('answer',0))])[:40])+str(q.get('why') or '')[:160])
    if qi+1<len(quiz):_n40_send_quiz(cid,course_id,idx,qi+1)
    else:
        c=_n35_conn();sc=c.execute('SELECT score,answered,current,days FROM courses WHERE id=?',(course_id,)).fetchone();c.close()
        if sc:send_text(cid,'📚 Lesson done. Running score %d/%d · %d of %d lessons delivered. Next one at %s IST, or /learn next.'%(sc[0],sc[1],sc[2],sc[3],_n36_kv_get('n40_learn_time','19:00')))

def _n40_learn_loop():
    while True:
        try:
            oid=OWNER.get('id');now=_n36_now() if '_n36_now' in globals() else _n40_dt.datetime.now()
            if oid and now.strftime('%H:%M')==str(_n36_kv_get('n40_learn_time','19:00')):
                r=_n40_course(oid)
                if r and r[4]=='active' and _n40_time.time()-float(r[6] or 0)>20*3600:_n40_send_lesson(oid,r[0])
        except Exception:pass
        _n40_time.sleep(50)

def _n40_learn_cmd(cid,arg):
    a=arg.strip();low=a.lower()
    if low in ('','status'):
        r=_n40_course(cid)
        if not r:send_text(cid,'No course running. Try: /learn Power BI in 10 days — or say "teach me Excel in 7 days".');return
        send_text(cid,'📚 %s (%s)\nLesson %d of %d delivered · quiz score %d/%d · learn time %s IST\n/learn next · /learn pause · /learn resume · /learn stop'%(r[2],r[4],r[5],r[3],r[8],r[9],_n36_kv_get('n40_learn_time','19:00')));return
    if low=='next':
        r=_n40_course(cid)
        if not r:send_text(cid,'No course running.');return
        if r[4]!='active':send_text(cid,'Course is paused — /learn resume first.');return
        send_text(cid,'📖 Preparing the next lesson...');_n40_threading.Thread(target=_n40_send_lesson,args=(cid,r[0]),daemon=True).start();return
    if low in ('pause','resume','stop'):
        r=_n40_course(cid)
        if not r:send_text(cid,'No course running.');return
        st={'pause':'paused','resume':'active','stop':'stopped'}[low]
        c=_n35_conn();c.execute('UPDATE courses SET status=? WHERE id=?',(st,r[0]));c.commit();c.close();send_text(cid,'📚 Course %s.'%st);return
    m=_n40_re.match(r'(?i)time\s+(\d{1,2}):(\d{2})$',low)
    if m:_n36_kv_set('n40_learn_time','%02d:%s'%(int(m.group(1)),m.group(2)));send_text(cid,'📚 Daily lesson time set to %02d:%s IST.'%(int(m.group(1)),m.group(2)));return
    m=_n40_re.match(r'(?i)^(.{2,80}?)\s+(?:in|over|for)\s+(\d{1,2})\s*days?$',a)
    if m:_n40_start(cid,m.group(1),int(m.group(2)));return
    if len(a)>=2:_n40_start(cid,a,7);return
    send_text(cid,'Use /learn <topic> in <N> days')

# ------------------------------- callbacks -------------------------------------
_N40_CB_PREV=handle_callback
def handle_callback(cq):
    try:
        cid=(cq.get('message') or {}).get('chat',{}).get('id');data=str(cq.get('data') or '')
        if data.startswith('n40:'):
            try:tg('answerCallbackQuery',callback_query_id=cq.get('id'))
            except Exception:pass
            if cid!=OWNER.get('id'):
                try:send_text(cid,'That menu is owner-only.')
                except Exception:pass
                return
            d=data[4:]
            if d.startswith('m:'):_n40_menu(cid,d[2:]);return
            if d.startswith('c:'):_n40_run(cid,d[2:]);return
            if d.startswith('q:'):
                p=d[2:].split(':')
                if len(p)==4:_n40_grade(cid,int(p[0]),int(p[1]),int(p[2]),int(p[3]))
                return
            return
    except Exception as e:
        try:_n210_log_fail(cid,'nemo40_callback',data,str(e))
        except Exception:pass
    return _N40_CB_PREV(cq)

# ------------------------------- dispatcher ------------------------------------
def _n40_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/menu','/m','/nemomenu'):_n40_menu(cid,'main');return True
    if low in ('/nemostatus','/nemo40','/allstatus'):send_text(cid,_n40_status(cid));return True
    if low.startswith('/learn'):_n40_learn_cmd(cid,txt[6:]);return True
    if low in ('/help','/help40','/newhelp','/commands'):
        if low!='/help':send_text(cid,_N40_HELP_CARD,kb=_n40_kb([[('🧭 Open menu','m:main')]]));return True
        return False
    if txt and not txt.startswith('/'):
        cmd=_n40_nl_route(cid,txt)
        if cmd:_n40_run(cid,cmd);return True
    return False

_N40_PREV_HANDLE=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();chat=(msg.get('chat') or {});low=txt.lower()
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id'):
            if low.startswith(('/menu','/nemostatus','/learn','/nemo40')):
                try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                except Exception:pass
                return
        if _n40_dispatch(msg):return
        if cid==OWNER.get('id') and low=='/help':
            r=_N40_PREV_HANDLE(msg)
            try:send_text(cid,_N40_HELP_CARD,kb=_n40_kb([[('🧭 Open menu','m:main')]]))
            except Exception:pass
            return r
    except Exception as e:
        try:_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo40_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N40_PREV_HANDLE(msg)

