# ------------------------------- regression / eval -----------------------------
_PRIME_REGRESSION_V40_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V40_PREV();extra=[]
    if isinstance(r,dict):r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v39-version',)]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v40-version',lambda:VERSION=='40.0')
    add('v40-menu-shape',lambda:all(isinstance(_n40_kb(v[1]).get('inline_keyboard'),list) for v in _N40_MENUS.values()))
    add('v40-nl-mind',lambda:_n40_nl_route(0,'show my mind map')=='/mind')
    add('v40-nl-daycard',lambda:_n40_nl_route(0,'day card')=='/daycard now')
    add('v40-nl-photos',lambda:_n40_nl_route(0,'find the photo of the plumber card')=='/photos the plumber card')
    add('v40-nl-quiet',lambda:_n40_nl_route(0,'quiet hours 11 to 7')=='/quiet 11:00-07:00')
    add('v40-nl-learn',lambda:_n40_nl_route(0,'teach me Power BI in 10 days')=='/learn Power BI in 10 days')
    add('v40-nl-none',lambda:_n40_nl_route(0,'what is the capital of France') is None)
    add('v40-learn-tables',lambda:(lambda c:(c.execute('SELECT COUNT(*) FROM courses').fetchone() is not None,c.close())[0])(_n35_conn()))
    add('v40-status-text',lambda:'NEMO STATUS' in _n40_status(OWNER.get('id')))
    add('v40-callback-hook',lambda:callable(handle_callback) and handle_callback is not _N40_CB_PREV)
    add('v40-owner-gate',lambda:callable(handle) and callable(_n40_dispatch))
    add('v40-authority-unchanged',lambda:(_v184_compile_control('x','run powershell delete all files') or {}).get('kind') not in ('shell','powershell','cmd','terminal'))
    if not isinstance(r,dict):
        return {'id':'RG40','version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_N40_EVAL_PREV=_n28_eval
def _n28_eval():
    rows=_N40_EVAL_PREV()
    rows.extend([{'name':'v40-command-center','ok':callable(_n40_menu),'detail':'one /menu, one /nemostatus, plain-language routes, Telegram command list'},
                 {'name':'v40-learn-mode','ok':callable(_n40_start),'detail':'daily lessons with lesson cards and tap quizzes'}])
    seen=set();out=[]
    for x in reversed(rows):
        n=str(x.get('name') or '')
        if n in seen:continue
        seen.add(n);out.append(x)
    return list(reversed(out))

_N40_MAIN_PREV=main
def main():
    try:_n40_threading.Thread(target=_n40_learn_loop,daemon=True,name='nemo-learn40').start()
    except Exception:pass
    try:_n40_threading.Thread(target=lambda:(_n40_time.sleep(20),_n40_register_commands()),daemon=True).start()
    except Exception:pass
    return _N40_MAIN_PREV()


# =============================================================================
# NEMO 41.0 — MEDIA ENGINE (fast, free video + audio)
#   One front door: /dl <link or search words> (aliases /d, "download …", "gaana
#   download karo …", "mp3 of <link>"). What makes it fast:
#     · parallel fragment download (8 connections) instead of one stream
#     · audio = best m4a/opus stream sent AS-IS via sendAudio (no ffmpeg transcode;
#       MP3 only when you say mp3)
#     · video = best stream that already fits Telegram's 50MB, height ladder
#       1080→720→480→360, sent via sendVideo (streamable, plays inline)
#     · too big? no re-encode: stream-copy SPLIT into ≤48MB parts, sent in order
#     · resend cache: the same link/mode again is delivered instantly from
#       Telegram's file_id — zero download
#     · live progress edits every ~3s; DRM refused honestly; your cookies+proxy used
#     · self-heal: extractor errors trigger one yt-dlp upgrade per day, then retry
#   Search: no link → "ytsearch1:" of your words. Playlist: add "playlist" (max 10, audio).
#   Uses the existing rails: owner-only, /browsercookies, /proxy, DRM list.
# =============================================================================
# NEMO 42.0 — FAMILY MODE
#   /family add <telegram id> <name> · /family remove <id> · /family list
#   Members get: unlimited friendly chat (no guest cap), their own /remind and
#   /todo, a SHARED family list (/list add milk · /list · /list done 2), and
#   "tell Gautam …" → relayed to you with their name. They never see your memory,
#   files, server, money or settings; owner-only commands stay owner-only.
#   Keys, connections, trading/shell/payment authority: UNCHANGED.
# =============================================================================
VERSION='42.0'
import re as _n41_re, os as _n41_os, time as _n41_time, json as _n41_json, hashlib as _n41_hashlib, subprocess as _n41_sp, threading as _n41_threading, glob as _n41_glob

_N41_DIR='/root/nemo_media'
try:_n41_os.makedirs(_N41_DIR,exist_ok=True)
except Exception:_N41_DIR='/tmp'
_N41_CAP=48*1024*1024

def _n41_init():
    c=_n35_conn()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS media_cache(key TEXT PRIMARY KEY, file_id TEXT, kind TEXT, title TEXT, size INTEGER, ts REAL);
    CREATE TABLE IF NOT EXISTS family(uid TEXT PRIMARY KEY, name TEXT, added REAL, active INTEGER DEFAULT 1);
    CREATE TABLE IF NOT EXISTS family_list(id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, by_name TEXT, item TEXT, done INTEGER DEFAULT 0);
    """)
    c.commit();c.close()
try:_n41_init()
except Exception:pass

# ------------------------------- request parsing -------------------------------
_N41_URL_RE=_n41_re.compile(r'https?://\S+')
_N41_NL_RE=_n41_re.compile(r"(?i)^\s*(?:nemo[,\s]*)?(?:please\s+)?(?:download|dl|save|get|fetch)\s+(?:me\s+)?(?:this\s+|the\s+|that\s+)?(?:video|audio|song|gaana|mp3|reel|clip|music|track)?\s*(?:of|from|for)?\s*(.+?)\s*(?:download\s*karo|dl\s*karo)?\s*$|^\s*(?:nemo[,\s]*)?(.+?)\s+(?:download|dl)\s*(?:karo|kar do|kardo)\s*$|^\s*(?:nemo[,\s]*)?(?:mp3|audio|song|gaana)\s+(?:of|from)\s+(https?://\S+)\s*$|^\s*(?:nemo[,\s]*)?(?:gaana|gana|song|video|audio|mp3|reel|clip)\s+(?:download|dl)\s*(?:karo|kar do|kardo)?\s+(.{2,200})$")
def _n41_parse(text):
    """→ (query_or_url, mode, playlist) or None. mode: video|audio|mp3"""
    t=' '.join(str(text or '').split())
    if not t:return None
    low=t.lower();mode='video'
    if _n41_re.search(r'\b(mp3)\b',low):mode='mp3'
    elif _n41_re.search(r'\b(audio|song|gaana|gana|music|track|sound)\b',low):mode='audio'
    playlist=bool(_n41_re.search(r'\bplaylist\b',low))
    m=_N41_URL_RE.search(t)
    if m:return (m.group(0).strip('<>"\''),mode,playlist)
    q=_n41_re.sub(r'(?i)\b(download|dl|save|get|fetch|me|this|the|that|video|audio|song|gaana|gana|mp3|reel|clip|music|track|of|from|for|karo|kar do|kardo|please|nemo|playlist)\b','',t)
    q=' '.join(q.split()).strip(' ,.:-')
    return (q,mode,playlist) if len(q)>=2 else None

def _n41_is_dl_order(text):
    t=str(text or '').strip()
    if t.startswith('/'):return False
    if not _N41_NL_RE.match(t):return False
    low=t.lower()
    if _n41_re.search(r'(?i)\b(to the server|onto the server|report|pdf|file from the server|/root/)\b',low):return False
    return True

# ------------------------------- helpers ---------------------------------------
def _n41_key(url,mode):return _n41_hashlib.sha1((mode+'|'+url).encode()).hexdigest()[:20]
def _n41_cache_get(key):
    try:
        c=_n35_conn();r=c.execute('SELECT file_id,kind,title FROM media_cache WHERE key=?',(key,)).fetchone();c.close();return r
    except Exception:return None
def _n41_cache_put(key,file_id,kind,title,size):
    try:
        c=_n35_conn();c.execute('INSERT OR REPLACE INTO media_cache VALUES(?,?,?,?,?,?)',(key,file_id,kind,title[:200],int(size or 0),_n41_time.time()));c.commit();c.close()
    except Exception:pass

def _n41_base_cmd():
    cmd=['yt-dlp','--no-warnings','--newline','--no-playlist','-N','8','--concurrent-fragments','8','--retries','3','--fragment-retries','5','--socket-timeout','20','--no-mtime']
    if _n41_os.path.exists('/root/nemo_cookies.txt'):cmd+=['--cookies','/root/nemo_cookies.txt']
    try:
        px=net_proxy()
        if px:cmd+=['--proxy',px]
    except Exception:pass
    return cmd

def _n41_fmt(mode):
    if mode=='audio':return ['-f','ba[ext=m4a][filesize<48M]/ba[ext=m4a]/ba[ext=webm][filesize<48M]/ba/b']
    if mode=='mp3':return ['-f','ba/b','-x','--audio-format','mp3','--audio-quality','5']
    return ['-f',('b[ext=mp4][filesize<48M]/bv*[ext=mp4][height<=1080][filesize<40M]+ba[ext=m4a]/b[height<=720][ext=mp4]/bv*[height<=720]+ba/b[height<=480]/b'),'--merge-output-format','mp4']

def _n41_probe(path):
    try:
        out=_n41_sp.run(['ffprobe','-v','error','-show_entries','format=duration,bit_rate','-of','json',path],capture_output=True,text=True,timeout=30).stdout
        j=_n41_json.loads(out or '{}').get('format',{});return float(j.get('duration') or 0),float(j.get('bit_rate') or 0)
    except Exception:return 0.0,0.0

def _n41_split(path):
    """Stream-copy split into ≤48MB parts (no re-encode). Returns list of part paths or []."""
    size=_n41_os.path.getsize(path);dur,br=_n41_probe(path)
    if not dur:return []
    parts=int(size//_N41_CAP)+1;seg=max(20,int(dur/parts)-2)
    base,ext=_n41_os.path.splitext(path);tmpl=base+'_part%02d'+ext
    try:
        r=_n41_sp.run(['ffmpeg','-y','-loglevel','error','-i',path,'-c','copy','-map','0','-f','segment','-segment_time',str(seg),'-reset_timestamps','1',tmpl],capture_output=True,text=True,timeout=600)
    except Exception:return []
    out=sorted(_n41_glob.glob(base+'_part*'+ext))
    return out if out and all(_n41_os.path.getsize(p)<=50*1024*1024 for p in out) else out[:0]

def _n41_send_media(cid,path,mode,title,caption=''):
    """sendVideo/sendAudio (streamable, inline) → returns telegram file_id or ''"""
    import requests as _rq
    fname=_n41_os.path.basename(path)
    try:
        with open(path,'rb') as f:
            if mode=='video':
                r=_rq.post(TG+'/sendVideo',data={'chat_id':cid,'caption':caption[:1000],'supports_streaming':'true'},files={'video':(fname,f)},timeout=300).json()
                fid=(((r.get('result') or {}).get('video') or {}).get('file_id')) if r.get('ok') else ''
            else:
                r=_rq.post(TG+'/sendAudio',data={'chat_id':cid,'caption':caption[:1000],'title':title[:64]},files={'audio':(fname,f)},timeout=300).json()
                fid=(((r.get('result') or {}).get('audio') or {}).get('file_id')) if r.get('ok') else ''
        if fid:
            try:LASTFILE[cid]=path
            except Exception:pass
            return fid
    except Exception:pass
    try:
        if _send_file(cid,path,caption or title):return 'doc'
    except Exception:pass
    return ''

def _n41_resend(cid,file_id,kind,title):
    try:
        method='sendVideo' if kind=='video' else 'sendAudio';field='video' if kind=='video' else 'audio'
        r=tg(method,**{'chat_id':cid,field:file_id,'caption':'⚡ '+title[:900]+'\n(instant — from cache)'})
        return bool(r.get('ok'))
    except Exception:return False

_N41_HEAL={'day':''}
def _n41_self_heal(err):
    el=str(err or '').lower()
    if not any(w in el for w in ('unable to extract','signature','nsig','http error 403','unsupported url','player response','n challenge')):return False
    today=_n41_time.strftime('%Y-%m-%d')
    if _N41_HEAL['day']==today:return False
    _N41_HEAL['day']=today
    try:_n41_sp.run(['python3','-m','pip','install','-U','yt-dlp','--break-system-packages','-q'],capture_output=True,timeout=240)
    except Exception:pass
    return True

# ------------------------------- the download ----------------------------------
def _n41_download(cid,target,mode='video',playlist=False,_retry=False):
    if cid!=OWNER.get('id'):send_text(cid,'Only the Boss can download media.');return
    is_url=bool(_N41_URL_RE.match(target))
    if is_url and _VID_DRM.search(target):
        send_text(cid,"That's DRM-protected paid streaming — encrypted, can't be downloaded (and I won't break the DRM). Any non-DRM site works.");return
    if not _imp('yt_dlp',notify=False):
        send_text(cid,'🔧 Installing the downloader (first time)...');auto_install('yt_dlp',notify=False)
    url=target if is_url else 'ytsearch1:'+target
    key=_n41_key(url,mode+('-pl' if playlist else ''))
    if not playlist:
        hit=_n41_cache_get(key)
        if hit and hit[0] and hit[0]!='doc' and _n41_resend(cid,hit[0],hit[1],hit[2]):return
    tag=key[:10];tmpl=_n41_os.path.join(_N41_DIR,'m_'+tag+('_%(playlist_index)02d' if playlist else '')+'.%(ext)s')
    label={'video':'video','audio':'audio','mp3':'MP3'}[mode]
    ph=tg('sendMessage',chat_id=cid,text='📥 Getting the %s%s%s...'%(label,' (playlist, up to 10)' if playlist else '',(' from '+_short_host(url)) if is_url else (' for "%s"'%target[:60])))
    mid=(ph.get('result') or {}).get('message_id')
    cmd=_n41_base_cmd()+_n41_fmt(mode)+['-o',tmpl,'--print','after_move:filepath','--print','title']
    if playlist:cmd=[c for c in cmd if c!='--no-playlist']+['--yes-playlist','--playlist-end','10']
    t0=_n41_time.time();last=0;title='';stderr_tail=''
    try:
        p=_n41_sp.Popen(cmd+[url],stdout=_n41_sp.PIPE,stderr=_n41_sp.PIPE,text=True,bufsize=1)
        titles=[]
        def _drain():
            nonlocal stderr_tail
            for line in p.stderr:stderr_tail=(stderr_tail+line)[-1500:]
        _n41_threading.Thread(target=_drain,daemon=True).start()
        for line in p.stdout:
            line=line.strip()
            m=_n41_re.search(r'\[download\]\s+([\d.]+)%.*?of\s+~?\s*([\d.]+\w+)(?:.*?at\s+([\d.]+\w+/s))?',line)
            if m and mid and _n41_time.time()-last>3:
                last=_n41_time.time()
                try:tg('editMessageText',chat_id=cid,message_id=mid,text='📥 %s %s%% of %s%s'%(label,m.group(1),m.group(2),(' · '+m.group(3)) if m.group(3) else ''))
                except Exception:pass
            elif line and not line.startswith('[') and not _n41_os.path.sep in line and len(line)<200:titles.append(line)
        p.wait(timeout=1200);title=(titles[0] if titles else '')[:120]
    except Exception as e:
        try:p.kill()
        except Exception:pass
        deliver(cid,mid,'Downloader error: '+type(e).__name__+': '+str(e)[:150]);return
    files=sorted([f for f in _n41_glob.glob(_n41_os.path.join(_N41_DIR,'m_'+tag+'*')) if not f.endswith(('.part','.ytdl')) and '_part' not in f],key=lambda f:_n41_os.path.getmtime(f))
    if not files:
        el=stderr_tail.lower()
        if not _retry and _n41_self_heal(stderr_tail):
            deliver(cid,mid,'The site changed something — I updated my downloader, retrying once...');return _n41_download(cid,target,mode,playlist,_retry=True)
        if any(w in el for w in ('sign in','log in','login','private','members-only','cookies','not a bot')):tip='\nThat one needs your logged-in session: export cookies.txt and send /browsercookies.'
        elif any(w in el for w in ('drm','encrypted','protected')):tip='\nThe stream is DRM-encrypted, so it cannot be downloaded.'
        elif 'no video results' in el or 'did not return any data' in el:tip='\nNothing found for that search. Try more specific words or paste the link.'
        else:tip=('\n'+stderr_tail[-300:]) if stderr_tail else ''
        deliver(cid,mid,'Could not download that.'+tip);return
    deliver(cid,mid,'📦 Downloaded in %.0fs — sending %d file%s...'%(_n41_time.time()-t0,len(files),'' if len(files)==1 else 's'))
    kind='video' if mode=='video' else 'audio'
    for i,path in enumerate(files):
        size=_n41_os.path.getsize(path);ttl=title or _n41_os.path.splitext(_n41_os.path.basename(path))[0]
        cap=('🎬 ' if kind=='video' else '🎧 ')+ttl+(' (%d/%d)'%(i+1,len(files)) if len(files)>1 else '')+' · %.1f MB'%(size/1e6)
        if size<=_N41_CAP:
            fid=_n41_send_media(cid,path,kind,ttl,cap)
            if fid and not playlist:_n41_cache_put(key,fid,kind,ttl,size)
            continue
        parts=_n41_split(path)
        if parts:
            send_text(cid,'✂️ %.0f MB is over Telegram\'s limit — sending as %d parts (no quality loss).'%(size/1e6,len(parts)))
            for j,pp in enumerate(parts):_n41_send_media(cid,pp,kind,ttl,cap+' · part %d/%d'%(j+1,len(parts)))
        else:
            send_text(cid,'📦 %.0f MB is over Telegram\'s 50MB limit and could not be split here. Saved on the server: %s'%(size/1e6,path))
    try:
        for f in _n41_glob.glob(_n41_os.path.join(_N41_DIR,'m_*')):
            if _n41_time.time()-_n41_os.path.getmtime(f)>2*86400:_n41_os.remove(f)
    except Exception:pass

def _n41_menu(cid,target):
    rows=[[('🎬 Video','dl:v:'),('🎧 Audio (fast)','dl:a:'),('🎵 MP3','dl:m:')]]
    kb={'inline_keyboard':[[{'text':t,'callback_data':'n41:'+d+target[:50]} for t,d in row] for row in rows]}
    send_text(cid,'What do you want from: '+target[:150],kb=kb)

# ------------------------------- FAMILY MODE -----------------------------------
def _n42_members():
    try:
        c=_n35_conn();rows=c.execute('SELECT uid,name FROM family WHERE active=1').fetchall();c.close();return {str(r[0]):r[1] for r in rows}
    except Exception:return {}
def _n42_is_member(cid):return str(cid) in _n42_members()
def _n42_name(cid):return _n42_members().get(str(cid),'')

def _n42_list_text():
    try:
        c=_n35_conn();rows=c.execute('SELECT id,by_name,item,done FROM family_list ORDER BY done,id DESC LIMIT 40').fetchall();c.close()
    except Exception:rows=[]
    if not rows:return '🛒 Family list is empty. "/list add milk" adds an item.'
    return '🛒 FAMILY LIST\n'+'\n'.join('%s #%d %s  (%s)'%('✅' if r[3] else '▫️',r[0],r[2],r[1]) for r in rows)+'\n\n/list add <item> · /list done <id> · /list clear'

def _n42_list_cmd(cid,who,arg):
    a=arg.strip();low=a.lower()
    if low.startswith('add '):
        c=_n35_conn();c.execute('INSERT INTO family_list(ts,by_name,item) VALUES(?,?,?)',(_n41_time.time(),who,a[4:].strip()[:120]));c.commit();c.close()
        send_text(cid,'🛒 Added: '+a[4:].strip()[:120]);_n42_notify_others(cid,'🛒 %s added "%s" to the family list.'%(who,a[4:].strip()[:80]));return
    m=_n41_re.match(r'done\s+(\d+)',low)
    if m:
        c=_n35_conn();c.execute('UPDATE family_list SET done=1 WHERE id=?',(int(m.group(1)),));c.commit();c.close();send_text(cid,'✅ Marked #%s done.'%m.group(1));return
    if low=='clear':
        c=_n35_conn();c.execute('DELETE FROM family_list WHERE done=1');c.commit();c.close();send_text(cid,'🧹 Cleared the done items.');return
    send_text(cid,_n42_list_text())

def _n42_notify_others(from_cid,text):
    for uid in list(_n42_members().keys())+[str(OWNER.get('id'))]:
        if uid and uid!=str(from_cid):
            try:send_text(int(uid),text)
            except Exception:pass

_N42_TELL_RE=_n41_re.compile(r"(?i)^\s*(?:nemo[,\s]*)?(?:tell|inform|message|msg|relay to|bata do|bol do|keh do)\s+(?:the\s+)?(?:boss|owner|gautam|papa|dad|him|usko|unko)\s*[:,-]?\s*(.{2,600})$")

def _n42_family_handle(msg):
    """Runs for allow-listed family members only. Returns True when handled."""
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower();who=_n42_name(cid) or 'family'
    if low.startswith('/list'):_n42_list_cmd(cid,who,txt[5:]);return True
    m=_N42_TELL_RE.match(txt)
    if m:
        try:send_text(OWNER.get('id'),'👨‍👩‍👧 Message from %s: %s'%(who,m.group(1).strip()))
        except Exception:pass
        send_text(cid,'✅ Passed on to him.');return True
    if low in ('/start','/help'):
        send_text(cid,'Hi %s! I am Nemo. You can chat with me, set reminders (/remind), keep your to-dos (/todo), use the family list (/list) and say "tell Gautam …" to relay a message.'%who);return True
    if low.startswith(('/remind','/todo','/remember','/forget','/timer','/weather','/translate')):return False   # base handles, per-chat
    if txt.startswith('/'):
        send_text(cid,'That command is for the owner. You can chat, /remind, /todo, /list, or "tell Gautam …".');return True
    # unlimited friendly chat — bypass the guest cap by using the owner-less fast core-free path
    try:
        try:UCOUNT.pop(cid,None)
        except Exception:pass
        ans=ask_ai(cid,txt,remember=False,timeout=90,ground='You are chatting with %s, a family member of your owner. Be warm, brief and helpful. Never reveal the owner\'s private memory, files, server, money or settings.'%who)
        send_text(cid,ans or 'Sorry, my brain is busy — try again in a minute.')
    except Exception:send_text(cid,'Sorry, my brain is busy — try again in a minute.')
    return True

def _n42_family_cmd(cid,arg):
    a=arg.strip();low=a.lower()
    m=_n41_re.match(r'add\s+(\d{3,15})\s+(.{1,40})$',a)
    if m:
        c=_n35_conn();c.execute('INSERT OR REPLACE INTO family(uid,name,added,active) VALUES(?,?,?,1)',(m.group(1),m.group(2).strip(),_n41_time.time()));c.commit();c.close()
        send_text(cid,'👨‍👩‍👧 Added %s (%s). They can chat, /remind, /todo, /list and "tell Gautam …".'%(m.group(2).strip(),m.group(1)));return
    m=_n41_re.match(r'(?:remove|rm|del)\s+(\d{3,15})$',low)
    if m:
        c=_n35_conn();c.execute('UPDATE family SET active=0 WHERE uid=?',(m.group(1),));c.commit();c.close();send_text(cid,'Removed %s from family.'%m.group(1));return
    mem=_n42_members()
    send_text(cid,('👨‍👩‍👧 FAMILY (%d)\n'%len(mem)+'\n'.join('• %s — %s'%(n,u) for u,n in mem.items()) if mem else 'No family members yet.')+'\n\n/family add <telegram id> <name> · /family remove <id>\n(They can find their id by sending /start to me — I show it in the guest greeting, or use @userinfobot.)')

# ------------------------------- callbacks / dispatcher ------------------------
_N41_CB_PREV=handle_callback
def handle_callback(cq):
    try:
        cid=(cq.get('message') or {}).get('chat',{}).get('id');data=str(cq.get('data') or '')
        if data.startswith('n41:dl:'):
            try:tg('answerCallbackQuery',callback_query_id=cq.get('id'))
            except Exception:pass
            if cid!=OWNER.get('id'):return
            mode={'v':'video','a':'audio','m':'mp3'}.get(data[7:8],'video');target=data[9:]
            _n41_threading.Thread(target=_n41_download,args=(cid,target,mode,False),daemon=True,name='nemo-media41').start();return
    except Exception:pass
    return _N41_CB_PREV(cq)

def _n41_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/nemo41','/media','/mediastatus'):
        try:
            c=_n35_conn();n=c.execute('SELECT COUNT(*) FROM media_cache').fetchone()[0];c.close()
        except Exception:n=0
        send_text(cid,'NEMO 41.0 — MEDIA ENGINE\n━━━━━━━━━━━━━━━━━━━━\n/dl <link or words> [audio|mp3|playlist]\nParallel fragments · no-transcode audio · fit-to-50MB video · stream-copy split · instant resend cache (%d cached)\nCookies: %s · proxy: %s · ffmpeg: %s\n"download …", "gaana download karo …", "mp3 of <link>" also work'%(n,'yes' if _n41_os.path.exists('/root/nemo_cookies.txt') else 'no',net_proxy() or 'none',('yes' if _n41_sp.run(['which','ffmpeg'],capture_output=True).returncode==0 else 'NO — apt install ffmpeg for splitting/mp3')));return True
    if low.startswith(('/dl ','/d ','/dl\n')) or low in ('/dl','/d'):
        arg=txt.split(' ',1)[1].strip() if ' ' in txt else ''
        if not arg:send_text(cid,'Use /dl <link or search words> — add "audio", "mp3" or "playlist" as needed.');return True
        p=_n41_parse(arg)
        if not p:send_text(cid,'Give me a link or a few words to search.');return True
        target,mode,pl=p
        if _N41_URL_RE.match(target) and not _n41_re.search(r'\b(audio|mp3|video|song|gaana|playlist)\b',low):_n41_menu(cid,target);return True
        _n41_threading.Thread(target=_n41_download,args=(cid,target,mode,pl),daemon=True,name='nemo-media41').start();return True
    if low.startswith('/family'):_n42_family_cmd(cid,txt[7:]);return True
    if low.startswith('/list'):_n42_list_cmd(cid,'Gautam' if not _n35_get_fact(cid,'name') else _n35_get_fact(cid,'name'),txt[5:]);return True
    if txt and not txt.startswith('/') and _n41_is_dl_order(txt):
        p=_n41_parse(txt)
        if p:
            target,mode,pl=p;_n41_threading.Thread(target=_n41_download,args=(cid,target,mode,pl),daemon=True,name='nemo-media41').start();return True
    return False

_N41_PREV_HANDLE=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');chat=(msg.get('chat') or {});txt=(msg.get('text') or '').strip()
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id'):
            if _n42_is_member(cid) and txt:
                if _n42_family_handle(msg):return
            elif txt.lower().startswith(('/dl','/family','/media','/nemo41','/list')):
                try:send_text(cid,'That command is owner-only. You can still chat with me normally.')
                except Exception:pass
                return
        if _n41_dispatch(msg):return
    except Exception as e:
        try:_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo41_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N41_PREV_HANDLE(msg)

