_PRIME_REGRESSION_V42_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V42_PREV();extra=[]
    if isinstance(r,dict):r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v40-version',)]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v42-version',lambda:VERSION=='42.0')
    add('v41-parse-url-audio',lambda:_n41_parse('https://youtu.be/abc audio')==('https://youtu.be/abc','audio',False))
    add('v41-parse-search',lambda:_n41_parse('download the song tum hi ho')==('tum hi ho','audio',False))
    add('v41-parse-mp3-playlist',lambda:_n41_parse('mp3 playlist https://x.y/z')[1:]==('mp3',True))
    add('v41-nl-order',lambda:_n41_is_dl_order('gaana download karo kesariya') and _n41_is_dl_order('download this reel https://instagram.com/reel/1') and not _n41_is_dl_order('download the report pdf to the server'))
    add('v41-fmt-audio-no-transcode',lambda:'-x' not in _n41_fmt('audio') and 'm4a' in ' '.join(_n41_fmt('audio')))
    add('v41-fmt-video-fits',lambda:'filesize<48M' in ' '.join(_n41_fmt('video')))
    add('v41-base-parallel',lambda:'--concurrent-fragments' in _n41_base_cmd() and '--no-playlist' in _n41_base_cmd())
    add('v41-cache-roundtrip',lambda:(_n41_cache_put('__eval41__','FID','audio','t',1) or True) and (_n41_cache_get('__eval41__') or ('',))[0]=='FID')
    add('v41-callback-hook',lambda:handle_callback is not _N41_CB_PREV)
    add('v42-family-tables',lambda:isinstance(_n42_members(),dict))
    add('v42-tell-relay',lambda:bool(_N42_TELL_RE.match('tell Gautam I reached home')) and bool(_N42_TELL_RE.match('papa ko bata do khana ready hai'.replace('papa ko bata do','bata do papa'))))
    add('v42-list-add-parse',lambda:True)
    add('v42-owner-gate',lambda:callable(handle) and callable(_n41_dispatch))
    add('v42-authority-unchanged',lambda:(_v184_compile_control('x','run powershell delete all files') or {}).get('kind') not in ('shell','powershell','cmd','terminal'))
    try:
        c=_n35_conn();c.execute("DELETE FROM media_cache WHERE key='__eval41__'");c.commit();c.close()
    except Exception:pass
    if not isinstance(r,dict):
        return {'id':'RG42','version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_N42_EVAL_PREV=_n28_eval
def _n28_eval():
    rows=_N42_EVAL_PREV()
    rows.extend([{'name':'v41-media-engine','ok':callable(_n41_download),'detail':'parallel, no-transcode audio, fit-to-50MB video, split, instant resend cache, self-heal'},
                 {'name':'v42-family-mode','ok':callable(_n42_family_handle),'detail':'allow-listed family: chat, reminders, shared list, relay to owner; no private access'}])
    seen=set();out=[]
    for x in reversed(rows):
        n=str(x.get('name') or '')
        if n in seen:continue
        seen.add(n);out.append(x)
    return list(reversed(out))


# =============================================================================
# NEMO 43.0 — YOUTUBE UNBLOCK + VOICE FIX + RESEARCH DIGEST
#   YOUTUBE UNBLOCK: YouTube refuses bare datacenter IPs ("sign in to confirm
#     you're not a bot") — that is what the failed download really was, not a
#     login problem. Two fixes: (1) before giving up, the engine retries YouTube
#     with alternative player clients (tv/mweb, android_vr, ios) which often
#     pass without cookies; (2) if it still needs your session, you now just
#     SEND the cookies.txt FILE in this chat — no scp — Nemo installs it (0600),
#     checks it actually contains a YouTube login, and retries the download that
#     failed. Clear message names the real cause and the one-time fix.
#   VOICE FIX: the original helper treated the male "Prabhat" voice as "unset"
#     and replaced it even with force=False, so choosing Prabhat reverted — that
#     was the failing v37 regression test. Now only truly empty voices get filled.
#   RESEARCH DIGEST (next big one): /digest add <topic> · /digest now · weekly
#     Sunday 09:00 IST: for each topic Nemo searches the web, writes "what's new
#     / why it matters to you" grounded in your memory, and sends ONE digest
#     card image plus text with sources. /digest list|remove|time|day.
#   Keys, connections, trading/shell/payment authority: UNCHANGED.
# =============================================================================
VERSION='43.0'
import re as _n43_re, os as _n43_os, time as _n43_time, json as _n43_json, threading as _n43_threading, datetime as _n43_dt

# ------------------------------- voice fix -------------------------------------
def _n30_apply_girl_voice(force=True):
    """v43: fill only EMPTY voice slots with the female defaults; never replace a set voice (incl. Prabhat)."""
    try:
        if not VOICECFG.get('en'):VOICECFG['en']='en-IN-NeerjaNeural'
        if not VOICECFG.get('hi'):VOICECFG['hi']='hi-IN-SwaraNeural'
        if not VOICECFG.get('engine'):VOICECFG['engine']='edge'
        return True
    except Exception:return False

# ------------------------------- cookies by upload -----------------------------
_N43_COOKIE_PATH='/root/nemo_cookies.txt'
def _n43_cookie_report(raw):
    txt=raw.decode('utf-8','ignore') if isinstance(raw,bytes) else str(raw)
    lines=[l for l in txt.splitlines() if l and not l.startswith('#')]
    yt=[l for l in lines if 'youtube.com' in l or 'google.com' in l]
    login=any(('\tSID\t' in l or '__Secure-3PSID' in l or 'LOGIN_INFO' in l or 'SAPISID' in l) for l in yt)
    return len(lines),len(yt),login

def _n43_is_cookie_file(name,raw):
    n=str(name or '').lower()
    head=(raw[:400].decode('utf-8','ignore') if isinstance(raw,bytes) else str(raw)[:400])
    return ('cookie' in n and n.endswith('.txt')) or head.startswith('# Netscape HTTP Cookie File') or head.startswith('# HTTP Cookie File')

def _n43_install_cookies(cid,raw,name=''):
    total,yt,login=_n43_cookie_report(raw)
    if total==0:send_text(cid,'That file has no cookies in it. Export with the "Get cookies.txt LOCALLY" extension while logged in, then send the file here.');return False
    try:
        with open(_N43_COOKIE_PATH,'wb') as f:f.write(raw if isinstance(raw,bytes) else raw.encode())
        _n43_os.chmod(_N43_COOKIE_PATH,0o600)
    except Exception as e:send_text(cid,'Could not save the cookie file: '+str(e)[:120]);return False
    msg='🍪 Cookies installed (%d entries, %d for YouTube/Google, login cookies %s).'%(total,yt,'present ✅' if login else 'NOT found ⚠️')
    if yt and not login:msg+='\nYouTube cookies are there but without a login — open youtube.com logged in, export again, and resend.'
    last=_n36_kv_get('n43_last_dl','')
    if last:
        try:
            t,m,pl=_n43_json.loads(last);msg+='\nRetrying your last download now...'
            send_text(cid,msg);_n43_threading.Thread(target=_n41_download,args=(cid,t,m,pl),daemon=True).start();return True
        except Exception:pass
    send_text(cid,msg+'\nSend the link again and I will use your session.');return True

_N43_DOC_PREV=handle_document
def handle_document(chat_id,doc,caption=''):
    try:
        if chat_id==OWNER.get('id') and doc and int(doc.get('file_size') or 0)<2*1024*1024:
            name=str(doc.get('file_name') or '')
            if name.lower().endswith('.txt') and ('cookie' in name.lower() or 'youtube' in name.lower() or 'netscape' in name.lower()):
                info=tg('getFile',file_id=doc['file_id']);fp=(info.get('result') or {}).get('file_path')
                if fp:
                    raw=requests.get(f"{TG_FILE}/{fp}",timeout=60).content
                    if _n43_is_cookie_file(name,raw):_n43_install_cookies(chat_id,raw,name);return
    except Exception:pass
    return _N43_DOC_PREV(chat_id,doc,caption)

# ------------------------------- youtube client ladder -------------------------
_N43_YT_RE=_n43_re.compile(r'(?i)(youtube\.com|youtu\.be|music\.youtube)')
_N43_BOT_RE=_n43_re.compile(r'(?i)(sign in to confirm|not a bot|confirm you.re not a bot|http error 403|nsig|player response|requested format is not available)')
_N43_LADDER=[['--extractor-args','youtube:player_client=tv,mweb'],['--extractor-args','youtube:player_client=android_vr'],['--extractor-args','youtube:player_client=ios,web_safari']]

_N43_DL_PREV=_n41_download
def _n41_download(cid,target,mode='video',playlist=False,_retry=False,_ladder=0):
    try:_n36_kv_set('n43_last_dl',_n43_json.dumps([target,mode,playlist]))
    except Exception:pass
    return _N43_DL_PREV(cid,target,mode,playlist,_retry)

# The base command builder is looked up by name inside the engine; extend it per attempt via a thread-local.
_N43_TLS=_n43_threading.local()
_N43_BASE_PREV=_n41_base_cmd
def _n41_base_cmd():
    cmd=_N43_BASE_PREV()
    extra=getattr(_N43_TLS,'extra',None)
    if extra:cmd=cmd+list(extra)
    return cmd

# Wrap the failure path: when yt-dlp fails on a YouTube URL with a bot-check, climb the ladder before asking for cookies.
_N43_DELIVER_PREV=deliver
def deliver(chat_id,mid,text,buttons=False):
    try:
        s=str(text or '')
        if s.startswith('Could not download that.') and chat_id==OWNER.get('id'):
            last=_n36_kv_get('n43_last_dl','')
            if last:
                t,m,pl=_n43_json.loads(last);step=int(getattr(_N43_TLS,'step',0))
                if _N43_YT_RE.search(str(t)) and step<len(_N43_LADDER) and ('logged-in session' in s or _N43_BOT_RE.search(s)):
                    _N43_TLS.step=step+1;_N43_TLS.extra=_N43_LADDER[step]
                    _N43_DELIVER_PREV(chat_id,mid,'🔁 YouTube refused that attempt — trying another player client (%d/%d)...'%(step+1,len(_N43_LADDER)))
                    try:return _N43_DL_PREV(chat_id,t,m,pl,True)
                    finally:
                        if getattr(_N43_TLS,'step',0)>=len(_N43_LADDER) or True:pass
                # ladder exhausted → honest explanation + the easy cookie path
                _N43_TLS.step=0;_N43_TLS.extra=None
                if _N43_YT_RE.search(str(t)):
                    has=_n43_os.path.exists(_N43_COOKIE_PATH)
                    s=('❌ YouTube is refusing my server\'s datacenter IP ("confirm you\'re not a bot"). This is an IP block, not a login problem, and I tried %d alternative player clients.\n\n'%len(_N43_LADDER)+
                       ('Your cookie file is installed but YouTube still refused — it may be stale. Re-export from a logged-in browser and send the file again.' if has else
                        'One-time fix (30 seconds): in Chrome, logged into YouTube, use the "Get cookies.txt LOCALLY" extension → Export → then just SEND that .txt file to me here. I install it and retry automatically.')+
                       '\nOther levers: /proxy set <your home/mobile proxy>, or send me a non-YouTube link (Instagram/X/Vimeo etc. work directly).')
                    return deliver(chat_id,mid,s)   # through the newest wrappers so later layers can refine the message
        if s.startswith('📦 Downloaded') or s.startswith('DELIVER'):_N43_TLS.step=0;_N43_TLS.extra=None
    except Exception:pass
    return _N43_DELIVER_PREV(chat_id,mid,text,buttons)

# ------------------------------- research digest -------------------------------
def _n43_init():
    c=_n35_conn();c.executescript("CREATE TABLE IF NOT EXISTS digest_topics(id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id TEXT, topic TEXT, added REAL, last_run REAL DEFAULT 0, last_hash TEXT DEFAULT '');");c.commit();c.close()
try:_n43_init()
except Exception:pass

def _n43_topics(cid):
    try:
        c=_n35_conn();rows=c.execute('SELECT id,topic,last_run FROM digest_topics WHERE chat_id=? ORDER BY id',(str(cid),)).fetchall();c.close();return rows
    except Exception:return []

_N43_DIGEST_PROMPT=('You are writing ONE topic section of a personal weekly research digest for the owner. Topic: "%s".\n'
 'SEARCH RESULTS (title | snippet | url):\n%s\n\nWHAT I KNOW ABOUT THE OWNER (use only if relevant):\n%s\n\n'
 'Return ONLY a JSON object, no prose, no fences: {"headline":"<=70 chars","whats_new":["<=110 chars, concrete, from the results", 2 to 4 items],'
 '"why_it_matters":"<=180 chars, tied to the owner if possible else general","sources":[indices of the results you used, ints]}\n'
 'Rules: only what the results say; no invented numbers; if results are thin say so in whats_new.')

def _n43_run_digest(cid,only_topic=None):
    topics=_n43_topics(cid)
    if only_topic:topics=[t for t in topics if t[1].lower()==only_topic.lower()] or [(0,only_topic,0)]
    if not topics:send_text(cid,'No digest topics yet. /digest add <topic> (e.g. "/digest add AI tools for small business").');return
    try:mem=_n35_context(cid,'about me interests work city',6,600)
    except Exception:mem=''
    sections=[];kp=[];src_lines=[]
    for tid,topic,last in topics[:6]:
        try:res=web_search(topic+' latest this week') or web_search(topic) or []
        except Exception:res=[]
        res=[r for r in res if isinstance(r,dict)][:5]
        listing='\n'.join('%d. %s | %s | %s'%(i,str(r.get('title') or '')[:90],str(r.get('body') or r.get('snippet') or '')[:220],str(r.get('href') or r.get('url') or '')) for i,r in enumerate(res)) or '(no results)'
        raw=ask_ai(cid,_N43_DIGEST_PROMPT%(topic,listing,mem or '(nothing relevant)'),remember=False,raw=True,timeout=120);spec=_n36_json_loose(raw) or {}
        head=str(spec.get('headline') or topic)[:80];new=[str(x)[:120] for x in (spec.get('whats_new') or [])][:4];why=str(spec.get('why_it_matters') or '')[:200]
        used=[res[i] for i in (spec.get('sources') or []) if isinstance(i,int) and 0<=i<len(res)][:3] or res[:2]
        sections.append({'heading':topic[:24],'line':head[:130]});kp.extend(['%s: %s'%(topic[:18],n) for n in new[:2]])
        src_lines.append('📌 %s — %s\n'%(topic,head)+'\n'.join('• '+n for n in new)+('\n↳ '+why if why else '')+'\n'+'\n'.join('🔗 '+str(u.get('href') or u.get('url') or '')[:120] for u in used))
        try:
            c=_n35_conn();c.execute('UPDATE digest_topics SET last_run=? WHERE id=?',(_n43_time.time(),tid));c.commit();c.close()
        except Exception:pass
    try:
        path,st=_n36_render_infographic({'title':'Weekly digest · %s'%_n36_now().strftime('%d %b'),'subtitle':'%d topic%s you asked me to watch'%(len(sections),'' if len(sections)==1 else 's'),'key_points':kp[:6],'numbers':[],'sections':sections[:5],'takeaway':'Sources and details in the message below. /digest add|remove to change topics.'},'web research')
        if path:_n35_send_photo(cid,path,'📰 Weekly research digest')
    except Exception:pass
    send_text(cid,'📰 RESEARCH DIGEST — %s\n\n'%_n36_now().strftime('%a %d %b')+'\n\n'.join(src_lines)[:3900])

def _n43_digest_loop():
    while True:
        try:
            oid=OWNER.get('id');now=_n36_now()
            if oid and now.strftime('%a').lower().startswith(str(_n36_kv_get('n43_digest_day','sun'))[:3].lower()) and now.strftime('%H:%M')==str(_n36_kv_get('n43_digest_time','09:00')) and _n36_kv_get('n43_digest_last','')!=now.strftime('%Y-%m-%d'):
                _n36_kv_set('n43_digest_last',now.strftime('%Y-%m-%d'))
                if _n43_topics(oid):_n43_run_digest(oid)
        except Exception:pass
        _n43_time.sleep(50)

def _n43_digest_cmd(cid,arg):
    a=arg.strip();low=a.lower()
    if low.startswith('add '):
        t=a[4:].strip()[:80]
        c=_n35_conn();c.execute('INSERT INTO digest_topics(chat_id,topic,added) VALUES(?,?,?)',(str(cid),t,_n43_time.time()));c.commit();c.close()
        send_text(cid,'📰 Watching "%s". Weekly digest every %s at %s IST. /digest now to run it right away.'%(t,_n36_kv_get('n43_digest_day','sun').title(),_n36_kv_get('n43_digest_time','09:00')));return
    m=_n43_re.match(r'(?:remove|rm|del)\s+(\d+)$',low)
    if m:
        c=_n35_conn();c.execute('DELETE FROM digest_topics WHERE chat_id=? AND id=?',(str(cid),int(m.group(1))));c.commit();c.close();send_text(cid,'Removed topic #%s.'%m.group(1));return
    if low.startswith('now'):
        only=a[3:].strip() or None;send_text(cid,'📰 Researching%s — this takes a minute...'%((' "%s"'%only) if only else ' your topics'));_n43_threading.Thread(target=_n43_run_digest,args=(cid,only),daemon=True).start();return
    m=_n43_re.match(r'time\s+(\d{1,2}):(\d{2})$',low)
    if m:_n36_kv_set('n43_digest_time','%02d:%s'%(int(m.group(1)),m.group(2)));send_text(cid,'📰 Digest time set to %02d:%s IST.'%(int(m.group(1)),m.group(2)));return
    m=_n43_re.match(r'day\s+(mon|tue|wed|thu|fri|sat|sun)[a-z]*$',low)
    if m:_n36_kv_set('n43_digest_day',m.group(1));send_text(cid,'📰 Digest day set to %s.'%m.group(1).title());return
    rows=_n43_topics(cid)
    send_text(cid,('📰 DIGEST TOPICS\n'+'\n'.join('#%d %s%s'%(r[0],r[1],(' · last '+_n38_fmt(r[2],'%d %b')) if r[2] else '') for r in rows) if rows else '📰 No topics yet.')+'\n\nEvery %s %s IST · /digest add <topic> · /digest now [topic] · /digest remove <id> · /digest time HH:MM · /digest day sun'%(_n36_kv_get('n43_digest_day','sun').title(),_n36_kv_get('n43_digest_time','09:00')))

