VERSION='43.1'
import re as _n431_re, subprocess as _n431_sp, time as _n431_time, json as _n431_json, threading as _n431_threading

def _n431_ytdlp_version():
    try:return _n431_sp.run(['yt-dlp','--version'],capture_output=True,text=True,timeout=20).stdout.strip() or '?'
    except Exception:return 'not installed'

def _n431_upgrade_ytdlp(force=False):
    """Upgrade to the newest yt-dlp: stable first, then pre-release (nightly) if stable is unchanged. Returns (old,new,changed)."""
    old=_n431_ytdlp_version()
    if not force and _n36_kv_get('n431_last_up','')==_n431_time.strftime('%Y-%m-%d-%H'):return old,old,False
    _n36_kv_set('n431_last_up',_n431_time.strftime('%Y-%m-%d-%H'))
    for args in (['python3','-m','pip','install','-U','yt-dlp','--break-system-packages','-q'],['python3','-m','pip','install','-U','--pre','yt-dlp','--break-system-packages','-q']):
        try:_n431_sp.run(args,capture_output=True,timeout=300)
        except Exception:pass
        new=_n431_ytdlp_version()
        if new!=old:return old,new,True
    return old,_n431_ytdlp_version(),False

