            last=_n36_kv_get('n43_last_dl','')
            if last and int(getattr(_N43_TLS,'step',0))==0 and not getattr(_N43_TLS,'upgraded',False):
                _N43_TLS.upgraded=True
                _N431_DELIVER_PREV(chat_id,mid,'🔧 YouTube changed its player ("page needs to be reloaded") — updating my downloader to the newest build first...')
                old,new,changed=_n431_upgrade_ytdlp(force=True)
                try:send_text(chat_id,('⬆️ yt-dlp %s → %s. Retrying...'%(old,new)) if changed else ('yt-dlp is already the newest (%s). Trying other player clients...'%new))
                except Exception:pass
                t,m,pl=_n431_json.loads(last)
