# =============================================================================
# NEMO 44.0 — RELIABILITY DOCTOR + AUTO-HEAL (the next big one) + fixes
#   FIXES FROM THE LAST SCREENSHOT
#     · YouTube final message now shows the REAL last error from yt-dlp (kept per
#       attempt), classifies it (bot-check / PO-token required / player changed /
#       format missing / cookies invalid) and names the matching fix. No guessing.
#     · /ytdoctor — runs yt-dlp verbosely on a known video and reports version,
#       cookie login presence, Node.js availability, and whether YouTube is asking
#       for a PO token. /ytpot install — sets up the free bgutil PO-token provider
#       when Node 18+ exists (documented steps, output shown, nothing hidden).
#     · Fast-core ground block is now hard-capped at 2,400 chars with priorities
#       (memory > lessons > world > referents) — the v39-ground-compact test failed
#       live because your real memory is bigger than my harness.
#   RELIABILITY DOCTOR: /doctor runs LIVE checks on every subsystem — Telegram,
#     brains/providers, Google token + scopes, email send path, downloader
#     (yt-dlp, ffmpeg, cookies, PO token), disk/memory, unified memory DB
#     integrity, fast core, regression — applies SAFE auto-fixes (upgrade yt-dlp,
#     reinstall missing pip packages, SQLite integrity/vacuum, clear stale temp),
#     and returns a scorecard with the exact next step for anything red.
#     Nightly at 04:30 IST it re-runs and messages you ONLY when something changed.
#   Keys, connections, trading/shell/payment authority: UNCHANGED.
# =============================================================================
VERSION='44.0'
import re as _n44_re, os as _n44_os, time as _n44_time, json as _n44_json, subprocess as _n44_sp, threading as _n44_threading, shutil as _n44_shutil

# ------------------------------- fast-core ground cap --------------------------
if '_n39_ground' in globals():
    _N44_GROUND_PREV=_n39_ground
    def _n39_ground(chat_id,src,ground):
        g=_N44_GROUND_PREV(chat_id,src,ground)
        cap=2400
        if len(g)<=cap:return g
        # keep whole blocks in priority order until the cap; the last rule line always stays
        blocks=[b for b in g.split('\n\n') if b.strip()];tail=[b for b in blocks if b.startswith('ACTION RULE')];rest=[b for b in blocks if not b.startswith('ACTION RULE')]
        pri=lambda b:0 if b.startswith('NEMO UNIFIED MEMORY') else 1 if 'LESSON' in b[:40].upper() else 2 if b.startswith('PHOTO MEMORY') else 3 if b.startswith('OPEN LOOPS') else 4 if 'WORLD' in b[:40].upper() else 5
        rest.sort(key=pri);out=[];used=sum(len(t)+2 for t in tail)
        for b in rest:
            if used+len(b)+2>cap:
                if not out:out.append(b[:cap-used-40].rsplit('\n',1)[0]);used=cap
                continue
            out.append(b);used+=len(b)+2
        return '\n\n'.join(out+tail)

# ------------------------------- youtube truth ---------------------------------
_N44_ERRS=[]   # last stderr tails per attempt
def _n44_classify(err):
    e=str(err or '').lower()
    if 'po token' in e or 'potoken' in e or 'pot provider' in e:return 'POTOKEN','YouTube is demanding a PO token for this client from a datacenter IP. Fix: /ytpot install (needs Node.js), then retry.'
    if 'sign in to confirm' in e or 'not a bot' in e:return 'BOTCHECK','Bot-check on the server IP. Fix: fresh cookies exported from a PRIVATE window logged in as the NEMO account (then close that window so they do not rotate) → send the file here.'
    if 'page needs to be reloaded' in e or 'failed to extract any player response' in e:return 'PLAYER','YouTube changed its player and the newest yt-dlp could not follow yet. Retry in a few hours; /ytupdate later.'
    if 'requested format is not available' in e or 'no video formats' in e:return 'FORMATS','Formats were hidden for this client (usually PO-token related). /ytpot install, or try "audio".'
    if 'cookies' in e and ('invalid' in e or 'expired' in e or 'no longer valid' in e):return 'COOKIES','The cookie file is invalid/expired. Re-export and resend.'
    if 'http error 429' in e:return 'RATELIMIT','YouTube rate-limited the server IP. Wait an hour or use /proxy.'
    if 'private video' in e or 'members-only' in e or 'age' in e and 'confirm' in e:return 'ACCESS','This video needs the account to have access (age/members/private). Cookies from an account that can watch it.'
    return 'UNKNOWN','Unclassified error — see /dlerror for the full text.'

# capture stderr tails: wrap the engine's deliver failure path by reading its message
_N44_DELIVER_PREV=deliver
def deliver(chat_id,mid,text,buttons=False):
    try:
        s=str(text or '')
        if chat_id==OWNER.get('id'):
            if s.startswith('Could not download that.'):
                _N44_ERRS.append(s.split('\n',1)[1][:700] if '\n' in s else s[:700]);del _N44_ERRS[:-8]
            if s.startswith('❌ YouTube is refusing'):
                last=_N44_ERRS[-1] if _N44_ERRS else '';kind,fix=_n44_classify(last)
                s=('❌ YouTube download failed after upgrading yt-dlp (%s) and trying %d player clients.\n\n'%(_n431_ytdlp_version() if '_n431_ytdlp_version' in globals() else '?',len(_N43_LADDER))+
                   'Real error (%s): %s\n\n'%(kind,(last[-260:] if last else 'not captured'))+
                   'What fixes this: '+fix+'\n\n/ytdoctor for a full diagnosis · /dlerror for the complete error · non-YouTube links (Instagram/X/Vimeo/Reddit) work directly.')
                pass  # keep errors for /dlerror
        return _N44_DELIVER_PREV(chat_id,mid,s,buttons)
    except Exception:pass
    return _N44_DELIVER_PREV(chat_id,mid,text,buttons)

def _n44_node():
    try:
        v=_n44_sp.run(['node','--version'],capture_output=True,text=True,timeout=10).stdout.strip();return v or ''
    except Exception:return ''

def _n44_pot_installed():
    try:
        out=_n44_sp.run(['python3','-m','pip','show','bgutil-ytdlp-pot-provider'],capture_output=True,text=True,timeout=30).stdout
        return 'Version' in out
    except Exception:return False

def _n44_ytdoctor(cid):
    lines=['🩺 YOUTUBE DOCTOR']
    ver=_n431_ytdlp_version() if '_n431_ytdlp_version' in globals() else '?';lines.append('yt-dlp: '+ver)
    ck='/root/nemo_cookies.txt'
    if _n44_os.path.exists(ck):
        try:t,y,l=_n43_cookie_report(open(ck,'rb').read());lines.append('cookies: %d total, %d YouTube/Google, login %s, age %.0fh'%(t,y,'present' if l else 'MISSING',(_n44_time.time()-_n44_os.path.getmtime(ck))/3600))
        except Exception:lines.append('cookies: present (unreadable)')
    else:lines.append('cookies: none')
    node=_n44_node();lines.append('node.js: '+(node or 'not installed'));lines.append('PO-token provider: '+('installed' if _n44_pot_installed() else 'not installed'))
    lines.append('ffmpeg: '+('yes' if _n44_shutil.which('ffmpeg') else 'NO'));lines.append('proxy: '+(net_proxy() or 'none'))
    # live probe on a tiny public video, verbose, 60s
    cmd=['yt-dlp','-v','--simulate','--no-playlist','--socket-timeout','15']
    if _n44_os.path.exists(ck):cmd+=['--cookies',ck]
    try:
        p=_n44_sp.run(cmd+['https://www.youtube.com/watch?v=jNQXAC9IVRw'],capture_output=True,text=True,timeout=90);err=(p.stderr or '')[-1800:]
        ok=p.returncode==0;kind,fix=_n44_classify(err)
        pot=bool(_n44_re.search(r'(?i)po token',err));lines.append('live probe: '+('OK ✅' if ok else 'FAILED ❌ (%s)'%kind));lines.append('YouTube asking for PO token: '+('YES' if pot else 'no'))
        clients=_n44_re.findall(r'(?i)\[youtube\] [^:]+: (?:Downloading|Requesting) ([a-z_]+) player',err)
        if clients:lines.append('clients tried: '+', '.join(sorted(set(clients))[:6]))
        if not ok:lines.append('\nNext step: '+fix)
        warn=[l for l in err.splitlines() if 'WARNING' in l][-3:]
        if warn:lines.append('\nyt-dlp warnings:\n'+'\n'.join(w[:200] for w in warn))
    except Exception as e:lines.append('live probe: error '+str(e)[:120])
    if not node:lines.append('\nTo enable PO tokens: install Node.js 18+ on the server (apt install nodejs npm or NodeSource), then /ytpot install.')
    send_text(cid,'\n'.join(lines)[:3900])

def _n44_pot_install(cid):
    node=_n44_node()
    if not node:send_text(cid,'Node.js is not installed. Run on the server: apt-get install -y nodejs npm (or NodeSource for Node 20) — then /ytpot install again.');return
    send_text(cid,'⚙️ Installing the bgutil PO-token provider (node %s)... this can take 2-3 minutes.'%node)
    log=[]
    def run(args,cwd=None,t=600):
        try:
            p=_n44_sp.run(args,cwd=cwd,capture_output=True,text=True,timeout=t);log.append('$ '+' '.join(args)+'\n'+(p.stdout+p.stderr)[-600:]);return p.returncode==0
        except Exception as e:log.append('$ '+' '.join(args)+'\nERR '+str(e)[:200]);return False
    ok1=run(['python3','-m','pip','install','-U','bgutil-ytdlp-pot-provider','--break-system-packages','-q'])
