# ------------------------------- reliability doctor ----------------------------
def _n44_check(name,fn):
    try:
        ok,detail,fix=fn();return {'name':name,'ok':bool(ok),'detail':str(detail)[:160],'fix':str(fix or '')[:160]}
    except Exception as e:return {'name':name,'ok':False,'detail':type(e).__name__+': '+str(e)[:120],'fix':''}

def _n44_doctor(auto_fix=True):
    R=[]
    R.append(_n44_check('Telegram',lambda:(bool((tg('getMe') or {}).get('ok')),'bot API reachable','check TELEGRAM token / network')))
    def _brains():
        try:
            st=dict(HEALTH) if isinstance(HEALTH,dict) else {}
            down=st.get('down');return (not down,'providers %s'%('DOWN' if down else 'up')+(' · fast core ON' if ('_n39_enabled' in globals() and _n39_enabled()) else ''),'/brain for cooldowns; /provider doctor')
        except Exception:return (True,'unknown','')
    R.append(_n44_check('Brains',_brains))
    def _google():
        try:
            if not google_ready():return (False,'not linked','/google to link (calendar, mail, drive)')
            tok=google_token();return (bool(tok),'token %s'%('valid' if tok else 'refresh FAILED'),'/google → re-authorize')
        except Exception as e:return (False,str(e)[:80],'/google')
    google_result=_n44_check('Google',_google)
    R.append(google_result)
    R.append(_n44_check('Email',lambda:_n702_email_probe(google_result['ok'])))
    def _dl():
        v=_n431_ytdlp_version() if '_n431_ytdlp_version' in globals() else '?';ff=bool(_n44_shutil.which('ffmpeg'));ck=_n44_os.path.exists('/root/nemo_cookies.txt')
        pot=bool(_n36_kv_get('n44_pot_script',''));ok=v not in ('?','not installed') and ff
        return (ok,'yt-dlp %s · ffmpeg %s · cookies %s · PO-token %s'%(v,'yes' if ff else 'NO','yes' if ck else 'no','yes' if pot else 'no'),('apt install ffmpeg' if not ff else '')+(' · /ytupdate' if v in ('?','not installed') else ''))
    R.append(_n44_check('Downloader',_dl))
    def _disk():
        du=_n44_shutil.disk_usage('/');pct=100.0*du.used/du.total;return (pct<90,'%.0f%% used, %.1f GB free'%(pct,du.free/1e9),'clear /root/nemo_media, /root/nemo_backups' if pct>=90 else '')
    R.append(_n44_check('Disk',_disk))
    def _mem():
        m={}
        for line in open('/proc/meminfo'):
            k,v=line.split(':',1);m[k]=float(v.strip().split()[0])
        pct=100.0*(1-m.get('MemAvailable',0)/max(1,m.get('MemTotal',1)));return (pct<92,'%.0f%% used'%pct,'restart heavy apps' if pct>=92 else '')
    R.append(_n44_check('Memory',_mem))
    def _db():
        c=_n35_conn();r=c.execute('PRAGMA integrity_check').fetchone()[0];n=c.execute('SELECT COUNT(*) FROM facts WHERE active=1').fetchone()[0];c.close()
        return (r=='ok','unified memory %s · %d facts'%(r,n),'backup nemo_memory.db and /mindmigrate' if r!='ok' else '')
    R.append(_n44_check('Memory DB',_db))
    def _deps():
        missing=[m for m in ('requests','matplotlib','yt_dlp','edge_tts','pypdf') if not _imp(m,notify=False)]
        return (not missing,'missing: '+', '.join(missing) if missing else 'core packages present',('auto-installing' if auto_fix else 'pip install')+' '+' '.join(missing) if missing else '')
    R.append(_n44_check('Packages',_deps))
    def _reg():
        r=prime_regression_suite();bad=[t.get('name') for t in r.get('tests',[]) if not t.get('ok')][:5]
        return (r.get('verdict')=='PASS','%s passed, %s failed'%(r.get('passed'),r.get('failed'))+((' → '+', '.join(bad)) if bad else ''),'/regress for detail' if bad else '')
    R.append(_n44_check('Regression',_reg))
    fixes=[]
    if auto_fix:
        for r in R:
            if r['name']=='Packages' and not r['ok']:
                for m in [x.strip() for x in r['detail'].replace('missing:','').split(',') if x.strip()]:
                    try:auto_install(m,notify=False);fixes.append('installed '+m)
                    except Exception:pass
            if r['name']=='Downloader' and 'yt-dlp ?' in r['detail'] or (r['name']=='Downloader' and 'not installed' in r['detail']):
                try:auto_install('yt_dlp',notify=False);fixes.append('installed yt-dlp')
                except Exception:pass
            if r['name']=='Disk' and not r['ok']:
                try:
                    n=0
                    for d in ('/root/nemo_media','/tmp'):
                        for f in _n44_os.listdir(d) if _n44_os.path.isdir(d) else []:
                            p=_n44_os.path.join(d,f)
                            if f.startswith(('m_','nemo30-','nemo37_in')) and _n44_time.time()-_n44_os.path.getmtime(p)>3600:_n44_os.remove(p);n+=1
                    if n:fixes.append('cleared %d temp media files'%n)
                except Exception:pass
        try:
            c=_n35_conn();c.execute('PRAGMA wal_checkpoint(TRUNCATE)');c.close()
        except Exception:pass
    return R,fixes

def _n44_doctor_text(R,fixes):
    score=sum(1 for r in R if r['ok']);lines=['🩺 RELIABILITY DOCTOR — %d/%d healthy · v%s'%(score,len(R),VERSION),'━━━━━━━━━━━━━━━━━━━━']
    for r in R:lines.append('%s %s — %s%s'%('✅' if r['ok'] else '❌',r['name'],r['detail'],('\n     ↳ fix: '+r['fix']) if (not r['ok'] and r['fix']) else ''))
    if fixes:lines.append('\n🔧 Auto-fixed: '+'; '.join(fixes))
    lines.append('\n/doctor again anytime · nightly re-check messages you only on change · /ytdoctor for YouTube specifically')
    return '\n'.join(lines)

