try:_n45_init()
except Exception:pass
def _n45_tokens(s):return ' '.join(sorted({w for w in _n45_re.findall(r'[a-z0-9]+',str(s or '').lower()) if len(w)>2}))

_N45_SEND_PREV=_n41_send_media
def _n41_send_media(cid,path,mode,title,caption=''):
    fid=_N45_SEND_PREV(cid,path,mode,title,caption)
    try:
        if fid and cid==OWNER.get('id'):
            src=''
            try:src=_n45_json.loads(_n36_kv_get('n43_last_dl','[]'))[0]
            except Exception:pass
            c=_n35_conn();c.execute('INSERT INTO library(chat_id,ts,title,source,kind,size,file_id,path,tokens) VALUES(?,?,?,?,?,?,?,?,?)',(str(cid),_n45_time.time(),str(title)[:200],str(src)[:300],mode,_n45_os.path.getsize(path) if _n45_os.path.exists(path) else 0,fid if fid!='doc' else '',path,_n45_tokens(title+' '+src)));c.commit();c.close()
    except Exception:pass
    return fid

def _n45_lib_search(cid,q,limit=8):
    toks=set(_n45_tokens(q).split())
    try:
        c=_n35_conn();rows=c.execute('SELECT id,ts,title,source,kind,size,file_id,path,tokens FROM library WHERE chat_id=? ORDER BY id DESC LIMIT 400',(str(cid),)).fetchall();c.close()
    except Exception:rows=[]
    if not toks:return rows[:limit]
    scored=[(len(toks & set((r[8] or '').split())),r) for r in rows];scored=[x for x in scored if x[0]>0];scored.sort(key=lambda x:(-x[0],-x[1][1]))
    return [r for s,r in scored[:limit]]

def _n45_lib_line(r):return '#%d %s %s · %.1f MB · %s%s'%(r[0],'🎬' if r[4]=='video' else '🎧',(r[2] or '')[:60],(r[5] or 0)/1e6,_n38_fmt(r[1],'%d %b') if '_n38_fmt' in globals() else '',('' if r[6] else ' · (file expired, re-download)'))

def _n45_lib_cmd(cid,arg):
    a=arg.strip();low=a.lower()
    if low.startswith('send '):
        m=_n45_re.search(r'(\d+)',low)
        if m:
            c=_n35_conn();r=c.execute('SELECT id,ts,title,source,kind,size,file_id,path FROM library WHERE chat_id=? AND id=?',(str(cid),int(m.group(1)))).fetchone();c.close()
            if not r:send_text(cid,'No library item #%s.'%m.group(1));return
            if r[6] and _n41_resend(cid,r[6],r[4],r[2] or ''):return
            if r[7] and _n45_os.path.exists(r[7]):_n41_send_media(cid,r[7],r[4],r[2] or '');return
            send_text(cid,'That file is gone from Telegram and disk — /dl the source again: '+(r[3] or ''));return
    if low.startswith('drive '):
        m=_n45_re.search(r'(\d+)',low)
        if m:
            c=_n35_conn();r=c.execute('SELECT title,path FROM library WHERE chat_id=? AND id=?',(str(cid),int(m.group(1)))).fetchone();c.close()
            if not r or not r[1] or not _n45_os.path.exists(r[1]):send_text(cid,'The local file is no longer on the server (cleaned after 2 days). /library send works from Telegram; for Drive, /dl it again then /library drive.');return
            try:
                fn=globals().get('drive_upload') or globals().get('gdrive_upload')
                if fn and google_ready():fn(r[1]);send_text(cid,'☁️ Uploaded to Google Drive: '+(r[0] or ''))
                else:send_text(cid,'Google Drive is not linked (/google).')
            except Exception as e:send_text(cid,'Drive upload failed: '+str(e)[:120])
            return
    if low=='stats':
        c=_n35_conn();n,sz=c.execute('SELECT COUNT(*),COALESCE(SUM(size),0) FROM library WHERE chat_id=?',(str(cid),)).fetchone();k=c.execute("SELECT kind,COUNT(*) FROM library WHERE chat_id=? GROUP BY kind",(str(cid),)).fetchall();c.close()
        send_text(cid,'📚 Library: %d items · %.0f MB total · '%(n,sz/1e6)+', '.join('%s %d'%(a,b) for a,b in k));return
    rows=_n45_lib_search(cid,a,10)
    if not rows:send_text(cid,'📚 Library is empty'+((' for "%s"'%a) if a else '')+'. Everything you /dl from now on is indexed here.');return
    send_text(cid,'📚 MEDIA LIBRARY'+((' · "%s"'%a) if a else '')+'\n'+'\n'.join(_n45_lib_line(r) for r in rows)+'\n\n/library send <id> resends instantly · /library drive <id> · /library stats')

_N45_NL=_n45_re.compile(r"(?i)^\s*(?:nemo[,\s]*)?(?:send|resend|give)\s+(?:me\s+)?(?:that|the|my)\s+(?:song|video|reel|clip|audio|track|file)\s+(?:again|about\s+(.{2,60})|(.{2,60}))\s*$|^\s*(?:nemo[,\s]*)?(?:find|search)\s+(?:my\s+)?(?:downloads?|library)\s+(?:for\s+)?(.{2,60})$")

def _n45_dispatch(msg):
    cid=(msg.get('chat') or {}).get('id');txt=(msg.get('text') or '').strip();low=txt.lower()
    if cid!=OWNER.get('id'):return False
    if low in ('/ytfix','/youtubefix'):_n45_threading.Thread(target=_n45_ytfix,args=(cid,),daemon=True).start();return True
    if low.startswith('/library') or low.startswith('/lib '):_n45_lib_cmd(cid,txt.split(' ',1)[1] if ' ' in txt else '');return True
    if txt and not txt.startswith('/'):
        m=_N45_NL.match(txt)
        if m:
            q=(m.group(1) or m.group(2) or m.group(3) or '').strip()
            if not q:
                rows=_n45_lib_search(cid,'',1)
                if rows:_n45_lib_cmd(cid,'send %d'%rows[0][0]);return True
            _n45_lib_cmd(cid,q);return True
    return False

_N45_PREV_HANDLE=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');chat=(msg.get('chat') or {});low=(msg.get('text') or '').strip().lower()
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id') and low.startswith(('/library','/lib ','/ytfix')):
            try:send_text(cid,'That command is owner-only.')
            except Exception:pass
            return
        if _n45_dispatch(msg):return
    except Exception as e:
        try:_n210_log_fail((msg.get('chat') or {}).get('id'),'nemo45_dispatch',msg.get('text',''),str(e))
        except Exception:pass
    return _N45_PREV_HANDLE(msg)

