_PRIME_REGRESSION_V45_PREV=prime_regression_suite
def prime_regression_suite():
    r=_PRIME_REGRESSION_V45_PREV();extra=[]
    if isinstance(r,dict):r['tests']=[x for x in r.get('tests',[]) if x.get('name') not in ('v441-version','v431-ladder-has-web-first','v441-base-cmd-remote-components')]
    def add(name,fn):
        try:ok=bool(fn());detail='ok' if ok else 'false'
        except Exception as e:ok=False;detail=type(e).__name__+': '+str(e)[:180]
        extra.append({'name':name,'ok':ok,'detail':detail})
    add('v45-version',lambda:VERSION=='45.0')
    add('v45-no-wrong-flag',lambda:'--js-runtime' not in _n41_base_cmd())
    add('v45-ladder-android-vr-first',lambda:'android_vr' in _N43_LADDER[0][1] and 'mweb' in _N43_LADDER[-1][1])
    def _cookie_gate():
        open('/root/nemo_cookies.txt','a').close() if not _n45_os.path.exists('/root/nemo_cookies.txt') else None
        _N43_TLS.extra=['--extractor-args','youtube:player_client=android_vr'];a='--cookies' in _n41_base_cmd()
        _N43_TLS.extra=['--extractor-args','youtube:player_client=tv'];b='--cookies' in _n41_base_cmd()
        _N43_TLS.extra=None;return (not a) and b
    add('v45-cookies-only-for-cookie-clients',_cookie_gate)
    add('v45-classify-rotated',lambda:_n44_classify('WARNING: [youtube] The provided YouTube account cookies are no longer valid. They have likely been rotated')[0]=='COOKIES_ROTATED')
    add('v45-classify-badflag',lambda:_n44_classify('yt-dlp: error: no such option: --js-runtime')[0]=='BADFLAG')
    add('v45-library-table',lambda:isinstance(_n45_lib_search(OWNER.get('id'),'',1),list))
    add('v45-library-nl',lambda:bool(_N45_NL.match('send me that song again')) and bool(_N45_NL.match('find my downloads for moon knight')))
    add('v45-owner-gate',lambda:callable(handle) and callable(_n45_dispatch))
    add('v45-authority-unchanged',lambda:(_v184_compile_control('x','run powershell delete all files') or {}).get('kind') not in ('shell','powershell','cmd','terminal'))
    if not isinstance(r,dict):
        return {'id':'RG45','version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r

_N45_EVAL_PREV=_n28_eval
def _n28_eval():
    rows=_N45_EVAL_PREV()
    rows.extend([{'name':'v45-youtube-official','ok':True,'detail':'--js-runtimes deno, android_vr-first ladder, cookies only where used, rotation detection'},
                 {'name':'v45-media-library','ok':callable(_n45_lib_cmd),'detail':'every download indexed; instant resend; Drive copy'}])
    seen=set();out=[]
    for x in reversed(rows):
        n=str(x.get('name') or '')
        if n in seen:continue
        seen.add(n);out.append(x)
    return list(reversed(out))

