def _n49_test_reset(cid):
    try:
        c=_n35_conn()
        tids=[r[0] for r in c.execute('SELECT id FROM thread49 WHERE chat_id=?',(str(cid),)).fetchall()]
        for t in tids:c.execute('DELETE FROM thread49_turn WHERE thread_id=?',(t,))
        c.execute('DELETE FROM goal49 WHERE chat_id=?',(str(cid),));c.execute('DELETE FROM capsule49 WHERE chat_id=?',(str(cid),));c.execute('DELETE FROM trace49 WHERE chat_id=?',(str(cid),));c.execute('DELETE FROM thread49 WHERE chat_id=?',(str(cid),));c.execute('DELETE FROM thread49_focus WHERE chat_id=?',(str(cid),));c.commit();c.close();_n49_focus_set(cid,'')
    except Exception:pass

def _n49_regression_fixture():
    cid='__n49_eval__';_n49_test_reset(cid)
