# =============================================================================
# NEMO 50.0 — TOOL FABRIC + EXECUTION GRAPH + UNIVERSAL RECEIPTS (BATCH 1)
#
# Purpose: stop growing Nemo as a pile of disconnected commands. This layer creates
# a discoverable tool registry, a deterministic capability router, persistent
# execution graphs, structured action receipts, cross-memory search, failure
# recording/replay, shadow routing, and a release gate. Existing tools remain the
# actual executors; v50 does NOT widen money/destructive/security authority.
#
# New owner tools:
#   /nemo50                    status
#   /tools50 [query]           discover registered tools
#   /tool50 <name>             inspect one tool
#   /toolhealth50              capability health map
#   /route50 <request>         show deterministic route (no execution)
#   /plan50 <request>          build/persist execution graph (no execution)
#   /shadow50 <request>        simulate the graph, no external effects
#   /run50 <request>           execute only the supported safe/explicit graph
#   /runs50                    recent runs
#   /receipt50 [run-id]        execution receipts
#   /search50 <query>          cross-memory/personal-knowledge search
#   /failure50 <complaint>     record last request/reply as regression evidence
#   /failures50                list recorded failures
#   /replay50 <failure-id>     replay routing in SHADOW mode only
#   /secretshealth50           secret/OAuth presence health, never values
#   /releasegate50 [candidate] static/runtime deployment gate
#
# Guarantees:
#   * all DB changes are CREATE TABLE/INDEX IF NOT EXISTS;
#   * no old DB/file is deleted or rewritten;
#   * credentials/config definitions are untouched;
#   * high-risk tools remain delegated to existing mature gates and are NOT
#     auto-executed by the new generic executor;
#   * tool receipts describe evidence actually observed, not imagined success.
# =============================================================================
VERSION='50.0'
import re as _n50_re, os as _n50_os, time as _n50_time, json as _n50_json
import uuid as _n50_uuid, hashlib as _n50_hashlib, ast as _n50_ast, threading as _n50_threading

_N50_LOCK=_n50_threading.RLock()
_N50_STATS={'routes':0,'plans':0,'runs':0,'shadow':0,'receipts':0,'failures':0,'replays':0,'errors':0}
_N50_EMAIL_RE=_n50_re.compile(r'(?i)(?<![\w.+-])([\w.+-]+@[\w.-]+\.[a-z]{2,})(?![\w.-])')
_N50_URL_RE=_n50_re.compile(r'(?i)https?://[^\s<>"\']+')
_N50_COMPLAINT_RE=_n50_re.compile(r"(?i)^\s*(?:nemo[,:\s]*)?(?:this is wrong|wrong|wrong result|you misunderstood|not what i asked|you did not understand|you didn't understand|galat hai|galat|samjhe nahi|samjha nahi|yeh galat hai)\b")


def _n50_init():
    c=_n35_conn();c.executescript("""
    CREATE TABLE IF NOT EXISTS tool50_registry(
      name TEXT PRIMARY KEY, category TEXT, description TEXT, risk TEXT, permission TEXT,
      handler TEXT, version TEXT, enabled INTEGER DEFAULT 1, health TEXT DEFAULT 'unknown',
      schema_json TEXT DEFAULT '{}', updated REAL);
    CREATE TABLE IF NOT EXISTS exec50_run(
      id TEXT PRIMARY KEY, chat_id TEXT, created REAL, updated REAL, task TEXT,
      status TEXT, shadow INTEGER DEFAULT 0, route_json TEXT DEFAULT '{}',
      result TEXT DEFAULT '', error TEXT DEFAULT '');
    CREATE INDEX IF NOT EXISTS idx_exec50_run_chat ON exec50_run(chat_id,updated DESC);
    CREATE TABLE IF NOT EXISTS exec50_step(
      id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT, idx INTEGER, name TEXT,
      tool TEXT, args_json TEXT DEFAULT '{}', depends_json TEXT DEFAULT '[]',
      status TEXT DEFAULT 'PLANNED', started REAL DEFAULT 0, ended REAL DEFAULT 0,
      result TEXT DEFAULT '', error TEXT DEFAULT '');
    CREATE INDEX IF NOT EXISTS idx_exec50_step_run ON exec50_step(run_id,idx);
    CREATE TABLE IF NOT EXISTS receipt50(
      id TEXT PRIMARY KEY, run_id TEXT, step_idx INTEGER, chat_id TEXT, ts REAL,
      action TEXT, target TEXT, status TEXT, evidence TEXT, meta_json TEXT DEFAULT '{}');
    CREATE INDEX IF NOT EXISTS idx_receipt50_run ON receipt50(run_id,ts);
    CREATE TABLE IF NOT EXISTS failure50(
      id TEXT PRIMARY KEY, chat_id TEXT, ts REAL, source TEXT, user_text TEXT,
      context TEXT, observed TEXT, expected TEXT, tags TEXT, status TEXT DEFAULT 'open',
      fingerprint TEXT UNIQUE);
    CREATE INDEX IF NOT EXISTS idx_failure50_chat ON failure50(chat_id,ts DESC);
    CREATE TABLE IF NOT EXISTS release50(
      id TEXT PRIMARY KEY, ts REAL, candidate TEXT, base TEXT, version TEXT,
      ast_ok INTEGER, compile_ok INTEGER, guards INTEGER, cred_changed INTEGER,
      cred_removed INTEGER, regress_passed INTEGER, regress_failed INTEGER,
      eval_passed INTEGER, eval_failed INTEGER, verdict TEXT, detail TEXT);
    """);c.commit();c.close()
    _n50_register_builtin_tools()


def _n50_j(x,limit=12000):
    try:return _n50_json.dumps(x,ensure_ascii=False,default=str)[:limit]
    except Exception:return '{}'


def _n50_safe_text(x,limit=2000):
    s=str(x or '')
    try:s=_n49_redact(s)
    except Exception:pass
    # Never store obvious secret-setting messages in v50 telemetry.
    try:
        if _n49_sensitive(s):return '[sensitive command redacted]'
    except Exception:pass
    return s[:limit]


def _n50_callable(name):
    try:return callable(globals().get(name))
    except Exception:return False


_N50_BUILTINS=[
 ('web.search','research','Fresh public web search','LOW','AUTO_SAFE','web_search',{'q':'string'}),
 ('web.fetch','research','Fetch/analyze an explicit web page','LOW','AUTO_SAFE','fetch_site',{'url':'url','want':'string'}),
 ('memory.cross_search','memory','Search Unified Mind, semantic memory, photos, media, threads and knowledge','LOW','AUTO_SAFE','_n50_cross_search',{'query':'string'}),
 ('artifact.pdf','artifact','Professional researched PDF/report through existing Publisher','LOW','AUTO_SAFE','make_pdf',{'topic':'string','email_to':'email?'}),
 ('artifact.docx','artifact','Create Word document through existing maker','LOW','AUTO_SAFE','make_docx',{'topic':'string','email_to':'email?'}),
 ('artifact.chart','artifact','Create chart through existing chart maker','LOW','AUTO_SAFE','make_chart',{'spec':'string'}),
 ('email.send','communication','Send email through existing Gmail/SMTP path','MEDIUM','OWNER_APPROVAL','send_email',{'to':'email','subject':'string','body':'string','attach_path':'path?'}),
 ('calendar.read','productivity','Read upcoming connected Google Calendar events','LOW','AUTO_SAFE','gcal_upcoming',{'days':'int'}),
 ('browser.agent','device','Use existing browser agent','MEDIUM','OWNER_APPROVAL','browser_agent',{'goal':'string'}),
 ('server.shell','systems','Run owner server command through existing shell rail','HIGH','EXISTING_GUARD','run_shell',{'cmd':'string'}),
 ('market.history','market','Read market history through existing market-data function','LOW','AUTO_SAFE','get_history',{'symbol':'string'}),
 ('photo.search','memory','Search persistent Photo Memory','LOW','AUTO_SAFE','_n37_photo_search',{'query':'string'}),
 ('media.library','media','Search persistent Media Library','LOW','AUTO_SAFE','_n45_lib_search',{'query':'string'}),
 ('knowledge.search','knowledge','Search Nemo Prime knowledge index','LOW','AUTO_SAFE','prime_knowledge_search',{'query':'string'}),
 ('project.threads','project','Read ThreadVault/project continuity state','LOW','AUTO_SAFE','_n49_threads',{'query':'string?'}),
]


def _n50_register_builtin_tools():
    now=_n50_time.time();c=_n35_conn()
    try:
        for name,cat,desc,risk,perm,handler,schema in _N50_BUILTINS:
            health='ready' if _n50_callable(handler) else 'missing'
            c.execute('INSERT OR REPLACE INTO tool50_registry(name,category,description,risk,permission,handler,version,enabled,health,schema_json,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?)',
                      (name,cat,desc,risk,perm,handler,VERSION,1,health,_n50_j(schema,2000),now))
        c.commit()
    finally:c.close()


def _n50_tools(query=''):
    q=str(query or '').strip().lower();c=_n35_conn()
    try:rows=c.execute('SELECT name,category,description,risk,permission,handler,version,enabled,health,schema_json FROM tool50_registry ORDER BY category,name').fetchall()
    finally:c.close()
    if q:
        toks={x for x in _n50_re.findall(r'[a-z0-9_.-]+',q) if len(x)>1}
        rows=[r for r in rows if toks & set(_n50_re.findall(r'[a-z0-9_.-]+',' '.join(str(x or '').lower() for x in r[:6])))]
    return rows


def _n50_tool_text(query=''):
    rows=_n50_tools(query)
    if not rows:return 'No registered tool matches that query.'
    lines=['🧰 NEMO TOOL FABRIC — %d tool%s'%(len(rows),'' if len(rows)==1 else 's')]
    for r in rows[:40]:lines.append('%s %s · %s · %s\n   %s'%('✅' if r[8]=='ready' and r[7] else '⚠️',r[0],r[1],r[3],r[2]))
    lines.append('\n/tools50 <word> · /tool50 <exact-name> · /toolhealth50')
    return '\n'.join(lines)


def _n50_tool_detail(name):
    n=str(name or '').strip().lower();rows=_n50_tools()
    r=next((x for x in rows if x[0].lower()==n),None)
    if not r:return 'Tool not found. Use /tools50.'
    return ('🧰 '+r[0]+'\nCategory: '+r[1]+'\nRisk: '+r[3]+'\nPermission: '+r[4]+'\nHandler: '+r[5]+
            '\nHealth: '+r[8]+'\nSchema: '+r[9]+'\n\n'+r[2])


def _n50_tool_health():
    _n50_register_builtin_tools();rows=_n50_tools();ready=sum(1 for r in rows if r[8]=='ready')
    lines=['🩺 TOOL HEALTH — %d/%d handlers ready'%(ready,len(rows))]
    cats={}
    for r in rows:cats.setdefault(r[1],[]).append(r)
    for cat in sorted(cats):
        a=cats[cat];lines.append('%s: %d/%d'% (cat,sum(1 for x in a if x[8]=='ready'),len(a)))
        for x in a:
            if x[8]!='ready':lines.append('  ❌ '+x[0]+' → missing '+x[5])
    return '\n'.join(lines)


# ------------------------------- cross-memory search ---------------------------
def _n50_cross_search(cid,query,limit=18):
    q=' '.join(str(query or '').split()).strip()
    if not q:return []
    hits=[]
    def add(source,label,detail,score=1.0,ref=''):
        d=_n50_safe_text(detail,900).strip()
        if d:hits.append({'source':source,'label':_n50_safe_text(label,160),'detail':d,'score':float(score),'ref':str(ref or '')[:120]})
    try:
        ctx=_n35_context(cid,q,limit=8,budget=1800)
        if ctx:add('unified-memory','Unified Mind',ctx,3.0)
    except Exception:pass
    try:
        for i,r in enumerate(mem_recall(q,k=6,minsim=.35) or []):add('semantic-memory','Semantic recall',str(r),2.4-i*.1)
    except Exception:pass
    try:
        for r in (_n37_photo_search(cid,q,5) or []):
            # id,ts,kind,title,summary,entities,tokens,path
            add('photo-memory',str(r[3] or r[0]),str(r[4] or '')+' '+str(r[5] or ''),2.6,str(r[0]))
    except Exception:pass
    try:
        for r in (_n45_lib_search(cid,q,5) or []):
            add('media-library',str(r[3] if len(r)>3 else 'Media'),str(r),2.2,str(r[0] if r else ''))
    except Exception:pass
    try:
        for r in (_n49_threads(cid,12) or []):
            hay=' '.join(str(x or '') for x in r[3:6])
            ov=len(set(_n50_re.findall(r'[a-z0-9]+',q.lower())) & set(_n50_re.findall(r'[a-z0-9]+',hay.lower())))
            if ov:add('threadvault',str(r[3]),str(r[5] or r[8] or ''),1.5+ov*.25,str(r[0]))
    except Exception:pass
    try:
        for r in (_n49_goals(cid,None,30) or []):
            hay=' '.join(str(x or '') for x in r)
            ov=len(set(_n50_re.findall(r'[a-z0-9]+',q.lower())) & set(_n50_re.findall(r'[a-z0-9]+',hay.lower())))
            if ov:add('goal-stack',str(r[4]),'status='+str(r[5])+((' · '+str(r[6])) if r[6] else ''),1.7+ov*.2,str(r[0]))
    except Exception:pass
    try:
        for r in (prime_knowledge_search(q,6) or []):add('knowledge-lake',str(r.get('title') if isinstance(r,dict) else 'Knowledge'),str(r),1.8)
    except Exception:pass
    # dedup by normalized source/detail prefix
    seen=set();out=[]
    for h in sorted(hits,key=lambda x:x['score'],reverse=True):
        k=(h['source'],_n50_re.sub(r'\W+',' ',h['detail'].lower())[:160])
        if k in seen:continue
        seen.add(k);out.append(h)
        if len(out)>=int(limit):break
    return out


def _n50_cross_text(cid,q):
    hits=_n50_cross_search(cid,q,18)
    if not hits:return '🔎 No matching personal-memory evidence found for: '+q
    lines=['🔎 CROSS-MEMORY SEARCH — '+q]
    for h in hits:lines.append('• [%s] %s\n  %s'%(h['source'],h['label'],h['detail'][:500]))
    return '\n\n'.join(lines)[:3900]


# ------------------------------- deterministic router --------------------------
def _n50_emails(text):return list(dict.fromkeys(m.group(1) for m in _N50_EMAIL_RE.finditer(str(text or ''))))

def _n50_text_without_emails(text):return _N50_EMAIL_RE.sub('[EMAIL]',str(text or ''))

def _n50_explicit_urls(text):return _N50_URL_RE.findall(_n50_text_without_emails(text))


def _n50_route(text):
    t=' '.join(str(text or '').split()).strip();low=t.lower();emails=_n50_emails(t);urls=_n50_explicit_urls(t)
    tools=[];reasons=[];risk='LOW';current=False;compound=False
    def need(tool,reason):
        if tool not in tools:tools.append(tool);reasons.append(reason)
    if _n50_re.search(r'\b(latest|today|right now|current|currently|news|market|price|weather|recent|this week|live)\b',low):current=True
    personal=bool(_n50_re.search(r'\b(my|mine|remember|recall|we discussed|we talked|sent you|my file|my photo|my project|my download|where were we)\b',low))
    report=bool(_n50_re.search(r'\b(report|pdf|briefing|analysis report|detailed report|detail report)\b',low))
    docx=bool(_n50_re.search(r'\b(word document|docx|word file)\b',low))
    chart=bool(_n50_re.search(r'\b(chart|graph|plot)\b',low))
    email_action=bool(emails and _n50_re.search(r'\b(email|mail|send|forward)\b',low))
    market=bool(_n50_re.search(r'\b(nifty|sensex|banknifty|stock|stocks|market|markets|fii|dii|vix|index|indices)\b',low))
    web_intent=bool(current or _n50_re.search(r'\b(search|research|find out|look up|verify online|web)\b',low))
    if personal:need('memory.cross_search','personal-context language')
    if market and not report:need('market.history','market-data language')
    if web_intent and not report:need('web.search','fresh/current research language')
    if urls:need('web.fetch','explicit URL present')
    if report:need('artifact.pdf','report/PDF requested')
    if docx:need('artifact.docx','Word document requested')
    if chart:need('artifact.chart','chart/graph requested')
    if email_action and not report and not docx:need('email.send','explicit email address + send/email verb')
    if _n50_re.search(r'\b(browser|website login|fill form|click|navigate)\b',low):need('browser.agent','browser interaction requested');risk='MEDIUM'
    if _n50_re.search(r'\b(shell|terminal|powershell|bash|server command|systemctl|restart service)\b',low):need('server.shell','system command requested');risk='HIGH'
    if email_action and risk=='LOW':risk='MEDIUM'
    compound=len(tools)>1 or (report and email_action)
    if report and (current or market or _n50_re.search(r'\bwhy\b',low)):
        # Existing Publisher Godmode performs fresh research internally; do not add a duplicate search step.
        tools=[x for x in tools if x!='web.search']
        reasons=[x for x in reasons if x!='fresh/current research language']
    if not tools:need('brain.chat','no deterministic tool requirement')
    _N50_STATS['routes']+=1
    return {'text':t,'intent':('compound' if compound else tools[0]),'tools':tools,'risk':risk,'current':current,'personal':personal,'compound':compound,'emails':emails,'urls':urls,'reasons':reasons}


def _n50_route_text(text):
    r=_n50_route(text)
    return ('🧭 CAPABILITY ROUTER\nIntent: %s\nTools: %s\nRisk: %s\nCurrent/fresh: %s\nPersonal context: %s\nCompound: %s\nEmail targets: %d\nExplicit URLs: %d\nReasons: %s' %
            (r['intent'],', '.join(r['tools']),r['risk'],'yes' if r['current'] else 'no','yes' if r['personal'] else 'no','yes' if r['compound'] else 'no',len(r['emails']),len(r['urls']),'; '.join(r['reasons']) or 'normal chat'))


# ------------------------------- execution graphs ------------------------------
def _n50_run_id():return 'R50-'+_n50_uuid.uuid4().hex[:10].upper()

def _n50_plan(cid,text,shadow=False,persist=True):
    route=_n50_route(text);rid=_n50_run_id();t=route['text'];low=t.lower();steps=[]
    def step(name,tool,args=None,depends=None):steps.append({'idx':len(steps)+1,'name':name,'tool':tool,'args':args or {},'depends':depends or []})
    emails=route['emails'];email_to=emails[0] if emails else ''
    # Personal search can be a grounding step when explicitly personal.
    if 'memory.cross_search' in route['tools']:step('Search personal knowledge','memory.cross_search',{'query':t})
    # Explicit URLs are deterministic fetch targets. Email domains are never converted to URLs.
    for u in route['urls'][:2]:step('Fetch explicit page','web.fetch',{'url':u,'want':t})
    if 'market.history' in route['tools']:
        sym='NIFTY'
        for x in ('BANKNIFTY','SENSEX','NIFTY'):
            if x.lower() in low:sym=x;break
        step('Read market history','market.history',{'symbol':sym})
    if 'web.search' in route['tools']:step('Research fresh web evidence','web.search',{'query':t})
    if 'artifact.pdf' in route['tools']:
        # make_pdf already performs the mature deep-research/QA pipeline and may email the SAME verified artifact.
        topic=t
        if email_to:
            topic=_N50_EMAIL_RE.sub('',topic)
            topic=_n50_re.sub(r'(?i)\b(?:and\s+)?(?:also\s+)?(?:email|mail|send)(?:\s+it|\s+me|\s+this|\s+the\s+report)?(?:\s+to)?\s*[:,-]?\s*',' ',topic)
            topic=' '.join(topic.split()).strip(' ,.-') or t
        step('Build researched PDF report','artifact.pdf',{'topic':topic,'email_to':email_to})
    if 'artifact.docx' in route['tools']:step('Build Word document','artifact.docx',{'topic':t,'email_to':email_to})
    if 'artifact.chart' in route['tools']:step('Build chart','artifact.chart',{'spec':t})
    if 'email.send' in route['tools']:
        # Generic email requires explicit content; never invent a body from an unrelated thread.
        step('Send explicit email','email.send',{'to':email_to,'subject':'Nemo message','body':t})
    if 'browser.agent' in route['tools']:step('Browser task','browser.agent',{'goal':t})
    if 'server.shell' in route['tools']:step('Server command','server.shell',{'cmd':t})
    if not steps:step('Answer normally','brain.chat',{'query':t})
    if persist:
        now=_n50_time.time();c=_n35_conn()
        try:
            c.execute('INSERT INTO exec50_run(id,chat_id,created,updated,task,status,shadow,route_json) VALUES(?,?,?,?,?,?,?,?)',(rid,str(cid),now,now,_n50_safe_text(t,4000),'PLANNED',1 if shadow else 0,_n50_j(route)))
            for s in steps:c.execute('INSERT INTO exec50_step(run_id,idx,name,tool,args_json,depends_json,status) VALUES(?,?,?,?,?,?,?)',(rid,s['idx'],s['name'],s['tool'],_n50_j(s['args']),_n50_j(s['depends']),'PLANNED'))
            c.commit();_N50_STATS['plans']+=1
        finally:c.close()
    return rid,route,steps


def _n50_plan_text(cid,text,shadow=False):
    rid,r,steps=_n50_plan(cid,text,shadow=shadow,persist=True)
    lines=['🧩 EXECUTION GRAPH '+rid,('Mode: SHADOW — no external effects' if shadow else 'Mode: PLAN — nothing executed yet'),'Risk: '+r['risk']]
    for s in steps:lines.append('%d. %s\n   tool=%s'%(s['idx'],s['name'],s['tool']))
    if not shadow:lines.append('\n/run50 '+text+'\nexecutes the supported graph. High-risk generic tools remain behind existing rails.')
    return '\n'.join(lines)[:3900]


def _n50_receipt(rid,idx,cid,action,target,status,evidence,meta=None):
    rec='RC50-'+_n50_uuid.uuid4().hex[:12].upper();now=_n50_time.time();c=_n35_conn()
    try:c.execute('INSERT INTO receipt50(id,run_id,step_idx,chat_id,ts,action,target,status,evidence,meta_json) VALUES(?,?,?,?,?,?,?,?,?,?)',(rec,rid,int(idx),str(cid),now,str(action)[:120],_n50_safe_text(target,500),str(status)[:40],_n50_safe_text(evidence,1800),_n50_j(meta or {},4000)));c.commit();_N50_STATS['receipts']+=1
    finally:c.close()
    return rec


def _n50_execute_tool(cid,rid,s):
    tool=s['tool'];a=s['args'];idx=s['idx'];target='';evidence='';result='';status='VERIFIED'
    # Generic executor intentionally supports only tools whose result can be observed without widening authority.
    if tool=='memory.cross_search':
        h=_n50_cross_search(cid,a.get('query',''),18);result=_n50_cross_text(cid,a.get('query',''));evidence='%d cross-memory hits'%len(h);target=a.get('query','')
    elif tool=='web.search':
        q=a.get('query','');rows=web_search(q) or [];target=q
        if not rows:raise RuntimeError('web search returned no results')
        result='\n\n'.join('[%d] %s\n%s\n%s'%(i+1,r.get('title',''),r.get('body',''),r.get('href','')) for i,r in enumerate(rows[:5]))
        evidence='%d fresh search results'%len(rows)
    elif tool=='web.fetch':
        # Existing fetch_site sends its own response; return value is not a reliable artifact, so receipt is EXECUTED not VERIFIED.
        target=a.get('url','');fetch_site(cid,target,a.get('want',''));status='EXECUTED';evidence='existing fetch_site invoked for explicit URL';result='Fetch dispatched to mature web path.'
    elif tool=='market.history':
        target=a.get('symbol','NIFTY');data=get_history(target)
        if data is None:raise RuntimeError('market history unavailable')
        try:n=len(data)
        except Exception:n=1
        evidence='market history returned %s row(s)'%n;result=str(data[-5:] if hasattr(data,'__getitem__') else data)[:2500]
    elif tool=='artifact.pdf':
        target=a.get('topic','');before=str((LASTFILE.get(cid) if isinstance(LASTFILE,dict) else '') or '')
        make_pdf(cid,target,a.get('email_to',''))
        after=str((LASTFILE.get(cid) if isinstance(LASTFILE,dict) else '') or '')
        if not after or not _n50_os.path.exists(after):raise RuntimeError('publisher did not leave a verified output file')
        evidence='artifact exists: %s bytes'%_n50_os.path.getsize(after);result='PDF delivered: '+after
        if a.get('email_to'):
            # Existing publisher attempts email. We only state evidence we can observe: no current LAST_EMAIL_ERR.
            if globals().get('LAST_EMAIL_ERR'):status='PARTIAL';evidence+='; email path reported error'
            else:evidence+='; publisher email path reported no error'
    elif tool=='artifact.docx':
        target=a.get('topic','');before=str((LASTFILE.get(cid) if isinstance(LASTFILE,dict) else '') or '')
        make_docx(cid,target,a.get('email_to',''));after=str((LASTFILE.get(cid) if isinstance(LASTFILE,dict) else '') or '')
        if after and _n50_os.path.exists(after):evidence='artifact exists: %s bytes'%_n50_os.path.getsize(after);result='Document delivered: '+after
        else:status='EXECUTED';evidence='existing Word maker invoked; no new LASTFILE evidence';result='Word maker completed its delivery path.'
    elif tool=='artifact.chart':
        target=a.get('spec','');make_chart(cid,target);status='EXECUTED';evidence='existing chart maker invoked';result='Chart maker completed its delivery path.'
    elif tool=='email.send':
        # Explicit /run50 is owner intent, but still use existing send_email implementation; exact recipient is required.
        target=a.get('to','')
        if not target or target not in _n50_emails(target):raise RuntimeError('valid explicit recipient required')
        ok=send_email(target,a.get('subject','Nemo message'),a.get('body',''))
        if not ok:raise RuntimeError(globals().get('LAST_EMAIL_ERR') or 'email send failed')
        evidence='existing email sender returned success';result='Email send path returned success.'
    elif tool=='calendar.read':
        target='Google Calendar';ev=gcal_upcoming(int(a.get('days',2) or 2)) or [];evidence='%d upcoming event(s)'%len(ev);result=str(ev)[:2500]
    elif tool in ('browser.agent','server.shell'):
        raise PermissionError(tool+' is intentionally not auto-executed by Tool Fabric; use the existing dedicated command/approval rail')
    elif tool=='brain.chat':
        target=a.get('query','');result=str(ask_ai(cid,target,remember=True,timeout=180) or '');evidence='brain returned %d characters'%len(result)
    else:raise RuntimeError('tool not supported by v50 executor: '+tool)
    rec=_n50_receipt(rid,idx,cid,tool,target,status,evidence,{'result_preview':_n50_safe_text(result,600)})
    return status,result,evidence,rec


def _n50_run(cid,text,shadow=False):
    rid,route,steps=_n50_plan(cid,text,shadow=shadow,persist=True);_N50_STATS['shadow' if shadow else 'runs']+=1
    c=_n35_conn();c.execute('UPDATE exec50_run SET status=?,updated=? WHERE id=?',('SHADOW' if shadow else 'RUNNING',_n50_time.time(),rid));c.commit();c.close()
    if shadow:
        for s in steps:_n50_receipt(rid,s['idx'],cid,s['tool'],str(s['args'])[:400],'SHADOW','would execute; no external effect')
        c=_n35_conn();c.execute("UPDATE exec50_run SET status='SHADOW_COMPLETE',updated=?,result=? WHERE id=?",(_n50_time.time(),'No external effects executed.',rid));c.commit();c.close()
        return rid,'🧪 SHADOW COMPLETE '+rid+'\n'+_n50_plan_text_from(rid,route,steps)+'\n\nNo external effects were performed.'
    outputs=[];final='COMPLETE';err=''
    for s in steps:
        now=_n50_time.time();c=_n35_conn();c.execute("UPDATE exec50_step SET status='RUNNING',started=? WHERE run_id=? AND idx=?",(now,rid,s['idx']));c.commit();c.close()
        try:
            st,res,ev,rec=_n50_execute_tool(cid,rid,s);outputs.append('%d. %s — %s (%s)'%(s['idx'],s['name'],st,ev[:220]))
            c=_n35_conn();c.execute('UPDATE exec50_step SET status=?,ended=?,result=? WHERE run_id=? AND idx=?',(st,_n50_time.time(),_n50_safe_text(res,3500),rid,s['idx']));c.commit();c.close()
            if st=='PARTIAL':final='PARTIAL'
        except Exception as e:
            final='FAILED';err=type(e).__name__+': '+str(e)[:700];outputs.append('%d. %s — FAILED (%s)'%(s['idx'],s['name'],err))
            _n50_receipt(rid,s['idx'],cid,s['tool'],str(s['args'])[:400],'FAILED',err)
            c=_n35_conn();c.execute("UPDATE exec50_step SET status='FAILED',ended=?,error=? WHERE run_id=? AND idx=?",(_n50_time.time(),err,rid,s['idx']));c.commit();c.close();break
    c=_n35_conn();c.execute('UPDATE exec50_run SET status=?,updated=?,result=?,error=? WHERE id=?',(final,_n50_time.time(),'\n'.join(outputs)[:5000],err,rid));c.commit();c.close()
    return rid,'⚙️ EXECUTION '+rid+' — '+final+'\n'+'\n'.join(outputs)+'\n\n/receipt50 '+rid


def _n50_plan_text_from(rid,route,steps):
    return 'Risk: '+route['risk']+'\n'+'\n'.join('%d. %s → %s'%(s['idx'],s['name'],s['tool']) for s in steps)


def _n50_recent_runs(cid,limit=12):
    try:
        c=_n35_conn();rows=c.execute('SELECT id,created,updated,task,status,shadow,error FROM exec50_run WHERE chat_id=? ORDER BY updated DESC LIMIT ?',(str(cid),int(limit))).fetchall();c.close();return rows
    except Exception:return []


def _n50_runs_text(cid):
    rows=_n50_recent_runs(cid,15)
    if not rows:return 'No v50 execution runs yet.'
    return '⚙️ RECENT RUNS\n'+'\n'.join('%s · %s · %s\n  %s'%(r[0],r[4],_n50_time.strftime('%d %b %H:%M',_n50_time.localtime(r[2])),r[3][:120]) for r in rows)


def _n50_receipts_text(cid,rid=''):
    try:
        c=_n35_conn()
        if rid:rows=c.execute('SELECT id,run_id,step_idx,ts,action,target,status,evidence FROM receipt50 WHERE chat_id=? AND run_id=? ORDER BY ts',(str(cid),rid)).fetchall()
        else:rows=c.execute('SELECT id,run_id,step_idx,ts,action,target,status,evidence FROM receipt50 WHERE chat_id=? ORDER BY ts DESC LIMIT 20',(str(cid),)).fetchall()
        c.close()
    except Exception:rows=[]
    if not rows:return 'No matching v50 receipts.'
    lines=['🧾 EXECUTION RECEIPTS'+((' — '+rid) if rid else '')]
    for r in rows:lines.append('%s · %s · step %s · %s\n  %s'%(r[6],r[4],r[2],r[0],r[7]))
    return '\n'.join(lines)[:3900]


# ------------------------------- failure recorder/replay -----------------------
def _n50_failure_add(cid,complaint='',source='owner-feedback',user_text=None,observed=None,expected=''):
    if user_text is None:
        try:user_text=str(LASTQ.get(cid) or '')
        except Exception:user_text=''
    if observed is None:
        try:observed=str(LASTREPLY.get(cid) or '')
        except Exception:observed=''
    context=''
    try:context=_n49_thread_brief(cid,_n49_focus_id(cid)) if _n49_focus_id(cid) else ''
    except Exception:pass
    base='\0'.join([str(cid),str(user_text),str(observed),str(complaint)])
    fp=_n50_hashlib.sha256(base.encode('utf-8','ignore')).hexdigest()[:24]
    fid='F50-'+fp[:10].upper();c=_n35_conn()
    try:
        c.execute('INSERT OR IGNORE INTO failure50(id,chat_id,ts,source,user_text,context,observed,expected,tags,status,fingerprint) VALUES(?,?,?,?,?,?,?,?,?,?,?)',
                  (fid,str(cid),_n50_time.time(),source,_n50_safe_text(user_text,3000),_n50_safe_text(context,2500),_n50_safe_text(observed,3500),_n50_safe_text(expected or complaint,1800),'routing,owner-feedback','open',fp));new=c.total_changes>0;c.commit()
    finally:c.close()
    if new:_N50_STATS['failures']+=1
    return fid,new


def _n50_failures(cid,limit=20):
    try:c=_n35_conn();r=c.execute('SELECT id,ts,source,user_text,observed,expected,status FROM failure50 WHERE chat_id=? ORDER BY ts DESC LIMIT ?',(str(cid),int(limit))).fetchall();c.close();return r
    except Exception:return []


def _n50_failures_text(cid):
    rows=_n50_failures(cid,20)
    if not rows:return 'No recorded v50 failures.'
    return '🧪 REGRESSION RECORDER\n'+'\n\n'.join('%s · %s · %s\nINPUT: %s\nEXPECTED/FEDBACK: %s'%(r[0],r[6],_n50_time.strftime('%d %b %H:%M',_n50_time.localtime(r[1])),r[3][:220],r[5][:220]) for r in rows)[:3900]


def _n50_failure_get(cid,fid):
    try:c=_n35_conn();r=c.execute('SELECT id,ts,source,user_text,context,observed,expected,status FROM failure50 WHERE chat_id=? AND id=?',(str(cid),str(fid).upper())).fetchone();c.close();return r
    except Exception:return None


def _n50_replay(cid,fid):
    r=_n50_failure_get(cid,fid)
    if not r:return 'Failure case not found.'
    _N50_STATS['replays']+=1;route=_n50_route(r[3]);rid,_,steps=_n50_plan(cid,r[3],shadow=True,persist=True)
    for s in steps:_n50_receipt(rid,s['idx'],cid,s['tool'],str(s['args'])[:400],'SHADOW','failure replay; no external action')
    c=_n35_conn();c.execute("UPDATE exec50_run SET status='REPLAY_COMPLETE',updated=?,result=? WHERE id=?",(_n50_time.time(),'failure '+r[0],rid));c.commit();c.close()
    return ('🔁 FAILURE REPLAY — '+r[0]+'\nNo external action executed.\n\nOriginal input:\n'+r[3][:700]+'\n\nCurrent route:\n'+_n50_route_text(r[3])+'\n\nGraph:\n'+_n50_plan_text_from(rid,route,steps))[:3900]


# ------------------------------- secret/oauth health ---------------------------
def _n50_secret_health():
    lines=['🔐 SECRETS / CONNECTION HEALTH','Values are NEVER displayed.']
    try:
        st=secrets_status();loaded=st.get('loaded',{}) if isinstance(st,dict) else {}
        for label,src in sorted(loaded.items()):lines.append(('✅ ' if src not in ('unset','','none') else '⚠️ ')+str(label)+' — '+str(src))
        ins=st.get('in_source',[]) if isinstance(st,dict) else []
        lines.append('Baked secret definitions still present: %d'%len(ins))
    except Exception as e:lines.append('⚠️ secret status unavailable: '+type(e).__name__)
    try:lines.append(('✅' if google_ready() else '⚠️')+' Google account link — '+('connected' if google_ready() else 'not connected'))
    except Exception:lines.append('⚠️ Google account link — unknown')
    try:
        have=[k for k in ('app_id','secret','user','totp','pin') if isinstance(BROKER,dict) and BROKER.get(k)]
        lines.append(('✅' if len(have)>=5 else '⚠️')+' FYERS credential fields present — %d/5'%len(have))
    except Exception:pass
    try:lines.append(('✅' if _n50_os.path.exists('/root/nemo_cookies.txt') else '•')+' YouTube cookie file — '+('present' if _n50_os.path.exists('/root/nemo_cookies.txt') else 'not present'))
    except Exception:pass
    return '\n'.join(lines)[:3900]


# ------------------------------- release gate ----------------------------------
def _n50_guard_count(code):
    try:
        tree=_n50_ast.parse(code);n=0
        for node in tree.body:
            if isinstance(node,_n50_ast.If):
                try:
                    t=node.test
                    if isinstance(t,_n50_ast.Compare) and isinstance(t.left,_n50_ast.Name) and t.left.id=='__name__':n+=1
                except Exception:pass
        return n
    except Exception:return -1


def _n50_version_from(code):
    try:return _extract_version(code)
    except Exception:
        ms=_n50_re.findall(r"(?m)^VERSION\s*=\s*['\"]([^'\"]+)['\"]",code);return ms[-1] if ms else '?'


def _n50_release_gate(cid,candidate=False):
    try:base=_self_read()
    except Exception:
        try:base=open(__file__,encoding='utf-8',errors='ignore').read()
        except Exception:base=''
    code=base;label='running source';dynamic=True
    if candidate:
        dynamic=False
        try:lc=(LAST_CODE.get(cid) or {}) if isinstance(LAST_CODE,dict) else {};code=lc.get('code') or ''
        except Exception:code=''
        label='last attached candidate'
        if not code:return 'No candidate Python file is staged. Attach the full Nemo .py first, then /releasegate50 candidate.'
    ast_ok=True
    try:_n50_ast.parse(code)
    except Exception:ast_ok=False
    try:compile_ok=bool(_compile_check(code)[0])
    except Exception:compile_ok=ast_ok
    guards=_n50_guard_count(code);changed=[];removed=[]
    try:changed,removed=_update_cred_changes(base,code) if candidate else ([],[])
    except Exception:pass
    rp=rf=ep=ef=None;detail=[]
    if dynamic:
        try:
            rr=prime_regression_suite();rp=int(rr.get('passed',0));rf=int(rr.get('failed',0));detail.append('regression='+str(rr.get('verdict')))
        except Exception as e:detail.append('regression-error='+type(e).__name__)
        try:
            ev=_n28_eval();ep=sum(1 for x in ev if x.get('ok'));ef=len(ev)-ep
        except Exception as e:detail.append('eval-error='+type(e).__name__)
    static_ok=ast_ok and compile_ok and guards==1 and not removed and not changed
    verdict='PASS' if static_ok and (not dynamic or (rf==0 and ef==0)) else ('PASS_WITH_EXISTING_FAILURES' if static_ok and dynamic else 'FAIL')
    rid='REL50-'+_n50_uuid.uuid4().hex[:10].upper();c=_n35_conn()
    try:c.execute('INSERT INTO release50(id,ts,candidate,base,version,ast_ok,compile_ok,guards,cred_changed,cred_removed,regress_passed,regress_failed,eval_passed,eval_failed,verdict,detail) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',(rid,_n50_time.time(),label,VERSION,_n50_version_from(code),1 if ast_ok else 0,1 if compile_ok else 0,guards,len(changed),len(removed),rp,rf,ep,ef,verdict,'; '.join(detail)));c.commit();c.close()
    except Exception:pass
    lines=['🚦 RELEASE GATE — '+verdict,'Target: '+label,'Version: '+_n50_version_from(code),'AST: '+('PASS' if ast_ok else 'FAIL'),'Compile: '+('PASS' if compile_ok else 'FAIL'),'Production guards: '+str(guards),'Credential/config changed: '+str(len(changed)),'Credential/config removed: '+str(len(removed))]
    if dynamic:lines+=['Regression: '+(('%d pass / %d fail'%(rp,rf)) if rp is not None else 'unavailable'),'Evaluation: '+(('%d pass / %d fail'%(ep,ef)) if ep is not None else 'unavailable')]
    else:lines.append('Candidate gate is STATIC only; runtime regression must run after deployment in the target environment.')
    if changed:lines.append('Changed names: '+', '.join(changed[:12]))
    if removed:lines.append('Removed names: '+', '.join(removed[:12]))
    return '\n'.join(lines)[:3900]


