_N50_HANDLE_PREV=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');chat=msg.get('chat') or {};txt=(msg.get('text') or '').strip();low=txt.lower()
        if cid==OWNER.get('id') and chat.get('type','private')=='private':
            if low in ('/nemo50','/toolfabric','/toolsos'):
                send_text(cid,_n50_status(cid));return
            if low.startswith('/tools50'):
                send_text(cid,_n50_tool_text(txt[len('/tools50'):].strip()));return
            if low.startswith('/tool50 '):
                send_text(cid,_n50_tool_detail(txt[len('/tool50 '):].strip()));return
            if low in ('/toolhealth50','/toolhealth'):
                send_text(cid,_n50_tool_health());return
            if low.startswith('/route50'):
                arg=txt[len('/route50'):].strip();send_text(cid,_n50_route_text(arg) if arg else 'Usage: /route50 <request>');return
            if low.startswith('/plan50'):
                arg=txt[len('/plan50'):].strip();send_text(cid,_n50_plan_text(cid,arg,False) if arg else 'Usage: /plan50 <request>');return
            if low.startswith('/shadow50'):
                arg=txt[len('/shadow50'):].strip()
                if not arg:send_text(cid,'Usage: /shadow50 <request>');return
                rid,res=_n50_run(cid,arg,True);send_text(cid,res);return
            if low.startswith('/run50'):
                arg=txt[len('/run50'):].strip()
                if not arg:send_text(cid,'Usage: /run50 <request>');return
                send_text(cid,'⚙️ Building and executing verified tool graph...')
                def _go50():
                    try:rid,res=_n50_run(cid,arg,False);send_text(cid,res)
                    except Exception as e:send_text(cid,'v50 execution failed safely: '+type(e).__name__+': '+str(e)[:300])
                _n50_threading.Thread(target=_go50,daemon=True,name='nemo-run50').start();return
            if low=='/runs50':send_text(cid,_n50_runs_text(cid));return
            if low.startswith('/receipt50'):
                send_text(cid,_n50_receipts_text(cid,txt[len('/receipt50'):].strip().upper()));return
            if low.startswith('/search50'):
                q=txt[len('/search50'):].strip();send_text(cid,_n50_cross_text(cid,q) if q else 'Usage: /search50 <what to find across my memory/files/photos/media/projects>');return
            if low.startswith('/failure50'):
                note=txt[len('/failure50'):].strip();fid,new=_n50_failure_add(cid,note);send_text(cid,('🧪 Recorded regression case '+fid if new else 'That exact failure is already recorded as '+fid)+'\nUse /replay50 '+fid+' to test routing without external actions.');return
            if low=='/failures50':send_text(cid,_n50_failures_text(cid));return
            if low.startswith('/replay50'):
                fid=txt[len('/replay50'):].strip().upper();send_text(cid,_n50_replay(cid,fid) if fid else 'Usage: /replay50 <failure-id>');return
            if low in ('/secretshealth50','/oauthhealth50'):
                send_text(cid,_n50_secret_health());return
            if low.startswith('/releasegate50'):
                arg=txt[len('/releasegate50'):].strip().lower();send_text(cid,'🚦 Running release gate...');
                def _rg():
                    try:send_text(cid,_n50_release_gate(cid,arg in ('candidate','new','staged')))
                    except Exception as e:send_text(cid,'Release gate error: '+type(e).__name__+': '+str(e)[:300])
                _n50_threading.Thread(target=_rg,daemon=True,name='nemo-release50').start();return
            # Persist real owner complaints as replayable regression evidence, then let normal conversation answer too.
            if txt and not txt.startswith('/') and _N50_COMPLAINT_RE.search(txt):
                try:_n50_failure_add(cid,txt,'natural-feedback')
                except Exception:pass
    except Exception:_N50_STATS['errors']+=1
    return _N50_HANDLE_PREV(msg)


