# ------------------------------- ROUTER REPAIR ---------------------------------
_N51_ROUTE_PREV=_n50_route

def _n51_owner_email_for(text):
    """Resolve the owner's configured address only when the language explicitly says email ME/MY email."""
    t=str(text or '')
    if _N51_PLACEHOLDER_RE.search(t):return ''
    if not _n51_re.search(r"(?i)\b(?:email|mail|send)\s+(?:it\s+|this\s+|the\s+report\s+)?(?:to\s+)?(?:me|my\s+email|my\s+mail)\b|\bto\s+my\s+(?:email|mail)\b",t):return ''
    try:
        e=str(OWNER_EMAIL or '').strip()
        return e if _n50_emails(e) else ''
    except Exception:return ''


def _n50_route(text):
    r=dict(_N51_ROUTE_PREV(text));t=' '.join(str(text or '').split()).strip();low=t.lower()
    email_requested=bool(_N51_EMAIL_REQUEST_RE.search(t))
    emails=list(r.get('emails') or [])
    if email_requested and not emails:
        own=_n51_owner_email_for(t)
        if own:emails=[own]
    r['emails']=emails
    # "markets are down" is current even without the literal word "today".
    market_live=bool(_N51_MARKET_MOVE_RE.search(t))
    if market_live:r['current']=True
    deep_research=bool(_N51_DEEP_RESEARCH_RE.search(t))
    placeholder=bool(_N51_PLACEHOLDER_RE.search(t))
    email_missing=bool(email_requested and not emails and (placeholder or _n51_re.search(r"(?i)\b(?:email|mail|send)\b",t)))
    r['email_requested']=email_requested;r['email_missing']=email_missing;r['market_live']=market_live;r['deep_research']=deep_research
    tools=list(r.get('tools') or []);reasons=list(r.get('reasons') or [])
    def need(tool,reason):
        if tool not in tools:tools.append(tool);reasons.append(reason)
    # Upgrade actual tool selection for common live/read-only needs.
    if deep_research and 'artifact.pdf' not in tools:need('research.omni','explicit deep/multi-source research request')
    if market_live and 'artifact.pdf' not in tools:
        # One synthesized market tool is better than unrelated history-only output.
        tools=[x for x in tools if x not in ('market.history','web.search')]
        reasons=[x for x in reasons if x not in ('market-data language','fresh/current research language')]
        need('market.explain','current market-move explanation requested')
    if _n51_re.search(r"(?i)\b(?:weather|forecast|temperature|rain)\b",t) and 'artifact.pdf' not in tools:need('weather.current','weather request')
    if _n51_re.search(r"(?i)\b(?:unread\s+(?:mail|email)|inbox\s+(?:summary|unread)|check\s+(?:my\s+)?(?:mail|email))\b",t):need('google.mail_unread','connected Gmail read request')
    if _n51_re.search(r"(?i)\b(?:drive\s+file|google\s+drive|search\s+(?:my\s+)?drive)\b",t):need('google.drive_search','connected Drive search request')
    if _n51_re.search(r"(?i)\b(?:system\s+snapshot|server\s+health|system\s+health|ram\s+usage|memory\s+usage|disk\s+usage)\b",t):need('system.snapshot','local system inspection')
    if _n51_re.search(r"(?i)\b(?:database\s+(?:health|integrity|check)|db\s+(?:health|integrity|check))\b",t):need('database.quickcheck','read-only SQLite integrity request')
    if _n51_re.search(r"(?i)\b(?:backup\s+(?:status|audit|health)|check\s+(?:my\s+)?backups?)\b",t):need('backup.audit','backup inventory request')
    if _n51_re.search(r"(?i)\b(?:security\s+audit|cyber\s+audit|security\s+health)\b",t):need('security.local_audit','read-only local security audit')
    if _n51_re.search(r"(?i)\b(?:network\s+(?:health|diagnostic|check)|dns\s+(?:health|check))\b",t):need('network.health','read-only network connectivity check')
    if _n51_re.search(r"(?i)\b(?:app\s+logs?|service\s+logs?|journal\s+logs?|show\s+logs?)\b",t):need('logs.read','read-only service log request')
    if _n51_re.search(r"(?i)\b(?:ask\s+(?:multiple|three|different)\s+brains|brain\s+council|model\s+council|second\s+opinion\s+from\s+models)\b",t):need('brain.council','explicit multi-brain council request')
    # If an email was requested but target is missing, do NOT silently guess an address.
    if email_missing:
        reasons.append('email requested but no valid explicit/configured owner target resolved')
    tools=list(dict.fromkeys(tools))
    # New specialized tools supersede the generic fallback/search route rather than duplicating work.
    if 'research.omni' in tools and 'web.search' in tools:
        tools.remove('web.search')
        try:reasons.remove('fresh/current research language')
        except Exception:pass
    if len(tools)>1 and 'brain.chat' in tools:tools.remove('brain.chat')
    r['tools']=tools;r['reasons']=reasons
    r['compound']=bool(len(r['tools'])>1 or (email_requested and ('artifact.pdf' in r['tools'] or 'artifact.docx' in r['tools'])))
    r['risk']='MEDIUM' if email_requested and r.get('risk')=='LOW' else r.get('risk','LOW')
    r['intent']='compound' if r['compound'] else (r['tools'][0] if r['tools'] else 'brain.chat')
    _N51_STATS['routes']+=1
    return r


_N51_ROUTE_TEXT_PREV=_n50_route_text
def _n50_route_text(text):
    r=_n50_route(text)
    extra='\nEmail requested: %s%s'%('yes' if r.get('email_requested') else 'no',' · target MISSING' if r.get('email_missing') else '')
    extra+='\nMarket-now semantics: %s'%('yes' if r.get('market_live') else 'no')
    extra+='\nDeep research: %s'%('yes' if r.get('deep_research') else 'no')
    return ('🧭 CAPABILITY ROUTER\nIntent: %s\nTools: %s\nRisk: %s\nCurrent/fresh: %s\nPersonal context: %s\nCompound: %s\nEmail targets: %d\nExplicit URLs: %d%s\nReasons: %s' %
            (r['intent'],', '.join(r['tools']),r['risk'],'yes' if r['current'] else 'no','yes' if r['personal'] else 'no','yes' if r['compound'] else 'no',len(r['emails']),len(r['urls']),extra,'; '.join(r['reasons']) or 'normal chat'))[:3900]


# ------------------------------- NERO / ML ROUTER ------------------------------
def _n51_task_class(text,image_b64=None,deep=False,long_output=False):
    t=str(text or '').lower()
    if image_b64:return 'vision'
    if _n51_re.search(r'\b(python|javascript|typescript|sql|pine\s*script|code|function|bug|traceback|program|api\s+code)\b',t):return 'code'
    if _n51_re.search(r'\b(nifty|sensex|banknifty|stocks?|market|markets|option|fii|dii|vix|portfolio)\b',t):return 'market'
    if _n51_re.search(r'\b(loan|emi|debt|finance|financial|cashflow|cash flow|roi|break[- ]?even|interest|gst|tax)\b',t):return 'finance'
    if _n51_re.search(r'\b(report|pdf|docx|document|spreadsheet|xlsx|chart|presentation|slides)\b',t):return 'artifact'
    if _N51_DEEP_RESEARCH_RE.search(t) or _n51_re.search(r'\b(latest|today|news|current|research|verify online|look up|find out)\b',t):return 'research'
    if _n51_re.search(r'\b(remember|recall|my wife|my project|where were we|what did i|my photo|my file)\b',t):return 'personal'
    if _n51_re.search(r'\b(email|send|delete|restart|open|close|download|upload|schedule|remind|create event|buy|sell|order)\b',t):return 'action'
    if deep or long_output:return 'deep'
    if len(t)>800:return 'deep'
    return 'chat'


def _n51_base_candidates(task,image_b64,deep,long_output):
    if image_b64:return list(VISION_MODELS)
    if task=='artifact':base=list(WRITER_MODELS)
    elif task in ('code','research','market','finance','deep') or deep or long_output:base=list(SMART_MODELS)
    else:
        try:base=list(FAST_MODELS if MODE.get(OWNER.get('id'))=='fast' else SMART_MODELS)
        except Exception:base=list(SMART_MODELS)
    try:
        for m in EXTRA_MODELS:
            if m not in base and m not in RETIRED_MODELS:base.append(m)
    except Exception:pass
    return list(dict.fromkeys(base))


def _n51_global_model_stats():
    try:
        c=_learn_conn();rows=c.execute('SELECT model,calls,ok,fail,avg_latency FROM model_stats').fetchall();c.close()
        return {r[0]:{'calls':r[1],'ok':r[2],'fail':r[3],'lat':float(r[4] or 0)} for r in rows}
    except Exception:return {}


def _n51_task_stats(task):
    try:
        c=_n35_conn();rows=c.execute('SELECT model,calls,ok,fail,avg_latency,feedback_good,feedback_bad FROM neuro51_task_model WHERE task_class=?',(task,)).fetchall();c.close()
        return {r[0]:{'calls':r[1],'ok':r[2],'fail':r[3],'lat':float(r[4] or 0),'good':r[5],'bad':r[6]} for r in rows}
    except Exception:return {}


def _n51_model_score(task,model,total_calls=0):
    ts=_n51_task_stats(task).get(model,{});gs=_n51_global_model_stats().get(model,{})
    tc=int(ts.get('calls',0));tok=int(ts.get('ok',0));tf=int(ts.get('fail',0));good=int(ts.get('good',0));bad=int(ts.get('bad',0))
    gc=int(gs.get('calls',0));gok=int(gs.get('ok',0))
    # Bayesian smoothed task-success dominates; global history is a smaller prior.
    task_rate=(tok+2.0)/(tc+4.0)
    global_rate=(gok+2.0)/(gc+4.0) if gc else .5
    fb_rate=(good+1.0)/(good+bad+2.0)
    lat=float(ts.get('lat') or gs.get('lat') or 0)
    latency_pen=min(.16,max(0.0,lat/120.0))
    explore=min(.08,_n51_math.sqrt(_n51_math.log(max(2,total_calls+2.0))/(tc+1.0))*.035)
    score=.68*task_rate+.20*global_rate+.12*fb_rate+explore-latency_pen
    try:
        h=MODEL_HEALTH.get(model) or {}
        if float(h.get('until',0) or 0)>_n51_time.time():score-=1.0
    except Exception:pass
    return score,{'task_calls':tc,'task_rate':task_rate,'global_calls':gc,'global_rate':global_rate,'feedback':good-bad,'latency_s':lat,'explore':explore}


def _n51_rank_models(task,candidates):
    cands=list(dict.fromkeys(candidates or []))
    stats=_n51_task_stats(task);total=sum(int(x.get('calls',0)) for x in stats.values())
    # Preserve configured order until at least some task-specific evidence exists.
    if total<5:return cands
    indexed=list(enumerate(cands))
    indexed.sort(key=lambda im:(-_n51_model_score(task,im[1],total)[0],im[0]))
    return [m for _,m in indexed]


def _n51_neuro_update(task,model,ok,latency,feedback=0,weight=1):
    if not model or model=='unknown':return
    try:
        c=_n35_conn();row=c.execute('SELECT calls,ok,fail,avg_latency,feedback_good,feedback_bad FROM neuro51_task_model WHERE task_class=? AND model=?',(task,model)).fetchone()
        calls,oks,fails,avg,good,bad=row or (0,0,0,0.0,0,0);w=max(1,int(weight));nc=calls+w
        navg=((float(avg or 0)*calls)+(float(latency or 0)*w))/max(1,nc)
        c.execute('INSERT OR REPLACE INTO neuro51_task_model(task_class,model,calls,ok,fail,avg_latency,feedback_good,feedback_bad,last_ts) VALUES(?,?,?,?,?,?,?,?,?)',
                  (task,model,nc,oks+(w if ok else 0),fails+(0 if ok else w),navg,good+(w if feedback>0 else 0),bad+(w if feedback<0 else 0),_n51_time.time()))
        c.commit();c.close()
    except Exception:_N51_STATS['errors']+=1


def _n51_neuro_log(cid,task,cands,ranked,model,ok,lat,source='runtime',feedback=0,note=''):
    try:
        c=_n35_conn();c.execute('INSERT INTO neuro51_decision(chat_id,ts,task_class,candidates,ranked,observed_model,success,latency,source,feedback,note) VALUES(?,?,?,?,?,?,?,?,?,?,?)',
          (str(cid),_n51_time.time(),task,','.join(cands)[:1800],','.join(ranked)[:1800],str(model)[:300],1 if ok else 0,float(lat or 0),source,int(feedback),_n51_safe(note,500)));c.commit();c.close()
    except Exception:pass


def _n51_last_neuro(cid):
    try:
        c=_n35_conn();r=c.execute('SELECT id,ts,task_class,candidates,ranked,observed_model,success,latency,feedback,note FROM neuro51_decision WHERE chat_id=? ORDER BY id DESC LIMIT 1',(str(cid),)).fetchone();c.close();return r
    except Exception:return None


def _n51_brain_route_text(text):
    task=_n51_task_class(text);cands=_n51_base_candidates(task,None,task in ('deep','research','code','market','finance'),False);ranked=_n51_rank_models(task,cands);ts=_n51_task_stats(task);total=sum(int(x.get('calls',0)) for x in ts.values())
    lines=['🧠 NERO — NEURAL EXPERIENCE ROUTING OPTIMIZER','Task class: '+task,'Evidence for this class: %d observed call(s)'%total,'Candidate order:']
    for i,m in enumerate(ranked,1):
        sc,why=_n51_model_score(task,m,total);lines.append('%d. %s · score %.3f · task samples %d · global samples %d'%(i,m,sc,why['task_calls'],why['global_calls']))
    lines.append('NERO is a lightweight contextual-bandit/online-learning router, not a fake neural-network claim. It only reorders models already configured in Nemo.')
    return '\n'.join(lines)[:3900]


_N51_ASK_PREV=ask_ai
def ask_ai(chat_id,text,image_b64=None,remember=True,timeout=180,long_output=False,models_override=None,deep=False,ground='',raw=False):
    # Explicit caller model choices are authoritative; NERO never rewrites them.
    eligible=bool(models_override is None and chat_id==OWNER.get('id') and isinstance(text,str) and text.strip() and not getattr(_N51_TLS,'inside',False))
    if not eligible:
        return _N51_ASK_PREV(chat_id,text,image_b64=image_b64,remember=remember,timeout=timeout,long_output=long_output,models_override=models_override,deep=deep,ground=ground,raw=raw)
    task=_n51_task_class(text,image_b64,deep,long_output);cands=_n51_base_candidates(task,image_b64,deep,long_output);ranked=_n51_rank_models(task,cands)
    t0=_n51_time.time();ans='';err=''
    try:
        _N51_TLS.inside=True;_N51_STATS['neuro_calls']+=1
        _N51_TLS.auto_models=ranked
        ans=_N51_ASK_PREV(chat_id,text,image_b64=image_b64,remember=remember,timeout=timeout,long_output=long_output,models_override=ranked,deep=deep,ground=ground,raw=raw)
        return ans
    except Exception as e:
        err=type(e).__name__+': '+str(e)[:180];raise
    finally:
        _N51_TLS.auto_models=None
        _N51_TLS.inside=False;lat=_n51_time.time()-t0
        try:model=_learn_model_from_debug(chat_id)
        except Exception:model='unknown'
        bad=bool(err or not ans or str(ans).startswith(('🧠 My brains are all busy','OpenRouter key invalid')))
        _n51_neuro_update(task,model,not bad,lat)
        _n51_neuro_log(chat_id,task,cands,ranked,model,not bad,lat,'runtime',0,err)


# ------------------------------- ACCOUNTABILITY OS -----------------------------
def _n51_aid():return 'A51-'+_n51_hashlib.sha256((str(_n51_time.time_ns())+str(_n51_os.getpid())).encode()).hexdigest()[:11].upper()


def _n51_account_event(aid,stage,status,detail='',evidence='',actor='nemo'):
    try:
        ev=_n51_hashlib.sha256((str(stage)+'\0'+str(status)+'\0'+str(evidence)).encode('utf-8','ignore')).hexdigest()[:20]
        c=_n35_conn();c.execute('INSERT INTO account51_event(request_id,ts,stage,status,actor,detail,evidence,evidence_hash) VALUES(?,?,?,?,?,?,?,?)',
          (aid,_n51_time.time(),str(stage)[:80],str(status)[:40],str(actor)[:80],_n51_safe(detail,1400),_n51_safe(evidence,1800),ev));c.commit();c.close()
    except Exception:pass


def _n51_account_start(cid,task,shadow=False):
    aid=_n51_aid();r=_n50_route(task);now=_n51_time.time()
    try:
        c=_n35_conn();c.execute('INSERT INTO account51_request(id,chat_id,ts,updated,task,route,risk,status,outcome) VALUES(?,?,?,?,?,?,?,?,?)',
          (aid,str(cid),now,now,_n51_safe(task,3500),str(r.get('intent',''))[:120],str(r.get('risk','LOW'))[:40],'SHADOW' if shadow else 'RECEIVED',''));c.commit();c.close()
    except Exception:pass
    _n51_account_event(aid,'RECEIVED','OK','request accepted; shadow='+str(bool(shadow)),'','owner');_N51_STATS['accounts']+=1
    return aid


def _n51_account_finish(aid,rid,started,result_text=''):
    status='UNKNOWN';err='';receipts=[]
    try:
        c=_n35_conn();r=c.execute('SELECT status,error FROM exec50_run WHERE id=?',(rid,)).fetchone();
        if r:status,err=r[0],r[1] or ''
        receipts=c.execute('SELECT step_idx,action,status,evidence FROM receipt50 WHERE run_id=? ORDER BY step_idx,ts',(rid,)).fetchall();c.close()
    except Exception:pass
    vc=sum(1 for x in receipts if x[2]=='VERIFIED');ec=sum(1 for x in receipts if x[2]=='EXECUTED');fc=sum(1 for x in receipts if x[2]=='FAILED')
    if status in ('SHADOW','SHADOW_COMPLETE'):outcome='SHADOW_ONLY'
    elif status=='FAILED' or fc:outcome='FAILED'
    elif status=='PARTIAL':outcome='PARTIAL'
    elif status=='COMPLETE' and receipts and vc==len(receipts):outcome='VERIFIED_COMPLETE'
    elif status=='COMPLETE' and receipts:outcome='COMPLETED_WITH_UNVERIFIED_STEPS'
    elif status=='COMPLETE':outcome='COMPLETE_NO_RECEIPT'
    else:outcome=status or 'UNKNOWN'
    dur=int((_n51_time.time()-started)*1000)
    try:
        c=_n35_conn();c.execute('UPDATE account51_request SET updated=?,status=?,v50_run_id=?,evidence_count=?,verified_count=?,executed_count=?,failed_count=?,duration_ms=?,outcome=?,result=?,error=? WHERE id=?',
          (_n51_time.time(),status,rid,len(receipts),vc,ec,fc,dur,outcome,_n51_safe(result_text,2500),_n51_safe(err,1000),aid));c.commit();c.close()
    except Exception:pass
    for x in receipts:_n51_account_event(aid,'STEP_'+str(x[0]),x[2],x[1],x[3],'tool')
    _n51_account_event(aid,'FINAL',outcome,'v50 status='+str(status),'%d receipt(s), %d verified'%(len(receipts),vc),'nemo')
    if outcome=='VERIFIED_COMPLETE':_N51_STATS['verified']+=1
    elif outcome=='FAILED':_N51_STATS['failed']+=1
    elif outcome not in ('SHADOW_ONLY',):_N51_STATS['partial']+=1
    return outcome,vc,len(receipts),dur


_N51_RUN_PREV=_n50_run
def _n50_run(cid,text,shadow=False):
    aid=_n51_account_start(cid,text,shadow);started=_n51_time.time();rid=''
    try:
        rid,res=_N51_RUN_PREV(cid,text,shadow)
        outcome,vc,rc,dur=_n51_account_finish(aid,rid,started,res)
        return rid,(str(res)+'\n\n🧾 Accountability '+aid+' · '+outcome+' · evidence %d/%d verified'%(vc,rc))[:3900]
    except Exception as e:
        _n51_account_event(aid,'FINAL','FAILED',type(e).__name__,str(e)[:500]);_N51_STATS['failed']+=1
        try:
            c=_n35_conn();c.execute("UPDATE account51_request SET updated=?,status='FAILED',outcome='FAILED',error=?,duration_ms=? WHERE id=?",(_n51_time.time(),_n51_safe(type(e).__name__+': '+str(e),1000),int((_n51_time.time()-started)*1000),aid));c.commit();c.close()
        except Exception:pass
        raise


def _n51_account_rows(cid,limit=15):
    try:
        c=_n35_conn();r=c.execute('SELECT id,updated,task,route,risk,status,outcome,evidence_count,verified_count,failed_count,duration_ms,v50_run_id,error FROM account51_request WHERE chat_id=? ORDER BY updated DESC LIMIT ?',(str(cid),int(limit))).fetchall();c.close();return r
    except Exception:return []


def _n51_account_text(cid,aid=''):
    try:
        c=_n35_conn()
        if aid:
            r=c.execute('SELECT id,updated,task,route,risk,status,outcome,evidence_count,verified_count,failed_count,duration_ms,v50_run_id,error FROM account51_request WHERE chat_id=? AND id=?',(str(cid),aid)).fetchone()
            ev=c.execute('SELECT ts,stage,status,actor,detail,evidence,evidence_hash FROM account51_event WHERE request_id=? ORDER BY ts',(aid,)).fetchall();c.close()
            if not r:return 'Accountability record not found.'
            lines=['🧾 ACCOUNTABILITY '+r[0],'Outcome: '+str(r[6])+' · runtime status '+str(r[5]),'Route: '+str(r[3])+' · risk '+str(r[4]),'Evidence: %d receipts · %d verified · %d failed'%(r[7],r[8],r[9]),'Duration: %d ms'%r[10],'Task: '+r[2][:700]]
            for x in ev[-20:]:lines.append('%s · %s · %s — %s%s'%(x[1],x[2],x[3],x[4][:180],(' | evidence: '+x[5][:220]) if x[5] else ''))
            if r[12]:lines.append('Error: '+r[12][:500])
            return '\n'.join(lines)[:3900]
        rows=c.execute('SELECT id,updated,task,route,risk,status,outcome,evidence_count,verified_count,failed_count,duration_ms,v50_run_id,error FROM account51_request WHERE chat_id=? ORDER BY updated DESC LIMIT 15',(str(cid),)).fetchall();c.close()
    except Exception:rows=[]
    if not rows:return 'No v51 accountability runs yet. /run50 automatically creates them.'
    lines=['🧾 NEMO ACCOUNTABILITY — RECENT']
    for r in rows:lines.append('%s · %s · %d/%d verified · %dms\n  %s'%(r[0],r[6],r[8],r[7],r[10],r[2][:130]))
    return '\n'.join(lines)[:3900]


def _n51_trust_text(cid):
    rows=_n51_account_rows(cid,100)
    if not rows:return 'No evidence-backed execution history yet.'
    nonshadow=[r for r in rows if r[6]!='SHADOW_ONLY'];n=len(nonshadow);ver=sum(1 for r in nonshadow if r[6]=='VERIFIED_COMPLETE');fail=sum(1 for r in nonshadow if r[6]=='FAILED');partial=n-ver-fail
    rec=sum(int(r[7] or 0) for r in nonshadow);vrec=sum(int(r[8] or 0) for r in nonshadow)
    coverage=(100.0*vrec/max(1,rec)) if rec else 0.0
    return ('📐 ACCOUNTABILITY COVERAGE\nExecutions observed: %d\nVerified complete: %d\nPartial/unverified: %d\nFailed: %d\nReceipt verification coverage: %.1f%%\n\nThis is evidence coverage, NOT a made-up probability that Nemo is truthful.'%(n,ver,partial,fail,coverage))


# ------------------------------- REAL HANDS PACK -------------------------------
def _n51_market_symbol(text):
    t=str(text or '').upper()
    if 'BANKNIFTY' in t or 'BANK NIFTY' in t:return '^NSEBANK'
    if 'SENSEX' in t:return '^BSESN'
    if 'NIFTY' in t:return '^NSEI'
    if 'S&P' in t or 'SP500' in t or 'S&P 500' in t:return '^GSPC'
    if 'NASDAQ' in t:return '^IXIC'
    # explicit common ticker-ish token, otherwise Nifty.
    m=_n51_re.search(r'\b[A-Z]{2,12}(?:\.NS)?\b',str(text or ''))
    return m.group(0) if m and m.group(0) not in ('WHY','MARKET','MARKETS','INDIAN','GLOBAL','TODAY','REPORT') else '^NSEI'


def _n51_market_explain(cid,q):
    syms=[('^NSEI','Nifty 50'),('^BSESN','Sensex'),('^GSPC','S&P 500'),('^IXIC','Nasdaq'),('USDINR=X','USD/INR'),('CL=F','Crude'),('GC=F','Gold')]
    live=[]
    for sym,label in syms:
        try:
            x=get_quote(sym)
            if x and x.get('price') is not None:
                pct=((x['price']-x['prev'])/x['prev']*100.0) if x.get('prev') else None
                live.append('%s: %.2f%s'%(label,float(x['price']),(' (%+.2f%%)'%pct) if pct is not None else ''))
        except Exception:pass
    rows=web_search('global indian stock markets nifty sensex today reasons '+str(q)[:500]) or []
    ctx='\n'.join('[%d] %s — %s'%(i+1,r.get('title',''),r.get('body','')[:450]) for i,r in enumerate(rows[:6]))
    if not live and not rows:return {'ok':False,'text':'Live market/news evidence is unavailable right now.','evidence':'no live quote or web evidence'}
    prompt=('You are Nemo market evidence analyst. Explain the CURRENT move asked by the owner using ONLY the live data/news packet below. Separate OBSERVED DATA, LIKELY DRIVERS, INDIA-SPECIFIC DRIVERS, GLOBAL DRIVERS, and WHAT TO WATCH NEXT. Do not invent a cause merely because two events coincide. Do not give a buy/sell order.\n\nOWNER REQUEST:\n'+str(q)+'\n\nLIVE DATA:\n'+'\n'.join(live)+'\n\nCURRENT SEARCH EVIDENCE:\n'+ctx)
    ans=_N51_ASK_PREV(cid,prompt,remember=False,timeout=180,long_output=True,models_override=list(SMART_MODELS),raw=False)
    return {'ok':bool(ans),'text':str(ans or ''),'evidence':'%d live instruments + %d search results'%(len(live),len(rows)),'sources':[r.get('href','') for r in rows[:6]]}


def _n51_research_answer(cid,q):
    _N51_STATS['research']+=1
    try:ctx,rows,health=omni_context(q,True,18,14000)
    except Exception:ctx='';rows=[];health={}
    # Supplement OmniSource with general web results for current topics.
    wr=web_search(q) or []
