    if not ctx and not wctx:return {'ok':False,'text':'No research source returned usable evidence. I did not invent an answer.','evidence':'0 evidence items'}
    prompt=('You are NEMO DEEP RESEARCH CELL. Synthesize the owner request from the supplied evidence only. Distinguish CONFIRMED EVIDENCE, INFERENCE, DISAGREEMENT/UNCERTAINTY, and PRACTICAL CONCLUSION. Prefer primary/institutional/current sources when relevant. Never fabricate a source or number.\n\nREQUEST:\n'+str(q)+'\n\nOMNISOURCE:\n'+ctx+'\n\nWEB:\n'+wctx)
    ans=_N51_ASK_PREV(cid,prompt,remember=False,timeout=240,long_output=True,models_override=list(SMART_MODELS),raw=False)
