        t=_n51_time.time();ok=False;detail=''
        try:
            c=_n51_sqlite.connect('file:'+p+'?mode=ro',uri=True,timeout=.8);row=c.execute('PRAGMA quick_check').fetchone();c.close();detail=str(row[0] if row else 'no result');ok=(detail.lower()=='ok')
        except Exception as e:detail=type(e).__name__+': '+str(e)[:160]
