def _n51_backup_audit():
    root='/root/nemo_backups';files=[]
    try:
        if _n51_os.path.isdir(root):
            for p in _n51_glob.glob(root+'/*'):
                try:
                    if _n51_os.path.isfile(p):files.append((_n51_os.path.getmtime(p),_n51_os.path.getsize(p),_n51_os.path.basename(p)))
                except Exception:pass
    except Exception:pass
    files.sort(reverse=True);total=sum(x[1] for x in files)
    txn={}
    try:
        if _n51_os.path.exists('/root/nemo_update_txn.json'):txn=_n51_jsonlib.load(open('/root/nemo_update_txn.json'))
    except Exception:txn={}
    return {'count':len(files),'total_mb':round(total/1048576.0,2),'newest':[{'name':x[2],'bytes':x[1],'age_hours':round((_n51_time.time()-x[0])/3600.0,1)} for x in files[:8]],'update_journal_present':bool(txn),'journal_keys':sorted(list(txn.keys()))[:20] if isinstance(txn,dict) else []}


def _n51_network_health():
    hosts=['api.telegram.org','openrouter.ai','www.googleapis.com','generativelanguage.googleapis.com'];rows=[]
    for h in hosts:
        t=_n51_time.time();ok=False;ip='';err=''
