def _n51_log_read(name='nemobot',n=80):
    name=_n51_re.sub(r'[^A-Za-z0-9_.@-]','',str(name or 'nemobot'))[:80] or 'nemobot';n=max(10,min(200,int(n or 80)))
    txt=app_logs(name,n);lines=str(txt or '').splitlines();err=[x for x in lines if _n51_re.search(r'(?i)\b(error|exception|traceback|failed|fatal|critical)\b',x)]
    return {'service':name,'lines':len(lines),'errorish':len(err),'error_excerpt':err[-12:],'tail':'\n'.join(lines[-35:])[-3500:]}


