      ('brain.council','brain','Independent configured-model council plus judge','LOW','OWNER_READ','_n51_council',{'query':'string'}),
      ('market.quote','market','Current/delayed quote through existing market source','LOW','OWNER_READ','get_quote',{'symbol':'string'}),
      ('market.explain','market','Evidence-backed current market move explanation','LOW','OWNER_READ','_n51_market_explain',{'query':'string'}),
      ('news.brief','research','Current news titles/snippets through existing web search','LOW','OWNER_READ','get_news_brief',{'topic':'string'}),
      ('weather.current','research','Current weather + forecast through existing Open-Meteo hand','LOW','OWNER_READ','get_weather',{'city':'string'}),
      ('google.mail_unread','communication','Read unread Gmail metadata/snippets through connected Google account','MEDIUM','OWNER_READ','gmail_unread',{'limit':'int'}),
      ('google.drive_search','knowledge','Search connected Google Drive file metadata','MEDIUM','OWNER_READ','gdrive_search',{'query':'string'}),
      ('system.snapshot','systems','Read process/RAM/disk/thread runtime snapshot','LOW','OWNER_READ','_n51_system',{}),
      ('logs.read','systems','Read local systemd service logs','LOW','OWNER_READ','_n51_log_read',{'service':'string','lines':'int'}),
      ('database.quickcheck','systems','Read-only SQLite PRAGMA quick_check across Nemo stores','LOW','OWNER_READ','_n51_db_quickcheck',{}),
      ('backup.audit','systems','Read backup inventory and update-journal metadata','LOW','OWNER_READ','_n51_backup_audit',{}),
