# Extended planner for new tools + explicit missing-input gate.
_N51_PLAN_PREV=_n50_plan
def _n50_plan(cid,text,shadow=False,persist=True):
    route=_n50_route(text);rid='R51-'+_n50_hashlib.sha256((str(_n51_time.time_ns())+str(cid)).encode()).hexdigest()[:10].upper();t=route['text'];low=t.lower();steps=[]
    def step(name,tool,args=None,depends=None):steps.append({'idx':len(steps)+1,'name':name,'tool':tool,'args':args or {},'depends':depends or []})
    emails=route.get('emails') or [];email_to=emails[0] if emails else ''
    if route.get('email_missing'):
        step('Need email recipient','clarify.required',{'question':'I can do the report/research, but I need the complete recipient email address. If you mean your configured owner address, say “email me”.'})
    else:
        if 'memory.cross_search' in route['tools']:step('Search personal knowledge','memory.cross_search',{'query':t})
        for u in (route.get('urls') or [])[:2]:step('Fetch explicit page','web.fetch',{'url':u,'want':t})
        if 'research.omni' in route['tools']:step('Deep multi-source research','research.omni',{'query':t})
        if 'market.explain' in route['tools']:step('Explain current market move','market.explain',{'query':t})
        elif 'market.history' in route['tools']:step('Read market history','market.history',{'symbol':_n51_market_symbol(t)})
        if 'market.quote' in route['tools']:step('Read market quote','market.quote',{'symbol':_n51_market_symbol(t)})
        if 'web.search' in route['tools']:step('Research fresh web evidence','web.search',{'query':t})
        if 'news.brief' in route['tools']:step('Read news brief','news.brief',{'topic':t})
        if 'weather.current' in route['tools']:
            city=_n51_re.sub(r'(?i).*?\b(?:weather|forecast|temperature|rain)\b(?:\s+(?:in|for))?\s*','',t).strip(' ?') or 'Udaipur'
            step('Read weather','weather.current',{'city':city[:120]})
        if 'google.mail_unread' in route['tools']:step('Read unread Gmail','google.mail_unread',{'limit':8})
        if 'google.drive_search' in route['tools']:
            q=_n51_re.sub(r'(?i).*?\b(?:drive|google drive)\b','',t).strip(' :?-') or t
            step('Search Google Drive','google.drive_search',{'query':q[:300]})
        if 'system.snapshot' in route['tools']:step('Read system snapshot','system.snapshot',{})
        if 'database.quickcheck' in route['tools']:step('Check Nemo databases','database.quickcheck',{})
        if 'backup.audit' in route['tools']:step('Audit backups','backup.audit',{})
        if 'security.local_audit' in route['tools']:step('Run local security audit','security.local_audit',{})
        if 'network.health' in route['tools']:step('Check core network paths','network.health',{})
        if 'logs.read' in route['tools']:
            m=_n51_re.search(r'(?i)\b(?:logs?|service)\s+(?:for\s+)?([A-Za-z0-9_.@-]{2,80})',t);svc=m.group(1) if m else 'nemobot'
            step('Read service logs','logs.read',{'service':svc,'lines':80})
        if 'brain.council' in route['tools']:step('Ask multi-brain council','brain.council',{'query':t})
        if 'artifact.pdf' in route['tools']:
            topic=t
            if email_to:
                topic=_N50_EMAIL_RE.sub('',topic);topic=_n51_re.sub(r'(?i)\b(?:and\s+)?(?:also\s+)?(?:email|mail|send)(?:\s+it|\s+me|\s+this|\s+the\s+report)?(?:\s+to)?\s*[:,-]?\s*',' ',topic);topic=' '.join(topic.split()).strip(' ,.-') or t
            step('Build researched PDF report','artifact.pdf',{'topic':topic,'email_to':email_to})
        if 'artifact.docx' in route['tools']:step('Build Word document','artifact.docx',{'topic':t,'email_to':email_to})
        if 'artifact.chart' in route['tools']:step('Build chart','artifact.chart',{'spec':t})
        if 'email.send' in route['tools']:step('Send explicit email','email.send',{'to':email_to,'subject':'Nemo message','body':t})
        if 'browser.agent' in route['tools']:step('Browser task','browser.agent',{'goal':t})
        if 'server.shell' in route['tools']:step('Server command','server.shell',{'cmd':t})
        if not steps:step('Answer normally','brain.chat',{'query':t})
    if persist:
        now=_n51_time.time();c=_n35_conn()
        try:
            c.execute('INSERT INTO exec50_run(id,chat_id,created,updated,task,status,shadow,route_json) VALUES(?,?,?,?,?,?,?,?)',(rid,str(cid),now,now,_n50_safe_text(t,4000),'PLANNED',1 if shadow else 0,_n50_j(route)))
            for s in steps:c.execute('INSERT INTO exec50_step(run_id,idx,name,tool,args_json,depends_json,status) VALUES(?,?,?,?,?,?,?)',(rid,s['idx'],s['name'],s['tool'],_n50_j(s['args']),_n50_j(s['depends']),'PLANNED'))
            c.commit();_N50_STATS['plans']+=1
        finally:c.close()
    return rid,route,steps


_N51_EXEC_PREV=_n50_execute_tool
