# ------------------------------- SOURCE / ARCHITECTURE AUDIT -------------------
def _n51_source_audit(store=True):
    try:src=open(__file__,encoding='utf-8',errors='ignore').read();raw=src.encode('utf-8',errors='ignore')
    except Exception:return {'ok':False,'error':'source unavailable'}
    try:tree=__import__('ast').parse(src)
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)[:120]}
    import ast as _a
    funcs=[n.name for n in _a.walk(tree) if isinstance(n,(_a.FunctionDef,_a.AsyncFunctionDef))];classes=[n.name for n in _a.walk(tree) if isinstance(n,_a.ClassDef)]
    from collections import Counter as _C
    cnt=_C(funcs);dups={k:v for k,v in cnt.items() if v>1};guards=0
    for n in tree.body:
        if isinstance(n,_a.If):
            try:
                if isinstance(n.test,_a.Compare) and isinstance(n.test.left,_a.Name) and n.test.left.id=='__name__':guards+=1
            except Exception:pass
    dbpaths=sorted(set(_n51_re.findall(r"['\"](/root/[^'\"]+?\.(?:db|sqlite|sqlite3|json|txt|log))['\"]",src)))
    r={'ok':True,'version':VERSION,'bytes':len(raw),'lines':src.count('\n')+1,'functions':len(funcs),'classes':len(classes),'handle_defs':cnt.get('handle',0),'ask_defs':cnt.get('ask_ai',0),'main_defs':cnt.get('main',0),'duplicate_func_names':len(dups),'thread_spawns':len(_n51_re.findall(r'\.Thread\s*\(',src)),'version_assignments':len(_n51_re.findall(r"(?m)^VERSION\s*=\s*['\"]",src)),'db_paths':len(dbpaths),'main_guards':guards,'sha256':_n51_hashlib.sha256(raw).hexdigest(),'top_duplicates':sorted(dups.items(),key=lambda x:(-x[1],x[0]))[:15],'paths':dbpaths[:80]}
    r['risks']=[]
    if r['handle_defs']>30:r['risks'].append('very deep handle-wrapper stack')
    if r['ask_defs']>8:r['risks'].append('deep ask_ai wrapper stack')
    if r['main_defs']>20:r['risks'].append('many historical main wrappers')
    if r['thread_spawns']>200:r['risks'].append('large background-thread surface; monitor duplicate loops')
    if store:
        try:
            c=_n35_conn();c.execute('INSERT INTO audit51_snapshot(ts,version,bytes,lines,functions,classes,handle_defs,ask_defs,main_defs,duplicate_func_names,thread_spawns,version_assignments,db_paths,main_guards,sha256,detail) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',(_n51_time.time(),VERSION,r['bytes'],r['lines'],r['functions'],r['classes'],r['handle_defs'],r['ask_defs'],r['main_defs'],r['duplicate_func_names'],r['thread_spawns'],r['version_assignments'],r['db_paths'],r['main_guards'],r['sha256'],_n51_json({'risks':r['risks'],'top_duplicates':r['top_duplicates']},3500)));c.commit();c.close()
        except Exception:pass
    return r


def _n51_audit_text():
    a=_n51_source_audit(True)
    if not a.get('ok'):return 'Audit unavailable: '+str(a.get('error'))
    return ('🔬 NEMO WHOLE-SOURCE AUDIT — v%s\n'%VERSION+
      'Source: %d lines · %.2f MB · SHA %s…\n'%(a['lines'],a['bytes']/1048576.0,a['sha256'][:16])+
      'Functions: %d · classes: %d · duplicate function names: %d\n'%(a['functions'],a['classes'],a['duplicate_func_names'])+
      'Wrapper surface: handle×%d · ask_ai×%d · main×%d\n'%(a['handle_defs'],a['ask_defs'],a['main_defs'])+
      'Thread construction sites: %d · VERSION assignments: %d · persistent file/DB literals: %d\n'%(a['thread_spawns'],a['version_assignments'],a['db_paths'])+
      'Effective production __main__ guards: %d\n'%a['main_guards']+
      'Top duplicate defs: '+', '.join('%s×%d'%x for x in a['top_duplicates'][:10])+'\n'+
      'Architecture flags: '+('; '.join(a['risks']) if a['risks'] else 'none from structural thresholds')+'\n\n'+
      'Interpretation: Fast Core/Tool Fabric reduce runtime cost, but historical wrappers remain technical debt. Do not mass-delete them in a live release; consolidate by measured routing and regression-backed migration.')[:3900]


