def _n51_hands_text():
    names=['research.omni','brain.council','market.quote','market.explain','news.brief','weather.current','google.mail_unread','google.drive_search','system.snapshot','logs.read','database.quickcheck','backup.audit','security.local_audit','network.health']
    return '🦾 NEMO HANDS PACK — %d NEW/UPGRADED TOOLS\n'%len(names)+'\n'.join('• '+x for x in names)+'\n\nUse /tools50 <word>, /route50 <request>, /shadow50 <request>, or /run50 <request>. Consequential browser/shell/money authority is unchanged.'


def _n51_neuro_status(cid):
    try:
        c=_n35_conn();rows=c.execute('SELECT task_class,model,calls,ok,fail,avg_latency,feedback_good,feedback_bad FROM neuro51_task_model ORDER BY calls DESC LIMIT 30').fetchall();dec=c.execute('SELECT COUNT(*) FROM neuro51_decision').fetchone()[0];c.close()
    except Exception:rows=[];dec=0
    lines=['🧠 NERO — ADAPTIVE BRAIN ROUTER','Recorded routing decisions: %d'%dec]
    if not rows:lines.append('No task-specific samples yet; configured model order is preserved until evidence accumulates.')
    else:
        for r in rows[:15]:lines.append('%s · %s · %d calls · %d ok/%d fail · %.1fs · feedback %+d'%(r[0],r[1],r[2],r[3],r[4],float(r[5] or 0),int(r[6] or 0)-int(r[7] or 0)))
    lines.append('\n/brainroute51 <request> · /rate51 good|bad [note] · /council51 <question>')
    return '\n'.join(lines)[:3900]


def _n51_rate(cid,arg):
    p=str(arg or '').strip().split(None,1)
    if not p or p[0].lower() not in ('good','bad','up','down','+','-'):return 'Use /rate51 good [note] or /rate51 bad [note] after an answer.'
    last=_n51_last_neuro(cid)
    if not last:return 'No NERO decision exists yet.'
    good=p[0].lower() in ('good','up','+');note=p[1] if len(p)>1 else ''
    task,model=last[2],last[5]
    if not model or model=='unknown':return 'The last answer did not expose a measurable model identity, so I will not assign fake credit.'
    _n51_neuro_update(task,model,good,float(last[7] or 0),1 if good else -1,3);_n51_neuro_log(cid,task,(last[3] or '').split(','),(last[4] or '').split(','),model,good,float(last[7] or 0),'owner-feedback',1 if good else -1,note);_N51_STATS['neuro_feedback']+=1
    return ('✅' if good else '⚠️')+' Feedback applied to '+model+' for task class '+task+'. NERO will use this as weighted routing evidence.'


