_N51_HANDLE_PREV=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');chat=msg.get('chat') or {};txt=(msg.get('text') or '').strip();low=txt.lower()
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id') and low.startswith(('/nemo51','/hands51','/nero51','/brainroute51','/rate51','/council51','/research51','/accountability51','/trust51','/audit51')):
            send_text(cid,'That command is owner-only.');return
        if cid==OWNER.get('id') and chat.get('type','private')=='private':
            if low in ('/nemo51','/neuro51','/accountos51'):send_text(cid,_n51_status(cid));return
            if low in ('/hands51','/tools51'):send_text(cid,_n51_hands_text());return
            if low in ('/nero51','/brains51'):send_text(cid,_n51_neuro_status(cid));return
            if low.startswith('/brainroute51'):
                q=txt[len('/brainroute51'):].strip();send_text(cid,_n51_brain_route_text(q) if q else 'Usage: /brainroute51 <request>');return
            if low.startswith('/rate51'):
                send_text(cid,_n51_rate(cid,txt[len('/rate51'):].strip()));return
            if low.startswith('/council51'):
                q=txt[len('/council51'):].strip()
                if not q:send_text(cid,'Usage: /council51 <question>');return
                send_text(cid,'🧠 Brain Council is consulting independent configured models...')
                def _cc():
                    try:
                        x=_n51_council(cid,q);send_text(cid,x.get('text','Council returned no answer.')+'\n\nEvidence: '+x.get('evidence',''))
                    except Exception as e:send_text(cid,'Council failed safely: '+type(e).__name__+': '+str(e)[:300])
                _n51_threading.Thread(target=_cc,daemon=True,name='nemo-council51').start();return
            if low.startswith('/research51'):
                q=txt[len('/research51'):].strip()
                if not q:send_text(cid,'Usage: /research51 <question>');return
                send_text(cid,'🔎 Deep Research Cell: gathering independent evidence...')
                def _rr():
                    try:
                        x=_n51_research_answer(cid,q);send_text(cid,x.get('text','No research answer.')+'\n\nEvidence: '+x.get('evidence',''))
                    except Exception as e:send_text(cid,'Research failed safely: '+type(e).__name__+': '+str(e)[:300])
                _n51_threading.Thread(target=_rr,daemon=True,name='nemo-research51').start();return
            if low.startswith('/accountability51'):
                aid=txt[len('/accountability51'):].strip().upper();send_text(cid,_n51_account_text(cid,aid));return
            if low in ('/trust51','/verification51'):send_text(cid,_n51_trust_text(cid));return
            if low in ('/audit51','/architecture51'):send_text(cid,_n51_audit_text());return
    except Exception:_N51_STATS['errors']+=1
    return _N51_HANDLE_PREV(msg)


