def _n52_init():
    global _N52_INIT_DONE
    c=_n35_conn();c.executescript("""
    CREATE TABLE IF NOT EXISTS kernel52_request(
      id TEXT PRIMARY KEY, chat_id TEXT, ts REAL, updated REAL, fingerprint TEXT,
      parent_id TEXT DEFAULT '', task TEXT, intent TEXT, risk TEXT, status TEXT,
      shadow INTEGER DEFAULT 0, run_id TEXT DEFAULT '', account_id TEXT DEFAULT '',
      current_step INTEGER DEFAULT 0, total_steps INTEGER DEFAULT 0,
      verified_steps INTEGER DEFAULT 0, result TEXT DEFAULT '', error TEXT DEFAULT '',
      duration_ms INTEGER DEFAULT 0, duplicate_of TEXT DEFAULT '');
    CREATE INDEX IF NOT EXISTS idx_kernel52_chat ON kernel52_request(chat_id,updated DESC);
    CREATE INDEX IF NOT EXISTS idx_kernel52_fp ON kernel52_request(chat_id,fingerprint,ts DESC);
    CREATE TABLE IF NOT EXISTS kernel52_event(
      id INTEGER PRIMARY KEY AUTOINCREMENT, request_id TEXT, ts REAL, stage TEXT,
      status TEXT, detail TEXT, evidence TEXT DEFAULT '', hash TEXT DEFAULT '');
    CREATE INDEX IF NOT EXISTS idx_kernel52_event ON kernel52_event(request_id,ts);
    CREATE TABLE IF NOT EXISTS tool52_perf(
      tool TEXT PRIMARY KEY, calls INTEGER DEFAULT 0, verified INTEGER DEFAULT 0,
      partial INTEGER DEFAULT 0, failed INTEGER DEFAULT 0, avg_latency REAL DEFAULT 0,
      last_latency REAL DEFAULT 0, last_status TEXT DEFAULT '', last_ts REAL DEFAULT 0);
    CREATE TABLE IF NOT EXISTS agent52_run(
      id TEXT PRIMARY KEY, chat_id TEXT, ts REAL, task TEXT, status TEXT,
      evidence TEXT DEFAULT '', synthesis TEXT DEFAULT '', duration_ms INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS agent52_seat(
      id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT, role TEXT, model TEXT,
      status TEXT, latency REAL DEFAULT 0, answer TEXT DEFAULT '', error TEXT DEFAULT '');
    CREATE INDEX IF NOT EXISTS idx_agent52_run ON agent52_seat(run_id,id);
    CREATE TABLE IF NOT EXISTS retry52_link(
      child_run TEXT PRIMARY KEY, parent_run TEXT, step_idx INTEGER, tool TEXT,
      ts REAL, status TEXT DEFAULT 'CREATED');
    """);c.commit();c.close()
    _n52_register_tools()
    _N52_INIT_DONE=True


def _n52_ensure_init():
    global _N52_INIT_DONE
    if _N52_INIT_DONE:return True
    try:_n52_init();return True
    except Exception:return False


def _n52_safe(v,n=2200):
    try:return _n50_safe_text(v,n)
    except Exception:return str(v or '')[:n]


def _n52_j(v,n=5000):
    try:return _n50_j(v,n)
    except Exception:
        try:return _n52_json.dumps(v,ensure_ascii=False,default=str)[:n]
        except Exception:return '{}'


def _n52_fp(cid,text,shadow=False):
    t=' '.join(str(text or '').lower().split())
    # email local-parts are retained in the fingerprint but obvious secrets are not.
    try:
        if _n49_sensitive(t):t='[sensitive-command]'
    except Exception:pass
    return _n52_hashlib.sha256((str(cid)+'\0'+('S' if shadow else 'R')+'\0'+t).encode('utf-8','ignore')).hexdigest()[:28]


def _n52_kid():return 'K52-'+_n52_uuid.uuid4().hex[:11].upper()


def _n52_event(kid,stage,status,detail='',evidence=''):
    try:
        h=_n52_hashlib.sha256((str(stage)+'\0'+str(status)+'\0'+str(evidence)).encode('utf-8','ignore')).hexdigest()[:20]
        c=_n35_conn();c.execute('INSERT INTO kernel52_event(request_id,ts,stage,status,detail,evidence,hash) VALUES(?,?,?,?,?,?,?)',
          (kid,_n52_time.time(),str(stage)[:80],str(status)[:40],_n52_safe(detail,1500),_n52_safe(evidence,1800),h));c.commit();c.close()
    except Exception:pass


def _n52_recent_duplicate(cid,fp,seconds=35):
    try:
        c=_n35_conn();r=c.execute("SELECT id,status,run_id,result,updated FROM kernel52_request WHERE chat_id=? AND fingerprint=? AND ts>? AND status IN ('COMPLETE','VERIFIED_COMPLETE','PARTIAL','NEEDS_INPUT','SHADOW_COMPLETE','RUNNING') ORDER BY ts DESC LIMIT 1",
          (str(cid),fp,_n52_time.time()-seconds)).fetchone();c.close();return r
    except Exception:return None


def _n52_kernel_start(cid,text,shadow=False,parent=''):
    _n52_ensure_init()
    fp=_n52_fp(cid,text,shadow);dup=_n52_recent_duplicate(cid,fp)
    if dup:return None,dup
    kid=_n52_kid();route=_n50_route(text);now=_n52_time.time()
    try:
        c=_n35_conn();c.execute('INSERT INTO kernel52_request(id,chat_id,ts,updated,fingerprint,parent_id,task,intent,risk,status,shadow) VALUES(?,?,?,?,?,?,?,?,?,?,?)',
          (kid,str(cid),now,now,fp,str(parent or ''),_n52_safe(text,4000),str(route.get('intent',''))[:120],str(route.get('risk','LOW'))[:40],'RECEIVED',1 if shadow else 0));c.commit();c.close()
    except Exception:pass
    _n52_event(kid,'RECEIVED','OK','canonical request envelope created')
    _N52_STATS['kernel']+=1
    return kid,None


def _n52_kernel_finish(kid,rid,res,started):
    status='UNKNOWN';steps=[]
    try:
        c=_n35_conn();rr=c.execute('SELECT status,error FROM exec50_run WHERE id=?',(rid,)).fetchone();steps=c.execute('SELECT idx,tool,status,result,error FROM exec50_step WHERE run_id=? ORDER BY idx',(rid,)).fetchall();c.close()
        if rr:status=rr[0] or status;err=rr[1] or ''
        else:err='run record missing'
    except Exception as e:err=type(e).__name__+': '+str(e)[:300]
    verified=sum(1 for x in steps if x[2]=='VERIFIED')
    total=len(steps)
    if status=='COMPLETE' and total and verified==total:outcome='VERIFIED_COMPLETE'
    elif status=='COMPLETE':outcome='COMPLETE'
    elif status in ('SHADOW_COMPLETE','SHADOW'):outcome='SHADOW_COMPLETE'
    else:outcome=status
    dur=int((_n52_time.time()-started)*1000)
    try:
        c=_n35_conn();c.execute('UPDATE kernel52_request SET updated=?,status=?,run_id=?,current_step=?,total_steps=?,verified_steps=?,result=?,error=?,duration_ms=? WHERE id=?',
          (_n52_time.time(),outcome,str(rid or ''),max([x[0] for x in steps] or [0]),total,verified,_n52_safe(res,3000),_n52_safe(err,1000),dur,kid));c.commit();c.close()
    except Exception:pass
    _n52_event(kid,'FINAL',outcome,'run='+str(rid)+'; duration_ms='+str(dur),'%d/%d steps verified'%(verified,total))
    return outcome,verified,total,dur


# ------------------------------- TOOL SCHEMA / GROUNDING -----------------------
def _n52_tool_row(tool):
    try:
        c=_n35_conn();r=c.execute('SELECT name,risk,permission,schema_json,enabled,health FROM tool50_registry WHERE name=?',(str(tool),)).fetchone();c.close();return r
    except Exception:return None


def _n52_schema(tool):
    r=_n52_tool_row(tool)
    if not r:return {}
    try:return _n52_json.loads(r[3] or '{}')
    except Exception:return {}


def _n52_validate_step(original_text,s):
    """Fail closed on malformed/generated tool args. No external effects here."""
    tool=str(s.get('tool') or '');a=s.get('args') or {};errs=[];schema=_n52_schema(tool)
    if not isinstance(a,dict):return False,['args are not an object']
    for k,typ in schema.items():
        optional=str(typ).endswith('?');base=str(typ).rstrip('?')
        v=a.get(k)
        if (v is None or v=='') and not optional:
            errs.append('missing '+str(k));continue
        if v in (None,''):continue
        if base=='email' and not _n50_emails(str(v)):errs.append(str(k)+' is not a valid email')
        elif base=='url' and not _n50_explicit_urls(str(v)):errs.append(str(k)+' is not an http(s) URL')
        elif base=='int':
            try:int(v)
            except Exception:errs.append(str(k)+' is not an integer')
        elif base in ('number','float'):
            try:float(v)
            except Exception:errs.append(str(k)+' is not numeric')
    # Ground consequential destinations in current request. Never allow an LLM/planner
    # to smuggle in a different email/URL target.
    if tool=='email.send':
        to=str(a.get('to') or '')
        allowed=_n50_emails(original_text)
        own=_n51_owner_email_for(original_text)
        if own:allowed=list(dict.fromkeys(allowed+[own]))
        if not to or to not in allowed:errs.append('email target is not grounded in the current request')
    if tool=='web.fetch':
        u=str(a.get('url') or '')
        if u and u not in _n50_explicit_urls(original_text):errs.append('URL is not explicit in the current request')
    if tool=='server.shell':errs.append('generic Kernel executor does not expand shell authority')
    ok=not errs
    _N52_STATS['validated']+=1
    if not ok:_N52_STATS['rejected_args']+=1
    return ok,errs


def _n52_tool_perf(tool,status,latency):
    try:
        c=_n35_conn();r=c.execute('SELECT calls,verified,partial,failed,avg_latency FROM tool52_perf WHERE tool=?',(tool,)).fetchone();calls=(r[0] if r else 0)+1;ver=(r[1] if r else 0)+(1 if status=='VERIFIED' else 0);par=(r[2] if r else 0)+(1 if status in ('PARTIAL','NEEDS_INPUT') else 0);fail=(r[3] if r else 0)+(1 if status=='FAILED' else 0);old=(r[4] if r else 0.0);avg=float(latency) if calls==1 else old+(float(latency)-old)/calls
        c.execute('INSERT OR REPLACE INTO tool52_perf(tool,calls,verified,partial,failed,avg_latency,last_latency,last_status,last_ts) VALUES(?,?,?,?,?,?,?,?,?)',(tool,calls,ver,par,fail,avg,float(latency),status,_n52_time.time()));c.commit();c.close()
    except Exception:pass


def _n52_tool_perf_text():
    try:
        c=_n35_conn();rows=c.execute('SELECT tool,calls,verified,partial,failed,avg_latency,last_status FROM tool52_perf ORDER BY calls DESC,tool LIMIT 30').fetchall();c.close()
    except Exception:rows=[]
    if not rows:return 'No Tool Performance evidence yet. Use /run50 or /run52 to create measured executions.'
    L=['📈 TOOL PERFORMANCE — observed runtime evidence']
    for r in rows:
        rate=(100.0*r[2]/r[1]) if r[1] else 0;L.append('%s · %d call(s) · %.0f%% verified · fail %d · avg %.0f ms · last %s'%(r[0],r[1],rate,r[4],r[5]*1000,r[6]))
    return '\n'.join(L)


