def _n52_num(x):
    try:return float(str(x).replace(',','').replace('₹','').strip())
    except Exception:return None


def _n52_emi(principal,annual_rate,months):
    p=float(principal);r=float(annual_rate)/1200.0;n=int(months)
    if p<=0 or n<=0 or annual_rate<0:raise ValueError('principal/months must be positive and rate non-negative')
    emi=(p/n) if r==0 else p*r*(1+r)**n/((1+r)**n-1)
    total=emi*n;return {'principal':round(p,2),'annual_rate_pct':round(float(annual_rate),4),'months':n,'emi':round(emi,2),'total_payment':round(total,2),'total_interest':round(total-p,2)}


def _n52_unit_economics(revenue,variable_cost,fixed_cost,units):
    rev=float(revenue);var=float(variable_cost);fix=float(fixed_cost);u=float(units)
    if u<=0:raise ValueError('units must be positive')
    contribution=rev-var;margin=(contribution/rev*100.0) if rev else 0.0
    cpu=contribution/u;be=(fix/cpu) if cpu>0 else None
    profit=contribution-fix
    return {'revenue':round(rev,2),'variable_cost':round(var,2),'fixed_cost':round(fix,2),'units':round(u,4),'contribution':round(contribution,2),'contribution_margin_pct':round(margin,2),'profit_before_tax':round(profit,2),'contribution_per_unit':round(cpu,2),'break_even_units':None if be is None else round(be,2)}


_ALLOWED_CALC_NODES=(_n52_ast.Expression,_n52_ast.BinOp,_n52_ast.UnaryOp,_n52_ast.Constant,_n52_ast.Add,_n52_ast.Sub,_n52_ast.Mult,_n52_ast.Div,_n52_ast.FloorDiv,_n52_ast.Mod,_n52_ast.Pow,_n52_ast.USub,_n52_ast.UAdd)
def _n52_calculate(expr):
    s=str(expr or '').strip()
    if len(s)>180:raise ValueError('expression too long')
    tree=_n52_ast.parse(s,mode='eval')
    for n in _n52_ast.walk(tree):
        if not isinstance(n,_ALLOWED_CALC_NODES):raise ValueError('only numeric arithmetic is allowed')
        if isinstance(n,_n52_ast.Constant) and not isinstance(n.value,(int,float)):raise ValueError('only numeric constants are allowed')
        if isinstance(n,_n52_ast.Pow):pass
    val=eval(compile(tree,'<nemo-calc>','eval'),{'__builtins__':{}},{})
    if not isinstance(val,(int,float)) or not _n52_math.isfinite(float(val)):raise ValueError('result is not finite')
    if abs(float(val))>1e100:raise ValueError('result too large')
    return {'expression':s,'result':val}


def _n52_official_search(cid,q):
    query=str(q or '').strip()
    if not query:return {'ok':False,'text':'Missing query','evidence':''}
    qq=query+' (site:gov.in OR site:nic.in OR site:pib.gov.in OR site:rbi.org.in OR site:sebi.gov.in)'
    try:raw=web_search(qq)
    except Exception as e:return {'ok':False,'text':'Official-source search failed: '+type(e).__name__+': '+str(e)[:160],'evidence':''}
    ok=bool(raw and len(str(raw).strip())>20)
    return {'ok':ok,'text':str(raw or '')[:7000],'evidence':'search constrained toward Indian official/public-authority domains; verify source URLs in returned evidence'}


def _n52_calendar_agenda(days=3):
    n=max(1,min(14,int(days or 3)));x=gcal_upcoming(n)
    return {'days':n,'events':x or [],'count':len(x or [])}


def _n52_project_brief(cid,q=''):
    q=str(q or '').strip();out={'threads':[],'goals':[],'search':[]}
    try:
        rows=_n49_threads(cid,20) or []
        if q:
            toks=set(_n52_re.findall(r'[a-z0-9]+',q.lower()));rows=[r for r in rows if toks & set(_n52_re.findall(r'[a-z0-9]+',' '.join(str(x or '').lower() for x in r)))]
        out['threads']=[list(r) for r in rows[:5]]
    except Exception:pass
    try:out['goals']=[list(r) for r in (_n49_goals(cid,None,15) or [])[:10]]
    except Exception:pass
    try:out['search']=_n50_cross_search(cid,q or 'project goals pending',8)
    except Exception:pass
    return out


def _n52_memory_provenance(cid,q):
    hits=_n50_cross_search(cid,q,15)
    return {'query':q,'hits':hits,'sources':sorted(set(str(x.get('source')) for x in hits)),'count':len(hits)}


def _n52_processes(limit=20):
    n=max(5,min(60,int(limit or 20)))
    try:
        r=_n52_sp.run(['ps','-eo','pid,ppid,comm,%cpu,%mem,etimes','--sort=-%cpu'],capture_output=True,text=True,timeout=10)
        lines=(r.stdout or '').splitlines()[:n+1];return {'ok':r.returncode==0,'lines':lines,'count':max(0,len(lines)-1)}
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)[:180]}


def _n52_services(limit=35):
    n=max(5,min(80,int(limit or 35)))
    try:
        r=_n52_sp.run(['systemctl','list-units','--type=service','--all','--no-pager','--no-legend'],capture_output=True,text=True,timeout=15)
        lines=(r.stdout or '').splitlines()[:n];bad=[x for x in lines if ' failed ' in (' '+x.lower()+' ') or ' inactive ' in (' '+x.lower()+' ')]
        return {'ok':r.returncode==0,'services':lines,'shown':len(lines),'failed_or_inactive':bad[:15]}
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)[:180]}


def _n52_files_inventory():
    roots=['/root/nemo_projects','/root/nemo_media','/root/nemo_photos','/root/nemo_backups','/root/library','/root/nemo_code']
    out=[]
    for root in roots:
        if not _n52_os.path.exists(root):continue
        files=0;size=0;newest=0
        try:
            for base,dirs,names in _n52_os.walk(root):
                # avoid hidden credential-like subtrees/files from becoming inventory content
                dirs[:]=[d for d in dirs if not d.startswith('.')]
                for name in names:
                    p=_n52_os.path.join(base,name)
                    try:st=_n52_os.stat(p);files+=1;size+=st.st_size;newest=max(newest,st.st_mtime)
                    except Exception:pass
                    if files>=10000:break
                if files>=10000:break
            out.append({'root':root,'files':files,'size_mb':round(size/1048576.0,2),'newest':newest})
        except Exception as e:out.append({'root':root,'error':type(e).__name__})
    return out


def _n52_code_self_audit():
    try:src=open(__file__,encoding='utf-8',errors='ignore').read();tree=_n52_ast.parse(src)
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)[:180]}
    from collections import Counter
    funcs=[n.name for n in _n52_ast.walk(tree) if isinstance(n,(_n52_ast.FunctionDef,_n52_ast.AsyncFunctionDef))];cnt=Counter(funcs)
    return {'ok':True,'version':VERSION,'lines':src.count('\n')+1,'bytes':len(src.encode('utf-8')),'functions':len(funcs),'duplicate_function_names':sum(1 for v in cnt.values() if v>1),'handle_defs':cnt.get('handle',0),'ask_ai_defs':cnt.get('ask_ai',0),'main_defs':cnt.get('main',0),'sha256':_n52_hashlib.sha256(src.encode('utf-8')).hexdigest(),'top_duplicates':sorted([(k,v) for k,v in cnt.items() if v>1],key=lambda x:(-x[1],x[0]))[:12]}


