        if tool=='memory.provenance':
            x=_n52_memory_provenance(cid,a.get('query',''));status='VERIFIED';res=_n52_j(x,5000);ev='%d cross-memory hit(s) from %d source type(s)'%(x.get('count',0),len(x.get('sources') or []));rec=_n50_receipt(rid,s['idx'],cid,tool,a.get('query',''),status,ev,{});ok=True;return status,res,ev,rec
        if tool=='system.processes':
            x=_n52_processes(a.get('limit',20));status='VERIFIED' if x.get('ok') else 'FAILED';res=_n52_j(x,4200);ev='read-only ps process metadata';rec=_n50_receipt(rid,s['idx'],cid,tool,'this VPS',status,ev,{});ok=x.get('ok');
            if not ok:raise RuntimeError(x.get('error','process read failed'))
