            r=c.execute('SELECT id,ts,task,status,evidence,synthesis,duration_ms FROM agent52_run WHERE id=? AND chat_id=?',(mid,str(cid))).fetchone();seats=c.execute('SELECT role,model,status,latency,answer,error FROM agent52_seat WHERE run_id=? ORDER BY id',(mid,)).fetchall();c.close()
            if not r:return 'Mesh run not found.'
