# ------------------------------- COMMAND DISPATCH ------------------------------
_N52_HANDLE_PREV=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');chat=msg.get('chat') or {};txt=(msg.get('text') or '').strip();low=txt.lower()
        gated=('/nemo52','/kernel52','/tools52','/toolperf52','/nero52','/mesh52','/meshes52','/retry52','/run52','/shadow52','/emi52','/economics52','/official52','/calc52')
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id') and low.startswith(gated):send_text(cid,'That command is owner-only.');return
        if cid==OWNER.get('id') and chat.get('type','private')=='private':
            if low in ('/nemo52','/kernelstatus52'):send_text(cid,_n52_status(cid));return
            if low in ('/kernel52','/requests52'):send_text(cid,_n52_kernel_text(cid));return
            if low in ('/tools52','/hands52'):_n50_register_builtin_tools();send_text(cid,_n50_tool_text());return
            if low in ('/toolperf52','/performance52'):send_text(cid,_n52_tool_perf_text());return
            if low in ('/nero52','/nero2'):send_text(cid,_n52_nero_text(cid));return
            if low.startswith('/mesh52'):
                q=txt[len('/mesh52'):].strip()
                if not q:send_text(cid,'Usage: /mesh52 <complex question or plan>');return
                send_text(cid,'🧠 Agent Mesh: evidence → researcher → analyst → critic → planner → synthesis...')
                def go():
                    try:
                        x=_n52_agent_mesh(cid,q);send_text(cid,(x.get('text') or 'No synthesis.')[:3600]+'\n\nMesh '+x.get('id','')+' · seats '+str(x.get('seats',0))+' · '+str(x.get('duration_ms',0))+' ms')
                    except Exception as e:send_text(cid,'Agent Mesh failed safely: '+type(e).__name__+': '+str(e)[:300])
                _n52_threading.Thread(target=go,daemon=True,name='nemo-mesh52').start();return
            if low.startswith('/meshes52'):
                mid=txt[len('/meshes52'):].strip().upper();send_text(cid,_n52_mesh_text(cid,mid));return
            if low.startswith('/retry52'):
                r=txt[len('/retry52'):].strip();send_text(cid,_n52_retry(cid,r) if r else 'Usage: /retry52 <failed run id>');return
            if low.startswith('/run52'):
                q=txt[len('/run52'):].strip()
                if not q:send_text(cid,'Usage: /run52 <task>');return
                send_text(cid,'⚙️ Kernel execution started...')
                def runit():
                    try:rid,res=_n50_run(cid,q,False);send_text(cid,res)
                    except Exception as e:send_text(cid,'Kernel execution failed safely: '+type(e).__name__+': '+str(e)[:500])
                _n52_threading.Thread(target=runit,daemon=True,name='nemo-run52').start();return
            if low.startswith('/shadow52'):
                q=txt[len('/shadow52'):].strip()
                if not q:send_text(cid,'Usage: /shadow52 <task>');return
                try:rid,res=_n50_run(cid,q,True);send_text(cid,res)
                except Exception as e:send_text(cid,'Shadow planning failed: '+type(e).__name__+': '+str(e)[:400]);return
                return
            if low.startswith('/emi52'):
                parts=txt[len('/emi52'):].strip().replace(',','').split()
                if len(parts)!=3:send_text(cid,'Usage: /emi52 <principal> <annual-rate-%> <months>');return
                try:send_text(cid,'🧮 EMI\n'+_n52_j(_n52_emi(float(parts[0]),float(parts[1]),int(parts[2])),2500))
                except Exception as e:send_text(cid,'EMI input error: '+str(e)[:220]);return
                return
            if low.startswith('/economics52'):
                parts=txt[len('/economics52'):].strip().replace(',','').split()
                if len(parts)!=4:send_text(cid,'Usage: /economics52 <revenue> <variable-cost> <fixed-cost> <units>');return
                try:send_text(cid,'📊 UNIT ECONOMICS\n'+_n52_j(_n52_unit_economics(*map(float,parts)),2600))
                except Exception as e:send_text(cid,'Economics input error: '+str(e)[:220]);return
                return
            if low.startswith('/official52'):
                q=txt[len('/official52'):].strip()
                if not q:send_text(cid,'Usage: /official52 <government/policy/scheme question>');return
                send_text(cid,'🏛 Searching official/public-authority sources first...')
                def off():
                    x=_n52_official_search(cid,q);send_text(cid,(x.get('text') or 'No result.')[:3700]+'\n\nEvidence policy: '+x.get('evidence',''))
                _n52_threading.Thread(target=off,daemon=True,name='nemo-official52').start();return
            if low.startswith('/calc52'):
                q=txt[len('/calc52'):].strip()
                try:send_text(cid,'🧮 '+_n52_j(_n52_calculate(q),1400))
                except Exception as e:send_text(cid,'Calculator input error: '+str(e)[:220]);return
                return
    except Exception:_N52_STATS['errors']+=1
    return _N52_HANDLE_PREV(msg)


