    if not isinstance(r,dict):return {'id':'RG52','version':VERSION,'passed':sum(1 for x in extra if x['ok']),'failed':sum(1 for x in extra if not x['ok']),'verdict':'PASS' if all(x['ok'] for x in extra) else 'FAIL','tests':extra}
    r['tests'].extend(extra);r['passed']=sum(1 for x in r['tests'] if x.get('ok'));r['failed']=len(r['tests'])-r['passed'];r['verdict']='PASS' if not r['failed'] else 'FAIL';r['version']=VERSION;return r


