def _n53_contract_text(q=''):
    _n53_seed_contracts();q=str(q or '').strip().lower()
    try:
        c=_n35_conn();rows=c.execute('SELECT tool,side_effect,idempotent,reversible,retry_class,postcondition,required_connection,max_seconds FROM tool53_contract ORDER BY tool').fetchall();c.close()
    except Exception:rows=[]
