# Planner adds only v53 tools; all older routes continue to the proven v52 planner.
_N53_PLAN_PREV=_n50_plan
def _n50_plan(cid,text,shadow=False,persist=True):
    oldrid,route,steps=_N53_PLAN_PREV(cid,text,shadow=shadow,persist=False)
    chosen=set(route.get('tools') or []);new={'understanding.semantic','memory.timeline','research.evidence_graph','action.contract_audit','kernel.architecture'}
    if not (chosen & new):return _N53_PLAN_PREV(cid,text,shadow=shadow,persist=persist)
    steps=[s for s in steps if s.get('tool')!='brain.chat']
    def add(name,tool,args):
        if tool not in [x.get('tool') for x in steps]:steps.append({'idx':len(steps)+1,'name':name,'tool':tool,'args':args,'depends':[]})
    if 'understanding.semantic' in chosen:add('Classify meaning','understanding.semantic',{'text':text})
    if 'memory.timeline' in chosen:add('Search episodic timeline','memory.timeline',{'query':text})
    if 'research.evidence_graph' in chosen:add('Build evidence graph','research.evidence_graph',{'query':text})
    if 'action.contract_audit' in chosen:add('Audit tool contracts','action.contract_audit',{'query':text})
    if 'kernel.architecture' in chosen:add('Inspect kernel architecture','kernel.architecture',{})
    for i,s in enumerate(steps,1):s['idx']=i
    rid='R53-'+_n53_uuid.uuid4().hex[:10].upper()
    if persist:
        now=_n53_time.time();c=_n35_conn()
        try:
            c.execute('INSERT INTO exec50_run(id,chat_id,created,updated,task,status,shadow,route_json) VALUES(?,?,?,?,?,?,?,?)',(rid,str(cid),now,now,_n53_safe(text,4000),'PLANNED',1 if shadow else 0,_n53_j(route)))
            for s in steps:c.execute('INSERT INTO exec50_step(run_id,idx,name,tool,args_json,depends_json,status) VALUES(?,?,?,?,?,?,?)',(rid,s['idx'],s['name'],s['tool'],_n53_j(s.get('args') or {}),_n53_j(s.get('depends') or []),'PLANNED'))
            c.commit()
        finally:c.close()
    return rid,route,steps


