    if tool=='understanding.semantic':
        x=_n53_understand(cid,a.get('text',''));status='VERIFIED';res=_n53_j(x,4000);ev='local deterministic/semantic context frame';rec=_n50_receipt(rid,s['idx'],cid,tool,'meaning frame',status,ev,{})
    elif tool=='memory.timeline':
        x=_n53_memory_search(cid,a.get('query',''),18);status='VERIFIED';res=_n53_j(x,5000);ev='%d episodic timeline hit(s)'%len(x);rec=_n50_receipt(rid,s['idx'],cid,tool,a.get('query',''),status,ev,{})
    elif tool=='research.evidence_graph':
        x=_n53_evidence_graph(cid,a.get('query',''));status='VERIFIED' if x.get('ok') else 'PARTIAL';res=x.get('text','');ev=x.get('evidence','');rec=_n50_receipt(rid,s['idx'],cid,tool,a.get('query',''),status,ev,{'run':x.get('id'),'sources':x.get('sources'),'coverage':x.get('coverage')})
    elif tool=='action.contract_audit':
        status='VERIFIED';res=_n53_contract_text(a.get('query',''));ev='read-only contract registry inspection';rec=_n50_receipt(rid,s['idx'],cid,tool,a.get('query',''),status,ev,{})
    elif tool=='kernel.architecture':
        status='VERIFIED';res=_n53_j(_n53_kernel_architecture(),5000);ev='AST/source compatibility metrics';rec=_n50_receipt(rid,s['idx'],cid,tool,'running Nemo',status,ev,{})
    else:
        status,res,ev,rec=_N53_EXEC_PREV(cid,rid,s)
    ok,detail=_n53_postcheck(tool,status,res,ev,a);final=status
