_N53_HANDLE_PREV=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');chat=msg.get('chat') or {};txt=(msg.get('text') or '').strip();low=txt.lower()
        is_owner=bool(cid==OWNER.get('id') and chat.get('type','private')=='private')
        gated=('/nemo53','/kernel53','/understand53','/teachroute53','/timeline53','/remember53','/evidence53','/contracts53','/run53','/shadow53')
        if chat.get('type','private')=='private' and OWNER.get('id') and cid!=OWNER.get('id') and low.startswith(gated):send_text(cid,'That command is owner-only.');return
        if is_owner:
            # Observe ordinary owner text once; do not store secret-setting commands.
            if txt and not low.startswith('/'):
                try:_n53_ingress(cid,txt)
                except Exception:_N53_STATS['errors']+=1
            if low in ('/nemo53','/fivecore53'):send_text(cid,_n53_status(cid));return
            if low in ('/kernel53','/architecture53'):send_text(cid,_n53_kernel_text(cid));return
            if low.startswith('/understand53'):
                q=txt[len('/understand53'):].strip();send_text(cid,_n53_understand_text(cid,q) if q else 'Usage: /understand53 <text>');return
            if low.startswith('/teachroute53'):
                q=txt[len('/teachroute53'):].strip()
                if '|' not in q:send_text(cid,'Usage: /teachroute53 <intent> | <example>');return
                a,b=q.split('|',1);send_text(cid,_n53_teach_route(cid,a,b));return
            if low.startswith('/timeline53'):
                q=txt[len('/timeline53'):].strip();send_text(cid,_n53_memory_text(cid,q));return
            if low.startswith('/remember53'):
                q=txt[len('/remember53'):].strip()
                if not q:send_text(cid,'Usage: /remember53 <important fact, decision or event>');return
                mid=_n53_memory_add(cid,q,'explicit_memory','owner-explicit',True,'explicit /remember53');send_text(cid,'Stored in Memory Fabric timeline as '+str(mid)+'. Existing Unified Mind remains untouched.');return
            if low.startswith('/evidence53'):
                q=txt[len('/evidence53'):].strip()
                if not q:send_text(cid,'Usage: /evidence53 <research question>');return
                send_text(cid,'🕸 Evidence Graph: gathering and normalizing sources...')
                def eg():
                    try:send_text(cid,_n53_evidence_text(cid,q))
                    except Exception as e:send_text(cid,'Evidence Graph failed safely: '+type(e).__name__+': '+str(e)[:300])
                _n53_threading.Thread(target=eg,daemon=True,name='nemo-evidence53').start();return
            if low.startswith('/contracts53'):
                q=txt[len('/contracts53'):].strip();send_text(cid,_n53_contract_text(q));return
            if low.startswith('/run53'):
                q=txt[len('/run53'):].strip()
                if not q:send_text(cid,'Usage: /run53 <task>');return
                iid,_=_n53_ingress(cid,q,'EXECUTION_REQUEST','/run53')
                send_text(cid,'⚙️ Five-Core Kernel execution started...')
                def rr():
                    try:
                        rid,res=_n50_run(cid,q,False)
                        try:c=_n35_conn();c.execute("UPDATE kernel53_ingress SET exec_run=?,status='DELEGATED_COMPLETE' WHERE id=?",(str(rid),iid));c.commit();c.close()
                        except Exception:pass
                        send_text(cid,res)
                    except Exception as e:send_text(cid,'Execution failed safely: '+type(e).__name__+': '+str(e)[:400])
                _n53_threading.Thread(target=rr,daemon=True,name='nemo-run53').start();return
            if low.startswith('/shadow53'):
                q=txt[len('/shadow53'):].strip()
                if not q:send_text(cid,'Usage: /shadow53 <task>');return
                try:rid,res=_n50_run(cid,q,True);send_text(cid,res)
                except Exception as e:send_text(cid,'Shadow failed safely: '+type(e).__name__+': '+str(e)[:400]);return
                return
    except Exception:_N53_STATS['errors']+=1
    return _N53_HANDLE_PREV(msg)


