def _n55_breadth(index='NIFTY'):
    rows=_n55_nse_index_rows(index);source='NSE index API';data=[]
    if rows:
        for x in rows:
            p=_n55_num(x.get('pChange'),0);vol=_n55_num(x.get('totalTradedVolume'),0);data.append({'symbol':x.get('symbol'),'change_pct':p,'volume':vol,'last':_n55_num(x.get('lastPrice'))})
    else:
        source='fallback constituent list + quote sources';u=_N55_BANK_FALLBACK if 'BANK' in _n55_norm_symbol(index) else _N55_NIFTY_FALLBACK
        def q(s):
            try:
                z=fyers_quote_live(s) if (fyers_ready() or fyers_login()) else get_quote(s)
                if not z:return None
                ch=_n55_num(z.get('chp'));price=_n55_num(z.get('price'));prev=_n55_num(z.get('prev'))
                if ch is None and price is not None and prev:ch=(price/prev-1)*100
                return {'symbol':s,'change_pct':ch or 0,'volume':_n55_num(z.get('vol'),0),'last':price}
            except Exception:return None
        with _N55Pool(max_workers=8) as ex:
            for z in ex.map(q,u):
                if z:data.append(z)
    adv=sum(1 for x in data if x['change_pct']>0.05);dec=sum(1 for x in data if x['change_pct']<-0.05);unch=max(0,len(data)-adv-dec);upv=sum(x['volume'] or 0 for x in data if x['change_pct']>0);dnv=sum(x['volume'] or 0 for x in data if x['change_pct']<0)
    ratio=(adv/dec) if dec else (float(adv) if adv else 0);vr=(upv/dnv) if dnv else None;top=sorted(data,key=lambda x:x['change_pct'],reverse=True)
    _N55_STATS['breadth']+=1
    return {'index':_n55_norm_symbol(index),'source':source,'constituents':len(data),'advancers':adv,'decliners':dec,'unchanged':unch,'advance_decline_ratio':round(ratio,2),'up_down_volume_ratio':round(vr,2) if vr is not None else None,'breadth_pct':round(100*(adv-dec)/max(1,len(data)),1),'leaders':top[:5],'laggards':list(reversed(top[-5:])) if top else [],'note':'fallback universe may differ from current official composition when NSE discovery is unavailable'}


