def _n55_expiry_value(d):
    ed=(d or {}).get('expiryData') or (d or {}).get('expiry_data') or []
    vals=[]
    for x in ed:
        if isinstance(x,dict):
            raw=x.get('date') or x.get('expiry') or x.get('expiryDate') or x.get('timestamp')
            ts=x.get('timestamp') or x.get('expiry') if isinstance(x.get('expiry'),(int,float)) else x.get('timestamp')
            vals.append({'label':str(raw or ''),'timestamp':int(ts) if isinstance(ts,(int,float)) else None})
        elif x:vals.append({'label':str(x),'timestamp':None})
    return vals


def _n55_parse_expiry_ts(label,ts=None):
    if ts:
        try:return float(ts)
        except Exception:pass
    s=str(label or '')
    for fmt in ('%d-%m-%Y','%Y-%m-%d','%d %b %Y','%d-%b-%Y','%d/%m/%Y'):
        try:return _n55_dt.datetime.strptime(s,fmt).replace(hour=15,minute=30,tzinfo=_N55_IST).timestamp()
        except Exception:pass
    return None


def _n55_prev_chain(symbol):
    try:
        c=_n35_conn();r=c.execute('SELECT ts,payload FROM market55_option_snapshot WHERE symbol=? ORDER BY ts DESC LIMIT 1',(str(_n55_norm_symbol(symbol)),)).fetchone();c.close()
        if r:return float(r[0]),_n55_json.loads(r[1])
    except Exception:pass
    return None,None


def _n55_option_chain_struct(symbol='NIFTY',strikes=12,expiry_ts=None,persist=True):
    _n55_ensure();sym=_n55_norm_symbol(symbol)
