# =============================================================================
# NEMO 56.0 — NATURAL ACTION + SYSTEMATIC RESEARCH + ZERO TOOL-LEAK RECOVERY
# FIVE UPGRADES IN ONE
#
# UPGRADE 1 — NATURAL ACTION ROUTER 6.0
#   Plain owner language such as "go get me information about upcoming X",
#   "find details about X", "what new projects are coming in X" and Hinglish/
#   typo variants route directly to a real read-only research capability instead
#   of asking a chat model to invent a pseudo tool call.
#
# UPGRADE 2 — PUBLIC RESEARCH FULFILLMENT 2.0
#   Multi-query public-web retrieval -> bounded safe fetch -> authority-aware
#   evidence dossier -> final synthesis. Reuses v54 InternetOS URL/SSRF guards.
#
# UPGRADE 3 — TOOL-LEAK ZERO 3.0
#   Catches bracket, XML, JSON and prefixed pseudo tool calls (including the exact
#   "⚡ [fetch(url='...')]" production failure). Corrupt cached answers are
#   quarantined/ignored; model-generated tool text is never treated as authority.
#   For an already-grounded public research request, Nemo recovers by re-running
#   the ORIGINAL owner request through the real read-only research path.
#
# UPGRADE 4 — SYSTEMATIC RESPONSE COMPOSER 2.0
#   Research answers are delivered in a Telegram-friendly structure: direct
#   answer, key findings, details/status/timeline, confirmed-vs-unclear, impact,
#   and real source list. Evidence/page text is treated as untrusted data.
#
# UPGRADE 5 — ACTION ACCOUNTABILITY 2.0
#   Persistent natural-action ledger records original intent, normalized request,
#   chosen route, lifecycle status, source count and completion evidence. /why56
#   and /last56 expose operational receipts, never hidden chain-of-thought.
#
# PRESERVATION / AUTHORITY INVARIANTS
#   * no credential/config definition from v55 is changed or removed;
#   * no existing DB/table/file is dropped/truncated/renamed;
#   * public research is READ-ONLY; no new email/browser/trading/shell authority;
#   * external writes continue through existing authenticated/approval rails;
#   * leaked model tool syntax is never executed merely because a model printed it;
#   * old routes remain available as compatibility fallback.
# =============================================================================
VERSION='56.0'
import re as _n56_re, time as _n56_time, json as _n56_json, uuid as _n56_uuid
import hashlib as _n56_hashlib, threading as _n56_threading

_N56_LOCK=_n56_threading.RLock()
_N56_TLS=_n56_threading.local()
_N56_ACTIVE={}
_N56_RECOVERING=set()
_N56_STATS={'natural_routes':0,'research':0,'sources':0,'tool_leaks':0,'cache_quarantine':0,'recoveries':0,'systematic':0,'errors':0}

# Known provider/tool syntaxes that must never appear as user-facing prose.
# Unlike v48, these patterns are intentionally NOT anchored to the beginning of
# the message, so prefixes such as "⚡ " cannot bypass the firewall.
_N56_TOOL_BRACKET_RE=_n56_re.compile(
    r"(?is)\[\s*(?:fetch|web_search|search_web|browser|open_url|call_tool|tool|internet_fetch|internet_search|"
    r"web\.run|web_run)\s*\([^\]\n]{0,3200}\)\s*\]")
_N56_TOOL_BARE_RE=_n56_re.compile(
    r"(?im)^\s*(?:⚡|🔎|🧠|➡️|•|-)?\s*(?:fetch|web_search|search_web|open_url|call_tool|internet_fetch|internet_search)\s*\(\s*(?:url|query)\s*=.{0,2600}\)\s*$")
_N56_TOOL_XML_RE=_n56_re.compile(
    r"(?is)<tool_call\b[^>]*>.*?</tool_call>|<function_call\b[^>]*>.*?</function_call>|<invoke\b[^>]*>.*?</invoke>|<tool\b[^>]*>.*?</tool>|<function\b[^>]*>.*?</function>")
# JSON-ish tool records; narrow to known tool keys + known internal names.
_N56_TOOL_JSON_RE=_n56_re.compile(
    r"(?is)\\{\\s*[\"']?(?:tool|function|name)[\"']?\\s*:\s*[\"'](?:fetch|web_search|search_web|browser|open_url|internet\\.fetch|internet\\.search)[\"'][^{}]{0,2200}\\}")

_N56_FRESH_RE=_n56_re.compile(r'(?i)\b(?:upcoming|coming|planned|proposed|announced|future|latest|current|recent|today|now|new|development|projects?|status|202[5-9])\b')
_N56_RETRIEVE_RE=_n56_re.compile(r'(?i)^\s*(?:(?:hey\s+)?nemo[,:]?\s*)?(?:please\s+|pls\s+|can you\s+|could you\s+)?(?:go\s+)?(?:get|find|find out|search|research|look up|lookup|check|tell me|show me|give me|bring me|dig up)\b')
_N56_INFO_RE=_n56_re.compile(r'(?i)\b(?:information|info|details?|updates?|news|developments?|projects?|plans?|status|everything|complete picture|what is happening|what\'s happening|about)\b')
_N56_QUESTION_RE=_n56_re.compile(r'(?i)^\s*(?:what|which|where|when|who|how|are there|is there|tell me|show me)\b')
_N56_PRIVATE_RE=_n56_re.compile(r'(?i)\b(?:my\s+(?:email|emails|gmail|inbox|calendar|drive|contacts?|files?|documents?|photos?|messages?|account)|unread\s+(?:mail|email|emails)|my\s+meetings?)\b')
_N56_SIDE_EFFECT_RE=_n56_re.compile(r'(?i)\b(?:email|mail|send|post|publish|upload|submit|buy|purchase|pay|transfer|delete|remove|change password|log\s*in|sign\s*in|place order|trade|sell|book|reserve|call\s+him|call\s+her)\b')
_N56_MARKET_RE=_n56_re.compile(r'(?i)\b(?:nifty|banknifty|sensex|finnifty|midcpnifty|option chain|options?|futures?|equity|stock market|share market|intraday|fyers|zerodha|strike|pcr|gex|gamma|vix)\b')
_N56_FILE_MEDIA_RE=_n56_re.compile(r'(?i)\b(?:download|mp3|mp4|youtube|reel|video|audio|file path|server file)\b')
_N56_DEEP_RE=_n56_re.compile(r'(?i)\b(?:deep|deeply|detailed|complete|comprehensive|full|everything|all aspects|end to end|from start to end)\b')

_N56_FIXES={
 'infracture':'infrastructure','infrastucture':'infrastructure','infrastruture':'infrastructure','infrastrcture':'infrastructure',
 'devlepment':'development','developement':'development','develpment':'development','upcomming':'upcoming','upcomingg':'upcoming',
 'infomation':'information','informtion':'information','detials':'details','udipur':'udaipur','udaipure':'udaipur'
}


def _n56_init():
    c=_n35_conn();c.executescript("""
    CREATE TABLE IF NOT EXISTS action56_event(
      id TEXT PRIMARY KEY, chat_id TEXT, ts REAL, updated REAL, original_text TEXT,
      normalized_text TEXT, intent TEXT, route TEXT, status TEXT, source_count INTEGER DEFAULT 0,
      result_hint TEXT DEFAULT '', detail TEXT DEFAULT '', duration_ms INTEGER DEFAULT 0);
    CREATE INDEX IF NOT EXISTS idx_a56_chat ON action56_event(chat_id,ts DESC);
    CREATE TABLE IF NOT EXISTS output56_quarantine(
      id TEXT PRIMARY KEY, chat_id TEXT, ts REAL, kind TEXT, sample_hash TEXT,
      sample TEXT DEFAULT '', recovered INTEGER DEFAULT 0, recovery_query TEXT DEFAULT '');
    CREATE INDEX IF NOT EXISTS idx_q56_chat ON output56_quarantine(chat_id,ts DESC);
    """);c.commit();c.close()
    _n56_register_tools()


