def _n57_init():
    c=_n35_conn();c.executescript("""
    CREATE TABLE IF NOT EXISTS hands57_manifest(
      tool TEXT PRIMARY KEY, category TEXT, reach TEXT, side_effect TEXT, risk TEXT,
      permission TEXT, auto_safe INTEGER DEFAULT 0, verifier TEXT DEFAULT '', description TEXT DEFAULT '', updated REAL);
    CREATE TABLE IF NOT EXISTS hands57_mission(
      id TEXT PRIMARY KEY, chat_id TEXT, ts REAL, updated REAL, text TEXT, kind TEXT,
      target TEXT, status TEXT, plan_json TEXT DEFAULT '{}', result TEXT DEFAULT '', evidence TEXT DEFAULT '', duration_ms INTEGER DEFAULT 0);
    CREATE INDEX IF NOT EXISTS idx_h57_mission_chat ON hands57_mission(chat_id,ts DESC);
    CREATE TABLE IF NOT EXISTS hands57_device_perm(
      device_id TEXT, capability TEXT, enabled INTEGER DEFAULT 0, updated REAL, PRIMARY KEY(device_id,capability));
    CREATE TABLE IF NOT EXISTS hands57_idempotency(
      idem_key TEXT PRIMARY KEY, ts REAL, mission_id TEXT, status TEXT, result TEXT DEFAULT '');
    """);c.commit();c.close();_n57_seed_manifest();_n57_register_tools()


def _n57_reach_class(name,cat):
    n=str(name or '').lower();c=str(cat or '').lower()
    if n.startswith('market.') or 'market' in c:return 'MARKET'
    if n.startswith('google.') or n.startswith('email.') or 'communication' in c:return 'CONNECTED_ACCOUNT'
    if n.startswith('device.') or 'device' in c:return 'ENROLLED_DEVICE'
    if n.startswith(('browser.','internet.','web.')) or 'research' in c:return 'INTERNET'
    if n.startswith(('system.','server.','logs.','network.','database.','backup.','security.')) or 'systems' in c:return 'VPS'
    if n.startswith(('files.','artifact.','memory.')) or 'knowledge' in c:return 'DATA'
    return 'LOCAL'


def _n57_seed_manifest():
    try:_n50_register_builtin_tools()
    except Exception:pass
    try:rows=_n50_tools()
    except Exception:rows=[]
    c=_n35_conn();now=_n57_time.time()
    try:
        for r in rows:
            name,cat,desc,risk,perm=r[0],r[1],r[2],r[3],r[4];side='none';ver='result'
            try:
                cr=_n53_contract(name)
                if cr:side=str(cr[1] or 'none');ver=str(cr[5] or 'result')
            except Exception:pass
            auto=int(str(perm) in ('AUTO_SAFE','OWNER_READ') and side in ('','none') and str(risk) in ('','LOW'))
            c.execute('INSERT OR REPLACE INTO hands57_manifest(tool,category,reach,side_effect,risk,permission,auto_safe,verifier,description,updated) VALUES(?,?,?,?,?,?,?,?,?,?)',
                      (name,cat,_n57_reach_class(name,cat),side,risk,perm,auto,ver,str(desc or '')[:700],now))
        c.commit()
    finally:c.close()


def _n57_reach_status():
    _n57_seed_manifest();out={}
    try:
        c=_n35_conn();rows=c.execute('SELECT reach,COUNT(*),SUM(auto_safe) FROM hands57_manifest GROUP BY reach ORDER BY reach').fetchall();c.close()
        for r in rows:out[str(r[0])]={'tools':int(r[1]),'auto_safe':int(r[2] or 0)}
    except Exception:pass
    out['INTERNET_STATE']={'search':callable(globals().get('web_search')),'browser':callable(globals().get('browser_agent')),'fetch':callable(globals().get('fetch_site'))}
    try:out['ACCOUNT_STATE']={'google':bool(google_ready()),'email':bool(BOT_EMAIL or google_ready())}
    except Exception:out['ACCOUNT_STATE']={'google':False,'email':False}
    try:
        ds=[d for d in _device_load().get('devices',{}).values() if not d.get('revoked')]
        out['DEVICE_STATE']={'enrolled':len(ds),'online':sum(1 for d in ds if _device_online(d)),'agent57':sum(1 for d in ds if str(d.get('agent_version57') or '')=='57.0')}
    except Exception:out['DEVICE_STATE']={'enrolled':0,'online':0,'agent57':0}
    return out


def _n57_reach_text():
    x=_n57_reach_status();L=['🦾 NEMO 57 — HANDS REACH MAP','━━━━━━━━━━━━━━━━━━━━']
    for k in ('INTERNET','CONNECTED_ACCOUNT','ENROLLED_DEVICE','VPS','DATA','MARKET','LOCAL'):
        if k in x:L.append('%s · %d tools · %d auto-safe'%(k,x[k]['tools'],x[k]['auto_safe']))
    i=x['INTERNET_STATE'];a=x['ACCOUNT_STATE'];d=x['DEVICE_STATE']
    L+=['','LIVE REACH',
        'Internet: search %s · browser %s · fetch %s'%('ON' if i['search'] else 'OFF','ON' if i['browser'] else 'OFF','ON' if i['fetch'] else 'OFF'),
        'Google: %s · email path: %s'%('CONNECTED' if a['google'] else 'OFF','READY' if a['email'] else 'OFF'),
        'Devices: %d enrolled · %d online · %d on Device Agent 4.0'%(d['enrolled'],d['online'],d['agent57']),
        '', 'Reach is limited to public Internet, this VPS, connected accounts and devices you explicitly enroll. Generic arbitrary remote access is not added.']
    return '\n'.join(L)[:3900]


def _n57_emails(t):
    try:return list(dict.fromkeys(_N52_EMAIL_RE.findall(str(t or ''))))
    except Exception:return list(dict.fromkeys(_n57_re.findall(r'(?i)\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b',str(t or ''))))


def _n57_urls(t):
    try:return list(dict.fromkeys(_n50_explicit_urls(str(t or ''))))
    except Exception:return list(dict.fromkeys(_n57_re.findall(r'https?://[^\s<>\]\)]+',str(t or ''))))


def _n57_public_url(url):
    try:
        p=_n57_urlparse(str(url or '').strip())
        if p.scheme not in ('http','https') or not p.hostname:return False,'only explicit http/https URLs are allowed'
        h=p.hostname.strip('[]').lower()
        if h in ('localhost','localhost.localdomain') or h.endswith('.local'):return False,'local/private hostname is blocked by this generic hand'
        try:
            ip=_n57_ipaddress.ip_address(h)
            if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_reserved:return False,'private/reserved IP is blocked by this generic hand'
        except ValueError:pass
        return True,''
    except Exception:return False,'invalid URL'


def _n57_device_candidates(text=''):
    try:items=list(_device_load().get('devices',{}).items())
    except Exception:return []
    t=str(text or '').lower();out=[]
    for did,d in items:
        if d.get('revoked'):continue
        name=str(d.get('name') or '').lower();plat=str(d.get('platform') or '').lower();score=0
        if did.lower() in t:score+=100
        if name and name in t:score+=90
        if any(x in t for x in ('laptop','computer','pc','desktop','windows')) and 'windows' in plat:score+=30
        if any(x in t for x in ('phone','mobile','android')) and 'android' in plat:score+=30
        if 'iphone' in t and ('ios' in plat or 'iphone' in plat):score+=30
        if _device_online(d):score+=4
        out.append((score,did,d))
    return sorted(out,key=lambda x:(-x[0],str(x[2].get('name',''))))


def _n57_pick_device(text=''):
    c=_n57_device_candidates(text)
    if not c:return None,None,'no enrolled device matches'
    if c[0][0]>=30:return c[0][1],c[0][2],''
    online=[x for x in c if _device_online(x[2])]
    if len(online)==1:return online[0][1],online[0][2],''
    if len(c)==1:return c[0][1],c[0][2],''
    return None,None,'device is ambiguous; say its enrolled name'


def _n57_resolve(text):
    t=str(text or '');did,d,derr=_n57_pick_device(t) if _N57_DEVICE_CUE.search(t) else (None,None,'')
    paths=[m.group(1) for m in _n57_re.finditer(r'["\']((?:[A-Za-z]:\\|/)[^"\']{1,260})["\']',t)]
    sm=_n57_re.search(r'(?i)\bservice\s+([A-Za-z0-9_.@-]{1,80})',t)
    try:sym=_n51_market_symbol(t)
    except Exception:sym=''
    _N57_STATS['resolutions']+=1
    return {'emails':_n57_emails(t),'urls':_n57_urls(t),'paths':paths[:8],'service':sm.group(1) if sm else '',
            'market_symbol':sym,'device_id':did or '','device_name':str((d or {}).get('name') or ''),'device_online':bool(d and _device_online(d)),'ambiguity':derr}


def _n57_perm_default(cap):return cap=='observe'


def _n57_perm_get(did,cap):
    try:
        c=_n35_conn();r=c.execute('SELECT enabled FROM hands57_device_perm WHERE device_id=? AND capability=?',(str(did),str(cap))).fetchone();c.close()
        return bool(r[0]) if r else _n57_perm_default(cap)
    except Exception:return _n57_perm_default(cap)


def _n57_perm_set(did,cap,on):
    if cap not in ('observe','control','clipboard','voice'):return False
    try:
        c=_n35_conn();c.execute('INSERT OR REPLACE INTO hands57_device_perm(device_id,capability,enabled,updated) VALUES(?,?,?,?)',(str(did),cap,1 if on else 0,_n57_time.time()));c.commit();c.close();return True
    except Exception:return False


def _n57_perm_for(kind):
    if kind in _N57_CONTROL:return 'control'
    if kind in _N57_CLIP:return 'clipboard'
    if kind in _N57_VOICE:return 'voice'
    return 'observe'


def _n57_perm_text(device_q):
    did,d,err=_n57_pick_device(device_q)
    if not did:return 'Device permission lookup: '+err
    vals=['ON' if _n57_perm_get(did,x) else 'OFF' for x in ('observe','control','clipboard','voice')]
    return ('🔐 DEVICE HAND PERMISSIONS — %s\nobserve=%s · control=%s · clipboard=%s · voice=%s\nAgent=%s · Online=%s\n\nObserve defaults ON for an enrolled device. Control, clipboard and voice default OFF until you enable them.'%
            (d.get('name'),vals[0],vals[1],vals[2],vals[3],str(d.get('agent_version57') or 'legacy'),'yes' if _device_online(d) else 'no'))


def _n57_parse_device(text):
    t=' '.join(str(text or '').split());low=t.lower();r=_n57_resolve(t)
    if not (_N57_DEVICE_CUE.search(t) and _N57_ACTION_CUE.search(t)):return None
    act='';val='';urls=r.get('urls') or []
    if _n57_re.search(r'(?i)\b(?:screenshot|screen\s*shot|capture (?:my )?screen|take (?:a )?screen)',t):act='screenshot'
    elif _n57_re.search(r'(?i)\b(?:active|current|foreground)\s+window\b',t):act='active_window'
    elif _n57_re.search(r'(?i)\b(?:show|list|get)\s+(?:my\s+)?(?:open\s+)?windows\b',t):act='window_list'
    elif urls and _n57_re.search(r'(?i)\b(?:open|launch|go to|visit)\b',t):act='open_url';val=urls[0]
    elif _n57_re.search(r'(?i)\b(?:read|get|show)\s+(?:my\s+)?clipboard\b',t):act='clipboard_read'
    elif _n57_re.search(r'(?i)\b(?:copy|put|set)\b.*\bclipboard\b',t):
        act='clipboard_write';m=_n57_re.search(r'(?i)\b(?:copy|put|set)\s+["\']?(.+?)["\']?\s+(?:to|into|on)\s+(?:my\s+)?clipboard\b',t);val=(m.group(1).strip() if m else '')[:1500]
    elif _n57_re.search(r'(?i)\b(?:volume|mute|unmute)\b',t):
        act='volume'
        if 'unmute' in low:val='unmute'
        elif 'mute' in low:val='mute'
        elif _n57_re.search(r'(?i)\b(?:down|lower|decrease)\b',t):val='down'
        elif _n57_re.search(r'(?i)\b(?:up|raise|increase)\b',t):val='up'
        else:
            m=_n57_re.search(r'(?i)\b(?:volume|to)\s*(\d{1,3})\b',t);val='set:'+str(max(0,min(100,int(m.group(1))))) if m else ''
    elif _n57_re.search(r'(?i)\b(?:speak|say)\b',t):
        act='voice_speak';m=_n57_re.search(r'(?i)\b(?:speak|say)\s+["\']?(.+?)["\']?(?:\s+on\s+(?:my\s+)?(?:laptop|pc|phone|device).*)?$',t);val=(m.group(1).strip() if m else '')[:1200]
    elif _n57_re.search(r'(?i)\b(?:battery|device status|system status)\b',t):act='battery' if 'battery' in low else 'sysinfo'
    elif _n57_re.search(r'(?i)\b(?:open|launch|start)\b',t):
        act='open_app';m=_n57_re.search(r'(?i)\b(?:open|launch|start)\s+(.+?)(?:\s+on\s+(?:my\s+)?(?:laptop|computer|pc|windows|desktop|phone|mobile|android|iphone|device)\b|$)',t);val=(m.group(1).strip(' "\'').lower() if m else '')[:80]
    if not act:return None
    if act in ('open_url','open_app','clipboard_write','volume','voice_speak') and not val:return {'ok':False,'action':act,'error':'required action value is missing','resolution':r,'confidence':.94}
    if act=='open_url':
        ok,why=_n57_public_url(val)
        if not ok:return {'ok':False,'action':act,'error':why,'resolution':r,'confidence':.98}
    if act=='open_app' and val not in _N57_APPS:return {'ok':False,'action':act,'error':'app outside Device Agent 4.0 allowlist: '+val,'resolution':r,'confidence':.98}
    if not r.get('device_id'):return {'ok':False,'action':act,'error':r.get('ambiguity') or 'device could not be resolved','resolution':r,'confidence':.96}
    return {'ok':True,'action':act,'value':val,'device_id':r['device_id'],'device_name':r['device_name'],'resolution':r,'confidence':.98}


def _n57_compile(text):
    d=_n57_parse_device(text)
    if d:return {'kind':'DEVICE_ACTION','ok':d.get('ok',False),'confidence':d.get('confidence',.9),'device':d.get('device_name'),'device_id':d.get('device_id'),'action':d.get('action'),'value':d.get('value',''),'error':d.get('error',''),'resolution':d.get('resolution',{}),'steps':[{'tool':'device.precise_action','action':d.get('action')}]}
    try:
        route=_n50_route(text);return {'kind':'TOOL_FABRIC','ok':True,'confidence':.95,'route':route,'resolution':_n57_resolve(text),'steps':[{'tool':x} for x in route.get('tools',[])]}
    except Exception as e:return {'kind':'LEGACY_OR_CHAT','ok':False,'confidence':.4,'error':type(e).__name__+': '+str(e)[:240],'resolution':_n57_resolve(text),'steps':[]}


_DEVICE_QUEUE_V57_PREV=_device_queue_job
def _device_queue_job(did,kind,args=None):
    if kind not in _N57_NEW_DEVICE:return _DEVICE_QUEUE_V57_PREV(did,kind,args)
    try:
        db=_device_jobs_init(_device_load());d=db.get('devices',{}).get(str(did))
        if not d or d.get('revoked'):return None,'device not found or revoked'
        cap=_n57_perm_for(kind)
        if not _n57_perm_get(did,cap):return None,cap+' permission is OFF'
        jid='job_'+_n57_uuid.uuid4().hex[:14]
        with _DEVICE_LOCK:
            db=_device_jobs_init(_device_load());db.setdefault('jobs',{})[jid]={'id':jid,'device_id':did,'kind':kind,'args':args or {},'state':'queued','created':_n57_time.time(),'result':None,'source':'hands57'};_device_save(db)
        try:audit('device','queue_job',jid+' '+kind,'ok')
        except Exception:pass
        return jid,None
    except Exception as e:return None,type(e).__name__+': '+str(e)[:180]


def _n57_job(jid):
    try:return _device_jobs_init(_device_load()).get('jobs',{}).get(str(jid))
    except Exception:return None


def _n57_wait_job(jid,timeout=48):
    end=_n57_time.time()+max(2,min(90,int(timeout)))
    while _n57_time.time()<end:
        j=_n57_job(jid)
        if j and j.get('state') in ('done','failed'):return j
        _n57_time.sleep(.8)
    _N57_STATS['timeouts']+=1;return _n57_job(jid)


def _n57_device_action(cid,device_q,action,value='',wait=True):
    did,d,err=_n57_pick_device(device_q)
    if not did:return {'ok':False,'status':'NEEDS_INPUT','error':err,'verified':False}
    if not _device_online(d):return {'ok':False,'status':'OFFLINE','error':'device is offline','verified':False,'device_id':did}
    kind=str(action or '').lower();cap=_n57_perm_for(kind)
    if not _n57_perm_get(did,cap):return {'ok':False,'status':'NEEDS_PERMISSION','error':cap+' permission is OFF. Use /handperm57 '+str(d.get('name'))+' '+cap+' on','verified':False,'device_id':did}
    if kind in _N57_NEW_DEVICE and str(d.get('agent_version57') or '')!='57.0':return {'ok':False,'status':'NEEDS_AGENT57','error':'This action needs Device Agent 4.0. Generate /deviceagent57 '+str(d.get('name'))+' and run it on that device.','verified':False,'device_id':did}
    args={}
    if kind=='open_url':
        ok,why=_n57_public_url(value)
        if not ok:return {'ok':False,'status':'BLOCKED','error':why,'verified':False}
        args={'url':value}
    elif kind=='open_app':
        app=str(value or '').lower().strip()
        if app not in _N57_APPS:return {'ok':False,'status':'BLOCKED','error':'app outside allowlist','verified':False}
        args={'app':app}
    elif kind=='clipboard_write':args={'text':str(value or '')[:1500]}
    elif kind=='volume':args={'mode':str(value or '')[:30]}
    elif kind in ('voice_speak','notify'):args={'text':str(value or '')[:1200]}
    jid,qerr=_device_queue_job(did,kind,args)
    if qerr or not jid:return {'ok':False,'status':'BLOCKED','error':qerr or 'queue failed','verified':False}
    _N57_STATS['device_jobs']+=1
    if not wait:return {'ok':True,'status':'DISPATCHED','job_id':jid,'verified':False,'evidence':'authenticated device job queued'}
    j=_n57_wait_job(jid,48)
    if not j or j.get('state') not in ('done','failed'):
        _N57_STATS['partial']+=1;return {'ok':True,'status':'DISPATCHED','job_id':jid,'verified':False,'evidence':'queued but no device postcondition returned yet'}
    res=str(j.get('result') or '');ok=j.get('state')=='done';verified=ok and bool(res.strip()) and not res.upper().startswith('ERROR:')
    if verified:_N57_STATS['verified']+=1
    else:_N57_STATS['partial']+=1
    return {'ok':ok,'status':'VERIFIED_COMPLETE' if verified else ('FAILED' if not ok else 'PARTIAL'),'job_id':jid,'verified':verified,
            'result':('valid screenshot payload' if kind=='screenshot' and 'base64,' in res else res[:1200]),'raw_result':res if kind=='screenshot' else '',
            'evidence':'authenticated device heartbeat returned '+str(j.get('state'))+' postcondition','device':d.get('name')}


def _n57_send_screen(cid,raw):
    s=str(raw or '');s=s.split('base64,',1)[1] if 'base64,' in s else s
    try:data=_n57_b64.b64decode(_n57_re.sub(r'\s+','',s),validate=True)
    except Exception:return False
    if len(data)<100:return False
    p=_n57_os.path.join(_n57_tempfile.gettempdir(),'nemo57_'+_n57_uuid.uuid4().hex[:8]+'.png')
    try:
        open(p,'wb').write(data)
        with open(p,'rb') as f:r=requests.post(TG+'/sendPhoto',data={'chat_id':cid,'caption':'🖥 Verified screenshot from enrolled device'},files={'photo':('screen.png',f)},timeout=60)
        return bool(r.ok)
    except Exception:return False
    finally:
        try:_n57_os.remove(p)
        except Exception:pass


def _n57_idem_key(cid,text):return _n57_hashlib.sha256((str(cid)+'|'+ ' '.join(str(text or '').lower().split())).encode()).hexdigest()[:28]


def _n57_idem_get(k,window=45):
    try:
        c=_n35_conn();r=c.execute('SELECT ts,mission_id,status,result FROM hands57_idempotency WHERE idem_key=?',(k,)).fetchone();c.close()
        return r if r and _n57_time.time()-float(r[0])<window else None
    except Exception:return None


def _n57_idem_put(k,mid,st,res):
    try:
        c=_n35_conn();c.execute('INSERT OR REPLACE INTO hands57_idempotency(idem_key,ts,mission_id,status,result) VALUES(?,?,?,?,?)',(k,_n57_time.time(),mid,st,_n57_safe(res,1600)));c.commit();c.close()
    except Exception:pass


def _n57_mission_start(cid,text,plan):
    mid='H57-'+_n57_uuid.uuid4().hex[:10].upper();now=_n57_time.time();target=str(plan.get('device') or '')
    try:
        c=_n35_conn();c.execute('INSERT INTO hands57_mission(id,chat_id,ts,updated,text,kind,target,status,plan_json) VALUES(?,?,?,?,?,?,?,?,?)',(mid,str(cid),now,now,_n57_safe(text,3000),plan.get('kind',''),target,'RUNNING',_n57_j(plan,6500)));c.commit();c.close()
    except Exception:pass
    return mid,now


def _n57_mission_end(mid,st,res,ev,t0):
    try:
        c=_n35_conn();c.execute('UPDATE hands57_mission SET updated=?,status=?,result=?,evidence=?,duration_ms=? WHERE id=?',(_n57_time.time(),st,_n57_safe(res,5000),_n57_safe(ev,2400),int((_n57_time.time()-t0)*1000),mid));c.commit();c.close()
    except Exception:pass
    _N57_STATS['missions']+=1


def _n57_execute_mission(cid,text):
    k=_n57_idem_key(cid,text);dup=_n57_idem_get(k)
    if dup:return {'id':dup[1],'status':'DUPLICATE_SUPPRESSED','text':'♻️ Same Hands mission was already '+str(dup[2])+' recently. I did not execute it again.\n'+str(dup[3] or '')[:900]}
    plan=_n57_compile(text);mid,t0=_n57_mission_start(cid,text,plan)
    if not plan.get('ok'):
        res='I could not safely ground that action: '+str(plan.get('error') or 'ambiguous request');_n57_mission_end(mid,'NEEDS_INPUT',res,'precision resolver blocked guessing',t0);_n57_idem_put(k,mid,'NEEDS_INPUT',res);return {'id':mid,'status':'NEEDS_INPUT','text':res}
    try:
        if plan.get('kind')=='DEVICE_ACTION':
            x=_n57_device_action(cid,plan.get('device') or plan.get('device_id'),plan.get('action'),plan.get('value',''),True);st=x.get('status','FAILED');ev=x.get('evidence') or x.get('error','');rr=x.get('result') or x.get('error','')
            if plan.get('action')=='screenshot' and x.get('raw_result'):_n57_send_screen(cid,x['raw_result'])
            out='🦾 HANDS MISSION '+mid+'\nAction: '+str(plan.get('action'))+' · Target: '+str(plan.get('device') or plan.get('device_id'))+'\nStatus: '+st+'\nEvidence: '+str(ev)[:700]+(('\nResult: '+str(rr)[:1000]) if rr else '')
        else:
            rid,res=_n50_run(cid,text,False);st='COMPLETE' if res else 'PARTIAL';ev='delegated to existing Kernel/Tool Fabric run '+str(rid);out=('🦾 HANDS MISSION '+mid+'\nKernel run: '+str(rid)+'\n\n'+str(res or 'No final result returned.'))[:3900]
        _n57_mission_end(mid,st,out,ev,t0);_n57_idem_put(k,mid,st,out);return {'id':mid,'status':st,'text':out}
    except Exception as e:
        _N57_STATS['errors']+=1;out='Hands mission failed safely: '+type(e).__name__+': '+str(e)[:450];_n57_mission_end(mid,'FAILED',out,'execution exception',t0);_n57_idem_put(k,mid,'FAILED',out);return {'id':mid,'status':'FAILED','text':out}


def _n57_missions(cid,mid=''):
    try:
        c=_n35_conn();rows=([c.execute('SELECT id,kind,target,status,text,result,evidence,duration_ms FROM hands57_mission WHERE id=? AND chat_id=?',(mid,str(cid))).fetchone()] if mid else c.execute('SELECT id,kind,target,status,text,result,evidence,duration_ms FROM hands57_mission WHERE chat_id=? ORDER BY ts DESC LIMIT 10',(str(cid),)).fetchall());c.close();rows=[r for r in rows if r]
    except Exception:rows=[]
    if not rows:return 'No Hands 57 missions recorded.'
    L=['🧾 HANDS 57 ACCOUNTABILITY']
    for r in rows:
        L.append('%s · %s · %s · %d ms\n  %s'%(r[0],r[3],r[1],int(r[7] or 0),str(r[4])[:160]))
        if mid:L+=['Evidence: '+str(r[6])[:900],'Result: '+str(r[5])[:1800]]
    return '\n'.join(L)[:3900]


# Device Agent 4.0 generator: authenticated enrolled-device client, fixed allowlist only.
# There is no arbitrary shell/cmd/PowerShell command endpoint.
def prime_device_agent_script(base_url,enroll_token,name):
    tpl=r'''#!/usr/bin/env python3
import json,os,platform,time,urllib.request,shutil,subprocess,socket,base64,tempfile,webbrowser,re
BASE=__BASE__.rstrip('/');ENROLL=__ENROLL__;NAME=__NAME__;STATE=os.path.expanduser('~/.nemo_device.json');PENDING=[]
CAPS=['sysinfo','disk','processes','network','service_status','screenshot','window_list','active_window','battery','notification_list','phone_location','file_list','clipboard_read','clipboard_write','voice_listen','voice_interrupt','open_url','open_app','volume','voice_speak','notify']
def post(url,obj,auth=''):
 h={'Content-Type':'application/json'}
 if auth:h['Authorization']='Bearer '+auth
 q=urllib.request.Request(BASE+url,data=json.dumps(obj).encode(),headers=h,method='POST');return json.loads(urllib.request.urlopen(q,timeout=30).read().decode())
def load():
 try:return json.load(open(STATE))
 except Exception:return {}
def save(x):
 with open(STATE,'w') as f:json.dump(x,f)
 try:os.chmod(STATE,0o600)
 except Exception:pass
def enroll():
 s=load()
 if s.get('device_id') and s.get('device_secret'):return s
 r=post('/api/device/enroll',{'token':ENROLL,'name':NAME,'platform':platform.system(),'hostname':platform.node()})
 if not r.get('device_id') or not r.get('device_secret'):raise RuntimeError('enrollment failed')
 save(r);return r
def run(cmd,timeout=12):
 try:p=subprocess.run(cmd,capture_output=True,text=True,timeout=timeout);return (p.stdout or p.stderr)[-16000:]
 except Exception as e:return 'ERROR:'+type(e).__name__+': '+str(e)
def telemetry():
 t={'os':platform.platform(),'arch':platform.machine(),'user':os.environ.get('USER') or os.environ.get('USERNAME'),'agent_version':'57.0'}
 try:t['local_ip']=socket.gethostbyname(socket.gethostname())
 except Exception:pass
 try:a,b,c=shutil.disk_usage(os.path.expanduser('~'));t['disk_pct']=round(100*b/max(a,1),1)
 except Exception:pass
 try:t['battery_pct']=json.loads(run(['termux-battery-status'],4)).get('percentage') if shutil.which('termux-battery-status') else None
 except Exception:pass
 return t
def screenshot():
 p=os.path.join(tempfile.gettempdir(),'nemo_screen.png')
 try:
  from PIL import ImageGrab
  im=ImageGrab.grab();im.thumbnail((1280,1280));im.save(p,'PNG',optimize=True)
 except Exception as e:return 'ERROR:'+type(e).__name__+': '+str(e)
 try:return 'data:image/png;base64,'+base64.b64encode(open(p,'rb').read()).decode()
 finally:
  try:os.remove(p)
  except Exception:pass
def active_window():
 try:
  if platform.system()=='Windows':
   import ctypes
   u=ctypes.windll.user32;w=u.GetForegroundWindow();n=u.GetWindowTextLengthW(w);b=ctypes.create_unicode_buffer(n+1);u.GetWindowTextW(w,b,n+1);return b.value or '(no title)'
  if platform.system()=='Darwin':return run(['osascript','-e','tell application "System Events" to get name of first application process whose frontmost is true'])
  return run(['xdotool','getactivewindow','getwindowname']) if shutil.which('xdotool') else 'active-window helper unavailable'
 except Exception as e:return 'ERROR:'+type(e).__name__+': '+str(e)
def clip_read():
 if platform.system()=='Windows':return run(['powershell','-NoProfile','-Command','Get-Clipboard -Raw'],8)
 if platform.system()=='Darwin':return run(['pbpaste'],8)
 if shutil.which('termux-clipboard-get'):return run(['termux-clipboard-get'],8)
 return run(['xclip','-selection','clipboard','-o'],8) if shutil.which('xclip') else 'ERROR:clipboard helper unavailable'
def clip_write(t):
 t=str(t or '')[:1500];b=base64.b64encode(t.encode()).decode()
 if platform.system()=='Windows':r=run(['powershell','-NoProfile','-Command','$b=[Convert]::FromBase64String($args[0]);Set-Clipboard -Value ([Text.Encoding]::UTF8.GetString($b))',b],10)
 elif platform.system()=='Darwin':
  try:p=subprocess.run(['pbcopy'],input=t,text=True,capture_output=True,timeout=8);r=p.stderr or 'ok'
  except Exception as e:r='ERROR:'+str(e)
 elif shutil.which('termux-clipboard-set'):r=run(['termux-clipboard-set',t],8)
 else:r='ERROR:clipboard helper unavailable'
 return r if str(r).startswith('ERROR:') else 'clipboard_written_chars='+str(len(t))
def open_app(a):
 a=str(a or '').lower().strip();maps={'Windows':{'notepad':['notepad.exe'],'calculator':['calc.exe'],'calc':['calc.exe'],'explorer':['explorer.exe'],'file explorer':['explorer.exe'],'edge':['msedge.exe'],'microsoft edge':['msedge.exe'],'chrome':['chrome.exe'],'google chrome':['chrome.exe'],'settings':['cmd.exe','/c','start','ms-settings:'],'task manager':['taskmgr.exe'],'powershell':['powershell.exe'],'terminal':['wt.exe']},'Darwin':{'calculator':['open','-a','Calculator'],'chrome':['open','-a','Google Chrome'],'google chrome':['open','-a','Google Chrome'],'settings':['open','-a','System Settings'],'terminal':['open','-a','Terminal']},'Linux':{'calculator':['gnome-calculator'],'chrome':['google-chrome'],'google chrome':['google-chrome'],'settings':['gnome-control-center'],'terminal':['x-terminal-emulator']}}
 cmd=maps.get(platform.system(),{}).get(a)
 if not cmd:return 'ERROR:app outside local allowlist'
 try:subprocess.Popen(cmd,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL);time.sleep(1);return 'opened_app='+a+'; foreground='+active_window()[:250]
 except Exception as e:return 'ERROR:'+type(e).__name__+': '+str(e)
def volume(m):
 m=str(m or '').lower()
 if platform.system()=='Windows':
  try:
   import ctypes
   k={'mute':0xAD,'unmute':0xAD,'down':0xAE,'up':0xAF}.get(m)
   if k:ctypes.windll.user32.keybd_event(k,0,0,0);ctypes.windll.user32.keybd_event(k,0,2,0);return 'volume_'+m
   return 'ERROR:exact volume set unavailable; use up/down/mute'
  except Exception as e:return 'ERROR:'+str(e)
 if shutil.which('pactl'):
  if m=='up':return run(['pactl','set-sink-volume','@DEFAULT_SINK@','+5%']) or 'volume_up'
  if m=='down':return run(['pactl','set-sink-volume','@DEFAULT_SINK@','-5%']) or 'volume_down'
  if m in ('mute','unmute'):return run(['pactl','set-sink-mute','@DEFAULT_SINK@','1' if m=='mute' else '0']) or 'volume_'+m
 return 'ERROR:volume helper unavailable'
def speak(t):
 t=str(t or '')[:1200];b=base64.b64encode(t.encode()).decode()
 if platform.system()=='Windows':r=run(['powershell','-NoProfile','-Command','$t=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($args[0]));Add-Type -AssemblyName System.Speech;$s=New-Object System.Speech.Synthesis.SpeechSynthesizer;$s.Speak($t)',b],30);return r if r.startswith('ERROR:') else 'spoken'
 if platform.system()=='Darwin':return run(['say',t],30) or 'spoken'
 return run(['termux-tts-speak',t],30) if shutil.which('termux-tts-speak') else 'ERROR:TTS helper unavailable'
def execute(j):
 k=j.get('kind');a=j.get('args') or {};r=''
 if k=='sysinfo':r=json.dumps(telemetry(),indent=2)
 elif k=='disk':r=run(['df','-h']) if os.name!='nt' else run(['wmic','logicaldisk','get','size,freespace,caption'])
 elif k=='processes':r=run(['ps','aux']) if os.name!='nt' else run(['tasklist'])
 elif k=='network':r=run(['ss','-lntup']) if os.name!='nt' else run(['netstat','-ano'])
 elif k=='service_status':r=run(['systemctl','status','--no-pager',str(a.get('service') or '')[:80]]) if os.name!='nt' else run(['sc','query',str(a.get('service') or '')[:80]])
 elif k=='screenshot':r=screenshot()
 elif k=='window_list':r=run(['powershell','-NoProfile','-Command','Get-Process | Where-Object {$_.MainWindowTitle} | Select ProcessName,MainWindowTitle | Format-Table -AutoSize']) if platform.system()=='Windows' else active_window()
 elif k=='active_window':r=active_window()
 elif k=='battery':r=run(['termux-battery-status']) if shutil.which('termux-battery-status') else json.dumps({'battery_pct':telemetry().get('battery_pct')})
 elif k=='notification_list':r=run(['termux-notification-list']) if shutil.which('termux-notification-list') else 'Termux:API notification access unavailable'
 elif k=='phone_location':r=run(['termux-location','-p','gps','-r','once'],25) if shutil.which('termux-location') else 'Termux:API location unavailable'
 elif k=='file_list':
  root=os.path.abspath(os.path.expanduser(str(a.get('path') or '~')));r='\n'.join(os.listdir(root)[:300])
 elif k=='voice_listen':r=run(['termux-speech-to-text'],45) if shutil.which('termux-speech-to-text') else 'Speech endpoint unavailable'
 elif k=='voice_interrupt':r='interrupt acknowledged'
 elif k=='clipboard_read':r=clip_read()
 elif k=='clipboard_write':r=clip_write(a.get('text'))
 elif k=='open_url':
  u=str(a.get('url') or '')[:1600]
  try:r='opened_url='+u if re.match(r'^https?://',u,re.I) and webbrowser.open(u,new=2) else 'ERROR:URL not accepted'
  except Exception as e:r='ERROR:'+str(e)
 elif k=='open_app':r=open_app(a.get('app'))
 elif k=='volume':r=volume(a.get('mode'))
 elif k=='voice_speak':r=speak(a.get('text'))
 elif k=='notify':r='ERROR:notification helper unavailable on this agent build'
 else:return {'id':j.get('id'),'ok':False,'error':'unsupported bounded action'}
 return {'id':j.get('id'),'ok':not str(r).startswith('ERROR:'),'result':str(r)[:450000]}
while True:
 try:
  s=enroll();payload={'telemetry':telemetry(),'capabilities':CAPS,'agent_version':'57.0','job_results':PENDING};PENDING=[]
  r=post('/api/device/'+s['device_id']+'/heartbeat',payload,s['device_secret'])
  for j in (r.get('jobs') or [])[:3]:PENDING.append(execute(j))
 except Exception as e:print('Nemo agent:',e)
 time.sleep(5)
'''
    return tpl.replace('__BASE__',repr(base_url)).replace('__ENROLL__',repr(enroll_token)).replace('__NAME__',repr(name))


_DEVICE_HEARTBEAT_V57_PREV=_device_heartbeat
def _device_heartbeat(did,secret,payload):
    ok,msg=_DEVICE_HEARTBEAT_V57_PREV(did,secret,payload)
    if ok:
        try:
            db=_device_load();d=db.get('devices',{}).get(str(did))
            if d:
                av=str((payload or {}).get('agent_version') or ((payload or {}).get('telemetry') or {}).get('agent_version') or '')[:30];caps=(payload or {}).get('capabilities')
                if av:d['agent_version57']=av
                if isinstance(caps,list):d['capabilities57']=[str(x)[:60] for x in caps[:80]]
                db['devices'][str(did)]=d;_device_save(db)
        except Exception:pass
    return ok,msg


def _n57_agent_file(name):
    base=(WEBCFG.get('public_url') or '').strip()
    if not base.startswith('https://'):return None,'Set an HTTPS public_url first with /setdomain.'
    tok=_device_enroll_create(name);code=prime_device_agent_script(base,tok,name);p='/tmp/nemo_device_agent57_'+_n57_re.sub(r'[^A-Za-z0-9_-]','_',str(name or 'device'))[:30]+'.py'
    try:open(p,'w',encoding='utf-8').write(code);_n57_os.chmod(p,0o700);return p,''
    except Exception as e:return None,type(e).__name__+': '+str(e)[:220]


def _n57_register_tools():
    tools=[
      ('hands.reach_map','systems','Live reach map across Internet/accounts/VPS/data/market/enrolled devices','LOW','OWNER_READ','_n57_reach_status',{}),
      ('hands.resolve','systems','Ground current-request targets without guessing','LOW','OWNER_READ','_n57_resolve',{'text':'string'}),
      ('hands.mission','systems','Execute one grounded mission through existing Kernel or Device Hands','MEDIUM','OWNER_ACTION','_n57_execute_mission',{'text':'string'}),
      ('device.precise_action','device','Bounded action on an enrolled device with permission and postcondition','MEDIUM','OWNER_ACTION','_n57_device_action',{'device':'string','action':'string','value':'string?'}),
      ('hands.mission_status','reliability','Read Hands 57 mission receipts','LOW','OWNER_READ','_n57_missions',{'mission_id':'string?'})]
    try:
        c=_n35_conn();now=_n57_time.time()
        for name,cat,desc,risk,perm,handler,schema in tools:c.execute('INSERT OR REPLACE INTO tool50_registry(name,category,description,risk,permission,handler,version,enabled,health,schema_json,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?)',(name,cat,desc,risk,perm,handler,VERSION,1,'ready' if callable(globals().get(handler)) else 'missing',_n57_j(schema,1600),now))
        c.commit();c.close()
    except Exception:_N57_STATS['errors']+=1


def _n57_status(cid):
    d=_n57_reach_status()['DEVICE_STATE']
