    if 'age-restricted' in e or ('sign in' in e and 'age' in e):return 'ACCESS','Authorized account access is required for this media.'
    if 'sign in to confirm' in e or 'not a bot' in e:return 'BOTCHECK','YouTube rejected the server/IP/session. Use the PO-token provider path, a legitimate configured proxy, or authorized account cookies when actually required.'
    if 'po token' in e or ('pot' in e and 'token' in e):return 'POTOKEN','The selected client needs a PO token. Run /mediafix59 and retry.'
    if 'javascript runtime' in e:return 'JS','JavaScript challenge runtime unavailable. Run /mediafix59.'
    if 'requested format is not available' in e or 'no video formats' in e:return 'FORMATS','Requested format is unavailable for this client/quality.'
    if 'http error 429' in e:return 'RATELIMIT','The service rate-limited this server. Wait before retrying or use your legitimate configured proxy.'
    if 'cookies' in e and ('invalid' in e or 'expired' in e or 'no longer valid' in e):return 'COOKIES','Cookie session is stale/invalid.'
    if 'unsupported url' in e:return 'UNSUPPORTED','yt-dlp does not support this page; a direct public media URL may still work.'
