def _n60_pick_video(arr,h,progressive=None):
    arr=[x for x in (arr or []) if isinstance(x,dict) and x.get('url')]
    if progressive is not None:arr=[x for x in arr if bool(x.get('videoOnly'))!=(True if not progressive else False)] if False else [x for x in arr if bool(x.get('videoOnly'))== (False if progressive else True)]
