def _n62_prepare_helpers():
    try:
        _n62_os.makedirs(_N62_NODE,exist_ok=True)
        open(_N62_JS,'w',encoding='utf-8').write(_N62_JS_CODE)
        open(_N62_PTF,'w',encoding='utf-8').write(_N62_PTF_CODE)
        return True
    except Exception:return False
try:_n62_prepare_helpers()
except Exception:pass

def _n62_trace(rid,backend,status,detail='',ms=0):
    x={'backend':str(backend),'status':str(status),'detail':str(detail)[:500],'ms':round(float(ms or 0),1)}
    _N62_TRACE.setdefault(rid,[]).append(x)
    try:_n60_perf(str(backend),status=='OK',float(ms or 0),'' if status=='OK' else detail)
    except Exception:pass

def _n62_youtubejs_health():
    node=_n62_shutil.which('node') or ''
    pkg=_n62_os.path.join(_N62_NODE,'node_modules','youtubei.js','package.json')
    ver='missing'
    try:
        if _n62_os.path.exists(pkg):ver=str(_n62_json.load(open(pkg,encoding='utf-8')).get('version') or 'installed')
    except Exception:pass
    return {'node':node or 'missing','youtubei_js':ver,'helper':_n62_os.path.exists(_N62_JS)}

def _n62_youtubejs_resolve(url,mode,quality):
    vid=_n60_video_id(url);h=_n62_youtubejs_health()
    if not vid:return None
    if h['node']=='missing' or h['youtubei_js']=='missing':return None
    try:
        r=_n62_sp.run([h['node'],_N62_JS,vid,mode,str(quality)],cwd=_N62_NODE,capture_output=True,text=True,timeout=_N62_ENGINE_TIMEOUT)
        lines=[x for x in (r.stdout or '').splitlines() if x.strip().startswith('{')]
        j=_n62_json.loads(lines[-1]) if lines else {}
        if not j.get('ok'):return None
        out={'backend':j.get('backend','youtubejs'),'title':_n60_safe_name(j.get('title') or vid)}
        if j.get('progressive',{}).get('url'):
            p=j['progressive'];out.update({'progressive':p['url'],'video_mime':p.get('mime','')})
        if j.get('video',{}).get('url'):
            p=j['video'];out.update({'video':p['url'],'video_mime':p.get('mime','')})
        if j.get('audio',{}).get('url'):
            p=j['audio'];out.update({'audio':p['url'],'audio_mime':p.get('mime','')})
        return out if any(out.get(k) for k in ('progressive','video','audio')) else None
    except Exception:return None

def _n62_pytubefix_bounded(url,mode,quality,tag):
    if not _n60_video_id(url):return {'ok':False,'backend':'pytubefix','error':'not YouTube URL'}
    try:
        r=_n62_sp.run(['python3',_N62_PTF,url,mode,str(quality),_N59_DIR,tag],capture_output=True,text=True,timeout=_N62_ALT_TIMEOUT)
        lines=[x for x in (r.stdout or '').splitlines() if x.strip().startswith('{')];j=_n62_json.loads(lines[-1]) if lines else {}
        if j.get('ok'):
            files=[x for x in j.get('files',[]) if _n62_os.path.isfile(x)]
            if mode=='mp3' and files:
                src=files[-1];out=_n62_os.path.splitext(src)[0]+'.mp3';ok,er=_n60_audio_to_mp3(src,out)
                if ok:files=[out]
            return {'ok':bool(files),'backend':'pytubefix','files':files,'title':j.get('title','media'),'error':'' if files else 'no file'}
        return {'ok':False,'backend':'pytubefix','error':j.get('error') or (r.stderr or '')[-600:]}
    except _n62_sp.TimeoutExpired:return {'ok':False,'backend':'pytubefix','error':'timeout'}
    except Exception as e:return {'ok':False,'backend':'pytubefix','error':type(e).__name__+': '+str(e)[:400]}

def _n62_newpipe_cfg():
    """Optional trusted/self-hosted NewPipeWeb backend. Configure media_newpipe_url in Nemo secrets/env."""
    base=str(_n60_secret('media_newpipe_url','') or '').strip().rstrip('/')
    return base

def _n62_stream_items(obj,path=''):
    out=[]
    if isinstance(obj,dict):
        u=obj.get('url') or obj.get('content') or obj.get('streamUrl') or obj.get('stream_url')
        if isinstance(u,str) and u.startswith(('http://','https://')):
            d=dict(obj);d['_path']=path;out.append(d)
        for k,v in obj.items():out.extend(_n62_stream_items(v,(path+'.'+str(k)).strip('.')))
    elif isinstance(obj,list):
        for i,v in enumerate(obj):out.extend(_n62_stream_items(v,path+'['+str(i)+']'))
    return out

def _n62_newpipe_resolve(url,mode,quality):
    vid=_n60_video_id(url);base=_n62_newpipe_cfg()
    if not vid or not base:return None
    host=(_n60_up.urlparse(base).hostname or '').lower();allow_local=host in ('127.0.0.1','localhost','::1')
    if not _n60_is_public_url(base,allow_local=allow_local):return None
    try:
        r=_n60_get(base+'/stream/'+vid,timeout=_N62_ENGINE_TIMEOUT,allow_local=allow_local);j=r.json();items=_n62_stream_items(j)
        if not items:return None
        def mime(x):return str(x.get('mimeType') or x.get('mime_type') or x.get('format') or x.get('type') or '').lower()
        def path(x):return str(x.get('_path') or '').lower()
        def height(x):
            try:return int(x.get('height') or _n62_re.sub(r'\D','',str(x.get('quality') or x.get('qualityLabel') or x.get('resolution') or '0')) or 0)
            except Exception:return 0
        def bitrate(x):
            try:return int(x.get('bitrate') or _n62_re.sub(r'\D','',str(x.get('averageBitrate') or x.get('bitRate') or '0')) or 0)
            except Exception:return 0
        aud=[x for x in items if 'audio' in mime(x) or 'audio' in path(x)];aud.sort(key=bitrate,reverse=True)
        vids=[x for x in items if 'video' in mime(x) or 'video' in path(x)]
        h=_n60_target_h(quality);vc=[x for x in vids if 0<height(x)<=h] or vids;vc.sort(key=lambda x:(height(x),bitrate(x)),reverse=True)
        title=_n60_safe_name((j.get('title') if isinstance(j,dict) else '') or vid)
        out={'backend':'newpipeweb','title':title}
        if mode in ('audio','mp3'):
            if aud:out['audio']=str(aud[0].get('url') or aud[0].get('content') or aud[0].get('streamUrl') or aud[0].get('stream_url'));out['audio_mime']=mime(aud[0])
        else:
            if vc:out['video']=str(vc[0].get('url') or vc[0].get('content') or vc[0].get('streamUrl') or vc[0].get('stream_url'));out['video_mime']=mime(vc[0])
            if aud:out['audio']=str(aud[0].get('url') or aud[0].get('content') or aud[0].get('streamUrl') or aud[0].get('stream_url'));out['audio_mime']=mime(aud[0])
        return out if any(out.get(k) for k in ('progressive','video','audio')) else None
    except Exception:return None

def _n62_resolver_mesh(url,mode,quality):
    jobs=[('youtubejs',_n62_youtubejs_resolve),('piped',_n61_piped_resolve),('invidious',_n61_inv_resolve)]
    if _n62_newpipe_cfg():jobs.append(('newpipeweb',_n62_newpipe_resolve))
    ex=_n62_cf.ThreadPoolExecutor(max_workers=len(jobs));fs={ex.submit(fn,url,mode,quality):name for name,fn in jobs};out=[]
    try:
        for f in _n62_cf.as_completed(fs,timeout=_N62_RESOLVE_BUDGET):
            try:r=f.result()
            except Exception:r=None
            if r:out.append(r)
    except Exception:pass
    for f in fs:f.cancel()
    ex.shutdown(wait=False,cancel_futures=True)
    if _n61_botblocked():
        def rank(x):
            b=str(x.get('backend','')).lower()
            if ':proxy' in b:return 0
            if 'piped' in b:return 1
            if 'youtubejs' in b:return 3
            return 2
        out.sort(key=rank)
    return out

def _n62_fast_ytdlp(url,mode,quality,tag,timeout=70):
    tmpl=_n62_os.path.join(_N59_DIR,tag+'_alt_%(title).100s_%(id)s.%(ext)s')
    cmd=_n59_base(False,None,False)+['--socket-timeout','10','--retries','1','--fragment-retries','1']+_n59_fmt(mode,quality)+['--no-playlist','-o',tmpl,url]
    try:
        r=_n62_sp.run(cmd,capture_output=True,text=True,timeout=timeout);err=(r.stderr or '')[-1200:]
        if r.returncode==0:
            fs=[x for x in _n59_glob.glob(_n62_os.path.join(_N59_DIR,tag+'_alt_*')) if _n62_os.path.isfile(x) and not x.endswith(('.part','.ytdl','.json'))]
            if fs:return {'ok':True,'backend':'yt-dlp-alt-source','files':sorted(set(fs),key=_n62_os.path.getmtime),'title':_n62_os.path.basename(fs[-1])}
        return {'ok':False,'backend':'yt-dlp-alt-source','error':err or 'extractor failed'}
    except _n62_sp.TimeoutExpired:return {'ok':False,'backend':'yt-dlp-alt-source','error':'timeout'}
    except Exception as e:return {'ok':False,'backend':'yt-dlp-alt-source','error':type(e).__name__+': '+str(e)[:300]}

def _n62_source_candidates(query):
    q=str(query or '').strip();seen=set();out=[]
    if not q:return out
    searches=[('soundcloud','site:soundcloud.com '+q),('bandcamp','site:bandcamp.com '+q),('archive','site:archive.org/details '+q),('peertube',q+' PeerTube'),('odysee','site:odysee.com '+q),('ccc','site:media.ccc.de '+q)]
    def one(pair):
        label,qq=pair
        try:return label,web_search(qq) or []
        except Exception:return label,[]
    ex=_n62_cf.ThreadPoolExecutor(max_workers=6);fs=[ex.submit(one,p) for p in searches]
    try:
        for f in _n62_cf.as_completed(fs,timeout=12):
            label,rows=f.result()
            for z in rows[:5]:
                u=str((z or {}).get('href') or (z or {}).get('url') or '').strip()
                if not u or u in seen or not _n60_is_public_url(u):continue
                h=(_n60_up.urlparse(u).hostname or '').lower()
                ok=(label=='soundcloud' and 'soundcloud.com' in h) or (label=='bandcamp' and 'bandcamp.com' in h) or (label=='archive' and 'archive.org' in h) or (label=='odysee' and 'odysee.com' in h) or (label=='ccc' and 'media.ccc.de' in h) or (label=='peertube' and 'youtube.com' not in h and 'youtu.be' not in h)
                if ok:seen.add(u);out.append({'source':label,'url':u,'title':str((z or {}).get('title') or q)})
    except Exception:pass
    ex.shutdown(wait=False,cancel_futures=True)
    return out[:12]

def _n62_try_alt_sources(query,mode,quality,tag,rid,cid,mid):
    xs=_n62_source_candidates(query)
    if not xs:return None,[]
    errs=[]
    for i,x in enumerate(xs[:6],1):
        _n61_edit(cid,mid,'⬇️ MEDIA OMNIMESH 62 · '+rid+'\nTrying alternate public source '+str(i)+'/'+str(min(6,len(xs)))+': '+x['source']+'...')
        t0=_n62_time.time();r=_n62_fast_ytdlp(x['url'],mode,quality,tag+'_s'+str(i),timeout=45);ms=(_n62_time.time()-t0)*1000
        _n62_trace(rid,'source:'+x['source'],'OK' if r.get('ok') else 'FAIL',r.get('error',''),ms)
        if r.get('ok'):r['backend']='source:'+x['source'];return r,errs
        errs.append(x['source']+': '+str(r.get('error',''))[:220])
    return None,errs

