_N62_AGENT_PREV=prime_device_agent_script

def prime_device_agent_script(base_url,enroll_token,name):
    code=_N62_AGENT_PREV(base_url,enroll_token,name)
    needle=" elif k=='notify':r='ERROR:notification helper unavailable on this agent build'\n else:return {'id':j.get('id'),'ok':False,'error':'unsupported bounded action'}"
    block=r""" elif k=='media_download':
  target=str(a.get('target') or '')[:1800]; mode=str(a.get('mode') or 'video'); quality=str(a.get('quality') or 'best')
  if not target:return {'id':j.get('id'),'ok':False,'error':'target required'}
  root=os.path.join(os.path.expanduser('~'),'Downloads','Nemo');os.makedirs(root,exist_ok=True)
  ytdlp=shutil.which('yt-dlp') or shutil.which('yt-dlp.exe')
  if not ytdlp:
   try:
    subprocess.run([sys.executable,'-m','pip','install','-U','yt-dlp'],capture_output=True,text=True,timeout=180)
    ytdlp=shutil.which('yt-dlp') or shutil.which('yt-dlp.exe')
   except Exception:pass
  cmd=[ytdlp] if ytdlp else [sys.executable,'-m','yt_dlp']
  src=target if re.match(r'^https?://',target,re.I) else 'ytsearch1:'+target
  fmt='bestaudio/best' if mode in ('audio','mp3') else ('bv*[height<=720]+ba/b[height<=720]' if quality in ('720','720p') else 'bv*+ba/b')
  tmpl=os.path.join(root,'%(title).100s_%(id)s.%(ext)s');cmd += ['-f',fmt,'--no-playlist','-o',tmpl]
  if mode=='mp3':cmd += ['-x','--audio-format','mp3']
  cmd += [src]
  try:
   p=subprocess.run(cmd,capture_output=True,text=True,timeout=900)
   if p.returncode!=0:r='ERROR:'+(p.stderr or p.stdout or 'download failed')[-1400:]
   else:
    fs=[os.path.join(root,x) for x in os.listdir(root) if os.path.isfile(os.path.join(root,x))];fs.sort(key=lambda x:os.path.getmtime(x),reverse=True)
    r=json.dumps({'saved':fs[0] if fs else root,'bytes':os.path.getsize(fs[0]) if fs else 0})
  except Exception as e:r='ERROR:'+type(e).__name__+': '+str(e)
 elif k=='notify':r='ERROR:notification helper unavailable on this agent build'
 else:return {'id':j.get('id'),'ok':False,'error':'unsupported bounded action'}"""
    if needle in code:code=code.replace(needle,block)
    code=code.replace("'agent_version':'57.0'","'agent_version':'62.0'")
    return code

_DEVICE_HEARTBEAT_V62_PREV=_device_heartbeat
def _device_heartbeat(did,secret,payload):
    ok,msg=_DEVICE_HEARTBEAT_V62_PREV(did,secret,payload)
    if ok:
        try:
            av=str((payload or {}).get('agent_version') or '')
            if av.startswith('62'):
                db=_device_load();d=db.get('devices',{}).get(str(did))
                if d:d['agent_version62']=av;db['devices'][str(did)]=d;_device_save(db)
        except Exception:pass
    return ok,msg

def _n62_relay_device(target,mode,quality,timeout=930):
    try:
        db=_device_load();now=_n62_time.time();cand=[]
        for did,d in (db.get('devices',{}) or {}).items():
            if str(d.get('agent_version62') or '').startswith('62') and now-float(d.get('last_seen') or 0)<30 and _n57_perm_get(did,'control'):cand.append((did,d))
        if not cand:return {'ok':False,'error':'no online Agent-62 device with control permission'}
        did,d=cand[0];jid,err=_device_queue_job(did,'media_download',{'target':target,'mode':mode,'quality':quality})
        if err:return {'ok':False,'error':str(err)}
        t0=_n62_time.time()
        while _n62_time.time()-t0<timeout:
            j=_n57_job_get(jid) if '_n57_job_get' in globals() else (_device_jobs_init(_device_load()).get('jobs',{}) or {}).get(jid)
            if j and str(j.get('state') or '').lower() in ('done','complete','failed'):
                ok=str(j.get('state') or '').lower() in ('done','complete')
                return {'ok':ok,'backend':'device:'+str(d.get('name') or did),'result':j.get('result'),'error':'' if ok else str(j.get('result') or 'device failed')}
            _n62_time.sleep(3)
        # The authenticated device accepted the job but may still be downloading. Do not call that a failure.
        j=_n57_job_get(jid) if '_n57_job_get' in globals() else (_device_jobs_init(_device_load()).get('jobs',{}) or {}).get(jid)
        if j and str(j.get('state') or '').lower() in ('queued','sent'):
            return {'ok':True,'dispatched':True,'backend':'device:'+str(d.get('name') or did),'result':'Download dispatched to enrolled device; it will save under ~/Downloads/Nemo. Job '+jid}
        return {'ok':False,'error':'device relay timeout'}
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)[:300]}

def _n62_agent_file(name):
    base=(WEBCFG.get('public_url') or '').strip()
    if not base.startswith('https://'):return None,'Set an HTTPS public_url first with /setdomain.'
    tok=_device_enroll_create(name);code=prime_device_agent_script(base,tok,name);p='/tmp/nemo_device_agent62_'+_n62_re.sub(r'[^A-Za-z0-9_-]','_',str(name or 'device'))[:30]+'.py'
    try:open(p,'w',encoding='utf-8').write(code);_n62_os.chmod(p,0o700);return p,''
    except Exception as e:return None,type(e).__name__+': '+str(e)[:220]

# ------------------------------- setup / health -------------------------------
def _n62_setup(cid):
    _n62_prepare_helpers();lines=['🔧 MEDIA 62 setup']
    try:_n60_setup(cid);lines.append('base yt-dlp/PyTubeFix stack: requested')
    except Exception as e:lines.append('base stack: '+type(e).__name__)
    if not _n62_shutil.which('node'):
        lines.append('Node.js: missing (YouTube.js unavailable until Node is installed)')
    else:
        try:
            _n62_os.makedirs(_N62_NODE,exist_ok=True)
            if not _n62_os.path.exists(_n62_os.path.join(_N62_NODE,'package.json')):_n62_sp.run(['npm','init','-y'],cwd=_N62_NODE,capture_output=True,text=True,timeout=60)
            r=_n62_sp.run(['npm','install','youtubei.js@latest','--no-audit','--no-fund'],cwd=_N62_NODE,capture_output=True,text=True,timeout=240)
            lines.append('YouTube.js: '+('installed/updated' if r.returncode==0 else 'install failed'))
        except Exception as e:lines.append('YouTube.js: '+type(e).__name__)
    try:
        r=_n62_sp.run(['python3','-m','pip','install','-U','streamlink','--break-system-packages','-q'],capture_output=True,text=True,timeout=240)
        lines.append('Streamlink: '+('installed/updated' if r.returncode==0 else 'install failed'))
    except Exception as e:lines.append('Streamlink: '+type(e).__name__)
    send_text(cid,'\n'.join(lines)+'\n\nRun /mediadoctor62 after setup.')

def _n62_health():
    h=_n62_youtubejs_health();cu,_=_n60_cobalt_cfg()
