def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');chat=msg.get('chat') or {};txt=(msg.get('text') or msg.get('caption') or '').strip();low=txt.lower();owner=(cid==OWNER.get('id') and chat.get('type','private')=='private')
        if owner:
            if low in ('/nemo62','/media62','/mediaomni62'):send_text(cid,_n62_status_text());return
            if low.startswith('/mediafix62'):_n60_threading.Thread(target=_n62_setup,args=(cid,),daemon=True).start();return
            if low.startswith('/mediadoctor62'):send_text(cid,'🩺 MEDIA 62 DOCTOR\n'+_n60_json.dumps(_n62_health(),indent=2)[:3600]);return
            if low.startswith('/mediasources62'):send_text(cid,_n62_status_text());return
            if low.startswith('/setmedia62'):
                parts=txt.split(None,2)
                if len(parts)<3 or parts[1].lower()!='newpipe':send_text(cid,'Usage: /setmedia62 newpipe <https://trusted-NewPipeWeb-backend>  ·  use off to disable');return
                val=parts[2].strip()
                if val.lower() in ('off','disable','disabled','none'):
                    save_secret('media_newpipe_url','');send_text(cid,'✅ NewPipeWeb backend disabled.');return
                host=(_n60_up.urlparse(val).hostname or '').lower();allow_local=host in ('127.0.0.1','localhost','::1')
                if not _n60_is_public_url(val,allow_local=allow_local):send_text(cid,'That endpoint is not a valid trusted HTTP/HTTPS NewPipeWeb backend.');return
                save_secret('media_newpipe_url',val.rstrip('/'));send_text(cid,'✅ NewPipeWeb backend saved. Run /mediadoctor62 to confirm it is visible.');return
            if low.startswith('/mediatrace62'):
                rid=txt.split(' ',1)[1].strip().upper() if ' ' in txt else '';send_text(cid,_n62_attempt_text(rid));return
            if low.startswith('/deviceagent62'):
                name=txt.split(' ',1)[1].strip() if ' ' in txt else 'My-Laptop';p,er=_n62_agent_file(name)
                if not p:send_text(cid,'Agent-62 generation failed: '+er);return
                send_document(cid,p,_n62_os.path.basename(p),'text/x-python');send_text(cid,'Agent-62 generated. Run only on a device you own/control, then enable control with /handperm57 <device> control on. Media relay saves files into ~/Downloads/Nemo on that device.');return
            if low.startswith('/dl62') or low.startswith('/download62'):
                arg=txt.split(' ',1)[1] if ' ' in txt else ''
                if not arg:send_text(cid,'Usage: /dl62 <title or public/authorized URL>');return
                _n60_threading.Thread(target=_n62_download,args=(cid,arg),daemon=True,name='media62').start();return
            if txt and not txt.startswith('/') and _n60_parse(txt).get('order'):_n60_threading.Thread(target=_n62_download,args=(cid,txt),daemon=True,name='media62-natural').start();return
    except Exception as e:
        try:send_text((msg.get('chat') or {}).get('id'),'Media 62 routing error: '+type(e).__name__+': '+str(e)[:160])
        except Exception:pass
    return _N62_HANDLE_PREV(msg)

