def _n63_portal_url(key):
    p=_N63_PORTALS.get(str(key).lower()) or {}
    custom=str(_n60_secret('media_portal_'+str(key).lower()+'_url','') or '').strip()
    return (custom or p.get('url') or '').rstrip('/')+'/'

def _n63_stat(name,ok,ms,detail=''):
    try:
        with _N63_PORTAL_LOCK:
            d=_N63_PORTAL_STATS.setdefault(str(name),{'calls':0,'ok':0,'fail':0,'avg_ms':0.0,'last_error':'','last_ts':0})
            d['calls']+=1;d['ok']+=1 if ok else 0;d['fail']+=0 if ok else 1
            d['avg_ms']=((float(d['avg_ms'])*(d['calls']-1))+float(ms))/max(1,d['calls']);d['last_ts']=_n63_time.time();d['last_error']='' if ok else str(detail)[:500]
    except Exception:pass

def _n63_ext_from_type(ctype,mode='video'):
    c=str(ctype or '').lower()
    if 'audio/mpeg' in c:return '.mp3'
    if 'audio/mp4' in c or 'm4a' in c:return '.m4a'
    if 'audio/webm' in c:return '.webm'
    if 'video/webm' in c:return '.webm'
    if 'video/mp4' in c:return '.mp4'
    return '.mp3' if mode=='mp3' else ('.m4a' if mode=='audio' else '.mp4')

def _n63_rank_text(txt,href,mode,quality):
    s=(str(txt or '')+' '+str(href or '')).lower();score=0
    if mode in ('audio','mp3'):
        score += 70 if 'mp3' in s else 0;score += 45 if 'audio' in s or 'm4a' in s else 0
        for b,w in [('320',30),('256',20),('192',15),('128',10)]:
            if b in s:score+=w
        if any(x in s for x in ('mp4','video','1080','720')):score-=30
    else:
        score += 55 if 'mp4' in s or 'video' in s else 0
        q=str(_n60_target_h(quality));score += 40 if q in s else 0
        for h,w in [('2160',28),('1440',25),('1080',22),('720',18),('480',12),('360',8)]:
            if h in s and int(h)<=_n60_target_h(quality):score+=w
        if 'mp3' in s or 'audio only' in s:score-=40
    if 'download' in s:score+=20
    if any(x in s for x in ('facebook','twitter','share','privacy','terms','advert')):score-=50
    return score

def _n63_portal_download(cid,key,media_url,mode,quality,tag):
    """Best-effort browser adapter. Never handles CAPTCHA/auth/private/DRM bypass."""
    p=_N63_PORTALS.get(str(key).lower())
    if not p:return {'ok':False,'backend':'portal:'+str(key),'error':'unknown portal'}
    if not p.get('auto'):
        return {'ok':False,'backend':'portal:'+str(key),'error':p.get('note') or 'assisted-only portal'}
    if not _n60_video_id(media_url):return {'ok':False,'backend':'portal:'+str(key),'error':'portal requires a canonical public YouTube URL'}
    t0=_n63_time.time();home=_n63_portal_url(key);downloads=[];browser=None
    try:
        ok,why=_ensure_playwright(cid)
        if not ok:raise RuntimeError('Playwright unavailable: '+str(why))
        from playwright.sync_api import sync_playwright
        with sync_playwright() as pw:
            browser=pw.chromium.launch(headless=True)
            ctx=browser.new_context(accept_downloads=True,user_agent='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131 Safari/537.36')
            page=ctx.new_page();page.set_default_timeout(7000)
            page.on('dialog',lambda d:d.dismiss())
            def ondl(dl):downloads.append(dl)
            page.on('download',ondl)
            page.goto(home,wait_until='domcontentloaded',timeout=22000)
            # Stop instead of trying to beat a challenge/security page.
            body=(page.locator('body').inner_text(timeout=5000) or '')[:6000].lower()
            if any(x in body for x in ('captcha','verify you are human','cloudflare challenge','access denied')):
                raise RuntimeError('portal requires a human/security checkpoint')
            # Find the visible URL/search box.
            inp=None
            for loc in [page.locator('input[type="url"]'),page.locator('input[type="text"]'),page.locator('input:not([type])')]:
                try:
                    n=min(loc.count(),12)
                    for i in range(n):
                        el=loc.nth(i)
                        if not el.is_visible():continue
                        meta=' '.join([str(el.get_attribute('placeholder') or ''),str(el.get_attribute('name') or ''),str(el.get_attribute('id') or '')]).lower()
                        if any(w in meta for w in p.get('input_words',())) or inp is None:inp=el
                        if any(w in meta for w in p.get('input_words',())):break
                    if inp is not None:break
                except Exception:continue
            if inp is None:raise RuntimeError('portal input box not found')
            inp.fill(media_url)
            # Submit the form/button.
            clicked=False
            for word in p.get('submit_words',()):
                try:
                    loc=page.get_by_role('button',name=_n63_re.compile(word,_n63_re.I))
                    if loc.count() and loc.first.is_visible():loc.first.click();clicked=True;break
                except Exception:pass
            if not clicked:
                try:inp.press('Enter');clicked=True
                except Exception:pass
            if not clicked:raise RuntimeError('portal submit control not found')
            # Wait for conversion/result DOM, but not indefinitely.
            end=_n63_time.time()+28
            while _n63_time.time()<end and not downloads:
                page.wait_for_timeout(1200)
                text=(page.locator('body').inner_text(timeout=3000) or '')[:8000].lower()
                if any(x in text for x in ('captcha','verify you are human')):raise RuntimeError('portal requires a human checkpoint')
                # Collect visible result links/buttons and rank by desired format.
                candidates=[]
                try:
                    links=page.locator('a[href]');n=min(links.count(),80)
                    for i in range(n):
                        a=links.nth(i)
                        try:
                            if not a.is_visible():continue
                            href=str(a.get_attribute('href') or '');txt=str(a.inner_text(timeout=1000) or '')
                            sc=_n63_rank_text(txt,href,mode,quality)
                            if sc>20:candidates.append((sc,a,href,txt))
                        except Exception:continue
                except Exception:pass
                candidates.sort(key=lambda x:x[0],reverse=True)
                if candidates:
                    # Try only a few top-ranked result controls; popups/challenges are not bypassed.
                    for sc,a,href,txt in candidates[:4]:
                        if downloads:break
                        if href and href.startswith(('http://','https://')) and _n60_is_public_url(href):
                            # Direct-looking media link: download ourselves so evidence is a real file.
                            try:
                                rr=requests.get(href,headers={'User-Agent':_N60_UA,'Referer':page.url},stream=True,timeout=(12,25),allow_redirects=True)
                                ct=(rr.headers.get('content-type') or '').lower();cl=int(rr.headers.get('content-length') or 0)
                                if rr.ok and ('audio/' in ct or 'video/' in ct or 'octet-stream' in ct) and (not cl or cl<=_N60_MAX):
                                    ext=_n63_ext_from_type(ct,mode);out=_n63_os.path.join(_N59_DIR,tag+'_portal_'+key+ext);total=0
                                    with open(out+'.part','wb') as f:
                                        for ch in rr.iter_content(256*1024):
                                            if ch:f.write(ch);total+=len(ch)
                                    if total>32768:_n63_os.replace(out+'.part',out);downloads.append(('file',out));break
                            except Exception:pass
                        try:a.click(timeout=3500);page.wait_for_timeout(900)
                        except Exception:pass
                    if downloads:break
            if downloads:
                item=downloads[0]
                if isinstance(item,tuple):out=item[1]
                else:
                    dl=item;name=_n60_safe_name(dl.suggested_filename or ('portal_'+key))+''
                    ext=_n63_os.path.splitext(name)[1] or _n63_ext_from_type('',mode);out=_n63_os.path.join(_N59_DIR,tag+'_portal_'+key+ext);dl.save_as(out)
                if _n63_os.path.isfile(out) and _n63_os.path.getsize(out)>32768:
                    ms=(_n63_time.time()-t0)*1000;_n63_stat(key,True,ms);return {'ok':True,'backend':'portal:'+key,'files':[out],'title':_n63_os.path.basename(out)}
            raise RuntimeError('portal returned no verified downloadable file')
    except Exception as e:
        ms=(_n63_time.time()-t0)*1000;_n63_stat(key,False,ms,str(e));return {'ok':False,'backend':'portal:'+str(key),'error':type(e).__name__+': '+str(e)[:900]}
    finally:
        try:
            if browser:browser.close()
        except Exception:pass

def _n63_try_server_portals(cid,media_url,mode,quality,tag,rid,mid=None):
    errs=[]
    for key in ('y2mate','savefrom'):
        try:
            if mid:_n61_edit(cid,mid,'⬇️ MEDIA PORTAL 63 · '+rid+'\nTrying '+_N63_PORTALS[key]['name']+' browser fallback...')
        except Exception:pass
        t0=_n63_time.time();r=_n63_portal_download(cid,key,media_url,mode,quality,tag+'_'+key);_n62_trace(rid,'portal:'+key,'OK' if r.get('ok') else 'FAIL',r.get('error',''),(_n63_time.time()-t0)*1000)
        if r.get('ok'):return r,errs
        errs.append(key+': '+str(r.get('error') or '')[:220])
    return None,errs

