def _n63_portal_handoff(target,portal='vidssave',timeout=18):
    try:
        db=_device_load();now=_n63_time.time();cand=[]
        for did,d in (db.get('devices',{}) or {}).items():
            if str(d.get('agent_version63') or '').startswith('63') and now-float(d.get('last_seen') or 0)<40 and _n57_perm_get(did,'control'):cand.append((did,d))
        if not cand:return {'ok':False,'error':'no online Agent-63 device with control permission'}
        did,d=cand[0];jid,err=_device_queue_job(did,'media_portal',{'portal':portal,'media_url':target})
        if err:return {'ok':False,'error':str(err)}
        t0=_n63_time.time()
        while _n63_time.time()-t0<timeout:
            j=_n57_job_get(jid) if '_n57_job_get' in globals() else (_device_jobs_init(_device_load()).get('jobs',{}) or {}).get(jid)
            if j and str(j.get('state') or '').lower() in ('done','complete','failed'):
                ok=str(j.get('state') or '').lower() in ('done','complete');return {'ok':ok,'backend':'portal-device:'+portal,'result':j.get('result'),'error':'' if ok else str(j.get('result') or 'failed')}
            _n63_time.sleep(2)
        return {'ok':True,'dispatched':True,'backend':'portal-device:'+portal,'result':'Portal handoff queued on '+str(d.get('name') or did)+'; source URL copied to clipboard. Job '+jid}
    except Exception as e:return {'ok':False,'error':type(e).__name__+': '+str(e)[:400]}

def _n63_portal_status():
    lines=['🌐 NEMO 63 MEDIA PORTAL BRIDGE','']
    for k,p in _N63_PORTALS.items():
        d=_N63_PORTAL_STATS.get(k,{})
        lines.append(('AUTO' if p.get('auto') else 'ASSIST')+' · '+p['name']+' · '+_n63_portal_url(k))
        if d:lines.append('  calls %s · ok %s · fail %s · avg %.1fs'%(d.get('calls',0),d.get('ok',0),d.get('fail',0),float(d.get('avg_ms',0))/1000))
        if p.get('note'):lines.append('  '+p['note'])
    lines += ['','Server automation: Y2Mate + SaveFrom (best-effort, verified-file only).','VidsSave: assisted browser handoff only; its published terms prohibit abuse through automation.','No CAPTCHA/DRM/private-access bypass.']
    return '\n'.join(lines)

