# ------------------------------- v63 downloader -------------------------------
def _n63_download(cid,request):
    p=_n60_parse(request);target=p.get('target') or '';mode=p.get('mode') or 'video';quality=p.get('quality') or 'best';playlist=bool(p.get('playlist'))
    if not target:send_text(cid,'Tell me the public/authorized song/video or send its link.');return
    fp=_n63_hashlib.sha256((target+'|'+mode+'|'+quality).encode()).hexdigest()[:24]
    with _N62_LOCK:
        old=_N62_ACTIVE.get(fp)
        if old and _n63_time.time()-old[1]<300:send_text(cid,'♻️ Same Media 63 job is already running: '+old[0]);return
        rid='MR63-'+_n63_uuid.uuid4().hex[:10].upper();_N62_ACTIVE[fp]=(rid,_n63_time.time());_N61_CANCEL[rid]=_n60_threading.Event();_N62_TRACE[rid]=[]
    ph=tg('sendMessage',chat_id=cid,text='⬇️ MEDIA PORTAL 63 · '+rid+'\nResolving request...');mid=(ph.get('result') or {}).get('message_id');tag=rid.lower().replace('-','_');res=None;canonical=target;query='';errs=[]
    try:
        if target.startswith('ytsearch1:'):
            query=target.split(':',1)[1];_n61_edit(cid,mid,'⬇️ MEDIA PORTAL 63 · '+rid+'\nSearching for “'+query[:120]+'”...')
            t0=_n63_time.time();rr=_n61_fast_search(query);_n62_trace(rid,'youtube-search','OK' if rr else 'FAIL','',(_n63_time.time()-t0)*1000)
            if rr:canonical=rr['url'];_n61_edit(cid,mid,'⬇️ MEDIA PORTAL 63 · '+rid+'\nFound: '+rr.get('title','')[:160]+'\nTrying native resolver mesh...')
        if _n60_video_id(canonical):
            t0=_n63_time.time();cands=_n62_resolver_mesh(canonical,mode,quality);_n62_trace(rid,'resolver-race','OK' if cands else 'FAIL','%d candidates'%len(cands),(_n63_time.time()-t0)*1000)
            for c in cands:
                r=_n61_mat(cid,mid,rid,c,mode,tag)
                _n62_trace(rid,str(c.get('backend')),'OK' if r.get('ok') else 'FAIL',r.get('error',''),0)
                if r.get('ok'):res=r;break
            if not res:
                cu,_=_n60_cobalt_cfg()
                if cu:
                    r=_n60_cobalt_backend(canonical,mode,quality,tag+'_cb');_n62_trace(rid,'cobalt','OK' if r.get('ok') else 'FAIL',r.get('error',''),0)
                    if r.get('ok'):res=r
            if not res:
                r=_n62_pytubefix_bounded(canonical,mode,quality,tag+'_ptf');_n62_trace(rid,'pytubefix','OK' if r.get('ok') else 'FAIL',r.get('error',''),0)
                if r.get('ok'):res=r
            # New: independent converter websites. They resolve YouTube on their side, which can work when VPS->YouTube is blocked.
            if not res:
                r,es=_n63_try_server_portals(cid,canonical,mode,quality,tag,rid,mid);errs+=es
                if r and r.get('ok'):res=r
            if not res and not _n61_botblocked():
                r=_n62_fast_ytdlp(canonical,mode,quality,tag+'_yd',timeout=55);_n62_trace(rid,'yt-dlp','OK' if r.get('ok') else 'FAIL',r.get('error',''),0)
                if r.get('ok'):res=r
        elif canonical and not canonical.startswith('ytsearch1:'):
            r=_n62_fast_ytdlp(canonical,mode,quality,tag,timeout=60);_n62_trace(rid,'site-extractor','OK' if r.get('ok') else 'FAIL',r.get('error',''),0)
            if r.get('ok'):res=r
        if not res and query:
            r,es=_n62_try_alt_sources(query,mode,quality,tag,rid,cid,mid);errs+=es
            if r and r.get('ok'):res=r
        if not res:
            # Existing direct residential downloader first.
            _n61_edit(cid,mid,'⬇️ MEDIA PORTAL 63 · '+rid+'\nServer routes failed · checking enrolled residential device...')
            rr=_n62_relay_device(query or canonical,mode,quality,timeout=18);_n62_trace(rid,'device-relay','OK' if rr.get('ok') else 'FAIL',rr.get('error',''),0)
            if rr.get('ok'):
                _n61_edit(cid,mid,'✅ MEDIA PORTAL 63 · '+rid+'\nDEVICE DOWNLOAD DISPATCHED\n'+str(rr.get('result'))[:1100]);return
        if not res and _n60_video_id(canonical):
            # VidsSave is deliberately assisted rather than automated because its current published terms prohibit abuse through automation.
            rr=_n63_portal_handoff(canonical,'vidssave',timeout=12);_n62_trace(rid,'portal-device:vidssave','OK' if rr.get('ok') else 'FAIL',rr.get('error',''),0)
            if rr.get('ok'):
                _n61_edit(cid,mid,'🟡 MEDIA PORTAL 63 · '+rid+'\nVidsSave opened on your enrolled laptop and the YouTube URL was copied to clipboard.\nChoose MP3/MP4 quality and click Download in the browser.\n'+str(rr.get('result') or '')[:700]);return
        if not res:
            _n61_edit(cid,mid,'❌ MEDIA PORTAL 63 · '+rid+'\nFAILED — native engines, converter portals, alternate sources, and available device paths were checked.\nUse /mediatrace62 '+rid+' for the backend trace, or /portals63 to inspect portal status.');return
        files=res.get('files') or [];title=res.get('title') or 'media';_n61_edit(cid,mid,'⬇️ MEDIA PORTAL 63 · '+rid+'\nDownload finished · delivering...');d=_n60_deliver(cid,files,mode,title);st='COMPLETE' if d['sent'] and not d['partial'] else 'PARTIAL';_n61_edit(cid,mid,'✅ MEDIA PORTAL 63 · '+rid+'\n'+st+'\nBackend: '+str(res.get('backend'))+'\n'+title[:180]+'\n%.1f MB'%(d['total']/1e6))
    finally:
        with _N62_LOCK:_N62_ACTIVE.pop(fp,None);_N61_CANCEL.pop(rid,None)

_N63_HANDLE_PREV=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');chat=msg.get('chat') or {};txt=(msg.get('text') or msg.get('caption') or '').strip();low=txt.lower();owner=(cid==OWNER.get('id') and chat.get('type','private')=='private')
        if owner:
            if low in ('/nemo63','/media63','/portals63'):send_text(cid,_n63_portal_status());return
            if low.startswith('/deviceagent63'):
                name=txt.split(' ',1)[1].strip() if ' ' in txt else 'My-Laptop';p,er=_n63_agent_file(name)
                if not p:send_text(cid,'Agent-63 generation failed: '+er);return
                send_document(cid,p,_n63_os.path.basename(p),'text/x-python');send_text(cid,'Agent-63 generated. Run it only on a device you own/control, then enable control with /handperm57 <device> control on. It can open Y2Mate/SaveFrom/VidsSave and copy a public YouTube URL for assisted fallback.');return
            if low.startswith('/portal63'):
                parts=txt.split(None,2)
                if len(parts)<3:send_text(cid,'Usage: /portal63 y2mate|savefrom|vidssave <public YouTube URL>');return
                key=parts[1].lower();url=parts[2].strip()
                if key not in _N63_PORTALS or not _n60_video_id(url):send_text(cid,'Use a supported portal and a public YouTube watch/shorts/youtu.be URL.');return
                if key=='vidssave':
                    r=_n63_portal_handoff(url,key);send_text(cid,'VidsSave handoff: '+(_n63_json.dumps(r,ensure_ascii=False)[:1800]));return
                _n60_threading.Thread(target=lambda:_n63_portal_command(cid,key,url),daemon=True,name='portal63').start();return
            if low.startswith('/dl63') or low.startswith('/download63'):
                arg=txt.split(' ',1)[1] if ' ' in txt else ''
                if not arg:send_text(cid,'Usage: /dl63 <title or public/authorized URL>');return
                _n60_threading.Thread(target=_n63_download,args=(cid,arg),daemon=True,name='media63').start();return
            if txt and not txt.startswith('/') and _n60_parse(txt).get('order'):_n60_threading.Thread(target=_n63_download,args=(cid,txt),daemon=True,name='media63-natural').start();return
    except Exception as e:
        try:send_text((msg.get('chat') or {}).get('id'),'Media 63 routing error: '+type(e).__name__+': '+str(e)[:180])
        except Exception:pass
    return _N63_HANDLE_PREV(msg)

def _n63_portal_command(cid,key,url):
    rid='P63-'+_n63_uuid.uuid4().hex[:8].upper();send_text(cid,'🌐 '+_N63_PORTALS[key]['name']+' portal test · '+rid+'\nTrying public URL...')
    r=_n63_portal_download(cid,key,url,'video','720p',rid.lower())
    if r.get('ok'):
        d=_n60_deliver(cid,r.get('files') or [],'video',r.get('title') or 'media');send_text(cid,'✅ Portal test complete · '+str(r.get('backend'))+' · %.1f MB'%(d.get('total',0)/1e6))
    else:send_text(cid,'❌ Portal test failed · '+str(r.get('error') or 'unknown')[:1800])

