# =============================================================================
# NEMO 64.0 — MEDIA WORKSPACE + DOWNLOAD CONTROL
# Five upgrades in one:
# 1) Persistent download job/status workspace with truthful stages and elapsed time.
# 2) Downloaded-file catalog with stable file IDs and Telegram resend/visibility.
# 3) Owner file controls: info, rename, delete-confirm, trim, MP3 conversion.
# 4) Bounded portal attempts + stale-job/duplicate-lock recovery + cancellation visibility.
# 5) Verified delivery receipts: a file is COMPLETE only when bytes exist and delivery is attempted.
# Public/authorized media only. No DRM, CAPTCHA, paywall, private-access, or auth bypass.
# =============================================================================
VERSION='64.0'
import os as _n64_os, re as _n64_re, time as _n64_time, json as _n64_json, hashlib as _n64_hashlib
import threading as _n64_threading, uuid as _n64_uuid, shutil as _n64_shutil

_N64_LOCK=_n64_threading.RLock()
_N64_ACTIVE={}
_N64_PORTAL_TIMEOUT=42
_N64_MIN_FILE=32768


def _n64_init():
    c=_n35_conn();c.executescript("""
    CREATE TABLE IF NOT EXISTS media64_job(
      id TEXT PRIMARY KEY, chat_id TEXT, created REAL, updated REAL, request TEXT,
      target TEXT, mode TEXT, quality TEXT, status TEXT, stage TEXT DEFAULT '',
      backend TEXT DEFAULT '', title TEXT DEFAULT '', error TEXT DEFAULT '', file_ids TEXT DEFAULT '',
      message_id TEXT DEFAULT '', meta TEXT DEFAULT '{}');
    CREATE INDEX IF NOT EXISTS idx_media64_job_chat ON media64_job(chat_id,created DESC);
    CREATE TABLE IF NOT EXISTS media64_file(
      id TEXT PRIMARY KEY, created REAL, updated REAL, job_id TEXT, path TEXT UNIQUE,
      name TEXT, ext TEXT, size INTEGER DEFAULT 0, mode TEXT DEFAULT '', backend TEXT DEFAULT '',
      title TEXT DEFAULT '', sha256 TEXT DEFAULT '', deleted INTEGER DEFAULT 0, meta TEXT DEFAULT '{}');
    CREATE INDEX IF NOT EXISTS idx_media64_file_updated ON media64_file(updated DESC);
    """);c.commit();c.close()
try:_n64_init()
except Exception:pass


def _n64_job_new(cid,request,target,mode,quality,mid=''):
    rid='MR64-'+_n64_uuid.uuid4().hex[:10].upper();now=_n64_time.time()
    try:
        c=_n35_conn();c.execute('INSERT INTO media64_job(id,chat_id,created,updated,request,target,mode,quality,status,stage,message_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)',
          (rid,str(cid),now,now,str(request)[:1500],str(target)[:1500],str(mode),str(quality),'RUNNING','QUEUED',str(mid or '')));c.commit();c.close()
    except Exception:pass
    return rid


def _n64_job_update(rid,**kw):
    allow={'status','stage','backend','title','error','file_ids','message_id','meta'};xs=[(k,v) for k,v in kw.items() if k in allow]
    if not xs:return
    try:
        c=_n35_conn();sql='UPDATE media64_job SET updated=?,'+','.join(k+'=?' for k,v in xs)+' WHERE id=?';vals=[_n64_time.time()]+[str(v)[:6000] for k,v in xs]+[rid];c.execute(sql,vals);c.commit();c.close()
    except Exception:pass


def _n64_job_get(rid):
    try:
        c=_n35_conn();r=c.execute('SELECT id,chat_id,created,updated,request,target,mode,quality,status,stage,backend,title,error,file_ids,message_id,meta FROM media64_job WHERE id=?',(str(rid),)).fetchone();c.close()
        if not r:return None
        keys=['id','chat_id','created','updated','request','target','mode','quality','status','stage','backend','title','error','file_ids','message_id','meta'];return dict(zip(keys,r))
    except Exception:return None


def _n64_jobs(cid=None,limit=12):
    try:
        c=_n35_conn();
        if cid is None:r=c.execute('SELECT id,created,updated,request,status,stage,backend,title,error,file_ids FROM media64_job ORDER BY created DESC LIMIT ?', (int(limit),)).fetchall()
        else:r=c.execute('SELECT id,created,updated,request,status,stage,backend,title,error,file_ids FROM media64_job WHERE chat_id=? ORDER BY created DESC LIMIT ?', (str(cid),int(limit))).fetchall()
        c.close();keys=['id','created','updated','request','status','stage','backend','title','error','file_ids'];return [dict(zip(keys,x)) for x in r]
    except Exception:return []


def _n64_sha(path):
    try:
        h=_n64_hashlib.sha256()
        with open(path,'rb') as f:
            for ch in iter(lambda:f.read(1024*1024),b''):h.update(ch)
        return h.hexdigest()
    except Exception:return ''


def _n64_register_file(path,job_id='',mode='',backend='',title=''):
    try:
        p=_n64_os.path.abspath(str(path));
        if not _n64_os.path.isfile(p):return ''
        sz=_n64_os.path.getsize(p)
        if sz<1 or (sz<_N64_MIN_FILE and backend not in ('https76','https77')):return ''
        name=_n64_os.path.basename(p);ext=_n64_os.path.splitext(name)[1].lower();now=_n64_time.time();sha=''
        c=_n35_conn();old=c.execute('SELECT id FROM media64_file WHERE path=? AND deleted=0',(p,)).fetchone()
        if old:
            fid=str(old[0]);c.execute('UPDATE media64_file SET updated=?,job_id=CASE WHEN ?<>"" THEN ? ELSE job_id END,name=?,ext=?,size=?,mode=CASE WHEN ?<>"" THEN ? ELSE mode END,backend=CASE WHEN ?<>"" THEN ? ELSE backend END,title=CASE WHEN ?<>"" THEN ? ELSE title END WHERE id=?',(now,str(job_id),str(job_id),name,ext,int(sz),str(mode),str(mode),str(backend),str(backend),str(title)[:500],str(title)[:500],fid));c.commit();c.close();return fid
        sig=_n64_hashlib.sha256((p+'|'+str(sz)+'|'+str(int(_n64_os.path.getmtime(p)))).encode()).hexdigest()[:10].upper();fid='F64-'+sig
        try:
            if sz<=300*1024*1024:sha=_n64_sha(p)
        except Exception:pass
        c.execute('INSERT OR REPLACE INTO media64_file(id,created,updated,job_id,path,name,ext,size,mode,backend,title,sha256,deleted,meta) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,0,?)',
          (fid,now,now,str(job_id),p,name,ext,int(sz),str(mode),str(backend),str(title)[:500],sha,'{}'));c.commit();c.close();return fid
    except Exception:return ''


def _n64_scan_files():
    out=[]
    try:
        for name in _n64_os.listdir(_N59_DIR):
            p=_n64_os.path.join(_N59_DIR,name)
            if not _n64_os.path.isfile(p) or name.endswith(('.part','.ytdl','.json','.tmp')):continue
            try:
                if _n64_os.path.getsize(p)<_N64_MIN_FILE:continue
            except Exception:continue
            fid=_n64_register_file(p)
            if fid:out.append(fid)
    except Exception:pass
    return out


def _n64_file(fid):
    try:
        _n64_scan_files();c=_n35_conn();r=c.execute('SELECT id,created,updated,job_id,path,name,ext,size,mode,backend,title,sha256,deleted,meta FROM media64_file WHERE id=?',(str(fid).upper(),)).fetchone();c.close()
        if not r:return None
        keys=['id','created','updated','job_id','path','name','ext','size','mode','backend','title','sha256','deleted','meta'];return dict(zip(keys,r))
    except Exception:return None


def _n64_files(limit=20):
    _n64_scan_files()
    try:
        c=_n35_conn();rows=c.execute('SELECT id,updated,job_id,path,name,ext,size,mode,backend,title,deleted FROM media64_file WHERE deleted=0 ORDER BY updated DESC LIMIT ?', (int(limit),)).fetchall();c.close();keys=['id','updated','job_id','path','name','ext','size','mode','backend','title','deleted'];return [dict(zip(keys,x)) for x in rows]
    except Exception:return []


def _n64_files_text(limit=20):
    rows=_n64_files(limit);lines=['📁 NEMO MEDIA WORKSPACE 64', 'Folder: '+str(_N59_DIR)]
    if not rows:return '\n'.join(lines+['','No verified downloaded files exist yet.'])
    lines+=['','VERIFIED FILES']
    for r in rows:
        lines.append('%s · %.1f MB · %s\n%s'%(r['id'],float(r['size'] or 0)/1e6,(r['ext'] or '').lstrip('.').upper() or 'FILE',str(r['name'])[:120]))
    lines+=['','Use /file64 F64-... for details · /send64 F64-... to send it here.']
    return '\n'.join(lines)[:3900]


def _n64_status_text(cid,rid=''):
    if rid:
        j=_n64_job_get(rid)
        if not j:return 'Media 64 job not found.'
        elapsed=max(0,_n64_time.time()-float(j.get('created') or 0));return ('⬇️ MEDIA JOB '+j['id']+'\nStatus: '+str(j['status'])+'\nStage: '+str(j['stage'])+'\nElapsed: %.0fs'%elapsed+'\nBackend: '+str(j['backend'] or '—')+'\nFiles: '+str(j['file_ids'] or '—')+('\nError: '+str(j['error'])[:900] if j['error'] else ''))
    rows=_n64_jobs(cid,10);lines=['⬇️ MEDIA JOBS 64']
    if not rows:return '\n'.join(lines+['','No jobs recorded.'])
    for j in rows:
        elapsed=max(0,_n64_time.time()-float(j.get('created') or 0));lines.append('%s · %s · %s · %.0fs'%(j['id'],j['status'],j['stage'],elapsed))
    return '\n'.join(lines)[:3900]


