def _n64_portal_bounded(cid,key,url,mode,quality,tag,timeout=_N64_PORTAL_TIMEOUT):
    box={};done=_n64_threading.Event()
    def run():
        try:box['r']=_n63_portal_download(cid,key,url,mode,quality,tag)
        except Exception as e:box['r']={'ok':False,'backend':'portal:'+key,'error':type(e).__name__+': '+str(e)[:500]}
        finally:done.set()
    _n64_threading.Thread(target=run,daemon=True,name='portal64-'+str(key)).start()
    if not done.wait(timeout):return {'ok':False,'backend':'portal:'+key,'error':'TIMEOUT: no verified file within %ss'%int(timeout)}
    return box.get('r') or {'ok':False,'backend':'portal:'+key,'error':'portal returned no result'}


def _n64_mode_from_file(f):
    e=str((f or {}).get('ext') or '').lower()
    return 'audio' if e in ('.mp3','.m4a','.aac','.wav','.flac','.opus','.ogg') else 'video' if e in ('.mp4','.mkv','.webm','.mov','.avi') else 'document'


def _n64_send_id(cid,fid):
    f=_n64_file(fid)
    if not f or f.get('deleted'):return False,'file not found'
    p=f.get('path') or ''
    if not _n64_os.path.isfile(p):return False,'file is indexed but missing from disk'
    mode=_n64_mode_from_file(f)
    try:
        if mode=='document':send_document(cid,p,f.get('name') or _n64_os.path.basename(p));return True,'document'
        x=_n59_send_file(cid,p,mode,f.get('title') or f.get('name') or 'media');return (bool(x),str(x or 'send failed'))
    except Exception as e:return False,type(e).__name__+': '+str(e)[:300]


def _n64_safe_new_name(old,new):
    base=_n60_safe_name(str(new or '').strip())
    if not base:return ''
    oe=_n64_os.path.splitext(old)[1];ne=_n64_os.path.splitext(base)[1]
    if not ne and oe:base+=oe
    return base[:180]


def _n64_rename(fid,new):
    f=_n64_file(fid)
    if not f or f.get('deleted'):return False,'file not found'
    old=f['path'];nn=_n64_safe_new_name(f['name'],new)
    if not nn:return False,'invalid new name'
    dest=_n64_os.path.join(_n64_os.path.dirname(old),nn)
    if _n64_os.path.exists(dest):return False,'a file with that name already exists'
    try:
        _n64_os.replace(old,dest);now=_n64_time.time();c=_n35_conn();c.execute('UPDATE media64_file SET path=?,name=?,ext=?,updated=? WHERE id=?',(dest,nn,_n64_os.path.splitext(nn)[1].lower(),now,str(fid).upper()));c.commit();c.close();return True,nn
    except Exception as e:return False,type(e).__name__+': '+str(e)[:300]


def _n64_delete(fid,confirm=False):
    if not confirm:return False,'confirmation required: /delete64 '+str(fid)+' CONFIRM'
    f=_n64_file(fid)
    if not f or f.get('deleted'):return False,'file not found'
    try:
        if _n64_os.path.isfile(f['path']):_n64_os.remove(f['path'])
        c=_n35_conn();c.execute('UPDATE media64_file SET deleted=1,updated=? WHERE id=?',(_n64_time.time(),str(fid).upper()));c.commit();c.close();return True,'deleted'
    except Exception as e:return False,type(e).__name__+': '+str(e)[:300]


def _n64_trim(fid,start,end):
    f=_n64_file(fid)
    if not f or f.get('deleted'):return False,'file not found',''
    p=f['path'];root,ext=_n64_os.path.splitext(p);out=root+'_trim'+ext
    try:
        r=_n60_sp.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-ss',str(start),'-to',str(end),'-i',p,'-c','copy',out],capture_output=True,text=True,timeout=1800)
        if r.returncode!=0 or not _n64_os.path.isfile(out) or _n64_os.path.getsize(out)<_N64_MIN_FILE:return False,(r.stderr or 'trim failed')[-600:],''
        nf=_n64_register_file(out,f.get('job_id') or '',_n64_mode_from_file(f), 'edit:trim',f.get('title') or '');return True,'trimmed',nf
    except Exception as e:return False,type(e).__name__+': '+str(e)[:400],''


def _n64_mp3(fid):
    f=_n64_file(fid)
