def _n64_finalize(cid,mid,rid,res,mode):
    files=[p for p in (res.get('files') or []) if _n64_os.path.isfile(p) and _n64_os.path.getsize(p)>=_N64_MIN_FILE]
    if not files:
        _n64_job_update(rid,status='FAILED',stage='NO_VERIFIED_FILE',error='backend reported success but no verified file exists');_n61_edit(cid,mid,'❌ MEDIA WORKSPACE 64 · '+rid+'\nFAILED\nNo verified file exists on the VPS, so there is nothing to send.');return
    title=res.get('title') or _n64_os.path.basename(files[-1]);ids=[]
    for p in files:
        x=_n64_register_file(p,rid,mode,res.get('backend') or '',title)
        if x:ids.append(x)
    _n64_job_update(rid,status='READY',stage='FILE_READY',backend=res.get('backend') or '',title=title,file_ids=','.join(ids))
    _n61_edit(cid,mid,'📁 MEDIA WORKSPACE 64 · '+rid+'\nFILE READY\n'+(', '.join(ids) if ids else 'indexed')+'\nDelivering downloaded files...')
    d=_n60_deliver(cid,files,mode,title);st='COMPLETE' if d.get('sent') and not d.get('partial') else 'PARTIAL'
    _n64_job_update(rid,status=st,stage='DELIVERED' if st=='COMPLETE' else 'DELIVERY_PARTIAL')
    _n61_edit(cid,mid,('✅' if st=='COMPLETE' else '🟡')+' MEDIA WORKSPACE 64 · '+rid+'\n'+st+'\nBackend: '+str(res.get('backend') or 'unknown')+'\nFiles: '+(', '.join(ids) if ids else '—')+'\nSize: %.1f MB'%(float(d.get('total') or 0)/1e6)+('\nVerified Drive saves: '+str(d['drive_saved']) if 'drive_saved' in d else '')+'\nAsk to show downloaded files, or say: Retry F64-ID to Drive.')


