def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');chat=msg.get('chat') or {};txt=(msg.get('text') or msg.get('caption') or '').strip();low=txt.lower();owner=(cid==OWNER.get('id') and chat.get('type','private')=='private')
        if owner:
            if low in ('/nemo64','/media64','/files64','/downloads64'):
                send_text(cid,_n64_files_text(20)+'\n\n'+_n64_status_text(cid));return
            if low.startswith('/status64'):
                rid=txt.split(None,1)[1].strip() if ' ' in txt else '';send_text(cid,_n64_status_text(cid,rid));return
            if low.startswith('/file64') or low.startswith('/info64'):
                a=txt.split(None,1);send_text(cid,_n64_file_info_text(_n64_file(a[1].strip())) if len(a)>1 else 'Usage: /file64 F64-...');return
            if low.startswith('/send64'):
                a=txt.split(None,1)
                if len(a)<2:send_text(cid,'Usage: /send64 F64-...');return
                ok,detail=_n64_send_id(cid,a[1].strip());send_text(cid,('✅ Sent.' if ok else '❌ Send failed: ')+str(detail)[:500]);return
            if low.startswith('/rename64'):
                a=txt.split(None,2)
                if len(a)<3:send_text(cid,'Usage: /rename64 F64-... New File Name');return
                ok,detail=_n64_rename(a[1],a[2]);send_text(cid,('✅ Renamed to ' if ok else '❌ Rename failed: ')+str(detail));return
            if low.startswith('/delete64'):
                a=txt.split()
                if len(a)<2:send_text(cid,'Usage: /delete64 F64-... CONFIRM');return
                ok,detail=_n64_delete(a[1],len(a)>2 and a[2].upper()=='CONFIRM');send_text(cid,('✅ ' if ok else '❌ ')+str(detail));return
            if low.startswith('/trim64'):
                a=txt.split()
                if len(a)<4:send_text(cid,'Usage: /trim64 F64-... START END\nExample: /trim64 F64-ABC 00:00:10 00:00:40');return
                ok,detail,nf=_n64_trim(a[1],a[2],a[3]);send_text(cid,('✅ Trimmed: '+nf if ok else '❌ Trim failed: '+str(detail)[:700]));return
            if low.startswith('/mp364'):
                a=txt.split()
                if len(a)<2:send_text(cid,'Usage: /mp364 F64-...');return
                ok,detail,nf=_n64_mp3(a[1]);send_text(cid,('✅ MP3 ready: '+nf if ok else '❌ MP3 failed: '+str(detail)[:700]));return
            if low.startswith('/cancel64'):
                a=txt.split(None,1);rid=a[1].strip() if len(a)>1 else ''
                if not rid:send_text(cid,'Usage: /cancel64 MR64-...');return
                ev=_N61_CANCEL.get(rid)
                if ev:ev.set();_n64_job_update(rid,status='CANCEL_REQUESTED',stage='CANCEL_REQUESTED');send_text(cid,'🛑 Cancel requested for '+rid)
                else:send_text(cid,'No active cancellable job found for '+rid)
                return
            if low.startswith('/dl64') or low.startswith('/download64'):
                arg=txt.split(' ',1)[1] if ' ' in txt else ''
                if not arg:send_text(cid,'Usage: /dl64 <title or public/authorized URL>');return
                _n64_threading.Thread(target=_n64_download,args=(cid,arg),daemon=True,name='media64').start();return
            if txt and not txt.startswith('/') and _n60_parse(txt).get('order'):
                _n64_threading.Thread(target=_n64_download,args=(cid,txt),daemon=True,name='media64-natural').start();return
    except Exception as e:
        try:send_text((msg.get('chat') or {}).get('id'),'Media 64 routing error: '+type(e).__name__+': '+str(e)[:220])
        except Exception:pass
    return _N64_HANDLE_PREV(msg)


