        cid=(msg.get('chat') or {}).get('id');chat=msg.get('chat') or {};txt=(msg.get('text') or msg.get('caption') or '').strip();low=txt.lower();owner=(cid==OWNER.get('id') and chat.get('type','private')=='private')
        if owner:
            if low in ('/nemo65','/media65','/mediarepair65'):
                send_text(cid,'NEMO 65.0 — MEDIA SELF-HEAL\n━━━━━━━━━━━━━━━━━━━━\nRuntime-aware dependency repair: ACTIVE\nPyTubeFix worker interpreter: '+str(_n65_sys.executable)+'\nAuto-preflight before downloads: ACTIVE\nVerified-file rules from v64: ACTIVE\n\n/mediafix65 · /mediadoctor65 · /files64 · /status64');return
            if low.startswith('/mediafix65') or low.startswith('/mediafix62'):
                _n65_threading.Thread(target=lambda:_n65_preflight(cid,force=True,full=True),daemon=True,name='mediafix65').start();return
            if low.startswith('/mediadoctor65') or low.startswith('/mediadoctor62'):
                send_text(cid,_n65_doctor_text());return
            if low.startswith('/dl65') or low.startswith('/download65') or low.startswith('/dl64') or low.startswith('/download64'):
                arg=txt.split(' ',1)[1] if ' ' in txt else ''
                if not arg:send_text(cid,'Usage: /dl65 <title or public/authorized URL>');return
