VERSION='66.0'
import os as _n66_os, re as _n66_re, time as _n66_time, json as _n66_json, uuid as _n66_uuid
import shutil as _n66_shutil, importlib.util as _n66_iu, threading as _n66_threading

_N66_LOCK=_n66_threading.RLock()
_N66_SEM=_n66_threading.BoundedSemaphore(4)
_N66_FUT={}
_N66_CANCEL={}
_N701_ADMISSION=_n66_threading.BoundedSemaphore(12)
_N66_LAST_ROUTE={}
_N66_BOOT={'done':False,'errors':[],'ts':0}
