def _n66_db_init():
    try:
        c=_n35_conn();c.executescript("""
        CREATE TABLE IF NOT EXISTS task66(
          id TEXT PRIMARY KEY, chat_id TEXT, created REAL, updated REAL,
          kind TEXT, request TEXT, status TEXT, stage TEXT, result TEXT DEFAULT '',
          error TEXT DEFAULT '', verified INTEGER DEFAULT 0, cancel_requested INTEGER DEFAULT 0,
          duration_ms INTEGER DEFAULT 0
        );
        CREATE INDEX IF NOT EXISTS idx_task66_chat ON task66(chat_id,updated DESC);
        CREATE TABLE IF NOT EXISTS route66_event(
          id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id TEXT, ts REAL,
          request TEXT, kind TEXT, confidence REAL, reason TEXT
        );
        """);c.commit();c.close()
    except Exception as e:
        _N66_BOOT['errors'].append('db:'+type(e).__name__)
try:_n66_db_init()
except Exception:pass


def _n66_safe(s,n=3600):
    x=' '.join(str(s or '').split()) if n<1500 else str(s or '')
    return x[:n]


def _n66_send(cid,text):
    s=str(text or '')
    try:s,blocked=_n56_strip_tool_markup(s)
    except Exception:blocked=False
    if not s.strip():s='I could not produce a clean result. The internal output was blocked instead of being shown to you.'
    # Keep Telegram replies readable. Existing send_text can handle its own splitting where supported.
    try:return send_text(cid,s)
    except Exception:return None


def _n66_task_new(cid,kind,request,stage='QUEUED'):
    tid='T66-'+_n66_uuid.uuid4().hex[:10].upper();now=_n66_time.time()
    try:
        c=_n35_conn();c.execute('INSERT INTO task66(id,chat_id,created,updated,kind,request,status,stage) VALUES(?,?,?,?,?,?,?,?)',(tid,str(cid),now,now,str(kind)[:80],str(request)[:3000],'QUEUED',stage));c.commit();c.close()
    except Exception:pass
    return tid,now


def _n66_task_update(tid,status=None,stage=None,result=None,error=None,verified=None,started=None,cancel=None):
    xs=[];vals=[]
    for k,v in [('status',status),('stage',stage),('result',result),('error',error),('verified',verified),('cancel_requested',cancel)]:
        if v is not None:
            xs.append(k+'=?');vals.append(int(v) if k in ('verified','cancel_requested') else str(v)[:5000])
    xs.append('updated=?');vals.append(_n66_time.time())
    if started is not None:
        xs.append('duration_ms=?');vals.append(int((_n66_time.time()-started)*1000))
    try:
        c=_n35_conn();c.execute('UPDATE task66 SET '+','.join(xs)+' WHERE id=?',vals+[tid]);c.commit();c.close()
    except Exception:pass


def _n66_cancelled(tid):
    ev=_N66_CANCEL.get(tid)
    return bool(ev and ev.is_set())


def _n66_worker(cid,tid,started,kind,request,fn,args,kwargs,verified_when_result=False,_admission_reserved=False):
    acquired=False
    _n71_tls=globals().get('_N71_TLS')
    try:
        # Poll cancellation while queued. Every acquired permit is released in finally.
        while not acquired:
            if _n66_cancelled(tid):
                _n66_task_update(tid,status='CANCELLED',stage='CANCELLED_BEFORE_EXECUTION',started=started,cancel=1)
                return
            acquired=_N66_SEM.acquire(timeout=0.25)
        if _n66_cancelled(tid):
            _n66_task_update(tid,status='CANCELLED',stage='CANCELLED_BEFORE_EXECUTION',started=started,cancel=1)
            return
        _n66_task_update(tid,status='RUNNING',stage='EXECUTING',started=started)
        if _n71_tls is not None:_n71_tls.task_id=tid
        r=fn(*args,**kwargs)
        if _n66_cancelled(tid):
            _n66_task_update(tid,status='CANCEL_REQUESTED',stage='RETURNED_AFTER_CANCEL_REQUEST',result=_n66_safe(r,1800),started=started,cancel=1)
            return
        text='';verified=False
        if isinstance(r,dict):
            text=str(r.get('text') or r.get('result') or '')
            if r.get('ok') is False:
                _n66_task_update(tid,status='FAILED',stage='TOOL_REPORTED_FAILURE',result=_n66_safe(text,3000),error=str(r.get('error') or 'Tool returned ok=False')[:800],verified=0,started=started)
                if text.strip():_n66_send(cid,text)
                return
            verified=bool(r.get('verified') or (r.get('ok') and r.get('evidence')))
        elif isinstance(r,str):text=r
        # Legacy verified_when_result remains accepted for call compatibility, but
        # nonempty text alone is not proof of a completed external action.
        _n66_task_update(tid,status='COMPLETE',stage='DONE',result=_n66_safe(text,3000),verified=1 if verified else 0,started=started)
        if text.strip():_n66_send(cid,text)
    except Exception as e:
        er=type(e).__name__+': task execution failed; inspect server logs/receipts.'
        _n66_task_update(tid,status='FAILED',stage='FAILED',error=er,verified=0,started=started)
        _n66_send(cid,'Task '+tid+' failed. '+er+' Use /task66 '+tid+' for status.')
    finally:
        if _n71_tls is not None and hasattr(_n71_tls,'task_id'):del _n71_tls.task_id
        if acquired:_N66_SEM.release()
        with _N66_LOCK:
            _N66_FUT.pop(tid,None)
            _N66_CANCEL.pop(tid,None)
        if _admission_reserved:_N701_ADMISSION.release()


def _n66_submit(cid,kind,request,fn,*args,verified_when_result=False,**kwargs):
    # Four executing workers + up to eight waiting threads; admission comes first.
    if not _N701_ADMISSION.acquire(blocking=False):
        tid,started=_n66_task_new(cid,kind,request)
        _n66_task_update(tid,status='REJECTED',stage='QUEUE_FULL',error='Task engine has 12 admitted jobs; request was not executed.',started=started)
        _n66_send(cid,'Task '+tid+' rejected: queue full; this request was NOT executed. Wait for a task to finish or use /cancel66 all, then resend.')
        return None
    tid=None
    try:
        tid,started=_n66_task_new(cid,kind,request)
        ev=_n66_threading.Event()
        f=_n66_threading.Thread(target=_n66_worker,args=(cid,tid,started,kind,request,fn,args,kwargs,verified_when_result,True),daemon=True,name='nemo701-'+tid[-6:])
        with _N66_LOCK:
            _N66_CANCEL[tid]=ev
            _N66_FUT[tid]=f
        f.start()
        return tid
    except Exception:
        with _N66_LOCK:
            if tid is not None:
                _N66_FUT.pop(tid,None);_N66_CANCEL.pop(tid,None)
        _N701_ADMISSION.release()
        if tid is not None:_n66_task_update(tid,status='FAILED',stage='THREAD_START_FAILED',verified=0)
        raise


def _n66_tasks_text(cid,tid=''):
    try:
        c=_n35_conn()
        if tid:
            r=c.execute('SELECT id,created,updated,kind,request,status,stage,result,error,verified,cancel_requested,duration_ms FROM task66 WHERE id=? AND chat_id=?',(tid,str(cid))).fetchone();c.close()
            if not r:return 'Task not found.'
            return ('🧭 TASK '+r[0]+'\nKind: '+str(r[3])+'\nStatus: '+str(r[5])+' · Stage: '+str(r[6])+'\nVerified: '+('yes' if r[9] else 'no')+' · Cancel requested: '+('yes' if r[10] else 'no')+'\nDuration: '+str(r[11])+' ms\nRequest: '+str(r[4])[:900]+(('\nResult: '+str(r[7])[:1400]) if r[7] else '')+(('\nError: '+str(r[8])[:900]) if r[8] else ''))[:3900]
        rows=c.execute('SELECT id,kind,status,stage,request,duration_ms FROM task66 WHERE chat_id=? ORDER BY updated DESC LIMIT 12',(str(cid),)).fetchall();c.close()
    except Exception:rows=[]
    if not rows:return 'No v66 supervised tasks yet.'
    L=['🧭 NEMO TASK SUPERVISOR']
    for r in rows:L.append('%s · %s · %s/%s · %dms\n  %s'%(r[0],r[1],r[2],r[3],int(r[5] or 0),str(r[4])[:120]))
    return '\n'.join(L)[:3900]


def _n66_cancel(cid,arg=''):
    if cid!=OWNER.get('id'):return 'Owner only.'
    a=str(arg or '').strip();done=[]
    with _N66_LOCK:
        targets=list(_N66_FUT.keys()) if not a or a.lower()=='all' else [a]
        for tid in targets:
            ev=_N66_CANCEL.get(tid)
            if ev:
                ev.set();done.append(tid)
                _n66_task_update(tid,status='CANCEL_REQUESTED',stage='CANCEL_REQUESTED',cancel=1)
    return 'Cancellation requested for: '+(', '.join(done) if done else 'no active task matched')+'. Queued jobs stop before execution. Running legacy/network calls stop cooperatively when they return; already completed actions are not undone.'


