def _n66_classify(text):
    t=' '.join(str(text or '').split()).strip();low=t.lower()
    out={'kind':'LEGACY','confidence':.35,'reason':'legacy/general conversation fallback'}
    if not t or t.startswith('/'):return out
    if _N66_CAP_RE.search(t):return {'kind':'CAPABILITIES','confidence':1.0,'reason':'owner asked what Nemo can do'}
    if _N66_HEALTH_RE.search(t):return {'kind':'HEALTH','confidence':.98,'reason':'self-health/diagnostic request'}
    if _N66_TASK_RE.search(t):return {'kind':'TASKS','confidence':.97,'reason':'running-task status request'}
    if _N66_FILES_RE.search(t):return {'kind':'FILES','confidence':.96,'reason':'download/file workspace request'}
    try:
        d=_n57_parse_device(t)
        if d:return {'kind':'DEVICE','confidence':.99 if d.get('ok') else .94,'reason':'explicit enrolled-device action','detail':d}
    except Exception:pass
    try:
        mp=_n60_parse(t)
        if mp.get('order') or _N66_MEDIA_RE.search(t):return {'kind':'MEDIA','confidence':.99,'reason':'media download request'}
    except Exception:
        if _N66_MEDIA_RE.search(t):return {'kind':'MEDIA','confidence':.96,'reason':'media wording'}
    # Keep highly specialized MarketOS commands/queries on their mature legacy route, but directly answer broad current market explanations.
    if _N66_MARKET_NOW_RE.search(t) and not _n66_re.search(r'(?i)\b(?:option chain|greeks|gex|gamma|strike|vwap|volume profile|scanner|open interest|\boi\b)\b',t):
        return {'kind':'MARKET_CURRENT','confidence':.96,'reason':'current market explanation request'}
    try:
        f=_n56_classify(t)
        if f.get('kind')=='PUBLIC_RESEARCH':return {'kind':'RESEARCH','confidence':float(f.get('confidence') or .9),'reason':str(f.get('reason') or 'fresh public research')}
    except Exception:pass
    return out


