def _n67_market_direction(text):
    t=str(text or '').lower()
    if _n67_re.search(r'\b(?:down|fall(?:ing|en)?|declin(?:e|ing|ed)|drop(?:ped|ping)?|red|sell[- ]?off|crash(?:ing|ed)?)\b',t):return 'DOWN'
    if _n67_re.search(r'\b(?:up|rise|rising|rose|gain(?:ing|ed)?|green|rally(?:ing|ied)?)\b',t):return 'UP'
    return ''


def _n67_market_snapshot(text):
    sym=_n51_market_symbol(text);labels={'^NSEI':'Nifty 50','^BSESN':'Sensex','^NSEBANK':'Bank Nifty','^GSPC':'S&P 500','^IXIC':'Nasdaq'};label=labels.get(sym,sym)
    q=None;pct=None
    try:q=get_quote(sym)
    except Exception:q=None
    if q and q.get('price') is not None and q.get('prev'):
        try:pct=(float(q['price'])-float(q['prev']))/float(q['prev'])*100.0
        except Exception:pct=None
    try:clock=_n55_market_clock()
    except Exception:clock={}
    return sym,label,q,pct,clock


def _n67_market_task(cid,text):
    sym,label,q,pct,clock=_n67_market_snapshot(text);asked=_n67_market_direction(text);state=str(clock.get('state') or 'UNKNOWN');prefix=''
    if pct is not None:
        actual='UP' if pct>0.03 else ('DOWN' if pct<-0.03 else 'FLAT')
        if asked and actual not in (asked,'FLAT'):
            price=float(q.get('price')) if q and q.get('price') is not None else 0.0
            prefix=('PREMISE CHECK\nLatest available %s quote is %.2f (%+.2f%%), so it is %s — not %s in the latest quote.\nMarket session: %s.\n\n'
                    %(label,price,pct,actual.lower(),asked.lower(),state))
            # If the premise is wrong, answer that first and do not invent causes for a move that is not present.
            try:
                rows=web_search('%s India market latest today intraday pressure reasons'%label) or []
                brief='\n'.join('• '+str(r.get('title') or '')+' — '+str(r.get('body') or '')[:220] for r in rows[:4] if r.get('title'))
            except Exception:brief=''
            tail=('If you meant “why was it under pressure intraday?” or “why are global markets weak?”, say that and I will analyze that exact move.' if not brief else
                  'Current headlines that may explain broader/intraday pressure (not a claim that %s closed down):\n%s'%(label,brief))
            return {'text':prefix+tail,'ok':True,'verified':True,'evidence':'latest target quote + market session'+(' + current headlines' if brief else '')}
    # Premise is consistent/neutral: use the mature evidence path, but force session/premise discipline into the prompt.
    ctx='[NEMO67 CHECK: target=%s; latest_pct=%s; market_state=%s. Correct the owner explicitly if the request premise conflicts with these values. Distinguish latest-session close from intraday movement.]\n%s'%(label,('%.3f'%pct if pct is not None else 'unknown'),state,text)
    r=_n51_market_explain(cid,ctx)
    if isinstance(r,dict):
        return {'text':str(r.get('text') or 'No current market evidence returned.'),'ok':bool(r.get('ok')),'verified':bool(r.get('evidence')),'evidence':r.get('evidence','')}
    return {'text':str(r),'ok':bool(r),'verified':False}

