def _n68_conn():
    return _n35_conn()


def _n68_init():
    try:
        c=_n68_conn()
        c.execute('CREATE TABLE IF NOT EXISTS semantic68_cache(id TEXT PRIMARY KEY, chat_id TEXT, query TEXT, norm TEXT, pref_sig TEXT, answer TEXT, ts REAL, expires REAL, hits INTEGER DEFAULT 0, model TEXT, meta_json TEXT)')
        c.execute('CREATE INDEX IF NOT EXISTS idx_sem68_chat_exp ON semantic68_cache(chat_id,expires DESC)')
        c.execute('CREATE TABLE IF NOT EXISTS pref68(chat_id TEXT, key TEXT, value TEXT, updated REAL, PRIMARY KEY(chat_id,key))')
        c.execute('CREATE TABLE IF NOT EXISTS config68(key TEXT PRIMARY KEY, value TEXT, updated REAL)')
        c.execute('CREATE TABLE IF NOT EXISTS sub68(id TEXT PRIMARY KEY, chat_id TEXT, topic TEXT, target TEXT, enabled INTEGER, last_event_ts REAL DEFAULT 0, created REAL, updated REAL)')
        c.execute('CREATE INDEX IF NOT EXISTS idx_sub68_enabled ON sub68(enabled,topic)')
        # v58 EventBus table can be absent in a fresh/test DB; create the durable source table without re-registering old tool provenance.
        c.execute("CREATE TABLE IF NOT EXISTS event58(id TEXT PRIMARY KEY, ts REAL, kind TEXT, source TEXT, subject TEXT, payload_json TEXT DEFAULT '{}', severity TEXT DEFAULT 'INFO', consumed INTEGER DEFAULT 0)")
        c.execute('CREATE INDEX IF NOT EXISTS idx_event58_ts ON event58(ts DESC)')
        c.execute('CREATE INDEX IF NOT EXISTS idx_event58_kind ON event58(kind,ts DESC)')
        c.execute('CREATE TABLE IF NOT EXISTS audit68(seq INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, kind TEXT, actor TEXT, action TEXT, target TEXT, status TEXT, data_size INTEGER DEFAULT 0, detail TEXT, prev_hash TEXT, entry_hash TEXT UNIQUE)')
        c.execute('CREATE TABLE IF NOT EXISTS backup68(id TEXT PRIMARY KEY, ts REAL, mode TEXT, local_path TEXT, bytes INTEGER, sha256 TEXT, remote TEXT, remote_status TEXT, status TEXT, detail TEXT)')
        defaults={'cache_enabled':'1','cache_ttl':'3600','cache_similarity':'0.85','cache_max':'600','backup_remote':'','backup_daily':'0','backup_time':'03:30','backup_full':'0'}
        now=_n68_time.time()
        for k,v in defaults.items():c.execute('INSERT OR IGNORE INTO config68(key,value,updated) VALUES(?,?,?)',(k,v,now))
        c.commit();c.close();return True
    except Exception:
        _N68_STATS['errors']+=1;return False


def _n68_cfg(k,default=''):
    try:
        c=_n68_conn();r=c.execute('SELECT value FROM config68 WHERE key=?',(str(k),)).fetchone();c.close();return str(r[0]) if r else str(default)
    except Exception:return str(default)


