# ---------------------- UPGRADE 1: SEMANTIC PROMPT CACHE 2.0 -----------------
def _n68_norm(q):
    q=str(q or '').lower();q=_n68_re.sub(r'https?://\S+',' ',q);q=_n68_re.sub(r'[^a-z0-9\u0900-\u097f]+',' ',q)
    return ' '.join(q.split())[:1800]


def _n68_similarity(a,b):
    a=_n68_norm(a);b=_n68_norm(b)
    if not a or not b:return 0.0
    if a==b:return 1.0
    sa=set(a.split());sb=set(b.split());jac=len(sa&sb)/float(max(1,len(sa|sb)))
    # Remove conversational wrapper words so harmless rephrases match on the actual subject.
    stop={'explain','what','is','are','the','a','an','in','of','to','me','please','tell','about','simple','simply','words','word','define','meaning','how','does','work'}
    ca={x for x in sa if x not in stop};cb={x for x in sb if x not in stop};core=(len(ca&cb)/float(max(1,len(ca|cb)))) if (ca or cb) else jac
    seq=_n68_difflib.SequenceMatcher(None,a,b).ratio()
    return max(jac,seq,0.80*core+0.20*seq)


_N68_PREF_ALLOWED={'tone','depth','format','language','max_length','delivery'}
_N68_PREF_DEFAULT={'tone':'natural','depth':'adaptive','format':'systematic','language':'auto','max_length':'adaptive','delivery':'telegram'}

