def _n68_pref_sig(cid):
    p=_n68_prefs(cid);raw='|'.join('%s=%s'%(k,p.get(k,'')) for k in sorted(p))
    return _n68_hashlib.sha256(raw.encode('utf-8','ignore')).hexdigest()[:12]


