def _n68_cache_put(cid,q,ans,model=''):
    try:
        if not ans or len(str(ans).strip())<20:return False
        ttl=max(60,min(604800,int(float(_n68_cfg('cache_ttl','3600')))));now=_n68_time.time();cid_s=str(cid);pref=_n68_pref_sig(cid)
        key='C68-'+_n68_hashlib.sha256((cid_s+'\0'+pref+'\0'+_n68_norm(q)).encode('utf-8','ignore')).hexdigest()[:18].upper()
        c=_n68_conn();c.execute('INSERT OR REPLACE INTO semantic68_cache(id,chat_id,query,norm,pref_sig,answer,ts,expires,hits,model,meta_json) VALUES(?,?,?,?,?,?,?,?,?,?,?)',(key,cid_s,str(q)[:2200],_n68_norm(q),pref,str(ans)[:12000],now,now+ttl,0,str(model)[:240],_n68_json.dumps({'ttl':ttl})))
        lim=max(50,min(3000,int(float(_n68_cfg('cache_max','600')))));c.execute('DELETE FROM semantic68_cache WHERE id IN (SELECT id FROM semantic68_cache WHERE chat_id=? ORDER BY ts DESC LIMIT -1 OFFSET ?)',(cid_s,lim));c.commit();c.close();_N68_STATS['cache_put']+=1;return True
    except Exception:_N68_STATS['errors']+=1;return False


