# ------------------------ UPGRADE 5: AUDIT LEDGER 2.0 -------------------------
def _n68_audit(kind,actor,action,target,status,data_size=0,detail=''):
    try:
        c=_n68_conn();r=c.execute('SELECT entry_hash FROM audit68 ORDER BY seq DESC LIMIT 1').fetchone();prev=(r[0] if r else 'GENESIS')
        ts=_n68_time.time();payload='|'.join(map(str,[round(ts,6),kind,actor,action,target,status,int(data_size or 0),detail,prev]));h=_n68_hashlib.sha256(payload.encode('utf-8','ignore')).hexdigest()
        c.execute('INSERT INTO audit68(ts,kind,actor,action,target,status,data_size,detail,prev_hash,entry_hash) VALUES(?,?,?,?,?,?,?,?,?,?)',(ts,str(kind)[:60],str(actor)[:80],str(action)[:160],str(target)[:300],str(status)[:40],int(data_size or 0),str(detail)[:900],prev,h));c.commit();c.close();_N68_STATS['audit']+=1;return h
    except Exception:_N68_STATS['errors']+=1;return ''


def _n68_audit_verify():
    try:
        c=_n68_conn();rows=c.execute('SELECT seq,ts,kind,actor,action,target,status,data_size,detail,prev_hash,entry_hash FROM audit68 ORDER BY seq').fetchall();c.close();prev='GENESIS'
        for r in rows:
            payload='|'.join(map(str,[round(float(r[1]),6),r[2],r[3],r[4],r[5],r[6],int(r[7] or 0),r[8],prev]));h=_n68_hashlib.sha256(payload.encode('utf-8','ignore')).hexdigest()
            if r[9]!=prev or r[10]!=h:return False,'chain mismatch at seq '+str(r[0])
            prev=h
        return True,'%d entries verified'%len(rows)
    except Exception as e:return False,type(e).__name__+': '+str(e)[:200]


def _n68_audit_text(limit=20):
    ok,ver=_n68_audit_verify();L=['🛡 AUDIT LEDGER 68','Integrity: '+('PASS' if ok else 'FAIL')+' · '+ver,'Tamper-evident hash chain; not hardware/WORM immutability.','']
    try:
        c=_n68_conn();rows=c.execute('SELECT seq,kind,action,status,data_size FROM audit68 ORDER BY seq DESC LIMIT ?',(max(1,min(50,int(limit))),)).fetchall();c.close()
        for r in rows:L.append('#%s · %s · %s · %s · %s bytes'%(r[0],r[1],r[2],r[3],r[4] or 0))
    except Exception:pass
    return '\n'.join(L)[:3900]


# -------------------- UPGRADE 3: AGENT EVENT BUS PUB/SUB 2.0 -----------------
def _n68_topic_match(pattern,topic):
    p=str(pattern or '').strip();t=str(topic or '').strip()
    if p=='*':return True
    if p.endswith('.*'):return t==p[:-2] or t.startswith(p[:-1])
    return p==t


def _n68_subscribe(cid,topic,target='telegram'):
    topic=str(topic or '').strip().lower();target=str(target or 'telegram').strip()
    if not topic:return 'Topic required.'
    sid='SUB68-'+_n68_uuid.uuid4().hex[:10].upper();now=_n68_time.time()
    try:
        c=_n68_conn();c.execute('INSERT INTO sub68(id,chat_id,topic,target,enabled,last_event_ts,created,updated) VALUES(?,?,?,?,1,?,?,?)',(sid,str(cid),topic,target,now,now,now));c.commit();c.close();_n68_audit('eventbus','owner','subscribe',topic,'OK',0,'target='+target);return '✅ '+sid+' subscribed '+target+' to '+topic
    except Exception as e:return 'Subscribe failed: '+type(e).__name__


def _n68_register_handler(name,fn):
    if name and callable(fn):_N68_HANDLER_REGISTRY[str(name)]=fn;return True
    return False


def _n68_publish(topic,payload='',source='owner',severity='INFO'):
    topic=str(topic or '').strip().lower();payload=str(payload or '')[:6000]
    if not topic:return {'ok':False,'error':'topic required'}
    try:r=_n58_event_emit(topic,source,topic,{'text':payload},severity)
    except Exception as e:r={'ok':False,'error':type(e).__name__+': '+str(e)[:200]}
    if r.get('ok'):_N68_STATS['pub']+=1;_n68_audit('eventbus',source,'publish',topic,'OK',len(payload),severity)
    return r


def _n68_dispatch_events():
    try:
        c=_n68_conn();subs=c.execute('SELECT id,chat_id,topic,target,last_event_ts FROM sub68 WHERE enabled=1').fetchall()
        for sid,cid,pat,target,last in subs:
            events=c.execute('SELECT id,ts,kind,source,subject,payload_json,severity FROM event58 WHERE ts>? ORDER BY ts LIMIT 60',(float(last or 0),)).fetchall();new_last=float(last or 0)
            for e in events:
                new_last=max(new_last,float(e[1] or 0))
                if not _n68_topic_match(pat,e[2]):continue
                try:payload=_n68_json.loads(e[5] or '{}')
                except Exception:payload={}
                msg=str(payload.get('text') or e[4] or '');delivered=False
                if target=='telegram':
                    try:send_text(int(cid),'📡 '+str(e[2])+'\n'+msg[:3200]);delivered=True
                    except Exception:pass
                elif target.startswith('handler:'):
                    fn=_N68_HANDLER_REGISTRY.get(target.split(':',1)[1])
                    if callable(fn):
                        try:fn({'id':e[0],'ts':e[1],'topic':e[2],'source':e[3],'payload':payload,'severity':e[6]});delivered=True
                        except Exception:pass
                if delivered:_N68_STATS['deliver']+=1;_n68_audit('eventbus','nemo','deliver',str(e[2]),'OK',len(msg),'sub='+sid+' target='+target)
            c.execute('UPDATE sub68 SET last_event_ts=?,updated=? WHERE id=?',(new_last,_n68_time.time(),sid))
        c.commit();c.close()
    except Exception:_N68_STATS['errors']+=1


