def _n68_cache_cmd(cid,txt):
    if cid!=OWNER.get('id'):return 'Owner only.'
    a=txt.split(None,1)[1].strip().lower() if len(txt.split(None,1))>1 else 'stats'
    if a=='clear':
        c=None
        try:
            c=_n68_conn();c.execute('DELETE FROM semantic68_cache WHERE chat_id=?',(str(cid),));c.commit()
            return 'Old v68 cache entries cleared. Answer reuse remains disabled.'
        except Exception:return 'Cache clear failed.'
        finally:
            if c is not None:c.close()
    return _n68_cache_text(cid)


def _n68_pref_cmd(cid,txt):
    a=txt.split(None,1)[1].strip() if len(txt.split(None,1))>1 else 'show'
    if a.lower() in ('show','get','status'):return _n68_pref_text(cid)
    if a.lower().startswith('set '):
        p=a[4:].strip().split(None,1)
        if len(p)<2:return 'Usage: /pref68 set tone concise'
        return _n68_pref_set(cid,p[0],p[1])
    if a.lower().startswith('reset '):
        k=a[6:].strip().lower()
        try:c=_n68_conn();c.execute('DELETE FROM pref68 WHERE chat_id=? AND key=?',(str(cid),k));c.commit();c.close();return '✅ Reset '+k
        except Exception:return 'Reset failed.'
    return _n68_pref_text(cid)


def _n68_agent_cmd(cid,txt):
    a=txt.split(None,1)[1].strip() if len(txt.split(None,1))>1 else 'show';low=a.lower()
    if low in ('show','status','subs'):return _n68_agent_text(cid)
    if low.startswith('broadcast '):
        rest=a[len('broadcast '):].strip();p=rest.split(None,1)
        if len(p)<2:return 'Usage: /agent68 broadcast <topic> <payload>'
        r=_n68_publish(p[0],p[1],'owner','INFO');return ('✅ Event '+str(r.get('id'))) if r.get('ok') else ('❌ '+str(r.get('error')))
    if low.startswith('subscribe '):
        p=a[len('subscribe '):].strip().split(None,1);return _n68_subscribe(cid,p[0],p[1] if len(p)>1 else 'telegram')
    if low.startswith('off '):
        sid=a[4:].strip()
        try:c=_n68_conn();c.execute('UPDATE sub68 SET enabled=0,updated=? WHERE id=? AND chat_id=?',(_n68_time.time(),sid,str(cid)));c.commit();c.close();return '✅ '+sid+' disabled.'
        except Exception:return 'Subscription update failed.'
    return _n68_agent_text(cid)


def _n68_backup_cmd(cid,txt):
    a=txt.split(None,1)[1].strip() if len(txt.split(None,1))>1 else 'show';low=a.lower()
    if low in ('show','status','list'):return _n68_backup_text()
    if low.startswith('remote '):
        v=a[7:].strip()
        if not v:return 'Remote cannot be empty.'
        _n68_setcfg('backup_remote',v);_n68_audit('backup','owner','set remote','offsite','OK',0,'non-secret rclone destination');return '✅ Off-site destination saved. Use an rclone crypt remote for encrypted storage.'
    if low.startswith('daily '):
        p=a[6:].strip().split()
        if not p:return 'Usage: /backup68 daily 03:30 on'
        tm=p[0]
        if not _n68_re.match(r'^(?:[01]\d|2[0-3]):[0-5]\d$',tm):return 'Time must be HH:MM.'
        on=(len(p)<2 or p[1].lower() in ('on','enable','1','yes'));_n68_setcfg('backup_time',tm);_n68_setcfg('backup_daily','1' if on else '0');return '✅ Daily backup '+('ON' if on else 'OFF')+' @ '+tm
    if low.startswith('now'):
        mode='full' if 'full' in low else 'memory';r=_n68_snapshot(mode);return ('✅ '+r['id']+' · '+r['status']+' · %.1f MB\nLocal: %s\nSHA256: %s\nRemote: %s'%(r['bytes']/1048576.0,r['path'],r['sha256'][:20]+'…',r['remote_status']))[:3900]
    return _n68_backup_text()


_N68_HANDLE_PREV=handle
def handle(msg):
    try:
        cid=(msg.get('chat') or {}).get('id');chat=msg.get('chat') or {};txt=(msg.get('text') or msg.get('caption') or '').strip();low=txt.lower();owner=(cid==OWNER.get('id') and chat.get('type','private')=='private')
        if owner:
            if low in ('/nemo68','/performance68','/continuity68'):
                send_text(cid,'NEMO 68.0 — PERFORMANCE + PERSONALIZATION + CONTINUITY\nSemantic cache 2.0 · Preferences 3.0 · Agent Pub/Sub 2.0 · Off-site continuity · Tamper-evident audit\n\n/cache68 · /pref68 · /agent68 · /backup68 · /audit68');return
            if low.startswith('/cache68') or low.startswith('/cache '):send_text(cid,_n68_cache_cmd(cid,txt.replace('/cache ','/cache68 ',1)));return
            if low.startswith('/pref68') or low.startswith('/pref '):send_text(cid,_n68_pref_cmd(cid,txt.replace('/pref ','/pref68 ',1)));return
            if low.startswith('/agent68'):send_text(cid,_n68_agent_cmd(cid,txt));return
            if low.startswith('/backup68'):send_text(cid,_n68_backup_cmd(cid,txt));return
            if low.startswith('/audit68'):
                if 'verify' in low:
                    ok,d=_n68_audit_verify();send_text(cid,('✅ ' if ok else '❌ ')+d);return
                send_text(cid,_n68_audit_text());return
    except Exception as e:
        try:send_text((msg.get('chat') or {}).get('id'),'Nemo 68 layer error: '+type(e).__name__+': '+str(e)[:220]+'\nFalling back to v67.')
        except Exception:pass
    return _N68_HANDLE_PREV(msg)


