def _n69_hist(cid,t,action,target,file_id=''):
    hid='MU69-'+_n69_uuid.uuid4().hex[:10].upper();meta={'tags':t.get('tags',''),'score':t.get('score',0),'download_allowed':bool(t.get('download_allowed'))}
    try:
        c=_n69_conn();c.execute('INSERT INTO music69_history(id,chat_id,ts,provider,track_id,title,artist,mood,target,action,url,license,file_id,meta_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)',(hid,str(cid),_n69_time.time(),str(t.get('provider')),str(t.get('id')),str(t.get('title'))[:500],str(t.get('artist'))[:300],str(t.get('mood'))[:80],str(target)[:80],str(action),str(t.get('page_url') or t.get('stream_url') or '')[:1600],str(t.get('license') or '')[:800],str(file_id or ''),_n69_json.dumps(meta)));c.commit();c.close()
    except Exception:pass
    _N69_LAST[str(cid)]={'history_id':hid,'track':t,'target':target};return hid


def _n69_feedback(cid,rating,track_key=''):
    last=_N69_LAST.get(str(cid)) or {};t=last.get('track') or {}
    if not track_key:track_key=t.get('key') or (_n69_track_key(t) if t else '')
    if not track_key:return 'No recent music track to rate.'
    if not t:
        try:
            c=_n69_conn();r=c.execute('SELECT provider,title,artist,meta_json FROM music69_history WHERE chat_id=? ORDER BY ts DESC LIMIT 1',(str(cid),)).fetchone();c.close()
            if r:
                m=_n69_json.loads(r[3] or '{}');t={'provider':r[0],'title':r[1],'artist':r[2],'tags':m.get('tags','')}
        except Exception:pass
    rv={'like':1,'love':2,'dislike':-1,'skip':-1}.get(str(rating).lower(),0)
    try:
        c=_n69_conn();c.execute('INSERT OR REPLACE INTO music69_feedback(chat_id,track_key,provider,title,artist,tags,rating,ts) VALUES(?,?,?,?,?,?,?,?)',(str(cid),str(track_key),str(t.get('provider','')),str(t.get('title',''))[:500],str(t.get('artist',''))[:300],str(t.get('tags',''))[:1200],rv,_n69_time.time()));c.commit();c.close();_N69_STATS['feedback']+=1
        return '✅ Music preference learned: '+('more like this' if rv>0 else 'less like this')+'.'
    except Exception:return 'Could not save music feedback.'


def _n69_history_text(cid,limit=12):
    try:
        c=_n69_conn();rows=c.execute('SELECT id,provider,title,artist,target,action,file_id FROM music69_history WHERE chat_id=? ORDER BY ts DESC LIMIT ?',(str(cid),max(1,min(30,int(limit))))).fetchall();c.close()
    except Exception:rows=[]
    L=['🎵 MUSIC 69 HISTORY']
