    if low in ('show','status'):
        m=_n69_get_mood(cid);return 'Mood: '+(('none' if not m else '%s → %s · confidence %.0f%% · expires in %dm'%(m['mood'],m['target'],m['confidence']*100,max(0,int((m['expires']-_n69_time.time())/60)))))+'\nAuto music: '+('ON' if _n69_cfg('music69_auto','0')=='1' else 'OFF')
    if low in ('clear','reset'):_n69_clear_mood(cid);return '✅ Temporary mood state cleared.'
