def _n69_natural_music_goal(txt):
    t=' '.join(str(txt or '').lower().split())
    if _n69_re.search(r'\b(?:play|put on|start)\b.{0,35}\b(?:music|song|songs|bhajan|track)\b',t):
        if 'focus' in t or 'study' in t:return 'focus'
        if any(x in t for x in ('calm','relax','peace')):return 'calm'
        if any(x in t for x in ('motivat','energy','energi','workout')):return 'energize'
        if any(x in t for x in ('happy','cheer','uplift','feel better')):return 'uplift'
        if any(x in t for x in ('bhajan','bhakti','devotional','spiritual')):return 'spiritual'
        return 'discover'
    return ''


