    if '_n79_dispatch' in globals():
        try:
            if _n79_dispatch(msg):return
            if _n79_owner(msg) and _n79_feature(msg):return
        except Exception:
            try:send_text((msg.get('chat') or {}).get('id'),'Development/feature handler failed. No legacy action was attempted.')
            except Exception:pass
