def _n702_model_override_contract():
    """Behavioral v51 routing contract, tested through v69/68/54/51 wrappers.
    Clone functions into private globals and terminate at a fake provider. No
    production globals, network, credentials, DBs or request stats are mutated.
    This checks wrapper forwarding, not provider availability or model quality.
    """
    import types as _types
    calls=[]
    def sink(*args,**kwargs):
        calls.append((args,kwargs))
        return 'nemo-model-override-fixture'
    def forbidden(*args,**kwargs):
        raise AssertionError('Explicit model choice unexpectedly entered automatic ranking/cache')
    layers=[(globals().get('_N54_ASK_PREV'),'_N51_ASK_PREV'),
            (globals().get('_N68_ASK_PREV'),'_N54_ASK_PREV'),
            (globals().get('_N69_ASK_PREV'),'_N68_ASK_PREV'),
            (globals().get('ask_ai'),'_N69_ASK_PREV')]
    target=sink
    try:
        for fn,delegate in layers:
            if not isinstance(fn,_types.FunctionType):return False
            env=dict(fn.__globals__)
            env.update({'OWNER':{'id':1},delegate:target,
                        '_n69_get_mood':lambda cid:None,
                        '_n68_pref_ground':lambda cid:'',
                        '_n68_cache_eligible':lambda *a,**kw:False,
                        '_n68_cache_get':forbidden,'_n68_cache_put':forbidden,
                        '_N51_TLS':_types.SimpleNamespace(inside=False),
                        '_N51_STATS':{},'_N54_TLS':_types.SimpleNamespace(inside=False),
                        '_N54_STATS':{},'_n51_task_class':forbidden,
                        '_n51_base_candidates':forbidden,'_n51_rank_models':forbidden,
                        '_n54_human_contract':forbidden})
            clone=_types.FunctionType(fn.__code__,env,fn.__name__,fn.__defaults__,fn.__closure__)
            clone.__kwdefaults__=fn.__kwdefaults__
            target=clone
        for image in (None,'fixture-image-not-sent'):
            chosen=['fixture/explicit-model']
            result=target(1,'fixture question',image_b64=image,models_override=chosen,
                          remember=True,timeout=7,long_output=True,deep=True,ground='fixture data',raw=False)
            if result!='nemo-model-override-fixture':return False
            args,kwargs=calls[-1]
            if kwargs.get('models_override') is not chosen:return False
            if kwargs.get('image_b64')!=image or kwargs.get('timeout')!=7:return False
            if kwargs.get('ground')!='fixture data':return False
        return len(calls)==2
    except Exception:
        return False



def _n702_email_probe(google_token_ok):
    """Read-only readiness probe. Mailbox access does not establish send/delivery."""
    try:
        if google_ready():
            if not google_token_ok:
                return False,'Gmail not verified: Google token refresh failed','/google to re-authorize, then /doctor'
            profile=google_get('https://gmail.googleapis.com/gmail/v1/users/me/profile')
            if isinstance(profile,dict) and profile.get('emailAddress'):
                return True,'Gmail mailbox readable; sending/delivery not tested',''
            return False,'Gmail mailbox probe failed; sending untested','check Gmail permissions with /google'
        if BOT_EMAIL and BOT_EMAIL_PASS:
            return False,'SMTP credentials configured; connection/delivery untested','test email connection or link /google'
        return False,'no email path configured','/google or /email set'
    except Exception as e:
        return False,'Email probe failed: '+type(e).__name__,'/google then /doctor'


# NEMO 71 — bounded work plans using existing providers, persistence and delivery.
# This module's contents are integrated before the single active main() guard.
import threading as _n71_threading
_N71_TLS=_n71_threading.local()
_N71_LOCK=_n71_threading.RLock()
_N71_ALLOWED={'search','recall','calculate','draft','file'}
