def _n77_config():
    import os,json
    cfg={'batch_limit':5,'playlist_limit':3,'media_timeout':900,'youtube_client':'auto','browserless_enabled':False,'browserless_daily_calls':5}
    path=os.path.join(os.path.dirname(os.path.abspath(DATA_FILE)),'nemo_downloads.json')
    if os.path.exists(path):
        with open(path,encoding='utf-8') as f:extra=json.load(f)
        if not isinstance(extra,dict) or set(extra)-set(cfg):raise ValueError('Invalid nemo_downloads.json settings')
        cfg.update(extra)
    for key,lo,hi in [('batch_limit',1,10),('playlist_limit',1,10),('media_timeout',60,3600),('browserless_daily_calls',1,100)]:
        if type(cfg[key]) is not int or not lo<=cfg[key]<=hi:raise ValueError('Invalid download setting: '+key)
    if cfg['youtube_client'] not in ('auto','mweb'):raise ValueError('youtube_client must be auto or mweb')
    if type(cfg['browserless_enabled']) is not bool:raise ValueError('browserless_enabled must be true or false')
    return cfg


def _n77_check_cancel():
    if '_n78_check' in globals():_n78_check()
    if _n66_cancelled(getattr(_N71_TLS,'task_id','')):raise ValueError('Download cancelled')


def _n77_url(url):
    import urllib.parse,socket,ipaddress
    p=urllib.parse.urlsplit(url)
    if p.scheme!='https' or not p.hostname or p.username or p.password or p.port not in (None,443):raise ValueError('Use a public HTTPS URL without embedded credentials')
    ips=[a[4][0] for a in socket.getaddrinfo(p.hostname,443,type=socket.SOCK_STREAM)]
    if not ips or any(not ipaddress.ip_address(x).is_global for x in ips):raise ValueError('Private network addresses are not downloadable')
    return p


def _n77_host(host,base):return host==base or host.endswith('.'+base)


def _n77_parse(text):
    import re,urllib.parse
    t=str(text);low=t.lower()
    if re.search(r"\b(don't|do not|never|not|if|explain|how)\b",low):raise ValueError('Please give an explicit download request')
    if not re.search(r'\b(download|save|export|capture)\b',low):raise ValueError('Tell me to download, save, export or capture the link')
    urls=list(dict.fromkeys(x.rstrip('.,);]') for x in re.findall(r'https://[^\s<>]+',t)))
    if not urls:raise ValueError('Include at least one HTTPS link')
    cfg=_n77_config()
    if len(urls)>cfg['batch_limit']:raise ValueError('This request exceeds the configured batch limit of '+str(cfg['batch_limit']))
    mode='video'
    for word,value in [('audio','audio'),('mp3','mp3'),('subtitle','subtitles'),('subtitles','subtitles'),('thumbnail','thumbnail'),('screenshot','screenshot')]:
        if re.search(r'\b'+word+r'\b',low):mode=value
    if re.search(r'\b(?:as|to) (?:a )?pdf\b',low):mode='pdf'
    quality=next((str(h) for h in (2160,1080,720,480,360) if re.search(r'\b'+str(h)+r'p?\b',low)),'1080')
    return {'urls':urls,'mode':mode,'quality':quality,'playlist':bool(re.search(r'\bplaylist\b',low)),'cfg':cfg}


def _n77_error(raw):
    s=str(raw).lower()
    if any(x in s for x in ('drm protected','drm-protected','has drm')):return 'DRM-protected content is not supported.'
    if any(x in s for x in ('confirm you','botdetection','sign in','login required','cookies are no longer valid','authentication')):
        return 'The site requires a valid authorized browser session or rejected this server. Check download health and follow the YouTube setup guide; Google Drive login does not authenticate YouTube downloads.'
    if any(x in s for x in ('po token','po_token')):return 'YouTube requires a compatible PO-token provider. Check download health and the official yt-dlp PO Token Guide.'
    if any(x in s for x in ('javascript runtime','js runtime','n challenge','ejs')):return 'YouTube JavaScript support is missing or incompatible. Install a supported Deno runtime and update yt-dlp with its default dependencies.'
    if any(x in s for x in ('429','too many requests','rate limit')):return 'The site rate-limited this server. Pause requests and retry later.'
    if 'no module named yt_dlp' in s or 'ffmpeg not found' in s:return 'The bot Python media dependencies or ffmpeg are missing. Check download health and install them in the reported environment.'
    if 'unsupported url' in s:return 'This site or URL is not supported by the installed extractor. Supply its direct downloadable file link.'
    if any(x in s for x in ('private video','not available','unavailable','403','404','geo')):return 'This content is unavailable or access is restricted for this session/location.'
    if 'requested format' in s:return 'The requested format is unavailable. Try a lower resolution or audio only.'
    return 'The extractor did not produce a verified file. Check download health; the site may need updated extraction support.'


def _n77_cookie_status():
    import os,http.cookiejar,time
    path=str(globals().get('_N59_COOKIE') or '')
    if not path or not os.path.isfile(path):return 'missing',None
    if os.path.islink(path):return 'symlink rejected',None
    try:
        if os.path.getsize(path)>2*1024*1024:return 'oversized cookie file rejected',None
        jar=http.cookiejar.MozillaCookieJar(path);jar.load(ignore_discard=True,ignore_expires=True)
        yt=[c for c in jar if _n77_host(c.domain.lstrip('.'),'youtube.com')]
        valid=[c for c in yt if not c.is_expired()]
        if not valid:return 'no unexpired YouTube entries',None
        return str(len(valid))+' unexpired YouTube entries (not a live login test)',path
    except Exception:return 'invalid Netscape cookie file',None


def _n77_health():
    import shutil,subprocess,sys,os,importlib.metadata
    def version(package):
        try:return importlib.metadata.version(package)
        except Exception:return 'not found in bot Python'
    cookie,_=_n77_cookie_status();cfg=_n77_config()
    root=os.path.dirname(os.path.abspath(DATA_FILE));free=shutil.disk_usage(root).free/1024**3
    deno=globals().get('_n59_deno',lambda:shutil.which('deno'))()
    lines=['Nemo Download Manager 78','Python executable: '+sys.executable,'yt-dlp Python: '+version('yt-dlp'),'EJS package: '+version('yt-dlp-ejs'),
           'Deno: '+('found; version compatibility not tested' if deno else 'missing'),
           'ffmpeg: '+('found' if shutil.which('ffmpeg') else 'missing'),
           'YouTube cookies: '+cookie,'PO provider package: '+version('bgutil-ytdlp-pot-provider'),'YouTube client: '+cfg['youtube_client'],
           'Local disk free: %.1f GiB'%free,'Drive uploads: '+('account bound' if _n76_settings() else 'bind account first'),
           'Limits: 2 GiB/file; %s links/request; %s playlist entries'%(cfg['batch_limit'],cfg['playlist_limit']),
           'Browserless: '+('enabled; live access not tested' if cfg['browserless_enabled'] else 'disabled (optional paid webpage captures)'),
           'These are configuration checks, not proof that YouTube or any other site can be downloaded.']
    if '_n78_health' in globals():lines.extend(_n78_health())
    return '\n'.join(lines)


def _n77_command(url,folder,plan,cookies=None):
    import sys,os
    spec=plan.get('_n87') or {}
    playlist=plan['playlist']
    cmd=[sys.executable,'-m','yt_dlp','--ignore-config','--newline','--no-progress','--socket-timeout','20',
         '--retries','2','--fragment-retries','2','--concurrent-fragments','2','--restrict-filenames',
         '--max-filesize',str(_N76_MAX_FILE),'--max-downloads',str(plan['cfg']['playlist_limit'] if playlist else 1),
         '--no-overwrites','-o',os.path.join(folder,'%(title).100s_%(id)s.%(ext)s')]
    if playlist:cmd+=['--sleep-interval','3','--max-sleep-interval','8']        # pacing only matters between several downloads
    for runtime in _n87_js_runtimes():cmd+=['--js-runtimes',runtime]            # Deno and/or Node.js 20+: YouTube needs one of them
    if not _n87_has_ejs():cmd+=['--remote-components','ejs:github']             # no solver package installed: let yt-dlp fetch its own
    home=globals().get('_N59_PROVIDER_HOME','')
    if home and os.path.isdir(os.path.join(home,'server')):cmd+=['--extractor-args','youtubepot-bgutilscript:server_home='+os.path.join(home,'server')]
    client=spec.get('client') or ('mweb' if plan['cfg']['youtube_client']=='mweb' else '')
    if client:cmd+=['--extractor-args','youtube:player_client='+client]
    proxy=_n87_proxy()
    if proxy:cmd+=['--proxy',proxy]                                              # your own /proxy, as the earlier download engines used
    if cookies:cmd+=['--cookies',cookies]
    cmd+=['--yes-playlist','--playlist-end',str(plan['cfg']['playlist_limit'])] if playlist else ['--no-playlist']
    mode=plan['mode'];h=int(plan['quality'])
    if mode=='mp3':cmd+=['-f','bestaudio/best','-x','--audio-format','mp3','--audio-quality','2']
    elif mode=='audio':cmd+=['-f','bestaudio/best']
    elif mode=='subtitles':cmd+=['--skip-download','--write-subs','--write-auto-subs','--sub-langs','en.*,hi.*','--sub-format','vtt']
    elif mode=='thumbnail':cmd+=['--skip-download','--write-thumbnail']
    else:cmd+=['-f','bv*+ba/b','-S','res:%d,vcodec:h264,acodec:aac'%h,'--merge-output-format','mp4']   # best up to N p, H.264/AAC first, never "format not available"
    if '_n78_tune' in globals():cmd=_n78_tune(cmd,plan)
    return cmd+['--',url]


def _n77_media(url,plan):
    import os,shutil,tempfile
    p=_n77_url(url)
    if not plan.get('_browser_media') and not any(_n77_host(p.hostname,h) for h in _N77_MEDIA_HOSTS):raise ValueError('Use a direct file URL for this site; it is outside the supported media host list')
    root=os.path.join(os.path.dirname(os.path.abspath(DATA_FILE)),'nemo_download77')
    if os.path.islink(root):raise ValueError('Download directory cannot be a symlink')
    os.makedirs(root,mode=0o700,exist_ok=True)
    if not _N77_MEDIA_LOCK.acquire(blocking=False):raise ValueError('Another media download is active. Retry when it finishes')
    cookie_copy=''
    try:
        _n77_check_cancel()
        folder=_n78_folder(root,plan) if '_n78_folder' in globals() else tempfile.mkdtemp(prefix='media_',dir=root)
        youtube=any(_n77_host(p.hostname,h) for h in _N87_YT_HOSTS)
        cookie=None
        if youtube:
            _,source=_n77_cookie_status()
            if source:
                cookie_copy=os.path.join(folder,'session.cookies');shutil.copyfile(source,cookie_copy);os.chmod(cookie_copy,0o600);cookie=cookie_copy
        ctx={'url':url,'plan':plan,'folder':folder,'cookie':cookie,'youtube':youtube,'host':p.hostname,
             'deadline':_n87_time.monotonic()+float(plan['cfg']['media_timeout'])}
        return _n87_chain(ctx)
    finally:
        if cookie_copy and os.path.exists(cookie_copy):os.unlink(cookie_copy)
        _N77_MEDIA_LOCK.release()


def _n77_stream(response,name,maximum=None):
    import os,tempfile,re,time,shutil
    limit=min(maximum or _N76_MAX_FILE,_N76_MAX_FILE)
    root=os.path.join(os.path.dirname(os.path.abspath(DATA_FILE)),'nemo_download77')
    if os.path.islink(root):raise ValueError('Download directory cannot be a symlink')
    os.makedirs(root,mode=0o700,exist_ok=True)
    safe=re.sub(r'[^A-Za-z0-9_.-]','_',name)[:160].lstrip('.') or 'download.bin'
    temp='';size=0;start=time.monotonic()
    try:
        if response.status_code!=200:raise ValueError('Download service HTTP '+str(response.status_code))
        declared=response.headers.get('Content-Length')
        if declared and int(declared)>limit:raise ValueError('File exceeds the download size limit')
        fd,temp=tempfile.mkstemp(prefix='fetch_',suffix='_'+safe+'.part',dir=root)
        with os.fdopen(fd,'wb') as f:
            for block in response.iter_content(1024*1024):
                _n77_check_cancel()
                if time.monotonic()-start>300:raise ValueError('File transfer time limit reached')
                size+=len(block)
                if size>limit:raise ValueError('File exceeds the download size limit')
                if shutil.disk_usage(root).free<512*1024*1024:raise ValueError('Local disk reserve reached')
                f.write(block)
        if not size or declared and size!=int(declared):raise ValueError('Empty or incomplete download')
        dest=temp[:-5];os.replace(temp,dest);temp='';return dest
    finally:
        response.close()
        if temp and os.path.exists(temp):os.unlink(temp)


def _n77_google_file(url,mode):
    import re,urllib.parse,requests,os,hashlib
    p=urllib.parse.urlsplit(url)
    if p.hostname not in ('drive.google.com','docs.google.com'):raise ValueError('Expected a Google Drive or Docs link')
    match=re.search(r'/d/([A-Za-z0-9_-]+)',p.path)
    fid=match.group(1) if match else urllib.parse.parse_qs(p.query).get('id',[''])[0]
    if not re.fullmatch(r'[A-Za-z0-9_-]{8,200}',fid):raise ValueError('Use an individual Drive file or Google document link; folder imports are not enabled')
    meta=_n76_call('GET','files/'+fid,params={'fields':'id,name,mimeType,size,md5Checksum,capabilities(canDownload)'})
    if meta.get('capabilities',{}).get('canDownload') is not True:raise ValueError('The connected Google account does not have download permission')
    mime=meta.get('mimeType','');name=meta.get('name','download');endpoint='https://www.googleapis.com/drive/v3/files/'+fid;params={'alt':'media'};limit=_N76_MAX_FILE
    exports={'application/vnd.google-apps.document':('application/pdf','.pdf'),
             'application/vnd.google-apps.spreadsheet':('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','.xlsx'),
             'application/vnd.google-apps.presentation':('application/pdf','.pdf')}
    if mime.startswith('application/vnd.google-apps.'):
        if mime not in exports:raise ValueError('This Google file type is not supported for export')
        typ,ext=('application/pdf','.pdf') if mode=='pdf' else exports[mime]
        endpoint+='/export';params={'mimeType':typ};name+=ext;limit=10*1024*1024
    elif int(meta.get('size',0))>limit:raise ValueError('Drive source exceeds the 2 GiB limit')
    r=requests.get(endpoint,params=params,headers={'Authorization':'Bearer '+google_token()},stream=True,timeout=(10,45),allow_redirects=False)
    path=_n77_stream(r,name,limit)
    if not mime.startswith('application/vnd.google-apps.'):
        size=os.path.getsize(path)
        if str(size)!=str(meta.get('size')):raise ValueError('Drive source size verification failed')
        if meta.get('md5Checksum'):
            md=hashlib.md5()
            with open(path,'rb') as f:
                for block in iter(lambda:f.read(1024*1024),b''):md.update(block)
            if md.hexdigest()!=meta['md5Checksum']:raise ValueError('Drive source checksum verification failed')
    return path


def _n77_paid_reserve(cap,request_key):
    import datetime
    day=datetime.datetime.now(datetime.timezone.utc).date().isoformat();c=_n35_conn()
    try:
        c.execute('CREATE TABLE IF NOT EXISTS download77_paid(day TEXT PRIMARY KEY,calls INTEGER NOT NULL)')
        c.execute('CREATE TABLE IF NOT EXISTS download77_capture(request_key TEXT PRIMARY KEY,state TEXT,path TEXT)');c.commit();c.execute('BEGIN IMMEDIATE')
        old=c.execute('SELECT state,path FROM download77_capture WHERE request_key=?',(request_key,)).fetchone()
        if old:
            c.rollback()
            if old[0]=='COMPLETE' and __import__('os').path.isfile(old[1]):return old[1]
            raise ValueError('This paid capture was already attempted; its outcome is unconfirmed. Send a new request only if you want another potentially billable attempt')
        row=c.execute('SELECT calls FROM download77_paid WHERE day=?',(day,)).fetchone()
        count=row[0] if row else 0
        if count>=cap:raise ValueError('Daily Browserless call limit reached')
        c.execute('INSERT OR REPLACE INTO download77_paid VALUES(?,?)',(day,count+1))
        c.execute('INSERT INTO download77_capture VALUES(?,?,?)',(request_key,'STARTED',''));c.commit();return ''
    except Exception:c.rollback();raise
    finally:c.close()


def _n77_capture(url,mode,cfg,request_key):
    import requests,os
    _n77_url(url)
    if mode not in ('pdf','screenshot'):raise ValueError('Unsupported capture format')
    key=str(_n60_secret('browserless_key','') or '')
    if not cfg['browserless_enabled'] or not key:raise ValueError('Optional Browserless capture is not configured. Enable it with a service key and a daily call limit; ordinary file/video downloads do not need it')
    _n77_check_cancel();previous=_n77_paid_reserve(cfg['browserless_daily_calls'],request_key)
    if previous:return previous
    endpoint='pdf' if mode=='pdf' else 'screenshot';ext='.pdf' if mode=='pdf' else '.png'
    options={'format':'A4','printBackground':True} if mode=='pdf' else {'type':'png','fullPage':True}
    # Fixed API operations; no model-generated code or session cookies sent to the vendor.
    r=requests.post('https://production-sfo.browserless.io/'+endpoint,params={'token':key},json={'url':url,'options':options,'gotoOptions':{'waitUntil':'networkidle2','timeout':30000}},stream=True,timeout=(10,90),allow_redirects=False)
    path=_n77_stream(r,'webpage'+ext,50*1024*1024)
    with open(path,'rb') as f:magic=f.read(8)
    if not (magic.startswith(b'%PDF-') if mode=='pdf' else magic==b'\x89PNG\r\n\x1a\n'):raise ValueError('Capture service did not return the expected file type')
    c=_n35_conn()
    try:c.execute("UPDATE download77_capture SET state='COMPLETE',path=? WHERE request_key=?",(path,request_key));c.commit()
    finally:c.close()
    return path


def _n77_task(msg):
    import urllib.parse,os
    cid=(msg.get('chat') or {}).get('id');text=msg.get('text','')
    if cid!=OWNER.get('id') or msg['chat'].get('type','private')!='private':return {'ok':False,'text':'Owner private chat only.'}
    try:
        low=text.lower().strip(' .!?')
        if low in ('check download health','check my downloader','download health'):return {'ok':True,'text':_n77_health()}
        if low in ('show my downloads','show downloaded files'):return {'ok':True,'text':_n64_files_text(20)}
        plan=_n77_parse(text)
        if not _n76_settings():raise ValueError('Bind the intended Drive account first: Check my Drive, then Use <email> for downloads')
        binding=_n76_settings();user=_n76_profile()['user']
        if binding['id']!=user['permissionId'] or binding['email'].lower()!=user['emailAddress'].lower():raise ValueError('Connected Google account changed; rebind the intended account first')
        results=[];failures=0
        for i,url in enumerate(plan['urls'],1):
            _n77_check_cancel();send_text(cid,'Download '+str(i)+'/'+str(len(plan['urls']))+' started. Format: '+plan['mode']+('. Playlist scope: first '+str(plan['cfg']['playlist_limit'])+' entries only.' if plan['playlist'] else '.'))
            try:
                p=_n77_url(url);warning=''
                if p.hostname in ('drive.google.com','docs.google.com'):files=[_n77_google_file(url,plan['mode'])]
                elif plan['mode'] in ('pdf','screenshot'):files=[_n77_capture(url,plan['mode'],plan['cfg'],__import__('hashlib').sha256((str(cid)+'|'+str(msg.get('message_id') or getattr(_N71_TLS,'task_id','unknown'))+'|'+url+'|'+plan['mode']).encode()).hexdigest())]
                elif any(_n77_host(p.hostname,h) for h in _N77_MEDIA_HOSTS):files,warning=_n77_media(url,plan)
                else:
                    if p.hostname in ('dropbox.com','www.dropbox.com'):
                        query=urllib.parse.parse_qsl(p.query,keep_blank_values=True);query=[(k,v) for k,v in query if k not in ('dl','raw')]+[('dl','1')]
                        url=urllib.parse.urlunsplit((p.scheme,p.netloc,p.path,urllib.parse.urlencode(query),''))
                    direct_ext=os.path.splitext(p.path)[1].lower()
                    acceptable={'audio':('.mp3','.m4a','.wav','.flac','.ogg','.opus','.aac'),'mp3':('.mp3',),'subtitles':('.srt','.vtt',),'thumbnail':('.jpg','.jpeg','.png','.webp')}
                    if plan['mode']!='video' and direct_ext not in acceptable.get(plan['mode'],()):raise ValueError('Conversion or extraction requires a supported media-site link; for an existing file, send its direct file URL')
                    files=[_n76_direct_download(url)]
                for path in files:
                    _n77_check_cancel();fid=_n64_register_file(path,'','file','https77','')
                    ok=_n76_archive(cid,path)
                    if not ok:
                        failures+=1;results.append('File retained: '+(fid or os.path.basename(path))+('. Say: Retry '+fid+' to Drive' if fid else ''))
                if warning:failures+=1;results.append(warning)
            except Exception as e:
                failures+=1;results.append('Item '+str(i)+': '+(str(e)[:450] if isinstance(e,ValueError) else type(e).__name__+'; operation not confirmed'))
        return {'ok':not failures,'text':'Download batch '+('finished with issues' if failures else 'completed; verified Drive links sent')+('.\n'+'\n'.join(results) if results else '.'),'verified':not failures}
    except Exception as e:return {'ok':False,'text':'Download stopped: '+(str(e)[:450] if isinstance(e,ValueError) else type(e).__name__)}


def _n77_dispatch(msg):
    import re
    if '_n78_dispatch' in globals() and _n78_dispatch(msg):return True
    text=msg.get('text','');low=text.lower().strip(' .!?');chat=msg.get('chat') or {}
    if chat.get('id')!=OWNER.get('id') or chat.get('type','private')!='private':return False
    special=low in ('check download health','check my downloader','download health','show my downloads','show downloaded files')
    if not special:
        if not re.search(r'\b(download|save|export|capture)\b',low) or 'https://' not in text:return False
        if re.search(r"\b(don't|do not|never|not|if|explain|how)\b",low):return False
    tid=_n66_submit(chat['id'],'DOWNLOAD77',text,_n77_task,dict(msg))
    if not tid:send_text(chat['id'],'Download queue is full; retry after an active task finishes.')
    return True


# Official read-only YouTube Data API integration. Independent of media extraction.
def _n771_reserve(search=False):
    import datetime
    day=datetime.datetime.now(datetime.timezone.utc).date().isoformat();kind='search' if search else 'read';cap=50 if search else 200
    c=_n35_conn()
    try:
        c.execute('CREATE TABLE IF NOT EXISTS youtube771_usage(day TEXT,kind TEXT,calls INTEGER,PRIMARY KEY(day,kind))');c.commit();c.execute('BEGIN IMMEDIATE')
        row=c.execute('SELECT calls FROM youtube771_usage WHERE day=? AND kind=?',(day,kind)).fetchone();count=row[0] if row else 0
        if count>=cap:raise ValueError('Nemo daily YouTube '+kind+' request limit reached; resets at 00:00 UTC')
        c.execute('INSERT OR REPLACE INTO youtube771_usage VALUES(?,?,?)',(day,kind,count+1));c.commit()
    except Exception:c.rollback();raise
    finally:c.close()


def _n771_error(status,payload):
    error=payload.get('error') or {};reasons=[]
    for item in (error.get('errors') or [])+(error.get('details') or []):
        if isinstance(item,dict):reasons.append(item.get('reason',''))
    values=set(reasons)
    if values & {'quotaExceeded','dailyLimitExceeded','rateLimitExceeded','RATE_LIMIT_EXCEEDED'}:return 'Google YouTube quota/rate limit reached. Check this project’s quotas and retry after the applicable reset.'
    if values & {'API_KEY_IP_ADDRESS_BLOCKED','ipRefererBlocked'}:return 'API key IP restriction rejected this server. Check the VPS public outbound IP, including IPv6 if used.'
    if values & {'accessNotConfigured','SERVICE_DISABLED'}:return 'Enable YouTube Data API v3 in the project that owns this key.'
    if values & {'keyInvalid','API_KEY_INVALID'}:return 'Google rejected the API key. Replace only youtube_api_key using the setup helper.'
    if status==403:return 'Google denied this request. Check the enabled API, key API/IP restrictions and quota; no raw credential-bearing error was displayed.'
    if status==404:return 'YouTube resource not found or not accessible through this public API key.'
    return 'YouTube API HTTP '+str(status)+'. Request not completed.'


def _n771_api(endpoint,params):
    import requests,json
    if endpoint not in ('search','videos','playlistItems'):raise ValueError('Unsupported YouTube API operation')
    if any(k in params for k in ('key','access_token','oauth_token')):raise ValueError('Credentials cannot be supplied as tool arguments')
    key=str(_n60_secret('youtube_api_key','') or '').strip()
    if not key:raise ValueError('YouTube API key not configured. Say: Set up YouTube API in your private Nemo chat, then reply to its setup prompt.')
    _n77_check_cancel();_n771_reserve(endpoint=='search')
    try:
        r=requests.get('https://www.googleapis.com/youtube/v3/'+endpoint,params=dict(params,key=key),timeout=(10,25),allow_redirects=False,stream=True)
        try:
            raw=bytearray()
            for block in r.iter_content(65536):
                _n77_check_cancel();raw.extend(block)
                if len(raw)>1024*1024:raise ValueError('YouTube API response exceeded the size limit')
            try:j=json.loads(raw)
            except Exception:raise ValueError('YouTube returned an unreadable response') from None
            if not isinstance(j,dict):raise ValueError('Invalid YouTube API response')
            if r.status_code!=200:raise ValueError(_n771_error(r.status_code,j))
            if not isinstance(j.get('items'),list):raise ValueError('YouTube response missing its items list')
            return j
        finally:r.close()
    except requests.RequestException:raise ValueError('YouTube API network request failed. No connection success or download is claimed.') from None


def _n771_id(url,playlist=False):
    import re,urllib.parse
    p=urllib.parse.urlsplit(url.strip().rstrip('.,);]'))
    if p.scheme!='https' or p.username or p.password or p.port not in (None,443):raise ValueError('Use a YouTube HTTPS link')
    if p.hostname not in ('youtube.com','www.youtube.com','m.youtube.com','music.youtube.com','youtu.be'):raise ValueError('Expected a YouTube link')
    q=urllib.parse.parse_qs(p.query)
    if playlist:ident=q.get('list',[''])[0];pattern=r'[A-Za-z0-9_-]{10,200}'
    else:
        parts=p.path.strip('/').split('/')
        ident=parts[0] if p.hostname=='youtu.be' else parts[1] if len(parts)==2 and parts[0] in ('shorts','live','embed') else q.get('v',[''])[0]
        pattern=r'[A-Za-z0-9_-]{11}'
    if not re.fullmatch(pattern,ident):raise ValueError('The link does not contain a valid '+('playlist' if playlist else 'video')+' ID')
    return ident


def _n771_title(value):
    import html,re
    return re.sub(r'[\x00-\x1f\x7f]',' ',html.unescape(str(value)))[:180]


def _n771_task(msg):
    import re
    chat=msg.get('chat') or {};text=msg.get('text','').strip();low=text.lower().strip(' .!?')
    if chat.get('id')!=OWNER.get('id') or chat.get('type','private')!='private':return {'ok':False,'text':'Owner private chat only.'}
    try:
        if low in ('check youtube api','test youtube api','test youtube connection'):
            _n771_api('videos',{'part':'snippet','chart':'mostPopular','regionCode':'IN','maxResults':1})
            return {'ok':True,'verified':True,'text':'YouTube Data API: PASS — Google accepted one read request from this server. Search/metadata access only; YouTube login, media download and Drive upload were not tested.'}
        m=re.fullmatch(r'(?:search youtube for|find youtube videos about)\s+(.+)',text,re.I|re.S)
        if m:
            query=m.group(1).strip()
            if not 1<=len(query)<=300:raise ValueError('Use a search query between 1 and 300 characters')
            j=_n771_api('search',{'part':'snippet','q':query,'type':'video','maxResults':5,'regionCode':'IN'})
            rows=[]
            for item in j['items'][:5]:
                ident=(item.get('id') or {}).get('videoId','');snippet=item.get('snippet') or {}
                if re.fullmatch(r'[A-Za-z0-9_-]{11}',ident):rows.append(_n771_title(snippet.get('title','Untitled'))+'\n'+_n771_title(snippet.get('channelTitle',''))+'\nhttps://www.youtube.com/watch?v='+ident)
            return {'ok':True,'text':'YouTube search · up to 5 results · India region\n\n'+('\n\n'.join(rows) if rows else 'No accessible video results returned.')+'\n\nSource: YouTube Data API. No video was downloaded or watched.'}
        m=re.fullmatch(r'(?:show youtube video details|youtube video details|list youtube playlist)\s+(https://\S+)',text,re.I)
        if not m:raise ValueError('Say: Search YouTube for <topic>, Show YouTube video details <link>, or List YouTube playlist <link>')
        playlist=low.startswith('list youtube playlist');ident=_n771_id(m.group(1),playlist)
        if playlist:
            j=_n771_api('playlistItems',{'part':'snippet','playlistId':ident,'maxResults':20});rows=[]
            for item in j['items'][:20]:
                s=item.get('snippet') or {};vid=(s.get('resourceId') or {}).get('videoId','')
                title=_n771_title(s.get('title','Unavailable item'))
                rows.append(title+('\nhttps://www.youtube.com/watch?v='+vid if re.fullmatch(r'[A-Za-z0-9_-]{11}',vid) else ''))
            return {'ok':True,'text':('YouTube playlist · first page, up to 20 entries\n'+'\n\n'.join(rows)+'\n'+('More entries exist; this is not the complete playlist.' if j.get('nextPageToken') else 'End of returned playlist page.')+'\nSource: YouTube Data API. Nothing downloaded.')[:3900]}
        j=_n771_api('videos',{'part':'snippet,contentDetails,statistics,status','id':ident})
        if not j['items']:raise ValueError('Video not returned by the public API. It may be private, removed or unavailable; the API key cannot establish which.')
        v=j['items'][0];s=v.get('snippet') or {};d=v.get('contentDetails') or {};stats=v.get('statistics') or {}
        lines=['YouTube video details',_n771_title(s.get('title','Untitled')),'Channel: '+_n771_title(s.get('channelTitle','')),
               'Published: '+str(s.get('publishedAt','unknown')),'Duration (ISO 8601): '+str(d.get('duration','unknown')),
               'Views reported: '+str(stats.get('viewCount','not provided')),'https://www.youtube.com/watch?v='+ident,
               'Source: YouTube Data API metadata. This does not prove playback/download availability; no video was watched or downloaded.']
        return {'ok':True,'text':'\n'.join(lines)}
    except Exception as e:return {'ok':False,'text':'YouTube API: '+(str(e)[:500] if isinstance(e,ValueError) else 'Request failed; no success claimed.')}


def _n771_dispatch(msg):
    import re
    chat=msg.get('chat') or {};text=msg.get('text','').strip();low=text.lower().strip(' .!?')
    if chat.get('id')!=OWNER.get('id') or chat.get('type','private')!='private':return False
    if low not in ('check youtube api','test youtube api','test youtube connection') and not re.match(r'^(search youtube for|find youtube videos about|show youtube video details|youtube video details|list youtube playlist)\s+',text,re.I):return False
    tid=_n66_submit(chat['id'],'YOUTUBE771',text,_n771_task,dict(msg))
    if not tid:send_text(chat['id'],'Task queue is full; retry the YouTube request after an active task finishes.')
    return True

# END YOUTUBE API 771

# Direct owner-only key setup; intercept before task queues, AI and legacy memory.
import threading as _n772_threading
import time as _n772_time
_N772_LOCK = _n772_threading.RLock()
_N772_PENDING = {}
_N772_BUSY = set()


def _n772_save_key(key, path='/root/bot_secrets.json'):
    import json, os, re, tempfile, fcntl
    from pathlib import Path
    path = Path(path)
    if not re.fullmatch(r'AIza[A-Za-z0-9_-]{35}', key):
        raise ValueError('Unexpected key format')
    if path.is_symlink() or not path.is_file():
        raise ValueError('Existing regular secrets file required')
    fd = os.open(str(path)+'.youtube-setup.lock', os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW, 0o600)
    with os.fdopen(fd, 'w') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        if path.is_symlink():
            raise ValueError('Secrets file cannot be a symlink')
        before = path.read_bytes(); info = path.stat(); data = json.loads(before)
        if not isinstance(data, dict):
            raise ValueError('Secrets file must be an object')
        data['youtube_api_key'] = key
        backup_fd, backup = tempfile.mkstemp(prefix=path.name+'.youtube-backup-', dir=path.parent)
        with os.fdopen(backup_fd, 'wb') as f:
            f.write(before); f.flush(); os.fsync(f.fileno())
        tmp_fd, tmp = tempfile.mkstemp(prefix='.youtube-key-', dir=path.parent)
        try:
            with os.fdopen(tmp_fd, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2); f.write('\n'); f.flush(); os.fsync(f.fileno())
                if os.geteuid() == 0:
                    os.fchown(f.fileno(), info.st_uid, info.st_gid)
            if path.is_symlink() or path.read_bytes() != before:
                raise ValueError('Secrets changed during setup')
            os.replace(tmp, path)
        finally:
            if os.path.exists(tmp):
                os.unlink(tmp)
        return backup


def _n772_probe(key):
    import requests, json
    try:
        _n771_reserve(False)
        response = requests.get('https://www.googleapis.com/youtube/v3/videos',
            params={'key':key, 'part':'id', 'chart':'mostPopular', 'regionCode':'IN', 'maxResults':1},
            timeout=(10,25), allow_redirects=False, stream=True)
        try:
            body = bytearray()
            for block in response.iter_content(16384):
                body.extend(block)
                if len(body) > 262144:
                    return False, 'Google response exceeded the size limit.'
            payload = json.loads(body)
            if not isinstance(payload, dict):
                return False, 'Google returned an invalid response.'
            if response.status_code != 200:
                return False, _n771_error(response.status_code, payload)
            if not isinstance(payload.get('items'), list):
                return False, 'Google response was incomplete.'
            return True, 'YouTube API read test passed.'
        finally:
            response.close()
    except Exception:
        # Never stringify request exceptions: they can contain the key in the URL.
        return False, 'YouTube validation could not finish. Check connectivity and the daily API request limit.'


def _n772_say(cid, text):
    return tg('sendMessage', chat_id=cid, text=text, protect_content=True)


def _n772_shadowed():
    import os
    return bool(os.environ.get('YOUTUBE_API_KEY') or os.environ.get('NEMO_YOUTUBE_API_KEY'))


def _n772_key_setup(msg):
    import json, re
    chat = msg.get('chat') or {}; sender = msg.get('from') or {}
    cid = chat.get('id'); mid = msg.get('message_id')
    txt = str(msg.get('text') or msg.get('caption') or '').strip()
    low = txt.lower().rstrip('.!')
    start = low in ('set up youtube api', 'setup youtube api', 'connect youtube api',
                    'change youtube api key', 'set up youtube key')
    cancel = low == 'cancel youtube setup'
    owner = (cid == OWNER.get('id') and sender.get('id') == OWNER.get('id')
             and chat.get('type') == 'private' and not sender.get('is_bot'))
    forwarded = any(msg.get(k) for k in ('forward_origin','forward_date','forward_from','forward_from_chat'))
    reply_id = (msg.get('reply_to_message') or {}).get('message_id')
    suspicious = bool(re.search(r'AIza[A-Za-z0-9_-]{20,}', json.dumps(msg, ensure_ascii=False)))
    # Ordinary chat must not wait behind Telegram network calls in setup.
    peek = _N772_PENDING.get(cid) if owner else None
    if not (start or cancel or suspicious or (peek and reply_id == peek['prompt'])):
        return False
    with _N772_LOCK:
        pending = _N772_PENDING.get(cid) if owner else None
        reply = bool(pending and reply_id == pending['prompt'])
        if not (start or cancel or suspicious or reply):
            return False
        if reply:
            _N772_PENDING.pop(cid, None)
        # Remove credential-bearing input from the shared update object before I/O.
        if suspicious or reply:
            msg.clear()
            msg.update({'chat':{'id':cid,'type':chat.get('type')},
                        'from':{'id':sender.get('id')}, 'message_id':mid,
                        'text':'[YouTube credential input handled]'})
        if owner and cancel and not suspicious:
            _N772_PENDING.pop(cid, None)
            _n772_say(cid, 'YouTube setup cancelled. Saved keys are unchanged.'); return True
        if owner and start and not forwarded and not suspicious:
            if cid in _N772_BUSY:
                _n772_say(cid, 'YouTube key validation is already running.'); return True
            if _n772_shadowed():
                _n772_say(cid, 'An environment variable overrides the YouTube key. Remove that override on the server before using chat setup. No keys changed.'); return True
            _N772_PENDING.pop(cid, None)
            sent = tg('sendMessage', chat_id=cid, protect_content=True,
                text='Reply to THIS message with only your YouTube API key within 5 minutes. '
                     'The key passes through Telegram; bot chats are not end-to-end encrypted. '
                     'I will make one Google API read test, save only if it passes, and try to delete your key message. '
                     'Say Cancel YouTube setup to stop.',
                reply_markup={'force_reply':True, 'selective':True, 'input_field_placeholder':'YouTube API key only'})
            prompt = (sent.get('result') or {}).get('message_id') if isinstance(sent,dict) else None
            if sent and sent.get('ok') and type(prompt) is int:
                _N772_PENDING[cid] = {'prompt':prompt, 'expires':_n772_time.monotonic()+300}
            return True
        deleted = False
        if (suspicious or reply) and type(mid) is int:
            try:
                deleted = bool(tg('deleteMessage', chat_id=cid, message_id=mid).get('ok'))
            except Exception:
                pass
        if not owner:
            return True
        suffix = '' if deleted else ' Message deletion was not confirmed; delete the key message yourself.'
        if forwarded or not reply or type(mid) is not int or mid <= pending['prompt']:
            _n772_say(cid, 'Key not saved. Say Set up YouTube API, then reply directly to the new prompt with the key.'+suffix); return True
        if _n772_time.monotonic() > pending['expires']:
            _n772_say(cid, 'Setup expired. Key not saved. Say Set up YouTube API again.'+suffix); return True
        if not re.fullmatch(r'AIza[A-Za-z0-9_-]{35}', txt):
            _n772_say(cid, 'Expected only a Google API key. Nothing saved. Say Set up YouTube API to retry.'+suffix); return True
        if cid in _N772_BUSY or _n772_shadowed():
            _n772_say(cid, 'Setup blocked by another validation or a server environment override. No keys changed.'+suffix); return True
        _N772_BUSY.add(cid)
    try:
        ok, detail = _n772_probe(txt)
        if not ok:
            _n772_say(cid, 'Key NOT saved; existing keys are unchanged. '+detail+' Say Set up YouTube API to retry.'+suffix)
            return True
        try:
            _n772_save_key(txt)
        except Exception:
            _n772_say(cid, 'Validation passed, but saving failed. No success is claimed; check the existing secrets file and its permissions.'+suffix)
            return True
        _n772_say(cid, 'YouTube API connected and key saved. Other credentials preserved; private backup created. '
            'Try: Search YouTube for Python tutorials. Video downloading is a separate connection.'+suffix)
        return True
    finally:
        with _N772_LOCK:
            _N772_BUSY.discard(cid)


# Nemo 78: persistent owner-scoped download jobs. No new API keys.
import threading as _n78_threading
_N78_LOCK = _n78_threading.RLock()
_N78_TLS = _n78_threading.local()
_N78_THREAD = None
_N78_WAKE = _n78_threading.Event()
_N78_PROCESS_LOCK = None


def _n78_db():
    c = _n35_conn()
    c.execute('PRAGMA busy_timeout=10000')
    c.execute('CREATE TABLE IF NOT EXISTS download78_jobs(id TEXT PRIMARY KEY,owner INTEGER,request TEXT UNIQUE,payload TEXT,state TEXT,stage TEXT,progress TEXT,files TEXT,links TEXT,attempts INTEGER,cancel INTEGER,created REAL,updated REAL,receipt INTEGER,error TEXT)')
    c.execute('CREATE TABLE IF NOT EXISTS download78_events(job TEXT,stage TEXT,at REAL)')
    c.execute('CREATE TABLE IF NOT EXISTS download78_preferences(owner INTEGER PRIMARY KEY,quality TEXT,browser INTEGER)')
    c.commit()
    return c


def _n78_rows(owner, job=None):
    import sqlite3
    c = _n78_db(); c.row_factory = sqlite3.Row
    try:
        rows = c.execute('SELECT * FROM download78_jobs WHERE owner=?'+(' AND id=?' if job else '')+' ORDER BY created DESC,id DESC LIMIT 30', (owner,job) if job else (owner,)).fetchall()
        return [dict(r) for r in rows]
    finally:c.close()


def _n78_update(job, **changes):
    import time
    allowed = {'state','stage','progress','files','links','attempts','cancel','receipt','error'}
    if not changes or set(changes)-allowed:raise ValueError('Invalid download update')
    changes['updated'] = time.time()
    c = _n78_db()
    try:
        c.execute('UPDATE download78_jobs SET '+','.join(k+'=?' for k in changes)+' WHERE id=?', (*changes.values(),job)); c.commit()
    finally:c.close()


def _n78_pref(owner, **changes):
    c = _n78_db()
    try:
        row = c.execute('SELECT quality,browser FROM download78_preferences WHERE owner=?',(owner,)).fetchone()
        prefs = {'quality':row[0] if row else '1080','browser':bool(row[1]) if row else False}
        if changes:
            if set(changes)-set(prefs):raise ValueError('Invalid preference')
            prefs.update(changes)
            if prefs['quality'] not in ('360','480','720','1080','2160') or type(prefs['browser']) is not bool:raise ValueError('Invalid preference value')
            c.execute('INSERT OR REPLACE INTO download78_preferences VALUES(?,?,?)',(owner,prefs['quality'],int(prefs['browser'])));c.commit()
        return prefs
    finally:c.close()


def _n78_plan(text, owner):
    import re
    # Keep the existing explicit-intent and URL validation boundary.
    plan = _n77_parse(text)
    explicit = re.search(r'\b(?:360|480|720|1080|2160)p?\b',text.lower())
    if not explicit:
        plan['quality'] = '720' if re.search(r'\b(small(?:er)?(?: size)?|data saver|quick)\b',text.lower()) else _n78_pref(owner)['quality']
    plan['browser'] = _n78_pref(owner)['browser']
    plan['discover'] = bool(re.search(r'\b(browser|webpage|embedded)\b',text.lower()))
    return plan


def _n78_enqueue(msg):
    import json, time, uuid, hashlib
    owner = msg['chat']['id']; plan = _n78_plan(msg['text'],owner)
    binding = _n76_settings()
    if not binding:raise ValueError('Bind your Drive account first: Check my Drive, then Use <email> for downloads')
    c = _n78_db(); ids = []
    try:
        c.execute('BEGIN IMMEDIATE')
        count = c.execute("SELECT COUNT(*) FROM download78_jobs WHERE owner=? AND state IN ('QUEUED','RUNNING','PAUSED')",(owner,)).fetchone()[0]
        existing = []
        for i,url in enumerate(plan['urls']):
            req = str(owner)+':'+str(msg['message_id'])+':'+str(i)
            row = c.execute('SELECT id FROM download78_jobs WHERE request=?',(req,)).fetchone()
            existing.append((req,row[0] if row else None,url))
        if count+sum(not x[1] for x in existing)>20:raise ValueError('Download queue has 20 unfinished jobs. Finish or cancel some first.')
        for req,found,url in existing:
            if found:ids.append(found);continue
            job = 'D78-'+uuid.uuid4().hex[:10].upper(); now = time.time()
            payload = dict(plan,urls=[url],owner=owner,drive_id=binding['id'],drive_email=binding['email'].lower())
            c.execute('INSERT INTO download78_jobs VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
                (job,owner,req,json.dumps(payload),'QUEUED','Queued','{}','[]','[]',0,0,now,now,0,''))
            ids.append(job)
        c.commit()
    except Exception:c.rollback();raise
    finally:c.close()
    _N78_WAKE.set()
    return ids


def _n78_check():
    job = getattr(_N78_TLS,'job',None)
    if not job:return
    owner = getattr(_N78_TLS,'owner',None)
    rows = _n78_rows(owner,job)
    if not rows or rows[0]['cancel']:raise ValueError('Download cancelled')
    if OWNER.get('id') != owner:raise ValueError('Owner changed; download stopped')


def _n78_card(row):
    import json
    p = json.loads(row['progress'] or '{}'); lines = ['Nemo download '+row['id'],row['state']+' · '+row['stage']]
    if p.get('total',0)>0:lines.append('%.1f%% · %.1f / %.1f MiB'%(min(100,100*p.get('bytes',0)/p['total']),p.get('bytes',0)/1048576,p['total']/1048576))
    elif p.get('bytes',0)>0:lines.append('%.1f MiB transferred'%(p['bytes']/1048576))
    if p.get('speed',0)>0:lines.append('%.2f MiB/s'%(p['speed']/1048576))
    if p.get('eta',0)>0:lines.append('About %d seconds remaining in this stage'%p['eta'])
    if row['error']:lines.append(row['error'])
    if row['state'] in ('PAUSED','FAILED'):lines.append('Say: Resume download '+row['id'])
    if row['state']=='DONE':lines.extend(json.loads(row['links']))
    return '\n'.join(lines)


def _n78_progress(stage, values=None, force=False):
    import time,json,math
    job = getattr(_N78_TLS,'job',None)
    if not job:return
    now = time.monotonic(); last = getattr(_N78_TLS,'last',0)
    if not force and now-last<2:return
    _N78_TLS.last = now
    clean = {}
    for key,value in (values or {}).items():
        if key in ('bytes','total','speed','eta') and isinstance(value,(int,float)) and math.isfinite(value) and value>=0:clean[key]=value
    previous=_n78_rows(_N78_TLS.owner,job)
    if previous and previous[0]['stage']!=stage:
        c=_n78_db()
        try:c.execute('INSERT INTO download78_events VALUES(?,?,?)',(job,stage,time.time()));c.commit()
        finally:c.close()
    _n78_update(job,stage=stage,progress=json.dumps(clean))
    rows = _n78_rows(_N78_TLS.owner,job)
    if not rows:return
    # Edit one receipt at most once every 10 seconds; no raw URLs/cookies/logs.
    if force or now-getattr(_N78_TLS,'notified',0)>=10:
        _N78_TLS.notified=now; row=rows[0]
        try:
            if row['receipt']:tg('editMessageText',chat_id=row['owner'],message_id=row['receipt'],text=_n78_card(row))
        except Exception:pass


def _n78_log_progress(log):
    import json,os
    if not getattr(_N78_TLS,'job',None):return
    pos=getattr(_N78_TLS,'logpos',0)
    try:
        with open(log,'rb') as f:
            if os.path.getsize(log)<pos:pos=0
            f.seek(pos);data=f.read(65536)
        split=data.rfind(b'\n')
        if split<0:return
        _N78_TLS.logpos=pos+split+1
        for line in data[:split].decode('utf-8','replace').splitlines():
            if line.startswith('N78:'):
                try:
                    v=json.loads(line[4:]);_n78_progress('Downloading',{'bytes':v.get('downloaded_bytes'),'total':v.get('total_bytes') or v.get('total_bytes_estimate'),'speed':v.get('speed'),'eta':v.get('eta')})
                except (ValueError,TypeError,AttributeError):pass
            elif '[Merger]' in line or '[ExtractAudio]' in line:_n78_progress('Processing media',force=True)
    except OSError:pass


def _n78_folder(root,plan):
    import os,re,tempfile
    job=getattr(_N78_TLS,'job',None)
    if not job:return tempfile.mkdtemp(prefix='media_',dir=root)
    if not re.fullmatch(r'D78-[A-F0-9]{10}',job):raise ValueError('Invalid job directory')
    folder=os.path.join(root,job)
    if os.path.islink(folder):raise ValueError('Job folder cannot be a symlink')
    os.makedirs(folder,mode=0o700,exist_ok=True);_N78_TLS.logpos=0
    return folder


def _n78_tune(cmd, plan):
    import os
    cmd=list(cmd)
    # Progressive adaptation after failure: 4 -> 2 -> 1, bounded by available RAM.
    attempts=getattr(_N78_TLS,'attempts',1); fragments=max(1,4//(2**min(2,max(0,attempts-1))))
    try:
        with open('/proc/meminfo') as f:
            free=next(int(l.split()[1]) for l in f if l.startswith('MemAvailable:'))
        if free<512*1024:fragments=1
    except (OSError,StopIteration,ValueError):pass
    cmd[cmd.index('--concurrent-fragments')+1]=str(fragments)
    cmd.remove('--no-progress')
    cmd += ['--progress','--progress-template','download:N78:%(progress)j','--continue','--abort-on-unavailable-fragments',
            '--retry-sleep','http:exp=1:8','--retry-sleep','fragment:exp=1:8']
    # Retain YouTube/site pacing; do not claim delay removal is universally safe.
    if plan.get('_browser_media'):cmd+=['--referer',plan['_browser_page'],'--proxy',plan['_browser_proxy']]
    return cmd


def _n78_verify_files(paths):
    import os,hashlib
    records=[]
    for path in paths:
        if not os.path.isfile(path) or os.path.islink(path):raise ValueError('Downloaded file missing')
        size=os.path.getsize(path)
        if not 0<size<=_N76_MAX_FILE:raise ValueError('Downloaded file size invalid')
        h=hashlib.sha256()
        with open(path,'rb') as f:
            for chunk in iter(lambda:f.read(1048576),b''):_n78_check();h.update(chunk)
        records.append({'path':path,'size':size,'sha256':h.hexdigest()})
    return records


def _n78_binding(payload):
    bound=_n76_settings()
    if not bound or bound['id']!=payload['drive_id'] or bound['email'].lower()!=payload['drive_email']:
        raise ValueError('Drive binding changed. Submit a new request for the intended account.')


def _n78_run(row):
    import json,os,urllib.parse
    payload=json.loads(row['payload']);_n78_binding(payload);_n78_check()
    saved=json.loads(row['files']);links=json.loads(row['links']);warning=''
    if saved:
        fresh=_n78_verify_files([r['path'] for r in saved])
        if fresh!=saved:raise ValueError('Retained file changed. Submit a new download request.')
    else:
        url=payload['urls'][0];p=_n77_url(url);_n78_progress('Resolving source',force=True)
        if p.hostname in ('drive.google.com','docs.google.com'):paths=[_n77_google_file(url,payload['mode'])]
        elif any(_n77_host(p.hostname,h) for h in _N77_MEDIA_HOSTS) and not payload.get('discover'):
            paths,warning=_n77_media(url,payload)
        elif payload.get('discover') or (payload.get('browser') and not os.path.splitext(p.path)[1]):
            if not payload.get('browser'):raise ValueError('Say Enable browser video discovery first. Optional Playwright and Chromium must be installed.')
            _n78_progress('Discovering browser media',force=True)
            media=_n78_discover(url)
            with _n78_proxy() as proxy:
                browser_plan=dict(payload,_browser_media=True,_browser_page=url,_browser_proxy=proxy)
                paths,warning=_n77_media(media,browser_plan)
        else:
            ext=os.path.splitext(p.path)[1].lower()
            acceptable={'audio':('.mp3','.m4a','.wav','.flac','.ogg','.opus','.aac'),'mp3':('.mp3',),'subtitles':('.srt','.vtt',),'thumbnail':('.jpg','.jpeg','.png','.webp')}
            if payload['mode']!='video' and ext not in acceptable.get(payload['mode'],()):raise ValueError('Use a supported media link for conversion, or a direct file matching the requested format.')
            if p.hostname in ('dropbox.com','www.dropbox.com'):
                q=[(k,v) for k,v in urllib.parse.parse_qsl(p.query) if k not in ('dl','raw')]+[('dl','1')]
                url=urllib.parse.urlunsplit((p.scheme,p.netloc,p.path,urllib.parse.urlencode(q),''))
            _n78_progress('Downloading file',force=True)
            paths=[_n78_direct(url)]
        if warning:raise ValueError('Some media items failed. Partial files retained; retry this job.')
        _n78_progress('Verifying files',force=True);saved=_n78_verify_files(paths)
        _n78_update(row['id'],files=json.dumps(saved))
    for index,record in enumerate(saved):
        _n78_check();_n78_binding(payload)
        if index<len(links):continue
        _n78_progress('Uploading to Drive',force=True)
        _n64_register_file(record['path'],'','file','download78','')
        link=_n76_upload(record['path'])
        if not isinstance(link,str) or not link.startswith('https://drive.google.com/'):raise ValueError('Drive upload was not verified')
        links.append(link);_n78_update(row['id'],links=json.dumps(links))
    if not saved or len(links)!=len(saved):raise ValueError('No complete verified delivery')
    _n78_progress('Verified in Drive',force=True)
    _n78_update(row['id'],state='DONE',stage='Verified in Drive',error='',progress='{}')


def _n78_claim():
    import sqlite3,time
    c=_n78_db();c.row_factory=sqlite3.Row
    try:
        c.execute('BEGIN IMMEDIATE')
        row=c.execute("SELECT * FROM download78_jobs WHERE state='QUEUED' AND cancel=0 AND owner=? ORDER BY created,id LIMIT 1",(OWNER.get('id'),)).fetchone()
        if row:
            c.execute("UPDATE download78_jobs SET state='RUNNING',stage='Starting',attempts=attempts+1,updated=? WHERE id=?",(time.time(),row['id']));c.commit()
            result=dict(row);result['attempts']+=1;return result
        c.commit();return None
    finally:c.close()


def _n78_work_once():
    import json
    row=_n78_claim()
    if not row:return False
    _N78_TLS.job=row['id'];_N78_TLS.owner=row['owner'];_N78_TLS.attempts=row['attempts'];_N78_TLS.last=0;_N78_TLS.notified=0
    try:
        if not row['receipt']:
            try:
                sent=tg('sendMessage',chat_id=row['owner'],text='Nemo download '+row['id']+' starting.')
                if sent.get('ok'):_n78_update(row['id'],receipt=int(sent['result']['message_id']))
            except Exception:pass
        _n78_progress('Preparing download',force=True)
        _n78_run(row)
    except Exception as e:
        current=_n78_rows(row['owner'],row['id'])[0]
        cancelled=current['cancel']
        # Never send raw extractor/request exceptions or signed URLs to chat.
        error='Cancelled; partial files retained.' if cancelled else 'Transfer or verification failed. Check download health, then resume this job. No complete delivery is claimed.'
        if getattr(e,'_n87',False):
            error=str(e)[:2600]                       # v87: the per-source report of the download chain (already free of links, paths and cookies)
        elif isinstance(e,ValueError):
            categories={
              'rate-limit':'The source rate-limited this server. Wait before resuming.',
              'session':'The source returned a sign-in/session rejection. This does not prove your cookies expired. Diagnose YouTube before resuming.',
              'PO-token':'The YouTube PO-token provider needs attention. Check download health.',
              'DRM':'DRM-protected media is not supported.',
              'JavaScript':'The YouTube JavaScript runtime needs attention. Check download health.',
              'Disk reserve':'Disk reserve reached. Free space before resuming.',
              'size limit':'The file exceeds the configured size limit.',
              'time limit':'Transfer time limit reached. Partial files retained.',
              'Drive chunk HTTP':'Drive upload was interrupted. Resume to reconcile the retained file.',
              'ffprobe':'Media verification needs ffprobe installed on the server.'}
            for phrase,message in categories.items():
                if phrase.lower() in str(e).lower():error=message;break
            known=('Drive binding changed.','Retained file changed.','Say Enable browser','Browser found no','Browser found multiple','Browser discovery requires','Browser media requires','Some media items failed.')
            if str(e).startswith(known):error=str(e)
        _n78_update(row['id'],state='CANCELLED' if cancelled else 'FAILED',stage='Cancelled' if cancelled else 'Failed',error=error)
    finally:
        try:
            current=_n78_rows(row['owner'],row['id'])[0]
            send_text(row['owner'],_n78_card(current))
        except Exception:pass
        _N78_TLS.job=None
    return True


def _n78_loop():
    while True:
        try:
            if _n78_work_once():continue
        except Exception:pass
        _N78_WAKE.wait(2);_N78_WAKE.clear()


def _n78_start():
    import os,fcntl,time
    global _N78_THREAD,_N78_PROCESS_LOCK
    with _N78_LOCK:
        if _N78_THREAD and _N78_THREAD.is_alive():return
        root=os.path.dirname(os.path.abspath(DATA_FILE))
        fd=os.open(os.path.join(root,'nemo_download78.lock'),os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW,0o600)
        lock=os.fdopen(fd,'w')
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:lock.close();return
        c=_n78_db()
        try:
            c.execute("UPDATE download78_jobs SET state='PAUSED',stage='Interrupted by restart',error='Partial files retained. Resume when ready.',updated=? WHERE state='RUNNING'",(time.time(),));c.commit()
        finally:c.close()
        _N78_PROCESS_LOCK=lock
        _N78_THREAD=_n78_threading.Thread(target=_n78_loop,name='nemo-download78',daemon=True);_N78_THREAD.start()


def _n78_control(owner, action, ident=None):
    rows=_n78_rows(owner,ident.upper() if ident else None)
    if ident:rows=[r for r in rows if r['id']==ident.upper()]
    elif action=='cancel':rows=[r for r in rows if r['state'] in ('RUNNING','QUEUED','PAUSED')]
    else:rows=[r for r in rows if r['state'] in ('FAILED','PAUSED','CANCELLED')]
    if len(rows)!=1:return 'Specify the job ID from Show download queue; there is no single matching job.'
    row=rows[0];c=_n78_db()
    try:
        if action=='cancel':
            c.execute("UPDATE download78_jobs SET cancel=1,state=CASE WHEN state='RUNNING' THEN state ELSE 'CANCELLED' END WHERE id=? AND owner=? AND state IN ('RUNNING','QUEUED','PAUSED')",(row['id'],owner))
            changed=c.total_changes;c.commit()
            return ('Cancellation requested for ' if changed else 'Job is already finished: ')+row['id']
        if row['attempts']>=5:return 'Five attempts reached. Check download health and submit a new request.'
        c.execute("UPDATE download78_jobs SET state='QUEUED',stage='Queued for recovery',cancel=0,error='' WHERE id=? AND owner=? AND state IN ('FAILED','PAUSED','CANCELLED')",(row['id'],owner))
        changed=c.total_changes;c.commit();_N78_WAKE.set()
        return ('Recovery queued for ' if changed else 'Job is not resumable in its current state: ')+row['id']
    finally:c.close()


def _n78_dispatch(msg):
    import re,json
    chat=msg.get('chat') or {};owner=chat.get('id');text=(msg.get('text') or '').strip();low=text.lower().strip(' .!?')
    if owner!=OWNER.get('id') or chat.get('type')!='private' or (msg.get('from') or {}).get('id')!=owner:return False
    if low in ('show download performance','download performance'):
        send_text(owner,_n78_performance(owner));return True
    if low in ('show download queue','download status','how are my downloads going','download progress'):
        rows=_n78_rows(owner);send_text(owner,'\n\n'.join(_n78_card(r) for r in rows[:8])[:3900] if rows else 'Your download queue is empty.');return True
    match=re.fullmatch(r'(cancel|stop|resume|retry) (?:that |my |the )?download(?: (D78-[a-f0-9]{10}))?',text,re.I)
    if match:
        send_text(owner,_n78_control(owner,'cancel' if match[1].lower() in ('cancel','stop') else 'resume',match[2]));_n78_start();return True
    if low in ('enable browser video discovery','disable browser video discovery'):
        enabled=low.startswith('enable');_n78_pref(owner,browser=enabled)
        send_text(owner,'Browser discovery '+('enabled. Requires Playwright and Chromium on the server; uses an isolated public session, not your personal login.' if enabled else 'disabled.'));return True
    match=re.fullmatch(r'(?:prefer|remember|use) (360|480|720|1080|2160)p? (?:for )?(?:my )?downloads',low)
    if match:_n78_pref(owner,quality=match[1]);send_text(owner,'Remembered '+match[1]+'p as your download ceiling.');return True
    if low in ('make it audio','make it mp3','make it smaller'):
        rows=[r for r in _n78_rows(owner) if r['state']=='QUEUED']
        if len(rows)!=1:send_text(owner,'I need exactly one queued download for that change. Active downloads cannot be changed in place.');return True
        row=rows[0];p=json.loads(row['payload'])
        if low=='make it smaller':p['quality']='720'
        else:p['mode']='mp3' if low=='make it mp3' else 'audio'
        c=_n78_db()
        try:
            c.execute("UPDATE download78_jobs SET payload=? WHERE id=? AND state='QUEUED'",(json.dumps(p),row['id']));changed=c.total_changes;c.commit()
        finally:c.close()
        send_text(owner,'Queued download updated.' if changed else 'That download already started; submit a new request.');return True
    if re.search(r'\b(download|save) (?:this|that)\b',low) and 'https://' not in text:
        quoted=msg.get('reply_to_message') or {}
        links=re.findall(r'https://[^\s<>]+',str(quoted.get('text') or quoted.get('caption') or ''))
        if links:
            text=text+' '+' '.join(links);msg=dict(msg,text=text);low=text.lower()
    if not re.search(r'\b(download|save|export|capture)\b',low) or 'https://' not in text:return False
    if re.search(r"\b(don't|do not|never|not|if|explain|how)\b",low):return False
    # Existing paid captures remain in their original explicitly bounded workflow.
    plan=_n77_parse(text)
    if plan['mode'] in ('pdf','screenshot'):return False
    try:
        ids=_n78_enqueue(msg);send_text(owner,'Queued '+', '.join(ids)+'. Say Show download queue or Cancel download <job ID>.');_n78_start()
    except Exception as e:
        safe=str(e) if isinstance(e,ValueError) and 'https://' not in str(e) else 'Queue could not start; check download health.'
        send_text(owner,safe[:500])
    return True


def _n78_direct_inner(url, proxy):
    import os,shutil,requests,subprocess,time,signal,urllib.parse
    # Use aria2 only for HTTPS files with a demonstrated range response.
    # Redirecting/small/unknown-size sources retain the existing HTTP path.
    p=_n77_url(url);aria=shutil.which('aria2c')
    if not aria or not getattr(_N78_TLS,'job',None):return _n76_direct_download(url)
    response=requests.get(url,proxies={'https':proxy},headers={'Range':'bytes=0-0','Accept-Encoding':'identity'},stream=True,timeout=(10,20),allow_redirects=False)
    try:
        import re
        m=re.fullmatch(r'bytes 0-0/(\d+)',response.headers.get('Content-Range',''))
        total=int(m[1]) if m else 0
        eligible=response.status_code==206 and 8*1048576<=total<=_N76_MAX_FILE
        etag=response.headers.get('ETag','')
    finally:response.close()
    if not eligible:return _n76_direct_download(url)
    root=os.path.join(os.path.dirname(os.path.abspath(DATA_FILE)),'nemo_download77')
    if os.path.islink(root):raise ValueError('Download root cannot be a symlink')
    os.makedirs(root,mode=0o700,exist_ok=True);folder=_n78_folder(root,{})
    ext=os.path.splitext(p.path)[1].lower()
    if not re.fullmatch(r'\.[a-z0-9]{1,8}',ext):ext='.bin'
    name='download'+ext;path=os.path.join(folder,name)
    if os.path.islink(path) or os.path.islink(path+'.aria2'):raise ValueError('Download path cannot be a symlink')
    cmd=[aria,'--https-proxy='+proxy,'--no-proxy=','--no-conf=true','--allow-overwrite=true','--auto-file-renaming=false','--continue=true',
         '--max-connection-per-server=4','--split=4','--min-split-size=4M','--max-http-redirect=0',
         '--max-tries=2','--retry-wait=3','--connect-timeout=15','--timeout=30','--check-certificate=true',
         '--file-allocation=none','--console-log-level=error','--summary-interval=0','--dir='+folder,'--out='+name]
    if etag and '\n' not in etag and '\r' not in etag:cmd+=['--header=If-Range: '+etag]
    cmd+=['--',url];_n77_url(url)
    proc=_n78_spawn(cmd,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True)
    started=time.monotonic()
    try:
        while proc.poll() is None:
            _n78_check()
            if time.monotonic()-started>900:raise ValueError('Direct download time limit reached')
            if shutil.disk_usage(folder).free<512*1048576:raise ValueError('Disk reserve reached')
            if os.path.exists(path) and os.path.getsize(path)>_N76_MAX_FILE:raise ValueError('Download size exceeded limit')
            # Sparse/preallocated file size is not byte progress; don't fabricate a percentage.
            _n78_progress('Downloading file with up to four connections')
            time.sleep(.25)
        if proc.returncode or not os.path.isfile(path) or os.path.getsize(path)!=total or os.path.exists(path+'.aria2'):
            raise ValueError('Direct download incomplete; resume this job')
        os.chmod(path,0o600);return path
    finally:
        if proc.poll() is None:
            try:os.killpg(proc.pid,signal.SIGTERM);proc.wait(timeout=3)
            except Exception:
                try:os.killpg(proc.pid,signal.SIGKILL);proc.wait(timeout=3)
                except Exception:pass


def _n78_discover(url):
    import urllib.parse,time
    _n77_url(url)
    try:from playwright.sync_api import sync_playwright
    except ImportError:raise ValueError('Browser discovery requires Playwright and Chromium installed on the server.') from None
    candidates=[];blocked=[False]
    def guard(route):
        try:
            p=_n77_url(route.request.url)
            if route.request.resource_type in ('image','font'):
                route.abort();return
            route.continue_()
        except Exception:
            blocked[0]=True;route.abort()
    def observe(response):
        try:
            if response.status!=200:return
            p=_n77_url(response.url);mime=response.headers.get('content-type','').split(';')[0].lower()
            path=p.path.lower()
            if mime in ('video/mp4','video/webm','application/vnd.apple.mpegurl','application/x-mpegurl','application/dash+xml') or path.endswith(('.m3u8','.mpd','.mp4','.webm')):
                if response.url not in candidates and len(candidates)<12:candidates.append(response.url)
        except Exception:pass
    try:
        with _n78_proxy() as proxy, sync_playwright() as pw:
            browser=pw.chromium.launch(headless=True,proxy={'server':proxy},args=['--proxy-bypass-list=<-loopback>'])
            try:
                context=browser.new_context(accept_downloads=False,service_workers='block')
                context.route('**/*',guard)
                page=context.new_page();page.on('response',observe)
                page.goto(url,wait_until='domcontentloaded',timeout=25000)
                # Fixed DOM operation only; no instructions from page content are executed as agent commands.
                page.locator('video').evaluate_all('(els) => els.forEach(v => {v.muted=true; v.play().catch(()=>{});})')
                deadline=time.monotonic()+8
                while time.monotonic()<deadline:
                    _n78_check();page.wait_for_timeout(250)
                context.close()
            finally:browser.close()
    except ValueError:raise
    except Exception:raise ValueError('Browser discovery requires a working Playwright Chromium installation and a reachable public page.') from None
    manifests=[u for u in candidates if urllib.parse.urlsplit(u).path.lower().endswith(('.m3u8','.mpd'))]
    options=manifests or candidates
    if not options:raise ValueError('Browser found no supported public media. A login, DRM, or unsupported player may be involved.')
    if len(options)!=1:raise ValueError('Browser found multiple media streams. Send the specific video page or a direct media link.')
    return options[0]


def _n78_spawn(cmd, **kwargs):
    import os,sys,subprocess
    # A small supervisor terminates its process group if the bot disappears.
    # No preexec_fn (unsafe in a threaded process), shell, or generated shell text.
    supervisor = """import os,sys,time,signal,subprocess
parent=int(sys.argv[1])
if os.getppid()!=parent:sys.exit(125)
child=subprocess.Popen(sys.argv[2:],stdin=subprocess.DEVNULL)
while child.poll() is None:
    if os.getppid()!=parent:
        os.killpg(os.getpgrp(),signal.SIGTERM)
        sys.exit(125)
    time.sleep(.2)
sys.exit(child.returncode if child.returncode>=0 else 128-child.returncode)
"""
    return subprocess.Popen([sys.executable,'-c',supervisor,str(os.getpid()),*cmd],**kwargs)


def _n78_public_addresses(host, port):
    import socket,ipaddress
    if port != 443:raise ValueError('HTTPS port required')
    rows=socket.getaddrinfo(host,port,type=socket.SOCK_STREAM)
    if not rows or any(not ipaddress.ip_address(r[4][0]).is_global for r in rows):
        raise ValueError('Public destination required')
    return rows


def _n78_proxy():
    # Pin each CONNECT to a validated public IP; redirects require a new check.
    import contextlib,socketserver,socket,select,urllib.parse
    @contextlib.contextmanager
    def manager():
        slots=_n78_threading.BoundedSemaphore(16);active=set();lock=_n78_threading.Lock()
        class Handler(socketserver.StreamRequestHandler):
            def handle(self):
                if not slots.acquire(False):return
                remote=None
                try:
                    self.connection.settimeout(10)
                    line=self.rfile.readline(8193)
                    if len(line)>8192:return
                    parts=line.decode('ascii').split()
                    if len(parts)!=3 or parts[0]!='CONNECT':return
                    target=urllib.parse.urlsplit('https://'+parts[1])
                    if not target.hostname or target.username or target.password or target.path:return
                    rows=_n78_public_addresses(target.hostname,target.port or 443)
                    total=0
                    while True:
                        header=self.rfile.readline(8193);total+=len(header)
                        if total>16384:return
                        if header in (b'\r\n',b'\n'):break
                        if not header:return
                    for family,kind,protocol,_,address in rows:
                        try:
                            remote=socket.socket(family,kind,protocol);remote.settimeout(10);remote.connect(address);break
                        except OSError:
                            if remote:remote.close()
                            remote=None
                    if remote is None:return
                    with lock:active.update((remote,self.connection))
                    self.connection.sendall(b'HTTP/1.1 200 Connection Established\r\n\r\n')
                    while True:
                        readable,_,_=select.select([self.connection,remote],[],[],30)
                        if not readable:return
                        for source in readable:
                            data=source.recv(65536)
                            if not data:return
                            (remote if source is self.connection else self.connection).sendall(data)
                except Exception:pass
                finally:
                    with lock:
                        active.discard(self.connection)
                        if remote:active.discard(remote)
                    if remote:remote.close()
                    slots.release()
        class Server(socketserver.ThreadingTCPServer):
            daemon_threads=True
            allow_reuse_address=False
        server=Server(('127.0.0.1',0),Handler)
        thread=_n78_threading.Thread(target=server.serve_forever,daemon=True);thread.start()
        try:yield 'http://127.0.0.1:'+str(server.server_address[1])
        finally:
            server.shutdown();server.server_close()
            with lock:
                for connection in active:
                    try:connection.shutdown(socket.SHUT_RDWR)
                    except OSError:pass
                    connection.close()
    return manager()


def _n78_performance(owner):
    import json
    rows=[r for r in _n78_rows(owner) if r['state']=='DONE'][:5]
    if not rows:return 'No completed v78 downloads yet. Measurements appear after verified Drive delivery.'
    lines=['Nemo download measurements (includes queue time; no speedup claim)']
    for row in rows:
        size=sum(f['size'] for f in json.loads(row['files']))
        lines.append('%s · %.1f MiB · %.1f s request-to-finish'%(row['id'],size/1048576,max(0,row['updated']-row['created'])))
        c=_n78_db()
        try:events=c.execute('SELECT stage,at FROM download78_events WHERE job=? ORDER BY at',(row['id'],)).fetchall()
        finally:c.close()
        totals={}
        for (stage,start),(_,end) in zip(events,events[1:]):totals[stage]=totals.get(stage,0)+max(0,end-start)
        lines.extend('  '+stage+': %.1f s'%duration for stage,duration in totals.items())
    return '\n'.join(lines)[:3900]


def _n78_health():
    import shutil,importlib.util
    try:playwright=importlib.util.find_spec('playwright') is not None
    except (ValueError,ImportError):playwright=False
    rows=_n78_rows(OWNER.get('id'));prefs=_n78_pref(OWNER.get('id'))
    active=sum(r['state'] in ('QUEUED','RUNNING','PAUSED') for r in rows)
    running=bool(_N78_THREAD and _N78_THREAD.is_alive())
    return ['v78 queue worker: '+('running' if running else 'not running in this process'),
            'Unfinished jobs: '+str(active)+' / 20',
            'aria2: '+('available; direct range-compatible files only' if shutil.which('aria2c') else 'not installed; ordinary HTTP fallback'),
            'Browser discovery: '+('enabled' if prefs['browser'] else 'disabled')+'; Playwright '+('installed; Chromium and live operation not tested' if playwright else 'not installed'),
            'Preferred quality ceiling: '+prefs['quality']+'p',
            'Media fragments: up to 4, then 2 / 1 on subsequent attempts; memory cap applies.']


