def _n87_classify(text):
    low = str(text or '').lower()
    for klass, needles in _N87_CLASSES:
        if any(n in low for n in needles):
            return klass
    return 'unknown'


def _n87_clean(text, limit=150):
    """One short line that is safe to show: no links, paths, e-mail addresses or secret-looking values."""
    t = str(text or '')
    t = _n87_re.sub(r'https?://\S+', '[link]', t)
    t = _n87_re.sub(r'(?:/[\w.\-]+){2,}', '[path]', t)
    t = _n87_re.sub(r'\S+@\S+', '[email]', t)
    t = ' '.join(t.split())
    try:
        t = _n86_mask(t)
    except Exception:
        pass
    return t[:limit]


def _n87_err_line(raw):
    lines = [x.strip() for x in str(raw or '').splitlines() if x.strip()]
    for line in reversed(lines):
        if 'ERROR' in line or 'error' in line.lower()[:12]:
            return _n87_clean(line)
    return _n87_clean(lines[-1]) if lines else ''


# ------------------------------------------------ small facts about this server ------------------------------------------------
_N87_NODE = {'checked': 0.0, 'version': None, 'path': ''}


def _n87_node():
    """(path, major version) of a Node.js that yt-dlp can use (20+), cached for 10 minutes."""
    now = _n87_time.time()
    if now - _N87_NODE['checked'] < 600:
        return _N87_NODE['path'], _N87_NODE['version']
    path, major = '', None
    exe = _n87_shutil.which('node')
    if exe:
        try:
            r = _n87_sp.run([exe, '--version'], capture_output=True, text=True, timeout=10)
            m = _n87_re.match(r'v(\d+)', (r.stdout or '').strip())
            major = int(m.group(1)) if m else None
            path = exe
        except Exception:
            pass
    _N87_NODE.update({'checked': now, 'version': major, 'path': path})
    return path, major


