def _n87_db():
    c = _n35_conn()
    c.execute('CREATE TABLE IF NOT EXISTS download87_stats(source TEXT PRIMARY KEY, ok INTEGER DEFAULT 0, fail INTEGER DEFAULT 0, last_ok REAL DEFAULT 0, '
              "last_fail REAL DEFAULT 0, last_class TEXT DEFAULT '')")
    c.execute('CREATE TABLE IF NOT EXISTS download87_share(file_id TEXT PRIMARY KEY, state TEXT, ts REAL)')
    c.commit()
    return c


def _n87_stat(source, ok, klass=''):
    try:
        c = _n87_db()
        try:
            now = _n87_time.time()
            row = c.execute('SELECT ok,fail FROM download87_stats WHERE source=?', (source,)).fetchone()
            good, bad = (row[0], row[1]) if row else (0, 0)
            if ok:
                c.execute('INSERT OR REPLACE INTO download87_stats VALUES(?,?,?,?,COALESCE((SELECT last_fail FROM download87_stats WHERE source=?),0),?)',
                          (source, good + 1, bad, now, source, ''))
            else:
                c.execute('INSERT OR REPLACE INTO download87_stats VALUES(?,?,?,COALESCE((SELECT last_ok FROM download87_stats WHERE source=?),0),?,?)',
                          (source, good, bad + 1, source, now, str(klass)[:30]))
            c.commit()
        finally:
            c.close()
    except Exception:
        _N87_STATS['errors'] += 1


def _n87_stats():
    try:
        c = _n87_db()
        try:
            return {r[0]: {'ok': r[1], 'fail': r[2], 'last_ok': r[3], 'last_fail': r[4], 'last_class': r[5]}
                    for r in c.execute('SELECT source,ok,fail,last_ok,last_fail,last_class FROM download87_stats').fetchall()}
        finally:
            c.close()
    except Exception:
        return {}


def _n87_preferred(keys, host_is_youtube):
    """The source that most recently worked (within 3 days, and later than its last failure) is tried first."""
    if not host_is_youtube:
        return ''
    stats = _n87_stats()
    now = _n87_time.time()
    best, when = '', 0.0
    for key in keys:
        s = stats.get(key)
        if s and s['last_ok'] and now - s['last_ok'] < 3 * 86400 and s['last_ok'] > s['last_fail'] and s['last_ok'] > when:
            best, when = key, s['last_ok']
    return best


# ------------------------------------------------ checking what arrived ------------------------------------------------
def _n87_probe(path):
    """(has_video, has_audio, duration seconds). Raises ValueError when ffprobe is missing."""
    if not _n87_shutil.which('ffprobe'):
        raise ValueError('ffprobe is required to verify downloaded media')
    r = _n87_sp.run(['ffprobe', '-v', 'error', '-show_entries', 'stream=codec_type:format=duration', '-of', 'json', path],
                    capture_output=True, text=True, timeout=30)
    if r.returncode:
        return False, False, 0.0
    j = _n87_json.loads(r.stdout or '{}')
    kinds = [s.get('codec_type') for s in j.get('streams', []) if isinstance(s, dict)]
    try:
        duration = float((j.get('format') or {}).get('duration') or 0)
    except (TypeError, ValueError):
        duration = 0.0
    return 'video' in kinds, 'audio' in kinds, duration


def _n87_verify(path, mode):
    """(ok, reason). A file only counts when it is a real, playable video/audio of non-trivial size."""
    try:
        size = _n87_os.path.getsize(path)
    except OSError:
        return False, 'file missing'
    if mode in ('subtitles', 'thumbnail'):
        return size > 0, 'empty file' if size <= 0 else ''
    if size < _N87_MIN_BYTES:
        return False, 'file too small (%d bytes)' % size
    has_video, has_audio, duration = _n87_probe(path)
    if mode == 'video' and not has_video:
        return False, 'no video stream'
    if mode in ('audio', 'mp3') and not has_audio:
        return False, 'no audio stream'
    if duration < 0.5:
        return False, 'no playable duration'
    return True, ''


def _n87_collect(folder, before, plan):
    """New media files in `folder` that pass the check. Returns (files, problems)."""
    mode = plan['mode']
    allowed = ('.vtt', '.srt') if mode == 'subtitles' else ('.jpg', '.jpeg', '.png', '.webp') if mode == 'thumbnail' else ('.mp3',) if mode == 'mp3' else _N87_MEDIA_EXT
    files, problems = [], []
    for name in sorted(_n87_os.listdir(folder)):
        path = _n87_os.path.join(folder, name)
        if name in before or not name.lower().endswith(allowed) or _n87_os.path.islink(path) or not _n87_os.path.isfile(path):
            continue
        if _n87_re.search(r'\.f\d+\.[A-Za-z0-9]+$', name):          # a leftover single-stream piece that was never merged
            continue
        size = _n87_os.path.getsize(path)
        if not 0 < size <= _N76_MAX_FILE:
            continue
        ok, why = _n87_verify(path, mode)
        if ok:
            files.append(path)
        else:
            problems.append(why)
            try:
                _n87_os.unlink(path)       # a junk file would make the next attempt think "already downloaded"
            except OSError:
                pass
    return files, problems


def _n87_left(ctx):
    return ctx['deadline'] - _n87_time.monotonic()


def _n87_sleep_check(ctx):
    """Cancellation and the overall time limit; raises ValueError for cancellation (never treated as a source failure)."""
    _n77_check_cancel()
    if _n87_left(ctx) <= 0:
        raise _N87Timeout('overall time limit')


class _N87Timeout(Exception):
    pass


class _N87Fail(ValueError):
    """Every source failed. str(self) is safe to show: no links, paths, cookies or raw extractor output."""

    def __init__(self, text, klass='unknown'):
        super().__init__(text)
        self.klass = klass
        self._n87 = True


