# ------------------------------------------------ the server's own numbers: memory, swap, disk, CPU, who uses the memory ------------------------------------------------
# Found with the owner's own screenshots: asked "How much memory and disk does your server have?", Nemo said he had no live figures and offered to run commands through a code tool he
# does not have switched on. His system view knew only his own process, free disk and load. This reads /proc and the disk directly (read-only, no AI, no shell) and answers at once.
_N91_PROC = '/proc'


def _n91_readfile(path):
    try:
        with open(path, encoding='utf-8', errors='replace') as f:
            return f.read(200000)
    except OSError:
        return ''


def _n91_meminfo():
    out = {}
    for ln in _n91_readfile(_n91_os.path.join(_N91_PROC, 'meminfo')).split('\n'):
        m = _n91_re.match(r'^(\w+):\s+(\d+)\s*kB', ln)
        if m:
            out[m.group(1)] = int(m.group(2)) * 1024
    return out


def _n91_proc_status(pid):
    d = {}
    for ln in _n91_readfile(_n91_os.path.join(_N91_PROC, str(pid), 'status')).split('\n')[:60]:
        m = _n91_re.match(r'^(Name|VmRSS|Threads):\s*(.+)$', ln)
        if m:
            d[m.group(1)] = m.group(2).strip()
    return d


_N91_HINT_SECRETISH = _n91_re.compile(r'^[A-Za-z0-9+_\-]{24,}$')


def _n91_proc_hint(pid):
    """A few plain words that say WHAT a process is (a module or script name, or "env NAME" for one of Nemo's tool environments). Command-line options are never shown, an argument that
    looks like a key is dropped, and the rest is masked like any other text."""
    base = _n91_os.path.join(_N91_PROC, str(pid))
    bits = []
    try:
        exe = _n91_os.readlink(_n91_os.path.join(base, 'exe'))
        m = _n91_re.search(r'/nemo_envs/([A-Za-z0-9_.-]{1,32})/', exe)
        if m:
            bits.append('env ' + m.group(1))
    except OSError:
        pass
    parts = _n91_readfile(_n91_os.path.join(base, 'cmdline')).split('\x00')
    args = (parts[0].split(' ')[1:] + parts[1:])[:6] if parts and ' ' in parts[0] else parts[1:6]          # npm and node rewrite their title into one string: "npm exec @scope/package"
    words = []
    for a in args:
        a = a.strip()
        if not a or a.startswith('-') or '=' in a or ':' in a.replace('://', 'X') or len(a) > 80:
            continue
        if '/' in a and not a.startswith('@'):
            a = '…/' + '/'.join(a.rstrip('/').split('/')[-2:])
        elif _N91_HINT_SECRETISH.match(a) and _n91_re.search(r'\d', a) and _n91_re.search(r'[A-Za-z]', a):
            continue
        words.append(a)
        if len(words) == 2:
            break
    if words:
        bits.append(' '.join(words))
    return _n91_untrusted(' · '.join(bits), 56)


def _n91_kb(text):
    m = _n91_re.match(r'^(\d+)\s*kB', str(text or ''))
    return int(m.group(1)) * 1024 if m else 0


def _n91_vmstat():
    out = {}
    for ln in _n91_readfile(_n91_os.path.join(_N91_PROC, 'vmstat')).split('\n'):
        m = _n91_re.match(r'^(pswpin|pswpout)\s+(\d+)', ln)
        if m:
            out[m.group(1)] = int(m.group(2))
    return out


def _n91_swap_rate(sample):
    """Pages per second swapped in and out RIGHT NOW (two readings about a second apart), or None when this system does not say or when not asked to sample."""
    if not sample:
        return None
    a = _n91_vmstat()
    if 'pswpin' not in a or 'pswpout' not in a:
        return None
    t0 = _n91_time.time()
    _n91_time.sleep(1.0)
    b = _n91_vmstat()
    dt = max(0.2, _n91_time.time() - t0)
    if 'pswpin' not in b or 'pswpout' not in b:
        return None
    return {'in': max(0.0, (b['pswpin'] - a['pswpin']) / dt), 'out': max(0.0, (b['pswpout'] - a['pswpout']) / dt)}


def _n91_psi():
    """The kernel's own "how long did programs wait for memory" figures (10-second averages, percent), or None."""
    out = {}
    for ln in _n91_readfile(_n91_os.path.join(_N91_PROC, 'pressure', 'memory')).split('\n'):
        m = _n91_re.match(r'^(some|full)\s+avg10=([\d.]+)', ln)
        if m:
            out[m.group(1)] = float(m.group(2))
    return out or None


def _n91_swap_state(r):
    """'none' (no swap or under half used), 'stale' (swap is mostly full but memory is free and nothing is being swapped now), 'pressure' (swap is mostly full AND the server is short of memory or
    swapping now), 'unclear' (swap mostly full, memory is fine, but I could not measure activity)."""
    if not r.get('swap_total') or r['swap_used'] * 2 < r['swap_total']:
        return 'none'
    low = r['mem_total'] and r['mem_avail'] < 0.25 * r['mem_total']
    rate = r.get('swap_rate')
    psi = r.get('psi')
    active = bool(rate and (rate['in'] + rate['out']) > 50)
    stalled = bool(psi and psi.get('some', 0) >= 5.0)
    if low or active or stalled:
        return 'pressure'
    return 'stale' if (rate is not None or psi is not None) else 'unclear'


def _n91_resources(top=5, sample=True):
    """{'mem_total','mem_avail','swap_total','swap_used','disk_total','disk_used','disk_free','cpus','load','uptime','own','top'} (bytes / seconds); empty parts when this system does not say."""
    mi = _n91_meminfo()
    r = {'mem_total': mi.get('MemTotal', 0), 'swap_total': mi.get('SwapTotal', 0)}
    r['mem_avail'] = mi.get('MemAvailable', mi.get('MemFree', 0) + mi.get('Buffers', 0) + mi.get('Cached', 0)) if mi else 0
    r['swap_used'] = max(0, mi.get('SwapTotal', 0) - mi.get('SwapFree', 0))
    try:
        du = _n91_shutil.disk_usage('/')
        r.update(disk_total=du.total, disk_used=du.used, disk_free=du.free)
    except OSError:
        r.update(disk_total=0, disk_used=0, disk_free=0)
    try:
        r['cpus'] = _n91_os.cpu_count() or 0
    except Exception:
        r['cpus'] = 0
    la = _n91_readfile(_n91_os.path.join(_N91_PROC, 'loadavg')).split()
    try:
        r['load'] = [float(x) for x in la[:3]]
    except ValueError:
        r['load'] = []
    try:
        r['uptime'] = float(_n91_readfile(_n91_os.path.join(_N91_PROC, 'uptime')).split()[0])
    except (ValueError, IndexError):
        r['uptime'] = 0.0
    own = _n91_proc_status('self')
    r['own'] = {'rss': _n91_kb(own.get('VmRSS')), 'threads': own.get('Threads', '?')} if own else {}
    procs = []
    try:
        names = [n for n in _n91_os.listdir(_N91_PROC) if n.isdigit()][:800]
    except OSError:
        names = []
    me = str(_n91_os.getpid())
    for n in names:
        st = _n91_proc_status(n)
        rss = _n91_kb(st.get('VmRSS'))
        if rss:
            procs.append((rss, _n91_clip(st.get('Name', '?'), 24), n == me, n))
    procs.sort(reverse=True)
    r['top'] = [(rss, name, mine, ('' if mine else _n91_proc_hint(pid))) for rss, name, mine, pid in procs[:top]]
    r['psi'] = _n91_psi()
    r['swap_rate'] = _n91_swap_rate(sample)
    return r


def _n91_gb(n):
    return '%.1f GB' % (n / 1073741824.0) if n >= 1073741824 * 0.1 else '%d MB' % round(n / 1048576.0)


def _n91_resources_text(compact=False, r=None):
    r = r if r is not None else _n91_resources(sample=not compact)
    if not r.get('mem_total'):
        return 'I cannot read this server\'s memory figures (this system does not expose them), so I will not guess.'
    mem_used = max(0, r['mem_total'] - r['mem_avail'])
    pct = lambda a, b: int(round(100.0 * a / b)) if b else 0
    swap_pct = pct(r['swap_used'], r['swap_total'])
    warns, notes = [], []
    state = _n91_swap_state(r)
    rate = r.get('swap_rate')
    if state == 'pressure':
        why = 'memory is short' if (r['mem_total'] and r['mem_avail'] < 0.25 * r['mem_total']) else ('it is swapping right now' if (rate and rate['in'] + rate['out'] > 50) else 'programs are waiting for memory')
        warns.append('swap is %d%% full and %s: the server is short of memory and slows down' % (swap_pct, why))
    elif state == 'stale':
        notes.append('ℹ️ Swap is %d%% full, but %s, so it holds old unused data. That is harmless; it clears when the programs that wrote it restart, or at a reboot.' % (
            swap_pct, 'memory is available and the server is not swapping right now' if rate is not None else 'memory is available and the kernel reports no memory stalls'))
    elif state == 'unclear':
        notes.append('ℹ️ Swap is %d%% full, but memory is available; I could not measure whether it is swapping right now.' % swap_pct)
    if r['mem_avail'] < 512 * 1048576:
        warns.append('less than 0.5 GB of memory is really free')
    if r['disk_total'] and r['disk_free'] < 5 * 1073741824:
        warns.append('less than 5 GB of disk is free')
    if r['cpus'] and r['load'] and r['load'][0] / r['cpus'] > 1.5:
        warns.append('the processor is overloaded (load %.2f on %d core%s)' % (r['load'][0], r['cpus'], '' if r['cpus'] == 1 else 's'))
    mem_line = 'Memory: %s total · %s used · %s available' % (_n91_gb(r['mem_total']), _n91_gb(mem_used), _n91_gb(r['mem_avail']))
    swap_line = ('Swap: %s · %s used (%d%%)%s%s' % (_n91_gb(r['swap_total']), _n91_gb(r['swap_used']), swap_pct, ' ⚠️' if state == 'pressure' else '',
                                                    (' · swapping now: %d in, %d out pages/s' % (round(rate['in']), round(rate['out']))) if rate and (rate['in'] + rate['out']) > 50 else (' · not swapping now' if rate is not None else ''))) if r['swap_total'] else 'Swap: none'
    disk_line = ('Disk (/): %s · %s used (%d%%) · %s free %s' % (_n91_gb(r['disk_total']), _n91_gb(r['disk_used']), pct(r['disk_used'], r['disk_total']), _n91_gb(r['disk_free']),
                                                              '⚠️ LOW' if r['disk_free'] < 5 * 1073741824 else '✅')) if r['disk_total'] else 'Disk: not readable'
    cpu_line = 'CPU: %s core%s%s' % (r['cpus'] or '?', '' if r['cpus'] == 1 else 's', (' · load %s (1.0 per core = fully busy)' % ' '.join('%.2f' % x for x in r['load'])) if r['load'] else '')
    if compact:
        return '🖥 Server: memory %s available of %s · swap %d%% used%s · disk %s free · %s core%s' % (_n91_gb(r['mem_avail']), _n91_gb(r['mem_total']), swap_pct, ' ⚠️' if state == 'pressure' else '',
                                                                                                 _n91_gb(r['disk_free']), r['cpus'] or '?', '' if r['cpus'] == 1 else 's')
    lines = ['🖥 SERVER RESOURCES (read directly from the server just now)', mem_line, swap_line, disk_line, cpu_line]
    own = r.get('own') or {}
    up = ('Server up %s' % _n91_dur(r['uptime'])) if r.get('uptime') else ''
    if own.get('rss'):
        up += (' · ' if up else '') + 'Nemo uses %s of memory, %s thread%s' % (_n91_gb(own['rss']), own.get('threads', '?'), '' if str(own.get('threads')) == '1' else 's')
    if up:
        lines.append(up)
    if r.get('top'):
        lines.append('Biggest memory users: ' + ' · '.join('%s %s%s%s' % (name, _n91_gb(rss), ' (Nemo)' if mine else '', (' [%s]' % hint) if hint else '') for rss, name, mine, hint in r['top']))
    lines.extend(notes)
    lines.append(('⚠️ ' + '; '.join(warns) + '.') if warns else '✅ Nothing is short right now.')
    gb = r['mem_avail'] / 1073741824.0
    fits = 'a 7B model (about 4-5 GB) could fit' if gb >= 6.5 else 'a 3B model (about 2 GB) could fit' if gb >= 3 else 'only very small models (under about 1 GB) are realistic'
    lines.append('What it means for add-ons: a local AI model needs about its file size in free memory; with %s available %s. Voice, OCR and embedding add-ons should load one at a time.' % (_n91_gb(r['mem_avail']), fits))
    return '\n'.join(lines)


_N91_RES_WORDS = _n91_re.compile(r'(?i)\b(?:memory|ram|swap|disk|storage|cpu|vcpu|cores?|resources|specs?|load)\b')
_N91_RES_STRONG = _n91_re.compile(r'(?i)\b(?:ram|disk(?:\s+space)?|vcpus?|cpu)\b')
_N91_RES_SUBJECT = _n91_re.compile(r'(?i)\b(?:server|vps|droplet|machine|your\s+(?:memory|ram|disk|swap|cpu|storage|resources|specs)|do\s+you\s+have|you\s+have|nemo|the\s+system|system\s+(?:status|resources|health))\b')
_N91_RES_ASK = _n91_re.compile(r'(?i)^(?:how\s+(?:much|many|full|busy)|what(?:\'s|\s+is|\s+are)?|show|tell|check|give|display|is|are|do\s+you|does|can\s+you\s+(?:show|tell|check)|server|vps|system|memory|disk|ram|swap|free)\b')
_N91_RES_ELSEWHERE = _n91_re.compile(r'(?i)\b(?:phone|mobile|iphone|android|laptop|pc|computer|tablet|sd\s*card|google\s+drive|drive\s+storage|icloud|gmail|mailbox|my\s+brain|human|elephant|game|trade|trading|futures|options|currency|interest|bond)\b')


def _n91_asks_resources(t):
    t = str(t or '').strip()
    if not t or len(t) > 140 or '://' in t or '\n' in t or _N91_RES_ELSEWHERE.search(t) or not _N91_RES_ASK.match(t):
        return False
    if _n91_re.match(r'(?i)^(?:server|vps|droplet)\s+(?:status|resources?|specs?|health|usage|memory|ram|disk|storage)\??$', t):
        return True
    return bool(_N91_RES_WORDS.search(t) and (_N91_RES_SUBJECT.search(t) or _N91_RES_STRONG.search(t)))


_N91_EYE_PREV = _n88_eye_system
def _n88_eye_system(now=None):
    r = _N91_EYE_PREV(now)
    try:
        if r.get('ok'):
            r = dict(r, text=r['text'] + '\n' + _n91_resources_text(compact=True))
    except Exception:
        pass
    return r


